INSERT INTO public.curated_artifacts VALUES (1, 'Cracked Data Core', 'A remnant of the Old World''s network.', 'The silicon is pitted and scarred, but a faint blue light still pulses within. It hums with the static of a billion forgotten conversations.', 'artifact_data_core', 'boss', NULL, 'Drops from: Chapter 5 Boss — Data Sentinel', 0.0300, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (2, 'Void Shard', 'A pulsating fragment of Yaldabaoth''s prison.', 'Cold to the touch and seemingly absorbing the light around it. To hold it is to feel the weight of infinite isolation.', 'artifact_void_shard', 'boss', NULL, 'Drops from: Chapter 10 Boss — Void Warden', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (3, 'Membrane Leaf', 'Flora found only in the Lower Towers.', 'Transparent and veined with a bioluminescent sap. It feeds on the atmospheric pressure of the tower''s depths.', 'artifact_membrane_leaf', 'chapter', NULL, 'Drops from: Chapter 3 Mastery', 0.0500, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (4, 'Conduit''s Focus', 'A broken lens used to channel cosmic energy.', 'Once part of a Drifter''s apparatus. Though cracked, it still refracts the Akashic flow into visible spectrums.', 'artifact_conduit_focus', 'boss', NULL, 'Drops from: Chapter 15 Boss — Akashic Conduit', 0.0300, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (9, 'Pallid Fragment', 'A shard of the Mask itself, impossibly light.', 'Its surface shifts between states of matter. Those who stare too long claim to see faces forming in its reflections.', 'artifact_pallid_fragment', 'boss', NULL, 'Drops from: Book 1 Final Boss — The Pallid Mask', 0.0100, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (10, 'Tower Foundation Stone', 'A cube of impossibly dense material from Level 1.', 'Warm to the touch despite its appearance. The stone remembers the weight of every floor above it.', 'artifact_foundation_stone', 'chapter', NULL, 'Drops from: Chapter 1 Mastery', 0.0500, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (11, 'Static Discharge Coil', 'Sparking remnant from a deactivated defense grid.', 'Arcs of residual energy leap between its contacts. Each discharge echoes the last transmission it carried.', 'artifact_discharge_coil', 'boss', NULL, 'Drops from: Chapter 20 Boss — Grid Controller', 0.0300, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (12, 'Collapsed Star Marble', 'A gravity-warped sphere from the Observatory.', 'Impossibly heavy for its size. Light bends visibly around it, creating a permanent halo effect.', 'artifact_star_marble', 'boss', NULL, 'Drops from: Chapter 30 Boss — Stellar Observer', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (13, 'Drifter''s Compass', 'Points toward sources of concentrated Akashic energy.', 'The needle spins lazily until it detects a rift. Then it locks on with mechanical precision, trembling with anticipation.', 'artifact_drifter_compass', 'rare_spawn', NULL, 'Rare drop from: Wandering Drifter encounters', 0.0050, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (14, 'Echo Chamber Resonator', 'Amplifies the faintest whispers from the tower walls.', 'Press it against stone and hear centuries of conversations layered over each other in a beautiful, maddening cacophony.', 'artifact_echo_resonator', 'boss', NULL, 'Drops from: Chapter 40 Boss — Echo Keeper', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (15, 'Substrate Filament', 'A thread of living circuitry from the tower''s nervous system.', 'It writhes slowly when exposed to bioelectric fields. The tower is alive, and this is proof.', 'artifact_substrate_filament', 'boss', NULL, 'Drops from: Chapter 50 Boss — Substrate Mind', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (16, 'Gravity Anchor', 'A stabilization device from the mid-tower engineering bays.', 'When activated, it creates a pocket of normal gravity in the tower''s wildly fluctuating fields.', 'artifact_gravity_anchor', 'chapter', NULL, 'Drops from: Chapter 25 Mastery', 0.0400, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (17, 'Phase Spider Silk', 'Gossamer thread that shifts between dimensions.', 'It exists in two places at once. Pull one end and the other moves in a mirror dimension.', 'artifact_spider_silk', 'rare_spawn', NULL, 'Rare drop from: Phase Spider encounters', 0.0050, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (18, 'Memory Spool', 'A crystalline recording medium from the Archive.', 'Contains compressed memories of tower inhabitants. Playing them back reveals fragments of lives lived in perpetual ascension.', 'artifact_memory_spool', 'boss', NULL, 'Drops from: Chapter 60 Boss — Archive Guardian', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (19, 'Pallid Mask Shard', 'A fragment of the legendary mask, vibrating with power.', 'Even this small piece radiates the presence of its whole. Those nearby feel watched by something ancient and patient.', 'artifact_mask_shard', 'boss', NULL, 'Drops from: Chapter 70 Boss — Mask Fragment', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (20, 'Entropy Lens', 'A cracked lens that reveals hidden decay patterns.', 'Look through it and watch the universe unravel at the molecular level. Beautiful and terrifying in equal measure.', 'artifact_entropy_lens', 'boss', NULL, 'Drops from: Chapter 91 Boss — Entropy Weaver', 0.0250, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (21, 'Ascending Flame Ember', 'A perpetually burning coal from the Upper Furnace.', 'It never cools, never dims, never consumes itself. A perfect violation of thermodynamics.', 'artifact_flame_ember', 'boss', NULL, 'Drops from: Chapter 95 Boss — Furnace Lord', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (22, 'Void Walker''s Boot', 'A single boot that phases through solid matter.', 'The wearer''s footsteps leave no mark. They walk not on the ground but through the idea of ground.', 'artifact_void_boot', 'boss', NULL, 'Drops from: Chapter 98 Boss — Void Walker', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (23, 'Temporal Dust', 'Grains of sand from a broken hourglass of ages.', 'Each grain contains a frozen moment. Shake the vial and watch civilizations rise and fall in the swirling patterns.', 'artifact_temporal_dust', 'chapter', NULL, 'Drops from: Chapter 93 Mastery', 0.0400, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (24, 'Demiurge''s Fingerbone', 'A fossilized digit from the creator itself.', 'It points unerringly toward the next floor. The bone remembers the hand that built the tower.', 'artifact_demiurge_bone', 'boss', NULL, 'Drops from: Chapter 100 Boss — Demiurge Shade', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (25, 'Cosmic Thread', 'A strand of the fabric between dimensions.', 'Invisible to the naked eye but felt as a vibration in the chest. Pull it and reality dimples.', 'artifact_cosmic_thread', 'boss', NULL, 'Drops from: Chapter 103 Boss — Cosmic Weaver', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (26, 'Red Hat''s Calling Card', 'A bloodstained card with impossible geometry.', 'The angles are wrong. Following the lines with your eyes leads them to places that shouldn''t exist within a flat surface.', 'artifact_red_hat_card', 'rare_spawn', NULL, 'Rare drop from: Red Hat Agent encounters', 0.0040, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (27, 'Akashic Record Fragment', 'A page torn from the universal memory.', 'The text rewrites itself as you read, always showing what you most need to know. The information is always true but never comforting.', 'artifact_akashic_record', 'boss', NULL, 'Drops from: Chapter 105 Boss — Record Keeper', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (28, 'Etheris Crystal', 'Pure crystallized tower energy.', 'It glows with an inner light that responds to the holder''s emotional state. In anger it blazes; in peace it dims to a warm ember.', 'artifact_etheris_crystal', 'chapter', NULL, 'Drops from: Chapter 97 Mastery', 0.0400, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (29, 'Corruption Bloom', 'A flower that thrives on tainted energy.', 'Its petals are a deep, wrong shade of purple. It converts corruption to sustenance, growing more beautiful as its environment decays.', 'artifact_corruption_bloom', 'boss', NULL, 'Drops from: Chapter 107 Boss — Corruption Nexus', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (30, 'Resonance Fork', 'A tuning fork attuned to the tower''s frequency.', 'Strike it and the tower hums in response. Doors open, walls shift, and hidden passages reveal themselves.', 'artifact_resonance_fork', 'boss', NULL, 'Drops from: Chapter 108 Boss — Resonance Matrix', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (31, 'Null Field Emitter', 'Generates a localized zone where powers fail.', 'Within its range, all supernatural abilities cease. A great equalizer and a terrifying weapon.', 'artifact_null_emitter', 'boss', NULL, 'Drops from: Chapter 110 Boss — Null Entity', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (32, 'Ascending Heart', 'The crystallized ambition of a thousand climbers.', 'It beats with the collective determination of every soul that reached this height. Their courage is now yours.', 'artifact_ascending_heart', 'boss', NULL, 'Drops from: Book 2 Final Boss — The Ascending One', 0.0100, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (33, 'Phantom Circuit Board', 'Technology from a timeline that never happened.', 'Its components are made of materials that don''t exist in this reality. It functions perfectly despite being theoretically impossible.', 'artifact_phantom_circuit', 'rare_spawn', NULL, 'Rare drop from: Phantom Engineer encounters', 0.0040, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (34, 'Singularity Pearl', 'A droplet of compressed spacetime.', 'Light circles its surface endlessly, never escaping. A miniature black hole tamed and contained.', 'artifact_singularity_pearl', 'boss', NULL, 'Drops from: Chapter 112 Boss — Singularity Core', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (35, 'Dream Catcher Web', 'Spun from the boundary between sleep and death.', 'It catches not dreams but intentions. Hang it nearby and know exactly what every nearby consciousness desires.', 'artifact_dream_web', 'chapter', NULL, 'Drops from: Chapter 100 Mastery', 0.0400, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (36, 'Abyssal Lantern', 'Illuminates things that prefer to remain hidden.', 'Its light penetrates all darkness, including the metaphorical kind. Secrets recoil from its glow.', 'artifact_abyssal_lantern', 'boss', NULL, 'Drops from: Chapter 113 Boss — Abyss Watcher', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (37, 'Transcendence Seed', 'A bud of potential that could become anything.', 'It exists in a superposition of all possible forms. Observation doesn''t collapse it — it chooses what to become based on need.', 'artifact_transcend_seed', 'boss', NULL, 'Drops from: Chapter 114 Boss — Garden of Potential', 0.0250, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (38, 'Yaldabaoth''s Tear', 'A frozen droplet from the imprisoned creator.', 'It contains the grief of a god. To hold it is to understand the weight of creating something you cannot control.', 'artifact_yaldabaoth_tear', 'boss', NULL, 'Drops from: Chapter 118 Boss — Prison Warden', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (39, 'Infinity Mirror Shard', 'A fragment that reflects infinite versions of reality.', 'Every reflection shows a different timeline. In some you climb; in others you fall. In one, the tower was never built.', 'artifact_infinity_mirror', 'boss', NULL, 'Drops from: Chapter 120 Boss — Mirror Entity', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (40, 'Architect''s Blueprint', 'Plans for a floor that was never built.', 'The designs are elegant and impossible. Rooms inside rooms, stairs that lead up by going down. M.C. Escher would weep.', 'artifact_blueprint', 'chapter', NULL, 'Drops from: Chapter 116 Mastery', 0.0400, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (41, 'Quantum Entanglement Key', 'A key paired to a lock that exists everywhere.', 'Turn it anywhere and a door opens somewhere. The connection between key and lock transcends space.', 'artifact_quantum_key', 'boss', NULL, 'Drops from: Chapter 122 Boss — Quantum Gate', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (42, 'Soul Prism', 'Refracts consciousness into its component drives.', 'Look through it and see yourself as you truly are: a spectrum of desires, fears, and forgotten promises.', 'artifact_soul_prism', 'boss', NULL, 'Drops from: Chapter 125 Boss — Soul Collector', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (43, 'Tower''s Heartbeat', 'A rhythmic pulse from the tower''s deepest core.', 'It beats in time with your own heart. As you climb higher, the synchronization grows stronger. You and the tower are becoming one.', 'artifact_tower_heartbeat', 'boss', NULL, 'Drops from: Chapter 128 Boss — Core Guardian', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (44, 'Light Eater Mandible', 'A jaw fragment from a creature that feeds on photons.', 'In its presence, shadows deepen and colors desaturate. It is always hungry, and light is always plentiful.', 'artifact_light_eater', 'rare_spawn', NULL, 'Rare drop from: Light Eater encounters', 0.0040, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (45, 'Akashic Lens', 'Reveals the true nature of all things observed.', 'The ultimate tool of perception. It strips away pretense, illusion, and self-deception. Most users can''t handle what they see.', 'artifact_akashic_lens', 'boss', NULL, 'Drops from: Chapter 130 Boss — Truth Arbiter', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (46, 'Elysium Gate Fragment', 'A piece of the final door.', 'It hums with finality. This fragment knows it is part of an ending — and every ending is also a beginning.', 'artifact_gate_fragment', 'chapter', NULL, 'Drops from: Chapter 125 Mastery', 0.0400, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (47, 'Cosmic Weave Thread', 'Fabric of the multiverse made tangible.', 'Each thread is a timeline. Pull gently and realities brush against each other. Pull hard and they merge. Neither outcome is safe.', 'artifact_cosmic_weave', 'boss', NULL, 'Drops from: Chapter 132 Boss — Weave Spinner', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (48, 'Consciousness Engine', 'A device that converts thought into energy.', 'Think near it and watch it glow. Dream near it and watch it blaze. It proves that consciousness is not a byproduct but a fundamental force.', 'artifact_consciousness_eng', 'boss', NULL, 'Drops from: Chapter 133 Boss — Mind Engine', 0.0200, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (49, 'Timeless Observer Monocle', 'Allows viewing of all temporal states simultaneously.', 'Past, present, and future are displayed in overlapping layers. Sorting through them requires a consciousness that transcends linear time.', 'artifact_timeless_monocle', 'rare_spawn', NULL, 'Rare drop from: Temporal Observer encounters', 0.0040, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (50, 'Final Theorem Proof', 'The mathematical proof that reality is recursive.', 'Written on a surface that exists in more than three dimensions. Reading it expands the mind in ways that cannot be undone.', 'artifact_final_theorem', 'boss', NULL, 'Drops from: Chapter 135 Boss — Logic Arbiter', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (51, 'Elysium''s Crown Jewel', 'The ultimate artifact, a gem from Elysium itself.', 'It radiates the pure energy of ascension. Those who hold it know, with absolute certainty, that the climb was worth it.', 'artifact_crown_jewel', 'boss', NULL, 'Drops from: Book 3 Final Boss — The Transcendent', 0.0050, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (52, 'Primordial Ember', 'The first spark of creation, still burning.', 'Before the tower, before the world, there was this. An eternal flame that contains the blueprint of all that exists.', 'artifact_primordial_ember', 'boss', NULL, 'Drops from: Chapter 136 Boss — Origin Flame', 0.0150, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (53, 'Unity Fractal', 'A pattern that contains itself infinitely.', 'Zoom in or out — the same pattern repeats forever. It proves that the small and the large are the same. As above, so below.', 'artifact_unity_fractal', 'chapter', NULL, 'Drops from: Chapter 130 Mastery', 0.0400, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifacts VALUES (54, 'Omega Key', 'Opens the door that opens all doors.', 'It doesn''t fit any specific lock. It fits the concept of ''locked.'' With it, nothing is closed to you.', 'artifact_omega_key', 'boss', NULL, 'Drops from: Chapter 138 Boss — Final Gatekeeper', 0.0100, NULL, true, '2026-03-09 12:40:25.289342-04', '2026-03-09 12:40:25.289342-04');
INSERT INTO public.curated_artifact_tiers VALUES (5, 1, 'common', '{"wisdom": 1, "agility": 1, "strength": 5, "vitality": 2, "intelligence": 2}', NULL, 1.0000);
INSERT INTO public.curated_artifact_tiers VALUES (6, 1, 'uncommon', '{"wisdom": 2, "agility": 2, "strength": 8, "vitality": 3, "intelligence": 3}', NULL, 0.5000);
INSERT INTO public.curated_artifact_tiers VALUES (1, 1, 'rare', '{"wisdom": 3, "agility": 3, "strength": 13, "vitality": 5, "intelligence": 5}', NULL, 0.1000);
INSERT INTO public.curated_artifact_tiers VALUES (8, 1, 'epic', '{"wisdom": 4, "agility": 4, "strength": 20, "vitality": 8, "intelligence": 8}', 'Enhanced passive effect', 0.0200);
INSERT INTO public.curated_artifact_tiers VALUES (9, 1, 'cosmic', '{"wisdom": 7, "agility": 7, "strength": 35, "vitality": 14, "intelligence": 14}', 'Ultimate passive effect', 0.0050);
INSERT INTO public.curated_artifact_tiers VALUES (10, 2, 'common', '{"wisdom": 1, "agility": 1, "strength": 5, "vitality": 2, "intelligence": 2}', NULL, 1.0000);
INSERT INTO public.curated_artifact_tiers VALUES (11, 2, 'uncommon', '{"wisdom": 2, "agility": 2, "strength": 8, "vitality": 3, "intelligence": 3}', NULL, 0.5000);
