INSERT INTO public.entities VALUES (1949, 'The Automated Business', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (548, 'Work', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:51:29.102752-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (592, 'Anticipation (Camping Adventure)', false, 'Excitement and eager energy permeating the scouts at the start of the day; infectious enthusiasm for merit badge challenges.', 'Joyful, hopeful, triumphant.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 37, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:52:44.252541-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (264, 'Grandmother', false, 'Elderly family member, voice now clouded by dementia.', 'Present through fragmented memory and loss.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (2408, 'Newspaper', false, 'A newspaper containing the news of the S Corp''s discovery of the temple in Zambia.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 197, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:42:29.884905-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (1038, 'The Engineer (Protagonist)', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:30:36.560497-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (1095, 'Non-Human Entities', false, 'Beings from alternate realities that are reportedly ''bleeding through'' into our world via quantum experiments. They are described as not looking entirely human and observing people with an unnerving intelligence.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:34:59.83941-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (1097, 'IBM Researcher', false, 'A scientist who was interviewed about the quantum experiments. She hinted that the computations were like crossing into parallel universes and that anomalies were things bleeding through.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:34:59.83941-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (735, 'Awards and Mementos', false, 'Professional accomplishments lining narrator''s office; now deemed disposable.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 46, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:58:32.087628-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (1273, 'David (Protagonist)', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:51:40.884139-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (1895, 'Timmy the Goldfish', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (734, 'Car (Narrator''s)', false, 'Private refuge; contains untouched phone and windshield view of nothing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 46, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:58:32.087628-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (1571, 'Can of Raid', false, 'A standard can of aerosol insecticide.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 124, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (1904, 'AutoDoc', false, 'A sleek cylindrical chamber with soft white bedding and a glowing, cloud-like interior. It is designed to heal injuries using nanites, but the process is excruciatingly painful.', NULL, 'A faint hum during initialization, a quiet hiss as the door opens and closes.', NULL, 'Injection port, internal bedding.', 'Administers nanites to deconstruct and reconstruct tissue at a molecular level, healing severe injuries.', NULL, NULL, NULL, 158, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (1055, 'Protagonist (Narrator)', false, 'The resolute commander leading the operation from the war room, making critical decisions under pressure.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:32:17.378803-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (1943, 'AutoDoc, the Flesh Abomination', true, 'A towering, living structure of pulsating flesh and bone, constantly writhing with tentacles and screaming from countless gaping mouths. It exudes an aura of false promise and cosmic dread, representing the catastrophic failure of mortals playing God.', NULL, NULL, NULL, NULL, NULL, '"In front of me stood a towering structure, made of pulsating flesh and bone, adorned with writhing tentacles and gaping mouths. It was the AutoDoc, a grotesque abomination that promised everlasting life at a terrible cost."', '"Blood dripped from its jagged edges, screams echoed from within its walls..."', 'As the central antagonist of the scene, the AutoDoc is not just a monster but a sentient piece of architecture that actively corrupts its environment. It embodies the theme of immortality''s terrible price, making it a significant and focal threat.', 161, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (1948, 'The Grandmother', false, 'The narrator''s mother-in-law, who lives in Japan and has been waiting many years to see her family again.', 'Overjoyed and emotional, her voice trembling as she embraces her daughter and grandson after a long separation.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 162, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (4306, 'AP Biology Test', false, 'An impending academic exam that serves as the primary catalyst for the scene''s conflict. The threat of failing it is presented as more brutal and devastating than a physical concussion.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 371, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:19:18.294406-05', '2026-03-14 18:06:15.112419-04', 8, NULL);
INSERT INTO public.entities VALUES (2279, 'Illuminati', false, 'A mythologized secret society said to control world events; dismissed by Narrator as fiction invented by ''drunken Bavarians,'' but invoked humorously and then metaphorically in conversation.', NULL, NULL, NULL, NULL, 'Alleged total control over world affairs; recruitment of the powerful and wealthy.', NULL, NULL, NULL, 190, 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:59.228789-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (5354, 'Liquid Mathematics', false, 'The fundamental, code-like substance of reality in the construct. It shatters in a crystalline crash upon the impact of Yaldabaoth''s head, signifying the complete dissolution of existence.', NULL, 'A crystalline crash.', NULL, NULL, NULL, NULL, NULL, NULL, 458, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (1183, 'The Son''s Phone', false, 'A standard smartphone that becomes the key to the first breakthrough with the crystal. It is the first device to detect the crystal''s NFC signal.', NULL, NULL, NULL, 'Running a Roblox game when the discovery is made.', NULL, NULL, NULL, NULL, 86, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (2378, 'UPS', false, 'A major global shipping and logistics company, one of the targets for the narrator''s partnership proposal.', NULL, NULL, NULL, NULL, 'Extensive global distribution network and infrastructure.', NULL, NULL, NULL, 195, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:40:35.865132-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (2379, 'FedEx', false, 'A major global courier delivery services company, one of the targets for the narrator''s partnership proposal.', NULL, NULL, NULL, NULL, 'Extensive global distribution network and infrastructure.', NULL, NULL, NULL, 195, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:40:35.865132-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (4384, 'The Conspiring Shadows', true, 'These are not mere absences of light but sentient, conspiring entities that inhabit the corners of Stephen''s room. They seem to feed on his paranoia and are described as whispering and watching with a detached, knowing amusement.', NULL, NULL, NULL, NULL, NULL, '''Shadows conspire in the corners of my room. I think they whisper.'' and ''The shadows in my room seem to be watching me with what I can only describe as amusement.''', 'Whispering just beyond the edge of hearing, and watching with silent amusement.', 'Unlike normal shadows, these are portrayed as an active, intelligent presence. They contribute directly to the psychological horror of the scene, acting as silent, judging observers of Stephen''s trauma and social obliviousness.', 377, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (2409, 'University of Chicago', false, 'The academic institution where the protagonist works.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 197, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:42:29.884905-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (2430, 'Sanity', false, 'The protagonist''s mental and psychological stability.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 199, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:43:55.646305-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (5312, 'The First Book', false, 'The author''s previous book, used as a benchmark for quality and considered less rough than the second book.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 455, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:41:20.990247-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (2672, 'Lord Vishnu', false, 'A principal Hindu deity known as the preserver of the universe. He is mentioned by the priest as the consort of Lakshmi.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 221, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:03:44.339838-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (415, 'Protagonist''s Son', false, 'The protagonist''s child whose school is offering the London trip opportunity.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 25, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:24:09.210121-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (2954, 'Underground River Legend', false, 'A local legend about a subterranean river with mystical properties, rumored to influence dreams. It becomes a central clue in the group''s investigation.', NULL, NULL, NULL, NULL, 'Theorized to have properties that can affect human consciousness, possibly causing the coordinated sleepwalking.', NULL, NULL, NULL, 248, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:27:23.550079-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (2253, 'Earth', false, 'The human homeworld, only mentioned as the source of the cosmic call and the destination the Ancient Entity is hurtling toward. Described as the birthplace of the colonists'' kind.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 187, 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (3098, 'Narrator''s Aide', false, 'An assistant to the narrator who is present during the meeting. They act efficiently and without words, providing the legal agreement at the precise moment it is needed.', 'Professional and focused.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 263, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:39:22.750481-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (3308, 'Somali Forces', false, 'Military or paramilitary forces planned to be used for a suicide run to deliver and detonate the God Killer at its target.', NULL, NULL, NULL, NULL, 'Military operations, suicide missions.', NULL, NULL, NULL, 283, 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (3245, 'Alien Soil', false, 'The ground of the new planet, representing the first point of physical contact for the newcomers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 278, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (3268, 'Commanding Officer', false, 'The commanding officer of the Exo-Interstellar Exploratory Force on Pluto. Delivers a stirring and sobering welcome speech to new recruits.', 'Authoritative, inspiring, and pragmatic.', 'A clear, commanding voice addressing the recruits.', NULL, 'Likely a standard uniform for the force.', 'Leadership, public speaking, and strategic communication.', NULL, NULL, NULL, 281, 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (4491, 'The Mocking Echo', true, 'An incorporeal entity that serves as a herald or guardian of the threshold the group is attempting to breach. Its presence is felt as a bone-deep cold and heard as a disembodied, intelligent laughter that seems to ridicule their efforts from the shadows.', NULL, NULL, NULL, NULL, NULL, '''The temperature drops another ten degrees, and somewhere in the darkness beyond our circle, something that might have been laughter echoes off the paneled walls.''', 'The disembodied, echoing laughter that signifies its arrival and malicious awareness.', 'Unlike a passive spirit, this entity actively influences the physical environment (temperature) and displays intelligent, mocking behavior. It is the first active antagonist to respond to the ritual, acting as a sentient warning sign of the greater dangers the group is invoking.', 385, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:02.688626-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (3643, 'Holy Plasma Cannons', false, 'The primary energy weapons of the fleet. They unleash torrents of holy energy capable of splintering powerful shields.', NULL, 'Unleashing torrents of energy.', NULL, NULL, 'Firing deadly volleys of plasma.', NULL, NULL, NULL, 312, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (531, 'Amazon Rainforest', false, 'Biodiverse ecosystem and home to indigenous communities, threatened by Global Grid expansion.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (3884, 'Procedurally Generated Universe', false, 'The narrator''s paranoid theory that his reality is a fake, repetitive, and unimaginative simulation. This concept represents his existential dread and the perceived lack of genuine risk or meaning in his life.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 331, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (533, 'United Nations', false, 'Global diplomatic body where world leaders are expressing concern and demanding answers about the Global Grid''s implications.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (4051, 'Etheris (Destroyed)', false, 'The former universe that was completely annihilated by the protagonist. Its absence is a primary component of his guilt.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 346, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (4106, 'Computer Desk', false, 'An old desk with a worn surface, serving as the protagonist''s workspace.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 351, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:02:24.178458-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (4122, 'Holographic Banners', false, 'Banners suspended in mid-air over the square, shimmering with otherworldly luminescence and depicting unknown constellations. They add to the celebratory and futuristic atmosphere.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 352, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:03:23.934309-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (4123, 'Sky-whales', false, 'Graceful creatures with iridescent wings that circle overhead in the Sorhhindian sky. They are part of the vibrant tapestry of life on the planet.', NULL, 'The gentle sigh of the wind through their wings.', NULL, NULL, NULL, NULL, NULL, NULL, 352, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:03:23.934309-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (4127, 'Yukiko Memorial Square', true, 'Generated manifestation: Yukiko Memorial Square', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 352, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:03:23.934309-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (4815, 'Jamie''s Parents', false, 'The parents of Jamie and Tiffany. They have invited Stephen over for Christmas Day.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 411, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (5293, 'Jay', false, 'An individual whom Whitney claims to have found, mentioned just before the phone line goes dead.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 452, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:39:11.351125-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (702, 'Monday', false, 'Appears ordinary on surface yet carries weight of inevitability and looming collapse.', 'Ominous, suffocating, inevitable.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 44, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:57:17.721641-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (5468, 'Azathoth', false, 'A powerful entity mentioned as the one responsible for trapping Lady Illkeserod in the failing vessel and trying to force her out.', NULL, NULL, NULL, NULL, 'Capable of imprisoning other powerful beings within constructs or vessels.', NULL, NULL, NULL, 471, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (5621, 'Vanilla and Peach Scent', false, 'A sharp, sweet, and undeniable scent that doesn''t belong in the memory of the AP Bio classroom. It is powerful enough to colonize the moment and override the smells of formaldehyde and pizza grease.', NULL, NULL, 'Vanilla and peaches.', NULL, 'Acts as a powerful sensory trigger and signifier of Jamie''s (ብሪትለሪሌት) presence.', NULL, NULL, NULL, 486, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (3701, 'The Pyre', false, 'A fire of self-immolation, described as the ''only and last resort'' for the desperate.', NULL, 'The roar of flames.', 'Burning flesh and despair.', NULL, NULL, NULL, NULL, NULL, 316, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (703, 'Mental Fragmentation', false, 'Narrator''s thoughts are chaos, tangled with fragments of dread and obsession.', 'Disorienting, uncontrollable, alarming.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 44, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:57:17.721641-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (3993, 'ኢልከሴሮድመሜብሃባኖኖራሊሊ', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (262, 'Forgotten Knowledge', false, 'Something the narrator believed would remain hidden forever, now resurfacing with their awakening.', 'Suppressed, dangerous, threatening.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (6396, 'The Inner Elsewhere', false, 'A non-physical space or state of consciousness where Stephen finds himself present while his physical body is unconscious on the ground.', NULL, NULL, NULL, NULL, 'Allows for dual-consciousness or out-of-body experience.', NULL, NULL, NULL, 549, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (263, 'Dead Friend', false, 'A deceased person whose warmth and embrace provided comfort to the narrator.', 'Presence now dissolved into shadow and memory.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (265, 'Memories of Love and Loss', false, 'Bittersweet recollections that have become unbearable reminders of things impossible to hold onto.', 'Tormented, agonizing, intolerable.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (268, 'Neural Pathways', false, 'The biological structures holding memories alive; targets for severance through force of will and substance abuse.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (269, 'Blackout Benders', false, 'Episodes of extreme substance intoxication used as a tool to induce forgetting and memory loss.', 'Desperate, self-inflicted, consuming.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (306, 'Oblivion (Manifestation)', false, 'The threat of fragile memories vanishing; the danger of losing complex schematics and divine visions forever.', 'Threatening, relentless; racing against time; memories threaten to fade into oblivion.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 19, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (307, 'Quantum Entanglement and Superposition', false, 'Quantum mechanical principles enabling the trapping of objects in infinite superposition through quantum entanglement.', NULL, NULL, NULL, NULL, 'Trap objects in infinite superposition; tap into boundless states; access all possible realities simultaneously.', NULL, NULL, NULL, 19, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (6490, 'Trapped Souls', false, 'Trillions of souls residing within the Abyss (the prison) who are unaware of their captivity. They perceive their constant suffering as a normal and deserved part of existence, and are the focus of Stephen and Jamie''s mission.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 555, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (6642, 'AI Covers', false, 'Artwork generated by artificial intelligence, used as a temporary solution for the final book''s cover due to the author''s inability to afford a professional designer.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 568, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (308, 'Reality Fabric (Manifestation)', false, 'The fragile structure of reality itself; woven throughout dimensions and multi-verse; capable of being shattered by Engine instability.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 19, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (309, 'Electromagnetic Energy Field', false, 'Otherworldly charge permeating the workshop and surrounding cornfield; pulsing undercurrent of electricity crackles through stalks.', NULL, 'Tangible train clacking thrumming in bones; electricity crackling through air.', NULL, NULL, NULL, NULL, NULL, NULL, 19, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (704, 'Collapse (Impending)', false, 'A sense that the fragile order of the narrator''s life is about to break down.', 'Fatalistic, inevitable, overwhelming.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 44, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:57:17.721641-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (297, 'Matter Replicator', false, 'Individual clones forming nanite limbs, capable of transforming ambient energy into any substance imaginable.', NULL, NULL, NULL, NULL, 'Transform ambient energy into any substance; replicate food to end hunger; create hyper-exotic materials for space-spanning structures; generate medicine for debilitating diseases.', NULL, NULL, NULL, 19, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (343, 'Jake', false, 'An office team member with frustrated tenure.', 'Angry, indignant about unfair promotion practices.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 22, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:06.05021-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (1950, 'The Trip to Japan', false, 'A long-awaited family journey to Japan, motivated by the wife''s desire to see her mother and show her son his roots after evacuating due to the Fukushima disaster years prior.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 162, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-03-14 18:06:15.112419-04', 8, NULL);
INSERT INTO public.entities VALUES (19, 'Stephen A Salaka', false, 'Author and cover/jacket designer of Elysium Rising', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (4260, 'The Hangover', false, 'A severe physical and mental affliction causing the narrator''s skull to feel cracked and his thoughts to leak. It makes basic actions difficult and contributes to his overall sense of disorientation.', 'Painful and oppressive.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 366, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (27, 'Eleanor Roosevelt', false, 'Historical figure whose philosophical statement about dreams serves as the opening epigraph', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (376, 'City Streets', false, 'Deserted roads during early morning hours.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 23, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:55.447677-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (5, 'Yaldabaoth Variant — The Demiurge Shard [Class A]', true, 'A true fragment of Yaldabaoth''s divine power, broken off and operating with semi-autonomous purpose. It manifests as a writhing mass of mouths and eyes encased in a cracked shell of corrupted golden light — like a piece of a shattered god still trying to function as the whole. Each mouth speaks in a different language simultaneously. Each eye focuses on a different dimension. The shell pulses and fractures continuously, leaking tendrils of liquid shadow that reach for anything living. Where it floats, reality develops hairline cracks — fine as spider silk, spreading outward in geometric patterns. It is unmistakably a piece of something unimaginably larger, and that implication is perhaps more terrifying than the shard itself.', 'Fractured megalomania. Each mouth expresses a different facet of Yaldabaoth''s personality simultaneously — one rages, one bargains, one weeps, one commands, one simply screams. The overall effect is a cacophony of divine narcissism struggling to maintain coherence without the whole.', 'A dissonant chord of multiple voices speaking over each other in dead and living languages. The wet sound of mouths opening and closing. A crystalline ringing when its shell fractures further. Beneath it all, a deep, tectonic groan — the sound of broken divinity.', 'Burnt sugar and formaldehyde. The cloying, overripe sweetness of divinity left to rot, mixed with the sharp preservative tang of something trying desperately not to decay further.', 'Encased in a cracked shell of corrupted divine light that serves as both armor and containment. Fragments of the shell can be weaponized as projectile shrapnel.', 'Localized reality manipulation — can warp physics, reverse causality, and unmake matter within a limited radius. Each mouth can cast independently, creating overlapping fields of hostile effect. The eyes can lock onto targets across dimensional boundaries, making conventional hiding impossible. When damaged, it sheds shell fragments that continue to function as autonomous hazards. Can temporarily merge with the local environment, making walls speak and floors hunger.', 'When Yaldabaoth was weakened or wounded across the cycles of its imprisonment, pieces broke away. Each shard retains a portion of the Demiurge''s power and personality but lacks the unified will that makes the whole so dangerous. They are, in a sense, feral gods — divine power without divine purpose, running on fragmented instinct.', '"I AM I AM I AM I AM I AM — which one of me is speaking? Does it matter? Every mouth is mine. Every word is law. KNEEL."', 'Class A — the first variant that wields genuine divine power rather than psychological tricks or environmental control. A Demiurge Shard is a legitimate existential threat within its radius of influence. However, its fractured nature is both its strength (unpredictable, multi-vector attacks) and its weakness (it cannot coordinate its many selves effectively, creating openings between its conflicting impulses).', NULL, 'anthropic', 'claude-opus-4-6', '2026-03-01 14:37:14.948981-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (21, 'The Dream-Born Eternal Engine', false, 'A revolutionary technology discovered by a tech manager protagonist, born from dreams and capable of propelling humanity into an interstellar future', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (22, 'The Malevolent Entity', false, 'An unspecified malevolent force attracted by the protagonist''s success with the Eternal Engine, threatening reality itself', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
