INSERT INTO public.entities VALUES (24, 'The Beauty of Dreams', true, 'An aspirational theme established through Eleanor Roosevelt''s epigraph, suggesting optimism and innovation', 'Hopeful, visionary', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (25, 'The Weight of Nightmares', true, 'A counterbalancing thematic force established through John Irving''s epigraph, representing inevitable darkness and forces beyond personal control', 'Ominous, inevitable, unsettling', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
