INSERT INTO public.entities VALUES (294, 'Cornfield (Exterior)', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (32, 'The Needle', false, 'A needle dancing on the heads of angels; represents the narrow passage of adversity and trial', NULL, 'Subtle dancing movements', NULL, NULL, 'Creates passage through which grains of sand must pass; dances with angelic grace', NULL, NULL, NULL, 2, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (33, 'The Heads of Angels', false, 'Divine or celestial supports upon which the needle dances; represents spiritual or cosmic foundation', NULL, NULL, NULL, NULL, 'Provide support and witness to the grain''s passage', NULL, NULL, NULL, 2, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (34, 'Fate', false, 'The binding force that connects the lost to their destined finder; the path walked together', 'Inexorable, purposeful, redemptive', NULL, NULL, NULL, 'Orchestrates reunion; guides toward redemption; makes distractions meaningless', NULL, NULL, NULL, 2, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (36, 'The Weight of Uncertainty', false, 'The state of being lost and adrift; the condition of not knowing one''s purpose or place', 'Isolating, disorienting, existential', 'Silence of void', NULL, NULL, 'Creates vulnerability and smallness; defines the grain''s predicament', NULL, NULL, NULL, 2, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (296, 'Nanite Swarms', false, 'Powered by the Eternal Engine, composed of individual clones of Matter Replicators with mandible clicks and organic-like vitality despite being apex technology.', NULL, 'Stutter and emit belching sounds, both terrible and pure; sound strange and organic.', NULL, NULL, 'Each limb made of Matter Replicators capable of transforming ambient energy into any substance; can replicate food, create exotic materials, generate medicine; possess Infinitron processing cores.', NULL, NULL, NULL, 19, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 2, NULL);
INSERT INTO public.entities VALUES (41, 'The Void of Mundanity', false, 'The everyday cacophony of ordinary life; attention-hungry void where fleeting blips disappear; urban throng and bustle; the ceaseless chatter of normal existence', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (43, 'The Enigma', false, 'The ineffable quality of The Pointers that resists explanation; their transcendent nature that lingers in minds; the mark they leave on society and consciousness', 'Haunting, persistent, transformative', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (35, 'Distractions', false, 'Forces that pull away from the true path and destined reunion; obstacles to purpose', 'Seductive, deceptive, ultimately hollow', NULL, NULL, NULL, 'Create illusion of importance; obscure true purpose', NULL, NULL, NULL, 2, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (298, 'Infinitron Core', false, 'Processing cores within nanites that hold the real magic, tapping into combined knowledge of infinite realms and emitting waves of Akashic data.', NULL, NULL, NULL, NULL, 'Tap into infinite dimensional knowledge; emit Akashic data waves; ripple through multi-verse fabric; create invisible mesh network between dimensions; access all infinite insanity-inducing wonders and horrors.', NULL, NULL, NULL, 19, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (299, 'Exotic Matter (Reality Shield)', false, 'A shield of inert chaos protecting the Engine''s volatile heart from collapsing and shattering the fragile fabric of reality.', NULL, NULL, NULL, NULL, 'Shields against explosive collapse; protects reality fabric from shattering; acts as stabilizing force against quantum volatility.', NULL, NULL, NULL, 19, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (42, 'Collective Uncertainty', false, 'Shared societal questioning and existential doubt; the collective holding of breath; unified sense of mystery and unknowing across humanity', 'Anticipatory, questioning, obsessive', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (31, 'The Destined Other', false, 'An appointed figure who arrives at the designated moment to find and redeem the lost', 'Purposeful, fated to complete a divine reunion', NULL, NULL, NULL, 'Destined connection, ability to recognize and find the lost', NULL, NULL, NULL, 2, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (293, 'The Workshop', false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
INSERT INTO public.entities VALUES (44, 'Urban Plazas and Beaches', false, 'Bustling public spaces where The Pointers materialize; sun-drenched beaches and city plazas serving as stages for the phenomenon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
