INSERT INTO public.entities VALUES (9, 'Ether Voidling', false, 'A fast, pulsating celestial entity.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-03-01 19:42:07.441395-05', '2026-03-14 18:06:15.112419-04', 1, NULL);
INSERT INTO public.entities VALUES (140, 'Collective Despair', false, 'Shared emotional state among employees facing meaningless tasks, hollow gestures, and executive disconnection.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:07:03.395028-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (1806, 'The Forgotten Deity', false, 'A towering, ancient being with a patchwork of decaying skin, exposed muscle, and twisted, blood-gleaming horns. Once a guide to early mortals, it is now a forgotten horror that revels in carnage and asserts dominance through fear.', 'A mix of grim satisfaction in its power, a sense of being out of place in the modern world, and nostalgia for its distant past.', NULL, 'The overwhelming stench of death and decay clings to it like a cloak.', NULL, 'Causes death and decay on a massive scale. Its touch can physically corrupt objects and drive mortals to madness by imparting forbidden knowledge.', NULL, NULL, NULL, 148, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:39:40.94263-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (472, 'Wife', false, 'Sleeping peacefully beside the narrator in bed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:48:56.287326-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
