INSERT INTO public.entities VALUES (126, 'Jack', false, 'Entry-level data entry analyst who uses a wheelchair. Demonstrates steady voice, determination, and mischievous confidence despite physical limitations and workplace insensitivity.', 'Disbelief and discomfort initially; becomes assertive and confident with his office chair race idea.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:07:03.395028-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (129, 'Zechariah', false, 'Finance team leader who leads grand entrance in elaborate Krampus costume with horns, bells, and faux chains.', NULL, NULL, NULL, 'Krampus costume with horns, bells, faux chains; candy to lob at colleagues.', NULL, NULL, NULL, NULL, 9, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:07:03.395028-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (130, 'Finance Team', false, 'Group of accountants dressed in elaborate Krampus costumes, complete with horns, bells, and faux chains. They sing traditional Krampus songs with requests for beer and lob candy at colleagues.', NULL, 'Traditional Krampus songs; jingling of bells and chains; gleeful menace.', NULL, NULL, NULL, NULL, NULL, NULL, 9, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:07:03.395028-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (132, 'The Developers', false, 'Diverse group of developers accustomed to mental acrobatics of coding rather than physical exertion. Initially bewildered by COO''s demands but find solidarity in Jack''s office chair race idea.', 'Bewilderment, fear, confusion transitioning to cautious enthusiasm and collective despair.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:07:03.395028-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
