INSERT INTO public.entities VALUES (136, 'Holiday Party', false, 'Annual IT holiday party with promised catered feast from local spot blending barbecue, sushi, and German cuisine. Glittering breakroom decorations; colleagues in ugly sweaters.', 'Anticipation transitioning to disappointment and disillusionment.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:07:03.395028-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (131, 'Mattias', false, 'Senior software engineer who exchanges looks of disbelief with Jan amid workplace absurdity.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:07:03.395028-05', '2026-03-14 18:06:15.112419-04', 3, NULL);
INSERT INTO public.entities VALUES (477, 'Guilt (About Enjoyment)', false, 'Emotional weight that shadows the narrator''s enjoyment of entertainment; conflict between present happiness and looming concerns.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 29, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:48:56.287326-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (479, 'Packing Frenzy', false, 'Rapid-fire mobilization of family to prepare camping gear; items stacked, unstacked, checked methodically.', 'Chaotic, energized, purposeful', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 29, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:48:56.287326-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
