INSERT INTO public.entities VALUES (460, 'Video Game Obsession', false, 'The hypnotic pull of Roblox; glowing screen transforming son into absorbed player.', NULL, NULL, NULL, NULL, 'Draws attention completely; resists interruption; creates resistance to dinner calls.', NULL, NULL, NULL, 28, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:48:16.546021-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
