INSERT INTO public.entities VALUES (495, 'Fleeting Calm', false, 'The illusory sense of peace that masks deeper threats and anxieties.', 'deceptive, fragile, false', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 30, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:49:27.981808-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (525, 'Material Shortages', false, 'Critical shortage of steel, concrete, and essential materials caused by the Grid''s unprecedented demand, affecting global industries.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 7, NULL);
