INSERT INTO public.entities VALUES (2849, 'Distant Airport', false, 'A landmark on the northern horizon that serves as the focal point for the residents'' synchronized pointing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 238, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:19:11.399424-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
