INSERT INTO public.entities VALUES (669, 'Cold Pressed Coffee', false, 'The Scoutmaster''s famous cold pressed coffee, noted for its distinctive aroma.', NULL, NULL, 'Unmistakable aroma of brewing coffee.', NULL, NULL, NULL, NULL, NULL, 42, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:56:07.472375-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
INSERT INTO public.entities VALUES (516, 'Truth (Elusive Answers)', false, 'The unattainable goal driving Todd''s obsession; promises clarity but remains hidden.', 'Tantalizing, just beyond reach, consuming.', NULL, NULL, NULL, 'Calls to Todd; justifies his sacrifice of family stability.', NULL, NULL, NULL, 32, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:07.05205-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (517, 'Global Grid', false, 'A vast, synchronized network of construction projects at major transportation hubs worldwide, operating with complete secrecy and no official explanation. Scale and purpose remain unknown.', NULL, NULL, NULL, NULL, 'Coordinated development across continents, material manipulation, infrastructure construction, resource monopolization.', NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 9, NULL);
INSERT INTO public.entities VALUES (519, 'Construction Noise', false, 'Relentless auditory disruption from machinery operating around the clock at transportation hubs.', NULL, 'Continuous mechanical clamor, grinding, drilling, and equipment operation.', NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (521, 'Public Speculation', false, 'Collective public conjecture about the Grid''s origins, ranging from government cover-ups to covert corporate ventures.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (522, 'Local Authorities', false, 'Official bodies providing no information about the construction projects, fueling public distrust and speculation.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (523, 'Shadowy Corporation', false, 'An unnamed, resource-rich organization orchestrating the Global Grid''s synchronized development worldwide.', NULL, NULL, NULL, NULL, 'Resource coordination, infrastructure orchestration, global synchronization, secrecy maintenance.', NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 6, NULL);
INSERT INTO public.entities VALUES (524, 'Grid Fever', false, 'Internet-dubbed panic and economic crisis caused by the Grid''s relentless consumption of steel, concrete, and essential building materials.', 'Panic, uncertainty, desperation for resources.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (535, 'Diplomatic Strain', false, 'Rising tension between nations caused by the Grid''s mysterious development and lack of transparency.', 'Suspicion, anger, distrust, urgency.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (536, 'Global Security Concerns', false, 'Widespread fear among world leaders that the Global Grid poses a threat to national security and sovereignty.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
