INSERT INTO public.entities VALUES (538, 'Disrupted City Life', false, 'Breakdown of ordinary urban existence caused by relentless construction at major hubs.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (540, 'Economic Crisis', false, 'Global economic hardship resulting from material shortages and industrial slowdowns caused by Grid demand.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 4, NULL);
INSERT INTO public.entities VALUES (541, 'Construction Barriers', false, 'Physical barriers obscuring transportation hubs from public view, preventing observation of Grid construction.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 33, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-14 18:06:15.112419-04', 5, NULL);
