INSERT INTO public.entity_beat_appearances VALUES (362, 292, 72, 'ally', true, 'Consumed by doubt and existential dread; witnesses nanite materialization; trapped in workshop choked by swarm; questions whether they''ve unleashed catastrophic forces.', '2026-02-27 13:15:18.882025-05');
