INSERT INTO public.entity_beat_appearances VALUES (591, 157, 114, 'unknown', true, 'Physical and mental state revealed—unwashed, sleep-deprived, surrounded by detective-like web of connections only he understands.', '2026-02-27 13:49:48.022183-05');
INSERT INTO public.entity_beat_appearances VALUES (592, 505, 114, 'unknown', false, 'Dark circles under eyes hint at countless nights spent awake obsessing over investigation.', '2026-02-27 13:49:48.022183-05');
INSERT INTO public.entity_beat_appearances VALUES (593, 501, 114, 'neutral', false, 'Pinned everywhere, connected by red string in pattern only Todd understands.', '2026-02-27 13:49:48.022183-05');
INSERT INTO public.entity_beat_appearances VALUES (594, 157, 115, 'unknown', true, 'Cannot let go of investigation despite its toll; driven by desperate belief that truth lies hidden in chaos.', '2026-02-27 13:49:48.022183-05');
INSERT INTO public.entity_beat_appearances VALUES (595, 506, 115, 'unknown', true, 'Compels Todd to hold on despite fatigue and frustration; prevents him from releasing the investigation.', '2026-02-27 13:49:48.022183-05');
INSERT INTO public.entity_beat_appearances VALUES (596, 503, 115, 'neutral', false, 'Todd believes truth is out there, hidden in the mess, and is determined to expose it.', '2026-02-27 13:49:48.022183-05');
INSERT INTO public.entity_beat_appearances VALUES (597, 159, 115, 'enemy', false, 'Unknown entity that Todd believes has to be behind this and is determined to expose.', '2026-02-27 13:49:48.022183-05');
INSERT INTO public.entity_beat_appearances VALUES (598, 195, 116, 'ally', true, 'Storms in, confronts Todd about chaos and living conditions; expresses frustration and concern for their daughter.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (599, 157, 116, 'ally', false, 'Recipient of Stacey''s confrontation; startled from focus.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (600, 512, 116, 'neutral', false, 'Visual representation of chaos consuming the home.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (601, 513, 116, 'neutral', false, 'Setting for confrontation; physical manifestation of deterioration.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (602, 157, 117, 'ally', true, 'Justifies obsession by claiming everything is connected; admits he is close to answers.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (603, 511, 117, 'unknown', false, 'Underlying force preventing Todd from stopping; justifies his behavior.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (604, 516, 117, 'unknown', false, 'Referenced as goal just beyond reach; drives Todd''s continued investigation.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (605, 195, 118, 'ally', true, 'Anger softens to sadness; expresses understanding but reaches her emotional limit.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (606, 157, 118, 'ally', false, 'Recipient of Stacey''s emotional shift; realizes the toll of his obsession.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (607, 514, 118, 'ally', false, 'Underlying emotion tempering Stacey''s anger; conflict between love and self-preservation.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (608, 148, 118, 'unknown', false, 'Shared state defining Stacey''s emotional limits.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (609, 157, 119, 'ally', true, 'Admits he cannot stop; confesses that stopping feels like falling apart.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (610, 195, 119, 'ally', false, 'Expresses longing for what they were; uncertainty about endurance.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (611, 511, 119, 'unknown', false, 'Defines Todd''s inability to stop; tied to his sense of self.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (612, 514, 119, 'ally', false, 'Mutual admission of missing each other; paradox of love and destruction.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (613, 195, 120, 'ally', true, 'Leaves with brief hand squeeze; abandons hope of changing Todd but maintains love.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (614, 157, 120, 'ally', false, 'Left alone to return to investigation; hopes to find answers before losing everything.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (615, 512, 120, 'neutral', false, 'Headlines flutter, calling Todd back into tangled investigation world.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (616, 516, 120, 'unknown', false, 'Waiting to be uncovered; represents Todd''s final hope and his greatest loss.', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.entity_beat_appearances VALUES (617, 518, 121, 'neutral', true, 'Sites of mysterious construction, obscured by barriers, operating 24/7 with no official explanation.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (618, 519, 121, 'neutral', true, 'Causes resident sleeplessness through incessant machinery operation.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (619, 276, 121, 'neutral', false, 'Widespread effect of construction noise on residents near transportation hubs.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (620, 521, 121, 'neutral', false, 'Residents theorize about government cover-ups and secretive corporate ventures due to lack of official information.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (621, 522, 121, 'neutral', false, 'Provide no information about the construction, fueling speculation.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (622, 538, 121, 'neutral', false, 'Familiar urban rhythms replaced by constant construction clamor.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (623, 517, 122, 'unknown', true, 'Synchronized construction projects from Beijing to Miami become evident as coordinated global effort.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (624, 523, 122, 'unknown', true, 'Speculation mounts that vast resources and coordination point to a single hidden entity orchestrating developments.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (625, 42, 122, 'neutral', false, 'Scale and secrecy confound experts, who offer theories from transport networks to defense initiatives.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (626, 525, 123, 'neutral', true, 'Unprecedented demand for steel, concrete, and essential materials creates global scarcity and price spikes.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (627, 524, 123, 'neutral', true, 'Internet-dubbed phenomenon describing panic and economic strain from the Grid''s insatiable material consumption.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (628, 540, 123, 'neutral', false, 'Industries from automotive to furniture manufacturing experience slowdowns due to resource scarcity.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (629, 526, 123, 'neutral', false, 'Experiences production slowdowns due to material scarcity.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (630, 527, 123, 'neutral', false, 'Experiences production slowdowns due to material scarcity.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (631, 528, 124, 'ally', true, 'Hacker network launches coordinated campaign to expose Global Grid secrets through file leaks and network infiltration.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (632, 529, 124, 'ally', false, 'Public declaration calling for transparency and accountability, becoming rallying point for truth-seekers.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (633, 542, 124, 'neutral', false, 'Confidential information stolen and leaked by Ghostnet to expose the Grid.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (634, 543, 124, 'neutral', false, 'Galvanized by Ghostnet''s leaks, public demands answers about the Grid''s purpose.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (635, 530, 125, 'ally', true, 'Unite to protect ancestral Amazon lands from advancing Global Grid development.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (636, 531, 125, 'neutral', false, 'Ancestral territory threatened by Grid encroachment.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (637, 532, 125, 'neutral', false, 'Indigenous environmental wisdom used as cultural and ecological defense against Grid expansion.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (638, 533, 126, 'neutral', false, 'Global forum where world leaders demand answers about the Grid.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (640, 517, 126, 'unknown', true, 'Subject of international diplomatic pressure; rapid complex structures with no transparency cause security concerns.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (641, 535, 126, 'neutral', false, 'International relations deteriorate due to lack of transparency about the Grid.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (642, 536, 126, 'neutral', false, 'World leaders fear implications for national security and sovereignty.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (643, 537, 126, 'neutral', false, 'Nations demand identification of responsible entities and clarity on Grid''s purpose.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (644, 278, 127, 'ally', true, 'Anticipates escape but is held back by work; scrambles to pack and depart late.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (645, 473, 127, 'ally', false, 'Shares anticipation for the camping trip; part of the delayed departure.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (646, 548, 127, 'enemy', true, 'Last-minute meeting refuses to release protagonist, pushing departure into evening.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (647, 478, 127, 'neutral', false, 'Finally arrives as long-awaited escape; delayed by work obligations.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (648, 278, 128, 'ally', true, 'Fumbles through tent setup in darkness; mutters about packing issues but is drawn into son''s adventurous spirit.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (649, 473, 128, 'ally', true, 'Creatively transforms tent setup chaos into adventure; infectious antics uplift the experience.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (650, 549, 128, 'neutral', false, 'Dark and imposing; shadows stretch like sentinels; tests the campers with fire-ant piles and darkness.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (651, 552, 128, 'neutral', false, 'Stubborn poles and obstacles become vehicles for adventure through son''s creativity.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (652, 553, 128, 'neutral', false, 'Complete darkness challenges tent assembly; only flashlights and desire drive progress.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (653, 278, 129, 'ally', true, 'Savors the campfire moment; observes and reflects on the profound nature of the experience.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (654, 551, 129, 'ally', false, 'Gathered at campfire with peaceful smiles; creates welcoming community.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (655, 554, 129, 'neutral', true, 'Central gathering point; crackles with laughter and life; facilitates the profound moment.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (656, 555, 129, 'neutral', false, 'Marshmallows brown and blister; central sensory pleasure and bonding activity.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (657, 556, 129, 'neutral', false, 'Quiet majesty overhead; witness to the peaceful gathering below.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (658, 557, 129, 'neutral', false, 'Flickering flames mirrored in their faces; collective expression of wonder and peace.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (659, 558, 129, 'neutral', false, 'Grounds the moment through murmuring conversations and embers; creates peaceful anchor.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (660, 559, 129, 'neutral', true, 'Crystallizes as protagonist savors the sensory richness and senses transcendence beyond camping.', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.entity_beat_appearances VALUES (661, 561, 130, 'neutral', true, 'Begins telling the story of ancient scouts who ventured beyond marked trails and encountered something strange in the forest.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (662, 554, 130, 'neutral', false, 'Dying fire provides atmospheric backdrop; pops and hisses as the scoutmaster draws everyone into the narrative.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (663, 551, 130, 'ally', false, 'Gathered audience, drawn in by the scoutmaster''s deliberate pacing and low voice.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (664, 568, 130, 'ally', false, 'Feels the weight of the story directed at them; shifts under the scoutmaster''s deliberate gaze.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (665, 565, 131, 'unknown', true, 'The scoutmaster describes this hidden clearing alive with impossible geometry, shadows of gears, and tendrils moving in illogical ways. It offers glimpses of future and unspoken truths but demands something in return.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (666, 566, 131, 'unknown', false, 'A relentless sound that grows louder as scouts venture deeper, vibrating through bones and resonating through trees, emanating from or connected to the Power of Infinity.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (719, 583, 140, 'ally', true, 'Struggles to stay calm and lead; doubt gnaws at him; time warps into meaningless stretches; barely believes his own reassurances.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (936, 734, 175, 'neutral', false, 'Acts as the physical setting for the narrator''s moment of despair.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (667, 567, 131, 'neutral', false, 'The scouts who explored beyond marked trails, encountered the Power of Infinity, and were transformed by it, returning with hollow eyes.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (668, 571, 131, 'unknown', false, 'Described as a testing force with seemingly sentient qualities; possesses the ability to show explorers what they need to see.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (669, 227, 131, 'unknown', false, 'Manifested in those who returned from the Power of Infinity as a hollow look, as if a piece of them had been left behind.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (670, 561, 132, 'neutral', true, 'Delivers cryptic final message, locking his gaze onto the protagonist; shifts tone to something softer and intimate; offers assurance despite the disturbing narrative.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (671, 568, 132, 'ally', false, 'Sits frozen, experiencing the scoutmaster''s gaze as intensely meaningful; hears the forest''s hum louder and more familiar; recognizes something in the words.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (672, 551, 132, 'ally', false, 'Remains silent, filled with nervous tension, the weight of the story and its implications hanging heavily around them.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (673, 566, 132, 'unknown', false, 'Becomes louder and more present in the protagonist''s awareness, echoing something far too familiar from their buried past.', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.entity_beat_appearances VALUES (674, 221, 133, 'unknown', true, 'Lies restless on thin sleeping pad, mind haunted by scoutmaster''s story; night sounds amplify unease.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (675, 575, 133, 'neutral', false, 'Confines the narrator, offering shelter but no psychological refuge.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (676, 576, 133, 'unknown', false, 'Generates night sounds and atmosphere that feed the narrator''s dread.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (677, 577, 133, 'unknown', false, 'Faint rhythmic hum punctuates the silence, intensifying unease through mystery.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (678, 581, 133, 'unknown', false, 'Tugs at the narrator despite seeming ridiculous; bridges rational skepticism and irrational compulsion.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (679, 457, 133, 'unknown', false, 'Sharpened by stillness and creaks of branches; central emotional force.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (680, 561, 133, 'neutral', false, 'Story weaves itself into fabric of narrator''s thoughts; absent physically but omnipresent mentally.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (681, 579, 133, 'neutral', false, 'Claims the narrator, drawing him toward sleep despite unease.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (682, 578, 134, 'neutral', true, 'Tangled realm of fog and endless trees where machinery hum persists; offers no relief from waking dread.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (683, 576, 134, 'unknown', false, 'Manifests in dreams as endless trees shrouded in thick fog; setting merges with subconscious.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (684, 577, 134, 'unknown', false, 'Rhythmic hum threads through dream-fog; bridges waking unease and subconscious dread.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (685, 457, 134, 'unknown', false, 'Persists and deepens in dreams; becomes omnipresent force across all states of consciousness.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (686, 221, 134, 'unknown', false, 'Trapped in dreams; physically at rest but mentally unable to escape the story''s pull.', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.entity_beat_appearances VALUES (687, 551, 135, 'neutral', true, 'Scouts gather at camp kitchen, excited and energized for the day''s merit badge activities.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (688, 561, 135, 'neutral', false, 'Oversees scouts; his story from the night before lingers in scouts'' imaginations.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (689, 583, 135, 'neutral', false, 'Present at camp, observing scouts'' excitement and preparation.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (690, 592, 135, 'neutral', true, 'Infectious energy and excitement permeates the gathering; eyes shining with joy.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (691, 590, 135, 'neutral', false, 'Provided to scouts as tools for navigation and merit badge activities.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (692, 591, 135, 'neutral', false, 'Provided to scouts as tools for navigation and merit badge activities.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (693, 551, 136, 'neutral', true, 'Scouts navigate forest throughout the day, reaching checkpoints, celebrating triumphs, sharing lighthearted banter and snacks.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (694, 549, 136, 'neutral', true, 'Provides the setting for scout navigation; beautiful, expansive, full of life; offers nothing disruptive.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (695, 595, 136, 'neutral', true, 'Cuts through forest stillness as scouts celebrate checkpoint reaches; reflects camaraderie and joy.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (696, 596, 136, 'neutral', true, 'Motivates scouts'' navigation efforts; drives the day''s activities and achievements.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (697, 589, 136, 'neutral', false, 'Targets for scout navigation; scouts successfully reach them throughout the day.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (698, 583, 137, 'neutral', true, 'Watches scouts return to camp; confronted with worst fear as son''s patrol fails to appear; confirmed missing.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (699, 455, 137, 'neutral', true, 'Member of missing patrol; has not returned to camp by evening; patrol status confirmed as missing.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (700, 585, 137, 'enemy', true, 'Scout patrol led by narrator''s son; fails to reach checkpoints; does not return to camp; confirmed missing by scoutmaster.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (701, 561, 137, 'neutral', true, 'Tallies returning scout groups; confirms that narrator''s son''s patrol is missing; delivers devastating news.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (702, 215, 137, 'enemy', true, 'Materializes as scouts are accounted for; crystallizes into horror upon confirmation of missing patrol.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (703, 597, 137, 'enemy', true, 'Narrator''s deepest fear regarding son''s safety is confirmed when scoutmaster reports patrol missing.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (704, 595, 137, 'neutral', false, 'Returning scouts'' joyful laughter and triumph; conspicuously absent for the missing patrol.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (705, 589, 137, 'neutral', false, 'Missing patrol failed to reach several checkpoints, not even the easiest ones, despite weeks of training.', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.entity_beat_appearances VALUES (706, 602, 138, 'ally', true, 'Organizes and fans out into the forest with flashlights and maps as darkness falls.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (707, 603, 138, 'enemy', true, 'Swallows shouts; resists the search party''s efforts; roots snag boots; branches snap back as deliberate obstacles.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (708, 604, 138, 'enemy', true, 'Encroaching and consuming; obscures trails and landmarks.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (709, 583, 138, 'ally', true, 'Leads the search party; feels breath growing shallow as the labyrinth deepens.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (710, 613, 138, 'enemy', false, 'Stretch long and claw-like, leaning in as though watching.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (712, 605, 139, 'neutral', true, 'Breaks through the edge of perception, trembling and disjointed, guiding the narrator forward.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (713, 583, 139, 'ally', true, 'Surges forward following the voice, tripping and stumbling until finding the lost patrol.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (714, 168, 139, 'unknown', false, 'Jolts through the narrator''s veins, propelling him toward the clearing.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (715, 601, 139, 'ally', true, 'Found standing nervously in a clearing; pale faces showing terror melted with relief; unable to explain what happened.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (716, 600, 139, 'ally', true, 'Voice cracks as he attempts to explain the impossible: ''We kept going back. No matter where we turned, we ended up... here.''', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (717, 590, 139, 'neutral', false, 'One scout holds a shredded map with white knuckles.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (718, 603, 140, 'mini-boss', true, 'Tightens its grip; loops trails impossibly; stretches distances; warps time; closes in around the group with each turn.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (4080, 3123, 929, 'enemy', false, 'Their absence is the source of the tension.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (720, 604, 140, 'enemy', false, 'Twists the landscape; closes in; flashlight beams flicker across shapes that seem to shift.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (721, 601, 140, 'ally', false, 'Cling to one another; whisper nervous questions; show panic bleeding into fear.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (722, 183, 140, 'enemy', false, 'Gnaws at the narrator; undermines his leadership and strained reassurances.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (723, 617, 140, 'enemy', false, 'Minutes stretch into hours; temporal disorientation exhausts the group.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (724, 619, 140, 'enemy', false, 'Weight of darkness and exhaustion presses harder with each step; chest tightens.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (725, 614, 140, 'enemy', false, 'Loom closer like grasping bones.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (726, 615, 140, 'enemy', false, 'Drag at boots; terrain drags at the group with each step.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (727, 554, 141, 'ally', true, 'Faint glow breaks through the trees after hours of disorientation; feels unreal, like a mirage from desperation.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (728, 601, 141, 'ally', true, 'Stumbles into camp, collapses in relief.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (729, 583, 141, 'ally', true, 'Senses the forest deliberately released them; cannot dismiss the feeling that the forest is watching, waiting for another chance.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (730, 603, 141, 'mini-boss', false, 'Releases the group because it wanted to; continues watching and waiting for another opportunity to pull them back.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (731, 616, 141, 'unknown', false, 'Palpable relief as the group reaches camp; though fear lingers.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (732, 620, 141, 'unknown', false, 'Uncertainty whether the campfire is real or another forest delusion.', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.entity_beat_appearances VALUES (733, 624, 142, 'neutral', true, 'Rapidly forget terror and scatter into games of manhunt, their laughter ringing through trees as if nothing happened.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (734, 628, 142, 'enemy', false, 'Dissolves completely and abruptly, leaving narrator questioning if it was real or imaginary.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (735, 549, 142, 'unknown', false, 'Nightmare dissolved; its maze-like chaos gave way to apparent normalcy.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (736, 221, 142, 'ally', false, 'Observes scouts'' rapid emotional recovery with disbelief; wonders if the terror was real.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (737, 221, 143, 'ally', true, 'Sits by dying campfire, finding momentary relief in son''s retelling but haunted by underlying unease.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (738, 473, 143, 'ally', true, 'Recounts day''s adventures with animated enthusiasm, bright eyes, witty observations, and infectious grin.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (739, 554, 143, 'neutral', false, 'Dwindled to embers; provides fading warmth and crackle as comforting backdrop to son''s story.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (740, 629, 143, 'neutral', false, 'Darkness presses in; shadows dance; twigs snap and leaves crunch beyond firelight, sending narrator''s eyes darting.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (741, 631, 143, 'enemy', false, 'Persists despite momentary relief from son''s animated retelling; underlying unease never truly fades.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (742, 632, 143, 'neutral', false, 'Seated around campfire with narrator and scouts; part of the recovered normalcy.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (743, 221, 144, 'ally', true, 'Lies in tent; replays fragmented events; unable to distinguish reality from imagination; drifts into uneasy sleep.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (744, 627, 144, 'neutral', false, 'Canvas interior becomes isolation chamber where narrator stares at ceiling and obsessively replays the day.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (745, 444, 144, 'enemy', true, 'Day''s events loop: drone of unseen lowing, looping trails, forest that seemed to breathe; cling to narrator, blurring reality and imagination.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (746, 549, 144, 'enemy', false, 'Sentient or malevolent presence; ''seems not done'' with the narrator; haunts him even in the tent.', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.entity_beat_appearances VALUES (747, 278, 145, 'unknown', true, 'Running through fractured kaleidoscope landscape with no memory of why; lungs burning, driven by oppressive drone in air.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (748, 641, 145, 'neutral', false, 'World spins around protagonist; ground shifts between cornstalks, earth, gravel, and molten tar-like substance.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (749, 647, 145, 'neutral', false, 'Protagonist became lost trying to return to workshop despite knowing these fields like back of their hand.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (750, 278, 146, 'unknown', true, 'Pushes through jagged branches into forest; stumbles on gnarled roots; mind screams that this familiar place has become deeply wrong.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (751, 636, 146, 'neutral', true, 'Opens before protagonist; path twists in impossible loops; ancient trees warp familiar landmarks into grotesque parodies; ground sticky and treacherous.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (752, 644, 146, 'neutral', false, 'Tear at protagonist''s arms leaving trails of icy fire as they push through.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (753, 643, 146, 'neutral', false, 'Erupt from ground like skeletal hands; protagonist stumbles on them.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (754, 642, 146, 'neutral', false, 'Violent purple and black with jagged lightning illuminating sneering, whispering faces in clouds.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (755, 278, 147, 'unknown', true, 'Trudges through molasses-like ground; presses hands to ears against invasive voices; body moves forward compulsively despite terror; every nerve screams to turn back.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (756, 640, 147, 'mini-boss', true, 'Looms beyond veil of fog; exerts invisible tether; fills protagonist with palpable dread; waits patiently for protagonist to be drawn to unnamed destination.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (757, 637, 147, 'enemy', false, 'Swirl and slither around protagonist mockingly; dart and recoil as if sentient and predatory.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (758, 638, 147, 'enemy', true, 'Grow louder and more invasive; wrap around mind like barbed wire; slither like worms through thoughts; unravel protagonist''s resolve.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (759, 639, 147, 'enemy', false, 'Flicker through thick fog with unnaturally bending and stretching forms; carry whispers filled with malice.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (760, 646, 147, 'neutral', false, 'Thick veil that obscures distorted figures and the ancient presence beyond; creates sense of unseen danger.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (761, 645, 147, 'enemy', false, 'Pulls protagonist forward despite every nerve screaming to resist; compels movement toward unnamed destination.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (762, 650, 147, 'neutral', false, 'Thick, sour, choking air fills lungs with rot; intensifies nightmarish atmosphere.', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.entity_beat_appearances VALUES (763, 278, 148, 'ally', true, 'Stumbles into clearing and recognizes it; approaches the device with trembling limbs.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (764, 653, 148, 'neutral', false, 'Revealed as recognized location where son''s patrol was found; throbs with testing energy.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (765, 654, 148, 'unknown', true, 'Spotted embedded in tree bark; its faint glow cuts through fog like a beacon.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (766, 655, 148, 'unknown', false, 'Massive tree at center of clearing; serves as anchor for the device.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (767, 658, 148, 'neutral', false, 'Referenced as historical event; adds emotional weight to location recognition.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (768, 278, 149, 'ally', true, 'Reaches for device; fingers slip against cold surface; body screams for relief as world tightens.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (769, 654, 149, 'enemy', true, 'Actively resists removal; pulsates with icy heat; refuses to relinquish hold from tree.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (770, 656, 149, 'enemy', true, 'Escalate into cacophony of screams; each voice like jagged blade slicing into mind.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (771, 657, 149, 'enemy', true, 'Tightens world around protagonist; branches twist into cage; ground heaves; threatens complete consumption.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (772, 661, 149, 'enemy', false, 'Bites into skin like frost; transmits contradictory icy heat; saps strength.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (773, 660, 149, 'ally', false, 'Quivers and weakens; lungs gasp for thick air; vision darkens at edges; strength ebbs.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (774, 278, 150, 'ally', true, 'Summons desperate certainty that failure means death; delivers primal roar; grits teeth and gives final violent pull; twists body backward.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (775, 654, 150, 'enemy', true, 'Resists extraction; tears free with gut-wrenching snap; protagonist succeeds in claiming it.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (776, 657, 150, 'enemy', true, 'Looms as existential threat; protagonist''s body is battering ram against its will to consume.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (777, 660, 150, 'ally', false, 'Twisted violently; throws weight backward; reaches final reserves of strength in primal roar.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (778, 278, 151, 'ally', true, 'Collapses to ground; clutches device to chest; world spins wildly; faces absolute silence.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (779, 654, 151, 'unknown', true, 'Extracted and now held against protagonist''s chest; catalyst for forest''s eruption and collapse.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (780, 657, 151, 'enemy', true, 'Erupts in explosion of sound and light; shudders in agony; collapses into complete silence.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (781, 655, 151, 'unknown', false, 'Shudders as though in agony when device tears free; participates in forest''s eruption.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (782, 656, 151, 'enemy', false, 'Becomes single shrieking note; then dissolves into silence.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (783, 659, 151, 'neutral', true, 'Descends as final state after eruption; suffocating and complete; marks transformation or ritual completion.', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.entity_beat_appearances VALUES (784, 278, 152, 'ally', true, 'Abruptly awakens at campsite edge, jolted from nightmare as though thrown through glass; trembling, exhausted, clutching the mysterious device.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (785, 673, 152, 'neutral', true, 'Violent, disorienting transition from nightmare to waking reality defines the opening moment.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (786, 667, 152, 'neutral', false, 'Morning sun streams through trees, creating a bright, serene setting that mockingly contrasts with protagonist''s terror.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (787, 668, 152, 'neutral', false, 'Cheerful melody feels jarring and mocking despite its brightness.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (788, 665, 152, 'unknown', true, 'Cold weight in protagonist''s hand grounds them even as mind reels; central to their distress.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (789, 672, 152, 'neutral', false, 'Body completely exhausted as though protagonist had run an ultra-marathon.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (790, 674, 152, 'neutral', false, 'Fingers trembling as they hold the device; physical manifestation of psychological distress.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (791, 664, 153, 'neutral', true, 'Walks up unexpectedly behind protagonist; questions them casually about the object; suggests returning to camp.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (792, 278, 153, 'ally', true, 'Startled by the scoutmaster''s approach; whispers explanation about finding the device in a tree.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (793, 670, 153, 'neutral', false, 'Heavy footsteps crunch on forest floor, alerting protagonist to the scoutmaster''s presence.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (794, 561, 153, 'neutral', false, 'Mentioned as making famous cold pressed coffee; offers indirect incentive for protagonist to return to camp.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (795, 665, 153, 'unknown', false, 'Object of the scoutmaster''s casual question; protagonist takes one last look before stashing it.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (796, 278, 154, 'ally', true, 'Stashes device hastily in pocket; heart racing; makes way back to campsite guided by coffee aroma.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (797, 665, 154, 'unknown', false, 'Stashed hastily in protagonist''s pocket; taken one last look before concealment.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (798, 669, 154, 'neutral', true, 'Unmistakable aroma of brewing coffee grounds protagonist in reality and leads them back to camp; grounding force against racing heart.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (799, 550, 154, 'neutral', false, 'Destination; protagonist navigates back using coffee aroma as guide.', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.entity_beat_appearances VALUES (800, 278, 155, 'unknown', true, 'Breaking camp and acknowledging the weight of the device as puzzle, answer, and terrifying purpose', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (801, 677, 155, 'unknown', true, 'Grounding protagonist; representing untapped potential, terror, and inner purpose', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (802, 549, 155, 'neutral', false, 'Clinging to protagonist with whispers, shadows, and suffocating stillness; reluctant to release', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (803, 685, 155, 'ally', false, 'Deep inner calling awakened by the device that protagonist hadn''t realized they were searching for', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (804, 278, 156, 'unknown', true, 'Driving long road home; experiencing disorientation as familiar world becomes strange', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (805, 324, 156, 'neutral', false, 'Endless ribbon of asphalt serving as transitional space between forest and civilization', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (806, 680, 156, 'neutral', false, 'Landmarks now appearing strange and altered; world seen through warped lens', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (807, 677, 156, 'unknown', false, 'Constant humming reminder of boundary between reality and dream becoming paper-thin', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (808, 686, 156, 'neutral', true, 'Growing separation between protagonist''s perception and objective reality; forest''s influence persisting', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (809, 278, 157, 'unknown', true, 'Churning with conflicting emotions; heart racing as competing forces battle for their commitment', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (810, 682, 157, 'neutral', true, 'Beckoning loud and persistent with responsibilities and comforting monotony', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (811, 677, 157, 'unknown', true, 'Representing key to something greater or potential trap; embodying possibilities protagonist must choose between', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (812, 103, 157, 'ally', false, 'Pulling protagonist toward understanding and unlocking device''s mysteries', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (813, 684, 157, 'enemy', false, 'Restraining force warning against embracing the unknown represented by the device', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (814, 278, 158, 'unknown', true, 'Arriving home in late afternoon; achieving fragile peace and accepting lingering mysteries', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (815, 681, 158, 'neutral', false, 'Offering sanctuary and return to ordinary life; blessing of normality', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (816, 549, 158, 'neutral', false, 'Left behind but mysteries lingering at edges of protagonist''s mind; unresolved but accepted', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (817, 677, 158, 'unknown', false, 'Whispering of adventures yet to come; quiet reminder that nothing is truly over', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (818, 687, 158, 'ally', true, 'Settling over protagonist; allowing acceptance of mysteries and device''s promise simultaneously', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.entity_beat_appearances VALUES (819, 221, 159, 'ally', true, 'Wakes from sleep, clinging to weekend memories while dread seeps into bones.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (1313, 157, 270, 'enemy', true, 'Passionately accuses Stacey of being blind to the conspiracy orchestrated by S Corp.', '2026-02-27 14:36:01.424183-05');
INSERT INTO public.entity_beat_appearances VALUES (1314, 195, 270, 'ally', false, 'Pleads with Todd to stop his paranoid accusations, expressing her fear.', '2026-02-27 14:36:01.424183-05');
INSERT INTO public.entity_beat_appearances VALUES (822, 215, 159, 'enemy', true, 'Seeps into narrator''s bones upon waking; contrasts with weekend serenity.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (823, 472, 159, 'ally', false, 'Sleeps peacefully beside narrator, her steady breathing stark contrast to his internal turmoil.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (824, 696, 159, 'unknown', false, 'Sits on nightstand, amplifying narrator''s sense of unease and deepening dread.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (825, 698, 160, 'enemy', true, 'Vivid, unsettling nocturnal vision clings like toxic fog; feels real and tangible despite being a dream.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (826, 697, 160, 'mini-boss', true, 'Incomprehensible mechanism with pulsing rhythms and shifting shadows; hum acts as siren''s call; pulls at narrator''s core.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (827, 221, 160, 'ally', true, 'Wanders through labyrinth of machine; feels allure of understanding mixed with terror; jolts awake in cold sweat.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (828, 221, 161, 'ally', true, 'Connects dream to Pointers, worries about mental state and reality dissolution.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (1315, 1104, 270, 'enemy', false, 'Is the subject of Todd''s rant about rewriting memories and lives.', '2026-02-27 14:36:01.424183-05');
INSERT INTO public.entity_beat_appearances VALUES (830, 696, 161, 'unknown', true, 'Possibly found by narrator; seemingly connected to both dream and Pointers.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (831, 703, 161, 'enemy', true, 'Narrator questions if mind is unraveling, grasping for threads in darkness.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (1316, 159, 270, 'enemy', false, 'Named by Todd as the puppet master behind The Conspiracy.', '2026-02-27 14:36:01.424183-05');
INSERT INTO public.entity_beat_appearances VALUES (833, 221, 162, 'ally', true, 'Drags himself through motions of morning; thoughts tangled with dread and obsession; senses inevitable collapse.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (834, 701, 162, 'neutral', false, 'Each step feels heavier than the last; mechanical and burdensome.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (835, 702, 162, 'enemy', true, 'Looms ordinary on surface yet carries weight of inevitability; harbinger of collapse.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (836, 704, 162, 'enemy', true, 'Narrator feels shift in air; fragile order of life about to break; collapse becomes absolute by day''s end.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (837, 221, 163, 'ally', true, 'Walks through the stripped office, gripped by unease; observes transformation and packs away Christmas ornaments.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (838, 709, 163, 'neutral', true, 'Serves as the setting; once-vibrant now alien, silent, and lifeless; stripped of personal touches.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (839, 457, 163, 'neutral', false, 'Grips the narrator as they move through the office; deepens with each observation.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (840, 712, 163, 'neutral', false, 'Invades narrator''s nose as an unsettling scent of old wood and damp soil; signals decay.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (841, 221, 164, 'ally', true, 'Reflects on nearly a decade of hard-earned success, triumphs, and respect as the company''s ''IT Doctor'' and crisis navigator.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (842, 713, 164, 'neutral', true, 'Once benefited from narrator''s crisis management and stabilization; now deteriorated.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (843, 720, 164, 'neutral', false, 'Narrator''s hard-earned sense of stability now feels like a faded photograph, evidence of a time before rot.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (844, 717, 164, 'ally', false, 'Once relied on narrator; affectionately called them ''IT Doctor'' for diagnostic and fixing expertise.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (845, 221, 165, 'ally', true, 'Blames COO and CEO for company deterioration; recognizes systemic corruption masquerading as incompetence.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (846, 366, 165, 'mini-boss', true, 'Primary antagonist; chaos incarnate, hired for proximity to power; over-promises, under-delivers; deflects blame while stealing credit.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (847, 128, 165, 'enemy', true, 'Complicit through willful blindness; bound to COO in unnatural, shadow-forged partnership; laughs at employees'' struggles.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (849, 718, 165, 'neutral', false, 'Half-jokes and half-truths about COO''s alleged supernatural agreement; reflect collective suspicion.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (850, 221, 166, 'ally', true, 'Resolves to bury resentment and continue job despite chaos; pushes everything down into their cold chest.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (852, 713, 166, 'neutral', false, 'Narrator continues to serve despite deterioration; unwinnable battle against forces thriving on collapse.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (853, 221, 167, 'ally', true, 'On client call; detects seismic disturbances; senses impending doom through instinct.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (854, 366, 167, 'enemy', true, 'Causes rhythmic thudding; approaching with HR rep; generates foreboding presence.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (855, 741, 167, 'unknown', false, 'Manifestation of dread; crescendos as COO approaches.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (856, 724, 167, 'neutral', false, 'Enters silently behind COO; expression unreadable; foreboding presence.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (857, 366, 168, 'mini-boss', true, 'Launches verbal assault; fires narrator with profanity; spittle flies; voice shakes walls; reads scripted litany; brays like unhinged creature.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (858, 221, 168, 'ally', true, 'Frozen between disbelief and fury; palms slick; throat dry; stares at COO; begs HR rep with gaze.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (859, 724, 168, 'neutral', false, 'Nervous tittering; offers no intervention; becomes salt in the wound through complicity.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (860, 733, 168, 'unknown', false, 'Shoved toward narrator; begin accumulation of oppressive legality.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (861, 221, 169, 'ally', true, 'Processes betrayal; shallow gasps; feels cosmic weight; trapped in office; recognizes destruction of legacy.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (863, 729, 169, 'unknown', true, 'Years of expertise, technology, relationships stripped away; reduced to hollow shell.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (864, 730, 169, 'unknown', false, 'Raw cosmic weight; echoes through room; marks fundamental rupture in narrator''s existence.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (865, 736, 169, 'unknown', false, 'Manifests as assault on principles; integrity, loyalty, transparency crushed beneath weight of COO''s jihad.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (866, 366, 170, 'mini-boss', true, 'Leans back in narrator''s chair (squealing); wears smug grin; dismisses possessions as worthless crap; orders immediate departure.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (867, 221, 170, 'ally', true, 'Questions about belongings; watches chair scream; receives cutting dismissal; words cut deeper than indignity itself.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (869, 724, 170, 'neutral', false, 'Flinches at cruelty but remains silent; lips pressed into thin, unreadable line; passive witness continues.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (870, 725, 171, 'enemy', true, 'Arrive with broad shoulders and expressionless faces; declare no negotiation; clamp hands on narrator''s arms with iron grips; frog-march narrator through halls.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (871, 221, 171, 'ally', true, 'Does not struggle; numb; heart pounds with despair and fury; treated as prisoner; dragged through office; glimpses pale-faced survivors.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (872, 727, 171, 'neutral', false, 'Silent and motionless; pale faces with vacant eyes; pity and fear warring within; terrified to intervene; willing themselves invisible.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (873, 736, 171, 'unknown', false, 'Forced seizure; mechanical precision; treatment as prisoner rather than human; reverberation through entire being.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (848, 716, 165, 'enemy', false, 'Is remembered as evidence of the COO''s unnatural, dark influence.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (851, 714, 166, 'neutral', false, 'Is consciously pushed down and buried within the narrator''s chest, a simmering force beneath a professional exterior.', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.entity_beat_appearances VALUES (862, 728, 169, 'enemy', true, 'Manifests as a physical and cosmic weight, crushing years of the narrator''s dedication.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (868, 735, 170, 'neutral', false, 'Are devalued and threatened with disposal by the COO.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (935, 788, 175, 'enemy', false, 'Settles into the narrator''s stomach, a ''cold and immovable'' presence.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (874, 738, 171, 'unknown', false, 'Wild pounding in narrator''s chest; audible manifestation of emotional collapse during forced removal.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (875, 221, 172, 'ally', true, 'Sits alone in car; unable to move; numb; paralyzed by enormity of loss; phone untouched; stares through windshield at nothing; time blurs.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (876, 732, 172, 'unknown', true, 'Cloak settling over narrator; prevents thinking, acting; becomes complete dissociation in solitary car.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (878, 737, 172, 'unknown', false, 'Lingers in narrator''s mouth; marks permanent exile from office; taste of torn-away life.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (879, 740, 172, 'unknown', false, 'Blurs and stretches; each second becomes eternity; becomes meaningless in narrator''s paralysis.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (880, 743, 159, 'ally', true, 'Wakes up and struggles against the pull of a dreaded reality, clinging to positive memories.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (820, 331, 159, 'enemy', false, 'Shatters the narrator''s sleep, forcing him into the day.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (882, 745, 159, 'enemy', false, 'Seeps into the narrator''s consciousness as he wakes.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (821, 691, 159, 'ally', false, 'Acts as a fleeting mental reprieve for the narrator.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (884, 455, 159, 'ally', false, 'His laughter is recalled as part of the Weekend Memories.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (885, 743, 160, 'ally', true, 'Recalls a vivid and unsettling dream that felt tangibly real.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (886, 748, 160, 'mini-boss', true, 'Dominates the narrator''s dream memory with its hypnotic and sinister presence.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (887, 749, 160, 'enemy', false, 'Inhabit the machine, adding to the sense of being watched.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (888, 743, 161, 'ally', true, 'Tries to connect the dream to the Pointers and The Device, questioning his own sanity.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (829, 39, 161, 'unknown', false, 'Enter the narrator''s thoughts as a possible explanation for the strange events, representing a source of global unease.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (890, 751, 161, 'unknown', false, 'Sits menacingly on the nightstand, suspected by the narrator to be a catalyst for his experiences.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (891, 743, 162, 'ally', true, 'Forces himself through his morning routine under the weight of his chaotic thoughts and a sense of impending doom.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (832, 331, 162, 'enemy', false, 'Sounds again, pulling the narrator from his obsessive thoughts back to the immediate present.', '2026-02-27 13:57:17.721641-05');
INSERT INTO public.entity_beat_appearances VALUES (893, 752, 162, 'enemy', true, 'Manifests as a powerful premonition that the narrator''s world is about to fracture.', '2026-02-27 14:04:23.20534-05');
INSERT INTO public.entity_beat_appearances VALUES (894, 755, 163, 'ally', true, 'Walks through the changed office, feeling an increasing sense of unease and disconnection as they observe the bare walls and strange smell.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (895, 445, 163, 'neutral', false, 'Acts as the catalyst for the narrator''s mood, its hollowed-out state mirroring a deeper decay.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (896, 757, 163, 'enemy', false, 'Invades the narrator''s senses, providing a tangible signal that something is fundamentally wrong.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (897, 758, 163, 'neutral', false, 'Manifests and deepens within the narrator as they pack away personal items, solidifying their alienation.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (898, 755, 164, 'ally', true, 'Reflects on their past accomplishments and respected status within the company.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (899, 759, 164, 'neutral', false, 'Is recalled as a memory of a better time, highlighting the contrast between the company''s stable past and chaotic present.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (900, 125, 165, 'mini-boss', true, 'Is identified as the parasitic source of the company''s rot, a chaotic force of incompetence and potential supernatural malevolence.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (901, 761, 165, 'enemy', false, 'Is described as the COO''s enabler, blinded by their personal relationship and complicit in the company''s destruction.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (902, 755, 165, 'ally', false, 'Recounts the damage caused by the leadership duo, expressing deep contempt and suspicion.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (904, 755, 166, 'ally', true, 'Resolves to continue performing their duties despite the situation.', '2026-02-27 14:05:27.01787-05');
INSERT INTO public.entity_beat_appearances VALUES (906, 743, 167, 'ally', false, 'Notices the seismic disturbance while on a client call and feels a sense of doom.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (907, 726, 167, 'neutral', false, 'Is on the phone with the narrator, unaware of the unfolding events.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (908, 770, 167, 'enemy', true, 'Vibrates through the floor, heralding the COO''s approach and triggering the narrator''s anxiety.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (909, 771, 167, 'neutral', false, 'Manifests in the narrator as a certainty that the day is about to be shattered.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (910, 767, 168, 'mini-boss', true, 'Brutally and profanely fires the narrator with a guttural roar.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (911, 743, 168, 'ally', false, 'Is frozen in disbelief and rising fury, receiving the verbal assault.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (912, 768, 168, 'enemy', false, 'Watches the event unfold, offering only nervous tittering instead of intervention.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (913, 743, 169, 'ally', false, 'Processes the attack as a deep betrayal and the destruction of his career.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (915, 774, 169, 'neutral', false, 'Is perceived by the narrator as being destroyed in this moment.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (916, 767, 170, 'mini-boss', true, 'Dismisses the narrator''s belongings as worthless and orders him to leave immediately.', '2026-02-27 14:06:21.630833-05');
