INSERT INTO public.entity_beat_appearances VALUES (919, 776, 170, 'neutral', false, 'Screams in agony under the COO''s weight, personifying the situation''s horror.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (920, 777, 171, 'enemy', true, 'Arrive and forcibly seize the narrator by the arms to escort him out.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (921, 743, 171, 'ally', false, 'Is frog-marched through the office, feeling the burning indignity and dehumanization.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (922, 778, 171, 'neutral', false, 'Watch in silent, motionless fear as the narrator is dragged past them.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (923, 743, 172, 'ally', false, 'Sits paralyzed in his car, unable to process what has happened.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (877, 734, 172, 'neutral', false, 'Serves as a silent, isolated chamber for the narrator''s shock.', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.entity_beat_appearances VALUES (925, 780, 172, 'neutral', true, 'Descends upon the narrator, preventing him from thinking or acting.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (926, 781, 172, 'neutral', false, 'Sits untouched, symbolizing the narrator''s disconnection from his life.', '2026-02-27 14:06:21.630833-05');
INSERT INTO public.entity_beat_appearances VALUES (927, 743, 173, 'ally', false, 'Loses all hope as they discover the full extent of the COO''s purge.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (928, 784, 173, 'mini-boss', true, 'Systematically enacts a ''scorched-earth'' plan, firing the narrator''s colleagues and friends.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (929, 787, 173, 'neutral', false, 'Is held onto by the narrator before being ''snuffed out entirely''.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (930, 785, 173, 'neutral', false, 'Are revealed to be casualties of the COO''s campaign.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (931, 743, 174, 'ally', false, 'Reads about the company''s final demise in the newspaper.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (932, 786, 174, 'neutral', true, 'Officially declares bankruptcy, its buildings becoming ''silent shells stripped of meaning''.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (933, 790, 174, 'neutral', false, 'Serves as the messenger of the company''s collapse.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (934, 743, 175, 'ally', true, 'Sits in their car, overwhelmed by the loss, feeling numb, hollow, and defeated.', '2026-02-27 14:07:30.385865-05');
INSERT INTO public.entity_beat_appearances VALUES (1371, 755, 286, 'ally', true, 'Experiences the Engine''s terrifying transformation and the warping of reality around him.', '2026-02-27 14:39:32.031313-05');
INSERT INTO public.entity_beat_appearances VALUES (937, 292, 176, 'ally', true, 'Exhausted and despairing, surrenders to sleep and enters the surreal dreamscape.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (938, 794, 176, 'enemy', false, 'Haunts the protagonist''s thoughts as they drift off, representing the failure of their waking life.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (939, 795, 176, 'neutral', false, 'Acts as the force that transports the protagonist from consciousness to the dreamscape.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (940, 796, 176, 'neutral', false, 'Form the living, shifting visual fabric of the dreamscape the protagonist enters.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (941, 292, 177, 'ally', true, 'Is drawn toward and cautiously approaches a group of mysterious figures.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (942, 797, 177, 'neutral', false, 'Appear as a cluster of eerie, wavering beings, their ancient eyes glowing with unspoken truths.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (943, 798, 178, 'ally', true, 'Steps forward, introduces themself and their group (The Weavers), and explains the nature of The Threshold and the protagonist''s rare ability to walk between realms.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (944, 292, 178, 'ally', false, 'Listens with a mixture of wonder and disbelief, beginning to grasp the significance of their dreams.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (945, 799, 178, 'ally', false, 'Are named as the guardians of The Threshold, providing context for The Weaver''s role.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (946, 292, 179, 'ally', true, 'Challenges The Weaver with frustration and disbelief, demanding to know why they waited so long to reveal themselves after a lifetime of torment.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (947, 798, 179, 'ally', false, 'Calmly explains that the protagonist was not ready until this moment, and that the past suffering was a necessary part of their journey to prepare them.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (948, 292, 180, 'ally', true, 'Accepts their role with defiant resolve, committing to exploring The Threshold despite their fear.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (949, 798, 180, 'ally', false, 'Expresses approval but delivers a final, solemn warning about the dangers lurking in the dreamscape''s depths before fading away.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (950, 800, 180, 'enemy', false, 'Are introduced as a significant threat within The Threshold, a place of despair.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (951, 801, 180, 'enemy', false, 'Are described as the fate of those consumed by The Deeper Shadows, reinforcing the Weaver''s warning.', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_beat_appearances VALUES (952, 292, 181, 'ally', true, 'Moves deeper into the Threshold, listening to the ambient voices and approaching a cluster of Dreamers.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (953, 804, 181, 'neutral', false, 'Acts as the setting, its atmosphere filled with the Whispering Voices.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (954, 805, 181, 'neutral', false, 'Form a vast tapestry of sound, creating a sense of mystery and profound meaning.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (955, 806, 181, 'neutral', true, 'Engage in an animated discussion about the power of dreams and imagination, their voices resonating with musical quality.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (956, 807, 181, 'neutral', false, 'Is discussed by the Dreamers as the source of magic and boundless possibility.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (957, 292, 182, 'ally', true, 'Experiences a profound realization about the Threshold''s nature, feeling both humbled and terrified, while also sensing a personal connection.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (958, 804, 182, 'neutral', true, 'Is revealed to be a living entity where actions can influence the past and future, shaping the waking world.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (959, 808, 182, 'neutral', false, 'Is understood to be a malleable concept that can be altered by even the faintest whisper within the Threshold.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (960, 809, 182, 'unknown', false, 'Manifests as a strong feeling within the protagonist, binding them to the Threshold and suggesting their presence is inevitable.', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_beat_appearances VALUES (961, 278, 183, 'ally', false, 'Plunges deeper into the Threshold out of curiosity, only to be assaulted by nightmarish visions that attack their sanity.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (962, 804, 183, 'neutral', false, 'Shifts from a place of wonder to a cruel, jagged landscape that actively rejects the protagonist and gives birth to their fears.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (963, 812, 183, 'enemy', false, 'Coalesce from the darkness to physically and mentally torment the protagonist.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (964, 814, 183, 'enemy', false, 'Fill the air with malicious, sanity-eroding hisses and gasps.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (965, 817, 183, 'mini-boss', true, 'Acts as the focal point of the assault, tearing at the protagonist''s mind by twisting familiar faces and memories.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (966, 798, 184, 'ally', true, 'Appears suddenly to banish the nightmares, rescue the protagonist, and explain the nature of the Threshold and the source of the danger.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (967, 815, 184, 'ally', false, 'Sears through the darkness, dissolving the Nightmarish Forms and ending the immediate threat.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (968, 278, 184, 'ally', false, 'Is rescued from the brink of madness and receives crucial wisdom about the dangers of the Threshold and their own inner shadows.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (969, 812, 184, 'enemy', false, 'Shriek and dissolve into nothingness upon the Weaver''s arrival.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (970, 816, 184, 'neutral', false, 'Are identified by the Weaver as the true source of the monsters the protagonist faced.', '2026-02-27 14:10:26.29339-05');
INSERT INTO public.entity_beat_appearances VALUES (971, 278, 185, 'ally', false, 'Observes and processes the surreal beauty and impossible physics of the Threshold.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (972, 820, 185, 'neutral', false, 'Contributes to the surreal visual landscape of the Threshold.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (973, 821, 185, 'neutral', false, 'Acts as another example of the Threshold''s physics-defying nature.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (974, 822, 185, 'neutral', false, 'Represents a distorted fragment of possibility in the distance.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (975, 823, 185, 'neutral', true, 'Identified as the force shaping the surreal visions of the Threshold.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (976, 278, 186, 'ally', false, 'Feels humbled and awed by the appearance and presence of Elysium.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (977, 824, 186, 'neutral', true, 'Emerges at sunset, radiating molten light and a powerful, sacred resonance.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (978, 825, 186, 'neutral', false, 'Emanates from Elysium, filling the air and vibrating through the Protagonist.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (979, 278, 187, 'ally', false, 'Is surrounded by the Hooded Figures and follows their unified gesture to look back at Elysium.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (980, 826, 187, 'enemy', true, 'Materialize in vast numbers, silently surrounding the protagonist and creating an oppressive atmosphere.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (981, 827, 187, 'mini-boss', false, 'Directs the Hooded Figures to raise their hands and point in unison past the protagonist.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (982, 824, 187, 'neutral', false, 'Becomes the focus of the Hooded Figures'' attention, revealed as the true subject of their silent revelation.', '2026-02-27 14:11:11.469603-05');
INSERT INTO public.entity_beat_appearances VALUES (983, 830, 188, 'mini-boss', true, 'Erupts through the house, shattering the dream of Elysium and violently waking the protagonist.', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_beat_appearances VALUES (984, 278, 188, 'ally', false, 'Is jolted from his dream, becomes tangled in his sheets, and screams in frustration over the noise.', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_beat_appearances VALUES (985, 824, 188, 'neutral', false, 'The ethereal dream that is instantly dissolved by the chaotic noise.', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_beat_appearances VALUES (986, 831, 188, 'neutral', false, 'Identified as the source of the music, shouting a muffled apology from his room.', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_beat_appearances VALUES (987, 834, 188, 'neutral', false, 'The technology used by the son to create the house-wide cacophony.', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_beat_appearances VALUES (988, 278, 189, 'ally', true, 'Stumbles to the shower to wash away the confusion, but remains mentally preoccupied with the dream.', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_beat_appearances VALUES (989, 833, 189, 'neutral', true, 'Remains stubbornly in the protagonist''s mind, its golden towers vivid and unshaken despite the rude awakening.', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_beat_appearances VALUES (990, 835, 189, 'neutral', false, 'Its hot water is used as a tool by the protagonist to try and cleanse himself of the jarring transition.', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_beat_appearances VALUES (991, 278, 190, 'ally', true, 'Sits alone, drinking coffee and trying to recall the details of his dream about Elysium.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (992, 108, 190, 'neutral', false, 'Acts as an anchor for the protagonist, who stares into it while lost in thought.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (993, 824, 190, 'unknown', false, 'Haunts the protagonist''s thoughts with its golden spires and tantalizingly out-of-reach meaning.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (994, 838, 191, 'ally', true, 'Returns home, perceives her husband''s preoccupation, and gently questions him about it.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (995, 278, 191, 'ally', false, 'Deflects questions about his firing but admits to having an intense and unusual dream.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (996, 844, 191, 'enemy', false, 'Serves as the assumed cause of the protagonist''s distress, which he deflects from discussing.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (997, 278, 192, 'ally', true, 'Describes the details of his dream—Elysium, the spires, and the hooded figures—to his wife.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (998, 838, 192, 'ally', false, 'Listens with growing curiosity and a hint of skepticism.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (999, 839, 192, 'unknown', false, 'Is described in detail, establishing its vividness and significance.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (1000, 824, 192, 'unknown', false, 'Described as a living, breathing city of golden spires.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (1001, 826, 192, 'unknown', false, 'Described as non-threatening beings who pointed toward the towers.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (1002, 838, 193, 'ally', true, 'Suggests the dream is stress-related but pragmatically encourages the protagonist to write it down and analyze it.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (1003, 278, 193, 'ally', false, 'Accepts his wife''s advice and resolves to document the dream, acknowledging its persistent and significant feeling.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (1004, 839, 193, 'unknown', false, 'Is established as a puzzle to be solved, something that cannot be ignored.', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_beat_appearances VALUES (1005, 292, 194, 'ally', true, 'Experiences jarring disorientation after his old life vanishes, feeling adrift and paralyzed by his newfound freedom.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1006, 848, 194, 'enemy', false, 'Its sudden disappearance is the cause of the protagonist''s disorientation.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1007, 849, 194, 'neutral', true, 'Manifests as an ''unsettling stillness'' that leaves the protagonist unsure of where to go.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1008, 850, 194, 'neutral', false, 'Acts as a paralyzing force on the protagonist.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1009, 292, 195, 'ally', true, 'Recognizes his past neglect of his family and feels a mix of regret and resolve to change.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1010, 851, 195, 'ally', false, 'His presence and the simple moments shared with him become the catalyst for his father''s new purpose.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1011, 852, 195, 'ally', false, 'Represents a relationship the protagonist is resolved to be more present in.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1012, 853, 195, 'ally', true, 'Begins to emerge as the protagonist finds profound meaning in simple family interactions.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1013, 292, 196, 'ally', true, 'Embraces his role as a father and husband, finding a deep and real fulfillment in being present for his family.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1014, 854, 196, 'ally', true, 'Become the central stage for the protagonist''s transformation, revealing a fulfillment he never knew he was missing.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1015, 853, 196, 'ally', false, 'Solidifies as the central, guiding principle of the protagonist''s new life, surpassing any past corporate achievement.', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_beat_appearances VALUES (1016, 292, 197, 'ally', true, 'Becomes fixated on the Pointers and begins searching for them online, only to find all traces have vanished.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1017, 39, 197, 'unknown', true, 'Their complete disappearance from all records becomes the central, driving mystery for the protagonist.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1018, 857, 197, 'neutral', false, 'Acts as the catalyst for the protagonist''s obsessive need to understand the Pointers.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1019, 292, 198, 'ally', true, 'Struggles with his rational mind, questioning his own sanity as he delves into absurd online theories.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1020, 859, 198, 'enemy', true, 'Represent the irrational ''rabbit holes'' he falls into out of desperation for answers.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1021, 858, 198, 'neutral', false, 'Serves as the source for the absurd hypotheses he explores.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1022, 292, 199, 'ally', true, 'Pivots his research and discovers a chilling temporal correlation between two major phenomena.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1023, 860, 199, 'neutral', true, 'Becomes the new focus of research, offering a potential framework for understanding the Pointers.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1024, 861, 199, 'unknown', false, 'Its period of peak activity is identified as coinciding with the rise of Mandela Effect reports.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1025, 862, 199, 'unknown', false, 'The organization whose work is now implicated in the protagonist''s developing theory.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1026, 292, 200, 'ally', true, 'Finds and reads a compelling confession that seems to confirm his wildest fears.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1027, 864, 200, 'neutral', true, 'Provides a terrifying narrative linking CERN, the Mandela Effect, and a fundamental breakdown of reality.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1028, 863, 200, 'unknown', false, 'The author of the post, whose sincerity makes the threat feel real and immediate.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1029, 865, 200, 'enemy', true, 'Emerges as the ultimate threat described in the post, a potential consequence of CERN''s experiments.', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_beat_appearances VALUES (1030, 860, 201, 'enemy', true, 'Defined not as misremembering but as a terrifying violation of reality.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1031, 876, 201, 'neutral', false, 'Their genuine fear is used as evidence of the phenomenon''s severity.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1032, 867, 202, 'ally', true, 'Theorizes that their work at CERN with the LHC is the cause of the Mandela Effect, having torn holes in reality.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1033, 862, 202, 'neutral', false, 'Identified as the organization whose hubris led to the disaster.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1034, 871, 202, 'neutral', false, 'The specific instrument used to tear holes in the fabric of existence.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1035, 872, 202, 'enemy', false, 'Theorized to be bleeding into our reality through the tears.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1036, 867, 203, 'ally', true, 'Works with William and discovers the true nature of the memory corruption, realizing something darker is awakening.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1037, 868, 203, 'neutral', false, 'His mind is revealed to be contaminated with threads from other worlds.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1038, 875, 203, 'enemy', false, 'Infect William''s memories, creating something grotesque and alien.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1039, 873, 203, 'mini-boss', false, 'Sensed as a watching, hungry presence from behind the veil of existence.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1040, 873, 204, 'mini-boss', true, 'Its presence intensifies, pressing against reality, communicating with the researcher, and causing the final collapse of the lab environment.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1041, 867, 204, 'ally', false, 'Loses control of the experiments and their own memories as the presence grows stronger.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1042, 874, 204, 'neutral', false, 'Vanish from existence, a sign of the escalating chaos.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1043, 877, 204, 'enemy', false, 'Becomes the sole remaining, active collider, roaring with a life of its own.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1044, 878, 204, 'enemy', false, 'The researcher''s mind begins to bleed together with other lives, showing their complete loss of control.', '2026-02-27 14:15:25.564744-05');
INSERT INTO public.entity_beat_appearances VALUES (1045, 292, 205, 'neutral', false, 'Attempts to dismiss the CERN account as fiction but is unable to shake the unease it causes.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1046, 881, 205, 'neutral', true, 'Is the subject of the protagonist''s rationalization, being dismissed as ''bullshit'' and a ''bad rip-off''.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1047, 882, 205, 'enemy', false, 'Manifests within the protagonist, resisting his attempts to dismiss the strange account.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1048, 889, 205, 'neutral', false, 'Used as a comparison to frame the CERN account as derivative horror fiction.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1049, 292, 206, 'neutral', false, 'Reflects on the degradation of Mandela Effect reports, feels a sense of wrongness, and acknowledges his obsession is fading.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1050, 883, 206, 'neutral', false, 'Recalled as a benchmark of eerie consistency and vividness.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1051, 884, 206, 'neutral', false, 'Recalled as examples of current absurd nonsense, which creates a troubling contrast with earlier reports.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1052, 885, 206, 'enemy', true, 'Emerges from the protagonist''s analysis of the conflicting reports, signaling a deeper problem.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1053, 39, 206, 'unknown', false, 'Mentioned as the original focus of the protagonist''s now-waning obsession.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1054, 862, 206, 'unknown', false, 'Mentioned as its peak activity coincided with the period of consistent, vivid reports.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1055, 886, 206, 'neutral', false, 'Observed by the protagonist as now-meaningless remnants of his faded obsession.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1056, 887, 206, 'neutral', false, 'Represents the culmination of the protagonist''s disillusionment with his research.', '2026-02-27 14:16:25.005146-05');
INSERT INTO public.entity_beat_appearances VALUES (1057, 221, 207, 'ally', true, 'Sits alone in his office, feeling the weight of his obsessive research and exhaustion.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1058, 894, 207, 'neutral', false, 'Tower around the Narrator, symbolizing his obsession and creating a cluttered, suffocating environment.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1059, 900, 207, 'neutral', false, 'Permeates the atmosphere of the office, described as a suffocating blend.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1060, 454, 207, 'neutral', false, 'Mentioned as a source of future conflict over the mess, highlighting the personal cost of the Narrator''s obsession.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1061, 221, 208, 'ally', false, 'Experiences the supernatural phenomena, his fear shifting to a reckless curiosity.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1062, 896, 208, 'enemy', true, 'Begin to twist and move unnaturally, heralding the intrusion of the supernatural.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1063, 897, 208, 'enemy', false, 'Fill the air, taunting the Narrator and adding to the unsettling atmosphere.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1064, 898, 208, 'mini-boss', true, 'Makes its presence known by pressing against reality and drawing closer like a predator.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1065, 901, 208, 'neutral', false, 'Manifests as the room trembles and the hum of reality falters, indicating the presence''s power.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1066, 39, 209, 'unknown', true, 'Manifest before the Narrator, point past him at something he already knows, and then vanish.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1067, 221, 209, 'ally', false, 'Witnesses the Pointers, feels his pulse thunder, and understands their gesture is significant before they disappear.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1068, 898, 209, 'mini-boss', false, 'Is the likely subject of the Pointers'' gesture, the ''something unseen'' they point towards.', '2026-02-27 14:17:16.799995-05');
INSERT INTO public.entity_beat_appearances VALUES (1069, 906, 210, 'enemy', true, 'Rips through the garage, destroying the Eternal Engine and creating the wreckage.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1070, 295, 210, 'neutral', false, 'Is utterly destroyed and vanishes.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1071, 908, 210, 'enemy', false, 'Descends after the explosion, described as heavy and suffocating.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1072, 904, 211, 'ally', true, 'Stumbles through the wreckage, disoriented, and searches for the flashlight.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1073, 204, 211, 'enemy', false, 'Presses in like a predator, causing disorientation.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1074, 910, 211, 'neutral', false, 'Acts as a physical obstacle, tripping the narrator.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1075, 201, 211, 'ally', false, 'The object of the narrator''s desperate search.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1076, 904, 212, 'ally', true, 'Confirms the engine is gone and discovers the pulsing residue on the floor.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1077, 912, 212, 'mini-boss', true, 'Is discovered on the floor, pulsing as if alive and causing a fearful reaction.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1078, 234, 212, 'enemy', false, 'The emptiness left by the engine feels like it is staring back at the narrator.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1079, 908, 213, 'enemy', true, 'Is perceived as being alive and actively waiting, becoming the primary source of dread.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1080, 904, 213, 'ally', false, 'Realizes the silence is not empty but waiting, confirming the fear that something has escaped.', '2026-02-27 14:18:41.368644-05');
INSERT INTO public.entity_beat_appearances VALUES (1081, 221, 214, 'ally', false, 'Observes the mysterious object, feeling compelled by its impossible properties to investigate it.', '2026-02-27 14:19:37.382513-05');
INSERT INTO public.entity_beat_appearances VALUES (1082, 917, 214, 'unknown', true, 'Sits on the narrator''s bedside table, its uncanny weight, symmetry, and faint thrumming acting as a silent enigma.', '2026-02-27 14:19:37.382513-05');
INSERT INTO public.entity_beat_appearances VALUES (1083, 221, 215, 'ally', false, 'Becomes frustrated while attempting to document and measure the object in his makeshift lab.', '2026-02-27 14:19:37.382513-05');
INSERT INTO public.entity_beat_appearances VALUES (1084, 917, 215, 'enemy', true, 'Actively resists documentation by distorting photographs and defies logic by having inconsistent physical measurements.', '2026-02-27 14:19:37.382513-05');
INSERT INTO public.entity_beat_appearances VALUES (1085, 919, 215, 'neutral', false, 'Serve as physical proof of The Engine''s resistance to being documented, appearing as pixelated and blurred images.', '2026-02-27 14:19:37.382513-05');
INSERT INTO public.entity_beat_appearances VALUES (1086, 221, 216, 'ally', false, 'Conducts crude power tests on The Engine, witnessing its destructive potential firsthand.', '2026-02-27 14:19:37.382513-05');
INSERT INTO public.entity_beat_appearances VALUES (1087, 917, 216, 'mini-boss', true, 'Demonstrates its immense power by burning out a TV remote, a bulb, and shattering a small fan, revealing its unpredictable and dangerous nature.', '2026-02-27 14:19:37.382513-05');
