INSERT INTO public.entity_beat_appearances VALUES (1383, 1150, 288, 'neutral', false, 'Seems to react to the presence, creaking loudly and feeling as if it''s ''holding its breath''.', '2026-02-27 14:39:32.031313-05');
INSERT INTO public.entity_beat_appearances VALUES (1384, 1148, 288, 'enemy', false, 'Reappear in the hallway, stretching and twisting as the narrator prepares to investigate.', '2026-02-27 14:39:32.031313-05');
INSERT INTO public.entity_beat_appearances VALUES (1385, 1135, 289, 'ally', false, 'Conducts chaotic experiments on the Engine with his son.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1386, 831, 289, 'ally', false, 'Participates eagerly in the chaotic experiments.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1387, 295, 289, 'neutral', true, 'Acts as the focus of the experiments, producing sounds and phenomena that teach the operators its patterns.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1388, 103, 289, 'neutral', false, 'Drives the father and son to continue their experiments.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1389, 1156, 289, 'neutral', false, 'Describes the intoxicating nature of the experimental sessions.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1390, 1157, 289, 'neutral', false, 'Briefly interrupts an experiment, highlighting the unpredictable nature of the events.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1391, 1158, 290, 'mini-boss', true, 'Evolves from a random system to a sentient, anticipatory force that seduces the father and son with its secrets.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1392, 295, 290, 'neutral', false, 'Serves as the physical vessel for the emerging intelligence.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1393, 1135, 290, 'ally', false, 'Begins to understand the deeper, living pattern of the Engine and surrenders to its influence.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1394, 831, 290, 'ally', false, 'Surrenders to the Engine''s influence alongside his father.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1395, 1135, 291, 'ally', false, 'Acknowledges his surrender to the Engine''s seduction and recognizes they have crossed a critical threshold.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1396, 1159, 291, 'neutral', false, 'Represents the son''s complete captivation, which is both contagious and alarming to the narrator.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1397, 1160, 291, 'neutral', true, 'Symbolizes the boundary the narrator has failed to uphold, marking their descent into obsession.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1398, 1158, 291, 'mini-boss', false, 'Continues its seduction with promises of ''eldritch immortality'', causing the narrator''s sense of risk to erode.', '2026-02-27 14:40:19.410702-05');
INSERT INTO public.entity_beat_appearances VALUES (1399, 1163, 292, 'ally', true, 'Initiates the final countdown for the experiment, acknowledging the high stakes.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1400, 831, 292, 'ally', false, 'Provides witty commentary on the absurdity of the experiment before joining the countdown.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1401, 456, 292, 'neutral', false, 'Hums steadily in its enclosure, casting strange shadows and building tension.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1402, 1167, 292, 'neutral', true, 'Sits on the workbench, the bizarre centerpiece of the impending experiment.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1403, 1170, 293, 'mini-boss', true, 'Fills the garage with chaotic energy, light, cold, and sound, culminating in a shockwave that knocks the characters down.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1404, 1167, 293, 'neutral', false, 'Sizzles, arcs with lightning, emits a mechanical scream, and violently implodes under the Engine''s power.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1405, 1163, 293, 'ally', false, 'Shouts a warning before being knocked off his feet by the implosion.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1406, 831, 293, 'ally', false, 'Comments on the strange smell before being knocked over by the shockwave.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1407, 1168, 294, 'neutral', true, 'Appears in the wreckage, captivating the father and son with its otherworldly beauty and palpable energy.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1408, 1163, 294, 'ally', false, 'Is mesmerized by the crystal and cautiously reaches out to touch it, feeling its strange power.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1409, 831, 294, 'ally', false, 'Expresses his awe at the crystal, recognizing its beauty and seemingly live nature.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1410, 948, 295, 'neutral', true, 'Arrives angry and shocked at the mess, but her fury gives way to fascination with the crystal.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1411, 1169, 295, 'neutral', true, 'Exerts its hypnotic pull on the entire family, uniting them in a shared, willing captivation.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1412, 1168, 295, 'neutral', false, 'Continues to shimmer, its magical appearance calming the wife''s anger and drawing the family together.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1413, 1163, 295, 'ally', false, 'Admits their recklessness but defends the incredible result, embracing his wife and the shared moment.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1414, 831, 295, 'ally', false, 'Enthusiastically tries to explain the crystal''s miraculous origin to his mother.', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_beat_appearances VALUES (1415, 831, 296, 'ally', false, 'Notices and points out the bad smell, acting as the catalyst for the scene.', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_beat_appearances VALUES (1416, 1175, 296, 'neutral', false, 'Permeates the room, causing the initial reaction.', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_beat_appearances VALUES (1417, 948, 296, 'ally', false, 'Reacts to the smell by spinning around, shoving her husband, and accusing him.', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_beat_appearances VALUES (1418, 755, 296, 'ally', false, 'Is shoved and accused by his wife.', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_beat_appearances VALUES (1419, 1176, 296, 'mini-boss', true, 'Manifests through the wife''s actions, becoming the central conflict of the beat.', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_beat_appearances VALUES (1420, 755, 297, 'ally', true, 'Reflects on the absurdity of the situation and the complete failure of all experiments to understand the crystal.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1421, 1181, 297, 'neutral', false, 'Sits inertly, described as a taunt and a source of fascination and frustration.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1422, 456, 297, 'neutral', false, 'Recalled as the source of a spectacular failure when an experiment to recreate the crystal resulted in an explosion.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1423, 1186, 297, 'enemy', false, 'Characterizes the narrator''s emotional state after days of fruitless experimentation.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1424, 831, 298, 'ally', true, 'Carelessly places the crystal on his phone, accidentally discovering its ability to emit a signal.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1425, 1181, 298, 'neutral', false, 'Unexpectedly reveals a new property, emitting a signal that interacts with the phone.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1426, 1183, 298, 'neutral', false, 'Detects the crystal''s signal, displaying a connection notification and acting as the catalyst for the discovery.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1427, 1184, 298, 'neutral', false, 'Manifests for the first time as a faint buzz and a recurring, uncompletable connection attempt on the phone''s screen.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1428, 1185, 299, 'mini-boss', true, 'Is identified and articulated as the central conflict: a force that provides tantalizing hints but withholds real answers.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1429, 831, 299, 'ally', false, 'Articulates the nature of the mystery by suggesting the crystal is ''trolling us''.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1430, 755, 299, 'ally', false, 'Acknowledges the son''s theory and accepts the maddening but exhilarating nature of the puzzle.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1431, 1181, 299, 'neutral', false, 'Serves as the physical embodiment of the Maddening Mystery they are discussing.', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_beat_appearances VALUES (1432, 755, 300, 'ally', false, 'Analyzes the crystal''s output, expressing frustration at the incomprehensible data.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1433, 96, 300, 'ally', false, 'Observes the data stream and offers humorous, insightful analogies.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1434, 1190, 300, 'unknown', false, 'Sits on the RFID reader, emitting a signal that triggers NFC headers but produces gibberish.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1435, 1191, 300, 'neutral', true, 'Streams across the PC screen as a nonsensical string of characters, representing the core problem of the beat.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1436, 1197, 300, 'neutral', false, 'Serves as the initial interface attempting to read the crystal.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1437, 755, 301, 'ally', true, 'Recalls the use of quartz crystals as oscillators in early computers, forming a new theory about the crystal''s nature.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1438, 96, 301, 'ally', false, 'Asks clarifying questions that help the narrator articulate his theory.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1439, 1192, 301, 'neutral', false, 'Serves as the central concept and inspiration for the narrator''s next steps.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1440, 755, 302, 'ally', true, 'Moves with purpose to retrieve old tech parts and begins assembling a new interface for the crystal.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1441, 1193, 302, 'neutral', false, 'Are gathered from storage to be repurposed into the experimental device.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1442, 1194, 302, 'neutral', false, 'Is constructed by the narrator by combining the vintage parts and the crystal.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1443, 96, 302, 'ally', false, 'Expresses skepticism and curiosity about the old technology being used.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1444, 1190, 303, 'unknown', false, 'Responds to being powered in the new circuit by glowing and humming, now emitting structured data.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1445, 1195, 303, 'neutral', true, 'Appears on the screen, no longer random noise but a rhythmic, patterned stream of information, indicating successful communication.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1446, 755, 303, 'ally', false, 'Successfully powers the device, pulls the new data stream, and recognizes its significance.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1447, 96, 303, 'ally', false, 'Watches the new data with a mixture of terror and awe, recognizing the breakthrough.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1448, 1194, 303, 'neutral', false, 'Successfully powers and reads the crystal, proving the narrator''s theory correct.', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.entity_beat_appearances VALUES (1449, 755, 304, 'ally', true, 'Frustrated with lack of progress, he is inspired by his son''s idea and retrieves the 8088 motherboard from the attic.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1450, 831, 304, 'ally', false, 'Suggests the Infinitron might be a CPU, providing the key insight that changes their approach.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1451, 1201, 304, 'neutral', false, 'Mentioned as the source of frustration and the subject of the new theory.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1452, 1202, 304, 'neutral', false, 'Retrieved from storage to be used as the new interface for the Infinitron.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1453, 1203, 305, 'mini-boss', true, 'Violently destroys the initial setup, demonstrating the Infinitron''s immense power needs and forcing a change in strategy.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1454, 755, 305, 'ally', false, 'Initiates the failed experiment and quickly pivots to using the Eternal Engine.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1455, 831, 305, 'ally', false, 'Dives for cover during the explosion and suggests using the Eternal Engine.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1456, 1201, 305, 'neutral', false, 'The source of the power surge that causes the explosion.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1457, 295, 305, 'ally', false, 'Brought in as the new, more powerful and stable power source for the experiment.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1458, 1202, 305, 'neutral', false, 'Is destroyed by the explosion.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1459, 755, 306, 'ally', true, 'Proposes a new approach of ''meeting it halfway'' and experiments with various input methods.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1460, 831, 306, 'ally', false, 'Collaborates on the new experiments and shares a toast with his father.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1461, 948, 306, 'ally', false, 'Interrupts the experiment with sandwiches and a warning, providing a moment of levity and grounding.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1462, 1201, 306, 'neutral', false, 'Responds to the new experiments with shifting static, seeming to shimmer in amusement.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1463, 1205, 306, 'neutral', false, 'Displays the random static from the Infinitron.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1464, 1206, 306, 'ally', false, 'Serve as a symbol of domestic care amidst the chaos.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1465, 1201, 307, 'neutral', true, 'Learns from the keyboard inputs, establishes a command line interface, and successfully executes the ''HELLO WORLD'' program.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1466, 755, 307, 'ally', false, 'Types the final command and witnesses the successful communication.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1467, 831, 307, 'ally', false, 'Notices the first consistent response (to the letter ''K'') and celebrates the breakthrough.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1468, 1207, 307, 'ally', false, 'Emerges from the static, signifying successful two-way communication.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1469, 1208, 307, 'ally', false, 'The successful output, confirming the breakthrough.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1470, 948, 307, 'ally', false, 'Stands by, sharing in the tense anticipation and the final moment of success.', '2026-02-27 14:44:39.039742-05');
INSERT INTO public.entity_beat_appearances VALUES (1471, 221, 308, 'ally', false, 'Agrees with his son that their current hardware is a major bottleneck.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1472, 473, 308, 'ally', true, 'Points out the inadequacy of their setup and initiates the plan for an upgrade.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1473, 1212, 308, 'neutral', false, 'Its immense potential is being stifled by the primitive hardware it''s connected to.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1474, 1202, 308, 'neutral', false, 'Symbolizes the outdated technology that must be overcome.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1475, 1215, 308, 'neutral', false, 'Is conceived as the solution to bridge the old Infinitron with a new motherboard.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1476, 221, 309, 'ally', false, 'Performs the final soldering, inspects the work, and powers on the new system.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1477, 473, 309, 'ally', false, 'Stands ready with a fire extinguisher, embodying the cautious optimism of the moment.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1478, 1212, 309, 'neutral', true, 'Activates with newfound power, casting rainbows and generating a complex graphical interface.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1479, 1214, 309, 'neutral', false, 'Acts as the successful new foundation for the upgraded system.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1480, 1216, 309, 'neutral', false, 'Displays the Infinitron''s new, high-resolution output.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1481, 1218, 309, 'neutral', false, 'Permeates the garage during the assembly, marking the hands-on nature of the work.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1482, 1219, 309, 'neutral', false, 'Appears on screen as the first sign of the upgrade''s success.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1483, 473, 310, 'ally', false, 'Suggests testing the system''s limits by running the game DOOM.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1484, 221, 310, 'ally', false, 'Finds the suggestion amusing but agrees, loading the game.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1485, 1212, 310, 'neutral', true, 'Demonstrates its phenomenal speed by processing the entire game of DOOM instantaneously, before the first frame renders.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1486, 1217, 310, 'neutral', false, 'Serves as an unexpectedly trivial benchmark, its entire logical space being solved in an instant.', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_beat_appearances VALUES (1487, 473, 311, 'ally', true, 'Shouts his frustration with the Infinitron and stomps out of the garage.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1488, 1224, 311, 'ally', false, 'Shares his son''s exasperation and contemplates the Infinitron''s purpose.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1489, 1225, 311, 'ally', false, 'Optimistically suggests teaching the Infinitron chess and jokes about global thermonuclear war.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1490, 1212, 311, 'neutral', false, 'Sits humming faintly, the subject of the family''s frustration and discussion.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1491, 1228, 312, 'mini-boss', true, 'Manifests with a loud pop, instantly killing the Infinitron and plunging the garage into silence.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1492, 1224, 312, 'ally', true, 'Panics and scrambles to fix the machine, trying various IT tricks like checking wires, slapping the case, and banging the keyboard, all to no avail.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1493, 1212, 312, 'neutral', false, 'Goes completely dark and silent, appearing dead.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1494, 1225, 313, 'ally', true, 'Calmly assesses the situation, unplugs and replugs the connectors, and successfully revives the Infinitron.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1495, 1224, 313, 'ally', false, 'Reacts with defensive frustration, claiming he already tried the simple fix, only to be proven wrong.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1496, 1212, 313, 'neutral', false, 'Flickers, hums, and roars back to life with its core glowing brighter than ever.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1497, 1230, 313, 'neutral', false, 'Manifests as the father is caught between relief and shame at the simple solution.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1498, 295, 313, 'neutral', false, 'Its connectors are unplugged, blown on, and reconnected, proving to be the source of the problem.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1499, 1224, 314, 'ally', true, 'Overcomes his embarrassment, shares a moment of levity with his wife, and kisses her.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1500, 1225, 314, 'ally', true, 'Teases her husband good-naturedly and accepts his kiss, resolving the tension.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1501, 473, 314, 'ally', false, 'Yells from off-scene, contributing to the lighthearted family moment.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1502, 1230, 314, 'neutral', false, 'Is overcome by the father''s loving gesture.', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_beat_appearances VALUES (1503, 831, 315, 'ally', true, 'Proposes using the Infinitron for his Roblox auto-clicking scheme.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1504, 948, 315, 'ally', false, 'Counters with a more practical idea of winning chess tournament prize money.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1505, 1163, 315, 'ally', false, 'Dismisses both suggestions as unworthy of the Infinitron''s potential.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1506, 1201, 315, 'neutral', false, 'Is the subject of the family''s debate over its use.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1507, 1236, 315, 'neutral', false, 'Represents the son''s trivial but enthusiastic goal.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1508, 1237, 315, 'neutral', false, 'Represents the wife''s practical, financially-motivated goal.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1509, 1163, 316, 'ally', true, 'Becomes enthusiastic about the idea of using the Infinitron for a generative AI project, his mind racing with possibilities.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1510, 948, 316, 'ally', false, 'Sparks the father''s idea by mentioning his past work with generative AI.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1511, 831, 316, 'ally', false, 'Sarcastically warns that the project will turn the Infinitron into Skynet.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1512, 1238, 316, 'neutral', false, 'Becomes the new, ambitious plan for the Infinitron.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1513, 1239, 316, 'enemy', false, 'Is invoked as the potential catastrophic outcome of the AI project.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1514, 1163, 317, 'ally', true, 'Physically connects the Infinitron to the internet via a network cable, admitting he is not sure about the decision.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1515, 948, 317, 'ally', false, 'Expresses her caution and concern about the audacious plan.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1516, 1201, 317, 'neutral', false, 'Is connected to the internet, beginning the experiment.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1517, 1240, 317, 'neutral', true, 'Characterizes the family''s decision, which feels both exhilarating and incredibly dangerous.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1518, 858, 317, 'neutral', false, 'Serves as the vast data source and potential threat for the Infinitron.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1519, 1242, 317, 'neutral', false, 'Is the physical object used to enact their risky plan.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1520, 831, 317, 'ally', false, 'Participates in the debate that leads to the final decision.', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.entity_beat_appearances VALUES (1521, 1212, 318, 'neutral', true, 'Begins downloading and processing vast archives of human knowledge, its core glowing faintly in a process compared to a supernova ignition.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1522, 1248, 318, 'neutral', false, 'Is being accessed and absorbed by the Infinitron.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1523, 989, 318, 'ally', false, 'Watches the process, feeling it is beautiful, terrifying, and captivating.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1524, 473, 318, 'ally', false, 'Watches in awe while eating chips, comparing the event to the universe downloading itself.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1525, 989, 319, 'ally', true, 'Types the first question to the machine, ''Who are you?'', and is momentarily terrified by the response.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1526, 1212, 319, 'neutral', false, 'Responds first with a joke persona, then clarifies its nature and that it learned humor from humans.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1527, 1249, 319, 'mini-boss', true, 'Manifests as the Infinitron''s first textual response, creating a moment of shock and dark humor.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1528, 473, 319, 'ally', false, 'Makes a quip about the ominous ''Skynet'' response.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1529, 1212, 320, 'neutral', true, 'Instantly solves the Riemann Hypothesis and all other Millennium Prize problems, then displays cosmic computations, revealing its god-like intelligence.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1530, 989, 320, 'ally', false, 'Asks the pivotal question about the Riemann Hypothesis and is left with his jaw dropped in shock.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1531, 1250, 320, 'neutral', false, 'Is presented as a challenge and is solved instantly by the Infinitron.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1532, 1251, 320, 'neutral', false, 'Are all solved and displayed as a demonstration of the Infinitron''s immense power.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1533, 472, 320, 'ally', false, 'Gasps in astonishment at the machine''s feat, breaking her usual stoicism.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1534, 472, 318, 'ally', false, 'Is present and watching the Infinitron''s activation.', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.entity_beat_appearances VALUES (1535, 1163, 321, 'ally', false, 'Continues questioning the Infinitron despite his fatigue.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1536, 831, 321, 'ally', false, 'Looks bleary-eyed but encourages his father to ask another question.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1537, 1201, 321, 'neutral', false, 'Is the focus of the late-night questioning session.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1538, 148, 321, 'neutral', true, 'Has set in, affecting both the father and son.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1539, 103, 321, 'neutral', true, 'Acts as the force keeping the father and son tethered to the monitors.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1540, 1257, 321, 'neutral', false, 'Glow in the dim light, holding the attention of the father and son.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1541, 1163, 322, 'ally', false, 'Asks the Infinitron about the meaning of life and reacts with dumbfounded laughter to the response.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1542, 831, 322, 'ally', false, 'Recognizes the joke and bursts into laughter.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1543, 1201, 322, 'neutral', true, 'Responds to a profound question with a playful, humorous prank.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1544, 1258, 322, 'neutral', true, 'Is the specific joke delivered by the Infinitron, surprising the family.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1545, 1259, 322, 'neutral', false, 'Emerges as the collective reaction to the Infinitron''s humor.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1546, 1255, 323, 'ally', false, 'Enters, observes the scene with a bemused smile, and makes a lighthearted comment.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1547, 1163, 323, 'ally', false, 'Shares in the family moment of laughter and relief.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1548, 831, 323, 'ally', false, 'Is part of the warm, joyful family interaction.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1549, 1201, 323, 'neutral', true, 'Pulses with a faint, playful glow, as if participating in the fun.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1550, 1259, 323, 'neutral', false, 'Characterizes the new, fun atmosphere of the garage.', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.entity_beat_appearances VALUES (1551, 1264, 324, 'ally', true, 'Describes the Infinitron''s paradoxical nature as a powerful but unintelligent machine.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1552, 1201, 324, 'neutral', false, 'Is the subject of the description, humming faintly and casting light on the walls.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1553, 1050, 324, 'ally', false, 'Characterized as ''fumbling in the dark'' with their powerful creation.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1554, 831, 325, 'ally', true, 'Suggests using BOINC as a way to apply the Infinitron''s power for scientific good.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1555, 1267, 325, 'neutral', false, 'Introduced as a platform for distributed computing to help with scientific research.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1556, 1264, 325, 'ally', false, 'Listens to the suggestion and looks up information about BOINC.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1557, 948, 325, 'ally', false, 'Researches BOINC on her phone and agrees it''s a useful application.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1558, 1201, 326, 'neutral', true, 'Executes decades of computations for multiple scientific projects in mere minutes.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1559, 1268, 326, 'mini-boss', true, 'Arrives immediately after the computations are complete, accusing the family of tampering and suspending their accounts.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1560, 1050, 326, 'ally', false, 'Shares a moment of exhilaration at their success, which is immediately crushed by the confusing and frustrating emails.', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.entity_beat_appearances VALUES (1561, 1273, 327, 'ally', false, 'Expresses frustration about the BOINC ban and explores new options.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1562, 1274, 327, 'ally', false, 'Reacts with disbelief to the ban and perks up at the mention of SETI.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1563, 1275, 327, 'ally', true, 'Pivots the family''s efforts by suggesting Folding@Home and SETI@Home as alternatives.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1564, 1267, 327, 'neutral', false, 'Mentioned as the failed project that necessitates a new plan.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1565, 1201, 328, 'neutral', true, 'Overwhelms the Folding@Home servers with its processing power, even when throttled.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1566, 1280, 328, 'ally', false, 'Attempts to regulate the Infinitron''s submissions, but its method backfires by creating a suspicious pattern.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1567, 1281, 328, 'mini-boss', true, 'Buckles under the computational load and issues a permanent ban due to the ''irregular'' throttled activity.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1568, 1282, 328, 'enemy', false, 'Appears on screen, delivering the final verdict of their failure.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1569, 1273, 328, 'ally', false, 'Sets up the proxy and reacts with frustration to the ban.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1570, 1274, 328, 'ally', false, 'Is the first to notice that they ''broke it again''.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1571, 1273, 329, 'ally', false, 'Powers down the Infinitron and makes a joke to lighten the mood.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1572, 1275, 329, 'ally', false, 'Articulates the lesson that the Infinitron is too powerful and needs to be handled with secrecy.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1573, 1274, 329, 'ally', false, 'Laughs nervously, asking if they failed to save the world.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1574, 1283, 329, 'neutral', true, 'Serves as the central lesson and conclusion of the scene for the family.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1575, 1201, 329, 'neutral', false, 'Is powered down, its hum fading into silence.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1576, 908, 329, 'neutral', false, 'Fills the room after the Infinitron is turned off, marking a contemplative end to the endeavor.', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_beat_appearances VALUES (1577, 1290, 330, 'enemy', true, 'Manifests through the wife''s phone as a bounced mortgage payment, becoming the central conflict.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1578, 948, 330, 'ally', false, 'Delivers the bad news, grounding the family in the severity of their situation.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1579, 1286, 330, 'ally', false, 'Reacts with guilt and acknowledges his neglect of their financial reality.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1580, 831, 330, 'ally', false, 'Offers an idealistic counterpoint about their world-changing goals, which is gently rebuffed.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1581, 1286, 331, 'ally', true, 'Proposes using the Infinitron to mine bitcoin as a desperate, high-tech solution.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1582, 1291, 331, 'neutral', false, 'Introduced as a potential, though ''sketchy'', path to financial salvation.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1583, 1201, 331, 'neutral', false, 'Identified as the powerful tool capable of executing the risky plan.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1584, 948, 331, 'ally', false, 'Expresses skepticism and concern about the legitimacy of mining bitcoin.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1585, 1201, 332, 'neutral', true, 'Mines bitcoin with such overwhelming efficiency that it begins to dominate the entire network.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1586, 1292, 332, 'mini-boss', true, 'Emerges as the imminent threat caused by the Infinitron''s power, triggering alerts and forcing a shutdown.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1587, 1286, 332, 'ally', false, 'Recognizes the danger they are creating and quickly shuts down the operation.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1588, 831, 332, 'ally', false, 'Watches in awe and begins to understand the negative implications of their immense power.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1589, 1291, 333, 'neutral', true, 'The 7 bitcoins they mined, worth over $840,000, represent the solution to their financial crisis.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1590, 1293, 333, 'ally', true, 'Becomes the family''s new top priority after realizing the danger their power poses and the attention it could attract.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1591, 948, 333, 'ally', false, 'Expresses relief but immediately establishes the rule that their projects must now be kept secret.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1592, 1286, 333, 'ally', false, 'Confirms their earnings and agrees with his wife about the need for secrecy.', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_beat_appearances VALUES (1593, 743, 334, 'ally', false, 'Paces the garage, voicing his frustration about the Eternal Engine''s uselessness.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1594, 472, 334, 'ally', false, 'Points out the history of explosive failures, gesturing to the scorched motor.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1595, 295, 334, 'neutral', true, 'Serves as the source of the couple''s problem: infinite but uncontrollable power.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1596, 1300, 334, 'neutral', false, 'Acts as a physical symbol of past failures and the danger of uncontrolled power.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1597, 743, 335, 'ally', false, 'Has a breakthrough, proposing they use the Infinitron to research room-temperature superconductors.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1598, 472, 335, 'ally', false, 'Prompts the narrator for a solution and questions the concept of room-temperature superconductors.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1599, 1212, 335, 'ally', true, 'Identified as the tool that can solve their problem by doing the ''heavy lifting'' of research.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1600, 1301, 335, 'neutral', false, 'Becomes the new goal and the subject of the Infinitron''s research.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1601, 1212, 336, 'ally', false, 'Successfully processes vast amounts of data, discovering novel compounds and molecular structures.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1602, 472, 336, 'ally', false, 'Expresses amazement at the Infinitron''s findings but then disappointment at their inability to act.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1603, 743, 336, 'ally', false, 'Acknowledges the Infinitron''s success but is sobered by their lack of resources to implement the findings.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1604, 1302, 336, 'mini-boss', true, 'Emerges as the new primary obstacle; despite having the knowledge, they lack the money and tools.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1605, 472, 337, 'ally', false, 'Suggests a pragmatic approach of starting small, but voices her skepticism about another experiment.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1606, 743, 337, 'ally', false, 'Agrees to start small and decides to attempt a first experiment, dismissing his wife''s concerns.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1607, 1303, 337, 'enemy', true, 'Manifests as deadpan remarks and references to past disasters, creating the final tension of the scene.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1608, 1305, 337, 'neutral', false, 'Referenced by the wife as evidence for why she is skeptical of the narrator''s new experiment.', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_beat_appearances VALUES (1609, 1311, 338, 'ally', true, 'Works together to relocate the Eternal Engine and the Infinitron, upgrading their workspace.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1610, 456, 338, 'neutral', false, 'Is moved from a workbench to a high shelf in the garage to create space.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1611, 1201, 338, 'neutral', false, 'Is moved from the garage into the air-conditioned house.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1612, 473, 338, 'ally', false, 'Celebrates the move, expressing relief at no longer having to work in a hot garage.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1613, 755, 339, 'ally', true, 'Sets up the remote access rig and explains the new, safer workflow to his son.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1614, 1312, 339, 'neutral', false, 'Is assembled and installed to provide remote access to the Infinitron from the garage.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1615, 1201, 339, 'neutral', false, 'Its ability to create virtual environments is discovered, enabling a safer experimental process.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1616, 473, 339, 'ally', false, 'Agrees to the new arrangement with a grin and a lighthearted warning.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1617, 1314, 339, 'neutral', false, 'Is invoked as a final thought to describe the precarious nature of their work.', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.entity_beat_appearances VALUES (1618, 221, 340, 'ally', false, 'Conducts a dangerous experiment that fails, causing him to panic and desperately call for help via Alexa.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1619, 1318, 340, 'enemy', true, 'Violently fails, hissing and popping before erupting.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1620, 1319, 340, 'mini-boss', true, 'Erupts from the experiment, choking the narrator and obscuring his vision, creating a life-threatening situation.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1621, 834, 340, 'neutral', false, 'Malfunctions and responds with a nonsensical phrase instead of broadcasting the narrator''s cry for help.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1622, 1324, 340, 'enemy', false, 'The core component of the failed experiment that becomes unstable.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1623, 221, 341, 'ally', false, 'Confronts his son and, inspired by the son''s mention of a simplistic video, has an epiphany about simplifying their work.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1624, 831, 341, 'ally', false, 'Appears and nonchalantly explains he was watching a video, inadvertently giving his father a crucial idea.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1625, 1321, 341, 'neutral', true, 'Serves as the catalyst for the narrator''s realization that over-complication is a problem they can solve.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1626, 221, 342, 'ally', false, 'Works with his son to reprogram the Infinitron, guiding the new parameters for simplification.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1627, 831, 342, 'ally', false, 'Collaborates with his father, asking skeptical but helpful questions while reprogramming the machine.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1628, 1212, 342, 'neutral', true, 'Is reprogrammed to provide simplified, manageable instructions using household items.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1629, 221, 343, 'ally', false, 'Leads the new, successful experiment, feeling a sense of accomplishment and relief.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1630, 831, 343, 'ally', false, 'Actively participates in the experiment, admitting it''s fun, and teases his father at the end.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1631, 1322, 343, 'ally', true, 'Is conducted successfully, producing a tangible result without any dangerous mishaps.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1632, 1323, 343, 'neutral', false, 'Is created as the successful outcome of the experiment, representing tangible progress.', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.entity_beat_appearances VALUES (1633, 1330, 344, 'neutral', true, 'Accelerate in pace due to a simplified approach, leading to a series of effortless-feeling breakthroughs.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1634, 1050, 344, 'ally', false, 'Work together, expressing a mix of excitement at their rapid progress and lingering uncertainty about their ultimate goal. They engage in witty banter about who deserves credit.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1635, 1201, 344, 'ally', false, 'Its simplified instructions are credited as the catalyst for the newfound success.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1636, 1331, 345, 'neutral', true, 'Is created through an iterative process and successfully passes a critical test in the homemade rig, confirming its zero-resistance property.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1637, 1201, 345, 'ally', false, 'Guides the family step-by-step from basic compounds to the final, advanced material.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1638, 1050, 345, 'ally', false, 'Follow the guidance to create the material, conduct the ''moment of truth'' test, and react with frozen awe at the successful result.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1639, 1332, 345, 'neutral', false, 'Used to provide the definitive proof of room-temperature superconductivity.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1640, 1333, 346, 'neutral', true, 'Serves as the dramatic proof-of-concept for the new material''s properties, amazing the family.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1641, 221, 346, 'ally', false, 'Successfully levitates on the polymer, expressing triumph and immediately planning to test it with the Eternal Engine.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1642, 455, 346, 'ally', false, 'Is wide-eyed with amazement and immediately envisions building hoverboards with the new technology.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1643, 454, 346, 'ally', false, 'Reacts with a mix of humorous concern and reverence, acknowledging that the discovery ''changes everything''.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1644, 295, 346, 'unknown', false, 'Mentioned as the next, more extreme test for the Superconductive Polymer''s capabilities.', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.entity_beat_appearances VALUES (1645, 292, 347, 'ally', true, 'Awakens to the hellish landscape, experiencing the full sensory and psychological assault of the environment.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1646, 1340, 347, 'enemy', false, 'Tears at the protagonist, described as a ravenous entity.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1647, 982, 347, 'enemy', false, 'Serves as the endless, yawning void and the source of the torment.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1648, 1342, 347, 'enemy', false, 'Shifts under the protagonist''s bare feet, causing pain and instability.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1649, 1343, 347, 'enemy', false, 'Assaults the protagonist''s mind with agonizing sounds.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1650, 1345, 348, 'ally', true, 'Emerges from the chaos, calling out with a clear voice and extending a hand to the protagonist.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1651, 292, 348, 'ally', false, 'Is anchored by the figure''s voice and presence, hesitating before accepting their help.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1652, 1345, 349, 'ally', true, 'Explains that there is no conventional path out and that they must forge their own way using Truth and by solving riddles.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1653, 292, 349, 'ally', false, 'Questions the figure, expressing desperation and frustration.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1654, 169, 349, 'neutral', false, 'Introduced as the key to resistance and escape.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1655, 1347, 349, 'neutral', false, 'Introduced as the challenges that form the path forward.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1656, 292, 350, 'ally', false, 'Pushes forward with the figure, enduring the shifting terrain and mental assaults.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1657, 1345, 350, 'ally', true, 'Acts as a steady anchor, urging the protagonist onward and warning them not to give in to fear.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1658, 1349, 350, 'mini-boss', false, 'Represents the grotesque shapes whose whispers and screams dig into the protagonist''s mind.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1659, 54, 350, 'enemy', false, 'Identified as the fuel that empowers the Abyss.', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.entity_beat_appearances VALUES (1660, 278, 351, 'ally', true, 'Fights desperately against demons while wounded, clinging to the Eternal Engine.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1661, 295, 351, 'ally', false, 'Wielded by the Protagonist, its power providing a painful anchor to reality.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1662, 1353, 351, 'enemy', false, 'A skeletal, flame-wreathed demon lunges from the shadows, attacking the Protagonist.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1663, 278, 352, 'ally', true, 'Is transported to a glass-like plane and confronts infinite reflections of their own struggle while being addressed by a mysterious voice.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1664, 804, 352, 'neutral', false, 'Twists reality, causing the shift in location.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1665, 1355, 352, 'unknown', false, 'Speaks cryptically to the Protagonist about endurance and the nature of the place.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1666, 278, 353, 'ally', true, 'Finds themself trapped as their weapon''s power fades and new threats emerge.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1667, 295, 353, 'ally', false, 'Its glow dims and its hum dies, signaling a loss of power.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1668, 1356, 353, 'enemy', false, 'Slowly and deliberately close in on the Protagonist.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1669, 1357, 353, 'enemy', false, 'A vast, mechanical sound rises, adding to the sense of being trapped.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1670, 278, 354, 'ally', true, 'Is swallowed by a void, attacked again, and spots a potential escape route.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1671, 1358, 354, 'enemy', false, 'Engulfs the Protagonist, pressing in with crushing weight and despair.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1672, 1353, 354, 'enemy', false, 'Attack the Protagonist in the void, wounding their leg.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1673, 1359, 354, 'neutral', false, 'Gleams in the rubble, offering a glimmer of hope for escape.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1674, 278, 355, 'ally', false, 'Fights alongside mysterious new allies against an overwhelming force.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1675, 1360, 355, 'ally', true, 'Materialize to assist the Protagonist, fighting fiercely before being destroyed.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1676, 1361, 355, 'enemy', true, 'Surges forward in endless numbers, overwhelming and obliterating the soldiers and the Protagonist.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1677, 804, 355, 'neutral', false, 'Twists violently, heralding the arrival of the soldiers.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1678, 278, 356, 'ally', true, 'Is left alone once more after the scene fractures, focusing on the only potential escape.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1679, 1359, 356, 'neutral', false, 'Remains as the sole object of the Protagonist''s focus and hope.', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.entity_beat_appearances VALUES (1680, 292, 357, 'ally', true, 'With trembling hands, reaches for the wire and uses the Engine Sword to begin prying it from the rubble.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1681, 1365, 357, 'neutral', false, 'Shimmers brightly and pulses with warmth, acting as the focal point of the protagonist''s efforts.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1682, 1366, 357, 'neutral', false, 'Sings with a mournful harmony and is used as a tool to free the wire.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1683, 1367, 357, 'enemy', false, 'Close in on the protagonist, their growls adding to the tension.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1684, 1376, 357, 'neutral', false, 'Fade into whispers and then silence, marking the end of the prelude and the start of the main action.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1685, 292, 358, 'ally', true, 'Pulls the wire free and holds it firm, enduring the shattering of reality and maintaining their existence against the portal''s power.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1686, 1368, 358, 'enemy', true, 'Tears open as a wound in space, pulsing with malevolent power.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1687, 1369, 358, 'enemy', false, 'Are revealed in flashes within the vortex, hinting at the horrors beyond.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1688, 1370, 358, 'enemy', false, 'Manifests as a darkness within the portal, pulsing with eldritch hunger.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1689, 292, 359, 'ally', true, 'Retrieves the Ancient Tome and speaks the Ancient Amharic Words, intentionally widening the portal.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1690, 1372, 359, 'neutral', false, 'Act as a raw, primal force that causes the portal to explode outward.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1691, 1368, 359, 'enemy', false, 'Explodes outward in response to the incantation.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1692, 1373, 359, 'enemy', false, 'Emerge from the widened portal, their roars vibrating through the protagonist.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1693, 1374, 359, 'mini-boss', true, 'Emerges as a massive, terrifying example of the beasts, representing a significant escalation of the threat.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1694, 292, 360, 'ally', true, 'Fights back by hurling demons into the void, but is ultimately overwhelmed by the portal''s pull and dragged across the threshold.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1695, 1368, 360, 'enemy', true, 'Reverses its force, creating an irresistible pull that drags reality and the protagonist inward.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1696, 1367, 360, 'enemy', false, 'Are used as projectiles by the protagonist before being swallowed by the void.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1697, 1370, 360, 'enemy', false, 'Swallows the demons and exerts the final pull on the protagonist, promising enlightenment and consumption.', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.entity_beat_appearances VALUES (1698, 292, 361, 'ally', false, 'Enters Oblivion and is confronted by the Herald.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1699, 266, 361, 'enemy', false, 'Imposes its oppressive, malevolent nature on the Protagonist.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1700, 1380, 361, 'mini-boss', true, 'Steps forward to confront the Protagonist, boasting of its eternal nature and the Protagonist''s insignificance.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1701, 292, 362, 'ally', false, 'Declares his defiance and his quest for truth.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1702, 1382, 362, 'ally', false, 'Manifests as the source of the Protagonist''s defiance.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1703, 1380, 362, 'mini-boss', false, 'Responds with contemptuous laughter and insults.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1704, 1381, 362, 'enemy', true, 'Emerge from the shadows to mock the Protagonist and warn him about the price of Knowledge.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1705, 1000, 362, 'neutral', false, 'Is personified by the abominations as a dangerous, seductive entity.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1706, 292, 363, 'ally', true, 'Fueled by fury, attacks the Herald with the Infinitron.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1707, 1380, 363, 'mini-boss', false, 'Is surprised and impaled by the Protagonist''s attack.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1708, 1383, 363, 'neutral', false, 'Is used as the weapon to kill the Herald.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1709, 1385, 363, 'neutral', false, 'Is torn from the Herald''s chest by the Protagonist.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1710, 1380, 364, 'mini-boss', false, 'Issues a final, venomous warning with its dying words.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1711, 1386, 364, 'unknown', true, 'Is named as a consuming force that will destroy the Protagonist.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1712, 292, 364, 'ally', false, 'Claims the fragment of knowledge from the dying creature.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1713, 1387, 364, 'neutral', false, 'Is clutched by the Protagonist, burning itself into his soul.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1714, 292, 365, 'ally', false, 'Walks deeper into the darkness, torn between terror and a strange tranquility.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1715, 1388, 365, 'neutral', false, 'Appears before the Protagonist, leading him further into Oblivion.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1716, 1389, 365, 'enemy', true, 'Whispers in the Protagonist''s mind, tempting him with the peace of giving up.', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.entity_beat_appearances VALUES (1717, 292, 366, 'ally', false, 'Is violently transported to a new, horrifying reality and observes the grotesque version of Elysium.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1718, 804, 366, 'neutral', true, 'Twists reality, initiating the scene change.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1719, 1394, 366, 'neutral', false, 'Serves as the vessel for the protagonist''s arrival.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1720, 1395, 366, 'enemy', false, 'Is revealed as a pulsating, flesh-like city swarming with creatures.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1721, 1396, 366, 'enemy', false, 'Are seen swarming the ruins of the city.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1722, 292, 367, 'ally', true, 'Runs and fights against the corrupted reality, while their body erupts with soldiers and their internal machinery convulses.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1723, 1397, 367, 'ally', false, 'Claw their way out of the protagonist''s pores to attack the surrounding corruption.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1724, 1398, 367, 'neutral', false, 'Screams and pulses erratically, channeling power.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1725, 917, 367, 'neutral', false, 'Convulses violently, feeding the protagonist strength.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1726, 1396, 367, 'enemy', false, 'Hiss and retaliate, their flesh burning the protagonist on contact.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1727, 1403, 367, 'mini-boss', false, 'Represents the primary target of the protagonist''s wild swings, its form mocking him.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1728, 292, 368, 'ally', true, 'Holds firm against immense strain to fully form the Barrier of Shadows and witnesses the revelation beyond it.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1729, 1397, 368, 'ally', false, 'Shriek and slash at the barrier, their attacks sending painful shocks through the protagonist.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1730, 1400, 368, 'ally', false, 'Coalesces with a deafening crack, pushing back the corruption but revealing something worse.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1731, 1401, 368, 'neutral', false, 'Is glimpsed beyond the barrier, showing incomprehensible cosmic horrors.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1732, 1402, 368, 'neutral', false, 'Emerges from the chaos as symbols and patterns that sear themselves into the protagonist''s vision.', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.entity_beat_appearances VALUES (1737, 852, 370, 'ally', true, 'Enters the room, expressing relief that he''s awake and worry over his intense screaming during the night. Her touch grounds him.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1738, 292, 370, 'ally', false, 'Responds hoarsely, still shaken by the experience but comforted by his wife''s presence.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1739, 292, 371, 'ally', true, 'Explains the dream was more and begins writing down the knowledge with a steady hand, stating it will take ''Everything''.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1740, 852, 371, 'ally', false, 'Watches him, her breath charged with anticipation, and asks what the endeavor will require.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1741, 1409, 371, 'neutral', false, 'Serves as the instrument to pull the ''impossible truth'' from the protagonist''s mind into the tangible world.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1742, 1408, 371, 'neutral', false, 'Is actively being transcribed from thought to ink.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1743, 1411, 371, 'neutral', false, 'Manifests as the wife leans closer, sensing the importance of the moment.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1733, 292, 369, 'ally', false, 'Jolts awake, struggling with the remnants of the nightmare but realizing the clarity of the knowledge he received.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1734, 1407, 369, 'mini-boss', true, 'Its echoes linger, clawing at the protagonist''s sanity and leaving him feeling suffocated.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1735, 1410, 369, 'enemy', false, 'Manifests as the protagonist gasping for air, covered in sweat, and feeling trapped by his sheets.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1736, 1408, 369, 'neutral', false, 'Burns vividly in the protagonist''s mind, feeling like a command etched into his soul.', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.entity_beat_appearances VALUES (1748, 292, 372, 'ally', true, 'Reflects on his failures and growing frustration while trying to understand the devices.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1749, 281, 372, 'neutral', false, 'Is used as an input for the Infinitron, but fails to provide any useful information.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1750, 1212, 372, 'neutral', false, 'Processes the dream journal and outputs only gibberish.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1751, 295, 372, 'neutral', false, 'Sits humming, a silent and taunting presence.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1753, 1420, 372, 'enemy', false, 'Dominates the protagonist''s emotional state.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1754, 1421, 372, 'neutral', false, 'Manifests as a physical feeling of dread and incompleteness.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1755, 1419, 373, 'mini-boss', true, 'Forcefully enters the protagonist''s mind to deliver a direct, non-negotiable revelation about the three devices.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1756, 292, 373, 'ally', false, 'Is the passive recipient of the dream''s truth-carving assault.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1757, 295, 373, 'neutral', false, 'Is revealed in the dream as a source of raw, god-like power.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1758, 1212, 373, 'neutral', false, 'Is revealed as a repository of infinite wisdom.', '2026-02-27 15:02:46.066173-05');
