INSERT INTO public.entity_beat_appearances VALUES (2774, 221, 630, 'ally', true, 'Escorted through opulent hallways, sinks into a plush chair feeling small and underdressed with a suitcase of gold beside them.', '2026-02-27 19:24:44.029135-05');
