INSERT INTO public.entity_beat_appearances VALUES (1879, 1508, 406, 'mini-boss', true, 'Identifies itself and offers a tempting peace, urging them to cease their struggle.', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.entity_beat_appearances VALUES (1880, 157, 406, 'ally', false, 'In a state of weary acceptance, agrees in unison with Stacey to accept the offer.', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.entity_beat_appearances VALUES (1881, 195, 406, 'ally', false, 'Overcome by the temptation to stop running, accepts the offer in unison with Todd.', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.entity_beat_appearances VALUES (1882, 1511, 406, 'neutral', false, 'Becomes the object of their shared desire as they ask to be made a channel of it.', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.entity_beat_appearances VALUES (1883, 195, 407, 'ally', true, 'Wakes up and struggles to differentiate between the nightmare and reality, until the pain and sight of her real leg wound confirms the horror.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1884, 513, 407, 'neutral', false, 'Its squalid, familiar details serve as an anchor to reality that is challenged by Stacey''s wound.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1885, 1516, 407, 'neutral', false, 'Clashes with Stacey''s real surroundings, causing her initial confusion.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1886, 1517, 407, 'neutral', true, 'Serves as the undeniable proof that the nightmare was real.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1887, 157, 407, 'ally', false, 'Is present but unconscious, sprawled on the floor snoring.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1888, 195, 408, 'ally', true, 'Shares a look with Todd, wordlessly acknowledging their shared fate and the loss of her defiance.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1889, 157, 408, 'ally', true, 'Wakes, checks his own injury, and locks eyes with Stacey, confirming he understands what happened to them.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1890, 1518, 408, 'neutral', false, 'Manifests between the two, a silent agreement of their new, terrifying reality.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1891, 1515, 408, 'enemy', false, 'Is identified as the transcendent entity that has marked them for an unknown purpose, leaving them to wait for its call.', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_beat_appearances VALUES (1892, 1515, 409, 'neutral', true, 'A slumbering cosmic presence that is stirred awake by a disturbance.', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_beat_appearances VALUES (1893, 1523, 409, 'neutral', false, 'The ripple in existence that awakens I AM.', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_beat_appearances VALUES (1894, 1515, 410, 'neutral', true, 'Turns its senses toward the mortal realm to investigate the tremor.', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_beat_appearances VALUES (1895, 456, 410, 'unknown', false, 'Is discovered by I AM as the source of the disturbance.', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_beat_appearances VALUES (1896, 1525, 410, 'unknown', false, 'Mentioned as the overreaching mortal creator of the Engine.', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_beat_appearances VALUES (1897, 1526, 410, 'neutral', false, 'Flickers through I AM''s consciousness upon its discovery.', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_beat_appearances VALUES (1898, 1527, 411, 'enemy', true, 'Emerge from their banishment, their collective presence crackling through the void with powerful, unspoken intent.', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_beat_appearances VALUES (1899, 1515, 412, 'neutral', true, 'Silently observes the Watchers as they debate, contemplating the cosmic balance and the potential consequences of their intervention.', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_beat_appearances VALUES (1900, 1527, 412, 'enemy', false, 'Debate whether to intervene with humanity, their different voices expressing awe, caution, and sinister delight.', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_beat_appearances VALUES (1901, 1529, 413, 'mini-boss', true, 'Forcefully interrupts the debate, hissing with malice and demanding immediate intervention before their chance to harvest souls is lost.', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_beat_appearances VALUES (1902, 1527, 413, 'enemy', false, 'Their debate is broken as they react to the fourth''s demand, shifting the group''s consensus towards action.', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_beat_appearances VALUES (1903, 1533, 414, 'enemy', true, 'Descend into the mortal realm, take on monstrous forms, and begin tormenting humanity.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1904, 1534, 414, 'mini-boss', false, 'Speaks for the group, declaring their mastery and intent to make humanity suffer.', '2026-02-27 15:14:12.843937-05');
