INSERT INTO public.entity_beat_appearances VALUES (1906, 1525, 415, 'enemy', true, 'Consumed by madness and greed, creates and activates the Matter Replicator with reckless abandon.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1907, 297, 415, 'enemy', false, 'Is created by fusing the Eternal Engine and Infinitron, unleashing cosmic terrors upon activation.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1908, 1541, 415, 'enemy', false, 'Drives the Dreamer to the brink of insanity.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1909, 1542, 415, 'enemy', false, 'Ignites the Dreamer''s depraved desires, leading to the device''s creation.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1910, 295, 415, 'neutral', false, 'Is fused into the Matter Replicator.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1911, 1212, 415, 'neutral', false, 'Is fused into the Matter Replicator.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1912, 1533, 416, 'enemy', true, 'Debate various sadistic methods for dealing with mortals, from consumption to psychological warfare.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1913, 1534, 416, 'mini-boss', false, 'Argues against simple annihilation, suggesting they toy with mortal sanity instead.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1914, 1515, 416, 'unknown', false, 'Listens to the debate in silent contemplation, separate from the others.', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_beat_appearances VALUES (1915, 1533, 417, 'enemy', true, 'Having reached a consensus, they descend upon the mortal world to enact their plan of psychological corruption.', '2026-02-27 15:14:12.843937-05');
