INSERT INTO public.entity_beat_appearances VALUES (1917, 1515, 418, 'enemy', true, 'Withdraws into the Abyss to observe events, choosing not to interfere directly.', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.entity_beat_appearances VALUES (1918, 982, 418, 'neutral', false, 'Serves as the realm that I AM melts back into.', '2026-02-27 15:15:11.588631-05');
