INSERT INTO public.entity_beat_appearances VALUES (2136, 1693, 469, 'neutral', false, 'Interpreted as a symphony accompanying the protagonist''s rise to power.', '2026-02-27 15:28:10.463106-05');
INSERT INTO public.entity_beat_appearances VALUES (2137, 1640, 470, 'ally', false, 'Explains the Infinitron''s struggles with the volatile stock market, feeling defensive.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2138, 472, 470, 'ally', false, 'Expresses her deep frustration with their financial and living situation through sarcasm.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2139, 473, 470, 'ally', false, 'Questions the point of the Infinitron if they are still ''broke''.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2140, 1701, 470, 'enemy', true, 'Dominates the conversation as the family grapples with their lack of funds and slow progress.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2141, 1700, 470, 'neutral', false, 'Serve as the physical backdrop and symbol of the family''s stressful, transitional state.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2142, 1212, 470, 'neutral', false, 'Its disappointing performance is the catalyst for the family''s discussion and frustration.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2143, 473, 471, 'ally', false, 'Suggests the pivotal idea of replicating gold to solve their money problems.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2144, 1640, 471, 'ally', true, 'Seizes upon the idea with excitement, scans the family heirloom, and begins mass-producing gold.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2145, 1702, 471, 'neutral', false, 'Used as the atomic template for the replication process.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2146, 1212, 471, 'neutral', false, 'Switches from market analysis to physical replication, churning out gold bars and chains.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2147, 1703, 471, 'neutral', false, 'Begins to appear in vast quantities, piling up in the house.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2148, 472, 471, 'ally', false, 'Angrily points out the narrator''s foolish attempt to smelt gold when the machine can create bars directly.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2149, 1704, 472, 'mini-boss', true, 'Manifests as the family realizes they have no way to sell their massive haul, creating paranoia and conflict.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2150, 1703, 472, 'neutral', false, 'Transforms from a solution into the source of the problem, a literal ton of useless, dangerous metal.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2151, 1705, 472, 'neutral', false, 'Their refusal to handle large amounts serves as the first concrete proof that liquidating the gold is a massive problem.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2152, 1640, 472, 'ally', false, 'His initial excitement turns to apprehension and paranoia as he grapples with the consequences.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2153, 472, 472, 'ally', false, 'Shares in the growing sense of urgency and fear over their untenable situation.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2154, 473, 472, 'ally', false, 'Makes a snarky comment (''Talk about yellow brick road, Dr. Oz.''), highlighting the absurdity of their predicament.', '2026-02-27 15:29:19.507091-05');
INSERT INTO public.entity_beat_appearances VALUES (2155, 221, 473, 'ally', true, 'Driven by desperation, uses anonymity tools to search the dark web and makes contact with a shady figure known as The Viper.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2156, 1713, 473, 'neutral', false, 'Acts as the primary motivator for the narrator''s risky online search.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2157, 1703, 473, 'neutral', false, 'The source of the narrator''s crushing stress, its presence in the home is a constant pressure.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2158, 1711, 473, 'neutral', false, 'Serves as the illicit venue where the narrator finds the contact for The Viper.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2159, 1709, 473, 'mini-boss', false, 'Responds to the narrator''s message with a terse, demanding summons for a meeting.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2160, 1712, 473, 'neutral', false, 'Enables the narrator''s secret search for a criminal buyer.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2161, 472, 474, 'ally', true, 'Confronts the narrator, discovering his plan and expressing alarm and skepticism about dealing with ''The Viper''.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2162, 221, 474, 'ally', false, 'Is caught by his wife and defends his dangerous plan as their only remaining option, ultimately deciding to proceed with the meeting.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2163, 1709, 474, 'mini-boss', false, 'His name and the nature of the proposed meeting become the focal point of the wife''s concern and the couple''s argument.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2164, 1703, 474, 'neutral', false, 'A single bar is taken by the narrator to serve as a sample for the clandestine meeting.', '2026-02-27 15:30:15.446954-05');
INSERT INTO public.entity_beat_appearances VALUES (2165, 1709, 475, 'mini-boss', true, 'Meets the couple, establishes his professional demeanor, and examines their gold, with his interest quickly turning to cold suspicion due to its perfection.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2166, 292, 475, 'ally', false, 'Presents the gold for inspection, attempting to maintain a confident facade during the tense transaction.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2167, 852, 475, 'ally', false, 'Observes the interaction, her initial nervousness justified as The Viper''s attitude shifts.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2168, 1703, 475, 'neutral', false, 'Its flawless appearance is inspected, becoming the central point of contention.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2169, 1719, 475, 'neutral', false, 'Permeates the interaction, escalating as The Viper''s suspicion grows.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2170, 1709, 476, 'mini-boss', true, 'Abruptly rejects the gold as worthless and dangerous, snaps at the couple for wasting his time, and issues a veiled threat before leaving.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2171, 292, 476, 'ally', false, 'Experiences a moment of panic (''stomach dropped'') as the deal collapses, leaving him in a worse position.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2172, 852, 476, 'ally', false, 'Reacts with visible fear, her face going pale at The Viper''s hostility.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2173, 1703, 476, 'neutral', false, 'Is declared an untraceable liability, cementing its status as an unsolvable problem for the couple.', '2026-02-27 15:31:04.243613-05');
INSERT INTO public.entity_beat_appearances VALUES (2174, 1724, 477, 'enemy', true, 'Dominates the family''s life, causing them to see threats everywhere and barricade themselves in their home.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2175, 1640, 477, 'ally', false, 'Experiences the paranoia and frustration, trying to think rationally while his wife urges immediate action.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2176, 948, 477, 'ally', false, 'Articulates the family''s fear and demands they end their involvement with The Viper and get rid of the gold.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2177, 831, 477, 'ally', false, 'Contributes to the paranoia by reporting that he saw someone watching him.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2178, 1726, 477, 'enemy', false, 'Appear near the house, serving as a physical manifestation of the family''s fear of being watched.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2179, 1728, 477, 'enemy', false, 'Allegedly observed by the son, confirming the family''s fears of surveillance.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2180, 1725, 477, 'neutral', false, 'Its presence in the garage is described as an ''unbearable, glowing liability'' that fuels the family''s desperation.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2181, 1709, 478, 'mini-boss', true, 'Listens to the narrator''s declaration with unnerving intensity and silence, then casually agrees, subverting all expectations of a violent confrontation.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2182, 1640, 478, 'ally', false, 'Confronts The Viper to declare they are withdrawing from the deal, despite his intense fear.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2183, 948, 478, 'ally', false, 'Accompanies her husband to the final meeting, presenting a united front.', '2026-02-27 15:31:52.077212-05');
INSERT INTO public.entity_beat_appearances VALUES (2184, 1733, 479, 'neutral', true, 'Runs into the bar looking for her ''sparkly crayon'', inadvertently shattering her father''s menacing act.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2185, 1709, 479, 'enemy', false, 'His tough-guy persona crumbles instantly as he shifts into a gentle father, admitting his act was ''pure theatrics''.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2186, 1735, 479, 'enemy', false, 'Is exposed as a complete fabrication and dissolves on contact with domestic reality.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2187, 1640, 479, 'ally', false, 'Exchanges a wide-eyed glance with his wife, trying to process the sudden, absurd turn of events.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2188, 454, 479, 'ally', false, 'Reacts with disbelief and begins to see the humor in the situation.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2189, 1734, 479, 'neutral', false, 'Is clutched by the daughter, adding a layer of innocent absurdity to the scene.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2190, 1640, 480, 'ally', true, 'Bursts into laughter with his wife, releasing weeks of tension and finding a new resolve.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2191, 454, 480, 'ally', true, 'Mimics the daughter''s voice, breaks the remaining tension with laughter, and reassures her husband.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2192, 139, 480, 'neutral', false, 'Dominates the couple''s perception of the events, leading to cathartic laughter.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2193, 166, 480, 'enemy', false, 'Is reflected upon as a state they endured, which has now been broken by the ridiculous truth.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2194, 1738, 480, 'ally', false, 'Manifests as the couple drives home, united in their goal to find a real solution.', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_beat_appearances VALUES (2195, 1640, 481, 'ally', false, 'Enters the club and is immediately overwhelmed.', '2026-02-27 15:33:41.60525-05');
