INSERT INTO public.entity_beat_appearances VALUES (2199, 1640, 482, 'ally', true, 'Sits down and reflects on their fall from power and current state of anonymity.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2200, 1640, 483, 'ally', true, 'Considers their hidden abilities and questions their purpose.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2201, 1746, 483, 'ally', false, 'Are contemplated by the protagonist as a source of potential action.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2202, 1640, 484, 'ally', true, 'Recalls the event that brought them to this world.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2203, 1747, 484, 'neutral', false, 'Is remembered as the magical catalyst for the protagonist''s displacement.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2204, 1640, 485, 'ally', true, 'Recognizes the irony of possessing truth-revealing powers in a place of fantasy.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2205, 1746, 485, 'ally', false, 'Are identified as a source of ironic power in this setting.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2206, 1743, 485, 'enemy', false, 'Are unaware of the powerful being in their midst, highlighting the irony.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2207, 1640, 486, 'ally', true, 'Wrestles with uncertainty about their role, whether as an observer or an agent of change.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2208, 1640, 487, 'ally', true, 'Concludes their reflection with a vow to understand the world and use their powers.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2209, 1746, 487, 'ally', false, 'Are what the protagonist vows to harness in unexpected ways.', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_beat_appearances VALUES (2210, 831, 488, 'ally', true, 'Excitedly announces his game''s success, crediting the AI Infinitron.', '2026-02-27 15:34:52.287488-05');
