INSERT INTO public.entity_beat_appearances VALUES (2217, 1758, 489, 'neutral', false, 'Are the subject of the son''s request for business expansion.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2218, 755, 490, 'ally', true, 'Retreats to the garage-turned-fulfillment-center and reinforces the ''homework first'' rule.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2219, 831, 490, 'ally', false, 'Enters the garage to announce another order for a custom USB hub.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2220, 1761, 490, 'neutral', false, 'Represents the success and creativity of the merchandise being sold.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2221, 1759, 490, 'neutral', false, 'Is embodied by the chaotic, package-filled state of the garage.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2222, 755, 491, 'ally', true, 'Expresses his longing for the ''meaningful'' work of his past scientific experiments.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2223, 1762, 491, 'mini-boss', true, 'Manifests as the narrator''s internal conflict, causing him to devalue their current success.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2224, 831, 491, 'ally', false, 'Counters his father''s nostalgia by showing a review that proves their work is inspiring others.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2225, 948, 491, 'ally', false, 'Challenges her husband''s perspective by highlighting the practical success and financial benefits of their venture.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2226, 755, 492, 'ally', true, 'Accepts their new direction as a different form of innovation and rejoins the family in packing boxes.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2227, 948, 492, 'ally', false, 'Gently guides her husband toward this new perspective and then humorously urges him back to work.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2228, 831, 492, 'ally', false, 'Frames his work as ''entrepreneurial art,'' helping his father re-contextualize their venture.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2229, 1759, 492, 'neutral', false, 'Becomes the focus of the family''s renewed, unified purpose.', '2026-02-27 15:34:52.287488-05');
INSERT INTO public.entity_beat_appearances VALUES (2230, 221, 493, 'ally', false, NULL, '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_beat_appearances VALUES (2231, 1767, 493, 'enemy', true, 'The narrator reflects on the crushing physical toll of their work, comparing it to the deadly corporate culture he witnessed in Japan.', '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_beat_appearances VALUES (2232, 1768, 493, 'neutral', false, 'Mentioned as a grim comparison point for the family''s current state of overwork.', '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_beat_appearances VALUES (2233, 473, 494, 'ally', false, 'Bursts in excitedly to show off his Roblox game''s new update.', '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_beat_appearances VALUES (2234, 1755, 494, 'neutral', true, 'The coordinated action of automatons in the game serves as the catalyst for the narrator''s new idea.', '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_beat_appearances VALUES (2235, 221, 494, 'ally', false, 'Has a moment of inspiration, realizing they can build robots to solve their labor problem.', '2026-02-27 15:35:53.115407-05');
