INSERT INTO public.entity_beat_appearances VALUES (2237, 1775, 495, 'enemy', true, 'The wife expresses doubt about the robot plan by reminding the narrator of his past engineering disasters.', '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_beat_appearances VALUES (2238, 221, 495, 'ally', false, 'Defends his new idea against his wife''s teasing and skepticism.', '2026-02-27 15:35:53.115407-05');
