INSERT INTO public.entity_beat_appearances VALUES (2247, 221, 497, 'ally', false, 'Feels a sense of progress and accomplishment as the first prototype proves functional.', '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_beat_appearances VALUES (2248, 1777, 498, 'ally', true, 'Transforms the garage from chaos to efficiency by packing orders with precision, despite occasional, humorous mistakes.', '2026-02-27 15:36:43.559597-05');
INSERT INTO public.entity_beat_appearances VALUES (2249, 1780, 498, 'neutral', false, 'Mentioned as an object Boxy once mistakenly taped up.', '2026-02-27 15:36:43.559597-05');
