INSERT INTO public.entity_beat_appearances VALUES (2251, 1640, 499, 'ally', true, 'Watches Boxy and internally questions if this new automated life is meaningful innovation or a distraction from his true passions.', '2026-02-27 15:36:43.559597-05');
INSERT INTO public.entity_beat_appearances VALUES (2252, 1779, 499, 'neutral', true, 'Manifests as the central conflict of the beat, causing the narrator to yearn for his past life of research and discovery.', '2026-02-27 15:36:43.559597-05');
INSERT INTO public.entity_beat_appearances VALUES (2253, 985, 499, 'ally', false, 'Flickers within the narrator before being overshadowed by his doubt.', '2026-02-27 15:36:43.559597-05');
INSERT INTO public.entity_beat_appearances VALUES (2254, 472, 500, 'ally', true, 'Shares the narrator''s nostalgia but reframes their business as a different, valid form of problem-solving, providing comfort and then playfully ending the conversation.', '2026-02-27 15:36:43.559597-05');
INSERT INTO public.entity_beat_appearances VALUES (2255, 1640, 500, 'ally', false, 'Expresses his feelings to his wife and finds comfort in her perspective, breaking the tension with a joke.', '2026-02-27 15:36:43.559597-05');
