INSERT INTO public.entity_beat_appearances VALUES (2405, 989, 539, 'ally', true, 'Driven by fear of his failing health, he secretly builds the AutoDoc as a desperate gamble to heal himself.', '2026-02-27 15:48:27.36101-05');
