INSERT INTO public.entity_beat_appearances VALUES (2772, 2183, 629, 'neutral', false, 'Gleams over polished marble floors, contributing to the overwhelming sense of opulence.', '2026-02-27 19:23:59.009867-05');
INSERT INTO public.entity_beat_appearances VALUES (2773, 2188, 629, 'neutral', false, 'The Narrator''s dominant emotional experience upon approaching and entering the Goldman Sachs building.', '2026-02-27 19:23:59.009867-05');
INSERT INTO public.entity_beat_appearances VALUES (2778, 221, 631, 'ally', true, 'Pitches The S Corp''s account needs, presenting gold bullion as proof of assets while being deliberately vague about its origin.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2779, 2190, 631, 'neutral', false, 'Enters with calculated precision, acknowledges the gold with neutral curiosity, and immediately probes its origin.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2780, 2192, 631, 'neutral', false, 'Herr Müller''s gaze shifts to the suitcase; it becomes the focal point of the pitch.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2781, 1623, 631, 'neutral', false, 'Named by the Narrator as the corporate entity seeking the international account.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2782, 2194, 631, 'neutral', false, 'Secretly the true source of the gold; the Narrator must conceal its existence.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2783, 2190, 632, 'mini-boss', true, 'Explains rigorous compliance requirements — authenticity verification, chain of custody, AML laws — creating the primary obstacle to the Narrator''s plan.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2784, 2195, 632, 'enemy', false, 'The institutional regulatory force Herr Müller invokes as a non-negotiable barrier to processing the gold deposit.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2785, 221, 632, 'ally', false, 'Masks rising panic, agrees to provide all necessary documentation, and forces a smile while sweating.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2786, 2192, 632, 'neutral', false, 'Secured by Goldman Sachs for testing pending proper paperwork.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2787, 2197, 632, 'neutral', false, 'Manifests physically as a bead of sweat down the Narrator''s back under compliance scrutiny.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2788, 221, 633, 'ally', true, 'Leaves the meeting, mind racing; realizes a convincing false backstory for the gold must be constructed without exposing the replicator.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2789, 2196, 633, 'ally', false, 'Identified as the critical tool the Narrator must create to satisfy Goldman Sachs compliance and secure the account.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2790, 2194, 633, 'neutral', false, 'The secret that must be protected at all costs as the Narrator plans deceptive documentation.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2791, 2197, 633, 'neutral', false, 'Thoughts oscillate between cautious optimism and catastrophic scenarios during the agonizing post-meeting wait.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2792, 2195, 633, 'enemy', false, 'The looming regulatory threat that makes the fabrication of documentation a high-stakes necessity.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2793, 2190, 634, 'neutral', true, 'Calls to confirm gold authentication was successful but notes additional formalities must be addressed quickly to finalize the account.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2794, 221, 634, 'ally', false, 'Exhales in relief upon hearing the gold passed authentication; agrees to proceed and leans back with exhausted satisfaction.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2795, 2199, 634, 'neutral', false, 'The pivotal event confirming gold authentication and flagging remaining formalities.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2796, 2192, 634, 'neutral', false, 'Successfully authenticated; its value is now poised to be integrated into The S Corp''s new account.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2797, 2196, 634, 'ally', false, 'Still required — the additional formalities Herr Müller references mean the paper trail must be produced promptly.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2798, 1623, 634, 'neutral', false, 'Its corporate account is now close to finalization, representing a major milestone in the Narrator''s larger plan.', '2026-02-27 19:24:44.029135-05');
INSERT INTO public.entity_beat_appearances VALUES (2799, 221, 635, 'ally', true, 'Escorted to the conference room after arriving at Kaufmann''s office, having been referred by the Zurich banker.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2800, 2202, 635, 'ally', false, 'Greets the Narrator warmly, stating he has been briefed on requirements.', '2026-02-27 19:25:58.74048-05');
