INSERT INTO public.entity_beat_appearances VALUES (2802, 2214, 635, 'neutral', false, 'Referenced as the one who briefed Kaufmann and provided the referral.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2803, 2217, 635, 'ally', false, 'The institutional setting welcoming the Narrator.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2804, 2202, 636, 'ally', true, 'Explains tax implications, regulatory compliance, asset separation, liability protection, and the need for a fabricated acquisition backstory.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2805, 221, 636, 'ally', false, 'Listens carefully, gives vague but cooperative answers about the unconventional nature of funds.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2806, 1623, 636, 'neutral', false, 'Discussed as the target corporate structure for asset consolidation.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2807, 2218, 636, 'neutral', false, 'Kaufmann identifies the need to create a plausible backstory for the funds.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2808, 2195, 636, 'enemy', false, 'Implicitly present as the regulatory framework Kaufmann must navigate.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2809, 221, 637, 'ally', true, 'Cautiously discloses the true scale—trillions across hundreds of thousands of accounts—and stresses the need for identity protection.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2810, 2202, 637, 'ally', false, 'Absorbs the staggering revelation with composure, calling it ''substantial'' but not insurmountable.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2811, 2205, 637, 'neutral', false, 'Cited as the source of compounding wealth across the accounts.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2812, 2215, 637, 'neutral', false, 'Narrator hints at gold as only a small part of broader reserves, requests secure U.S. transport.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2813, 2213, 637, 'ally', false, 'Narrator explicitly wants family shielded from any liability or identity exposure.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2814, 2202, 638, 'ally', true, 'Outlines multi-layered strategy using intermediary holding companies in Switzerland, Monaco, Nigeria, Cayman Islands, and Luxembourg.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2815, 2206, 638, 'neutral', false, 'Proposed as buffers between source accounts and The S Corp.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2816, 1623, 638, 'neutral', false, 'Positioned as the ultimate legal owner of consolidated funds.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2817, 221, 638, 'ally', false, 'Tries to keep up, asking clarifying questions about the layering approach.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2818, 2195, 638, 'enemy', false, 'The threat Kaufmann is designing the layered structure to evade.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2819, 221, 639, 'ally', true, 'Reveals seed capital origins—Amazon store and son''s Twitch following—and explains wealth came from an automated system with no human managers.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2820, 2202, 639, 'ally', false, 'Proposes creating fictional investment manager personas with fabricated résumés and digital footprints.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2821, 2208, 639, 'neutral', false, 'Named as one source of initial seed capital.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2822, 455, 639, 'neutral', false, 'His Twitch following contributed additional seed money.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2823, 2210, 639, 'neutral', false, 'Audience whose monetization provided seed capital.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2824, 2205, 639, 'neutral', false, 'Revealed as the ''automated system'' behind all growth—no human managers exist.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2825, 2207, 639, 'neutral', false, 'Kaufmann proposes creating these to attribute the algorithmic growth to apparent human expertise.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2826, 2202, 640, 'ally', true, 'Confirms the complete strategy: all accounts funneled through holding companies into The S Corp, growth attributed to fabricated managers, family fully insulated.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2827, 221, 640, 'ally', false, 'Summarizes the plan back to Kaufmann and confirms his understanding.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2828, 2206, 640, 'neutral', false, 'Confirmed as the structural mechanism channeling assets into The S Corp.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2829, 2207, 640, 'neutral', false, 'Formally attributed as the architects of the wealth system in the fabricated narrative.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2830, 2213, 640, 'ally', false, 'Confirmed as completely insulated from any liability or direct links.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2831, 2218, 640, 'neutral', false, 'The overarching story tying together all components of the strategy.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2832, 2202, 641, 'ally', true, 'Assures the Narrator the plan is airtight, references the Johannesburg Papers as proof of the firm''s superior discretion.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2833, 221, 641, 'ally', false, 'Expresses final relief and optimism; thanks Kaufmann and shakes hands.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2834, 2211, 641, 'neutral', false, 'Cited by Kaufmann as evidence of his firm''s track record in large-scale financial concealment.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2835, 2212, 641, 'neutral', false, 'Referenced as a known failure Kaufmann contrasts with the secret Johannesburg operation.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2836, 2217, 641, 'ally', false, 'Presented as the trusted institution behind all prior successes and the current plan.', '2026-02-27 19:25:58.74048-05');
INSERT INTO public.entity_beat_appearances VALUES (2837, 221, 642, 'ally', true, 'Commutes daily to Zurich via ERB to complete corporate restructuring paperwork and secure permanent office space.', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.entity_beat_appearances VALUES (2838, 2202, 642, 'ally', false, 'Meets with the Narrator for corporate restructuring; grants permanent office space after being informed of the portal under NDA.', '2026-02-27 19:27:27.353131-05');
