INSERT INTO public.entity_beat_appearances VALUES (2840, 2225, 642, 'neutral', false, 'Central focus of the grueling daily meetings and planning sessions.', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.entity_beat_appearances VALUES (2841, 2227, 642, 'neutral', false, 'Enables the Narrator to reveal the portal to Liam, facilitating deeper cooperation.', '2026-02-27 19:27:27.353131-05');
