INSERT INTO public.entity_beat_appearances VALUES (2847, 2224, 643, 'ally', false, 'Created with humanlike personalities by the Infinitron; begin handling day-to-day administrative activities.', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.entity_beat_appearances VALUES (2848, 2230, 643, 'neutral', false, 'Setting where the Narrator conceives the robot-assistance idea while reviewing paperwork.', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.entity_beat_appearances VALUES (2849, 221, 644, 'ally', true, 'Acknowledges inevitability of exposure and devises a global network of corporate facades to deflect scrutiny.', '2026-02-27 19:27:27.353131-05');
