INSERT INTO public.entity_beat_appearances VALUES (2851, 2229, 644, 'enemy', false, 'Anticipated threat of curious investigators once large financial transactions begin rippling through global markets.', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.entity_beat_appearances VALUES (2852, 2228, 644, 'neutral', false, 'Conceived and crystallized as the strategy to mask The S Corp''s true nature worldwide.', '2026-02-27 19:27:27.353131-05');
