INSERT INTO public.entity_beat_appearances VALUES (2857, 2242, 645, 'neutral', false, 'The timeless void the entity drifts within before being disturbed.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2858, 2233, 646, 'unknown', true, 'Emerges fully from its chamber, twisted and contorted, and slaughters the invaders in violent retribution.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2859, 2234, 646, 'enemy', false, 'Breach the chamber and are immediately massacred by the awakened entity.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2860, 2235, 646, 'enemy', false, 'Its echoing sound drives the entity to madness and hastens its awakening.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2861, 2240, 646, 'neutral', false, 'Blood and screams fill the air as the entity exacts its vengeance.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2862, 2233, 647, 'unknown', true, 'Struggles against chaotic tremors and fragmented memories while consumed by dread and claustrophobia.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2863, 444, 647, 'neutral', false, 'Assault the entity''s consciousness — visions of boundless power and forgotten dimensions.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2864, 2238, 647, 'neutral', false, 'Grips the entity in primal terror, a wholly new sensation for its immortal mind.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2865, 2236, 647, 'neutral', false, 'Transformed in the entity''s perception from a haven into a suffocating cage.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2866, 2233, 648, 'unknown', true, 'Power surges and boils within its form; it breaks free with an otherworldly roar, shattering the ice prison.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2867, 2239, 648, 'neutral', false, 'Bubbles and boils under the entity''s skin with uncontrollable ferocity before exploding outward.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2868, 2236, 648, 'neutral', false, 'Ice tunnels shatter, crystal shards scatter like stars as the entity breaks free.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2869, 2241, 648, 'neutral', false, 'The broader Europan ice structure shudders with the force of the entity''s release.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2870, 2233, 649, 'unknown', true, 'Revels in carnage and madness, laughing maniacally and realizing the full apocalyptic scope of its powers.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2871, 2240, 649, 'neutral', false, 'The entity stands amidst carnage, tasting blood and exulting in horror.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2872, 2239, 649, 'neutral', false, 'The entity fully comprehends its power''s scope — capable of rending worlds apart with a mere thought.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2873, 444, 649, 'neutral', false, 'Past dominion reassembles fully as the entity revels in its glorious return to power.', '2026-02-27 19:28:40.312583-05');
INSERT INTO public.entity_beat_appearances VALUES (2874, 2244, 650, 'unknown', true, 'Exits the cavern and surveys the metallic colony defiling its ancient frozen domain.', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.entity_beat_appearances VALUES (2875, 2245, 650, 'neutral', false, 'Looms before the entity as an alien technological scar across the ancient ice.', '2026-02-27 19:29:52.368815-05');
