INSERT INTO public.entity_beat_appearances VALUES (2878, 2244, 651, 'unknown', true, 'Feels fury reignite and senses the irresistible cosmic call from Earth pulling it toward madness.', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.entity_beat_appearances VALUES (2879, 2247, 651, 'unknown', false, 'Creeps into the entity''s mind as a sinister pull, beckoning it to madness and bloodshed.', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.entity_beat_appearances VALUES (2880, 2253, 651, 'unknown', false, 'Identified as the source of the cosmic call and birthplace of the colonists.', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.entity_beat_appearances VALUES (2881, 2252, 651, 'neutral', false, 'The entity descends into a frenzy of cosmic horror driven by forces beyond human comprehension.', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.entity_beat_appearances VALUES (2882, 2244, 652, 'unknown', true, 'Surges toward the surface with primal fury, cracking frozen ice in its wake.', '2026-02-27 19:29:52.368815-05');
