INSERT INTO public.entity_beat_appearances VALUES (3005, 755, 667, 'ally', true, 'Recognizes the need for a physical presence and creates the RELMs to achieve this goal.', '2026-02-27 19:37:19.726648-05');
INSERT INTO public.entity_beat_appearances VALUES (3007, 2328, 667, 'ally', false, 'Are created as the solution for global property acquisition.', '2026-02-27 19:37:19.726648-05');
INSERT INTO public.entity_beat_appearances VALUES (3010, 2328, 668, 'ally', true, 'One of the RELMs discovers the ideal property after days of searching.', '2026-02-27 19:37:19.726648-05');
INSERT INTO public.entity_beat_appearances VALUES (3012, 2333, 668, 'neutral', false, 'Is the abstract concept that the skyscraper comes to represent.', '2026-02-27 19:37:19.726648-05');
INSERT INTO public.entity_beat_appearances VALUES (3013, 159, 668, 'ally', false, 'Is the beneficiary of the RELM''s successful discovery.', '2026-02-27 19:37:19.726648-05');
INSERT INTO public.entity_beat_appearances VALUES (2969, 159, 669, 'ally', false, 'Successfully acquires the property, establishing its concrete presence.', '2026-02-27 19:34:24.735892-05');
INSERT INTO public.entity_beat_appearances VALUES (3017, 755, 669, 'ally', false, 'Stands before the skyscraper, feeling the weight of the journey and the potential of what has been built.', '2026-02-27 19:37:19.726648-05');
INSERT INTO public.entity_beat_appearances VALUES (2966, 2298, 669, 'ally', false, 'Mentioned as the leader of the firm handling the acquisition.', '2026-02-27 19:34:24.735892-05');
INSERT INTO public.entity_beat_appearances VALUES (3019, 755, 670, 'ally', false, 'Expresses his initial impression of the building as ''wasted space''.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3020, 96, 670, 'ally', false, 'Compares the building to a ''liminal space'' and wants to record it for YouTube.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3021, 2297, 670, 'neutral', true, 'Its empty, immaculate state creates an eerie, unsettling atmosphere.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3023, 1786, 671, 'ally', false, 'Initiates the design discussion by suggesting the need for plants.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3024, 755, 671, 'ally', false, 'Agrees with his wife and suggests adding collaborative workstations.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3025, 96, 671, 'ally', false, 'Suggests adding ''jungle vibes'' with plants and a game room for the robotic staff.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3026, 2342, 671, 'ally', true, 'Is formed and expanded upon by the family''s brainstorming session.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3027, 2343, 671, 'neutral', false, 'Are mentioned as the hypothetical users of the proposed game room.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3028, 1786, 672, 'ally', true, 'Proposes creating a large event space for networking and showcases to maintain public appearances.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3029, 755, 672, 'ally', false, 'Admires his wife''s brilliant and strategic idea.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3030, 2342, 672, 'ally', false, 'Is further solidified with the addition of a strategic event space.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3031, 755, 673, 'ally', false, 'Connects to the Infinitron and activates the nanites to begin construction.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3032, 1212, 673, 'neutral', false, 'Acts as the interface for the narrator to command the nanites.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3033, 1847, 673, 'ally', true, 'Flow through the building like ''liquid silver'', rapidly transforming it according to the family''s vision.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3034, 2297, 673, 'neutral', false, 'Undergoes a physical transformation from an empty shell to a functional headquarters.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3035, 96, 673, 'ally', false, 'Watches the transformation, mesmerized, and calls it ''peak madness''.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3036, 2297, 674, 'neutral', true, 'Undergoes a complete transformation into a modern headquarters.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3037, 2348, 674, 'ally', false, 'Populate the headquarters, creating the illusion of a bustling corporate environment.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3038, 2349, 674, 'neutral', false, 'Added to the headquarters to help breathe life into the building.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3039, 1623, 674, 'ally', false, 'Its ambitions are the driving force behind the headquarters'' transformation.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3040, 2350, 675, 'neutral', true, 'Are created deep beneath the skyscraper to house the gateway network.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3041, 2351, 675, 'ally', true, 'Are installed in the subfloors, forming the backbone of global expansion.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3042, 96, 675, 'ally', false, 'Is mentioned as the inspiration for the subfloors via a meme he shared.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3043, 2352, 676, 'ally', true, 'Deploy through gateways to establish unassuming S Corp outposts in key global cities.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3044, 2353, 676, 'neutral', true, 'Are established in prime locations, appearing as mundane businesses while secretly housing gateways.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3022, 1080, 670, 'neutral', false, 'Serves as the primary descriptor for the building''s unsettling feeling.', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_beat_appearances VALUES (3045, 1293, 676, 'ally', false, 'Is maintained through the use of unassuming facades and careful operations.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3046, 2298, 676, 'ally', false, 'Is mentioned as orchestrating the purchases to maintain discretion.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3047, 755, 677, 'ally', true, 'Stands in the Houston hub, marveling at the empire and global network he has built.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3048, 2358, 677, 'ally', false, 'Represents the culmination of their efforts, a creation that transcends traditional boundaries.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3049, 2357, 677, 'ally', false, 'Is recognized as an extraordinary creation that seamlessly connects the world.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3050, 2297, 677, 'neutral', false, 'Serves as the central hub from which the narrator observes his creation.', '2026-02-27 19:39:02.867922-05');
INSERT INTO public.entity_beat_appearances VALUES (3051, 221, 678, 'ally', true, 'Collapses on the couch and breaks the silence by asking his wife for ideas on how to use the ERB gateway, his excitement palpable.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3052, 454, 678, 'ally', true, 'Sits in her favorite armchair, grounding her husband''s excitement with a soft-spoken warning about the dangers of moving too fast and gaining public attention.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3053, 2107, 678, 'neutral', false, 'Serves as the central topic of conversation, its limitless potential sparking both excitement and caution.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3054, 2366, 678, 'neutral', false, 'Provides a place of comfort and contemplation for the wife.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3055, 973, 678, 'neutral', false, 'Provides a place of rest for the narrator.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3056, 986, 678, 'neutral', false, 'Provides ambient, flickering light in the otherwise quiet room.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3057, 2369, 678, 'neutral', false, 'Sits in the wife''s lap, symbolizing a desire for control.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3058, 455, 679, 'ally', true, 'Bursts into the room, full of energy, and excitedly proposes his idea for a global race through the gateway.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3059, 2370, 679, 'neutral', true, 'The son''s enthusiastic but impractical suggestion that is gently rejected by his parents due to the need for secrecy.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3060, 221, 679, 'ally', false, 'Cautiously explains the need for secrecy using analogies of Batman and in-game trolls to illustrate the dangers of exposure.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3061, 454, 679, 'ally', false, 'Reinforces the need for a long-term, invisible strategy, reframing the rejection of the son''s idea as a matter of careful planning.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3062, 2372, 679, 'enemy', false, 'Invoked by the narrator as the ultimate real-world consequence of losing their anonymity.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3063, 2373, 679, 'neutral', false, 'Used as an analogy to explain why the family must remain anonymous.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3064, 221, 680, 'ally', true, 'Pivots from the previous discussion to propose a new, more viable idea: using the gateway to revolutionize global shipping.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3065, 2371, 680, 'neutral', true, 'The narrator''s vision for a practical, scalable, and covert application of the gateway technology, which is embraced by the family.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3066, 455, 680, 'ally', false, 'Quickly grasps and embraces the new idea, enthusiastically labeling it ''Amazon on steroids''.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3067, 454, 680, 'ally', false, 'Gives her cautious approval to the shipping idea, emphasizing the need to stay under the radar.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3068, 2375, 680, 'ally', false, 'Mentioned as part of the core, secret operational team alongside the family and the gateway.', '2026-02-27 19:39:52.734381-05');
INSERT INTO public.entity_beat_appearances VALUES (3069, 755, 681, 'ally', true, 'Decides on an ambitious plan and arranges a clandestine meeting with major shipping companies.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3070, 2378, 681, 'neutral', false, 'Contacted by the narrator to attend the meeting.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3071, 2379, 681, 'neutral', false, 'Contacted by the narrator to attend the meeting.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3072, 2380, 681, 'neutral', false, 'Contacted by the narrator to attend the meeting.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3073, 755, 682, 'ally', true, 'Challenges the executives and uses his secret technology to send test packages.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3074, 2381, 682, 'neutral', false, 'Express doubt but agree to the test, providing shipping labels and preparing packages.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3075, 2385, 682, 'neutral', false, 'Serve as the physical proof for the demonstration.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3077, 2352, 682, 'ally', false, 'Tasked off-screen to carry the packages through the gateways and confirm their arrival.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3078, 2381, 683, 'ally', true, 'React with shock, disbelief, and excitement upon receiving confirmation of the deliveries.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3079, 755, 683, 'ally', false, 'Skillfully deflects questions about his methods, focusing on the successful outcome.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3080, 2382, 683, 'neutral', false, 'Its existence is proven, but its mechanics remain a mystery to the executives.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3081, 755, 684, 'ally', true, 'Moves swiftly to formalize partnerships and establish the operational structure.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3082, 2387, 684, 'ally', false, 'Are formed, redefining the logistics industry.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3083, 2386, 684, 'neutral', false, 'Are established as the mysterious ''black box'' operational hubs for the new service.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3084, 2388, 684, 'neutral', false, 'Are implemented to protect the secrecy of the technology.', '2026-02-27 19:40:35.865132-05');
INSERT INTO public.entity_beat_appearances VALUES (3085, 1623, 685, 'ally', true, 'Its innovations are revolutionizing the shipping industry.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3086, 2391, 685, 'neutral', false, 'Enable the obliteration of cumbersome cross-border shipping processes.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3087, 2392, 685, 'neutral', false, 'Become quietly reliant on The S Corp''s technology.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3088, 221, 686, 'ally', true, 'Scrolls through Facebook and is struck by a revolutionary idea for personal transportation.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3089, 2394, 686, 'neutral', false, 'Serves as the catalyst for the narrator''s new vision with its phrase ''People are packages too''.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3090, 2395, 686, 'neutral', false, 'Takes root in the narrator''s mind, envisioning a world of instantaneous travel.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3091, 2297, 686, 'neutral', false, 'Acts as the setting where the narrator has his moment of inspiration.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3092, 2401, 686, 'neutral', false, 'The online community where the inspirational meme is posted.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3093, 2396, 687, 'neutral', true, 'Begin construction on new sites, disguised as human workers.', '2026-02-27 19:41:28.26476-05');
