INSERT INTO public.entity_beat_appearances VALUES (3098, 2400, 688, 'mini-boss', true, 'Erupts over the mysterious construction sites, creating intrigue and threatening secrecy.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3099, 221, 688, 'ally', false, 'Welcomes the intrigue and remains confident, intending to maintain secrecy until the project is ready.', '2026-02-27 19:41:28.26476-05');
INSERT INTO public.entity_beat_appearances VALUES (3100, 292, 689, 'ally', true, 'Reads a newspaper at their desk at the University of Chicago, learning about the S Corp''s discovery.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3101, 2408, 689, 'neutral', false, 'Serves as the medium for delivering the news about the temple.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3102, 159, 689, 'unknown', false, 'Mentioned in the newspaper as the discoverer of the temple.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3103, 2407, 689, 'neutral', false, 'The subject of the news article that captures the protagonist''s interest.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3104, 2409, 689, 'neutral', false, 'The setting for the protagonist''s mundane life before the call.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3105, 292, 690, 'ally', true, 'Accepts the S Corp''s offer, travels by jet, and arrives at the temple, feeling its energy and being consumed by curiosity.', '2026-02-27 19:42:29.884905-05');
