INSERT INTO public.entity_beat_appearances VALUES (3108, 2411, 690, 'neutral', false, 'Transports the protagonist to the temple site in Zambia.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3109, 2407, 690, 'neutral', false, 'The destination; its presence is physically felt upon arrival.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3110, 2412, 690, 'unknown', true, 'Radiates from the temple, causing unease and beckoning the protagonist closer.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3111, 2414, 690, 'neutral', false, 'Consumes the protagonist, compelling them to enter the temple despite the danger.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3112, 2413, 690, 'enemy', false, 'Mentioned as being inside the temple, establishing the threat the protagonist is about to face.', '2026-02-27 19:42:29.884905-05');
INSERT INTO public.entity_beat_appearances VALUES (3113, 292, 691, 'ally', false, 'Stands at the edge of the site, witnessing the mist and the visions it brings.', '2026-02-27 19:43:10.473409-05');
