INSERT INTO public.entity_beat_appearances VALUES (3116, 2419, 691, 'neutral', false, 'Begins to overwhelm the protagonist as a result of the visions.', '2026-02-27 19:43:10.473409-05');
INSERT INTO public.entity_beat_appearances VALUES (3117, 292, 692, 'ally', false, 'Feels their sense of self unravel and experiences pain as symbols are etched onto their skin.', '2026-02-27 19:43:10.473409-05');
