INSERT INTO public.entity_beat_appearances VALUES (3120, 2421, 692, 'neutral', false, 'Chant in the protagonist''s mind, furthering their disorientation.', '2026-02-27 19:43:10.473409-05');
INSERT INTO public.entity_beat_appearances VALUES (3121, 292, 693, 'ally', false, 'Is used as a vessel by the mist, forced to venture deeper and witness unspeakable horrors.', '2026-02-27 19:43:10.473409-05');
INSERT INTO public.entity_beat_appearances VALUES (3122, 2417, 693, 'mini-boss', true, 'Takes full control of the protagonist, using their body as a vessel to carry out its will.', '2026-02-27 19:43:10.473409-05');
