INSERT INTO public.entity_beat_appearances VALUES (3125, 2424, 693, 'neutral', false, 'Fill rooms, showcasing the temple''s deadly nature.', '2026-02-27 19:43:10.473409-05');
INSERT INTO public.entity_beat_appearances VALUES (3126, 292, 694, 'ally', false, 'Loses the last of their sanity as they witness the deity.', '2026-02-27 19:43:55.646305-05');
INSERT INTO public.entity_beat_appearances VALUES (3127, 2430, 694, 'neutral', false, 'Slips away completely, marking the point of no return.', '2026-02-27 19:43:55.646305-05');
