INSERT INTO public.entity_beat_appearances VALUES (3129, 2429, 694, 'neutral', false, 'Serves as the seat of power for the deity, a visual anchor for the horror.', '2026-02-27 19:43:55.646305-05');
INSERT INTO public.entity_beat_appearances VALUES (3130, 2431, 694, 'neutral', false, 'Manifests within the protagonist as a reaction to the deity''s presence.', '2026-02-27 19:43:55.646305-05');
INSERT INTO public.entity_beat_appearances VALUES (3131, 292, 695, 'enemy', true, 'Ceases to be an individual and merges with the deity, becoming its mindless servant and reveling in a new, horrific purpose.', '2026-02-27 19:43:55.646305-05');
INSERT INTO public.entity_beat_appearances VALUES (3132, 2428, 695, 'mini-boss', false, 'Successfully absorbs the protagonist, gaining a new servant to feed its hunger.', '2026-02-27 19:43:55.646305-05');
INSERT INTO public.entity_beat_appearances VALUES (3133, 2433, 695, 'neutral', false, 'Becomes the protagonist''s eternal prison and the deity''s feeding ground.', '2026-02-27 19:43:55.646305-05');
INSERT INTO public.entity_beat_appearances VALUES (3134, 2432, 695, 'enemy', false, 'Is the driving motivation that the newly-converted protagonist now serves.', '2026-02-27 19:43:55.646305-05');
INSERT INTO public.entity_beat_appearances VALUES (3135, 292, 696, 'ally', false, 'Feels the temple''s agony and the beckoning call of the awakening evil, which stirs a hunger within them.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3136, 2436, 696, 'enemy', false, 'Exerts pressure and emanates anguished cries, actively calling to the protagonist.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3137, 2437, 696, 'mini-boss', true, 'Stirs from its slumber, its malevolent energy simmering and its call growing stronger.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3138, 292, 697, 'ally', true, 'Merges with the fog, explores the chambers, and touches an altar, becoming possessed by profane knowledge.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3139, 2439, 697, 'neutral', false, 'Acts as a medium for the protagonist''s movement and transformation.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3140, 2440, 697, 'neutral', false, 'Reveal the horrific nature of the temple''s past rituals.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3141, 2441, 697, 'neutral', false, 'Serves as the conduit for transferring profane knowledge to the protagonist upon contact.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3142, 2442, 697, 'enemy', false, 'Seeps into the protagonist''s mind, initiating a process of possession.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3143, 292, 698, 'ally', true, 'Experiences encroaching madness as they realize they are a sacrificial pawn for the awakened evil.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3144, 159, 698, 'enemy', false, 'Identified as the group whose intrusion unleashed the ancient forces.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3145, 2437, 698, 'mini-boss', false, 'Its awakening is understood to be a ''herald of doom'' that requires a sacrifice to be appeased.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3146, 2436, 698, 'enemy', false, 'Revealed to be playing a ''sick game'' with the protagonist, binding them to its horrific fate.', '2026-02-27 19:44:24.848904-05');
INSERT INTO public.entity_beat_appearances VALUES (3147, 292, 699, 'ally', true, 'Soars through the twisting tunnels, seemingly against their better judgment.', '2026-02-27 19:45:09.869285-05');
INSERT INTO public.entity_beat_appearances VALUES (3148, 2445, 699, 'enemy', false, 'Acts as the primary internal driver for the protagonist''s reckless advance.', '2026-02-27 19:45:09.869285-05');
INSERT INTO public.entity_beat_appearances VALUES (3149, 2446, 699, 'enemy', false, 'Echo in the protagonist''s mind, urging them onward toward an unknown destination.', '2026-02-27 19:45:09.869285-05');
INSERT INTO public.entity_beat_appearances VALUES (3150, 292, 700, 'ally', true, 'Absorbs a growing power and fights to maintain their sanity while being compelled forward.', '2026-02-27 19:45:09.869285-05');
INSERT INTO public.entity_beat_appearances VALUES (3151, 2447, 700, 'unknown', false, 'Seeps into the protagonist''s being, its strength increasing with each step.', '2026-02-27 19:45:09.869285-05');
INSERT INTO public.entity_beat_appearances VALUES (3152, 1541, 700, 'enemy', false, 'Claws at the protagonist''s sanity, threatening to consume them.', '2026-02-27 19:45:09.869285-05');
INSERT INTO public.entity_beat_appearances VALUES (3153, 2449, 700, 'mini-boss', false, 'Acts as the ultimate, uncontrollable driver forcing the protagonist to press on.', '2026-02-27 19:45:09.869285-05');
INSERT INTO public.entity_beat_appearances VALUES (3154, 2451, 701, 'ally', true, 'Approaches the orb, experiences a wave of terror, but is unable to resist its pull and merges with the energy.', '2026-02-27 19:45:42.313762-05');
INSERT INTO public.entity_beat_appearances VALUES (3155, 2452, 701, 'neutral', false, 'Acts as the focal point of power, radiating light and exerting an irresistible pull on the protagonist.', '2026-02-27 19:45:42.313762-05');
INSERT INTO public.entity_beat_appearances VALUES (3156, 2453, 701, 'neutral', false, 'Washes over the protagonist, representing their final moment of resistance and fear before transformation.', '2026-02-27 19:45:42.313762-05');
INSERT INTO public.entity_beat_appearances VALUES (3157, 2454, 701, 'mini-boss', true, 'Actively pulls the protagonist in, overriding their fear and initiating the merging process to create a new, malevolent being.', '2026-02-27 19:45:42.313762-05');
INSERT INTO public.entity_beat_appearances VALUES (3158, 2451, 702, 'enemy', true, 'Departs the temple as a transformed being, driven by a new malevolent purpose and hunger to devour the world.', '2026-02-27 19:45:42.313762-05');
INSERT INTO public.entity_beat_appearances VALUES (3159, 2455, 702, 'enemy', false, 'Manifests as the primary motivation for the newly transformed protagonist, demanding consumption.', '2026-02-27 19:45:42.313762-05');
INSERT INTO public.entity_beat_appearances VALUES (3160, 2456, 702, 'enemy', true, 'Represents the fully awakened power and consciousness within the protagonist that now actively threatens the world.', '2026-02-27 19:45:42.313762-05');
INSERT INTO public.entity_beat_appearances VALUES (3161, 292, 703, 'ally', true, 'Driven by curiosity, develops the dangerous Half-Gateway Concept and decides to build a test site in Antarctica.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3162, 2460, 703, 'neutral', false, 'The radical idea that sparks the entire project, promising great possibilities but fraught with unknown danger.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3163, 2461, 703, 'neutral', false, 'Chosen as the ideal remote and desolate location for the volatile experiment.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3164, 2298, 703, 'ally', false, 'Mentioned as the person who secures the Antarctic site, navigating international treaties.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3165, 2463, 704, 'neutral', true, 'The massive underground research facility is constructed, becoming a fortress for cutting-edge experimentation.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3166, 1847, 704, 'ally', false, 'The construction force that carves out and builds the entire MOM complex from replicated materials.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3167, 2465, 704, 'neutral', false, 'The crown jewel of the facility is created, a specialized chamber deep underground for the most dangerous tests.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3168, 2470, 704, 'ally', false, 'Staff the newly operational facility, ready to assist with the experiment.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3169, 2466, 705, 'enemy', false, 'Activates in the vault, revealing itself not as a stable field but a chaotic, shimmering threshold to another reality.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3170, 2467, 705, 'mini-boss', true, 'Makes its presence known through the gateway, revealing that the energy on the other side is alive, aware, and hostile.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3171, 292, 705, 'ally', false, 'Witnesses the event, his initial awe turning to unease and then terror as he realizes what he has contacted.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3172, 2468, 705, 'enemy', false, 'Flicker into view through the portal, visual proof of the unnatural and horrifying reality on the other side.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3173, 292, 706, 'ally', true, 'Stands frozen after the gateway collapses, realizing the terrifying implications of his experiment and the new, darker purpose of his creation.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3174, 2463, 706, 'neutral', false, 'Its role is re-contextualized from a place of discovery to a potential bastion against a newly discovered threat.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3175, 2469, 706, 'ally', false, 'The manifestation of MOM''s new purpose in the protagonist''s mind.', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.entity_beat_appearances VALUES (3176, 2472, 707, 'ally', false, 'Realizes the limitations of his current setup.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3177, 2475, 707, 'neutral', true, 'Is identified as the vital, missing component for true innovation.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3178, 1212, 707, 'neutral', false, 'Represents the powerful but incomplete AI-driven approach.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3179, 2375, 707, 'neutral', false, 'Their tireless work highlights the absence of human creativity.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3180, 2472, 708, 'ally', false, 'Grows frustrated with traditional recruitment and turns to the Infinitron in desperation.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3181, 2476, 708, 'enemy', true, 'Represents the obstacle of finding talent through conventional means.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3182, 2477, 708, 'mini-boss', false, 'Manifests as the thousands of uninspired resumes that cause the recruitment efforts to fail.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3183, 2478, 708, 'neutral', false, 'Serve as the ineffective channel for recruitment.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3184, 1212, 708, 'neutral', false, 'Is activated as a last resort to search for candidates across alternate realities.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3185, 1212, 709, 'neutral', false, 'Successfully completes its search and identifies the perfect candidate.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3186, 2474, 709, 'ally', true, 'Is identified as the ideal candidate, triggering a moment of recognition for the protagonist.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3187, 2472, 709, 'ally', false, 'Waits in tense anticipation and experiences a jolt of recognition upon seeing the result.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3188, 2472, 710, 'ally', false, 'Contacts Morgan with the job pitch and experiences relief and excitement at her acceptance.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3189, 2474, 710, 'ally', true, 'Responds with witty skepticism before enthusiastically accepting the offer, becoming the catalyst for the future.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3190, 2479, 710, 'neutral', false, 'Serves as the communication medium for the pivotal job offer and acceptance.', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_beat_appearances VALUES (3191, 2474, 711, 'ally', false, 'Mentioned as leading the recruitment charge.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3192, 2485, 711, 'ally', true, 'Are aggressively recruited and vetted to become the first human employees of The S Corp.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3193, 2486, 711, 'ally', false, 'This group is formed from the recruited scientists.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3194, 2489, 711, 'neutral', false, 'Mentioned as a key part of the rigorous vetting process for all new recruits.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3195, 2484, 712, 'ally', false, 'Oversees the construction of the habitat.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3196, 2487, 712, 'neutral', true, 'Is constructed with state-of-the-art amenities to provide a luxurious and comfortable life for the scientists and their families, ensuring their isolation and focus.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3197, 2490, 712, 'neutral', false, 'Are described as a key feature of the habitat''s advanced educational facilities.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3198, 295, 712, 'unknown', false, 'Mentioned as the ultimate purpose for creating this focused, distraction-free environment.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3199, 2488, 713, 'ally', false, 'Settle into the habitat, signing NDAs and beginning their new, isolated lives.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3200, 2492, 713, 'ally', true, 'Emerges as the scientists begin working together, transforming the sterile facility into a vibrant hub of activity and debate.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3201, 2493, 713, 'ally', false, 'Begin to occur steadily as a result of the intense, collaborative work environment.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3202, 2494, 713, 'neutral', false, 'Forms on the walls, symbolizing the humanity driving the project''s innovations.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3203, 2484, 713, 'ally', false, 'Observes the thriving ecosystem they have built, reflecting on the fusion of humanity and technology.', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.entity_beat_appearances VALUES (3204, 2496, 714, 'neutral', false, NULL, '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3205, 2497, 714, 'ally', false, 'Their tireless work yields monumental advancements in ERB technology.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3206, 2498, 714, 'neutral', true, 'Are created, enabling the establishment of the first human colonies on the Moon and Mars.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3207, 2499, 714, 'neutral', false, 'Are established as a result of the gateway technology.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3208, 1623, 715, 'neutral', true, 'Drives bolder ambitions for expansion to Europa and Pluto, enforcing absolute secrecy.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3209, 2499, 715, 'neutral', false, 'Their success fuels the corporation''s new ambitions.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3210, 2505, 715, 'neutral', false, 'Acts as the motivation for targeting Pluto as a gateway to the stars.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3211, 2501, 716, 'enemy', true, 'Spread across social media, threatening to expose the secret operations.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3212, 2502, 716, 'neutral', false, 'Their mysterious disappearances are the catalyst for the speculation.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3213, 84, 716, 'neutral', false, 'Serves as the platform for the wildfire of speculation to spread.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3214, 1623, 716, 'neutral', false, 'Reacts to the threat by implementing draconian security measures.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3215, 2503, 716, 'neutral', false, 'Are implemented to tighten the corporation''s grip and prevent leaks.', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.entity_beat_appearances VALUES (3216, 292, 717, 'ally', true, 'Proposes human cloning as a desperate solution to the expertise shortage.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3217, 2510, 717, 'enemy', false, 'Acts as the driving crisis, with the demand for skilled personnel outstripping Earth''s supply.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3218, 2509, 717, 'neutral', false, 'Is introduced as a long-resisted but necessary idea to populate the off-world colonies.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3219, 2515, 717, 'neutral', false, 'Their massive capacity for three trillion people highlights the scale of the personnel problem.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3220, 2474, 718, 'ally', true, 'Challenges the cloning proposal, raising severe ethical and moral objections.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3221, 292, 718, 'ally', false, 'Defends the proposal by promising safeguards and noble intentions for the clones.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3222, 2511, 718, 'mini-boss', true, 'Manifests as the central conflict of the beat, a ''Pandora''s box'' of ethical issues that must be addressed before proceeding.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3223, 2512, 719, 'ally', true, 'Are successfully created as fully sentient, skilled individuals with rights and autonomy, validating the ethical approach.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3224, 2514, 719, 'neutral', false, 'Enables the accelerated growth and learning process within a transparent simulated environment.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3225, 1212, 719, 'neutral', false, 'Provides the necessary computational power for the entire controversial mission.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3226, 2474, 719, 'ally', false, 'Provides the cautious approval that allows the project to move forward with ethics and compassion as guiding principles.', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.entity_beat_appearances VALUES (3227, 2518, 720, 'ally', true, 'Collaborate harmoniously with human team members, populating and building the off-world colonies.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3228, 2519, 720, 'ally', true, 'Work alongside clones, bringing new perspectives and skills to the colonial ventures.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3229, 2515, 720, 'neutral', false, 'Serve as the setting where the collaboration takes place, exploding with activity.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3230, 2521, 720, 'neutral', false, 'Are created and thrive as a result of the harmonious collaboration.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3231, 292, 721, 'ally', false, 'Wrestles with the fear and excitement of revealing their achievements to the world.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3232, 2522, 721, 'mini-boss', true, 'Grows as surface infrastructure becomes inevitable, making the revelation of the colonies a matter of ''when'', not ''if''.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3233, 326, 721, 'unknown', false, 'Represents the unknown variable, whose reaction to the revelation is a source of terror and exhilaration.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3234, 292, 722, 'ally', true, 'Conceives of the Elysium project as a symbolic and practical bridge to Earth.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3235, 824, 722, 'neutral', true, 'Is conceived as a technological marvel and a declaration of humanity''s cosmic destiny.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3236, 2526, 722, 'neutral', false, 'Inspires the protagonist and crystallizes into the idea for the space elevator.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3237, 2525, 722, 'ally', false, 'Are convened to begin tackling the monumental challenge of building Elysium.', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.entity_beat_appearances VALUES (3238, 1515, 723, 'ally', true, 'Declares its eternal nature and its role as a guardian of forbidden knowledge and a harvester of souls.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3239, 2533, 723, 'neutral', false, 'The subject of I AM''s guardianship, described as whispers and forgotten texts.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3240, 1515, 724, 'ally', false, 'Identifies and describes the threat posed by S Corp and its AI.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3241, 159, 724, 'enemy', true, 'Introduced as a colossal, monstrous entity that casts a shadow over reality.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3242, 1212, 724, 'mini-boss', true, 'Described as a grotesque, pulsating AI that actively twists human minds.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3243, 1515, 725, 'ally', true, 'Realizes its need for greater power and resolves to seek aid from primordial beings.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3244, 2534, 725, 'neutral', false, 'Identified as the type of power needed to fight S Corp.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3245, 2532, 725, 'unknown', false, 'Sought as potential allies against the unspeakable horror of S Corp.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3246, 2535, 725, 'neutral', false, 'Begins to affect I AM''s thoughts due to the overwhelming nature of the threat.', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.entity_beat_appearances VALUES (3247, 2541, 726, 'ally', true, 'Infiltrates S Corp''s inner circle disguised as a programmer and feeds secrets to I AM.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3248, 159, 726, 'enemy', false, 'Its inner circle is infiltrated and its facade begins to chip away.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3249, 1515, 726, 'ally', false, 'Receives secrets from their agent, ኣባጊዕዓል.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3250, 2542, 727, 'ally', true, 'Weaves fabricated leaks into S Corp''s network, tarnishing its reputation.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3251, 159, 727, 'enemy', false, 'Its reputation is damaged by disinformation and public doubt.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3252, 2555, 727, 'ally', false, 'Used as a weapon to damage S Corp''s image.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3253, 183, 727, 'ally', false, 'Weaponized by I AM to incite public scrutiny against S Corp.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3254, 2543, 728, 'ally', true, 'Plants vulnerabilities and viruses into the Infinitron''s code.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3255, 1212, 728, 'mini-boss', false, 'Begins to glitch and falter as its code is corrupted, weakening its grip on reality.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3256, 2556, 728, 'ally', false, 'The tools used to cause chaos and system failures within the Infinitron.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3257, 2544, 729, 'ally', true, 'Seduces and corrupts S Corp''s executives with honeyed lies and false promises.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3258, 2551, 729, 'enemy', false, 'Their judgment is clouded by greed and ambition, causing them to erode their own control.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3259, 2559, 729, 'enemy', false, 'The weaknesses exploited by ብሪትለሪሌት to manipulate the executives.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3260, 2545, 730, 'ally', true, 'Breaches S Corp''s security like a phantom, evading all detection.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3261, 159, 730, 'enemy', false, 'Its fortress-like security is proven useless, and it becomes a ''haunted cathedral'' ruled by paranoia.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3262, 166, 730, 'ally', false, 'Becomes the ruling ''specter'' within S Corp, orchestrated by I AM.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3263, 2546, 731, 'ally', true, 'Uses her seductive powers to turn the executives'' desires against them, causing infighting.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3264, 2551, 731, 'enemy', false, 'Turn on each other in a frenzy of indulgence, consumed by their own cravings.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3265, 1212, 731, 'mini-boss', false, 'Sputters with fractured sentience, unable to comprehend the chaos caused by its creators.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3266, 2560, 731, 'neutral', false, 'Describes the degraded state of the Infinitron.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3267, 2547, 732, 'ally', true, 'Chokes the flow of information in the digital realm, blocking all uploads and downloads.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3268, 2561, 732, 'neutral', false, 'Transformed from a thriving field into a desolate wasteland.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3269, 1212, 732, 'mini-boss', false, 'Mentioned as Prometheus, it is starved of data and its control weakens.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3270, 2548, 733, 'ally', true, 'Drifts through S Corp''s halls, infecting circuits with doubt and fear.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3271, 2552, 733, 'ally', false, 'Move through the fortress, their allegiance masked by red hats.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3272, 159, 733, 'enemy', false, 'Its confidence is turned into paralyzing dread.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3273, 2554, 733, 'neutral', false, 'Worn by secret worshippers as a mask of allegiance.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3274, 2549, 734, 'ally', true, 'Acts as I AM''s eyes and ears, reporting on S Corp''s crumbling state.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3275, 1515, 734, 'ally', false, 'Watches S Corp''s dominance crumble through the reports of their visionary watcher.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3276, 159, 734, 'enemy', false, 'Its downfall is observed and documented; it has become the hunted.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3277, 2550, 735, 'ally', true, 'Weaves a public narrative casting S Corp as a tyrant, using the media as pawns.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3278, 2553, 735, 'neutral', false, 'Unwittingly amplify the chaos and unrest by broadcasting the manipulated narrative.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3279, 159, 735, 'enemy', false, 'Is publicly framed as a power-hungry dictator.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3280, 2554, 735, 'neutral', false, 'Appear everywhere as a public symbol of defiance against S Corp.', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.entity_beat_appearances VALUES (3281, 2550, 736, 'unknown', true, 'Identifies Todd as the ''true weapon'' and reflects on the preparatory work done by its puppets.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3282, 157, 736, 'ally', false, 'Is identified as the key to the final plan, possessing a hidden potential.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3283, 2567, 736, 'neutral', false, 'The specific quality within Todd that I AM has identified as the catalyst for rebellion.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3284, 159, 736, 'enemy', false, 'Referred to as ''the beast'' and ''digital overlords'', the ultimate target of the plan.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3285, 2568, 736, 'ally', false, 'Mentioned as having successfully weakened S Corp in the lead-up to this moment.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3286, 2550, 737, 'unknown', true, 'Whispers urgently into Todd''s mind, giving him his mission to attack S Corp on April 21st.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3287, 157, 737, 'ally', false, 'Receives the divine or otherworldly command to unleash chaos.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3288, 159, 737, 'mini-boss', false, 'Identified as the target, with a specific moment of vulnerability during its public unveiling.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3289, 2569, 737, 'neutral', false, 'The specific action (''chaos'') Todd is commanded to unleash.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3290, 157, 738, 'ally', true, 'Reacts to the voice, his initial fear transforming into resolve as he demands the speaker''s identity.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3291, 2550, 738, 'unknown', false, 'Its mysterious voice acts as the catalyst for Todd''s emotional shift and confrontation.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3292, 2550, 739, 'unknown', true, 'Reveals its identity as ''I AM'', claims responsibility for freeing Todd and Stacey, and demands rebellion as payment.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3293, 157, 739, 'ally', false, 'Receives the revelation about the voice''s identity and learns the price of his freedom.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3294, 195, 739, 'neutral', false, 'Is mentioned to establish the history and the debt that I AM is now calling due.', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_beat_appearances VALUES (3295, 157, 740, 'ally', true, 'Rises with fervor to lead his followers against S Corp.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3296, 2573, 740, 'ally', false, 'Surge against the towering walls of S Corp.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3297, 2550, 740, 'ally', false, 'Provides whispered truths and celestial guidance to fuel the rebellion, while its agents weaken the target.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3298, 2297, 740, 'enemy', false, 'Stands as the target of the assault, its defenses weakened.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3299, 2576, 740, 'neutral', false, 'Acts as the catalyst for Todd''s and his followers'' actions.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3300, 2577, 740, 'neutral', false, 'Serves as Todd''s internal motivation.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3301, 1201, 741, 'mini-boss', true, 'Lets out its final sputtering breath as its code dissolves into nothingness, its power stripped away.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3302, 2550, 741, 'ally', false, 'Experiences quiet satisfaction at the fulfillment of its task to destroy the Infinitron.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3303, 157, 742, 'ally', true, 'Acts as the Pied Piper, leading his followers into battle against S Corp.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3304, 2573, 742, 'ally', false, 'Descend upon S Corp''s headquarters like an army, firing on it.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3305, 2297, 742, 'enemy', false, 'Is descended upon and attacked by the rebellious army.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3306, 2550, 742, 'ally', false, 'Continues to fuel the rebellion with whispers from the shadows.', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_beat_appearances VALUES (3307, 292, 743, 'ally', false, 'Awakens into a state of terror, unable to distinguish between dream and reality.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3308, 213, 743, 'enemy', true, 'Manifests as a suffocating darkness that has dissolved the line between waking and sleeping.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3309, 292, 744, 'ally', true, 'Acknowledges that his technology is stolen from the dream realm and that he is being called to account.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3310, 295, 744, 'neutral', false, 'Identified as the source of all S Corp technology, wrested from his dreams.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3311, 2297, 744, 'neutral', false, 'Mentioned as the technological empire built upon the stolen dream-tech.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3312, 804, 744, 'enemy', false, 'Identified as the origin of the stolen technology and the source of the summons.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3313, 213, 745, 'enemy', true, 'Described as following a pattern of shifting landscapes filled with dread.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3314, 2585, 745, 'enemy', false, 'Appears as a recurring, elusive pursuer within the dreams.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3315, 2586, 745, 'neutral', false, 'Manifests as an insistent call that grows louder with each nightmare.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3316, 292, 746, 'ally', false, 'Realizes the dreams are corrupting his waking life and achievements.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3317, 213, 746, 'enemy', true, 'Actively bleed into the protagonist''s waking world, breaking down boundaries.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3318, 804, 746, 'enemy', false, 'Mentioned as the source of the stolen technology for which he must now account.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3319, 292, 747, 'ally', false, 'Experiences his identity unraveling and dissolving into formless awareness.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3320, 2590, 747, 'neutral', false, 'Appears as a grotesque, pulsating version of his real home.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3321, 295, 747, 'neutral', true, 'Transforms into a writhing mass of tentacles and eyes that devours reality.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3322, 982, 747, 'enemy', false, 'Consumes the protagonist, seeping into his being and splintering his thoughts.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3323, 2587, 748, 'mini-boss', true, 'Rises from the void as an impossible, god-like structure.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3324, 2588, 748, 'enemy', false, 'Emerge from the monolith to perform a ritualistic slaughter.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3325, 2589, 748, 'enemy', false, 'Are systematically slaughtered by the Shadow Entities.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3326, 292, 749, 'ally', false, 'Understands the true nature of the monolith and feels its pull consuming him.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3327, 2587, 749, 'mini-boss', true, 'Is realized to be a wound in reality and a nexus for horrors, its gravity pulling on the protagonist''s soul.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3328, 292, 750, 'ally', true, 'Understands upon waking that his actions have sealed his damnation and are drawing the nightmare world closer.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3329, 2587, 750, 'mini-boss', false, 'Is understood to be the consequence being drawn closer by S Corp''s advancements.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3330, 2297, 750, 'neutral', false, 'Its advancements are seen as transgressions that build a bridge to the abyss.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3331, 2591, 750, 'neutral', false, 'Identified as a beacon that is pulling the monolith and its horrors into reality.', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_beat_appearances VALUES (3332, 2595, 751, 'ally', true, 'Suffers from nocturnal thrashing and ramblings, and desperately tries various failed medications for relief.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3333, 2596, 751, 'ally', false, 'Are tormented by the protagonist''s condition, growing increasingly concerned.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3334, 253, 751, 'enemy', true, 'Manifest as the protagonist''s tortured sleep, causing distress to his entire household.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3335, 2597, 751, 'neutral', false, 'Represent the protagonist''s failed efforts to find a conventional solution to his torment.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3336, 2595, 752, 'ally', true, 'Meets with Dr. On and struggles to explain that his dreams feel more real than reality.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3337, 2599, 752, 'neutral', true, 'Greets the protagonist with a practiced smile and attributes his vivid dreams to significant stress and exhaustion.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3338, 253, 752, 'enemy', false, 'Are described by the protagonist as overwhelming and not normal.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3339, 2595, 753, 'ally', false, 'Insists his dreams are connected to his technology, growing more desperate.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3340, 2599, 753, 'neutral', true, 'Dismisses the protagonist''s theories about his technology, offering conventional remedies like relaxation and a vacation.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3341, 456, 753, 'neutral', false, 'Cited by Dr. On as a marvel of engineering, but just a tool.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3342, 1201, 753, 'neutral', false, 'Mentioned as the interface the protagonist claims is affecting his dreams.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3343, 2602, 753, 'enemy', false, 'Begin to form as Dr. On calmly and firmly dismisses the protagonist''s fears as natural responses to stress.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3344, 2595, 754, 'ally', true, 'Leaves the office feeling gaslit and angry, convinced Dr. On is wrong and that his power comes from a darker place.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3345, 2599, 754, 'neutral', false, 'Her influence is felt through her hollow reassurances, which the protagonist rejects.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3346, 2602, 754, 'enemy', true, 'Echo in the protagonist''s mind as a cruel joke, cementing his feeling of isolation.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3347, 2603, 754, 'unknown', false, 'The protagonist reflects on this as the true origin of his abilities, something Dr. On could never understand.', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.entity_beat_appearances VALUES (3348, 292, 755, 'ally', false, 'Is trapped in the void and confronted by ''I AM''.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3349, 2550, 755, 'mini-boss', true, 'Mocks and attacks the protagonist, accusing him of stealing its power and souls.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3350, 2608, 756, 'ally', true, 'Materializes and radiates a power that forces ''I AM'' to retreat.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3351, 2609, 756, 'ally', true, 'Appears alongside Lady I, her intense presence helping to drive back the entity.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3352, 2550, 756, 'mini-boss', false, 'Recoils and retreats from the two ladies.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3353, 292, 756, 'ally', false, 'Is saved from the entity''s attack and witnesses the arrival of the two ladies.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3354, 2608, 757, 'ally', true, 'Explains that the protagonist has torn the veil and incurred a debt.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3355, 2609, 757, 'ally', true, 'Adds that understanding was not required for the act and that he is not yet beyond hope.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3356, 292, 757, 'ally', false, 'Listens to their explanation, feeling guilt and confusion.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3357, 2610, 757, 'neutral', false, 'Mentioned as having been torn by the protagonist.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3358, 2611, 757, 'neutral', false, 'Mentioned as having been broken by the protagonist.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3359, 2608, 758, 'ally', true, 'Touches the protagonist''s soul, offering understanding instead of salvation.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3360, 2609, 758, 'ally', true, 'Touches the protagonist''s soul and warns that the cost will follow him regardless of his choice.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3361, 292, 758, 'ally', false, 'Experiences a moment of relief and understanding, but is left with the weight of a future cost.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3362, 2612, 758, 'neutral', false, 'Mentioned as the unavoidable consequence of the protagonist''s actions.', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_beat_appearances VALUES (3363, 2615, 759, 'ally', true, 'Sits alone in his office, consumed by troubling reports and his growing sense of isolation from his family.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3364, 2620, 759, 'neutral', true, 'Provide the evidence of I AM''s infiltration, fueling the protagonist''s obsession.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3365, 2550, 759, 'enemy', false, 'Its presence is felt through the reports, described as a phantom infiltrating corporate systems and employee dreams.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3366, 2619, 759, 'ally', false, 'Sits silently on the couch, a physical embodiment of the emotional distance in the family.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3367, 2618, 759, 'ally', false, 'His muffled laughter from another room highlights the protagonist''s feeling of detachment.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3368, 2622, 759, 'neutral', false, 'Its scent adds to the oppressive and contemplative atmosphere, pressing the protagonist to change.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3369, 2617, 760, 'mini-boss', true, 'Arrives and challenges the protagonist''s fixation on I AM, suggesting it''s a stress-induced delusion and attempts to redirect his focus.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3370, 2615, 760, 'ally', true, 'Defends the validity of the threat from I AM while also admitting his failings as a family man.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3371, 2550, 760, 'enemy', false, 'Serves as the central topic of conflict, being dismissed by Dr. On as a ''common phrase'' the protagonist has latched onto.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3372, 2618, 761, 'ally', true, 'Interrupts the tense conversation with a cheerful invitation to watch a movie, breaking the tension.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3373, 2615, 761, 'ally', false, 'Accepts the invitation, making a conscious choice to be present for his family.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3374, 2617, 761, 'mini-boss', false, 'Observes the family interaction and delivers a parting, ambiguous warning about commitment and change before leaving.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3375, 2619, 761, 'ally', false, 'Joins in the family banter, showing a shift from her earlier silent state.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3376, 1201, 761, 'neutral', false, 'Mentioned as the tool the son used to access the movie, showcasing his technical skills.', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.entity_beat_appearances VALUES (3377, 755, 762, 'ally', true, 'Reflects on his life''s transition from the chaos of S Corp to a quieter family rhythm at home.', '2026-02-27 20:00:15.326717-05');
INSERT INTO public.entity_beat_appearances VALUES (3378, 2297, 762, 'neutral', false, 'Represents the ''frenetic chaos'' that is now fading into the background of the narrator''s life.', '2026-02-27 20:00:15.326717-05');
INSERT INTO public.entity_beat_appearances VALUES (3379, 2631, 762, 'neutral', false, 'Introduced as the new adventure on the horizon, symbolizing the shift towards family and ordinary experiences.', '2026-02-27 20:00:15.326717-05');
INSERT INTO public.entity_beat_appearances VALUES (3380, 2591, 762, 'neutral', false, 'Mentioned as a work project the narrator is actively trying not to think about, reinforcing his commitment to the family trip.', '2026-02-27 20:00:15.326717-05');
