INSERT INTO public.entity_beat_appearances VALUES (3607, 755, 808, 'ally', true, 'Discovers online discussions about two contradictory designs for the Time Reversal card, linking it to the Mandela Effect.', '2026-02-27 20:12:57.002851-05');
INSERT INTO public.entity_beat_appearances VALUES (3608, 2775, 808, 'neutral', false, 'Becomes the subject of an online conspiracy, with evidence of two co-existing but officially singular designs.', '2026-02-27 20:12:57.002851-05');
