INSERT INTO public.entity_beat_appearances VALUES (3618, 2749, 811, 'ally', true, 'Conjures a vivid, visceral vision of a battlefield and narrates the story of the Knight Templar to illustrate a point about time and dreams.', '2026-02-27 20:13:53.489482-05');
