INSERT INTO public.entity_beat_appearances VALUES (3796, 2870, 854, 'ally', true, 'Shares the overwhelming complexities and ethical dilemmas of his work regarding S Corp''s space colonies, expressing doubt and fear.', '2026-02-27 20:24:08.058684-05');
INSERT INTO public.entity_beat_appearances VALUES (3797, 2908, 854, 'ally', false, 'Listens intently, offers reassurance, and reminds him of the collective strength of his team, helping to restore his clarity.', '2026-02-27 20:24:08.058684-05');
INSERT INTO public.entity_beat_appearances VALUES (3798, 2914, 854, 'neutral', false, 'The subject of Dr. S''s anxieties and the source of the immense pressure he feels.', '2026-02-27 20:24:08.058684-05');
INSERT INTO public.entity_beat_appearances VALUES (3799, 2915, 854, 'ally', false, 'Invoked by his wife as a reminder that he is not shouldering the burden alone.', '2026-02-27 20:24:08.058684-05');
INSERT INTO public.entity_beat_appearances VALUES (3800, 2909, 855, 'ally', true, 'Emerges from his room and excitedly recounts his victory in a Roblox game, which he achieved through teamwork with another player.', '2026-02-27 20:24:08.058684-05');
INSERT INTO public.entity_beat_appearances VALUES (3801, 2870, 855, 'ally', false, 'Recognizes the parallel between his son''s gaming success and his own professional challenges, affirming the importance of collaboration.', '2026-02-27 20:24:08.058684-05');
INSERT INTO public.entity_beat_appearances VALUES (3802, 2908, 855, 'ally', false, 'Exchanges a knowing smile with her husband and adds that perseverance is also key.', '2026-02-27 20:24:08.058684-05');
INSERT INTO public.entity_beat_appearances VALUES (3803, 2916, 855, 'neutral', false, 'Serves as the central topic of the son''s story and the catalyst for the scene''s thematic conclusion.', '2026-02-27 20:24:08.058684-05');
