INSERT INTO public.entity_beat_appearances VALUES (3807, 2920, 857, 'ally', true, 'Mischievously tells Aditi about Mrs. Kapoor''s sleepwalking, successfully capturing her interest.', '2026-02-27 20:25:10.009804-05');
INSERT INTO public.entity_beat_appearances VALUES (3808, 2919, 857, 'ally', false, 'Her attention is diverted from her chores and exhaustion to the intriguing local mystery.', '2026-02-27 20:25:10.009804-05');
