INSERT INTO public.entity_beat_appearances VALUES (3840, 2939, 866, 'neutral', false, 'Is the subject of the friends'' intense discussion and theorizing.', '2026-02-27 20:26:37.326805-05');
INSERT INTO public.entity_beat_appearances VALUES (3841, 2946, 866, 'mini-boss', false, 'The deliberate, synchronized nature of this group is identified by Raj as the key anomaly, elevating the mystery.', '2026-02-27 20:26:37.326805-05');
INSERT INTO public.entity_beat_appearances VALUES (3842, 2943, 867, 'neutral', false, 'Rings, interrupting the friends'' conversation.', '2026-02-27 20:26:37.326805-05');
INSERT INTO public.entity_beat_appearances VALUES (3843, 2944, 867, 'unknown', true, 'Lingers in the minds of Aditi and her friends, while simultaneously beginning to gain traction online.', '2026-02-27 20:26:37.326805-05');
