INSERT INTO public.entity_beat_appearances VALUES (3848, 2941, 868, 'ally', false, 'Acts as the skeptic, suggesting it''s just a normal mass sleepwalking event.', '2026-02-27 20:27:23.550079-05');
INSERT INTO public.entity_beat_appearances VALUES (3849, 2953, 868, 'ally', false, 'Points out the synchronized pointing, arguing it''s coordinated and not random.', '2026-02-27 20:27:23.550079-05');
INSERT INTO public.entity_beat_appearances VALUES (3850, 2945, 869, 'ally', true, 'Transforms into a team of amateur detectives, researching mass sleepwalking events.', '2026-02-27 20:27:23.550079-05');
