INSERT INTO public.entity_beat_appearances VALUES (3854, 2919, 870, 'ally', false, 'Observes that other sleepwalking videos are being dismissed online by the public.', '2026-02-27 20:27:23.550079-05');
INSERT INTO public.entity_beat_appearances VALUES (3855, 2956, 870, 'enemy', true, 'Is theorized by Neha as the reason people are unable or unwilling to connect the dots about the events.', '2026-02-27 20:27:23.550079-05');
