INSERT INTO public.entity_beat_appearances VALUES (3861, 2959, 872, 'ally', true, 'Reflects on the massive scale of the Space Elevator project and consciously decides to prioritize this ''waking world'' engineering challenge over his ''dreamscape'' explorations.', '2026-02-27 20:28:23.734349-05');
INSERT INTO public.entity_beat_appearances VALUES (3862, 2874, 872, 'neutral', false, 'Serves as the object of the protagonist''s focus and the source of the scene''s central conflict.', '2026-02-27 20:28:23.734349-05');
INSERT INTO public.entity_beat_appearances VALUES (3863, 2474, 873, 'ally', true, 'Delivers a stark update on material failures, expressing a mix of deep frustration and defiant determination to overcome the obstacles.', '2026-02-27 20:28:23.734349-05');
