INSERT INTO public.entity_beat_appearances VALUES (3871, 2965, 875, 'enemy', true, 'Manifests through Morgan''s frustration as she questions why the materials are failing despite the math being correct, comparing it to a ''worm'' eating them from inside.', '2026-02-27 20:28:23.734349-05');
