INSERT INTO public.entity_beat_appearances VALUES (3876, 2657, 876, 'ally', true, 'Recounts past experimental failures involving wet cardboard and beer to illustrate a point about unconventional thinking.', '2026-02-27 20:29:16.283956-05');
