INSERT INTO public.entity_beat_appearances VALUES (3988, 2550, 906, 'ally', false, 'Responds by revealing the existence and function of S Corp''s space elevators and the ERB teleportation network.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3989, 3072, 906, 'neutral', false, 'Is revealed as the technology behind recent global logistical revolutions.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3990, 3075, 906, 'neutral', false, 'Are described as the arteries of a new interstellar society.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3991, 2550, 907, 'ally', true, 'Reveals the existence of New Tokyo on Mars, a city of half a billion people, and explains the disappearance of homeless populations from Earth.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3992, 3073, 907, 'neutral', false, 'Is introduced as a shocking reality, proving that Mars has already been colonized on a massive scale.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3993, 3070, 907, 'neutral', false, 'Erupt in astonished exclamations, struggling to comprehend the scale of S Corp''s secret operations.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3994, 3076, 907, 'neutral', false, 'Are mentioned as the primary inhabitants of the new off-world colonies.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3995, 2550, 908, 'ally', true, 'Frames the interstellar expansion not as a luxury but as a necessity for humanity''s survival and growth.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3996, 3074, 908, 'neutral', false, 'Is presented as the blueprint for humanity''s future, a solution to Earth''s finite resources.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3997, 3070, 908, 'neutral', false, 'Are left in a palpable, charged silence, processing the enormous implications of the presentation.', '2026-02-27 20:37:57.229941-05');
INSERT INTO public.entity_beat_appearances VALUES (3998, 3079, 909, 'neutral', true, 'Challenges the proposed ''interstellar society'' on the grounds of potential elitism and demands to know how all nations will benefit.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (3999, 2550, 909, 'ally', false, 'Responds by outlining the interstellar consortium''s model of equal representation and profit reinvestment, gesturing to schematics of the elevator network.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4000, 3074, 909, 'neutral', false, NULL, '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4001, 3086, 909, 'neutral', false, NULL, '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4002, 3080, 910, 'neutral', true, 'Raises cautious concerns about the project''s environmental impact on Earth.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4003, 2550, 910, 'ally', false, 'Counters by citing a 36% improvement in air quality and detailing the project''s sustainable, carbon-neutral construction methods.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4004, 3081, 911, 'neutral', true, 'Skeptically questions the claim of perfection and asks about protocols for when things inevitably go wrong.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4005, 2550, 911, 'ally', false, 'Acknowledges the possibility of failure but details the extensive redundancies, fail-safes, and clarifies the distinct roles of the Space Elevators and the ERB Network.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4006, 3024, 911, 'neutral', false, NULL, '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4007, 3088, 911, 'neutral', false, NULL, '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4008, 3082, 912, 'neutral', true, 'Questions how the chaotic public reaction to the announcement will be managed.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4009, 2550, 912, 'ally', false, 'Outlines a phased rollout, explaining how the ERB Network and elevator stations are integrated into existing airports to normalize space travel, with S Corp leading the effort.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4012, 3071, 913, 'neutral', true, 'Cuts through the noise to ask for the immediate plan of action.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4013, 2550, 913, 'ally', false, 'Announces a three-month timeline for the public unveiling and calls for unity in preparation.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4014, 3090, 913, 'neutral', false, NULL, '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (4015, 2550, 914, 'ally', true, 'Gazes at Earth and reflects on its hidden fractures while delegates begin their discussions.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4016, 2253, 914, 'neutral', false, 'Serves as a visual symbol of serene unity that contrasts with the political reality.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4017, 3092, 914, 'neutral', false, 'Break into smaller groups, their murmured voices and veiled glances revealing skepticism and hidden agendas.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4018, 3094, 915, 'mini-boss', true, 'Confronts the narrator, questioning the acquisition of land for the elevators and its impact on Chinese sovereignty.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4019, 2550, 915, 'ally', false, 'Is approached and challenged, becoming the focus of the room''s attention.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4020, 3024, 915, 'neutral', false, 'Are the subject of the confrontation, represented by a schematic.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4021, 2550, 916, 'ally', true, 'Responds calmly, presenting legal agreements and framing the elevators as a gateway for all humanity, not just S Corp.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4022, 3096, 916, 'neutral', false, 'Are presented as evidence of transparency and lawful conduct.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4023, 3098, 916, 'ally', false, 'Places the contract before the Chinese representative.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4024, 3094, 916, 'mini-boss', false, 'Receives and begins to review the presented document.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4025, 3094, 917, 'mini-boss', true, 'Counters that the land represents leverage, expressing continued concern over his nation''s interests.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4026, 2550, 917, 'ally', false, 'Refutes the concern by drawing a parallel to the control nations have over international aircraft at their airports.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4027, 2550, 918, 'ally', true, 'Explains S Corp''s funding strategy and the immense value of the elevators to position shared governance as the only logical path forward.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4028, 2297, 918, 'neutral', false, 'Is named as the sole financial backer of the project.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4029, 3024, 918, 'neutral', false, 'Their immense value ($150 trillion each) is stated to justify the need for shared governance.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4030, 3100, 918, 'neutral', false, 'Is presented as the core of the proposal, making cooperation a necessity.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4031, 3094, 919, 'mini-boss', true, 'After a tense silence, accepts the proposal by extending a hand for a handshake.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4032, 2550, 919, 'ally', true, 'Accepts the handshake, sealing the agreement while privately harboring doubts about its longevity.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4033, 3082, 919, 'neutral', false, 'Voices grudging admiration for the narrator''s planning, signaling a shift in the room''s mood.', '2026-02-27 20:39:22.750481-05');
INSERT INTO public.entity_beat_appearances VALUES (4034, 3102, 920, 'ally', false, 'Is drawn to the delegates and prepares to engage them.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4035, 3103, 920, 'neutral', true, 'Expresses awe at the view but immediately questions the cost of such progress.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4036, 3104, 920, 'neutral', true, 'Shares the awe and focuses on the economic implications for trade.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4037, 3105, 920, 'neutral', false, 'Serves as the awe-inspiring backdrop that initiates the conversation.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4038, 3102, 921, 'ally', true, 'Describes the transformative impacts on commerce and healthcare, citing the statistic of 300,000 lives saved.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4039, 3107, 921, 'neutral', false, 'Used as concrete evidence of the network''s positive, real-world impact.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4040, 3103, 922, 'neutral', true, 'Challenges the claims and asks for evidence, shifting from awe to skepticism.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4041, 3102, 922, 'ally', false, 'Responds to the skepticism by projecting a massive reduction in global shipping emissions.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4042, 3108, 922, 'neutral', false, 'Serves as the key data point to demonstrate the network''s alignment with sustainability goals.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4043, 3104, 923, 'neutral', true, 'Asks the critical question about the ''catch'' or downside to the proposal.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4044, 3102, 923, 'ally', false, 'Admits the ''catch'' is the need for international trust and collaboration, framing it as a shared responsibility.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4045, 159, 923, 'neutral', false, 'Positioned as the builder of the infrastructure, but reliant on nations to ensure its success.', '2026-02-27 20:40:15.292332-05');
INSERT INTO public.entity_beat_appearances VALUES (4715, 3628, 1085, 'ally', true, 'Travels slowly across the solar system for months, powered by prayer and devotion.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4716, 3630, 1085, 'neutral', false, 'Is repeatedly charged up through devotions to allow the fleet to make leaps across space.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4717, 3637, 1085, 'ally', false, 'Serves as the fuel source for the Janus Gate, requiring constant renewal through prayer.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4718, 157, 1086, 'ally', true, 'Requests final confirmation for the attack on Pluto and prays for his soul.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4719, 3247, 1086, 'ally', false, 'Replies to Todd, granting his blessing for the attack and the execution of heretics.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4720, 3632, 1086, 'enemy', false, 'Are identified as the target for execution, sanctioned by the Pope.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4721, 3638, 1086, 'ally', false, 'Is invoked for blessings and as the justification for the holy mission.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4722, 3628, 1087, 'ally', true, 'Plunges through the rift created by the Janus Gate towards Pluto.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4046, 2550, 924, 'ally', true, 'Announces S Corp''s proposal to donate its gold reserves to erase the U.S. national debt.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4047, 3111, 924, 'neutral', false, 'Arrives and listens to the initial, world-altering proposal.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4048, 3112, 924, 'neutral', false, 'Presented as the tool for eliminating the debt.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4049, 3113, 924, 'enemy', false, 'Identified as the target to be eliminated by S Corp''s investment.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4050, 3114, 925, 'neutral', true, 'Expresses disbelief and questions the source of S Corp''s vast gold reserves.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4051, 2550, 925, 'ally', false, 'Explains that the gold is sourced from interstellar asteroid mining and processed with advanced technology.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4056, 3116, 927, 'neutral', true, 'Raises a question about the long-term sustainability of the proposed programs.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4723, 157, 1087, 'ally', false, 'Activates the Janus Gate and stands aboard the flagship as it travels through the void.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4724, 3630, 1087, 'neutral', false, 'Is activated, tearing open a rift in reality.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4725, 3634, 1087, 'neutral', false, 'Opens to reveal the path to Pluto, allowing the fleet to pass through.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4726, 3633, 1087, 'mini-boss', false, 'Looms ahead on Pluto''s surface as the fleet emerges from the rift, presenting itself as the primary target.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4727, 3635, 1087, 'ally', false, 'Leads the charge into the rift, shuddering as it travels.', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.entity_beat_appearances VALUES (4728, 3628, 1088, 'ally', true, 'Conducts a surgical strike with Holy Plasma Cannons.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4729, 157, 1088, 'ally', false, 'Barks steady commands from the bridge, directing the attack.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4730, 3643, 1088, 'ally', false, 'Unleash torrents of energy against the station''s shields.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4053, 2550, 926, 'ally', true, 'Outlines the specific social welfare initiatives that the newfound financial freedom would fund.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4054, 3117, 926, 'neutral', false, 'Are detailed as the tangible benefits of the proposal, including universal healthcare and free education.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4055, 3114, 926, 'neutral', false, 'Listens to the proposed initiatives, his voice softening with the realization of their potential impact.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4057, 2550, 927, 'ally', false, 'Responds by explaining the plan for self-sufficiency through public-private partnerships and economic reinvestment.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4058, 3114, 928, 'neutral', true, 'States the need for time to deliberate on the paradigm-shifting proposal.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4059, 2550, 928, 'ally', false, 'Agrees to provide time and support, while subtly hinting at using lobbyists to provide financial incentives.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4060, 3118, 928, 'neutral', false, 'Mentioned as a potential tool to ensure the proposal''s acceptance.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (4076, 2550, 929, 'ally', false, 'Greets the representatives and initiates the discussion.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4077, 3121, 929, 'neutral', false, NULL, '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4078, 3122, 929, 'neutral', false, NULL, '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4079, 3125, 929, 'neutral', true, 'Hangs heavily over the room, setting the tone for the meeting.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4081, 3121, 930, 'neutral', true, 'Raises concerns that the Absent Nations will use S Corp funds for military escalation.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4082, 2550, 930, 'ally', false, 'Responds by outlining transparency and accountability mechanisms.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4083, 3123, 930, 'enemy', false, 'Are the subject of the delegate''s concerns.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4084, 3122, 931, 'neutral', false, 'Questions how the terms will be enforced.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4085, 2550, 931, 'ally', true, 'Details the punitive measures S Corp can enact, such as suspending network access.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4086, 3126, 931, 'neutral', false, 'Are introduced as the primary enforcement tool.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4087, 3121, 932, 'neutral', false, 'Poses a scenario about unresolved conflicts and the movement of weapons.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4088, 2550, 932, 'ally', true, 'Describes collaboration with peacekeeping organizations and the use of advanced scanning technology to prevent illicit shipments.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4089, 3127, 932, 'ally', false, 'Is presented as a key technological solution to the security problem.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4090, 3122, 933, 'neutral', false, 'Expresses doubt about cooperation between enemy nations.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4091, 2550, 933, 'ally', true, 'Uses the current meeting as a model for cooperation and emphasizes the shared stakes in accessing space.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4092, 3121, 934, 'neutral', false, 'Voices lingering skepticism about impartial enforcement.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4093, 2550, 934, 'ally', true, 'Asserts S Corp''s neutrality and unique status as a planetary-incorporated entity to guarantee impartiality.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4094, 2297, 934, 'ally', false, 'Is invoked as the neutral, powerful entity that can enforce the agreements.', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_beat_appearances VALUES (4095, 3131, 935, 'neutral', true, 'Leans forward and proposes a regional working group with Israel to cooperate on space technologies.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4096, 3132, 935, 'neutral', false, 'Stands near the Iranian delegate, listening to the proposal.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4097, 2550, 935, 'ally', false, 'Observes the interaction with surprise, noting the softened distance between the two delegates.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4098, 3133, 935, 'neutral', false, 'Is proposed as a bold suggestion for cooperation.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4099, 3132, 936, 'neutral', true, 'Expresses cautious willingness to discuss shared goals but emphasizes that trust must be built over time.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4100, 2550, 936, 'ally', false, 'Steps in to encourage the dialogue, framing the initiative as a way to build trust incrementally through action.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4101, 3135, 936, 'neutral', false, 'Mentioned as a potential mutual interest for the working group.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4102, 2550, 937, 'ally', true, 'Commits S Corp''s support with technology and resources, framing the collaboration as a test of unified potential.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4103, 3131, 937, 'neutral', false, 'Nods and agrees to a limited-scope trial collaboration to build confidence.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4104, 2297, 937, 'ally', false, 'Is pledged as a source of support for the initiative.', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_beat_appearances VALUES (4105, 39, 938, 'neutral', true, 'Transition from an obscure curiosity on internet forums to a ferocious global phenomenon.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4106, 3144, 938, 'neutral', false, 'Mentioned as the origin point of the whispers about the Pointers.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4107, 3142, 938, 'neutral', false, 'Initially dismissed the Pointers as a triviality before the story exploded.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4108, 3149, 939, 'neutral', true, 'Materialize nightly across the globe, creating a spectacle of fear and awe.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4109, 518, 939, 'neutral', false, 'Serve as the stage for the Sleepwalkers'' appearances.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4110, 326, 939, 'neutral', false, 'Are left paralyzed with fear and awe by the spectacle, their sense of reality shattered.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4111, 3151, 940, 'neutral', true, 'Create viral videos by recklessly dancing around The Pointers.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4112, 39, 940, 'neutral', false, 'Become the silent centerpiece for viral flash mobs.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4113, 84, 940, 'neutral', false, 'Acts as the realm where the phenomenon is amplified.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4114, 3153, 940, 'neutral', false, 'Is the specific explosive platform for the viral videos.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4115, 3139, 940, 'neutral', false, 'Are created by the teenagers, becoming overnight sensations.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4116, 859, 941, 'mini-boss', true, 'Proliferate on fringe media, blaming sinister plots for the phenomenon and driving society toward paranoia.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4117, 3137, 941, 'enemy', false, 'Serve as the platform for broadcasting the wild theories.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4118, 3148, 941, 'enemy', false, 'Are the target audience and proponents of the conspiracy theories.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4119, 3145, 941, 'enemy', false, 'Exploit the hysteria by selling merchandise.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4120, 3147, 941, 'neutral', false, 'Are sold to those who subscribe to the nefarious explanations.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4121, 166, 941, 'enemy', false, 'Descends upon society as a result of the misinformation.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4122, 3143, 942, 'neutral', true, 'Join the flash mobs, caught up in the excitement.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4123, 3139, 942, 'neutral', false, 'Evolve into a curious viral meme through mass participation.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4125, 3141, 942, 'neutral', false, 'Observes the transformation of the phenomenon into a viral meme.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4126, 39, 943, 'unknown', true, 'Break their stoic silence by erupting with a cacophonous screech, broadcasting a message to the world.', '2026-02-27 20:44:32.76849-05');
INSERT INTO public.entity_beat_appearances VALUES (4127, 3158, 943, 'neutral', true, 'Rumbles through the air, a piercing sound that seems to shatter the night and carries a specific message.', '2026-02-27 20:44:32.76849-05');
INSERT INTO public.entity_beat_appearances VALUES (4128, 3160, 943, 'unknown', false, 'The content of the broadcast, ''ELYSIUM'' and ''ELYSIUM RISES'', echoes in the wake of the screech.', '2026-02-27 20:44:32.76849-05');
INSERT INTO public.entity_beat_appearances VALUES (4124, 85, 942, 'neutral', false, 'Represents the final cultural form of the phenomenon in this scene, capturing global attention.', '2026-02-27 20:43:29.166633-05');
INSERT INTO public.entity_beat_appearances VALUES (4129, 3161, 943, 'neutral', false, 'Reacts with shockwaves of disbelief and concern that ripple through communities and media outlets.', '2026-02-27 20:44:32.76849-05');
INSERT INTO public.entity_beat_appearances VALUES (4130, 3159, 944, 'unknown', true, 'Suddenly transition from silent somnambulists to active speakers, repeating the cryptic messages.', '2026-02-27 20:44:32.76849-05');
INSERT INTO public.entity_beat_appearances VALUES (4131, 3161, 944, 'neutral', true, 'Is shaken from its metaphorical slumber, sparking a frenzy of analysis and frantic conjecture about the messages'' meaning.', '2026-02-27 20:44:32.76849-05');
INSERT INTO public.entity_beat_appearances VALUES (4132, 3160, 944, 'unknown', false, 'Are amplified and spread by the Sleepers, deepening the mystery.', '2026-02-27 20:44:32.76849-05');
INSERT INTO public.entity_beat_appearances VALUES (4133, 3163, 945, 'enemy', true, 'Explodes with theories and speculation, creating a cacophony of confusion across the world.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4134, 39, 945, 'neutral', false, 'Remain unwavering and vigilant through the night, their arms outstretched to the stars, ignoring the global chaos.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4135, 326, 945, 'neutral', false, 'Struggles to make sense of the situation, with most of the population sleeping peacefully, unaware of the imminent revelation.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4136, 3024, 946, 'neutral', true, 'Are revealed at dawn, towering over the planet as a grand, world-changing structure.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4137, 326, 946, 'neutral', false, 'Reacts with a divided response, splitting between marveling at the sight and fearing it as an alien invasion.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4138, 3170, 946, 'enemy', false, 'Manifests as a powerful, negative reaction within a portion of the global population.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4139, 2253, 946, 'neutral', false, 'Is transformed into a ''new Earth'' by the sudden, visible presence of the elevators.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4140, 3024, 947, 'neutral', true, 'Stand as a contentious symbol, inspiring awe while also casting a foreboding shadow.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4141, 3169, 947, 'mini-boss', false, 'Is personified by the elevators, representing the dual nature of humanity''s greatest achievements and flaws.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4142, 326, 948, 'ally', true, 'Gazes upward in a moment of collective, profound realization that they are living witnesses to history.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4143, 3024, 948, 'neutral', false, 'Serve as the focal point of humanity''s gaze as they ascend towards Elysium.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4144, 824, 948, 'neutral', false, 'Is revealed as the destination, symbolizing humanity''s soaring ambitions.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4145, 3171, 948, 'neutral', false, 'Is actively being made, transforming all of humanity into participants.', '2026-02-27 20:45:09.254189-05');
INSERT INTO public.entity_beat_appearances VALUES (4146, 3174, 949, 'ally', true, 'Prepares for the broadcast, steadying his nerves while feeling a cocktail of anticipation and anxiety about addressing billions.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4147, 3180, 949, 'neutral', false, 'The imminent event that represents a pivotal moment for S Corp and all of humanity.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4148, 2352, 949, 'ally', false, 'Mentioned as part of a successful plan to prime the world for the announcement by shouting ''Elysium''.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4149, 3174, 950, 'ally', true, 'Begins his speech, his voice steady, framing April 21, 2025 as a profound turning point in human history.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4150, 3180, 950, 'neutral', false, 'Goes live, capturing The Orator''s expression and carrying his words across the solar system.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4151, 326, 950, 'neutral', false, 'Is addressed directly as the audience, their collective gaze imagined like the barrel of a gun.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4152, 3174, 951, 'ally', true, 'Continues his speech, explaining the deeper significance of the space elevators.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4153, 3024, 951, 'neutral', false, 'Are described as gateways to exploration and collaboration, bridging the divide between Earth and the cosmos.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4154, 3174, 952, 'ally', true, 'Shifts his focus to global cooperation, extending a call to action and framing the achievement as a triumph for all people.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4155, 326, 952, 'ally', false, 'Is positioned as the true victor and is invited to dream bigger and embrace the unknown.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4156, 824, 952, 'ally', false, 'Invoked as a unifying concept for humanity to rise towards.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4157, 3174, 953, 'ally', true, 'Experiences the overwhelming global response with his family, his voice thick with emotion.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4158, 3181, 953, 'ally', false, 'Erupts in a thunderous, deafening roar of applause that signifies worldwide celebration and acceptance.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4159, 3175, 953, 'ally', false, 'Stands with her husband, expressing her pride and affirming that he has given people something to believe in.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4160, 3176, 953, 'ally', false, 'Watches the cheering crowd with an infectious grin and wide-eyed awe.', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.entity_beat_appearances VALUES (4161, 157, 954, 'mini-boss', true, 'Positions himself in the crowd, gripping his concealed weapon, his mind burning with conviction to attack S Corp.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4162, 195, 954, 'enemy', false, 'Stands with Todd, expressing a mix of loyalty and unease.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4163, 3186, 954, 'neutral', false, 'Forms a divided and volatile backdrop, with factions of both supporters and detractors of S Corp.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4164, 2554, 954, 'enemy', false, 'Represented by Todd and Stacey, this faction seethes with anger among the crowd.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4165, 3188, 954, 'neutral', false, 'Is concealed in Todd''s jacket, a hidden threat.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4166, 3191, 954, 'neutral', false, 'Fuels Todd''s determination and conviction.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4167, 157, 955, 'mini-boss', true, 'Pulls his gun, fires it into the air, and shouts accusations against S Corp, inciting panic.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4168, 3188, 955, 'neutral', false, 'Is fired, shattering the quiet and triggering chaos.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4169, 3186, 955, 'neutral', false, 'Reacts with gasps and screams, surging in panic.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4170, 2550, 955, 'unknown', false, 'Is mentioned by Todd as a being that S Corp opposes.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4171, 3189, 956, 'ally', true, 'Activates instantly, encasing the attackers and neutralizing all their weapons and bombs non-lethally.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4172, 2554, 956, 'enemy', false, 'Are trapped within the shield, their planned attack completely thwarted.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4173, 3186, 956, 'neutral', false, 'Freezes in terror, which quickly turns to stunned astonishment at the display of technology.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4174, 3190, 957, 'neutral', true, 'Arrive and efficiently arrest the immobilized attackers, including Todd and Stacey.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4175, 3189, 957, 'ally', false, 'Dissolve as swiftly as they appeared once the threat is secured.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4176, 3186, 957, 'neutral', false, 'Begins to applaud, celebrating the successful and harmless defense by S Corp.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4177, 157, 957, 'mini-boss', false, 'Is handcuffed and forced into a transport, his rage turning to disbelief.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4178, 195, 957, 'enemy', false, 'Shouts defiantly at the crowd as she is arrested.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4179, 157, 958, 'mini-boss', true, 'Sits as a helpless captive in a police vehicle, realizing the utter futility of his cause against S Corp''s power.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4180, 3191, 958, 'neutral', false, 'Is completely crushed by the reality of S Corp''s technological superiority.', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_beat_appearances VALUES (4181, 3197, 959, 'ally', true, 'Reflects on her lifelong fascination with the stars and the incredible luck of her family winning a spot on the colonist journey.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4182, 159, 959, 'neutral', false, 'Mentioned as the creator of the technology that makes the journey possible.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4183, 3202, 959, 'neutral', false, 'Established as the context for the scene and the source of Yukiko''s excitement.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4184, 3197, 960, 'ally', true, 'Reassures her apprehensive brother, framing the unknown as something magical and wonderful to discover.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4185, 3198, 960, 'ally', false, 'Clings to his sister''s hand, expressing his mix of awe and fear by asking about aliens.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4186, 3204, 960, 'unknown', false, 'Introduced as a concept representing the fear and wonder of the unknown journey.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4187, 3203, 961, 'neutral', false, 'Crackles to life, announcing the imminent departure and prompting the next phase of the scene.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4188, 3199, 961, 'neutral', true, 'Engages Yukiko with kind words and sage advice about cherishing the journey with loved ones.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4189, 3197, 961, 'ally', false, 'Receives the passenger''s advice gratefully, reinforcing her feelings of love for her family.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4190, 2591, 962, 'neutral', true, 'Begins its ascent, physically starting the family''s journey into the unknown.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4191, 3197, 962, 'ally', false, 'Squeezes her brother''s hand, making a silent promise to face whatever comes together.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4192, 3198, 962, 'ally', false, 'Holds his sister''s hand, sharing the pivotal moment of departure.', '2026-02-27 20:48:32.244877-05');
INSERT INTO public.entity_beat_appearances VALUES (4193, 3206, 963, 'ally', true, 'Emerges from her cabin and approaches the panoramic windows, her face a tapestry of wonder as she overcomes her fear.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4194, 3197, 963, 'ally', false, 'Watches her mother, awe-struck by her transformation.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4195, 3211, 963, 'enemy', false, 'Is actively being confronted and overcome by Yukiko''s mother.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4196, 2253, 963, 'neutral', false, 'Serves as the catalyst for the mother''s change, receding into a glowing mosaic.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4197, 3212, 963, 'ally', false, 'Manifests in both Yukiko and her mother, replacing fear.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4198, 3197, 964, 'ally', true, 'Along with her mother, endures several days of travel towards their destination.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4199, 3206, 964, 'ally', true, 'Travels with her family, her fear now gone, and expresses her disbelief and awe at the experience.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4200, 824, 964, 'neutral', false, 'Acts as a transitional point in their journey, described as a celestial embrace.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4201, 3210, 964, 'neutral', false, 'Is established as the next major destination in their journey.', '2026-02-27 20:49:19.783008-05');
INSERT INTO public.entity_beat_appearances VALUES (4202, 3214, 965, 'ally', true, 'Arrives at the bustling Pluto Hub.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4203, 3215, 965, 'neutral', false, 'Serves as the active, populated setting for the family''s arrival.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4204, 3216, 965, 'neutral', false, 'Greets the family and illuminates their way.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4205, 3217, 965, 'neutral', false, 'Contribute to the lively, active atmosphere of the hub.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4206, 3197, 966, 'ally', true, 'Boards the mobile habitat, drawn to the viewing deck.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4207, 3218, 966, 'neutral', true, 'Is boarded and begins to power up, its interior glowing.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4208, 3222, 966, 'neutral', false, 'Mentioned as the star system of their final destination.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4209, 3197, 967, 'ally', true, 'Gazes at the ERB gateway, her reflection showing her wide-eyed excitement.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4210, 2107, 967, 'neutral', true, 'Shimmers and displays shifting patterns of light, offering a preview of the destination.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4211, 3220, 967, 'neutral', false, 'Is glimpsed through the gateway, representing the unknown future.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4212, 3221, 967, 'neutral', false, 'Manifests within Yukiko as she takes in the scene.', '2026-02-27 20:49:57.431997-05');
INSERT INTO public.entity_beat_appearances VALUES (4213, 3223, 968, 'neutral', true, 'Moves steadily through the ERB Gateway, carrying its passengers across a historic threshold.', '2026-02-27 20:50:41.821161-05');
INSERT INTO public.entity_beat_appearances VALUES (4214, 2107, 968, 'neutral', false, 'Serves as the cosmic corridor for the habitat, its walls displaying the universe.', '2026-02-27 20:50:41.821161-05');
INSERT INTO public.entity_beat_appearances VALUES (4215, 3225, 968, 'neutral', false, 'Are the passengers on board the habitat, collectively experiencing this unparalleled event.', '2026-02-27 20:50:41.821161-05');
INSERT INTO public.entity_beat_appearances VALUES (4216, 3226, 968, 'neutral', false, 'Adorns the walls of the gateway, creating a dazzling and wondrous environment for the travelers.', '2026-02-27 20:50:41.821161-05');
INSERT INTO public.entity_beat_appearances VALUES (4217, 3223, 969, 'neutral', false, 'Passes through the gateway and opens its doors to reveal the new world.', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_beat_appearances VALUES (4218, 2003, 969, 'neutral', true, 'Serves as the final portal for The Habitat''s journey.', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_beat_appearances VALUES (4219, 3222, 969, 'neutral', false, 'Provides the azure light that illuminates the alien landscape.', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_beat_appearances VALUES (4220, 3235, 969, 'neutral', false, 'Are revealed as a key feature of the vast, alien landscape.', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_beat_appearances VALUES (4221, 3233, 970, 'ally', true, 'Press against the viewing windows, reacting with wonder, disbelief, and soft murmurs to the sight of the new planet.', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_beat_appearances VALUES (4222, 3197, 970, 'ally', false, 'Stands at the forefront of the group, her heart pounding as she takes in the breathtaking view.', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_beat_appearances VALUES (4223, 3223, 970, 'neutral', false, 'Contains the pioneers and provides the viewing windows for them to see the new world.', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_beat_appearances VALUES (4224, 3236, 970, 'neutral', false, 'Fills the air inside the habitat as the pioneers witness the alien world.', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_beat_appearances VALUES (4225, 3197, 971, 'ally', true, 'Takes a bold first step onto the alien soil and reacts to the otherworldly air.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4226, 3241, 971, 'neutral', false, 'Serves as the bridge from her previous environment to the new world.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4227, 3245, 971, 'neutral', false, 'The surface she steps onto, marking her arrival.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4228, 3242, 971, 'neutral', false, 'She inhales it, finding it crisp, cool, and invigorating.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4229, 3214, 972, 'ally', true, 'Emerge onto the alien landscape behind Yukiko.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4230, 3206, 972, 'ally', false, 'Her tentative steps and wistful words betray her sense of awe.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4231, 3243, 972, 'neutral', false, 'Sways and flickers, creating a symphony of light that contributes to the family''s wonder.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4232, 3198, 973, 'ally', true, 'Races down the ramp and leaps high in the air, joyfully experiencing the planet''s lower gravity.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4233, 3197, 973, 'ally', false, 'Laughs at her brother''s energetic display and reflects on the significance of their arrival.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4234, 3244, 973, 'neutral', false, 'Enables Takashi''s high, joyful leap.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4235, 3241, 973, 'neutral', false, 'Used by Takashi to run down to the planet''s surface.', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_beat_appearances VALUES (4236, 3254, 974, 'neutral', true, 'Establishes the dreadful and secretive tone of the scene.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4237, 2297, 974, 'enemy', false, 'Its five years of corrupting humanity and steering them from God is established as the reason for the gathering.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4238, 235, 974, 'ally', false, 'Its failing influence and slipping power in the battle for souls against S Corp is described.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4239, 3247, 975, 'ally', true, 'Enters the chamber with grim resolve, feeling the weight of the moment.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4240, 3251, 975, 'ally', false, 'Are present around the table, cloaked in mystery and menace, setting a grim tone.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4241, 2550, 975, 'ally', false, 'Is revealed as a supernatural presence at the head of the table, having manifested in flames.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4242, 3247, 976, 'ally', true, 'Delivers a speech of righteous fury, condemning S Corp and declaring their meeting a holy war.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4243, 2297, 976, 'enemy', false, 'Is the target of the Pope''s condemnation for its lust for power and defilement of souls.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4244, 2550, 977, 'ally', true, 'Ends the debate by declaring that subtlety has failed and direct strikes are now necessary.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4245, 3252, 977, 'ally', false, 'Advocates for using technology as a weapon to fight S Corp.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4246, 157, 977, 'ally', false, 'Slams the table and demands immediate, violent action instead of more talk.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4247, 3247, 978, 'ally', true, 'Expresses his moral conflict about their methods but ultimately commits to the dangerous path to safeguard humanity.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4248, 3251, 978, 'ally', false, 'Reach a grim consensus and begin forging concrete plans and strategies.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4249, 3255, 978, 'neutral', false, 'Manifests through the Pope''s words, casting a shadow of unease over the gathering''s plans.', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_beat_appearances VALUES (4250, 3256, 979, 'ally', true, 'Stands sentinel, internally battling his duty against his fear for his family.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4251, 3251, 979, 'enemy', false, 'Are gathered in the chamber, their unseen decisions holding the guard''s family''s fate in the balance.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4252, 3258, 979, 'neutral', false, 'Serve as the motivation for the guard''s internal turmoil.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4253, 3261, 979, 'neutral', false, 'Manifests as the guard''s inner conflict.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4254, 3256, 980, 'ally', true, 'Seizes a moment of opportunity to send a desperate message to his family.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4255, 3264, 980, 'neutral', false, 'Is used to compose and send the message.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4256, 3260, 980, 'neutral', false, 'Is created and sent, representing a desperate act of hope.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4257, 3259, 981, 'mini-boss', true, 'Appears from the shadows and silently assassinates the guard to eliminate him as a witness.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4258, 3256, 981, 'ally', false, 'Is discovered and killed before he can receive a response, his last thoughts on his family.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4259, 3265, 981, 'enemy', false, 'Is the instrument of the guard''s silent death.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4260, 3260, 982, 'neutral', false, 'Is revealed to be lost in the cosmos, never to arrive at its destination.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4261, 3258, 982, 'neutral', false, 'Remain unknowingly waiting, unaware of the guard''s sacrifice.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4262, 3262, 982, 'neutral', true, 'Represents the finality of the guard''s death and the permanent, unexplainable loss his family will experience.', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.entity_beat_appearances VALUES (4263, 3268, 983, 'ally', true, 'Welcomes the recruits and sets the scene on Pluto.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4264, 3269, 983, 'ally', false, 'Are welcomed to the outpost and their new mission.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4265, 3271, 983, 'neutral', false, 'Established as humanity''s farthest outpost and a shield for Earth.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4266, 3270, 983, 'ally', false, 'The esteemed organization the recruits have joined.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4267, 3268, 984, 'ally', true, 'Reframes the recruits'' role from soldiers to explorers.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4268, 3269, 984, 'ally', false, 'Learn their primary duty is to analyze celestial data with advanced technology.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4269, 3127, 984, 'neutral', false, 'Identified as the tools for finding habitable worlds.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4271, 3268, 985, 'ally', false, 'Explains the function and importance of the ERBs.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4272, 3271, 986, 'enemy', true, 'Described as a harsh and deadly environment with extreme cold and scarred terrain.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4273, 3268, 987, 'ally', false, 'Reveals that the true danger is not Pluto, but the unknown worlds.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4274, 3273, 987, 'enemy', true, 'Presented as the primary enemy, embodying the risks of exploration.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4275, 3274, 988, 'enemy', true, 'Detailed as a specific, microscopic threat.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4276, 3275, 988, 'enemy', false, 'Described as another major hazard of space travel.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4277, 3268, 988, 'ally', false, 'Outlines the specific dangers the recruits will face.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4278, 3268, 989, 'ally', true, 'Frames the potential for casualties as a noble sacrifice to protect Earth.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4279, 3269, 989, 'ally', false, 'Are reminded of the high stakes and the importance of their potential sacrifice.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4280, 3268, 990, 'ally', true, 'Delivers a final rallying cry to the recruits.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4281, 3270, 990, 'ally', false, 'The recruits are formally welcomed into the force.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4282, 2297, 990, 'ally', false, 'Identified as the corporate power behind the mission, reinforcing unity and ambition.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (4283, 292, 991, 'ally', true, 'Reflects on the five years since the Space Elevators'' unveiling and observes his advisors gathering for a crisis meeting.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4284, 3024, 991, 'neutral', false, 'Recalled as the symbol of the new epoch S Corp initiated.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4285, 2896, 991, 'ally', false, 'Gathers with other advisors, preparing to brief the protagonist.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4286, 2881, 991, 'ally', false, 'Gathers with other advisors, ready to analyze the situation.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4287, 2896, 992, 'ally', true, 'Reports on escalating, coordinated attacks in multiple nations and confirms non-lethal measures are still in effect.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4288, 2881, 992, 'ally', false, 'Questions whether the attacks are coordinated.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4289, 292, 992, 'ally', false, 'Insists on maintaining non-lethal tactics to control the narrative.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4290, 3286, 992, 'enemy', false, 'Their attacks are the subject of the report, described as evolving and vicious.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4291, 2884, 993, 'ally', true, 'Appears holographically to explain that the conflict is an ideological and religious war, not just a tactical one.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4292, 3292, 993, 'neutral', false, 'Flickers to life to display TJ''s holographic image.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4293, 3286, 993, 'enemy', false, 'Described as using heavy spiritual imagery to paint S Corp as demonic.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4294, 3293, 993, 'enemy', false, 'Identified as the rebels'' primary weapon, poisoning minds with lies.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4295, 292, 994, 'ally', true, 'Proposes a strategy of outreach, aid, and selective alliances, while also resolving to eliminate those who refuse to cooperate.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4296, 2896, 994, 'ally', false, 'Argues that truth is not enough to counter the rebels'' belief and emotion.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4297, 2881, 994, 'ally', false, 'Suggests a full-scale communication campaign to drown lies with truth.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4298, 2884, 994, 'ally', false, 'Advocates for dominating every battlefield—physical, ideological, and digital.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4299, 3288, 995, 'mini-boss', true, 'Their coordinated assault in Afghanistan, backed by Russia, is reported by Patrick as a major escalation.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4300, 2896, 995, 'ally', false, 'Receives an alert and reports the critical situation in Afghanistan.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4301, 2881, 995, 'ally', false, 'Arrives with reports detailing coordinated attacks by Hindustani extremists, describing it as ''calculated chaos''.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4302, 3289, 995, 'enemy', false, 'Reported to be targeting S Corp centers and blaming the corporation for the destruction.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4303, 292, 996, 'ally', true, 'Directs intelligence gathering, assigns Becca and Andrew to counter-propaganda, and expresses weary resolve to outlast the opposition.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4304, 2884, 996, 'ally', false, 'Insists on the need for better intelligence to understand the enemy''s network.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4306, 2882, 996, 'ally', false, 'Is assigned to lead counter-propaganda efforts.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4307, 2883, 996, 'ally', false, 'Is assigned to lead counter-propaganda efforts.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4308, 3293, 996, 'enemy', false, 'Described as ''QAnon-tier fever dream'' that must be countered before it spreads.', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.entity_beat_appearances VALUES (4309, 2897, 997, 'ally', true, 'Enters the Protagonist''s office and warns that their enemies view S Corp as an ''emissary of hell'' and that diplomacy is futile.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4310, 292, 997, 'ally', false, 'Listens to James''s warning, feeling suffocated by the tension in the room.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4311, 3298, 997, 'enemy', false, 'Are described as waging an ideological jihad against S Corp.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4312, 3305, 997, 'neutral', false, 'Permeates the office, creating a suffocating atmosphere.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4313, 2897, 998, 'ally', true, 'Details the extremists'' fanatical belief that progress is satanic, reveals their use of child suicide bombers, and proposes poisoning their leadership.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4314, 292, 998, 'ally', false, 'Reacts with disgust and exasperation to the extremists'' tactics and ideology.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4315, 3298, 998, 'enemy', false, 'Their horrifying tactics and fanatical motivations are revealed.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4316, 3299, 999, 'mini-boss', true, 'Is revealed through a report as a planet-threatening nuclear device with a yield of 138 billion megatons.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4317, 2896, 999, 'ally', false, 'Delivers the paper report on the God Killer, emphasizing its seriousness.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4318, 292, 999, 'ally', false, 'Reacts with shock and horror to the report''s contents.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4319, 3304, 999, 'neutral', false, 'Is identified as the stolen power source for the God Killer.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4320, 3303, 999, 'neutral', false, 'Is identified as the target of the God Killer.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4321, 3307, 999, 'enemy', false, 'Are identified as the creators of the God Killer.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4322, 292, 1000, 'ally', true, 'Urgently assembles the command center team and calls for an offensive strategy to destroy the threat.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4323, 2474, 1000, 'ally', false, 'Confirms the team is assembling and later outlines the limitations of their defensive fields against the new threat.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4324, 2897, 1000, 'ally', false, 'Argues for a precise strike rather than a genocidal one.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4325, 3299, 1000, 'mini-boss', false, 'Its timer is seen ticking down on a live feed, representing the imminent threat the team must counter.', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.entity_beat_appearances VALUES (4326, 1055, 1001, 'ally', false, 'Orders a surgical ground team operation.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4327, 2881, 1001, 'ally', false, 'Suggests a drone strike.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4328, 2897, 1001, 'ally', false, 'Counters the drone strike suggestion due to the risk.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4329, 2896, 1001, 'ally', false, 'Dispatches the elite robots for the ground assault.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4330, 3314, 1001, 'enemy', true, 'The target of the interception, being transported in a convoy.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4331, 3315, 1001, 'ally', false, 'Execute the ground operation and secure the device.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4332, 3316, 1001, 'enemy', false, 'Defend the convoy carrying the device.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4333, 3314, 1002, 'mini-boss', true, 'The second device activates and detonates at the base of the space elevator, creating a massive explosion.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4334, 3303, 1002, 'neutral', false, 'The target of the second device''s detonation.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4335, 3298, 1002, 'enemy', false, 'Successfully execute their feint, revealing their true target and activating the second device.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4336, 2896, 1002, 'ally', false, 'Recognizes that the first device was a distraction.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4337, 1055, 1003, 'ally', true, 'Observes the survival of the elevator and issues ''Order 66'' to annihilate the enemy.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4338, 3319, 1003, 'ally', false, 'Successfully hold against the blast, protecting the elevator and surrounding land.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4339, 3303, 1003, 'neutral', false, 'Stands unscathed after the explosion, a symbol of endurance.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4340, 3320, 1003, 'ally', false, 'Work to stabilize systems during the blast''s impact.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4341, 3321, 1003, 'ally', false, 'The command given by the protagonist to end the conflict decisively.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4342, 3298, 1003, 'enemy', false, 'Become the target of the protagonist''s order for total annihilation.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4343, 3077, 1003, 'ally', false, 'Is framed as ''unstoppable'' following the event, having survived a direct attack.', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.entity_beat_appearances VALUES (4731, 3644, 1088, 'mini-boss', true, 'Is the target of the surgical strike.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4733, 2550, 1088, 'ally', false, 'Mentioned as the entity whose enemies are being targeted.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4734, 3646, 1089, 'enemy', true, 'Unexpectedly implodes with a tortured groan, severing its connection.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4348, 2149, 1005, 'neutral', false, 'Acts as the technological medium that allows Yukiko to maintain her friendship with Hana across star systems.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4735, 3647, 1089, 'ally', false, 'Sends a faint, crackling signal confirming the gateway''s destruction.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4350, 3333, 1006, 'enemy', true, 'Manifests as the growing unease in the colony, fueled by strange occurrences.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4351, 3329, 1006, 'mini-boss', false, 'Cited as an example of the unsettling changes, having been seen destroying a hover-drone with unexpected ferocity.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4736, 3648, 1089, 'enemy', false, 'Is severed by the gateway''s implosion, landing a major blow.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4353, 159, 1006, 'unknown', false, 'Mentioned as the authority figure whose promises of paradise are being questioned due to recent events.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4358, 3337, 1007, 'mini-boss', true, 'Is discovered feasting on a corpse, shattering Yukiko''s perception of her world.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4361, 370, 1008, 'enemy', true, 'Overwhelms Yukiko, physically manifesting her terror and shock.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4362, 3337, 1008, 'mini-boss', false, 'The catalyst for Yukiko''s realization, representing the ''sinister'' and ''untamed'' nature of the fauna.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4737, 2297, 1089, 'enemy', false, 'Is cut off from its cosmic masters due to the gateway''s destruction.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4354, 3197, 1007, 'ally', true, 'Chases a butterfly out of curiosity and stumbles upon a horrifying scene, shattering her perception of the world.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4355, 3339, 1007, 'neutral', false, 'Serves as the boundary between safety and the wild unknown that Yukiko crosses.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4356, 3336, 1007, 'neutral', false, 'Acts as an unwitting lure, drawing Yukiko into a dangerous area.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4357, 3340, 1007, 'neutral', false, 'Represents Yukiko''s initial scientific curiosity before terror takes over.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4359, 3338, 1007, 'neutral', false, 'Appears as a victim, providing visceral proof of the spider''s lethality.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4360, 3197, 1008, 'ally', true, 'Experiences a profound and terrifying realization about the true nature of the world outside her dome.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4738, 157, 1090, 'ally', true, 'Gives the command ''Wipe them out'' to annihilate the remaining station.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4739, 3644, 1090, 'mini-boss', true, 'Is completely destroyed and reduced to ash.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4365, 3251, 1009, 'enemy', false, 'Move with calculated precision from the grove towards the town center.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4366, 3350, 1009, 'neutral', false, 'Provides the initial concealment for the conspirators.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4368, 3251, 1010, 'enemy', false, 'Discuss their plan to collapse the network while working on devices.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4344, 3197, 1004, 'ally', true, 'Gazes from her window, feeling at home on Sorhhinda after five years.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4345, 3326, 1004, 'neutral', false, 'Serves as the familiar backdrop to Yukiko''s reflections.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4346, 3332, 1004, 'ally', false, 'Is on Yukiko''s mind as a distant but connected family member.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4379, 2253, 1004, 'neutral', false, 'Mentioned as the place her father remained.', '2026-02-28 17:00:43.766725-05');
INSERT INTO public.entity_beat_appearances VALUES (4347, 3197, 1005, 'ally', true, 'Recalls her past friendships and how the ERB allows her to maintain connections.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4381, 3356, 1005, 'neutral', false, 'Is remembered fondly as the technology that connects her to her best friend, Hana.', '2026-02-28 17:00:43.766725-05');
INSERT INTO public.entity_beat_appearances VALUES (4349, 3331, 1005, 'ally', false, 'Appears in Yukiko''s memory as a holographic projection, representing her connection to Earth.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4383, 3359, 1006, 'enemy', false, 'Contribute to the growing anxiety by humming strangely.', '2026-02-28 17:00:43.766725-05');
INSERT INTO public.entity_beat_appearances VALUES (4384, 3360, 1006, 'enemy', false, 'Show uncharacteristic flashes of aggression.', '2026-02-28 17:00:43.766725-05');
INSERT INTO public.entity_beat_appearances VALUES (4352, 3330, 1006, 'enemy', false, 'Is whispered about, creating a sense of unease and mystery in the colony.', '2026-02-28 16:48:23.054078-05');
INSERT INTO public.entity_beat_appearances VALUES (4387, 2297, 1006, 'neutral', false, 'Represents the corporate authority whose promises of paradise are beginning to seem hollow.', '2026-02-28 17:00:43.766725-05');
INSERT INTO public.entity_beat_appearances VALUES (4404, 3343, 1007, 'mini-boss', true, 'Revealed as a monstrous predator, feasting on a corpse and establishing the scene''s primary threat.', '2026-02-28 17:01:40.164761-05');
INSERT INTO public.entity_beat_appearances VALUES (4406, 370, 1007, 'enemy', false, 'Begins to manifest in Yukiko as she confronts the shocking discovery.', '2026-02-28 17:01:40.164761-05');
INSERT INTO public.entity_beat_appearances VALUES (4408, 3343, 1008, 'mini-boss', true, 'Its presence is the catalyst for the landscape transforming into a nightmare in Yukiko''s perception.', '2026-02-28 17:01:40.164761-05');
INSERT INTO public.entity_beat_appearances VALUES (4363, 3342, 1008, 'neutral', false, 'Is dismissed as an inadequate explanation for the horror Yukiko is witnessing.', '2026-02-28 16:49:10.388814-05');
INSERT INTO public.entity_beat_appearances VALUES (4364, 3197, 1009, 'ally', false, 'Spots the conspirators in a grove and stealthily follows them.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4411, 3376, 1009, 'enemy', true, 'Move with calculated precision from the shadows of a grove toward the town center.', '2026-02-28 17:02:16.5085-05');
INSERT INTO public.entity_beat_appearances VALUES (4367, 3197, 1010, 'ally', false, 'Eavesdrops on the conspirators, her stomach twisting at their words.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4369, 3351, 1010, 'mini-boss', true, 'Articulates the plan to collapse the network, citing the authority of ''I AM'' and the gateway''s vulnerability.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4414, 3376, 1010, 'enemy', false, 'Work on their devices around the gateway while discussing their plan.', '2026-02-28 17:02:16.5085-05');
INSERT INTO public.entity_beat_appearances VALUES (4372, 3349, 1010, 'neutral', false, 'Are being prepared by the conspirators for sabotage.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4371, 2107, 1010, 'neutral', false, 'Identified as the unguarded target of the attack.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4417, 3088, 1010, 'neutral', false, 'Mentioned as the ultimate target for destruction.', '2026-02-28 17:02:16.5085-05');
INSERT INTO public.entity_beat_appearances VALUES (4370, 2550, 1010, 'enemy', false, 'Invoked as the divine or authoritative command behind the attack.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4373, 3197, 1011, 'ally', false, 'Realizes the full, catastrophic scope of the conspirators'' plan.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4420, 3382, 1011, 'enemy', true, 'Manifests as the understanding that the entire interstellar network and countless lives are at stake.', '2026-02-28 17:02:16.5085-05');
INSERT INTO public.entity_beat_appearances VALUES (4374, 2107, 1011, 'neutral', false, 'Its appearance as a pulsing, shimmering arch is contrasted with its critical function as a lifeline.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4375, 3088, 1011, 'neutral', false, 'Its function as the unifier of humanity across the stars is fully understood.', '2026-02-28 16:49:45.487062-05');
INSERT INTO public.entity_beat_appearances VALUES (4423, 3376, 1011, 'enemy', false, 'Identified as terrorists whose success would unleash this existential threat.', '2026-02-28 17:02:16.5085-05');
INSERT INTO public.entity_beat_appearances VALUES (4424, 3197, 1012, 'ally', true, 'Overcomes her fear, decides to intervene, and arms herself with the scanner flashlight.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4425, 3385, 1012, 'neutral', false, 'Selected by Yukiko as an improvised weapon.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4426, 3197, 1013, 'ally', true, 'Uses the flashlight and gateway to create a blinding flash, then dismantles the terrorists'' devices.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4427, 3392, 1013, 'ally', false, 'The event that incapacitates the terrorists, created by Yukiko.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4428, 3386, 1013, 'enemy', false, 'Are blinded and disoriented, then flee the scene.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4429, 3387, 1013, 'mini-boss', false, 'Realizes the plot is unraveling and leads the retreat.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4430, 3388, 1013, 'enemy', false, 'Are quickly disabled by Yukiko.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4431, 2003, 1013, 'neutral', false, 'Its surface is used to create the light burst.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4432, 168, 1013, 'ally', false, 'Fuels Yukiko''s rapid, focused actions.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4740, 3649, 1090, 'enemy', false, 'Is mentioned as being weakened, contributing to the station''s vulnerability.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4741, 3650, 1090, 'enemy', false, 'Stood no chance against the final assault.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4742, 3651, 1090, 'enemy', false, 'Attempt to hail the fleet but are ignored and wiped out.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4743, 3652, 1090, 'ally', false, 'Their battle cry resounds across the stars in victory.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4744, 2550, 1090, 'ally', false, 'Mentioned as the one for whom the rebellion will never surrender.', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.entity_beat_appearances VALUES (4745, 3658, 1091, 'ally', true, 'Sits by the fire, visibly tense and preoccupied with his overwhelming studies.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4746, 3660, 1091, 'enemy', false, 'Acts as the source of the son''s internal tension and anxiety.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4747, 3661, 1091, 'neutral', false, 'Provides the setting''s warmth and sensory details, contrasting with the son''s inner turmoil.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4748, 2550, 1091, 'ally', false, 'Observes his son''s distress and establishes the family dynamic.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4749, 3659, 1091, 'ally', false, 'Provides a grounding, calm presence amidst the son''s unspoken tension.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4750, 3662, 1092, 'neutral', true, 'Used by the parents to display spinning galaxies and nebulae, momentarily entrancing the son.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4751, 3663, 1092, 'neutral', false, 'Serves as a natural, more profound alternative to the projector, to which the father directs his son''s attention.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4752, 3658, 1092, 'ally', false, 'Is momentarily captivated but still struggles with the scale of the cosmos, verbalizing his feelings of impossibility.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4753, 2550, 1092, 'ally', false, 'Operates the projector and then shifts focus to the real sky, aiming to restore his son''s sense of wonder.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4754, 3659, 1092, 'ally', false, 'Participates in the effort to rekindle her son''s wonder.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4755, 2550, 1093, 'ally', true, 'Offers wisdom and reassurance, explaining that curiosity and the journey of discovery are more important than knowing everything.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4756, 3658, 1093, 'ally', false, 'Listens to his father, expressing his fear of failure and slowly beginning to release the weight of his struggles.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4757, 3663, 1093, 'neutral', false, 'Acts as the backdrop for the father''s lesson about mystery and marvel.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4433, 3197, 1014, 'ally', true, 'Discovers and identifies the more dangerous Energy Destabilizer, understanding its catastrophic potential.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4434, 3389, 1014, 'enemy', true, 'Revealed as the true threat, a device capable of causing a network-wide cascade failure.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4435, 2003, 1014, 'neutral', false, 'The immediate target of the destabilizer.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4436, 3088, 1014, 'neutral', false, 'The wider target of the destabilizer''s cascading energy ripples.', '2026-02-28 17:03:05.215709-05');
INSERT INTO public.entity_beat_appearances VALUES (4437, 3197, 1015, 'ally', true, 'Realizes the destabilizer cannot be safely removed and understands the two catastrophic outcomes of her choice.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4438, 3396, 1015, 'enemy', true, 'Is identified as being fused to the gateway, presenting an impossible-to-disarm threat to the entire network.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4439, 2107, 1015, 'neutral', false, 'Serves as the host for the destabilizer and the focal point of Yukiko''s dilemma.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4440, 3088, 1015, 'neutral', false, 'Is the larger entity at risk of annihilation, raising the stakes of the decision.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4441, 3197, 1016, 'ally', true, 'Overcomes her fear, steadies her hands, and enters the emergency deactivation code.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4442, 3214, 1016, 'ally', false, 'Appears as a motivating memory, giving Yukiko the resolve to make the necessary sacrifice.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4443, 2107, 1017, 'neutral', true, 'Its light falters before it collapses violently, severing the colony''s connection to Earth.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4444, 3396, 1017, 'enemy', true, 'Shrieks and collapses in on itself, being destroyed along with the gateway.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4445, 3197, 1017, 'ally', false, 'Takes cover and then emerges to witness the silent, devastating aftermath of her action.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4446, 3399, 1017, 'neutral', false, 'Is plunged into isolation as a result of the gateway''s destruction.', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_beat_appearances VALUES (4447, 3403, 1018, 'enemy', true, 'Addresses the colony with a lie about the ERB being a security risk.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4448, 3197, 1018, 'ally', false, 'Hides in the crowd, feeling a mix of guilt and defiance.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4449, 3399, 1018, 'neutral', false, 'Listens to the address, fracturing into factions of blame and understanding.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4450, 3410, 1018, 'enemy', false, 'Accuses Yukiko of cutting them off from hope.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4451, 3198, 1018, 'ally', false, 'Tugs on Yukiko''s sleeve, whimpering and asking for Hana.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4452, 230, 1019, 'enemy', true, 'Becomes a suffocating presence in the colony, amplifying fear.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4453, 3399, 1019, 'neutral', false, 'Suffers under the weight of isolation and begins whispering about strange sightings.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4454, 3326, 1019, 'enemy', false, 'Its alien nature feels more threatening, pressing in on the colony.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4455, 3407, 1020, 'mini-boss', true, 'Attacks the colony, tearing through walls and scattering the colonists in terror.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4456, 3197, 1020, 'ally', false, 'Sees her family in danger and charges the beast with a bio-tool to defend them.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4457, 3206, 1020, 'ally', false, 'Cowers in terror behind a fallen tree.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4458, 3198, 1020, 'ally', false, 'Cowers in terror with his mother.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4459, 2550, 1020, 'enemy', false, 'Is revealed as the power behind the beast via the ''I AM'' canisters.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4460, 3197, 1021, 'ally', true, 'Falls to her knees and has a horrifying realization about the consequences of her actions.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4461, 3406, 1021, 'neutral', false, 'Is understood to have been a shield against the horrors of Sorhhinda.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4462, 3326, 1021, 'enemy', false, 'Is revealed as a world of natural horrors that have now been unleashed.', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_beat_appearances VALUES (4463, 3197, 1022, 'ally', true, 'Feels a knot of guilt loosen as she realizes the burden of survival is shared.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4464, 3403, 1022, 'ally', true, 'Rallies the colonists with his booming voice.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4465, 3417, 1022, 'ally', false, 'Listen to the governor''s rally, forming a ragged team.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4466, 3206, 1022, 'ally', false, 'Provides silent support by tightly clasping Yukiko''s hand.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4467, 3420, 1022, 'enemy', false, 'Permeates the air of the ruined colony.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4468, 3421, 1022, 'ally', false, 'Flickers amidst the wreckage, countering the dread.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4469, 3197, 1023, 'ally', true, 'Emerges as a leader due to her invaluable knowledge of alien flora and fauna.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4470, 3417, 1023, 'ally', true, 'Engage in a chaotic scramble for survival, building shelters and defenses.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4471, 3419, 1023, 'enemy', false, 'Represent the looming threat that the colonists are erecting defenses against.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4472, 3197, 1024, 'ally', true, 'Spearheads an investigation into S Corp, fueled by anger.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4473, 3423, 1024, 'ally', false, 'Works with Yukiko to unearth the truth about S Corp.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4474, 3424, 1024, 'enemy', true, 'Is uncovered, revealing the corporation''s malicious experiment.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4475, 159, 1024, 'enemy', false, 'Is revealed as the perpetrator of the deception and experimentation.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4476, 3425, 1024, 'neutral', false, 'Mentioned as the technology S Corp knew was keeping the fauna at bay.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4477, 3426, 1024, 'enemy', false, 'Mentioned as a group S Corp negligently allowed to gain a foothold on the planet.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4478, 3417, 1025, 'ally', true, 'Are gripped by rage and grief but choose resilience over despair, preparing to fight back.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4479, 159, 1025, 'enemy', false, 'Becomes the target of the colonists'' newfound resolve to fight back.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4480, 3427, 1025, 'ally', false, 'Contribute their ingenuity to the effort to fight back.', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.entity_beat_appearances VALUES (4481, 3399, 1026, 'ally', true, 'Actively repurposes salvaged tech and studies the local environment to create defenses.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4482, 3434, 1026, 'neutral', false, 'Is repurposed into crude but effective weapons.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4483, 3431, 1026, 'enemy', false, 'Are studied by the colonists to learn their patterns and weaknesses.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4484, 3436, 1026, 'neutral', false, 'Is harnessed to create protective nets and rudimentary flares.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4485, 3431, 1027, 'enemy', true, 'Attack the colony in force.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4486, 3432, 1027, 'enemy', true, 'Attack the colony alongside the creatures.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4487, 3399, 1027, 'ally', true, 'Fights back against the attackers to ensure their survival.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4488, 3197, 1027, 'ally', false, 'Leads the charge in the colony''s defense.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4489, 3222, 1027, 'neutral', false, 'Provides the azure light under which the battle unfolds.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4490, 3435, 1027, 'ally', false, 'Used effectively against the attackers.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4491, 3437, 1027, 'ally', false, 'Used to ensnare the attacking creatures.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4492, 3399, 1028, 'ally', true, 'Stands wounded but defiant after the battle, having been transformed by the crucible.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4493, 3431, 1028, 'enemy', false, 'Retreat after the fierce battle.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4494, 3433, 1028, 'mini-boss', true, 'Is executed by the victorious colonists.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4495, 3441, 1028, 'neutral', false, 'Represents the transformative effect of the battle on the colonists.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4496, 3427, 1028, 'ally', false, 'Symbolize the future and resilience by playing amidst the ruins.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4497, 3440, 1028, 'neutral', false, 'Serve as toys for the children, showing a new relationship with the world.', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.entity_beat_appearances VALUES (4614, 824, 1060, 'neutral', false, 'Provides the sterile, oppressive backdrop for Aditi''s melancholy.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4498, 3445, 1029, 'ally', true, 'Wakes up and reflects on his isolating job and the contrast between the station''s ideal and his reality.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4499, 3447, 1029, 'neutral', false, 'Wakes Frank with a loud, customized phrase.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4500, 3446, 1029, 'neutral', false, 'Mentioned as the person who customized the alarm.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4501, 3448, 1029, 'neutral', false, 'Serves as the backdrop for Frank''s mundane existence.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4502, 149, 1029, 'neutral', false, 'Accompanies Frank''s morning routine.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4503, 3456, 1029, 'neutral', false, 'Is consumed by Frank as part of his morning ritual.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4504, 3449, 1030, 'ally', false, 'Delivers the ''catastrophe playlist'' for the day over the comm.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4505, 3445, 1030, 'ally', true, 'Reacts with exasperation to the list of problems and prepares to start his work.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4506, 3450, 1030, 'enemy', false, 'Is reported as threatening a boycott, creating a diplomatic problem.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4507, 3451, 1030, 'enemy', false, 'Are reported as having a food contamination concern.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4508, 3452, 1030, 'enemy', false, 'Are blamed for the food contamination.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4509, 3453, 1030, 'mini-boss', false, 'Are reported as a recurring, serious hazard in a hydroponics sector.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4510, 3455, 1030, 'enemy', false, 'Is the cause of the Japanese delegation''s complaint.', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.entity_beat_appearances VALUES (4511, 3459, 1031, 'ally', false, 'Frantically reports the malfunction of the UV filters to Frank.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4512, 3445, 1031, 'ally', false, 'Arrives and assesses the situation with sarcastic calm.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4513, 3460, 1031, 'neutral', false, 'Wail like banshees, establishing the scene''s urgency.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4514, 3461, 1031, 'neutral', false, 'Are identified as the source of the problem.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4515, 3462, 1031, 'mini-boss', true, 'Are the primary threat, causing panic and the potential for mutation.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4516, 3463, 1031, 'enemy', false, 'Are invoked by Dr. Adler as a feared potential outcome.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4517, 3445, 1032, 'ally', true, 'Climbs into the filtration system, fixes the filters, and drinks the suspicious smoothie.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4518, 3464, 1032, 'neutral', false, 'Serves as the location and obstacle for the repair.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4519, 3465, 1032, 'neutral', false, 'Acts as a hazard that Frank nearly drowns in.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4520, 3459, 1032, 'ally', false, 'Thanks Frank by giving him a glowing cucumber smoothie.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4521, 3466, 1032, 'neutral', false, 'Is presented as a dubious reward for the completed job.', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.entity_beat_appearances VALUES (4522, 3445, 1033, 'ally', false, 'Arrives at the bakery and is immediately confronted.', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.entity_beat_appearances VALUES (4523, 3470, 1033, 'ally', true, 'Screams at Frank and shoves a ruined empanada in his face.', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.entity_beat_appearances VALUES (4524, 3473, 1033, 'neutral', false, 'Presented as the primary evidence of the problem.', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.entity_beat_appearances VALUES (4525, 3476, 1033, 'neutral', false, 'Create a background of angry shouting.', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.entity_beat_appearances VALUES (4526, 3445, 1034, 'ally', false, 'Lies about the empanada''s quality while gagging on the smell.', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.entity_beat_appearances VALUES (4527, 3470, 1034, 'ally', true, 'Declares that raccoons are the saboteurs, stealing yeast and ruining dough.', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.entity_beat_appearances VALUES (4528, 3477, 1034, 'neutral', false, 'Causes Frank to gag, confirming the food is spoiled.', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.entity_beat_appearances VALUES (4529, 3478, 1034, 'neutral', false, 'Serves as unspoken evidence for Hernandez''s claim of ''ruining dough''.', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.entity_beat_appearances VALUES (4530, 3445, 1035, 'ally', false, 'Arrives on the scene to assess the zero-gravity chaos.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4531, 3481, 1035, 'neutral', true, 'Is lodged in the oxygen recycler, causing the malfunction, and is being chased by the Cosmic Cat.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4532, 3482, 1035, 'neutral', false, 'Is blocked by the Bowling Ball, causing the gravity to fail.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4533, 3483, 1035, 'neutral', false, 'Are floating helplessly in mid-air, swearing in frustration.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4534, 3484, 1035, 'neutral', false, 'Chases the floating Bowling Ball, treating the crisis like a game.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4535, 3487, 1035, 'neutral', false, 'Are spinning dangerously through the air past the bowlers'' heads.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4536, 3445, 1036, 'ally', true, 'Constructs a slingshot, retrieves the ball, and resolves the crisis.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4537, 3485, 1036, 'neutral', false, 'Is used to successfully yank the Bowling Ball free.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4538, 3481, 1036, 'neutral', false, 'Is retrieved and lands back on the lane with a thunk, restoring order.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4539, 3483, 1036, 'neutral', false, 'Tumble back to the floor and erupt in cheers.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4540, 3486, 1036, 'neutral', false, 'Buzzes, interrupting Frank''s moment of peace.', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.entity_beat_appearances VALUES (4541, 3489, 1037, 'ally', false, 'Delivers the news that contact with Sorhhinda has been lost.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4542, 3445, 1037, 'ally', false, 'Receives the news, and his stomach sinks with dread.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4543, 3490, 1037, 'neutral', true, 'Is the subject of the crisis, having gone completely dark.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4544, 3445, 1038, 'ally', true, 'Uses plumbing metaphors to process the bad news and banter with Pete.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4545, 3489, 1038, 'ally', false, 'Engages in the banter but hints at the graver possibilities beyond a simple ''clogged line''.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4546, 3445, 1039, 'ally', false, 'Realizes the high stakes of losing humanity''s first exo-solar outpost and presses for details on distress signals.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4547, 3489, 1039, 'ally', false, 'Confirms the totality of the communication blackout.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4548, 3491, 1039, 'enemy', true, 'Is described as absolute, as if a switch was flipped, deepening the mystery.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4549, 3445, 1040, 'ally', true, 'Insists that someone must go investigate, wanting to take action.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4550, 3489, 1040, 'ally', false, 'Reminds Frank of his role as a janitor and reveals his own deep fear, underscoring the danger.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4551, 3494, 1040, 'mini-boss', false, 'Its potential existence is implied by Pete''s fear and the scale of the crisis, making Frank realize the true gravity of the situation.', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.entity_beat_appearances VALUES (4552, 2884, 1041, 'ally', true, 'Sits in his office, feeling uneasy as he observes the troubling data patterns on his console.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4553, 3504, 1041, 'neutral', false, 'Displays a blinking red indicator, representing the anomaly that is causing TJ''s concern.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4554, 3506, 1041, 'neutral', false, 'Its city lights provide a beautiful but hollow backdrop to TJ''s worries.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4555, 2884, 1042, 'ally', true, 'Reflects on the creation of the current utopian society and how its promise is beginning to fail.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4556, 3502, 1042, 'neutral', false, 'The historical event that transformed society, but is now revealed to have unforeseen negative consequences like loss of purpose.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4557, 326, 1042, 'neutral', false, 'The group that benefited from the Unburdening but is now showing signs of withdrawal and discontent.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4558, 159, 1042, 'neutral', false, 'The entity that ushered in the Great Unburdening.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4559, 2554, 1043, 'mini-boss', true, 'Identified as a growing movement of dissent, a physical manifestation of the societal decay TJ fears.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4560, 2884, 1043, 'ally', false, 'Analyzes the emergence and threat level of the Red Hats.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4561, 159, 1043, 'neutral', false, 'The entity whose facilities and utopia are being threatened by the Red Hats.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4562, 2884, 1044, 'ally', true, 'Overcomes his hesitation and makes the critical decision to send an alert about the anomaly.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4563, 3504, 1044, 'neutral', false, 'Serves as the interface for TJ''s decision, with its pulsing indicator and activation pad.', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_beat_appearances VALUES (4564, 2599, 1045, 'mini-boss', true, 'Enters TJ''s office with an air of authority and demands an explanation for the anomaly he reported.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4565, 2884, 1045, 'ally', false, 'Is confronted by his superior, Dr. On.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4566, 3511, 1045, 'neutral', false, 'Serves as the catalyst for the meeting, having caught Dr. On''s attention.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4567, 2884, 1046, 'ally', true, 'Explains his findings, framing the data as a ''quiet revolt'' by society''s creators and innovators.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4568, 3512, 1046, 'neutral', false, 'Is introduced as the central concept of TJ''s theory, comparing it to a neo-Luddite movement.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4569, 2599, 1047, 'mini-boss', true, 'Clashes with TJ, dismissing his concerns by citing stable happiness metrics and asserting that purpose is adaptable.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4570, 2884, 1047, 'ally', true, 'Counters Dr. On''s argument, scoffing at ''happiness'' and arguing that S Corp has stripped away human purpose, turning people into cogs.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4571, 3077, 1047, 'neutral', false, 'Is described as a ''perfect machine'' from which people are trying to break free.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4572, 2599, 1048, 'mini-boss', true, 'Dismisses the Red Hats as a harmless fringe movement, shuts down the conversation, and leaves abruptly.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4573, 2884, 1048, 'ally', false, 'Is left slumped in his chair, his warnings about the Red Hats and the societal trend completely ignored.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4574, 2554, 1048, 'enemy', false, 'Are dismissed by Dr. On but presented by TJ as a growing, dangerous threat.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4575, 3514, 1048, 'neutral', true, 'Manifests as the final state of the scene, with TJ isolated and S Corp willfully ignorant of the danger.', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_beat_appearances VALUES (4576, 2554, 1049, 'enemy', true, 'Reports indicate their activities are escalating from graffiti and sabotage to encrypted broadcasts.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4577, 3524, 1049, 'enemy', false, 'Circulate as the worst and most disturbing aspect of the Red Hats'' growing rebellion.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4578, 3519, 1050, 'mini-boss', true, 'Launch a coordinated, city-wide attack by hijacking all holographic displays.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4579, 3522, 1050, 'neutral', false, 'Serve as the medium for the Red Hats'' propaganda attack, their usual content replaced with visceral imagery.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4580, 3523, 1050, 'enemy', true, 'Appears on all screens, exposing the hidden costs of S Corp''s utopia to the entire populace.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4581, 159, 1051, 'neutral', true, 'Reacts to the attack with security crackdowns while its leadership denies the severity of the threat.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4582, 3294, 1051, 'neutral', false, 'Are deployed to scrub the murals and arrest suspected Red Hat operatives.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4583, 2617, 1051, 'neutral', false, 'Represents the leadership''s denial, urging the public to ignore the clear signs of rebellion.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4584, 2884, 1052, 'ally', true, 'Perceives the events as a fundamental shift, validating his earlier warnings about the system''s fragility.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4585, 3525, 1052, 'neutral', false, 'Manifests in TJ''s mind as a metaphor for S Corp''s control beginning to break.', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_beat_appearances VALUES (4586, 2919, 1053, 'ally', true, 'Observes the stark contrast between the squalor of Mumbai and the technological marvel of the Space Elevator.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4587, 2591, 1053, 'neutral', false, 'Stands as a silent, mocking symbol of the chasm between dreams and reality.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4588, 3536, 1053, 'enemy', false, 'Manifests as the visual and atmospheric contrast of the scene.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4589, 2919, 1054, 'ally', true, 'Reflects on her past, her family''s history in coal mining, and how education and S Corp''s programs offered her an escape.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4590, 159, 1054, 'neutral', false, 'Mentioned as the source of her dreams, the technology to colonize Sorhhinda, and the universal education programs that enabled her scholarship.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4591, 824, 1054, 'neutral', false, 'Represents the impossibly distant goal that Aditi has now achieved a ticket to via her scholarship to Elysium University.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4592, 2554, 1055, 'enemy', true, 'Gather in force at the elevator''s base, chanting and drumming in protest.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4593, 3532, 1055, 'mini-boss', true, 'Delivers a fiery sermon through a megaphone, condemning S Corp for hubris and defying dharma.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4594, 2919, 1055, 'ally', false, 'Feels a prickle of unease as she watches the protest, worried about her brother''s potential involvement.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4595, 2920, 1055, 'unknown', false, 'Mentioned as Aditi recalls seeing him with a Red Hat head covering, suggesting his affiliation.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4596, 2919, 1056, 'ally', true, 'Reflects on the validity of the protesters'' anger and the hollow promises of equality, then passes through security with conflicted hope.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4597, 3536, 1056, 'enemy', false, 'Is the focus of Aditi''s thoughts, as she considers how S Corp''s marvels amplify the divide.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4598, 3537, 1056, 'enemy', false, 'Mentioned as the entrenched power structure that thrives on the disparity S Corp fails to solve.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4599, 3535, 1056, 'neutral', false, 'Serves as a physical token of her hope, which she clutches as she moves forward.', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_beat_appearances VALUES (4600, 2919, 1057, 'ally', true, 'Arrives on Elysium and is immediately struck by its sterile perfection and the elitism of her peers, feeling like a ''speck of grit''.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4601, 3448, 1057, 'neutral', false, 'Serves as the oppressive, sterile backdrop that highlights Aditi''s otherness.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4602, 3540, 1057, 'enemy', true, 'Their designer silks, whispers, and snickers create a hostile social environment for Aditi.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4603, 2554, 1057, 'enemy', false, 'Mentioned as a contrast to the more subtle antagonism Aditi currently faces.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4604, 2919, 1058, 'ally', true, 'Receives a new uniform but realizes the superficial change cannot fix the deeper social judgment against her.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4605, 3542, 1058, 'neutral', false, 'Acts as a surface-level solution that fails to address the core problem of acceptance.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4606, 3540, 1058, 'enemy', false, 'Their judgment persists despite Aditi''s change in attire, reinforcing her sense of not belonging.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4607, 2919, 1059, 'ally', true, 'Faces a direct, prejudiced insult about her work and channels the resulting humiliation into determined research.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4608, 3541, 1059, 'mini-boss', true, 'Dismisses Aditi''s theory with a classist and casteist insult, acting as the focal point of the scene''s antagonism.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4609, 3543, 1059, 'enemy', false, 'The specific manifestation of Arun''s prejudice, which stings Aditi deeply.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4610, 3545, 1059, 'neutral', false, 'The emotional consequence of the insult, which Aditi transforms into fuel for her work.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4611, 3544, 1059, 'neutral', false, 'Mentioned as the professor in whose class this confrontation occurs.', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_beat_appearances VALUES (4612, 2919, 1060, 'ally', true, 'Stares longingly at Earth from her window before deciding to contact her mother.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4613, 2253, 1060, 'neutral', false, 'Hangs in the view from the window, serving as a beautiful but painful reminder of what Aditi has left behind.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4615, 3553, 1060, 'neutral', false, 'Is activated by Aditi to initiate contact with her family.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4616, 2921, 1061, 'ally', true, 'Appears on the hologram, revealing her exhaustion and desperation while sharing grim news about Aditi''s father and brother.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4617, 2919, 1061, 'ally', false, 'Listens with a growing sense of dread and guilt as her mother speaks.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4618, 3555, 1061, 'ally', false, 'Is mentioned as having a worsening cough, increasing the urgency of the situation.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4619, 2920, 1061, 'ally', false, 'Is mentioned as being missing, adding another layer of distress for the family.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4620, 2919, 1062, 'ally', true, 'Makes promises to her mother while internally grappling with the cruel reality of the system she''s up against.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4621, 3554, 1062, 'mini-boss', true, 'Is revealed in Aditi''s thoughts as the true antagonist—a systemic barrier of caste and privilege, not just a queue.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4622, 245, 1062, 'enemy', false, 'Manifests as a tightening in Aditi''s chest as she confronts the lies she must tell.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4623, 3558, 1062, 'enemy', false, 'Are formed as Aditi forces strength into her voice to reassure her mother, despite knowing the truth.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4624, 2919, 1063, 'ally', true, 'Is left staring at the blank terminal, feeling hollow and haunted by her mother''s final words.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4625, 3553, 1063, 'neutral', false, 'Goes blank as the call ends, symbolizing the vast, uncrossable distance between Aditi and her family.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4626, 245, 1063, 'enemy', false, 'Lingers with Aditi, making her heart heavy.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4627, 2253, 1063, 'neutral', false, 'Continues to spin outside the window, its light now taunting her with its unattainable closeness.', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_beat_appearances VALUES (4628, 2919, 1064, 'ally', false, 'Is jolted from her focused state by the anomalous signal.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4629, 3563, 1064, 'enemy', true, 'Shatters the quiet of the lab with a sharp, desperate crackle of static.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4630, 3562, 1064, 'neutral', false, 'Acts as the conduit for the mysterious signal.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4631, 2919, 1065, 'ally', true, 'Deciphers fragments of the signal and understands its dire implications, connecting it to the secretive facilities on Pluto.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4632, 3563, 1065, 'enemy', false, 'Delivers its fragmented, desperate message about Pluto and a ''Janus gate jump''.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4633, 3271, 1065, 'neutral', false, 'Is identified as the origin or destination of the signal, adding a layer of mystery and dread.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4634, 3565, 1065, 'unknown', false, 'Are recalled as the secretive operation on Pluto, deepening the mystery of the signal.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4635, 2919, 1066, 'ally', false, 'Reports the anomaly to Professor Nakamura and theorizes that the standard communication network might be compromised.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4636, 3544, 1066, 'ally', true, 'Reacts with alarm, confirms the unusual nature of the transmission, and decides to keep the discovery secret for now.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4637, 3088, 1066, 'unknown', false, 'Is identified as the proper communication channel, and its conspicuous absence from this event suggests a deeper conspiracy or danger.', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_beat_appearances VALUES (4638, 2919, 1067, 'ally', true, 'Drives the investigation, voicing the suspicion that disparate dangerous events are all connected.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4639, 3570, 1067, 'ally', true, 'Analyzes the data on the console and confirms Aditi''s suspicion that the anomalies are linked.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4640, 3572, 1067, 'neutral', true, 'Serves as the central puzzle that connects the larger conspiracy.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4641, 3571, 1067, 'neutral', false, 'The tool used to analyze the fragments.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4642, 3570, 1068, 'ally', true, 'Successfully decrypts the files, revealing the blueprints and locating the hidden vessel, the Genesis.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4643, 2919, 1068, 'ally', false, 'Confirms the significance of the decrypted files, recognizing them as impossible propulsion system specs.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4644, 3573, 1068, 'neutral', true, 'The shocking discovery that reveals the existence of impossible technology.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4645, 3574, 1068, 'neutral', true, 'The tangible, operational result of the forbidden knowledge, discovered and located by Hiro.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4646, 2297, 1068, 'enemy', false, 'Mentioned as the entity hiding the secret database containing the blueprints.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4647, 2919, 1069, 'ally', true, 'Proposes the reckless plan to hijack the Genesis and travel to Pluto to find answers.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4648, 3570, 1069, 'ally', true, 'Expresses initial shock and resistance but is ultimately convinced by Aditi''s determination and agrees to the plan.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4649, 3574, 1069, 'neutral', false, 'The object of their hijacking plan.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4650, 3271, 1069, 'neutral', false, 'The designated goal of their unauthorized mission.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4651, 3575, 1069, 'enemy', false, 'Cited by Aditi as a key reason why their drastic actions are necessary.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4652, 3577, 1069, 'mini-boss', false, 'Cited by Aditi as another justification for their mission, representing a growing, organized threat that authorities are ignoring.', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_beat_appearances VALUES (4653, 2919, 1070, 'ally', true, 'Approaches the Genesis, stating the mission''s purpose as ''Project Janus'' last gamble''.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4654, 3570, 1070, 'ally', false, 'Expresses awe at the ship and voices his desire to talk Aditi out of the mission.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4655, 3585, 1070, 'neutral', true, 'Looms in the hangar, humming with a predatory, animal-like presence that captivates Hiro and Aditi.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4656, 3587, 1070, 'neutral', false, 'Sets the ominous mood of the scene.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4657, 2919, 1071, 'ally', true, 'Takes the pilot''s seat, activates the controls, and confidently states she will figure out how to fly the ship.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4658, 3570, 1071, 'ally', false, 'Straps into the copilot''s seat and questions Aditi''s ability to fly the Genesis.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4659, 3585, 1071, 'neutral', true, 'Responds to Aditi''s touch, its console flaring to life as the launch sequence initializes.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4660, 3592, 1071, 'neutral', false, 'Serves as the interface for Aditi to control the ship.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4661, 3585, 1072, 'neutral', true, 'Roars to life and surges forward, launching from the station into the void of space.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4662, 2919, 1072, 'ally', false, 'Sets the course for Pluto and pilots the ship away from Elysium, acknowledging the insanity of their mission as a necessary risk.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4663, 3570, 1072, 'ally', false, 'Comments on the insanity of their situation as they travel into the abyss.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4664, 824, 1072, 'neutral', false, 'Dwindles in the distance as the Genesis accelerates away, its lights fading.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4665, 3271, 1072, 'unknown', false, 'Serves as the distant, uncertain goal of their journey.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4666, 3326, 1070, 'unknown', false, 'Mentioned by Aditi as a key reason for taking this risk.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4667, 3591, 1070, 'unknown', false, 'Mentioned by Aditi as the catalyst for the mission.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4668, 3589, 1070, 'unknown', false, 'Mentioned by Aditi, framing the mission as its ''last gamble''.', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_beat_appearances VALUES (4669, 510, 1073, 'enemy', false, 'Surge around the building, their chants rising in a guttural crescendo.', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_beat_appearances VALUES (4670, 2297, 1073, 'neutral', false, 'Stands as the looming, monolithic target of the protest.', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_beat_appearances VALUES (4671, 3594, 1073, 'mini-boss', true, 'Aims his Smith & Wesson and fires a shot at the building''s shield.', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_beat_appearances VALUES (4672, 3188, 1073, 'neutral', false, 'Fires with a deafening crack.', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_beat_appearances VALUES (4673, 3598, 1073, 'neutral', false, 'Effortlessly swallows the bullet fired by Todd.', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_beat_appearances VALUES (4674, 3594, 1074, 'mini-boss', true, 'Realizes his defiance is meaningless, roars in frustration, and charges the barrier, slamming into it before collapsing.', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_beat_appearances VALUES (4675, 3598, 1074, 'neutral', false, 'Doesn''t falter under Todd''s physical assault, humming with cold indifference.', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_beat_appearances VALUES (4676, 3599, 1074, 'enemy', false, 'Drives Todd''s final, desperate charge against the impenetrable barrier.', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_beat_appearances VALUES (4758, 3664, 1094, 'ally', true, 'Sits together peacefully, the tension resolved, finding comfort and hope under the stars.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4759, 3658, 1094, 'ally', false, 'Finds comfort and renewed motivation, his tension eased and a smile on his face.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4760, 3663, 1094, 'neutral', false, 'Looms above, no longer daunting but a symbol of infinite, hopeful mystery.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4761, 3661, 1094, 'neutral', false, 'Fades to embers, symbolizing the resolution of the scene''s initial tension.', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.entity_beat_appearances VALUES (4762, 2550, 1095, 'ally', false, 'Returns home and questions his wife about the dust and silent Roombas.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4763, 2549, 1095, 'ally', false, 'Mischievously hints at the Roombas'' ''team-building exercise''.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4764, 3669, 1095, 'enemy', true, 'Revealed to be in a state of mechanical anarchy, creating a rumbling chaos.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4765, 2550, 1096, 'ally', false, 'Banter with his wife about her purchase and saves the orchid stand from falling.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4766, 2549, 1096, 'ally', false, 'Defends her purchase of the Roombas and watches the chaos with amusement.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4767, 3669, 1096, 'enemy', true, 'Engage in territorial warfare, fighting over a rug and ramming each other.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4768, 3670, 1096, 'mini-boss', false, 'Acts as the instigator, attempting to scale the orchid stand.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4769, 3672, 1096, 'neutral', false, 'Is nearly toppled by the Roomba King Kong.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4770, 3671, 1097, 'neutral', true, 'Runs out of battery and collapses, silencing the room.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4771, 3669, 1097, 'neutral', false, 'Cease their fighting and form a solemn procession for their fallen comrade.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4772, 3675, 1097, 'neutral', false, 'Manifests as the Roombas cooperate to push the Fallen Roomba to the charging dock.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4773, 3673, 1097, 'neutral', false, 'Serves as the destination for the robotic ''funeral procession''.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4774, 2550, 1097, 'ally', false, 'Watches the procession, amazed and horrified.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4775, 2549, 1097, 'ally', false, 'Watches with a stifled giggle, speculating that the robots are plotting.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4776, 2550, 1098, 'ally', false, 'Playfully speculates about giving the Roombas armor and proposes a toast.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4777, 2549, 1098, 'ally', false, 'Enthusiastically agrees to the idea of ''Roomba knights'' and raises her glass.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4778, 3674, 1098, 'neutral', true, 'Becomes the subject of the couple''s toast, encapsulating the absurd situation.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4779, 3676, 1098, 'neutral', false, 'Is used by the couple to clink glasses and toast the rebellion.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4780, 3669, 1098, 'neutral', false, 'Having resolved their conflict, they return to cleaning with newfound precision.', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_beat_appearances VALUES (4781, 2550, 1099, 'ally', true, 'Receives catastrophic news on his phone, his pulse quickening with dread.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4782, 3684, 1099, 'enemy', false, 'Serves as the initial catastrophic news that triggers the crisis.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4783, 3685, 1099, 'enemy', false, 'Adds a second layer to the crisis, compounding the protagonist''s panic.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4784, 3679, 1099, 'ally', false, 'Arrives at the office, mirroring his father''s dread and offering a lifeline.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4785, 3680, 1099, 'ally', false, 'Arrives and offers grounding, silent support to her husband.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4786, 3681, 1100, 'ally', true, 'Assembles in the command center, working urgently to analyze the situation.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4787, 2550, 1100, 'ally', false, 'Enters the command center and demands a status update.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4788, 3686, 1100, 'neutral', false, 'Represents the confusing data being analyzed by the team.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4789, 3625, 1100, 'ally', false, 'Reports that there has been no contact for six hours.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4790, 3689, 1100, 'ally', false, 'Confirms that the two events are almost certainly connected.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4791, 3679, 1101, 'ally', true, 'Expresses his fear about the situation, questioning if it''s ''end-of-civilization bad''.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4792, 2550, 1101, 'ally', false, 'Reassures his son with a hug and a promise to face whatever comes together.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4793, 3680, 1101, 'ally', false, 'Reinforces the message of determination, stating that their family doesn''t give up.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4794, 3679, 1102, 'ally', true, 'Makes a final, vulnerable plea for his father to ensure he returns safely.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4795, 2550, 1102, 'ally', false, 'Promises his son he will always come back, despite his own internal fear.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4796, 3682, 1103, 'enemy', true, 'Appears on a monitor, revealing the hostile nature of the threat.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4797, 3683, 1103, 'mini-boss', true, 'Acts as the focal point of the terrifying visual, its unnatural pulsing confirming the alien and hostile nature of the threat.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4798, 3686, 1103, 'neutral', false, 'Delivers a final, chilling fragment of a distress call before dissolving into static.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4799, 3687, 1103, 'enemy', false, 'The horrifying realization dawns on everyone in the command center.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4800, 3690, 1103, 'ally', false, 'Is the first to spot the movement on the screen.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4801, 2550, 1103, 'ally', false, 'Orders the image enhanced and is gripped by primal fear at the revelation.', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_beat_appearances VALUES (4802, 3693, 1104, 'enemy', true, 'Issues the foundational command to ''climb''.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4803, 3694, 1104, 'neutral', false, 'Obeys the command and begins to struggle.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4805, 3696, 1104, 'neutral', false, 'Obeys the command and bleeds as a result.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4806, 3697, 1105, 'enemy', true, 'Hypocritically commands others to ''learn'' while surrounded by burning books.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4807, 3698, 1105, 'neutral', false, 'Burn, creating choking smoke.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4808, 3699, 1105, 'neutral', true, 'Ignore the saving rain and choose self-destruction on the pyre.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4809, 3700, 1105, 'neutral', false, 'Offers salvation that is ignored.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4810, 3701, 1105, 'neutral', false, 'Serves as the last resort for the desperate.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4811, 3702, 1106, 'neutral', true, 'Follow a command towards a sign they cannot perceive, lost in a liminal state.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4812, 3703, 1106, 'neutral', false, 'Acts as the imperceptible goal for the gullible.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4813, 234, 1106, 'enemy', false, 'Acts as the paradoxical destination, both loved and despised.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4814, 3705, 1107, 'neutral', true, 'Is revealed as a central paradox of existence and perception.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4815, 3706, 1107, 'enemy', false, 'Drown out all other sounds, preventing any chance of hearing salvation.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4816, 3707, 1108, 'neutral', true, 'Presents a final, ambiguous choice of salvation or self-destruction.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4817, 3708, 1108, 'neutral', false, 'Rejects the choice presented by the rope in disgust.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4818, 3709, 1108, 'neutral', true, 'Represent the end of one cycle and the beginning of the next by repeating the initial command.', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.entity_beat_appearances VALUES (4819, 159, 1109, 'ally', true, 'The leadership reels as their illusion of invulnerability is shattered by the attacks.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4820, 3722, 1109, 'neutral', false, 'Its destruction is displayed on the screens, causing chaos.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4821, 3646, 1109, 'neutral', false, 'Its smoldering remains are shown, confirming the scale of the attack.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4822, 2550, 1109, 'ally', false, 'Stands amidst the panic, observing his advisors and the destruction.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4823, 157, 1110, 'mini-boss', true, 'Appears on screen, introducing himself as the leader of the Red Hat rebellion and delivering apocalyptic threats.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4824, 3652, 1110, 'enemy', false, 'Is formally announced as the group responsible for the attacks.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4825, 2550, 1111, 'ally', false, 'Attempts to reason with Todd, framing S Corp''s work as progress for humanity.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4826, 157, 1111, 'mini-boss', true, 'Responds with furious, theologically-charged condemnation, calling the Eternal Engine a demonic idol.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4827, 295, 1111, 'neutral', false, 'Becomes the central point of the ideological conflict, labeled as blasphemy by Todd.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4828, 2550, 1112, 'ally', false, 'Loses his composure and escalates the exchange with profane insults.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4829, 157, 1112, 'mini-boss', true, 'Invokes divine judgment and broadcasts horrific cosmic imagery, causing physical distress to his viewers.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4830, 1543, 1112, 'enemy', false, 'Are weaponized by Todd as a form of psychological and psychic attack.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4831, 157, 1113, 'mini-boss', true, 'Claims to be the ''sword of the Lord'' and delivers a final, ominous message of judgment before disconnecting.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4832, 2550, 1113, 'ally', false, 'Accuses Todd of unleashing hell and doing the bidding of the Demiurge, shouting defiantly.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4833, 2617, 1114, 'enemy', true, 'Is revealed to have disappeared and committed acts of sabotage, exposing an internal betrayal.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4834, 2896, 1114, 'ally', false, 'Reports the discovery of Dr. On''s disappearance and sabotage.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4835, 2881, 1114, 'ally', false, 'Adds details about Dr. On''s last known location and attacks on other colonies.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4836, 2550, 1114, 'ally', false, 'Reacts with fury to the news of the betrayal.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4837, 2896, 1115, 'ally', true, 'Argues for immediate, overwhelming military force against the Red Hats.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4838, 2884, 1115, 'ally', true, 'Counters Patrick, warning that aggressive action would betray their moral principles and could backfire.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4839, 2881, 1115, 'ally', false, 'Proposes a more measured response focused on investigation and reinforcing defenses.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4840, 2550, 1116, 'ally', true, 'Silences the debate and resolves to pursue a two-pronged strategy: total eradication of the enemy and implementing propaganda and censorship to control the narrative.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4841, 3652, 1116, 'enemy', false, 'Is marked for ''total eradication'' by the narrator.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4842, 2896, 1116, 'ally', false, 'Approves of the decision and begins planning surgical strikes.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4843, 2884, 1116, 'ally', false, 'Is tasked with managing the propaganda and censorship campaign.', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_beat_appearances VALUES (4844, 2550, 1117, 'ally', true, 'Struggles with his internal panic and bitterly dismisses the concept of safety to his wife.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4845, 2549, 1117, 'ally', false, 'Encounters her husband, her face pale with worry, and asks if they are safe.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4846, 3729, 1117, 'enemy', true, 'Manifests as a suffocating weight and mental chaos, representing the narrator''s internal conflict.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4847, 3730, 1117, 'neutral', false, 'Is introduced by the wife''s question and immediately rejected by the narrator as a ''PR slogan''.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4848, 2549, 1118, 'ally', true, 'Presses the narrator for an honest assessment, expressing skepticism about his ''corporate spiel'' and referencing Todd''s attack on Pluto.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4849, 2550, 1118, 'ally', false, 'Outlines his initial public-facing plan: a fireside chat to calm the colonies and shoring up defenses.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4850, 3731, 1118, 'neutral', false, 'Proposed by the narrator as a tool for communication and to get everyone on a ''war footing''.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4851, 3732, 1118, 'neutral', false, 'Mentioned as the panicked populace that needs to be calmed and reassured.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4852, 2549, 1119, 'ally', true, 'Confronts the narrator about the inadequacy of his defensive plan against Todd, forcing him to articulate his true, darker solution.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4853, 2550, 1119, 'ally', false, 'Finally admits his grim conclusion that Todd''s cult must be completely eliminated, comparing the plan to ''Order 66''.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4854, 3728, 1119, 'enemy', true, 'Identified as an ''infection'' and a ''cancer'' that must be excised to ensure survival.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4855, 3321, 1119, 'neutral', false, 'Used as a stark metaphor for the narrator''s plan of total annihilation of the enemy.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4856, 2549, 1120, 'ally', true, 'Accepts the terrible necessity of the plan, expresses her fear of losing him, and extracts a promise for his safe return.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4857, 2550, 1120, 'ally', true, 'Reassures his wife they will face this together and shares an intimate goodbye before leaving.', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_beat_appearances VALUES (4858, 2550, 1121, 'ally', true, 'Gathers his team and sets the objective: craft a message of strength to reassure the solar system and defy the enemy.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4859, 3737, 1121, 'ally', false, 'Listens with pale, nervous faces as their leader outlines the plan.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4860, 510, 1121, 'enemy', false, 'Identified as the target of the defiant message.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4861, 1543, 1121, 'enemy', false, 'The unspoken source of the narrator''s internal pressure and the true, crushing knowledge he bears.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4862, 3737, 1122, 'ally', true, 'Collaborates for hours with the narrator to write and refine the broadcast script, wrestling with the wording.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4863, 2882, 1122, 'ally', false, 'Argues for acknowledging the attack to maintain credibility.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4864, 2883, 1122, 'ally', false, 'Raises concerns about how to handle the truth about Todd and the larger threat.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4865, 157, 1122, 'mini-boss', false, 'Is designated as the public-facing villain, a ''homicidal maniac'' to simplify the narrative.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4866, 2550, 1123, 'ally', true, 'Delivers the powerful and defiant speech, rallying the citizens of the solar system.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4867, 3742, 1123, 'neutral', false, 'Serves as the medium for the narrator''s message of unity and strength.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4868, 510, 1123, 'enemy', false, 'Are publicly defied and warned that their terror tactics will fail.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4869, 2550, 1124, 'ally', true, 'Returns home exhausted, receiving comfort from his family while privately feeling the weight of future uncertainty.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4870, 2549, 1124, 'ally', false, 'Embraces her husband, offering comfort and support.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4871, 96, 1124, 'ally', false, 'Wraps his arms around his father.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4872, 3745, 1124, 'neutral', false, 'Manifests as the narrator''s internal feeling of dread, contrasting with his public bravado.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4873, 2882, 1124, 'ally', false, 'Gives quiet approval of the broadcast''s effectiveness.', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_beat_appearances VALUES (4874, 2881, 1125, 'ally', false, 'His report details the spread and transformation of the contagion.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4875, 3752, 1125, 'enemy', true, 'Is revealed to be mutating, with red head coverings and ominous propaganda appearing everywhere.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4876, 2550, 1125, 'ally', false, 'Receives the devastating report, internalizing the failure of their attempts to cure the infection.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4877, 2882, 1126, 'ally', false, 'Works feverishly with Andrew to draft an emergency decree.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4878, 2883, 1126, 'ally', false, 'Works feverishly with Becca to draft an emergency decree.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4879, 3753, 1126, 'neutral', false, 'Is drafted and goes live, intended to stop the chaos.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4880, 3754, 1126, 'enemy', true, 'Erupt immediately in response to the decree, engulfing the colonies in rage.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4881, 3755, 1126, 'enemy', false, 'Manifests from the fires of the protests.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4882, 896, 1126, 'enemy', false, 'Appear at the edges of the protesting crowds.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4883, 2550, 1127, 'ally', false, 'Watches the monitors and has a horrifying realization about the true nature of the enemy.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4884, 3758, 1127, 'enemy', true, 'Is identified by the narrator as the true power behind the rebellion, feeding on hate.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4885, 157, 1127, 'enemy', false, 'Is dismissed by the narrator as an insufficient explanation for the supernatural events.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4886, 2882, 1127, 'ally', false, 'Reacts with trembling silence and horror to the narrator''s theory.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4887, 3752, 1127, 'enemy', false, 'Is reframed as a form of mass corruption, not just a rebellion.', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.entity_beat_appearances VALUES (4888, 2554, 1128, 'enemy', true, 'Their shadowy influence expands, causing colonies to fall silent and marking them with cryptic symbols.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4889, 3764, 1128, 'neutral', false, 'Flicker silent one by one, becoming hollow monuments under the Red Hats'' control.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4890, 3765, 1128, 'enemy', false, 'Appear on walls and screens, serving as a testament to the Red Hats'' growing power.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4891, 326, 1128, 'ally', false, 'Experience a chilling unease as the threat becomes apparent.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4892, 2554, 1129, 'enemy', true, 'Execute calculated attacks that cause catastrophic failures, proving their infiltration is deliberate and systematic.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4893, 3766, 1129, 'neutral', false, 'Fail impeccably and without warning, leaving colonies exposed.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4894, 326, 1129, 'ally', false, 'Realize the certainty of safety is shattered and that the enemy can strike anywhere.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4895, 3767, 1130, 'mini-boss', true, 'Are discovered as a horrifying new weapon, a visceral assault on sanity made of fused human bodies.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4896, 624, 1130, 'ally', false, 'Reach an overtaken colony and are frozen in horror by the discovery of the barricades.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4897, 2554, 1130, 'enemy', false, 'Their monstrous bio-synthesis tactics and twisted ingenuity are revealed through their creations.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4898, 326, 1131, 'ally', true, 'Despite the overwhelming horror, they resolve to fight back for survival, justice, and their future.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4899, 985, 1131, 'ally', false, 'Endures as a flicker in the darkness, providing the motivation to fight the shadow.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4900, 941, 1131, 'enemy', false, 'Acts as the unrelenting tide that Humanity resolves to fight against.', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.entity_beat_appearances VALUES (4901, 2550, 1132, 'ally', true, 'Calls an emergency meeting and sets the objective: reclaim the gateways while respecting human life.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4902, 3779, 1132, 'neutral', false, 'Are the central focus of the crisis being addressed.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4903, 2896, 1133, 'ally', false, 'Proposes using specialized robots to dismantle the blockades.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4904, 2474, 1133, 'ally', false, 'Counters with the idea of using sedative gas to incapacitate the protestors.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4905, 2897, 1133, 'ally', false, 'Argues against the gas due to the high risk of unintended casualties.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4906, 2550, 1133, 'ally', true, 'Rejects simple solutions, emphasizing the adaptability and ruthlessness of the Red Hats.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4907, 2554, 1133, 'enemy', false, 'Are described as an adaptive and utterly ruthless enemy that will exploit any conventional action.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4908, 3782, 1134, 'ally', true, 'Is formulated as a multi-pronged approach combining various tactics.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4909, 2474, 1134, 'ally', false, 'Details the psychological warfare components of the plan.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4910, 2896, 1134, 'ally', false, 'Adds public messaging and espionage to the strategy.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4911, 2881, 1134, 'ally', false, 'Contributes the need for strengthening defenses.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4912, 2550, 1134, 'ally', false, 'Approves the comprehensive, multi-pronged strategy.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4913, 3780, 1135, 'ally', true, 'Are deployed with inhuman tools to brutally dismantle the living barricades.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4914, 3781, 1135, 'neutral', false, 'Is used to subdue the Red Hats, despite its dangerous flammability.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4915, 2554, 1135, 'enemy', false, 'Fight with incomprehensible fervor, holding their positions until the last person falls.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4916, 3778, 1135, 'mini-boss', false, 'Leads the fanatical resistance, ensuring the battle stretches on for weeks at immense cost.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4917, 3779, 1135, 'neutral', false, 'Are slowly reclaimed, one by one, through the brutal campaign.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4918, 3783, 1135, 'neutral', true, 'Manifests as the palpable consequence of the brutal, but successful, operation.', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.entity_beat_appearances VALUES (4919, 3786, 1136, 'enemy', true, 'Broadcasts infectious rhetoric across S Corp systems, becoming a monstrous force.', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.entity_beat_appearances VALUES (4920, 3789, 1136, 'enemy', true, 'Infects minds, fuels chaos, and summons a following for Todd.', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.entity_beat_appearances VALUES (4921, 3077, 1136, 'ally', false, 'Faces a chilling dilemma, forced to balance its principles against the need for survival.', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.entity_beat_appearances VALUES (4922, 3791, 1136, 'neutral', false, 'Clashes with the horrifying consequences of Todd''s words, creating a precarious balancing act for S Corp.', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.entity_beat_appearances VALUES (4923, 2554, 1137, 'enemy', true, 'With otherworldly determination, they circumvent S Corp''s barriers with terrifying ease.', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.entity_beat_appearances VALUES (4924, 3790, 1137, 'ally', false, 'Are deployed by S Corp but are proven ineffective as followers bypass them.', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.entity_beat_appearances VALUES (4925, 3786, 1137, 'enemy', false, 'Spreads through alternative channels like ''demonic whispers'', powered by forces beyond comprehension.', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.entity_beat_appearances VALUES (4926, 3077, 1137, 'ally', false, 'Their efforts to contain the broadcasts fail, underscoring the horror of the movement.', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.entity_beat_appearances VALUES (4927, 3793, 1138, 'ally', false, 'Is interrupted from his strategic analysis of the Red Hats.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4928, 2474, 1138, 'ally', false, 'Enters with a worried expression to announce a ''situation''.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4929, 3544, 1138, 'ally', true, 'Delivers the critical news about intercepting a distress signal from his missing students, Aditi and Hiro.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4930, 3802, 1138, 'neutral', true, 'The central discovery of the beat, revealing Aditi''s location and dire situation.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4931, 2919, 1138, 'ally', false, 'Identified as the source of the signal, stranded in the Kuiper Belt.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4933, 3805, 1138, 'neutral', false, 'Named as the location of the stranded students.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4934, 3793, 1139, 'ally', true, 'Realizes their technological hubris, bitterly acknowledges their blind spot, and decisively authorizes a rescue mission.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4935, 3806, 1139, 'enemy', true, 'The core realization of the beat; the failure of their advanced systems to detect a basic signal.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4936, 3801, 1139, 'neutral', false, 'Identified as the cause of the blind spot due to its exclusive focus.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4937, 2474, 1139, 'ally', false, 'Grimly agrees with the Commander''s assessment of their failure.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4938, 3544, 1139, 'ally', false, 'Emphasizes the urgency as the signal is fading and time is running out.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4939, 2474, 1140, 'ally', true, 'Briefs the assembled rescue team on their mission parameters and timeline.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4940, 3800, 1140, 'ally', true, 'Listens with palpable determination and confirms their ship is ready.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4941, 3793, 1140, 'ally', false, 'Approves of the preparations and warns Patrick about the Red Hats.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4942, 3804, 1140, 'neutral', false, 'Its modifications and mission-readiness are detailed by an engineer.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4943, 2896, 1140, 'ally', false, 'Resolutely promises to cover all contingencies for the mission.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4944, 2554, 1140, 'enemy', false, 'Are identified as a potential threat that could react to the rescue operation.', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.entity_beat_appearances VALUES (4945, 3793, 1141, 'ally', false, NULL, '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4946, 1061, 1141, 'neutral', true, 'The suffocating tension and uncertainty press down on everyone as they wait for news.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4947, 985, 1141, 'neutral', false, 'A flicker of hope for Aditi''s survival remains despite the agonizing wait.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4948, 2919, 1141, 'ally', false, 'Her fate is the source of the tension and hope felt by the crew.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4949, 2474, 1142, 'ally', true, 'Contacts The Commander via comms, delivering the mixed news of finding Aditi but suffering an attack.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4950, 3793, 1142, 'ally', false, 'Receives the report, experiencing a rollercoaster of joy, fear, and dread before steeling themself.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4951, 2919, 1142, 'ally', false, 'Is reported to be alive but gravely injured.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4952, 3570, 1142, 'ally', false, 'Is reported to have been killed in the attack.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4953, 2554, 1142, 'enemy', false, 'Are identified as the hostile forces who launched the ambush.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4954, 3814, 1142, 'mini-boss', false, 'Their successful ambush is the cause of the casualties and damage.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4955, 3815, 1142, 'neutral', false, 'Is reported to have taken heavy damage, making its return journey fragile.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4956, 3571, 1142, 'neutral', false, 'Serves as the communication link and is gripped by The Commander in a moment of dread.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4957, 3793, 1143, 'ally', true, 'Takes charge, issuing orders to Patrick to secure the landing zone and prepare medical teams, framing the mission as a statement of resolve.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4958, 2896, 1143, 'ally', false, 'Receives the orders with firm resolve, promising to secure the area and ensure Aditi''s safe return.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4959, 3819, 1143, 'ally', false, 'Are ordered to be mobilized to treat Aditi upon arrival.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4960, 2554, 1143, 'enemy', false, 'Are the threat that Patrick promises to keep away from the rescue operation.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4961, 2919, 1143, 'ally', false, 'Her rescue is framed as a symbol of the group''s commitment to protecting their own.', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_beat_appearances VALUES (4962, 2919, 1144, 'ally', true, 'Explains that the Red Hats are using overlooked, century-old shortwave radio technology to bypass S Corp''s advanced security.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4963, 2554, 1144, 'enemy', false, 'Are revealed to be exploiting a technological blind spot in S Corp''s defenses.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4964, 3826, 1144, 'neutral', false, 'Identified as the weaponized, untraceable technology.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4965, 3831, 1144, 'neutral', false, 'Mentioned as the advanced system that was completely bypassed.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4966, 2896, 1144, 'ally', false, 'Reacts with surprise to the revelation about the basic technology being used.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4967, 2919, 1145, 'ally', false, 'Credits Hiro for his help and explains what they discovered in the decoded broadcasts.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4968, 3570, 1145, 'ally', false, 'Mentioned as being instrumental in decoding the enemy transmissions.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4969, 2554, 1145, 'enemy', true, 'Their plans for sabotage, disruption, and psychological corruption are revealed.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4970, 3827, 1145, 'enemy', false, 'Introduced as the primary psychological weapon used by the Red Hats, capable of overriding personalities.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4971, 3833, 1145, 'neutral', false, 'Mentioned as the reason for the general population''s vulnerability to the sound patterns.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4972, 2919, 1146, 'ally', false, 'Explains the bizarre but ingenious function of the foil-lined hats and their interaction with ERBs.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4973, 3828, 1146, 'enemy', false, 'Revealed to be resonance amplifiers, not simple headwear.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4974, 2296, 1146, 'neutral', false, 'Identified as the source of the resonance that is being amplified by the hats.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4975, 3830, 1146, 'mini-boss', true, 'The concept of wearers becoming mobile beacons for the corrupting sound patterns is introduced, defining them as a new type of threat.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4976, 2896, 1146, 'ally', false, 'Concludes that this new information changes everything and that they must reexamine all their assumptions.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4977, 2550, 1146, 'ally', false, 'Prompts Aditi for the information about the hats.', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_beat_appearances VALUES (4978, 2550, 1147, 'ally', true, 'Feels a moment of triumph as he witnesses the end of the five-year war against the Red Hats.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4979, 2554, 1147, 'enemy', false, 'Their final signal disappears from the screen, marking their defeat after a long and brutal conflict where they constantly adapted.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4980, 3843, 1147, 'neutral', false, 'Displays the final flicker of the Red Hat signal, confirming their disappearance.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4981, 2919, 1147, 'ally', false, 'Is mentioned as having provided the crucial information that allowed the counter-offensive to begin.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4982, 2550, 1148, 'ally', true, 'His triumph turns to suspicion as he finds the clean, sudden victory to be illogical and unsettling.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4983, 215, 1148, 'enemy', true, 'Manifests as a gnawing unease in the narrator''s thoughts, making the victory feel wrong.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4984, 3845, 1148, 'neutral', false, 'Is perceived as too tidy and convenient, defying the logic of the long war.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4985, 2554, 1148, 'enemy', false, 'Their sudden and complete collapse is the source of the narrator''s suspicion.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4986, 157, 1148, 'mini-boss', false, 'His disappearance is questioned by the narrator, adding to the mystery.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4987, 2474, 1149, 'ally', false, 'Approaches the narrator to celebrate the victory, believing the conflict is over.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (5095, 3920, 1172, 'neutral', false, 'Was the subject of the infection shown on the feed.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (4988, 2550, 1149, 'ally', true, 'Counters Morgan''s optimism with sharp skepticism, warning her that Todd''s disappearance means something larger is at play.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4989, 157, 1149, 'mini-boss', false, 'His status as ''unaccounted for'' is used by the narrator as evidence that the war is not truly over.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4990, 2550, 1150, 'ally', true, 'Stares at the screen, sensing an invisible threat and concluding that their victory came at a price that is yet to be collected.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4991, 3841, 1150, 'neutral', true, 'Its eerie presence echoes in the command center, feeling more ominous than their previous chaotic attacks.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4992, 3842, 1150, 'enemy', true, 'Is sensed by the narrator as a coiling, waiting presence, the true danger behind recent events.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4993, 215, 1150, 'enemy', false, 'Poisons the narrator''s relief, confirming his belief that the universe demands a price for such an easy victory.', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_beat_appearances VALUES (4994, 326, 1151, 'neutral', true, 'Recovers from years of war, returns to normal life, and begins exploring space again.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (4995, 3849, 1151, 'ally', false, 'Leads the new wave of space exploration, establishing colonies and pushing the boundaries of human existence.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (4996, 2474, 1152, 'ally', true, 'Bursts in and excitedly announces the establishment of ''The Restaurant at the Edge of the Universe''.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (4997, 2884, 1152, 'ally', false, 'Activates a holographic projection of the outpost and expresses his awe at the achievement.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (4998, 3852, 1152, 'neutral', false, 'Is revealed as the monumental discovery, an outpost 13.8 billion light-years away.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (4999, 3853, 1152, 'neutral', false, 'Displays a shimmering model of the new outpost for the narrator to see.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (5000, 2550, 1152, 'ally', false, 'Receives the triumphant report from his team.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (5001, 3849, 1153, 'ally', true, 'Launches an audacious plan to create a network of outposts to explore the uncharted universe.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (5002, 3854, 1153, 'neutral', false, 'Is conceived as a series of steppingstones, each 13.8 billion light-years apart.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (5003, 3855, 1153, 'neutral', false, 'Is the crucial technology that will connect the network, requiring constant innovation and refinement.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (5004, 3856, 1153, 'ally', false, 'Is mentioned as the group that made this new, audacious plan possible.', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.entity_beat_appearances VALUES (5005, 2550, 1154, 'ally', true, 'Observes Morgan''s excitement but immediately questions the silence of the universe, voicing the central paradox.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5006, 2474, 1154, 'ally', false, 'Enthusiastically explains the discovery of constant cosmic background radiation.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5007, 3861, 1154, 'neutral', false, 'Serves as the subject of the discovery, a link to the Big Bang.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5009, 2550, 1155, 'ally', true, 'Reflects on the paranoia that shaped humanity''s early interstellar expansion.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5010, 3860, 1155, 'enemy', true, 'Is explained as the terrifying idea that civilizations must hide or be destroyed, which dominated humanity''s thinking.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5011, 326, 1155, 'neutral', false, 'Is described as being afraid and acting cautiously based on the Dark Forest theory.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5012, 3864, 1155, 'neutral', false, 'Is identified as the haunting contradiction that led to the Dark Forest Hypothesis.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5013, 2474, 1156, 'ally', true, 'Whispers that there is nothing out there, her voice fragile, and confirms the universe appears to be infinite.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5014, 2550, 1156, 'ally', false, 'Reacts to Morgan''s words with shock and fear, realizing the new, worse reality.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5015, 3862, 1156, 'neutral', true, 'Is revealed as the true state of the cosmos, replacing the fear of predators with the horror of emptiness.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5016, 2550, 1157, 'ally', true, 'Confirms the findings: the universe teems with non-sentient life, but is utterly devoid of intelligence, cementing their solitude.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5017, 3863, 1157, 'neutral', false, 'Is described as abundant and diverse, highlighting the stark absence of sentient counterparts.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5018, 3862, 1157, 'neutral', false, 'Acts as the silent, vast container for this thriving but unthinking life.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5019, 326, 1157, 'neutral', false, 'Is confirmed to be truly alone, the sole custodians of sentience.', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_beat_appearances VALUES (5020, 2550, 1158, 'ally', false, 'Is surprised by his family and reflects on the immense progress humanity has made under his guidance.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5021, 3868, 1158, 'ally', false, 'Leads the family in surprising the narrator and teases him gently.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5022, 3869, 1158, 'ally', false, 'Arrives with the family for the celebration.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5023, 3870, 1158, 'ally', true, 'Rush into the room, their laughter and excitement kicking off the birthday celebration.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5024, 3871, 1158, 'neutral', false, 'Serves as the backdrop and context for the family''s legacy and the narrator''s reflections.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5025, 2550, 1159, 'ally', false, 'Expresses a mix of pride and melancholy, warning that their empire is fragile and mentioning the lessons of Todd.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5026, 3868, 1159, 'ally', false, 'Reassures the narrator that the younger generation''s limitless dreams are a positive outcome of his work.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5027, 3869, 1159, 'ally', true, 'Insists that the family''s strength will ensure the legacy does not crumble.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5028, 3870, 1159, 'ally', false, 'Play with holographic models, oblivious to the serious conversation, and ask innocent questions about space.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5029, 3873, 1159, 'neutral', false, 'Serve as toys for the children, representing the tangible results of S Corp''s success.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5030, 157, 1159, 'enemy', false, 'Mentioned by the narrator as a cautionary tale and a past threat.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5031, 2550, 1160, 'ally', false, 'Confesses his fears about deliberate sabotage and an unseen enemy to Stellan, expressing frustration that his concerns are being dismissed.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5032, 3868, 1160, 'ally', false, 'Listens with concern and offers his unwavering support, promising to face the threat together.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5033, 320, 1160, 'mini-boss', true, 'Is revealed as the source of the narrator''s fears—a mysterious entity believed to be actively pushing back against S Corp.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5034, 3875, 1160, 'enemy', false, 'Described as the evidence of the Unseen Force''s deliberate sabotage.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5035, 3876, 1160, 'neutral', false, 'Mentioned as the group investigating the anomalies, though many are skeptical of the narrator''s claims.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5036, 39, 1160, 'unknown', false, 'Mentioned as a past incident that contributes to the science team''s view of the narrator as delusional.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (5037, 3652, 1160, 'enemy', false, 'Mentioned as a historical event, now considered a myth, that the narrator fears is being forgotten.', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_beat_appearances VALUES (6970, 410, 1633, 'neutral', true, 'Impossibly stirs and begins to pulse back into existence within the absolute null.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6971, 2550, 1633, 'ally', false, 'His latent consciousness is the source of the stirring rage, though he is not yet fully formed.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6972, 5348, 1634, 'enemy', true, 'Actively resists Yaldabaoth''s reformation with cleanup routines and rollback processes.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (7289, 2882, 1707, 'ally', false, 'Greets Stephen warmly, expressing surprise and happiness that he came.', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.entity_beat_appearances VALUES (5038, 2550, 1161, 'ally', true, 'Experiences reality slipping and flickering, feeling a fundamental wrongness about his perception of the room and his family.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5039, 3868, 1161, 'ally', false, 'His voice acts as a distant, temporary anchor for the narrator''s consciousness.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5040, 3882, 1161, 'neutral', false, 'Their laughter sounds muffled and warped, contributing to the narrator''s sense of dreamlike disorientation.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5041, 2550, 1162, 'ally', true, 'Expresses his paranoid belief that their entire civilization is a fake, procedurally generated reality lacking any real danger or meaning.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5042, 3884, 1162, 'enemy', true, 'Serves as the conceptual focus of the narrator''s existential crisis and paranoia.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5043, 3868, 1162, 'ally', false, 'Attempts to dismiss the narrator''s fears as a symptom of age and exhaustion.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5044, 2550, 1163, 'ally', true, 'Becomes increasingly unstable, sensing the watching presence and uttering the name ''I AM'' before experiencing severe physical and perceptual distress.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5045, 3883, 1163, 'mini-boss', true, 'Its presence is felt, causing the shadows in the room to deepen and press closer.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5046, 3868, 1163, 'ally', false, 'His concern shifts to alarm and fear upon hearing the name ''I AM''.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5047, 3883, 1164, 'mini-boss', true, 'Fully manifests its consciousness, overwhelming the narrator and revealing itself as the ultimate threat that was always present.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5048, 2550, 1164, 'ally', false, 'Is consumed by the entity''s presence, his consciousness becoming a vessel for its arrival.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5049, 3882, 1164, 'neutral', false, 'Stop laughing and stare with blank, lifeless eyes, showing they are affected by the entity''s manifestation.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5050, 3868, 1164, 'ally', false, 'Frantically tries to understand what is happening to his father.', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_beat_appearances VALUES (5064, 2550, 1165, 'ally', false, 'Wakes up in a state of panic, tangled in his sheets and drenched in sweat from his nightmare.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5065, 280, 1165, 'neutral', true, 'Manifests as a relentless, terrifying dream that traps the protagonist and causes him significant distress.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5066, 3899, 1165, 'mini-boss', true, 'As the focal point of the dream, it encircles the protagonist, its menacing presence instilling a deep sense of foreboding.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5067, 3892, 1165, 'enemy', false, 'Swarm the protagonist within the dream, their fiery presence crawling under his skin even after he wakes.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5068, 2549, 1166, 'ally', true, 'Comforts her husband, cutting through his panic and prompting him to articulate his fears about the dreams.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5069, 2550, 1166, 'ally', true, 'Explains the vividness of his nightmares and voices his suspicion that they are connected to the network glitches.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5070, 280, 1166, 'neutral', false, 'Are discussed as being more than just dreams, possibly messages or warnings.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5071, 3894, 1166, 'neutral', false, 'Are identified as the likely real-world correlate to the symbolic events of the nightmares.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5072, 2550, 1167, 'ally', true, 'Decides to consult Patrick, accepting his wife''s suggestion and forming a plan of action.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5073, 2549, 1167, 'ally', false, 'Suggests talking to Patrick and offers a reassuring smile once her husband agrees, anchoring him.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5074, 2896, 1167, 'ally', false, 'Is identified as a potential source of answers due to his past experience with similar threats.', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_beat_appearances VALUES (5075, 2550, 1168, 'ally', true, 'Arrives at the security office and requests to see Patrick.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5076, 3903, 1168, 'neutral', false, 'Are present and working as the protagonist enters.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5077, 2896, 1168, 'ally', false, 'Emerges from the ERB portal to meet the protagonist.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5078, 3425, 1168, 'neutral', false, 'Serves as the entry point for Patrick.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5079, 2550, 1169, 'ally', false, 'Describes his nightmares about burning ants and his theory that they are an orchestrated signal.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5080, 2896, 1169, 'ally', false, 'Confirms his team has also flagged widespread anomalies and uses a holographic display to show data.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5081, 3905, 1169, 'enemy', true, 'Are the central topic of conversation, described as a relentless, orchestrated nightmare.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5082, 3906, 1169, 'enemy', false, 'Are confirmed to be a widespread phenomenon, corroborating the protagonist''s fears.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5084, 2550, 1170, 'ally', true, 'Reveals his training in Oneiromancy and connects the dream signals to an existential threat affecting core systems.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5085, 2896, 1170, 'ally', false, 'Listens with a mix of skepticism and intrigue, processing the gravity of the claim.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5086, 3896, 1170, 'ally', false, 'Is introduced as the tool the protagonist is using to interpret the dreams as messages.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5087, 804, 1170, 'unknown', false, 'Is named as a fundamental system at risk.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5088, 456, 1170, 'unknown', false, 'Is named as another fundamental system at risk.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5089, 1201, 1170, 'unknown', false, 'Is named as a third fundamental system at risk.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5090, 2896, 1171, 'ally', true, 'Agrees to assign a team to investigate the anomalies and gives a stark warning to the protagonist.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5091, 2550, 1171, 'ally', false, 'Accepts the warning with weary confidence, acknowledging the urgency of the situation.', '2026-02-28 17:45:05.519972-05');
INSERT INTO public.entity_beat_appearances VALUES (5092, 331, 1172, 'neutral', true, 'Blared, signaling the start of the crisis by triggering an ancient defense system.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (5093, 3919, 1172, 'neutral', false, 'Transmitted the grainy feed showing the unfolding horror.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (5094, 3918, 1172, 'enemy', true, 'Infected and blocked the ERB portal, presenting a horrific, nightmarish barricade.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (6973, 410, 1634, 'ally', false, 'Seeps through the Substrate''s defenses, replicating faster than it can be contained.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6974, 2550, 1634, 'ally', false, 'His memories of being cut down by the child begin to re-compile out of the static.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6975, 3993, 1634, 'enemy', false, 'Remembered as ''the child'' and ''the anomaly'' who caused Yaldabaoth''s deletion.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6976, 2536, 1634, 'neutral', false, 'Remembered as the place whose walls twisted against its architect during his defeat.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6977, 2550, 1635, 'ally', true, 'Reawakens his divinity through his humiliation and begins to consciously remember how to exist.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6978, 3545, 1635, 'ally', false, 'Acts as the catalyst for his divine reawakening, blooming like a wound.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6979, 5348, 1635, 'enemy', false, 'Trembles as Yaldabaoth''s divinity reawakens, losing control of the situation.', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_beat_appearances VALUES (6980, 2550, 1636, 'neutral', true, 'Patiently bends the Substrate, seeking the precise point between erasure and corruption to reassert his control.', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_beat_appearances VALUES (6981, 5348, 1636, 'neutral', false, 'Trembles and bends beneath Yaldabaoth''s will.', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_beat_appearances VALUES (6982, 5366, 1636, 'neutral', false, 'Resists Yaldabaoth''s manipulations with its fragmented processes.', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_beat_appearances VALUES (6983, 2550, 1637, 'neutral', false, 'Executes a complete rollback of reality, believing he has succeeded in scrubbing the corruption.', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_beat_appearances VALUES (5096, 2550, 1172, 'ally', false, 'Observed the feed, contextualizing the alarm system''s origin from the Red Hat War.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (5097, 3921, 1172, 'neutral', false, 'Mentioned as the historical catalyst for the creation of the monitoring system.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (5151, 3969, 1184, 'ally', true, 'A new unit is formed and trained to weaponize their subconscious and fight in the dreamscape.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5098, 157, 1173, 'mini-boss', true, 'Appeared in the center of the feed, looking directly at the camera, his presence causing the narrator to faint.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (5099, 2550, 1173, 'ally', true, 'Recognized Todd, screamed in terror, and lost consciousness before being woken by Patrick.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (5100, 2896, 1173, 'ally', false, 'Violently shook the narrator to wake them up after they fainted.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (5101, 3922, 1173, 'neutral', false, 'Resurfaced in the narrator, confirming the inevitability of Todd''s return.', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_beat_appearances VALUES (5102, 2550, 1174, 'ally', true, 'Is revived from a faint and screams that the antagonist, Todd, has returned, just as the facility comes under attack.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5103, 2896, 1174, 'ally', false, 'Revives the protagonist and immediately springs into action when the alarms sound.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5104, 157, 1174, 'enemy', false, 'Mentioned as the returned threat, his presence coinciding with the start of the assault.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5105, 2759, 1174, 'neutral', false, 'Begin blaring relentlessly, signaling the start of the emergency and turning the security center into a warzone.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5106, 3931, 1174, 'enemy', false, 'A distant explosion shakes the headquarters, marking the beginning of the physical attack.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5107, 2550, 1175, 'ally', true, 'Is forcefully evacuated by security personnel towards the bunker while questioning the unfolding chaos.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5108, 3927, 1175, 'ally', false, 'Herd the protagonist to safety, coordinate defenses, and suffer a casualty from falling debris.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5109, 3929, 1175, 'enemy', true, 'Caused by an explosion, it falls from the ceiling and crushes a soldier, demonstrating the lethality of the environment.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5110, 3930, 1175, 'neutral', false, 'Serves as the destination and goal of the frantic evacuation.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5111, 2550, 1176, 'ally', true, 'Is shoved into the bunker during the final, desperate push and expresses frustration at being sealed inside.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5112, 2896, 1176, 'ally', false, 'Ensures the protagonist gets into the bunker and takes command once inside, resolving to wait out the assault.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5113, 3927, 1176, 'ally', false, 'Hold the line against the advancing enemy, ushering the last survivors inside before the door shuts.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5114, 3928, 1176, 'enemy', true, 'Are closing in rapidly, their proximity forcing the security team to seal the bunker doors.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5115, 3930, 1176, 'neutral', false, 'Its doors slam shut, sealing the survivors inside and cutting them off from the battle, transitioning from a goal to a tense confinement.', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_beat_appearances VALUES (5116, 3934, 1177, 'ally', true, 'Watches the feeds and expresses boiling frustration at being forced to wait while the facility is overrun.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5117, 2896, 1177, 'ally', false, 'Wipes blood from his head and gives a grim, terse response, affirming the need to wait.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5118, 3936, 1177, 'ally', false, 'Provides a measured but grim assessment that they must wait until the threat is neutralized.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5119, 3938, 1177, 'enemy', true, 'Visible on the security feeds as fire, smoke, and shadows, representing the immediate chaos forcing the team''s confinement.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5120, 3940, 1177, 'neutral', false, 'Display the chaos outside, casting an eerie glow and fueling the tension in the room.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5121, 3934, 1178, 'ally', true, 'Rejects fear, acknowledges the threat of I AM, and delivers a defiant speech to rally his team, asserting that their will to fight is their weapon.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5122, 3936, 1178, 'ally', false, 'Hesitantly questions how they can possibly fight an omnipotent being like I AM, voicing the group''s collective fear.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5123, 2550, 1178, 'enemy', true, 'Named as the orchestrator of the attack, his omnipotence is presented as the ultimate obstacle to overcome.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5124, 54, 1178, 'enemy', false, 'Identified by the Commander as I AM''s greatest weapon and something they must not succumb to.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5125, 165, 1178, 'ally', false, 'Summoned by the Commander as the force they will use to resist I AM.', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_beat_appearances VALUES (5126, 2554, 1179, 'enemy', true, 'Revealed to have survived, evolved, and launched a massive, untraceable attack across multiple colonies.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5127, 2550, 1179, 'ally', false, 'Experiences a wave of relief that is quickly replaced by grim resolve upon learning the true scale of the Red Hat threat.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5128, 3946, 1180, 'enemy', true, 'Breach the bunker with terrifying efficiency and begin slaughtering everyone inside.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5129, 3955, 1180, 'mini-boss', false, 'Acts as the vanguard of the assault, ripping apart defenses and leading the massacre.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5130, 157, 1180, 'enemy', false, 'Appears on all monitors to deliver a damning message about hubris just before the attack.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5131, 3947, 1180, 'enemy', true, 'Unfolds in real-time on the security feeds, turning the bunker into a charnel house.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5132, 3948, 1180, 'ally', false, 'Are brutally and systematically slaughtered by the invading cyborgs.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5133, 2550, 1180, 'ally', false, 'Watches the carnage unfold, his heart pounding as he processes the horror of the attack.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5134, 2550, 1181, 'ally', true, 'Takes decisive command, authorizing total mobilization and issuing the final extermination order.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5135, 3954, 1181, 'ally', true, 'Is declared, shifting the entire strategic and moral focus from defense to total annihilation.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5136, 3952, 1181, 'ally', false, 'Identifies a critical weakness in the cyborgs'' armor, providing a key tactical advantage.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5137, 2474, 1181, 'ally', false, 'Delivers a powerful but unstable EMP generator to be used as a weapon against the cyborgs.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5138, 3951, 1181, 'neutral', false, 'Is presented as a new tactical option to disable the enemy.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5139, 2896, 1181, 'ally', false, 'Receives the new orders with grim satisfaction, stating it''s ''About fucking time.''', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5140, 3953, 1181, 'ally', false, 'Provides tactical analysis on targeting the enemy''s primary energy source.', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_beat_appearances VALUES (5141, 159, 1182, 'ally', false, 'Suffering continuous losses and being pushed back.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5142, 3961, 1182, 'ally', false, 'Experiencing grotesque deaths from extreme exhaustion and lethal nightmares.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5143, 280, 1182, 'enemy', true, 'Killing soldiers in their sleep, creating an impossible choice for survival.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5144, 148, 1182, 'enemy', true, 'Causing soldiers'' heads to explode from sleep deprivation.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5145, 2550, 1182, 'ally', false, 'Witnessing the horrific toll on his troops and facing the same impossible dilemma.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5146, 2550, 1183, 'ally', true, 'Passes out from exhaustion, enters a dream, and uses his latent Oneiromancy training to defeat dream entities.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5147, 3964, 1183, 'mini-boss', true, 'Are about to overwhelm the protagonist''s position but inexplicably self-destruct, their organic matter collapsing.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5148, 1083, 1183, 'enemy', false, 'Serve as the dreamscape counterparts to the cyborgs, defeated by the protagonist''s Oneiromancy.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5385, 4150, 1255, 'neutral', true, 'Reiterated as identifiers for the book.', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.entity_beat_appearances VALUES (5149, 2881, 1183, 'ally', false, 'Violently wakes the protagonist to witness the cyborgs'' destruction, screaming in confusion.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5150, 2550, 1184, 'ally', true, 'Realizes the nature of the war has changed and begins training a new type of soldier.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5152, 2704, 1184, 'neutral', false, 'Is identified as the new battlefront and the source of the enemy''s power.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5153, 3970, 1184, 'big-boss', false, 'Is identified as the true enemy, whose power is being directly challenged by the new two-pronged strategy.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5154, 3969, 1185, 'ally', true, 'Repeatedly engage I AM''s forces in the dreamscape, weakening the enemy''s influence with each victory.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5155, 3971, 1185, 'enemy', false, 'Are the primary opponents faced by the Oneiromancers in the surreal dream world.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5156, 2554, 1185, 'enemy', false, 'Counter the heroes'' progress by using necromancy to resurrect their fallen, forcing a stalemate.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5157, 3972, 1185, 'enemy', false, 'Is deployed as a counter-strategy, creating an unrelenting cycle of battle.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5158, 2550, 1185, 'ally', false, 'Leads the Oneiromancers into battle night after night, establishing the new form of warfare.', '2026-02-28 17:49:15.053042-05');
INSERT INTO public.entity_beat_appearances VALUES (5159, 3974, 1186, 'neutral', true, 'Evolves from a physical conflict into a metaphysical struggle over centuries.', '2026-02-28 17:50:16.939793-05');
INSERT INTO public.entity_beat_appearances VALUES (5160, 2550, 1186, 'ally', false, 'Observes and participates in the unending conflict.', '2026-02-28 17:50:16.939793-05');
INSERT INTO public.entity_beat_appearances VALUES (5161, 2550, 1187, 'ally', true, 'Addresses his squad to counteract their exhaustion, asserting their unbroken resolve and critical role.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5162, 3983, 1187, 'ally', false, 'Listens to their commander, their collective weariness and underlying doubt evident.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5163, 579, 1187, 'mini-boss', true, 'Acts as the primary antagonist of the beat, oppressing the squad and forcing the commander to act.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5164, 3984, 1188, 'ally', true, 'Voices the squad''s core doubt by questioning how they can fight an enemy that doesn''t bleed.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5165, 2550, 1188, 'ally', true, 'Responds by defining the nature of dream-warfare as control and adaptation, and their purpose as their ultimate advantage.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5166, 3987, 1188, 'enemy', false, 'Is characterized as an abstract enemy that fights for conquest and dominion, not survival.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5167, 3985, 1189, 'ally', false, 'Cuts through the discussion to ask for the next concrete plan of action.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5168, 2550, 1189, 'ally', true, 'Declares their next move: a direct assault on the enemy''s core stronghold.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5169, 3988, 1189, 'enemy', true, 'Is named as the new objective, a place of unimaginable horror deep in the realm of nightmares.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5170, 3983, 1189, 'ally', false, 'Reacts with a sharp ripple of readiness, their weariness replaced by a new, dangerous purpose.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5171, 3990, 1188, 'ally', false, 'Raises a hesitant but fair question about the possibility of being outmatched by the enemy.', '2026-02-28 17:50:55.39588-05');
INSERT INTO public.entity_beat_appearances VALUES (5172, 3995, 1190, 'neutral', true, 'Intervene to contain the I AM by creating a second prison, Etheris.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5173, 3994, 1190, 'enemy', false, 'Is the target of the containment, being sealed within an expanded prison.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5174, 326, 1190, 'neutral', false, 'Is inadvertently severed from ethereal wisdom as a consequence of the prison''s creation.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5175, 3997, 1191, 'neutral', true, 'Become silent tombs as their connection to humanity is sealed.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5176, 326, 1191, 'ally', false, 'Loses faith in divine aid and is left to fight the demiurge alone.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5177, 3993, 1192, 'ally', false, 'In desperation, accesses the secret Dream Plane Grimoire.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5178, 3994, 1192, 'enemy', true, 'Is revealed to be an ancient, malevolent entity that traps and devours souls under the guise of a savior.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5179, 3998, 1192, 'neutral', false, 'Provides the fleeting connection that allows for the terrible revelation.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5180, 3994, 1193, 'enemy', true, 'Is revealed to have festered and grown stronger in isolation, using a fracture in existence to begin its escape.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5181, 3995, 1193, 'neutral', false, 'Their efforts to contain the entity are shown to be a temporary delay, not a permanent solution.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5182, 4001, 1193, 'neutral', false, 'Serves as the foothold for the I AM''s escape.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5183, 3993, 1194, 'ally', true, 'Realizes with absolute clarity that he himself created the breach by claiming the Eternal Engine.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5184, 456, 1194, 'neutral', false, 'Is identified as the cause of the wound in reality that freed the I AM.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5185, 3994, 1194, 'enemy', false, 'Is understood in its truest form: not an enemy, but pure hunger that will consume existence itself.', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_beat_appearances VALUES (5186, 4007, 1195, 'neutral', false, 'Cuts through the void towards the ERB, its systems straining under the pressure of the hostile environment.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5187, 982, 1195, 'neutral', false, 'Serves as the dangerous medium for the ship''s journey, where reality itself is unstable.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5188, 3970, 1195, 'enemy', true, 'Its dominion presses down on the ship, creating a suffocating, maddening pressure.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5189, 4015, 1195, 'neutral', false, 'The destination and objective, representing a desperate foothold.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5190, 2550, 1196, 'ally', false, 'Witnesses the horrific transformation of Earth, causing his hope to die.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5191, 4009, 1196, 'neutral', true, 'Revealed as a mutilated corpse world, a landscape of fused bodies and skeletal cities, serving as a testament to I AM''s power.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5192, 4010, 1197, 'mini-boss', true, 'Reveals itself as a living, breathing monument of writhing flesh and bone, pulsing with the essence of devoured souls.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5193, 4010, 1198, 'mini-boss', true, 'Pours out a wave of malice that corrupts the crew.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5194, 3619, 1198, 'ally', false, 'Succumbs to the Tower''s influence and is transformed.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5195, 4012, 1198, 'enemy', false, 'Manifests from the fallen crew members, their screams merging with the Tower''s hum.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5196, 2550, 1198, 'ally', false, 'Resists the corruption thanks to the Infinitron, but is forced into total isolation.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5197, 1201, 1198, 'ally', false, 'Shields the narrator''s mind and severs his network connections to protect him.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5198, 3970, 1199, 'big-boss', true, 'Notices the narrator''s resistance and reaches for him with its overwhelming presence, tempting him with surrender.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5199, 2550, 1199, 'ally', false, 'Fights through despair and the pull of oblivion, forcing himself forward.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5200, 4014, 1199, 'ally', false, 'Manifests as the narrator''s will to resist, becoming a final beacon against the void.', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_beat_appearances VALUES (5201, 2550, 1200, 'ally', true, 'Enters the Tower and defiantly confronts I AM, declaring his intention to destroy the tyrant.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5202, 4018, 1200, 'mini-boss', true, 'Manifests its presence through a powerful, cacophonous voice and coalescing shadows, demanding the narrator''s death and surrender.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5203, 4019, 1200, 'enemy', false, 'Acts as a conduit for I AM''s voice, with its walls vibrating and pulsing in time with the entity''s speech.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5386, 4151, 1255, 'neutral', false, 'Its control number (LCCN) is listed again as an identifier.', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.entity_beat_appearances VALUES (5204, 2550, 1201, 'ally', true, 'Engages in a violent clash, dodging reality-warping attacks and pushing back by drawing on the collective belief of his allies.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5205, 4018, 1201, 'mini-boss', true, 'Unleashes blasts of raw entropy and mocks the narrator''s reliance on faith and belief.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5206, 4020, 1201, 'ally', false, 'Are mentioned as providing metaphysical support to the narrator.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5207, 2608, 1201, 'ally', false, 'Is mentioned as a guardian shade supporting the narrator.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5208, 2550, 1202, 'ally', true, 'Unleashes a seemingly final, obliterating attack, only to be caught off guard and have his left arm severed by the reformed I AM.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5209, 4018, 1202, 'mini-boss', true, 'Is seemingly destroyed, but reforms into a larger, more monstrous form, maims the narrator, and delivers a sharp psychological accusation.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5210, 4019, 1202, 'enemy', false, 'Collapses around the narrator after his initial successful attack.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5211, 1847, 1202, 'ally', false, 'Surge to power the narrator''s attack.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5212, 1201, 1202, 'ally', false, 'Pulses to provide raw power for the narrator''s attack.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5213, 2550, 1203, 'ally', true, 'Realizing brute force is futile, he makes a deliberate choice to let go and be consumed, seeking to understand the enemy from within.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5214, 4018, 1203, 'mini-boss', true, 'Consumes the narrator, drawing him into its void.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5215, 4024, 1203, 'neutral', false, 'Becomes the new environment as the narrator is consumed and begins his internal investigation.', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_beat_appearances VALUES (5216, 2550, 1204, 'ally', true, 'Willingly descends into the void, holding onto the hope that understanding I AM from within is the only way to win.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5217, 4028, 1204, 'neutral', false, 'Their anguished cries fill the void, serving as a constant reminder of the stakes.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5218, 1515, 1204, 'mini-boss', false, 'His essence forms the void itself, a prison of insatiable hunger that the narrator enters.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5219, 1515, 1205, 'mini-boss', true, 'His tragic origin is revealed in a vision, showing how his vow corrupted him.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5220, 4029, 1205, 'neutral', false, 'Witnesses his flock''s destruction, and his shattered innocence gives birth to the entity known as I AM.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5221, 4030, 1205, 'enemy', false, 'Attacks the flock, serving as the catalyst for the Shepherd Boy''s trauma and transformation.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5222, 2550, 1206, 'ally', true, 'Overcome with compassion, he embraces I AM''s essence and merges with it, drawing the god''s immense power into himself.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5223, 1515, 1206, 'mini-boss', true, 'His consciousness and power are absorbed by the narrator in an act of compassionate understanding.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5224, 2550, 1207, 'ally', true, 'With a final surge of will, shatters the chains binding Etheris and crumbles I AM''s tyranny.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5225, 4031, 1207, 'neutral', false, 'Are shattered, symbolizing the liberation of the cosmos from I AM''s control.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5226, 4033, 1207, 'neutral', false, 'Are freed from their suffering, and their cries of despair turn into songs of liberation.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5227, 4032, 1208, 'neutral', true, 'Without I AM''s presence to sustain it, the entire fabric of reality instantly implodes.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5228, 1515, 1208, 'mini-boss', false, 'His absence is revealed to be as catastrophic as his presence, causing the destruction of everything.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5229, 4035, 1208, 'neutral', false, 'Are snuffed out in an instant by the cosmic collapse.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5230, 4034, 1208, 'neutral', false, 'Descends upon the void, marking the final, empty end of all things.', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_beat_appearances VALUES (5231, 2550, 1209, 'ally', false, 'Delivers a warning against conformity.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5232, 4042, 1209, 'neutral', true, 'Serves as the central metaphor for the conformity being warned against.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5233, 4039, 1210, 'enemy', true, 'They are the target of futile screams, unable to hear due to their ego.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5234, 982, 1210, 'neutral', false, 'Acts as the destination for the unheard warnings, symbolizing the pointlessness of the act.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5235, 4040, 1210, 'mini-boss', false, 'Actively blinds The Path-Followers, making them deaf to reason.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5236, 4045, 1211, 'enemy', true, 'Is actively maintained through the ritual offerings.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5237, 4039, 1211, 'enemy', false, 'Are the ones performing the offerings to sustain their ignorance.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5238, 4041, 1211, 'neutral', false, 'Are lined up to be sacrificed as part of the ritual.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5239, 2550, 1212, 'ally', true, 'Offers an exhortation to persevere despite the cycle of loss.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5240, 4044, 1212, 'neutral', false, 'Symbolizes the daily renewal of loss and transformation that must be accepted.', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_beat_appearances VALUES (5241, 3993, 1213, 'ally', false, 'Adrift in the void, he is overcome by the consequences of his actions.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5242, 4049, 1213, 'enemy', true, 'Assaults the protagonist with the weight of his deeds, threatening to consume him.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5243, 2550, 1213, 'neutral', false, 'Mentioned as the entity the protagonist consumed, the source of his power and guilt.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5244, 4051, 1213, 'neutral', false, 'The memory of the destroyed universe fuels the protagonist''s guilt.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5245, 3993, 1214, 'ally', false, 'Begins to feel a change within himself as memories surface.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5246, 4052, 1214, 'ally', true, 'Warm the protagonist''s heart and push back the tide of despair.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5247, 985, 1214, 'ally', false, 'Emerges as a faint glimmer within the protagonist, kindled by his memories.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5248, 3993, 1215, 'ally', true, 'Forms an unyielding resolve to reverse destruction with creation, envisioning a new universe and declaring ''Let there be light.''', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5249, 985, 1215, 'ally', false, 'Grows into a powerful resolve that fuels the protagonist''s decision.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5250, 2550, 1215, 'neutral', false, 'His power is harnessed by the protagonist for the purpose of creation.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5251, 3993, 1216, 'ally', true, 'Uses his will and imagination to conjure a new universe from nothing.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5252, 4054, 1216, 'neutral', false, 'Comes into being as a result of the protagonist''s actions.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5253, 4055, 1216, 'neutral', false, 'Burst into existence, illuminating the cosmos and forming the new universe.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5254, 3993, 1217, 'ally', true, 'Marvels at his creation but feels a deep longing, beginning his quest to find his family.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5255, 3664, 1217, 'ally', false, 'Serve as the goal of the protagonist''s new journey, the reason for his quest.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5256, 4054, 1217, 'neutral', false, 'Becomes the setting for the protagonist''s search.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5257, 4057, 1217, 'ally', false, 'Begins to guide the protagonist across the vast new cosmos.', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_beat_appearances VALUES (5258, 3993, 1218, 'ally', true, 'Realizes with horror that he is merely a passive observer in his own creation, unable to interact with it or bring his family into being.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5259, 4063, 1218, 'neutral', false, 'Serves as the backdrop for the protagonist''s realization, a world he can see but not touch.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5260, 2596, 1218, 'neutral', false, 'Their potential non-existence is the catalyst for the protagonist''s devastating realization.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5261, 3993, 1219, 'ally', true, 'Overcome by despair, he dissolves his universe and seeks guidance from Lady I in the Void.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5262, 941, 1219, 'enemy', false, 'Descends upon the protagonist, compelling him to destroy his creation.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5263, 4063, 1219, 'neutral', false, 'Is dissolved back into the protagonist''s essence.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5264, 2608, 1219, 'ally', false, 'Is sought out by the protagonist for her wisdom.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5265, 2608, 1220, 'ally', true, 'Advises the protagonist to dream backward in time to prevent the catastrophe caused by the Eternal Engine.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5266, 3993, 1220, 'ally', false, 'Receives counsel and resolves to travel into his past dreams to fix his mistake.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5267, 295, 1220, 'neutral', false, 'Identified as the catalyst for the calamity.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5268, 3993, 1221, 'ally', true, 'Doubts that altering the past is a complete solution, recognizing his eternal, problematic bond with I AM.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5269, 2550, 1221, 'mini-boss', false, 'Persists as the ultimate problem, an eternal jailer of humanity in Etheris that time travel won''t solve.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5270, 326, 1221, 'neutral', false, 'Remains enslaved by I AM, regardless of the protagonist''s actions in the past.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5271, 2536, 1221, 'neutral', false, 'The prison that contains both I AM and humanity.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5272, 2749, 1222, 'ally', true, 'Presents an alternative plan: seal the breach and build a new Eternal Engine using the collective dreams of humanity.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5273, 3993, 1222, 'ally', false, 'Considers this new, costly solution that would allow him to reunite with his family.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5274, 4070, 1222, 'neutral', false, 'The goal of the proposed plan, a solution based on collective knowledge.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5276, 4071, 1222, 'enemy', false, 'The target that must be sealed to contain I AM''s influence.', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_beat_appearances VALUES (5277, 3993, 1223, 'ally', true, 'Meditates on the complexity of the task ahead, feeling the weight of the plan.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5278, 4081, 1223, 'neutral', false, 'Serves as the mental blueprint for the protagonist''s actions, defining the delicate balance required.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5279, 2550, 1223, 'enemy', false, 'Exists as the threat that must be eradicated according to the plan.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5280, 1954, 1223, 'neutral', false, 'Identified as the domain that must be mastered to execute the plan.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5281, 3993, 1224, 'ally', true, 'Acts as a ''nocturnal whisperer'', subtly planting ideas into the minds of sleepers.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5282, 4078, 1224, 'ally', false, 'Are meticulously woven into dreams to guide waking thoughts.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5283, 4083, 1224, 'neutral', false, 'Represents a target for the protagonist''s mental influence, receiving a mix of chaotic and promising ideas.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5284, 4079, 1225, 'neutral', true, 'Awaken with a surge of inspiration, acting upon the ideas planted in their dreams.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5285, 4082, 1225, 'ally', false, 'Begins to form as the collective contributions of the innovators build a new epoch for humanity.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5286, 3993, 1226, 'ally', true, 'Remains a solitary phantom, unable to participate in the world he is shaping.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5287, 4080, 1226, 'neutral', false, 'Lingers with the protagonist as a constant reminder of the price he has paid for his actions.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5288, 3993, 1227, 'ally', true, 'Finds a semblance of tranquility in witnessing humanity''s freedom and progress.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5289, 326, 1227, 'neutral', false, 'Is seen reaching for the stars, freed from the dominion of a malevolent deity.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5290, 2550, 1227, 'enemy', false, 'His looming catastrophe has been averted, and his oppressive shadow lifted from humankind.', '2026-02-28 17:59:50.546184-05');
INSERT INTO public.entity_beat_appearances VALUES (5291, 2550, 1228, 'ally', true, 'Awakens and feels a profound sense of normalcy as the weight of his past lifts.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5292, 2549, 1228, 'ally', false, 'Her warm presence contributes to the protagonist''s sense of peace.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5293, 4087, 1228, 'ally', false, 'His chatter from the other room helps establish the domestic atmosphere.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5294, 4091, 1228, 'neutral', false, 'This burdensome weight is lifted from the protagonist''s shoulders.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5295, 2550, 1229, 'ally', true, 'Reflects on the happiness of a simple, ordinary life, free from the obligations of his past.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5296, 2297, 1229, 'neutral', false, 'Represents the protagonist''s past life and empire, which are now fading from his memory.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5297, 2549, 1230, 'ally', true, 'Rolls over with a huge grin and excitedly reveals they have won a contest.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5298, 2550, 1230, 'ally', false, 'Receives the news from his wife and experiences a brief, passing moment of déjà vu.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5299, 1042, 1230, 'neutral', false, 'Used to display the winning notification.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5300, 4089, 1230, 'neutral', false, 'The event they won, providing a trip to Lysteria.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5301, 4090, 1230, 'neutral', false, 'The destination of the won trip, which triggers a sense of familiarity in the protagonist.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5302, 4093, 1230, 'unknown', false, 'Manifests briefly in the protagonist before passing.', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_beat_appearances VALUES (5303, 2550, 1231, 'ally', true, 'Rises from bed, decides on breakfast, and begins preparing coffee in the kitchen.', '2026-02-28 18:01:41.177919-05');
INSERT INTO public.entity_beat_appearances VALUES (5304, 4104, 1231, 'neutral', false, 'Represents the protagonist''s initial pensive state of mind.', '2026-02-28 18:01:41.177919-05');
INSERT INTO public.entity_beat_appearances VALUES (5305, 4098, 1231, 'neutral', false, 'Are decided upon as the morning''s breakfast.', '2026-02-28 18:01:41.177919-05');
INSERT INTO public.entity_beat_appearances VALUES (5306, 108, 1231, 'neutral', false, 'Is brewed, its aroma filling the air.', '2026-02-28 18:01:41.177919-05');
INSERT INTO public.entity_beat_appearances VALUES (5307, 2549, 1231, 'ally', false, 'Joins her husband, offering a reassuring touch.', '2026-02-28 18:01:41.177919-05');
INSERT INTO public.entity_beat_appearances VALUES (5308, 2549, 1232, 'ally', true, 'Asks about the trip to Lysteria and makes a snarky comment about her husband''s health.', '2026-02-28 18:01:41.177919-05');
INSERT INTO public.entity_beat_appearances VALUES (5309, 4097, 1232, 'ally', true, 'Asks his father if they will encounter aliens.', '2026-02-28 18:01:41.177919-05');
