INSERT INTO public.entity_beat_appearances VALUES (5347, 4117, 1242, 'ally', true, 'Connects components in his dream, causing the Eternal Engine to materialize. He reaches out to touch it, trembling with anticipation.', '2026-02-28 18:04:05.780779-05');
