INSERT INTO public.entity_beat_appearances VALUES (5397, 4164, 1260, 'neutral', true, 'The concept of technology''s failure to deliver on its promise is the core of his bitter reflection.', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_beat_appearances VALUES (5398, 20, 1260, 'neutral', false, 'Cited as an example of his failed ambitions.', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_beat_appearances VALUES (5399, 160, 1260, 'neutral', false, 'Mentioned as a figure from his past when his dreams were still intact.', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_beat_appearances VALUES (5400, 2550, 1261, 'ally', true, 'Faces another system failure, but finds peace by focusing on a cherished memory and defiantly accepting his fate.', '2026-02-28 18:07:20.891756-05');
