INSERT INTO public.entity_beat_appearances VALUES (5414, 2550, 1264, 'ally', false, 'Reflects on the internal societal collapse caused by apathy and a lack of future.', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.entity_beat_appearances VALUES (5415, 326, 1264, 'neutral', true, 'Retreated inward, stopped having children, and lost all ambition, leading to a demographic collapse.', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.entity_beat_appearances VALUES (5416, 4178, 1264, 'neutral', false, 'Blamed for killing ambition and fostering a culture of apathy.', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.entity_beat_appearances VALUES (5417, 2550, 1265, 'ally', false, 'Experiences a series of surreal technological glitches, causing him to question his sanity and the nature of reality.', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.entity_beat_appearances VALUES (5418, 4179, 1265, 'mini-boss', true, 'Manifests on his pod''s display, on the viewport, and within AI-generated art, becoming the focal point of his anxiety.', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.entity_beat_appearances VALUES (5419, 4180, 1265, 'enemy', false, 'Begins chanting in garbled, reversed digital Latin, contributing to the unsettling atmosphere.', '2026-02-28 18:08:18.883378-05');
