INSERT INTO public.entity_beat_appearances VALUES (5421, 2550, 1266, 'ally', true, 'Accepts his impending death with resignation, reflecting on the meaninglessness of his unlived lives.', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_beat_appearances VALUES (5422, 4186, 1266, 'neutral', false, 'Dissolve into irrelevance within the narrator''s mind as he faces death.', '2026-02-28 18:09:14.221319-05');
