INSERT INTO public.entity_beat_appearances VALUES (5431, 3993, 1268, 'ally', true, 'Is struck by a powerful kick to the temple, causing his perception of reality to begin fracturing.', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_beat_appearances VALUES (5432, 4194, 1268, 'mini-boss', true, 'Delivers a full-contact heel kick to the protagonist''s head, violating the rules of the match.', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_beat_appearances VALUES (5433, 4198, 1268, 'enemy', false, 'Serves as the catalyst for the protagonist''s consciousness shattering.', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_beat_appearances VALUES (5434, 3993, 1269, 'ally', true, 'Experiences a total breakdown of his senses, convulsing as he is flooded with visions, distorted sounds, and memories from other lives.', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_beat_appearances VALUES (5435, 4196, 1269, 'enemy', true, 'Overwhelms the protagonist''s mind with chaotic sensory input, including voices, memories, and physical sensations of vomiting up dreams.', '2026-02-28 18:10:08.709858-05');
