INSERT INTO public.entity_beat_appearances VALUES (5439, 3993, 1271, 'ally', true, 'Wakes into a state of panic as his world collapses and fragmented memories from multiple realities assault him.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5440, 4201, 1271, 'enemy', true, 'Manifests as a ''wild animal'' inside the protagonist, fueling his terror.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5441, 4202, 1271, 'mini-boss', false, 'Tears through the protagonist and ''sinks claws into my thoughts,'' actively attacking his mind.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5442, 444, 1271, 'enemy', false, 'Detonates like a bomb, showing him scenes of a failed Sorhhinda dream, rusted habitats, the gym, space, and a pod.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5443, 4207, 1271, 'neutral', false, 'Holds the protagonist in place, contributing to his feeling of helplessness.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5444, 160, 1271, 'unknown', false, 'Is remembered laughing at the protagonist''s pain across different lifetimes.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5445, 4205, 1271, 'ally', false, 'Her voice is heard as a memory, providing a faint sense of being an ''anchor''.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5446, 3993, 1272, 'ally', true, 'Engages in a desperate internal dialogue, asking ''Who am I?'' to make sense of his fractured state.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5447, 4206, 1272, 'neutral', true, 'Replies to the protagonist''s question, warning him not to ''let go'' and pleading not to repeat a past mistake.', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5448, 444, 1272, 'enemy', false, 'Continues to multiply, showing visions of planetary decay, collapsing colonies, and different versions of himself (young body, old mind, dead god).', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_beat_appearances VALUES (5449, 3993, 1273, 'ally', true, 'Experiences a fractured sense of self and consciousness, struggling with his own thoughts and memories after hearing a familiar voice.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5450, 4217, 1273, 'neutral', true, 'Explodes within the protagonist''s mind, causing pain and disorientation with images of a scared old man and a young man.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5451, 2549, 1273, 'ally', false, 'Is remembered as deceased, adding to the protagonist''s confusion about the voice he hears.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5452, 4215, 1273, 'neutral', false, 'Serves as the source of the voice that triggers the protagonist''s episode.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5453, 3993, 1274, 'ally', true, 'Regains partial consciousness, observes the surreal scene with detachment and a ''new panic'', recognizes Jamie, and is overwhelmed by the encroaching shadows before passing out.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5454, 4211, 1274, 'ally', true, 'Calls out to the protagonist, her familiar face and voice cutting through the chaos and adding a layer of mystery to their relationship.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5455, 4213, 1274, 'enemy', true, 'Manifest physically, crowding in and observing both Jamie and the protagonist as his terror becomes ''pure and refined''.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5456, 251, 1274, 'neutral', false, 'Attend to the protagonist, placing him on a gurney, their appearance distorted by his perception.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5457, 4214, 1274, 'mini-boss', false, 'Whispers ''Not again,'' revealing a history with and higher understanding of the unfolding supernatural events.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5458, 4216, 1274, 'neutral', false, 'Used to restrain and transport the protagonist.', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_beat_appearances VALUES (5459, 3993, 1275, 'ally', true, 'Experiences a horrifying synesthetic episode, struggling with the dual identity of a 16-year-old and a 74-year-old before losing consciousness.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5460, 4221, 1275, 'neutral', false, 'Clinically assesses the protagonist''s condition, dismissing his confused whispers as ''head trauma babble''.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5461, 4222, 1275, 'neutral', false, 'Serves as the chaotic container for the protagonist''s sensory breakdown.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5462, 4223, 1275, 'enemy', false, 'Envelops the protagonist, pulling him into unconsciousness at the end of the beat.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5463, 4228, 1275, 'neutral', false, 'Is referenced in a synesthetic memory triggered by the color blue.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5464, 3993, 1276, 'ally', true, 'Experiences clinical death, drifts in a cold void while witnessing his past and future deaths, and is violently shocked back to life.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5465, 234, 1276, 'enemy', false, 'Acts as the environment for the protagonist''s temporary death, a space of absolute cold and nothingness.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5466, 4225, 1276, 'mini-boss', true, 'Assaults the protagonist''s consciousness with visions of his mortality across different lifetimes.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5467, 4221, 1276, 'ally', false, 'Performs life-saving measures, including chest compressions and defibrillation.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5468, 4227, 1276, 'ally', false, 'Is heard shouting to drive faster, adding to the urgency of the resuscitation effort.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5469, 4226, 1276, 'neutral', false, 'Acts as the force of revival, cracking the darkness and restarting the protagonist''s heart.', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.entity_beat_appearances VALUES (5470, 3993, 1277, 'ally', false, 'Is revived and immediately subjected to the trauma of a violent car crash.', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.entity_beat_appearances VALUES (5471, 251, 1277, 'ally', false, 'Successfully revive the protagonist but are caught in the crash, with one shouting a warning before impact.', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.entity_beat_appearances VALUES (5472, 4233, 1277, 'mini-boss', true, 'Appears suddenly and violently strikes the ambulance, initiating the crash.', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.entity_beat_appearances VALUES (5473, 4234, 1277, 'enemy', true, 'Serves as the central, chaotic action of the scene, as the ambulance rolls multiple times.', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.entity_beat_appearances VALUES (5474, 4222, 1277, 'neutral', false, 'Acts as the container for the chaos, lurching and rolling violently.', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.entity_beat_appearances VALUES (5475, 3993, 1278, 'ally', true, 'Regains consciousness pinned in the wreckage, assesses his fatal injuries, observes the other driver, and laughs as he succumbs to nothingness.', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.entity_beat_appearances VALUES (5476, 4242, 1278, 'neutral', false, 'Imprisons the protagonist and emits steam, setting the scene of the accident''s aftermath.', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.entity_beat_appearances VALUES (5477, 4244, 1278, 'neutral', false, 'Its death-wail distorts into silence, marking the end of the immediate chaos.', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.entity_beat_appearances VALUES (5478, 4240, 1278, 'neutral', false, 'Remains motionless, leading the protagonist to believe he is dead and reinforcing the severity of the situation.', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.entity_beat_appearances VALUES (5479, 4246, 1278, 'ally', false, 'Continues to beat irregularly, representing the protagonist''s tenacious but failing grip on life.', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.entity_beat_appearances VALUES (5480, 4241, 1278, 'mini-boss', false, 'Stumbles from his car, serving as the external cause of the protagonist''s plight.', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.entity_beat_appearances VALUES (5481, 4243, 1278, 'neutral', false, 'Its loss causes disorientation and ultimately leads to the protagonist losing consciousness.', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.entity_beat_appearances VALUES (5482, 4245, 1278, 'neutral', false, 'Envelops the protagonist as he finally loses his fight to stay conscious.', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.entity_beat_appearances VALUES (5483, 3993, 1279, 'ally', false, 'Wakes up and frantically writes in his notebook to ground himself amidst temporal chaos.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5484, 4249, 1279, 'enemy', true, 'Manifests as impossible and looping timestamps on the alarm clock, revealing that reality is broken.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5485, 4250, 1279, 'enemy', false, 'Serves as the focal point for the temporal corruption, transforming into a horrifying creature that bleeds.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5486, 4253, 1279, 'neutral', false, 'Acts as the tool for the protagonist''s desperate attempt to assert his own existence against the chaos.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5487, 4256, 1279, 'neutral', false, 'Emanates from the clock, adding a layer of unsettling, melancholy familiarity and foreshadowing.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5488, 3993, 1280, 'ally', false, 'Moves to his bookshelf and discovers the corruption has spread to his childhood books.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5489, 4251, 1280, 'enemy', true, 'Reveal their corrupted nature with shifting titles and flesh-like paper, deepening the protagonist''s identity crisis.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5490, 3993, 1281, 'ally', false, 'Is assaulted by mental commands and physical threats, finally collapsing as he is consumed.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5491, 4254, 1281, 'enemy', false, 'Mentally assault the protagonist, increasing the pressure and confusion.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5492, 637, 1281, 'mini-boss', true, 'Peel from the walls and physically attack the protagonist, acting as the final catalyst for reality''s collapse.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5493, 204, 1281, 'enemy', false, 'Consumes the protagonist and the room as reality folds in on itself.', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.entity_beat_appearances VALUES (5494, 3993, 1282, 'ally', false, 'Wakes up feeling physically ill and is immediately confronted with a disorienting news report.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5495, 4260, 1282, 'enemy', false, 'Causes physical pain and mental fog, making the narrator more vulnerable to the psychological shock.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5496, 4261, 1282, 'neutral', false, 'Broadcasts the news report about Nelson Mandela.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5497, 4262, 1282, 'neutral', true, 'Serves as the catalyst for the scene''s conflict, presenting a version of history that contradicts the narrator''s memory.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5498, 3993, 1283, 'ally', false, 'Discovers his journal and witnesses its contents rewriting themselves, deepening his panic.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5499, 4263, 1283, 'neutral', false, 'Acts as the medium for the shifting reality.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5500, 4264, 1283, 'mini-boss', true, 'Manifest as actively changing text, directly assaulting the narrator''s sanity and sense of a stable past.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5501, 3993, 1284, 'ally', false, 'Driven by hunger, he seeks something real but instead finds more evidence of reality''s instability. He eats anyway, swallowing the lie.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5502, 4265, 1284, 'neutral', false, 'Motivates the narrator to move to the kitchen.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5503, 4266, 1284, 'neutral', true, 'Represent the subtle, uncanny corruption of everyday objects, confirming the narrator''s fears that reality itself is wrong.', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_beat_appearances VALUES (5504, 2550, 1285, 'ally', false, 'Watches in confusion as the television operates on its own.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5505, 4269, 1285, 'neutral', true, 'Activates autonomously and begins flipping through channels, displaying impossible content.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5506, 4270, 1285, 'unknown', true, 'Manifests on the screen, showing two conflicting realities and causing disorientation.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5507, 4275, 1285, 'neutral', false, 'Sits untouched, confirming the supernatural nature of the event.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5508, 4276, 1285, 'neutral', false, 'Rewinds itself to perpetuate the reality-flipping display.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5509, 2550, 1286, 'ally', true, 'Is paralyzed by terror, physically assaulted by a shadow, and subjected to a violent psychic vision.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5510, 4271, 1286, 'enemy', true, 'Emerge from the TV, fill the room, and advance on the narrator.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5511, 4272, 1286, 'mini-boss', true, 'Makes physical contact with the narrator, triggering a paralyzing vision of death.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5512, 4273, 1286, 'enemy', false, 'Manifests alongside the shadows, intensifying the atmosphere of dread.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5513, 4274, 1286, 'enemy', false, 'Occurs as a psychic attack, showing the narrator his own gruesome end.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5514, 4269, 1286, 'enemy', false, 'Serves as the portal for the shadows and then abruptly returns to a normal broadcast.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5515, 4277, 1286, 'neutral', false, 'Appears on screen, marking the sudden and jarring end of the supernatural assault.', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.entity_beat_appearances VALUES (5516, 2550, 1287, 'ally', true, 'Turns to his journal for stability and engages in a written dialogue with his fractured self about his displacement.', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_beat_appearances VALUES (5517, 4263, 1287, 'ally', true, 'Serves as a tangible anchor and the medium for the narrator''s internal, multi-temporal conversation.', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_beat_appearances VALUES (5518, 4283, 1287, 'enemy', true, 'The subject of the journal entry and the source of the narrator''s confusion and fractured identity.', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_beat_appearances VALUES (5519, 1942, 1287, 'mini-boss', false, 'Acts as the underlying motivation for the narrator to seek solace in his journal.', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_beat_appearances VALUES (5520, 4284, 1288, 'neutral', false, 'Its opening sound acts as the trigger for the climax of fear.', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_beat_appearances VALUES (5521, 4281, 1288, 'enemy', true, 'His imminent arrival, signaled by the garage door, is the source of the narrator''s terror.', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_beat_appearances VALUES (5522, 1942, 1288, 'mini-boss', true, 'Escalates dramatically, causing a physical reaction in the narrator.', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_beat_appearances VALUES (5523, 2550, 1288, 'ally', true, 'Reacts to the sound with a spike of terror and a physiological response.', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_beat_appearances VALUES (5524, 2550, 1289, 'mini-boss', true, 'Slams the door open, his presence distorting reality, and begins a verbal assault on his son.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5525, 3993, 1289, 'ally', false, 'Is confronted by his father and becomes the target of his rage.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5526, 4292, 1289, 'neutral', false, 'Is named as the reason for the father''s anger and the family''s ''embarrassment''.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5527, 2550, 1290, 'mini-boss', true, 'Begins the physical beating, using his belt as a weapon.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5528, 3993, 1290, 'ally', false, 'Dissociates from the pain, watching the event from above as his body is beaten.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5529, 4289, 1290, 'neutral', false, 'Manifests as the narrator''s coping mechanism, splitting his consciousness.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5530, 4290, 1290, 'enemy', false, 'Is the instrument of the physical abuse.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5531, 2549, 1290, 'enemy', false, 'Appears in the doorway, watching the beating with detached passivity.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5532, 3993, 1291, 'ally', true, 'Experiences a moment of clarity and defiance, realizing his father''s limitations and choosing to delay his screams.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5533, 2550, 1291, 'mini-boss', false, 'Continues the beating, unaware of his son''s internal act of rebellion.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5534, 3993, 1292, 'ally', true, 'Finally cries out, then endures the remainder of the assault by taking solace in his knowledge of his parents'' futures.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5535, 2550, 1292, 'mini-boss', false, 'Experiences sadistic joy at his son''s cry, continues the beating until he gets bored, and then leaves.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5536, 4293, 1292, 'enemy', false, 'Manifests in the father''s eyes, revealing his perverse pleasure in his son''s pain.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5537, 4291, 1292, 'ally', false, 'Serves as the narrator''s internal shield, allowing him to endure the pain with a sense of ultimate victory.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5538, 2549, 1292, 'enemy', false, 'Loses interest and leaves with her husband.', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_beat_appearances VALUES (5539, 2550, 1293, 'ally', true, 'Patches himself up with bandages and spite, endures the effects of his concussion, and sits on his bed, where he discovers a mysterious note in his journal.', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.entity_beat_appearances VALUES (5540, 4298, 1293, 'enemy', false, 'Actively disorients the narrator, causing his ears to ring and the room to spin.', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.entity_beat_appearances VALUES (5541, 4296, 1293, 'neutral', false, 'Used by the narrator to treat his physical injuries.', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.entity_beat_appearances VALUES (5542, 4297, 1293, 'neutral', false, 'Acts as a metaphorical force giving the narrator the will to patch himself up.', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.entity_beat_appearances VALUES (5543, 4301, 1293, 'neutral', false, 'Provides a place for the narrator to sit and experience his first moment of solitude.', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.entity_beat_appearances VALUES (5544, 4263, 1293, 'neutral', false, 'Lies open on the bed, presenting a mysterious note to the narrator.', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.entity_beat_appearances VALUES (5545, 4300, 1293, 'unknown', false, 'Appears in the journal, introducing a cryptic warning and an element of mystery.', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.entity_beat_appearances VALUES (5546, 3993, 1294, 'ally', true, 'Wakes up in agony, relives trauma, and is struck by the horrifying realization that he has a biology test.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5547, 4304, 1294, 'enemy', true, 'Dominates the narrator''s physical state, making every movement an ordeal.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5548, 4305, 1294, 'enemy', false, 'Plays in the narrator''s mind upon waking.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5549, 4306, 1294, 'enemy', false, 'The realization of its existence hits the narrator with devastating force.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5550, 4309, 1294, 'mini-boss', true, 'Cuts through the physical pain, becoming the primary source of torment due to the threat of his father''s reaction.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5551, 2550, 1294, 'enemy', false, 'Mentioned as the ultimate source of the fear, who will deliver the ''main course'' of punishment for failure.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (6206, 4776, 1438, 'enemy', false, 'Acts as the underlying predatory force driving Jamie''s seductive actions.', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.entity_beat_appearances VALUES (5552, 3993, 1295, 'ally', true, 'Struggles with the paradox of having lived through this and learned the material, yet being unable to remember it now, which leads to an explosion of rage.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5553, 4310, 1295, 'neutral', false, 'Serves as the physical representation of the knowledge he cannot access.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5554, 410, 1295, 'neutral', true, 'Erupts from the narrator as the culmination of his physical pain, fear, and intense frustration.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5555, 4173, 1295, 'enemy', true, 'Becomes the target of the narrator''s rage, blamed for stealing his knowledge and forcing him to relive this ''nightmare''.', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.entity_beat_appearances VALUES (5556, 3993, 1296, 'ally', true, 'Feeling desperate about his test and disconnected from his own knowledge, he calls Jamie at 2:19 AM.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5557, 4211, 1296, 'ally', false, 'Answers the phone and expresses immediate concern for the narrator''s well-being after his concussion.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5558, 4318, 1296, 'neutral', false, 'Acts as the conduit for their conversation.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5559, 4211, 1297, 'ally', true, 'Offers to stay up and help the narrator study using her notes, creating a moment of profound connection.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5560, 4319, 1297, 'neutral', false, 'Manifests in the silence between them, described as a ''live wire''.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5561, 3993, 1297, 'ally', false, 'Is taken aback by her kindness and grapples with the nature of their relationship.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5562, 4211, 1298, 'ally', true, 'Demonstrates her deep understanding of the narrator by correctly guessing he''s not writing notes, based on the sounds he makes.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5563, 3993, 1298, 'ally', false, 'Feels a mix of terror and wonder at being known so well, which conflicts with his fragmented memories of their relationship.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5564, 4211, 1299, 'ally', false, 'Continues to explain biology, her voice growing softer with exhaustion, creating a rhythmic, comforting sound.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5565, 3993, 1299, 'ally', true, 'Falls deeper into appreciation for her presence, focusing on the connection between them rather than the academic material.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5566, 4211, 1300, 'ally', true, 'Asks the narrator if he ever feels like he''s living the wrong life, unknowingly touching upon the central truth of his existence.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5567, 4320, 1300, 'neutral', false, 'Is introduced as a shared feeling, bridging the gap between Jamie''s teenage angst and the narrator''s dimensional crisis.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5568, 3993, 1300, 'ally', false, 'Agrees with her, finding a moment of profound, shared vulnerability.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5569, 4211, 1301, 'ally', false, 'Exchanges affectionate goodbyes and tells the narrator he''s ''tougher than you think,'' leaving him with a sense of hope.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5570, 3993, 1301, 'ally', true, 'Hangs up the phone feeling more alive and hopeful, despite the looming threats of the test and his father.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (5571, 2550, 1301, 'enemy', false, 'Remains as a lingering threat that the narrator must face after the call ends.', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_beat_appearances VALUES (6984, 5348, 1637, 'neutral', false, 'Convulses, fractures, and refolds as timelines are compressed.', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_beat_appearances VALUES (5572, 3993, 1302, 'ally', true, 'Goes through his mundane Monday morning routine, observing his injuries with a sense of detachment.', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.entity_beat_appearances VALUES (5573, 4331, 1302, 'neutral', false, 'Appear worse in the mirror than they felt, serving as a physical reminder of the weekend''s tournament.', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.entity_beat_appearances VALUES (5574, 3993, 1303, 'ally', true, 'Arrives at school and is confronted by his friends, who are concerned about his bruised face.', '2026-02-28 18:21:18.761858-05');
