INSERT INTO public.entity_beat_appearances VALUES (5579, 4211, 1304, 'ally', false, 'Touches Stephen''s arm, a possessive gesture that escalates the non-verbal conflict with Becca.', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.entity_beat_appearances VALUES (5580, 2882, 1304, 'ally', false, 'Counters Jamie''s physical contact by moving closer to Stephen and inviting him to lunch.', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.entity_beat_appearances VALUES (5581, 4330, 1305, 'mini-boss', true, 'Overwhelms Stephen, preventing him from responding to the girls'' offers of cookies and company, causing him to miss the opportunity.', '2026-02-28 18:21:18.761858-05');
