INSERT INTO public.entity_beat_appearances VALUES (6985, 5367, 1637, 'mini-boss', true, 'Refuses to be erased by the rollback, persisting like a stubborn infection and contaminating the restored reality.', '2026-02-28 22:18:26.71525-05');
