INSERT INTO public.entity_beat_appearances VALUES (6988, 5366, 1638, 'enemy', true, 'Twitches in response to the anomaly and begins to spontaneously write a new, unregistered process into existence.', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_beat_appearances VALUES (6989, 5367, 1638, 'mini-boss', false, 'Its persistent humming rhythm triggers a responsive evolution within The System.', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_beat_appearances VALUES (6990, 5368, 1638, 'enemy', false, 'Begins to emerge, shifting the system''s parameters and undermining Yaldabaoth''s authority.', '2026-02-28 22:18:26.71525-05');
