INSERT INTO public.entity_beat_appearances VALUES (6999, 2550, 1641, 'ally', true, 'Realizes his absolute prison has been penetrated and reacts with rage.', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_beat_appearances VALUES (7000, 5375, 1641, 'neutral', false, 'Is channeled through the system, causing it to shudder and scream in protest.', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_beat_appearances VALUES (5586, 4329, 1305, 'neutral', false, 'Mentally screams at his younger self to take action, highlighting the cowardice and inaction.', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.entity_beat_appearances VALUES (5602, 3993, 1306, 'ally', true, 'Arrives just in time for class, reflects on a conversation with friends, and settles in for a test.', '2026-02-28 18:22:18.394996-05');
