INSERT INTO public.entity_beat_appearances VALUES (5609, 4338, 1307, 'mini-boss', true, 'Violently assaults Stephen''s senses, causing him to experience a terrifying fall from collapsing scaffolding and physically collapse.', '2026-02-28 18:22:18.394996-05');
