INSERT INTO public.entity_beat_appearances VALUES (5614, 4308, 1308, 'neutral', false, 'Appears to be by Stephen''s side showing concern, but then is suddenly back at the front of the class as if nothing happened, creating a sense of unreality.', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.entity_beat_appearances VALUES (5615, 4211, 1308, 'ally', false, 'Stares at Stephen with a worried expression after his collapse.', '2026-02-28 18:22:18.394996-05');
