INSERT INTO public.entity_beat_appearances VALUES (5618, 3993, 1309, 'ally', false, 'Arrives at the table and is immediately put in the middle of a friendly rivalry between Jamie and Becca.', '2026-02-28 18:23:01.002886-05');
