INSERT INTO public.entity_beat_appearances VALUES (5661, 4211, 1319, 'ally', true, 'Flirtatiously talks to Stephen, using their recent Magic game as a thinly veiled metaphor for her romantic interest in him.', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.entity_beat_appearances VALUES (5662, 3993, 1319, 'ally', false, 'Responds to Jamie''s advances literally, completely missing the romantic subtext and focusing on game mechanics.', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.entity_beat_appearances VALUES (5663, 4353, 1319, 'neutral', false, 'Serves as the central topic of conversation, interpreted very differently by Jamie and Stephen.', '2026-02-28 18:24:40.738767-05');
