INSERT INTO public.entity_beat_appearances VALUES (5671, 4391, 1322, 'ally', true, 'Drives the Corvette and experiences the intimate, seductive touches of Jamie and Becca, fulfilling a deep-seated desire.', '2026-02-28 18:25:31.010103-05');
