INSERT INTO public.entity_beat_appearances VALUES (5675, 4392, 1323, 'mini-boss', true, 'The Corvette slams into a causeway wall, violently killing the occupants and ending the dream.', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.entity_beat_appearances VALUES (5676, 4391, 1323, 'ally', false, 'Loses control of the car and is impaled by the steering column, dying while still being touched by Jamie and Becca.', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.entity_beat_appearances VALUES (5677, 4211, 1323, 'neutral', false, 'Her voice turns sharp with fear before she is killed in the impact.', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.entity_beat_appearances VALUES (5678, 2882, 1323, 'neutral', false, 'Is killed in the impact, her teeth still on Stephen''s neck.', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.entity_beat_appearances VALUES (5679, 3993, 1324, 'ally', true, 'Wakes violently from the dream and has a moment of crystalline clarity about the source of his visions.', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.entity_beat_appearances VALUES (5681, 4388, 1324, 'neutral', false, 'Becomes a place of grim realization, smelling of ''old regret''.', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.entity_beat_appearances VALUES (5682, 4404, 1325, 'ally', true, 'The group is described as recovering from substance use, scattered throughout the chaotic but luxurious basement.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5683, 4408, 1325, 'neutral', false, 'The state of the basement is described, reflecting the group''s contradictory nature.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5684, 3993, 1325, 'ally', false, 'Observes and narrates the scene, feeling the comforting nature of the mess.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5685, 3993, 1326, 'ally', true, 'Observes the positions and interactions of his friends, specifically noting the physical intimacy initiated by Jamie and Becca.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5686, 4211, 1326, 'ally', false, 'Positions herself against the narrator''s thigh, beginning her claim.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5687, 2882, 1326, 'ally', false, 'Mirrors Jamie on the narrator''s other side, brushing his arm to stake her claim.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5688, 2896, 1326, 'ally', false, 'Observes everyone with quiet intensity.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5689, 4342, 1326, 'ally', false, 'Sits in her corner with her grimoires, watching.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5690, 2884, 1326, 'ally', false, 'Is animatedly talking about a conspiracy theory, oblivious to the building tension.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5691, 2474, 1326, 'ally', false, 'Laughs at TJ''s story, touching his shoulder.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5692, 4406, 1327, 'neutral', true, 'The unspoken conflict between Jamie and Becca escalates through competitive touch and dialogue.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5693, 4211, 1327, 'ally', false, 'Leans close to the narrator, tracing patterns on his wrist and verbally challenging Becca.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5694, 2882, 1327, 'ally', false, 'Tightens her grip on the narrator''s knee and slides a hand onto his shoulder in response to Jamie.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5695, 3993, 1327, 'ally', false, 'Is the passive center of the conflict, feeling like a ''wishbone at Thanksgiving''.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5696, 4211, 1328, 'ally', true, 'After a brief power struggle with Becca, she takes control of the bottle from TJ and spins it with theatrical precision.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5697, 4407, 1328, 'neutral', false, 'Becomes the focal point of the game, spun to decide ''fate''.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5698, 2884, 1328, 'ally', false, 'Suggests the game and wisely hands the bottle to Jamie to de-escalate the tension between her and Becca.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5699, 2882, 1328, 'ally', false, 'Challenges Jamie but loses the initiative to spin first.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5700, 4405, 1329, 'mini-boss', true, 'Detonates inside the narrator''s skull just as Jamie is about to kiss him, causing a violent convulsion.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5701, 3993, 1329, 'ally', false, 'Is physically thrown backward by the force of the internal psychic attack, screaming in agony and confusion.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5702, 4211, 1329, 'ally', false, 'Is moving in to claim her kiss when the narrator convulses away from her, leaving her shocked and hurt.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5703, 4404, 1330, 'ally', true, 'The entire group gathers around the narrator, their previous activities and conflicts forgotten in the face of his distress.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5704, 4211, 1330, 'ally', false, 'Sets aside her frustration and irritation to kneel beside the narrator, offering gentle, protective comfort.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5705, 2882, 1330, 'ally', false, 'Forgets her rivalry with Jamie and offers steady, grounding support to the narrator.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5706, 3993, 1330, 'ally', false, 'Insists he has something urgent to tell them all, cutting through the shock with a new purpose.', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.entity_beat_appearances VALUES (5707, 3993, 1331, 'ally', true, 'Declares ''When I was eight, I died'' and begins to describe how his mother was poisoning him.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5708, 2549, 1331, 'enemy', false, 'Mentioned as the one who administered the ''special medicine'' that was actually poison.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5709, 4211, 1331, 'ally', false, 'Reacts with shock and moves to sit beside the narrator, placing a hand on his knee.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5710, 2882, 1331, 'ally', false, 'Hesitates before sitting on the narrator''s other side.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5711, 2884, 1331, 'ally', false, 'Interrupts to ask for clarification: ''Your mom was poisoning you?''', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5712, 3993, 1332, 'ally', true, 'Describes his physical deterioration, hospitalization, and being resuscitated after twelve minutes of cardiac arrest.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5713, 4342, 1332, 'ally', false, 'Reacts with shock to the ''twelve minutes'', dropping her grimoires.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5714, 2896, 1332, 'ally', false, 'Lets his cigarette burn out unnoticed while listening, expressing his horror.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5715, 3993, 1333, 'ally', true, 'Describes the void and the entity he encountered, and then blurts out the name ''Benji''.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5716, 4342, 1333, 'ally', false, 'Asks the narrator what he dreamed or saw while he was dead.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5717, 4419, 1333, 'mini-boss', false, 'Described as a nightmarish figure waiting in the void that called the narrator by a forgotten name.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5718, 4421, 1333, 'unknown', false, 'The name is suddenly recalled and spoken aloud by the narrator, hanging in the air.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5719, 4420, 1334, 'neutral', true, 'Presented by the narrator as the sole proof that his experience and forgotten past were real.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5720, 3993, 1334, 'ally', false, 'Pulls the photo from his journal to counter the skepticism of his friends.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5721, 2896, 1334, 'ally', false, 'Suggests the narrator''s experience could have been a hallucination from his brain shutting down.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5722, 2884, 1334, 'ally', false, 'Questions the reality of the narrator''s vision.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5723, 4420, 1335, 'neutral', true, 'Passed around the group, prompting discussion about the poverty and desperation it depicts.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5724, 4423, 1335, 'neutral', false, 'Identified in the photo as the family''s squatted home.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5725, 3993, 1335, 'ally', false, 'Explains the context of the photo: their homelessness, his father''s theft, and the family squatting in the trailer.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5726, 2550, 1335, 'enemy', false, 'Mentioned as having stolen the junk around the trailer and later denying Nevada ever existed.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5727, 4211, 1335, 'ally', false, 'Examines the photo and comments on the look in the narrator''s eyes.', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.entity_beat_appearances VALUES (5728, 3993, 1336, 'ally', true, 'Explains his theory about dimension-hopping and the entity from the void that he believes is hunting them.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5729, 4435, 1336, 'enemy', false, 'Is identified by the narrator as the ultimate threat that is ''coming for all of them''.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5730, 4432, 1337, 'enemy', true, 'Erupts at full volume, broadcasting the paranormal children''s show.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5731, 4433, 1337, 'mini-boss', true, 'Appears on screen, screams its name, and reveals its sentient, horrifying nature with human teeth, terrifying the group.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5732, 3993, 1337, 'ally', false, 'Reacts with terror to the broadcast.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5733, 4211, 1337, 'ally', false, 'Reacts with terror, grabbing the narrator tighter.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5734, 2882, 1337, 'ally', false, 'Stumbles backward in fear.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5735, 2884, 1337, 'ally', false, 'Dives for the remote in a panicked attempt to stop the noise.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5736, 2896, 1337, 'ally', false, 'Runs to the TV to try and unplug it.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5737, 2896, 1338, 'ally', true, 'Discovers the TV is unplugged and, using the pool cue, smashes the back of the set to silence it.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5738, 2882, 1338, 'ally', false, 'Quickly grabs a pool cue and gives it to Patrick, enabling him to stop the television.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5739, 4434, 1338, 'neutral', false, 'Used as a tool to destroy the television''s internal components.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5740, 4432, 1338, 'enemy', false, 'Is physically destroyed and finally silenced.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5741, 3993, 1338, 'ally', false, 'Stands in stunned silence with the others, processing the terrifying event and its implications.', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.entity_beat_appearances VALUES (5742, 3993, 1339, 'ally', false, 'Exhausted, he examines his journal with Jamie and Whitney.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5743, 4211, 1339, 'ally', false, 'Curls against the narrator for comfort while looking through the journal.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5744, 4342, 1339, 'ally', false, 'Joins the others on the floor, examining the journal.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5745, 2896, 1339, 'ally', true, 'Notices Becca''s distress and moves to comfort her, initiating a connection.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5746, 2882, 1339, 'ally', false, 'Is comforted by Patrick, and her perception of him begins to change.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5747, 3993, 1340, 'ally', true, 'Discovers binding sigils and entries in his journal that he doesn''t remember, sparking his confusion and fear.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5748, 4444, 1340, 'neutral', false, 'Serves as the catalyst, revealing impossible information that contradicts the narrator''s memory.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5749, 4342, 1340, 'ally', false, 'Identifies a symbol in the journal as a binding sigil for lost souls.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5750, 4211, 1340, 'ally', false, 'Points out the mysterious entry to the narrator.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5751, 4342, 1341, 'ally', true, 'Reveals that she and Patrick have been having death visions and dreams of being other people, proposing they have all been switched between dimensions.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5753, 2896, 1341, 'ally', false, 'Confirms the shared experience of the visions and theorizes it''s why they found each other.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5754, 3993, 1341, 'ally', false, 'Listens to Whitney''s confession, which validates his own impossible theory.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5755, 4447, 1342, 'ally', true, 'The group collectively agrees on a new, unifying purpose: to find the narrator''s original self.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5756, 4211, 1342, 'ally', false, 'Articulates the quest first, providing a surge of hope and determination.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5757, 4446, 1342, 'ally', false, 'Becomes the focal point of the group''s quest, representing their collective hope for returning home.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5758, 3993, 1342, 'ally', false, 'Proposes the toast to finding home, accepting his role in the quest.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5759, 4342, 1342, 'ally', false, 'Echoes the toast, committing to the quest.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5760, 2896, 1342, 'ally', false, 'Participates in the decision, solidifying the group''s unity.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5761, 2882, 1342, 'ally', false, 'Returns with Patrick and joins the newly formed pact.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5762, 2474, 1339, 'ally', false, 'Attempts to flirt with TJ.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5763, 2884, 1339, 'ally', false, 'Completely misses Morgan''s romantic cues, instead focusing on the philosophical implications of their situation.', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_beat_appearances VALUES (5764, 2896, 1343, 'ally', true, 'Notices the time on the sound system and complains about the late hour and his homework, breaking the group''s focus.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5765, 4456, 1343, 'neutral', false, 'Displays the time (11:47 PM), prompting Patrick''s outburst.', '2026-02-28 18:30:11.029133-05');
