INSERT INTO public.entity_beat_appearances VALUES (5767, 4211, 1343, 'ally', false, 'Suggests a sleepover on Friday to continue their work.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5768, 2884, 1343, 'ally', false, 'Confirms he can host the sleepover in his basement.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5769, 4458, 1343, 'neutral', false, 'Is established as the group''s plan for continuing their investigation.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5770, 4459, 1343, 'unknown', false, 'Is the reason for the group''s planning and Whitney''s research.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5771, 3993, 1343, 'ally', false, 'Observes the group''s planning and agrees to the Friday meeting.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5772, 4211, 1344, 'ally', true, 'Shares an intimate hug with the narrator that is about to escalate into a kiss.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5773, 3993, 1344, 'ally', true, 'Reciprocates Jamie''s affection, leaning in for a kiss.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5774, 2882, 1344, 'mini-boss', true, 'Interrupts the moment by sharply calling Jamie''s name and announcing her mother''s arrival with a knowing smirk.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5775, 4455, 1344, 'neutral', false, 'Her arrival (and honking horn) provides the pretext for Becca''s interruption.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5776, 2896, 1344, 'ally', false, 'Stands with Becca, his arm over her shoulder, acting as a silent partner in the interruption.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5777, 4460, 1344, 'enemy', false, 'Manifests through Becca''s power play, shattering the intimate moment and establishing a rivalry.', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.entity_beat_appearances VALUES (5778, 3993, 1345, 'ally', false, 'Arrives at the basement and observes his friends preparing for the ritual, making a wry comment about their plan.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5779, 2884, 1345, 'ally', false, 'Hosts the group and drinks imported beer, replying to the narrator''s comment.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5780, 4342, 1345, 'ally', true, 'Meticulously arranges candles for the ritual, setting the scene.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5781, 4211, 1346, 'ally', true, 'Moves close to the narrator on the couch, touches his knee, and reminds him of their ''unfinished business'' from a game of Spin the Bottle.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5782, 3993, 1346, 'ally', false, 'Reacts with confusion, then embarrassment and physical arousal to Jamie''s advances, his concussion adding to his disorientation.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5783, 4473, 1346, 'neutral', false, 'Manifests strongly between Jamie and the narrator, described as ''playfully dangerous''.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5784, 2882, 1346, 'ally', false, 'Interrupts the moment between Jamie and the narrator by calling Jamie away for a ''girl emergency''.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5785, 2896, 1347, 'ally', false, 'Flirts with Becca while carving symbols into plywood with a hunting knife and discusses the ritual instructions from the BBS.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5786, 2882, 1347, 'ally', false, 'Flirts back with Patrick, questions the source of the instructions, and expresses nervousness about her parents finding out.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5787, 4471, 1347, 'neutral', false, 'Is presented by Patrick as the source of their forbidden knowledge.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5788, 4469, 1347, 'enemy', true, 'Intensifies, causing the narrator''s head to pound and his vision to distort the candlelight into dancing, jagged shapes.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5789, 3993, 1347, 'ally', false, 'Experiences a severe spike in pain and disorientation from his injury, but is grounded by Jamie''s touch.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5790, 4211, 1347, 'ally', false, 'Returns to the narrator, expresses concern for his well-being, and touches his hand, grounding him.', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.entity_beat_appearances VALUES (5791, 4342, 1348, 'ally', true, 'Spreads her tarot cards and delivers a solemn warning about the ritual''s permanent consequences.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5792, 4484, 1348, 'neutral', false, 'Acts as the focal point for the ritual''s beginning, appearing strangely aged and magical.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5793, 2882, 1348, 'ally', false, 'Expresses fear of the ritual and its consequences, clutching her cross necklace for comfort.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5794, 2884, 1348, 'ally', false, 'Dismisses Becca''s fears with sarcasm while opening a beer.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5795, 3993, 1348, 'ally', false, 'Observes the scene, noting the strange properties of the tarot cards.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5796, 4342, 1349, 'ally', true, 'Creates the protective salt circle with deliberate precision.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5797, 4485, 1349, 'neutral', false, 'Is completed, defining the sacred and protected space for the ritual.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5798, 4486, 1349, 'neutral', true, 'Stretch and then freeze solid, providing the first undeniable proof of a supernatural occurrence.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5799, 2882, 1349, 'ally', false, 'Whispers in fear at the sight of the frozen flames and leans on Patrick for support.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5800, 2896, 1349, 'ally', false, 'Comforts Becca and expresses reckless excitement about the unknown, smoking a clove cigarette.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5801, 4487, 1349, 'mini-boss', true, 'Manifests as a sudden drop in temperature and a mocking laugh from the darkness beyond the circle.', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.entity_beat_appearances VALUES (5802, 4498, 1350, 'enemy', true, 'The event begins as the chanting causes reality to crack, walls to leak fluid, and the friends'' bodies to begin their violent mutations.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5803, 4342, 1350, 'ally', false, 'Leads the chanting that triggers the event.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5804, 2884, 1350, 'ally', false, 'His body begins to mutate, with his blood turning purple and glass shards crawling up his arm.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5805, 2882, 1350, 'ally', false, 'Her prayerful voice distorts and her rosary snaps as her transformation begins.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5806, 4211, 1350, 'ally', false, 'Begins convulsing violently and vomiting liquid darkness.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5807, 3993, 1351, 'ally', true, 'His consciousness tears loose from his body, and he perceives his friends'' suffering through a new medium.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5808, 4499, 1351, 'neutral', false, 'Serve as the conduits connecting the narrator''s consciousness to the agony of his transforming friends, transmitting their terror directly to him.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5809, 4342, 1351, 'ally', false, 'Her transformation is perceived as searing light and fire through her silver thread.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5810, 4342, 1352, 'mini-boss', true, 'Her transformation culminates in her becoming a being of eternal fire, trapped in a cycle of death and rebirth while shrieking in agony.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5811, 4501, 1352, 'enemy', false, 'Erupts from the floor, vomiting impossible calendars and contributing to the temporal and sensory chaos.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5812, 4502, 1352, 'enemy', false, 'Announces the nature of the event, naming it the ''resonance bleed'' and confirming it is a response to the friends'' actions.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5813, 4498, 1352, 'enemy', false, 'The landscape fully transforms into impossible geometry and multiplying mirrors showing endless deaths.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5814, 4499, 1353, 'neutral', true, 'The threads connecting the narrator to his friends stretch taut and snap one by one, signifying the permanent loss of each friend.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5815, 4500, 1353, 'enemy', false, 'Fills the collapsing space, rising to engulf the narrator as the last thread breaks.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5816, 4211, 1353, 'ally', false, 'Her thread is the last to snap, and its breaking feels to the narrator like a part of his soul tearing away.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5817, 3993, 1353, 'ally', false, 'Is left alone in the encroaching darkness after all his connections to his friends are severed.', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_beat_appearances VALUES (5818, 3993, 1354, 'ally', true, 'Awakens in a strange, DMV-like waiting room, disoriented and confused after a traumatic experience.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5819, 4505, 1354, 'ally', false, 'Introduces himself as a Dimensional Interlocutor and expresses relief that the narrator is coherent. He offers a handshake and a juice box.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5820, 4509, 1354, 'neutral', false, 'Offered by Benji as a comforting measure, but the first one tastes like the narrator''s childhood trauma, revealing a deeper connection to his psyche.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5858, 4540, 1361, 'neutral', false, 'Discovered by TJ, their unsettlingly neat state prompts the group to get dressed, ending their vulnerable state.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5821, 4505, 1355, 'ally', true, 'Explains that the narrator is ''leaking'' between realities and has been classified as a Category Five Existential Hazard, detailing the dangers of breaking through The Veil.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5822, 3993, 1355, 'ally', false, 'Listens in a state of escalating shock and disbelief, trying to comprehend the cosmic scale of his situation.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5823, 2610, 1355, 'enemy', false, 'Mentioned as the barrier that people usually fail to survive breaking through, and whose ''compression rate'' is poor, contributing to the current crisis.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5824, 4505, 1356, 'ally', true, 'Reveals the origin of the narrator''s condition: a traumatic death at age eight that created a fracture, leading to a cascade of broken timelines and making him a cosmic glitch.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5825, 3993, 1356, 'ally', false, 'Receives the devastating history of his own existence across millions of years, learning that his entire life is an anomaly.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5826, 4510, 1356, 'big-boss', false, 'Mentioned as the central prisoner of the realm, whose containment system the narrator is inadvertently breaking.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5827, 2608, 1356, 'ally', false, 'Mentioned as Benji''s boss, who is orchestrating this attempt to understand and aid the narrator.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5828, 4505, 1357, 'ally', false, 'Attempts to give the narrator several tools and pieces of information to help him survive, but his efforts are thwarted.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5829, 2610, 1357, 'enemy', true, 'Actively corrupts every gift Benji tries to provide—the stone, the stabilization technique, and the warning—demonstrating its power as an antagonist.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5830, 3993, 1357, 'ally', false, 'Receives the corrupted gifts, grasping only fragments of their intended purpose as the reality of the waiting room collapses around him.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5831, 4512, 1357, 'neutral', false, 'Given to the narrator, but its signal is immediately dampened and inverted by The Veil, rendering it almost useless.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5832, 4513, 1357, 'neutral', false, 'Delivered via a crumbling fortune cookie, it is the one piece of aid that transmits its core message successfully.', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_beat_appearances VALUES (5833, 3993, 1358, 'ally', true, 'Regains consciousness and assesses the horrifying, surreal situation, checking on his friends.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5834, 4516, 1358, 'ally', false, 'Serve as the vulnerable, unconscious victims of the scene, establishing the stakes.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5835, 4523, 1358, 'enemy', true, 'Establishes the initial sense of dread and wrongness with its distorted proportions and unsettling atmosphere.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5836, 4211, 1358, 'ally', false, 'Is checked on by the narrator; her cold skin highlights the danger.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5837, 2884, 1358, 'ally', false, 'Is checked on by the narrator; his fever and strange muttering add to the mystery.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5838, 4524, 1359, 'neutral', false, 'Inexplicably turns on, channeling Benji''s voice and later an unearthly lullaby.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5839, 4505, 1359, 'ally', false, 'His voice crackles from the TV, providing a surreal link to a past event.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5840, 2882, 1359, 'ally', false, 'Her body is briefly hijacked by an alien consciousness.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5841, 4526, 1359, 'enemy', true, 'Speaks through Becca and performs a disturbing, intimate act on Patrick.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5842, 2896, 1359, 'ally', false, 'Undergoes a brief physical transformation and is the subject of the possessed Becca''s attention.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5843, 4523, 1359, 'enemy', false, 'Its walls begin to ripple and shift, revealing glimpses of a horrific otherworld.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5844, 4525, 1359, 'mini-boss', true, 'Emerge from the corners to become the scene''s ultimate threat, attacking and possessing Jamie.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5845, 4211, 1359, 'ally', false, 'Becomes the vessel for The Hungering Shadows.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5846, 3993, 1359, 'ally', false, 'Powerlessly witnesses the final possession before losing consciousness.', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_beat_appearances VALUES (5847, 3993, 1360, 'ally', false, 'Observes the others waking up, aware that he is the only one who remembers what happened.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5848, 2945, 1360, 'ally', true, 'The group wakes up one by one, naked and disoriented, with no memory of the summoning.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5849, 2884, 1360, 'ally', false, 'Wakes first and questions the situation, particularly the absence of their clothes.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5850, 4342, 1360, 'ally', false, 'Offers a dreamy, supernatural explanation for their missing clothes.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5851, 2882, 1360, 'ally', false, 'Wakes with a start in an embarrassing position but seems secretly pleased.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5852, 2896, 1360, 'ally', false, 'Remains calm and speculates they were ''gone somewhere''.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5853, 4485, 1360, 'neutral', false, 'Defines the boundary of the supernatural event, inside which the group is naked and outside of which everything is normal.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5854, 4543, 1360, 'mini-boss', false, 'Permeates the basement, establishing the unsettling and ''wrong'' atmosphere of the scene.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5855, 4211, 1361, 'ally', true, 'Wakes last and displays a changed, intense demeanor, expressing a new connection to the narrator.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5856, 3993, 1361, 'ally', false, 'Becomes the focus of Jamie''s new attention and discovers the change in the obsidian stone.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5857, 4539, 1361, 'neutral', true, 'Flares with a brilliant white light before crumbling to dust in the narrator''s hand, signifying its power is spent.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (7001, 2550, 1642, 'neutral', true, 'Experiences a sudden, shocking revelation about the true nature of his existence and imprisonment.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (7002, 5381, 1642, 'neutral', true, 'Acts as the catalyst, flooding Yaldabaoth''s awareness with the suppressed truth of his defeat and confinement.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (7003, 5379, 1642, 'mini-boss', false, 'Is revealed in the memories as the architect of Yaldabaoth''s prison and the source of his judgment.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (7004, 2536, 1642, 'neutral', false, 'Is revealed to be a cage, not a creation.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (7005, 2550, 1643, 'neutral', true, 'Transforms his rage into a focused sense of opportunity upon recognizing the breach as an escape route.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (5859, 4369, 1362, 'neutral', true, 'Appears unexpectedly and offers maternal comfort, tea, and sleeping arrangements, grounding the supernatural horror in mundane reality.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5860, 2945, 1362, 'ally', false, 'Collapse onto the furniture, exhausted, and accept Nana''s offer of care.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5861, 2884, 1362, 'ally', false, 'Responds to his Nana, confirming the group''s exhaustion.', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_beat_appearances VALUES (5877, 4548, 1363, 'ally', true, 'Meets with obsessive urgency, chasing the initial high of their supernatural discovery through constant communication.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5878, 3993, 1363, 'ally', false, 'Participates in the intense, round-the-clock investigation sessions.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5879, 4549, 1364, 'neutral', true, 'Members like Gil and James abandon the group, providing excuses like ''college prep'' and ''mental health concerns'' to distance themselves.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5880, 4548, 1364, 'neutral', false, 'Begins to fracture as skeptical members depart.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5881, 4211, 1365, 'mini-boss', true, 'Manipulatively accepts blame for TJ''s grounding, offering an explanation about wind-blown papers that contradicts Stephen''s memory of the events, planting seeds of doubt and appearing overly caring.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5882, 2884, 1365, 'ally', false, 'His expression softens, accepting Jamie''s false apology.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5883, 3993, 1365, 'ally', false, 'Feels a nagging suspicion about Jamie''s story but is impressed by her apparent concern for the group.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5884, 3993, 1366, 'ally', true, 'Attempts to discuss new findings about the shadows being ''suppressors'' but is met with open skepticism and dismissal.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5885, 4549, 1366, 'neutral', false, 'Gil and Andrew interrupt and counter Stephen''s theories, widening the divide in the group.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5886, 4271, 1366, 'enemy', false, 'Are identified as suppressive reality filters that have learned to hide from the group''s observation.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5887, 4211, 1367, 'mini-boss', true, 'Strategically proposes they pretend to stop the investigation to appease their parents, while secretly continuing. This creates tension with Becca.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5888, 2882, 1367, 'ally', false, 'Reacts with bitterness and suspicion to Jamie''s suggestion, highlighting the real consequences she is facing.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5889, 4549, 1368, 'neutral', true, 'Represented by Morgan, who argues for abandoning the investigation entirely, citing the psychological damage and real-world consequences like violence and family discord.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5890, 4548, 1368, 'neutral', false, 'Is confronted with the negative toll the investigation is taking on their lives.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5891, 4211, 1369, 'mini-boss', true, 'Makes a territorial claim on Stephen, suggesting they focus on dating and normal activities instead of the investigation.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5892, 4554, 1369, 'neutral', false, 'Manifests, causing Patrick to briefly disappear and highlighting the instability of their world.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5893, 2896, 1369, 'ally', false, 'Vanishes for a moment during the reality flicker, completely unaware of the event.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5894, 4211, 1370, 'mini-boss', true, 'Successfully isolates Stephen by systematically pushing Whitney away with pointed comments about their need for ''privacy''.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5895, 4342, 1370, 'ally', false, 'Is visibly hurt by Jamie''s words and leaves, marking the final dissolution of the core group''s unity.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5896, 3993, 1370, 'ally', false, 'Suspects Jamie is orchestrating the group''s collapse but allows himself to be drawn in by her affection and the promise of relief from the shadows.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5897, 4549, 1370, 'neutral', false, 'Depart from the table, finalizing the schism within the group.', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.entity_beat_appearances VALUES (5919, 4550, 1371, 'ally', false, 'Gather for Nana''s funeral, feeling the oppressive quiet.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5920, 4549, 1371, 'neutral', false, 'Stand apart from the main group, radiating discomfort.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5921, 4563, 1371, 'enemy', true, 'Gather along the fence, darker than they should be, establishing an eerie atmosphere.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5922, 4569, 1371, 'neutral', false, 'Cuts across the gravestones, adding to the chilling atmosphere.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (6245, 4802, 1448, 'neutral', false, 'Serves as the poison used against TJ.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6246, 4803, 1448, 'neutral', false, 'Mentioned as another of Jamie''s failed murder attempts at the school.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6247, 4211, 1449, 'ally', true, 'Shows genuine vulnerability and confusion, revealing that her human consciousness is fighting the possessing demon.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6248, 3993, 1449, 'ally', false, 'Listens to her confession and realizes the real Jamie is still present, strengthening his emotional connection to her.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6249, 2474, 1450, 'ally', true, 'Warns Stephen about Jamie''s escalating attempts and provides photographic evidence of the demon''s true form.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6250, 3993, 1450, 'ally', false, 'Argues that Jamie''s repeated failures are evidence that her human side is fighting back, and resolves to save her.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6251, 4801, 1450, 'neutral', false, 'Act as concrete proof of the supernatural threat, showing Jamie''s monstrous reflection.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6252, 4211, 1450, 'mini-boss', false, 'Is the subject of the conversation and is seen in the cafeteria, her predatory nature momentarily visible before she puts on a friendly facade for Stephen.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6253, 4811, 1451, 'neutral', false, 'Marks the beginning of a three-week period of freedom, setting the scene''s timeline and mood.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6254, 4211, 1451, 'mini-boss', true, 'Arrives full of excitement, embracing Stephen but also bringing him a thermos of suspicious chamomile tea as a pretext for poisoning him.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6255, 3993, 1451, 'ally', false, 'Is found by Jamie at his locker and momentarily forgets the danger due to her genuine joy.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6256, 4809, 1451, 'enemy', false, 'Is introduced by Jamie under the guise of being a remedy for insomnia, with its smell and her emphasis hinting at its true nature.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6257, 3993, 1452, 'ally', false, 'Makes the conscious decision to drink the poisoned tea, demonstrating a reckless trust in Jamie and passing her test.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6258, 4211, 1452, 'mini-boss', true, 'Reacts to him drinking the poison, drawing blood from his wrist and confronting him with the reality of their mutual deception, while questioning if their feelings are real.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6259, 4809, 1452, 'enemy', false, 'Is consumed by Stephen, burning his throat like acid.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6260, 4813, 1452, 'neutral', false, 'Is explicitly named as the dynamic of their relationship, which Jamie fears they are both ''losing''.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6261, 514, 1452, 'neutral', false, 'Is proposed by Jamie as the one variable that might be real and uncontrollable within their ''game''.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6262, 2730, 1452, 'unknown', false, 'Is mentioned as a name that bleeds through Jamie''s voice, hinting at her other identity.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (7006, 4071, 1643, 'neutral', true, 'Appears as a glowing vulnerability in the prison, offering a chance for escape.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (7007, 5383, 1643, 'neutral', false, 'Coils within Yaldabaoth, providing the emotional fuel that pivots into a desire for escape.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (7008, 5384, 1643, 'neutral', false, 'Manifests as Yaldabaoth''s newfound hope and recognition of his chance.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (5923, 4342, 1372, 'ally', false, 'Is the first to spot the translucent figure of Nana.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5924, 4560, 1372, 'unknown', true, 'Appears as a spirit, raises her hand, and sketches a sigil in the air before vanishing.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5925, 4564, 1372, 'unknown', false, 'Is created by Nana''s ghost, glowing for a moment before disappearing.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5926, 4549, 1373, 'neutral', true, 'Attempt to rationalize the ghostly sighting as a grief hallucination or heat distortion.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5927, 2884, 1373, 'ally', false, 'Insists with certainty that the figure was Nana.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5928, 4342, 1373, 'ally', false, 'Challenges the skeptics'' denial by pointing out their own fearful reaction.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5929, 4549, 1374, 'neutral', false, 'Make their excuses and depart hastily, leaving the core group behind.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5930, 4211, 1374, 'ally', true, 'Expresses her fear and concern over the cost of their supernatural obsession, highlighting the negative impact on their lives.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5931, 3993, 1374, 'ally', false, 'Listens to Jamie''s concerns and acknowledges the weight of their consequences.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5932, 4550, 1375, 'ally', true, 'Decide collectively to contact Benji for answers, planning to use TJ''s basement.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5933, 4505, 1375, 'unknown', false, 'Is identified as the group''s next course of action to gain information.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5934, 4563, 1375, 'enemy', false, 'Are seen shifting between headstones and following the group''s car as they depart.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5935, 3993, 1375, 'ally', false, 'Observes the shadows following them, and contemplates Nana''s appearance as a potential warning.', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.entity_beat_appearances VALUES (5953, 4579, 1376, 'ally', true, 'Gathers in the basement, debating the reality of Nana''s appearance and the wisdom of their plan.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5954, 3993, 1376, 'ally', false, 'Reassures Jamie and expresses a stubborn refusal to stop believing in mysteries.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5955, 4211, 1376, 'ally', false, 'Expresses deep fear of dying or being erased from existence, seeking comfort from Stephen.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5956, 4581, 1376, 'neutral', false, 'Is discussed and drawn by Whitney, who fears it is a warning, not a key.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5957, 4578, 1376, 'unknown', false, 'Is the subject of the group''s debate; her appearance is the reason for the summoning.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5958, 4580, 1377, 'enemy', true, 'Begins as the summoning chant starts, causing the air to thicken, the temperature to drop, and the walls to weep black tears.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5959, 4579, 1377, 'ally', false, 'Begins the chant and reacts with fear as reality immediately begins to buckle and tear.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5960, 4580, 1378, 'mini-boss', true, 'Intensifies its assault, transforming the basement into a living organism and inflicting direct, horrific physical harm on Jamie, TJ, and Whitney.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5961, 4211, 1378, 'ally', false, 'Collapses into a violent seizure, foaming at the mouth with a dark substance containing ancient words.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5962, 2884, 1378, 'ally', false, 'Screams as a deep, gaping wound spontaneously erupts on his arm, gushing blood.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5963, 4342, 1378, 'ally', false, 'Watches in horror as her fingernails and a finger dissolve into nothing.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5964, 4505, 1379, 'neutral', true, 'Materializes in a fragmented, furious state, yelling that he was interrupted while integrating with a gravity stapler.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5965, 4581, 1379, 'neutral', false, 'Is identified by Benji as a ''cosmic can opener'' that the group has just cut themselves on.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5966, 4579, 1379, 'ally', false, 'Reels from the cosmic entity''s chaotic arrival and learns they have performed ''emergency surgery on reality''.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5967, 4582, 1379, 'neutral', false, 'Mentioned by Benji as the object he was integrating with, emphasizing his alien nature.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5968, 4505, 1380, 'neutral', true, 'Explains that the group''s actions are straining cosmic ''suppression filters'' and making them visible to far worse entities before dissolving away.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5969, 4583, 1380, 'neutral', false, 'Are revealed by Benji to be failing, which is why the group is noticing flickers and echoes.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5970, 4579, 1380, 'ally', false, 'Listens to the dire warnings, left with the certainty that they have crossed an irreversible line.', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_beat_appearances VALUES (5971, 2884, 1381, 'neutral', true, 'Announces he is quitting the investigation due to fear and real-world consequences.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5972, 3993, 1381, 'ally', false, 'Receives the news of TJ''s departure, feeling the first major crack in the group''s foundation.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5973, 4593, 1381, 'enemy', false, 'Serves as the traumatic catalyst for TJ''s decision to quit.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5974, 2882, 1382, 'neutral', true, 'Announces she is leaving the group and taking Patrick with her, choosing ''sanity'' over the investigation.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5975, 3993, 1382, 'ally', false, 'Listens with desperation as another core member abandons their cause.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5976, 2896, 1382, 'neutral', false, 'Is declared to be leaving with Becca, further shrinking the group.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5977, 4211, 1383, 'mini-boss', true, 'Proposes that the remaining members quit the investigation, framing it as a return to a normal teenage life.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5978, 4342, 1383, 'ally', false, 'Reacts with disbelief to Jamie''s suggestion, questioning why they would stop now.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5979, 3993, 1383, 'ally', false, 'Sits in uncomfortable silence as Jamie makes her case, physically held by her.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5980, 4342, 1384, 'ally', true, 'Confronts Jamie, accusing her of systematically and deliberately sabotaging the group to isolate Stephen.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5981, 4211, 1384, 'mini-boss', true, 'Feebly denies the accusations while her face cycles through emotions, betraying her guilt.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (7009, 4071, 1644, 'neutral', true, 'Abruptly seals itself and its signal goes silent, closing the potential escape route.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (7010, 2550, 1644, 'neutral', true, 'Is thwarted before he can even act, his momentary hope extinguished as he is left trapped once more.', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_beat_appearances VALUES (7021, 3993, 1645, 'ally', true, 'Mutters to himself while writing, then freezes in confusion and fear after typing the word ''Etheris'' instead of ''Earth''.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7022, 2536, 1645, 'neutral', false, 'Appears inexplicably in Stephen''s writing, causing him to question his own mind and the nature of his reality.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7023, 3993, 1646, 'ally', true, 'Is confronted by his wife with a phone call from Whitney, which triggers a flood of impossible memories.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7024, 2549, 1646, 'unknown', false, 'Brings the phone to her husband, her face pale, acting as the catalyst for the memory cascade.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7025, 4378, 1646, 'neutral', false, 'Serves as the conduit for Whitney''s impossible voice.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7026, 4342, 1646, 'unknown', false, 'Speaks to Stephen over the phone, her name and voice unlocking forbidden knowledge within him.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7027, 5391, 1646, 'neutral', false, 'Surface violently in Stephen''s mind, shattering his understanding of his life.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7028, 5293, 1646, 'unknown', false, 'Is mentioned by Whitney just before the line goes dead.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7029, 5392, 1647, 'mini-boss', true, 'Acts as the primary antagonist, systematically and horrifically dismantling Stephen''s body from the inside out.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7290, 2897, 1707, 'ally', false, 'Greets Stephen with a firm handshake and genuine delight.', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.entity_beat_appearances VALUES (5982, 3993, 1384, 'ally', false, 'Attempts to intervene, calling Whitney''s accusations ''crazy''.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5983, 4594, 1385, 'enemy', true, 'Jamie forces Stephen to choose between her and Whitney.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5984, 4595, 1385, 'neutral', true, 'Stephen''s inability to speak acts as his choice, siding with Jamie.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5985, 4342, 1385, 'ally', false, 'Is emotionally destroyed by Stephen''s silent choice, her face collapsing in devastation.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5986, 3993, 1385, 'ally', false, 'Hesitates and remains silent, his inaction sealing Whitney''s fate and solidifying his alliance with Jamie.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5987, 4590, 1386, 'neutral', true, 'Bursts into the room, providing comic relief and interrupting the tense, intimate moment between Stephen and Jamie.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5988, 4211, 1386, 'mini-boss', false, 'Kisses Stephen, attempting to solidify her victory, but is immediately interrupted and flustered by her sister.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5989, 3993, 1386, 'ally', false, 'Is kissed by Jamie but his processing is cut short by Tiffany''s arrival, causing him to laugh hysterically.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5990, 4342, 1386, 'ally', false, 'Exits the scene, leaving a void that is immediately and absurdly filled by Tiffany.', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_beat_appearances VALUES (5991, 4605, 1387, 'ally', true, 'Gathering at their usual table for lunch and a game of Magic, establishing a baseline of normalcy and camaraderie.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (5992, 4342, 1387, 'ally', false, 'Shuffles Patrick''s deck, her distant behavior and secret investigations providing foreshadowing.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (5993, 4211, 1387, 'ally', false, 'Sits with the narrator, acting distant and watchful instead of playing.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (5994, 4606, 1388, 'enemy', true, 'Erupts into existence as Whitney draws a card, peeling reality away and replacing the courtyard with a terrifying dimension. It causes everyone''s eyes to bleed and transforms the cards.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (5995, 4342, 1388, 'ally', false, 'Her action of drawing a card triggers the event, and she becomes frozen in place.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (5996, 4605, 1388, 'ally', false, 'Are caught in the reality fracture, experiencing the sensory horror and physical effects like bleeding eyes.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (5997, 4607, 1389, 'mini-boss', true, 'Erupt from the ground to bind Whitney and drag her into the hellscape.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (5998, 4342, 1389, 'ally', false, 'Fights desperately against the chains and screams for help as she is abducted.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (5999, 4609, 1389, 'unknown', false, 'Speaks through Jamie, commenting on a change in ''parameters'' and unacceptable ''deviation''.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (6000, 4611, 1389, 'unknown', false, 'Appears when called upon, attempting to give a desperate, broken warning.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (6001, 3993, 1389, 'ally', false, 'Is paralyzed by the event, unable to help Whitney, and screams for Benji.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (6002, 4605, 1390, 'ally', true, 'Are left grappling with the aftermath, as the only ones who remember Whitney''s existence.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (6003, 4610, 1390, 'neutral', false, 'Have no memory of Whitney and are confused by the core group''s distress, highlighting the memory-altering nature of the event.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (6004, 4354, 1390, 'neutral', false, 'Remains on the table as a cryptic clue and a symbol of their failure, its text hinting at the consequences of letting Whitney be alone.', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_beat_appearances VALUES (6005, 4614, 1391, 'mini-boss', true, 'Arrives in the courtyard and immediately begins verbally abusing Mr. Martinez with racist and xenophobic threats, establishing his cruel and dominant personality.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6006, 4620, 1391, 'neutral', false, 'Is targeted by William''s verbal assault and retreats with his head down, muttering apologies.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6007, 4404, 1391, 'ally', false, 'Observes William''s arrival and behavior with dread and recognition of the threat he poses.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6008, 4614, 1392, 'mini-boss', true, 'Targets the friend group, claims their table, insults them with homophobic slurs, physically assaults TJ, and then feigns innocence when a teacher intervenes.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6009, 2884, 1392, 'ally', false, 'Confronts William for insulting Morgan and is violently slammed into the table.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6010, 4621, 1392, 'neutral', false, 'Intervenes in the conflict, ordering William to let TJ go but failing to issue any meaningful punishment.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6011, 3993, 1392, 'ally', false, 'Observes the assault and is personally threatened by William in a menacing whisper.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6012, 4614, 1393, 'mini-boss', true, 'Shifts tactics to psychologically torment Patrick by fabricating a shared history and threatening him with conversion therapy camp before walking away as a celebrated figure.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6013, 2896, 1393, 'ally', false, 'Is left horrified and confused by William''s gaslighting, unable to reconcile his own memories with the reality William is forcing upon him.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6014, 4618, 1393, 'enemy', false, 'The group fully confronts the horror of their situation, realizing Whitney has been erased and replaced by her torturer, who is now accepted by everyone else.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6015, 4622, 1393, 'neutral', false, 'Its absence is discovered, confirming the group''s isolation and the loss of a potential tool or warning.', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_beat_appearances VALUES (6016, 4634, 1394, 'neutral', true, 'The group attempts the summoning ritual in TJ''s basement and Jamie''s bedroom, but it fails, yielding only static and causing TJ to become violent.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6017, 2884, 1394, 'ally', false, 'Reacts to the ritual''s failure with violent anger, punching a wall and splitting his knuckles.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6018, 4211, 1394, 'ally', false, 'Her trapper keeper cracks, revealing a disturbing entity, leading her to conclude that their connection to Benji is severed without Whitney.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6019, 4632, 1394, 'enemy', false, 'Appears through Jamie''s broken trapper keeper, symbolizing the corrupted connection.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6020, 3993, 1394, 'ally', false, 'Observes TJ''s frightening change in personality and the bizarre events in Jamie''s room.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6021, 4633, 1395, 'mini-boss', true, 'Manifests through Becca, causing her to deny Whitney''s existence, verbally abuse her friends, and slap Patrick when he tries to comfort her.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6022, 2882, 1395, 'ally', false, 'Acts as the vessel for the memory corruption, becoming cruel and hostile.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6023, 2896, 1395, 'ally', false, 'Tries to comfort Becca and reason with her, but is met with denial and physical violence.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6024, 3993, 1395, 'ally', false, 'Witnesses the shocking transformation and attack, deepening the sense of dread.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6025, 4211, 1396, 'ally', true, 'Attempts to seduce the narrator and convince him to abandon the group, warning that TJ is becoming dangerous and their cause is hopeless.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6026, 3993, 1396, 'ally', false, 'Resists Jamie''s desperate, possessive advances, realizing she is trying to isolate him from his friends out of fear.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6027, 2884, 1396, 'ally', false, 'Drives the group to the beach, his clenched jaw and white knuckles on the steering wheel confirming Jamie''s fears about his growing rage.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6028, 4631, 1396, 'enemy', false, 'The narrator realizes this force is actively trying to divide them, which strengthens his resolve to stay loyal.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6029, 2882, 1397, 'ally', true, 'Explodes in a rage after the final ritual fails, accusing Jamie of stealing the narrator from her and declaring the entire group delusional before storming out.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6318, 4863, 1466, 'neutral', false, 'Its presence confirms the erasure.', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.entity_beat_appearances VALUES (6030, 4633, 1397, 'mini-boss', false, 'Drives Becca''s final, group-shattering outburst, successfully severing her from her friends.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6031, 4211, 1397, 'ally', false, 'Is the target of Becca''s furious accusations and breaks down sobbing.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6032, 2884, 1397, 'ally', false, 'Is left defeated, acknowledging that the group is powerless without their ''key''.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6033, 3993, 1397, 'ally', false, 'Tries to mediate the fight and is left in the dark with his remaining friends, feeling the group tear itself apart.', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_beat_appearances VALUES (6034, 4404, 1398, 'neutral', false, 'Scatters and fractures, with each member adopting a different coping mechanism after a shared trauma.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6035, 2896, 1398, 'ally', false, 'Gives up the ''chase'' and focuses intensely on his relationship with Becca.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6036, 2882, 1398, 'ally', false, 'Reunites with Patrick in a very public and affectionate way.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6037, 2884, 1398, 'ally', false, 'Throws himself into schoolwork with manic intensity to avoid dealing with the trauma.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6038, 4211, 1398, 'enemy', false, 'Begins her efforts to ''save'' the narrator by trying to make him move on from Whitney.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6039, 3993, 1398, 'ally', true, 'Rejects his friends'' coping mechanisms and resolves to not give up on remembering Whitney.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6040, 3993, 1399, 'ally', true, 'Begins a nightly ritual of writing down memories of Whitney and recording his dreams, noticing a disturbing pattern.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6041, 4263, 1399, 'neutral', false, 'Serves as the physical record of the narrator''s memories and dreams.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6042, 4342, 1399, 'ally', false, 'Appears in the narrator''s dreams, trying to communicate an urgent but unheard message.', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.entity_beat_appearances VALUES (6207, 2730, 1439, 'unknown', true, 'The name is spoken, acting as a trigger that shatters the illusion for Stephen.', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.entity_beat_appearances VALUES (6043, 4644, 1399, 'mini-boss', true, 'Manifests in the narrator''s dreams as a seductive block, preventing him from understanding what Whitney is trying to say.', '2026-02-28 18:44:47.603186-05');
