INSERT INTO public.entity_beat_appearances VALUES (6057, 4658, 1402, 'neutral', false, 'Represent the digital noise and dead ends Stephen encounters in his search.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6058, 3993, 1403, 'ally', true, 'Discovers Whitney''s future-dated message, prints it out, and freezes in fear when the noise almost wakes his father.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6059, 4656, 1403, 'neutral', true, 'Appears on the screen, providing a shocking and impossible clue.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6060, 4659, 1403, 'neutral', false, 'Loudly prints the message, turning the impossible digital text into a physical object and creating a moment of high tension.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6061, 2550, 1403, 'neutral', false, 'Stirs in his sleep, representing a physical threat that Stephen must avoid.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6062, 3993, 1404, 'ally', true, 'Calls Jamie for help, but is sidetracked by her seductive advances before trying to explain his discovery, leading to her frustration.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6063, 4211, 1404, 'ally', true, 'Answers the phone and immediately tries to seduce Stephen, but her tone shifts to anger and negotiation when he brings up Whitney.', '2026-02-28 18:46:03.28375-05');
