INSERT INTO public.entity_beat_appearances VALUES (6065, 4211, 1405, 'ally', false, 'Makes a final, highly seductive appeal before hanging up, leaving Stephen in a state of conflict and arousal.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6066, 3993, 1405, 'ally', true, 'Is left aroused and conflicted by the call, and as he finally falls asleep, he senses he is being watched.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6067, 1728, 1405, 'mini-boss', true, 'Appears outside Stephen''s window, observing him patiently as he succumbs to sleep.', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_beat_appearances VALUES (6068, 4665, 1406, 'neutral', true, 'Gives slurred, apathetic instructions to the cross country team while visibly intoxicated.', '2026-02-28 18:46:58.7638-05');
