INSERT INTO public.entity_beat_appearances VALUES (6070, 4672, 1406, 'neutral', false, 'Creates an oppressive, uncomfortable physical environment for the runners.', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.entity_beat_appearances VALUES (6071, 4656, 1407, 'neutral', true, 'Stephen reveals the message''s contents, urging the group to investigate a new trail.', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.entity_beat_appearances VALUES (6072, 4211, 1407, 'ally', false, 'Attempts to seduce Stephen and dissuade him from the investigation, suggesting they go off alone instead.', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.entity_beat_appearances VALUES (6073, 3993, 1407, 'ally', false, 'Resists Jamie''s distractions enough to convince the group to follow the message''s instructions.', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.entity_beat_appearances VALUES (6074, 2896, 1407, 'ally', false, 'Experiences a flash of a memory about a ''white and broken'' trailer that he dismisses as not his own.', '2026-02-28 18:46:58.7638-05');
