INSERT INTO public.entity_beat_appearances VALUES (6076, 4671, 1408, 'mini-boss', true, 'Appears in a clearing where it shouldn''t exist, its disturbing presence confirming the message''s validity and triggering confusing memories.', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.entity_beat_appearances VALUES (6077, 4673, 1408, 'neutral', false, 'The environment becomes increasingly dense and eerie as the group moves deeper, creating a sense of dread.', '2026-02-28 18:46:58.7638-05');
