INSERT INTO public.entity_beat_appearances VALUES (6079, 4674, 1408, 'enemy', false, 'Manifests in the group''s minds, blending the pasts of Whitney and another person named Will, causing profound confusion about what is real.', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.entity_beat_appearances VALUES (6080, 4211, 1408, 'ally', false, 'Her seductive demeanor vanishes, replaced by pure fear as she urges the group to recognize the danger.', '2026-02-28 18:46:58.7638-05');
