INSERT INTO public.entity_beat_appearances VALUES (6082, 4684, 1409, 'mini-boss', true, 'Manifests as a ''hiccup'' in reality, breaking physical laws, distorting time, and shifting the landscape around the group.', '2026-02-28 18:47:47.029577-05');
