INSERT INTO public.entity_beat_appearances VALUES (6094, 3993, 1411, 'ally', true, 'Feels the absence of a group member and frantically uses his journal to fight the memory erasure, successfully writing down Jamie''s name.', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.entity_beat_appearances VALUES (6095, 4689, 1411, 'enemy', true, 'Manifests as a hollow ache in Stephen''s chest and a gap in his memory that he struggles to fill.', '2026-02-28 18:47:47.029577-05');
