INSERT INTO public.entity_beat_appearances VALUES (6097, 4684, 1411, 'mini-boss', false, 'Actively tries to make Stephen forget Jamie, causing the journal pages to appear blank and the ink to resist forming her name.', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.entity_beat_appearances VALUES (6098, 4342, 1411, 'ally', false, 'Appears in a reflection, mouthing a desperate warning for the group to get out.', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.entity_beat_appearances VALUES (6099, 4211, 1412, 'enemy', true, 'Her dual nature is revealed as her human and inhuman selves flicker. Her red items begin to burn, and she screams a warning.', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.entity_beat_appearances VALUES (6100, 4686, 1412, 'enemy', true, 'Is identified by Whitney as the source of danger, brought by Jamie, and it accelerates the corruption of the dimension.', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.entity_beat_appearances VALUES (6101, 4342, 1412, 'ally', false, 'Her voice cuts through the air, identifying ''The Red'' and screaming for the group to run.', '2026-02-28 18:47:47.029577-05');
