INSERT INTO public.entity_beat_appearances VALUES (6120, 4342, 1417, 'ally', false, 'Her scream echoes in Stephen''s skull, a key traumatic element of the nightmare.', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_beat_appearances VALUES (6121, 3993, 1418, 'ally', true, 'Frantically tries to call his friends to confirm they are safe and sane.', '2026-02-28 18:50:07.121505-05');
