INSERT INTO public.entity_beat_appearances VALUES (6123, 4711, 1418, 'ally', false, 'Are all simultaneously trying to contact each other, causing the busy signals.', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_beat_appearances VALUES (6124, 4713, 1419, 'neutral', true, 'Serves as the digital space where the friends converge and the split in their memories becomes apparent.', '2026-02-28 18:50:07.121505-05');
