INSERT INTO public.entity_beat_appearances VALUES (6127, 3993, 1419, 'ally', false, 'Logs on and feels a flood of relief seeing his friends are alive, before realizing the deeper problem of their fractured memories.', '2026-02-28 18:50:07.121505-05');
