INSERT INTO public.entity_beat_appearances VALUES (6129, 4549, 1420, 'ally', false, 'Despite their disbelief and concern, they agree to come, choosing loyalty to their friends over logic.', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_beat_appearances VALUES (6130, 4717, 1420, 'neutral', false, 'Is established as the destination for the group''s investigation.', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_beat_appearances VALUES (6131, 4714, 1421, 'unknown', true, 'Appears without a sender, delivering an ominous warning to Stephen before vanishing completely.', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_beat_appearances VALUES (6132, 4715, 1421, 'mini-boss', false, 'Acts through the message, revealing an unseen party is monitoring the situation and has an agenda regarding Whitney.', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_beat_appearances VALUES (6133, 3993, 1421, 'ally', false, 'Is the sole recipient of the message, leaving him isolated with its terrifying implications.', '2026-02-28 18:50:07.121505-05');
