INSERT INTO public.entity_beat_appearances VALUES (6140, 3993, 1423, 'ally', false, 'Discovers the unconscious spirals he drew, the altered deck box, and the impossible card inside.', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_beat_appearances VALUES (6141, 4730, 1423, 'neutral', false, 'Revealed in the journal, a physical sign of his subconscious turmoil.', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_beat_appearances VALUES (6142, 4726, 1423, 'unknown', false, 'Appears on his desk, mysteriously changed in color and aura.', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_beat_appearances VALUES (6143, 4354, 1423, 'unknown', true, 'The central discovery of the beat. Its impossible art, rules, and physical feel deepen the mystery and horror.', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_beat_appearances VALUES (6144, 4342, 1423, 'ally', false, 'Her face is depicted on the Veilwalker card, dissolving into static.', '2026-02-28 18:51:11.880826-05');
