INSERT INTO public.entity_beat_appearances VALUES (6150, 4735, 1425, 'mini-boss', true, 'Knocks gently and speaks with unnatural warmth and pride, a complete reversal of his normal abusive behavior, which shocks Stephen.', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_beat_appearances VALUES (6151, 3993, 1425, 'ally', false, 'Reacts with physical rigidity and shock to his father''s uncharacteristic behavior, recognizing it as deeply wrong.', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_beat_appearances VALUES (6277, 3993, 1456, 'ally', false, 'Joins in confronting Morgan about the danger.', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_beat_appearances VALUES (6152, 4736, 1425, 'enemy', false, 'Serves as the mental baseline of what Stephen expects, highlighting the terrifying abnormality of the False Father''s actions.', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_beat_appearances VALUES (6153, 3993, 1426, 'ally', true, 'Instinctively checks his body and discovers with mounting terror that all the physical marks of his father''s abuse are gone.', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_beat_appearances VALUES (6154, 4737, 1426, 'neutral', false, 'Manifests as unmarked skin where bruises and welts should be, terrifying Stephen more than the actual injuries did.', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_beat_appearances VALUES (6155, 3993, 1427, 'ally', true, 'Grapples with the realization that this kind version of his father is a psychological trap, designed to make him want to trust, which he perceives as the ultimate danger.', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_beat_appearances VALUES (6156, 4735, 1427, 'mini-boss', false, 'His influence is felt as the source of the trap, his feigned kindness being more horrifying to Stephen than overt violence.', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_beat_appearances VALUES (6157, 4739, 1427, 'neutral', false, 'The smell of the pancakes symbolizes the tempting but dangerous lure of the false reality being presented.', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_beat_appearances VALUES (6158, 4579, 1428, 'ally', false, 'Gathers at 7 AM to share stories of their altered realities.', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.entity_beat_appearances VALUES (6159, 4744, 1428, 'enemy', true, 'Its effects are detailed by Jamie, TJ, Patrick, Morgan, Gil, and James, establishing the central conflict.', '2026-02-28 18:52:59.113523-05');
