INSERT INTO public.entity_beat_appearances VALUES (6165, 4752, 1429, 'neutral', false, 'Presented as tangible evidence that reality is broken.', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.entity_beat_appearances VALUES (6166, 4579, 1430, 'ally', true, 'Repeatedly chants Benji''s name around a candle in a desperate attempt to summon him, growing more frustrated with each failure.', '2026-02-28 18:52:59.113523-05');
