INSERT INTO public.entity_beat_appearances VALUES (6176, 4505, 1432, 'unknown', false, 'Tries to warn the group that the ''system'' is compromised but is physically attacked and censored by Reality''s Scream.', '2026-02-28 18:52:59.113523-05');
