INSERT INTO public.entity_beat_appearances VALUES (6183, 4765, 1434, 'neutral', true, 'Serves as the focal point of the beat, as Stephen reads it aloud and the group processes its terrifying implications.', '2026-02-28 18:54:03.780704-05');
