INSERT INTO public.entity_beat_appearances VALUES (6187, 2896, 1434, 'ally', false, 'Provides comfort to Becca, solidifying their bond.', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.entity_beat_appearances VALUES (6188, 4764, 1434, 'unknown', false, 'Are identified as the likely subjects of the warning, as they remember things they shouldn''t be able to.', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.entity_beat_appearances VALUES (6189, 2884, 1434, 'ally', false, 'Sits motionless, drained of energy and gripped by fear.', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.entity_beat_appearances VALUES (6190, 4211, 1435, 'ally', true, 'Her dual nature becomes apparent to Stephen, and she initiates an awkward, desperate kiss.', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.entity_beat_appearances VALUES (6191, 4763, 1435, 'mini-boss', true, 'Manifests visually and audibly to Stephen, revealing its presence within Jamie just before the kiss.', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.entity_beat_appearances VALUES (6192, 3993, 1435, 'ally', false, 'Observes TJ''s memory failure and Jamie''s superimposed demonic form, deepening his love and fear for her.', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.entity_beat_appearances VALUES (6193, 2884, 1435, 'ally', false, 'Demonstrates the effects of the fragmenting reality by being unable to remember if he is dating Morgan.', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.entity_beat_appearances VALUES (6194, 4766, 1436, 'enemy', true, 'Its effects are the central focus of Stephen''s internal monologue as he walks to school, feeling watched and questioning who is real.', '2026-02-28 18:54:03.780704-05');
