INSERT INTO public.entity_beat_appearances VALUES (6195, 3993, 1436, 'ally', false, 'Struggles with the certainty that the world is broken and he cannot trust those around him, even as he tries to hide his thoughts.', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.entity_beat_appearances VALUES (6196, 4211, 1436, 'ally', false, 'Her touch becomes both a comfort and a warning to Stephen, and her voice seems to hide a sinister whisper.', '2026-02-28 18:54:03.780704-05');
