INSERT INTO public.entity_beat_appearances VALUES (6221, 3993, 1443, 'ally', true, 'Explains the concept of ''Jailers'' and Etheris, and then agrees to act as bait in the group''s newly formed plan.', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.entity_beat_appearances VALUES (6222, 4783, 1443, 'ally', false, 'Process the new information and collaboratively develop a strategy to use Jamie''s interest in Stephen against her.', '2026-02-28 18:56:15.489481-05');
