INSERT INTO public.entity_beat_appearances VALUES (6224, 4785, 1443, 'enemy', false, 'Their nature as cosmic prison guards is explained by Stephen, providing crucial context for Jamie''s actions.', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.entity_beat_appearances VALUES (6225, 4211, 1444, 'unknown', true, 'Appears at Stephen''s locker, acting shy and affectionate, establishing her ''perfectly human'' baseline.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6226, 3993, 1444, 'ally', false, 'Observes Jamie''s behavior, noting the taste of her lip gloss and her sweet awkwardness.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6227, 4789, 1444, 'mini-boss', false, 'Executes a flawless performance of a teenage girl in love, using Jamie as its vessel.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6228, 4792, 1444, 'neutral', false, 'Provides a key sensory detail that reinforces Jamie''s apparent normalcy.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6229, 4789, 1445, 'mini-boss', true, 'Through Jamie, perfectly answers a series of impossible knowledge-based and social traps set by Stephen''s friends, mimicking absent people and recalling minute details with eerie precision.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6230, 4783, 1445, 'ally', false, 'Systematically test Jamie with questions about MTG decks, old homework, and a false shared memory to probe for weaknesses in her disguise.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6231, 4211, 1445, 'unknown', false, 'Serves as the mouthpiece and body for the entity, flawlessly passing every test without showing any sign of deception or supernatural origin.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6232, 4342, 1445, 'neutral', false, 'Her memory and habits are used as the basis for one of the tests.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6233, 3993, 1446, 'ally', true, 'Watches Jamie leave and voices his conclusion to the group: her performance is ''too perfect'', which is itself the most damning evidence against her.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6234, 4211, 1446, 'unknown', false, 'Kisses Stephen goodbye and walks away, maintaining her perfect human facade to the end of the school day.', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.entity_beat_appearances VALUES (6235, 4789, 1446, 'mini-boss', false, 'Successfully completes its daily performance, but its very perfection raises the suspicion it was trying to avoid.', '2026-02-28 18:56:54.400326-05');
