INSERT INTO public.entity_beat_appearances VALUES (6237, 3993, 1447, 'ally', false, 'Experiences the strange reversal of his parents'' behavior, recognizing it as a sign that reality is broken.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6238, 4211, 1447, 'mini-boss', true, 'Her nightly visits are the catalyst for the strange domestic situation.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6239, 4797, 1447, 'neutral', false, 'Actively encourages Jamie to stay over, which is completely out of character.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6240, 4798, 1447, 'neutral', false, 'Nods approvingly at Jamie''s presence, a stark change from his former violent self.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6241, 4211, 1448, 'mini-boss', true, 'Attempts to murder Morgan by drowning and TJ by poisoning, masking her actions with feigned innocence.', '2026-02-28 18:57:40.590472-05');
