INSERT INTO public.entity_beat_appearances VALUES (6244, 2884, 1448, 'neutral', false, 'Drinks the poisoned tea and immediately begins bleeding from his ears.', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.entity_beat_appearances VALUES (6263, 4211, 1453, 'mini-boss', true, 'Shifts from murder to domesticity, planning a future with Stephen including Christmas, college, and graduation, expressing wonder and disbelief at this change in herself.', '2026-02-28 18:58:36.287503-05');
