INSERT INTO public.entity_beat_appearances VALUES (6269, 514, 1454, 'neutral', true, 'Manifests as a paradoxical declaration, representing both a genuine emotion and a move in their ongoing game of deception.', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_beat_appearances VALUES (6270, 4579, 1455, 'ally', true, 'The group hikes through the woods, re-establishing their dynamic after Christmas break.', '2026-02-28 18:59:42.893371-05');
