INSERT INTO public.entity_beat_appearances VALUES (6281, 4342, 1457, 'unknown', false, 'Her forgotten memories flood back into Morgan''s mind, explaining the personal stakes.', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_beat_appearances VALUES (6282, 1555, 1458, 'mini-boss', true, 'Begins to ''breathe'' like a living creature, revealing its animate and monstrous nature.', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_beat_appearances VALUES (6283, 2896, 1458, 'ally', false, 'Is drawn toward the trailer''s door, mesmerized by Whitney''s voice.', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_beat_appearances VALUES (6284, 4832, 1458, 'enemy', false, 'Emanates from the trailer, luring Patrick closer.', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_beat_appearances VALUES (6285, 4211, 1458, 'ally', false, 'Erupts in terror, revealing she has some prior knowledge of the trailer''s evil and warns the group to flee.', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_beat_appearances VALUES (6286, 4833, 1458, 'enemy', false, 'Reach out from under the trailer towards Patrick.', '2026-02-28 18:59:42.893371-05');
