INSERT INTO public.entity_beat_appearances VALUES (6592, 5078, 1535, 'neutral', false, 'Forms above the sigil, allowing a glimpse into another reality.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6593, 5077, 1535, 'neutral', false, 'Appears through the membrane, representing a past the narrator is trying to connect with.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6594, 5075, 1535, 'neutral', false, 'Becomes unstable and convulses before exploding.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6595, 2474, 1535, 'ally', false, 'Shouts that the ritual''s resonance is wrong.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6596, 2883, 1535, 'ally', false, 'Yells for them to shut the ritual down.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6597, 5079, 1536, 'enemy', true, 'Violently throws the group members, causing significant injuries.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6598, 5082, 1536, 'enemy', false, 'Is obliterated by the dimensional breach, leaving Patrick an empty shell.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6599, 2896, 1536, 'neutral', false, 'Collapses and reboots into a blank, programmable state.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6600, 2882, 1536, 'ally', false, 'Rushes to Patrick''s side and realizes with horror that he is ''gone again''.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6601, 2883, 1536, 'ally', false, 'Screams in pain as he is thrown against a gas pump and severely injured.', '2026-02-28 19:19:21.715603-05');
