INSERT INTO public.entity_beat_appearances VALUES (6604, 3993, 1536, 'ally', false, NULL, '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6605, 5009, 1537, 'neutral', true, 'Reveals a new entry written in fresh ink that points the group toward Nevada as the true anchor point.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6606, 2882, 1537, 'ally', false, 'Delivers a grief-stricken monologue and decides to stay behind with Patrick and Andrew.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6607, 5081, 1537, 'neutral', false, 'Serves as the location where the remaining group members plan their next move.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6608, 2884, 1537, 'ally', false, NULL, '2026-02-28 19:19:21.715603-05');
