INSERT INTO public.entity_beat_appearances VALUES (6611, 3993, 1537, 'ally', false, NULL, '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6612, 2896, 1537, 'neutral', false, 'Sits blankly, awaiting commands, and confirms the new departure date.', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_beat_appearances VALUES (6613, 3993, 1538, 'ally', true, 'Observes his ''wrong'' parents and feels his skin crawl at their performative normalcy, internally rejecting this false reality.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6614, 2550, 1538, 'enemy', false, 'Performs the role of a perfect sitcom dad, washing dishes and humming, contributing to the oppressive atmosphere.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6615, 2549, 1538, 'enemy', false, 'Acts as a Stepford wife, watching TV with manufactured contentment and radiating an impenetrable, glossy happiness.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6616, 5027, 1538, 'mini-boss', true, 'Manifests through the parents'' behavior and the pristine environment, creating a deeply unsettling atmosphere for Stephen.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6617, 3993, 1539, 'ally', true, 'Asks for money for a trip and is unsettled by the immediate, excessive generosity, which his body reads as a prelude to violence.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6618, 2550, 1539, 'enemy', true, 'Offers Stephen $400 and a credit card without hesitation, a stark and disturbing contrast to his ''Real Dad''.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6619, 2549, 1539, 'enemy', false, 'Expresses performative support and enthusiasm for the trip, reinforcing the artificial family dynamic.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6620, 5089, 1539, 'enemy', false, 'Begins with an offering of cash and a credit card, presented as generosity but perceived as a tool of the false reality.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6621, 3993, 1540, 'ally', true, 'Resists the parents'' increasingly frantic and absurd bribes, shouting that he is leaving, which momentarily breaks their programming.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6622, 2550, 1540, 'enemy', true, 'Becomes frantic, offering beer, an inheritance, cars, and even a feature in Playboy to stop Stephen from leaving.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6623, 2549, 1540, 'enemy', true, 'Escalates her attempts to keep Stephen home, offering a PlayStation, a Sega Saturn, perfect grades, and a private Nine Inch Nails concert.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6624, 5089, 1540, 'enemy', true, 'Manifests as a desperate, chaotic flood of absurd material and experiential offerings designed to trap Stephen in the false reality.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6625, 3993, 1541, 'ally', true, 'Retreats to his room, escaping the parents'' influence and solidifying his resolve to leave for Nevada the next day.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6626, 5090, 1541, 'ally', false, 'Serves as Stephen''s only real anchor, a tangible connection to a reality outside the current illusion he is trapped in.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6627, 2550, 1541, 'enemy', false, 'Resets to his programmed normalcy, returning to the dishes as if the frantic bribery never happened.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6628, 2549, 1541, 'enemy', false, 'Resets her programming, offering a final, hollow bribe of a private concert before returning to her TV show.', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_beat_appearances VALUES (6629, 3993, 1542, 'ally', true, 'Packs his bag, feeling the unreality of his new possessions, and holds the clay sigil as his only anchor to truth.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6630, 5090, 1542, 'neutral', false, 'Provides a tangible, grounding sensation, pulsing in Stephen''s palm and reminding him of what is real.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6631, 5100, 1542, 'neutral', false, 'Serves as a symbol of the artificial, pristine world, contrasting with Stephen''s memory of his real, worn-out bag.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6632, 5096, 1542, 'ally', false, 'Is remembered by Stephen, offering advice that reinforces the idea that this paradise is still a prison.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6633, 3993, 1543, 'ally', true, 'Reflects on the sterile, performative love of his marriage in another timeline.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6634, 2549, 1543, 'neutral', false, 'Is remembered as a wife who provided a loveless, choreographed partnership, representing a different kind of prison.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6635, 2544, 1543, 'ally', false, 'Is thought of as the embodiment of genuine, seeing love, providing a stark contrast to Stephen''s past marriage.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6636, 2544, 1544, 'ally', true, 'Arrives and recounts the desperate, manipulative bribes her family is using to try and make her stay.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6637, 5098, 1544, 'enemy', false, 'Acts as agents of the Artificial Reality, offering horses and using an eight-year-old''s fantasies as emotional ammunition.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6638, 3993, 1544, 'ally', false, 'Listens and comforts Jamie, acknowledging the manipulative nature of their prison.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6639, 2544, 1545, 'ally', false, 'Reveals that she is late and might be pregnant, voicing her fear and conflict.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6640, 5099, 1545, 'neutral', true, 'Emerges as a concept—a new, powerful chain designed by the universe to bind them to this reality.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6641, 3993, 1545, 'ally', false, 'Reacts with quiet horror and understanding, placing a hand on her stomach and grappling with the new dilemma.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6642, 3993, 1546, 'ally', true, 'Reaffirms their choice to leave the ''beautiful cage'' and makes love with Jamie as a final, meaningful act.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6643, 2544, 1546, 'ally', true, 'Overcomes her fear, recommits to Stephen, and chooses truth over the potential family and safety offered by the lie.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6644, 5094, 1546, 'mini-boss', false, 'Makes a final, subtle attempt to persuade them with a shooting star and the smell of fresh-baked cookies.', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_beat_appearances VALUES (6645, 2884, 1547, 'ally', true, 'Arrives at the station bruised and traumatized after being attacked by his father.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6646, 2474, 1547, 'ally', false, 'Recounts hiding from the police in the woods with TJ.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6647, 3993, 1547, 'ally', false, 'Narrates the scene and expresses nervousness about being caught.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6648, 5114, 1547, 'enemy', false, 'Mentioned as the source of TJ''s injuries and legal troubles.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6649, 5111, 1548, 'neutral', true, 'Sells the tickets to ''Nowhere, Nevada'' and gives a cryptic warning after her eyes flicker with inhuman knowledge.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6650, 5109, 1548, 'neutral', false, 'Waits for the passengers, appearing decrepit and ominous.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6651, 5107, 1548, 'mini-boss', false, 'Welcomes the group aboard with a morbid announcement.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6652, 3993, 1548, 'ally', false, 'Purchases the tickets and observes the strangeness of the clerk and driver.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6653, 5108, 1549, 'enemy', true, 'A drunk passenger projectile vomits words, a key sign of the supernatural nature of the journey, before reality stabilizes.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6654, 2474, 1549, 'ally', false, 'Attempts to flirt with TJ, but her flirtation is interrupted by the reality hiccup and she becomes terrified.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6655, 2884, 1549, 'ally', false, 'Responds awkwardly to Morgan''s flirting and confirms the reality of the vomited words.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6656, 5112, 1550, 'enemy', true, 'Revealed to be a living, grotesque organ. It screams and bleeds when the bus is thrown by turbulence.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6657, 2544, 1550, 'ally', false, 'Initiates a kiss with Stephen inside the bathroom, a moment of rebellion amidst the horror.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6658, 3993, 1550, 'ally', false, 'Accompanies Jamie to the bathroom and shares a kiss before being thrown around by turbulence.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6659, 5108, 1550, 'enemy', false, 'A woman with solid black eyes delivers a warning in Latin after Jamie and Stephen emerge from the bathroom.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6660, 5110, 1551, 'enemy', true, 'The landscape outside becomes theoretical, with impossible signs and no other traffic.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6661, 5108, 1551, 'enemy', false, 'Become increasingly impossible, boarding through non-existent doors and delivering cryptic warnings before reality flashes back to normal.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6662, 3993, 1551, 'ally', false, 'Experiences a terrifying vision of being strangled by a ghost child.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6663, 2474, 1552, 'ally', true, 'Calculates and reveals the truth: the other passengers are ghosts from different decades who died in tragic accidents.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6664, 5108, 1552, 'enemy', false, 'Are identified as specific deceased individuals, confirming the bus is transporting ghosts.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6665, 2544, 1552, 'ally', false, 'Compares the bus to the ferry on the River Styx.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6666, 5107, 1552, 'mini-boss', false, 'Cheerfully confirms that they are not dead ''yet'' and that chronology is optional on this route.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6667, 5113, 1553, 'neutral', true, 'The bus transitions to this location, where the dead passengers are seen eternally shopping in a hopeless loop.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6668, 5108, 1553, 'enemy', false, 'Are left behind at their ''stop,'' trapped in the purgatorial gas station.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6669, 5107, 1553, 'mini-boss', false, 'Explains that unlike the ghosts, the four protagonists still have choices and a chance to turn back.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6670, 3993, 1553, 'ally', false, 'Experiences the transition and the return to the now-empty bus.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6671, 5115, 1554, 'ally', true, 'Grows warm and acts as a beacon, causing the theoretical landscape of Nevada to solidify and match the location in the image.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6672, 5107, 1554, 'mini-boss', false, 'Announces their arrival at the crossroads, the ''end of the line.''', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6673, 5110, 1554, 'enemy', false, 'Resolves from suggestion into a solid, real destination based on Stephen''s memory and photograph.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6674, 3993, 1554, 'ally', false, 'Feels the landscape change and prepares to disembark with Jamie.', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_beat_appearances VALUES (6675, 3993, 1555, 'ally', false, 'Exits the bus with his friends and begins the walk toward the ominous church.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6676, 5122, 1555, 'mini-boss', true, 'Appears on the horizon, a disturbing structure that rises from the desert ''like a bone pushed through skin''.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6677, 2884, 1555, 'ally', false, NULL, '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6678, 2474, 1555, 'ally', false, NULL, '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6679, 2544, 1555, 'ally', false, NULL, '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6680, 2544, 1556, 'ally', true, 'Kneels at the desecrated pulpit and begins drawing a protective sigil with chalk and her own blood.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6681, 5124, 1556, 'enemy', false, 'The filth covering the church interior is discovered, revealing the location to be an ''anti-church''.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6682, 5123, 1556, 'enemy', false, 'Begin emanating from the walls, commanding the group to leave.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6683, 3993, 1556, 'ally', false, NULL, '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6684, 3993, 1557, 'ally', true, 'Embraces his younger self after reality tears, only to recognize the smell of his mother''s poison, confirming her betrayal.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6685, 5125, 1557, 'neutral', false, 'Appears in an idealized version of the church and reveals he was poisoned before dissolving into his older self.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6686, 5126, 1557, 'enemy', false, 'Its presence is detected on the boy''s breath, serving as the catalyst for Stephen''s horrified realization.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6687, 2549, 1557, 'enemy', false, 'Her act of poisoning her son is identified as the source of the timeline fracture and Stephen''s core trauma.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6688, 5127, 1558, 'enemy', true, 'Triggered by the fusion of Stephen''s selves, it annihilates the church, the desert, and all of Stephen''s friends.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6689, 2544, 1558, 'ally', false, 'Is horrifically wounded by the first blast and crawls toward Stephen before being incinerated by the second.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6690, 2884, 1558, 'ally', false, 'Is killed instantly by the initial blast.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6691, 2474, 1558, 'ally', false, 'Is vaporized by her own chemicals in the explosion.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6692, 3993, 1558, 'ally', false, 'Survives the initial destruction only to be consumed by the final blast, accepting the sacrifice as the price to change timelines.', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_beat_appearances VALUES (6693, 5132, 1559, 'unknown', true, 'Calls out to the protagonist, pulling him from the void.', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_beat_appearances VALUES (6694, 3993, 1559, 'ally', false, 'Wakes up in a state of confusion, immediately noticing that the ceiling of the bedroom is wrong.', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_beat_appearances VALUES (6695, 3993, 1560, 'ally', true, 'Discovers his body is that of a small child, with weak limbs and soft hands, which triggers a wave of panic.', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_beat_appearances VALUES (6696, 5137, 1560, 'neutral', false, 'Begins to form as memories of the trailer home slam into the protagonist, conflicting with his more recent memories.', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_beat_appearances VALUES (6698, 3993, 1561, 'ally', true, 'As the teenager, he fights for control, cataloging memories and survival strategies with desperate fury.', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_beat_appearances VALUES (6699, 5134, 1561, 'neutral', false, 'Observes the panic of the other two with detached resignation, knowing he has already lived this fate.', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_beat_appearances VALUES (6700, 5137, 1562, 'neutral', true, 'Confronts its reflection as an eight-year-old in the bathroom mirror, seeing all three minds looking back.', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_beat_appearances VALUES (6701, 2549, 1562, 'enemy', false, 'Is heard humming off-screen, preparing the breakfast that the protagonist knows contains poison.', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_beat_appearances VALUES (6702, 3993, 1563, 'ally', false, 'Observes his mother''s broken state and the ritualistic preparation of the poison, recalling the scene with adult understanding layered over childhood fear.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6703, 2549, 1563, 'mini-boss', true, 'Operating as ''The Poisoning Mother Persona,'' she prepares the poisoned cereal and ''vitamins'' with a heartbreakingly sincere smile, fully embodying her role of deceptive caregiver.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6704, 5147, 1563, 'enemy', false, 'Is set before the protagonist as a seemingly magical breakfast, masking its true purpose.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6705, 5148, 1563, 'enemy', false, 'Is held by the mother, ready to be administered as part of the morning ritual.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6706, 3993, 1564, 'ally', true, 'Shatters the deception by asking his mother directly why she is poisoning him, using a child''s voice with an adult''s certainty.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6707, 2549, 1564, 'enemy', false, 'Her persona crumbles from certainty into confusion and horror. She drops the vial of poison.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6708, 5150, 1564, 'neutral', false, 'Is triggered by the protagonist''s question, causing timelines to hiccup and show alternate possibilities.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6709, 5148, 1564, 'enemy', false, 'Slips from the mother''s fingers and shatters on the floor, its potential futures collapsing into one.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6710, 2549, 1565, 'neutral', true, 'Collapses into sobs and confesses her motive, revealing the twisted logic behind her actions.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6711, 5149, 1565, 'enemy', false, 'Is given voice as the mother explains she was ''saving'' her son by making him weak and invisible to his violent father.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6712, 5151, 1565, 'enemy', false, 'Is explicitly named as the reason for the poisoning.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6713, 2608, 1565, 'enemy', false, 'Is mentioned as the source of the violence and fear that dominates the family.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6714, 3993, 1566, 'ally', true, 'Moves past his anger and fear to embrace his mother, offering comfort and forgiveness.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6715, 2549, 1566, 'ally', false, 'Collapses into her son''s embrace, grieving for what her love became and accepting his comfort.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6716, 5150, 1566, 'neutral', false, 'The kitchen settles into a new configuration, a space between timelines where this moment of mutual understanding and forgiveness can exist.', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_beat_appearances VALUES (6717, 3993, 1567, 'ally', true, 'Retreats to the bathroom, overwhelmed by his mother''s confession, while his inner personas argue.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6718, 5159, 1567, 'neutral', false, 'Debates whether their mother was trying to save or kill them, highlighting the protagonist''s fractured state.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6719, 5158, 1567, 'neutral', false, 'Appears and vanishes, a tangible memory of a lost future that offers no physical comfort.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6720, 2549, 1567, 'unknown', false, 'Is the subject of the internal debate, her toxic actions framing the protagonist''s trauma.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6721, 4505, 1568, 'ally', true, 'Manifests in his true cosmic form, complaining about the bureaucratic difficulty of appearing.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6722, 5157, 1568, 'neutral', false, 'Bends and shatters into light, serving as the portal for Benji''s arrival.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6723, 3993, 1568, 'ally', false, 'Reacts with a mixture of fear and exasperation to the cosmic intrusion.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6724, 4505, 1569, 'ally', true, 'Explains that the protagonist is a symptom of a failing cosmic prison and that his ability to remember makes him dangerous to the system.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6725, 3993, 1569, 'ally', false, 'Listens to the explanation, feeling a mix of confusion, relief, and guilt.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6726, 4510, 1569, 'mini-boss', false, 'Is introduced as the jailer of reality and the entity to whom the protagonist is dangerous.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6727, 4505, 1570, 'ally', true, 'Warns that Yaldabaoth is waking up and the protagonist will soon face him, before fading away while complaining about non-interference clauses.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6728, 4510, 1570, 'mini-boss', false, 'His presence becomes an immediate threat as the snoring from the bedroom stops, indicating he is now aware.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6729, 3993, 1570, 'ally', false, 'Is left alone to process the terrifying news and face the imminent threat.', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_beat_appearances VALUES (6730, 2608, 1571, 'mini-boss', true, 'Bursts from the bedroom in a drunken rage, his heavy footsteps signaling the start of the assault.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6731, 3993, 1571, 'ally', false, 'Sits on the bathroom floor, realizing he is trapped and bracing for the inevitable violence.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6732, 2549, 1571, 'neutral', false, 'Her sobs are silenced by the father''s explosive entrance, and she scrambles to become invisible.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6733, 5168, 1571, 'ally', false, 'Internally screams for the protagonist to run and hide, highlighting the feeling of being trapped.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6734, 2608, 1572, 'mini-boss', true, 'Systematically and brutally beats the protagonist with his belt, demonstrating practiced cruelty.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6735, 5167, 1572, 'enemy', false, 'Used as a weapon to deliver methodical, bone-cracking strikes.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6736, 3993, 1572, 'ally', false, 'Endures the beating, suffering broken bones and immense pain, causing his consciousness to fragment and eventually black out.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6737, 2549, 1572, 'neutral', false, 'Watches the beating helplessly from the kitchen, screaming but too terrified to intervene.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6738, 5168, 1572, 'ally', false, 'Reacts to the assault by curling into a ball of pure terror.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6739, 5169, 1572, 'ally', false, 'Mentally surges with the desire to fight back but is powerless.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6740, 5170, 1572, 'ally', false, 'Watches with cosmic resignation, having foreseen this outcome.', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_beat_appearances VALUES (6741, 3993, 1573, 'ally', true, 'Wakes and experiences a moment of false hope before the terror of the loop''s start becomes real.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6742, 2550, 1573, 'enemy', true, 'Arrives in his familiar, human form and initiates the first beating of the cycle.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6743, 2549, 1573, 'neutral', false, 'Her whimpering from the kitchen provides the auditory backdrop for the impending violence.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6744, 5177, 1573, 'enemy', false, 'Is drawn from its loops, signifying the start of the physical assault.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6745, 5178, 1574, 'enemy', true, 'Rapidly accelerates through thousands of cycles, causing reality to fray and decay.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6746, 5179, 1574, 'enemy', false, 'Manifests as the environment becomes hostile and surreal, with pulsing walls and screaming curtains.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6747, 2550, 1574, 'enemy', false, 'His physical form degrades with the cycles, becoming more monstrous and inhuman.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6748, 2549, 1574, 'neutral', false, 'Her presence fades from a person to a sound, a memory, and then nothing as she is erased.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6749, 3993, 1574, 'ally', false, 'Endures the escalating horror and physical agony of the repeating cycles.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6750, 5180, 1575, 'enemy', true, 'Reveals itself as the true intelligence behind the torture, explaining that this is a punishment for the protagonist''s choice to ''remember.''', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6751, 3993, 1575, 'ally', false, 'Screams in conceptual ways and finally understands the cosmic, deliberate nature of his damnation.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6752, 2550, 1575, 'enemy', false, 'Has fully dissolved into a ''probability cloud of fists and fury,'' a mere instrument for the Orchestrator.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6753, 5177, 1575, 'enemy', false, 'Becomes a trans-dimensional weapon, inflicting pain across geometries and concepts.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6754, 5181, 1575, 'neutral', false, 'Appears in a mirror as a helpless, sorrowful observer of the final, revealed horror.', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_beat_appearances VALUES (6755, 3993, 1576, 'ally', true, 'Wakes up and processes the horrifying transformation of his bedroom into a surreal tannery-classroom, realizing the extreme wrongness of his situation.', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_beat_appearances VALUES (6756, 5188, 1576, 'neutral', false, 'Serve as a key visual horror, explaining the grotesque purpose of the room to the protagonist.', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_beat_appearances VALUES (6757, 5186, 1576, 'enemy', false, 'Exists as a menacing piece of the environment, bubbling and foreshadowing the danger to come.', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_beat_appearances VALUES (6758, 2550, 1577, 'mini-boss', true, 'Enters, administers a mock ''pop quiz'' about leather, and then calmly guides the protagonist toward the glowing vat for an ''immersive education''.', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_beat_appearances VALUES (6759, 3993, 1577, 'ally', false, 'Is rendered speechless with fear, fails the ''quiz'', and is gently but inexorably pushed backward into the vat, where he is dissolved.', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_beat_appearances VALUES (6760, 5185, 1577, 'enemy', false, 'Are used as a teaching prop by the father before being discarded, where they move unnaturally on the floor.', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_beat_appearances VALUES (6761, 5187, 1577, 'enemy', false, 'Embraces the protagonist as he falls into the vat, stripping away his skin, muscle, and consciousness.', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_beat_appearances VALUES (6762, 3993, 1578, 'ally', true, 'Wakes within the memory, experiencing both comfort and grief at its normalcy, and allows himself a moment of hope when his father appears kind.', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_beat_appearances VALUES (6763, 5193, 1578, 'neutral', false, 'Acts as the primary trigger for the protagonist''s emotional state, grounding the scene in a painful memory of domesticity.', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_beat_appearances VALUES (6764, 2549, 1578, 'neutral', false, 'Contributes to the atmosphere of safety by humming contentedly in the background.', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_beat_appearances VALUES (6765, 2608, 1578, 'ally', false, 'Appears as a kind, younger version of himself, offering to take his son fishing and sparking a brief fantasy of a normal relationship.', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_beat_appearances VALUES (6766, 5195, 1578, 'neutral', true, 'Manifests as the protagonist''s internal, fleeting hope for a loving connection, which defines the emotional peak of the beat.', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_beat_appearances VALUES (6767, 2608, 1579, 'mini-boss', true, 'Transforms into a grotesque monster, produces a leather knife, and calmly disembowels his son while narrating the process like a lesson.', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_beat_appearances VALUES (6768, 3993, 1579, 'ally', false, 'Is paralyzed with shock and horror, becoming the subject of his father''s surreal vivisection, his internal selves reacting with screams and fascination.', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_beat_appearances VALUES (6769, 5194, 1579, 'enemy', false, 'Serves as the impossible instrument of the father''s violence, parting the protagonist''s flesh with surgical precision.', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_beat_appearances VALUES (6770, 3993, 1580, 'ally', false, 'Regains consciousness and observes the surreal horrors of the room, feeling a profound sense of numbness from endless repetition.', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_beat_appearances VALUES (6771, 5199, 1580, 'enemy', true, 'Manifests with screaming walls, upward-falling blood, and impossible physics to torment the protagonist.', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_beat_appearances VALUES (6772, 5203, 1580, 'ally', false, 'Characterizes the protagonist''s internal state, a hollowed-out replacement for fear.', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_beat_appearances VALUES (6773, 2608, 1580, 'mini-boss', false, 'Enters the room wielding the Flaming Belt, ready to administer another ''lesson''.', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_beat_appearances VALUES (6774, 5202, 1580, 'enemy', false, 'Held by the father, it radiates heat and casts unnatural shadows, serving as the instrument of torture.', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_beat_appearances VALUES (6775, 3993, 1581, 'ally', false, 'Asks his father a question with a flat, resigned voice, triggering an unexpected reaction.', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_beat_appearances VALUES (6776, 2608, 1581, 'mini-boss', true, 'Stops mid-stride, his form flickering with uncertainty and confusion for the first time ever. His power falters, and he ends the scene with an expression of desperation.', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_beat_appearances VALUES (6777, 5203, 1581, 'ally', false, 'Acts as the catalyst that breaks the father''s confidence and control, revealing his power to be an illusion.', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_beat_appearances VALUES (8019, 6145, 1872, 'neutral', false, 'Manifests as a destabilizing dream world that presents moral challenges to the Father.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (6778, 2550, 1582, 'mini-boss', true, 'Glitches and degenerates, revealing the protagonist''s true name (''Aspolin'') and the purpose of the loop before transforming into the Demiurge, Yaldabaoth.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6779, 3993, 1582, 'ally', false, 'Observes the horrific transformation of his father and learns his true name and the nature of his imprisonment.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6780, 5207, 1582, 'enemy', false, 'Acts as a tool of the father, its predatory eyes tracking the protagonist.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6781, 3993, 1583, 'ally', true, 'Calmly confronts Yaldabaoth, deconstructing its divinity with philosophical arguments and pointing out its weakness, causing reality to fracture.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6782, 2550, 1583, 'mini-boss', false, 'Expands its form and creates a cathedral of light, commanding the protagonist to kneel. Its power falters and its voice trembles when faced with disbelief.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6783, 5208, 1583, 'enemy', false, 'Provide the agonizing auditory backdrop to Yaldabaoth''s divine manifestation, then fall silent as its power wavers.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6784, 2550, 1584, 'mini-boss', true, 'Erupts in a childish tantrum of rage and denial, attempting one final, desperate reset by dragging the protagonist through all his past traumas before self-destructing.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6785, 3993, 1584, 'ally', false, 'Endures the forced regression through his past deaths and pains as the entity makes its final, futile move.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6786, 3993, 1585, 'ally', true, 'Floats in the peaceful void left by the entity''s destruction, finally free and feeling gratitude for the silence.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6787, 5209, 1585, 'neutral', false, 'Represents the aftermath of the conflict and the protagonist''s newfound freedom.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6788, 5210, 1585, 'unknown', false, 'Offers a single, brief line of approval before the scene ends in total silence.', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_beat_appearances VALUES (6789, 3993, 1586, 'ally', true, 'Awakens in the waiting room, experiencing a disorienting sense of déjà vu and recognizing the oppressive nature of the space.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6790, 5216, 1586, 'neutral', false, 'Establishes the aching, void-like atmosphere of the room.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6791, 5217, 1586, 'neutral', false, 'Serves as a symbol of the frozen, eternal conflict the protagonist is trapped in.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6792, 4505, 1587, 'ally', true, 'Cuts through the silence to explain the central paradox: I AM has trapped himself in a finite box with the one person who never believed in him.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6793, 2550, 1587, 'mini-boss', false, 'Is the subject of Benji''s explanation; his power causes the walls of the room to flicker in response.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6794, 3993, 1587, 'ally', false, 'Listens to Benji''s explanation, beginning to understand the nature of his imprisonment.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6795, 3993, 1588, 'ally', true, 'Has the sudden, terrible realization that I AM is the foundation of all reality and cannot be destroyed without annihilating everything.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6796, 5220, 1588, 'neutral', false, 'Manifests as an idea or inherited knowledge within the protagonist, defining the ultimate stakes.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6797, 5219, 1588, 'unknown', false, 'Are mentioned as the original jailers of I AM, providing context for his containment.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6798, 4505, 1589, 'ally', true, 'Reveals the ''beautiful part'' of the situation: the isolation provides the protagonist with privacy to confront I AM and answer the question of a god''s mortality without witnesses.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6799, 5221, 1589, 'ally', false, 'Is identified as the key strategic advantage given to the protagonist by I AM''s mistake.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6800, 2550, 1589, 'mini-boss', false, 'His presence causes the door to shudder violently, demonstrating his power and the instability of the prison just before the final confrontation is framed.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6801, 3993, 1589, 'ally', false, 'Receives Benji''s final, chilling explanation and prepares for the ultimate question.', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_beat_appearances VALUES (6802, 2550, 1590, 'mini-boss', true, 'Enters the scene as a writhing, corrupted entity and makes a declaration of his power.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6803, 3993, 1590, 'ally', true, 'Confronts the entity, reminding it that he has defeated and consumed it once before.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6804, 5227, 1590, 'enemy', false, 'Manifests around I AM, smearing the room with bleeding pixels and backwards mathematics.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6805, 2550, 1591, 'mini-boss', true, 'Taunts the protagonist about his past failures and reveals that Jamie is his creation designed for control.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6806, 3993, 1591, 'ally', true, 'Is emotionally wounded by the truth in the taunts, which triggers his rage.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6807, 2544, 1591, 'neutral', false, 'Is mentioned as a psychological tool used by I AM.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6808, 5228, 1591, 'ally', false, 'Begins to build within the protagonist like a ''nuclear reactor going critical''.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (7316, 5622, 1714, 'neutral', false, 'Acts as the catalyst for the vision, its cover growing hot to the touch.', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_beat_appearances VALUES (6809, 3993, 1592, 'ally', true, 'Attacks I AM and engages in a brutal, reality-breaking fight, eventually declaring he no longer cares if reality is destroyed.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6810, 2550, 1592, 'mini-boss', true, 'Fights back, explaining he was rebuilt by The Outsiders and is the substrate of reality.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6811, 5219, 1592, 'unknown', false, 'Are mentioned by I AM as the ones who rebuilt him.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6812, 3993, 1593, 'ally', true, 'Channels the muscle memory of his older self to deliver a perfect roundhouse kick that decapitates and completely destroys I AM.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6813, 2550, 1593, 'mini-boss', true, 'Shows terror for the first time before his head is kicked off and shatters into dust.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6814, 5227, 1593, 'enemy', false, 'Accelerates into a total collapse of the waiting room following I AM''s destruction.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6815, 2544, 1593, 'neutral', false, 'Is invoked by the protagonist as the reason for the final blow.', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_beat_appearances VALUES (6816, 5231, 1594, 'neutral', true, 'Applauds the protagonist and confirms that by killing the god, he has ended all of reality.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6817, 3993, 1594, 'ally', false, 'Observes the collapsing reality and asks if it is over.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6818, 982, 1594, 'neutral', false, 'Represents the ''collapsing everything'' that Benji gestures towards.', '2026-02-28 19:34:54.279468-05');
