INSERT INTO public.entity_beat_appearances VALUES (6820, 3993, 1595, 'ally', true, 'Asks about the fate and reality of Jamie.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6821, 5231, 1595, 'neutral', true, 'Explains Jamie''s paradoxical nature as both a real creation of the protagonist and a beautiful lie.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6822, 2544, 1595, 'ally', true, 'Is the subject of the conversation, her existence and reality being questioned and defined.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6823, 3993, 1596, 'ally', true, 'Dissolves into the void, feeling a sense of peace and relief while asking one last vulnerable question.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6824, 982, 1596, 'neutral', true, 'Actively dissolves the protagonist and Benji, described as static and a warm, silent void.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6825, 5231, 1596, 'neutral', false, 'Offers a final, cryptic, and meta-textual farewell before he also dissolves.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6826, 5235, 1596, 'neutral', false, 'Manifests within the protagonist as he dissolves.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6827, 5236, 1596, 'unknown', false, 'Mentioned by Benji as a hint that this ending is not final.', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_beat_appearances VALUES (6828, 3993, 1597, 'ally', true, 'Awakens and is hit with a profound sense of normalcy, finding solace as his memories of S Corp and his cosmic duties fade away.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6829, 2549, 1597, 'ally', false, 'Her warm presence in the bed contributes to the protagonist''s feeling of comfort and domestic peace.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6830, 831, 1597, 'ally', false, 'His happy chatter from the living room forms a key part of the ordinary morning atmosphere.', '2026-02-28 19:35:54.489486-05');
