INSERT INTO public.entity_beat_appearances VALUES (6832, 4091, 1597, 'neutral', false, 'Fades from the protagonist''s mind, lifting a great weight from him.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6833, 2297, 1597, 'neutral', false, 'Mentioned as a fading, dream-like memory, representing the grand life the protagonist is forgetting.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6834, 465, 1597, 'neutral', false, 'The game the son is playing, contributing to the auditory environment.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6835, 2549, 1598, 'ally', true, 'With a huge grin, she rolls over and excitedly announces that they have won a contest, showing the proof on her phone.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6836, 3993, 1598, 'ally', false, 'Receives the news from his wife and experiences a brief, passing moment of déjà vu about the prize.', '2026-02-28 19:35:54.489486-05');
