INSERT INTO public.entity_beat_appearances VALUES (6838, 4102, 1598, 'neutral', false, 'Mentioned as the catalyst for their contest entry and subsequent win.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6839, 5243, 1598, 'neutral', false, 'The event they have won, providing the central news of the beat.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6840, 4090, 1598, 'neutral', false, 'The destination prize of the contest, introduced as a marvel in space.', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_beat_appearances VALUES (6841, 3993, 1599, 'ally', true, 'Rises from bed, contemplates the day, and decides to make breakfast while being haunted by the name ''Jamie''.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6842, 2549, 1599, 'ally', false, 'Joins her husband in the kitchen and asks about his upcoming trip to Lysteria.', '2026-02-28 19:36:44.274997-05');
