INSERT INTO public.entity_beat_appearances VALUES (6845, 5253, 1600, 'mini-boss', true, 'Manifests as a sudden, violent image of a dark-eyed woman reaching for him amidst flames.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6846, 3993, 1601, 'ally', true, 'Involuntarily speaks the name ''Sorhhinda'', freezing in confusion and alarming his family.', '2026-02-28 19:36:44.274997-05');
