INSERT INTO public.entity_beat_appearances VALUES (6851, 3993, 1602, 'ally', false, 'Is physically and emotionally overwhelmed by a flood of memories and grief.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6852, 4703, 1602, 'neutral', false, 'Acts as the catalyst, triggering the full memory cascade.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6853, 5253, 1602, 'mini-boss', true, 'Unleashes a torrent of sensory details: her laugh, her touch, a church, sand, fire, and the pain of her death.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6854, 3993, 1603, 'ally', true, 'Contrasts the safe, passionless love of his wife with the fiery, rebellious love he shared with Jamie, feeling the profound loss.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6855, 2549, 1603, 'ally', false, 'Represents safe, predictable, and passionless love in the protagonist''s mind.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6856, 2544, 1603, 'ally', false, 'Represents fire, rebellion, and a passionate, all-consuming love that has been lost.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6857, 5253, 1603, 'mini-boss', false, 'Begins to fade, causing a new wave of panic and grief as the protagonist fears losing her again.', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_beat_appearances VALUES (6858, 3993, 1604, 'ally', false, 'Experiences a series of wrong sensory inputs: waffles taste like ash, his wife''s face flickers, and his son''s laughter loops.', '2026-02-28 19:37:41.028865-05');
