INSERT INTO public.entity_beat_appearances VALUES (6861, 851, 1604, 'ally', false, 'His laughter repeats like a broken record, adding to the unsettling atmosphere.', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_beat_appearances VALUES (6862, 5264, 1604, 'neutral', false, 'Taste like ash, contradicting their appearance.', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_beat_appearances VALUES (6863, 5266, 1604, 'mini-boss', true, 'Whispers a cryptic and menacing message to the protagonist, heightening his sense of dread.', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_beat_appearances VALUES (6864, 3993, 1605, 'ally', false, 'Is frozen mid-motion while trying to drink his coffee, becoming a helpless observer of the stasis.', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_beat_appearances VALUES (6865, 1134, 1605, 'neutral', false, 'Hangs frozen in the air, its steam rising in impossible, static spirals.', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_beat_appearances VALUES (6866, 5267, 1605, 'enemy', true, 'Manifests fully, freezing the protagonist, the environment, and the sun in the sky.', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_beat_appearances VALUES (6867, 3993, 1606, 'ally', true, 'Finds himself back in his real home in Florida, the strange experience fading as he grounds himself in the mundane reality of his life.', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_beat_appearances VALUES (6868, 2549, 1606, 'ally', false, 'Is heard humming normally in the kitchen.', '2026-02-28 19:37:41.028865-05');
