INSERT INTO public.entity_beat_appearances VALUES (6872, 3993, 1607, 'ally', true, 'Searches for jobs and begins the tedious process of updating his resume after finding a promising position at ExSpacey.', '2026-02-28 19:38:22.705997-05');
