INSERT INTO public.entity_beat_appearances VALUES (8020, 6143, 1872, 'enemy', false, 'Tempt the Father with offers of power, fame, and money, then flee in panic when the world collapses.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (6885, 3993, 1609, 'ally', true, 'Unconsciously speaks the word ''Etheris'' instead of ''Earth'', causing him to freeze in confusion and fear as his hands begin to shake.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6886, 2536, 1609, 'unknown', false, 'The word emerges from the protagonist''s mouth, triggering his state of alarm and the shift in the room''s atmosphere.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6887, 5287, 1610, 'neutral', true, 'A cascade of forgotten, traumatic memories is unlocked in the protagonist''s mind upon hearing Whitney''s name.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6888, 3993, 1610, 'ally', false, 'Is confronted by his wife with a phone call, hears Whitney''s name, and is overwhelmed by the sudden return of his past. He drops the phone in shock.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6889, 2549, 1610, 'ally', false, 'Enters the room looking pale and frightened, presenting the phone call from Whitney to her husband.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6890, 4342, 1610, 'unknown', false, 'Her name and voice from the phone act as the direct trigger for the protagonist''s memory recall. She attempts to deliver an urgent message about finding Jay.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6891, 1042, 1610, 'neutral', false, 'Acts as the physical medium for Whitney''s impossible call, connecting the protagonist to his forgotten past.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6892, 2544, 1610, 'enemy', false, 'Recalled in a memory fragment as ''the demon in Jamie''s smile''.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6893, 5293, 1610, 'unknown', false, 'Mentioned by Whitney as someone she has found, adding urgency and mystery to the call before it cuts out.', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_beat_appearances VALUES (6894, 3993, 1611, 'ally', true, 'Loses his job and decides this is the moment to finally write the book that has been in his head for two decades.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6895, 5299, 1611, 'neutral', false, 'The loss of this job acts as the catalyst for the author''s creative endeavor.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6896, 20, 1611, 'neutral', false, 'Exists as a 20-year-old idea that the author is now ready to manifest.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6897, 3993, 1612, 'ally', true, 'Writes the book, evolves its themes, seeks out publishers unsuccessfully, and ultimately decides to self-publish.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6898, 20, 1612, 'neutral', false, 'Is written over 6 months, with its themes evolving to include occult magic and politics.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6899, 5302, 1612, 'neutral', false, 'Is described as the initial, somewhat ''boring'' premise for the book.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6900, 5300, 1612, 'neutral', false, 'Reject the author''s manuscript over a 12-month period.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6901, 5301, 1612, 'neutral', false, 'Becomes the chosen platform for the book''s publication on February 6, 2025.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6902, 3993, 1613, 'ally', true, 'Declares the story of Elysium Rising complete and clarifies the purpose of Sorhhinda.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6903, 20, 1613, 'neutral', false, 'Is referred to as a completed story.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6904, 3326, 1613, 'neutral', false, 'Is defined as an unfinished teaser, fulfilling its intended purpose.', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_beat_appearances VALUES (6905, 3993, 1614, 'ally', true, 'Accepts a writing challenge, writes one chapter, and then succumbs to writer''s block.', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_beat_appearances VALUES (6906, 5305, 1614, 'neutral', false, 'Serves as the catalyst that prompts the author to begin writing.', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_beat_appearances VALUES (6907, 5306, 1614, 'neutral', false, 'Is created but its progress is halted after the first chapter.', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_beat_appearances VALUES (6908, 5307, 1614, 'mini-boss', true, 'Manifests and halts all creative progress for nearly a month, causing the author to feel creatively ''dead''.', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_beat_appearances VALUES (6909, 2544, 1615, 'ally', true, 'Appears in the author''s dreams, begging to be brought to life and breaking his writer''s block.', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_beat_appearances VALUES (6910, 3993, 1615, 'ally', true, 'Is haunted by his character''s plea and finds the motivation to continue the story.', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_beat_appearances VALUES (6911, 5308, 1615, 'neutral', false, 'Acts as the medium through which the character Jamie communicates with the author.', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_beat_appearances VALUES (6912, 3993, 1616, 'ally', true, 'Reflects on their writing process, the book''s length, and the constraints of the 90-day deadline.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6913, 5311, 1616, 'neutral', true, 'Is described as being 124k words and rougher than the first due to a tight deadline.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6914, 5312, 1616, 'neutral', false, 'Serves as a benchmark for quality, being less rough than the current book.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6915, 5313, 1616, 'neutral', false, 'Mentioned as an example of the author''s tendency to write excessively long first drafts.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6916, 3993, 1617, 'ally', true, 'Expresses hope to hire an editor and improve the books if they are successful.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6917, 5314, 1617, 'ally', false, 'Represents the potential for professional refinement of the author''s work.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6918, 5315, 1617, 'neutral', false, 'Are the hypothetical, streamlined future versions of the author''s work.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6919, 3993, 1618, 'ally', true, 'States that editing must wait for the completion of the next writing challenge.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6920, 5317, 1618, 'neutral', false, 'Is the next project, taking priority over editing the previous books.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6921, 5316, 1618, 'neutral', true, 'Is the upcoming event that dictates the author''s immediate schedule and priorities.', '2026-02-28 19:41:20.990247-05');
INSERT INTO public.entity_beat_appearances VALUES (6922, 5322, 1619, 'neutral', true, 'Presented as the title of the work.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6923, 19, 1619, 'neutral', false, 'Credited as the author and copyright holder.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6924, 26, 1620, 'neutral', false, 'Identified as the publisher.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6925, 5322, 1620, 'neutral', true, 'Assigned ISBNs and legal rights are detailed for it.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6926, 19, 1620, 'neutral', false, 'Named as the contact for permission requests.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6927, 5322, 1621, 'neutral', true, 'Its fictional nature is disclaimed and its various edition publication dates are listed.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6928, 5322, 1622, 'neutral', true, 'Summarized in a synopsis, providing the core premise of the story.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6929, 4154, 1622, 'neutral', false, 'Credited with providing cataloging information.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6930, 3993, 1622, 'ally', false, 'Introduced as the protagonist in the synopsis.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6931, 4141, 1622, 'ally', false, 'Introduced as the protagonist''s son in the synopsis.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6932, 2536, 1622, 'neutral', false, 'Introduced as the setting, a spiritual prison.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6933, 2550, 1622, 'mini-boss', false, 'Introduced as the parasitic demiurge Yaldabaoth, the ruler of Etheris.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6934, 5325, 1623, 'neutral', true, 'Presented to the reader as a content advisory.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6935, 5326, 1623, 'neutral', false, 'Mentioned to establish series continuity.', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_beat_appearances VALUES (6936, 3993, 1624, 'ally', true, 'Initiates an invocation, calling to the Summer Babes and offering gifts.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6937, 5332, 1624, 'neutral', false, 'Are summoned and addressed by the speaker.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6938, 5334, 1624, 'neutral', false, 'Offered as a gift.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6939, 5335, 1624, 'neutral', false, 'Offered as a gift to protect against The Night.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6940, 5333, 1624, 'enemy', false, 'Identified as the threat that the speaker''s gifts are meant to counter.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6941, 3993, 1625, 'ally', true, 'Warns against focusing on the future and advises cherishing the present.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6942, 5332, 1625, 'neutral', false, 'Receive counsel on how to perceive time.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6943, 1839, 1625, 'neutral', false, 'Presented as a dangerous fantasy to be ignored.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6944, 5337, 1625, 'neutral', false, 'Presented as the only thing worthy of care.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6945, 3993, 1626, 'ally', false, 'Describes the first category of lost souls as a cautionary example.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6946, 5338, 1626, 'neutral', true, 'Are described as lost, dreaming, and suffering from their own actions.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6947, 5343, 1626, 'enemy', false, 'Afflicts the souls as a consequence of their nature.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6948, 3993, 1627, 'ally', false, 'Describes the second category of willfully ignorant souls.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6949, 5339, 1627, 'neutral', true, 'Are described as being rapt in games and refusing to see reality.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6950, 5340, 1627, 'enemy', false, 'Surrounds and blinds the ignorant souls.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6951, 3993, 1628, 'ally', true, 'Bestows a final gift and calls upon the babes to strive for wisdom.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6952, 5332, 1628, 'neutral', false, 'Are given a final charge to grow and improve.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6953, 5341, 1628, 'neutral', false, 'Offered as the speaker''s final gift.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6954, 5342, 1628, 'neutral', false, 'Presented as the ultimate, everlasting reward for their efforts.', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_beat_appearances VALUES (6955, 2550, 1629, 'mini-boss', true, 'Declares himself the foundation of reality and threatens mutual annihilation to intimidate the child.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6956, 3993, 1629, 'ally', false, 'Smiles and calmly accepts the cost of mutual annihilation, stating he no longer cares.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6957, 5348, 1629, 'neutral', false, 'Is named by Yaldabaoth as his own identity, establishing the stakes of the conflict.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6958, 2550, 1630, 'mini-boss', false, 'Recoils as his logic fractures, experiences fear for the first time, and attempts to appeal to the child''s past humanity.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6959, 3993, 1630, 'ally', true, 'Strikes Yaldabaoth with impossible force and reveals its true, consuming nature, rejecting its human past.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6960, 5349, 1630, 'neutral', false, 'Manifests within Yaldabaoth, causing his divine form to glitch and his composure to break.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6961, 2550, 1631, 'mini-boss', false, 'Desperately proposes an eternal stalemate as his only remaining option.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6962, 3993, 1631, 'ally', true, 'Laughs off the stalemate, references a past tournament, and channels immense power for a final attack.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6963, 5350, 1631, 'neutral', false, 'Is referenced by the child as a key to unlocking its final attack.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6964, 5351, 1631, 'ally', false, 'Is channeled by the child, becoming the fuel for the final blow.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6965, 2550, 1632, 'mini-boss', true, 'Is struck, has his consciousness severed, and experiences his own deletion from existence as his head falls.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6966, 3993, 1632, 'ally', false, 'Delivers the final, universe-ending kick.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6967, 5352, 1632, 'enemy', false, 'Tumbles end-over-end and strikes the floor, triggering the end of the universe.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6968, 5353, 1632, 'neutral', false, 'Serves as the impact point that causes reality to shatter.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (6969, 5354, 1632, 'neutral', false, 'Shatters upon impact, representing the final dissolution of reality.', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_beat_appearances VALUES (7081, 5438, 1661, 'neutral', false, 'Are consumed dry, one after another, until the bottle is empty.', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_beat_appearances VALUES (7030, 3993, 1647, 'ally', true, 'Experiences the complete dissolution of his physical form, his consciousness scattering as his body is destroyed.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7031, 2549, 1647, 'unknown', false, 'Watches her husband''s transformation with an unnerving, placid detachment, her expression of concern feeling simulated and false.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7032, 5395, 1647, 'enemy', false, 'Serves as the final executioner when Stephen''s heart fails to synchronize with it, tearing itself apart.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7033, 204, 1647, 'neutral', false, 'Consumes Stephen''s consciousness at the end of his transformation.', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_beat_appearances VALUES (7034, 3993, 1648, 'ally', true, 'Wakes up and discusses the hopelessness of his job search and the slim chance of hearing back from Synergex.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7035, 2549, 1648, 'neutral', true, 'Prompts her husband about the Synergex email and joins him in reciting the catechism of corporate rejection.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7036, 5402, 1648, 'enemy', false, 'Is established as the central conflict and source of Stephen''s despair, having involved thousands of failed applications.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7037, 5401, 1648, 'neutral', false, 'Mentioned as the latest potential employer, representing a focal point of anxiety.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7038, 2549, 1649, 'mini-boss', true, 'Her demeanor shifts from warm to cold and clinical, insisting that Stephen must continue applying for jobs in a detached, logical manner.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7039, 3993, 1649, 'ally', false, 'Notices his wife''s alien change in behavior and feels unable to face another day of applying.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7040, 5404, 1649, 'enemy', false, 'Begins to manifest as the wife''s warmth is replaced by a cold, pressuring logic.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7041, 5403, 1650, 'unknown', true, 'Appears on the wife''s phone with a shimmering, unreadable number, causing confusion for Stephen before the phone locks itself.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7042, 3993, 1650, 'ally', false, 'Attempts to read the phone number but finds it impossible, experiencing a moment of pure confusion and memory lapse.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7043, 2549, 1650, 'mini-boss', false, 'Casually shows her husband the strange call she doesn''t remember, then dismisses the incident with a pleasant smile.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7044, 2549, 1651, 'mini-boss', true, 'Her expression inverts as she coldly criticizes Stephen''s plan to relax, escalating the argument and accusing him of not doing enough.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7045, 5404, 1651, 'enemy', true, 'Erupts into an open, sharp conflict, filling the kitchen with defensiveness and the feeling of uselessness.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7046, 3993, 1651, 'ally', false, 'Defends his need for a break from the job search, but is ultimately left alone with his cold coffee, feeling defeated.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7047, 5405, 1651, 'neutral', false, 'Mentioned as Stephen''s desired form of escape, which his wife dismisses as unproductive.', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_beat_appearances VALUES (7048, 3993, 1652, 'ally', true, 'Sits paralyzed by inertia, unable to apply for jobs and surrounded by physical manifestations of his decay.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7049, 1030, 1652, 'enemy', false, 'Presents an endless, meaningless scroll of corporate jobs that feel like a coffin.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7050, 5409, 1652, 'enemy', false, 'Manifests as the clutter and decay in the office, reflecting Stephen''s mental state.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7051, 2549, 1653, 'neutral', true, 'Performs a calculated, stiff hug as a ''down payment'' for Stephen''s promise to apply for jobs.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7052, 3993, 1653, 'ally', false, 'Receives the hug, recognizes its transactional nature, and feels a desperate, ugly flare of hope.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7053, 5411, 1653, 'neutral', false, 'Manifests as the hug, a gesture that feels like a system glitch and reinforces the transactional rules of the relationship.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7054, 3993, 1654, 'ally', true, 'Escapes into his video game, finds a hollow victory, and is then rejected by his wife, leaving him completely alone and without options.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7055, 5412, 1654, 'neutral', false, 'Serves as a temporary escape that ultimately provides no solace, as it is complete and empty.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7056, 5414, 1654, 'mini-boss', false, 'Confirms the finality of the game, stating ''There is nothing left to do,'' mirroring Stephen''s real-life predicament.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7057, 2549, 1654, 'neutral', false, 'Rejects Stephen''s bid for physical contact, citing a headache and creating an ''impenetrable wall'' between them.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7058, 5415, 1654, 'enemy', false, 'Acts as the final barrier, severing Stephen''s last attempt at finding connection.', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_beat_appearances VALUES (7059, 3993, 1655, 'ally', false, 'Performs the ritual of checking his email and receives the expected rejection.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7060, 5420, 1655, 'enemy', true, 'Sends the rejection email that confirms Stephen''s professional failure.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7061, 5419, 1655, 'enemy', false, 'Manifests as a confirmed loop, cementing Stephen''s despair.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7062, 5427, 1655, 'neutral', false, 'Serves as the medium for the bad news, becoming a ''tombstone'' for his career.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7063, 3993, 1656, 'ally', false, 'Makes a desperate advance for physical contact, but withdraws in shame.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7064, 2549, 1656, 'mini-boss', true, 'Rejects his touch by physically hardening her body into ''stone'', remaining silent and still.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7065, 3545, 1656, 'enemy', false, 'Arises from the rejection and the memory of past, loveless intimacy.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7066, 3993, 1657, 'ally', false, 'Tries to recall his wife''s name and is overcome with panic when he cannot.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7067, 5422, 1657, 'enemy', true, 'Manifests as a ''404 error'' in his brain, representing the ultimate disconnect.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7068, 370, 1657, 'enemy', false, 'Washes over Stephen as a cold, electric wave due to his memory failure.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7069, 2549, 1657, 'enemy', false, 'Finally speaks, using his name and unknowingly twisting the knife of his cognitive failure.', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_beat_appearances VALUES (7070, 3993, 1658, 'ally', true, 'Lies in bed waiting for his wife, crying into his pillow while trying to remain silent.', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_beat_appearances VALUES (7071, 5433, 1658, 'neutral', false, 'Serves as the physical space of his isolation and grief.', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_beat_appearances VALUES (7072, 5434, 1658, 'enemy', true, 'Acts as the primary fear motivating Stephen to hide his crying, as he believes discovering it would break him.', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_beat_appearances VALUES (7073, 2549, 1658, 'neutral', false, 'Her absence from the bed is the reason for Stephen''s vigil and a symbol of their separation.', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_beat_appearances VALUES (7074, 3993, 1659, 'ally', true, 'Succumbs to a spiral of self-hatred, internalizing his failures and arriving at the decision to end his life.', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_beat_appearances VALUES (7075, 5432, 1659, 'mini-boss', true, 'Dominates Stephen''s thoughts, convincing him he is a destructive ''black hole'' and the source of all his family''s problems.', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_beat_appearances VALUES (7076, 5435, 1659, 'enemy', false, 'Emerges as the final, calm outcome of the internal torment, presenting suicide as a rational solution.', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_beat_appearances VALUES (7077, 4141, 1659, 'neutral', false, 'Mentioned as another victim of Stephen''s perceived negative influence, reinforcing Stephen''s belief that his absence would be a benefit.', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_beat_appearances VALUES (7078, 3993, 1660, 'ally', true, 'Rises from bed and moves with mechanical precision to the bathroom, locating the medicine.', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_beat_appearances VALUES (7079, 5438, 1660, 'neutral', false, 'Are selected from a cluttered drawer under the sink.', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_beat_appearances VALUES (7080, 3993, 1661, 'ally', true, 'Methodically consumes the entire bottle of pills, returns the empty bottle, and lies down in the mattress divot to wait.', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_beat_appearances VALUES (7082, 5439, 1661, 'mini-boss', true, 'Is the awaited outcome of the body''s actions, equated with a final sleep that is about to take over.', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_beat_appearances VALUES (7083, 5440, 1661, 'neutral', false, 'The body settles into this cold space on the bed to await the end.', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_beat_appearances VALUES (7084, 3993, 1662, 'ally', true, 'Awakens in a disoriented state, trying to make sense of the strange, grey environment.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7085, 5450, 1662, 'neutral', false, 'Presents its disorienting and contradictory nature to the protagonist (damp but not wet, grey, etc.).', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7086, 3993, 1663, 'ally', true, 'Experiences a profound sense of wrongness triggered by a smell and the sensation of phantom limbs.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7087, 5445, 1663, 'neutral', false, 'Crawls up the protagonist''s nostrils, triggering a memory or recognition that doesn''t belong to their current form.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7088, 5446, 1663, 'neutral', false, 'Manifests as an itch and spasm in the protagonist''s shoulder blades, confirming that their body is not their own.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7089, 3993, 1664, 'ally', true, 'Observes the inhabitants of the purgatory and discovers with dawning horror that they are all trapped in a repeating loop.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7090, 5444, 1664, 'neutral', false, 'Perform their repetitive actions at precise intervals, providing the evidence of the loop.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7091, 5447, 1664, 'enemy', false, 'Its nature is revealed through the actions of the people it has trapped.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7092, 5448, 1665, 'mini-boss', true, 'Acts as a defense mechanism of the purgatory, inflicting excruciating pain on the protagonist when they try to interact with it.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7093, 3993, 1665, 'ally', false, 'Reaches for a real object, touches the magazine, and is psychically assaulted, causing their eyes to bleed before they collapse.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7094, 5450, 1665, 'neutral', false, 'The world spins and goes dark as the protagonist is overwhelmed.', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_beat_appearances VALUES (7095, 3993, 1666, 'ally', true, 'Awakens with memory of the loop, sees the ''strings'' on other souls, and feels terror as he senses a hostile presence.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7096, 5447, 1666, 'enemy', false, 'Provides the oppressive, repeating context that the protagonist now recognizes.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7097, 5456, 1666, 'neutral', false, 'Observed by the protagonist as evidence of the artificiality of his reality.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7098, 5455, 1666, 'enemy', false, 'Its presence is sensed as a direct response to the protagonist''s newfound awareness, causing the air to ''grow teeth''.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7099, 5453, 1667, 'mini-boss', true, 'Appears from the impossible coffee shop, diagnoses the protagonist''s ''leaking consciousness'', and compels him to come inside for an interrogation.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7100, 3993, 1667, 'ally', false, 'Is confronted by the woman and follows her into the coffee shop against his will.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7101, 5457, 1667, 'neutral', false, 'Serves the Memory Tea without acknowledgement, reinforcing the location''s artificiality.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7102, 5458, 1667, 'neutral', false, 'Is served to the protagonist as a tool for the interrogation.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7103, 5453, 1668, 'mini-boss', true, 'Conducts a deep interrogation, questioning the protagonist''s identity and revealing her true, powerful nature.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7104, 3993, 1668, 'ally', false, 'Drinks the tea, experiences memory fragments, and ultimately recalls the signal from Whitney, leading to the realization that he was deliberately positioned.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7105, 5459, 1668, 'neutral', false, 'Are triggered by the tea and the woman''s questions, providing clues to the protagonist''s former identity.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7106, 5462, 1668, 'ally', false, 'Is remembered by the protagonist, providing the final clue that his survival was not an accident.', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_beat_appearances VALUES (7107, 5465, 1669, 'mini-boss', true, 'Reveals her inhuman nature with mouths for corneas and rippling skin while interrogating the protagonist about ''the signal''.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7108, 3993, 1669, 'ally', false, 'Is trapped and terrified by the woman, unable to process her inhuman features and the intensity of the interrogation.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7109, 3591, 1669, 'unknown', false, 'Serves as the obsessive focus of the interrogation.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7110, 5465, 1670, 'mini-boss', true, 'Begins to malfunction and deconstruct, her voice skipping and her body melting into geometry as the vessel fails.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7111, 5469, 1670, 'enemy', false, 'Becomes visible, undulating beneath the woman''s now-translucent skin.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7112, 5470, 1670, 'unknown', false, 'Is seen pulsing deep within the woman''s impossible anatomy.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7113, 3993, 1670, 'ally', false, 'Is paralyzed with terror, pressing himself into the booth to escape the horrifying deconstruction of his captor.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7114, 3591, 1670, 'unknown', false, 'Is repeated obsessively until the word itself fragments and collapses into a hum.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7115, 2608, 1671, 'ally', true, 'Emerges from the failed vessel, solidifying into her true form. She comforts Benji, reveals she was trapped, and gently triggers a true memory.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7116, 3993, 1671, 'ally', false, 'Is overcome with shock and relief, recognizing his lover and breaking down in tears as she comforts him.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7117, 5468, 1671, 'enemy', false, 'Is named as the entity who trapped Lady Illkeserod in the vessel.', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_beat_appearances VALUES (7118, 5231, 1672, 'ally', true, 'Experiences the memory of his true nature as an observer consciousness, existing outside of linear time.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7119, 2608, 1672, 'ally', false, 'Remembered as Benji''s partner, a vast merged consciousness who oversees the Akashic Records.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7120, 5485, 1672, 'neutral', false, 'Mentioned as the domain that Ilse oversees, holding the memory of all things.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7121, 5231, 1673, 'ally', true, 'Recalls his mission to audit Etheris, his conversion by the prison, and his eventual targeting and deletion by the Purge Protocols.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7122, 2536, 1673, 'neutral', false, 'The setting of the memory, a prison-realm that has been corrupted.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7123, 2550, 1673, 'mini-boss', true, 'Identified as the corrupting force that feeds on the suffering of souls within Etheris.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7124, 3993, 1673, 'ally', false, 'Remembered as a younger, fiercely loving man whose soul was shredded alongside Jamie''s.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7125, 2544, 1673, 'ally', false, 'Remembered as an archon whose soul was shredded alongside Stephen''s in an eternal loop of suffering.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7126, 5482, 1673, 'enemy', false, 'The system process that recognized Benji as foreign and attempted to delete him.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7127, 5479, 1673, 'enemy', false, 'The original entity that infected the prison.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7128, 5478, 1673, 'neutral', false, 'Mentioned as the original creators of Etheris.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7129, 456, 1673, 'neutral', false, 'A machine that facilitated the dimensional torment of Stephen and Jamie.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7130, 5468, 1673, 'neutral', false, 'A chaotic entity existing at the foundation of the prison.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7131, 3993, 1674, 'ally', true, 'Returns to present awareness in the booth, his body trembling as his full consciousness (Benji) is restored.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7132, 5231, 1674, 'ally', true, 'His consciousness fully returns, reintegrating with his fragmented self and becoming whole.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7133, 2608, 1674, 'ally', false, 'Kneels before the protagonist, confirming his return to wholeness.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7134, 3591, 1674, 'ally', false, 'Identified as the key element from outside that anchored Benji''s consciousness and prevented his erasure.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7135, 4342, 1674, 'ally', false, 'Named as the source of the life-saving signal.', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_beat_appearances VALUES (7136, 2608, 1675, 'ally', true, 'Explains that Whitney has escaped, the prison is weakening, and that this provides an opportunity to rescue Stephen and others.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7137, 3993, 1675, 'ally', false, 'Listens and processes the new information, realizing the implications of Whitney''s escape.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7138, 5489, 1675, 'ally', false, 'Mentioned as the catalyst for the events, having escaped the prison and sent a signal back.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7139, 982, 1675, 'enemy', false, 'Discussed as the ''prison'' which is now weakening and has ''cracks''.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7141, 2550, 1675, 'big-boss', false, 'Mentioned as the entity feeding on the souls of those trapped in the prison.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7142, 2608, 1676, 'ally', false, 'Warns Benji about the imminent danger from the collectors and expresses her worry.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7143, 3993, 1676, 'ally', true, 'Accepts the danger, remembers his true nature as a warrior and his love for Ilse, and declares ''Let them come''.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7144, 5460, 1676, 'enemy', false, 'Introduced as a looming threat that will hunt them now that they are ''awake''.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7145, 2608, 1677, 'ally', false, 'Opens the door to the seam in reality and leads Benji through it.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7146, 3993, 1677, 'ally', false, 'Steps through the seam with Ilse, escaping the purgatory.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7147, 5493, 1677, 'neutral', true, 'Appears beyond the coffee shop door, serving as their escape route.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7148, 5460, 1677, 'mini-boss', true, 'Their hunt begins, signified by the sound of tearing fabric as the realm shudders.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7149, 982, 1677, 'enemy', false, 'The purgatory realm shudders and is described as a ''vast and hungry'' thing realizing its prey has escaped.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7150, 5489, 1677, 'ally', false, 'Her presence is felt like a beacon through the seam, guiding them.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7151, 3993, 1678, 'ally', true, 'Regains consciousness, endures a sensory overload, and discovers with confusion and shock that his fatal wounds are bandaged and then perfectly healed.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7152, 1748, 1678, 'enemy', false, 'Assaults Stephen''s senses as he wakes up, causing pain and disorientation before resolving into the image of his bedroom.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7153, 5506, 1678, 'neutral', false, 'Is recalled in visceral flashes, providing the context for Stephen''s surprise at being alive and healed.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7154, 5504, 1678, 'neutral', false, 'Acts as a mysterious clue on Stephen''s arm, prompting him to discover the impossible healing underneath.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7155, 5502, 1678, 'neutral', true, 'Manifests as perfect skin under the gauze, becoming the central mystery and point of disbelief for Stephen.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7156, 3993, 1679, 'ally', true, 'Attempts to show his wife his healed arm but is immediately drawn into a manipulative argument, becoming increasingly panicked and defensive until he flees.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7157, 2549, 1679, 'mini-boss', true, 'Enters the room, ignores Stephen''s miraculous state, and initiates a gaslighting argument about an electric bill, effectively trapping him psychologically and physically.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7158, 5503, 1679, 'enemy', true, 'Serves as the wife''s primary weapon, a conversational trap that makes the air feel thin and forces Stephen to retreat.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7159, 5505, 1679, 'neutral', false, 'Is used as the subject of the argument, a mundane detail weaponized to create confusion and conflict.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7160, 5502, 1679, 'neutral', false, 'Is dismissed and ignored by Stephen''s wife, highlighting the clash between the supernatural event and the crushing banality of the argument.', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_beat_appearances VALUES (7161, 2549, 1680, 'mini-boss', true, 'Criticizes Stephen''s housekeeping, job search, and past spending, blaming him for their financial problems while refusing to contribute her own savings.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7163, 5512, 1680, 'enemy', false, 'Acts as the underlying cause of the conflict, fueling the wife''s accusations and Stephen''s anxiety.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7164, 5515, 1680, 'neutral', false, 'Serves as the initial trigger for the wife''s complaints about the state of the kitchen.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7165, 5514, 1680, 'neutral', false, 'Becomes a major point of contention when Stephen suggests using it, revealing his wife''s selfishness.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7166, 4141, 1681, 'ally', true, 'Enters the scene, shows his father a TikTok video, and makes the observation that his mother acts like an NPC, bonding with Stephen over this shared perception.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7168, 5513, 1681, 'neutral', false, 'Introduces the central concept of ''NPC Energy'' that reframes Stephen''s understanding of his wife.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7169, 5511, 1681, 'neutral', false, 'The core concept from the video is discussed, comparing people who lack internal monologues to video game characters.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7170, 2549, 1681, 'mini-boss', false, 'Is the subject of the NPC comparison, with her scripted responses and lack of ''lore'' being analyzed by Xavier.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7172, 5511, 1682, 'neutral', true, 'Transforms from a funny observation into a terrifyingly plausible explanation for his wife''s behavior and his marital problems.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7173, 2549, 1682, 'mini-boss', false, 'Is mentally re-categorized by Stephen from a difficult human into a non-human ''subroutine'', a feature of his reality rather than a partner.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7174, 4141, 1682, 'ally', false, 'Is identified by Stephen as representing genuine consciousness, a ''real'' person in contrast to his mother.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7176, 5520, 1683, 'neutral', true, 'Begins, replacing Stephen''s reality with a field of slaughter.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7177, 5521, 1683, 'neutral', false, 'Discovered butchered, serving as the catalyst for the shepherd''s grief.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7178, 5523, 1683, 'neutral', true, 'Ignites within the shepherd, becoming a reality-rejecting force.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7179, 5522, 1683, 'enemy', false, 'Mentioned as the cruel perpetrators of the slaughter.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7181, 5524, 1684, 'ally', false, 'Attempts to soothe the shepherd''s rage, but the collision tears reality.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7182, 5523, 1684, 'neutral', true, 'Acts as the unstoppable force that crashes into Sophia''s wisdom, causing the breach.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7183, 5525, 1684, 'mini-boss', true, 'Vomits itself through the tear in reality, flooding the shepherd''s soul.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7184, 5526, 1684, 'enemy', false, 'Is created as Anti-Reality twists the shepherd''s pure affection into a possessive hunger.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7185, 5527, 1684, 'enemy', false, 'Forms as the new identity of the corrupted shepherd.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7187, 5520, 1685, 'neutral', false, 'Snaps shut, abruptly ending the psychic experience.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7188, 5526, 1685, 'enemy', true, 'Remains as a lingering coldness and an echo of hunger in Stephen''s gut.', '2026-02-28 22:32:54.020373-05');
