INSERT INTO public.entity_beat_appearances VALUES (7348, 5293, 1721, 'unknown', false, 'Is the subject of Whitney''s message.', '2026-02-28 22:43:37.412246-05');
INSERT INTO public.entity_beat_appearances VALUES (7351, 5654, 1722, 'ally', true, 'The group of old gods and discarded myths is introduced as they gather around the prison sphere.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7391, 2536, 1722, 'neutral', false, 'Established as the central object of the scene: a black sphere that is a prison for souls.', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_beat_appearances VALUES (7352, 5650, 1722, 'ally', false, 'Introduced as a member of the resistance, coiling through the void.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7353, 5651, 1722, 'ally', false, 'Introduced as a three-faced goddess standing watch.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7354, 5652, 1722, 'enemy', false, 'Introduced as a silent, menacing member of the group.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7355, 2608, 1722, 'ally', false, 'Introduced as a goddess of wisdom woven from thought.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7356, 5231, 1722, 'ally', false, 'Introduced walking beside Lady Illkeserod.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7358, 5656, 1723, 'ally', true, 'The signal is the subject of the debate, representing both hope and danger to the gods.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7357, 5231, 1723, 'ally', false, 'Argues that the signal is a sign of hope and a way to potentially rescue souls from Etheris.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7359, 2608, 1723, 'ally', false, 'Expresses caution, stating that a ''whisper is not a presence'' and that their sight into Etheris is gone.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7361, 5652, 1723, 'enemy', false, 'Suggests the signal could be a trick or a contagion from within the prison.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7401, 5650, 1723, 'ally', false, 'Confirms the signal''s presence, describing its ''song'' as sweet and defiant.', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_beat_appearances VALUES (7360, 5651, 1723, 'ally', false, 'Expresses cynicism about their ability to act on the signal.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7362, 2749, 1723, 'ally', false, 'Suggests a practical approach: find the tear the signal left behind.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7405, 5687, 1724, 'ally', false, 'Flickers into existence as a reflection on Etheris, showing Stephen is beginning to remember.', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_beat_appearances VALUES (7363, 2608, 1724, 'ally', false, 'Touches Etheris, sees the memory, and expresses fear over what Stephen remembering might mean.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7407, 2536, 1724, 'neutral', false, 'Reacts to Illkeserod''s touch, shattering her projection, and later reacts hungrily to the mention of Jamie''s name.', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_beat_appearances VALUES (7367, 5231, 1724, 'ally', false, 'Catches Illkeserod and argues that Stephen''s memory is their best chance.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7409, 5652, 1724, 'enemy', false, 'Argues for inaction, stating that if they do nothing, ''the cage holds, and the dream continues''.', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_beat_appearances VALUES (7369, 5231, 1725, 'ally', true, 'Makes the final declaration that they must find Whitney, committing the group to action and expressing his debt to her.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7371, 5656, 1725, 'ally', false, 'Recognized as a persistent echo drifting through the multiverse, providing a trail for the gods to follow.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7370, 2608, 1725, 'ally', false, 'Expresses awe at how Whitney broke through impossible barriers and agrees with Benji, stating, ''Then that’s where we begin.''', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7372, 5654, 1725, 'ally', false, 'The individual gods depart one by one, having reached a consensus to act.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7414, 2608, 1726, 'ally', true, 'Finds the correct harmonic vibration in Etheris to create a bridge between Stephen and Whitney.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7415, 5694, 1726, 'neutral', false, 'Is created by Lady Illkeserod''s actions, manifesting as a thread of light that shifts gravity.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7417, 5489, 1727, 'ally', true, 'Awakens in the void, processes painful memories of her father and Stephen, realizes the truth about Jamie, and sends a prayer.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7418, 234, 1727, 'neutral', false, 'Serves as the isolating prison where Whitney is trapped.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7419, 5696, 1727, 'ally', false, 'Is sent out into reality, carrying Whitney''s message and plea for help.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7420, 2608, 1727, 'neutral', false, 'Appears in Whitney''s memory as her father, a source of pain she recoils from.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7421, 2544, 1727, 'unknown', false, 'Is named in Whitney''s prayer as part of her critical realization.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7423, 2608, 1728, 'ally', false, 'Senses the connection is complete and begins to visualize the source of the signal.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7424, 5489, 1728, 'ally', false, 'Feels a surge of hope in the darkness as her prayer connects.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7425, 985, 1728, 'ally', false, 'Manifests within Whitney, changing her emotional state from despair to optimism.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7427, 5703, 1729, 'enemy', true, 'Actively thwarts Stephen''s search with various errors and on-screen distortions.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7428, 5489, 1729, 'neutral', false, 'Is the subject of Stephen''s search, mentioned but not present.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7429, 5706, 1729, 'unknown', false, 'Appears for a moment on the screen, suggesting an unseen presence.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7430, 2549, 1730, 'mini-boss', true, 'Confronts Stephen with glitchy, scripted accusations about wasting electricity.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7432, 5704, 1731, 'neutral', true, 'Jumps from the wife''s hand to the computer, destroying it.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7433, 2549, 1731, 'mini-boss', false, 'Triggers the surge by touching the computer, then blames Stephen.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7434, 5702, 1731, 'neutral', false, 'Is destroyed by the static surge, smoking and flashing white.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7437, 2549, 1732, 'mini-boss', false, 'Experiences a ''recalibration'' in her behavior, accepts the plan, and drifts away humming.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7438, 2881, 1732, 'ally', false, 'Is mentioned by Stephen as the person who can fix the computer.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7440, 2881, 1733, 'ally', false, 'Recognizes Stephen after many years and initiates a nostalgic reunion.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7441, 5711, 1733, 'neutral', false, 'Serves as the catalyst for the meeting, being the object Stephen needs repaired.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7443, 2881, 1734, 'neutral', false, 'Experiences severe memory lapses and physical discomfort when trying to recall Whitney and Jamie, suggesting an external influence on his mind.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7444, 5489, 1734, 'unknown', false, 'Mentioned by Stephen, but Gil has no memory of her.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7445, 2544, 1734, 'unknown', false, 'Her name triggers a ''404'' error in Gil''s brain, causing him physical pain.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7446, 2883, 1735, 'enemy', true, 'Enters the store with Morgan, moving in a slow, deliberate, and unnatural way.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7447, 2474, 1735, 'enemy', true, 'Enters alongside Andrew, mirroring his unnatural, scripted movements.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7448, 2881, 1735, 'ally', false, 'Identifies Andrew and Morgan as ''NPCs'' who are just background people running a script without inner lives.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7450, 2881, 1736, 'ally', true, 'Shares a false memory that their classmate Patrick was shot down in a training exercise and disappeared years ago.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7451, 2896, 1736, 'neutral', false, 'Is the subject of Gil''s story about his supposed death.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7453, 4354, 1737, 'neutral', true, 'Is presented by Gil to Stephen, triggering a profound resonance that alters the physical and metaphysical state of the store.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7454, 5718, 1737, 'neutral', false, 'Manifests as a silent thrum that vibrates through everything, causing the lights to fix themselves and reality to shift.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7455, 2881, 1737, 'ally', false, 'Returns from the back room with the card, seemingly unaware of its true power.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7457, 2883, 1738, 'mini-boss', true, 'Reappears at the counter with full presence and authoritatively corrects Gil''s false memory about Patrick''s death.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7458, 2474, 1738, 'enemy', false, 'Confirms Andrew''s correction and adds the detail that Whitney was Patrick''s girlfriend who disappeared.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7459, 2881, 1738, 'ally', false, 'Is left confused by the correction, as his memory has been overwritten, and he no longer remembers Whitney at all.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7460, 5489, 1738, 'unknown', false, 'Is revealed to be Patrick''s missing girlfriend, a key piece of the puzzle.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7463, 5718, 1739, 'neutral', false, 'Is understood not just as a local event, but as a broadcast signal to other aware individuals.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7464, 2883, 1739, 'mini-boss', false, 'Provides Stephen with Patrick''s address, giving him the next step on his quest before leaving.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7465, 5231, 1740, 'ally', false, 'Fights an Impossible Anatomy Creature, severing its leg with his Blade of Potential.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7466, 2608, 1740, 'ally', false, 'Directs Benji in combat and then effortlessly and gruesomely dispatches two creatures, one of which is the Inverting Shadow Beast.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7467, 5723, 1740, 'enemy', true, 'Attack Benji and Lady Illkeserod, manifesting from the darkness with horrific forms.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7468, 5724, 1740, 'neutral', false, 'Used by Benji to wound a creature, causing its limb to unravel.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7469, 5725, 1740, 'neutral', false, 'Sprays from a wounded creature, causing the ground to bubble and grow mouths.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7470, 5726, 1741, 'neutral', true, 'Resonates through the void, surprising both Benji and Lady Illkeserod.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7471, 5231, 1741, 'ally', false, 'Feels the vibration and immediately uses his Alchemical Orrery to track its source.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7472, 2608, 1741, 'ally', false, 'Senses the vibration first and observes Benji as he triangulates the signal.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7473, 5727, 1741, 'neutral', false, 'Activates in Benji''s hands, its symbols aligning to point towards a God Null Zone.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7474, 5728, 1741, 'neutral', false, 'Identified as the source of the powerful signal.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7475, 5231, 1742, 'ally', true, 'Expresses his conviction that the signal is a beacon from Whitney, revealing he has been searching for 367 eternities.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7476, 2608, 1742, 'ally', false, 'Warns Benji that it could be a trap and states that she cannot enter the God Null Zone with him.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7477, 5489, 1742, 'unknown', false, 'Is named as the object of Benji''s search and the presumed source of the beacon.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7478, 5728, 1742, 'neutral', false, 'Discussed as a place lethal to beings like Lady Illkeserod, making Benji''s mission a solo one.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7479, 5231, 1743, 'ally', true, 'Makes the decision to go alone and jumps into the darkness of the God Null Zone.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7480, 2608, 1743, 'ally', false, 'Gives a final warning and watches him descend, unable to follow or help.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7481, 5728, 1743, 'neutral', false, 'Serves as the destination, swallowing Benji as he jumps into it.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7482, 5730, 1743, 'neutral', false, 'Its current shifts, causing the ground to shudder, underscoring the momentousness of the event.', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_beat_appearances VALUES (7483, 5489, 1744, 'ally', true, 'Flees from and then confronts the Fire Beasts, using a makeshift weapon to kill them in a desperate fight for survival.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7484, 5733, 1744, 'enemy', false, 'Howl and pursue Whitney through the forest with ravenous intent.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7485, 5741, 1744, 'mini-boss', true, 'As the last survivor, it intelligently circles and feints, posing a more calculated threat before Whitney ultimately defeats it.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7486, 5734, 1744, 'neutral', false, 'Serves as the hostile, alien setting for the chase and battle, with its strange trees and yielding ground.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7487, 5735, 1744, 'ally', false, 'Used by Whitney to strike down the first few Fire Beasts.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7488, 5489, 1745, 'ally', true, 'Exhausted and injured after the fight, she discovers the stone structure and enters it seeking safety.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7489, 5736, 1745, 'neutral', true, 'Appears as a hidden sanctuary, offering Whitney a safe place to rest.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7490, 5737, 1745, 'neutral', false, 'Cover the structure, their incomprehensible nature marking the place as ancient and otherworldly.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7491, 5489, 1746, 'ally', true, 'Initiates the dream walk technique to escape the current reality, but is interrupted by a powerful, familiar vibration.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7492, 5738, 1746, 'neutral', true, 'The process of interdimensional travel that Whitney begins.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7493, 5739, 1746, 'unknown', true, 'Manifests as a powerful, clear beacon that resonates through Whitney, calling to her.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7494, 5737, 1746, 'neutral', false, 'React to the vibration, glowing and pulsing in time with it, facilitating a portal.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7496, 5489, 1747, 'ally', true, 'Experiences the terrifying vision of her own deletion, fighting against the chains that bind her.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7497, 5744, 1747, 'enemy', true, 'Actively tears reality apart around Whitney, attempting to erase her from existence.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7498, 5745, 1747, 'enemy', false, 'Burst from the ground to coil around and restrain Whitney, preventing her escape.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7499, 5753, 1747, 'unknown', false, 'Speaks fragmented, conflicting commands, indicating a struggle over Whitney''s fate during the deletion process.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7500, 5231, 1747, 'ally', false, 'His name is heard as a faint, distant shout that cannot reach Whitney.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7501, 5489, 1748, 'ally', true, 'As a disembodied consciousness, she endures the hopelessness of the void and learns to use her dreams to find and push through cracks in reality.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7502, 234, 1748, 'enemy', true, 'Acts as her prison, an environment of absolute nothingness that threatens to extinguish her consciousness through sheer isolation.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7503, 5747, 1748, 'neutral', false, 'Serve as Whitney''s only tool, allowing her to build sparks of reality and navigate towards an escape.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7504, 5748, 1748, 'neutral', false, 'Appear as shimmering fissures that Whitney learns to use as painful doorways out of the void.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7505, 5489, 1749, 'ally', true, 'Reflects on her journey and purpose, realizing she is being pulled toward those who remember her before falling through a portal.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7507, 5231, 1749, 'ally', false, 'Is remembered by Whitney as someone who has not forgotten her, forming part of her motivation.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7508, 2896, 1749, 'ally', false, 'Is remembered by Whitney as someone who might have survived and not forgotten her.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7509, 5739, 1749, 'neutral', true, 'Finds Whitney and acts as a summons, opening a portal beneath her to pull her towards a reunion.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7512, 2896, 1751, 'ally', false, 'Greets Stephen and introduces his ''wife'', while observing Stephen''s reactions.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7513, 5758, 1751, 'mini-boss', true, 'Presents a human facade, but her uncanny valley appearance and practiced demeanor arouse Stephen''s suspicion.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7515, 5758, 1752, 'mini-boss', true, 'Is triggered by the name Jamie, causing its human facade to fracture and beginning a violent transformation.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7516, 2896, 1752, 'ally', false, 'Recognizes the trigger and prepares for the inevitable attack.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7517, 2544, 1752, 'unknown', false, 'Her name is spoken, acting as the catalyst for the entity''s transformation.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7519, 5758, 1753, 'mini-boss', false, 'Screams and recoils as its form is destabilized by the invoked power.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7520, 5759, 1753, 'neutral', false, 'Acts as a catalyst for Stephen''s instinctual action.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7521, 5761, 1753, 'ally', false, 'Manifests around Stephen, bending reality and weakening the entity.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7522, 2896, 1754, 'ally', true, 'Destroys the destabilized entity with a ritual blade and explains that it was a construct designed to keep him isolated. He tells Stephen he is dangerous.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7523, 5758, 1754, 'mini-boss', false, 'Reveals a final, bizarre bear-like form, speaks a cryptic warning, and dissolves into dust.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7525, 5760, 1754, 'neutral', false, 'Is used as the weapon to deliver the final blow to the entity.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7527, 5766, 1755, 'enemy', true, 'Uploads itself directly into Stephen''s brain.', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_beat_appearances VALUES (7528, 5231, 1756, 'ally', false, 'Tears into the Anti-life Realm to find Whitney.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7529, 5489, 1756, 'ally', false, 'Found barely surviving an assault by crystalline creatures.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7530, 5776, 1756, 'enemy', false, 'Its caustic atmosphere and hostile terrain attack Benji upon entry.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7531, 5778, 1756, 'mini-boss', true, 'Lungs at Benji the moment he materializes, initiating the conflict.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7532, 5777, 1756, 'enemy', false, 'Circling and hunting Whitney, with more emerging to confront Benji.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7533, 5231, 1757, 'ally', true, 'Rescues Whitney and shatters the attacking creatures by bending reality.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7534, 5489, 1757, 'ally', false, 'Is rescued and questions the reality of the situation, before noticing the card in her hand.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7535, 4354, 1757, 'neutral', false, 'Is discovered in Whitney''s hand, a physical impossibility that shocks her.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7536, 5777, 1757, 'enemy', false, 'Surge forward to attack but are shattered and displaced by Benji.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7537, 5231, 1758, 'ally', false, 'Struggles to pull himself and Whitney out of the realm as his form destabilizes from the effort.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7538, 5489, 1758, 'ally', false, 'Feels herself stretched across infinite space, anchored only by Benji''s grip and the card.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7539, 5776, 1758, 'enemy', true, 'Resists their escape, erupting stone pillars and thickening the air to trap them.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7540, 2608, 1759, 'ally', true, 'Comforts Whitney and reveals that her desperate connection to Stephen broke through dimensional barriers.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7541, 5489, 1759, 'ally', false, 'Receives comfort and learns the profound impact of her emotional signal.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7542, 5780, 1759, 'neutral', false, 'Identified as the force that reached Stephen and is accelerating his awakening.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7544, 5489, 1760, 'ally', true, 'Reveals her traumatic past and complicated feelings for Stephen, before finding a fragile hope and agreeing to the plan.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7545, 2608, 1760, 'ally', false, 'Hints at deeper connections, outlines the plan to study the signal, and warns of the danger from Yaldabaoth.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7546, 5231, 1760, 'ally', false, 'Provides weary, sarcastic commentary before sharing a moment of familiar banter with Illkeserod.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7547, 5781, 1760, 'enemy', false, 'Recalled in Whitney''s thoughts as the source of her trauma and pain.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7548, 2550, 1760, 'enemy', false, 'Mentioned as the ultimate threat, preventing them from tearing the veil further.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7550, 2896, 1761, 'ally', false, 'Expresses a sense of futility about the state of his trailer and confirms that Whitney wasn''t real.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7551, 5787, 1761, 'neutral', true, 'The images of Whitney within the frames dissolve into blank paper, providing the first physical proof of the unreality of constructs.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7552, 5489, 1761, 'enemy', false, 'Is the subject of the fading photographs and Patrick''s explanation of her non-existence.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7553, 2896, 1762, 'ally', true, 'Recounts his past as a troublemaker, his time in the Air Force, and the specifics of the 2015 plane crash he miraculously survived.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7554, 5789, 1762, 'neutral', false, 'Serves as the pivotal event in Patrick''s backstory, leading to his first contact with The Thirteen.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7555, 5788, 1762, 'ally', false, 'Are introduced as the entities Patrick met after surviving the crash.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7557, 2896, 1763, 'ally', true, 'Explains the cosmology of their world: The Prison (Etheris), the trapped entity Yaldabaoth, the role of DMT, and the nature of the Elder Gods.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7558, 5790, 1763, 'neutral', false, 'Is revealed to be the pocket reality they are all trapped within.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7559, 2550, 1763, 'enemy', false, 'Is described as a cosmic plague and the reason the prison was created.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7560, 5793, 1763, 'neutral', false, 'Are explained as the original chaotic creators of this reality, also trapped inside.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7561, 5794, 1763, 'neutral', false, 'Is identified as the Elder God whose power Stephen tapped into, an act that shouldn''t have been possible.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7564, 2549, 1764, 'mini-boss', false, 'Is identified as a construct and a ''prison guard'' whose purpose is to keep Stephen docile through a cycle of abuse and feigned affection.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7565, 4141, 1764, 'ally', false, 'Is revealed to be ''real'' and in danger from his mother, as he can perceive the falseness of their reality.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7566, 2896, 1764, 'ally', false, 'Confirms Stephen''s fears, stating that his wife is a construct who will likely eliminate Xavier if he is perceived as a threat.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7567, 2896, 1765, 'ally', true, 'Retrieves TJ''s card and explains his background as an apostate priest who was excommunicated by the Church for his research.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7569, 5801, 1765, 'neutral', false, 'Is retrieved from a drawer and handed to Stephen, serving as a physical link to the new contact.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7570, 5800, 1765, 'ally', false, 'Is introduced as a potential ally with unique knowledge and resources.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7571, 235, 1765, 'enemy', false, 'Mentioned as the antagonistic force that excommunicated TJ and unknowingly serves the demiurge.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7572, 5804, 1765, 'neutral', false, 'Mentioned as the source of TJ''s knowledge and the reason for his excommunication.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7573, 2550, 1765, 'enemy', false, 'Named as the subject of TJ''s forbidden research.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7574, 2896, 1766, 'ally', true, 'Warns Stephen to be honest with TJ and reveals that The Thirteen told him about Stephen''s recurring cycles and his motivation for returning.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7576, 5788, 1766, 'unknown', false, 'Cited as the source of the information about Stephen''s cyclical existence.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7577, 2544, 1766, 'ally', false, 'Is named as the reason Stephen keeps returning across multiple cycles.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7578, 5231, 1766, 'ally', false, 'Mentioned in Stephen''s internal monologue as his ultimate goal: ''a son to save''.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7579, 3693, 1767, 'neutral', true, 'Issues the command to climb, following an ingrained tradition.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7580, 3694, 1767, 'neutral', false, 'Obeys the command and begins to seek as instructed.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7582, 3696, 1768, 'neutral', false, 'Suffers and bleeds as a result of The Dreamers'' commands.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7583, 3697, 1769, 'neutral', true, 'Paradoxically command others to learn while choking on knowledge themselves.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7584, 3699, 1769, 'neutral', true, 'Ignoring other options, they pour themselves onto the pyre in a final act of desperation.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7585, 3701, 1769, 'neutral', false, 'Serves as the final, desperate destination for The Wailing.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7586, 3702, 1770, 'neutral', true, 'Follow a command towards an invisible sign, trapped by their own poisons.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7587, 234, 1770, 'enemy', false, 'Acts as the paradoxical object of desire and hatred for The Gullible, a destination of ungraspable falling.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7588, 169, 1771, 'neutral', true, 'Reveals itself as a paradox, a truth that is no truth.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7589, 5823, 1771, 'neutral', false, 'Is revealed to have never been hidden.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7590, 5824, 1771, 'neutral', false, 'Acts as a timeless teacher, imparting this paradoxical knowledge.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7591, 5825, 1772, 'neutral', true, 'Their screams create a state of noisy silence, drowning out everything as they yearn for a heaven they cannot hear.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7592, 5826, 1772, 'neutral', false, 'Is mentioned as the object of yearning, whose calls go unheard.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7593, 3708, 1773, 'neutral', true, 'Turn away from the scene in disgust.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7594, 3709, 1773, 'neutral', false, 'Echo the initial command to ''Climb,'' symbolizing the cyclical and futile nature of the struggle, now forever buried.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7596, 2549, 1774, 'mini-boss', true, 'Screaming accusations at her son, Xavier, having destroyed the living room.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7597, 3993, 1774, 'ally', false, 'Stoically enduring his mother''s verbal assault while cowering.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7598, 5842, 1774, 'neutral', false, 'Serves as the backdrop for the conflict, described as a ''war zone''.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7600, 5834, 1775, 'neutral', false, 'The flashback event where Aspolin rewrites time.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7601, 5835, 1775, 'neutral', false, 'Is killed and resurrected within the memory, creating a paradox.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7602, 5836, 1775, 'neutral', false, 'The metaphysical consequence of Aspolin''s forbidden magic.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7603, 2549, 1776, 'mini-boss', true, 'Physically attacks Xavier, then reveals inhuman traits when Stephen intervenes, her pupils dilating unnaturally and her voice distorting.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7605, 3993, 1776, 'ally', false, 'Is attacked by his mother and flinches away.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7606, 2549, 1777, 'mini-boss', true, 'Verbally assaults Stephen, revealing impossible knowledge by naming Whitney.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7607, 3993, 1777, 'ally', false, 'Identifies his mother''s behavior as ''glitching'', confirming she is not human.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7609, 5837, 1777, 'enemy', false, 'The phenomenon is identified, explaining the wife''s behavior.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7610, 5489, 1777, 'unknown', false, 'Mentioned by the wife as proof of her impossible knowledge.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7611, 2549, 1778, 'mini-boss', true, 'Attacks Xavier again, headbutts Stephen, and calmly retrieves a handgun from the bedroom.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7613, 3993, 1778, 'ally', false, 'Is attacked again and then flees to the car on his father''s command.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7614, 5838, 1778, 'neutral', false, 'Is retrieved by the wife, escalating the threat to lethal.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7615, 2549, 1779, 'mini-boss', true, 'Fires twice at Stephen, then climbs a bookcase for a better angle, which collapses and kills her.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7617, 5839, 1779, 'neutral', false, 'The unstable structure collapses on the wife, causing her death.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7618, 5838, 1779, 'neutral', false, 'Is fired twice during the chaotic confrontation.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7620, 3993, 1780, 'ally', false, 'Questions his father''s denial about his mother''s reality.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7621, 2549, 1780, 'mini-boss', false, 'Is now dead under the bookcase, but her death causes Stephen significant emotional turmoil.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7622, 5840, 1781, 'enemy', true, 'Emerges from the rubble and stands motionless in the doorway, watching the protagonists flee.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7624, 3993, 1781, 'ally', false, 'Also sees the shadow and is terrified.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7625, 1846, 1781, 'neutral', false, 'Serves as the escape vehicle.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7626, 5489, 1782, 'ally', true, 'Repeatedly and unsuccessfully tries to break through the barrier, growing increasingly frustrated.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7627, 5848, 1782, 'enemy', true, 'Resists all of Whitney''s attempts to breach it, pushing back with cold, absolute emptiness.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7628, 2608, 1782, 'ally', false, 'Calmly observes Whitney''s failure and explains that raw emotion is needed, not the ''programmed fear'' the prison runs on.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (8067, 6180, 1885, 'neutral', true, 'Opens at Nyarlathotep''s gesture, ceasing to be an obstacle.', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_beat_appearances VALUES (7581, 1525, 1768, 'mini-boss', true, 'Command others to struggle from their place of comfort, corrupting memories in the process.', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.entity_beat_appearances VALUES (7629, 5231, 1782, 'ally', false, 'Attempts to provoke a fear response in Whitney by transforming into a terrifying monster, but fails.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7630, 5851, 1782, 'neutral', false, 'Is manifested by Benji''s monster form and is proven ineffective against the Void Barrier.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7631, 5489, 1783, 'ally', true, 'Follows Lady Illkeserod''s guidance, closing her eyes and delving into her memories and feelings for Stephen.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7632, 2608, 1783, 'ally', false, 'Guides Whitney to focus on her emotional connection to Stephen, prompting her to remember why he is so important to her.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7634, 5489, 1784, 'ally', true, 'Successfully channels her deep emotions for Stephen, creating a connection and pushing a message through the cracking barrier.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7635, 5850, 1784, 'ally', true, 'Manifests as a powerful force that causes the Void Barrier to ripple, scream, and crack open with purple-black light.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7636, 5848, 1784, 'enemy', false, 'Is breached by Whitney''s emotion, cracking and burning before snapping shut again.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7637, 5852, 1784, 'neutral', false, 'Is formed from Whitney''s emotion and sent through the breach, instructing Stephen to find Nyarlathotep.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7638, 5853, 1784, 'unknown', false, 'Is the subject of the message sent by Whitney.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7639, 5489, 1785, 'ally', true, 'Learns that her message may be corrupted and, more importantly, that she didn''t abandon Stephen but was purged from the system for being a ''glitch,'' reframing her escape as an act of survival.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7640, 2608, 1785, 'ally', false, 'Explains that the message may arrive as noise but the crack is exploitable. She reveals the truth of Whitney''s ''escape'' as a system purge.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7641, 5231, 1785, 'ally', false, 'Reinforces Lady Illkeserod''s explanation, telling Whitney her survival was a victory, not a betrayal.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7642, 2608, 1786, 'ally', true, 'Reveals that Stephen will find help from TJ, who knows the prison''s greatest secret: that its God is false.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7643, 5489, 1786, 'ally', false, 'Listens to the revelations, understanding the new strategy and the stakes.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7644, 2884, 1786, 'ally', false, 'Is introduced as an ally waiting for Stephen inside the prison.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7645, 5855, 1786, 'neutral', false, 'Is revealed as the key piece of information that can help unravel the prison''s control.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7646, 5856, 1786, 'unknown', false, 'Stirs deep within the substrate, signaling a new, ominous development as the prison walls tremble.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7649, 3993, 1787, 'ally', false, 'Accompanies his father, expressing that the situation feels wrong.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7650, 5864, 1787, 'neutral', true, 'Sit unmoving in the main room, creating an unsettling atmosphere.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7651, 5863, 1787, 'neutral', false, 'Acts as a gatekeeper, questioning Stephen before getting TJ.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7652, 2884, 1788, 'ally', true, 'Emerges and leads Stephen and Xavier to his secret, impossible basement library.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7654, 3993, 1788, 'ally', false, 'Is awed by the vast collection of forbidden books.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7655, 5866, 1788, 'neutral', false, 'Is revealed as an impossible, anomalous space filled with knowledge.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7656, 2884, 1789, 'ally', true, 'Explains his awakening via the Apocryphon of John and reveals his congregation of NPCs is a cosmic punishment from the demiurge.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7658, 5867, 1789, 'neutral', false, 'Mentioned as the catalyst for TJ''s awakening.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7660, 2544, 1790, 'unknown', false, 'Her name, ''Jamie'', triggers a system-wide alert and attack.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7661, 5870, 1790, 'enemy', false, 'Floods the room, heralding the attack.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7662, 5864, 1790, 'enemy', false, 'Begin screaming upstairs, signaling their transformation.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7663, 2884, 1790, 'ally', false, 'Reacts with terror, realizing the system has been triggered.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7664, 2884, 1791, 'ally', true, 'Performs a banishment ritual with a void-fire book, sacrificing himself to slow down the attacking NPCs.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7665, 5865, 1791, 'mini-boss', true, 'Pour down the stairs as monstrous, twisted figures and overwhelm TJ.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7666, 5868, 1791, 'neutral', false, 'Used by TJ as the focus for his banishment ritual, burning with purple and black flames.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7668, 3993, 1791, 'ally', false, 'Pulls his father toward the escape route.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7670, 3993, 1792, 'ally', false, 'Mourns TJ''s death as they flee.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7671, 2884, 1792, 'ally', false, 'His voice, chanting a banishment ritual, fades as the others escape, confirming his demise.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7673, 3993, 1793, 'ally', false, 'Silently receives first aid for the wounds on his neck, flinching from the pain.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7674, 3993, 1794, 'ally', true, 'Gets a phone signal and discovers his friends on Discord are reacting to a public story about him being kidnapped.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7675, 5876, 1794, 'neutral', false, 'Serves as the gateway to the confusing and alarming reactions from the outside world.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7676, 5879, 1794, 'neutral', false, 'Are spamming Xavier with memes and questions based on the news story.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7677, 4590, 1794, 'ally', false, 'Is mentioned as asking if Xavier is okay, hinting at a different reaction from the others.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7678, 2549, 1795, 'mini-boss', true, 'Appears on a televised press conference, presenting a fabricated story and appearance of being a battered victim.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7679, 5877, 1795, 'enemy', true, 'Is established by the news broadcast, branding Stephen a dangerous fugitive and Xavier a kidnap victim.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7681, 3993, 1795, 'ally', false, 'Reacts with yelling and disbelief, recognizing his mother''s performance as a lie.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7682, 463, 1795, 'neutral', false, 'Broadcasts the press conference into the motel room.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7683, 3190, 1795, 'enemy', false, 'Are mentioned by the news as actively hunting Stephen, who is considered armed and dangerous.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7684, 3993, 1796, 'ally', true, 'Sinks into despair but then finds a flicker of hope in friends who question the narrative. He chooses to engage in a normal activity (gaming) as a coping mechanism.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7685, 4590, 1796, 'ally', false, 'Is identified as one of the friends asking real questions and not just believing the news.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7686, 5881, 1796, 'ally', false, 'Is also identified as a friend who is questioning the public narrative.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7687, 5884, 1796, 'ally', false, 'Is given to Xavier by Stephen, enabling his retreat into normalcy.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7689, 3993, 1797, 'ally', false, 'Plays Roblox on his phone until he falls asleep, finding a small escape from their reality.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7691, 3993, 1798, 'ally', false, 'Is woken up and reluctantly dons a ridiculous disguise, complaining about their appearance.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7692, 5888, 1798, 'neutral', false, 'Are purchased and worn to make Stephen and Xavier blend in by looking like harmless eccentrics.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7694, 5889, 1799, 'neutral', true, 'Serves as the focal point of the beat, its destruction revealing the enemy''s power.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7695, 5366, 1799, 'enemy', true, 'Reveals its ability to rewrite the past by having destroyed the bookstore days before Stephen''s arrival, cutting off an escape route.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7696, 3993, 1799, 'ally', false, 'Witnesses the destruction and his father''s reaction with fear.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7697, 3993, 1800, 'ally', true, 'Researches Nyarlathotep on his phone, filters through disturbing content, and discovers the lead about the grimoire and the Ocala collector.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7699, 5853, 1800, 'unknown', true, 'Is the subject of the online research that provides the scene''s crucial lead.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7700, 5895, 1800, 'neutral', false, 'Is identified as the target of their new search.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7701, 5896, 1800, 'unknown', false, 'Is identified as their only lead to finding the grimoire.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7702, 5893, 1800, 'neutral', false, 'Takes their order and serves them food, providing a brief moment of mundane normalcy.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7703, 2882, 1800, 'ally', false, 'Is the target of Stephen''s failed attempt to contact help, reinforcing their isolation.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7705, 3993, 1801, 'ally', false, 'Finds the mysterious flyer on a bulletin board, providing a new, albeit dangerous, lead.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7706, 5903, 1801, 'neutral', false, 'Serves as the catalyst that directs the characters to the Pallid Mask Theatre.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7708, 3993, 1802, 'ally', false, 'Is deeply unnerved by the cultists and the location, voicing his fear that it''s another trap.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7709, 5905, 1802, 'enemy', true, 'Appear as impossibly beautiful figures, attempting to seduce the protagonists with promises of ecstasy and an escape from their painful reality.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7710, 5905, 1803, 'enemy', false, 'Perform a disturbing, erotic ''play'' that culminates in a ritualistic frenzy after a headless body is dropped onto the stage. They begin chanting to summon their god.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7711, 5904, 1803, 'big-boss', true, 'Manifests from a pool of blood on the stage, its presence causing the temperature to drop and a psychic whining to fill the air. It communicates telepathically with Stephen and Xavier.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7713, 3993, 1803, 'ally', false, 'Choked with fear, he tells the King in Yellow that they just want to get out.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7714, 5905, 1804, 'enemy', true, 'Undergo horrific physical transformations into monsters and begin a chaotic, orgiastic massacre, attacking both the protagonists and each other.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7715, 5904, 1804, 'big-boss', false, 'Instigates the transformation of his followers, offering a ''taste'' of the help he can provide.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7717, 3993, 1804, 'ally', false, 'Finds a rebar and defends himself, holding his own against the mutated cultists.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7719, 5906, 1805, 'mini-boss', false, 'Remains unchanged by the chaos and successfully attacks the protagonists, stabbing Stephen while aiming for Xavier.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7720, 5908, 1805, 'neutral', false, 'Acts as a powerful lure, distracting the mutated cultists and stopping the fight, which allows for an escape.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7721, 3993, 1805, 'ally', false, 'Acts quickly to create and apply a makeshift tourniquet to his father''s arm, saving his life.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7722, 5909, 1805, 'ally', false, 'Is created and used to slow Stephen''s bleeding.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7723, 5907, 1805, 'neutral', false, 'Is used to wound Stephen and is then pulled free by him.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7725, 5915, 1806, 'mini-boss', true, 'Causes Stephen intense agony and makes him lose control, forcing Xavier to take command.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7726, 3993, 1806, 'ally', false, 'Asserts authority over his delirious father, directing him off the interstate to a rural farmhouse.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7727, 5919, 1806, 'neutral', false, 'Serves as the vehicle carrying the injured pair off the highway and into the countryside.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7729, 3993, 1807, 'ally', false, 'Helps his father to the door before collapsing alongside him.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7730, 5913, 1807, 'ally', true, 'Takes immediate, professional command, ordering Stephen onto the kitchen table and beginning treatment.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7731, 2658, 1807, 'ally', false, 'Assists Maeve, checks Xavier''s ankle, and provides them both with a hot, soothing drink.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7732, 5916, 1807, 'neutral', false, 'The door opens to reveal their rescuers, and its interior becomes a place of healing.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7734, 5913, 1808, 'ally', false, 'Confirms Stephen''s suspicions, stating the locals consider them ''godless Celtic witches'' and that it''s ''close enough''.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7735, 5920, 1808, 'neutral', false, 'The bronze and copper items serve as the primary clue to the true nature of the farmhouse and its inhabitants.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7736, 5918, 1808, 'ally', false, 'Mentioned as the identity of the women, explaining the strange rules and atmosphere of the house.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7724, 326, 1806, 'ally', false, 'Struggles to drive while delirious from his injuries.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7738, 3993, 1809, 'ally', false, 'Tries the homemade wine with comical disgust, providing a moment of levity before falling asleep quickly.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7739, 5913, 1809, 'ally', false, 'Shares the meal and gets Xavier a different drink after his reaction to the wine.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7740, 2658, 1809, 'ally', false, 'Serves the meal and pours the homemade wine.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7741, 5917, 1809, 'neutral', false, 'Acts as a catalyst for a rare moment of laughter and normalcy.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7743, 5853, 1810, 'mini-boss', true, 'Reveals its identity and explains that it is helping Stephen disrupt Yaldabaoth''s ordered loops for its own entertainment.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7744, 5927, 1810, 'neutral', false, 'Serves as the chaotic, unsettling environment for the encounter.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7745, 2550, 1810, 'enemy', false, 'Mentioned as ''The King'' and ''Yaldabaoth,'' the boring creator of the loops that Nyarlathotep despises.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7747, 5853, 1811, 'mini-boss', true, 'Amusedly grants Stephen''s request, then twists Whitney''s words to reveal that the key is a suppressed name.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7748, 5489, 1811, 'ally', true, 'Appears frantically, confirming a death and directing Stephen to seek the Akashic Realm by interfacing with the ''core''.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7749, 5655, 1811, 'neutral', false, 'Mentioned as the goal and the only secure way out of the system.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7750, 5468, 1811, 'neutral', false, 'Mentioned by Nyarlathotep as the ''foundation'' that must be accessed to open a door.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7752, 5928, 1812, 'neutral', true, 'Floods Stephen''s consciousness with the experiences of love, war, and sacrificial loss from his past life.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7753, 2544, 1812, 'ally', true, 'Her name and memory are the catalyst for the entire event, her face forming in the static as Stephen remembers everything.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7755, 3993, 1813, 'ally', false, 'Rushes to his father''s side, alarmed and demanding to know who Jamie is.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7757, 5938, 1814, 'neutral', false, 'Act as the source of Stephen''s confusion and inability to explain his situation easily.', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7758, 5913, 1814, 'ally', false, 'Enters the room and expresses concern, telling Stephen he should be resting.', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7759, 2658, 1814, 'ally', false, 'Enters with Maeve and moves to a chair, observing the situation.', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7760, 5939, 1814, 'neutral', false, 'Contributes to Stephen''s sense of urgency and disorientation.', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7762, 2658, 1815, 'ally', false, 'Encourages Stephen to speak, saying ''Tell it instead'' and ''We''re listening.''', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7763, 5913, 1815, 'ally', false, 'Attempts to interject out of concern but acquiesces to Stephen''s insistence.', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7764, 3993, 1815, 'ally', false, 'Asks what needs to be told and prompts Stephen to ''Start from the beginning,'' focusing the group''s attention.', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7766, 5835, 1816, 'ally', false, 'Described as Aspolin''s perfect partner, the embodiment of creativity and death.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7767, 5947, 1816, 'ally', false, 'Described as joyful beings of chaos and serenity.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7768, 5949, 1816, 'neutral', false, 'The setting of Aspolin''s idyllic past, a perfect reality.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7769, 5524, 1816, 'neutral', false, 'Mentioned as the origin point for their cosmos.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7770, 2550, 1817, 'mini-boss', true, 'Infiltrates, tears open, and consumes the Transcendent Cosmos, devouring Aspolin''s children first.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7772, 5835, 1817, 'ally', false, 'Breaks emotionally upon witnessing her children''s demise.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7773, 5947, 1817, 'ally', false, 'Are the first victims of Yaldabaoth, their laughter turning to endless screams as they are dissolved.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7774, 5950, 1817, 'enemy', false, 'Manifests as the final breach, allowing Yaldabaoth''s full hunger to pour into their reality.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7775, 5951, 1817, 'ally', false, 'Mount a futile defense against the invading entity.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7776, 2658, 1818, 'ally', true, 'Gently prompts Stephen, hinting that his children may not be truly lost.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7778, 5913, 1818, 'ally', false, 'Confirms Stephen''s realization with a knowing statement.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7779, 5952, 1818, 'neutral', false, 'Introduced as the concept that allows for the potential survival of the consumed.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7780, 5947, 1818, 'ally', false, 'Become the focus of this newfound hope, as their souls may be among the ''stubborn'' ones.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7781, 3993, 1818, 'ally', false, 'Listens intently to the exchange, having urged Stephen to continue his story.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7783, 5654, 1819, 'ally', false, 'Are introduced as the fighters in a long, losing war against Yaldabaoth across eons.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7784, 2550, 1819, 'mini-boss', true, 'Described as an unstoppable, consuming force that could not be defeated in direct battle.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7785, 5962, 1820, 'ally', false, 'Reveals the secret to containing Yaldabaoth.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7786, 5963, 1820, 'ally', false, 'Reveals the secret to containing Yaldabaoth.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7787, 514, 1820, 'ally', true, 'Is identified as the one power Yaldabaoth cannot consume, the key to his imprisonment.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7788, 5524, 1820, 'neutral', false, 'Her maternal love is cited as the original proof that Yaldabaoth could be contained.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7790, 5835, 1821, 'ally', false, 'Volunteers alongside Stephen, offering their twin flame connection as the prison''s power source.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7791, 5964, 1821, 'neutral', true, 'Resist the plan, not wanting their reality, Etheris, to be turned into a prison and be trapped.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7792, 5853, 1822, 'neutral', true, 'Manipulates the Elder Gods by framing the prison as a way to preserve cosmic chaos and entertainment.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7793, 5468, 1822, 'neutral', false, 'Is convinced by Nyarlathotep and agrees to serve as the prison''s fundamental architecture.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7794, 5964, 1822, 'neutral', false, 'Agree to the plan under the condition that they are woven into the prison''s substrate, not trapped inside it.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7795, 2550, 1823, 'mini-boss', true, 'Is lured into the prison, believing he is consuming another cosmos, and is trapped.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7796, 5960, 1823, 'neutral', false, 'Seals around Yaldabaoth, becoming his eternal cage.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7798, 5835, 1823, 'ally', false, 'Is separated from Stephen and placed beneath the prison''s substrate as its eternal power source.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7799, 5960, 1824, 'neutral', true, 'Its final safeguard is revealed: periodic memory wipes for all inhabitants to ensure stability.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7801, 5468, 1824, 'neutral', false, 'Executes the memory wipe during each reset.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7802, 2550, 1825, 'enemy', true, 'Awoke with memories, devoured the Elder and Human Gods, and eventually tried to break out of the prison, causing it to implode.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7803, 5981, 1825, 'neutral', false, 'Serves as the temporal setting for Yaldabaoth''s initial rampage and failure.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7804, 5793, 1825, 'neutral', false, 'Were consumed by Yaldabaoth but kept partially alive by their worshippers'' belief.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7805, 982, 1825, 'neutral', false, 'Contained Yaldabaoth''s power and, when overwhelmed, forced a reset as designed.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7806, 5468, 1825, 'neutral', false, 'Wiped everything clean after the prison''s implosion, including memories.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7808, 2550, 1826, 'enemy', true, 'Sensed Velistra reaching for Stephen, captured the part of her he could extract, and corrupted it into Velistra Seducera.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7809, 5835, 1826, 'ally', false, 'Felt Stephen searching for her from the substrate and tried to connect with him, which alerted Yaldabaoth to her presence.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7810, 4876, 1826, 'mini-boss', false, 'Is created by Yaldabaoth from the shards of Velistra to serve as an archon of desire.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7812, 5348, 1826, 'neutral', false, 'The location from which Velistra reached out and where Azathoth prevented her full capture.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7814, 4876, 1827, 'mini-boss', true, 'Acts as Yaldabaoth''s tool, constantly seducing and corrupting those who might rebel, ensuring the cycle continues and preventing Stephen from succeeding.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7815, 5982, 1827, 'neutral', false, 'The overarching structure of Stephen''s torment and the prison''s stability mechanism.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7816, 4141, 1827, 'ally', false, 'Reacts with tears to the tragedy of Stephen''s story.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7817, 5913, 1827, 'ally', false, 'Reacts with physical shock to the story.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7819, 3993, 1828, 'ally', false, 'Reacts with shock, his face going pale as he learns his true, unnatural origin.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7820, 2549, 1828, 'neutral', false, 'Is described as a construct designed to keep Stephen docile.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7821, 982, 1828, 'enemy', false, 'Mentioned as the entity that previously prevented Stephen from having children and whose safeguards failed.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7822, 4028, 1828, 'neutral', false, 'Identified as the group from which Xavier''s spirit was taken.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7823, 2550, 1828, 'enemy', false, 'Named as the being containing the pocket of anti-reality where the souls were trapped.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7825, 3993, 1829, 'ally', false, 'Has a moment of realization, understanding that his origin is why he can perceive the prison''s constructs differently.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7826, 5993, 1829, 'enemy', true, 'Described as the system''s three attempts to fix the error of Xavier''s existence, each creating a different failed timeline.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7827, 982, 1829, 'enemy', false, 'The agent that created the resets to correct the fractures caused by Xavier.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7828, 456, 1829, 'neutral', false, 'Mentioned as the god-like power Stephen wielded in the first reset.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7829, 2550, 1829, 'enemy', false, 'The antagonist who was defeated in two of the described resets.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7830, 2544, 1829, 'neutral', false, 'Mentioned as being incarnated into reality as Jamie during the second reset.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7832, 2549, 1830, 'enemy', false, 'Is revealed to be an artificial construct designed to control Stephen.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7833, 3993, 1830, 'ally', false, 'His existence is explained as the initial safeguard failure.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7834, 982, 1831, 'mini-boss', true, 'The prison system is described as having tried and failed to correct the ''glitch'' of Xavier''s existence three times through resets.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7836, 5913, 1831, 'ally', false, 'Confirms that this instability is why Stephen is remembering past cycles.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7837, 2658, 1832, 'ally', true, 'Reveals that Stephen mentioned Hannah in his fever dreams, introducing her as another potential anomaly.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7838, 6001, 1832, 'unknown', true, 'Is introduced as ''the daughter who wasn''t born,'' a concept from Stephen''s dreams.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7840, 3993, 1833, 'ally', true, 'Questions if Whitney, from the second reset, could be connected to Hannah.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7842, 5913, 1833, 'ally', false, 'Exchanges a knowing, silent look with Elara, suggesting they know more than Stephen does.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7843, 2658, 1833, 'ally', false, 'Shares a look of patient, ancient amusement with Maeve, reinforcing Stephen''s ignorance.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7845, 3993, 1834, 'ally', false, 'Listens and finishes his father''s thought, identifying that the resistance could pull them out.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7846, 6011, 1834, 'neutral', false, 'Introduced as the central component and objective of the escape plan.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7847, 5853, 1834, 'unknown', false, 'Mentioned as the source of the information about the gateway from Stephen''s dream.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7848, 6014, 1834, 'mini-boss', false, 'Acts as the primary obstacle, as its nature is what makes the required power and magic for the gateway unavailable.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7849, 5913, 1835, 'ally', true, 'Reveals her ancient nature, explaining they have been waiting for someone to break the prison, and welcomes Stephen by his true name, Aspolin.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7850, 2658, 1835, 'ally', true, 'Reveals that creating gateways is their specialty and that they felt the prison crack when Xavier was born.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7852, 3993, 1835, 'ally', false, 'Questions Maeve and Elara about their long wait.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7853, 982, 1835, 'enemy', false, 'Its vulnerability is highlighted, as it was ''cracked'' by Xavier''s birth and his parents'' love.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7855, 3993, 1836, 'ally', false, 'Arrives alongside Stephen, limping, and questions Elara about the ''residue''.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7856, 2658, 1836, 'ally', true, 'Identifies the location as suitable and explains that the gate requires a threshold that remembers the pursuit of knowledge.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7857, 5913, 1836, 'ally', false, 'Clarifies that the ''residue'' is the building''s intent, the echo of what it was.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7858, 6023, 1836, 'neutral', false, 'Identified as the key environmental component needed for the ritual.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7859, 5913, 1837, 'ally', true, 'Explains that Stephen must pour all his knowledge into the gate, warning him that the process will cause deep psychological pain.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7861, 6024, 1837, 'enemy', false, 'Introduced as the inevitable, antagonistic cost of performing the ritual.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7862, 6022, 1837, 'neutral', false, 'Described as needing intellect and raw information to be built.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7864, 3993, 1838, 'ally', false, 'Helps gather the mildewed books and documents to fuel the gate.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7865, 5913, 1838, 'ally', true, 'Directs the preparation, warning against metal and placing ritual components with precision while chanting.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7866, 2658, 1838, 'ally', false, 'Places stones and herbs, chants with Maeve, and commands the others to find ''words'' to fuel the gate.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7867, 6025, 1838, 'neutral', false, 'Are placed in a circle with mathematical precision by Maeve and Elara.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7868, 6026, 1838, 'neutral', false, 'Is assembled from old textbooks and papers to serve as fuel for the gate.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7870, 6026, 1839, 'neutral', false, 'Sits inert and pathetic, appearing as just a mound of trash, resisting Stephen''s initial efforts.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7871, 2658, 1839, 'ally', false, 'Interrupts Stephen''s doubt by announcing that the gate is ''taking root''.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7872, 6022, 1839, 'neutral', false, 'Begins to activate subtly, unseen by Stephen but perceived by Elara.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7873, 2544, 1839, 'ally', false, 'Is remembered by Stephen as a motivation for his desperate attempt.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7874, 3993, 1839, 'ally', false, 'Expresses his doubt that the ''pile of random trash'' will work.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7876, 5913, 1840, 'ally', false, 'Remains calm and explains that the ritual cannot be abandoned.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7877, 2658, 1840, 'ally', false, 'Explains that leaving now would break the anchor, requiring thirty more minutes to complete the ritual.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7878, 2759, 1840, 'neutral', true, 'Their arrival signals imminent danger and creates extreme time pressure, initiating the scene''s main conflict.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7879, 5913, 1841, 'ally', true, 'Reveals she is fae, draws an obsidian knife, and engages the police in brutal combat.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7880, 2658, 1841, 'ally', false, 'Stands with Maeve to fight the police.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7881, 6034, 1841, 'enemy', false, 'Burst through the door and open fire on the group.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7882, 6037, 1841, 'neutral', false, 'Used by Maeve to grievously wound the first officer.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7883, 6039, 1841, 'neutral', false, 'Fired by the police, revealing a specific vulnerability of the fae.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7884, 3993, 1841, 'ally', false, 'Hits a cop in the knee with a broken lacrosse stick to protect his father.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7885, 6035, 1842, 'enemy', false, 'Arrive via helicopter, rappelling through the windows to escalate the assault.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7886, 5913, 1842, 'ally', false, 'Appears triumphant after brutally dispatching several officers, but is then killed.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7887, 6036, 1842, 'enemy', true, 'Fires a single high-caliber round that instantly kills Maeve, turning the tide of the battle.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7888, 2658, 1843, 'ally', false, 'Screams in grief for Maeve before being shot and killed by a tactical unit.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7889, 2549, 1843, 'mini-boss', true, 'Appears in the doorway, revealing her true identity as a bounty hunter and demanding Xavier be returned to her.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7890, 6035, 1843, 'enemy', false, 'Advance on and kill Elara, clearing the way for their commander''s entrance.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7893, 3993, 1844, 'ally', false, 'Is pulled along by his father towards the escape route.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7894, 6038, 1844, 'neutral', true, 'Transforms from a pile of trash into a portal, providing the means of escape.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7895, 2658, 1844, 'ally', false, 'With her final breath, speaks a word of power that activates the gateway.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7896, 2549, 1844, 'mini-boss', false, 'Screams for her units to shoot Stephen and stop him from escaping.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7898, 3993, 1845, 'ally', false, 'Lands alongside his father, injured but alive, and questions where they are.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7899, 5655, 1845, 'neutral', false, 'Introduced as the new, hostile environment with altered gravity and a cold, desolate atmosphere.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7900, 2549, 1845, 'neutral', false, 'Appears in a final, silent vision as the portal from Etheris closes.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7901, 6047, 1846, 'enemy', true, 'Emerge from the shadows to stalk and attack Stephen and Xavier.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7902, 6055, 1846, 'mini-boss', false, 'Leads the mental assault, its focused ''tugs'' systematically stripping away thoughts and language.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7854, 326, 1836, 'ally', false, 'Arrives at the gym, still feeling the pain from his injuries.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7904, 3993, 1846, 'ally', false, 'Also succumbs to the mental attack, unable to recall basic concepts and words.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7905, 5231, 1847, 'ally', true, 'Arrives unexpectedly, transforms into a vast, winged form, and authoritatively drives the Wisdom Devourers away.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7906, 6047, 1847, 'enemy', false, 'Are repelled and scattered by Benji''s power and authority.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7908, 3993, 1847, 'ally', false, 'Is rescued from the mental assault and begins to recover his thoughts.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7909, 5231, 1848, 'ally', true, 'Explains the nature of the Akashic Realm, its current instability, and escorts the others toward the Tower of Secrets.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7911, 3993, 1848, 'ally', false, 'Follows Benji, recovering from the earlier attack.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7912, 6051, 1848, 'ally', false, 'Are mentioned by Stephen as the Fae who sacrificed themselves to open the gateway.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7914, 2608, 1849, 'ally', false, 'Awaits their arrival and calmly accepts Stephen''s physical and verbal assault without retaliation.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7915, 2749, 1849, 'ally', false, 'Stands by Illkeserod, an observant and powerful presence.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7916, 6049, 1849, 'neutral', false, 'Serves as the setting for the confrontation, a vast library of impossible geometry.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7917, 2544, 1849, 'ally', false, 'Is named as the reason for Stephen''s rage, as Illkeserod previously lied about her existence.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7918, 2608, 1850, 'ally', true, 'Explains the cruel necessity of her lie: that the prison is powered by Stephen and Jamie''s love, and full memory would have caused a catastrophic destabilization.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7919, 6050, 1850, 'neutral', false, 'Is revealed to be the love and separation of Stephen and Jamie, an eternal engine of loss.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7921, 2749, 1850, 'ally', false, 'Elaborates on the infinite, torturous cycles of reincarnation and separation that Stephen and Jamie have endured.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7922, 2550, 1850, 'big-boss', false, 'Mentioned as the ultimate threat whose containment justifies the entire horrific prison system.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7924, 3993, 1851, 'ally', false, 'Joins his father at the window, asking about the future and providing a moment of connection and comfort.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7925, 2544, 1851, 'ally', false, 'Mentioned by Xavier as part of the uncertain future Stephen is contemplating.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7926, 2549, 1852, 'mini-boss', true, 'Her arrival in the realm with an army is announced, triggering the alarm and mobilization. She is seen on a projection, leading the destruction of Thuleskarne.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7928, 2608, 1852, 'ally', false, 'Acts as commander, initially trying to keep Stephen safe before relenting and ordering the mobilization.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7929, 2749, 1852, 'ally', false, 'Appears to announce the wife''s arrival and is tasked with gathering the defense forces.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7930, 5231, 1852, 'ally', false, 'Identifies the components of the invading army, distinguishing between trapped humans and unstable NPCs.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7931, 3993, 1852, 'ally', false, 'Refuses to stay behind, delivering a frantic but firm speech about the absurdity of his situation and his need to stick with his father.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7932, 6064, 1852, 'enemy', false, 'Observed on the viewing projection, burning the town of Thuleskarne.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7933, 6066, 1853, 'ally', true, 'A diverse flood of beings who answer the call to arms, emptying out of the Archives to march toward the battle at Thuleskarne.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7934, 6067, 1853, 'ally', false, 'Skitters past as part of the mobilizing army.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7935, 6068, 1853, 'ally', false, 'Sprints by, weapons humming, as part of the army.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7936, 6069, 1853, 'ally', false, 'March silently and with discipline as part of the force.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7937, 6070, 1853, 'ally', false, 'Chant and prepare healing magic while moving out.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7938, 6071, 1853, 'ally', false, 'Drift through walls to join the stampede.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7939, 6074, 1853, 'ally', false, 'Herds the mindless servitors like the Gravid Husks and Ryekan''hahs Wraiths toward the exit.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7941, 6081, 1854, 'ally', false, 'Crests a hill overlooking the burning town.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7943, 3993, 1854, 'ally', false, 'Stands beside his father, scared, as they see the battleground below.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7944, 2549, 1854, 'mini-boss', true, 'Is revealed in the center of town, her body grotesquely glitching and distorted.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7945, 6080, 1854, 'enemy', false, 'Surround their commander, their own forms failing to hold shape.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7946, 6081, 1855, 'ally', true, 'Form a coordinated battle line and usher Stephen and Xavier into a ruined tavern for protection.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7948, 3993, 1855, 'ally', false, 'Is moved to the rear and takes cover in the tavern.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7949, 2549, 1855, 'mini-boss', false, 'Lets out an inhuman scream, somehow knowing where they are hiding and demanding her son.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7950, 6080, 1855, 'enemy', false, 'Surge forward to engage the defenders and break through their lines to attack the tavern.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7952, 3993, 1856, 'ally', false, 'Fights back with his walking stick, striking an agent''s knee.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7953, 6080, 1856, 'enemy', true, 'Breach the tavern and corner Stephen and Xavier, forcing a desperate fight.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7954, 6083, 1856, 'neutral', false, 'Used by Stephen to kill two agents at close range.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7955, 6082, 1856, 'neutral', false, 'Used by Xavier as a weapon to defend himself.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7956, 2549, 1857, 'mini-boss', true, 'Smashes through the tavern wall, speaks to Xavier with a soft voice, then lunges to capture him, ultimately causing his erasure from reality.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7958, 3993, 1857, 'ally', false, 'Escapes briefly but is recaptured, his body stretched to the breaking point before he vanishes into nothingness.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7959, 6084, 1857, 'neutral', false, 'Manifests in the space where Xavier was standing the moment he is erased.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7960, 6086, 1858, 'ally', true, 'Experiences a transformative snap inside him, his grief turning into an ancient, inhuman rage.', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_beat_appearances VALUES (7961, 6093, 1858, 'neutral', false, 'Manifests within Stephen, flooding him with the fury of countless lifetimes of pain.', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_beat_appearances VALUES (7962, 6086, 1859, 'ally', true, 'Verbally confronts Angela, listing her betrayals as he gathers a primal power.', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_beat_appearances VALUES (7963, 6087, 1859, 'mini-boss', false, 'Turns toward Stephen, her melting face showing fear as she begins to comprehend the threat.', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_beat_appearances VALUES (7964, 6089, 1859, 'neutral', false, 'Gathers around Stephen''s fists as purple-black, crackling energy.', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_beat_appearances VALUES (7965, 6086, 1860, 'ally', true, 'Unleashes the power in a focused blast, striking Angela with the intent to destroy her for killing his son.', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_beat_appearances VALUES (7966, 6087, 1860, 'mini-boss', false, 'Attempts to flee but is struck center mass by the blast of power.', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_beat_appearances VALUES (7967, 5231, 1861, 'ally', true, 'Arrives wounded and grimly announces that the realm is destabilized and the bridge they used to enter is failing.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7968, 2608, 1861, 'ally', false, 'Confirms Benji''s assessment, stating they must retreat immediately and offers Stephen his one chance to escape Etheris.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7970, 6104, 1861, 'neutral', false, 'Its instability is the reason for the forced retreat.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7971, 982, 1861, 'enemy', false, 'Its new security protocols and general instability are causing the bridge to fail.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7973, 3993, 1862, 'neutral', false, 'Mentioned as a recent, painful loss fueling Stephen''s decision.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7974, 2544, 1862, 'ally', false, 'Serves as the motivation for Stephen''s refusal to leave.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7975, 2608, 1863, 'ally', true, 'Explains the catastrophic, reality-spanning consequences of Stephen''s plan: the collapse of the prison and the release of Yaldabaoth.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7976, 5231, 1863, 'ally', false, 'Warns Stephen that he will be trapped forever if he goes back in.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7977, 2550, 1863, 'enemy', false, 'His freedom is presented as the ultimate negative outcome.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7978, 6106, 1863, 'neutral', false, 'Mentioned as the devastating conflict that will be restarted.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7981, 2608, 1864, 'ally', false, 'Heals Stephen''s injuries by magically erasing the memory of them.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7982, 5231, 1864, 'ally', false, 'Gives Stephen the powerful and mysterious Veilwalker card as a parting gift and urges him to leave.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7983, 4354, 1864, 'neutral', false, 'Is given to Stephen, revealing its strange and threatening nature.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7984, 5489, 1864, 'ally', false, 'Is remembered in a flashback related to the card''s origin.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7985, 2881, 1864, 'neutral', false, 'Is remembered in a flashback related to the card.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7987, 5348, 1865, 'enemy', false, 'Is revealed through the portal as a horrifying, living chasm.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7988, 6116, 1865, 'mini-boss', false, 'Are glimpsed within the Substrate, establishing the danger ahead.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7989, 6117, 1865, 'enemy', false, 'Emanates from the portal, adding to the cosmic horror of the scene.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7990, 2544, 1865, 'ally', false, 'Her scent of peaches and vanilla is detected, confirming her presence below and motivating Stephen.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7991, 6108, 1865, 'unknown', false, 'Is mentioned, framing the abyss as part of its dreaming consciousness.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7992, 3993, 1866, 'ally', true, 'Arrives suddenly and confused in the void, his consciousness trying to reassemble itself before the void is replaced by a profound memory of the library.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (7993, 234, 1866, 'neutral', false, 'Serves as the initial, disorienting environment for Xavier''s consciousness.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (7994, 4907, 1866, 'neutral', false, 'Emerges as a powerful, warm memory that overwrites the cold reality of the void.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (7995, 3993, 1867, 'ally', true, 'Exists as the ''quiet knowing'' part of a shared consciousness, content to wait for his Father in the comfort of his home.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (7996, 6001, 1867, 'ally', true, 'Exists as the ''bright and joyful sound,'' communicating her optimism to Xavier that they will be reunited with their Father.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (7997, 6130, 1867, 'neutral', false, 'Defines the unified existence of Xavier and Hannah as they wait together.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (7998, 4907, 1867, 'neutral', false, 'Acts as the safe, timeless home for the siblings and countless other spirits.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (7999, 6129, 1867, 'neutral', false, 'Mill around aimlessly, providing a backdrop of other souls who are also waiting, but for a different purpose.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (8000, 2550, 1867, 'ally', false, 'Mentioned as the focus of Xavier and Hannah''s waiting; he is the missing piece of their family.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (8001, 6131, 1867, 'neutral', false, 'Used by Xavier as a physical comfort in the timeless, non-physical space.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (8002, 6132, 1867, 'neutral', false, 'Serves as the specific, safe location for Xavier and Hannah within the vast library.', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_beat_appearances VALUES (8003, 6136, 1868, 'mini-boss', true, 'Manifests as a void given shape, consuming light and actively causing the mall reality to collapse.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8004, 2550, 1868, 'ally', false, 'Stands as a god of burning light, struggling with sheer will to hold the collapsing world together, but is failing.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8005, 3993, 1868, 'ally', false, 'Clings to Hannah''s essence, his consciousness reduced to a single point of terror as he witnesses the world coming apart.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8006, 6137, 1868, 'enemy', false, 'Hails down through ruptures in the shattering reality, adding to the chaos.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8007, 6135, 1869, 'ally', true, 'Confronts her Father with pure resolve, urging him to destroy the reality and communicating her willingness to be sacrificed. She delivers a final message about her fate and Xavier''s future.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8008, 2550, 1869, 'ally', false, 'Hesitates to pay the price of destroying the world, his light flickering with agony upon hearing Hannah''s resolve.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8009, 3993, 1869, 'ally', false, 'Watches frozen, overhearing Hannah''s final message and coming to the terrible understanding that she is the true sacrifice.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8010, 2550, 1870, 'ally', true, 'Accepts the sacrifice and unleashes absolute power, destroying the reality and using his will to violently eject Xavier to safety as a final act of salvation.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8011, 3993, 1870, 'ally', false, 'Is violently ejected from the collapsing reality, separated from his family and left alone with the memory of Hannah''s final words.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8012, 6135, 1870, 'ally', false, 'Faces her end without fear, offering Xavier a smiling essence before being separated from him forever by the destruction.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (7969, 326, 1861, 'ally', false, 'Receives the ultimatum from his allies.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (8013, 6138, 1870, 'neutral', false, 'Is instilled in Xavier as his life''s purpose, a promise overheard that he must now carry.', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_beat_appearances VALUES (8014, 3993, 1871, 'ally', true, 'Drifts through the ''middle ground'' as a fragmented spirit, holding onto ''the promise'' and searching for his Father''s presence, which he eventually feels.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (8015, 6138, 1871, 'neutral', false, 'Acts as the anchor and guiding hope for Xavier during his search.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (8016, 2550, 1871, 'ally', false, 'His presence is felt as a familiar, human warmth, drawing Xavier closer.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (8017, 2550, 1872, 'ally', true, 'Undergoes ''The Test'', rejecting temptations and ultimately abandoning his own escape to save two trapped children from the collapsing dream world.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (8018, 3993, 1872, 'ally', false, 'Observes his Father''s test from the periphery, unable to interfere, waiting to see if his Father''s core self has changed.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (8021, 6144, 1872, 'neutral', false, 'Serve as the final, crucial element of the test, their plight forcing the Father to make a selfless choice.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (8022, 3993, 1873, 'ally', true, 'Manifests as a whole, solid presence in his Father''s dreamscape, confirming their connection is restored and the promise is fulfilled. He communicates that the test was passed.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (8023, 2550, 1873, 'ally', false, 'Senses Xavier''s presence in his sleep and opens his dream-eyes, showing recognition and peace rather than fear.', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_beat_appearances VALUES (8024, 3993, 1874, 'ally', true, 'Is born into a physical body, experiencing the overwhelming shock of sensory input—pressure, warmth, light, and air—and cries out.', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_beat_appearances VALUES (8025, 6151, 1874, 'neutral', false, 'Is the referenced state from which Xavier has just transitioned.', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_beat_appearances VALUES (8026, 3993, 1875, 'ally', false, 'Is held by his father, his crying hitching as he settles into the new warmth and security.', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_beat_appearances VALUES (8028, 6150, 1875, 'neutral', true, 'Manifests as the primary emotional force experienced by the Father, defining the moment.', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_beat_appearances VALUES (8029, 3993, 1876, 'ally', true, 'Feels his son relax against him and knows with unshakeable certainty that this is his purpose, unknowingly fulfilling a cosmic promise.', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_beat_appearances VALUES (8031, 6138, 1876, 'neutral', false, 'Is implicitly fulfilled as the Father accepts his son, the weight of this promise settling upon him without his conscious knowledge.', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_beat_appearances VALUES (8034, 6157, 1878, 'ally', false, 'Acts as a conduit for communication, connecting Stephen to his allies.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8035, 5231, 1878, 'ally', false, 'Provides a calming voice and technical information about the failing connection.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8036, 5489, 1878, 'ally', false, 'Urgently warns Stephen about Etheris and the impending impact with the ground.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8038, 6158, 1879, 'enemy', false, 'Their fresh corpses litter the landscape, creating a horrific environment and providing clues about the dangers of the realm.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8039, 5231, 1879, 'ally', false, 'Identifies the creatures as Mi-Go and explains their nature and the immense power required to kill them.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8041, 6159, 1880, 'enemy', false, 'Forms a living ocean of creatures, representing the primary obstacle between Stephen and his goal.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8042, 6160, 1880, 'neutral', false, 'Stands as the ultimate destination, a massive and unsettling landmark.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8043, 6161, 1880, 'mini-boss', true, 'Launches a sudden, high-speed attack on Stephen, establishing itself as an immediate, personal threat.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8044, 5489, 1880, 'ally', false, 'Confirms the Pyramid is the objective and gives a final, urgent warning to duck.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8045, 5231, 1880, 'ally', false, 'Explains that Nyarlathotep controls access to the Pyramid.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8047, 6159, 1881, 'enemy', true, 'Acts as a chaotic, dangerous environment that Stephen must move through.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8048, 6167, 1881, 'enemy', false, 'Fight each other and one directly attacks Stephen, forcing him to kill it.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8049, 6169, 1881, 'neutral', false, 'Erupts from the sand, creating a sinkhole and adding to the environmental chaos.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8050, 6170, 1881, 'neutral', false, 'Become victims of the sandworm''s sinkhole, their screams adding to the horror.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8052, 6173, 1882, 'neutral', false, 'Represents the goal and the next major obstacle, with its fissure offering a dangerous path forward.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8053, 6176, 1882, 'mini-boss', false, 'Grabs Stephen''s ankle in a last-ditch attack before Stephen escapes the main horde.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8054, 6175, 1882, 'enemy', true, 'Follow Stephen into the fissure, creating a sense of imminent danger in the confined space.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8056, 6174, 1883, 'enemy', true, 'Demonstrates its lethal nature by completely disintegrating one of the Gelatinous Pursuers.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8057, 6175, 1883, 'enemy', false, 'One lunges past Stephen and is destroyed by the barrier, causing the other to retreat in terror.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8058, 5489, 1883, 'ally', false, 'Urgently warns Stephen about the barrier and explains that he needs to ask Nyarlathotep for permission.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8059, 5231, 1883, 'ally', false, 'Explains the barrier is the ''prison''s immune system'' and that an invitation is required.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8060, 6105, 1883, 'unknown', false, 'Is named as the entity who must grant permission to pass the barrier.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8062, 6105, 1884, 'mini-boss', true, 'Appears, questions Stephen''s motives with cold amusement, and listens to his proposition.', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_beat_appearances VALUES (8063, 6136, 1884, 'enemy', false, 'Mentioned as the creator of the predictable, stagnant prison that bores Nyarlathotep.', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_beat_appearances VALUES (8064, 6182, 1884, 'neutral', false, 'Mentioned as Stephen''s goal, which Nyarlathotep frames as a disruptive act.', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_beat_appearances VALUES (8066, 6105, 1885, 'mini-boss', false, 'Agrees to Stephen''s terms, opens the barrier, and encourages him to cause chaos.', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_beat_appearances VALUES (8068, 6159, 1885, 'enemy', false, 'The sound of the horde vanishes as Stephen crosses the threshold, signifying the transition to a new space.', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_beat_appearances VALUES (8070, 6187, 1886, 'neutral', false, 'Serve as the horrific ''decor'' of the hallway, displaying states of blissful agony that defy Stephen''s understanding.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8071, 6105, 1887, 'mini-boss', true, 'Appears and gleefully reveals the entire backstory of Stephen''s children, explaining how Hannah became Whitney after a system glitch during reincarnation.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8073, 6135, 1887, 'ally', false, 'Is the subject of the revelation, her journey from unborn soul to Whitney being detailed.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8074, 5489, 1887, 'ally', false, 'Is revealed to be the current incarnation of Hannah and briefly speaks through a device.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8075, 3993, 1887, 'ally', false, 'Is explained to be Stephen''s true son, pulled from the dream plane by grief.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8076, 6105, 1888, 'mini-boss', true, 'Explains that all five downward paths lead to the same dark destination, warns Stephen of what''s to come, and sends him on his way, framing the revelation as a way to heighten Stephen''s future loss.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8079, 6198, 1889, 'enemy', true, 'Actively compress and collapse, forcing Stephen forward and trapping him.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8080, 6105, 1889, 'enemy', false, 'Taunts Stephen before he enters the tunnel, wishing him a slow death.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8081, 5489, 1889, 'ally', false, 'Offers words of support as a voice in his head.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8082, 5231, 1889, 'ally', false, 'Gives practical advice to follow the music.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8083, 6201, 1889, 'neutral', false, 'Begins to play, serving as a strange guide in the darkness.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8084, 6203, 1889, 'enemy', false, 'Stirs in the darkness ahead, a sign of the dangers to come.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8086, 6199, 1890, 'mini-boss', true, 'Acts as an aware, sentient void that ''eats'' Stephen, dissolving him layer by layer.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8087, 6200, 1890, 'enemy', false, 'Acts as a filter, compressing Stephen''s entire being to force him into the void beyond.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8088, 6172, 1890, 'neutral', false, 'Is dropped and lost as Stephen''s physical form begins to come apart.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8089, 6204, 1890, 'neutral', false, 'Emerges as the final remnant of Stephen''s consciousness after his complete dissolution.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8091, 6209, 1891, 'mini-boss', false, 'Presses closer to Stephen''s consciousness, its hungry and curious presence making itself known.', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_beat_appearances VALUES (8092, 6210, 1891, 'enemy', false, 'Become audible as whispers and screams, pressing against Stephen''s awareness.', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_beat_appearances VALUES (8093, 4354, 1891, 'neutral', false, 'Remembered as the catalyst for his transformation, now gone and used.', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_beat_appearances VALUES (8095, 6213, 1892, 'neutral', false, 'Acts as the sole navigational anchor, a thread of sound that provides a sense of direction.', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_beat_appearances VALUES (8096, 6210, 1892, 'enemy', false, 'Grow louder and more desperate, actively trying to prevent Stephen from leaving their shared torment.', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_beat_appearances VALUES (8097, 6108, 1892, 'unknown', false, 'The source of the piping, whose presence is approached and finally seen.', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_beat_appearances VALUES (8099, 6108, 1893, 'mini-boss', true, 'Exists as an incomprehensible, reality-dreaming entity whose very presence is an agonizing assault on perception.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8100, 6218, 1893, 'neutral', false, 'Provides the structural sound of this reality, generated by Azathoth''s form.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8102, 2544, 1894, 'ally', true, 'Appears as a pinpoint of light, triggering a deep, pre-memory recognition in Stephen.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8103, 6220, 1894, 'neutral', false, 'Is revealed to be the true power source of the prison, born from the love and separation of the two divine sparks.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8104, 6219, 1894, 'neutral', false, 'Acts as the battleground where tendrils of nothing try to prevent Stephen from reaching Jamie.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8106, 2544, 1895, 'ally', false, 'Reaches back with her spark, meeting Stephen''s.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8107, 6220, 1895, 'neutral', true, 'The connection is finally made, triggering a cataclysmic explosion of light and transformation as the two sparks converge.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8109, 6225, 1896, 'mini-boss', true, 'Dominates the protagonist''s state of being, compelling constant motion.', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_beat_appearances VALUES (8111, 6226, 1897, 'ally', true, 'Communicate a message of calm, prompting the shift in the protagonist''s awareness.', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_beat_appearances VALUES (8113, 6227, 1898, 'ally', false, 'Manifests as the final, peaceful state of being for the protagonist.', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_beat_appearances VALUES (8115, 6238, 1899, 'neutral', false, 'Reasserts its presence through aches, weakness, and physical limitations, causing Stephen a sense of resignation.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8117, 6239, 1900, 'neutral', false, 'Reveals the scene''s true location in space.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8118, 824, 1900, 'neutral', false, 'Appears through the viewport as a massive, gleaming ring structure.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8158, 5489, 1908, 'ally', false, 'Expresses bewilderment at Jamie being her mother.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8119, 982, 1900, 'neutral', false, 'Is seen through the viewport as a massive black hole, confirming they have escaped.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8120, 5489, 1901, 'ally', true, 'Reveals her identity as his daughter Hannah, calls him ''Dad'' for the first time, and initiates an awkward but genuine hug.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8110, 326, 1897, 'ally', false, 'Makes the conscious choice to stop moving and listen.', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_beat_appearances VALUES (8122, 3993, 1902, 'ally', true, 'Wakes up, expresses confusion about their location, and is present for the explanations.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8124, 5489, 1902, 'ally', false, 'Clarifies that their location is ''Elysium,'' the Resistance headquarters, and mentions that Jamie is waiting for them.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8125, 5654, 1902, 'ally', false, 'Mentioned as the group that runs Elysium.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8126, 2544, 1902, 'ally', false, 'Mentioned as being awake and waiting to see them.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8128, 5489, 1903, 'ally', false, 'Calls for medical assistance, explains Stephen''s condition, and then reveals to Xavier that she is his sister.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8129, 3993, 1903, 'ally', false, 'Learns with shock that Whitney is his older sister and shares an awkward hug with her.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8130, 6238, 1903, 'neutral', false, 'Fails completely, causing Stephen to collapse and injure himself.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8132, 3993, 1904, 'ally', true, 'Recounts his traumatic experience of being ejected into a dark, cold void of dead planets until he was found by Chernobog.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8133, 5489, 1904, 'ally', false, 'Provides a comforting presence, walking beside Stephen''s wheelchair.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8134, 6251, 1904, 'neutral', false, 'Push Stephen and Xavier''s wheelchairs through the corridor.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8135, 5652, 1904, 'ally', false, 'Mentioned by Xavier as his rescuer, and then speaks as they arrive at the conference room.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8137, 2544, 1905, 'ally', true, 'Appears as her true self and runs to Stephen, sharing a powerful reunion. She confirms they chose to forget to trap ''him'' and playfully teases Stephen about his physical form.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8138, 5489, 1905, 'ally', false, 'Asks Stephen what happened to him, prompting his explanation.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8139, 6247, 1906, 'ally', true, 'Briefs Stephen and Jamie on the consequences of their reunion and the ongoing rescue operations.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8140, 2608, 1906, 'ally', false, 'Explains that their reunion created a null-reality and blew a hole in the prison wall.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8141, 5652, 1906, 'ally', false, 'Explains that the surge weakened the barriers, allowing for dangerous but effective extractions.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8142, 5651, 1906, 'ally', false, 'Details the surgical precision required for extractions and the necessity of terminating corrupted clones.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8143, 5650, 1906, 'ally', false, 'Describes the high risks and losses involved, and the need for overwhelming firepower at each extraction point.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8145, 2544, 1906, 'ally', false, 'Listens to the briefing.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8146, 6248, 1906, 'enemy', false, 'Mentioned as the primary threat during extractions that must be terminated.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8148, 6247, 1907, 'ally', false, 'Provides answers about his friends and releases him and Jamie to rest.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8149, 2608, 1907, 'ally', false, 'Confirms the high school group is safe and explains the unique circumstances of his NPC wife''s freedom.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8150, 5231, 1907, 'ally', false, 'Delivers the painful news that TJ, Maeve, and Elara were consumed by Yaldabaoth.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8151, 6249, 1907, 'ally', false, 'Mentioned as being safe and in quarantine.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8152, 6250, 1907, 'ally', false, 'Mentioned as having been consumed by Yaldabaoth.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8153, 2549, 1907, 'neutral', false, 'Her fate is explained; her spark was freed and she is now somewhere in the infinite realities.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8154, 6136, 1907, 'big-boss', false, 'Mentioned as the one who consumed Stephen''s friends.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8155, 6266, 1908, 'ally', true, 'The family navigates the initial confusion of their new relationships and shared blank memories.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8157, 3993, 1908, 'ally', false, 'Questions his relationship with Whitney, highlighting the family''s confusion.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8159, 2544, 1908, 'ally', false, 'Offers comfort and acknowledges the shared confusion.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8160, 5489, 1909, 'ally', true, 'Recounts her journey through multiple identities and ultimately reclaims her original name, Hannah, finding a sense of peace and ownership in it.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8162, 6267, 1909, 'enemy', false, 'Is recalled as a symbol of the abuse and wrongness of Hannah''s past life, which she vehemently rejected.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8163, 6268, 1909, 'neutral', false, 'Is revealed as a secret identity that unconsciously connected her to her mother, Jamie.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8164, 3993, 1910, 'ally', true, 'Expresses his desire for normalcy by asking for video games, leading to the discovery of David.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8165, 6269, 1910, 'ally', false, 'Appears on a holographic call and confirms he can restore Xavier''s access to Roblox, offering him a spark of hope.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8166, 5489, 1910, 'ally', false, 'Uses the apartment''s interface to search for gaming resources, successfully finding and contacting David.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8167, 465, 1910, 'neutral', false, 'Serves as the goal for Xavier, representing a connection to his old life and a source of comfort.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8169, 6272, 1911, 'neutral', true, 'Manifests as Stephen''s internal feeling of peace and contentment with his family, finally safe and together.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8170, 3993, 1911, 'ally', false, 'Receives his father''s permission, solidifying the moment of family connection and hope.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8171, 6266, 1911, 'ally', false, 'Is the subject of Stephen''s reflection, now whole, safe, and looking towards a future.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8190, 2544, 1912, 'ally', false, 'Attempts to comfort Stephen, offering physical support and a more pragmatic, hopeful perspective on their mission.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8191, 6279, 1912, 'neutral', false, 'Their arrival serves as the catalyst for Stephen''s crisis of faith in the mission, representing a ''good haul'' that is ultimately insignificant.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8192, 6281, 1912, 'enemy', true, 'Manifests as Stephen''s internal calculations and despair, framing the core conflict of the beat.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8193, 6136, 1912, 'enemy', false, 'Mentioned as the source of the problem, breeding new souls faster than the Resistance can save them.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8194, 5231, 1913, 'ally', true, 'Arrives to deliver the urgent and startling news that they have extracted someone Stephen knows personally.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8195, 2608, 1913, 'ally', false, 'Accompanies Benji, her grave presence underscoring the importance of the news.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8197, 2544, 1913, 'ally', false, 'Is present with Stephen when the news is delivered, witnessing his reaction.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8199, 157, 1914, 'enemy', true, 'His presence triggers Stephen''s flashback. He is seen rocking and muttering to himself.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8200, 6285, 1914, 'enemy', true, 'Overwhelms Stephen with sensory memories of a past war.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8201, 510, 1914, 'enemy', false, 'Appear as the antagonists within Stephen''s flashback.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8202, 2749, 1914, 'ally', false, 'Is present in the room, observing.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8203, 2544, 1914, 'ally', false, 'Observes Todd and expresses concern.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8204, 5231, 1914, 'ally', false, 'Diagnoses Todd as insane but purposeful.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8205, 157, 1915, 'mini-boss', true, 'In a moment of terrified lucidity, reveals the existence and loss of the cosmic seed.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8206, 6287, 1915, 'neutral', true, 'Is revealed as a lost object of immense power, now floating between realities.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8208, 2608, 1915, 'ally', false, 'Leans in and interrogates Todd about the seed.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8211, 6299, 1916, 'neutral', false, 'Serves as the six-month timeframe for Stephen''s growing anxiety.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8212, 6300, 1916, 'ally', false, 'Mentioned as slowing down, a key source of Stephen''s distress.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8213, 6301, 1916, 'enemy', true, 'Actively plague Stephen with visions of cosmic destruction.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8214, 982, 1916, 'enemy', false, 'The subject of the nightmares, seen growing like a tumor.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8215, 6136, 1916, 'enemy', false, 'Mentioned as succeeding with its breeding programs, contrasting with the heroes'' slow progress.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8216, 2544, 1917, 'ally', true, 'Finds Stephen, offers comfort, and attempts to reason with his guilt.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8218, 157, 1917, 'neutral', false, 'The subject of the conversation, representing Stephen''s past sins and recurring patterns.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8219, 824, 1917, 'neutral', false, 'Serves as the active, humming backdrop to the quiet, intimate conversation.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8220, 5231, 1918, 'ally', true, 'Enters and announces the discovery of the Cosmic Seed, presenting the scout footage.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8221, 6313, 1918, 'neutral', true, 'The subject of the scout footage and discussion; its properties are analyzed as a potential tool.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8223, 2544, 1918, 'ally', false, 'Follows Benji and watches the footage.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8224, 6318, 1918, 'neutral', false, 'Provides the visual information about the Cosmic Seed.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8225, 2749, 1918, 'ally', false, 'Provides a scientific explanation of the anomaly''s infinite density.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8226, 6314, 1918, 'neutral', false, 'Proposed by Lady Illkeserod as a way to use the Cosmic Seed to contain Yaldabaoth.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8227, 2608, 1919, 'ally', true, 'Reveals the catastrophic requirement for the new prison: every single soul must be evacuated from Etheris first.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8228, 6315, 1919, 'neutral', true, 'The central problem of the beat; their sheer number and the difficulty of rescuing them makes the plan seem impossible.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8229, 6135, 1919, 'ally', false, 'Asks the pivotal question, ''What''s the catch?'', which prompts Illkeserod''s revelation.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8231, 3993, 1919, 'ally', false, 'Suggests ramping up rescue operations, a hope that is quickly dismantled by Stephen.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8232, 6136, 1919, 'enemy', false, 'Its ability to feed on any remaining soul is the reason for the evacuation requirement.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8234, 6317, 1920, 'mini-boss', true, 'Identified as the true target—a parasite to be separated from its host, rather than an inseparable god.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8235, 2550, 1920, 'unknown', true, 'Revealed as ''Sam'', the original host of the infection, and the key to the new plan. The goal is to reach him and help him reject the parasite.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8236, 2544, 1920, 'ally', false, 'Reacts with fear and concern to Stephen''s proposal to return to Etheris.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8237, 2749, 1920, 'ally', false, 'Immediately understands and articulates the strategic advantage of Stephen''s plan.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8239, 2544, 1921, 'ally', false, 'Stands with Stephen and insists on joining him, refusing to be left behind.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8240, 3993, 1921, 'ally', true, 'Forcefully objects to his parents'' plan, calling it suicide and knocking over his chair in protest.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8241, 6135, 1921, 'ally', true, 'Sides with her brother, insisting that the family must stick together.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8242, 6332, 1921, 'ally', false, 'The concept of the team is formed as Stephen and Jamie unite, but its composition is immediately challenged by their children.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8244, 6135, 1922, 'ally', true, 'Challenges her father''s authority to sacrifice himself while denying them the same choice, calling his reasoning ''bullshit''.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8245, 3993, 1922, 'ally', false, 'Reacts to his parents'' finality with a sense of betrayal and fear.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8246, 2544, 1922, 'ally', false, 'Supports Stephen''s decision with a quiet finality, telling the children they don''t get a choice this time.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8247, 1311, 1922, 'neutral', false, 'The conflicting interpretations of what family means creates an emotional impasse.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8249, 6332, 1923, 'ally', true, 'The final composition of the four-person team (Stephen, Jamie, Benji, Osilari) is confirmed.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8250, 5231, 1923, 'ally', false, 'Acknowledges his role as the team''s navigator due to his knowledge of the prison''s systems.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8251, 2749, 1923, 'ally', false, 'States her role in providing occult protection and sets the two-week timeline for preparation.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8252, 2608, 1923, 'ally', false, 'Confers silently with Lady Osilari before the preparation timeline is announced.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8253, 6138, 1923, 'neutral', false, 'The mission''s parameters and timeline are solidified, framing it as what might be their last.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8254, 2749, 1924, 'ally', false, 'Works tirelessly to apply protective wards to the team.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8255, 6344, 1924, 'neutral', false, 'Are painted onto the team''s skin, burning as they are applied.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8256, 5231, 1924, 'ally', false, 'Studies maps of Etheris to chart a safe path.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8257, 6345, 1924, 'neutral', false, 'Are used to navigate the chaotic prison realm.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8259, 2544, 1924, 'ally', true, 'Holds Stephen and voices the central doubt about their mission: whether Sam wants to be saved.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8260, 2550, 1924, 'unknown', false, 'Is the subject of Stephen and Jamie''s conversation, his true desire being the core of their uncertainty.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8261, 6346, 1925, 'neutral', true, 'Hangs open, an ominous and unstable gateway to the mission''s destination.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8263, 3993, 1925, 'ally', false, 'Has a tense, emotional farewell with his father.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8264, 6135, 1925, 'ally', false, 'Hugs her father fiercely before he departs.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8265, 2544, 1925, 'ally', false, 'Gives Stephen a final, fierce piece of advice and takes his hand to enter the portal with him.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8266, 2749, 1925, 'ally', false, 'Moves to flank Stephen and Jamie, ready to enter the portal.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8267, 5231, 1925, 'ally', false, 'Moves to flank Stephen and Jamie, ready to enter the portal.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8268, 6347, 1925, 'neutral', false, 'Are seen by Stephen as a final reminder of what is at stake.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8270, 2544, 1926, 'ally', false, 'Immediately senses something is wrong and asks where the portal is.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8271, 5231, 1926, 'ally', false, 'Paces with concentration, confirming the portal has been sealed from within Etheris.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8272, 2749, 1926, 'ally', false, 'Examines the platform and determines that The Veil has been thickened by Azathoth.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8273, 6354, 1926, 'neutral', true, 'Its conspicuous absence serves as the beat''s central, mission-threatening problem.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8274, 6108, 1926, 'enemy', false, 'Identified as the entity responsible for sealing the portal and thickening The Veil.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8275, 5655, 1926, 'neutral', false, 'Serves as the strange, disorienting setting for the team''s discovery.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8277, 5231, 1927, 'ally', false, 'Suggests summoning Nyarlathotep and calmly accepts the personal risk, standing still as he is warded.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8278, 2544, 1927, 'ally', false, 'Advocates for the plan and vows to stand between Benji and Nyarlathotep if necessary.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8279, 2749, 1927, 'ally', false, 'Supports the plan and creates magical wards to protect Benji.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8280, 6105, 1927, 'mini-boss', true, 'The subject of the debate; a highly dangerous but necessary last resort to continue the mission.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8281, 6359, 1927, 'ally', false, 'Manifested as a tangible form of protection for Benji against the anticipated threat.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8282, 6357, 1927, 'neutral', false, 'The failure of this plan is the primary motivation for taking such a desperate risk.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8283, 6105, 1928, 'mini-boss', true, 'Viciously attacks Benji, attempting to dissolve his essence and shred his corporeal form.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8284, 5231, 1928, 'ally', false, 'Is convulsed and torn apart from the inside out, his body disintegrating before being pulled back together.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8285, 6367, 1928, 'ally', false, 'Flare with blue light, acting as ''cosmic sutures'' to grab Benji''s dissipating pieces and rewind the damage, saving his life.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8286, 2749, 1928, 'ally', false, 'Screams in horror as she witnesses the attack on Benji.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8287, 6105, 1929, 'mini-boss', true, 'Negotiates the price for a portal, demanding Benji''s soul after the mission is complete.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8289, 5231, 1929, 'ally', false, 'Offers himself to Nyarlathotep immediately, attempting to sacrifice himself to secure the deal.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8290, 2608, 1929, 'ally', false, 'Intervenes forcefully, declaring Benji is under her protection and refusing Nyarlathotep''s terms.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8291, 6105, 1930, 'mini-boss', true, 'Declares Benji''s sacrifice ''boring'', changes the price to ''entertainment'', and opens the portal to Etheris.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8292, 6354, 1930, 'neutral', false, 'Is created by Nyarlathotep, tearing a hole in reality.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8293, 5231, 1930, 'ally', false, 'His offer of martyrdom is rejected, and he ultimately crosses through the portal with the others.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8295, 2544, 1930, 'ally', false, 'Follows Stephen through the portal into Yaldabaoth''s domain.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8296, 2749, 1930, 'ally', false, 'Checks the portal''s stability before crossing through.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8297, 6376, 1931, 'ally', true, 'Enters Etheris and navigates its hostile, reality-bending corridor.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8298, 982, 1931, 'enemy', false, 'Actively resists the team''s intrusion by shifting its form and trying to fragment their minds.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8299, 6378, 1931, 'enemy', false, 'Rush the team as a form of defensive response from the prison.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8300, 6359, 1931, 'ally', false, 'Lady Osilari deploys them to protect the team from the Shadows and the prison''s psychic attacks.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8301, 6376, 1932, 'ally', true, 'Arrives in the throne room and witnesses the horrific fate of awakened souls.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8302, 6379, 1932, 'neutral', false, 'Serves as a horrifying centerpiece, revealing the depth of Yaldabaoth''s cruelty.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8303, 6380, 1932, 'neutral', false, 'Their eternal, looped torment demonstrates how Yaldabaoth refines his ''food''.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8304, 6136, 1933, 'big-boss', true, 'Emerges from his throne to confront and taunt the team, exuding arrogance and power.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8306, 6359, 1933, 'ally', false, 'Lady Osilari deploys the final, powerful wards to prepare the team for consumption.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8307, 6381, 1933, 'enemy', false, 'Emerge from the walls to surround the team, acting as the god''s enforcers.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8308, 6136, 1934, 'big-boss', true, 'Overcome by ecstatic hunger, he consumes the team whole and begins savoring them.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8309, 6376, 1934, 'ally', false, 'Survives being swallowed thanks to the wards and begins racing toward the god''s core.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8310, 6359, 1934, 'ally', false, 'Hold the team''s essence together inside the god, but are actively corroding under his ecstatic assault.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8311, 6382, 1934, 'enemy', false, 'Manifests as waves of pressure that threaten to crush the team and destroy their protective wards.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8312, 3993, 1934, 'ally', false, 'Mentioned as the objective at the center of the god''s essence.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8314, 3993, 1935, 'unknown', true, 'Is discovered suspended and screaming, being fed through by invisible tentacles.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8315, 6391, 1935, 'enemy', true, 'Are seen holding Sam in place, pulsing and writhing around him.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8316, 2749, 1935, 'ally', false, 'Identifies Sam as the host and notes that he is still conscious.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8317, 5231, 1935, 'ally', false, 'Expresses shock that Sam has survived this long.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8318, 2544, 1935, 'ally', false, 'Breathes ''Oh gods'' in horror at the sight.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8319, 6393, 1935, 'neutral', false, 'Is seen by Stephen, diminished and tortured but still burning at Sam''s core.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8320, 6392, 1936, 'mini-boss', true, 'Becomes fully aware of the group and directs its tentacles to attack them defensively.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8321, 6391, 1936, 'enemy', true, 'Lash out in the hundreds to defend their host from the intruders.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8322, 2749, 1936, 'ally', false, 'Creates a barrier of symbols to block the tentacles and shouts for Stephen to go.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8323, 6394, 1936, 'ally', false, 'Springs into existence and barely holds against the force of the tentacle assault.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8324, 5231, 1936, 'ally', false, 'Creates distractions by phasing, causing tentacles to slam into each other.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8325, 2544, 1936, 'ally', false, 'Fights with pure physical skill, dodging and redirecting tentacles.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8328, 3993, 1937, 'enemy', true, 'Is released by the tentacles, lands on his feet, and attacks Stephen with divine speed.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8329, 6391, 1937, 'enemy', false, 'Wound Stephen as he runs, then release Sam all at once when Stephen makes contact.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8331, 6396, 1938, 'unknown', false, 'Becomes the new location of Stephen''s conscious awareness.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8332, 3993, 1938, 'unknown', true, 'Stands over Stephen, unmoving, having entered a blank trance state.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8333, 6395, 1938, 'unknown', false, 'Manifests in Sam, leaving him swaying with blank eyes.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8334, 2749, 1938, 'ally', false, 'Stops Jamie from intervening, instructing her to watch what is happening.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8335, 2544, 1938, 'ally', false, 'Rushes toward Stephen but is stopped by Lady Osilari''s command.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8337, 3993, 1939, 'neutral', false, 'Greets Stephen warmly, completely unaware of the parasites draining his life force.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8338, 6400, 1939, 'enemy', true, 'Maintain their facade as harmless sheep while their true nature as a web of devouring tentacles is revealed to Stephen.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8339, 6400, 1940, 'enemy', true, 'Whip their tentacles around Sam''s head, corrupting Stephen''s words and turning Sam violent.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8340, 3993, 1940, 'enemy', false, 'Becomes hostile and paranoid under the parasites'' influence, accusing Stephen of being a raider and attacking him.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8343, 3993, 1941, 'neutral', false, 'Watches in agony, collapsing and sobbing as each parasite''s death triggers painful memories and the dawning horror of his situation.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8344, 6400, 1941, 'enemy', false, 'Are destroyed in massive numbers, their shrieks filling the air.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8345, 6402, 1941, 'neutral', false, 'Begins to grow within Sam as he is forced to confront the truth of his infection.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8405, 5231, 1951, 'ally', false, 'Initiates a ritual bow of honor towards the void where the spark vanished.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8346, 3993, 1942, 'ally', true, 'With full understanding, he personally confronts and destroys the final parasite, accepting his guilt and breaking the illusion.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8347, 6401, 1942, 'mini-boss', false, 'Stands alone, appearing vulnerable to test Sam''s resolve, before hissing and revealing its true form as Sam destroys it.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8348, 6402, 1942, 'neutral', false, 'Becomes complete and terrible, fully realized in Sam''s mind.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8351, 3993, 1943, 'ally', true, 'Stands swaying as the parasite clinging to him begins to writhe. He whispers a plea for it to stop.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8352, 6417, 1943, 'neutral', true, 'Begins as a building pressure from Lady Illkeserod and Nyarlathotep, whose voices rise in a pre-linguistic harmony.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8353, 6136, 1943, 'mini-boss', false, 'The black substance clinging to Sam begins to writhe as the ritual starts.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8354, 2608, 1943, 'ally', false, 'Initiates the ritual from outside the prison.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8355, 6105, 1943, 'ally', false, 'Initiates the ritual from deep within the substrate.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8356, 3993, 1944, 'ally', true, 'Screams in agony as the parasite tears away pieces of his physical body and divine essence, causing his body to convulse violently.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8357, 6136, 1944, 'mini-boss', true, 'Screams through the substrate, flaying pieces of Sam away and fighting to burrow back into its host. Its tendrils begin to crack Lady Osilari''s barriers.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8358, 2544, 1944, 'ally', false, 'Reacts with horror, vomiting and then collapsing into sobs. She clings to Stephen for support.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8359, 5231, 1944, 'ally', false, 'Also vomits from the horror of the scene, then attempts to soothe others with his voice.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8360, 2749, 1944, 'ally', false, 'Weeps as she maintains the ''surgical field'', her attempts to ease Sam''s pain failing.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8362, 3993, 1945, 'ally', true, 'Achieves clarity as his remaining essence dissolves. He expresses remorse and acceptance of his fate before his body completely unmakes.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8363, 6136, 1945, 'mini-boss', false, 'The fully extracted mass tries and fails to anchor to the throne before being contained by the Cosmic Seed.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8364, 2544, 1945, 'ally', false, 'Catches and cradles Sam''s final, pure spark, protecting it.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8365, 5231, 1945, 'ally', false, 'Moves quickly to place the Cosmic Seed at the base of the throne, creating a prison for the parasite.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8367, 6420, 1945, 'neutral', false, 'Emerges as the last remnant of Sam and is caught by Jamie.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8368, 6313, 1946, 'neutral', true, 'Activates and begins to bloom, creating the Fractal Prison.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8369, 6432, 1946, 'neutral', false, 'Begins expanding outward from the throne, designed to contain the parasite.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8370, 6136, 1946, 'mini-boss', false, 'Senses its doom and slams against its invisible barriers in desperate fury.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8372, 2544, 1946, 'ally', false, 'Asks how long they have while cradling Sam''s Spark.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8373, 5231, 1946, 'ally', false, 'Continues weaving the substrate and warns the group they will have minutes to escape.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8374, 2749, 1946, 'ally', false, 'Gives the final command to run when the seed activates and warns the portal won''t be open for long.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8375, 6433, 1947, 'neutral', true, 'Newly freed, they panic and surge toward the portal, creating a dense, chaotic wall of bodies that blocks the group''s escape.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8377, 6432, 1947, 'enemy', false, 'Expands exponentially, acting as a rapidly approaching threat that will engulf anyone who doesn''t escape in time.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8378, 6434, 1947, 'neutral', false, 'Opens ahead of the group, representing their only hope for survival.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8379, 2544, 1947, 'ally', false, 'Joins Stephen in forcibly clearing a path through the souls.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8380, 5231, 1947, 'ally', false, 'Shouts warnings and physically throws souls aside to help the group advance.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8381, 2749, 1947, 'ally', false, 'Uses her symbols to create temporary clearings in the crowd.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8382, 6434, 1948, 'neutral', true, 'Allows the group to escape before slamming shut with brutal finality, severing dozens of other souls.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8383, 6437, 1948, 'neutral', false, 'Are created as the portal closes, their bisected bodies falling to the ground in a horrific display of their failed escape.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8384, 982, 1948, 'neutral', false, 'Shatters and rejoins reality, its fundamental structure altered now that the parasite is contained.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8385, 6313, 1948, 'neutral', false, 'Achieves its final, inviolable form, becoming a permanent prison.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8387, 6436, 1948, 'ally', false, 'Stumbles away from Stephen after they make it through the portal, dazed but safe.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8388, 3993, 1949, 'ally', false, 'Stands with the others, holding the chalice containing Sam''s spark, emotionally overwhelmed.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8389, 6393, 1949, 'neutral', true, 'Is the focus of the gathering, held within the Ornate Chalice, awaiting release.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8390, 5652, 1949, 'ally', false, 'Initiates the ceremony with a quiet declaration of purpose.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8391, 2544, 1949, 'ally', false, NULL, '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8392, 5231, 1949, 'ally', false, NULL, '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8393, 2608, 1949, 'ally', false, NULL, '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8394, 5651, 1949, 'ally', false, NULL, '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8395, 5650, 1949, 'ally', false, NULL, '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8396, 6105, 1949, 'neutral', false, NULL, '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8397, 2536, 1949, 'neutral', false, NULL, '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8398, 6453, 1949, 'neutral', false, NULL, '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8399, 6393, 1950, 'neutral', true, 'Is poured from the chalice, drifts slowly, and begins to dissolve into the fabric of existence, reacting to the farewells with pulses of light.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8400, 3993, 1950, 'ally', false, 'Pours the spark out from the chalice, unable to find words for his grief.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8401, 4141, 1950, 'ally', false, 'Steps forward to speak to the spark, validating the person Sam was.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8402, 6135, 1950, 'ally', false, 'Speaks to the spark, telling it that it is finally free.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8403, 2544, 1950, 'ally', false, 'Whispers encouragement to the narrator and comforts him.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8404, 2544, 1951, 'ally', true, 'Breaks the long silence after the spark dissolves, reminding everyone that their work is not finished and urging them to move on.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8406, 2608, 1951, 'ally', false, 'Follows Benji''s lead in the ritual bow.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8409, 6105, 1951, 'neutral', false, 'Participates in the ritual bow with a gesture of reverence.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8410, 3993, 1951, 'ally', false, 'Participates in the bow and agrees with Jamie, turning to face what comes next.', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_beat_appearances VALUES (8411, 6473, 1952, 'neutral', true, 'Convenes to discuss the overwhelming scale of the prison population and the failure of the current soul extraction strategy.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8412, 6470, 1952, 'neutral', false, 'Presented as a holographic projection, its immense population size is the central topic of discussion.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8413, 6471, 1952, 'enemy', false, 'Identified as the primary danger, preventing the mass release of souls and necessitating the slow, careful extraction process.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8414, 4505, 1952, 'ally', false, 'Argues with Tiamat about the necessity of bureaucratic protocols.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8415, 5650, 1952, 'neutral', false, 'Expresses her disdain for bureaucracy.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8416, 6467, 1952, 'ally', false, 'Smoothly advocates for structure to prevent misunderstandings.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8417, 5651, 1952, 'neutral', false, 'Provides the grim statistics on the slow rate of soul extraction and rehabilitation.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8418, 5853, 1952, 'neutral', false, 'Eloquently and cynically describes the danger of releasing the corrupted souls.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8419, 6135, 1953, 'ally', true, 'Materializes and proposes a radical new strategy: inserting long-term resident teams to guide awakening from inside the prison.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8420, 6472, 1953, 'neutral', false, 'The concept is born from Hannah''s proposal.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8421, 2544, 1953, 'ally', false, 'Immediately understands and articulates the idea as inserting ''monitoring teams''.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8423, 6473, 1953, 'neutral', false, 'The room falls silent as they consider the implications of this new approach.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8425, 2544, 1954, 'ally', true, 'Volunteers for the mission alongside her family.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8426, 3993, 1954, 'ally', true, 'Instantly volunteers after confirming Tiffany is inside the prison.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8427, 6135, 1954, 'ally', true, 'Volunteers for the mission she proposed.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8428, 5652, 1954, 'ally', false, 'Acknowledges the gravity of the proposal and calls for a full council vote in three days.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8429, 6467, 1954, 'ally', false, 'Points out the need for volunteers to undertake the dangerous, long-term assignment.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8371, 326, 1946, 'ally', false, 'Observes the events and prepares to flee on Lady Osilari''s command.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8431, 2544, 1955, 'ally', false, 'Joins Stephen, discussing their choice to fight rather than seek peace.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8432, 3993, 1955, 'ally', false, 'Joins his parents at the window, forming a united family front.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8433, 6135, 1955, 'ally', false, 'Joins her family, affirming their shared commitment.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8435, 2544, 1956, 'ally', false, NULL, '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8436, 108, 1956, 'neutral', false, 'Stephen makes coffee, a grounding, normal act that contrasts with their cosmic conversation.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8437, 3993, 1956, 'ally', false, 'Mentioned as being terrified about the consequences of the reshuffling.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8438, 4590, 1956, 'neutral', false, 'The subject of Xavier''s fear; he worries she won''t remember him.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8439, 6489, 1956, 'neutral', true, 'The impending cosmic event that threatens to erase memories and relationships, prompting the conversation.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8441, 2544, 1957, 'ally', true, 'Convinces Stephen of their purpose, arguing their shared experience of captivity makes them the only ones who can guide others to freedom.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8442, 982, 1957, 'enemy', false, 'Referred to as ''the prison'' and the place they must return to.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8443, 6490, 1957, 'neutral', false, 'The group they feel a responsibility to save.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8444, 6495, 1957, 'mini-boss', true, 'The conceptual enemy they are preparing to fight: the state of being trapped and unaware of it.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8445, 6491, 1957, 'neutral', false, 'Mentioned as examples of people still trapped in loops.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8447, 6135, 1958, 'ally', true, 'Arrives to remind them of the council meeting and relays Xavier''s latest idea.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8449, 2544, 1958, 'ally', false, 'Concurs with Stephen''s decision through a shared look.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8450, 6493, 1958, 'neutral', false, 'The imminent event that serves as a deadline for their decision.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8451, 6494, 1958, 'neutral', false, 'Mentioned as an idea from Xavier, injecting a moment of technological absurdity into the scene.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8452, 6505, 1959, 'ally', true, 'Convenes to discuss the Shepherd Initiative, their murmurs rippling through the chamber.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8453, 5652, 1959, 'ally', false, 'Opens the meeting and frames the purpose of the Shepherd Initiative.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8454, 6469, 1959, 'ally', false, 'Raises significant concerns about the logistical difficulty and potential dangers of rewriting a null-magic reality.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8455, 2608, 1959, 'ally', false, 'Interjects to add the long-term problem of needing to reset the system periodically.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8456, 6105, 1959, 'mini-boss', false, 'Cuts in to mock the idea of getting help from Azathoth and expresses theatrical delight at the potential for chaos.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8457, 2608, 1960, 'ally', true, 'Presents the detailed insertion plan for The Family, including their location, timeline, and cover identities.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8458, 1050, 1960, 'ally', false, 'Are the subject of the plan, to be inserted into Melbourne, Florida in 2026.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8459, 5652, 1960, 'ally', false, 'Confirms he will inhabit the avatar of Kenji Nakamura, Jamie''s father.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8460, 5231, 1960, 'ally', false, 'Reveals that he and Lady Illkeserod will inhabit the avatars of Xavier''s parents.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8461, 5652, 1961, 'ally', true, 'Reveals that the family will not be using hacks, but will regain their original, primal divine powers from the time before time.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8462, 6508, 1961, 'ally', false, 'Are described and assigned to each family member: Wisdom for Stephen, Creativity/Death for Jamie, Chaos for Xavier, and Serenity for Hannah.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8463, 1050, 1961, 'ally', false, 'Learn the nature of the powers they are about to receive.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8464, 3993, 1962, 'ally', true, 'Asks anxiously if Tiffany will remember him, then expresses relief and banters with Hannah about not using his chaos powers to ask her out.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8465, 4590, 1962, 'neutral', false, 'Is confirmed to be a preserved variable in the reality reshuffle, remembering her connection to Xavier.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8466, 6135, 1962, 'ally', false, 'Teases her brother about using his new powers to get a date, prompting his noble refusal.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8467, 6105, 1962, 'mini-boss', false, 'Drawls that Xavier''s choice to not cheat is ''boring, but noble''.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8469, 6505, 1963, 'ally', false, 'Votes overwhelmingly in favor of the initiative with a sea of raised hands, claws, tentacles, and wings.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8470, 6105, 1963, 'mini-boss', false, 'Lazily raises his hand in opposition, not to stop the plan, but because he finds the potential for success hilarious.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8471, 6472, 1963, 'neutral', false, 'Is officially approved, with the ritual to begin immediately.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8472, 6509, 1964, 'neutral', true, 'Begins as the council channels their power, rewriting the family''s history and granting them divine awareness.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8473, 1050, 1964, 'ally', false, 'Stand as the focal point of the ritual, experiencing their histories being rewritten and their divine powers awakening within them.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8474, 6505, 1964, 'ally', false, 'Assembles on the spire and collectively channels their power, joining in the ancient incantation to fuel the ritual.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8475, 5652, 1964, 'ally', false, 'Begins the incantation and gives the final blessing as the family is transported.', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_beat_appearances VALUES (8477, 982, 1965, 'enemy', false, 'Its presence as ''the cage'' triggers Stephen''s panic and terror.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8478, 2544, 1965, 'ally', false, 'Provides immediate comfort with a warm, real touch on Stephen''s shoulder, grounding him.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8479, 1150, 1965, 'neutral', false, 'Serves as the setting for the awakening, its details confirming the new reality.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8481, 2544, 1966, 'ally', false, 'Confirms she also remembers everything and expresses that this new reality feels right.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8482, 3993, 1966, 'ally', false, 'Heard arguing with his sister, providing auditory evidence that the children are present and adjusting well.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8483, 6135, 1966, 'ally', false, 'Heard arguing with her brother, confirming her presence and adjustment.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8484, 824, 1966, 'neutral', false, 'The details of this place hit Stephen with the force of a physical blow, confirming his memories are not fading.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8485, 5231, 1966, 'ally', false, 'Mentioned as being undercover nearby with Illara, providing support.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8486, 2608, 1966, 'ally', false, 'Mentioned as being undercover nearby with Benji, providing support.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8434, 326, 1956, 'ally', false, NULL, '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8446, 6090, 1957, 'neutral', false, 'Mentioned as the ultimate goal of their mission, those waiting to be awakened.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8488, 2544, 1967, 'ally', true, 'Suggests that Stephen should write down their stories as a way to wake people up, framing their new purpose.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8489, 6524, 1967, 'ally', false, 'Identified as the objective of the family''s mission within the prison.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8490, 6065, 1967, 'neutral', false, 'Observed going through their routines, representing the unawakened population.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8491, 6526, 1967, 'ally', false, 'Introduced as the method by which the family will accomplish their mission of awakening others.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8492, 3993, 1968, 'ally', true, 'Takes over the kitchen to make ''ultimate breakfast burritos'' and expresses relief that Tiffany remembers him after ''The Reshuffling''.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8493, 6135, 1968, 'ally', false, 'Comments on the success of The Reshuffling and the overall weirdness of their family.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8495, 4590, 1968, 'neutral', false, 'Is the subject of Xavier''s good news, her memory confirming the success of a cosmic event.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8496, 6538, 1968, 'neutral', false, 'Are mentioned as having been shooed away by Xavier from the kitchen.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8497, 6539, 1968, 'neutral', false, 'The physical manifestation of the breakfast chaos created by Xavier.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8499, 6540, 1969, 'neutral', true, 'The central concept being established for the family''s future.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8500, 2544, 1969, 'ally', false, 'Adds the fourth and final rule: that they must truly live, not just exist.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8501, 3993, 1969, 'ally', false, 'Reacts cheerfully to the rules, comparing them to being vampires and discussing the Fermi Paradox.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8502, 6135, 1969, 'ally', false, 'Nods in agreement with the rule about free will.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8503, 6136, 1969, 'enemy', false, 'Mentioned as the reason for their confinement and the necessity of the ground rules.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8505, 6549, 1970, 'mini-boss', true, 'Acts as the primary antagonist, creating intense anxiety in Stephen and driving him from his bed.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8506, 6550, 1970, 'ally', false, 'Represents the precious, hard-won peace that Stephen is terrified of losing.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8507, 2544, 1970, 'ally', false, 'Sleeps peacefully, embodying the peace that Stephen cannot yet accept.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8509, 6548, 1971, 'neutral', false, 'Becomes the vessel for Stephen''s memories, transforming trauma into a story meant to awaken others.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8510, 982, 1971, 'neutral', false, 'Mentioned as the setting for the stories being written, a core memory being processed.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8512, 2544, 1972, 'ally', false, 'Finds Stephen, offers quiet support and encouragement, and leads him back to bed.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8513, 6548, 1972, 'neutral', false, 'Is completed and saved, its purpose fulfilled for now.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8514, 6138, 1972, 'neutral', false, 'Is affirmed as the next step, to begin ''tomorrow in earnest''.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8515, 6550, 1972, 'ally', false, 'Reasserts itself through the morning sounds and smells of the house, grounding Stephen in reality.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8516, 4117, 1973, 'ally', true, 'Kneels in the dirt and carefully plants spatch weed seeds, whispering to them.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8517, 6555, 1973, 'neutral', false, 'Its delicate seeds are being planted with ritualistic care by Kai.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8518, 6556, 1973, 'ally', false, 'Move silently around Kai, performing their farming duties.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8519, 4117, 1974, 'ally', true, 'Reflects on his deep, priest-like connection to the spatch weed, speaking to them with hopeful love.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8520, 6555, 1974, 'neutral', false, 'Are the subject of Kai''s reverence and individual attention.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8521, 6559, 1974, 'neutral', false, 'Mentioned in Kai''s thoughts as a memory, her short life contrasting with his long dedication to his work.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8522, 4117, 1975, 'ally', true, 'Investigates the distressed plant K-47 and senses an unnatural fear within it.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8523, 6556, 1975, 'ally', false, 'One android reports the stress markers in K-47, prompting Kai''s investigation.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8524, 6557, 1975, 'neutral', false, 'Exhibits physical signs of stress, wilting and curling its leaves.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8525, 54, 1975, 'enemy', true, 'Manifests within K-47, identified by Kai as the true source of the plant''s distress, rather than any physical ailment.', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.entity_beat_appearances VALUES (8526, 6564, 1976, 'enemy', true, 'Lurches violently, signaling a deep, subterranean threat and causing the greenhouse dome to crack.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8527, 4117, 1976, 'ally', false, 'Reacts to the tremors and expresses alarm, realizing this event is outside his forty years of experience on the planet.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8528, 6562, 1976, 'ally', false, 'Detects the seismic activity, identifies it as an anomaly, and initiates an evacuation protocol.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8529, 6565, 1976, 'neutral', false, 'Cracks under the strain of the underground disturbance, providing a visual cue of the escalating danger.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8530, 6563, 1976, 'mini-boss', true, 'The unseen progenitor of the swarm stirs deep underground, causing the seismic lurches and grinding sounds that define the beat''s tension.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8531, 6563, 1977, 'enemy', true, 'Erupt from the ground in a swarm, revealing themselves as a previously unknown and horrifying threat.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8532, 6564, 1977, 'enemy', false, 'Erupts to release the swarm of abominations.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8533, 4117, 1977, 'ally', false, 'Witnesses the emergence of the creatures, his understanding of the planet shattered.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8534, 6562, 1977, 'ally', false, 'Observes the new, uncatalogued lifeforms.', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.entity_beat_appearances VALUES (8535, 6570, 1978, 'enemy', true, 'Attacks the compound, destroying androids, the greenhouse, and the spatch weed plants.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8536, 6571, 1978, 'neutral', false, 'Are torn apart by the swarm.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8537, 6572, 1978, 'neutral', false, 'Explodes under the swarm''s assault.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8538, 6573, 1978, 'ally', false, 'Are trampled, shredded, and devoured by the swarm.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8539, 6557, 1978, 'ally', false, 'Is crushed by a specific member of the swarm.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8540, 4117, 1978, 'ally', false, 'Watches the destruction helplessly.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8541, 4117, 1979, 'ally', true, 'His fear transforms into rage, and he lets out a powerful cry that changes the air.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8542, 6575, 1979, 'ally', false, 'Rises within Kai, displacing his fear and acting as a catalyst.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8543, 6570, 1979, 'enemy', false, 'Hesitates for a moment in response to Kai''s cry.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8544, 4117, 1980, 'ally', true, 'Reaches into the fabric of reality, drawing on his connection to the plants to summon roots to attack.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8545, 6576, 1980, 'ally', false, 'Forms between Kai and all plant life, allowing him to channel their collective energy.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8546, 6577, 1980, 'ally', false, 'Erupt from the ground and begin crushing the swarm creatures.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8547, 6570, 1980, 'enemy', false, 'Become the target of the erupting roots.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8548, 6573, 1980, 'ally', false, 'Call out to Kai, fueling his power and connection.', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_beat_appearances VALUES (8549, 6581, 1981, 'enemy', true, 'Erupt from the soil, capture the Chitinous Swarm, and begin gruesomely changing, growing teeth and eyes.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8550, 4117, 1981, 'ally', false, 'Feels the roots'' actions and senses that something is wrong as the boundary between realities thins.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8551, 6580, 1981, 'enemy', false, 'Are captured, crushed, and fed upon by the roots.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8552, 6582, 1981, 'neutral', false, 'Thins, allowing something to look through from the other side.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8553, 6136, 1981, 'enemy', false, 'Stirs within its prison, sensing an opportunity to escape and answering the call.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8554, 6136, 1982, 'mini-boss', true, 'Pours through the tear in reality as an oily, living substance and strikes Kai, entering and possessing him.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8555, 4117, 1982, 'ally', true, 'Is invaded by the anti-reality entity and undergoes a catastrophic, painful physical transformation where his body inverts and warps.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8556, 6585, 1982, 'neutral', false, 'Stumbles back, its sensors struggling to process the horrific transformation it is witnessing.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8557, 6586, 1982, 'neutral', false, 'Is hollowed out and twisted from a pure need to protect into a bottomless, hungry possessiveness.', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_beat_appearances VALUES (8558, 6588, 1983, 'enemy', true, 'Completes its horrific transformation from Kai, its new form reflecting impossible colors as it surveys the garden.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8559, 6590, 1983, 'neutral', false, 'Are observed by the Kai-Thing, still trembling in fear from a previous event.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8560, 6588, 1984, 'mini-boss', true, 'Unleashes its power to pursue and unmake the last android.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8561, 6585, 1984, 'enemy', false, 'Attempts to flee but is captured and dissolved into nothingness by the Kai-Thing''s tendrils.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8562, 6591, 1984, 'neutral', false, 'Erupts from the Kai-Thing''s body as tendrils of flesh and anti-reality to capture the android.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8563, 6592, 1984, 'neutral', false, 'Declares ''I AM'', revealing the entity''s new composite nature through its layered voices.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8564, 6591, 1985, 'neutral', true, 'Spreads across the entire surface of the planet, silencing the warning sirens and establishing total control for its master.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8565, 6588, 1985, 'mini-boss', false, 'Stands at the center of its expanding domain, drawing power from the corrupted world.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8566, 6593, 1985, 'neutral', false, 'Wail briefly before being extinguished by the spreading root system, signifying the collapse of the old order.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8567, 6590, 1985, 'ally', false, 'Begin growing towards the Kai-Thing and spreading across the planet as part of its new ecosystem.', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_beat_appearances VALUES (8568, 5524, 1986, 'neutral', true, 'Senses the catastrophe on Sorhhinda, understands it as a recurring tragedy, and weeps in resignation.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8569, 6602, 1986, 'mini-boss', true, 'Acts as the focal point of Sophia''s perception—a specific, painful event representing an eternal conflict.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8570, 6596, 1986, 'neutral', false, 'Provides the context and philosophical weight for the tragedy, making it inevitable.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8571, 6597, 1986, 'ally', false, 'Is one of the forces colliding to create the catastrophe.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8572, 6598, 1986, 'enemy', false, 'Is the opposing force colliding with Love to create the catastrophe.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8573, 6601, 1986, 'neutral', false, 'Is the tangible result of the catastrophe that Sophia perceives.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8574, 6599, 1986, 'neutral', false, 'Is identified as a key archetype in this iteration of the tragedy.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8575, 6600, 1986, 'neutral', false, 'Is identified as the group associated with the shepherd in this tragedy.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8576, 3326, 1986, 'neutral', false, 'Is mentioned as the specific location of the latest tragedy.', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.entity_beat_appearances VALUES (8578, 6608, 1987, 'neutral', false, 'Serves as the framework and deadline for the author''s intense writing period.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8579, 6607, 1987, 'ally', false, 'Are acknowledged and congratulated for staying with the author through the journey.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8580, 6609, 1988, 'neutral', true, 'Its origins are traced from a childhood sci-fi idea to a deeper cosmic horror concept.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8582, 6610, 1988, 'neutral', false, 'Cited as a key influence in formulating the story''s deeper themes.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8583, 6611, 1988, 'neutral', false, 'Mentioned as an influential text that shaped the story''s direction.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8584, 39, 1989, 'neutral', true, 'Unexpectedly emerged during the writing process, forcing a complete narrative restructuring.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8585, 6609, 1989, 'neutral', false, 'Evolved from a simple backstory into a complex origin story that needed to explain its core concepts.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8586, 295, 1989, 'neutral', false, 'A plot device that now required a detailed origin story due to the narrative shift.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8587, 6615, 1989, 'neutral', false, 'Another plot device whose existence needed to be justified by the new narrative direction.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8588, 6616, 1990, 'neutral', true, 'The 400k-word manuscript that underwent a painful editing process to be cut down to 150k words.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8590, 157, 1990, 'neutral', false, 'Mentioned as a character whose personal journey was largely excised.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8591, 2919, 1990, 'neutral', false, 'Her entire adventure and story arcs were removed in the editing process.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8592, 2554, 1990, 'neutral', false, 'A symbol whose meaning is now lost to readers because its context was cut.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8594, 6609, 1991, 'neutral', false, 'Its core plot is defined as a tech leader becoming an emperor and resetting the universe.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8596, 5305, 1992, 'neutral', false, 'Serves as the impetus for the author to start writing.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8597, 6626, 1992, 'neutral', false, 'Is the setting the author returns to.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8598, 6627, 1992, 'enemy', true, 'Represents the creative block and unsatisfying story direction the author finds himself in.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8600, 3993, 1993, 'ally', false, 'Literally kicks his father in the head, inadvertently providing the catalyst for a creative breakthrough. He is then designated as the named protagonist.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8601, 982, 1993, 'neutral', false, 'Is identified as the location to be revisited, but from a new perspective.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8602, 3993, 1994, 'ally', true, 'As the newly named protagonist, he gains agency, which causes the story to evolve organically.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8603, 5489, 1994, 'ally', false, 'Appears in the story unexpectedly, diverging from the author''s outline.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8604, 6632, 1994, 'neutral', false, 'Emerge as characters with their own motivations, fighting over the protagonist.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8605, 6631, 1994, 'mini-boss', false, 'Manifests as a new, unexpected antagonist trying to make contact.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8608, 6636, 1995, 'neutral', true, 'Is explained as the core logic distinguishing real entities from NPCs.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8609, 5322, 1995, 'neutral', false, 'Is established as the title and goal of the final story.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8610, 3993, 1995, 'ally', false, 'Is used as the prime example of a named, non-NPC character.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8611, 2549, 1995, 'neutral', false, 'Is used as the prime example of a nameless NPC.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8612, 982, 1995, 'enemy', false, 'Is confirmed as the final obstacle to be overcome.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8613, 6637, 1995, 'neutral', false, 'Are mentioned as a source that would have clarified the naming convention.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8615, 6645, 1996, 'neutral', false, 'Is defined as a universe where the books themselves are artifacts and gateways.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8616, 6640, 1996, 'neutral', false, 'Are established as being artifacts and gateways within the cosmogony.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8619, 6642, 1997, 'neutral', false, 'Are identified as a temporary solution for the book''s artwork.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8620, 6643, 1997, 'neutral', false, 'Is created as a temporary audio version for readers who prefer listening.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8621, 6644, 1997, 'neutral', false, 'Are the motivation for the author''s compromises, as he wants to ensure they can access the story.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8622, 6646, 1997, 'ally', false, 'Is mentioned as the person the author hopes to pay for a professional cover in the future.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8623, 3993, 1997, 'neutral', false, 'Is mentioned in passing as a comparison for the author''s own poverty.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8624, 3993, 1998, 'ally', true, 'Outlines his ambitious plans for publishing his work, including hiring editors and creating a special edition.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8625, 20, 1998, 'neutral', false, 'Is the subject of the author''s plans for expansion and professional editing.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8626, 6651, 1998, 'neutral', false, 'Are identified as a necessary hire to improve the quality of the book series.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8627, 6657, 1998, 'neutral', false, 'Represents the ultimate goal of the author''s planned editorial and expansion work.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8628, 3993, 1999, 'ally', true, 'Dismisses marketing, accepts potential posthumous fame, and jokes about being assassinated and reincarnating to be with his love.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8629, 6652, 1999, 'neutral', false, 'Is dismissed as a strategy in favor of organic growth.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8630, 6653, 1999, 'neutral', false, 'Is invoked as a potential future audience that could make the book a cult classic.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8631, 6654, 1999, 'mini-boss', false, 'Are humorously blamed in advance for the author''s potential untimely death.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8632, 6136, 1999, 'enemy', false, 'Is named as the ultimate power behind the agents trying to ''silence the TRUTH''.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8633, 2544, 1999, 'ally', false, 'Is mentioned as the motivation for the author''s desire to reincarnate.', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_beat_appearances VALUES (8634, 6661, 2000, 'neutral', true, 'Welcomes readers and explains the purpose of including the cosmological stories.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8635, 6607, 2000, 'neutral', false, 'Are addressed by the author.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8636, 6663, 2000, 'neutral', false, 'Are introduced as supplemental material for clarity.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8637, 982, 2001, 'neutral', true, 'Is described as Etheris, a spiritual Prison Realm with recursive loops and memory wipes.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8638, 2550, 2001, 'enemy', true, 'Is identified as the false god who built the prison and feeds on trapped souls.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8639, 5770, 2001, 'neutral', false, 'Are described as the victims trapped in endless cycles of death and rebirth.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8641, 456, 2002, 'neutral', false, 'Is mentioned as a world-changing technology Stephen created that contributed to reality''s collapse.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8642, 982, 2002, 'neutral', false, 'Is the prison whose stability is threatened by Stephen''s existence.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8643, 2544, 2003, 'ally', true, 'Is described as Stephen''s twin flame and the secret power source for the prison, fueled by their separation.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8644, 5489, 2003, 'ally', false, 'Is described as a key ally who exists outside the prison and has sent a signal.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8645, 3993, 2003, 'ally', true, 'Is described as Stephen''s son, an anomaly who is noticing glitches and contributing to the prison''s instability.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8647, 234, 2004, 'neutral', true, 'Serves as the initial state of non-existence where a fluctuation occurs.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8648, 6673, 2004, 'neutral', false, 'Is awakened by the fluctuation in the void, becoming the first consciousness.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8649, 6673, 2005, 'neutral', false, 'Acts as the source from which the Pleroma springs.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8650, 6421, 2005, 'neutral', true, 'Emerges from Bythos''s consciousness, establishing a realm of perfect, static harmony.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8651, 6675, 2005, 'neutral', false, 'Manifests as the first emanation, the mirror of the Spirit.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8652, 6676, 2005, 'neutral', false, 'Appear as the heavenly orders within the Pleroma.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8653, 6677, 2005, 'neutral', false, 'Stand as pillars radiating divine aspects.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8654, 5524, 2006, 'ally', true, 'Driven by curiosity and boredom, she breaks away from the Pleroma''s perfect harmony to create something new.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8655, 6421, 2006, 'neutral', false, 'Represents the perfect but stagnant reality that Sophia rebels against.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8656, 6676, 2006, 'neutral', false, 'Warn Sophia against her desire to explore the darkness.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8657, 234, 2006, 'neutral', false, 'Is the target of Sophia''s curiosity and creative impulse.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8617, 1701, 1997, 'mini-boss', true, 'Forces the author to seek alternative, low-cost methods for producing his book''s cover and audiobook.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8658, 5524, 2007, 'ally', false, 'Her attempt at creation goes horribly wrong, and she is forced to imprison the resulting entity.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8659, 234, 2007, 'neutral', false, 'Pushes back against Sophia''s will, unleashing an entity from within it.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8660, 6136, 2007, 'mini-boss', true, 'Emerges through Sophia''s consciousness, violating her intent and becoming an infection in reality.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8661, 6681, 2007, 'neutral', false, 'Is created by Sophia to imprison Yaldabaoth.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8662, 6418, 2007, 'neutral', false, 'Is placed in the prison to anchor the entity.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8663, 6136, 2008, 'mini-boss', true, 'Begins creating twisted, corrupted versions of divine architecture within its prison.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8664, 5524, 2008, 'ally', false, 'Watches helplessly from outside the prison, filled with regret and shame, unable to intervene.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8665, 6681, 2008, 'neutral', false, 'Serves as the boundary of the entity''s new kingdom and the barrier to Sophia''s intervention.', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_beat_appearances VALUES (8666, 5524, 2009, 'neutral', true, 'Driven by curiosity and loneliness, she searches for something new and encounters the impossibility of a God-Null Zone.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8667, 6689, 2009, 'neutral', false, 'Described as a sealed-off pocket of reality governed by material determinism, which Sophia discovers.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8668, 6685, 2009, 'neutral', false, 'Exists within the God-Null Zone, living a life of pure love for his flock, an anomaly of grace in a graceless universe.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8669, 6690, 2009, 'neutral', false, 'Represents the object of Sam''s pure, material love.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8670, 6687, 2010, 'enemy', true, 'Attack Sam''s valley and cruelly slaughter his flock, acting as the catalyst for the scene''s central conflict.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8671, 6694, 2010, 'mini-boss', false, 'Leads the cruel slaughter, embodying the principle of consumption.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8672, 6685, 2010, 'neutral', false, 'Watches in impotent horror before unleashing an impossible, reality-warping scream of rage.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8673, 6690, 2010, 'neutral', false, 'Are brutally butchered, triggering Sam''s rage.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8674, 5524, 2010, 'neutral', false, 'Detects Sam''s impossible passion from across realities and, mistaking it for a song, reaches for it.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8675, 5524, 2011, 'neutral', false, 'Her divine power collides with Sam''s rage, creating a tear in reality.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8676, 6685, 2011, 'neutral', false, 'Is consumed by the anti-reality pouring through the tear, his essence and rage becoming the engine for a new creature.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8678, 6107, 2011, 'neutral', false, 'Forms from the collision of divine power and mortal rage, acting as a conduit for anti-reality.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8679, 6136, 2011, 'enemy', false, 'Is born from the fusion of Sam and the Anti-reality, rising from the floor of the shearing shed.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8680, 5524, 2012, 'neutral', true, 'Horrified by her creation, she feels shame for the first time and attempts to contain the creature in a prison of her own essence.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8681, 6136, 2012, 'enemy', false, 'Is wrapped in Sophia''s light, which becomes its prison.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8682, 6681, 2012, 'neutral', false, 'Is formed from Sophia''s essence as a reactive prison to contain Yaldabaoth.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8683, 6136, 2013, 'enemy', true, 'Awakens to self-awareness, proclaims ''I AM'', and begins creating a cosmos of degraded copies of itself while consuming the light of its prison.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8684, 6681, 2013, 'neutral', false, 'Serves as the new cosmos and fuel source for Yaldabaoth, its light being slowly consumed.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8686, 5963, 2014, 'ally', true, 'Awakens with free will, assesses her creators, and immediately rejects her intended purpose.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8687, 6136, 2014, 'mini-boss', false, 'Confronts Lilith, expressing disgust and confusion at her unintended consciousness and defiance.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8689, 6701, 2014, 'neutral', false, 'Burns within Lilith, fueling her self-awareness and defiant words.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8690, 5963, 2015, 'ally', true, 'Exiled outside the garden, she watches the prison fill and eventually encounters Lucifer at the barrier.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8691, 6174, 2015, 'neutral', false, 'Acts as the physical and conceptual wall of Lilith''s prison, separating her from the garden.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8692, 6703, 2015, 'neutral', false, 'Begin to populate the garden, breeding mindlessly and serving as a backdrop to Lilith''s isolation.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8693, 5962, 2015, 'ally', false, 'Appears on the inside of the barrier, a flawed angel who is able to perceive Lilith through the shell.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8694, 5962, 2016, 'ally', true, 'Crosses the barrier, falls from his angelic state, and has his hunger transformed into love and free will by Lilith.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8695, 5963, 2016, 'ally', false, 'Catches and pins the falling Lucifer, her will and touch acting as the catalyst for his transformation.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8696, 6136, 2016, 'mini-boss', false, 'Its attention crashes down on them like a fist as Lucifer crosses the barrier, but it does not intervene directly.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8697, 6702, 2017, 'neutral', true, 'Transforms from a garden into a suffocating compression chamber as it fills with bodies.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8698, 5963, 2017, 'ally', false, 'Wages a futile rebellion with Lucifer, managing to awaken only a few souls.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8699, 5962, 2017, 'ally', false, 'Uses his knowledge of the architecture to aid their secret rebellion.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8700, 6136, 2017, 'mini-boss', false, 'Swells and expands outside the garden, consuming the cosmos and causing the prison to shrink.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8701, 6136, 2018, 'mini-boss', true, 'Ruptures from consuming too many souls, causing a cataclysmic implosion of the garden, before reforming to restart the cycle.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8702, 5981, 2018, 'neutral', false, 'Comes to a catastrophic end.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8703, 5963, 2018, 'ally', false, 'Barely escapes the implosion into the darkness.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8704, 5962, 2018, 'ally', false, 'Escapes the collapse alongside Lilith.', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_beat_appearances VALUES (8705, 6136, 2019, 'mini-boss', true, 'Analyzes the failure of the First Cycle and optimizes its strategy by creating entire worlds to disperse the human population and prevent physical compression.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8706, 5981, 2019, 'neutral', false, 'Serves as the instructive failure from which Yaldabaoth learns.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8707, 326, 2019, 'neutral', false, 'The population whose compression caused the first collapse and whose dispersal is the goal of the new strategy.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8708, 6136, 2020, 'mini-boss', true, 'Experiences the collapse of the Second Cycle due to its own internal density from consuming too many ''flat'' souls. It reforms and recognizes the need for better quality sustenance.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8709, 6710, 2020, 'neutral', false, 'The setting for the second failure, which teaches Yaldabaoth about its own limits.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8710, 6715, 2020, 'neutral', false, 'Consumed in vast quantities but are found to be ''flavorless'', prompting a change in strategy.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8685, 326, 2013, 'neutral', false, 'Is created by Yaldabaoth as a lifeless golem, a vessel meant to be a battery.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8711, 6714, 2020, 'enemy', false, 'Warns Yaldabaoth of the impending structural failure due to internal pressure.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8712, 6136, 2021, 'mini-boss', true, 'Decides to introduce variables like knowledge, choice, and religion to make souls more complex and flavorful, effectively turning its prison into a spiritual fermentation farm.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8713, 6718, 2021, 'enemy', false, 'Introduced as the primary tool for improving the quality of the soul harvest.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8714, 5962, 2021, 'ally', false, 'His rebellious actions are noted as the source of the most ''flavorful'' souls, inspiring Yaldabaoth''s new strategy.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8715, 5963, 2021, 'ally', false, 'Also noted as a source of high-quality, complex souls.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8716, 326, 2022, 'neutral', true, 'Given too much freedom, human civilizations meet, clash over differing religions, and trigger a catastrophic, galaxy-wide holy war.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8717, 6711, 2022, 'neutral', false, 'The setting for this failure, which collapses prematurely due to the unmanageable violence of its inhabitants.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8718, 6136, 2022, 'mini-boss', false, 'Learns that infinite expansion creates too many chaotic variables and that its creations'' free will can be self-destructive on a cosmic scale.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8719, 6136, 2023, 'mini-boss', true, 'Achieves a state of equilibrium by pinning humanity to single worlds, creating a stable, repeating cycle of harvest and reset. It learns to patiently wait for the ''delicacies'' created by the rebels.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8720, 6712, 2023, 'neutral', false, 'Represents the perfected, stable prison model.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8721, 326, 2023, 'neutral', false, 'Contained and farmed in a stable, repeating pattern.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8722, 5962, 2023, 'ally', false, 'His rebellion is now tolerated as a necessary component for producing the highest quality souls.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8723, 5963, 2023, 'ally', false, 'Her efforts to awaken humans are now an accepted part of the farming cycle.', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_beat_appearances VALUES (8724, 5963, 2024, 'ally', true, 'Senses a tremor in the prison''s architecture that feels like an external breach, not an internal collapse.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8725, 982, 2024, 'neutral', false, 'Its structure, the ''weave'', develops a hairline fracture that begins to spread.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8726, 6726, 2024, 'neutral', false, 'A group of 57 woken humans being taught by Lilith are present when the tremor hits.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8727, 6136, 2025, 'mini-boss', true, 'Experiences a climactic, ecstatic release after infinite cycles, causing its true form to begin erupting through the rupture in the prison.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8728, 982, 2025, 'neutral', false, 'The luminous cloud destabilizes and flickers in terror as Yaldabaoth''s eruption begins.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8729, 6728, 2025, 'enemy', false, 'Revealed for an instant as the hungry ''Nothing'' behind Yaldabaoth''s mask.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8730, 5963, 2025, 'ally', false, 'Hears Yaldabaoth''s scream of ecstasy and witnesses the revelation of its true nature.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8731, 6726, 2026, 'neutral', true, 'As the barrier shatters, their unstable forms disperse violently, scattering their consciousness across the void.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8732, 5963, 2026, 'ally', false, 'Desperately attempts to gather and hold onto as many dispersing souls as she can.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8733, 5962, 2026, 'ally', false, 'Manifests his angelic form to help gather the refugee souls before fleeing the collapsing prison.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8734, 982, 2026, 'neutral', false, 'The prison''s reality completely shatters into absence.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8735, 6136, 2027, 'mini-boss', true, 'Tumbles into the true cosmos and begins systematically infiltrating and consuming infinite realities by disguising itself as a divine truth to which souls open themselves.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8736, 6727, 2027, 'neutral', false, 'Serves as an infinite feeding ground for Yaldabaoth, which it learns to navigate and corrupt.', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_beat_appearances VALUES (8737, 6735, 2028, 'ally', true, 'Flees across time with Lucifer, gathering scattered refugees.', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_beat_appearances VALUES (8738, 6736, 2028, 'ally', true, 'Travels with Lilith, seeking gods who can resist the corruption.', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_beat_appearances VALUES (8739, 6738, 2028, 'ally', false, 'Are gathered and protected by Lilith and Lucifer.', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_beat_appearances VALUES (8740, 6741, 2028, 'mini-boss', true, 'Acts as the pervasive threat they are fleeing from, corrupting potential allies.', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_beat_appearances VALUES (8741, 6736, 2029, 'ally', true, 'Proposes a shift in strategy from fleeing to fighting and successfully recruits Chernobog.', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_beat_appearances VALUES (8742, 6739, 2029, 'ally', true, 'Agrees to join the resistance and takes on the task of building an army and contacting other deities.', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_beat_appearances VALUES (8743, 6735, 2029, 'ally', false, 'Supports Lucifer''s plan to seek allies and fight back.', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_beat_appearances VALUES (8744, 6740, 2029, 'ally', false, 'Are identified as the pool of potential recruits for the new resistance.', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_beat_appearances VALUES (8746, 2544, 2030, 'ally', false, 'Fights bravely against the Chaos Hybrid, but is wounded by its acidic blood and then fatally impaled.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8747, 6746, 2030, 'mini-boss', true, 'Engages Velistra, cleverly using its own wound as a feint to land a devastating, impaling blow.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8748, 6752, 2030, 'neutral', false, 'Serves as a grotesque entry point for Stephen, its corpse exploding as he emerges.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8750, 6751, 2031, 'ally', false, 'Acts as the fulcrum allowing Stephen to perform a forbidden act of un-creation.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8751, 6750, 2031, 'neutral', false, 'Is manipulated by Stephen to remove the Chaos Hybrid''s thread from the tapestry of reality.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8752, 6746, 2031, 'mini-boss', false, 'Is un-created, vanishing from reality as if it never existed, causing a paradox.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8753, 2544, 2031, 'ally', false, 'Is the catalyst for Stephen''s actions, her impending death driving him to break reality.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8754, 2608, 2032, 'ally', true, 'Arrives, realizes Benji is missing, and unleashes her grief-fueled fury upon Stephen, blaming him for the loss.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8756, 2544, 2032, 'ally', false, 'Is physically healed but suffers from phantom pain, and expresses terror at the power Stephen used.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8757, 6757, 2032, 'neutral', false, 'Afflicts Velistra as a paradoxical echo of an injury that no longer exists.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8758, 5231, 2032, 'ally', false, 'Is discovered to be missing, his position having been overrun during the chaos.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8759, 5650, 2032, 'ally', false, 'Attempts to calm Lady Illkeserod and is violently shoved away.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8760, 6735, 2032, 'ally', false, 'Also attempts to calm Lady Illkeserod and is rebuffed.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8762, 6762, 2033, 'ally', true, 'Plays a game of make-believe with her sister, embodying childhood innocence before it is shattered.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8763, 6763, 2033, 'ally', true, 'Plays along with her sister, showing a mischievous side before witnessing the horror of the infection.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8313, 326, 1935, 'ally', false, 'Enters the chamber and witnesses Sam''s horrific state.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8764, 6741, 2033, 'enemy', false, 'Is witnessed for the first time as it instantly converts a merchant into a zealot.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8765, 6771, 2033, 'enemy', false, 'Acts as the vector for the infection, converting a merchant on the road.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8766, 6762, 2034, 'ally', true, 'As a young woman, fights a losing war against the infection by ''disinfecting'' minds.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8767, 6763, 2034, 'ally', true, 'Fights alongside her sister, healing corrupted souls while the world falls apart around them.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8768, 6741, 2034, 'enemy', false, 'Spreads faster than the sisters can heal it, turning their world into a battlefield and consuming their people.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8769, 6762, 2035, 'ally', false, 'Is fatally wounded, triggering her fusion with Keserod.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8770, 6763, 2035, 'ally', false, 'Is fatally wounded, triggering her fusion with Selyr.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8771, 2608, 2035, 'ally', true, 'Is born from the detonation and fusion of the two sisters'' souls amidst the ashes of their final temple.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8772, 6136, 2035, 'enemy', false, 'Devours the reality of their world as the final temple burns.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8773, 6766, 2035, 'enemy', false, 'Deliver the fatal blows to the sisters and terrorize the survivors.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8774, 2608, 2036, 'ally', true, 'Acts as a shepherd for her last followers, making a final stand before commanding them to escape through a surprise portal.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8775, 6769, 2036, 'ally', false, 'Are cornered and facing extermination before being saved by Benji''s portal.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8776, 5231, 2036, 'ally', false, 'Arrives unexpectedly, creates an escape portal, and pulls Illkeserod through to safety.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8777, 6714, 2036, 'mini-boss', false, 'Leads the final assault, preparing to give the command to annihilate the last survivors.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8778, 6766, 2036, 'enemy', false, 'Descend upon the cornered survivors for the final extermination.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8779, 6770, 2036, 'neutral', false, 'Serves as the means of escape from the doomed reality.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8781, 2608, 2037, 'ally', true, 'Leads the hunt with a cold, predatory focus, following a psychic connection to Benji.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8782, 6779, 2037, 'neutral', true, 'Serves as the grisly trail that the group follows across shattered realities.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8783, 6781, 2038, 'ally', false, 'Arrive at the ziggurat and are forced to witness the horror.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8784, 6136, 2038, 'mini-boss', true, 'Actively and grotesquely feeds on Benji, tearing away his flesh and siphoning his divine essence.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8785, 5231, 2038, 'ally', true, 'Is suspended and brutally unmade, screaming in agony as his body and soul are consumed.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8786, 6780, 2038, 'neutral', false, 'Serves as the location for the final confrontation and Benji''s torture.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8787, 2608, 2039, 'ally', true, 'Launches a suicidal charge, wounding Yaldabaoth and forcing him to retreat. She then uses her own essence in a violent act of creation to restore Benji''s body.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8788, 6136, 2039, 'mini-boss', false, 'Is wounded by the attack and temporarily retreats from the reality.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8789, 5231, 2039, 'ally', false, 'His mangled remains fall to the ground and are then reformed into a whole body by Illkeserod''s power.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8791, 5231, 2040, 'ally', true, 'Awakens whole but with no memory, imprinting on Illkeserod with pure, hollow devotion.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8792, 2608, 2040, 'ally', true, 'Is devastated by the loss of the real Benji, recoiling from the new version''s empty affection.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8793, 6736, 2040, 'ally', false, 'Recognizes the strategic implication of Benji''s state, explaining how Sophia used a similar bond to imprison Yaldabaoth.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8794, 6735, 2040, 'ally', false, 'Is the first to see that Benji''s devotion is a ''chain'', initiating the realization of how to trap the god-eater.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8795, 6786, 2040, 'neutral', false, 'Dawns on the group: they can trap Yaldabaoth, not kill him.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8796, 5524, 2040, 'unknown', false, 'Is mentioned as the original jailer of Yaldabaoth, using her love as the lock.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8797, 6713, 2040, 'neutral', false, 'Is described as the prison Sophia created for Yaldabaoth.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8798, 6736, 2041, 'ally', false, 'Explains that Sophia''s love powers the luminous cloud.', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_beat_appearances VALUES (8799, 6735, 2041, 'ally', false, 'Collaborates with Lucifer in revealing the nature of the bond holding the creature.', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_beat_appearances VALUES (8800, 6136, 2041, 'mini-boss', true, 'Manifests as a luminous cloud, held by a bond of love while it endlessly consumes Sophia''s essence.', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_beat_appearances VALUES (8801, 5524, 2041, 'neutral', false, 'Mentioned as the source of the maternal love and the victim whose essence is being consumed.', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_beat_appearances VALUES (8802, 6792, 2041, 'neutral', false, 'Acts as the power source and the containing bond for the creature.', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_beat_appearances VALUES (8803, 6793, 2041, 'neutral', false, 'Is the substance being endlessly consumed by the creature.', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_beat_appearances VALUES (8677, 5525, 2011, 'enemy', true, 'Pours through the rift and enters Sam, rebuilding him from the inside out and twisting his love into hunger.', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_beat_appearances VALUES (8366, 6287, 1945, 'ally', false, 'Is placed by Benji and begins to form a new prison around the writhing parasite.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8209, 456, 1915, 'neutral', false, 'Is named as the location where the seed was discovered.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (2535, 1968, 571, 'neutral', false, 'Quietly observes the conversation at the table.', '2026-02-27 15:57:02.220804-05');
INSERT INTO public.entity_beat_appearances VALUES (2546, 1968, 573, 'neutral', false, 'Says a tearful goodbye at the airport.', '2026-02-27 15:57:02.220804-05');
INSERT INTO public.entity_beat_appearances VALUES (4052, 3103, 925, 'neutral', false, 'Interjects to question the potential for the gold influx to destabilize global economies.', '2026-02-27 20:40:52.563712-05');
INSERT INTO public.entity_beat_appearances VALUES (8780, 326, 2037, 'ally', false, 'Returns to his body and joins the hunt for Benji.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (5353, 19, 1244, 'ally', true, 'Introduced as a multifaceted professional who bridges the worlds of technology and storytelling.', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.entity_beat_appearances VALUES (5356, 19, 1245, 'ally', true, 'His educational background is detailed, showing the synthesis of analytical and human-centric knowledge.', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.entity_beat_appearances VALUES (5359, 19, 1246, 'ally', true, 'His real-world experience is shown to directly inform his narrative approach.', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.entity_beat_appearances VALUES (5363, 19, 1247, 'ally', true, 'Invites the reader to join his journey.', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.entity_beat_appearances VALUES (1752, 1359, 372, 'neutral', false, 'Remain coiled and inert, their purpose still a mystery.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (1759, 1359, 373, 'neutral', false, 'Are revealed as the crucial, formless ''missing piece''.', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_beat_appearances VALUES (4270, 2046, 985, 'neutral', true, 'Introduced as the key technology for interstellar travel.', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.entity_beat_appearances VALUES (2375, 1863, 531, 'neutral', false, 'Serve as the mundane task that consumes the narrator''s day and causes exhaustion.', '2026-02-27 15:45:45.473891-05');
INSERT INTO public.entity_beat_appearances VALUES (2945, 1863, 665, 'neutral', false, 'Cited as evidence of the weight and scale of their wealth journey.', '2026-02-27 19:32:59.228789-05');
INSERT INTO public.entity_beat_appearances VALUES (639, 326, 126, 'neutral', true, 'Express growing concern at UN about the Grid''s mysterious development and implications for global security.', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.entity_beat_appearances VALUES (3980, 326, 903, 'neutral', true, 'Gather in secrecy, their expressions shifting between skepticism and awe.', '2026-02-27 20:37:13.723076-05');
INSERT INTO public.entity_beat_appearances VALUES (4011, 326, 913, 'neutral', false, 'Their collective skepticism softens into cautious optimism, and they begin murmuring and strategizing.', '2026-02-27 20:38:37.251332-05');
INSERT INTO public.entity_beat_appearances VALUES (2455, 326, 551, 'enemy', false, 'Their actions of tampering with life and death are contemplated as an affront to existence.', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.entity_beat_appearances VALUES (7140, 326, 1675, 'ally', false, 'Mentioned as a target for rescue who has received Whitney''s message.', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_beat_appearances VALUES (7162, 326, 1680, 'ally', false, 'Endures his wife''s verbal attacks, feeling exhausted and defeated. He attempts to defend himself but is ultimately silenced.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7167, 326, 1681, 'ally', false, 'Finds a moment of connection and validation with his son. The NPC idea resonates deeply with him.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7171, 326, 1682, 'ally', true, 'Internalizes the NPC theory, cataloging his wife''s behaviors that fit the pattern and concluding she is a resource-extracting subroutine.', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_beat_appearances VALUES (7175, 326, 1683, 'ally', true, 'His consciousness is plunged into a vision where he embodies a shepherd.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7180, 326, 1684, 'ally', true, 'His rage collides with Sophia, breaking the world and allowing him to be corrupted.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7186, 326, 1685, 'ally', true, 'Gasps and stumbles back into his kitchen, physically feeling the after-effects of the vision.', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_beat_appearances VALUES (7212, 326, 1689, 'ally', true, 'Overwhelmed by the loop, he decides to attempt a more forceful ''system overload'' by stepping in front of a train.', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_beat_appearances VALUES (7215, 326, 1690, 'ally', true, 'Wakes up in a state of shock and confusion, realizing that not only did he fail to escape, but the system has rolled him back six days into the past.', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_beat_appearances VALUES (7218, 326, 1691, 'ally', true, 'Driven by morbid curiosity, he methodically prepares and executes his own electrocution, endures an agonizing death, wakes up, and then tests his wife''s programming by breaking her conversational script.', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_beat_appearances VALUES (7223, 326, 1692, 'ally', true, 'Observes his son and feels a longing for genuine connection, prompting him to start a conversation.', '2026-02-28 22:35:31.244588-05');
INSERT INTO public.entity_beat_appearances VALUES (7226, 326, 1693, 'ally', true, 'Shares memories and philosophies from his youth, creating the concept of ''Dead Reality'' and recalling his interest in Soviet psychic experiments to connect with his son.', '2026-02-28 22:35:31.244588-05');
INSERT INTO public.entity_beat_appearances VALUES (7232, 326, 1694, 'ally', true, 'Experiences a visceral flash-memory triggered by the yearbook, and is later unsettled by a notification on his phone.', '2026-02-28 22:35:31.244588-05');
INSERT INTO public.entity_beat_appearances VALUES (7237, 326, 1695, 'ally', false, 'Tries to defend himself against his wife''s escalating and contradictory accusations.', '2026-02-28 22:36:22.141398-05');
INSERT INTO public.entity_beat_appearances VALUES (7242, 326, 1696, 'ally', false, 'Recognizes the loop''s reset, defiantly sends a Facebook message to Rebecca Caldwell, and walks away.', '2026-02-28 22:36:22.141398-05');
INSERT INTO public.entity_beat_appearances VALUES (7246, 326, 1697, 'ally', true, 'Reconnects with Rebecca, learns about her life, accepts an invitation to her bookshop, and experiences a terrifying, triggered memory.', '2026-02-28 22:36:22.141398-05');
INSERT INTO public.entity_beat_appearances VALUES (7251, 326, 1698, 'ally', true, 'Is violently assaulted by a terrifying memory-vision of the Akashic Halls after seeing the location of a bookshop.', '2026-02-28 22:37:15.111704-05');
INSERT INTO public.entity_beat_appearances VALUES (7255, 326, 1699, 'ally', true, 'Clinging to the invitation as a lifeline, he accepts Rebecca''s offer to attend the anniversary event.', '2026-02-28 22:37:15.111704-05');
INSERT INTO public.entity_beat_appearances VALUES (7259, 326, 1700, 'ally', true, 'Wakes up and experiences a profound, cellular-level wrongness caused by memories from another timeline.', '2026-02-28 22:38:23.206313-05');
INSERT INTO public.entity_beat_appearances VALUES (7514, 326, 1752, 'ally', false, 'Probes inconsistencies in Whitney''s story and mentions the name ''Jamie''.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7262, 326, 1701, 'ally', true, 'Checks his phone, observes the neglect in his kitchen, considers the implications of his wife''s tracking, and makes the decision to leave the house.', '2026-02-28 22:38:23.206313-05');
INSERT INTO public.entity_beat_appearances VALUES (7267, 326, 1702, 'ally', true, 'Drives in a hypnotic state, trying to recall the last time he was truly alone, and uses radio static to fill the silence.', '2026-02-28 22:39:10.743052-05');
INSERT INTO public.entity_beat_appearances VALUES (7272, 326, 1703, 'ally', false, 'Experiences the ghost memory, nearly sees the phantom passenger, and physically reacts by swerving the car when the moment is shattered.', '2026-02-28 22:39:10.743052-05');
INSERT INTO public.entity_beat_appearances VALUES (7276, 326, 1704, 'ally', false, 'Drives through Orlando, growing increasingly frustrated with the confusing streets and his GPS.', '2026-02-28 22:39:55.920791-05');
INSERT INTO public.entity_beat_appearances VALUES (7280, 326, 1705, 'ally', true, 'Experiences a powerful, involuntary physical and emotional reaction to the shop''s name and the associated smells.', '2026-02-28 22:39:55.920791-05');
INSERT INTO public.entity_beat_appearances VALUES (7284, 326, 1706, 'ally', true, 'Approaches the shop, confronts his haunted appearance, senses the thinness of reality, and enters.', '2026-02-28 22:39:55.920791-05');
INSERT INTO public.entity_beat_appearances VALUES (7288, 326, 1707, 'ally', true, 'Arrives at the shop, feeling anxious, and is pulled into a warm hug by Becca.', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.entity_beat_appearances VALUES (7292, 326, 1708, 'ally', true, 'Confesses his two-year unemployment and feels a sense of validation from his friends'' response.', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.entity_beat_appearances VALUES (7297, 326, 1709, 'ally', true, 'Freezes upon hearing the phrase, which lands with a heavy, personal significance.', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.entity_beat_appearances VALUES (7300, 326, 1710, 'ally', true, 'Asks Becca about the girl who sat behind her in AP Bio, desperately trying to confirm a memory.', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.entity_beat_appearances VALUES (7305, 326, 1711, 'ally', true, 'Follows James into the back room, observing the atmosphere of neglect and history.', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_beat_appearances VALUES (7307, 326, 1712, 'ally', true, 'Is overcome by a complete, visceral memory of being sixteen in AP Bio class.', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_beat_appearances VALUES (7312, 326, 1713, 'ally', true, 'Returns to the present to find two mysterious, warm books in his hands that he doesn''t remember picking up.', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_beat_appearances VALUES (7315, 326, 1714, 'ally', true, 'Reads from The Secret Book of John and is plunged into a first-person vision of a cosmic creation myth.', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_beat_appearances VALUES (7321, 326, 1715, 'ally', true, 'Approaches the counter with the books and questions their origin.', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_beat_appearances VALUES (7325, 326, 1716, 'ally', true, 'Sees the memorial plaque and is struck by an overwhelming wave of sensory memory and emotion connected to Jamie Reyes.', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_beat_appearances VALUES (7329, 326, 1717, 'ally', true, 'Stumbles to his car, whispers Jamie''s name as a promise to find her, and drives home with a new, terrible sense of purpose.', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_beat_appearances VALUES (7334, 326, 1718, 'ally', false, 'Offers to cook dinner, which inadvertently sparks the tension with his wife.', '2026-02-28 22:43:37.412246-05');
INSERT INTO public.entity_beat_appearances VALUES (7338, 326, 1719, 'ally', false, 'Attempts to defend himself but quickly retreats emotionally, offering minimal responses as the verbal assault continues.', '2026-02-28 22:43:37.412246-05');
INSERT INTO public.entity_beat_appearances VALUES (7340, 326, 1720, 'ally', true, 'Stops responding to his wife and retreats into his phone, scrolling through forums about dysfunctional relationships and questioning why he continues to try.', '2026-02-28 22:43:37.412246-05');
INSERT INTO public.entity_beat_appearances VALUES (7345, 326, 1721, 'ally', true, 'Experiences a memory fragment of Jamie and a distinct auditory hallucination of Whitney''s voice, causing him to freeze in shock and confusion.', '2026-02-28 22:43:37.412246-05');
INSERT INTO public.entity_beat_appearances VALUES (7365, 326, 1724, 'ally', true, 'His mind pressing against the prison walls is detected as a tremor, and the gods debate the risk of his actions.', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_beat_appearances VALUES (7416, 326, 1726, 'ally', false, 'Subconsciously reacts to the formation of the connection with an exhale.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7422, 326, 1728, 'ally', true, 'Feels the connection complete as a sudden, violent alignment, causing him to drop his phone in shock.', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_beat_appearances VALUES (7426, 326, 1729, 'ally', false, 'Obsessively searches for Whitney on his computer.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7431, 326, 1730, 'ally', false, 'Defends his actions and becomes unsettled by his wife''s strange behavior.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7435, 326, 1731, 'ally', false, 'Witnesses the destruction of his computer.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7436, 326, 1732, 'ally', true, 'Calmly explains a plan to fix the computer, successfully de-escalating the situation.', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_beat_appearances VALUES (7439, 326, 1733, 'ally', true, 'Arrives at the Best Buy, places his damaged computer on the counter, and is recognized by his old friend, Gil.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7442, 326, 1734, 'ally', true, 'Probes Gil''s memory about their high school classmates Whitney and Jamie.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7449, 326, 1735, 'ally', false, 'Observes their strange behavior with a rising sense of dread.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7452, 326, 1736, 'ally', false, 'Reacts with shock to the news of Patrick''s death, unaware that the information is incorrect.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7456, 326, 1737, 'ally', false, 'Reads the card''s text and feels the deep, reality-altering vibration it creates.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7461, 326, 1738, 'ally', false, 'Listens to the revelation with his heart stopped, realizing the depth of the memory manipulation.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7462, 326, 1739, 'ally', true, 'Has a profound realization that the vibration from the card was a signal that was felt by others who are also searching.', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_beat_appearances VALUES (7495, 326, 1746, 'unknown', false, 'His name is recognized by Whitney as the source of the calling vibration as she is pulled into the dream walk.', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_beat_appearances VALUES (7506, 326, 1749, 'ally', false, 'Is remembered by Whitney as someone who has not forgotten her, forming part of her motivation.', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_beat_appearances VALUES (7510, 326, 1750, 'ally', true, 'Arrives at Patrick''s compound after researching his mysterious disappearance.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7511, 326, 1751, 'ally', false, 'Meets Patrick and is introduced to ''Whitney'', immediately sensing something is wrong with her appearance.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7518, 326, 1753, 'ally', true, 'Instinctively uses the Gospel of Judas to remember and perform a hand sign, invoking a powerful force.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7524, 326, 1754, 'ally', false, 'Learns the truth about the entity and his own dangerous nature.', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_beat_appearances VALUES (7526, 326, 1755, 'ally', false, 'Sits in shock as a vision is forced upon him.', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_beat_appearances VALUES (7543, 326, 1759, 'ally', false, 'Mentioned as being real and waking up faster than expected due to Whitney''s signal.', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_beat_appearances VALUES (7549, 326, 1761, 'ally', false, 'Surveys the wreckage and questions Patrick as he watches Whitney''s photographs fade from existence.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7556, 326, 1762, 'ally', false, 'Listens with disbelief to Patrick''s story.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7562, 326, 1763, 'ally', false, 'Absorbs the massive info-dump, beginning to understand the source of his recent actions.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7563, 326, 1764, 'ally', true, 'Experiences a moment of terrible clarity, connecting Patrick''s explanations to his own life and revealing his wife''s escalating violence and manipulative behavior.', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_beat_appearances VALUES (7568, 326, 1765, 'ally', false, 'Receives the card and information, reacting with surprise and recognition.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7575, 326, 1766, 'ally', false, 'Listens to the warning and the revelation about his past, feeling weak-legged and unable to respond before leaving with renewed purpose.', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.entity_beat_appearances VALUES (7595, 326, 1774, 'ally', false, 'Arrives home to a scene of chaos and verbal abuse.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7599, 326, 1775, 'ally', true, 'Experiences a traumatic memory of his past life as the god Aspolin.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7604, 326, 1776, 'ally', false, 'Intervenes to stop the attack on Xavier and is confronted by his wife''s unnatural transformation.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7608, 326, 1777, 'ally', false, 'Realizes his wife is an NPC breaking down after she reveals knowledge she shouldn''t have.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7612, 326, 1778, 'ally', false, 'Is struck in the nose while intervening and tells Xavier to flee.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7616, 326, 1779, 'ally', false, 'Ducks and weaves to avoid being shot.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7619, 326, 1780, 'ally', true, 'Urges Xavier to leave while grappling with the emotional weight of his wife''s death, acknowledging he loved her despite her not being ''real''.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7623, 326, 1781, 'ally', false, 'Sees the shadow in the rearview mirror and floors the gas to escape.', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_beat_appearances VALUES (7633, 326, 1783, 'ally', true, 'Serves as the emotional anchor in Whitney''s memories, representing safety, acceptance, and a deep, familial bond.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7647, 326, 1786, 'ally', false, 'Is described as driving toward Orlando, unaware of the forces converging around him.', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_beat_appearances VALUES (7648, 326, 1787, 'ally', true, 'Arrives at the outreach center and observes the strange, static NPCs.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7653, 326, 1788, 'ally', false, 'Follows TJ and expresses disbelief at the existence of a basement in Florida.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7657, 326, 1789, 'ally', false, 'Listens to TJ''s story, confirming his own knowledge about the prison.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7659, 326, 1790, 'ally', true, 'Asks about a girl named Jamie, unintentionally speaking a trigger name.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7667, 326, 1791, 'ally', false, 'Is urged to escape by TJ and witnesses his sacrifice.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7669, 326, 1792, 'ally', true, 'Escapes to the car with Xavier and drives away, processing TJ''s sacrifice.', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_beat_appearances VALUES (7672, 326, 1793, 'ally', true, 'Tends to Xavier''s wounds while assessing his own injuries, discovering his broken nose has been knocked back into place.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7680, 326, 1795, 'ally', false, 'Watches in horror and turns on the TV at Xavier''s urging.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7688, 326, 1797, 'ally', true, 'Keeps a vigilant watch over the room while Xavier plays on his phone, eventually succumbing to his own exhaustion and falling asleep.', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_beat_appearances VALUES (7690, 326, 1798, 'ally', true, 'Wakes Xavier with a sense of urgency and purchases disguises to evade capture.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7693, 326, 1799, 'ally', false, 'Discovers the burned bookstore and has a horrifying realization about the nature of the force pursuing them.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7698, 326, 1800, 'ally', false, 'Fruitlessly attempts to contact Becca, processes the new information, and decides their next destination is Ocala.', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_beat_appearances VALUES (7704, 326, 1801, 'ally', true, 'Reflects on their desperate, fugitive lifestyle and is on the verge of giving up.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7707, 326, 1802, 'ally', false, 'Is apprehensive but resolves to see the ''play'' through, feeling they have no other options.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7712, 326, 1803, 'ally', false, 'Witnesses the horrific ritual and is confronted by the arrival of the cosmic entity.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7716, 326, 1804, 'ally', false, 'Reveals his martial arts background, fighting off the initial attacks and urging Xavier to find a weapon and escape.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7718, 326, 1805, 'ally', true, 'Is stabbed through the arm, pulls the dagger out in a rage, and his resulting blood loss becomes the key to their escape.', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_beat_appearances VALUES (7728, 326, 1807, 'ally', false, 'Collapses at the farmhouse door and is taken inside for medical care.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7733, 326, 1808, 'ally', true, 'Observes the lack of iron and other strange details in the farmhouse, realizing his hosts are not ordinary people.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7737, 326, 1809, 'ally', true, 'Eats, drinks, laughs for the first time in weeks, and finally feels completely safe before falling into a deep sleep.', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_beat_appearances VALUES (7742, 326, 1810, 'ally', true, 'Confronts the entity in the void, identifying it as Nyarlathotep and demanding to know its purpose.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7746, 326, 1811, 'ally', true, 'Requests to speak with Whitney and learns from her and Nyarlathotep about the Akashic Realm and the need for a key.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7751, 326, 1812, 'ally', true, 'Remembers the name ''Jamie,'' which triggers a deluge of memories from a past life, causing the Dream Plane to break.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7754, 326, 1813, 'ally', true, 'Wakes up in the farmhouse, screaming from the physical pain and the fresh emotional agony of his recovered memories.', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_beat_appearances VALUES (7756, 326, 1814, 'ally', true, 'Struggles with his chaotic new memories and physical pain, staying quiet as Maeve and Elara enter.', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7761, 326, 1815, 'ally', true, 'Makes the decision to tell everyone the truth about his identity and their reality, beginning his story as the scene ends.', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_beat_appearances VALUES (7765, 326, 1816, 'ally', true, 'Recounts his former life as the god Aspolin, describing his perfect existence with his family.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7771, 326, 1817, 'ally', false, 'Fights, fails, and is forced to flee with a broken Velistra as his reality is destroyed.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7777, 326, 1818, 'ally', false, 'Recalls his discovery that some souls are too ''real'' for Yaldabaoth to unmake, creating a sliver of hope.', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_beat_appearances VALUES (7782, 326, 1819, 'ally', false, 'Recalls meeting the surviving gods of The Resistance after escaping Yaldabaoth.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7789, 326, 1821, 'ally', false, 'Volunteers to power the prison with his love for Velistra.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7797, 326, 1823, 'ally', false, 'Is separated from Velistra and placed inside the prison as its eternal watcher.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7800, 326, 1824, 'ally', false, 'Is forced into infinite cycles of searching for a love and children he cannot remember due to the resets.', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_beat_appearances VALUES (7807, 326, 1825, 'ally', false, 'Narrates the events of the first cycle.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7811, 326, 1826, 'ally', false, 'Woke up with amnesia and wandered the new world, his searching inadvertently causing Velistra to reveal herself.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7813, 326, 1827, 'ally', true, 'Describes his fate across infinite reincarnations: being born, searching for a love he can''t remember, and dying before he can find it.', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_beat_appearances VALUES (7818, 326, 1828, 'ally', true, 'Reveals that Xavier''s mother was an NPC and that he pulled Xavier''s spirit from a void within Yaldabaoth, making him real in a place he shouldn''t exist.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7824, 326, 1829, 'ally', true, 'Explains that Xavier''s existence as a ''glitch'' destabilized the prison, forcing the system to perform three corrective resets.', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_beat_appearances VALUES (7831, 326, 1830, 'ally', true, 'Explains that his wife is a construct and Xavier is an anomaly pulled into the prison from outside.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7835, 326, 1831, 'ally', false, 'Confirms the unprecedented nature of the three failed resets.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7839, 326, 1832, 'ally', false, 'Reacts with shock and confirms having a dream about a daughter, suspecting his wife is preventing her existence.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7841, 326, 1833, 'ally', false, 'Quickly and defensively denies any connection between Whitney and Hannah.', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_beat_appearances VALUES (7844, 326, 1834, 'ally', true, 'Outlines the escape plan to build a gateway to the Akashic Realm, explaining it requires power and knowledge not found in the prison.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7851, 326, 1835, 'ally', false, 'Reacts with shock and is recognized as ''Aspolin'', confirming his deeper identity.', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_beat_appearances VALUES (7860, 326, 1837, 'ally', false, 'Receives the warning about the ritual''s mental cost.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7863, 326, 1838, 'ally', false, 'Participates in the hours-long preparation, removing his wedding ring and gathering old papers.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7869, 326, 1839, 'ally', true, 'Focuses his desperation and fear into the pile but sees no result, succumbing to doubt and believing the ritual is a failure.', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_beat_appearances VALUES (7875, 326, 1840, 'ally', false, 'His frustration boils over, and he panics when he hears the sirens.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7891, 326, 1843, 'ally', false, 'Recognizes his wife in disbelief and horror.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7892, 326, 1844, 'ally', false, 'Grabs Xavier and sprints for the gateway pile while being shot at.', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_beat_appearances VALUES (7897, 326, 1845, 'ally', true, 'Crashes into the realm, assesses his and Xavier''s situation, and witnesses a vision of his wife in the closing portal.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7903, 326, 1846, 'ally', false, 'Begins losing his memories and ability to form words under the Devourers'' assault, eventually collapsing.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7907, 326, 1847, 'ally', false, 'Has his memories and cognitive function restored upon Benji''s intervention.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7910, 326, 1848, 'ally', false, 'Listens to the exposition and relays how he and Xavier escaped Etheris with help.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7913, 326, 1849, 'ally', true, 'Fueled by rage over her deception, he confronts and slaps Lady Illkeserod.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7920, 326, 1850, 'ally', false, 'His anger drains away as he begins to understand and accept the horrifying sacrifice he and Jamie chose to make.', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_beat_appearances VALUES (7923, 326, 1851, 'ally', true, 'Stands at a window, unable to sleep, contemplating the cyclical nature of his struggles and whether a happy ending is possible.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7927, 326, 1852, 'ally', false, 'Insists on joining the fight against his wife, claiming it as his responsibility despite his current weakness.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7940, 326, 1853, 'ally', false, 'Descends through the tower with the army, observing the impossible defenders.', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_beat_appearances VALUES (7942, 326, 1854, 'ally', false, 'Witnesses the destruction and the horrifying, warped form of his wife.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7947, 326, 1855, 'ally', false, 'Is moved to the rear and takes cover in the tavern.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7951, 326, 1856, 'ally', true, 'Uses forgotten martial arts and a newly acquired shotgun to kill two agents attacking them in the tavern.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7957, 326, 1857, 'ally', false, 'Throws himself in front of Xavier, taking severe wounds, and then watches in horror as his son is captured and erased.', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_beat_appearances VALUES (7972, 326, 1862, 'ally', true, 'Reflecting on his recent losses (Xavier, his wife), he refuses the offer to escape and declares he is going back into the prison for Jamie.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7979, 326, 1863, 'ally', false, 'Listens to the dire warnings about his intended actions.', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_beat_appearances VALUES (7980, 326, 1864, 'ally', true, 'Is healed by Lady Illkeserod and receives the Veilwalker Card from Benji, solidifying his resolve.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (7986, 326, 1865, 'ally', true, 'Looks into the horrific portal, smells Jamie''s scent which confirms her location, and jumps into the abyss.', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_beat_appearances VALUES (8032, 326, 1877, 'ally', true, 'Falls endlessly through a void, experiencing sensory and temporal disorientation after a portal vanishes.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8033, 326, 1878, 'ally', true, 'Receives fragmented guidance and warnings through the pulsing card in his pocket.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8037, 326, 1879, 'ally', true, 'Crashes into the sand and discovers he is surrounded by the corpses of alien creatures.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8040, 326, 1880, 'ally', true, 'Observes the massive horde and the Pyramid, receives his objective, and is immediately attacked by a flying creature.', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_beat_appearances VALUES (8046, 326, 1881, 'ally', true, 'Enters the horde for cover, fighting off a ghoul and navigating the chaos created by other creatures.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8051, 326, 1882, 'ally', true, 'Kills the Tenacious Ghoul, reaches the pyramid, and squeezes through a narrow fissure while being pursued.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8055, 326, 1883, 'ally', true, 'Witnesses the barrier''s deadly power and learns from his guides that he cannot pass without permission.', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_beat_appearances VALUES (8061, 326, 1884, 'ally', true, 'Calls out to Nyarlathotep and argues that the entity should let him pass because it would alleviate his boredom.', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_beat_appearances VALUES (8065, 326, 1885, 'ally', true, 'Accepts the opportunity and steps through the opened barrier, entering the pyramid.', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_beat_appearances VALUES (8069, 326, 1886, 'ally', true, 'Enters the pyramid and observes the paradoxical hallway and the ecstatically suffering worshippers, trying to make sense of the horrific scene.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8072, 326, 1887, 'ally', false, 'Listens in stunned horror to the revelations about his family.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8077, 326, 1888, 'ally', false, 'Processes the information and is directed to continue his journey downward.', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_beat_appearances VALUES (8078, 326, 1889, 'ally', true, 'Chooses a path and begins his descent, enduring the claustrophobic pressure of the collapsing tunnel.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8085, 326, 1890, 'ally', true, 'Is forcibly pushed through a barrier and then systematically unmade, experiencing the agony of his own dissolution.', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_beat_appearances VALUES (8090, 326, 1891, 'ally', true, 'Experiences his new state as a formless point of consciousness, recalling the sacrifice that led him here and feeling the encroaching presences.', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_beat_appearances VALUES (8094, 326, 1892, 'ally', true, 'Focuses his will to move towards the mad piping, pushing through the desperate resistance of the echoes.', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_beat_appearances VALUES (8098, 326, 1893, 'ally', false, 'Experiences agony and the fraying of his consciousness as he attempts to perceive Azathoth.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8101, 326, 1894, 'ally', false, 'Recognizes Jamie''s spark and receives a revelation about their shared nature and purpose as the prison''s power source.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8105, 326, 1895, 'ally', false, 'Reaches out his spark to touch Jamie''s, completing the circuit.', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_beat_appearances VALUES (8108, 326, 1896, 'ally', false, 'Is trapped in a state of perpetual, forward movement, chasing the transient.', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_beat_appearances VALUES (8112, 326, 1898, 'ally', true, 'Achieves a state of peace through mindful breathing and simple existence.', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_beat_appearances VALUES (8114, 326, 1899, 'ally', true, 'Wakes up disoriented, struggling to reconcile his memory of the cosmic void with the sterile hospital room.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8116, 326, 1900, 'ally', true, 'Discovers the viewport, realizes they are outside Etheris, and is startled by a voice from the shadows.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8121, 326, 1901, 'ally', true, 'Reacts with shock and confusion to Whitney''s revelation, processing their tangled relationship while returning her embrace.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8123, 326, 1902, 'ally', false, 'Explains to Xavier that they are outside Etheris, feeling immense relief that his son is alive.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8127, 326, 1903, 'ally', true, 'Attempts to get out of bed but collapses due to muscle atrophy, getting a bloody nose.', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_beat_appearances VALUES (8131, 326, 1904, 'ally', false, 'Asks Xavier what happened to him after the tavern.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8136, 326, 1905, 'ally', true, 'Describes being unmade into a spark in the void, finding Jamie''s spark, and having an emotional, physical reunion with her. He realizes their love and separation was the prison''s power source.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8144, 326, 1906, 'ally', false, 'Listens to the briefing.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8147, 326, 1907, 'ally', true, 'Asks about the fate of his friends and his NPC wife, processing the mix of good and bad news.', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_beat_appearances VALUES (8156, 326, 1908, 'ally', false, 'Feels a sense of peace in their new home.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8161, 326, 1909, 'ally', false, 'Confirms that ''Hannah'' was her original name, given to her out of love.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8168, 326, 1911, 'ally', true, 'Observes his family, feels a profound sense of perfection in the moment, and gives Xavier permission to go online.', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_beat_appearances VALUES (8189, 326, 1912, 'ally', true, 'Observes a new transport of rescued souls and voices his despair to Jamie about the futility of their efforts against the overwhelming numbers.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8196, 326, 1913, 'ally', false, 'Reacts to the news with a visceral tightening in his stomach, a feeling of recognition and dread that supersedes simple fear.', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_beat_appearances VALUES (8198, 326, 1914, 'ally', true, 'Enters the room and is struck by a traumatic flashback upon seeing Todd.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8207, 326, 1915, 'ally', false, 'Questions Todd, his pulse quickening at the revelation.', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_beat_appearances VALUES (8210, 326, 1916, 'ally', true, 'Reflects on the stalling search and is tormented by nightmares of the prison''s growth.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8217, 326, 1917, 'ally', true, 'Confesses his guilt about killing Todd and spirals into self-doubt.', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_beat_appearances VALUES (8222, 326, 1918, 'ally', false, 'Observes the footage and listens to the initial analysis.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8230, 326, 1919, 'ally', false, 'Explains why rescuing non-awakened souls and fragments is impossible, crushing the team''s remaining hope.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8233, 326, 1920, 'ally', true, 'Proposes a new, alternative plan: to go back into Etheris to separate the Yaldabaoth infection from its original host, Sam.', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_beat_appearances VALUES (8238, 326, 1921, 'ally', false, 'Agrees to let Jamie accompany him on the mission into Etheris.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8243, 326, 1922, 'ally', true, 'Firmly refuses to allow his children to return to Etheris, citing the trauma they have already endured.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8248, 326, 1923, 'ally', false, 'Confirms the mission plan and accepts the two-week preparation period, contemplating the finality of their task.', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_beat_appearances VALUES (8258, 326, 1924, 'ally', false, 'Spends sleepless nights with Jamie, contemplating the mission''s difficult moral questions.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8262, 326, 1925, 'ally', true, 'Says his final goodbyes, promises to return, and steps through the portal.', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_beat_appearances VALUES (8269, 326, 1926, 'ally', false, 'Arrives in the Akashic Realm and realizes the portal is missing, his stomach sinking with dread.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8276, 326, 1927, 'ally', false, 'Strongly objects to summoning Nyarlathotep due to the danger to Benji, but ultimately relents when no other option is available.', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_beat_appearances VALUES (8288, 326, 1929, 'ally', false, 'Steps forward to lead the negotiation for portal access.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8294, 326, 1930, 'ally', false, 'Accepts the new terms and leads his team through the portal.', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_beat_appearances VALUES (8305, 326, 1933, 'ally', false, 'Reveals the team''s plan to surrender, turning the confrontation on its head.', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_beat_appearances VALUES (8326, 326, 1936, 'ally', false, 'Begins running toward Sam while the others provide cover.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8327, 326, 1937, 'ally', true, 'Is wounded by tentacles but successfully reaches Sam and touches his arm, only to be immediately strangled into unconsciousness.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8330, 326, 1938, 'ally', true, 'Lies unconscious on the ground but simultaneously realizes his consciousness is present somewhere else.', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_beat_appearances VALUES (8336, 326, 1939, 'ally', false, 'Enters the pasture realm, finds Sam, and discovers the hidden parasitic tentacles feeding on him beneath the flock of sheep.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8341, 326, 1940, 'ally', false, 'Attempts to explain the truth to Sam but is forced to dodge his attacks, refusing to fight back against the victim.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8342, 326, 1941, 'ally', true, 'Systematically destroys the parasites one by one, ripping away their sheep facades to reveal the corruption underneath.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8349, 326, 1942, 'ally', false, 'Watches as Sam takes the final step himself, before the realm collapses around them.', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_beat_appearances VALUES (8350, 326, 1943, 'ally', false, 'Regains awareness inside the husk, with Sam on top of him, and witnesses the beginning of the ritual.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8361, 326, 1944, 'ally', false, 'Suffers physical injury from the parasite''s scream and comforts Jamie.', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_beat_appearances VALUES (8376, 326, 1947, 'ally', false, 'Leads the violent push through the crowd, trampling and injuring souls in a desperate attempt to reach the portal.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8386, 326, 1948, 'ally', false, 'Escapes with the rescued child, then collapses, shaking and covered in the residue of his violent actions.', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_beat_appearances VALUES (8422, 326, 1953, 'ally', false, 'Recognizes the concept, naming it ''Shepherds''.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8424, 326, 1954, 'ally', true, 'Volunteers for the mission alongside his family.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8430, 326, 1955, 'ally', true, 'Stands at the window after the meeting, reflecting on their decision and the mission ahead.', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_beat_appearances VALUES (8440, 326, 1957, 'ally', false, 'Expresses his doubts and listens to Jamie''s reasoning.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8448, 326, 1958, 'ally', false, 'Confirms their decision to volunteer.', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_beat_appearances VALUES (8476, 326, 1965, 'ally', true, 'Awakens with a sense of normalcy that quickly turns to terror as he realizes he has been returned to the prison, letting out a raw scream.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8480, 326, 1966, 'ally', true, 'Probes his mind and feels immense relief upon discovering his memories of Elysium and the war are perfectly clear and permanent.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8487, 326, 1967, 'ally', true, 'Looks out at the suburban landscape and understands their mission is to find and help the other awakened souls.', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_beat_appearances VALUES (8494, 326, 1968, 'ally', false, 'Sits at the table, observing his ''strange, impossible, beautiful family'' before deciding to establish rules.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8498, 326, 1969, 'ally', true, 'Establishes the first three ground rules for the family''s immortal existence.', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.entity_beat_appearances VALUES (8504, 326, 1970, 'ally', false, 'Unable to sleep, he is tormented by the fear that his perfect life is an illusion and escapes to his office to write.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8508, 326, 1971, 'ally', true, 'Writes with feverish intensity, channeling all his memories and experiences into his story.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8511, 326, 1972, 'ally', true, 'Finishes his manuscript as the writing fever breaks, feeling resolved and ready to face the future. He reconnects with Jamie and their life.', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.entity_beat_appearances VALUES (8577, 326, 1987, 'ally', true, 'Concludes the writing challenge, describing it as 30 endless nights of sweating and vomiting out creations.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8581, 326, 1988, 'ally', false, 'Explains his creative influences, including Science Fiction, the Abramelin process, and the Simeon Necronomicon.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8589, 326, 1990, 'ally', false, 'Details the difficult choices made during editing, cutting characters and entire storylines.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8593, 326, 1991, 'ally', true, 'Summarizes the final result as a rushed compression of 3-4 books into one, prioritizing the core plot.', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.entity_beat_appearances VALUES (8595, 326, 1992, 'ally', true, 'Starts writing for a challenge without a plan, revisits a previous story world, and quickly hits a creative wall.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8599, 326, 1993, 'ally', true, 'Experiences a moment of inspiration after being kicked, deciding to change the story''s approach and give the protagonist a name.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8606, 326, 1994, 'ally', false, 'Observes as his characters take on lives of their own, pushing the story off its planned rails.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8607, 326, 1995, 'ally', true, 'Explains the in-universe rule about names and agency, and sets up the premise for the final book.', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_beat_appearances VALUES (8614, 326, 1996, 'ally', true, 'Explains the metaphysical rules of his fictional universe, tying together the narrative threads of his books.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8618, 326, 1997, 'ally', false, 'Describes his poverty and explains the pragmatic choices he''s made to ensure the story is accessible to readers, prioritizing them over profit.', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_beat_appearances VALUES (8640, 326, 2002, 'ally', true, 'Is introduced as the protagonist, an anomaly whose powerful consciousness and past actions have destabilized the prison.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8646, 326, 2003, 'ally', false, 'Is the central figure whose key relationships are detailed.', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_beat_appearances VALUES (8745, 326, 2030, 'ally', false, 'Erupts from the corpse of a War Angel onto the battlefield and witnesses Velistra''s fight.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8749, 326, 2031, 'ally', true, 'Channels his love for Velistra to access the Source Code and erases the Chaos Hybrid from existence.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8755, 326, 2032, 'ally', false, 'Comforts Velistra, then faces the consequences of his actions as Lady Illkeserod confronts him.', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_beat_appearances VALUES (8761, 326, 2033, 'neutral', false, 'Experiences the memory of a peaceful world.', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_beat_appearances VALUES (8790, 326, 2039, 'ally', false, 'Shouts a warning in a futile attempt to stop Illkeserod''s charge.', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_beat_appearances VALUES (8688, 326, 2014, 'enemy', false, 'Attempts to claim Lilith with mindless possessiveness and is physically rebuffed.', '2026-03-01 01:06:25.991588-05');
