INSERT INTO public.entity_beat_appearances VALUES (5656, 4338, 1317, 'enemy', false, 'Are the primary topic of conversation, a shared supernatural trauma between Stephen and Whitney.', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.entity_beat_appearances VALUES (5680, 4338, 1324, 'enemy', true, 'Are understood not as random flashes, but as the bleed-through from the deaths of his alternate selves.', '2026-02-28 18:25:31.010103-05');
