INSERT INTO public.entity_scene_appearances VALUES (1256, 1286, 96, 'ally', true, NULL, 'Experiences a shift from guilt and stress over the family''s finances to decisive action, then to alarm at the power they''ve unleashed, and finally to relieved but cautious satisfaction.', NULL, NULL, NULL, 'Husband to The Wife and father to The Son. He is the technical mind behind the Infinitron and proposes the bitcoin mining solution.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1257, 948, 96, 'ally', true, NULL, 'Moves from being darkened and worried by the financial news to skeptical of the bitcoin plan, then alarmed by the consequences, and finally to pragmatic relief, insisting on future secrecy.', NULL, NULL, NULL, 'Wife of The Narrator and mother of The Son. She acts as the voice of reason and grounds the family in their real-world problems.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1258, 831, 96, 'ally', true, NULL, 'His initial idealism about changing the world gives way to awe at the Infinitron''s power, followed by a dawning understanding of the serious consequences and the gravity of their situation.', NULL, NULL, NULL, 'Son of The Narrator and The Wife. He represents the idealistic and curious perspective of the family.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1259, 1201, 96, 'neutral', true, 'Its purpose is pivoted from world-changing projects to cryptocurrency mining, revealing a level of computational power so immense it threatens to destabilize a global network.', NULL, 'Temporarily connected to a bitcoin mining pool and configured for hashing operations.', NULL, NULL, 'The family''s powerful computational device, used to solve their financial crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1260, 1290, 96, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist of the scene, which the family must overcome.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1261, 1291, 96, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The target of the Infinitron''s mining operation and the source of the family''s sudden wealth.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1262, 1292, 96, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The unintended, dangerous consequence of the Infinitron''s overwhelming power being applied to the Bitcoin network.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1263, 1293, 96, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The primary lesson learned from the bitcoin mining incident.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1264, 1294, 96, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.entity_scene_appearances VALUES (1265, 743, 97, 'ally', true, NULL, 'Cycles from frustration over the Eternal Engine''s limitations to excitement about using the Infinitron, then back to frustration due to lack of resources, before settling on determined optimism for a small-scale experiment.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:53:45.224779-05', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_scene_appearances VALUES (1266, 472, 97, 'ally', true, NULL, 'Acts as a pragmatic and skeptical counterpoint. She is initially unimpressed, then amazed by the Infinitron''s results, but quickly becomes resigned to their financial limitations before expressing deadpan skepticism about another experiment.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:53:45.224779-05', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.entity_scene_appearances VALUES (1267, 295, 97, 'neutral', true, 'Described as humming quietly in the corner, its infinite power is a source of frustration due to the characters'' inability to control or utilize it effectively.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:53:45.224779-05', '2026-02-27 14:53:45.224779-05');
