INSERT INTO public.entity_scene_appearances VALUES (354, 278, 23, 'ally', true, 'Exhausted IT troubleshooter forced to resolve catastrophic server failure at 4:44 a.m.; discovers malicious script tied to COO''s credentials.', 'Panicked initially, then focused and determined during troubleshooting; ends scene with satisfaction mixed with dread about future disasters.', 'At keyboard/computer terminal during intense debugging session.', 'Drives home exhausted after successfully restoring server at dawn.', 'Woken by frantic 4:44 a.m. call from CEO about server outage.', 'Reports to CEO Francine; recognizes COO as ongoing threat; appreciated by IT team for solving crisis.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:55.447677-05', '2026-02-27 13:17:55.447677-05');
INSERT INTO public.entity_scene_appearances VALUES (355, 128, 23, 'neutral', true, 'Pacing anxiously in corner office during server crisis; initially blames protagonist based on COO''s false claims.', 'Frantic, desperate, and panicked during crisis; shifts to relieved and mellow after server restoration.', NULL, 'Orders team to rest after server comes back online; tension visibly melts.', 'Makes the initial 4:44 a.m. call claiming protagonist caused the server failure.', NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:55.447677-05', '2026-02-27 13:17:55.447677-05');
INSERT INTO public.entity_scene_appearances VALUES (356, 366, 23, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned as absent during server crisis; blamed protagonist falsely for the outage.', 'Directly antagonistic to protagonist; manipulates CEO into blaming wrong person; represents ongoing existential threat to company stability.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:55.447677-05', '2026-02-27 13:17:55.447677-05');
INSERT INTO public.entity_scene_appearances VALUES (357, 367, 23, 'ally', true, NULL, NULL, NULL, 'Celebrate successful server restoration with nervous cheers and gratitude.', 'Summoned from bed by emergency server outage; arrive at office ready to troubleshoot.', 'Collaborate with protagonist; respect protagonist''s leadership and technical skill; grateful for solution.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:55.447677-05', '2026-02-27 13:17:55.447677-05');
INSERT INTO public.entity_scene_appearances VALUES (358, 368, 23, 'neutral', true, NULL, NULL, NULL, 'Successfully restored to full operation as dawn breaks; green light signals triumphant reboot.', 'Found completely offline with error messages flooding console.', NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:55.447677-05', '2026-02-27 13:17:55.447677-05');
INSERT INTO public.entity_scene_appearances VALUES (359, 369, 23, 'enemy', true, NULL, NULL, NULL, 'Deleted by protagonist via sharp keystroke; immediately restores server functionality.', 'Discovered embedded in codebase during deep troubleshooting; protagonist spots it while scanning code.', NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:55.447677-05', '2026-02-27 13:17:55.447677-05');
