INSERT INTO public.entity_scene_appearances VALUES (636, 278, 41, 'ally', true, 'Trembling, gasping, vision darkening, muscles quivering with strain and desperation.', 'Desperate, terrified of death, summoning final reserves of strength and will to survive.', 'Now clutches the extracted glowing device to their chest.', NULL, NULL, 'Haunted by the location''s connection to their son''s patrol; fighting against the forest''s malevolence.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:55:25.624876-05', '2026-02-27 13:55:25.624876-05');
