INSERT INTO public.entity_scene_appearances VALUES (773, 292, 48, 'ally', true, NULL, 'Begins the scene battered, numb, and despairing after being fired. Moves through exhaustion and surrender into a state of curiosity and trepidation in the dreamscape. Becomes frustrated and defiant when questioning the Weaver, before finally settling into a state of fearful resolve and acceptance of their new role.', NULL, NULL, 'The protagonist is present from the start of the scene, falling asleep in their bed.', 'Is tormented by the memory of the COO''s Insult. Encounters the Shadowy Figures and is guided by The Weaver, who reveals their destiny as a bridge-walker between realms.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (774, 794, 48, 'enemy', false, NULL, NULL, NULL, 'Fades as the protagonist is pulled into the dreamscape.', 'Manifests as a recurring thought as the protagonist tries to fall asleep.', 'A mental antagonist to The Protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (775, 795, 48, 'neutral', true, NULL, NULL, NULL, 'Its purpose is fulfilled once the protagonist has entered The Threshold.', 'Takes hold of the protagonist as they lie exhausted in bed.', 'Acts as a transitionary force for The Protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (776, 796, 48, 'neutral', true, NULL, NULL, NULL, 'Remain as a background element of the location.', 'Appear as the protagonist fully enters the dreamscape.', 'Inhabitants of The Threshold.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (777, 797, 48, 'neutral', true, NULL, NULL, NULL, 'One of them, The Weaver, steps forward to interact, while the others remain in the background.', 'The protagonist is drawn towards them by an unseen force.', 'They are the group to which The Weaver belongs.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (778, 798, 48, 'ally', true, NULL, NULL, NULL, 'Fades back into the swirling mist after delivering their message and warning.', 'Steps forward from the group of Shadowy Figures to greet the protagonist.', 'A member of The Weavers who acts as a guide and mentor to The Protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (779, 799, 48, 'ally', true, NULL, NULL, NULL, 'Remain present in The Threshold but fade from focus when The Weaver departs.', 'Revealed by name when The Weaver introduces themself and their purpose.', 'A collective of which The Weaver is a part. They have been watching The Protagonist for a long time.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (780, 800, 48, 'enemy', true, NULL, NULL, NULL, NULL, 'Mentioned by The Weaver as a warning to the protagonist.', 'The dangerous, hostile aspect of The Threshold, home to The Lost Echoes.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (781, 801, 48, 'enemy', true, NULL, NULL, NULL, NULL, 'Described by The Weaver as the fate of those who venture too deep into the shadows.', 'Inhabitants of The Deeper Shadows.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (782, 802, 48, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:08:39.176988-05', '2026-02-27 14:08:39.176988-05');
INSERT INTO public.entity_scene_appearances VALUES (783, 292, 49, 'ally', true, NULL, NULL, NULL, NULL, 'Pushes deeper into the Threshold, drawn by an unseen force.', 'Feels an undeniable thread of familiarity binding them to the Threshold, suggesting a pre-ordained role.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:09:38.251105-05', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_scene_appearances VALUES (784, 804, 49, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Acts as a container and amplifier for the Dreamers and their thoughts. Has a mysterious, inevitable connection to The Protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:09:38.251105-05', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_scene_appearances VALUES (785, 805, 49, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'They are the audible essence of The Threshold, composed of the collective unconscious of the Dreamers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:09:38.251105-05', '2026-02-27 14:09:38.251105-05');
INSERT INTO public.entity_scene_appearances VALUES (786, 806, 49, 'neutral', true, NULL, NULL, NULL, NULL, 'Observed by the protagonist in a cluster, engaged in animated discussion.', 'They are the inhabitants and co-creators of the Threshold.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:09:38.251105-05', '2026-02-27 14:09:38.251105-05');
