INSERT INTO public.entity_scene_appearances VALUES (809, 278, 52, 'ally', true, NULL, NULL, NULL, NULL, 'Is experiencing a dream of Elysium at the start of the scene.', 'Father to ''The Son''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:01.87074-05', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_scene_appearances VALUES (810, 830, 52, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Erupts suddenly throughout the house via Alexa''s speaker group.', 'Weaponized by ''The Son'' against the protagonist''s peace.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:01.87074-05', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_scene_appearances VALUES (811, 831, 52, 'neutral', true, NULL, NULL, NULL, NULL, 'Is in his bedroom when he decides to play the music.', 'Son of the ''Protagonist''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:01.87074-05', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_scene_appearances VALUES (812, 824, 52, 'neutral', false, NULL, NULL, NULL, 'Its beauty is ''dissolved in an instant'' by the loud music.', 'The protagonist is dreaming of this place as the scene begins.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:01.87074-05', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_scene_appearances VALUES (813, 833, 52, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifests as a mental afterimage immediately after the protagonist wakes up.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:01.87074-05', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_scene_appearances VALUES (814, 834, 52, 'neutral', true, NULL, NULL, NULL, NULL, 'Is discovered and utilized by ''The Son'' to play music.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:01.87074-05', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_scene_appearances VALUES (815, 835, 52, 'neutral', true, NULL, NULL, NULL, NULL, 'The protagonist stumbles to it in a daze.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:01.87074-05', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_scene_appearances VALUES (816, 836, 52, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:01.87074-05', '2026-02-27 14:12:01.87074-05');
INSERT INTO public.entity_scene_appearances VALUES (817, 278, 53, 'ally', true, 'Appears fatigued and confused, with hair thick with sweat. He nurses a coffee mug while lost in thought.', 'Haunted and preoccupied by a vivid dream, while also processing the stress and anger from his recent firing. He is initially withdrawn but opens up to his wife about the dream.', NULL, NULL, 'The protagonist is already in the kitchen at the start of the scene.', 'Husband to the Protagonist''s Wife. He feels guilty for holding back from her but ultimately confides in her about his dream.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (818, 838, 53, 'ally', true, NULL, NULL, NULL, 'Leaves to go to her office after their conversation concludes.', 'Enters the kitchen after returning home, announced by the sound of the garage door.', 'Wife of the Protagonist. She acts as a supportive but grounding force for him.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (819, 839, 53, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'The central preoccupation of the Protagonist, overshadowing even his recent firing.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (820, 824, 53, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'The setting of ''The Dream of Elysium''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (821, 841, 53, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'The object of the Hooded Figures'' unified gesture.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (822, 826, 53, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'Inhabitants or guides within ''The Dream of Elysium''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (823, 108, 53, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (824, 844, 53, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'A major source of the protagonist''s current stress, though he actively avoids discussing it.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (825, 415, 53, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned as having departed for school, leaving behind cereal crumbs.', 'Son of the Protagonist and Protagonist''s Wife.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:12:47.335901-05', '2026-02-27 14:12:47.335901-05');
INSERT INTO public.entity_scene_appearances VALUES (826, 292, 54, 'ally', true, 'He is no longer defined by his corporate job and is actively redefining his identity around his family. He has shifted from a high-powered executive to a present father and husband.', 'Moves from a state of jarring disorientation and paralysis to one of quiet resolve and profound fulfillment. He grapples with the loss of his old identity while embracing his new purpose.', NULL, NULL, 'The scene opens with him adrift after the end of his all-consuming career.', 'He is the father of his son and husband to his wife, and is actively working to repair and deepen these bonds. He views his former corporate life as a past identity he has shed.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:13:50.207638-05', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_scene_appearances VALUES (827, 848, 54, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The antagonist to the protagonist''s new sense of self and family purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:13:50.207638-05', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_scene_appearances VALUES (828, 849, 54, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A direct consequence of leaving ''The Former Corporate Life''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:13:50.207638-05', '2026-02-27 14:13:50.207638-05');
INSERT INTO public.entity_scene_appearances VALUES (829, 850, 54, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:13:50.207638-05', '2026-02-27 14:13:50.207638-05');
