INSERT INTO public.entity_scene_appearances VALUES (834, 292, 55, 'ally', true, NULL, 'Becomes obsessive and fixated on the Pointers, driven by a compulsive need for answers. He struggles between his rational IT training and the pull of conspiracy, experiencing growing unease and a ''bone-deep chill'' as his research deepens.', NULL, NULL, NULL, 'Investigator of The Pointers, The Mandela Effect, and CERN''s activities.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:14:30.642504-05', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_scene_appearances VALUES (835, 39, 55, 'unknown', false, 'Their existence has been completely erased from the internet and all records, including news articles and the protagonist''s own social media history, as if ''scrubbed from reality''.', NULL, NULL, NULL, NULL, 'The central mystery driving the protagonist''s obsession.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:14:30.642504-05', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_scene_appearances VALUES (836, 857, 55, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned as the catalyst that convinced the protagonist of a deeper connection to the Pointers, sparking his obsessive research.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:14:30.642504-05', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_scene_appearances VALUES (837, 858, 55, 'neutral', true, 'Serves as the primary tool for the protagonist''s investigation, portrayed as a chaotic space containing both verifiable data and absurd ''rabbit holes'' of conspiracy.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:14:30.642504-05', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_scene_appearances VALUES (838, 859, 55, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Represents a threat to the protagonist''s rationality and sanity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:14:30.642504-05', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_scene_appearances VALUES (839, 860, 55, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Theorized to be correlated with the Large Hadron Collider''s activity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:14:30.642504-05', '2026-02-27 14:14:30.642504-05');
INSERT INTO public.entity_scene_appearances VALUES (840, 861, 55, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'Operated by CERN; potentially the cause of the Mandela Effect and Reality Destabilization.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:14:30.642504-05', '2026-02-27 14:14:30.642504-05');
