INSERT INTO public.entity_scene_appearances VALUES (849, 862, 56, 'neutral', true, 'The organization''s work, specifically with the LHC, is identified as the direct cause of tearing holes in reality and creating portals to other dimensions.', NULL, NULL, NULL, 'Mentioned as the researcher''s ''playground'' and the origin point of the dimensional bleed.', 'Employer of The Researcher and their colleagues.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:15:25.564744-05', '2026-02-27 14:15:25.564744-05');
