INSERT INTO public.entity_scene_appearances VALUES (853, 874, 56, 'neutral', false, NULL, NULL, NULL, 'Ceased to exist due to the spiraling chaos of the experiments.', NULL, 'Colleagues of The Researcher.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:15:25.564744-05', '2026-02-27 14:15:25.564744-05');
