INSERT INTO public.entity_scene_appearances VALUES (903, 755, 61, 'ally', true, NULL, 'His emotional state shifts rapidly from exhilaration at his success to overwhelming terror and shock as the engine fails and explodes.', NULL, NULL, NULL, 'Husband to the Narrator''s Wife and father to the Narrator''s Son. He is the sole operator and victim of the Eternal Engine''s failure.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:20:22.890265-05', '2026-02-27 14:20:22.890265-05');
INSERT INTO public.entity_scene_appearances VALUES (904, 295, 61, 'enemy', true, 'Becomes violently unstable, glowing and shuddering before its catastrophic failure.', NULL, 'Its copper terminals glow and then shoot molten metal.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:20:22.890265-05', '2026-02-27 14:20:22.890265-05');
INSERT INTO public.entity_scene_appearances VALUES (905, 927, 61, 'neutral', true, 'Fails catastrophically, with jagged fissures racing across its surface before it shatters completely in the explosion.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:20:22.890265-05', '2026-02-27 14:20:22.890265-05');
INSERT INTO public.entity_scene_appearances VALUES (906, 928, 61, 'enemy', true, 'Briefly subsides into exhilaration before returning as overwhelming terror during the engine''s failure.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:20:22.890265-05', '2026-02-27 14:20:22.890265-05');
INSERT INTO public.entity_scene_appearances VALUES (907, 929, 61, 'neutral', true, 'The sound escalates dramatically, deepening into a resonant thrum, then a roar, and finally a deafening, screaming crescendo before being replaced by silence.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:20:22.890265-05', '2026-02-27 14:20:22.890265-05');
INSERT INTO public.entity_scene_appearances VALUES (908, 930, 61, 'enemy', true, NULL, NULL, NULL, 'Ends abruptly, leaving behind wreckage and silence.', 'Occurs as the climax of the engine''s instability, completely destroying the lab.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:20:22.890265-05', '2026-02-27 14:20:22.890265-05');
INSERT INTO public.entity_scene_appearances VALUES (909, 931, 61, 'enemy', true, NULL, NULL, NULL, NULL, 'Created at the moment the glass enclosure explodes.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:20:22.890265-05', '2026-02-27 14:20:22.890265-05');
INSERT INTO public.entity_scene_appearances VALUES (910, 932, 61, 'enemy', true, NULL, NULL, NULL, NULL, 'Appears as the engine becomes critically unstable, just before the main explosion.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:20:22.890265-05', '2026-02-27 14:20:22.890265-05');
