INSERT INTO public.entity_scene_appearances VALUES (914, 755, 62, 'ally', true, NULL, 'Experiences a rapid and extreme emotional rollercoaster, moving from shock and confusion to overwhelming panic and despair, followed by a moment of bitter acceptance, and culminating in a surge of profound relief and awe.', NULL, NULL, NULL, 'Creator and operator of the Eternal Engine. Experiences a crisis of confidence and responsibility related to his family''s well-being.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:21:20.399666-05', '2026-02-27 14:21:20.399666-05');
INSERT INTO public.entity_scene_appearances VALUES (915, 295, 62, 'neutral', true, 'Initially perceived as completely vanished from the wreckage, leaving no trace. It is later revealed to be intact and humming softly in its corner, having merely phased out of visibility.', NULL, 'Its glass enclosure is now shattered.', NULL, NULL, 'The central focus of the Narrator''s experiment; its apparent disappearance and reappearance drive the scene''s entire emotional arc.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:21:20.399666-05', '2026-02-27 14:21:20.399666-05');
