INSERT INTO public.entity_scene_appearances VALUES (953, 221, 66, 'ally', true, NULL, NULL, NULL, 'The scene ends as he follows his wife to bed, finding temporary respite from his anxieties.', 'The scene opens with him staring blankly at a TV, exhausted.', 'Husband to his wife, who provides comfort and grounding. Enemy of the dream-constructs representing his job search.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.entity_scene_appearances VALUES (954, 472, 66, 'ally', true, NULL, NULL, NULL, 'Leads the narrator to bed at the end of the scene.', 'Present at the beginning of the scene, offering to watch TV. Re-enters the narrative focus when the narrator wakes from his nightmare.', 'Wife of the narrator; acts as his anchor to reality.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.entity_scene_appearances VALUES (955, 978, 66, 'enemy', true, NULL, NULL, NULL, 'Disappears when the narrator jolts awake.', 'Manifests when the narrator''s exhaustion causes his perception of reality to shift.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.entity_scene_appearances VALUES (956, 979, 66, 'enemy', true, NULL, NULL, NULL, 'Disappear when the narrator wakes up.', 'Emerge from the horizon of the Unemployment Battlefield.', 'Minions of the Final Interview Round Boss.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.entity_scene_appearances VALUES (958, 968, 66, 'enemy', true, 'In this dream, they manifest as literal explosions that rock the landscape, mocking the narrator with phrases like ''thank you for your interest''.', NULL, NULL, 'Disappear when the dream ends.', 'Appear as explosions when the narrator fires his resume-bullets.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
