INSERT INTO public.entity_scene_appearances VALUES (1076, 157, 78, 'enemy', true, 'Sustains a significant cut on his hand after punching a wall and shattering beer bottles.', 'His emotional state degrades from passionate frustration into unhinged, violent rage, culminating in a physical attack on Stacey. He ends the scene sullen and bitter.', NULL, NULL, NULL, 'Acts as Stacey''s primary antagonist, driven by his paranoia. He believes she has been brainwashed by The Conspiracy and is actively working against him.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:36:01.424183-05', '2026-02-27 14:36:01.424183-05');
INSERT INTO public.entity_scene_appearances VALUES (1077, 195, 78, 'ally', true, NULL, 'Transitions from fearful and pleading to defiant and confrontational. She experiences a moment of dark temptation before reaffirming her moral boundaries, ending in a state of fearful compliance.', NULL, NULL, NULL, 'Victim of Todd''s abuse and paranoia. She fears for his sanity and her own safety, and briefly contemplates murdering him with rat poison.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:36:01.424183-05', '2026-02-27 14:36:01.424183-05');
INSERT INTO public.entity_scene_appearances VALUES (1078, 1104, 78, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The central focus of Todd''s obsession and the perceived enemy he is fighting against.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:36:01.424183-05', '2026-02-27 14:36:01.424183-05');
INSERT INTO public.entity_scene_appearances VALUES (1079, 159, 78, 'enemy', false, 'Explicitly named by Todd as the primary force behind the reality-rewriting conspiracy.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:36:01.424183-05', '2026-02-27 14:36:01.424183-05');
INSERT INTO public.entity_scene_appearances VALUES (1080, 39, 78, 'enemy', false, 'Used by Todd as a key piece of evidence for the conspiracy, which he claims Stacey has been forced to forget. Stacey can find no evidence of their existence.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:36:01.424183-05', '2026-02-27 14:36:01.424183-05');
