INSERT INTO public.entity_scene_appearances VALUES (1130, 1157, 83, 'neutral', true, NULL, NULL, NULL, 'Flees in terror after witnessing the experiment.', 'Runs through the garage during a ''mid-laser show''.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:40:19.410702-05', '2026-02-27 14:40:19.410702-05');
