INSERT INTO public.entity_scene_appearances VALUES (1138, 948, 84, 'neutral', true, NULL, NULL, NULL, NULL, 'Storms into the garage after the experiment, drawn by the noise and smell, to find the place in a state of chaos.', 'Wife of ''The Father'' and mother of ''The Son''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_scene_appearances VALUES (1139, 456, 84, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The power source for the experiment that creates ''The Crystal''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_scene_appearances VALUES (1140, 1167, 84, 'neutral', true, NULL, NULL, NULL, 'Violently implodes, splattering across the garage and leaving ''The Crystal'' in its place.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_scene_appearances VALUES (1141, 1168, 84, 'neutral', true, NULL, NULL, NULL, NULL, 'Materializes on the workbench in the center of the chaos where the chicken had been.', 'The miraculous and dangerous result of the experiment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.entity_scene_appearances VALUES (1142, 1169, 84, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'An emanation from ''The Crystal'' that affects ''The Father'', ''The Son'', and ''The Wife''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
