INSERT INTO public.entity_scene_appearances VALUES (1145, 755, 85, 'ally', true, NULL, 'Becomes the target of a sudden, suspicious accusation and a physical shove from his wife.', NULL, NULL, NULL, 'Husband to The Wife, father to The Son. Experiences a moment of jarring tension with his wife.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:42:18.622465-05', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_scene_appearances VALUES (1146, 831, 85, 'ally', true, NULL, 'Expresses disgust at a bad smell, inadvertently triggering a confrontation between his parents.', NULL, NULL, NULL, 'Son of The Narrator and The Wife.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:42:18.622465-05', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_scene_appearances VALUES (1147, 948, 85, 'ally', true, NULL, 'Reacts with sharp, immediate suspicion to a bad smell, physically shoving and accusing The Narrator.', NULL, NULL, NULL, 'Wife of The Narrator, mother of The Son. Her actions create a moment of domestic tension.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:42:18.622465-05', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_scene_appearances VALUES (1148, 1175, 85, 'neutral', true, NULL, NULL, NULL, NULL, 'First noticed and announced by The Son.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:42:18.622465-05', '2026-02-27 14:42:18.622465-05');
INSERT INTO public.entity_scene_appearances VALUES (1149, 1176, 85, 'enemy', true, NULL, NULL, NULL, NULL, 'Triggered by The Son pointing out The Bad Smell.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:42:18.622465-05', '2026-02-27 14:42:18.622465-05');
