INSERT INTO public.entity_scene_appearances VALUES (1151, 755, 86, 'ally', true, NULL, 'Oscillates between fascination and deep frustration with the crystal''s inertness, feeling taunted by its mysterious nature.', NULL, NULL, NULL, 'Father of ''The Son''. Co-investigator of ''The Crystal (Chicken Shit)''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_scene_appearances VALUES (1152, 831, 86, 'ally', true, NULL, 'Moves from bored dismissal of the crystal as a ''paperweight'' to excitement upon discovering its NFC properties, and finally to shared frustration when it refuses to connect.', NULL, NULL, NULL, 'Son of ''The Narrator''. Discovers the crystal''s hidden ability.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_scene_appearances VALUES (1153, 1181, 86, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The central object of mystery, frustrating both ''The Narrator'' and ''The Son''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_scene_appearances VALUES (1154, 456, 86, 'neutral', false, 'Mentioned as the origin of the crystal and the cause of a loud explosion that covered the garage in charred poultry during a failed experiment to replicate its creation.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.entity_scene_appearances VALUES (1155, 1183, 86, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Acts as a tool or catalyst that reveals a new property of ''The Crystal (Chicken Shit)''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
