INSERT INTO public.entity_scene_appearances VALUES (1306, 834, 100, 'neutral', false, NULL, NULL, 'The family has modified an Android app to integrate The Infinitron with the Alexa network, enabling full voice command control over their experimental setup.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
