INSERT INTO public.entity_scene_appearances VALUES (1184, 1212, 89, 'neutral', true, 'Successfully integrated with a contemporary motherboard via a custom adapter. It now produces a high-resolution graphical interface and demonstrates processing speeds that defy comprehension, capable of running an entire game instantaneously.', NULL, 'Now connected to a 3D-printed adapter, a contemporary motherboard, and outputs to a 4K monitor.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:45:41.493353-05', '2026-02-27 14:45:41.493353-05');
INSERT INTO public.entity_scene_appearances VALUES (1185, 1202, 89, 'neutral', true, NULL, NULL, NULL, 'Decommissioned and replaced by a contemporary motherboard, as it was too primitive to harness the Infinitron''s full potential.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:45:41.493353-05', '2026-02-27 14:45:41.493353-05');
