INSERT INTO public.entity_scene_appearances VALUES (1198, 1212, 90, 'neutral', true, 'Its crystalline glow goes dark after the power surge, then returns ''brighter than ever'' after being fixed.', NULL, NULL, NULL, NULL, 'The central focus of the family''s attention, frustration, and efforts.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:46:53.425867-05', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.entity_scene_appearances VALUES (1199, 1228, 90, 'mini-boss', true, NULL, NULL, NULL, 'The event is instantaneous, leaving silence and a dead machine in its wake.', 'Appears without warning, as if on cue.', 'The antagonistic force that creates the central conflict of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:46:53.425867-05', '2026-02-27 14:46:53.425867-05');
