INSERT INTO public.entity_scene_appearances VALUES (1243, 1273, 95, 'ally', true, NULL, 'Experiences a cycle of frustration from being banned, cautious optimism with a new plan, and finally resigned acceptance of the need for secrecy.', NULL, NULL, NULL, 'Husband to Sarah, father to Leo. Leads the family''s attempts to utilize the Infinitron.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:51:40.884139-05', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_scene_appearances VALUES (1244, 1274, 95, 'ally', true, NULL, 'Moves from incredulity and excitement (about SETI) to nervous humor in the face of repeated failure.', NULL, NULL, NULL, 'Son of David and Sarah.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:51:40.884139-05', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_scene_appearances VALUES (1245, 1275, 95, 'ally', true, NULL, 'Remains pragmatic and thoughtful, suggesting alternatives and ultimately articulating the key lesson about the Infinitron''s power and the need for secrecy.', NULL, NULL, NULL, 'Wife of David, mother of Leo.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:51:40.884139-05', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_scene_appearances VALUES (1246, 1201, 95, 'neutral', true, 'Its computational power is further contextualized as being so immense that it breaks public distributed computing projects, even when throttled. It is powered down at the end of the scene.', NULL, 'Temporarily connected to the Folding@Home network via a custom Django proxy.', 'Powered down by the family after they realize its power is too conspicuous for public projects.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:51:40.884139-05', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_scene_appearances VALUES (1247, 1267, 95, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned as the first project from which the family was banned, setting the context for their new attempt.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:51:40.884139-05', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.entity_scene_appearances VALUES (1248, 1278, 95, 'neutral', false, NULL, NULL, NULL, 'Permanently bans the family, ending their attempt to contribute.', 'Chosen as a new potential outlet for the Infinitron''s power after the BOINC failure.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:51:40.884139-05', '2026-02-27 14:51:40.884139-05');
