INSERT INTO public.entity_scene_appearances VALUES (1346, 292, 104, 'ally', true, 'Navigates the hostile void of Oblivion, confronting its denizens to seize a hidden truth.', 'Experiences overwhelming dread but channels it into defiant fury. His resolve is tested but ultimately holds firm, culminating in a violent act and the acceptance of a painful truth.', NULL, NULL, 'Enters Oblivion through a portal.', 'Adversary to the Demogorgon''s Herald and the Eldritch Abominations. Seeker of Knowledge and The Truth.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
