INSERT INTO public.entity_scene_appearances VALUES (1374, 852, 106, 'ally', true, NULL, 'Shifts from deep worry and fear for her husband to relief and then intense, charged anticipation as she realizes the significance of his experience.', NULL, NULL, 'Rushes into the room after hearing her husband''s screaming from the previous night.', 'Wife of ''The Protagonist''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
