INSERT INTO public.entity_scene_appearances VALUES (1381, 292, 107, 'ally', true, NULL, 'Moves from a state of gnawing frustration and a feeling of being watched to one of shock and sudden, forceful clarity after a revelatory dream.', NULL, NULL, NULL, 'Struggles to understand the secrets of the Eternal Engine, Infinitron, and Superconducting Wires. Is the target of The Unrelenting Dream''s revelation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_scene_appearances VALUES (1382, 281, 107, 'neutral', true, NULL, NULL, NULL, 'Becomes irrelevant once The Unrelenting Dream provides a direct revelation.', 'Used by the protagonist in a failed attempt to gain insight.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_scene_appearances VALUES (1383, 1212, 107, 'neutral', true, 'Initially perceived as unhelpful, pulsing with unreadable riddles and producing nonsense. The dream reframes it as a ''repository of infinite wisdom''.', NULL, NULL, NULL, NULL, 'One of the three core devices the protagonist is studying, along with the Eternal Engine and Superconducting Wires.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_scene_appearances VALUES (1384, 295, 107, 'neutral', true, 'Continues its steady humming, taunting the protagonist with its silence. The dream reveals its true nature as a source of raw, immense power, like an ''unchained god''.', NULL, NULL, NULL, NULL, 'One of the three core devices the protagonist is studying.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_scene_appearances VALUES (1386, 1419, 107, 'mini-boss', true, NULL, NULL, NULL, 'Ends abruptly, leaving the protagonist awake with its message ''seared into my brain''.', 'Manifests when the protagonist is about to surrender to frustration.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_scene_appearances VALUES (1387, 1420, 107, 'enemy', true, NULL, NULL, NULL, 'Is forcefully displaced by the shock and clarity of The Unrelenting Dream.', 'Builds over days of failed attempts and analysis of the dream journal.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_scene_appearances VALUES (1388, 1421, 107, 'neutral', true, NULL, NULL, NULL, 'Implicitly resolved by the dream''s revelation.', 'Accompanies the protagonist''s frustration, signaling that a key piece of the puzzle is missing.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_scene_appearances VALUES (1389, 1422, 107, 'neutral', false, NULL, NULL, NULL, 'Fades as the dream ends.', 'Revealed within The Unrelenting Dream as the true nature of the wires.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.entity_scene_appearances VALUES (1390, 1423, 107, 'neutral', false, NULL, NULL, NULL, 'Vanish when the dream ends.', 'Appear as part of the dream''s sensory landscape.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
