INSERT INTO public.entity_scene_appearances VALUES (1411, 1444, 110, 'ally', true, NULL, 'Experiences a rapid succession of intense emotions: dread during the device''s activation, awe and horror at the resulting creations, and finally a manic, roaring exhilaration upon realizing he has created a matter replicator.', NULL, NULL, NULL, 'Creator of the Eternal Engine, The Perfect Box, and the Grotesque Replicated Hand. Summons his family to witness his work.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.entity_scene_appearances VALUES (1412, 295, 110, 'neutral', true, 'Activates with a violent roar, its chamber crackling with arcing energy. It emits a blinding light that warps the space around it.', NULL, NULL, NULL, NULL, 'The primary device used in the experiment, which gives birth to The Perfect Box.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.entity_scene_appearances VALUES (1413, 1212, 110, 'neutral', true, 'Reacts to the Eternal Engine''s activation by escalating its hum to a ''mournful wail'' and flashing words on its monitors.', NULL, NULL, NULL, NULL, 'A secondary device that works in concert with the Eternal Engine.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.entity_scene_appearances VALUES (1414, 1447, 110, 'enemy', true, NULL, NULL, NULL, 'Subsides suddenly, leaving an eerie stillness.', 'Unleashed when the Eternal Engine is activated.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.entity_scene_appearances VALUES (1415, 1448, 110, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'Created by the Eternal Engine. It, in turn, creates the Grotesque Replicated Hand.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
