INSERT INTO public.entity_scene_appearances VALUES (1424, 472, 111, 'neutral', true, NULL, NULL, NULL, NULL, 'Enters the garage with her son to investigate the commotion.', 'Wife of the Protagonist and mother of the Son. She is vocally critical and fearful of her husband''s creations.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.entity_scene_appearances VALUES (1425, 473, 111, 'neutral', true, NULL, NULL, NULL, NULL, 'Enters the garage with his mother to see what his father has done.', 'Son of the Protagonist and the Wife. He is more curious than afraid, questioning the practical applications of the device.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.entity_scene_appearances VALUES (1426, 1459, 111, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A monstrous creation of the Etched Cube, serving as physical proof of the device''s dangerous imprecision.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
