INSERT INTO public.entity_scene_appearances VALUES (1440, 1474, 113, 'ally', true, NULL, NULL, NULL, 'Is suppressed by the reassertion of tradition in the second beat.', 'Manifests as the driving motivation for change.', 'An ally to The Liberator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:06.506523-05', '2026-02-27 15:08:06.506523-05');
