INSERT INTO public.entity_scene_appearances VALUES (1467, 157, 117, 'ally', true, 'His eyes are no longer yellow and monstrous.', 'He has shifted from being on the verge of violence to a state of weary acceptance and exhaustion, mirroring Stacey''s.', NULL, NULL, NULL, 'Shares a moment of unified surrender with Stacey.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.entity_scene_appearances VALUES (1468, 195, 117, 'ally', true, 'Her frame is bloodied and she is taking painful breaths.', 'She is broken, exhausted, and tormented by memories of monstrous growls, yet retains a flicker of hope before ultimately accepting the voice''s offer.', 'Her clothes are now torn.', NULL, NULL, 'Shares a moment of unified surrender with Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
