INSERT INTO public.entity_scene_appearances VALUES (1476, 195, 118, 'ally', true, 'Appears exhausted and ragged, with a fresh, bloody gash on her leg.', 'Her initial confusion and denial upon waking shift to a weary, resigned acceptance of her new reality. The defiance she once had is gone.', NULL, NULL, NULL, 'Shares a bond of shared trauma and an unknown fate with Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_scene_appearances VALUES (1477, 157, 118, 'ally', true, 'Suffers from an aching side, a physical mark from the otherworldly encounter.', 'Moves from a groggy state to a silent, dawning comprehension that their shared experience was real, culminating in weary acceptance.', NULL, NULL, NULL, 'Wordlessly affirms his shared experience with Stacey, solidifying their joint fate.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.entity_scene_appearances VALUES (1478, 1515, 118, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Has marked both Stacey and Todd, making them unwilling servants to its veiled agenda.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
