INSERT INTO public.entity_scene_appearances VALUES (1483, 1515, 119, 'neutral', true, NULL, NULL, NULL, NULL, 'Stirred from its slumber by a tremor in the fabric of reality.', 'Observes The Eternal Engine with curiosity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
