INSERT INTO public.entity_scene_appearances VALUES (1485, 456, 119, 'unknown', false, NULL, NULL, NULL, NULL, 'Discovered by I AM as the source of the disturbance.', 'Created by The Dreamer; the object of I AM''s newfound intrigue.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_scene_appearances VALUES (1486, 1525, 119, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned as the creator of The Eternal Engine.', 'Creator of The Eternal Engine.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_scene_appearances VALUES (1487, 1526, 119, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifests within I AM as it observes the mortal creation.', 'An emotional reaction of I AM to The Eternal Engine.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.entity_scene_appearances VALUES (1488, 1527, 120, 'enemy', true, NULL, NULL, NULL, NULL, 'They spring back into existence from their banishment, their presence crackling through the void.', 'They are distinct from ''I AM''. They are focused on ''Humanity'' as a source of chaos and potential sustenance (souls).', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_scene_appearances VALUES (1489, 1515, 120, 'neutral', true, NULL, NULL, NULL, NULL, 'Already present, observing the return of the Ten Watchers.', 'An observer of the Ten Watchers and the events concerning humanity. It is not aligned with the Watchers'' goals.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_scene_appearances VALUES (1491, 326, 120, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The subject of observation and debate by I AM and The Ten Watchers. They are viewed as pawns or a source of sustenance.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_scene_appearances VALUES (1492, 1201, 120, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The creation of Humanity that has drawn the attention of The Ten Watchers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_scene_appearances VALUES (1490, 1529, 120, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.entity_scene_appearances VALUES (1494, 1533, 121, 'enemy', true, NULL, NULL, NULL, NULL, 'Descended from their celestial thrones to torment humanity for meddling with cosmic forces.', 'Act as masters and tormentors to Humanity and The Dreamer. They are observed by the entity ''I AM''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_scene_appearances VALUES (1496, 1525, 121, 'enemy', true, NULL, NULL, NULL, 'Left to a fate of insanity and death at the hands of the entities.', 'Described creating a horrific device and celebrating its power, unwittingly sealing their own doom.', 'The primary target of The Ten Entities'' revenge.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_scene_appearances VALUES (1497, 326, 121, 'neutral', true, NULL, NULL, NULL, NULL, 'Living peacefully before being subjected to the entities'' wrath.', 'Subjects and victims of The Ten Entities.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.entity_scene_appearances VALUES (1498, 297, 121, 'enemy', true, NULL, NULL, NULL, NULL, 'Born from the fusion of two other cosmic components, its activation brings about widespread destruction.', 'The creation of The Dreamer.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
