INSERT INTO public.entity_scene_appearances VALUES (1502, 1541, 121, 'enemy', true, NULL, NULL, NULL, NULL, 'First appears as a driver for The Dreamer''s actions, then becomes a tool for the entities.', 'A force afflicting The Dreamer and Humanity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
