INSERT INTO public.entity_scene_appearances VALUES (1504, 1543, 121, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned as the end goal of the entities'' actions, marking their final transformation.', 'The future state of The Ten Entities.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
