INSERT INTO public.entity_scene_appearances VALUES (1506, 1515, 122, 'enemy', true, NULL, NULL, NULL, NULL, 'The entity is already present, but its presence becomes the focus as it withdraws from direct view.', 'Acts as an unseen observer and manipulator in relation to the preoccupied Ten Watchers. It is the master of the Abyss and the consumer of the Feast.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.entity_scene_appearances VALUES (1507, 982, 122, 'neutral', true, 'The Abyss is revealed to be the personal domain of I AM. Its function is redefined as both a prison for others and a sacred feeding ground for its master.', NULL, NULL, NULL, NULL, 'Serves as the home and sanctuary for the entity I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.entity_scene_appearances VALUES (1508, 1527, 122, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'Their distraction provides an opportunity for I AM to act unnoticed.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
