INSERT INTO public.entity_scene_appearances VALUES (2814, 2297, 242, 'neutral', true, 'The building''s conference room serves as the setting for a high-stakes crisis meeting, while its ERB gateway lobby is a hub of activity.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:22:13.658445-05', '2026-02-27 20:22:13.658445-05');
