INSERT INTO public.entity_scene_appearances VALUES (1514, 1554, 123, 'neutral', true, NULL, NULL, NULL, NULL, 'Brought to the parking lot by the Protagonist to duplicate an RV.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1515, 1555, 123, 'neutral', true, NULL, NULL, NULL, NULL, 'Already present in the parking lot when the scene begins.', 'The original template for the Duplicate RV.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1516, 1556, 123, 'neutral', true, NULL, NULL, NULL, NULL, 'Comes into existence after the replication process is completed.', 'A perfect copy of the Abandoned RV.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1517, 1557, 123, 'neutral', true, NULL, NULL, NULL, 'Fades away upon completion of the replication.', 'Appears when the Replicator is activated on the RV.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1518, 1558, 123, 'neutral', true, NULL, NULL, NULL, NULL, 'Set up by the protagonist to hold the Replicator.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1519, 168, 123, 'neutral', true, NULL, 'Courses through the Protagonist as he prepares to activate the Replicator, heightening his senses for the experiment.', NULL, 'Subsides into triumph after the successful replication.', 'Manifests within the Protagonist at the start of the experiment.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1520, 408, 123, 'neutral', true, NULL, 'Felt strongly by the Protagonist''s Wife, whose eyes glint with it as she watches the preparations.', NULL, 'Transforms into disbelief and excitement upon seeing the duplicate.', 'Manifests within the Protagonist''s Wife as they approach the RV.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1521, 1561, 123, 'neutral', true, NULL, NULL, NULL, 'Gives way to caution as practical concerns are discussed.', 'Manifests within the Protagonist when the Duplicate RV is revealed.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1522, 1562, 123, 'neutral', true, NULL, NULL, NULL, NULL, 'Becomes a point of focus after the replication is successful.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.entity_scene_appearances VALUES (1523, 292, 124, 'ally', true, NULL, 'Excited by the successful tests of his invention, amused by his family''s reactions, and acts as the calm scientific voice against his son''s fears.', NULL, NULL, NULL, 'Husband to The Wife and father to The Son. He leads the experiments with the Matter Replicator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1524, 948, 124, 'ally', true, NULL, 'Acts as a voice of reason, initially curious and impressed, but ultimately pragmatic and comically ruthless when dealing with the replicated flies.', NULL, NULL, NULL, 'Wife of The Protagonist and mother of The Son. She participates in the experiment but maintains a practical, grounded perspective.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1525, 831, 124, 'ally', true, NULL, 'Embodies unbridled curiosity and excitement, which quickly turns to imaginative, movie-inspired fear when dealing with replicating a living creature. He is shocked by his mother''s practical solution.', NULL, NULL, NULL, 'Son of The Protagonist and The Wife. He actively suggests new tests for the replicator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1526, 297, 124, 'neutral', true, 'Demonstrated to be capable of perfectly replicating complex inanimate objects and simple living organisms on a molecular level.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1527, 1567, 124, 'neutral', true, NULL, NULL, NULL, NULL, 'Replicated perfectly to demonstrate the device''s basic function.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1528, 1134, 124, 'neutral', true, NULL, NULL, NULL, NULL, 'Replicated flawlessly, including the chip, impressing the wife with its detail.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1529, 1569, 124, 'neutral', true, NULL, NULL, NULL, NULL, 'Successfully duplicated, proving the device works on living matter.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1530, 1570, 124, 'enemy', true, NULL, NULL, NULL, 'Killed by The Wife with a can of insecticide, along with its duplicate.', 'Introduced by the son as a test subject, sparking a debate about the dangers of replication.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1531, 1571, 124, 'neutral', true, NULL, NULL, NULL, NULL, 'Grabbed by The Wife to swiftly and pragmatically eliminate the original and replicated fruit flies.', 'Weapon used by The Wife against the Fruit Flies.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1532, 1572, 124, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifested when the son considers the potential negative outcomes of replicating a fruit fly.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1533, 1573, 124, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.entity_scene_appearances VALUES (1534, 278, 125, 'ally', true, NULL, 'Moves from frustration over the cumbersome technology to excitement and a dawning sense of immense power and potential.', NULL, NULL, NULL, 'Husband to the Wife, father to the Son. Leads the family in upgrading and experimenting with the replicator technology.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1535, 472, 125, 'ally', true, NULL, 'Initially frustrated and pragmatic about the device''s limitations, she becomes awestruck by the new potential for true creation.', NULL, NULL, NULL, 'Wife of the Protagonist, mother of the Son. She identifies the initial problem and later grasps the significance of the upgrade.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1536, 473, 125, 'ally', true, NULL, 'His casual curiosity evolves into creative inspiration, pushing the family to move beyond simple replication.', NULL, NULL, NULL, 'Son of the Protagonist and Wife. He provides key suggestions that advance the technology''s capabilities.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1537, 1212, 125, 'neutral', true, 'Its function is integrated into the new handheld device, though its consciousness as an AI interface remains accessible.', NULL, NULL, 'Absorbed into the Handheld Matter Replicator as a component.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1538, 297, 125, 'neutral', true, 'The original, bulky device is used one last time to create its successor before being rendered obsolete.', NULL, NULL, 'Absorbed into the Handheld Matter Replicator as a component.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1539, 295, 125, 'neutral', true, 'The original power source is integrated into the new, portable unit.', NULL, NULL, 'Absorbed into the Handheld Matter Replicator as a component.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1540, 1580, 125, 'neutral', true, NULL, NULL, NULL, 'Made obsolete by the creation of the integrated handheld unit.', 'Identified as the primary flaw of the initial replicator system, prompting the need for an upgrade.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1541, 1581, 125, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears on the Infinitron''s screen as the solution to the family''s problem.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1542, 1582, 125, 'neutral', true, NULL, NULL, NULL, NULL, 'Constructed by the original Matter Replicator based on the Infinitron''s schematic.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1543, 1583, 125, 'neutral', false, NULL, NULL, NULL, NULL, 'Introduced as the tool to bridge the gap between imagination and physical creation.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1544, 1584, 125, 'neutral', true, NULL, NULL, NULL, NULL, 'Created by the Handheld Matter Replicator using the integrated AutoCAD software.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1545, 1585, 125, 'unknown', true, NULL, NULL, NULL, NULL, 'Proposed jokingly by the protagonist as the next application for the replicator, signifying the family''s shift in thinking about its potential.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:49.484554-05', '2026-02-27 15:17:49.484554-05');
INSERT INTO public.entity_scene_appearances VALUES (1546, 278, 126, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Husband to Protagonist''s Wife, father to Protagonist''s Son.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1547, 415, 126, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Son of the Protagonist and Protagonist''s Wife.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1548, 838, 126, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Wife of the Protagonist, mother to the Protagonist''s Son.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1549, 1589, 126, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1550, 1590, 126, 'neutral', false, NULL, NULL, NULL, NULL, 'Proposed by the Protagonist as a solution to his family''s dissatisfaction with processed food.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1551, 1591, 126, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Disliked by the Protagonist''s Son and Wife.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1552, 1592, 126, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1553, 1593, 126, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A necessary component for the Gourmet Dining Experience.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1554, 1594, 126, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A necessary component for the Gourmet Dining Experience.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1555, 1595, 126, 'neutral', false, NULL, NULL, NULL, NULL, 'Requested by the Protagonist''s Son after he enjoys the spaghetti.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1556, 1596, 126, 'unknown', true, NULL, NULL, NULL, NULL, 'Mentioned when the protagonist forgets to place them to catch the replicated spaghetti.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:18:32.421244-05', '2026-02-27 15:18:32.421244-05');
INSERT INTO public.entity_scene_appearances VALUES (1557, 755, 127, 'ally', true, NULL, 'Initially feels jaded and frustrated by his inability to solve financial problems despite having immense power. He is startled by his wife, then becomes defensive, before finally feeling resolved and committed to acting responsibly.', NULL, NULL, NULL, 'Husband to ''The Wife'' and father to ''The Son''. He feels the weight of providing for his family and guiding them through the ethical dilemmas their technology presents.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1558, 948, 127, 'ally', true, NULL, 'Enters with mock disapproval, but quickly becomes serious and concerned about the family''s path. She acts as the moral compass, appealing to their values with a mixture of sternness and soft-spoken fear.', NULL, NULL, 'Enters the garage, surprising the narrator.', 'Wife of ''The Narrator'' and mother of ''The Son''. She is the pragmatic and ethical anchor of the family.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1559, 831, 127, 'ally', true, NULL, 'Curious and mischievous, he voices the temptation of using the replicator for easy money. He is receptive to his parents'' explanations, processing the complex consequences of their actions.', NULL, NULL, 'Pipes up from his desk in the corner during the family discussion.', 'Son of ''The Narrator'' and ''The Wife''. He represents youthful curiosity and the allure of shortcuts.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1560, 297, 127, 'neutral', true, 'Described as sleek and gleaming, sitting on the workbench and whispering promises of limitless creation. It is the central object of temptation and potential in the scene.', NULL, NULL, NULL, NULL, 'A powerful tool that the family must learn to use responsibly. It is the source of both their snacks and their moral dilemma.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1561, 295, 127, 'neutral', true, 'Described as a defiant monument to ambition, its rhythmic hum resonates like a challenge.', NULL, NULL, NULL, NULL, 'The power source for the Infinitron and, by extension, the Matter Replicator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1562, 1212, 127, 'neutral', true, 'It pulses with an alien intelligence, powered by the Eternal Engine.', NULL, NULL, NULL, NULL, 'A core piece of the family''s advanced technology.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1563, 1604, 127, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist that gives rise to the ''Temptation of Counterfeiting''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1564, 1605, 127, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Symbolizes the trivial current use of the powerful Matter Replicator and acts as the catalyst for the wife''s intervention.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1565, 1606, 127, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The primary internal antagonist that the family must confront and overcome.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
INSERT INTO public.entity_scene_appearances VALUES (1566, 1607, 127, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The counterforce to the ''Temptation of Counterfeiting'', championed by the wife and adopted by the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:19:40.564808-05', '2026-02-27 15:19:40.564808-05');
