INSERT INTO public.entity_scene_appearances VALUES (1579, 221, 129, 'ally', true, NULL, 'Moves from creative frustration and indecision to a moment of epiphany and excitement, which is then replaced by fear and resolve upon learning of the energy surges.', NULL, NULL, NULL, 'Husband to Wife, father to Son. He is the driving force behind naming and registering the family business, The S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:21:14.207833-05', '2026-02-27 15:21:14.207833-05');
INSERT INTO public.entity_scene_appearances VALUES (1580, 472, 129, 'ally', true, NULL, 'Shifts from quiet amusement and pragmatism to thoughtful acceptance of the business name, and finally to urgent concern about the consequences of their actions.', NULL, NULL, NULL, 'Wife to Narrator, mother to Son. Acts as a pragmatic sounding board and key decision-maker in the family venture.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:21:14.207833-05', '2026-02-27 15:21:14.207833-05');
INSERT INTO public.entity_scene_appearances VALUES (1581, 473, 129, 'ally', true, NULL, 'Goes from offering amusing suggestions to enthusiastic support for the business name, before becoming the alarmed messenger who discovers the threatening news article.', NULL, NULL, NULL, 'Son of the Narrator and Wife. Provides youthful enthusiasm and validation, and is the first to spot the external threat.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:21:14.207833-05', '2026-02-27 15:21:14.207833-05');
INSERT INTO public.entity_scene_appearances VALUES (1582, 1623, 129, 'neutral', false, NULL, NULL, NULL, NULL, 'Conceived by the narrator after days of deliberation and officially formed when the family completes the online registration.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:21:14.207833-05', '2026-02-27 15:21:14.207833-05');
