INSERT INTO public.entity_scene_appearances VALUES (1685, 1640, 141, 'ally', true, NULL, 'Shifts from tense and uncertain to bewildered, then relieved and amused. He realizes the source of his weeks-long paranoia was a harmless role-player.', NULL, NULL, NULL, 'Husband to the Narrator''s Wife. Initially intimidated by The Viper, but this feeling turns to incredulous laughter.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:32:30.451105-05', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_scene_appearances VALUES (1686, 454, 141, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Wife of the Awakened Being. Her initial suspicion of The Viper turns to ridicule.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:32:30.451105-05', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_scene_appearances VALUES (1687, 1709, 141, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Father to The Viper''s Daughter. His relationship with the narrator and his wife shifts from antagonist to a source of comic relief.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:32:30.451105-05', '2026-02-27 15:32:30.451105-05');
