INSERT INTO public.entity_scene_appearances VALUES (1690, 1735, 141, 'enemy', true, NULL, NULL, NULL, 'Instantly crumbles and is revealed as ''pure theatrics'' upon the arrival of his daughter.', 'Is the dominant aspect of The Viper''s character at the start of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:32:30.451105-05', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_scene_appearances VALUES (1691, 139, 141, 'neutral', true, NULL, 'Manifests strongly as the characters process the ridiculousness of their fears, culminating in laughter.', NULL, 'Is replaced by Renewed Determination as the couple leaves.', 'Emerges the moment The Viper''s daughter runs into the bar, revealing the truth.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:32:30.451105-05', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_scene_appearances VALUES (1692, 166, 141, 'enemy', false, NULL, NULL, NULL, 'Dispelled by the humorous revelation of The Viper''s true identity.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:32:30.451105-05', '2026-02-27 15:32:30.451105-05');
INSERT INTO public.entity_scene_appearances VALUES (1693, 1738, 141, 'ally', true, NULL, NULL, NULL, NULL, 'Arises from the relief and clarity gained after the confrontation with The Viper is resolved humorously.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:32:30.451105-05', '2026-02-27 15:32:30.451105-05');
