INSERT INTO public.entity_scene_appearances VALUES (1696, 1640, 142, 'ally', true, 'The protagonist''s true, powerful essence is now hidden behind an ordinary human facade, making them appear as just another anonymous face.', 'Fallen from a state of prestige and power, the protagonist feels overwhelmed, trapped, and anonymous. This shifts to contemplation, ironic awareness, and finally a determined resolve to understand their new circumstances.', NULL, NULL, 'Enters the strip club, beginning a period of reflection on their sudden displacement from their home realm.', 'An observer of the Strip Club Patrons, Dancers, and Bartender. Possessor of the Dormant Supernatural Powers. Displaced by the Gargantuan Pile of Gold.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:33:41.60525-05', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_scene_appearances VALUES (1697, 1743, 142, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Objects of the protagonist''s observation and a symbol of the club''s vice. They are watching the Dancers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:33:41.60525-05', '2026-02-27 15:33:41.60525-05');
INSERT INTO public.entity_scene_appearances VALUES (1698, 1744, 142, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The focus of the Strip Club Patrons'' attention.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:33:41.60525-05', '2026-02-27 15:33:41.60525-05');
