INSERT INTO public.entity_scene_appearances VALUES (1700, 1746, 142, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'An internal aspect of the Awakened Being, representing their true potential.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:33:41.60525-05', '2026-02-27 15:33:41.60525-05');
