INSERT INTO public.entity_scene_appearances VALUES (1717, 221, 144, 'ally', true, NULL, 'Moves from a state of extreme physical and mental exhaustion to renewed determination and inspiration after conceiving the robot plan, enduring his wife''s teasing with humor.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:35:53.115407-05', '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_scene_appearances VALUES (1718, 472, 144, 'ally', true, NULL, 'Her state is a mix of witty skepticism and amusement regarding her husband''s plans, grounded in his past failures. She eventually relents, offering cautious support for the robot project.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:35:53.115407-05', '2026-02-27 15:35:53.115407-05');
INSERT INTO public.entity_scene_appearances VALUES (1719, 473, 144, 'ally', true, NULL, 'Full of excitement about his video game, he unknowingly provides the crucial inspiration for the family''s new direction. He later contributes creative, if impractical, ideas to the robot design.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:35:53.115407-05', '2026-02-27 15:35:53.115407-05');
