INSERT INTO public.entity_scene_appearances VALUES (1841, 989, 157, 'ally', true, 'Appears preoccupied and pale as he grapples with a recent health diagnosis and a new, radical idea for self-preservation.', 'Experiences a shift from routine parental annoyance and guilt to deep-seated anxiety about his mortality, culminating in a spark of desperate, world-altering hope.', NULL, NULL, NULL, 'Father to his son. Patient of the Doctor. Owner of the Matter Replicator. Contemplates using technology to fight his Dire Health Diagnosis.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.entity_scene_appearances VALUES (1842, 473, 157, 'ally', true, NULL, 'Begins the scene with sorrow and guilt over his dead pet, which quickly turns to curiosity and concern for his father''s strange mood. He acts as a sounding board for his father''s radical ideas.', NULL, NULL, 'Enters the room holding the fishbowl containing the dead Timmy.', 'Son of the Father. Owner of Timmy the Goldfish.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.entity_scene_appearances VALUES (1843, 1895, 157, 'neutral', true, 'Starts the scene as a lifeless body floating in a bowl. Is replaced by a perfectly identical, living replica created by the Matter Replicator.', NULL, NULL, NULL, NULL, 'The son''s pet. Its death and replacement serve as the catalyst for the father''s epiphany.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.entity_scene_appearances VALUES (1844, 297, 157, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A refrigerator-mounted device used by the Father to create a new Timmy. Its function inspires the Father''s ''Dangerous Idea''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.entity_scene_appearances VALUES (1845, 1897, 157, 'neutral', false, NULL, NULL, NULL, 'The flashback ends.', 'Appears in the Father''s flashback.', 'The Father''s physician.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.entity_scene_appearances VALUES (1846, 1898, 157, 'enemy', false, NULL, NULL, NULL, NULL, 'Revealed during the Father''s flashback to a doctor''s appointment.', 'A condition afflicting the Father, delivered by the Doctor.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.entity_scene_appearances VALUES (1847, 1899, 157, 'neutral', true, NULL, NULL, NULL, NULL, 'Forms in the Father''s mind as he watches the Matter Replicator work.', 'A potential solution to the Dire Health Diagnosis, utilizing the Matter Replicator, Nanites, and Infinitron.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.entity_scene_appearances VALUES (1848, 1847, 157, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by the Father as a potential tool for molecular-level repair.', 'A component of the Father''s ''Dangerous Idea''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.entity_scene_appearances VALUES (1849, 1212, 157, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by the Father as a potential tool for rapid problem-solving.', 'A component of the Father''s ''Dangerous Idea''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
