INSERT INTO public.entity_scene_appearances VALUES (1852, 1904, 158, 'neutral', true, NULL, NULL, NULL, NULL, 'Built in secret by the Father to heal himself.', 'Invention of the Father.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.entity_scene_appearances VALUES (1853, 1847, 158, 'neutral', true, NULL, NULL, NULL, NULL, 'Injected into the Father''s bloodstream by the AutoDoc to begin the healing process.', 'The active healing agent within the AutoDoc.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.entity_scene_appearances VALUES (1854, 1906, 158, 'enemy', true, NULL, NULL, NULL, 'Vanishes abruptly when the nanite procedure is complete.', 'Manifests as soon as the nanites begin their work on the Father''s knee.', 'A direct side effect of the Nanites'' operation within the AutoDoc.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.entity_scene_appearances VALUES (1855, 472, 158, 'ally', true, NULL, NULL, NULL, NULL, 'Storms into the lab after finding her husband, who had been missing all night.', 'Wife of the Father, mother of the Son.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
