INSERT INTO public.entity_scene_appearances VALUES (1892, 1786, 162, 'ally', true, NULL, 'Experiencing a profound sense of nostalgia and joy upon returning to Japan and reuniting with her mother. She is focused on reconnecting with her past and sharing it with her family.', NULL, NULL, NULL, 'Wife of the narrator, mother of the son, and daughter of the grandmother.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
