INSERT INTO public.entity_scene_appearances VALUES (1954, 755, 167, 'ally', true, NULL, 'Moves from a state of quiet, internal obsession to one of firm, unwavering determination to pursue his dangerous wormhole theory, acknowledging but dismissing the immense risks involved.', NULL, NULL, NULL, 'Husband to his wife, father to his son. He persuades them to accept his dangerous new project.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:57:02.220804-05', '2026-02-27 15:57:02.220804-05');
INSERT INTO public.entity_scene_appearances VALUES (1955, 1786, 167, 'ally', true, NULL, 'Her state shifts from concern over her husband''s quietness to deep apprehension and unease about his plan. She ultimately resigns herself to his determination and agrees to support him, despite her fears.', NULL, NULL, NULL, 'Wife of the narrator, mother of their son. Acts as a voice of caution and reason.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:57:02.220804-05', '2026-02-27 15:57:02.220804-05');
INSERT INTO public.entity_scene_appearances VALUES (1956, 96, 167, 'ally', true, NULL, 'Moves from quiet observation to voicing direct concern and fear about the safety of his father''s plan, questioning the potential for catastrophic failure.', NULL, NULL, 'Enters the conversation to question the safety of the wormhole project.', 'Son of the narrator and his wife.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:57:02.220804-05', '2026-02-27 15:57:02.220804-05');
INSERT INTO public.entity_scene_appearances VALUES (1958, 2012, 167, 'neutral', false, NULL, NULL, NULL, NULL, 'Introduced by the narrator as the connection between the shrine''s gateway and graduate-level physics.', 'The central idea driving the scene''s conflict and resolution.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:57:02.220804-05', '2026-02-27 15:57:02.220804-05');
