INSERT INTO public.entity_scene_appearances VALUES (1998, 755, 171, 'ally', true, 'Physically and mentally exhausted from relentless work, drenched in sweat.', 'Cycles from resolve and frustration through a dream-state epiphany to triumphant, playful relief, tinged with a horrifying realization of past danger.', NULL, NULL, NULL, 'The creator and operator of the ERB, Infinitron, and Nanites. He views Entropy as his personal nemesis.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:00:57.945069-05', '2026-02-27 16:00:57.945069-05');
INSERT INTO public.entity_scene_appearances VALUES (1999, 2055, 171, 'neutral', true, NULL, NULL, NULL, NULL, 'Activated repeatedly by the narrator in his attempts to achieve stability.', 'The subject of the narrator''s obsession. Its stability is opposed by Entropy and enabled by the Gateway Structures.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:00:57.945069-05', '2026-02-27 16:00:57.945069-05');
INSERT INTO public.entity_scene_appearances VALUES (2000, 2056, 171, 'mini-boss', true, NULL, NULL, NULL, 'Temporarily overcome by the creation of the symmetrical Gateway Structures.', 'Manifests with every failed attempt to stabilize the portal.', 'The primary antagonist to the narrator''s goal of creating a stable ERB.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:00:57.945069-05', '2026-02-27 16:00:57.945069-05');
INSERT INTO public.entity_scene_appearances VALUES (2001, 2057, 171, 'neutral', false, NULL, NULL, NULL, NULL, 'Recalled by the narrator as he begins his cycle of refinement.', 'Acts as a source of motivation for the Narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:00:57.945069-05', '2026-02-27 16:00:57.945069-05');
INSERT INTO public.entity_scene_appearances VALUES (2002, 2058, 171, 'neutral', false, NULL, NULL, NULL, NULL, 'Appears to the narrator in a vivid dream when he is exhausted.', 'The solution to the problem posed by Entropy.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:00:57.945069-05', '2026-02-27 16:00:57.945069-05');
INSERT INTO public.entity_scene_appearances VALUES (2003, 2059, 171, 'neutral', false, NULL, NULL, NULL, NULL, 'Appears in a vivid dream, providing the key insight.', 'The design inspiration for the Gateway Structures.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:00:57.945069-05', '2026-02-27 16:00:57.945069-05');
