INSERT INTO public.entity_scene_appearances VALUES (2010, 221, 172, 'ally', true, NULL, 'Patient and educational, using a moment of casual stargazing to connect with his son through scientific concepts. He is amused by his son''s playful defensiveness and proud when he sparks genuine wonder.', NULL, NULL, NULL, 'Father to the Son. He acts as a teacher and guide in this scene, fostering his son''s curiosity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:01:50.513606-05', '2026-02-27 16:01:50.513606-05');
INSERT INTO public.entity_scene_appearances VALUES (2011, 473, 172, 'ally', true, NULL, 'Begins with a typical teenage mix of playful defiance and skepticism. His attitude shifts to piqued interest and finally to genuine wonder as he grasps the profound concepts his father explains.', NULL, NULL, NULL, 'Son of the Narrator. He challenges his father''s instructions but is ultimately receptive to his teachings.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:01:50.513606-05', '2026-02-27 16:01:50.513606-05');
