INSERT INTO public.entity_scene_appearances VALUES (2054, 2110, 176, 'neutral', true, NULL, NULL, NULL, 'Subsides into triumphant satisfaction after the successful reunion.', 'Manifests as soon as the narrator bursts through his front door.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 16:05:13.20571-05', '2026-02-27 16:05:13.20571-05');
