INSERT INTO public.entity_scene_appearances VALUES (2057, 1371, 177, 'neutral', true, 'The tome has a cracked leather cover and weathered pages. It actively pulses with a sinister energy, beckoning to the child, and unleashes a putrid stench of dust and musk when opened.', NULL, NULL, NULL, 'Found by The Child in the abandoned library.', 'The catalyst for the summoning of The Narrator (Keeper of Secrets).', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:06:15.207484-05', '2026-02-27 16:06:15.207484-05');
