INSERT INTO public.entity_scene_appearances VALUES (2065, 221, 178, 'ally', true, 'Once a powerful ruler, now feels like a powerless pawn witnessing an apocalyptic future. Their hands are covered in blood, though its origin is uncertain.', 'Flooded with terrifying visions, experiencing visceral dread, hopelessness, and fracturing sanity under the weight of inevitable cosmic collapse.', NULL, NULL, NULL, 'Acts as a brief, hopeless protector to the Blood-stained Child; is the primary victim of the Brutal Visions and the psychological torment of S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2066, 159, 178, 'enemy', false, 'Revealed through visions as a cosmically destructive force with an insatiable thirst for domination, reducing cities to ash and shattering minds. Its hunger is described as relentless and all-consuming.', NULL, NULL, NULL, NULL, 'The primary antagonist, responsible for the destruction witnessed by the Narrator and the terror of the Blood-stained Child.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2067, 2124, 178, 'neutral', true, NULL, NULL, NULL, NULL, 'Floods the narrator''s mind at the start of the scene.', 'A medium through which S Corp''s destructive nature is revealed to the Narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2068, 2125, 178, 'neutral', true, NULL, NULL, NULL, NULL, 'Observed by the narrator while walking through the ravaged city.', 'Victims of S Corp''s destruction.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2069, 2126, 178, 'neutral', true, NULL, NULL, NULL, NULL, 'Stumbles into the narrator''s path in the ruined city.', 'A symbol of lost innocence and a victim of S Corp; seeks comfort from the Narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2070, 2127, 178, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Become apparent as the source of the noise and smoke dominating the vision.', 'The physical manifestation of S Corp''s destructive engine.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2071, 2128, 178, 'enemy', true, NULL, NULL, NULL, NULL, 'Permeates the air of the ravaged city.', 'A direct byproduct of the S Corp Factories.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2072, 2129, 178, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifests when the narrator looks at the clinging child and knows any words of comfort would be lies.', 'An emotional response to the overwhelming power of S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2073, 2130, 178, 'enemy', false, NULL, NULL, NULL, NULL, 'Realized by the narrator as the final outcome of the current conflict.', 'The ultimate goal or result of S Corp''s hunger.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
INSERT INTO public.entity_scene_appearances VALUES (2074, 2131, 178, 'neutral', true, NULL, NULL, NULL, NULL, 'Occurs as the narrator accepts their inability to fight the inevitable.', 'A direct consequence of the narrator''s exposure to S Corp''s actions.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:07:02.241781-05', '2026-02-27 16:07:02.241781-05');
