INSERT INTO public.entity_scene_appearances VALUES (2084, 2142, 179, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Pose existential threat to the narrator''s ventures and the Infinitron''s operations.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:20:25.637792-05', '2026-02-27 19:20:25.637792-05');
