INSERT INTO public.entity_scene_appearances VALUES (2254, 755, 190, 'ally', true, NULL, 'Starts off humorous and paternal, but shifts to contemplative and slightly unnerved as he considers the real-world implications of his newfound wealth and the powerful forces it might attract.', 'Fiddles with his Masonic ring.', NULL, NULL, 'Husband to his wife, father to his son. He is a member of the Freemasons.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:36:31.08963-05', '2026-02-27 19:36:31.08963-05');
