INSERT INTO public.entity_scene_appearances VALUES (2267, 2328, 191, 'ally', true, NULL, NULL, NULL, NULL, 'Created by the narrator to solve the problem of acquiring physical properties for the S Corp.', 'Serve the S Corp and The Narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:37:19.726648-05', '2026-02-27 19:37:19.726648-05');
