INSERT INTO public.entity_scene_appearances VALUES (2272, 2333, 191, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifests as the reason for acquiring a ''perfect symbol'' like the skyscraper.', 'An attribute of the S Corp and The Narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:37:19.726648-05', '2026-02-27 19:37:19.726648-05');
