INSERT INTO public.entity_scene_appearances VALUES (2240, 2300, 191, 'neutral', true, NULL, NULL, NULL, 'They presumably close after the RELMs pass through.', 'Created as the method for deploying the RELMs on their missions.', 'A tool created by The Narrator via the ERBs.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:34:24.735892-05', '2026-02-27 19:37:19.726648-05');
INSERT INTO public.entity_scene_appearances VALUES (2275, 755, 192, 'ally', true, NULL, 'Moves from mild annoyance at the ''wasted space'' to amusement with his family''s ideas, and finally to pride and confidence as he activates the nanites to build their headquarters.', NULL, NULL, NULL, 'Husband to The Narrator''s Wife and father to The Narrator''s Son. He is the leader of The S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2276, 1786, 192, 'ally', true, NULL, 'Pragmatic and visionary, she is focused on making the sterile space functional and presentable, showing strategic foresight about potential media scrutiny.', NULL, NULL, NULL, 'Wife of The Narrator and mother of The Narrator''s Son. She acts as a key strategic partner in planning the headquarters.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2277, 96, 192, 'ally', true, NULL, 'Playful and tech-savvy, he views the empty space through the lens of internet culture and gaming. His attitude shifts to mesmerized awe upon witnessing the nanite transformation.', NULL, NULL, NULL, 'Son of The Narrator and The Narrator''s Wife.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2278, 2297, 192, 'neutral', true, 'The building is transformed from an immaculate but empty and sterile shell into a fully-realized, functional headquarters with one-way glass, new walls, floors, and designated spaces like lounges and workstations.', NULL, NULL, NULL, NULL, 'Serves as the headquarters for The S Corp and the canvas for the family''s vision.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2280, 1183, 192, 'neutral', true, NULL, NULL, NULL, NULL, 'The son pulls it out to start recording the eerie headquarters.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2281, 2342, 192, 'ally', true, NULL, NULL, NULL, 'The vision is fulfilled when the narrator deploys the nanites to make it a reality.', 'Begins with the wife''s suggestion for plants and grows as each family member contributes ideas.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2282, 2343, 192, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by the son as the intended users of a proposed game room.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2283, 1212, 192, 'neutral', true, NULL, NULL, NULL, NULL, 'The narrator connects to it to initiate the transformation of the building.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2284, 1847, 192, 'ally', true, NULL, NULL, NULL, 'Their work is completed, transforming the empty void into a functional space.', 'Activated by the narrator via the Infinitron to build the headquarters.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2285, 1623, 192, 'ally', false, NULL, NULL, NULL, NULL, 'The narrator names the company when his son expresses awe at the nanite transformation.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.entity_scene_appearances VALUES (2286, 2297, 193, 'neutral', true, 'The skyscraper has been transformed from an empty building into a fully functional, modern corporate headquarters for The S Corp, complete with offices, labs, and newly constructed subfloors.', NULL, 'Now contains modern office furniture, lab equipment, jungle plants, human-like robots, and a network of Permanent ERB Gateways in its subfloors.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:39:02.867922-05', '2026-02-27 19:39:02.867922-05');
