INSERT INTO public.entity_scene_appearances VALUES (2320, 2381, 195, 'ally', true, NULL, 'Their skepticism dissolves into disbelief and then palpable excitement and hunger for collaboration after the demonstration.', NULL, 'Leave the meeting with their imaginations ignited, eager to form a partnership.', 'Arrive at the Houston meeting room for the clandestine presentation.', 'Represent their respective companies (UPS, FedEx, DHL) in negotiations with the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:40:35.865132-05', '2026-02-27 19:40:35.865132-05');
