INSERT INTO public.entity_scene_appearances VALUES (2365, 292, 199, 'ally', true, 'Ceases to exist as an individual, becoming a mindless extension of the Cosmic Deity.', 'Shifts from dread to a perverse ecstasy in death and destruction as a servant.', NULL, 'Consciousness is subsumed by the Cosmic Deity, effectively ending their individual existence.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:43:55.646305-05', '2026-02-27 19:43:55.646305-05');
