INSERT INTO public.entity_scene_appearances VALUES (2408, 2472, 204, 'ally', true, 'Shifts focus from pure research to human resources, recognizing the limitations of his AI-driven setup and taking desperate measures to recruit a key scientist.', 'Experiences a rollercoaster of emotions: intellectual clarity, frustration with recruitment, desperation, tense anticipation, and finally a surge of relief and excitement.', NULL, NULL, NULL, 'Leads the Infinitron and Robots. Seeks out and successfully recruits Morgan, a former high school acquaintance.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_scene_appearances VALUES (2409, 1212, 204, 'neutral', true, 'Its function is expanded from a research tool to a cross-dimensional recruitment engine, sifting through alternate realities to find the perfect candidate.', NULL, NULL, NULL, NULL, 'A key tool used by the protagonist to overcome the failure of traditional recruitment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_scene_appearances VALUES (2410, 2474, 204, 'ally', false, NULL, NULL, NULL, NULL, 'Identified by the Infinitron''s search across alternate realities and contacted by the protagonist via Facebook.', 'Agrees to join The S Corp as Chief Scientist, becoming a key ally to the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_scene_appearances VALUES (2411, 2475, 204, 'neutral', false, NULL, NULL, NULL, NULL, 'Realized by the protagonist as the crucial missing element in his research facility.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_scene_appearances VALUES (2412, 2476, 204, 'enemy', false, NULL, NULL, NULL, 'Overcome by using the Infinitron for an unconventional search.', 'Initiated after the protagonist realizes the need for human minds.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
