INSERT INTO public.entity_scene_appearances VALUES (2415, 2479, 204, 'neutral', false, NULL, NULL, NULL, NULL, 'Chosen as the medium to contact Morgan after she is identified by the Infinitron.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_scene_appearances VALUES (2416, 2375, 204, 'neutral', true, 'Their tireless precision and buzzing sense of purpose serve as a stark contrast to the missing human element the protagonist seeks to add to the facility.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.entity_scene_appearances VALUES (2417, 1094, 204, 'neutral', false, 'Actively searched by the Infinitron as a repository of potential talent, shifting from a theoretical concept to a practical, albeit vast, hiring pool.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
