INSERT INTO public.entity_scene_appearances VALUES (2420, 2484, 205, 'ally', true, NULL, NULL, NULL, NULL, 'The narrator is present from the beginning of the scene, describing the recruitment and construction efforts they are leading.', 'Oversees the ''Scientists and their Families'' and built ''The Antarctic Secondary Habitat''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
