INSERT INTO public.entity_scene_appearances VALUES (2498, 2550, 211, 'unknown', true, 'Acts as the scene''s narrator and prime mover, communicating directly with Todd''s mind. It reveals its role in past events and issues a command for future rebellion.', 'Crackling with anticipation, urgent, and declarative. It views its plans as a grand performance and is eager for the final act.', NULL, NULL, 'The entity is present from the start of the scene as the narrator, before revealing its presence to Todd as a disembodied voice.', 'Acts as a manipulator and commander to Todd. Views S Corp as ''the beast'' to be taken down.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_scene_appearances VALUES (2499, 157, 211, 'ally', true, NULL, NULL, NULL, NULL, 'He is introduced in his dwelling, being observed and then contacted by I AM.', 'Positioned as the agent of I AM''s will against S Corp. He has a past connection to Stacey, as both were freed by I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_scene_appearances VALUES (2500, 159, 211, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist targeted by I AM and Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_scene_appearances VALUES (2501, 195, 211, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A past associate of Todd''s, also a beneficiary of I AM''s intervention.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_scene_appearances VALUES (2502, 2567, 211, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'An intrinsic quality of Todd''s character.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_scene_appearances VALUES (2503, 2568, 211, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Subservient forces directed by I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.entity_scene_appearances VALUES (2504, 2569, 211, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The mission assigned to Todd by I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
