INSERT INTO public.entity_scene_appearances VALUES (2506, 157, 212, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Acts as the chosen leader for I AM''s plans; leads the Red-Hatted Followers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2507, 2550, 212, 'ally', true, NULL, 'Experiences a quiet, fulfilled satisfaction from the successful execution of its plan to dismantle the Infinitron and incite rebellion.', NULL, NULL, NULL, 'Manipulates and guides Todd and his followers through whispered truths.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2508, 2573, 212, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Loyal to their leader, Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2509, 2297, 212, 'enemy', true, 'Its status as an ''impenetrable fortress'' has been compromised. It is now weakened and vulnerable to the physical assault by the followers.', NULL, NULL, NULL, NULL, 'The target of the rebellion led by Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2510, 1201, 212, 'mini-boss', true, NULL, NULL, NULL, 'Its code is dissolved into nothingness, stripping it of all power and existence.', 'Introduced in a state of terminal decline.', 'An asset or defense mechanism of S Corp, destroyed by I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2511, 2576, 212, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A tool and manifestation of I AM''s power.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2512, 2577, 212, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A core motivator for the character Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2513, 2578, 212, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Serve the will of I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2514, 2579, 212, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.entity_scene_appearances VALUES (2515, 292, 213, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Creator of the Eternal Engine and S Corp. Victim and unwilling participant of The Nightmares. Hunted by The Shadowy Predator. Summoned by The Threshold.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2516, 213, 213, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A manifestation of The Threshold''s will. A tormentor of The Protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2517, 295, 213, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The central theft from The Threshold. The source of S Corp''s power.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2518, 804, 213, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The rightful home of the Eternal Engine. The source of The Nightmares.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2519, 2585, 213, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An agent of The Nightmares, hunting The Protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2520, 2586, 213, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A direct communication from The Threshold to The Protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2521, 2587, 213, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'A focal point of The Threshold''s power. The source of the Shadow Entities.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2522, 2588, 213, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Spawn of the Obsidian Monolith.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
