INSERT INTO public.entity_scene_appearances VALUES (2524, 2590, 213, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A corrupted memory and symbol of the protagonist''s initial transgression.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2525, 2591, 213, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A creation of S Corp that acts as a tether to the Obsidian Monolith.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2526, 2297, 213, 'neutral', false, 'Mentioned as the protagonist''s technological empire, built upon the stolen Eternal Engine. It is now seen not as an achievement but as a transgression that is drawing the nightmares closer.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.entity_scene_appearances VALUES (2527, 982, 213, 'enemy', true, 'Appears as the formless chaos of the dream realm from which the monolith rises. It is an active force that seeps into the protagonist, dissolving his sense of self and merging with his consciousness.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
