INSERT INTO public.entity_scene_appearances VALUES (2529, 2595, 214, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'His condition is negatively impacting his family (wife and son). He seeks help from Dr. Pai M. On but feels invalidated by her.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
