INSERT INTO public.entity_scene_appearances VALUES (2540, 292, 215, 'ally', true, NULL, NULL, NULL, NULL, 'The scene opens with him already trapped in the crimson void during a dream.', 'Targeted by ''I AM''. Rescued and warned by Lady I and Lady A.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_scene_appearances VALUES (2541, 2550, 215, 'mini-boss', true, 'Manifests physically as a writhing, chaotic mass of limbs and eyes that seems to consume the fabric of the void. Its voice is a cacophony of whispers and screams.', 'Expresses mocking fury and possessiveness, accusing the protagonist of stealing its ''souls''.', NULL, 'Forced to recoil and retreat by the appearance and power of Lady I and Lady A.', 'Confronts the protagonist at the start of the dream.', 'Views the protagonist as a ''slave'' and a thief.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_scene_appearances VALUES (2542, 2608, 215, 'ally', true, NULL, NULL, NULL, NULL, 'Materializes in the void to save the protagonist from ''I AM''.', 'Acts as a rescuer and guide to the protagonist, alongside Lady A.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.entity_scene_appearances VALUES (2543, 2609, 215, 'ally', true, NULL, NULL, NULL, NULL, 'Appears alongside Lady I to intervene in the confrontation.', 'Acts as a rescuer and a stern mentor to the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
