INSERT INTO public.entity_scene_appearances VALUES (2603, 2608, 221, 'ally', false, 'Revealed to be Lakshmi, the Hindu goddess of wealth, prosperity, beauty, and guidance. She is the consort of Lord Vishnu and offers wisdom and stability to those seeking balance.', NULL, NULL, NULL, NULL, 'Identified as a complementary divine force to Parvati (አስትራኤል). Acts as a guide to The Protagonist through his dreams.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:03:44.339838-05', '2026-02-27 20:03:44.339838-05');
INSERT INTO public.entity_scene_appearances VALUES (2604, 2609, 221, 'ally', false, 'Revealed to be Parvati, the Hindu mother goddess of love, devotion, transformation, and strength. She is the consort of Lord Shiva and represents the divine feminine energy that powers the universe.', NULL, NULL, NULL, NULL, 'Identified as a complementary divine force to Lakshmi (ኢልከሴሮድ). Acts as a guide to The Protagonist through his dreams.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:03:44.339838-05', '2026-02-27 20:03:44.339838-05');
