INSERT INTO public.entity_scene_appearances VALUES (2650, 1525, 226, 'ally', true, NULL, NULL, NULL, NULL, 'The scene opens with The Dreamer pushing deeper into the dreamscape.', 'Rescued by አስትራኤል, who acts as a mentor and guide. Antagonized by the Winged Archangels.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:08:16.383368-05', '2026-02-27 20:08:16.383368-05');
INSERT INTO public.entity_scene_appearances VALUES (2651, 2609, 226, 'ally', true, 'Appears as an ethereal form shrouded in an aura of ancient knowledge, exuding profound authority.', 'Stern and compassionate, delivering a firm warning to The Dreamer.', NULL, NULL, 'Materializes to rescue The Dreamer from the archangels when all hope seems lost.', 'Acts as a savior and mentor to The Dreamer, chastising his arrogance while ensuring his safety.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:08:16.383368-05', '2026-02-27 20:08:16.383368-05');
INSERT INTO public.entity_scene_appearances VALUES (2652, 2721, 226, 'neutral', true, NULL, NULL, NULL, NULL, 'The setting for the protagonist''s reckless explorations.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:08:16.383368-05', '2026-02-27 20:08:16.383368-05');
INSERT INTO public.entity_scene_appearances VALUES (2653, 2722, 226, 'enemy', true, NULL, NULL, NULL, 'They hesitate and cease their attack upon the arrival of አስትራኤል.', 'Emerge from the Void Portal to punish The Dreamer for his transgression.', 'Guardians of the Dreamscape, acting as antagonists to The Dreamer.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:08:16.383368-05', '2026-02-27 20:08:16.383368-05');
