INSERT INTO public.entity_scene_appearances VALUES (2655, 2724, 226, 'neutral', true, NULL, NULL, NULL, NULL, 'Lady A transports The Dreamer here to save him.', 'A domain of አስትራኤል.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:08:16.383368-05', '2026-02-27 20:08:16.383368-05');
INSERT INTO public.entity_scene_appearances VALUES (2656, 2725, 226, 'enemy', true, NULL, NULL, NULL, 'Is replaced by humility and clarity after the near-death experience.', 'Drives the protagonist''s actions from the beginning of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:08:16.383368-05', '2026-02-27 20:08:16.383368-05');
INSERT INTO public.entity_scene_appearances VALUES (2657, 2726, 226, 'ally', true, NULL, NULL, NULL, NULL, 'Emerges within The Dreamer''s mind as he reflects on his near downfall in the Sanctuary Realm.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:08:16.383368-05', '2026-02-27 20:08:16.383368-05');
INSERT INTO public.entity_scene_appearances VALUES (2658, 2727, 226, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned as having been ignored by the protagonist in his hubris.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:08:16.383368-05', '2026-02-27 20:08:16.383368-05');
