INSERT INTO public.entity_scene_appearances VALUES (2661, 2730, 227, 'ally', true, NULL, NULL, NULL, NULL, 'Is pulled into the training realm by Lady A to begin his lessons.', 'Student and protégé of አስትራኤል (Lady A).', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:09:10.308532-05', '2026-02-27 20:09:10.308532-05');
INSERT INTO public.entity_scene_appearances VALUES (2662, 2609, 227, 'ally', true, 'Her presence is described as a commanding blend of allure and dread. Later, she appears luminous as she bestows the protagonist''s new title.', 'Displays exacting sternness as a teacher, which shifts to approval and pride upon her student''s success.', NULL, NULL, 'Initiates the scene by bringing the protagonist to the training realm.', 'Mentor to Aspolin.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:09:10.308532-05', '2026-02-27 20:09:10.308532-05');
