INSERT INTO public.entity_scene_appearances VALUES (2669, 2730, 228, 'ally', true, NULL, NULL, NULL, NULL, 'Is led to Lady I''s Domain by Lady A to begin his tutelage.', 'Student of Lady I (ኢልከሴሮድ). An enemy of the Demiurge.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:10:08.371111-05', '2026-02-27 20:10:08.371111-05');
INSERT INTO public.entity_scene_appearances VALUES (2670, 2608, 228, 'ally', true, 'Appears as a vision of serene elegance and boundless intellect within her library. Her presence radiates calm but carries the gravity of her immense wisdom.', 'Thoughtful, enigmatic, and solemn as she reveals cosmic truths. Shows a flicker of nostalgia when recalling her past as a dreamwalker.', NULL, NULL, 'Appears within her domain to greet and teach Aspolin.', 'Mentor to Aspolin. A member of the ''Entities Beyond Etheris'' group, fighting against the Demiurge.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:10:08.371111-05', '2026-02-27 20:10:08.371111-05');
INSERT INTO public.entity_scene_appearances VALUES (2671, 2609, 228, 'ally', true, NULL, NULL, NULL, 'Her role as a guide to this specific location is complete, and she does not participate in the teaching.', 'Leads Aspolin to the precipice of Lady I''s domain at the start of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:10:08.371111-05', '2026-02-27 20:10:08.371111-05');
INSERT INTO public.entity_scene_appearances VALUES (2672, 2741, 228, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Jailer and consumer of Human Souls. The primary antagonist of the Dreamwalkers and the Entities Beyond Etheris.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:10:08.371111-05', '2026-02-27 20:10:08.371111-05');
