INSERT INTO public.entity_scene_appearances VALUES (2854, 2919, 246, 'ally', true, 'She appears physically unchanged, but her actions are controlled by an external force while she sleepwalks.', 'Moves from contemplative comfort to a state of subconscious compulsion, acting without awareness. She later returns to normal with no memory of the event, implying a state of confusion upon discovering the recording.', 'Carries her phone, using it to record the event without conscious intent.', 'Returns to her home and bed after the mass event concludes, with her memory of it erased.', 'Starts the scene in her bed, contemplating recent events before falling asleep.', 'She is a victim of the ''Unseen Compulsion'' and a participant in the ''Crowd of Sleepwalkers''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:25:51.408193-05', '2026-02-27 20:25:51.408193-05');
INSERT INTO public.entity_scene_appearances VALUES (2855, 2921, 246, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned in Aditi''s thoughts as a source of comfort and grounding advice.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:25:51.408193-05', '2026-02-27 20:25:51.408193-05');
INSERT INTO public.entity_scene_appearances VALUES (2856, 2930, 246, 'enemy', true, NULL, NULL, NULL, 'The influence breaks suddenly, releasing the crowd from its control.', 'Manifests in Aditi''s room as she sleeps, initiating the sleepwalking event.', 'Controls Aditi and the Crowd of Sleepwalkers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:25:51.408193-05', '2026-02-27 20:25:51.408193-05');
INSERT INTO public.entity_scene_appearances VALUES (2857, 2931, 246, 'enemy', true, NULL, NULL, NULL, 'Disperses and shuffles back home after the controlling spell breaks.', 'Emerge from their homes across the city to join the mass procession.', 'Victims of the ''Unseen Compulsion''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:25:51.408193-05', '2026-02-27 20:25:51.408193-05');
INSERT INTO public.entity_scene_appearances VALUES (2858, 2932, 246, 'neutral', true, NULL, NULL, NULL, 'Remains with Aditi as she returns home, holding the only record of what transpired.', 'Aditi is compelled to pick it up from her bedside table as she begins to sleepwalk.', 'Used by the compelled Aditi to record the Crowd of Sleepwalkers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:25:51.408193-05', '2026-02-27 20:25:51.408193-05');
INSERT INTO public.entity_scene_appearances VALUES (2859, 2933, 246, 'neutral', false, NULL, NULL, NULL, NULL, 'Becomes the target of the crowd''s synchronized pointing.', 'The destination indicated by the Crowd of Sleepwalkers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:25:51.408193-05', '2026-02-27 20:25:51.408193-05');
