INSERT INTO public.entity_scene_appearances VALUES (2873, 2919, 248, 'ally', true, 'Becomes the focal point of an amateur investigation into the sleepwalking phenomenon she was part of.', 'Moves from initial confusion about her own involvement to determined curiosity and late-night contemplation, feeling a connection between the disparate clues.', NULL, NULL, NULL, 'Leader of her group of friends (Meera, Raj, Neha) investigating the mystery.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:27:23.550079-05', '2026-02-27 20:27:23.550079-05');
INSERT INTO public.entity_scene_appearances VALUES (2874, 2945, 248, 'ally', true, 'The group coalesces into a team of ''amateur detectives'', actively researching the mystery surrounding the sleepwalking video.', 'Their collective mood shifts from excitement and disbelief to serious, focused investigation, tinged with unease.', NULL, NULL, NULL, 'Comprised of Meera, Raj, and Neha, who support and challenge Aditi''s theories.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:27:23.550079-05', '2026-02-27 20:27:23.550079-05');
