INSERT INTO public.entity_scene_appearances VALUES (2950, 3027, 255, 'ally', true, NULL, NULL, NULL, NULL, 'Enters the scene by replying to Dr. S''s email.', 'A key part of ''All Staff'', led by Dr. S.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:33:32.630472-05', '2026-02-27 20:33:32.630472-05');
