INSERT INTO public.entity_scene_appearances VALUES (2953, 3025, 256, 'neutral', true, 'This group is now involved with the operation or use of space elevators, necessitating a specific safety reminder about this new technology.', NULL, NULL, NULL, 'Appear as the recipients of the safety email.', 'Subordinate to the ''Safety Team'' in matters of protocol.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:34:07.024254-05', '2026-02-27 20:34:07.024254-05');
