INSERT INTO public.entity_scene_appearances VALUES (2958, 3035, 257, 'neutral', true, NULL, NULL, NULL, NULL, 'Initiates the scene by sending a company-wide email about the banana incident.', 'A professional, collegial relationship with other S Corp departments like the Research Team and All Staff.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:34:36.900961-05', '2026-02-27 20:34:36.900961-05');
