INSERT INTO public.entity_scene_appearances VALUES (3012, 2550, 263, 'ally', true, NULL, 'Begins in a state of quiet contemplation, observing Earth''s deceptive unity. Becomes assertive and persuasive during the negotiation, and concludes with a sense of momentary relief tempered by lingering doubt about the future of the alliance.', NULL, NULL, NULL, 'Serves as the lead negotiator for S Corp, directly confronting the concerns of the Chinese Representative and persuading the delegates.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:39:22.750481-05', '2026-02-27 20:39:22.750481-05');
