INSERT INTO public.entity_scene_appearances VALUES (3030, 2550, 265, 'ally', true, NULL, 'Calm, confident, and persuasive, acting as the voice and negotiator for S Corp''s grand proposal.', NULL, NULL, NULL, 'Acts as the primary representative of S Corp, directly addressing the various national delegations.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:40:52.563712-05', '2026-02-27 20:40:52.563712-05');
