INSERT INTO public.entity_scene_appearances VALUES (3032, 3111, 265, 'neutral', true, NULL, NULL, NULL, NULL, 'Approaches the narrator after a previous group, bringing a palpable shift in the room''s energy.', 'The primary audience and target of S Corp''s proposal.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:40:52.563712-05', '2026-02-27 20:40:52.563712-05');
