INSERT INTO public.entity_scene_appearances VALUES (3041, 2550, 266, 'ally', true, NULL, 'Assertive, reassuring, and diplomatic, aiming to build trust and consensus among skeptical national representatives.', NULL, NULL, NULL, 'Acts as the primary negotiator and representative for S Corp, addressing the concerns of the Japanese and Korean delegates.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:41:44.9079-05', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_scene_appearances VALUES (3042, 3121, 266, 'neutral', true, NULL, NULL, NULL, NULL, 'Is present at the meeting to discuss the implications of S Corp''s global initiatives.', 'Acts as a primary questioner, voicing concerns on behalf of nations worried about military escalation and regional instability.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:41:44.9079-05', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_scene_appearances VALUES (3043, 3122, 266, 'neutral', true, NULL, NULL, NULL, NULL, 'Is present at the meeting to understand the new global framework proposed by S Corp.', 'Works alongside the Japanese Representative to scrutinize S Corp''s plans, eventually agreeing that bold measures are needed.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:41:44.9079-05', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_scene_appearances VALUES (3044, 3123, 266, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Their actions, particularly Russia''s involvement in the Ukraine conflict, are cited as the reason for the delegates'' skepticism.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:41:44.9079-05', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_scene_appearances VALUES (3045, 2297, 266, 'ally', true, 'In this scene, S Corp is presented not just as a corporation but as a neutral, planetary-incorporated entity with interstellar stewardship as its guiding principle, capable of enforcing its own terms.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:41:44.9079-05', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_scene_appearances VALUES (3046, 3125, 266, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifests as soon as the narrator approaches the delegates, stemming from the geopolitical reality of the missing nations.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:41:44.9079-05', '2026-02-27 20:41:44.9079-05');
