INSERT INTO public.entity_scene_appearances VALUES (3049, 3128, 266, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned in the first sentence as the group the narrator is leaving to speak with the Japanese and Korean representatives.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:41:44.9079-05', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_scene_appearances VALUES (3050, 3129, 266, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:41:44.9079-05', '2026-02-27 20:41:44.9079-05');
INSERT INTO public.entity_scene_appearances VALUES (3051, 2550, 267, 'ally', true, NULL, 'Observant and resolute, acting as a facilitator to seize a historic opportunity for diplomacy. Expresses a philosophy of incremental trust-building.', NULL, NULL, 'Already present, observing the delegates.', 'Acts as a mediator and supporter for the Israeli and Iranian delegates, leveraging S Corp''s resources to foster collaboration.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:42:35.074234-05', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_scene_appearances VALUES (3052, 3131, 267, 'neutral', true, NULL, NULL, NULL, NULL, 'Observed standing near the Israeli delegate in a neutral setting.', 'Historical adversary of the Israeli Delegate, but proposes a new collaborative relationship through the Regional Working Group.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:42:35.074234-05', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_scene_appearances VALUES (3053, 3132, 267, 'neutral', true, NULL, NULL, NULL, NULL, 'Observed standing near the Iranian delegate in a neutral setting.', 'Historical adversary of the Iranian Delegate, but shows willingness to engage in dialogue for mutual benefit.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:42:35.074234-05', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_scene_appearances VALUES (3054, 3133, 267, 'neutral', false, NULL, NULL, NULL, NULL, 'Proposed by the Iranian Delegate as a way to bridge divides.', 'The subject of agreement between the Israeli and Iranian delegates, supported by S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:42:35.074234-05', '2026-02-27 20:42:35.074234-05');
INSERT INTO public.entity_scene_appearances VALUES (3055, 2297, 267, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned by the narrator as a source of support for the new diplomatic initiative.', 'Pledged by the narrator to provide technology, resources, and facilitation for the Regional Working Group.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:42:35.074234-05', '2026-02-27 20:42:35.074234-05');
