INSERT INTO public.entity_scene_appearances VALUES (3103, 157, 272, 'mini-boss', true, NULL, NULL, NULL, 'Arrested by police and taken away in a transport vehicle.', 'Positioned within the crowd, preparing to launch an attack.', 'Accomplice of Stacey and member of the Red Hats. Views S Corp and ''I AM'' as opposing forces.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:47:15.516651-05', '2026-02-27 20:47:15.516651-05');
