INSERT INTO public.entity_scene_appearances VALUES (3105, 3186, 272, 'neutral', true, NULL, NULL, NULL, NULL, 'Gathered in the plaza to witness the culmination of S Corp''s broadcast.', 'Audience to both S Corp''s broadcast and the Red Hats'' attack.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:47:15.516651-05', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_scene_appearances VALUES (3106, 2554, 272, 'enemy', true, NULL, NULL, NULL, 'Neutralized by the Environmental Shields and arrested by the police.', 'Embedded within the crowd, awaiting the signal to attack.', 'Enemies of S Corp. Todd and Stacey are members.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:47:15.516651-05', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_scene_appearances VALUES (3107, 3188, 272, 'neutral', true, NULL, NULL, NULL, 'Wrenched from Todd''s grip by an unseen force and clatters uselessly to the ground.', 'Concealed in Todd''s jacket at the start of the scene.', 'Weapon belonging to Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:47:15.516651-05', '2026-02-27 20:47:15.516651-05');
INSERT INTO public.entity_scene_appearances VALUES (3108, 3189, 272, 'ally', true, NULL, NULL, NULL, 'Dissolves swiftly once the attackers are secured by police.', 'Activates instantly in response to Todd firing his gun.', 'A creation of Patrick, used to defend S Corp and the crowd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:47:15.516651-05', '2026-02-27 20:47:15.516651-05');
