INSERT INTO public.entity_scene_appearances VALUES (3110, 3191, 272, 'neutral', true, 'Is completely crushed and replaced by hollow disbelief and futility by the end of the scene.', NULL, NULL, 'Extinguished by the overwhelming reality of S Corp''s technological superiority.', 'Present within Todd as he prepares to act.', 'The primary motivation for Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:47:15.516651-05', '2026-02-27 20:47:15.516651-05');
