INSERT INTO public.entity_scene_appearances VALUES (3149, 2003, 277, 'neutral', true, NULL, NULL, NULL, 'The Habitat passes through it, and it is no longer the focus of the scene.', 'Appears as the final threshold for The Habitat''s journey.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:15.613926-05', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_scene_appearances VALUES (3150, 3222, 277, 'neutral', true, 'Its distant azure light illuminates the new alien planet, refracting through crystalline formations.', NULL, NULL, NULL, NULL, 'The primary light source for the Uncharted Alien Planet.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:15.613926-05', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_scene_appearances VALUES (3151, 3233, 277, 'ally', true, NULL, NULL, NULL, NULL, 'Are revealed inside The Habitat after the doors open.', 'Yukiko is one of The Pioneers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:15.613926-05', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_scene_appearances VALUES (3152, 3197, 277, 'ally', true, NULL, NULL, NULL, NULL, 'Is among The Pioneers watching from the viewing windows.', 'A member of The Pioneers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:15.613926-05', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_scene_appearances VALUES (3153, 3235, 277, 'neutral', true, NULL, NULL, NULL, NULL, 'Revealed as a prominent feature of the landscape when The Habitat''s doors open.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:15.613926-05', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_scene_appearances VALUES (3154, 3236, 277, 'neutral', true, NULL, NULL, NULL, NULL, 'Arises from The Pioneers as they prepare to witness the new world.', 'A manifestation of The Pioneers'' collective emotional state.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:15.613926-05', '2026-02-27 20:51:15.613926-05');
INSERT INTO public.entity_scene_appearances VALUES (3155, 3197, 278, 'ally', true, NULL, NULL, NULL, NULL, 'Descends a ramp to be the first to set foot on the alien soil.', 'Older sister to Takashi and daughter to her mother.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.entity_scene_appearances VALUES (3156, 3214, 278, 'ally', true, NULL, NULL, NULL, NULL, 'Emerge onto the alien planet''s surface after Yukiko.', 'A close-knit family unit exploring a new world together.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
