INSERT INTO public.entity_scene_appearances VALUES (3164, 3247, 279, 'ally', true, NULL, NULL, NULL, 'Disperses with the other conspirators after a plan is forged, heavy with the weight of their decision.', 'Enters the hidden chamber to convene a secret meeting to plot against S Corp.', 'Leader of The Conspirators and The Church; an ally of Todd and the Gaunt Entity; has a direct relationship with I AM, who appeared to him.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_scene_appearances VALUES (3165, 2550, 279, 'ally', true, 'Manifests as a presence at the head of the table, having first appeared to the Pope in the flames of a burning brazier. The darkness around this being thrums with otherworldly energy.', 'Authoritative and decisive. Believes subtlety has failed and advocates for direct, heart-striking attacks against S Corp.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.entity_scene_appearances VALUES (3319, 3399, 290, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Led by Governor Tanaka; home to Yukiko and her family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:04:30.698348-05', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.entity_scene_appearances VALUES (3166, 2297, 279, 'enemy', false, 'Described as a corrupting force that has warped humanity for five years, tightening its grip on the world and growing fat on desperation. Its influence is the target of the conspiracy.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
