INSERT INTO public.entity_scene_appearances VALUES (4685, 3993, 411, 'ally', true, NULL, 'Knowingly risks his life by drinking poisoned tea, driven by a complex mix of love, reckless faith, and perhaps a self-destructive curiosity about Jamie''s intentions. He is fully engaged in their mutual deception, acknowledging the lies and truths in their relationship.', NULL, NULL, NULL, 'Engaged in a dangerous, intimate, and paradoxical relationship with Jamie, where love and attempted murder coexist. He is the target of her demonic mission but also the object of her genuine affection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.entity_scene_appearances VALUES (3259, 3251, 287, 'enemy', true, NULL, NULL, NULL, NULL, 'Spotted moving with eerie precision in an overgrown grove.', 'Followers of ''I AM''; antagonists to Yukiko and the colony.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:49:45.487062-05', '2026-02-28 16:49:45.487062-05');
