INSERT INTO public.entity_scene_appearances VALUES (3239, 3197, 285, 'ally', true, NULL, NULL, NULL, NULL, 'The scene opens with her gazing out her window, reflecting on her life on Sorhhinda.', 'Daughter of the chief scientist and an ex-JSDF veteran. Best friends with Hana on Earth. A resident of the S Corp colony.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:48:23.054078-05', '2026-02-28 17:00:43.766725-05');
