INSERT INTO public.entity_scene_appearances VALUES (3249, 3197, 286, 'ally', true, NULL, NULL, NULL, NULL, 'Enters the scene by venturing outside the colony dome to chase a butterfly.', 'A resident of the colony, now a witness to the dangers outside its dome.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:49:10.388814-05', '2026-02-28 17:01:40.164761-05');
