INSERT INTO public.entity_scene_appearances VALUES (3298, 3197, 288, 'ally', true, 'Acts with frantic precision and desperation, showing tactical improvisation skills.', 'Moves from fear to steely resolve, then to adrenaline-fueled focus, and finally to fleeting relief followed by dawning horror.', 'Carries a pack with tools and a scanner flashlight, which she uses as a weapon.', NULL, NULL, 'Acts as a protector of The Gateway and the ERB Network against the Terrorists.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:03:05.215709-05', '2026-02-28 17:03:05.215709-05');
