INSERT INTO public.entity_scene_appearances VALUES (3309, 3197, 289, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Deeply connected to her family on Earth, whose memory gives her the strength to make a great sacrifice. She is now the person responsible for the colony''s isolation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:03:48.96191-05', '2026-02-28 17:03:48.96191-05');
INSERT INTO public.entity_scene_appearances VALUES (3310, 3396, 289, 'enemy', true, NULL, NULL, NULL, 'Destroyed in the gateway''s collapse after Yukiko enters the emergency deactivation code.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:03:48.96191-05', '2026-02-28 17:03:48.96191-05');
