INSERT INTO public.entity_scene_appearances VALUES (3411, 2884, 298, 'ally', true, NULL, NULL, NULL, NULL, 'Sitting in his office, observing a troubling data anomaly.', 'Employee of S Corp; architect of ''The Great Unburdening''; adversary to the ''Red Hats''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_scene_appearances VALUES (3412, 159, 298, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned as TJ''s employer and the entity whose efficiency reports contain the anomaly.', 'The governing/corporate power over New Atlantis and humanity''s current way of life.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_scene_appearances VALUES (3413, 3501, 298, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears as a blinking red indicator on TJ''s data stream, having grown from a whisper to a ''full-throated roar'' in the data over six months.', 'A symptom of the discontent fostered by The Great Unburdening and linked to the rise of the Red Hats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_scene_appearances VALUES (3414, 3502, 298, 'neutral', false, NULL, NULL, NULL, NULL, 'Recalled by TJ as the historical context for the current societal problems.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_scene_appearances VALUES (3416, 3504, 298, 'neutral', true, NULL, NULL, NULL, NULL, 'The central focus of TJ''s attention and the tool for his critical decision.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_scene_appearances VALUES (3417, 326, 298, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned in TJ''s reflection on the societal impact of The Great Unburdening.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_scene_appearances VALUES (3418, 3506, 298, 'neutral', false, NULL, NULL, NULL, NULL, 'Its lights are refracted through the domed ceiling of TJ''s office.', 'The setting for the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_scene_appearances VALUES (3415, 2554, 298, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.entity_scene_appearances VALUES (3420, 2599, 299, 'mini-boss', true, NULL, NULL, NULL, 'Abruptly ends the conversation after dismissing TJ''s concerns as baseless, stating the situation will be monitored.', 'Enters TJ''s office to inquire about a report he filed concerning a deviation in projections.', 'TJ''s superior at S Corp. She acts as an institutional antagonist, suppressing his warnings.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_scene_appearances VALUES (3421, 2884, 299, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A subordinate to Dr. On. He is the protagonist of the scene, attempting to warn S Corp of a looming crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_scene_appearances VALUES (3422, 3077, 299, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The employer of both TJ and Dr. On. It represents the institutional power structure that TJ is trying to warn.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_scene_appearances VALUES (3423, 3511, 299, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The catalyst for the scene; the physical evidence of TJ''s concerns.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_scene_appearances VALUES (3424, 3512, 299, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.entity_scene_appearances VALUES (3425, 2554, 299, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'An external threat that feeds on the internal problems TJ has identified.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
