INSERT INTO public.entity_scene_appearances VALUES (3428, 2884, 300, 'ally', true, NULL, NULL, NULL, NULL, 'Observes the fallout from the Red Hats'' propaganda attack and S Corp''s flawed response.', 'Implicitly an antagonist to S Corp''s leadership, like Dr. On, due to his dissenting views.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3429, 2617, 300, 'neutral', true, NULL, NULL, NULL, NULL, 'Mentioned as part of S Corp''s official response to the crisis.', 'A leader within S Corp, opposed to the Red Hats, and dismissive of warnings from people like TJ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
