INSERT INTO public.entity_scene_appearances VALUES (3430, 2554, 300, 'enemy', true, NULL, NULL, NULL, NULL, 'Their escalating activities are reported, setting the scene''s conflict.', 'The primary antagonistic force against S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3432, 159, 300, 'neutral', true, NULL, NULL, NULL, NULL, 'Responds to the Red Hat attacks with crackdowns and denial.', 'The ruling power, opposed by the Red Hats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3433, 3294, 300, 'neutral', true, NULL, NULL, NULL, NULL, 'Deployed in response to the Red Hats'' propaganda attack.', 'An instrument of S Corp''s power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3434, 3522, 300, 'neutral', true, NULL, NULL, NULL, NULL, 'Hijacked by the Red Hats to display their message.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3435, 3523, 300, 'enemy', true, NULL, NULL, NULL, 'Scrubbed by S Corp Security Forces.', 'Appears suddenly on all holographic displays, marking a major escalation in the conflict.', 'A tool created and used by the Red Hats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3436, 3524, 300, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned as part of the intelligence reports on escalating Red Hat activity.', 'An aspect of the Red Hat Zealots'' activities.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3437, 3525, 300, 'neutral', true, NULL, NULL, NULL, NULL, 'Realized by TJ as he observes the events unfolding.', 'A representation of S Corp''s weakening power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3431, 3519, 300, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.entity_scene_appearances VALUES (3439, 2919, 301, 'ally', true, NULL, 'Experiences a mix of hope for her future and unease about the societal inequality she''s leaving behind. She feels conflicted about S Corp''s role and worries about her brother''s potential involvement with the Red Hats.', 'Carries her Elysium University ID card.', NULL, NULL, 'Daughter of former coal-mining family members. Sister of Rahul. Scholarship student at Elysium University.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_scene_appearances VALUES (3440, 2591, 301, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_scene_appearances VALUES (3441, 159, 301, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Target of the Red Hats'' protests. Aditi''s benefactor via their universal education programs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.entity_scene_appearances VALUES (3442, 2554, 301, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Led by the Red Hat Leader. Potentially includes Aditi''s brother, Rahul.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
