INSERT INTO public.entity_scene_appearances VALUES (3450, 2919, 302, 'ally', true, 'Her Earth clothes are described as ''threadbare,'' a stark contrast to her peers'' designer silks. She later wears a replicated S Corp intern uniform.', 'Aditi feels alienated and like an outsider upon arrival. After being insulted, she experiences a sharp sting of humiliation which she channels into fierce determination.', 'She exchanges her ''threadbare Earth clothes'' for a ''replicated S Corp intern uniform''.', NULL, NULL, 'She is a student of Professor Nakamura and a target of scorn from her Elysian Peers, particularly Arun.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_scene_appearances VALUES (3451, 3540, 302, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'They are peers of Aditi whom they look down upon.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_scene_appearances VALUES (3452, 3541, 302, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Appears in an advanced astrophysics class to challenge Aditi.', 'A peer of Aditi who acts as her primary social antagonist in the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_scene_appearances VALUES (3453, 3542, 302, 'neutral', true, NULL, NULL, NULL, NULL, 'Replicated to solve Aditi''s ''attire problem''.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_scene_appearances VALUES (3454, 3543, 302, 'enemy', true, NULL, NULL, NULL, NULL, 'Uttered by Arun in an advanced astrophysics class.', 'Weaponized by Arun against Aditi.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_scene_appearances VALUES (3455, 3544, 302, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Teacher to Aditi and Arun.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_scene_appearances VALUES (3456, 3545, 302, 'neutral', true, NULL, NULL, NULL, NULL, 'Triggered by Arun''s ''Dalit speculation'' comment.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
