INSERT INTO public.entity_scene_appearances VALUES (3458, 3548, 302, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.entity_scene_appearances VALUES (3459, 2919, 303, 'ally', true, NULL, 'Overwhelmed by guilt, helplessness, and longing for her family. She feels the oppressive weight of her promises and the cold indifference of her new home on Elysium.', NULL, NULL, 'The scene opens with Aditi staring out her window at Earth, already in a state of melancholy.', 'Daughter to Aditi''s Mother and Aditi''s Father; sister to Rahul. She feels a deep, painful responsibility for their well-being.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3460, 2921, 303, 'ally', true, 'Appears via hologram looking thinner, with hollow cheeks and eyes rimmed with exhaustion.', 'Expresses a mixture of maternal warmth, deep weariness, and desperation. She is clinging to the fragile hope that Aditi can save them from their worsening situation on Earth.', NULL, 'The hologram transmission degrades and the call ends.', 'Appears as a flickering hologram when Aditi activates the terminal.', 'Mother to Aditi and Rahul; wife to Aditi''s Father. She is the emotional anchor for the family left on Earth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3461, 824, 303, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Aditi''s current home, but it serves as a gilded cage, mocking her inability to bring her family there.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3462, 2253, 303, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Aditi''s homeworld and the location of her family. It is a source of both longing and guilt for her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3463, 3553, 303, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The sole, fragile link between Aditi and her family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3464, 3554, 303, 'mini-boss', false, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist and obstacle in the scene, representing the systemic injustice Aditi is up against.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3465, 3555, 303, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Aditi''s father, whose declining health adds urgency to the family''s desire to leave Earth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3466, 2920, 303, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Aditi''s brother, whose absence is a source of pain and mystery.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3467, 245, 303, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An internal antagonist that plagues Aditi throughout the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3468, 3558, 303, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A direct consequence of Aditi''s interaction with her mother and her conflict with The Waitlist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.entity_scene_appearances VALUES (3469, 3559, 303, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
