INSERT INTO public.entity_scene_appearances VALUES (3470, 2919, 304, 'ally', true, NULL, 'Aditi''s state shifts from focused tranquility to shock and adrenaline-fueled urgency upon receiving the signal, which then evolves into serious concern and suspicion.', NULL, NULL, NULL, 'Student or junior researcher to Professor Nakamura. She trusts him enough to immediately report the dangerous anomaly.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.entity_scene_appearances VALUES (3471, 3544, 304, 'ally', true, NULL, NULL, NULL, NULL, 'Aditi rushes to his domicile to show him the strange signal.', 'Aditi''s superior and confidant regarding the anomalous signal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
