INSERT INTO public.entity_scene_appearances VALUES (3479, 2919, 305, 'ally', true, 'She is intensely focused on uncovering a conspiracy, displaying a fiery resolve that convinces Hiro to join her reckless plan.', 'A mix of anxiety and fierce determination. She feels the weight of the unfolding mystery but is resolute in her decision to act.', NULL, NULL, NULL, 'Relies on Hiro as a trusted technical expert and confidant, leveraging their shared rebellious spirit to push him into action.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.entity_scene_appearances VALUES (3480, 3570, 305, 'ally', true, NULL, NULL, NULL, NULL, 'Is present at the start of the scene, already working with Aditi on the mysterious data.', 'A close friend and ally to Aditi, bonded through a shared class and mindset. He acts as her technical counterpart.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
