INSERT INTO public.entity_scene_appearances VALUES (3491, 2297, 305, 'enemy', false, 'Revealed to be hiding a secret database containing blueprints for impossible faster-than-light technology, positioning S Corp as a keeper of dangerous secrets.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
