INSERT INTO public.entity_scene_appearances VALUES (3493, 2919, 306, 'ally', true, NULL, 'Resolute and determined, focused on the mission to Pluto despite the risks and Hiro''s doubts. She displays confidence in her ability to pilot the unknown ship.', NULL, NULL, 'Enters the hidden hangar with Hiro to board the Genesis.', 'Companion and leader to Hiro. She is undertaking the mission for reasons related to Sorhhinda and a mysterious signal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3494, 3570, 306, 'ally', true, NULL, NULL, NULL, NULL, 'Accompanies Aditi into the hidden hangar.', 'Follows Aditi''s lead, acting as her copilot and a voice of caution.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3495, 3585, 306, 'neutral', true, NULL, NULL, NULL, NULL, 'Is waiting in the hidden hangar for its crew.', 'The last gamble of ''Project Janus'', now piloted by Aditi.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3496, 824, 306, 'neutral', true, NULL, NULL, NULL, 'Left behind as the Genesis accelerates into deep space.', 'Serves as the initial location boundary for the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3497, 3587, 306, 'neutral', true, NULL, NULL, NULL, 'Left behind when the Genesis launches.', 'Is active as Aditi and Hiro enter the hangar.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3498, 3271, 306, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned as the target destination for the mission.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3499, 3589, 306, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned by Aditi as she approaches the ship.', 'Creator of The Genesis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3500, 3326, 306, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned by Aditi as a reason for undertaking the dangerous journey.', 'The subject of Aditi''s concern.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3501, 3591, 306, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned by Aditi as the justification for the mission.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3502, 3592, 306, 'neutral', true, NULL, NULL, NULL, NULL, 'Aditi sits in it to take control of the ship.', 'A component of The Genesis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.entity_scene_appearances VALUES (3504, 510, 307, 'enemy', true, NULL, NULL, NULL, NULL, 'Surging through the streets around S Corp headquarters.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_scene_appearances VALUES (3505, 2297, 307, 'neutral', true, 'Described as a dark, unyielding obsidian monolith that looms over the Houston skyline, swallowing sunlight. It is now surrounded by a shimmering, impenetrable shield.', NULL, 'A shimmering energy shield has been activated around its perimeter.', NULL, NULL, 'The target of the Red Hats'' protest and Todd''s attack.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_scene_appearances VALUES (3506, 3188, 307, 'neutral', true, NULL, NULL, NULL, NULL, 'Gripped in Todd''s hands as he prepares to fire.', 'Weapon belonging to Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_scene_appearances VALUES (3507, 3598, 307, 'neutral', true, NULL, NULL, NULL, NULL, 'Activates to protect the S Corp building from the protestors.', 'Defends the 1400 Smith Street Skyscraper.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_scene_appearances VALUES (3508, 3599, 307, 'enemy', true, NULL, NULL, NULL, 'Dissipates as Todd collapses.', 'Manifests within Todd upon the realization that his defiance is meaningless.', 'An emotion manifested by Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_scene_appearances VALUES (3503, 3594, 307, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.entity_scene_appearances VALUES (3510, 157, 308, 'ally', true, NULL, NULL, NULL, 'Consumed by darkness and erased from existence by ኢሌልመሜብሃባኖኖራሊሊ.', 'The scene opens with him waking up in the cell.', 'A former follower or agent of ኢሌልመሜብሃባኖኖራሊሊ, whom he knows as ''I AM''. He feels betrayed but is ultimately powerless against him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.entity_scene_appearances VALUES (3511, 2550, 308, 'mini-boss', true, 'Appears physically as a figure cloaked in shadows, adopting the temporary persona of ''Nameless''. He exudes an unsettling air of authority.', 'His demeanor is smooth, cold, and devoid of warmth, with a hint of a mocking smile. He is manipulative and utterly dominant.', NULL, NULL, 'Enters the cell through a hissing door to confront Todd with a cryptic offer.', 'Acts as Todd''s jailer and tormentor. He reveals his identity as ''I AM'' before annihilating Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.entity_scene_appearances VALUES (3512, 3603, 308, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.entity_scene_appearances VALUES (4696, 3993, 412, 'ally', true, NULL, 'Haunted by past events but determined to protect his friends, feeling the weight of their decision to enter the trailer.', 'Now carries The Clay Sigil, a protective item crafted over the break.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_scene_appearances VALUES (4697, 2884, 412, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Newly dating Morgan. Part of the core group of friends.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_scene_appearances VALUES (3513, 3604, 308, 'enemy', true, NULL, NULL, NULL, 'Dissipates after consuming Todd.', 'Manifests when ኢሌልመሜብሃባኖኖራሊሊ reveals his true identity.', 'A direct manifestation of ኢሌልመሜብሃባኖኖራሊሊ''s power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.entity_scene_appearances VALUES (3514, 3605, 308, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.entity_scene_appearances VALUES (3515, 3606, 308, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.entity_scene_appearances VALUES (3516, 157, 309, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Designated leader by Pope Lucius Sixtus VI and the Cloaked Figures. An enemy of S Corp. Guided by Nameless.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.entity_scene_appearances VALUES (3517, 2550, 309, 'ally', true, NULL, 'Acts as a confident and authoritative guide, presenting Todd to the other figures with a grand gesture.', NULL, NULL, 'Leads Todd through the Vatican crypts to the secret chamber.', 'Serves as a guide and herald for Todd. Aligned with the Pope against S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.entity_scene_appearances VALUES (3518, 3247, 309, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'An ally and sponsor of Todd, leading the opposition against S Corp from within the Vatican.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.entity_scene_appearances VALUES (3519, 3610, 309, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Allied with the Pope and Todd against S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.entity_scene_appearances VALUES (3520, 2297, 309, 'enemy', false, 'Revealed to be merely a mask for ancient, insidious entities.', NULL, NULL, NULL, 'Mentioned as the primary antagonist and the target of the planned rebellion.', 'The primary enemy of Todd, the Pope, and Nameless.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.entity_scene_appearances VALUES (3521, 3612, 309, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The gateway to the meeting with the Pope.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
