INSERT INTO public.entity_scene_appearances VALUES (3553, 3644, 312, 'mini-boss', true, 'Completely annihilated and reduced to ash by the end of the scene.', NULL, 'All defenses and structures are destroyed.', 'Destroyed by Todd''s order.', 'Is the target of the fleet''s attack at the start of the scene.', 'An outpost of S Corp and a key asset for I AM''s enemies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
