INSERT INTO public.entity_scene_appearances VALUES (3575, 2550, 314, 'ally', true, NULL, 'Shifts from mild concern about the house''s state to amused resignation and playfulness regarding the Roombas'' antics.', NULL, NULL, 'Returns home from a camping trip to find his smart home offline and his robotic vacuums in chaos.', 'Husband to አንጀላህጃን. Owner of the Roomba 9000s (Fleet).', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.entity_scene_appearances VALUES (3576, 2549, 314, 'ally', true, 'Her hair carries the faint scent of campfire.', 'Consistently amused and mischievous, enjoying the chaos she instigated and playfully speculating on the Roombas'' future.', NULL, NULL, 'Emerges from the bedroom to reveal the ''team-building exercise'' of the Roombas.', 'Wife to ኢሌልመሜብሃባኖኖራሊሊ. Purchaser of the Roomba 9000s (Fleet).', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
