INSERT INTO public.entity_scene_appearances VALUES (3586, 2550, 315, 'ally', true, NULL, 'His initial suffocating calm shatters into panic and dread upon receiving the news. He masks this with forced composure for his family, but by the end of the scene, he is gripped by primal fear and the weight of his responsibilities.', NULL, NULL, NULL, 'Husband to The Wife of ኢሌልመሜብሃባኖኖራሊሊ and father to The Son of ኢሌልመሜብሃባኖኖራሊሊ. He is the leader of the Emergency Response Team.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.entity_scene_appearances VALUES (3587, 3679, 315, 'ally', true, NULL, NULL, NULL, 'Remains in the hallway as his father returns to the command center.', 'Appears at his father''s office doorway after portaling from university, sensing trouble.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
