INSERT INTO public.entity_scene_appearances VALUES (3618, 2550, 317, 'ally', true, NULL, 'Initially an ''island in a sea of panic'', his shock turns to seething fury during the confrontation with Todd, culminating in a cold, unyielding resolve to eradicate his enemies.', NULL, NULL, NULL, 'Leader of S Corp and its advisors (Patrick, Gil, TJ). Primary antagonist to Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_scene_appearances VALUES (3619, 157, 317, 'mini-boss', false, NULL, NULL, NULL, 'Disconnects after delivering his final message of judgment.', 'Appears on the main screen in the war room after the destruction of S Corp assets.', 'Leader of the Red Hat rebellion and servant of ''the Almighty''. Views S Corp and its leader as demonic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_scene_appearances VALUES (3620, 159, 317, 'ally', true, 'Previously seen as invulnerable titans of technology, their illusion of safety is shattered by the Red Hats'' successful attack, revealing significant vulnerabilities and internal betrayal.', 'The organization''s leadership is plunged from confidence into chaos, panic, and dread.', NULL, NULL, NULL, 'The organization led by the narrator, now under direct assault by the Red Hat rebellion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_scene_appearances VALUES (3621, 3652, 317, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Led by Todd. Antagonistic to S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_scene_appearances VALUES (3622, 2617, 317, 'enemy', false, NULL, NULL, NULL, 'Disappeared from S Corp headquarters during the attack.', 'Mentioned after the confrontation with Todd, when it''s discovered she has disappeared.', 'A mole for the Red Hat rebellion within S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.entity_scene_appearances VALUES (3623, 2896, 317, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Advisor to ኢሌልመሜብሃባኖኖራሊሊ. In strategic disagreement with TJ and Gil.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
