INSERT INTO public.entity_scene_appearances VALUES (3628, 3722, 317, 'neutral', false, NULL, NULL, NULL, NULL, 'Its destruction is displayed on the war room screens, triggering the scene''s events.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
