INSERT INTO public.entity_scene_appearances VALUES (3631, 2550, 318, 'ally', true, NULL, 'Moves from a state of panicked uncertainty and feeling suffocated to grim determination after articulating the need to eliminate the enemy. He admits his fear and acknowledges the failure of his security systems, grounding his new resolve in harsh reality.', NULL, 'Leaves after a tense but intimate goodbye with his wife, now set on his course of action.', 'The scene opens with him walking down the hallway, consumed by panic.', 'Husband to አንጀላህጃን; primary target and opponent of Todd and his cult.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_scene_appearances VALUES (3632, 2549, 318, 'ally', true, NULL, 'Begins pale and worried, then becomes skeptical and confrontational, demanding the truth. She ends the scene in a state of grim acceptance of the necessary violence, her primary concern shifting to her husband''s survival.', NULL, 'Remains in the hallway after saying goodbye, her grip lingering on the narrator''s arm.', 'Emerges from the shadows of the hallway, nearly colliding with her husband.', 'Wife of ኢሌልመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_scene_appearances VALUES (3633, 157, 318, 'mini-boss', false, NULL, NULL, NULL, NULL, NULL, 'Leader of Todd''s Cult; primary antagonist to the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_scene_appearances VALUES (3634, 3728, 318, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Followers of Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.entity_scene_appearances VALUES (3635, 3729, 318, 'enemy', true, NULL, NULL, NULL, 'Subsides into grim resolve by the end of the scene after he decides on a course of action.', 'Present at the start of the scene as the narrator walks down the hallway.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
