INSERT INTO public.entity_scene_appearances VALUES (3642, 2550, 319, 'ally', true, NULL, 'Feels the immense pressure of leadership and the threat of madness from cosmic truths, but projects strength and conviction for his team and the public. After the broadcast, he is exhausted and privately feels the chill of uncertainty about the future.', NULL, 'Returns home via a portal after the broadcast is complete.', 'The scene opens with him feeling the weight of his responsibilities before gathering his team.', 'Leader of the S Corp Crisis Team. Husband to አንጀላህጃን and father to The Narrator''s Son.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_scene_appearances VALUES (3643, 3737, 319, 'ally', true, NULL, NULL, NULL, 'Disperses after the broadcast is successfully completed.', 'Already gathered in the briefing room when the narrator arrives.', 'Subordinate to and reliant on ኢሌልመሜብሃባኖኖራሊሊ for leadership.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.entity_scene_appearances VALUES (3644, 2882, 319, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the S Corp Crisis Team, advising ኢሌልመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
