INSERT INTO public.entity_scene_appearances VALUES (3654, 2550, 320, 'ally', true, NULL, 'Moves from a state of embattled leadership to dawning horror and dread. He realizes the rebellion is a supernatural corruption, not just a political movement, leaving him feeling powerless as he watches the chaos unfold.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
