INSERT INTO public.entity_scene_appearances VALUES (3714, 2919, 325, 'ally', false, 'She has been found but is now gravely injured after taking a direct hit during an attack. Her condition is critical and she requires immediate advanced medical care.', 'Unconscious and in a stabilized but critical medical state.', NULL, NULL, NULL, 'The focus of the rescue mission led by Morgan and overseen by The Commander. Was accompanied by Hiro.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.entity_scene_appearances VALUES (3715, 2474, 325, 'ally', true, NULL, NULL, NULL, 'The comm line goes quiet after she confirms her understanding of the new orders.', 'Appears via a comms call to report the status of the rescue mission.', 'Reports to The Commander; was the rescuer of Aditi and Hiro.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
