INSERT INTO public.entity_scene_appearances VALUES (3726, 2919, 326, 'ally', true, NULL, 'Calm and steady, despite recounting a harrowing experience. Her expression turns somber when detailing the enemy''s plans.', NULL, NULL, NULL, 'Briefs Patrick and the narrator (ኢሌልመሜብሃባኖኖራሊሊ) on the Red Hats'' tactics. Credits Hiro with helping her decode transmissions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3727, 2896, 326, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'An ally of Aditi and the narrator, working with them to understand the Red Hat threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3728, 2550, 326, 'ally', true, NULL, 'Calm but intent, gritting his teeth as the pieces of the enemy''s plan click into place.', NULL, NULL, NULL, 'Leads the debriefing, questioning Aditi to understand the full scope of the threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3729, 3570, 326, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Collaborated with Aditi to decipher the enemy''s plans.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3730, 2554, 326, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The primary antagonists, whose tactics are being revealed by Aditi.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3731, 3826, 326, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The medium for the Red Hats'' psychological attacks.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3732, 3827, 326, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The primary payload of the Red Hats'' shortwave broadcasts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3733, 3828, 326, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'A key component of the Red Hats'' strategy to create ''walking infection vectors''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3734, 2296, 326, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'An S Corp technology unwittingly being used against them by the Red Hats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3736, 3831, 326, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The system that was bypassed by the Red Hats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.entity_scene_appearances VALUES (3737, 3832, 326, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The tool that enabled the discovery of the Red Hats'' plans.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
