INSERT INTO public.entity_scene_appearances VALUES (3740, 2550, 327, 'ally', true, NULL, 'Experiences a brief moment of triumph that is quickly replaced by a gnawing unease and deep suspicion regarding the sudden victory. His mood shifts to sharp, firm resolve as he warns Morgan of a greater, unseen threat.', NULL, NULL, NULL, 'Leader/colleague to Morgan. Victor over the Red Hats. Senses a new, looming threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.entity_scene_appearances VALUES (3741, 2554, 327, 'enemy', false, NULL, NULL, NULL, 'All activity and signals disappeared suddenly and completely, without a clear cause, which is the central mystery of the scene.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
