INSERT INTO public.entity_scene_appearances VALUES (3761, 2550, 329, 'ally', true, NULL, 'Experiences a profound sense of existential dread and loneliness upon realizing the universe is empty of intelligent life. His initial fear of hidden enemies is replaced by the horror of absolute solitude.', NULL, NULL, NULL, 'Leader and colleague to Morgan. He voices the central existential question of the scene and reflects on humanity''s journey and fears.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_scene_appearances VALUES (3762, 2474, 329, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A long-time colleague of the narrator, sharing in the monumental discoveries and the subsequent existential crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_scene_appearances VALUES (3763, 326, 329, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The collective group to which the narrator and Morgan belong.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_scene_appearances VALUES (3764, 3860, 329, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The primary source of humanity''s initial fear and the guiding principle behind their cautious expansion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_scene_appearances VALUES (3765, 3861, 329, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The subject of Morgan''s initial, exciting discovery.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_scene_appearances VALUES (3766, 3862, 329, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The ultimate setting and antagonist of the scene, replacing the fear of the Dark Forest with the horror of being alone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_scene_appearances VALUES (3767, 3863, 329, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Serves as proof that life is abundant, making the absence of intelligent life all the more profound and unsettling.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.entity_scene_appearances VALUES (3768, 3864, 329, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The intellectual puzzle that gives rise to theories like the Dark Forest Hypothesis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
