INSERT INTO public.entity_scene_appearances VALUES (3771, 2550, 330, 'ally', true, NULL, 'Experiences a mix of pride and melancholy on his 300th birthday. He is warmed by his family''s presence but is deeply troubled by unseen threats to his empire, feeling the weight of his legacy and the uncertainty of the future.', NULL, NULL, NULL, 'Great-great-great-grandfather to Stellan and patriarch of the family. He is the founder and leader of S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_scene_appearances VALUES (3772, 3868, 330, 'ally', true, NULL, NULL, NULL, NULL, 'Enters the room with his family to surprise the narrator for his birthday.', 'Great-great-great-grandson of the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_scene_appearances VALUES (3773, 3869, 330, 'ally', true, NULL, NULL, NULL, NULL, 'Enters with Stellan and the rest of the family.', 'Wife of Stellan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_scene_appearances VALUES (3774, 3870, 330, 'ally', true, NULL, NULL, NULL, NULL, 'Scamper into the room as part of the birthday surprise.', 'Great-great-great-great-grandchildren of the narrator; grandchildren of Stellan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.entity_scene_appearances VALUES (3775, 3871, 330, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The narrator is the founder and CEO. Stellan holds a high-ranking position within it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
