INSERT INTO public.entity_scene_appearances VALUES (3784, 2550, 331, 'ally', true, NULL, 'Experiences a severe psychological breakdown, characterized by paranoia, perceptual distortion, and the feeling that reality is a fragile illusion. His state degrades from anxious suspicion to outright terror as he becomes a conduit for the entity ''I AM''.', NULL, NULL, NULL, 'Father of Stellan and grandfather to ''The Grandchildren''. He is being overwhelmed and seemingly possessed by the cosmic entity ''I AM (The Watching Presence)''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.entity_scene_appearances VALUES (3785, 3868, 331, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Son of ኢሌልመሜብሃባኖኖራሊሊ and father of ''The Grandchildren''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
