INSERT INTO public.entity_scene_appearances VALUES (3787, 3883, 331, 'mini-boss', true, NULL, NULL, NULL, NULL, 'First sensed as an unseen observer, it is named by the narrator and then fully manifests its presence, dominating the scene''s reality.', 'Acts as the primary antagonist, overwhelming the narrator (ኢሌልመሜብሃባኖኖራሊሊ) and threatening his family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
