INSERT INTO public.entity_scene_appearances VALUES (3791, 982, 331, 'neutral', true, 'Visible through the room''s window, the galaxies within it are described as dimming ''as if an unseen hand had closed around them'' during the manifestation of ''I AM''.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
