INSERT INTO public.entity_scene_appearances VALUES (3793, 2550, 332, 'ally', true, NULL, 'Begins in a state of extreme panic and terror after waking from a nightmare. This shifts to anxious contemplation as he discusses the dream''s meaning, and finally settles into a sense of resolve to seek help.', NULL, NULL, 'Wakes up from a recurring nightmare at the start of the scene.', 'Husband to አንጀላህጃን. Considers seeking counsel from Patrick. Plagued by the Humanoid Ants in his Nightmares.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:44:16.483489-05', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_scene_appearances VALUES (3881, 2550, 339, 'ally', true, NULL, 'Moves from strategic confidence to grim realization and resolve after a major plan backfires.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:50:16.939793-05', '2026-02-28 17:50:16.939793-05');
INSERT INTO public.entity_scene_appearances VALUES (3794, 2549, 332, 'ally', true, NULL, 'Calm, concerned, and comforting. She acts as a grounding presence for her husband, cutting through his panic with a soft voice and reassuring touch.', NULL, NULL, 'Is woken up by her husband''s thrashing and immediately moves to comfort him.', 'Wife to ኢሌልመሜብሃባኖኖራሊሊ. Suggests he speak with Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:44:16.483489-05', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_scene_appearances VALUES (3795, 3892, 332, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The primary antagonists within the protagonist''s Nightmares.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:44:16.483489-05', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_scene_appearances VALUES (3796, 280, 332, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Manifestation of the protagonist''s stress regarding the S Corp Network Glitches and his neglected Oneiromancy practice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:44:16.483489-05', '2026-02-28 17:44:16.483489-05');
INSERT INTO public.entity_scene_appearances VALUES (3797, 3894, 332, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The suspected real-world cause or correlate of the protagonist''s Nightmares.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:44:16.483489-05', '2026-02-28 17:44:16.483489-05');
