INSERT INTO public.entity_scene_appearances VALUES (3804, 2550, 333, 'ally', true, NULL, 'Experiencing intense, orchestrated nightmares that leave him feeling a sense of dread and urgency. He is convinced these dreams are a signal of a larger, existential threat and is determined to make others see the danger.', NULL, NULL, NULL, 'Long-time acquaintance of Patrick, dating back to high school. He is the one seeking help and providing the crucial, esoteric information about the threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:45:05.519972-05', '2026-02-28 17:45:05.519972-05');
