INSERT INTO public.entity_scene_appearances VALUES (3816, 2550, 334, 'ally', true, NULL, 'Experiences initial fear and anxiety, which escalates into profound shock and terror upon recognizing Todd, causing a loss of consciousness. This is followed by a frantic sense of vindication and panic upon waking.', NULL, NULL, NULL, 'Is assisted by Patrick after fainting. Views Todd as an inevitable, long-feared nemesis whose return confirms his deepest anxieties.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:45:52.320131-05', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_scene_appearances VALUES (3817, 157, 334, 'mini-boss', false, NULL, NULL, NULL, 'The feed and the narrator''s consciousness fade, but he remains a lingering threat.', 'Appears in the center of a security feed from a distant, infected portal.', 'The primary antagonist to the narrator (ኢሌልመሜብሃባኖኖራሊሊ), representing a long-buried but inevitable threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:45:52.320131-05', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_scene_appearances VALUES (3818, 2896, 334, 'ally', true, NULL, NULL, NULL, NULL, 'Appears after the narrator loses consciousness.', 'An ally to the narrator (ኢሌልመሜብሃባኖኖራሊሊ), providing immediate assistance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:45:52.320131-05', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_scene_appearances VALUES (3819, 331, 334, 'neutral', true, 'This specific alarm is part of an ancient defense and monitoring system designed after the Red Hat War to detect preternatural occurrences.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:45:52.320131-05', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_scene_appearances VALUES (3820, 3855, 334, 'neutral', false, 'It is revealed that the network has monitoring stations and equipment integrated into it as a fail-safe against preternatural threats, a legacy of the Red Hat War.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:45:52.320131-05', '2026-02-28 17:45:52.320131-05');
INSERT INTO public.entity_scene_appearances VALUES (3821, 3918, 334, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:45:52.320131-05', '2026-02-28 17:45:52.320131-05');
