INSERT INTO public.entity_scene_appearances VALUES (3827, 2550, 335, 'ally', true, NULL, 'Shifts from dazed fear and panic during the assault to contained frustration and grim determination after being sealed in the bunker.', NULL, NULL, 'Is violently shaken awake by Patrick after passing out.', 'Relies on Patrick and the Security Personnel for survival. Is the target of the evacuation effort. Confirms the return of the antagonist, Todd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_scene_appearances VALUES (3828, 2896, 335, 'ally', true, NULL, NULL, NULL, NULL, 'Appears at the protagonist''s side, reviving them at the start of the attack.', 'Acts as the protagonist''s primary protector and commander of the security team.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_scene_appearances VALUES (3829, 157, 335, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned by the protagonist as the cause of their collapse, confirming his return.', 'The primary antagonist in the protagonist''s mind, whose return heralds the physical assault on the headquarters.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_scene_appearances VALUES (3830, 3927, 335, 'ally', true, NULL, NULL, NULL, 'Sealed inside the bunker with the protagonist and Patrick.', 'Scramble into action as the alarms blare, immediately beginning defensive and evacuation procedures.', 'Serve under Patrick''s command and act as protectors for the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_scene_appearances VALUES (3831, 3928, 335, 'enemy', true, NULL, NULL, NULL, NULL, 'Their presence is announced by explosions and gunfire as they breach the facility''s perimeter.', 'The direct antagonists of the scene, actively trying to kill the security personnel and capture or kill leadership.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_scene_appearances VALUES (3832, 3929, 335, 'enemy', true, NULL, NULL, NULL, NULL, 'Manifests after a powerful explosion cracks the ceiling during the evacuation.', 'A direct consequence of the Enemy Forces'' attack, acting as an environmental weapon.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_scene_appearances VALUES (3833, 3930, 335, 'neutral', true, NULL, NULL, NULL, NULL, 'Serves as the destination for the desperate evacuation effort.', 'The object of salvation for the protagonists, which becomes a tense, claustrophobic sanctuary.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_scene_appearances VALUES (3834, 3931, 335, 'enemy', true, NULL, NULL, NULL, NULL, 'Begin occurring shortly after the sirens start, marking the start of the physical assault.', 'The primary tool of the Enemy Forces'' assault.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
INSERT INTO public.entity_scene_appearances VALUES (3882, 3855, 339, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:50:16.939793-05', '2026-02-28 17:50:16.939793-05');
INSERT INTO public.entity_scene_appearances VALUES (4786, 4913, 418, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'The inspiration for the heroes of ''Elysium Rising''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.entity_scene_appearances VALUES (3835, 2759, 335, 'neutral', true, NULL, NULL, NULL, 'Their sound is cut off when the bunker doors shut.', 'Begin blaring immediately after the protagonist confirms Todd''s return, initiating the chaos.', 'The auditory signal of the start of the assault.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:46:42.009965-05', '2026-02-28 17:46:42.009965-05');
