INSERT INTO public.entity_scene_appearances VALUES (3837, 3934, 336, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Leads Patrick and Officer Anya; considers I AM an ancient, mortal enemy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:47:35.618977-05', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_scene_appearances VALUES (3838, 2896, 336, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Subordinate to Commander Valerius.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:47:35.618977-05', '2026-02-28 17:47:35.618977-05');
