INSERT INTO public.entity_scene_appearances VALUES (3840, 2550, 336, 'enemy', false, NULL, 'His presence is felt as an ancient, omnipotent threat orchestrating the attack, casting a palpable shadow of fear and despair over the room.', NULL, NULL, 'Mentioned as the suspected orchestrator of the facility overrun, elevating the stakes of the conflict immensely.', 'The primary antagonist whose influence is the source of the immediate physical threat and the psychological fear affecting the protagonists.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:47:35.618977-05', '2026-02-28 17:47:35.618977-05');
INSERT INTO public.entity_scene_appearances VALUES (3841, 3938, 336, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:47:35.618977-05', '2026-02-28 17:47:35.618977-05');
