INSERT INTO public.entity_scene_appearances VALUES (3846, 2550, 337, 'ally', true, NULL, 'Shifts from tense resolve to shock and horror during the massacre, before hardening into cold, absolute fury, embracing a strategy of total extermination.', NULL, NULL, NULL, 'Commands the bunker''s forces, including Patrick, Morgan, and the recruit. Views Todd and the Red Hats with vengeful hatred.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3847, 2554, 337, 'enemy', true, NULL, NULL, NULL, NULL, 'Reemerge to launch a devastating, multi-colony assault after being presumed neutralized.', 'Led by Todd. The primary antagonists responsible for the massacre in the bunker.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3848, 157, 337, 'enemy', false, NULL, NULL, NULL, 'His image dissipates after delivering his message.', 'Appears on all bunker monitors to deliver a message just before his forces breach the facility.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3849, 3946, 337, 'enemy', true, NULL, NULL, NULL, NULL, 'Breach the bunker''s defenses, initiating a massacre.', 'The primary ground forces of the Red Hats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3850, 3947, 337, 'enemy', true, NULL, NULL, NULL, NULL, 'Begins immediately after the Red Hat cyborgs breach the bunker.', 'Perpetrated by the Red Hat Cyborgs against the Bunker Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3851, 3948, 337, 'ally', true, NULL, NULL, NULL, 'Largely wiped out during the massacre.', 'Present at the start of the scene, attempting to defend the bunker.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3852, 2896, 337, 'ally', true, NULL, NULL, NULL, NULL, 'Speaks up after the initial shock of the massacre to ask for direction.', 'Subordinate to the Commander (ኢሌልመሜብሃባኖኖራሊሊ) and commander of a special forces captain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3853, 2474, 337, 'ally', true, NULL, NULL, NULL, NULL, 'Storms into the command room to present the EMP device.', 'An ally providing critical support to the Commander.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3854, 3951, 337, 'neutral', true, NULL, NULL, NULL, NULL, 'Brought into the war room by Morgan as a potential tide-turner.', 'A tool to be used against the Red Hat Cyborgs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3855, 3952, 337, 'ally', true, NULL, NULL, NULL, NULL, 'Identifies the cyborgs'' weakness while observing security feeds.', 'A subordinate who proves his worth to the Commander.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3856, 3953, 337, 'ally', true, NULL, NULL, NULL, NULL, 'Steps forward to offer a strategic plan after the Commander gives the mobilization order.', 'Reports to Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3857, 3954, 337, 'ally', true, NULL, NULL, NULL, NULL, 'Declared by the Commander in response to the massacre.', 'The guiding principle for all allied characters at the end of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3858, 3955, 337, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:48:19.751524-05', '2026-02-28 17:48:19.751524-05');
INSERT INTO public.entity_scene_appearances VALUES (3860, 2550, 338, 'ally', true, 'He has transitioned from a corporate leader to a frontline military commander, actively fighting in a brutal war.', 'Experiences extreme exhaustion and desperation, which shifts to focused determination upon discovering the power of Oneiromancy. He becomes a mentor and leader for the new dream warriors.', NULL, NULL, NULL, 'Leads the S Corp Soldiers and the new Oneiromancer Soldiers. Is in direct opposition to Todd, the Red Hats, and I AM. Relies on his subordinate, Gil.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:49:15.053042-05', '2026-02-28 17:49:15.053042-05');
