INSERT INTO public.entity_scene_appearances VALUES (3877, 3974, 339, 'neutral', true, NULL, NULL, NULL, NULL, 'Evolved from a fiery conflict over decades and centuries.', 'The central conflict involving the narrator''s side and the Red Hats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:50:16.939793-05', '2026-02-28 17:50:16.939793-05');
