INSERT INTO public.entity_scene_appearances VALUES (3885, 2550, 340, 'ally', true, NULL, 'Displays strong leadership, cutting through his squad''s weariness with unwavering resolve. He is strategic and philosophical, articulating the nature of their abstract war to inspire his soldiers.', NULL, NULL, NULL, 'Commander of the Dream Squad, responsible for their morale and strategic direction against the enemy force I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:50:55.39588-05', '2026-02-28 17:50:55.39588-05');
