INSERT INTO public.entity_scene_appearances VALUES (3889, 579, 340, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An internal enemy that the Commander and the Dream Squad must overcome.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:50:55.39588-05', '2026-02-28 17:50:55.39588-05');
