INSERT INTO public.entity_scene_appearances VALUES (3891, 3988, 340, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The ultimate target for the Dream Squad''s next mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:50:55.39588-05', '2026-02-28 17:50:55.39588-05');
