INSERT INTO public.entity_scene_appearances VALUES (3895, 3993, 341, 'ally', true, NULL, 'Experiences a shift from desperation to horrified clarity and crushing guilt as he realizes his own actions (claiming the Eternal Engine) unleashed the I AM.', NULL, NULL, NULL, 'Co-creator of the Dream Plane Grimoire with Lady I (ኢልከሴሮድ). Unwittingly freed the I AM (Cosmic Devourer).', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_scene_appearances VALUES (3896, 3994, 341, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist of the Eternal War. Imprisoned by the Cosmic Entities. Worshipped by the Red Hat acolytes. Unwittingly freed by the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_scene_appearances VALUES (3897, 3995, 341, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Includes ኢልከሴሮድ (Lady I), አስትራኤል (Lady A), and ኦሲላሪ (Madam O). They act as jailers to the I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_scene_appearances VALUES (3898, 2536, 341, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
