INSERT INTO public.entity_scene_appearances VALUES (3901, 456, 341, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_scene_appearances VALUES (3902, 326, 341, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_scene_appearances VALUES (3903, 4001, 341, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_scene_appearances VALUES (3904, 2608, 341, 'ally', false, 'Revealed to have secretly co-created the Dream Plane Grimoire with the narrator as a failsafe.', NULL, NULL, NULL, NULL, 'One of the Cosmic Entities who imprisoned the I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_scene_appearances VALUES (3905, 4003, 341, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:52:10.07673-05', '2026-02-28 17:52:10.07673-05');
INSERT INTO public.entity_scene_appearances VALUES (3906, 2550, 342, 'ally', true, NULL, 'Experiences profound horror and despair upon witnessing the fate of Earth and his crew, which eventually hardens into a final, burning defiance against I AM. He becomes the last bastion of humanity''s will to resist.', 'Relies solely on the Infinitron after severing his connection to the S Corp network.', NULL, NULL, 'Captain of the Crew, protected by The Infinitron, and the sole object of I AM''s direct attention in the final moments.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3907, 3970, 342, 'big-boss', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist responsible for the corruption of Earth and the creator of the Obsidian Tower. It directly opposes the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3908, 4007, 342, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The transport for the narrator and his crew.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3909, 982, 342, 'neutral', true, 'The region near the front lines is described as a ''black maw of oblivion'' where the laws of reality are actively cracking under the influence of I AM.', NULL, NULL, NULL, NULL, 'The medium through which the scene''s events unfold.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3910, 4009, 342, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The former home of humanity, now a monument to I AM''s victory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3912, 3619, 342, 'ally', true, NULL, NULL, NULL, 'Corrupted and transformed one by one by the malice emanating from the Obsidian Tower.', NULL, 'Subordinates to the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3913, 4012, 342, 'enemy', true, NULL, NULL, NULL, NULL, 'Manifested as the original crew members were broken by the Obsidian Tower''s influence.', 'Once allies of the narrator, now part of the enemy force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3914, 1201, 342, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The sole reason for the narrator''s survival against the Tower''s corruption.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3915, 4014, 342, 'ally', true, NULL, NULL, NULL, NULL, 'Manifests within the narrator as he rejects the temptation to surrender to I AM.', 'The narrator''s final weapon against I AM''s psychological assault.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3916, 4015, 342, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The initial destination of the Aditi''s Genesis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3911, 4010, 342, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:53:26.778049-05', '2026-02-28 17:53:26.778049-05');
INSERT INTO public.entity_scene_appearances VALUES (3918, 2550, 343, 'ally', true, 'His left arm is severed at the shoulder by I AM during the climax of their battle.', 'Begins with defiant rage, which fuels his fight. After being maimed and confronted with a difficult truth, his state shifts to one of cold, deliberate resolve, leading him to sacrifice his consciousness for a deeper understanding.', 'Actively uses internal nanites and a device called the Infinitron to augment his physical power and fuel his final, reality-shattering attack.', NULL, NULL, 'Receives spiritual support from the shade of Lady I (ኢልከሴሮድ) and the Spirits of the Realms. Engaged in a climactic battle with the cosmic tyrant I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (3919, 4018, 343, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The tyrannical ruler of the Tower and the primary antagonist of the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (3920, 4019, 343, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Serves as the throne and physical manifestation of I AM''s power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (3921, 4020, 343, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned by the narrator as having his back during the most intense moment of the struggle against I AM.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (3922, 2608, 343, 'ally', false, NULL, NULL, NULL, NULL, 'The narrator feels her presence as a guardian shade, providing spiritual support during the battle.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (3923, 1847, 343, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A tool used by the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (3924, 1201, 343, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A tool used by the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (3925, 4024, 343, 'neutral', true, NULL, NULL, NULL, NULL, 'Becomes the setting after the narrator allows himself to be consumed by I AM.', 'The inner sanctum or essence of I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (3926, 4025, 343, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:54:28.254649-05', '2026-02-28 17:54:28.254649-05');
INSERT INTO public.entity_scene_appearances VALUES (4838, 4966, 422, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Allies to one another against the threat of the Auditor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.entity_scene_appearances VALUES (3927, 2550, 344, 'ally', true, 'Merges with the essence of I AM, absorbing the god''s immense power and the echoes of consumed souls. He uses this newfound might to shatter the chains binding Etheris, but his victory leads to the cosmos''s destruction.', 'Experiences a cascade of emotions: from resolute hope amidst despair, to overwhelming compassion for his enemy, to indomitable will during the act of liberation, and finally to implied horror at the pyrrhic victory.', NULL, NULL, NULL, 'Acts as the vessel for cosmic change by merging with his antagonist, I AM. He becomes the liberator of the Consumed Souls and Countless Beings, albeit for a fleeting moment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3928, 1515, 344, 'mini-boss', true, NULL, NULL, NULL, 'His consciousness and power are absorbed by the narrator, and his essence is dismantled, causing his tyrannical reign to end and the cosmos to collapse.', NULL, 'The primary antagonist whose existence is a paradox: he is both the jailer of all life and the pillar that supports it. He is the corrupted form of the Shepherd Boy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3929, 4028, 344, 'neutral', true, NULL, NULL, NULL, 'Freed during the shattering of I AM''s reign, only to be instantly annihilated in the cosmic implosion.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3930, 4029, 344, 'neutral', false, NULL, NULL, NULL, NULL, 'Appears in a vision that reveals the origin of I AM''s malevolence.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3931, 4030, 344, 'enemy', false, NULL, NULL, NULL, NULL, 'Appears within the vision of I AM''s origin.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3932, 4031, 344, 'neutral', true, NULL, NULL, NULL, 'Shattered by the narrator''s final surge of will.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3933, 4032, 344, 'neutral', true, NULL, NULL, NULL, 'Instantly implodes into darkness and shadow upon the dissolution of I AM''s sustaining influence.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3934, 4033, 344, 'neutral', true, NULL, NULL, NULL, 'Snuffed out in the instantaneous collapse of the cosmos.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3935, 4034, 344, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3936, 4036, 344, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:55:25.571096-05', '2026-02-28 17:55:25.571096-05');
INSERT INTO public.entity_scene_appearances VALUES (3937, 2550, 345, 'ally', true, NULL, 'Exhibits a state of weary wisdom and exhortation, observing the cyclical folly of others while urging an unseen listener to persevere.', NULL, NULL, NULL, 'Acts as a guide or commentator on the actions of The Path-Followers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3938, 4039, 345, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'They are the creators and victims of the Deafening Ego, and they perpetuate their ignorance by sacrificing the Sacrificial Soldiers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3939, 4040, 345, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The primary tool and affliction of The Path-Followers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3940, 4041, 345, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'They are the price paid for the comfort of The Path-Followers'' ignorance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3941, 4042, 345, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3942, 982, 345, 'neutral', true, 'In this scene, it serves as a symbol of absolute futility, a boundless emptiness that swallows all attempts at communication with the willfully ignorant, rendering them meaningless.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3943, 4044, 345, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3944, 4045, 345, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The goal and result of the offerings made by The Path-Followers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3945, 4046, 345, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:56:46.143084-05', '2026-02-28 17:56:46.143084-05');
INSERT INTO public.entity_scene_appearances VALUES (3946, 3993, 346, 'ally', true, 'Has become a singular, god-like cosmic entity after consuming I AM, adrift in a void of his own making. He now possesses the power to create universes.', 'Experiences a profound arc from crushing, suicidal guilt to a state of resolute hope and longing, driven by the memory of his family.', NULL, NULL, 'Finds himself in the void as the scene opens, the direct aftermath of his previous actions.', 'Mourns the loss of everyone, especially his family, and his entire journey becomes a quest to reunite with them. He wields the power of the consumed entity I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3947, 4049, 346, 'enemy', true, NULL, NULL, NULL, 'Is overcome and recedes when the protagonist focuses on memories of his family and finds hope.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3948, 2550, 346, 'neutral', false, NULL, NULL, NULL, 'Mentioned as having been consumed by the protagonist. His destructive power is now a tool the protagonist must learn to use for creation.', NULL, 'The source of the protagonist''s newfound power and the entity whose destruction is a source of guilt.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3949, 4051, 346, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The lost home of the protagonist and his family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3950, 4052, 346, 'ally', true, NULL, NULL, NULL, NULL, 'Arise from within the protagonist''s mind to combat his guilt.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3951, 985, 346, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3952, 4054, 346, 'neutral', true, NULL, NULL, NULL, NULL, 'Willed into existence by the protagonist''s declaration, ''Let there be light.''', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3953, 4055, 346, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3954, 3664, 346, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'The central motivation for the protagonist. Their memory fuels his hope, and the desire to find them drives his journey.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
INSERT INTO public.entity_scene_appearances VALUES (3955, 4057, 346, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
