INSERT INTO public.entity_scene_appearances VALUES (3957, 3993, 347, 'ally', true, NULL, 'Experiences a devastating realization of his powerlessness, leading to overwhelming despair. This shifts to determination upon receiving advice, followed by doubt about the solution''s efficacy, and finally contemplation of a difficult alternative.', NULL, NULL, NULL, 'He is the creator of the Conjured Universe and the would-be father of his family. He is eternally bound to I AM, seeks counsel from Lady I, and receives an alternative plan from Madam O.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:58:48.646912-05', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_scene_appearances VALUES (3958, 2608, 347, 'ally', true, NULL, NULL, NULL, 'Her counsel is given, and the narrative focus shifts to the protagonist''s doubts and Madam O''s alternative.', 'Sought out by the protagonist for guidance after he dissolves his creation.', 'Acts as a wise counselor to the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:58:48.646912-05', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_scene_appearances VALUES (3959, 2749, 347, 'ally', true, NULL, NULL, NULL, 'Her proposal is made, leaving the protagonist to consider the cost.', 'Interjects after the protagonist expresses doubt, offering a different path forward.', 'Offers an alternative solution to the problem posed by I AM, contrasting with Lady I''s advice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:58:48.646912-05', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_scene_appearances VALUES (3960, 2550, 347, 'mini-boss', false, 'His role is framed not just as a manipulative entity, but as a fundamental cosmic jailer whose existence defines the prison of Etheris and enslaves humanity.', NULL, NULL, NULL, NULL, 'The eternal antagonist and jailer of humanity, bound inexorably to the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:58:48.646912-05', '2026-02-28 17:58:48.646912-05');
INSERT INTO public.entity_scene_appearances VALUES (3961, 4063, 347, 'neutral', true, NULL, NULL, NULL, 'Dissolved back into the protagonist''s essence due to his despair.', 'The scene opens with the protagonist contemplating his existence within this universe.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:58:48.646912-05', '2026-02-28 17:58:48.646912-05');
