INSERT INTO public.entity_scene_appearances VALUES (3982, 2550, 349, 'ally', true, NULL, 'Experiences a profound sense of normalcy and contentment. He feels relief as the memories and responsibilities of his cosmic and corporate life fade away, embracing the simplicity of his current existence.', NULL, NULL, 'Awakens in his bed at the start of the scene.', 'Husband to አንጀላህጃን and father to the Teen Son. He feels cocooned by their family warmth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:00:54.47073-05', '2026-02-28 18:00:54.47073-05');
INSERT INTO public.entity_scene_appearances VALUES (3983, 2549, 349, 'ally', true, NULL, 'Exuberant and joyful, displaying a huge grin as she shares the exciting news about winning the contest.', NULL, NULL, 'Is present in bed with the protagonist as the scene begins.', 'Wife of ኢሌልመሜብሃባኖኖራሊሊ and mother to the Teen Son.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:00:54.47073-05', '2026-02-28 18:00:54.47073-05');
