INSERT INTO public.entity_scene_appearances VALUES (4051, 2550, 356, 'ally', true, 'Now a seventy-four-year-old man, confined to a hospice pod and reflecting on his life, career, and marriage as he faces a technologically-induced death.', 'Cycles from animalistic panic during suffocation to nostalgic melancholy, then to bitter disillusionment, and finally lands on a dark, defiant acceptance of his end.', NULL, NULL, NULL, 'Husband to the deceased አንጀላህጃን, father to their son. He feels a profound, if distant, love for his wife and a deep sense of failure regarding his youthful ambitions to change the world with technology.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_scene_appearances VALUES (4052, 2549, 356, 'ally', false, 'Her memory is a central focus. She is remembered for her dark sense of humor, a polite and distant smile, and a love expressed through precise daily rituals rather than passion. She died of cancer after refusing medical intervention.', NULL, NULL, NULL, NULL, 'Wife of the protagonist for forty-seven years and mother to their son. Her memory provides both comfort and a lens through which the protagonist views his life''s absurdities.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_scene_appearances VALUES (4053, 4161, 356, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The instrument of the protagonist''s potential death, turning a place of care into a source of torment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_scene_appearances VALUES (4055, 831, 356, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A product of one of the fourteen moments of genuine connection between his parents.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_scene_appearances VALUES (4056, 4164, 356, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Represents the protagonist''s core disillusionment and sense of a wasted life''s work.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_scene_appearances VALUES (4057, 20, 356, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.entity_scene_appearances VALUES (4058, 4166, 356, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'A symbol of the profound, albeit rare, connection he shared with his wife.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
