INSERT INTO public.entity_scene_appearances VALUES (5765, 5915, 508, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The primary force being fought by Stephen and Xavier, and the reason they seek help from Maeve and Elara.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_scene_appearances VALUES (4062, 2550, 357, 'ally', true, NULL, 'Begins in a state of cynical resignation and dark amusement while reflecting on humanity''s decline. His mood shifts to confusion and anxiety as surreal technological glitches begin to manifest around him, questioning his own sanity.', NULL, NULL, NULL, 'Recalls his former colleague, Leon, with a sense of nostalgic pity for his past optimism. Feels a profound sense of disillusionment with Humanity and The Universe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.entity_scene_appearances VALUES (4063, 160, 357, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A colleague and contemporary of the narrator during the brief AI boom.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
