INSERT INTO public.entity_scene_appearances VALUES (4076, 2550, 358, 'ally', true, 'His body fails and he dies, his consciousness dissolving into what he perceives as a cosmic hum. His final act is to whisper his last thoughts to the empty room.', 'Moves from philosophical resignation and acceptance of death to a state of transcendent dissolution, ending in a sense of final rest.', NULL, 'Dies and his consciousness dissolves into ''eternal blackness''.', NULL, 'Recalls the sound of his wife (አንጀላህጃን) dying, connecting his own death to hers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_scene_appearances VALUES (4077, 4185, 358, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The location of ኢሌልመሜብሃባኖኖራሊሊ''s death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_scene_appearances VALUES (4078, 4186, 358, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A mental construct of ኢሌልመሜብሃባኖኖራሊሊ, representing his unfulfilled potential.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_scene_appearances VALUES (4079, 4187, 358, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A final sensory hallucination experienced by ኢሌልመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_scene_appearances VALUES (4080, 4188, 358, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The final auditory experience of ኢሌልመሜብሃባኖኖራሊሊ as he dies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_scene_appearances VALUES (4081, 4189, 358, 'unknown', true, NULL, NULL, NULL, NULL, NULL, 'Displayed by the Mortality Pod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_scene_appearances VALUES (4082, 4190, 358, 'unknown', true, NULL, NULL, NULL, NULL, NULL, 'Displayed by the Mortality Pod alongside the Mysterious Geometric Symbol.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_scene_appearances VALUES (4083, 2549, 358, 'ally', false, NULL, NULL, NULL, 'The memory fades as the narrator''s own death progresses.', 'Appears as a memory when the narrator recognizes the sound of his own death rattle as being similar to hers.', 'The deceased wife of ኢሌልመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.entity_scene_appearances VALUES (4084, 3993, 359, 'ally', true, 'His sixteen-year-old self is experiencing a traumatic, reality-shattering event during a sparring match, receiving visions of past and future lives.', 'Starts with the shock and pain of a severe blow, transitioning into a state of profound confusion, terror, and surreal revelation as his consciousness fractures.', NULL, NULL, NULL, 'Is called ''Stephen'' by አንጀላህጃን, suggesting a deep, possibly multi-life connection. He is the victim of an attack by the Don Quai Sparring Partner.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_scene_appearances VALUES (4085, 4194, 359, 'mini-boss', true, NULL, NULL, NULL, 'His role as the attacker is complete after landing the kick; he fades into the background chaos.', 'Is engaged in a sparring match with the protagonist.', 'Antagonist to the protagonist in this scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_scene_appearances VALUES (4086, 2549, 359, 'ally', true, 'Appears as a shimmering, worried form materializing out of the protagonist''s chaotic visions. Her form unravels and reforms before sharpening into clarity.', 'Appears worried and concerned for the protagonist.', NULL, NULL, 'Materializes above the protagonist as he is on the verge of unconsciousness, her presence cutting through the chaos.', 'She appears to have an intimate connection with the protagonist, calling him by the name ''Stephen'' and having a familiar scent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_scene_appearances VALUES (4087, 4196, 359, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An antagonistic force assaulting the protagonist''s mind.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_scene_appearances VALUES (4088, 4197, 359, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears as a distinct vision within the broader reality fracture just before the protagonist loses consciousness.', 'Represents a future or alternate version of the protagonist, ኢልከሴሮድመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_scene_appearances VALUES (4089, 4198, 359, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_scene_appearances VALUES (4090, 4199, 359, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.entity_scene_appearances VALUES (4091, 3993, 360, 'ally', true, NULL, 'Experiencing extreme panic, confusion, and identity fragmentation as his consciousness is assaulted by memories from multiple realities. He feels trapped between different versions of himself.', NULL, NULL, 'The scene begins with his consciousness collapsing and reforming, throwing him into this state of crisis.', 'He is in an internal dialogue with his ''Older Self,'' is haunted by memories of ''Leon,'' and finds a sliver of hope in the voice of ''The Unknown Woman.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_scene_appearances VALUES (4092, 4201, 360, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An antagonistic force working in concert with ''The Shadow'' and ''Fragmented Memories'' to destabilize the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.entity_scene_appearances VALUES (4241, 4352, 375, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.entity_scene_appearances VALUES (4787, 4342, 418, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'A key member of the Composite Friends and a source of inspiration for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.entity_scene_appearances VALUES (4093, 4202, 360, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'An internal enemy that embodies the most aggressive aspect of the protagonist''s psychological collapse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
