INSERT INTO public.entity_scene_appearances VALUES (4100, 3993, 361, 'ally', true, 'His physical state is compromised, leaking fluid from his ear. His perception of reality is highly distorted, seeing faces as ''shifting geometry'' and time as dilated.', 'Experiences extreme disorientation, a fractured sense of self, and a detached state that gives way to a ''beautiful new panic'' before losing consciousness.', NULL, NULL, NULL, 'Confused by his relationship with Jamie, whom he only remembers as a classmate he admired from afar. He is being attended to by Medics and observed by the Shadows.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_scene_appearances VALUES (4101, 2549, 361, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned briefly as the protagonist struggles with his memories, confused by hearing a familiar voice and thinking of his deceased wife.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.entity_scene_appearances VALUES (4102, 4211, 361, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Appears to know Stephen as a friend, a fact that bewilders him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
