INSERT INTO public.entity_scene_appearances VALUES (4111, 3993, 362, 'ally', true, 'Physically a sixteen-year-old boy in medical shock, but his consciousness is overwhelmed by the memories and knowledge of a seventy-four-year-old man.', 'Experiencing a terrifying synesthetic cascade, deep confusion about his identity and age, and the horror of clinical death followed by a violent revival.', NULL, NULL, NULL, 'Experiences a synesthetic memory of his mother''s cooking. Is being treated by a medic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
