INSERT INTO public.entity_scene_appearances VALUES (4121, 3993, 363, 'ally', true, 'Successfully revived by medics, only to be immediately caught in a violent, multi-roll ambulance crash while still strapped to a gurney.', 'Experiences a jarring shift from the dazed relief of returning to consciousness to sudden, overwhelming shock and terror as the crash occurs.', NULL, NULL, 'Regains consciousness after being revived.', 'Patient of the Medics, victim of the Oncoming Car.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:01.412884-05', '2026-02-28 18:13:01.412884-05');
