INSERT INTO public.entity_scene_appearances VALUES (4130, 3993, 364, 'ally', true, 'Pinned upside down in a car wreck, bleeding from the head and severely injured.', 'Experiences disorientation and trauma, which shifts to a detached sense of gallows humor and calm resignation before he loses consciousness.', NULL, 'Loses consciousness due to blood loss, surrendering to ''Nothingness''.', NULL, 'Is a victim of the Drunk Driver''s actions. Observes the Medic''s likely death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:46.547574-05', '2026-02-28 18:13:46.547574-05');
