INSERT INTO public.entity_scene_appearances VALUES (4139, 3993, 365, 'ally', true, NULL, 'Experiences a state of extreme distress, moving from frantic desperation and confusion to resigned terror as his reality collapses around him.', NULL, 'Is consumed by darkness as reality folds in on itself.', 'Wakes up in his room at the start of the scene.', 'Is the sole observer and victim of the surreal events in his room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
