INSERT INTO public.entity_scene_appearances VALUES (4149, 3993, 366, 'ally', true, 'Physically suffering from a severe hangover, with a cracked-feeling skull and sluggish, uncoordinated movements.', 'Starts in a state of physical misery, which quickly escalates to profound confusion, disbelief, and mounting panic as his memories conflict with reality. He feels like he is losing his mind or dimension.', NULL, NULL, NULL, 'Subjected to the effects of The Shifting Truth and The Hangover. His perception of reality is being actively undermined.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_scene_appearances VALUES (4150, 4260, 366, 'enemy', true, NULL, NULL, NULL, NULL, 'Present from the moment the narrator wakes up, setting a tone of misery and vulnerability.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_scene_appearances VALUES (4151, 4261, 366, 'neutral', true, NULL, NULL, NULL, 'The narrator clicks it off to escape the disorienting news report.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.entity_scene_appearances VALUES (4152, 4262, 366, 'neutral', false, NULL, NULL, NULL, NULL, 'Broadcasted over the clock-radio, triggering the narrator''s initial confusion.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
