INSERT INTO public.entity_scene_appearances VALUES (4169, 2550, 368, 'ally', true, 'His sense of self has fractured into two distinct personas communicating through his journal: a scared sixteen-year-old and a seventy-year-old veteran of temporal chaos.', 'Gripped by a clinging fear and desperation, he seeks stability in his journal. He feels a primal terror at the thought of his father''s return.', 'Using a pen and his journal.', NULL, NULL, 'Son of ''The Narrator''s Father'', whom he deeply fears.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_scene_appearances VALUES (4170, 4263, 368, 'ally', true, NULL, NULL, NULL, NULL, 'The narrator opens it, desperate for something real to hold onto.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_scene_appearances VALUES (4171, 4281, 368, 'enemy', true, NULL, NULL, NULL, NULL, 'His imminent arrival is signaled by the garage door opening at the end of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_scene_appearances VALUES (4172, 1942, 368, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Lingers from a previous event and intensifies throughout the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_scene_appearances VALUES (4173, 4283, 368, 'enemy', true, NULL, NULL, NULL, NULL, 'It is the core problem the narrator is attempting to understand and survive.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_scene_appearances VALUES (4174, 4284, 368, 'neutral', true, NULL, NULL, NULL, NULL, 'Its sound signals the father''s arrival, triggering the scene''s climax.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_scene_appearances VALUES (4175, 4285, 368, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.entity_scene_appearances VALUES (4176, 3993, 369, 'ally', true, 'Physically beaten and bruised during the scene, his body is described as folding ''like origami made of meat and bone''. He is left on the floor by his parents.', 'Experiences extreme terror and pain, leading to a dissociative state. This evolves into a cold, defiant endurance fueled by his secret foreknowledge of his abusers'' future deaths.', NULL, NULL, NULL, 'Son of ኢሌልመሜብሃባኖኖራሊሊ and አንጀላህጃን. He is the victim of their abuse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_scene_appearances VALUES (4177, 2550, 369, 'mini-boss', true, 'His physical presence is described as ''wrong'' and unsettling, moving like ''broken machinery'' with a twitching face. His breath smells of sulfur and disappointed dreams.', 'Consumed by rage over a perceived family embarrassment, he displays sadistic joy when his son finally shows pain, revealing a perverse satisfaction in the abuse.', 'Wields a leather belt as a weapon.', 'Loses interest in the beating and leaves after his son has been subdued.', 'Slams the door open to confront his son about the tournament failure.', 'Father of ኢልከሴሮድመሜብሃባኖኖራሊሊ and husband of አንጀላህጃን. He is the primary abuser in the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_scene_appearances VALUES (4178, 2549, 369, 'enemy', true, 'Appears as a passive, detached observer, hovering in the doorway. She is compared to a ''photograph of concern with the emotional range of wallpaper''.', 'Exhibits complete emotional detachment, watching the abuse as if it were a ''nature documentary''. She is a silent enabler of the violence.', NULL, 'Loses interest and leaves with her husband.', 'Appears in the doorway after her husband begins the confrontation.', 'Mother of ኢልከሴሮድመሜብሃባኖኖራሊሊ and wife of ኢሌልመሜብሃባኖኖራሊሊ. She is a passive accomplice to the abuse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.entity_scene_appearances VALUES (4179, 4289, 369, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
