INSERT INTO public.entity_scene_appearances VALUES (4185, 2550, 370, 'ally', true, 'Heavily injured, suffering from a severe concussion that causes vertigo and ringing in his ears. He has physically patched himself together with bandages.', 'Operating on a mixture of spite and exhaustion. He is disoriented but finds a moment of quiet solitude after a period of intense chaos.', NULL, NULL, NULL, 'He is the owner of The Journal and the author of The Note, though he doesn''t seem to remember writing it. He is being actively afflicted by the Concussion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:18:40.25898-05', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.entity_scene_appearances VALUES (4186, 4296, 370, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Used by ኢሌልመሜብሃባኖኖራሊሊ for self-repair.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:18:40.25898-05', '2026-02-28 18:18:40.25898-05');
