INSERT INTO public.entity_scene_appearances VALUES (4193, 3993, 371, 'ally', true, 'Currently in the form of his sixteen-year-old self, his body is covered in fresh bruises and injuries from a recent beating.', 'Wakes in extreme physical pain, which is quickly overshadowed by intense dread about an upcoming test and his father''s reaction. This culminates in a powerful rage born of frustration and helplessness.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:19:18.294406-05', '2026-02-28 18:19:18.294406-05');
