INSERT INTO public.entity_scene_appearances VALUES (4204, 3993, 372, 'ally', true, NULL, 'Moves from academic desperation and existential dread to a state of profound appreciation and fragile hope, anchored by his connection with Jamie.', NULL, NULL, NULL, 'Deeply connected to Jamie, their friendship is fraught with unspoken romantic tension. He is terrified of his father (ኢሌልመሜብሃባኖኖራሊሊ).', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_scene_appearances VALUES (4205, 4211, 372, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Best friends with the narrator (ኢልከሴሮድመሜብሃባኖኖራሊሊ), with significant unspoken romantic feelings between them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.entity_scene_appearances VALUES (4206, 2550, 372, 'enemy', false, NULL, 'His presence is felt as an oppressive, looming threat of violence and punishment, tied to the narrator''s financial and academic failures. He is the source of the narrator''s fear regarding the phone bill.', NULL, NULL, NULL, 'The narrator''s father, who represents a source of fear and potential violence in this scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
