INSERT INTO public.entity_scene_appearances VALUES (4215, 3993, 373, 'ally', true, 'Has fresh, visible bruises on his face and body from a tournament fight, making him the subject of attention at school.', 'Begins the day feeling detached but quickly becomes confused, anxious, and paralyzed by indecision when confronted with unexpected romantic attention and the conflicting perspective of his older self.', NULL, NULL, NULL, 'Friend to Jamie and Becca, but is now the unwitting center of their rivalry for his affection. He is also in direct internal conflict with the memories and commentary of his older self.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.entity_scene_appearances VALUES (4216, 4211, 373, 'ally', true, NULL, NULL, NULL, 'Walks to Biology class with Becca after failing to get a definitive commitment from Stephen for lunch.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.entity_scene_appearances VALUES (4217, 2882, 373, 'ally', true, NULL, NULL, NULL, 'Walks to Biology class with Jamie, continuing their subtle competition.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
