INSERT INTO public.entity_scene_appearances VALUES (4223, 3993, 374, 'ally', true, 'He appears physically drained and disoriented after experiencing a violent vision, collapsing onto his desk.', 'Starts with mild social anxiety and pressure about the test, which shifts to abject terror during his vision, and finally lands on deep confusion and disorientation when reality seems to warp around him.', NULL, NULL, NULL, 'Student of Ms. Rodriguez. Friend of TJ and Patrick. Classmate and potential love interest of Jamie and Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
