INSERT INTO public.entity_scene_appearances VALUES (4234, 3993, 375, 'ally', true, 'He is distracted and troubled by flashes of memories from another life, particularly one triggered by the mention of a childhood sci-fi story idea.', 'Confused, distracted, and alarmed by his own memories and Whitney''s cryptic warnings. He tries to maintain a casual demeanor with his friends but is clearly disoriented.', 'Now in possession of a black demon Magic: The Gathering deck.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
