INSERT INTO public.entity_scene_appearances VALUES (4251, 3993, 376, 'ally', true, NULL, 'Experiences immense relief upon discovering he is not alone in his strange experiences, shifting from isolated fear to a sense of camaraderie and shared purpose.', NULL, NULL, NULL, 'Friend and confidant to Patrick and Whitney. Feels a renewed sense of connection with them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
