INSERT INTO public.entity_scene_appearances VALUES (4261, 3993, 377, 'ally', true, NULL, 'Begins the scene in a state of paranoid tension, which shifts to concern for Whitney, then awkwardness about his home life, and finally complete obliviousness to Jamie''s romantic intentions.', NULL, NULL, NULL, 'Receives a supportive call from Whitney who understands his trauma. Is the object of Jamie''s affections, though he is completely unaware of it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
