INSERT INTO public.entity_scene_appearances VALUES (4274, 3993, 378, 'ally', true, NULL, 'Moves from extreme physical and mental exhaustion to experiencing a vivid dream of desire, followed by the terror of a violent death, and culminating in a shocking, crystalline realization about the nature of his visions. He ends the scene with a sense of grim acceptance and paranoia.', NULL, 'Shuffles off to his room to process the revelation about his death visions.', 'Collapses onto his living room couch from sheer exhaustion.', 'Experiences a dream of intense intimacy with Jamie and Becca. Realizes his death visions are bleed-throughs from alternate versions of himself. Mentions Whitney as someone who understands his experiences.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.entity_scene_appearances VALUES (4275, 4211, 378, 'neutral', true, NULL, NULL, NULL, 'Dies in the car crash within the dream.', 'Appears in Stephen''s dream, sitting beside him in the Corvette.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
