INSERT INTO public.entity_scene_appearances VALUES (4285, 3993, 379, 'ally', true, 'Physically present in a friend''s basement, caught between the romantic advances of two friends before suffering a violent, convulsive episode triggered by an internal psychic event.', 'His state shifts from hazy observation and passive enjoyment of romantic tension to extreme agony, confusion, and fear after the psychic attack, culminating in an urgent need to confess something to his friends.', 'He has his journal open on his lap.', NULL, NULL, 'The object of affection and competition for Jamie and Becca. A core member of the friend group (TJ, Morgan, Whitney, Patrick).', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
