INSERT INTO public.entity_scene_appearances VALUES (4314, 3993, 381, 'ally', true, NULL, 'Moves from a state of exhaustion and despair after his confession to shock and terror during the paranormal TV event. The scene ends with him feeling a renewed, albeit fearful, sense of purpose and connection to the group.', NULL, NULL, NULL, 'Receives comfort and a kiss from Jamie, which establishes a romantic and protective dynamic. Witnesses Becca''s aborted attempt at comfort, creating a moment of unspoken tension. Is part of a newly formed group of allies (Whitney, TJ, Patrick, Becca, Jamie).', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
