INSERT INTO public.entity_scene_appearances VALUES (4325, 3993, 382, 'ally', true, 'He discovers his journal contains entries he doesn''t recall, leading him to believe he has been ''switched'' between dimensions each time he died in an alternate timeline. He becomes the catalyst for the group''s new quest.', 'Starts in a state of exhaustion, moves through confusion and terror upon discovering the journal''s contents, and lands on a determined, desperate hope as he resolves to find his ''correct'' self.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_scene_appearances VALUES (4326, 4211, 382, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Acts as an anchor for the narrator, curling against his side. She is the first to propose they can find ''the boy''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_scene_appearances VALUES (4327, 4342, 382, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Shares a telepathic understanding with Jamie and a history of shared strange experiences (death visions) with Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_scene_appearances VALUES (4328, 2896, 382, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Forms a new, deeper connection with Becca. He is protective of Whitney and shares the experience of death visions with her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.entity_scene_appearances VALUES (4329, 2882, 382, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Develops a new, significant bond with Patrick, moving from seeing him as Whitney''s shadow to a potential partner.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
