INSERT INTO public.entity_scene_appearances VALUES (4379, 3993, 386, 'ally', true, 'His consciousness is violently torn from his body, leaving him suspended by ''silver threads'' that connect him to his friends'' agony. His physical body experiences sympathetic trauma, including a massive nosebleed.', 'Experiences a cascade of terror, empathetic agony from his friends'' transformations, and finally profound loss and despair as his connections to them are severed.', NULL, NULL, NULL, 'Witnesses the horrific transformation and loss of his entire group of friends (Whitney, TJ, Becca, Jamie, Patrick), feeling their final moments intimately.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_scene_appearances VALUES (4380, 4342, 386, 'mini-boss', true, NULL, NULL, NULL, 'Her being ''explodes into purity,'' dissolving into abstract memes, and her silver thread ceases to exist rather than breaking.', 'Leads the group in the chant that initiates the reality-breaking event.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_scene_appearances VALUES (4381, 4211, 386, 'ally', true, NULL, NULL, NULL, 'Her silver thread to the narrator is the last to snap, signifying her being lost to the liquid darkness.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_scene_appearances VALUES (4382, 2884, 386, 'ally', true, NULL, NULL, NULL, 'His silver thread is the first to snap, indicating his consciousness is the first to be lost.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_scene_appearances VALUES (4383, 2882, 386, 'ally', true, NULL, NULL, NULL, 'Her silver thread, merged with Patrick''s, severs with a wet tearing noise.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.entity_scene_appearances VALUES (4384, 2896, 386, 'ally', true, NULL, NULL, NULL, 'His silver thread, merged with Becca''s, is severed.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
