INSERT INTO public.entity_scene_appearances VALUES (4397, 4510, 387, 'big-boss', false, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist and reason for the prison realm''s existence. The narrator''s actions are inadvertently disrupting its containment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.entity_scene_appearances VALUES (4398, 2608, 387, 'ally', false, 'Revealed to be one of the ''resistance goddesses'' and a ''Prison Architect'' operating outside the prison realm. She is Benji''s boss and has a keen interest in the narrator, believing he may be the key to fixing the system.', NULL, NULL, NULL, NULL, 'Benji''s superior and the leader of a resistance movement against Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
