INSERT INTO public.entity_scene_appearances VALUES (4402, 3993, 388, 'ally', true, NULL, 'Experiences a violent return to consciousness, filled with disorientation and terror. His fear escalates to panic as he witnesses his friends in peril and the reality of the basement warping around him, feeling utterly powerless before succumbing to unconsciousness again.', 'He is now completely naked.', 'The darkness rushes in from all sides, and he loses consciousness.', 'Slams back into his body with the force of a meteor, regaining consciousness on the basement floor.', 'He is one of five friends trapped in the basement. He feels a desperate need to protect them but is unable to act.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_scene_appearances VALUES (4403, 4516, 388, 'ally', true, NULL, NULL, NULL, NULL, 'They are already present when the narrator wakes up.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.entity_scene_appearances VALUES (4404, 4211, 388, 'ally', true, NULL, NULL, NULL, 'Remains in the scene, but her consciousness is overwritten by the shadows.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
