INSERT INTO public.entity_scene_appearances VALUES (4418, 3993, 389, 'ally', true, NULL, 'Remains the sole bearer of the memory of the summoning, creating a sense of isolation. He feels awkward and protective amidst the group''s collective nudity and amnesia.', NULL, NULL, NULL, 'Feels a new, intense connection from Jamie, which makes him self-conscious. He is the unspoken leader and witness for the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_scene_appearances VALUES (4419, 2945, 389, 'ally', true, 'The group is physically present, naked, and covered in a thin sheen of sweat following the summoning ritual. They are disheveled and exhausted.', 'Collectively disoriented, confused, and suffering from amnesia regarding the ritual. They exhibit a dazed acceptance and a soul-deep exhaustion.', 'Their clothes, which had vanished, are returned to them neatly folded.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.entity_scene_appearances VALUES (4420, 2884, 389, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'His Nana appears and takes charge of the group''s well-being.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
