INSERT INTO public.entity_scene_appearances VALUES (4455, 3993, 392, 'ally', true, NULL, 'Shifts from determined and reassuring towards Jamie to terrified during the reality breakdown, and finally to a state of grim resolve after Benji''s warnings. His curiosity remains a driving, and dangerous, trait.', NULL, NULL, NULL, 'Acts as a protector and confidant to Jamie. He is a core member of the group of friends.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_scene_appearances VALUES (4456, 4211, 392, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Has a close, intimate bond with Stephen. Member of the core group of friends.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
