INSERT INTO public.entity_scene_appearances VALUES (4468, 866, 392, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.entity_scene_appearances VALUES (4469, 3993, 393, 'ally', true, NULL, 'Shaken and filled with doubt after the failed summoning. He feels conflicted and desperate as his friends leave, ultimately succumbing to Jamie''s manipulation out of fear of loneliness, which leaves him feeling guilty and hollow.', NULL, NULL, NULL, 'His relationship with the group fractures. He is manipulated by Jamie into choosing her over Whitney, devastating his friendship with Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4470, 2884, 393, 'neutral', true, NULL, NULL, NULL, 'Quits the investigation due to failing grades, his mother''s concerns, and the trauma from the failed summoning.', 'Corners Stephen at his locker between classes.', 'Friend of Stephen and the group, but severs his ties to the investigation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4471, 2882, 393, 'neutral', true, NULL, NULL, NULL, 'Leaves the group, taking Patrick with her, believing the investigation is unhealthy and destructive.', 'Finds Stephen in the library during lunch.', 'A friend who prioritizes normalcy and safety over the group''s quest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4472, 4211, 393, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Is with Stephen and Whitney in her bedroom, initiating the final confrontation.', 'Acts as Stephen''s possessive girlfriend and Whitney''s antagonist. She successfully drives a wedge between them and dismantles their friend group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4508, 2884, 396, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A core member of the friend group. His escalating anger is a source of fear for Jamie and the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.entity_scene_appearances VALUES (4474, 4590, 393, 'neutral', true, NULL, NULL, NULL, 'Is yelled at by Jamie to get out, but her presence has already served its purpose.', 'Bursts into Jamie''s room, interrupting the moment between Stephen and Jamie after Whitney leaves.', 'Jamie''s younger sister.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4475, 2896, 393, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by Becca as leaving the group with her.', 'Friend to the group, provides a safe haven for Whitney after she leaves.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4476, 4548, 393, 'neutral', true, NULL, NULL, NULL, 'Systematically dismantled by internal dissent, fear, and Jamie''s targeted sabotage, until only Stephen and Jamie remain.', 'The group exists in a broken state at the beginning of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4477, 4593, 393, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned as the inciting incident for the group''s current state of fear and disillusionment.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4478, 4594, 393, 'enemy', true, NULL, NULL, NULL, 'Is resolved by Stephen''s silent choice.', 'Presented by Jamie at the climax of her confrontation with Whitney.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4479, 4595, 393, 'neutral', true, NULL, NULL, NULL, 'Its meaning is understood by Whitney, who accepts it as his final decision and leaves.', 'Occurs immediately after Jamie issues her ultimatum.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4480, 4596, 393, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned in the opening narration as a memory from the night of the summoning.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4481, 846, 393, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.entity_scene_appearances VALUES (4482, 3993, 394, 'ally', true, NULL, 'Begins the scene focused on a game of Magic, then is plunged into terror and paralysis during the reality breach. This shifts to profound guilt and grief upon realizing Whitney is gone and they failed to help her.', NULL, NULL, NULL, 'Part of the core friend group. In a relationship with Jamie. Feels responsible for not taking Whitney''s investigations seriously.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4483, 4342, 394, 'ally', true, NULL, NULL, NULL, 'Abducted by massive rusted chains that dragged her into a hellish alternate dimension.', NULL, 'Friend to the core group. Has a strained relationship with Jamie, causing her to stay with Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4484, 4211, 394, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The narrator''s partner. Her relationship with Whitney is complicated and unresolved.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4485, 2896, 394, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A supportive friend who is providing Whitney a place to stay and lending her his deck.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4486, 2884, 394, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the core friend group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4487, 2882, 394, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the core friend group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4488, 4605, 394, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A close-knit group bonded by shared experiences and hobbies, now united by a traumatic loss and a secret reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4489, 4606, 394, 'enemy', true, NULL, NULL, NULL, 'Vanishes abruptly, snapping back to normal reality after Jamie screams.', 'Manifests when Whitney attempts to draw a card, causing reality to ''stutter'' and ''peel'' away.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4490, 4607, 394, 'mini-boss', true, NULL, NULL, NULL, 'Disappeared with Whitney when she was fully dragged into the hellscape.', 'Emerged from the hell-ground specifically to capture Whitney.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4491, 4354, 394, 'neutral', true, 'After Whitney is taken, her initials on the card are seen slowly fading away.', NULL, NULL, NULL, 'This was the card Whitney was about to draw when the event was triggered. It remains as the only physical proof of her last moments.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4492, 4609, 394, 'unknown', true, NULL, NULL, NULL, 'Recedes from Jamie''s mind, allowing her to scream in her own voice.', 'Speaks through Jamie immediately after Whitney is taken by the chains.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4493, 4610, 394, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Peers of the main group, their memory alteration highlights the selective nature of the supernatural event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4494, 4611, 394, 'unknown', false, NULL, NULL, NULL, NULL, 'Summoned when the narrator screams Benji''s name for help during Whitney''s abduction.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4495, 4612, 394, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.entity_scene_appearances VALUES (4496, 3993, 395, 'ally', true, NULL, 'Experiences a mix of residual cosmic horror from a previous event and immediate, grounded fear and confusion due to William''s appearance and the reality shift. Feels a cold dread when personally threatened.', NULL, NULL, NULL, 'Observer and member of The Friend Group; feels protective of his friends, especially TJ and Patrick, against William''s aggression.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4497, 4614, 395, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist of the scene. He is the reality-warped replacement for Whitney, who was formerly Patrick''s best friend. He targets Mr. Martinez, The Friend Group, and specifically TJ and Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4498, 4404, 395, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A close-knit group united against William. They are the only ones who remember Whitney and the previous reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4499, 2896, 395, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A close friend of the narrator. He is the target of William''s gaslighting and threats of conversion therapy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4500, 2884, 395, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of The Friend Group. He is physically assaulted by William and is also the target of homophobic threats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4501, 4618, 395, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The underlying antagonist of the scene, with William Carson as its physical agent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4502, 4342, 395, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned as the group realizes she has been replaced in their timeline by William, her torturer.', 'The ''ghost'' of the scene; her memory is what separates the friend group''s perception from the new, hostile reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4503, 4620, 395, 'neutral', true, NULL, NULL, NULL, 'Changes direction to avoid further confrontation with William.', NULL, 'Victim of William''s racist verbal abuse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4504, 4621, 395, 'neutral', true, NULL, NULL, NULL, 'Walks away after giving William a verbal warning.', NULL, 'A figure of authority who provides a temporary, ineffective intervention in William''s bullying.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4505, 4622, 395, 'neutral', false, NULL, NULL, NULL, 'Discovered to be missing after the confrontation, heightening the sense of danger and isolation.', NULL, 'A key plot item whose absence signifies the group''s isolation in the new reality and Whitney''s peril.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4506, 4623, 395, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.entity_scene_appearances VALUES (4507, 3993, 396, 'ally', true, NULL, 'Becomes increasingly aware of the external forces corrupting his friends. He feels fear and desperation but also a growing resolve to hold the group together, resisting Jamie''s attempts to isolate him and trying to mediate Becca''s outburst.', NULL, NULL, NULL, 'Acts as the central observer and mediator. He is the target of Jamie''s possessive affection and Becca''s accusations, and he feels a strong sense of loyalty to TJ and the group''s original mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
