INSERT INTO public.entity_scene_appearances VALUES (4519, 3993, 397, 'ally', true, NULL, 'Moves from grieving obsession to renewed, focused determination after receiving a message from Whitney. His resolve to save her is solidified.', NULL, NULL, NULL, 'The narrator is the focal point of the friend group''s drama. He is the target of Jamie''s manipulations and the sole person actively trying to remember and rescue Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
