INSERT INTO public.entity_scene_appearances VALUES (4532, 3993, 398, 'ally', true, NULL, 'Struggling with insomnia and obsessed with Whitney''s disappearance. He feels a mix of desperation, fear, arousal, and conflict throughout the scene, torn between chasing a mystery and pursuing a relationship with Jamie.', NULL, NULL, NULL, 'Son of ኢሌልመሜብሃባኖኖራሊሊ. Friend/potential romantic interest of Jamie. Haunted by the memory and messages of Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.entity_scene_appearances VALUES (4533, 4342, 398, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'A close friend of Stephen, who is now obsessed with finding her. Also friends with Jamie and Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
