INSERT INTO public.entity_scene_appearances VALUES (4545, 3993, 399, 'ally', true, NULL, 'Torn between lustful distraction from Jamie''s advances and an urgent need to investigate Whitney''s mysterious warning. His focus is constantly being pulled in two directions, leading to internal conflict and anxiety.', NULL, NULL, NULL, 'Part of the core group of friends. He is the focus of Jamie''s seductive attention and the catalyst for the group''s investigation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
