INSERT INTO public.entity_scene_appearances VALUES (4560, 3993, 400, 'ally', true, NULL, 'Experiences escalating confusion, horror, and desperate panic as he witnesses reality break down. He becomes the sole anchor for a forgotten friend''s memory, fighting against a universe that wants him to forget.', NULL, NULL, NULL, 'Leader and memory-keeper for his group of friends. He feels a deep connection to Jamie, which allows him to resist her erasure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.entity_scene_appearances VALUES (4561, 4211, 400, 'enemy', true, NULL, NULL, NULL, 'Erased from reality and the memories of her friends, though Stephen''s refusal to forget keeps a trace of her alive.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
