INSERT INTO public.entity_scene_appearances VALUES (4573, 3993, 401, 'ally', true, NULL, 'His consciousness dissolves under the weight of cosmic agony, experiencing torment with crystalline clarity before fraying into nothing. His final perception is the scent of vanilla and peaches.', NULL, 'Consciousness dissolves at the end of the scene due to reality inverting.', NULL, 'Witnesses the torment of Jamie, whom he loves. Part of the group with Patrick, TJ, and Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
