INSERT INTO public.entity_scene_appearances VALUES (4586, 3993, 402, 'ally', true, NULL, 'Wakes in terror from a nightmare, feels escalating panic when he can''t reach his friends, experiences relief upon seeing them online, and is left with ominous dread after a mysterious message.', NULL, NULL, NULL, 'Protagonist of the scene. He is one of the ''Rememberers'' who experienced the shared nightmare and tries to rally his friends, both believers and skeptics.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4587, 4708, 402, 'enemy', false, NULL, NULL, NULL, NULL, 'Experienced by Stephen and several of his friends, causing them to wake up in terror.', 'The inciting incident of the scene, dividing the friend group into those who remember it and those who don''t.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4588, 4342, 402, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned as the screaming victim within the shared nightmare.', 'The focal point of the memory schism among the friend group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4589, 1555, 402, 'neutral', false, 'It is now identified as the central location of a shared, traumatic nightmare, containing a ''door that opened into hell''.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4590, 4711, 402, 'ally', true, NULL, NULL, NULL, NULL, 'They all try to contact each other simultaneously after waking up, and then converge on the BBS.', 'In opposition to The Skeptics, who do not share their memories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4591, 4549, 402, 'ally', true, NULL, NULL, NULL, NULL, 'They respond to the Rememberers'' frantic messages on the BBS with confusion and denial.', 'Friends with The Rememberers, their skepticism creates the central conflict of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4592, 4713, 402, 'neutral', true, NULL, NULL, NULL, NULL, 'Stephen logs on to find his friends after failing to reach them by phone.', 'The medium through which the memory schism is revealed and debated.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4593, 4714, 402, 'unknown', true, NULL, NULL, NULL, 'Vanishes when Stephen asks if anyone else saw it.', 'Appears at the bottom of the screen after the friends make their plan.', 'A manifestation of the Unknown Messenger''s will.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4594, 4715, 402, 'mini-boss', false, NULL, NULL, NULL, 'Retracts its message, leaving no trace.', 'Manifests its presence through the mysterious message sent to Stephen.', 'Acts as an unknown party influencing Stephen''s quest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4595, 370, 402, 'enemy', true, NULL, NULL, NULL, 'Subsides into relief when he sees his friends'' messages on the BBS.', 'Arises when Stephen gets repeated busy signals trying to call his friends.', 'An internal antagonist for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4596, 4717, 402, 'neutral', false, NULL, NULL, NULL, NULL, 'Proposed by Stephen as a place to investigate the nightmare''s reality.', 'The objective location for the group''s investigation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4597, 4211, 402, 'ally', true, NULL, NULL, NULL, NULL, 'Appears on the BBS, confirming she is alive.', 'Member of The Rememberers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4598, 4719, 402, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.entity_scene_appearances VALUES (4599, 3993, 403, 'ally', true, NULL, 'Frantic and terrified, desperately trying to document a traumatic nightmare to ground himself in reality. His state shifts to shocked disbelief and fear upon discovering the altered objects and the impossible message.', NULL, NULL, 'The scene opens with him, unable to sleep after the traumatic events.', 'He is tormented by the memory of Jamie burning for loving him, and is given a cryptic mission by the Mysterious Handwriting to find ''The Boy Who Remembers'', an apparent aspect of himself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4600, 1407, 403, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The source of Stephen''s immediate trauma, containing horrific visions of his friends Becca, Patrick, and Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4601, 4687, 403, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A tool for Stephen that is co-opted by an unknown force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4602, 2882, 403, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Friend of Stephen and Patrick; victim of The Nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4603, 2896, 403, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Friend of Stephen and Becca; victim of The Nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4604, 4211, 403, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'A love interest to Stephen, whose connection to him causes her immense suffering in the nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4605, 4726, 403, 'unknown', true, NULL, NULL, NULL, NULL, NULL, 'Belongs to Whitney, but its current state suggests a more sinister influence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4606, 4354, 403, 'unknown', true, NULL, NULL, NULL, NULL, NULL, 'A key artifact pointing Stephen toward his next objective.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4607, 4728, 403, 'unknown', true, NULL, NULL, NULL, NULL, NULL, 'An unknown entity communicating with Stephen, guiding or manipulating him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4608, 4729, 403, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'An integral part of Stephen''s psyche that he must find.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4609, 4730, 403, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A physical manifestation of Stephen''s subconscious turmoil.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4610, 4342, 403, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Owner of the deck box; a friend Stephen is concerned about.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4965, 5090, 433, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A gift from Benji to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4611, 2608, 403, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Mentioned by the Mysterious Handwriting as the one who taught Stephen ''that love comes with conditions''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4612, 4733, 403, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.entity_scene_appearances VALUES (4613, 3993, 404, 'ally', true, 'The physical marks of his father''s abuse—bruises and belt welts—have mysteriously vanished from his body, leaving his skin unmarked.', 'Initially rigid with fear, he becomes terrified and deeply unsettled by his father''s kind demeanor and the disappearance of his injuries, viewing the situation as a dangerous trap.', NULL, NULL, NULL, 'Son of ''The False Father'' and the ''Memory of the Abusive Father''. He is the recipient of a warning from Whitney via her journal and sketch.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_scene_appearances VALUES (4615, 4736, 404, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The true nature of the man whose face ''The False Father'' is wearing. His predictable cruelty is contrasted with the ''False Father''s'' more dangerous psychological manipulation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_scene_appearances VALUES (4616, 4737, 404, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A physical manifestation of the False Father''s power and the unreality of the current situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.entity_scene_appearances VALUES (4617, 4738, 404, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A conduit for a message from Whitney, a potential ally.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
