INSERT INTO public.entity_scene_appearances VALUES (4621, 3993, 405, 'ally', true, NULL, 'Initially sharing in the group''s desperation, he takes a leading role in both providing proof (the Veilwalker card) and initiating the summoning ritual for Benji. He is terrified but determined when confronted with Benji and Reality''s Scream.', 'Now possesses the Veilwalker MTG card, which is warm to the touch.', NULL, NULL, 'Acts as a leader and point of focus for the group''s attempts to understand and combat the fractured reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
