INSERT INTO public.entity_scene_appearances VALUES (4703, 1555, 412, 'mini-boss', true, 'The trailer is no longer a static object but a living, breathing entity. Its aluminum siding expands and contracts like lungs, and it actively lures people closer with supernatural phenomena.', 'Exhibits a predatory patience and hunger.', NULL, NULL, NULL, 'Acts as a prison or vessel for an unknown entity that uses Whitney''s memory as bait.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.entity_scene_appearances VALUES (4704, 4579, 412, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Their internal dynamics are a mix of new romance, friendship, and conflict driven by fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
