INSERT INTO public.entity_scene_appearances VALUES (4790, 3993, 419, 'ally', true, NULL, 'His emotional state shifts from cautious curiosity to a deep, protective love for Jamie. He actively chooses to embrace their fragile, new reality over the warnings he''s received, feeling more alive in this ''lie'' than he did in his previous life.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.entity_scene_appearances VALUES (4714, 3993, 413, 'ally', true, NULL, 'Experiences escalating terror and sensory overload while descending the stairs, shifting to desperate resolve as he witnesses Patrick''s sacrifice and takes the journal to escape.', 'Acquires Whitney''s Journal at the end of the scene.', NULL, NULL, 'Acts as the narrator and a member of the group, trying to keep them together. He is the one Patrick entrusts with the journal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4715, 4211, 413, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the group who seems to have a past connection to the forces in this realm. She is repelled by the containment fields around the journal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4716, 2896, 413, 'ally', true, NULL, NULL, NULL, 'His body is torn apart and scattered across dimensions by a vortex after he throws the journal to the narrator, his sacrifice serving as the price to move the anchor.', NULL, 'Deeply in love with Whitney, which fuels his actions. He is a loyal friend who sacrifices himself for the group''s escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4717, 2474, 413, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the group, saved by TJ when she is nearly pulled into the vortex.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4718, 2884, 413, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the group who saves Morgan from being pulled into the dimensional vortex.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4719, 2882, 413, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the group who attempts to save Patrick and is devastated by his death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4720, 4738, 413, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The focus of Patrick''s quest and the key to the group''s potential escape. It belonged to Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4721, 4844, 413, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The primary obstacle preventing the retrieval of the journal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4722, 637, 413, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Servants or inhabitants of the dimension, unleashed when the anchor is disturbed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.entity_scene_appearances VALUES (4723, 4846, 413, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Likely the consciousness or a part of the entity that owns the dimension they are trapped in.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
