INSERT INTO public.entity_scene_appearances VALUES (4725, 4848, 413, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Products of the dimension''s reality-warping nature, affecting the group psychologically.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
