INSERT INTO public.entity_scene_appearances VALUES (4727, 3993, 414, 'ally', true, NULL, 'Experiences traumatic shock, guilt, and helplessness in the face of Becca''s rage and the reality of Patrick''s erasure. He acts as a quiet defender of Jamie and the keeper of Whitney''s journal.', 'Now possesses Whitney''s Journal.', NULL, NULL, 'Target of Becca''s rage, protector of Jamie, and leader of the surviving group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.entity_scene_appearances VALUES (4728, 2882, 414, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Mourns Patrick deeply. Blames the narrator and Jamie for his death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.entity_scene_appearances VALUES (4729, 4211, 414, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Target of Becca''s rage. Has a protective but complicated relationship with the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
