INSERT INTO public.entity_scene_appearances VALUES (4742, 3993, 415, 'ally', true, NULL, 'Experiences a mix of grim determination to preserve memory, relief that the memories persist, and profound grief and loneliness over losing connections to Patrick and Whitney.', NULL, NULL, NULL, 'Mourns the loss of his friend Patrick and the severed connection to Whitney. His actions are driven by the desire to preserve their memory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:02:49.473155-05', '2026-02-28 19:02:49.473155-05');
