INSERT INTO public.entity_scene_appearances VALUES (4744, 4869, 415, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:02:49.473155-05', '2026-02-28 19:02:49.473155-05');
INSERT INTO public.entity_scene_appearances VALUES (4745, 4738, 415, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A physical, but now severed, link to Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:02:49.473155-05', '2026-02-28 19:02:49.473155-05');
INSERT INTO public.entity_scene_appearances VALUES (4746, 4342, 415, 'ally', false, NULL, NULL, NULL, NULL, 'She is mentioned in relation to her now-silent journal, representing a lost connection and a source of grief.', 'A lost friend whose voice is no longer accessible to the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:02:49.473155-05', '2026-02-28 19:02:49.473155-05');
INSERT INTO public.entity_scene_appearances VALUES (4747, 4872, 415, 'neutral', true, NULL, NULL, NULL, NULL, 'Emerges as the final, dominant feeling of the scene after the narrator confirms the lost connection.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:02:49.473155-05', '2026-02-28 19:02:49.473155-05');
INSERT INTO public.entity_scene_appearances VALUES (4748, 4873, 415, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:02:49.473155-05', '2026-02-28 19:02:49.473155-05');
INSERT INTO public.entity_scene_appearances VALUES (4749, 3993, 416, 'ally', true, 'Experiences a vivid, painful memory of his wife''s death, triggered by Jamie''s words. He learns the truth about Jamie''s nature and her role in the timeline, leaving him reeling from the revelations about his past lives and the potential artificiality of his marriage.', 'Shifts from quiet grief to shock, confusion, and incredulity as he processes Jamie''s cosmic confessions and the breakdown of reality around him.', NULL, NULL, NULL, 'His relationship with Jamie is completely reframed from a mysterious girl to an ancient cosmic being who has loved him across lifetimes. He is forced to reconsider his entire life with his deceased wife, questioning its reality and her role in the ''script''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4750, 4876, 416, 'mini-boss', true, NULL, NULL, NULL, 'Falls asleep, becoming a conduit for other voices before waking with no memory of the event.', 'Appears in the narrator''s room by slipping through the window frame like smoke.', 'Reveals she is an ancient being who was assigned to monitor the narrator. She fell in love with him after watching him survive impossible odds across lifetimes and may have caused the current reality fractures by pulling him back from death out of desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4836, 2883, 422, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Acts as a source of comfort and protection for Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.entity_scene_appearances VALUES (4751, 1786, 416, 'neutral', false, NULL, NULL, NULL, 'Dies in the memory as the heart monitor flatlines.', 'Appears within a memory triggered by Jamie''s words.', 'The narrator''s wife for over thirty years. Their relationship was built on prescribed roles rather than deep emotional connection, leaving both of them lonely.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4752, 4738, 416, 'neutral', true, 'The journal becomes an active participant in the scene. It transforms its cover to resemble ''Elysium Rising'', displays impossible photographs, and writes cryptic messages in shifting handwriting with ink that defies gravity.', NULL, NULL, NULL, NULL, 'Acts as a conduit for information and a visual indicator of reality''s breakdown, seemingly responding to Jamie''s revelations.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4753, 4879, 416, 'enemy', false, 'Revealed to be losing control of the prison realm, Etheris. He feeds on the identity confusion and trauma caused by souls being endlessly reborn with wiped memories.', NULL, NULL, NULL, 'Mentioned by Jamie as the controller of the prison realm.', 'The creator and master of Velistra Seducera, whom he forged as a ''perfect weapon''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4754, 4880, 416, 'ally', true, NULL, NULL, NULL, 'Ceases speaking as Jamie wakes up.', 'Manifests through Jamie after ink from the journal flows into her sleeping body.', 'Acts as an ally to the narrator, confirming Whitney is safe and providing a critical clue about his ''true name''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4755, 4342, 416, 'ally', false, 'Her status is updated by one of the disembodied voices, which states, ''She''s safe. Whitney''s safe. I''m holding the door for her''.', NULL, NULL, NULL, 'Mentioned by the voice speaking through Jamie.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4756, 4882, 416, 'enemy', false, NULL, NULL, NULL, 'Its purpose is fulfilled when the wife dies.', 'Appears in the narrator''s flashback to the hospital room.', 'The direct cause of the narrator''s wife''s death and a source of his past trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4757, 4883, 416, 'neutral', true, 'Jamie confesses that her desperate act of pulling the narrator back from death may have created or exacerbated the timeline fractures, making her partially responsible for the current state of reality.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4758, 4884, 416, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.entity_scene_appearances VALUES (4759, 3993, 417, 'ally', true, NULL, 'Starts the scene trying to maintain control and systematically investigate, but is thrown into a state of shock, denial, and existential dread upon being confronted with a past life and name (''Aspolin'') he doesn''t remember. The reality glitch solidifies his fear.', NULL, NULL, NULL, 'The narrator and protagonist, whose forgotten past as ''Aspolin'' is the key to the current mystery. He is friends with Jamie, Morgan, TJ, and Andrew.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.entity_scene_appearances VALUES (4760, 4211, 417, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A friend of Stephen and the group, acting as a reluctant guide or truth-teller.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.entity_scene_appearances VALUES (4761, 2474, 417, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A friend to the group with a significant crush on TJ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.entity_scene_appearances VALUES (4762, 2884, 417, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A core member of the friend group, and the object of Morgan''s affection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.entity_scene_appearances VALUES (4763, 2883, 417, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A friend to the group, providing levity in tense situations.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.entity_scene_appearances VALUES (4764, 4738, 417, 'unknown', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.entity_scene_appearances VALUES (4765, 2882, 417, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'A close friend of the group whose disappearance is a major emotional weight on them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.entity_scene_appearances VALUES (4766, 4893, 417, 'mini-boss', false, NULL, NULL, NULL, NULL, NULL, 'An enemy of the group who has taken over their friend, Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.entity_scene_appearances VALUES (4767, 4894, 417, 'neutral', true, NULL, NULL, NULL, 'Disappeared as part of a reality glitch, being replaced by a poster.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
