INSERT INTO public.entity_scene_appearances VALUES (4804, 3993, 420, 'ally', true, NULL, 'Frustrated and isolated, as he is the only one perceiving the subtle, unsettling shifts in reality while his friends embrace the false normalcy. He is insistent that something is deeply wrong.', NULL, NULL, NULL, 'Protagonist and narrator. Feels a growing attraction to Jamie. Acts as the group''s Cassandra, warning them of a danger they can''t see.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.entity_scene_appearances VALUES (4805, 4211, 420, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A supernatural entity becoming human. Developing a close, romantic-coded relationship with Stephen. Seen as a source of answers by the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.entity_scene_appearances VALUES (4806, 2882, 420, 'ally', true, NULL, NULL, NULL, NULL, 'Slams the lab door open, appearing suddenly and startling the group. She has just returned from a three-week stay at a conversion therapy facility.', 'A member of the friend group who was forcibly removed. Her return and traumatic experience galvanize the group''s resolve.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
