INSERT INTO public.entity_scene_appearances VALUES (4817, 3993, 421, 'ally', true, 'Sustains unspecified injuries during the chaotic escape, with his clothes singed and skin streaked with soot and blood.', 'His initial relief at sharing the journal turns to terror and desperation as reality collapses around him. He attempts to lead the group''s escape.', NULL, NULL, NULL, 'Acts as the de facto leader of the escaping group of students.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
