INSERT INTO public.entity_scene_appearances VALUES (4831, 4959, 422, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'Leader of the Firefighters and enforcer of the Reality Containment Protocols against the Named Group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.entity_scene_appearances VALUES (4832, 3993, 422, 'ally', true, NULL, 'Experiences escalating confusion and terror as he witnesses reality collapsing and learns his friend Jamie feels responsible for their predicament.', NULL, NULL, NULL, 'A member of the targeted group. Jamie has a protective mission focused on him, and he is friends with the others.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.entity_scene_appearances VALUES (4833, 4211, 422, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Feels responsible for the group''s safety, especially Stephen''s. Her choice to ''love Stephen'' violated her mission parameters.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.entity_scene_appearances VALUES (4834, 2474, 422, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'In a romantic relationship with TJ, which she solidifies with a desperate kiss.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.entity_scene_appearances VALUES (4835, 4963, 422, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'In a romantic relationship with Morgan, which he finally accepts and reciprocates.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.entity_scene_appearances VALUES (4845, 3993, 423, 'ally', true, NULL, 'Begins in a state of confusion and helplessness, which shifts to terror for Jamie''s safety. After her deletion, he experiences a tidal wave of grief and violent rage, which finally subsides into a cold, calculating state of shock and resolve.', NULL, NULL, 'Materializes in the chamber already restrained to a metal table along with the rest of the group.', 'Deeply attached to Jamie, viewing her as a person who chose love. He is allied with TJ, Andrew, and Becca. He sees the Auditor as a monstrous murderer.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.entity_scene_appearances VALUES (4928, 2884, 430, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A core member of the group, providing the location for their work and participating directly in experiments.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4846, 4211, 423, 'ally', true, NULL, NULL, NULL, 'Brutally and completely deleted from existence by the Auditor after being deemed a ''glitch'' that progressed beyond repair.', 'Appears restrained on a metal table alongside Stephen and the others.', 'Deeply in love with Stephen (ኢልከሴሮድመሜብሃባኖኖራሊሊ), a choice she defends with her life. She is an asset of an entity named Yaldabaoth, but has broken from her original programming.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.entity_scene_appearances VALUES (4848, 2884, 423, 'ally', true, NULL, NULL, NULL, NULL, 'Appears restrained on a table at the start of the scene.', 'An ally of Stephen, Andrew, and Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.entity_scene_appearances VALUES (4849, 2883, 423, 'ally', true, NULL, NULL, NULL, NULL, 'Appears restrained on a table at the start of the scene.', 'An ally of Stephen, TJ, and Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.entity_scene_appearances VALUES (4850, 2882, 423, 'ally', true, NULL, NULL, NULL, NULL, 'Appears restrained on a table at the start of the scene.', 'An ally of Stephen, TJ, and Andrew.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
