INSERT INTO public.entity_scene_appearances VALUES (4871, 3993, 425, 'ally', true, NULL, 'Experiences a surge of raw, triumphant defiance upon discovering the Auditor''s mistake, which quickly turns to horror and guilt upon witnessing the consequences of his actions.', NULL, NULL, NULL, 'Creator of the paradox that leads to Patrick''s death, earning Becca''s condemnation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.entity_scene_appearances VALUES (4873, 5001, 425, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A deceased friend of Stephen''s group whose true identity creates a system-breaking paradox.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.entity_scene_appearances VALUES (4874, 2896, 425, 'ally', true, NULL, NULL, NULL, 'Brutally deconstructed and deleted by the Paradox Resolution Mechanism to resolve a computational overflow caused by Jennifer''s paradoxical memory.', 'Appears suddenly where a bloodstain used to be, already in the process of being deconstructed.', 'Friend of Stephen and Becca. His death is a direct consequence of Stephen''s actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.entity_scene_appearances VALUES (4875, 2882, 425, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Friend of Stephen and Patrick. Her relationship with Stephen is shattered by his choice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
