INSERT INTO public.entity_scene_appearances VALUES (4878, 3993, 426, 'ally', true, NULL, 'Experiences profound confusion and disorientation upon waking in the reset reality. This shifts to disgust and alarm at the False Jamie''s behavior, and finally to immense relief and exhaustion upon the real Jamie''s return.', 'Acquires Jennifer''s Journal from his locker.', NULL, NULL, 'Boyfriend to both the False Jamie (unwillingly) and the real Jamie. Friend to the absent group of TJ, Morgan, Andrew, and Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.entity_scene_appearances VALUES (4879, 5007, 426, 'mini-boss', true, NULL, NULL, NULL, 'Her programming crashes and is overwritten by the real Jamie''s consciousness after touching Jennifer''s Journal.', NULL, 'Acts as Stephen''s girlfriend, but is an unwanted impostor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.entity_scene_appearances VALUES (4880, 4211, 426, 'ally', true, NULL, NULL, NULL, NULL, 'Her consciousness resurfaces and takes control of the ''False Jamie'' body after it is exposed to Jennifer''s Journal.', 'Stephen''s girlfriend, restored to her true self.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.entity_scene_appearances VALUES (4881, 5009, 426, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
