INSERT INTO public.entity_scene_appearances VALUES (4929, 2474, 430, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The lead scientist of the group, using TJ as a test subject and having her theories validated by Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4930, 2883, 430, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the group who provides the final piece of the puzzle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4891, 3993, 427, 'ally', true, 'Sustains a bloody nose and bruising after being physically assaulted by Becca. His glasses are knocked off during the attack.', 'Experiences a mix of denial about the previous supernatural events and profound guilt over Patrick''s death, accepting Becca''s assault as a deserved penance. He is anchored to reality by Jamie''s presence.', NULL, NULL, NULL, 'Protagonist. Attacked by Becca due to his role in Patrick''s death. Supported and defended by his girlfriend, Jamie. Part of the core group with TJ and Morgan investigating the supernatural occurrences.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4892, 2882, 427, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A close friend of Patrick, whom she was romantically interested in. She violently confronts Stephen before clinging to the hope that the returned Patrick can be ''fixed''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4893, 4211, 427, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Stephen''s girlfriend. She acts as his protector and anchor to reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4894, 2896, 427, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The returned version of a deceased friend. He is the focus of Becca''s desperate hope and the group''s suspicion and fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4895, 5009, 427, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A key tool for the group''s investigation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4896, 2474, 427, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'In a new, slightly awkward relationship with TJ. She acts as the group''s primary researcher and strategist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4897, 2884, 427, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'In a new relationship with Morgan. He is a loyal friend to the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4898, 5027, 427, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An oppressive force working against the protagonists'' awareness of the truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4899, 5028, 427, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A direct consequence of Patrick''s disappearance, fueling the conflict between Stephen and Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4900, 868, 427, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An antagonist to the general student body, representing the mundane evil that thrives when larger threats are dealt with.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4901, 4912, 427, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Serve as an audience and a representation of the normal world the main characters are no longer fully part of.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4902, 4505, 427, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'A potential source of information or aid for the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4903, 5032, 427, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.entity_scene_appearances VALUES (4904, 3993, 428, 'ally', true, NULL, 'Disturbed and overwhelmed as he relives thousands of his own deaths from a single day by reading from the journal. He is also frustrated by the overwhelming amount of conflicting information.', NULL, NULL, NULL, 'The focal point of the journal''s revelations. He is supported by his friends but bears the primary burden of the memories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4905, 4579, 428, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A tight-knit group of friends trying to support each other through a traumatic and confusing situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4906, 2884, 428, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A supportive friend to the others, often grounding the situation with his blunt reactions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4907, 2474, 428, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Acts as the group''s chronicler and voice of reason.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4908, 2883, 428, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Deeply mourning Patrick, his actions are driven by grief and a sense of hopelessness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4909, 2882, 428, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Her actions towards Patrick are driven by a desperate and possibly misguided attempt to reclaim what was lost.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4910, 2896, 428, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The subject of Andrew''s grief and Becca''s desperate experiments. His presence is a source of tension and unease for the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4911, 4211, 428, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Provides comfort and insight to Stephen, acting as a guide.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4912, 5009, 428, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The central clue the group is trying to decipher.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4913, 5042, 428, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A symbol of Andrew''s grief for Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4914, 5043, 428, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'An unseen antagonist that has trapped the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4915, 4505, 428, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'An ally the group is forbidden from contacting by The Monitoring System.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4916, 5045, 428, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.entity_scene_appearances VALUES (4917, 3993, 429, 'ally', true, NULL, 'Moves from panic and terror caused by his recurring nightmare to a state of tentative hope and intimacy due to Jamie''s intervention. His perception of February 14th begins to shift from mortality to possibility.', NULL, NULL, NULL, 'He is comforted and seduced by Jamie, who seeks to overwrite his trauma associated with February 14th. He is haunted by the memory of his mother, አንጀላህጃን.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.entity_scene_appearances VALUES (4918, 2544, 429, 'ally', true, 'Appears ethereal and angelic in the backlit doorway, though shadows cling to her. Her actions are deliberate and ritualistic.', 'Displays understanding and tenderness towards Stephen''s trauma, acting with a seductive and reverent purpose to transform his pain into love.', NULL, NULL, 'Slips into Stephen''s room through his window door to comfort him after sensing he was having a nightmare.', 'Acts as a comforter, lover, and source of lore for Stephen, revealing information about Yaldabaoth while physically and emotionally reassuring him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.entity_scene_appearances VALUES (4919, 2549, 429, 'enemy', false, 'Appears in Stephen''s memory as a figure of ''false concern,'' whose syrupy words hide guilt and relief regarding her son''s suffering.', NULL, NULL, NULL, NULL, 'Her memory is a source of trauma for her son, Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.entity_scene_appearances VALUES (4920, 5049, 429, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist of the scene''s first beat, directly tormenting Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.entity_scene_appearances VALUES (4921, 4510, 429, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The entity Stephen is ''really fighting''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.entity_scene_appearances VALUES (4922, 4263, 429, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The source of Stephen''s certainty about the pattern of his deaths.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.entity_scene_appearances VALUES (4923, 5052, 429, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The central point of conflict that Jamie tries to transform for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.entity_scene_appearances VALUES (4925, 3993, 430, 'ally', true, NULL, 'Experiences a moment of dawning realization in the library, followed by hope and shock upon the discovery of the photograph''s significance as a dimensional anchor.', NULL, NULL, NULL, 'Collaborates with Patrick, Becca, TJ, Morgan, Andrew, and Jamie to solve the mystery of the timeline fractures. The photograph is a direct link to his past.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4926, 2896, 430, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Acts as a key analytical partner to Stephen and the group. Develops a physically intimate but data-driven relationship with Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4927, 2882, 430, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Collaborates with Patrick in an intimate way to discover key geographical coordinates.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4931, 2544, 430, 'ally', true, NULL, 'Acts as a knowledgeable and confirming presence, radiating confidence in the group''s theories. Shows recognition and excitement when the photograph is mentioned.', NULL, NULL, NULL, 'Serves as a source of validation for Morgan''s theories and helps confirm the significance of the photograph.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4932, 5009, 430, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The central clue the group is working to decipher.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4933, 4883, 430, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The main antagonist force the group is fighting against.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4934, 5063, 430, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by Andrew as the missing component for the dimensional travel experiment.', 'A direct physical link to Stephen''s past and the key to the group''s mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4935, 5064, 430, 'neutral', true, NULL, NULL, NULL, 'The experiment failed and the Tesla coil shorted out.', NULL, 'The physical manifestation of Morgan''s theories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4936, 5065, 430, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The primary target of the group''s investigation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4937, 5066, 430, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A part of Stephen''s forgotten past, anchored by the photograph.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4938, 5067, 430, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.entity_scene_appearances VALUES (4939, 2544, 431, 'ally', true, 'Leads the dimensional breach ritual, using her own blood for the sigil. She is injured in the explosion but remains resolute.', 'Focused and determined during the ritual, then battered but pragmatic after its failure.', 'Uses chalk mixed with her blood to create the reflection sigil.', NULL, NULL, 'A key member of the group, working closely with Stephen, TJ, and Morgan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4940, 3993, 431, 'ally', true, 'Participates in the ritual and witnesses a vision of his eight-year-old self. He is injured in the explosion and feels a profound sense of guilt over what happened to Patrick.', 'Anxious before the ritual, horrified by the vision of his past, and finally filled with guilt and determination.', NULL, NULL, NULL, 'The narrator and a member of the group. He feels responsible for Patrick''s condition.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4941, 2884, 431, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the core group with Stephen, Jamie, Morgan, and the others.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4942, 2474, 431, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the core group, providing the scientific and logical framework for their actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4943, 2883, 431, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of the core group. He is left behind with Becca to recover from his injuries.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4944, 2896, 431, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The focus of Becca''s grief and desperation. His transformation and subsequent ''reboot'' is a source of trauma and guilt for the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4945, 2882, 431, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Deeply attached to Patrick, her actions are driven by her love for the person he used to be. She takes on a caretaker role for him and Andrew.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4946, 5075, 431, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
