INSERT INTO public.entity_scene_appearances VALUES (4948, 5077, 431, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears when the dimensional membrane forms during the ritual.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
