INSERT INTO public.entity_scene_appearances VALUES (4953, 5082, 431, 'enemy', true, NULL, NULL, NULL, 'Destroyed by the explosion from the failed ritual.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4954, 5083, 431, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.entity_scene_appearances VALUES (4955, 3993, 432, 'ally', true, NULL, 'Feels alienated, deeply unsettled, and trapped by the ''aggressive normalcy'' of his false family. His trauma responses are triggered by their kindness, and he is filled with a quiet resolve to escape this constructed reality.', NULL, 'Escapes to his room to get away from his parents and prepare for his departure.', NULL, 'Son of ''Wrong Dad'' and ''Wrong Mom'', whom he internally rejects. He feels a deep disconnect from them and their performative affection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_scene_appearances VALUES (4956, 2550, 432, 'enemy', true, 'Appears as a perfect sitcom father, wearing khaki shorts and a polo shirt, performing mundane chores with meditative calm. This facade is part of the false reality designed to contain Stephen.', 'Presents as a cheerful, supportive father, but this cracks to reveal frantic desperation when Stephen announces his departure. He becomes a mouthpiece for the false reality''s absurd attempts to keep Stephen contained.', NULL, NULL, NULL, 'Acts as the father figure in the false reality, attempting to control Stephen through manufactured kindness and bribery.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_scene_appearances VALUES (4957, 2549, 432, 'enemy', true, 'Appears as a Stepford wife, radiating a glossy, impenetrable happiness and manufactured maternal joy. Her contentment is described as being like ''fresh paint''.', 'Her performative joy escalates into manic, desperate bribery when faced with Stephen''s plan to leave, showing the hollow and programmed nature of her affection. She resets to her cheerful baseline after Stephen retreats.', NULL, NULL, NULL, 'Acts as the mother figure in the false reality, using excessive cheer and absurd offers to manipulate Stephen into staying.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_scene_appearances VALUES (4958, 5027, 432, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Is the baseline state of the false reality Stephen finds himself in at the start of the scene.', 'The primary antagonistic force of the scene, using the ''Wrong Parents'' as its agents to control Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_scene_appearances VALUES (5284, 5423, 466, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (4959, 5089, 432, 'enemy', true, NULL, NULL, NULL, 'Ceases when Stephen shouts his intention to leave, causing the parents'' programming to temporarily freeze.', 'Begins when Stephen announces his need for money to travel to Nevada.', 'A tool used by the ''Aggressive Normalcy'' and the parents to manipulate Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_scene_appearances VALUES (4960, 5090, 432, 'ally', true, NULL, NULL, NULL, NULL, 'Stephen takes hold of it upon retreating to his room, using it to anchor himself.', 'A gift from Benji, representing a real connection outside the false family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_scene_appearances VALUES (4961, 5091, 432, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.entity_scene_appearances VALUES (4962, 3993, 433, 'ally', true, NULL, 'Torn between the comfort of the artificial reality and the need for truth, but ultimately resolute. He feels a mix of nostalgia for a flawed past, deep love for Jamie, and grim determination to leave paradise.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4963, 2544, 433, 'ally', true, NULL, 'Terrified, conflicted by her family''s manipulations and the possibility of pregnancy, but ultimately defiant. Her bravado cracks, revealing fear, but she recommits to Stephen and their escape, choosing truth over comfort.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4964, 5094, 433, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4967, 2549, 433, 'neutral', false, 'Recalled as a wife who loved Stephen ''the way people love vintage furniture.'' Their relationship in the other timeline was a sterile, performative ''perfect choreography'' of affection without genuine feeling or connection.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4968, 5098, 433, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4969, 5099, 433, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The potential child of Stephen and Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4970, 5100, 433, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4971, 5101, 433, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4972, 5102, 433, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.entity_scene_appearances VALUES (4973, 3993, 434, 'ally', true, 'He is the narrator of this journey, carrying a significant photograph from his past that acts as a map. He is observant of the reality decay around him.', 'Begins the journey nervously, progresses through terror and confusion, and ends with a grim resolve to face his destination.', NULL, NULL, NULL, 'Boyfriend to Jamie (ብሪትለሪሌት), and friend to TJ and Morgan. He is the central protagonist of the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_scene_appearances VALUES (4974, 2544, 434, 'ally', true, 'She provides a grounding, rebellious presence for Stephen amidst the chaos. She is unafraid to explore the grotesque aspects of their journey.', 'Her initial defiant and sarcastic demeanor shifts to one of quiet, determined support for Stephen as the journey concludes.', NULL, NULL, NULL, 'Girlfriend to Stephen (ኢልከሴሮድመሜብሃባኖኖራሊሊ).', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_scene_appearances VALUES (4975, 2884, 434, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
