INSERT INTO public.entity_scene_appearances VALUES (4981, 5111, 434, 'neutral', true, NULL, NULL, NULL, 'The group boards the bus, leaving the station behind.', 'Sells the group their tickets to ''Nowhere, Nevada''.', 'An agent of the strange transit system, she provides the first explicit warning about their destination.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
