INSERT INTO public.entity_scene_appearances VALUES (4983, 5113, 434, 'neutral', true, NULL, NULL, NULL, 'A flash of light returns the four protagonists to the bus, leaving the ghosts behind.', 'The bus transitions here, and the protagonists find themselves suddenly inside.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
