INSERT INTO public.entity_scene_appearances VALUES (4987, 5117, 434, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.entity_scene_appearances VALUES (4988, 3993, 435, 'ally', true, 'His physical body is horrifically destroyed in the final explosion, with his skin blistering and peeling away, hair burning, and lungs searing. He remains conscious through the process, experiencing existential agony before his consciousness dissolves.', 'Moves from apprehension and disgust to profound relief and love upon seeing his younger self, which then shifts to horrified recognition of his mother''s betrayal. This culminates in a state of agonizing pain and a final, grim acceptance of the sacrifice required to change timelines.', NULL, NULL, NULL, 'Fuses with his younger self (Eight-year-old Stephen). Witnesses the brutal deaths of his friends TJ, Morgan, and his love, Jamie (ብሪትለሪሌት). Recognizes the betrayal inherent in his mother''s (አንጀላህጃን) actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4989, 2544, 435, 'ally', true, 'Suffers a catastrophic injury from an explosion, which tears away half her skull and face. Despite her fatal wounds, she attempts to crawl toward Stephen before being completely incinerated in a secondary methane detonation.', 'Initially focused and determined, creating protective sigils despite the desecrated environment. Her final moments are a display of desperate love and stubborn affection, trying to reach and communicate with Stephen even as she is dying.', 'Uses chalk mixed with her own blood to draw a powerful sigil on the church pulpit.', 'Killed in the catastrophic explosions that destroy the church.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4990, 2884, 435, 'ally', true, NULL, NULL, NULL, 'Killed instantly when the first explosion slams him into a wall.', 'Arrives with Stephen, Jamie, and Morgan to investigate the church in Nowhere, Nevada.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4991, 2474, 435, 'ally', true, NULL, NULL, NULL, 'Vaporized in a flash by a chemical reaction during the initial explosion.', 'Arrives with the group to analyze the temporal fracture point at the church.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4992, 5122, 435, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
