INSERT INTO public.entity_scene_appearances VALUES (4994, 5124, 435, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4995, 5125, 435, 'neutral', true, NULL, NULL, NULL, 'Dissolves into the present-day Stephen, fusing their timelines and triggering the catastrophic explosion.', 'Appears when reality tears, representing the original, untainted timeline Stephen is trying to reach.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4996, 5126, 435, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4997, 5127, 435, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4998, 2549, 435, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned as the source of the poison that fractured Stephen''s original timeline. Her betrayal is the core trauma Stephen confronts in the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (4999, 5129, 435, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.entity_scene_appearances VALUES (5000, 3993, 436, 'ally', true, 'His consciousness is now merged with two others (a child and an old man) inside his eight-year-old body, causing extreme disorientation and psychological conflict. He represents the determined, fighting aspect of the merged mind.', 'Experiences a mix of panic, confusion, and desperate fury. He is actively trying to regain control and assess the situation for survival, fighting against the memories and feelings of the other two consciousnesses.', NULL, NULL, 'Wakes up in a past version of his childhood bedroom after a reality-altering event, the Anchor Ritual, went unexpectedly.', 'Part of a fractured trinity with the Child and Old Man consciousnesses. Remembers his love for Jamie (ብሪትለሪሌት) and friendship with Whitney. Son of አንጀላህጃን and The Protagonist''s Father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5001, 5132, 436, 'unknown', false, NULL, NULL, NULL, 'Vanishes into silence after speaking a single phrase.', 'Calls out to the protagonist, initiating his awakening into the new reality.', 'The protagonist briefly associates the voice with ''Jennifer'' or ''Whitney''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5121, 4117, 449, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned as a fleeting thought.', 'Unknown connection to the protagonist''s past.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5002, 5133, 436, 'ally', true, NULL, NULL, NULL, NULL, 'Becomes aware as one of the three minds merged within the protagonist''s body.', 'The original inhabitant of the body, now a terrified passenger alongside the Teenager and Old Man consciousnesses.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5003, 5134, 436, 'neutral', true, NULL, NULL, NULL, NULL, 'Emerges as the third mind within the protagonist''s consciousness, seeping memories of hospice beds and failed dreams.', 'The fatalistic observer within the merged consciousness, contrasting with the Teenager''s fury and the Child''s terror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5004, 2549, 436, 'enemy', true, 'Perceived as a source of insidious danger. She is preparing a ''poison'' disguised as breakfast, continuing a cycle of abuse the protagonist now remembers.', 'Her emotional state is unknown, but her actions are perceived as methodical and threatening.', NULL, NULL, 'Her presence is revealed through the sound of humming from the kitchen as she prepares breakfast.', 'The protagonist''s mother, whose maternal care is a mask for a slow, poisonous form of abuse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5005, 5136, 436, 'mini-boss', true, NULL, NULL, NULL, 'Falls asleep, providing a temporary reprieve.', 'Slams the front door and stomps through the trailer before collapsing in his bedroom.', 'Father of the protagonist and husband of አንጀላህጃን. His role is that of a violent abuser.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5006, 5137, 436, 'neutral', true, NULL, NULL, NULL, NULL, 'Becomes fully realized when the protagonist understands there are three minds sharing one body.', 'The resulting entity from the flawed Anchor Ritual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5007, 2544, 436, 'unknown', false, NULL, NULL, NULL, NULL, 'Appears in a memory flash experienced by the teenager consciousness.', 'A significant, demonic figure from the teenager''s past, associated with love, desire, and destruction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5008, 4342, 436, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned as part of the teenager''s memories of how reality was altered.', 'A close friend whose erasure is a source of pain and motivation for the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5009, 5140, 436, 'neutral', false, NULL, NULL, NULL, NULL, 'Recalled as the cause of the protagonist''s current predicament.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5010, 5126, 436, 'enemy', true, NULL, NULL, NULL, NULL, 'The protagonist realizes his mother is preparing it when he hears her humming in the kitchen.', 'Weapon wielded by አንጀላህጃን.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5011, 5142, 436, 'unknown', true, NULL, NULL, NULL, 'Vanishes as quickly as she appeared.', 'Appears as an afterimage in the bathroom mirror, mouthing ''Remember me''.', 'Unknown, but her name ''tastes like geometry'', suggesting a connection to a different order of reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5012, 5143, 436, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.entity_scene_appearances VALUES (5013, 3993, 437, 'ally', true, NULL, 'Experiences a traumatic memory with layered consciousness—the fear of a child, the anger of a teenager, and the weary detachment of an old man. He moves from fearful observation to direct, world-breaking confrontation, and finally to a place of profound empathy and forgiveness for his mother.', NULL, NULL, NULL, 'Son of አንጀላህጃን and ኢልከሴሮድ. He is the victim of his mother''s poisoning, which is an attempt to protect him from his father''s violence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5014, 2549, 437, 'enemy', true, 'Her posture is broken and hunched, with yellowed bruises on her arms. Her skin has a waxy, bloated pallor, as if she is ''drowning slowly from the inside''.', 'Begins in a state of deceptive, ritualistic calm, playing the role of a caring mother. Upon being confronted, her psyche fractures, moving through confusion and horror into a complete breakdown of tectonic sobbing, grief, and horrified self-realization.', NULL, NULL, NULL, 'Mother of ኢልከሴሮድመሜብሃባኖኖራሊሊ and wife of ኢልከሴሮድ. She poisons her son out of a twisted desire to protect him from his father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5015, 2608, 437, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Father of ኢልከሴሮድመሜብሃባኖኖራሊሊ and husband of አንጀላህጃን. His violent nature is the catalyst for the entire scene, forcing his wife to take desperate, harmful measures to protect their son.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5016, 5147, 437, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5017, 5148, 437, 'enemy', true, NULL, NULL, NULL, 'Dropped by the mother and shatters on the floor when she is confronted.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5018, 5149, 437, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5019, 5150, 437, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5020, 5151, 437, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist force driving the actions of አንጀላህጃን.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5021, 5152, 437, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.entity_scene_appearances VALUES (5022, 3993, 438, 'ally', true, 'Now physically an eight-year-old, his consciousness is fractured into three distinct, warring personas: a terrified child, an angry teenager, and a resigned old man.', 'Overwhelmed by his mother''s confession, he is in a state of extreme distress, confusion, and internal conflict. He seeks refuge but is immediately confronted by cosmic revelations, shifting his state towards a fearful, reluctant acceptance of his role as a ''symptom'' of a failing reality.', NULL, NULL, NULL, 'His relationship with his mother is thrown into turmoil, seeing her as both a victimizer and someone trying to save him. He views Benji as a frustrating but necessary source of information. His fear of his father is amplified by the revelation that he is a vessel for Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5023, 2549, 438, 'unknown', false, NULL, 'Her actions of slowly poisoning her son are revealed, casting her in a dual light of maliciousness (''trying to kill us'') and misguided protection (''trying to save me''). She is the catalyst for the scene''s initial trauma.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5024, 4505, 438, 'ally', true, NULL, NULL, NULL, 'Fades away as the mirror repairs itself, complaining about cosmic paperwork and needing to report back to his supervisor.', 'Manifests by bending and then shattering the bathroom mirror into pure light.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5025, 4510, 438, 'mini-boss', false, NULL, NULL, NULL, NULL, NULL, 'Acts as the jailer of all humanity and is using the protagonist''s father as a vessel. He is the ultimate antagonist the protagonist must face.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5026, 5157, 438, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5027, 5158, 438, 'neutral', true, NULL, NULL, NULL, 'Vanishes when the protagonist tries to touch it, passing through it like empty air.', 'Appears suddenly on the edge of the sink during the protagonist''s internal debate.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5028, 5159, 438, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5029, 4342, 438, 'ally', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5030, 5161, 438, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5031, 2550, 438, 'enemy', false, 'Revealed to be a vessel or ''face'' for the cosmic entity Yaldabaoth, especially when Yaldabaoth is on ''autopilot''. His snoring is a sign of the entity''s dormancy, and its cessation signals the entity''s awakening.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5032, 5163, 438, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.entity_scene_appearances VALUES (5033, 3993, 439, 'ally', true, 'Appears as a small, vulnerable eight-year-old child. His body is described as a ''fragile eight-year-old shell'' with ''toothpick'' arms, incapable of defending itself.', 'Experiences a spectrum of emotions from grim resignation to pure terror that ''tastes like copper pennies.'' Under the physical assault, his consciousness fragments into three distinct personalities, each retreating from the overwhelming agony before he ultimately loses consciousness.', NULL, NULL, NULL, 'Son of ኢልከሴሮድ and አንጀላህጃን. He is the victim of his father''s brutal attack.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5034, 2608, 439, 'mini-boss', true, 'Appears as a physically imposing figure, ''six feet of rage'' in a wife-beater and jeans, smelling of motor oil. His face is flushed red and his eyes are bloodshot.', 'Consumed by a drunken, violent rage. He is described as a ''predator that''s caught a scent,'' moving with violent purpose and taking sadistic pleasure in the ''choreographed brutality'' he inflicts. His breathing becomes ''excited'' as the violence progresses.', 'Wields his leather belt as a weapon.', NULL, NULL, 'The father of the protagonist and husband of አንጀላህጃን. He is the abuser and primary antagonist of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5035, 2549, 439, 'neutral', true, NULL, 'Utterly helpless and terrified. She is reduced to stuttering sobs and whimpering, watching her son''s beating from the kitchen, too afraid to intervene because ''intervention only makes the monster hungrier.''', NULL, NULL, NULL, 'The mother of the protagonist and wife of ኢልከሴሮድ. She is a helpless witness to the abuse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5036, 5167, 439, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5037, 5168, 439, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A part of ኢልከሴሮድመሜብሃባኖኖራሊሊ''s psyche.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5038, 5169, 439, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A part of ኢልከሴሮድመሜብሃባኖኖራሊሊ''s psyche.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5039, 5170, 439, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A part of ኢልከሴሮድመሜብሃባኖኖራሊሊ''s psyche.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5040, 5171, 439, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An expression of ኢልከሴሮድ''s abusive nature.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5041, 5172, 439, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.entity_scene_appearances VALUES (5042, 3993, 440, 'ally', true, 'Physically subjected to repeated, brutal beatings within a time loop. His perception of reality is shattered, causing him to experience non-existent colors and un-invented languages as he is tortured across dimensions.', 'Begins with a brief, desperate hope that his trauma was a dream, which is immediately replaced by terror and despair. This state of agony becomes constant, culminating in a horrified understanding of his eternal, orchestrated punishment.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5043, 2550, 440, 'enemy', true, 'His form degrades from a human abuser into a series of increasingly monstrous and abstract forms. He becomes a naked, engorged figure, a being with ''too many mouths,'' and ultimately a ''probability cloud'' of violence, serving as a vessel for a cosmic entity.', 'His initial human rage transforms into a detached, cosmic cruelty and amusement at the protagonist''s suffering.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5044, 2549, 440, 'neutral', true, 'Her presence deteriorates with each cycle of the loop. She devolves from a whimpering woman in the kitchen to a distant sob, an echo, a shadow, and is finally erased from reality entirely.', 'Her initial state of audible fear and sorrow fades into nothingness as she is removed from existence.', NULL, 'Erased from reality by the deteriorating punishment loop after cycle 61,999.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5045, 5177, 440, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5046, 5178, 440, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5047, 5179, 440, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5048, 5180, 440, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Acts through ኢሌልመሜብሃባኖኖራሊሊ to torture ኢልከሴሮድመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5049, 5181, 440, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5050, 5182, 440, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.entity_scene_appearances VALUES (5051, 3993, 441, 'ally', true, NULL, 'Wakes in a state of confusion and terror, which escalates to paralyzed helplessness as he is confronted by his father and led to his apparent demise.', NULL, NULL, NULL, 'Son of the Leatherworker Father, who subjects him to a horrific ''final exam''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_scene_appearances VALUES (5052, 2550, 441, 'mini-boss', true, 'Appears as a calm, teacher-like figure in a well-worn leather apron, draped in dozens of belts.', 'Exhibits a detached, educational calmness that briefly flashes into hot-tempered anger before returning to a conversational tone while performing a monstrous act.', 'Wears a leather apron and carries an armful of dozens of belts.', 'Remains present as the protagonist is submerged in the vat, his purpose fulfilled.', 'Enters the room silently to administer a ''pop quiz''.', 'Father of the protagonist, acting as a surreal and terrifying educator in this nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_scene_appearances VALUES (5053, 5185, 441, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_scene_appearances VALUES (5054, 5186, 441, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_scene_appearances VALUES (5055, 5187, 441, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_scene_appearances VALUES (5056, 5188, 441, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_scene_appearances VALUES (5057, 5189, 441, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.entity_scene_appearances VALUES (5084, 5217, 445, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A symbolic representation of the central conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5285, 4141, 466, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5058, 3993, 442, 'ally', true, NULL, 'Experiences a moment of profound, grief-like longing for normalcy, followed by a fragile, desperate hope for paternal affection. This is violently replaced by a state of detached, horrified observation as he is vivisected by his father''s manifestation.', NULL, 'Is surgically disemboweled, causing his vision and consciousness to fracture at the end of the scene.', 'Wakes up within a hyperreal memory of his childhood home.', 'Son of አንጀላህጃን and ኢልከሴሮድ. He is the victim of his father''s surreal, violent lesson.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_scene_appearances VALUES (5059, 2549, 442, 'neutral', true, 'Appears as a comforting, peripheral part of a hyperreal memory, humming contentedly in the kitchen. She represents the idealized safety the protagonist craves.', 'Portrayed as content and peaceful.', NULL, 'Fades from focus as the scene shifts to the interaction with the father.', 'Is heard humming in the kitchen at the start of the memory.', 'Mother of the protagonist, wife of ኢልከሴሮድ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_scene_appearances VALUES (5119, 5253, 449, 'mini-boss', true, NULL, NULL, NULL, 'Begins to fade and blur, causing a second wave of pain as the protagonist feels he is losing Jamie all over again.', 'Appears first as a name, then a fragment, then a full-blown sensory flood triggered by a scent.', 'The primary antagonist of the scene, attacking the protagonist''s mental state and constructed reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5171, 5306, 454, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:52.537074-05', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_scene_appearances VALUES (5060, 2608, 442, 'mini-boss', true, 'Initially appears as a younger, relaxed, and kind version of himself. He then grotesquely transforms, his face crumpling, smile stretching into a shark-like maw, and eyes leaking a dark fluid.', 'His demeanor shifts from one of feigned paternal warmth to a terrifying, detached calm as he performs a surgical, educational vivisection on his son.', 'Produces a filleting knife made entirely of leather.', 'Dissolves his weapon and presumably fades as the protagonist''s vision fractures.', 'Appears in the bedroom doorway to offer a fishing trip.', 'Father of the protagonist. Acts as a monstrous tormentor in this memory-turned-nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_scene_appearances VALUES (5061, 5193, 442, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_scene_appearances VALUES (5062, 5194, 442, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_scene_appearances VALUES (5063, 5195, 442, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_scene_appearances VALUES (5064, 5196, 442, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.entity_scene_appearances VALUES (5065, 3993, 443, 'ally', true, NULL, 'After an eternity of repeated torture, his fear and pain have been worn down into a hollow, detached numbness. He now observes his own suffering with a distant, academic curiosity, which unexpectedly gives him power over his torturer.', NULL, 'The reset begins, causing reality to dissolve around him before he fully dies.', 'Surfaces into consciousness within the surreal bedroom.', 'Son of ኢልከሴሮድ. His newfound numbness breaks his father''s psychological hold over him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_scene_appearances VALUES (5066, 2608, 443, 'mini-boss', true, 'His physical form flickers with confusion when his son fails to react with fear, as if reality itself is struggling to maintain his terrifying presence.', 'His confident rage gives way to uncertainty, confusion, and finally desperation as he realizes his power over his son is an illusion based on a belief in pain that the victim no longer holds.', 'Enters wielding a Flaming Belt.', 'Is present as the scene dissolves for the reset.', 'Enters the bedroom to continue the cycle of torture.', 'Father and torturer of ኢልከሴሮድመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_scene_appearances VALUES (5067, 5199, 443, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_scene_appearances VALUES (5068, 5200, 443, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_scene_appearances VALUES (5069, 5201, 443, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_scene_appearances VALUES (5070, 5202, 443, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_scene_appearances VALUES (5071, 5203, 443, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_scene_appearances VALUES (5072, 5204, 443, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.entity_scene_appearances VALUES (5073, 3993, 444, 'ally', true, NULL, 'Transitions from a state of being tormented within the loop to one of calm, detached fascination and philosophical authority. He ultimately finds peace and gratitude in the final silence after confronting and deconstructing his tormentor.', NULL, NULL, NULL, 'Son of ኢሌልመሜብሃባኖኖራሊሊ. He is the victim of the loop created by his father, but in this scene, he seizes control of the narrative and dismantles his father''s power through logic and disbelief, ultimately achieving his freedom.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_scene_appearances VALUES (5074, 2550, 444, 'mini-boss', true, 'His form degenerates from a glitching human figure into a vast, impossible cosmic entity named Yaldabaoth. This divine form is unstable, described as an ''ill-fitting thrift store suit,'' and it progressively shrinks, flickers, and dissolves as its power wanes, finally detonating in a supernova of rage.', 'His emotional state devolves from abusive authority to arrogant divinity, which then crumbles into doubt, confusion, and finally a ''childish tantrum'' of pure, desperate rage upon realizing his defeat.', NULL, 'Self-destructs in a final, futile attempt to reset reality after being philosophically and existentially defeated by the protagonist.', 'Appears mid-swing, glitching and stuttering like a corrupted video file before transforming.', 'Father of ኢልከሴሮድመሜብሃባኖኖራሊሊ. He is revealed to be the Demiurge Yaldabaoth, the creator of the protagonist''s torturous loop, which he calls ''penance''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_scene_appearances VALUES (5075, 5207, 444, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A tool of torment wielded by ኢሌልመሜብሃባኖኖራሊሊ. It becomes insubstantial as its wielder''s power fades.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_scene_appearances VALUES (5076, 5208, 444, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A manifestation of Yaldabaoth''s power, their screams reflecting the false and painful nature of its divinity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_scene_appearances VALUES (5077, 5209, 444, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Represents the protagonist''s final freedom from the loop and his tormentor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_scene_appearances VALUES (5078, 5210, 444, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'An unknown observer, seemingly allied with or at least supportive of the protagonist''s victory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_scene_appearances VALUES (5079, 5211, 444, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.entity_scene_appearances VALUES (5080, 3993, 445, 'ally', true, 'Manifests as his eight-year-old self within the liminal waiting room, feeling small and out of place.', 'Begins disoriented and confused, with a sense of sharp, undeniable dread. This shifts to a grim understanding of the cosmic stakes of his confrontation with I AM.', NULL, NULL, 'Awakens in the scene at its start.', 'He is the sole object of I AM''s focus and the reason for their shared imprisonment. He is being guided and informed by Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5081, 2550, 445, 'mini-boss', true, 'His presence is not physical but environmental, causing the reality of the waiting room to flicker, grow cold, and undulate. He has inadvertently trapped himself in this finite space with the protagonist.', 'Implied to be experiencing isolation as a form of torture, unaware that this provides his adversary with a unique advantage.', NULL, NULL, 'Is the architect of the scene''s location, present from the beginning as the containing force.', 'Has imprisoned himself with his son, the one person who never believed in him, creating a paradoxical trap.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5082, 4505, 445, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Acts as a guide and expositor for the protagonist, explaining the nature of I AM''s trap and the opportunity it presents.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5083, 5216, 445, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5286, 370, 466, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5085, 5218, 445, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'An object used by Benji to punctuate his explanations and ground his surreal presence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5086, 5219, 445, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'Creators of Etheris; jailers of I AM.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5087, 5220, 445, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'This knowledge defines the ultimate stakes of the protagonist''s conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5088, 5221, 445, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The key condition needed for the protagonist to answer the question of divine mortality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5089, 5222, 445, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.entity_scene_appearances VALUES (5120, 3326, 449, 'unknown', false, NULL, NULL, NULL, NULL, 'Spoken aloud by the protagonist without him knowing why.', 'Connected to the protagonist''s lost memories, possibly a place or a code word.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5253, 5392, 463, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:21:08.477877-05', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_scene_appearances VALUES (5090, 3993, 446, 'ally', true, 'Appears as an eight-year-old boy but possesses the memories, fury, and martial skill of his older selves. He is able to channel these abilities into his small frame to fight a cosmic entity.', 'Begins with defiant fury, is momentarily staggered by painful truths revealed by his enemy, then escalates to a critical rage before settling into a cold, nihilistic resolve to destroy everything.', NULL, NULL, NULL, 'The son of and mortal enemy to I AM. His actions are fueled by rage and a desire to avenge the manipulation of his feelings for Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_scene_appearances VALUES (5091, 2550, 446, 'mini-boss', true, 'His form is no longer stable, appearing as a writhing, glitching mass of ''static and failing code'' that constantly collapses and rebuilds itself. He can form appendages, manifest his old face within a void, and cycle through the faces of other authority figures. Before his destruction, he is seen to have seven eyes arranged in a disturbing pattern.', 'Starts with divine arrogance, shifts to cruel, taunting mockery, and finally experiences genuine fear and terror just before being destroyed.', NULL, NULL, NULL, 'The protagonist''s father and arch-nemesis. He claims to have been rebuilt by ''The Outsiders'' and to have created the modern version of Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_scene_appearances VALUES (5092, 2544, 446, 'neutral', false, 'Re-contextualized by I AM as a ''creation'' and a ''succubus'' designed to keep the protagonist docile and controlled. This version of her is allegedly built from the protagonist''s memories of the real person.', NULL, NULL, NULL, NULL, 'Used as a psychological weapon by I AM against the protagonist. The protagonist''s final, destructive act is performed in her name.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_scene_appearances VALUES (5093, 5219, 446, 'unknown', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_scene_appearances VALUES (5094, 5227, 446, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_scene_appearances VALUES (5095, 5228, 446, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_scene_appearances VALUES (5096, 5229, 446, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.entity_scene_appearances VALUES (5097, 3993, 447, 'ally', true, 'His physical form dissolves into static and then nothingness as reality collapses.', 'Experiences a profound sense of peace and relief upon witnessing and accepting the end of everything, feeling as though a great weight has been lifted. His final question reveals a lingering, childlike vulnerability regarding Jamie.', NULL, 'Peacefully dissolves into the void as a fundamental part of the collapsing reality.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_scene_appearances VALUES (5098, 5231, 447, 'neutral', true, NULL, NULL, NULL, 'Dissolves into the void along with the protagonist and the rest of reality.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_scene_appearances VALUES (5099, 2550, 447, 'enemy', false, 'Referred to in the past tense, having just been killed by the protagonist. His death is the direct cause of reality''s collapse, as he was intrinsically connected to its substrate.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_scene_appearances VALUES (5100, 2544, 447, 'ally', false, 'Her existence is explained as a paradox; she was both real to the protagonist and a ''beautiful lie'' he created. Benji suggests that the act of imagining her so perfectly might grant her existence in some other reality.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_scene_appearances VALUES (5101, 982, 447, 'neutral', true, 'Manifests as the active, peaceful dissolution of all reality. It is described as swirling mathematical chaos, a warm and silent void, and a ''digital ivy'' of static that painlessly un-makes everything.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_scene_appearances VALUES (5102, 5235, 447, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_scene_appearances VALUES (5103, 5236, 447, 'unknown', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.entity_scene_appearances VALUES (5104, 3993, 448, 'ally', true, NULL, 'Experiences a profound sense of normalcy and contentment, feeling unburdened as his memories of S Corp and cosmic responsibilities fade into intangible wisps. He feels a brief, passing sense of déjà vu about the contest prize.', NULL, NULL, NULL, 'Husband to አንጀላህጃን and father to The Son. He feels cocooned by their domestic presence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_scene_appearances VALUES (5105, 2549, 448, 'ally', true, NULL, 'She is incredibly happy and excited, displaying a ''huge grin'' as she announces that the family has won a major contest.', 'Is in possession of her phone, which she uses to show her husband the news.', NULL, NULL, 'Wife of ኢልከሴሮድመሜብሃባኖኖራሊሊ and mother of The Son.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_scene_appearances VALUES (5106, 831, 448, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Son of ኢልከሴሮድመሜብሃባኖኖራሊሊ and አንጀላህጃን.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_scene_appearances VALUES (5107, 2297, 448, 'neutral', false, 'Exists only as a distant, fading memory in the protagonist''s mind. The once ''vivid and tangible'' grandeur of the empire is now ''ethereal and intangible''.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_scene_appearances VALUES (5108, 4102, 448, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
