INSERT INTO public.entity_scene_appearances VALUES (5114, 465, 448, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.entity_scene_appearances VALUES (5115, 3993, 449, 'ally', true, NULL, 'Starts with quiet contemplation, but becomes increasingly confused, fearful, and ultimately overwhelmed by a flood of grief and loss from resurfacing memories.', 'Holding a coffee mug.', NULL, NULL, 'Husband to አንጀላህጃን, father to the Protagonist''s Son, and former lover of ብሪትለሪሌት (Jamie). His current reality is being destabilized by memories of Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5116, 2549, 449, 'ally', true, 'The protagonist now perceives her as a source of safe, predictable, and passionless love. He describes her affection as practiced and her presence as a ''beautiful mannequin'', contrasting sharply with his memories of Jamie.', 'Her mood shifts from normal morning conversation to concern for her husband''s strange behavior and words.', NULL, NULL, 'Joins her husband in the kitchen for breakfast.', 'Wife of the protagonist, mother of their son. Her relationship with her husband is shown to be lacking the passion he once knew.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5162, 20, 453, 'neutral', false, NULL, NULL, NULL, NULL, 'The author decides to write it after being laid off.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:12.367746-05', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_scene_appearances VALUES (5163, 3326, 453, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned as a clarification of the author''s completed work.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:12.367746-05', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_scene_appearances VALUES (5117, 2544, 449, 'ally', false, 'Her memory is now vividly detailed as a woman with dark eyes, a chaotic laugh, and a personality of ''fire and rebellion''. She is associated with a traumatic event involving a church, sand, and fire where she died trying to tell the protagonist something important.', NULL, NULL, NULL, 'Her name and memory surface in the protagonist''s mind.', 'A past lover of the protagonist, representing a passionate, chaotic, and ultimately tragic love that he is beginning to remember.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5118, 415, 449, 'ally', true, NULL, NULL, NULL, NULL, 'Is present in the room, playing on his computer, and joins the conversation.', 'Son of ኢልከሴሮድመሜብሃባኖኖራሊሊ and አንጀላህጃን.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5122, 4090, 449, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned as the destination of the family trip.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5123, 160, 449, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned in conversation.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5124, 4703, 449, 'neutral', true, NULL, NULL, NULL, NULL, 'The protagonist smells it from ingredients on the counter.', 'The catalyst for the main conflict of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5125, 5259, 449, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
INSERT INTO public.entity_scene_appearances VALUES (5126, 3993, 450, 'ally', true, NULL, 'Experiences a jarring shift from confusion and dread within a hallucinatory reality to a grounded, albeit stressed, state in his actual life. The comfort of routine replaces the supernatural horror.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:37:41.028865-05', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_scene_appearances VALUES (5127, 2549, 450, 'ally', true, 'During the hallucination, her face flickers, momentarily taking on the features of Jamie (ብሪትለሪሌት). She later appears as her normal self, humming in the kitchen.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:37:41.028865-05', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_scene_appearances VALUES (5128, 2544, 450, 'enemy', false, NULL, NULL, NULL, NULL, 'Her features are hallucinated onto the protagonist''s wife''s face, a visual manifestation of his unresolved past.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:37:41.028865-05', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.entity_scene_appearances VALUES (5129, 851, 450, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:37:41.028865-05', '2026-02-28 19:37:41.028865-05');
