INSERT INTO public.entity_scene_appearances VALUES (5136, 3993, 451, 'ally', true, NULL, 'Cynical and resigned to the drudgery of job hunting, yet also prone to brief moments of profound reflection and fleeting creative impulses which he quickly dismisses.', NULL, NULL, NULL, 'Engages with the mundane task of finding a job, reflecting his current state of unemployment and need for purpose. He feels a connection to the job at ExSpacey but is immediately weighed down by the process.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:38:22.705997-05', '2026-02-28 19:38:22.705997-05');
