INSERT INTO public.entity_scene_appearances VALUES (5148, 3993, 452, 'ally', true, NULL, 'Experiences profound confusion and fear, his body shaking uncontrollably after speaking an unknown word. This escalates into shock as a phone call triggers a flood of traumatic, suppressed memories.', NULL, NULL, NULL, 'Husband to አንጀላህጃን. Recipient of a call from Whitney. His past is intertwined with Jamie, William, Benji, and the events surrounding ''The Kick''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:39:11.351125-05', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.entity_scene_appearances VALUES (5149, 2549, 452, 'ally', true, NULL, 'Appears pale and distressed, holding her phone cautiously as if it were a threat. Her voice cracks with fear when announcing the caller.', NULL, NULL, 'Walks into the room to deliver a phone call to her husband.', 'Wife of ኢልከሴሮድመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:39:11.351125-05', '2026-02-28 19:39:11.351125-05');
