INSERT INTO public.entity_scene_appearances VALUES (5161, 3993, 453, 'ally', true, NULL, 'Reflective and determined, recounting his creative journey after a professional setback. He expresses frustration with the traditional publishing route but satisfaction in completing his long-held project.', NULL, NULL, NULL, 'The author and creator of ''Elysium Rising'' and ''Sorhhinda''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:12.367746-05', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_scene_appearances VALUES (5164, 5299, 453, 'neutral', false, NULL, NULL, NULL, NULL, 'The catalyst for the author''s decision to start writing.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:12.367746-05', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_scene_appearances VALUES (5165, 5300, 453, 'neutral', false, NULL, NULL, NULL, NULL, 'Approached by the author after the manuscript was finished.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:12.367746-05', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_scene_appearances VALUES (5166, 5301, 453, 'neutral', false, NULL, NULL, NULL, NULL, 'Serves as the final step in the author''s publication journey.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:12.367746-05', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_scene_appearances VALUES (5167, 5302, 453, 'neutral', false, NULL, NULL, NULL, NULL, 'Explained as the initial, ''boring'' concept for the book.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:12.367746-05', '2026-02-28 19:40:12.367746-05');
INSERT INTO public.entity_scene_appearances VALUES (5168, 3993, 454, 'ally', true, NULL, 'Experiences a burst of creative energy, followed by a month of stagnation and frustration, which is then broken by a vivid, inspiring dream. He feels a renewed sense of purpose after his character ''Jamie'' communicates with him.', NULL, NULL, NULL, 'The creator of the ''Elysium Rising Sequel'' and the character ''Jamie''. He is influenced by the ''AutoCrit 90 day writing challenge'' and obstructed by the ''Creative Wall''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:52.537074-05', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_scene_appearances VALUES (5169, 2544, 454, 'ally', false, 'Manifests as a presence within the author''s dreams, no longer just a character on a page but an active agent demanding existence.', 'Desperate and demanding, ''begging'' to be brought to life.', NULL, NULL, 'Appears in the author''s dreams after he hits a creative wall, serving as a muse to break his writer''s block.', 'A character from the author''s story who directly influences him to continue writing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:52.537074-05', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_scene_appearances VALUES (5170, 5305, 454, 'neutral', false, NULL, NULL, NULL, NULL, 'The author was signed up for this challenge, which served as the initial catalyst for starting the sequel to ''Elysium Rising''.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:52.537074-05', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_scene_appearances VALUES (5172, 5307, 454, 'enemy', true, NULL, NULL, NULL, 'Overcome by the inspiration provided by Jamie''s appearance in the author''s dreams.', 'Appears after the first chapter of the sequel is completed, lasting for almost a month.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:52.537074-05', '2026-02-28 19:40:52.537074-05');
INSERT INTO public.entity_scene_appearances VALUES (5173, 5308, 454, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:40:52.537074-05', '2026-02-28 19:40:52.537074-05');
