INSERT INTO public.entity_scene_appearances VALUES (5190, 5326, 456, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Predecessor to ''Escape from Elysium''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:14:30.493156-05', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_scene_appearances VALUES (5191, 2550, 456, 'mini-boss', false, 'Revealed in the book''s synopsis as the parasitic demiurge Yaldabaoth, the primary antagonist and ruler of the spiritual prison Etheris.', NULL, NULL, NULL, NULL, 'Ruler of Etheris; antagonist to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:14:30.493156-05', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_scene_appearances VALUES (5192, 3993, 456, 'ally', false, 'Identified in the synopsis as the protagonist, a man trapped in a hostile domestic loop who awakens to the reality of his world being a prison. His goal is to save his family and reclaim his divinity.', NULL, NULL, NULL, NULL, 'Father of Xavier; primary target of Yaldabaoth''s prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:14:30.493156-05', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_scene_appearances VALUES (5193, 5329, 456, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:14:30.493156-05', '2026-02-28 22:14:30.493156-05');
INSERT INTO public.entity_scene_appearances VALUES (5194, 3993, 457, 'ally', true, NULL, 'Adopts a benevolent, instructive, and somewhat melancholic tone, acting as a guide or benefactor to the ''summer babes''.', NULL, NULL, 'The speaker begins a poetic invocation, establishing the scene''s tone and purpose.', 'Acts as a paternal or divine guide to the ''Summer Babes'', offering them gifts and wisdom.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:15:36.931761-05', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_scene_appearances VALUES (5195, 5332, 457, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The recipients of the speaker''s gifts and warnings.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:15:36.931761-05', '2026-02-28 22:15:36.931761-05');
