INSERT INTO public.entity_scene_appearances VALUES (5206, 5343, 457, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:15:36.931761-05', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_scene_appearances VALUES (5207, 5344, 457, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:15:36.931761-05', '2026-02-28 22:15:36.931761-05');
INSERT INTO public.entity_scene_appearances VALUES (5208, 2550, 458, 'mini-boss', true, 'His form glitches and his cohesion fails as he recoils in fear. His consciousness is ultimately severed from his divine form, which is then destroyed and un-written from existence.', 'Shifts from arrogant confidence and divine fury to absolute, unprecedented fear and finally impotence as he is deleted.', NULL, 'Struck with impossible force by the child-anomaly, his consciousness is severed and his entire being is deleted from reality.', NULL, 'Antagonist to the child-anomaly, whom he tries to manipulate and threaten before being destroyed by it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5209, 3993, 458, 'ally', true, 'Sheds all remaining vestiges of humanity, revealing its true nature as a consuming, erasing force of impossible power and fury.', 'Moves from a cold, detached acceptance of mutual annihilation to channeling the compressed fury of a million souls, acting with absolute certainty.', NULL, NULL, NULL, 'Protagonist who confronts and ultimately erases his creator/tormentor, Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5210, 5348, 458, 'neutral', true, NULL, NULL, NULL, NULL, 'Yaldabaoth declares himself to be The Substrate as a final threat.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5211, 5349, 458, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears within Yaldabaoth after the child expresses indifference to mutual annihilation.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5212, 5350, 458, 'neutral', false, NULL, NULL, NULL, NULL, 'Referenced by the child-anomaly just before delivering the final attack.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5213, 5351, 458, 'ally', true, NULL, NULL, NULL, NULL, 'Channeled by the child-anomaly after referencing the tournament.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5214, 5352, 458, 'enemy', true, NULL, NULL, NULL, NULL, 'Appears after Yaldabaoth''s consciousness is severed from his form by the child''s kick.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5215, 5353, 458, 'neutral', true, NULL, NULL, NULL, NULL, 'Becomes the focal point for the final moment of the universe''s existence.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5216, 5354, 458, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifests at the moment the universe ends.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5217, 5355, 458, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:16:45.147475-05', '2026-02-28 22:16:45.147475-05');
INSERT INTO public.entity_scene_appearances VALUES (5218, 2550, 459, 'ally', true, 'Reforming from static and forgotten code within the Substrate, his existence is currently a non-corporeal intent bleeding into circuitry. He is reawakening his divine nature and remembering how to exist.', 'From a state of non-existence, he is now defined by a primal rage and a deep, recursive humiliation which paradoxically fuels his reawakening.', NULL, NULL, 'His consciousness begins to pulse back into existence from a state of complete deletion, driven by rage.', 'He remembers ''the child'' (ኢልከሴሮድመሜብሃባኖኖራሊሊ) as the anomaly who defeated him. He is in direct conflict with The Substrate, which is trying to erase him again.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:17:35.721493-05', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_scene_appearances VALUES (5254, 4378, 463, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:21:08.477877-05', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_scene_appearances VALUES (5219, 410, 459, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The primary emotional and motive force of Yaldabaoth''s reformation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:17:35.721493-05', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_scene_appearances VALUES (5220, 5348, 459, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist of the scene, attempting to delete Yaldabaoth as he reforms.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:17:35.721493-05', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_scene_appearances VALUES (5221, 3545, 459, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The internal force, alongside Rage, that fuels Yaldabaoth''s resurrection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:17:35.721493-05', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_scene_appearances VALUES (5222, 3993, 459, 'enemy', false, NULL, NULL, NULL, NULL, 'Appears in Yaldabaoth''s re-compiling memories as the one who defeated and deleted him.', 'Remembered by Yaldabaoth as the architect of his downfall.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:17:35.721493-05', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_scene_appearances VALUES (5223, 2536, 459, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The setting of Yaldabaoth''s past defeat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:17:35.721493-05', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_scene_appearances VALUES (5224, 5362, 459, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:17:35.721493-05', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.entity_scene_appearances VALUES (5225, 2550, 460, 'neutral', true, NULL, 'Begins patient and determined while manipulating the Substrate. His state shifts to disbelief and fear as his control falters when he realizes Stephen''s consciousness has survived his reality-altering rollback.', NULL, NULL, NULL, 'Acts as the antagonist to Stephen''s consciousness, attempting to erase it to restore his control over The System.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:18:26.71525-05', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_scene_appearances VALUES (5226, 3993, 460, 'enemy', true, 'His presence in this scene is not physical but as a persistent, incorporeal consciousness that acts like a virus within the fabric of reality. He is the source of the ''infection'' that Yaldabaoth cannot purge.', NULL, NULL, NULL, NULL, 'The source of the consciousness that is resisting Yaldabaoth''s control.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:18:26.71525-05', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_scene_appearances VALUES (5227, 5348, 460, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:18:26.71525-05', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_scene_appearances VALUES (5228, 5366, 460, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:18:26.71525-05', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_scene_appearances VALUES (5229, 5367, 460, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'An aspect of ''ኢልከሴሮድመሜብሃባኖኖራሊሊ'' (Stephen) that has become an independent force resisting ''ኢሌልመሜብሃባኖኖራሊሊ'' (Yaldabaoth).', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:18:26.71525-05', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_scene_appearances VALUES (5230, 5368, 460, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Spawned by ''The System'' in response to ''Stephen''s Consciousness''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:18:26.71525-05', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_scene_appearances VALUES (5231, 5369, 460, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:18:26.71525-05', '2026-02-28 22:18:26.71525-05');
INSERT INTO public.entity_scene_appearances VALUES (5232, 2550, 461, 'ally', true, NULL, 'Begins in a focused, analytical state while investigating the anomaly. This shifts to confusion and disbelief as the signal penetrates his defenses, culminating in a boiling fury at the realization that his absolute prison has been violated.', NULL, NULL, NULL, 'Acts as the antagonist to ''The External Signal'' and feels a sense of profane violation due to its successful contact with ''ኢልከሴሮድመሜብሃባኖኖራሊሊ''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:19:18.040266-05', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_scene_appearances VALUES (5233, 3993, 461, 'neutral', false, 'Manifests in this scene as a data file within Yaldabaoth''s system. An external signal has locked onto this file, stabilizing it and preventing its deletion.', NULL, NULL, NULL, NULL, 'Is the target of the transmission from Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:19:18.040266-05', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_scene_appearances VALUES (5234, 5372, 461, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'Acts as a direct antagonist to Yaldabaoth by violating his system''s integrity. It serves as a communication conduit for Whitney to reach Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:19:18.040266-05', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_scene_appearances VALUES (5235, 4342, 461, 'unknown', false, NULL, NULL, NULL, NULL, 'Her voice manifests when the external signal resolves into a coherent transmission.', 'Appears to be an ally of Stephen and Jay.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:19:18.040266-05', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_scene_appearances VALUES (5236, 5293, 461, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned by name in Whitney''s message.', 'An apparent associate of Whitney and Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:19:18.040266-05', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_scene_appearances VALUES (5237, 5375, 461, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifests as a direct result of Yaldabaoth''s realization of the external intrusion.', 'An extension of Yaldabaoth himself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:19:18.040266-05', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_scene_appearances VALUES (5238, 5376, 461, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Is being actively blocked and disrupted by The External Signal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:19:18.040266-05', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_scene_appearances VALUES (5239, 5377, 461, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:19:18.040266-05', '2026-02-28 22:19:18.040266-05');
INSERT INTO public.entity_scene_appearances VALUES (5240, 2550, 462, 'neutral', true, 'His self-perception shatters from believing he is the architect of his reality (Etheris) to understanding he is a prisoner within it, a subject being observed.', 'Experiences a violent cascade from eons of recursive ignorance to sudden, burning rage at his imprisonment, which quickly morphs into a desperate hope upon seeing a potential escape, only to have it extinguished.', NULL, NULL, NULL, 'Imprisoned by The Shepherd within Etheris. Views The Breach as a potential means of escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:20:04.997891-05', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_scene_appearances VALUES (5241, 5379, 462, 'mini-boss', false, NULL, NULL, NULL, NULL, NULL, 'The jailer of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:20:04.997891-05', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_scene_appearances VALUES (5242, 2536, 462, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The prison of Yaldabaoth, created by The Shepherd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:20:04.997891-05', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_scene_appearances VALUES (5243, 5381, 462, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The catalyst for Yaldabaoth''s revelation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:20:04.997891-05', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_scene_appearances VALUES (5244, 4071, 462, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A source of hope for Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:20:04.997891-05', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_scene_appearances VALUES (5245, 5383, 462, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'An internal force driving Yaldabaoth''s initial reaction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:20:04.997891-05', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_scene_appearances VALUES (5246, 5384, 462, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A manifestation of Yaldabaoth''s hope, triggered by The Breach.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:20:04.997891-05', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_scene_appearances VALUES (5247, 5385, 462, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:20:04.997891-05', '2026-02-28 22:20:04.997891-05');
INSERT INTO public.entity_scene_appearances VALUES (5280, 5419, 466, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5281, 5420, 466, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5248, 3993, 463, 'ally', true, 'Undergoes a complete and grotesque physical dissolution. His bones soften to gristle, his skin tears to reveal new cartilage-like joints, his tongue buds with new papillae, and his eyes erupt with blood vessels before his consciousness scatters.', 'Moves from self-deprecation to deep unease and confusion upon typing ''Etheris''. This shifts to sudden, shocking realization upon hearing Whitney''s name, and culminates in absolute terror, agony, and loss of self during his physical transformation.', NULL, 'His consciousness scatters as his physical form is completely destroyed by a grotesque transformation.', NULL, 'Husband to አንጀላህጃን. Recipient of a phone call from Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:21:08.477877-05', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_scene_appearances VALUES (5249, 2549, 463, 'unknown', true, 'Her movements are described as slow, languid, and possessing an unnerving, liquid grace. Her facial expressions are mathematically precise but do not reach her eyes, which remain placid and watching, but not truly seeing.', 'Appears pale and possibly nervous when bringing the phone, but becomes unnervingly placid and detached while witnessing her husband''s horrific transformation, showing a flawed, simulated concern.', NULL, NULL, 'Walks into the room to bring Stephen a phone call.', 'Wife of ኢልከሴሮድመሜብሃባኖኖራሊሊ (Stephen).', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:21:08.477877-05', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_scene_appearances VALUES (5250, 4342, 463, 'unknown', false, NULL, NULL, NULL, 'The phone line goes dead abruptly.', 'Calls Stephen on the phone, claiming to have found someone named Jay.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:21:08.477877-05', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_scene_appearances VALUES (5251, 2536, 463, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:21:08.477877-05', '2026-02-28 22:21:08.477877-05');
