INSERT INTO public.entity_scene_appearances VALUES (5257, 204, 463, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:21:08.477877-05', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_scene_appearances VALUES (5258, 5397, 463, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:21:08.477877-05', '2026-02-28 22:21:08.477877-05');
INSERT INTO public.entity_scene_appearances VALUES (5259, 3993, 464, 'ally', true, NULL, 'Moves from a state of sleepy normalcy to one of profound weariness, despair, and defensiveness regarding his two-year-long, fruitless job search. He feels a sense of wrongness and confusion about his life''s circumstances.', NULL, NULL, 'Wakes up in his bed at the start of the scene.', 'Husband to አንጀላህጃን and father to Xavier. His relationship with his wife becomes extremely strained and confrontational over the course of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5260, 2549, 464, 'mini-boss', true, 'Her movements are described as becoming ''alien, like watching a demonstration,'' losing their natural quality.', 'Undergoes a dramatic shift from a warm, sleepy partner to a cold, clinical, and logical taskmaster. Her concern becomes superficial, and her smile inverts into a sterile expression of disapproval.', NULL, 'Leaves the kitchen after a tense argument, stating she has laundry to do.', 'Is present in bed with Stephen at the start of the scene.', 'Wife to ኢልከሴሮድመሜብሃባኖኖራሊሊ and mother to Xavier. She acts as the primary antagonist in the scene, pressuring Stephen relentlessly.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5261, 4141, 464, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Son of ኢልከሴሮድመሜብሃባኖኖራሊሊ and አንጀላህጃን. His presence is auditory, providing a backdrop of normalcy that contrasts with the tension between his parents.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5262, 5401, 464, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A potential employer for Stephen, representing the latest in a long line of interviews.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5263, 5402, 464, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonistic force driving the conflict between Stephen and his wife.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5264, 5403, 464, 'unknown', true, NULL, NULL, NULL, NULL, NULL, 'A mysterious event that deepens the sense of wrongness and unreality in the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5265, 5404, 464, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A direct result of The Two-Year Job Search and the wife''s strange change in demeanor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5266, 5405, 464, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Becomes a point of contention in his argument with his wife, who sees it as unproductive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5267, 5406, 464, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:01.340867-05', '2026-02-28 22:22:01.340867-05');
INSERT INTO public.entity_scene_appearances VALUES (5268, 3993, 465, 'ally', true, 'His physical state and environment are a direct reflection of his internal decay and inertia. He is trapped between the meaningless pressure of the job market and the hollow victory of his digital escapism.', 'Swings from defeated apathy to a desperate, ugly hope when offered a sliver of affection, which quickly curdles into deeper despair and loneliness upon rejection. He is starved for genuine connection and a sense of purpose.', NULL, NULL, NULL, 'His relationship with his wife, አንጀላህጃን, is transactional and strained. He views his video game character, Tinkles, as an extension of a powerful self he cannot be in reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5269, 2549, 465, 'neutral', true, NULL, 'Appears emotionally distant and operates on a transactional basis. She dispenses affection, like the stiff hug, as a calculated reward or ''down payment'' for Stephen''s compliance, and withdraws it just as clinically.', NULL, NULL, NULL, 'Acts as a gatekeeper of affection towards her husband, Stephen. Her connection seems conditional on his ability to secure a job and meet her expectations.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5270, 5409, 465, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5271, 1030, 465, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5272, 5411, 465, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5273, 5412, 465, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5274, 5413, 465, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5275, 5414, 465, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5276, 5415, 465, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5277, 5416, 465, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-02-28 22:22:52.179752-05');
INSERT INTO public.entity_scene_appearances VALUES (5278, 3993, 466, 'ally', true, 'His internal state is one of cognitive dissonance; he can recall obscure gaming details but not his own wife''s name, highlighting a severe psychological disconnect from his immediate reality.', 'He is in a state of numbing despair and failure, which escalates to shame, humiliation, and finally a ''cold, electric panic''. He feels like a beggar, starved for contact but repulsed by his own neediness and the memory of past degradation.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5279, 2549, 466, 'enemy', true, 'Physically present but emotionally absent, she acts as an immovable, cold barrier to Stephen''s attempts at connection. Her final line, ''What, Stephen?'', confirms her awareness but also her deep-seated irritation with him.', 'She is emotionally distant, cold, and unresponsive, completely absorbed in her phone. Her body language is defensive and rejecting, turning to ''stone'' at his touch, and she sighs with aggravation when he speaks to her.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5287, 5426, 466, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5288, 5427, 466, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5289, 5428, 466, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:23:40.799739-05', '2026-02-28 22:23:40.799739-05');
INSERT INTO public.entity_scene_appearances VALUES (5290, 3993, 467, 'ally', true, NULL, 'Overwhelmed by despair and a sense of worthlessness, he cries silently in bed. His emotional spiral leads him to a calm, logical conclusion that he must end his life.', NULL, NULL, NULL, 'Feels completely isolated from his wife (አንጀላህጃን) and feels like a burden to her and his son (Xavier). He is tormented by the manifestation of his own Crushing Self-Worthlessness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:24:34.87899-05', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_scene_appearances VALUES (5291, 2549, 467, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Her physical and emotional absence from the marital bed is a primary catalyst for Stephen''s despair. He perceives her as disappointed and burdened by him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:24:34.87899-05', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_scene_appearances VALUES (5292, 4141, 467, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Son of Stephen and his wife. Stephen views him as a victim of his own failures.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:24:34.87899-05', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_scene_appearances VALUES (5293, 5432, 467, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:24:34.87899-05', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_scene_appearances VALUES (5294, 5433, 467, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:24:34.87899-05', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_scene_appearances VALUES (5295, 5434, 467, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:24:34.87899-05', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_scene_appearances VALUES (5296, 5435, 467, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:24:34.87899-05', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_scene_appearances VALUES (5297, 5436, 467, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:24:34.87899-05', '2026-02-28 22:24:34.87899-05');
INSERT INTO public.entity_scene_appearances VALUES (5360, 5502, 474, 'neutral', true, NULL, NULL, NULL, NULL, 'Discovered by Stephen when he removes the gauze from his arm.', 'A miraculous event that is immediately ignored and invalidated by አንጀላህጃን.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5439, 5582, 482, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A tool used by አንጀላህጃን to monitor ስቴፈን.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:38:23.206313-05', '2026-02-28 22:38:23.206313-05');
INSERT INTO public.entity_scene_appearances VALUES (5298, 3993, 468, 'ally', true, 'Referred to as ''The body'', acting with fluid, emotionless precision. The narrative voice creates a sense of detachment from the character''s own actions.', 'Completely detached and mechanical, as if observing their own actions without feeling. Resigned to the act of suicide.', NULL, 'The character lies down in bed to await death, effectively ending their active role in the scene.', 'The scene opens with the character rising from bed.', 'Engaged in a final, one-sided interaction with the Expired Pills and Impending Death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:25:17.189248-05', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_scene_appearances VALUES (5299, 5438, 468, 'neutral', true, NULL, NULL, NULL, 'The empty bottle is placed back in the drawer after its contents are consumed.', 'Retrieved from a cluttered drawer under the bathroom sink.', 'The tool used by ''The body'' to bring about Impending Death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:25:17.189248-05', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_scene_appearances VALUES (5300, 5439, 468, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Its presence is invoked by the character''s actions and becomes the focus at the end of the scene.', 'The ultimate goal and antagonist of the scene, which the protagonist willingly embraces.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:25:17.189248-05', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_scene_appearances VALUES (5301, 5440, 468, 'neutral', true, NULL, NULL, NULL, NULL, 'Becomes relevant when the character returns to bed.', 'The final resting place for the character in this scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:25:17.189248-05', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_scene_appearances VALUES (5302, 5441, 468, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:25:17.189248-05', '2026-02-28 22:25:17.189248-05');
INSERT INTO public.entity_scene_appearances VALUES (5303, 3993, 469, 'ally', true, 'Wears mismatched layers of tweed and glasses that don''t focus. Feels dirty and physically wrong in their own body.', 'Begins in a state of deep confusion and disorientation, which shifts to dawning horror and existential dread upon realizing the nature of their reality. Culminates in excruciating pain and terror.', NULL, 'Loses consciousness after a painful psychic assault.', NULL, 'An outside observer to the looping inhabitants of the purgatory, feeling profoundly isolated and separate from them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:26:14.630133-05', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_scene_appearances VALUES (5304, 5444, 469, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'They serve as the primary evidence for the protagonist that the world is wrong and that they are the only conscious being present.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:26:14.630133-05', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_scene_appearances VALUES (5305, 5445, 469, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:26:14.630133-05', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_scene_appearances VALUES (5306, 5446, 469, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:26:14.630133-05', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_scene_appearances VALUES (5307, 5447, 469, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:26:14.630133-05', '2026-02-28 22:26:14.630133-05');
