INSERT INTO public.entity_scene_appearances VALUES (5309, 5449, 469, 'unknown', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:26:14.630133-05', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_scene_appearances VALUES (5310, 5451, 469, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:26:14.630133-05', '2026-02-28 22:26:14.630133-05');
INSERT INTO public.entity_scene_appearances VALUES (5311, 3993, 470, 'ally', true, 'His current form is described as ''wearing meat''. He is leaking consciousness, creating ''puddles of awareness''.', 'Experiences a shift from confusion to dawning awareness of his situation, followed by ''pure, primal, animal terror''. During the interrogation, he feels a mix of confusion, pain from fragmented memories, and a final, shocking realization of his purpose.', NULL, NULL, NULL, 'He is an anomaly being interrogated by the Woman in the White Coat. He is the target of The System''s Cleaner and was positioned by an outside force via The Signal from Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:03.516743-05', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_scene_appearances VALUES (5312, 5453, 470, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Appears out of a coffee shop that wasn''t there a moment before, specifically to confront the protagonist.', 'Acts as an interrogator and potential executioner for the system that runs the simulation. She is aware of Azathoth''s Guardians and The Collectors.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:03.516743-05', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_scene_appearances VALUES (5313, 5447, 470, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:03.516743-05', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_scene_appearances VALUES (5314, 5455, 470, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:03.516743-05', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_scene_appearances VALUES (5315, 5456, 470, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:03.516743-05', '2026-02-28 22:27:03.516743-05');
