INSERT INTO public.entity_scene_appearances VALUES (5321, 5462, 470, 'ally', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:03.516743-05', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_scene_appearances VALUES (5322, 5463, 470, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:03.516743-05', '2026-02-28 22:27:03.516743-05');
INSERT INTO public.entity_scene_appearances VALUES (5323, 3993, 471, 'ally', true, NULL, 'Experiences a rapid progression from confusion and fear to absolute terror while being interrogated by the inhuman woman. This state then transforms into profound shock, recognition, and overwhelming relief upon her transformation into Lady Illkeserod.', NULL, NULL, NULL, 'The true lover of Lady Illkeserod, he is the subject of her search and the focus of the interrogation by the vessel she was trapped in.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_scene_appearances VALUES (5324, 5465, 471, 'mini-boss', true, NULL, NULL, NULL, 'The vessel malfunctions and deconstructs under the strain of containing Lady Illkeserod, ultimately collapsing and allowing her to emerge.', 'Present at the start of the scene, interrogating the protagonist.', 'A prison or vessel for Lady Illkeserod, created or utilized by Azathoth. Acts as an interrogator and antagonist towards Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_scene_appearances VALUES (5389, 5531, 477, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A tool used by the simulation, manifested through አንጀላህጃን, to control and interact with ኢልከሴሮድመሜብሃባኖኖራሊሊ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:33:45.988017-05', '2026-02-28 22:33:45.988017-05');
INSERT INTO public.entity_scene_appearances VALUES (5390, 5532, 477, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A system process that becomes visible through the actions of አንጀላህጃን.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:33:45.988017-05', '2026-02-28 22:33:45.988017-05');
INSERT INTO public.entity_scene_appearances VALUES (5391, 5533, 477, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:33:45.988017-05', '2026-02-28 22:33:45.988017-05');
INSERT INTO public.entity_scene_appearances VALUES (5325, 2608, 471, 'ally', true, 'Her appearance solidifies from the deconstructed, sterile white vessel into her true form: a living woman with warm, brown eyes and olive-toned skin.', 'Shifts from a trapped, struggling consciousness fighting for control to a warm, loving, and relieved presence upon successfully reuniting with Benji.', 'The white coat of the vessel is shed, revealing simple, dark, comfortable clothing underneath.', NULL, 'Emerges from the collapsing form of ''The Woman in White'' after the vessel fails.', 'The true lover of Benji. She was trapped inside the vessel by Azathoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_scene_appearances VALUES (5326, 3591, 471, 'unknown', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_scene_appearances VALUES (5327, 5468, 471, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned by Lady Illkeserod as her captor.', 'The captor of Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_scene_appearances VALUES (5328, 5469, 471, 'enemy', true, NULL, NULL, NULL, 'Disappears when the vessel transforms into Lady Illkeserod.', 'Becomes visible as the vessel''s facade begins to fail.', 'A component of the vessel''s horrifying internal anatomy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_scene_appearances VALUES (5329, 5470, 471, 'unknown', true, NULL, NULL, NULL, 'Vanishes when the vessel solidifies into Lady Illkeserod''s true form.', 'Revealed as the vessel''s skin becomes permeable and translucent.', 'A fundamental, cosmic component of the being trapped within the vessel.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_scene_appearances VALUES (5330, 5471, 471, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:27:56.872263-05', '2026-02-28 22:27:56.872263-05');
INSERT INTO public.entity_scene_appearances VALUES (5440, 5427, 482, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:38:23.206313-05', '2026-02-28 22:38:23.206313-05');
INSERT INTO public.entity_scene_appearances VALUES (5331, 5231, 472, 'ally', true, 'Revealed to be the protagonist''s true, original consciousness—an ancient observer who is Ilse''s partner. He was fragmented and trapped after being targeted by Etheris''s purge protocols.', 'Moves from a state of forgotten purgatory to wholeness and clarity, experiencing the overwhelming weight and relief of remembering his true identity, purpose, and love for Ilse.', NULL, NULL, NULL, 'Lover and partner to Ilse (ኢልከሴሮድ). His fragmented self manifested as the protagonist (ኢልከሴሮድመሜብሃባኖኖራሊሊ).', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:28:48.741398-05', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_scene_appearances VALUES (5332, 2608, 472, 'ally', true, NULL, 'Focused and relieved, having successfully guided Benji back to his whole self through the painful memories.', NULL, NULL, NULL, 'Lover and partner to Benji (ቤንጂ). Acts as a guide and anchor for his reintegration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:28:48.741398-05', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_scene_appearances VALUES (5333, 3993, 472, 'ally', true, 'His consciousness is revealed to be a fragmented aspect of the observer entity, Benji. He experiences the memories of his true self and reintegrates, becoming whole again.', 'Shifts from a state of confusion to the overwhelming shock and relief of remembering his true, vast identity. His body trembles from the weight of returning to himself.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:28:48.741398-05', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_scene_appearances VALUES (5334, 2550, 472, 'mini-boss', false, 'Revealed to be the corrupting force within the prison-realm Etheris. Instead of merely being contained, he has infected the system and feeds on the dimensional suffering of the souls trapped within, such as Stephen and Jamie.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:28:48.741398-05', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_scene_appearances VALUES (5335, 2544, 472, 'ally', false, 'Recalled in memory not as a human woman, but as an archon in flesh, corrupted by endless cycles of death and rebirth. Her soul is perpetually shredded and scattered across Etheris by Yaldabaoth.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:28:48.741398-05', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_scene_appearances VALUES (5336, 2536, 472, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:28:48.741398-05', '2026-02-28 22:28:48.741398-05');
