INSERT INTO public.entity_scene_appearances VALUES (5344, 5485, 472, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:28:48.741398-05', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_scene_appearances VALUES (5345, 5486, 472, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:28:48.741398-05', '2026-02-28 22:28:48.741398-05');
INSERT INTO public.entity_scene_appearances VALUES (5346, 2608, 473, 'ally', true, NULL, 'Shifts from a grave, strategic demeanor to expressing deep worry for Benji''s safety, which then softens into a warm, loving smile upon his renewed determination. Her actions are driven by a mission to rescue others and a personal need to protect Benji.', NULL, 'Escapes the purgatory realm with Benji through a seam in reality.', 'Already present with Benji at the start of the scene.', 'Lover and protector of Benji (ኢልከሴሮድመሜብሃባኖኖራሊሊ). Views Whitney (ዊትኒ) as a key to their escape and Stephen (ስቴፈን) and Jamie (ብሪትለሪሌት) as allies to be rescued.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5347, 3993, 473, 'ally', true, 'Regains his sense of purpose and remembers his true nature as a warrior and witness, moving from a state of confusion to one of steady resolve.', 'Transitions from confusion and disorientation to a profound sense of determination and love, catalyzed by Ilse''s presence and the hope of escape. He accepts the coming danger without fear.', NULL, 'Escapes the purgatory realm with Ilse.', 'Already present, waking up to the reality of his situation.', 'Lover of Ilse (ኢልከሴሮድ). Considers Whitney (ዊትኒ) and Stephen (ስቴፈን) as friends he must help save.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5348, 5489, 473, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'An ally to Benji and Stephen, actively working to free them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5349, 5460, 473, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Antagonists to anyone attempting to escape the prison, such as Ilse and Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5350, 982, 473, 'enemy', true, 'The prison''s containment is described as weakening, with resets leaving ''cracks'' in its structure. When Benji and Ilse escape, the realm shudders and emits a sound like tearing fabric, described as something ''vast and hungry'' realizing its prey has escaped.', NULL, NULL, NULL, NULL, 'A prison for souls like Stephen and Jamie, controlled by Yaldabaoth. It is the primary antagonist environment of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5352, 5493, 473, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The means of escape for Ilse and Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5353, 5494, 473, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A construct of the Abyss/prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5354, 2550, 473, 'big-boss', false, NULL, NULL, NULL, NULL, NULL, 'Mentioned as the entity who feeds on the souls of those trapped in the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5355, 2544, 473, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Mentioned by Ilse as another person trapped in the prison who needs to be rescued.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5356, 5497, 473, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-02-28 22:29:58.036374-05');
INSERT INTO public.entity_scene_appearances VALUES (5392, 5534, 477, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:33:45.988017-05', '2026-02-28 22:33:45.988017-05');
INSERT INTO public.entity_scene_appearances VALUES (5429, 5571, 481, 'ally', false, NULL, NULL, NULL, NULL, 'Proposed by Rebecca in a text message as an invitation to Stephen.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:37:15.111704-05', '2026-02-28 22:37:15.111704-05');
INSERT INTO public.entity_scene_appearances VALUES (5430, 5562, 481, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned in a text message from Rebecca, its location marked by a pin on a map.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:37:15.111704-05', '2026-02-28 22:37:15.111704-05');
INSERT INTO public.entity_scene_appearances VALUES (5431, 5573, 481, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:37:15.111704-05', '2026-02-28 22:37:15.111704-05');
INSERT INTO public.entity_scene_appearances VALUES (5357, 3993, 474, 'ally', true, 'Wakes up in his bed, inexplicably healed from a recent suicide attempt. His arm, which he remembers slashing, now has perfect, unscarred skin.', 'Begins in a state of extreme disorientation and physical pain, which shifts to confusion and astonishment at his healing. This is quickly replaced by panic, frustration, and a feeling of being trapped during a gaslighting argument with his wife.', NULL, 'Escapes the argument by retreating to the master bathroom.', 'Regains consciousness at the start of the scene.', 'Husband to አንጀላህጃን. He is the victim of her psychological manipulation in this scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5358, 2549, 474, 'enemy', true, NULL, 'Appears outwardly mild, bored, and detached. Her actions reveal a manipulative and controlling nature, as she deliberately creates a no-win argument to destabilize Stephen.', 'Now possesses her phone and phone charger.', NULL, 'Enters the bedroom to get her phone charger.', 'Wife of ኢልከሴሮድመሜብሃባኖኖራሊሊ. Acts as his antagonist, trapping him in a conversation and blocking his exit.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5359, 1748, 474, 'enemy', true, NULL, NULL, NULL, 'Slowly resolves into the familiar details of his bedroom as his brain processes the input.', 'It is the first thing Stephen experiences upon regaining consciousness.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5536, 2536, 489, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:50:06.413732-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5753, 5903, 507, 'neutral', true, NULL, NULL, NULL, NULL, 'Found by Xavier on a cork bulletin board in a dusty occult shop in Nashville.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_scene_appearances VALUES (5361, 5503, 474, 'enemy', true, NULL, NULL, NULL, 'Stephen physically escapes the argument by retreating to the bathroom.', 'Begins when Stephen''s wife ignores his healed arm and asks about the electric bill.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5362, 5504, 474, 'neutral', true, NULL, NULL, NULL, 'Peeled off by Stephen to reveal his healed skin, and later vanishes entirely.', 'Stephen discovers it on his arm when the room comes into focus.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5363, 5505, 474, 'neutral', true, NULL, NULL, NULL, 'The argument is abandoned when Stephen flees to the bathroom.', 'Introduced into the conversation by Stephen''s wife as a tool of manipulation.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5364, 5506, 474, 'neutral', false, NULL, NULL, NULL, NULL, 'Recalled by Stephen as he tries to make sense of his current situation.', 'The cause of the wounds that have now been impossibly healed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5365, 5507, 474, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:10.20478-05', '2026-02-28 22:31:10.20478-05');
INSERT INTO public.entity_scene_appearances VALUES (5367, 2549, 475, 'mini-boss', true, NULL, 'Displays a cold, critical, and self-serving demeanor. She shifts from weary concern to hardened refusal when her own money is mentioned. Her actions are described as scripted and lacking genuine emotion.', NULL, 'Leaves to run errands after delivering her final criticisms.', NULL, 'Wife to Stephen, mother to Xavier. Acts as an antagonist, emotionally and financially pressuring Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:57.262898-05', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_scene_appearances VALUES (5368, 4141, 475, 'ally', true, NULL, NULL, NULL, 'Leaves the kitchen after sharing the TikTok video and his thoughts with his father.', 'Enters the kitchen after his mother leaves, looking for a snack.', 'Son of Stephen and አንጀላህጃን. He feels a disconnect from his mother and a growing bond with his father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:57.262898-05', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_scene_appearances VALUES (5369, 5511, 475, 'neutral', false, NULL, NULL, NULL, NULL, 'Introduced by Xavier via a TikTok video he shows to Stephen.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:57.262898-05', '2026-02-28 22:31:57.262898-05');
INSERT INTO public.entity_scene_appearances VALUES (5370, 5512, 475, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:57.262898-05', '2026-02-28 22:31:57.262898-05');
