INSERT INTO public.entity_scene_appearances VALUES (5378, 5520, 476, 'neutral', true, NULL, NULL, NULL, 'The vision snaps shut abruptly, returning Stephen to his kitchen.', 'Triggered by the word ''Bug'', it overtakes Stephen''s consciousness.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:32:54.020373-05', '2026-02-28 22:32:54.020373-05');
