INSERT INTO public.entity_scene_appearances VALUES (5384, 5526, 476, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The weaponized version of the shepherd''s love for The Slaughtered Flock.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:32:54.020373-05', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_scene_appearances VALUES (5385, 5527, 476, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:32:54.020373-05', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_scene_appearances VALUES (5386, 5528, 476, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:32:54.020373-05', '2026-02-28 22:32:54.020373-05');
INSERT INTO public.entity_scene_appearances VALUES (5387, 3993, 477, 'ally', true, 'He is testing the boundaries of his reality, observing his wife for signs of scripted behavior and intentionally acting in ways to break her loops.', 'His state shifts from weary exhaustion and depression to a sharp, morbid curiosity, which culminates in cold-blooded panic and horror upon confirming his wife is a looping NPC.', NULL, 'Flees the house in panic after confirming his wife is stuck in a conversational loop.', NULL, 'Husband to አንጀላህጃን, whom he now views as a malfunctioning program or NPC. He is testing the theories proposed by Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:33:45.988017-05', '2026-02-28 22:33:45.988017-05');
INSERT INTO public.entity_scene_appearances VALUES (5388, 2549, 477, 'mini-boss', true, 'Her behavior is revealed to be entirely scripted and robotic. When confronted with an unexpected response, she visibly glitches, buffers, and resets her conversational script, confirming she is not a conscious being.', 'Displays a limited range of programmed emotions (annoyance, contentment) that are tied to her scripts. Shows no genuine emotional response, only ''computerized confusion'' when her programming is disrupted.', NULL, 'Remains in the house as Stephen flees from her.', NULL, 'Wife of ኢልከሴሮድመሜብሃባኖኖራሊሊ. Her non-player character (NPC) nature is the central conflict and horror of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:33:45.988017-05', '2026-02-28 22:33:45.988017-05');
INSERT INTO public.entity_scene_appearances VALUES (5428, 2897, 481, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned in Rebecca''s text message as someone who will be at the anniversary event.', 'Works with Rebecca at the bookshop.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:37:15.111704-05', '2026-02-28 22:37:15.111704-05');
INSERT INTO public.entity_scene_appearances VALUES (5394, 2549, 478, 'enemy', true, 'Her behavior is revealed to be scripted and robotic; she repeats dialogue verbatim when faced with an unpredicted response. After a major reset, her physical appearance has glitched: her hair is shorter, thinner, and browner.', 'Exhibits a clinical, detached demeanor. Her responses are limited to programmed annoyance and concern for routine, lacking any genuine empathy or reaction to Stephen''s distress.', NULL, 'Leaves the bedroom and later the living room conversation when her script is disrupted or completed.', NULL, 'Wife of ስቴፈን. She acts as an unwitting warden of his simulated reality, her looping behavior confirming his suspicions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_scene_appearances VALUES (5395, 4141, 478, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned by Stephen as the source of the idea that NPCs loop.', 'An influential figure in Stephen''s recent memory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_scene_appearances VALUES (5438, 5581, 482, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'A feature of Stephen''s House that reflects his relationship with his wife.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:38:23.206313-05', '2026-02-28 22:38:23.206313-05');
INSERT INTO public.entity_scene_appearances VALUES (5396, 5538, 478, 'neutral', true, NULL, NULL, NULL, 'Is tipped into the bathtub, causing Stephen''s electrocution and disappearing upon the reset.', 'Retrieved by Stephen from the kitchen.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_scene_appearances VALUES (5397, 282, 478, 'enemy', true, NULL, NULL, NULL, 'Impacts Stephen, triggering a major system reset.', 'Approaches the railroad crossing as Stephen arrives.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_scene_appearances VALUES (5398, 5532, 478, 'enemy', true, NULL, NULL, NULL, NULL, 'Its existence is confirmed when Stephen wakes up after his first death.', 'The primary antagonist force imprisoning Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_scene_appearances VALUES (5399, 5541, 478, 'neutral', true, NULL, NULL, NULL, 'Ends when the darkness takes Stephen.', 'Occurs when the toaster oven hits the water.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_scene_appearances VALUES (5400, 5542, 478, 'neutral', true, NULL, NULL, NULL, 'Is replaced by agony and then panic as his experiments unfold.', 'Arises after Stephen contemplates Xavier''s words about NPCs.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-02-28 22:34:33.299402-05');
INSERT INTO public.entity_scene_appearances VALUES (5401, 5543, 478, 'neutral', true, NULL, NULL, NULL, 'Disappears from the narrative when the electrocution begins.', 'Is noticed by Stephen as he lies in the bathtub.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-02-28 22:34:33.299402-05');
