INSERT INTO public.entity_scene_appearances VALUES (5404, 4141, 479, 'ally', true, NULL, NULL, NULL, NULL, 'Already present in the room, gaming, when the scene begins.', 'Son of Stephen. He acts as a catalyst, prompting Stephen''s reflections and the discovery of the yearbook.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:35:31.244588-05', '2026-02-28 22:35:31.244588-05');
