INSERT INTO public.entity_scene_appearances VALUES (5414, 2549, 480, 'mini-boss', true, 'Her behavior deviates from its usual script by escalating to physical violence (throwing a glass) before abruptly resetting.', 'Moves from irritation to cold, sharp rage, culminating in a violent outburst. Her emotional state then unnaturally resets to the beginning of the argument loop, revealing her programmed nature.', NULL, 'Left in the room by Stephen after her behavioral loop resets.', NULL, 'Wife of ስቴፈን. Acts as an antagonist within the scene, enforcing the reality loop through repetitive, circular arguments.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:36:22.141398-05', '2026-02-28 22:36:22.141398-05');
