INSERT INTO public.entity_scene_appearances VALUES (5580, 5726, 493, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Believed by Benji to be a call from Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5475, 5618, 486, 'neutral', false, NULL, NULL, NULL, 'The memory collapses, returning Stephen to the present.', 'Triggered while Stephen is browsing the old books.', 'Features Stephen, Becca, and Jamie (ብሪትለሪሌት).', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5476, 2544, 486, 'ally', false, 'Appears in a memory as a girl with dark hair whose form seems unstable, as if light bends around her. She is described as ''too alive for memory, too wrong for reality.''', 'She offers a small, private smile, suggesting a shared secret and deep connection with Stephen.', NULL, NULL, NULL, 'The object of Stephen''s profound love in the memory. Her presence is associated with the scent of vanilla and peaches.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5477, 2882, 486, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Sits in front of Jamie (ብሪትለሪሌት) in Stephen''s memory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5478, 5621, 486, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Directly associated with Jamie (ብሪትለሪሌት).', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5479, 5622, 486, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears mysteriously in Stephen''s hands after his memory collapses.', 'A companion volume to The Gospel of Judas.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5480, 5623, 486, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears mysteriously in Stephen''s hands after his memory collapses.', 'A companion volume to The Secret Book of John.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5481, 5524, 486, 'ally', false, NULL, NULL, NULL, NULL, 'Stephen experiences her story as a first-person vision while reading The Secret Book of John.', 'The creator and mother of Yaldabaoth (the Demiurge). She acts as a secret benefactor to Adam and humanity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5845, 5996, 514, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5482, 2550, 486, 'mini-boss', false, 'Revealed in a vision in his primordial form: a monstrous, blind, and mad lion-faced serpent born from Sophia''s error. He is an abomination of chaos.', 'Characterized by impotent rage when his creation, Adam, will not move on its own.', NULL, NULL, 'Appears in the vision induced by The Secret Book of John, showing his origin.', 'The accidental son of Sophia. Creator of Adam and the prison realm of reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5483, 5626, 486, 'enemy', false, NULL, NULL, NULL, NULL, 'Created in the vision as a way for Sophia to hide her monstrous creation.', 'The domain of the Demiurge, Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5485, 5628, 486, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.entity_scene_appearances VALUES (5487, 2882, 487, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Co-owner of the bookstore with James. She shows concern for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_scene_appearances VALUES (5488, 2897, 487, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Co-owner of the bookstore with Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_scene_appearances VALUES (5489, 5632, 487, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'They seem to have been waiting specifically for Stephen. They previously belonged to, or are connected with, Jamie Reyes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_scene_appearances VALUES (5490, 2544, 487, 'neutral', false, 'Revealed to be Jamie Reyes, the deceased individual for whom the bookstore is named. Her memory is a powerful sensory experience for Stephen, associated with vanilla, peaches, and specific mannerisms, though he cannot recall her face.', NULL, NULL, NULL, NULL, 'She is the girl Stephen loved and lost, a fact he is just now remembering. The entire bookstore is a memorial to her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_scene_appearances VALUES (5491, 5634, 487, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_scene_appearances VALUES (5492, 4689, 487, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The negative space left by Jamie''s forgotten death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_scene_appearances VALUES (5493, 1846, 487, 'neutral', true, NULL, NULL, NULL, NULL, 'Stephen stumbles to it after the emotional shock inside the bookstore.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.entity_scene_appearances VALUES (5498, 5642, 488, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Used by Stephen as a tool to cope with his marital conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:43:37.412246-05');
INSERT INTO public.entity_scene_appearances VALUES (5499, 4217, 488, 'unknown', false, NULL, NULL, NULL, NULL, 'Triggered by the smell of the peach cobbler.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:43:37.412246-05');
INSERT INTO public.entity_scene_appearances VALUES (5503, 5647, 488, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:43:37.412246-05');
INSERT INTO public.entity_scene_appearances VALUES (5504, 5231, 489, 'ally', true, 'He appears smaller than the ancient gods but older. His cardigan flickers between colors that do not belong to the normal spectrum.', 'Hopeful and determined, unwavering in his belief that Whitney''s signal is a chance for the resistance. He is resolute and steady.', NULL, NULL, NULL, 'Acts as a grounding force for Lady Illkeserod and the primary advocate for pursuing Whitney''s signal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5505, 2608, 489, 'ally', true, 'Her body is woven from translucent filaments of thought. Her form is unstable, shattering and reforming after touching Etheris, with lines of blue-white light running beneath her skin.', 'Initially cautious and fearful of the consequences of Stephen remembering, she develops a sense of awe for Whitney''s power and resolves to find her.', NULL, NULL, NULL, 'Shares a close, protective bond with Benji, whom she pulled from the brink of deletion. She is a leading figure among the gathered gods.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5509, 5653, 489, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_scene_appearances VALUES (5518, 5663, 489, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:44:22.961777-05');
INSERT INTO public.entity_scene_appearances VALUES (5495, 2549, 488, 'mini-boss', true, 'Appears as a domestic figure baking, but quickly becomes the scene''s primary antagonist, launching a sustained verbal assault on Stephen.', 'Shifts from feigned neutrality to passive-aggression, then to open hostility and resentment. Her voice becomes a ''steady drone of accusation and guilt'' that cracks with a ''static-like'' quiver.', NULL, NULL, NULL, 'Wife of Stephen and mother of Xavier. Her relationship with Stephen is shown to be deeply strained and contentious.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:49:05.389963-05');
INSERT INTO public.entity_scene_appearances VALUES (5496, 4141, 488, 'neutral', true, NULL, NULL, NULL, 'Emotionally retreats from the conflict by putting on headphones, though he remains physically present.', 'Already present at his desk when the scene begins.', 'Son of Stephen and Angela.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:49:05.389963-05');
INSERT INTO public.entity_scene_appearances VALUES (5497, 5641, 488, 'neutral', true, NULL, NULL, NULL, NULL, 'Is in the oven at the start of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:49:05.389963-05');
INSERT INTO public.entity_scene_appearances VALUES (5523, 2825, 488, 'enemy', true, NULL, NULL, NULL, 'Fizzles out as Stephen stops responding, though the tension remains.', 'Sparked by Stephen''s offer to help with dinner.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:49:05.389963-05', '2026-02-28 22:49:05.389963-05');
INSERT INTO public.entity_scene_appearances VALUES (5524, 5427, 488, 'neutral', true, NULL, NULL, NULL, NULL, 'In Stephen''s hand during the argument.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:49:05.389963-05', '2026-02-28 22:49:05.389963-05');
INSERT INTO public.entity_scene_appearances VALUES (5525, 5670, 488, 'neutral', false, NULL, NULL, NULL, NULL, 'Accessed by Stephen as a way to mentally escape the argument.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:49:05.389963-05', '2026-02-28 22:49:05.389963-05');
INSERT INTO public.entity_scene_appearances VALUES (5754, 5904, 507, 'big-boss', true, NULL, NULL, NULL, NULL, 'Manifests from a pool of blood on the stage after being summoned by the cultists'' ritual.', 'The object of worship for the cultists. An Outer God connected to Nyarlathotep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_scene_appearances VALUES (5500, 2544, 488, 'unknown', false, 'Appears as a brief, fragmented memory of a girl laughing in a hallway, associated with the scent of vanilla and peaches.', NULL, NULL, 'The memory fragment fades.', 'Her memory is triggered by the smell of the peach cobbler.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:49:05.389963-05');
INSERT INTO public.entity_scene_appearances VALUES (5501, 5489, 488, 'unknown', false, 'Her voice is heard by Stephen in a clear auditory hallucination or recovered memory, delivering a cryptic message.', NULL, NULL, 'The voice fades, leaving Stephen confused.', 'Her voice is heard immediately following the memory of Jamie.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:49:05.389963-05');
INSERT INTO public.entity_scene_appearances VALUES (5502, 5293, 488, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned in Whitney''s message.', 'Seems to be an associate of Whitney whom she was searching for.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-02-28 22:49:05.389963-05');
