INSERT INTO public.entity_scene_appearances VALUES (5507, 5651, 489, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5508, 5652, 489, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Acts as an antagonist within the resistance, questioning their hopes and motives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5516, 2749, 489, 'ally', true, 'She appears by drifting out of the starlight, robed in symbols and shadow.', 'Analytical and strategic, she immediately focuses on the practical implications of Whitney''s actions, suggesting they find the ''tear'' she left behind.', NULL, NULL, 'Drifts into the gathering to offer a strategic perspective on Whitney''s signal.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5510, 5654, 489, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Comprised of Benji, Lady Illkeserod, Tiamat, Hecate, Chernobog, and Lady Osilari.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5513, 5489, 489, 'ally', false, 'Her signal, which broke through Etheris, is described as sweet, defiant, and almost human. Her actions demonstrate an impossible level of power, breaking through a sealed, soul-deleting prison.', 'Though not present, her actions are characterized as defiant and powerful.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5512, 5656, 489, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
