INSERT INTO public.entity_scene_appearances VALUES (5542, 5687, 489, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:50:06.413732-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5515, 2544, 489, 'ally', false, 'Appears as a memory to Stephen, powerful enough to be named by Lady Illkeserod and cause a reaction from the prison sphere.', NULL, NULL, NULL, NULL, 'Her memory is a catalyst for Stephen''s awakening.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5581, 5727, 493, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Used by Benji to track the Reality Vibration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5517, 2550, 489, 'big-boss', false, 'Mentioned as the entity trapped within Etheris that Stephen has prevented from escaping twice before. Its potential escape is a catastrophic threat.', NULL, NULL, NULL, NULL, 'The ultimate antagonist, imprisoned within Etheris.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5545, 5690, 489, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:50:06.413732-05', '2026-02-28 22:50:06.413732-05');
INSERT INTO public.entity_scene_appearances VALUES (5546, 2608, 490, 'ally', true, 'Performs a complex metaphysical ritual at the edge of the Akashic flow, successfully creating a connection across time and space.', 'Intensely focused during the ritual, then observant and analytical as she traces the resulting signal.', NULL, NULL, NULL, 'Acts as a facilitator to connect Stephen and Whitney. Is also remembered by Whitney as her father who disowned her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:51:12.844718-05', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_scene_appearances VALUES (5548, 5489, 490, 'ally', true, 'Awakens from a dreamlike state in a void, processes painful memories, realizes a crucial truth, and sends a desperate prayer for help.', 'Transitions from being lost, weightless, and fearful to a state of desperate clarity, and finally to feeling a surge of hope.', NULL, NULL, NULL, 'Trapped in the void, she is the target of Lady Illkeserod''s search and the source of the prayer sent to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:51:12.844718-05', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_scene_appearances VALUES (5549, 5694, 490, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:51:12.844718-05', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_scene_appearances VALUES (5550, 234, 490, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:51:12.844718-05', '2026-02-28 22:51:12.844718-05');
