INSERT INTO public.entity_scene_appearances VALUES (5552, 2544, 490, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned in Whitney''s prayer as a key part of the truth she has discovered.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:51:12.844718-05', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_scene_appearances VALUES (5553, 985, 490, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:51:12.844718-05', '2026-02-28 22:51:12.844718-05');
INSERT INTO public.entity_scene_appearances VALUES (5555, 2549, 491, 'mini-boss', true, 'Her physical movements have become jerky and unnatural, her facial expressions flicker, and her eyes don''t blink in unison. She trails a ''wrong'' smell.', 'Exhibits a scripted, confrontational anger that flattens to a monotone. After a moment of confusion, she ''recalibrates'' into a placid, humming state.', NULL, 'Drifts away after accepting Stephen''s plan to fix the computer, seemingly reset or recalibrated.', 'Appears in the doorway to confront Stephen about his computer usage.', 'Wife of ስቴፈን. Acts as the primary antagonist in the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:52:02.890953-05', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_scene_appearances VALUES (5556, 5489, 491, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The subject of Stephen''s obsessive search.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:52:02.890953-05', '2026-02-28 22:52:02.890953-05');
INSERT INTO public.entity_scene_appearances VALUES (5557, 5702, 491, 'neutral', true, NULL, NULL, NULL, 'Destroyed by a powerful static surge, causing it to smoke and the monitors to go dead.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:52:02.890953-05', '2026-02-28 22:52:02.890953-05');
