INSERT INTO public.entity_scene_appearances VALUES (5564, 2881, 492, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Old friend of Stephen. Former classmate of Patrick, Andrew, and Morgan, though his memories of them are unreliable.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5565, 5711, 492, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A point of conflict between Stephen and his wife; a catalyst for the scene''s events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5566, 5489, 492, 'unknown', false, 'Her existence is a point of contention; Gil cannot remember her at all. It is later revealed by Andrew and Morgan that she was Patrick''s girlfriend before she disappeared, correcting the narrative.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5567, 2544, 492, 'unknown', false, 'Mentioning her name causes a severe memory failure and physical pain in Gil, indicating she is a key figure connected to the glitches in their reality.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5568, 2883, 492, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'Accompanied by Morgan. A former classmate of Stephen, Gil, and Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5569, 2474, 492, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Partner to Andrew. Former classmate of the others.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5570, 2896, 492, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Was Whitney''s boyfriend. His disappearance and supposed death is a key piece of misinformation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5571, 4354, 492, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A key artifact that alters the scene''s reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5572, 5718, 492, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The direct effect of the Veilwalker Card.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5573, 5719, 492, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'An employee of the Best Buy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5574, 5720, 492, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-02-28 22:53:10.219175-05');
INSERT INTO public.entity_scene_appearances VALUES (5575, 5231, 493, 'ally', true, NULL, 'Shifts from a focused combatant to a state of desperate hope and grim determination upon discovering a potential sign of Whitney.', 'Uses an energy blade formed from the substrate of reality, and a complex tracking device resembling an alchemical orrery.', 'Jumps into the God Null Zone in pursuit of the signal.', NULL, 'Co-combatant and created of Lady Illkeserod; obsessive searcher for Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5576, 2608, 493, 'ally', true, 'Her form is unstable, flickering between a solid state and a mere ''idea of solid''.', 'Moves from annoyed detachment during the fight to surprise, then to a state of sad resignation and concern for Benji.', NULL, NULL, NULL, 'Acts as a powerful ally and creator-figure to Benji, but is unable to follow him into the null zone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5577, 5723, 493, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Hostile entities of the Interstitial Void, attacking Benji and Lady Illkeserod on sight.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5578, 5724, 493, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Wielded by Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5579, 5725, 493, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5582, 5728, 493, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The source of the signal and Benji''s destination.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5583, 5489, 493, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned as the person Benji has been searching for across 367 eternities. The signal is believed to be her beacon.', 'The object of Benji''s long search.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5584, 5730, 493, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5585, 5731, 493, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:54:12.55464-05', '2026-02-28 22:54:12.55464-05');
INSERT INTO public.entity_scene_appearances VALUES (5586, 5489, 494, 'ally', true, 'She is physically exhausted and injured, with a split chin and blistered palms from combat. Her shirt is torn and stained with her own blood.', 'Initially desperate and fighting for survival, she becomes relieved upon finding shelter, and finally focused as she initiates her dream walk.', 'Temporarily wields a gnarled branch from one of the forest''s trees as a makeshift weapon.', NULL, NULL, 'Feels a mysterious connection to a being named Stephen, who is calling to her from another reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5587, 5733, 494, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5588, 5734, 494, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Acts as the oppressive setting for Whitney''s flight and fight.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5589, 5735, 494, 'ally', true, NULL, NULL, NULL, 'Whitney drops it to grapple the final Fire Beast.', 'Whitney grabs it from the ground after being tripped while fleeing the Fire Beasts.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5590, 5736, 494, 'neutral', true, NULL, NULL, NULL, NULL, 'Whitney discovers it hidden in the forest after defeating the Fire Beasts and enters it seeking shelter.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5591, 5737, 494, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5592, 5738, 494, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5593, 5739, 494, 'unknown', true, NULL, NULL, NULL, NULL, NULL, 'It is a call from Stephen, which resonates with the Sigils to open a portal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5595, 5741, 494, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.entity_scene_appearances VALUES (5597, 5489, 495, 'ally', true, 'Her physical form is torn apart and she becomes an incorporeal consciousness trapped in a void. She learns to manifest herself in different realities by manipulating dreams.', 'Experiences extreme terror and powerlessness during her ''deletion'', followed by absolute isolation and hopelessness in the void. This evolves into stubborn resilience and finally a determined hope as she learns to navigate realities and feels a pull towards her friends.', NULL, 'At the end of the scene, she is pulled through a portal created by a mysterious vibration, falling towards a reunion with those who remember her.', 'The scene opens with her in a surreal dream-like state, which is quickly revealed to be the beginning of her existence being erased.', 'She remembers and longs for reunion with Stephen, Benji, and possibly Patrick. She is the target of The Deletion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5598, 5744, 495, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5599, 5745, 495, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5600, 234, 495, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5601, 5747, 495, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5602, 5748, 495, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5604, 5231, 495, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'His name is heard faintly during Whitney''s deletion. She believes he is one of the people who still remembers her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5605, 2896, 495, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Remembered by Whitney as someone who might also have survived and retained memory of her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5606, 5739, 495, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
