INSERT INTO public.entity_scene_appearances VALUES (5608, 5754, 495, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.entity_scene_appearances VALUES (5610, 2896, 496, 'ally', true, NULL, NULL, NULL, NULL, 'Appears in the doorway of his kitchen after Stephen enters the compound.', 'An old acquaintance of Stephen''s. Was being kept isolated by the Whitney Construct.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_scene_appearances VALUES (5611, 5758, 496, 'mini-boss', true, NULL, NULL, NULL, 'Destroyed by Patrick with a ritual blade after being destabilized by Stephen''s invocation.', 'Emerges from a hallway to greet Stephen alongside Patrick.', 'Posed as Patrick''s wife to keep him isolated. Acts as an antagonist towards Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_scene_appearances VALUES (5612, 5759, 496, 'neutral', true, NULL, NULL, NULL, NULL, 'Falls into Stephen''s hand when he stumbles into a bookshelf during the fight.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_scene_appearances VALUES (5613, 5760, 496, 'neutral', true, NULL, NULL, NULL, NULL, 'Grabbed by Patrick from the wall at the start of the fight.', 'Weapon used by Patrick to destroy the Whitney Construct.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_scene_appearances VALUES (5614, 5761, 496, 'ally', true, NULL, NULL, NULL, 'The effect dissipates after the entity is destabilized.', 'Invoked by Stephen when he makes a hand sign remembered from a dream.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_scene_appearances VALUES (5615, 2544, 496, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned by Stephen, which acts as a trigger for the Whitney Construct''s transformation.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_scene_appearances VALUES (5616, 5763, 496, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.entity_scene_appearances VALUES (5618, 2550, 497, 'enemy', false, 'His strategic evolution is revealed: from a mindless beast who inefficiently consumed souls to a sophisticated cosmic farmer. He now cultivates humanity''s suffering through tools like free will and religion to create a more ''flavorful'' and continuous source of nourishment.', 'His past frustration with inefficient consumption is shown, which led to his cold, precise, and terrifying new strategy.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:57:34.277129-05', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_scene_appearances VALUES (5755, 5905, 507, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Devoted followers of The King in Yellow.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.entity_scene_appearances VALUES (5619, 5766, 497, 'enemy', true, NULL, NULL, NULL, 'Recedes on its own after conveying the full scope of Yaldabaoth''s strategic evolution.', 'Appears suddenly, uploading itself into Stephen''s brain while he is in shock.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:57:34.277129-05', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_scene_appearances VALUES (5620, 326, 497, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Viewed by Yaldabaoth as a crop to be harvested for its psychic energy and suffering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:57:34.277129-05', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_scene_appearances VALUES (5621, 5768, 497, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:57:34.277129-05', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_scene_appearances VALUES (5622, 5769, 497, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Acts as a parasitic interface between Humanity and Yaldabaoth, disguised as a benevolent system of worship.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:57:34.277129-05', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_scene_appearances VALUES (5623, 5770, 497, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The primary resource sought by Yaldabaoth from Humanity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:57:34.277129-05', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_scene_appearances VALUES (5624, 5771, 497, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:57:34.277129-05', '2026-02-28 22:57:34.277129-05');
INSERT INTO public.entity_scene_appearances VALUES (5625, 5231, 498, 'ally', true, 'His form is unstable and flickers within the anti-life realm, where he manifests phantom wings that scream in protest. He expends immense energy to pull himself and Whitney out of the realm.', 'Moves from focused urgency to exhaustion, but still manages a crooked grin and banter with Illkeserod.', NULL, NULL, 'Tears through the dimensional membrane to rescue Whitney.', 'Acts as a rescuer to Whitney and shares a familiar, teasing dynamic with Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5626, 5489, 498, 'ally', true, 'Found bleeding and trembling, with skin being eaten away by the realm''s caustic atmosphere. She is physically and emotionally exhausted.', 'Shifts from desperate survival and terror to dazed confusion, then to emotional vulnerability and finally a fragile, newfound hope.', 'Is discovered to be holding the Veilwalker Card, an object that shouldn''t exist in the realm.', NULL, 'Discovered under siege in the anti-life realm.', 'Rescued by Benji. Cared for by Lady Illkeserod. Harbors deep, complicated feelings for Stephen, rooted in his past kindness, which contrasts with the trauma from her abusive father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5627, 2608, 498, 'ally', true, NULL, 'Displays a gentle, comforting demeanor towards Whitney, while also showing surgical precision in her analysis of the situation. Her interactions with Benji reveal a softer, almost human warmth.', NULL, NULL, 'Appears instantly when Benji and Whitney crash into her sanctum.', 'Acts as a maternal, guiding figure to Whitney and shares a familiar, tolerant affection for Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5629, 5776, 498, 'enemy', true, NULL, NULL, NULL, 'Benji forcibly tears himself and Whitney out of the realm.', 'Benji tears into this realm at the start of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5630, 5777, 498, 'enemy', true, NULL, NULL, NULL, 'Displaced across dimensions by Benji''s reality-bending abilities.', 'They are already present and hunting Whitney when Benji arrives.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5632, 4354, 498, 'neutral', true, NULL, NULL, NULL, NULL, 'Discovered clenched in Whitney''s hand after her rescue.', 'A powerful symbol of the connection between Whitney and Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5633, 5780, 498, 'neutral', true, NULL, NULL, NULL, NULL, 'Revealed by Lady Illkeserod as the reason Whitney was able to contact Stephen.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5634, 5781, 498, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned in Whitney''s internal monologue as a source of past trauma.', 'The source of Whitney''s trauma and complicated feelings about men and father figures.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5635, 2550, 498, 'enemy', false, 'Mentioned as a threat that still ''feeds inside the veil'', making any further dimensional tearing extremely dangerous.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5631, 5778, 498, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.entity_scene_appearances VALUES (5638, 2896, 499, 'ally', true, NULL, NULL, NULL, NULL, 'Is present in his trailer at the start of the scene.', 'Acts as a mentor and information source for Stephen, explaining the nature of their prison-reality, Yaldabaoth, and the constructs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5639, 5489, 499, 'enemy', false, 'Revealed to have been a construct, a ''dream someone else had'' with fuzzy, indistinct details about her past. Her physical representation in photographs dissolves into blank paper.', NULL, NULL, 'Her image and memory fade from existence as the truth of her nature as a construct is discussed and accepted.', NULL, 'Was Patrick''s constructed ''wife'', a tool of the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5640, 5787, 499, 'neutral', true, NULL, NULL, NULL, 'They become empty frames as Whitney''s image dissolves.', 'Are present in the trailer, being observed by Stephen.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5641, 5788, 499, 'ally', false, NULL, NULL, NULL, NULL, 'Introduced through Patrick''s story of his post-crash encounter.', 'They act as guides and teachers for Patrick, preparing him to assist Stephen. They are enemies of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5642, 5789, 499, 'neutral', false, NULL, NULL, NULL, NULL, 'Recounted by Patrick as the pivotal moment that led to his contact with The Thirteen.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5643, 5790, 499, 'neutral', true, NULL, NULL, NULL, NULL, 'Explained by Patrick as the true nature of their existence.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5644, 2550, 499, 'enemy', false, 'Further described not just as a conqueror, but as a cosmic plague that consumes everything, including realities and other gods. It is the primary entity that The Prison was built to contain.', NULL, NULL, NULL, NULL, 'The main antagonist contained within The Prison. It is an enemy to both humanity and the Elder Gods.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5645, 5792, 499, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by Patrick as the method he uses to communicate with his otherworldly contacts.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5646, 5793, 499, 'neutral', false, NULL, NULL, NULL, NULL, 'Explained by Patrick as the source of the power Stephen invoked.', 'Enemies of Yaldabaoth, but also hostile to humanity. Cthulhu is one of them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5647, 5794, 499, 'neutral', false, NULL, NULL, NULL, NULL, 'Identified by Patrick as the entity Stephen invoked.', 'A member of the Elder Gods.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5696, 5489, 503, 'ally', true, NULL, 'Moves from raw frustration and exhaustion to deep, nostalgic love and guilt, culminating in determined hope. She also experiences a revelation about her ''escape,'' reframing it as survival from a system purge.', NULL, NULL, NULL, 'Her deep, familial bond with Stephen is the key to breaching the void. She views Lady Illkeserod and Benji as guides and allies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_scene_appearances VALUES (5806, 5835, 512, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Stephen''s twin flame. Becomes the ''anode'' or power source of The Prison, separated from Stephen for eternity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5648, 2549, 499, 'mini-boss', false, 'Revealed to be a construct, a ''prison guard wearing a wedding ring''. Her behavior is an adaptive program: she escalates to violence and emotional manipulation when Stephen gets close to the truth, then reverts to a ''perfect'' loving wife to keep him docile and trapped. Her name on her driver''s license is unreadable, highlighting her artificial nature.', 'Her emotional state is not genuine, but a shifting facade designed to control Stephen. It ranges from violent and vile to perfectly loving and seductive depending on what is required to maintain his imprisonment.', NULL, NULL, NULL, 'Her relationship with Stephen is a lie, a jailer-prisoner dynamic disguised as a marriage. She perceives their son, Xavier, as a potential threat to her mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5649, 4141, 499, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned by Stephen as he connects the dots about his reality.', 'Son of Stephen. He is in danger from his constructed mother, who may eliminate him if he threatens her mission to keep Stephen docile.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5650, 5797, 499, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.entity_scene_appearances VALUES (5652, 2896, 500, 'ally', true, NULL, NULL, NULL, 'Remains in his study after Stephen leaves.', 'Is present at the start of the scene, ready to provide Stephen with help.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:00:16.411887-05', '2026-02-28 23:00:16.411887-05');
