INSERT INTO public.entity_scene_appearances VALUES (5659, 2544, 500, 'ally', false, 'Revealed to be the reason Stephen is trapped in a recurring cycle; he keeps coming back because he refuses to leave her behind.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:00:16.411887-05', '2026-02-28 23:00:16.411887-05');
