INSERT INTO public.entity_scene_appearances VALUES (5683, 2549, 502, 'mini-boss', true, 'Exhibits inhuman ''glitching'' behaviors like unnatural pupil dilation and jerky movements. Is ultimately killed when a bookcase collapses on her.', 'Begins in a state of extreme, irrational rage. Her emotions become distorted and performative, culminating in a cold, methodical attempt at murder before she is killed.', NULL, 'Crushed to death by a collapsing bookcase during her attack on Stephen.', NULL, 'Stephen''s wife and Xavier''s mother. Acts as the primary antagonist of the scene, physically and verbally attacking her family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_scene_appearances VALUES (5684, 3993, 502, 'ally', true, 'Receives four red scratch marks on his neck from his mother''s attack, which begin to bruise.', 'Moves from a practiced, stoic endurance of the verbal abuse to terror during the physical assault, and finally to a quiet, grim resolve to escape.', NULL, NULL, NULL, 'Son of Stephen and the wife. He is the initial target of his mother''s rage and identifies her strange behavior as ''glitching''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_scene_appearances VALUES (5685, 5834, 502, 'neutral', false, NULL, NULL, NULL, NULL, 'Triggered by the aggression of Stephen''s wife, causing time to feel like it shatters for him.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_scene_appearances VALUES (5686, 5835, 502, 'neutral', false, NULL, NULL, NULL, NULL, 'Appears only within Stephen''s flashback.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.entity_scene_appearances VALUES (5687, 5836, 502, 'neutral', false, NULL, NULL, NULL, NULL, 'A key concept revealed during Stephen''s memory.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
