INSERT INTO public.entity_scene_appearances VALUES (5697, 2608, 503, 'ally', true, NULL, 'Remains calm, patient, and guiding throughout. She acts as a mentor, pushing Whitney towards an emotional breakthrough and providing crucial exposition about the prison''s nature.', NULL, NULL, NULL, 'Acts as a mentor and guide to Whitney, helping her channel her power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_scene_appearances VALUES (5698, 5231, 503, 'ally', true, 'Shifts form from a winged eye wreathed in pale blue flame to a nine-foot-tall beast of black chitin with hundreds of claws, before returning to the eye form and settling on Whitney''s shoulder.', 'Goes from attempting to be terrifying to genuinely defeated when his monster form fails, then shifts to a supportive and professorial tone.', NULL, NULL, NULL, 'An ally to Whitney and Lady Illkeserod, providing both attempts at assistance and exposition.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
