INSERT INTO public.entity_scene_appearances VALUES (5709, 5858, 503, 'enemy', false, NULL, NULL, NULL, NULL, 'Recalled in Whitney''s memories as the source of her initial trauma and abandonment.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_scene_appearances VALUES (5710, 5859, 503, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.entity_scene_appearances VALUES (5712, 3993, 504, 'ally', true, NULL, 'Moves from curiosity and unease to awe in the library, and finally to terror and grief during the attack and escape.', NULL, 'Escapes with Stephen after TJ''s sacrifice.', 'Accompanies his father, Stephen, to the outreach center.', 'Son of Stephen. He is observant and supportive of his father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5713, 2884, 504, 'ally', true, NULL, NULL, NULL, 'Overwhelmed and killed by the Unraveled NPCs while performing a banishment ritual to allow Stephen and Xavier to escape.', 'Emerges from a ''STAFF ONLY'' room to greet Stephen after being summoned by Linda.', 'An old high school friend of Stephen. He acts as a guide and ultimately a savior, sacrificing himself for Stephen''s escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5714, 5863, 504, 'neutral', true, NULL, NULL, NULL, 'Presumed to have been transformed into one of the Unraveled NPCs during the attack.', 'Confronts Stephen and Xavier when they first enter the outreach center.', 'An associate of TJ, possibly one of his NPC congregation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5715, 5864, 504, 'neutral', true, NULL, NULL, NULL, 'They transform into the ''Unraveled NPCs'' when the system is triggered.', 'They are present in the main room when Stephen and Xavier arrive.', 'They are TJ''s ''flock,'' a punishment inflicted upon him by the demiurge based on a story he wrote as a teenager.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5717, 5866, 504, 'neutral', true, NULL, NULL, NULL, 'Left behind as Stephen and Xavier flee through a back stairwell.', 'Revealed when TJ leads Stephen and Xavier down a staircase.', 'TJ''s sanctuary and research center.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5718, 5867, 504, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by TJ as the source of his awakening seven years prior.', 'A key piece of lore in the Heretic''s Library.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5719, 5868, 504, 'neutral', true, NULL, NULL, NULL, 'Presumably consumed in the ritual as TJ is overwhelmed.', 'TJ pulls it from his backpack to confront the Unraveled NPCs.', 'TJ''s last-resort weapon.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5720, 2544, 504, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned by Stephen as a forgotten person from high school. Speaking her name acts as a trigger for the system''s defenses.', 'Her name is a system-level trigger, suggesting immense importance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5721, 5870, 504, 'enemy', true, NULL, NULL, NULL, 'Fled from by the protagonists.', 'Appears instantly when Stephen says the name ''Jamie''.', 'A defense mechanism of the prison/system.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5716, 5865, 504, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.entity_scene_appearances VALUES (5762, 3993, 508, 'ally', true, 'Sustains a badly sprained ankle during their flight.', 'Displays a ''new, terrified authority'' while directing his injured father, overriding Stephen''s delirium to get them to safety. He is pale and worried, but his disgust at the homemade wine provides a moment of levity before he succumbs to exhaustion.', NULL, NULL, NULL, 'Son of Stephen; patient to Maeve and Elara.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_scene_appearances VALUES (6489, 6652, 569, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (5724, 3993, 505, 'ally', true, 'Has four raw, red lines on his neck from his mother''s attack, which are now being bandaged.', 'Moves from a state of silent shock to panic and confusion upon seeing his friends'' messages, then to horrified disbelief and fury at his mother''s televised lies. This collapses into despair before a flicker of hope emerges from loyal friends, leading him to seek refuge in the normalcy of a mobile game.', 'Now possesses a cheap USB-C cable for his phone.', NULL, NULL, 'Son of Stephen and Angela. He is being protected by his father while being publicly portrayed as a kidnap victim by his mother. His relationships with his friends are being tested by the public narrative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_scene_appearances VALUES (5769, 5919, 508, 'neutral', true, NULL, NULL, NULL, 'Abandoned upon arrival at the farmhouse.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_scene_appearances VALUES (5770, 5920, 508, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_scene_appearances VALUES (5771, 5921, 508, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.entity_scene_appearances VALUES (5807, 5853, 512, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Mediator who convinces the Elder Gods to accept the prison plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5725, 2549, 505, 'mini-boss', false, 'Appears on television with a shaved head, a face covered in skillfully applied bruises, wearing a hospital gown, neck brace, and arm sling to present herself as a victim.', 'Publicly projects an image of a distraught, sobbing, and terrified victim, a calculated performance to manipulate public opinion.', NULL, 'The television is turned off.', 'Appears on a televised press conference.', 'Ex-wife of Stephen and mother of Xavier. She is actively working to frame Stephen as a violent kidnapper and position herself as the victim.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.entity_scene_appearances VALUES (5726, 5876, 505, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
