INSERT INTO public.entity_scene_appearances VALUES (5737, 3993, 506, 'ally', true, NULL, 'Moves from sleepy and annoyed by the disguise to frightened by the burned store. He then becomes focused and instrumental in researching their next lead, despite some disgust and nervous humor at the search results.', 'Acquires a garish tie-dye hoodie and a beanie as a disguise.', NULL, 'Is woken up by his father, Stephen, at the start of the scene.', 'Son of Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
