INSERT INTO public.entity_scene_appearances VALUES (5746, 5896, 506, 'unknown', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.entity_scene_appearances VALUES (5774, 5489, 509, 'ally', true, 'Appears as a frantic and terrified but real presence within the Dream plane, not just a memory.', 'Frantic and terrified, but determined to help Stephen. She is shaken by the death of TJ but urgently focuses on the plan to reach the Akashic Realm.', NULL, 'Her connection is cut off by Nyarlathotep.', 'Nyarlathotep opens a connection, allowing her to appear before Stephen in the void.', 'A desperate ally to Stephen, trying to guide him to safety and a way out of the system.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5775, 2544, 509, 'ally', false, NULL, NULL, NULL, NULL, 'Her name is revealed by Nyarlathotep as a ''key'' to unlock Stephen''s suppressed past, triggering a flood of memories.', 'The subject of Stephen''s recovered memories; a lost love for whom he sacrificed everything.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5776, 3993, 509, 'ally', true, NULL, 'Awakened and alarmed by his father''s screaming, his voice cracks with fear and confusion.', NULL, NULL, 'Appears at the end of the scene, rushing to Stephen''s side after he wakes up screaming.', 'Stephen''s son, who is present and concerned for his father''s well-being.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5777, 5927, 509, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The setting for the confrontation with Nyarlathotep and the reunion with Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5778, 5928, 509, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Directly linked to Stephen and Jamie, representing their shared past.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5779, 2550, 509, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned by Nyarlathotep as the ''bore'' who created the prison of loops and is a terrible host.', 'The creator of the system and the ideological opposite of Nyarlathotep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5780, 5655, 509, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The goal for Stephen, recommended by Whitney and connected to Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5781, 5468, 509, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The source of creation that Stephen must interface with, according to Nyarlathotep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5773, 5853, 509, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.entity_scene_appearances VALUES (5784, 5913, 510, 'ally', true, NULL, NULL, NULL, NULL, 'Enters the bedroom after hearing Stephen is awake, walking up the stairs softly.', 'Acts as a caregiver to Stephen and Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_scene_appearances VALUES (5785, 2658, 510, 'ally', true, NULL, NULL, NULL, NULL, 'Enters the bedroom with Maeve, moving to sit in a chair by the window.', 'Acts as a caregiver to Stephen and Xavier, and a confidante encouraging his story.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_scene_appearances VALUES (5786, 3993, 510, 'ally', true, 'Appears as a fourteen-year-old boy, initially silhouetted in his bed. He pulls a blanket around his shoulders as he prepares to listen to Stephen''s story.', 'Shows fear and confusion on his face, but is attentive and prompts Stephen to start his story from the beginning.', NULL, NULL, NULL, 'Looks to Stephen for answers and protection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_scene_appearances VALUES (5787, 5938, 510, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_scene_appearances VALUES (5788, 5939, 510, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_scene_appearances VALUES (5789, 5940, 510, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.entity_scene_appearances VALUES (5791, 3993, 511, 'ally', true, NULL, 'Deeply empathetic and emotional, he cries while listening to Stephen''s story and urges him to continue despite the pain, needing to understand the full truth.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_scene_appearances VALUES (5792, 2550, 511, 'enemy', false, 'His nature is further elaborated upon, described not just as a monster but as a cosmic infection and a devourer of entire realities, driven by a hunger for essence itself. His ability to learn from and steal the power of his victims is revealed.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_scene_appearances VALUES (5793, 2658, 511, 'ally', true, NULL, NULL, NULL, NULL, 'Leans forward to interject a key point into Stephen''s tragic story.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_scene_appearances VALUES (5794, 5913, 511, 'ally', true, NULL, NULL, NULL, NULL, 'Speaks up after Elara to confirm Stephen''s discovery about the souls.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
