INSERT INTO public.entity_scene_appearances VALUES (5801, 5952, 511, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_scene_appearances VALUES (5802, 5953, 511, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.entity_scene_appearances VALUES (5804, 2550, 512, 'mini-boss', false, 'Revealed to be a conceptual entity, an ''anti-reality'' that consumes other realities. He cannot be killed, only contained, as he feeds on erasure itself.', 'Experiences dawning horror upon realizing he has been trapped in the prison.', NULL, NULL, NULL, 'The primary antagonist being contained by The Prison. He is unable to understand or consume the manifestation of Love.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5805, 5654, 512, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Comprised of gods like Tiamat, Hecate, Chernobog, and Lady Illkeserod. They are the architects of the plan to imprison Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5944, 6096, 522, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5808, 5468, 512, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Foundation of The Prison. Wipes the memories of all inhabitants during each reset cycle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5809, 5960, 512, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Contains Yaldabaoth. Its foundation is Azathoth, its power source is Stephen and Velistra, and its outer wall is Sophia''s essence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5810, 514, 512, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Sophia''s maternal love was the original container; Stephen and Velistra''s twin flame love is the prison''s eternal battery.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5811, 5962, 512, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Reveals the secret that love is the key to containing Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5812, 5963, 512, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Reveals the secret that love is the key to containing Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5813, 5964, 512, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'They are convinced by Nyarlathotep to become part of the prison''s architecture, woven into its substrate to sleep and dream.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5814, 5524, 512, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The original jailer of Yaldabaoth, providing the blueprint for his new prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
