INSERT INTO public.entity_scene_appearances VALUES (5816, 2658, 512, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Listener in the present-day framing narrative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5817, 4141, 512, 'unknown', true, NULL, NULL, NULL, NULL, NULL, 'An audience to Stephen''s tale.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5818, 5953, 512, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.entity_scene_appearances VALUES (5820, 2550, 513, 'enemy', false, 'His history within the prison is detailed: he consumed the gods, went mad upon realizing his confinement, caused the first cycle to implode, and corrupted Velistra into an archon to quell rebellion in subsequent cycles.', 'Described as experiencing rage and desperation leading to madness during the first cycle.', NULL, NULL, NULL, 'Jailer and tormentor of Stephen. Creator of Velistra Seducera. Enemy of the Elder Gods and Azathoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5821, 4141, 513, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Ally and audience to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5822, 5913, 513, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Ally and audience to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5823, 2658, 513, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Ally and audience to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5824, 5835, 513, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Lover of Stephen. Source material for Velistra Seducera. Victim of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5826, 5468, 513, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Acts as a reset function for the Abyss/prison. Prevents Yaldabaoth from fully extracting Velistra.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5827, 982, 513, 'neutral', true, 'Revealed to be named Etheris, a reality with no internal magic, making it a perfect prison. It is designed to handle immense energy concentration by forcing an implosion and reset, a cycle which has repeated infinitely.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5828, 5348, 513, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5829, 5793, 513, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5830, 5981, 513, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5831, 5982, 513, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5832, 5983, 513, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Lover of Hobart McComas III (Stephen). Victim of the My Lai massacre.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5833, 5231, 513, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned as having been sent to investigate the crack in the prison''s foundation that formed after the deaths of Hobart and Si Le Tra Vi.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5825, 4876, 513, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.entity_scene_appearances VALUES (5836, 3993, 514, 'ally', true, 'His origin is revealed: he is not a native of the prison but a spirit pulled from a pocket of anti-reality, making him a ''glitch'' in the system.', 'Becomes pale with shock and confusion, transitioning to dawning understanding as his unique abilities are explained by his unnatural origin.', NULL, NULL, NULL, 'Learns he is the adopted spiritual son of Stephen, not the biological child of the woman he knew as his mother. His existence is the cause of the prison''s instability.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5837, 2549, 514, 'neutral', false, 'Explicitly identified as a non-player character (NPC), a ''construct'' created by the prison with safeguards designed to keep Stephen docile and searching.', NULL, NULL, NULL, NULL, 'Revealed to be a tool of the prison, not a true mother to Xavier or partner to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5838, 982, 514, 'enemy', true, 'Revealed to be an active system with ''safeguards'' and a ''design''. It can create NPC constructs and initiate reality-altering ''resets'' to correct anomalies that threaten its stability.', NULL, NULL, NULL, NULL, 'Acts as the primary antagonist, a jailer that actively tries to control its inhabitants and ''fix'' errors like Xavier''s existence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5839, 2550, 514, 'enemy', false, 'Described as containing a ''pocket of anti-reality'' at his center, which serves as a trap for consumed souls. He was the primary antagonist in two previous system resets.', NULL, NULL, NULL, NULL, 'Serves as a sort of cosmic container for the void from which Xavier was pulled. He is the recurring final boss of the prison''s cycles.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5840, 2544, 514, 'neutral', false, 'Mentioned as a key figure in the second system reset, where she was pulled into reality and incarnated as ''Jamie'' after Stephen''s natural death triggered the event.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5841, 4028, 514, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The spiritual origin point for Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5842, 5993, 514, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'A direct consequence of Xavier''s existence and a tool of the Abyss.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5843, 456, 514, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.entity_scene_appearances VALUES (5847, 5913, 515, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Works closely with Elara, sharing an unspoken understanding. Acts as a guide or informant for Stephen and Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_scene_appearances VALUES (5848, 2658, 515, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Shares a close, non-verbal bond with Maeve. Acts as a mentor or revealer of truths to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_scene_appearances VALUES (5849, 982, 515, 'enemy', true, 'The prison''s self-correction mechanism is revealed to be failing. It has attempted to ''reset'' reality three times to eliminate anomalies like Xavier but has been unsuccessful, an unprecedented event.', NULL, NULL, NULL, NULL, 'The antagonistic force containing all the characters. Its instability is allowing memories and ''glitches'' to persist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_scene_appearances VALUES (5850, 6001, 515, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'Stephen''s potential daughter; possibly connected to Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_scene_appearances VALUES (5851, 3993, 515, 'ally', true, 'Has a wrapped ankle, causing him to wince when putting weight on it.', 'Inquisitive and quick to make connections. He is confused by the silent communication between Maeve and Elara but is actively trying to understand the implications of Hannah and Whitney.', NULL, NULL, NULL, 'Son of Stephen. He is the original ''glitch'' that destabilized the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_scene_appearances VALUES (5852, 5489, 515, 'unknown', false, 'Her role is re-contextualized. Previously just a friend from an alternate reality, she is now speculated to have a deeper connection to the glitches in the system, possibly being linked to Hannah.', NULL, NULL, NULL, NULL, 'Theorized by Xavier to be connected to Hannah, a possibility Stephen denies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_scene_appearances VALUES (5853, 2549, 515, 'enemy', false, 'Revealed to be a construct designed to keep Stephen docile. She is now described as ''frigid'' and actively preventing the birth of Hannah, reinforcing her role as an agent of the prison.', NULL, NULL, NULL, NULL, 'Stephen''s wife and Xavier''s mother. Her purpose is to maintain the stability of Stephen''s imprisonment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_scene_appearances VALUES (5854, 6005, 515, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.entity_scene_appearances VALUES (5856, 3993, 516, 'ally', true, 'Described as an ''impossible boy'' who glitched the system by being born, highlighting his fundamental importance to the prison''s instability.', 'Engaged and quick-witted, immediately grasping the implications of his father''s plan and questioning the nature of their new allies.', NULL, NULL, NULL, 'Son of Stephen; the catalyst for the prison''s cracking.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5857, 982, 516, 'enemy', true, 'Revealed to have ''cracked'' when Xavier was born and when his parents'' love ''shook the foundations''. It is a place where the necessary magic and knowledge for escape do not exist naturally.', NULL, NULL, NULL, NULL, 'The primary antagonist environment that the characters are trying to escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5858, 5913, 516, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Partner to Elara; an ancient guardian or observer waiting to help Stephen (Aspolin).', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5859, 2658, 516, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Partner to Maeve; an ancient being ready to aid in the escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5860, 6011, 516, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The central objective of the characters'' plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5861, 5853, 516, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned by Stephen as the source of his escape plan.', 'An enigmatic source of information for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5862, 5654, 516, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned by Xavier as the group that can help them escape.', 'Allies of Stephen and Xavier operating in the outside world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5864, 5655, 516, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The goal of the escape plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5863, 6014, 516, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.entity_scene_appearances VALUES (5867, 3993, 517, 'ally', true, 'He limps on a tightly wrapped ankle, testing his weight on it.', 'Skeptical and audibly questioning of the ritual''s strange requirements and unassuming appearance.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5868, 5913, 517, 'ally', true, NULL, NULL, NULL, NULL, 'Arrives at the gymnasium with Stephen, Xavier, and Elara to begin the ritual.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5869, 2658, 517, 'ally', true, NULL, NULL, NULL, NULL, 'Arrives at the gymnasium with the group and identifies it as the correct location.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5870, 6022, 517, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Requires the ''Residue of Knowledge'' from the location, the ''Ritual Components'' for its foundation, the ''Pile of Refuse'' for fuel, and Stephen''s intellect to give it structure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5871, 6023, 517, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5872, 6024, 517, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5873, 6025, 517, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5874, 6026, 517, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5875, 2544, 517, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned in Stephen''s thoughts as a primary motivation for enduring the ritual.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5876, 6028, 517, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.entity_scene_appearances VALUES (5878, 3993, 518, 'ally', true, NULL, 'Becomes pale and terrified by the violence, calling out to his father for guidance and protection. He shows a brief moment of bravery by hitting a cop with a broken lacrosse stick.', NULL, 'Falls through the portal with his father.', NULL, 'Son of Stephen and the bounty hunter. He is the target of the opposing forces.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5943, 6095, 522, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Enemies of The Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (6490, 6653, 569, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (5879, 5913, 518, 'ally', true, NULL, NULL, NULL, 'Killed instantly when her head is vaporized by a high-caliber sniper round.', 'Is present at the start of the scene, performing a ritual with Elara.', 'Partner to Elara in their ritual and fight. A temporary, sacrificial protector for Stephen and Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5880, 2658, 518, 'ally', true, NULL, NULL, NULL, 'Shot in the back and killed by a tactical unit. She uses her dying breath to activate the portal.', 'Is present at the start of the scene, performing a ritual with Maeve.', 'Partner to Maeve. A temporary, sacrificial protector for Stephen and Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5881, 2549, 518, 'mini-boss', true, 'Her identity as a demure, quiet wife is revealed to be a facade. She appears as a cold, commanding bounty hunter in a dark suit with an FBI badge, completely comfortable with extreme violence.', 'Drops the mask of a loving wife entirely, becoming ruthless, authoritative, and screaming orders to kill Stephen.', 'Now wears a dark suit and an FBI badge.', NULL, 'Appears in the doorway after Maeve and Elara are killed, taking command of the tactical units.', 'Revealed to be an enemy and bounty hunter, not Stephen''s wife or Xavier''s mother. She is the commander of the tactical units.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5882, 6034, 518, 'enemy', true, NULL, NULL, NULL, 'Quickly and brutally killed or incapacitated by Maeve and Elara.', 'Burst through the door in response to the sirens.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5883, 6035, 518, 'enemy', true, NULL, NULL, NULL, NULL, 'Rappel through the high windows from a helicopter.', 'Subordinate to Stephen''s wife, who commands them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5884, 6036, 518, 'enemy', false, NULL, NULL, NULL, NULL, 'Implied to have taken position while the main assault was underway.', 'Part of the enemy force, likely a member of the tactical units.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5885, 6037, 518, 'neutral', true, NULL, NULL, NULL, 'Falls to the ground when Maeve is killed.', 'Maeve pulls it from beneath her shawl as the police arrive.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5886, 6038, 518, 'neutral', true, NULL, NULL, NULL, 'Collapses after Stephen and Xavier fall through.', 'Is the focus of the fae ritual at the start of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5887, 6039, 518, 'neutral', true, NULL, NULL, NULL, NULL, 'Used by the second cop to shoot Maeve.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5888, 2759, 518, 'neutral', true, NULL, NULL, NULL, 'Drowned out by the arrival of the helicopter.', 'Heard suddenly, interrupting Stephen''s frustrated outburst.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5889, 6041, 518, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.entity_scene_appearances VALUES (5891, 3993, 519, 'ally', true, 'His previously injured ankle feels strange and ''lighter'' due to the altered gravity of the Akashic Realm.', 'Experiences fear, grief over Maeve and Elara''s deaths, and cognitive confusion from the Wisdom Devourers'' attack. He is horrified upon learning the nature of his father''s and Jamie''s imprisonment.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5892, 5231, 519, 'ally', true, 'Appears more worn, tired, and tattered than before, as if he''s been fighting for a long time. He demonstrates a new ability to transform into a ''vast and winged'' form to intimidate creatures of the realm.', 'Weary but resolute. He is authoritative when dealing with the Devourers and acts as a knowledgeable, if tired, guide for Stephen and Xavier.', 'His cardigan is noted as being more worn and tattered.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5893, 2608, 519, 'ally', true, NULL, 'Appears sad, cautious, and resolute. She calmly accepts Stephen''s anger and explains her difficult choices with a sense of weary justification and guilt.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5894, 2749, 519, 'ally', true, 'Described as shorter, rounder, with dark skin and eyes that seem to contain entire universes. Her robes are brown and practical, covered in shifting embroidered symbols.', 'A calm, observant, and knowledgeable figure. Her voice is described as ''precise'' and ''motherly'' as she explains the horrifying scale of the prison''s cycles.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5895, 6047, 519, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5896, 5655, 519, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5897, 6049, 519, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'It is Lady Illkeserod''s domain and the center of the Archives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5898, 6050, 519, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5899, 6051, 519, 'ally', false, NULL, NULL, NULL, 'Died defending the gateway to allow Stephen and Xavier to escape.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5900, 2549, 519, 'neutral', false, NULL, NULL, NULL, NULL, 'Stephen sees a vision of her screaming on the other side of the closing portal from Etheris.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5901, 2544, 519, 'ally', false, NULL, NULL, NULL, NULL, 'The subject of Lady Illkeserod''s lie and the co-power source for the prison, whose existence Stephen now knows for certain.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5902, 2550, 519, 'big-boss', false, NULL, NULL, NULL, NULL, 'Mentioned by Lady Illkeserod as the entity the prison was built to contain, justifying the extreme sacrifices made by Stephen and Jamie.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5903, 6055, 519, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.entity_scene_appearances VALUES (5906, 3993, 520, 'ally', true, NULL, 'Starts as a quiet observer, sharing his father''s uncertainty, but becomes defiant and insistent on joining the fight, refusing to be left behind in safety.', 'His grip tightens on his walking stick, signifying its importance as a potential weapon or security object.', NULL, NULL, 'Son of Stephen. He shows a new, hard-edged resolve, moving past his recent trauma to stand with his father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5907, 2608, 520, 'ally', true, NULL, 'Acts as a decisive commander, initially pragmatic and protective by ordering Stephen to stay behind, but ultimately respects his resolve and allows him to join the defense.', NULL, NULL, NULL, 'Leader of the Archives'' defense forces, working alongside Osilari and Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5908, 2749, 520, 'ally', true, NULL, 'Appears grim but resolute, taking charge of gathering the defense forces. Her eyes glow faintly, hinting at her power and readiness for battle.', NULL, NULL, NULL, 'A key leader in the Archives, responsible for mobilizing the Priests of Osilari and other defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5941, 6093, 522, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'An internal force that possesses and empowers Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (6145, 157, 542, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Represents a past failure and a source of immense guilt for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_scene_appearances VALUES (5909, 5231, 520, 'ally', true, NULL, 'His voice is tight with tension as he explains the nature of the invading army, providing crucial intelligence on the enemy forces.', NULL, NULL, NULL, 'An ally who provides context and analysis of the threat, fighting alongside Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5910, 2549, 520, 'mini-boss', false, 'She has manifested as a powerful, reality-tearing being who has brought an entire army with her into the Akashic Realm. She is actively hunting Stephen and his family.', 'Depicted as a furious, destructive force, screaming and tearing reality apart in her hunt.', NULL, NULL, 'Her arrival is signaled by a pressure change and flaring symbols throughout the Archives, indicating a massive disturbance.', 'The primary antagonist of the scene, leading an army to find Stephen, whom she believes still belongs to her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5911, 2544, 520, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned by Xavier when he asks Stephen about their future relationship.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5912, 6064, 520, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Serves as the military force for the mini-boss, Angela.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5913, 6065, 520, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Subordinates within The Invading Army.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5914, 6066, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The primary defense force against The Invading Army.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5915, 6067, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A member of The Archives'' Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5916, 6068, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A unit within The Archives'' Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5917, 6069, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A unit within The Archives'' Defenders, loyal to Lady Osilari.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5918, 6070, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A support unit within The Archives'' Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5919, 6071, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A unit within The Archives'' Defenders, loyal to Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5920, 6072, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A mindless unit within The Archives'' Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5921, 6073, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A mindless unit within The Archives'' Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5922, 6074, 520, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A commander within The Archives'' Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5923, 6075, 520, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The initial battlefield for the conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5924, 6076, 520, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.entity_scene_appearances VALUES (5926, 3993, 521, 'ally', true, 'His physical form is violently stretched and distorted before he is erased from reality, leaving a void where he stood.', 'He is scared but fights back defiantly before being captured. His final moments are a silent, O-mouthed shock.', NULL, 'Erased from existence after being captured by his mother, his form popping like a bubble.', NULL, 'Son of Stephen and the warped Angela. He is the primary target of his mother''s maternal rage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_scene_appearances VALUES (5927, 2549, 521, 'mini-boss', true, 'Her form is grotesquely warped, with proportions stretching and compressing. Her face is a ''liquid nightmare'' that constantly melts and reforms, and her entire body glitches like a bad TV signal. She is fused with her suit and drenched in gore.', 'Exhibits a disturbing blend of possessive, almost tender maternal feelings towards Xavier, and pure, animalistic rage when thwarted.', NULL, NULL, NULL, 'The primary antagonist, hunting her son Xavier and husband Stephen. She commands the Twisted NPC Agents.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_scene_appearances VALUES (5928, 6080, 521, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_scene_appearances VALUES (5929, 6081, 521, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_scene_appearances VALUES (5930, 6082, 521, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_scene_appearances VALUES (5931, 6083, 521, 'neutral', true, NULL, NULL, NULL, 'Its fate is unmentioned after the fight in the tavern.', 'Taken from a human agent Stephen tackles inside the tavern.', 'Weapon used by Stephen to kill two agents.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_scene_appearances VALUES (5932, 6084, 521, 'neutral', true, NULL, NULL, NULL, NULL, 'Comes into being at the exact moment of Xavier''s disappearance.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_scene_appearances VALUES (5933, 6085, 521, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.entity_scene_appearances VALUES (5934, 6086, 522, 'ally', true, 'He becomes a conduit for a primal power, his hands crackling with purple-black energy.', 'Experiences a profound transformation from grief to an ancient, inhuman rage, which is then replaced by a cold, hollow shock and aching regret after he destroys his wife.', NULL, NULL, NULL, 'Husband of Angela, father of Xavier. He acts as both judge and executioner for Angela, fueled by rage over his son''s death. He is comforted by Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5935, 6087, 522, 'mini-boss', true, 'Her face is described as melting. Her body is torn apart by Stephen''s attack, revealing a divine spark at her core. For a moment before dissolving, her form reverts to a ''porcelain doll'' and her eyes become clear.', 'Shifts from potential fear to a moment of genuine humanity and whispered apology, before her ''NPC programming'' reasserts a final, possessive thought.', NULL, 'Completely destroyed by Stephen''s power blast. Her divine spark is freed and departs.', NULL, 'Wife of Stephen, murderer of their son Xavier. She is the target of Stephen''s rage and retribution.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5936, 6088, 522, 'ally', true, NULL, 'Her demeanor is gentle and her eyes are filled with pity for Stephen''s loss.', NULL, NULL, 'Appears beside Stephen after he collapses.', 'Acts as a guide and source of information for Stephen, explaining the nature of the Akashic Realm and the uncertainty of Xavier''s fate.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5937, 6089, 522, 'neutral', true, 'Manifests as crackling, purple-black energy around Stephen''s fists.', NULL, NULL, 'Vanishes from Stephen after Angela is destroyed, leaving him feeling hollow.', 'Channeled by Stephen through an instinctual, forgotten knowledge.', 'A force used by Stephen to exact his revenge on Angela.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5938, 6090, 522, 'neutral', true, 'Revealed at Angela''s core, it is small, weak, but real. It glows softly before departing.', NULL, NULL, 'Drifts upward and away after being freed from Angela''s form.', 'Appears as Angela''s body is torn apart.', 'The true essence within Angela, suggesting a core of something real beneath her corrupted programming.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5939, 4141, 522, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Son of Stephen and Angela. His murder by his mother drives the scene''s central conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5940, 6092, 522, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The setting of the scene and the mechanism by which Xavier disappears.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5942, 6094, 522, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Allies of Stephen and Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.entity_scene_appearances VALUES (5945, 5231, 523, 'ally', true, 'His cardigan is torn and bloody.', 'Appears grim and pleads with Stephen, desperate to make him understand the severity of the situation.', NULL, NULL, NULL, 'Ally to Stephen and Lady Illkeserod, acting as a messenger of the dire situation and the one who contacts Nyarlathotep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5946, 2608, 523, 'ally', true, NULL, 'Her expression is pained, her eyes heavy with sorrow and horror at Stephen''s decision. She shows a terrible, sad understanding of the consequences but ultimately sighs and agrees to help.', NULL, NULL, NULL, 'Ally to Stephen and Benji, she confirms the danger and negotiates with Nyarlathotep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5948, 3993, 523, 'neutral', false, 'Has been ejected into an unknown reality. Lady Illkeserod cannot sense if he is alive, dead, or trapped. His blood stains the stone on the battlefield, a physical reminder of his recent loss.', NULL, NULL, NULL, NULL, 'Stephen''s son, whose recent loss is a key factor in Stephen''s emotional state and decision-making.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5949, 2544, 523, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'The person Stephen is determined to rescue from the prison, serving as his sole remaining motivation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5950, 982, 523, 'enemy', true, 'The realm has become destabilized due to recent violence and has enacted new security protocols. Its impending collapse threatens to trap everyone inside, and Stephen''s plan to re-enter it will trigger this collapse, freeing Yaldabaoth.', NULL, NULL, NULL, NULL, 'The antagonistic setting, a cosmic prison whose structural integrity is failing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5951, 2550, 523, 'enemy', false, 'He is the entity trapped within the prison. The collapse of the prison, which Stephen''s actions will cause, will set him free to wreak havoc on countless realities.', NULL, NULL, NULL, NULL, 'The ultimate antagonist, whose freedom is the primary consequence of Stephen''s actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5952, 6104, 523, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The failing escape route that precipitates the scene''s central conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5953, 6105, 523, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'A powerful, neutral-to-antagonistic gatekeeper who must be bargained with for passage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5954, 6106, 523, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The historical conflict that established the current cosmic order, which is now threatened.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5955, 6107, 523, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The gateway to Stephen''s next objective.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5956, 6108, 523, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'The entity whose domain Stephen is about to enter.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5957, 5489, 523, 'neutral', false, 'Mentioned by Nyarlathotep as a previous system corruption that he unsuccessfully tried to purge, indicating her actions had significant, reality-level consequences.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5958, 6110, 523, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.entity_scene_appearances VALUES (5960, 5231, 524, 'ally', true, NULL, 'Concerned for Stephen''s safety but urges him onward due to a lack of time.', NULL, NULL, NULL, 'Gives Stephen the Veilwalker card as a protective gift.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5961, 2608, 524, 'ally', true, NULL, 'Pragmatic and direct, offering a warning along with her magical healing.', NULL, NULL, NULL, 'Heals Stephen''s wounds before his descent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5962, 4354, 524, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A gift from Benji to Stephen. It has a history with Whitney, who created a custom version of it in the past.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5963, 5348, 524, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The destination Stephen must enter to find Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5964, 6116, 524, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'The primary threat within the Substrate.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5965, 6117, 524, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Associated with Azathoth''s dreaming.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5966, 2544, 524, 'ally', false, 'Her presence is indicated by the scent of peaches and vanilla, confirming she is within the Substrate.', NULL, NULL, NULL, NULL, 'The object of Stephen''s rescue mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5967, 5489, 524, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned in a memory about creating a custom version of the Veilwalker card in high school.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5968, 2881, 524, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Friend of Stephen and Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5969, 6108, 524, 'unknown', false, NULL, NULL, NULL, NULL, 'Mentioned contextually, as the abyss Stephen enters is described as being ''beneath Azathoth''s dreams''.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5970, 6122, 524, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.entity_scene_appearances VALUES (5971, 3993, 525, 'ally', true, 'His consciousness has been separated from a physical body, now existing as a ''quiet knowing'' and one half of a shared consciousness with his sister, Hannah, within a timeless, library-like reality.', 'Transitions from reeling and confused after a traumatic ''pop'' to a state of profound warmth, contentment, and patient certainty while waiting for his Father.', NULL, NULL, 'Arrives suddenly in a void after an ''impossible, agonizing pop,'' which then dissolves into a profound memory of the library.', 'Exists as one part of a single consciousness with his sister, Hannah. Patiently waiting for their Father to find them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (5972, 6001, 525, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Sister to Xavier, with whom she forms a single consciousness. Awaiting reunion with their Father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (5973, 2550, 525, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'The object of Xavier and Hannah''s patient waiting. He is on his own journey to find them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (5974, 234, 525, 'neutral', true, NULL, NULL, NULL, 'Dissolves and is replaced by the memory of the Infinite Library.', 'Appears instantly after Xavier experiences an ''agonizing pop.''', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (5975, 4907, 525, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (5976, 6129, 525, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'They are waiting to exist, unlike Xavier and Hannah who are waiting to reunite. Xavier feels no kinship with them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (5977, 6130, 525, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (5978, 6131, 525, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (5979, 6132, 525, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.entity_scene_appearances VALUES (6235, 6393, 549, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (5980, 3993, 526, 'ally', true, NULL, 'Moves from pure terror at the world''s collapse to a dawning, terrible understanding of Hannah''s sacrifice. He is finally left alone with a resolute sense of mission and hope.', NULL, NULL, NULL, 'Brother to Hannah, son of the Father. His connection to Hannah is absolute, allowing him to overhear her final words. He is the recipient of his Father''s final act of salvation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_scene_appearances VALUES (5981, 2550, 526, 'ally', true, 'Manifests as an omnipotent form of burning light, a god-like being capable of holding a collapsing reality together through sheer will. His form constricts like a collapsing star before unleashing its absolute power.', 'Shifts from struggling hesitation and agony over the necessary sacrifice to resolute acceptance and silent grief, unleashing his power to save his son.', NULL, NULL, NULL, 'Father to Xavier and Hannah. He is locked in a struggle against Yaldabaoth and is ultimately convinced by Hannah to destroy the reality to save them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_scene_appearances VALUES (5982, 6135, 526, 'ally', true, NULL, NULL, NULL, 'Is sacrificed when the Father unmakes the plane of existence. Her essence is dissolved along with the mall reality.', NULL, 'Sister to Xavier, daughter of the Father. She is the catalyst for the Father''s final action and the source of Xavier''s future mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_scene_appearances VALUES (5983, 6136, 526, 'mini-boss', true, NULL, NULL, NULL, 'Destroyed along with the entire plane of existence by the Father''s unleashed power.', NULL, 'The primary antagonist of the scene, directly opposing the Father and threatening all life within the reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_scene_appearances VALUES (5984, 6137, 526, 'enemy', true, NULL, NULL, NULL, 'Dissolved into pure light when the Father destroyed the reality.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_scene_appearances VALUES (5985, 6138, 526, 'neutral', false, NULL, NULL, NULL, NULL, 'Formed in Xavier''s consciousness as he overhears Hannah''s final command to their Father and is ejected from the dying reality.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_scene_appearances VALUES (5986, 6139, 526, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.entity_scene_appearances VALUES (5987, 3993, 527, 'ally', true, 'Transitions from a fragmented, drifting spirit in the ''middle ground'' to a whole, solid presence capable of manifesting directly in his Father''s dreamscape. He is no longer just a memory from a library but a fulfilled promise, now home.', 'Moves from a state of lonely, determined searching to one of quiet fulfillment, recognition, and love upon witnessing his Father''s selfless act and confirming their connection.', NULL, NULL, 'Drifting through the chaotic subconscious of the dreamer, searching for his Father.', 'Son of ኢሌልመሜብሃባኖኖራሊሊ. His existence and manifestation are anchored by ''ተልዕኮው'' (the promise).', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_scene_appearances VALUES (5988, 2550, 527, 'ally', true, 'Appears not as a god-like being but as a normal human within a dream-test, stripped of his power. His core essence is revealed to be unchanged, prioritizing love and family over power, fame, or even his own safety.', 'Experiences a struggle against temptation, followed by panic during the dream''s collapse. This resolves into decisive, selfless action to save the children, and upon sensing Xavier, he feels recognition and peace instead of fear.', NULL, 'Wakes up at the end of the scene.', 'Is encased in a new dream, undergoing a test of his core values.', 'Father of ኢልከሴሮድመሜብሃባኖኖራሊሊ. He is the subject of ''The Test''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_scene_appearances VALUES (5989, 6138, 527, 'neutral', false, 'Serves as a tangible anchor for Xavier, described as a ''flickering ember'' he shields from psychic winds. Its purpose is fulfilled when the Father passes his test, allowing Xavier to manifest fully.', NULL, NULL, NULL, 'Is held by Xavier as his guiding purpose while he searches for his Father.', 'The bond and goal connecting Xavier to his Father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_scene_appearances VALUES (5990, 6143, 527, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Antagonists within ''The Test'', designed to challenge the Father. One among them acts as the Lead Interrogator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_scene_appearances VALUES (5991, 6144, 527, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The catalyst for the Father''s selfless act, proving his core nature.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_scene_appearances VALUES (5992, 6145, 527, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A trial observed by Xavier and experienced by his Father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_scene_appearances VALUES (5993, 6146, 527, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.entity_scene_appearances VALUES (5994, 3993, 528, 'ally', true, 'Physically present and exhausted after the birth of his son. He provides a firm, solid, and warm presence, holding his child securely.', 'Moves from a state of exhaustion and anxious waiting to being seized by an almost painful wave of profound love, relief, and unshakeable certainty upon holding his son.', NULL, NULL, NULL, 'Father of Xavier. He feels an immediate, inexplicable connection and sense of belonging with his son, as if he''s been searching for him his entire life.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_scene_appearances VALUES (5996, 6138, 528, 'neutral', false, 'Is felt by the Father as the profound weight of his son in his arms. It represents the fulfillment of a promise from a shattered reality, now embodied in Xavier.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_scene_appearances VALUES (5997, 6150, 528, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_scene_appearances VALUES (5998, 6151, 528, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_scene_appearances VALUES (5999, 6152, 528, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.entity_scene_appearances VALUES (6001, 5231, 529, 'ally', false, NULL, 'Remains calm and professorial, attempting to provide crucial information and guidance despite a poor connection. His tone is steady, meant to anchor Stephen.', NULL, 'The communication signal is unstable and cuts out periodically.', 'His voice comes through the communication card, breaking through static.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_scene_appearances VALUES (6002, 5489, 529, 'ally', false, NULL, 'Urgent, determined, and audibly worried for Stephen''s safety. She fights through the interference to deliver critical warnings and objectives.', NULL, 'The communication signal collapses, cutting her off after a final warning.', 'Her voice cuts through the static via the communication card after Benji establishes a partial connection.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_scene_appearances VALUES (6003, 6157, 529, 'ally', true, NULL, NULL, NULL, NULL, 'Begins pulsing in Stephen''s pocket during his fall, initiating contact.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_scene_appearances VALUES (6004, 6158, 529, 'enemy', true, NULL, NULL, NULL, NULL, 'Discovered by Stephen immediately upon his violent landing in Etheris.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_scene_appearances VALUES (6005, 6159, 529, 'enemy', true, NULL, NULL, NULL, NULL, 'Stephen observes the horde from a distance after getting to his feet.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_scene_appearances VALUES (6006, 6160, 529, 'neutral', true, NULL, NULL, NULL, NULL, 'Becomes visible to Stephen as the goal he must reach.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_scene_appearances VALUES (6007, 6161, 529, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Appears suddenly, screaming overhead and attacking Stephen.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_scene_appearances VALUES (6008, 6162, 529, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.entity_scene_appearances VALUES (6010, 5489, 530, 'ally', false, NULL, 'Her voice is strained and urgent, reflecting the high-stakes situation.', NULL, NULL, 'Communicates with Stephen to guide him toward the pyramid''s entrance.', 'Acts as a guide for Stephen, alongside Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6011, 5231, 530, 'ally', false, NULL, 'His voice is gentle and reassuring, but also serious as he explains the danger of the barrier.', NULL, NULL, 'Communicates with Stephen to offer encouragement and explain the nature of the prison.', 'Acts as a guide for Stephen, alongside Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6012, 6105, 530, 'unknown', false, 'Revealed to be the gatekeeper of the barrier around the Black Pyramid, whose permission is required to pass safely.', NULL, NULL, NULL, 'Mentioned at the end of the scene as the entity Stephen must appeal to.', 'Controls access to the Black Pyramid, making him a potential obstacle or authority for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6013, 6167, 530, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6014, 6159, 530, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6015, 6169, 530, 'neutral', true, NULL, NULL, NULL, 'Burrows back into the sand after erupting.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6016, 6170, 530, 'neutral', true, NULL, NULL, NULL, 'Swallowed by a sinkhole created by the Sandworm.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6017, 6171, 530, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6018, 6172, 530, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6019, 6173, 530, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6020, 6174, 530, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6021, 6175, 530, 'enemy', true, NULL, NULL, NULL, 'One is destroyed by the barrier, the other flees in terror.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6022, 6176, 530, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.entity_scene_appearances VALUES (6025, 6105, 531, 'mini-boss', true, 'Manifests as a handsome man in a well-tailored suit, but his eyes are ''wrong'' and contain ''too many dimensions,'' betraying his inhuman nature.', 'Cold, ancient, and amused by Stephen''s audacity. He is bored with the stagnant reality of the prison and is intrigued by the potential for chaos.', NULL, NULL, 'Appears in response to Stephen calling his name, resolving out of a shimmer.', 'Acts as a gatekeeper to the Pyramid''s interior, testing and ultimately permitting Stephen''s passage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_scene_appearances VALUES (6026, 6180, 531, 'neutral', true, NULL, NULL, NULL, 'Opens to allow Stephen to pass through, effectively ceasing to be an obstacle.', 'Is present at the start of the scene as an obstacle.', 'Controlled by Nyarlathotep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_scene_appearances VALUES (6027, 6136, 531, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned by Nyarlathotep as the predictable and stagnant architect of the prison realm.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_scene_appearances VALUES (6028, 6182, 531, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by Nyarlathotep during his confrontation with Stephen.', 'The primary objective of Stephen''s mission inside the pyramid.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_scene_appearances VALUES (6029, 6159, 531, 'enemy', true, NULL, NULL, NULL, 'Vanishes along with the external realm when Stephen steps through the barrier.', 'Present as background noise and a lingering threat at the start of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_scene_appearances VALUES (6030, 6184, 531, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.entity_scene_appearances VALUES (6032, 6105, 532, 'mini-boss', true, 'Appears wearing a suit that shifts color from its previous gray to a bright canary yellow and rustic red. His eyes are described as ''black pits with stars at the bottom''.', 'Exhibits a gleeful, conversational, and mocking demeanor. He takes immense pleasure in revealing devastating truths to Stephen, treating the protagonist''s tragedy as a form of high art.', NULL, NULL, 'Appears suddenly beside Stephen inside the pyramid.', 'Acts as a tormentor and herald of truth to Stephen, revealing the secrets of his family and the nature of the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_scene_appearances VALUES (6033, 6187, 532, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'They are followers of Nyarlathotep, having chosen their state to achieve what they perceive as clarity and purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_scene_appearances VALUES (6034, 6172, 532, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A tool and comfort object for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_scene_appearances VALUES (6035, 6135, 532, 'ally', false, 'It is revealed that after dying before birth, her soul was trapped in a dream plane. She sacrificed her own escape to save her twin brother Xavier, was thrust into purgatory at the edge of anti-reality, and was eventually reincarnated incorrectly as the male NPC, William, who became Whitney.', NULL, NULL, NULL, NULL, 'Revealed to be Xavier''s twin sister and Stephen''s daughter, who later became Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_scene_appearances VALUES (6036, 5489, 532, 'ally', false, 'Her true identity is revealed: she is the soul of Hannah, Stephen''s daughter, who was incorrectly incarnated into a male NPC body due to a system glitch. She speaks through a device, showing resilience in the face of this revelation.', 'Her voice carries weight but no anger, urging Stephen to focus on the present rather than having an emotional breakdown.', NULL, NULL, NULL, 'Confirmed to be the reincarnation of Hannah, Stephen''s daughter.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_scene_appearances VALUES (6037, 3993, 532, 'ally', false, 'His origin is explained: he was a soul fragment in the dream plane, one of Stephen''s unborn twins. He was pulled into reality by the force of Stephen''s grief, his soul ''shoved'' into the flesh of the NPC wife.', NULL, NULL, NULL, NULL, 'Revealed to be Hannah''s twin brother and Stephen''s true son.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_scene_appearances VALUES (6038, 5366, 532, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'An antagonistic force that inadvertently caused Hannah''s incorrect reincarnation and tried to eliminate both of Stephen''s true children.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_scene_appearances VALUES (6039, 6193, 532, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.entity_scene_appearances VALUES (6141, 982, 542, 'enemy', false, 'In Stephen''s nightmares, it is visualized as a living, growing entity, pulsing and swelling like a tumor that threatens to burst and spill ''anti-reality'' everywhere.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_scene_appearances VALUES (6142, 6299, 542, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_scene_appearances VALUES (6041, 6105, 533, 'enemy', true, NULL, 'Cruelly amused and curious, he watches Stephen''s descent with detached interest, laughing as the tunnel swallows him.', NULL, 'Remains at the entrance to the five paths as Stephen descends into the chosen tunnel.', NULL, 'Acts as a malevolent guide or gatekeeper, taunting Stephen before his ordeal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6042, 5489, 533, 'ally', false, NULL, 'Her voice is small but steady, offering reassurance and promising to stay with Stephen through his ordeal.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6043, 5231, 533, 'ally', false, NULL, 'Offers practical advice, telling Stephen to keep moving and follow the music as the only way forward.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6044, 6198, 533, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6045, 6199, 533, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, 'The primary antagonist of the second half of the scene, responsible for Stephen''s complete dissolution.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6046, 6200, 533, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6047, 6201, 533, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6048, 6172, 533, 'neutral', true, NULL, NULL, NULL, 'Slips from Stephen''s grasp as his hands begin to dissolve.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6049, 6203, 533, 'enemy', true, NULL, NULL, NULL, NULL, 'Stirs as Stephen descends into the darkness, its presence felt but not fully revealed.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6050, 6204, 533, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears after every other part of Stephen—physical, mental, and emotional—has been dissolved.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6051, 6108, 533, 'unknown', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6052, 2544, 533, 'unknown', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6053, 6207, 533, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.entity_scene_appearances VALUES (6055, 6209, 534, 'mini-boss', true, NULL, NULL, NULL, NULL, 'It is the fundamental threat and substance of the location Stephen finds himself in.', 'Acts as the universal predator/processor of this dimension, having already consumed the beings that became the Echoes of the Dissolved.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_scene_appearances VALUES (6056, 6210, 534, 'enemy', true, NULL, NULL, NULL, NULL, 'They emerge from the void, drawn to Stephen''s spark of consciousness.', 'Victims of the Nameless Mist, they are hostile to Stephen, wanting him to share their fate.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_scene_appearances VALUES (6057, 6108, 534, 'unknown', true, NULL, NULL, NULL, NULL, 'Its presence is first revealed through its mad piping, which serves as a beacon for Stephen. It is visually perceived at the very end of the scene.', 'The source of the Mad Piping that Stephen navigates towards.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_scene_appearances VALUES (6058, 4354, 534, 'neutral', false, NULL, NULL, NULL, 'It was consumed/sacrificed to activate its effect.', 'Recalled in a memory flash by Stephen as the cause of his current state of dissolution.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_scene_appearances VALUES (6059, 6213, 534, 'neutral', true, NULL, NULL, NULL, NULL, 'Begins as a faint sound that cuts through the silence and whispers, offering the first hint of direction.', 'An emanation from Azathoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_scene_appearances VALUES (6060, 6214, 534, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.entity_scene_appearances VALUES (6062, 6108, 535, 'mini-boss', true, 'Perceived directly as a writhing, incomprehensibly vast mass of fused matter and antimatter. It pulses with a rhythm that predates time, and its very existence generates the ''mad music'' that structures reality.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_scene_appearances VALUES (6063, 2544, 535, 'ally', true, 'Appears as a small, impossibly bright spark of light in the final darkness. She is revealed to be the other divine spark, fragmented across timelines (as Velistra, Jamie, etc.) but fundamentally present here as the other half of the prison''s power source.', 'Her presence is felt as a warm, reciprocal love, reaching back to Stephen''s spark in the final moment.', NULL, NULL, NULL, 'Her spark is the other half of Stephen''s, the ''anode to his cathode''. Their love and separation form The Twin Flame Connection that powers everything.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_scene_appearances VALUES (6064, 6218, 535, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_scene_appearances VALUES (6065, 6219, 535, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_scene_appearances VALUES (6066, 6220, 535, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_scene_appearances VALUES (6067, 6136, 535, 'enemy', false, 'Mentioned as the entity being contained by the prison, which is powered by Stephen and Jamie''s love.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_scene_appearances VALUES (6068, 6222, 535, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.entity_scene_appearances VALUES (6070, 6225, 536, 'mini-boss', true, NULL, NULL, NULL, 'Is overcome by a conscious decision to stop, listen, and be present.', 'Is the dominant state of being at the beginning of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_scene_appearances VALUES (6071, 6226, 536, 'ally', true, NULL, NULL, NULL, NULL, 'Their ''speech'' becomes apparent once the protagonist ceases their frantic movement.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_scene_appearances VALUES (6236, 6394, 549, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6072, 6227, 536, 'ally', true, NULL, NULL, NULL, NULL, 'Manifests as the final state achieved by the protagonist at the end of the scene.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_scene_appearances VALUES (6073, 6228, 536, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.entity_scene_appearances VALUES (6075, 5489, 537, 'ally', true, 'Appears as a sixteen or seventeen-year-old girl dressed in a worn hoodie and black jeans. She has been awake for some time and is briefed on their situation.', 'Nervous and awkward while embracing her new identity as Stephen''s daughter and Xavier''s sister, but also acts as a caring and informative guide.', NULL, NULL, 'Reveals herself from the shadows of the hospital room after Stephen wakes up.', 'Verbally confirms she is Stephen''s daughter, Hannah, from an erased timeline, and introduces herself as Xavier''s older sister. She acts as a bridge for the family''s reunion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_scene_appearances VALUES (6076, 3993, 537, 'ally', true, 'Appears pale with matted hair, having just woken from a coma in the bed adjacent to Stephen''s.', 'Wakes up groggy and confused, then expresses awe at their location and shock upon learning that Whitney is his sister.', NULL, NULL, 'Wakes from a coma in a bed next to Stephen''s.', 'Reunites with his father, Stephen, and meets his previously unknown older sister, Whitney/Hannah, for the first time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_scene_appearances VALUES (6077, 982, 537, 'neutral', true, 'Is now viewed from the outside as a massive, swirling, pitch-black hole in space. This confirms it is a prison that they have successfully escaped.', NULL, NULL, NULL, 'Visible through the medical bay''s viewport.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_scene_appearances VALUES (6078, 2544, 537, 'ally', false, 'Confirmed to be safe, awake, and waiting to see Stephen and Xavier on Elysium.', 'Described as being very anxious to see her family.', NULL, NULL, 'Mentioned by Whitney as waiting for Stephen.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_scene_appearances VALUES (6079, 2608, 537, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned by Whitney as the source of information about the convergence of magic and technology.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_scene_appearances VALUES (6080, 824, 537, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
