INSERT INTO public.entity_scene_appearances VALUES (6082, 6238, 537, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_scene_appearances VALUES (6083, 6239, 537, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.entity_scene_appearances VALUES (6085, 3993, 538, 'ally', true, NULL, 'Still deeply affected by the terror of being alone in a dead, empty reality after the tavern incident. He is quiet and subdued, but safe.', NULL, NULL, NULL, 'Reunited with his father, Stephen. Was rescued from the void by Chernobog.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6086, 5489, 538, 'ally', true, NULL, 'Acts as a comforting and grounding presence, expressing concern and relief for her family''s safety.', NULL, NULL, 'Is present from the start of the scene, walking beside Stephen''s wheelchair.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6087, 2544, 538, 'ally', true, 'No longer appears as a sixteen-year-old or a demonic entity, but as her true, divine self. She is described as solid, real, elegant, and perfect.', 'Overcome with emotion in a sob held for an eternity upon reuniting with Stephen, which quickly shifts to a playful, confident, and loving demeanor.', NULL, NULL, NULL, 'Reunites with Stephen, completing their ''circuit''. She is now part of the rescued group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6088, 5652, 538, 'ally', true, NULL, NULL, NULL, NULL, 'First mentioned by Xavier as his rescuer, then appears physically as a member of the council in the conference room.', 'Rescuer of Xavier and an ally to Stephen. Member of the Divine Council.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6089, 5651, 538, 'ally', true, NULL, NULL, NULL, NULL, 'Revealed as a member of the council when Stephen enters the conference room.', 'Member of the Divine Council.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6090, 5650, 538, 'ally', true, NULL, NULL, NULL, NULL, 'Revealed as a member of the council when Stephen enters the conference room.', 'Member of the Divine Council.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6091, 6247, 538, 'ally', true, NULL, NULL, NULL, NULL, 'They are waiting in the conference room to brief Stephen and Jamie.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
