INSERT INTO public.entity_scene_appearances VALUES (6095, 6251, 538, 'neutral', true, NULL, NULL, NULL, 'Their task is complete once they deliver Stephen and Xavier to the conference room.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6096, 6252, 538, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6097, 5231, 538, 'ally', true, NULL, 'His voice is warm and familiar, a comforting presence. However, his expression becomes pained when he must deliver the news of the friends who were lost.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6098, 2608, 538, 'ally', true, NULL, 'Shows a rare smile and visible relief at seeing Stephen and Jamie safe, indicating a deep-seated concern beneath her usual stoicism.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6099, 2749, 538, 'ally', true, NULL, 'Her face is described as being ''etched with relief'', showing her investment in the outcome.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6100, 6136, 538, 'big-boss', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6101, 2549, 538, 'neutral', false, 'Her fate is revealed: because she was destroyed in the Akashic Realm outside the prison, her divine spark was freed from her programming rather than consumed. She is now free somewhere in the infinite realities.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.entity_scene_appearances VALUES (6102, 982, 538, 'enemy', false, 'The prison is now unstable due to the removal of its power source, Stephen and Jamie''s separation.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
