INSERT INTO public.entity_scene_appearances VALUES (6146, 824, 542, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_scene_appearances VALUES (6105, 5489, 539, 'ally', true, 'She reclaims her original name, Hannah, shedding the identities of William, Whitney, and Jennifer. This marks a significant step in her journey of self-acceptance and freedom, choosing a name that feels ''birthed from love'' rather than one used for hiding or survival.', 'Moves from bewilderment about her new family to a profound sense of rightness and joy upon reclaiming her name. She feels her identity is finally her own.', NULL, NULL, NULL, 'Daughter of Stephen and Jamie, sister to Xavier. She is rediscovering her place in the family and her own identity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6106, 3993, 539, 'ally', true, NULL, 'Transitions from typical teenage boredom and frustration to genuine, unbridled hope upon discovering he can reconnect with his online life and games. This is the first time he has shown such a positive spark since his rescue.', NULL, NULL, NULL, 'Son of Stephen and Jamie, brother to Hannah. He is trying to find a sense of normalcy in their new, strange reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6107, 2544, 539, 'ally', true, NULL, 'Acts as a comforting, grounding, and supportive presence for her new family. She affirms Hannah''s journey and shares in Stephen''s sense of peace.', NULL, NULL, NULL, 'Mother to Hannah and Xavier, partner to Stephen. She is the emotional anchor of the family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6108, 6136, 539, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned as the entity who mercifully erased the ancient memories of the consumed souls, leaving their recent lives intact but the eternities before as a blank.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6109, 982, 539, 'neutral', false, 'Visible from the apartment''s viewport as an ''angry black hole,'' serving as a constant but distant reminder of the prison the family escaped.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6110, 6266, 539, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The central group of the scene, whose formation and affirmation is the primary theme.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6111, 6267, 539, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The antithesis of ''Hannah''; the identity she had to escape to become herself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6112, 6268, 539, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A stepping stone in Hannah''s journey from ''Whitney'' to ''Hannah'', and an unconscious link to her mother, Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6113, 6269, 539, 'ally', true, NULL, NULL, NULL, NULL, 'Appears on a holographic video call after Hannah finds him in a directory of rescued souls.', 'A fellow rescued soul who provides a crucial link to Xavier''s past and a sense of normalcy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6114, 465, 539, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The primary object of Xavier''s desire, representing a connection to normalcy and his past self.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6115, 6271, 539, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6116, 6272, 539, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.entity_scene_appearances VALUES (6118, 2544, 540, 'ally', true, NULL, 'Supportive, pragmatic, and comforting. She tries to ground Stephen and prevent him from spiraling into despair over the numbers.', NULL, NULL, NULL, 'Offers physical and emotional support to Stephen, holding his hand and gently challenging his pessimistic outlook.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_scene_appearances VALUES (6119, 5231, 540, 'ally', true, NULL, 'Serious and urgent, with a flickering expression that hints at the gravity of his news.', NULL, NULL, 'Arrives through a hissing door to deliver a critical message to Stephen and Jamie.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_scene_appearances VALUES (6120, 2608, 540, 'ally', true, 'Her presence is described as filling the room like gravity, indicating her authority and importance.', NULL, NULL, NULL, 'Accompanies Benji, adding weight and authority to the urgent news being delivered.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_scene_appearances VALUES (6121, 6136, 540, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
