INSERT INTO public.entity_scene_appearances VALUES (6124, 6281, 540, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_scene_appearances VALUES (6125, 6282, 540, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.entity_scene_appearances VALUES (6127, 157, 541, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Former leader of the Red Hats, a Luddite army that opposed Stephen in a past reality. His soul was altered by Yaldabaoth after his death and subsequent reset.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6128, 6285, 541, 'enemy', true, NULL, NULL, NULL, NULL, 'Triggered when Stephen sees Todd in the briefing room.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6129, 510, 541, 'enemy', false, NULL, NULL, NULL, NULL, 'Appears within Stephen''s traumatic flashback.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6130, 6287, 541, 'neutral', false, NULL, NULL, NULL, NULL, 'Revealed by Todd during his mad ramblings.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6132, 2749, 541, 'ally', true, 'Her tattooed symbols glow faintly in the dim light of the briefing room.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6133, 2544, 541, 'ally', true, NULL, 'Becomes tense and concerned upon hearing Todd''s mad whispers.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6134, 5231, 541, 'ally', true, NULL, 'Remains analytical, noting that there is a method to Todd''s madness.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6135, 6136, 541, 'enemy', false, NULL, NULL, NULL, NULL, 'Mentioned as the being worshipped by the Red Hats and the one who altered Todd''s soul after death.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6136, 2608, 541, 'ally', true, NULL, 'Shows keen interest in Todd''s revelation, leaning forward to press him for more information about the seed.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6137, 6294, 541, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.entity_scene_appearances VALUES (6139, 2544, 542, 'ally', true, NULL, 'Supportive, calm, and perceptive. She actively seeks to comfort Stephen and pull him out of his negative thought spiral.', NULL, NULL, 'Finds Stephen on the observation deck to check on him.', 'Acts as an emotional anchor for Stephen, offering physical and verbal comfort.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_scene_appearances VALUES (6140, 6136, 542, 'enemy', false, 'Mentioned as actively succeeding with its ''breeding programs'', increasing its threat while the heroes'' efforts stall.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.entity_scene_appearances VALUES (6238, 6396, 549, 'unknown', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6149, 2544, 543, 'ally', true, NULL, 'Moves from curiosity to sharp-eyed concern, then to horror at the proposed sacrifice, and finally to fear for Stephen''s safety when he suggests returning to Etheris.', NULL, NULL, NULL, 'Partner to Stephen; voices pragmatic and emotional concerns for the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6150, 5231, 543, 'ally', true, NULL, 'Begins with an unreadable expression, then shifts to a careful, analytical tone as he presents the data and its grim implications.', NULL, NULL, 'Enters the apartment to announce the discovery of the cosmic seed.', 'Key technical expert for the team.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6151, 2608, 543, 'ally', true, 'Her tattoos are noted to shiver, as if reacting to the unpleasant topic of Yaldabaoth''s growth.', 'Resolute and weary, delivering the catastrophic requirements for the new prison with a tired gravity. She seems burdened by the hard truths she must convey.', NULL, NULL, NULL, 'Acts as a senior strategist, outlining the core conflict and the difficult choices they face.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6152, 2749, 543, 'ally', true, NULL, 'Remains steady and analytical, providing technical confirmation of the anomaly''s properties and later grasping the strategic implication of Stephen''s plan.', NULL, NULL, NULL, 'Serves as a voice of scientific authority.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6153, 3993, 543, 'ally', true, NULL, 'His initial hopefulness about the new prison is quickly crushed by the logistical and ethical nightmare of evacuating every soul, leaving him quiet and disheartened.', NULL, NULL, NULL, 'Represents the hopeful, less jaded perspective within the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6154, 6135, 543, 'ally', true, NULL, 'Perceptive and direct, she cuts through the initial optimism to ask the crucial question about the ''catch''.', NULL, NULL, NULL, 'Acts as an insightful questioner.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6155, 6136, 543, 'enemy', false, 'Re-contextualized from a singular dark god to a parasitic ''infection'' that has a separate, original host. This reframes it as a force that can potentially be separated and managed, rather than an unbeatable entity.', NULL, NULL, NULL, NULL, 'The primary antagonist, whose containment is the central goal of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6156, 6313, 543, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The potential core of the New Prison for Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6157, 6314, 543, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6158, 6315, 543, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The population that the team is trying to save, but who also represent the failure condition for the new plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6159, 2550, 543, 'unknown', false, 'Revealed to be the original host of the Yaldabaoth infection. He is described as a separate consciousness buried and chained within the dark god, grieving the destruction he is forced to cause.', 'Described as being in a state of perpetual grief and imprisonment.', NULL, NULL, NULL, 'The host of the Yaldabaoth parasite.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6161, 6318, 543, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6162, 6319, 543, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6160, 6317, 543, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.entity_scene_appearances VALUES (6165, 2544, 544, 'ally', true, NULL, 'Fiercely loyal and resolute. She refuses to be left behind and is unwavering in her decision to accompany Stephen, later adopting a tone of finality when speaking to Xavier and Hannah.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6166, 3993, 544, 'ally', true, NULL, 'Initially declarative and concerned, his emotions shift to anger and then to a feeling of betrayal and fear when his parents refuse to let him join their mission.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6167, 6135, 544, 'ally', true, NULL, 'Expresses fierce loyalty and anger at her father''s perceived hypocrisy. She challenges his decision with a fiery determination, her voice cracking with emotion.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6168, 5231, 544, 'ally', true, NULL, 'Appears calm and ready to contribute his expertise to the mission, accepting his role without argument.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6169, 2749, 544, 'ally', true, NULL, 'Professional and focused, she outlines the necessity of preparation and provides a timeline, her demeanor suggesting a deep understanding of the dangers involved.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6170, 2608, 544, 'ally', true, NULL, 'Observant and silent, communicating non-verbally with Lady Osilari, suggesting a position of authority or shared understanding.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6171, 6136, 544, 'enemy', false, 'Described as a mindless, consuming entity, like a ''giant ooze that doesn’t know what it’s chewing''. Its essence has previously shredded and rebuilt the consciousnesses of Xavier and Hannah.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6172, 982, 544, 'neutral', false, 'Referred to as a place where divine essence matters but is dampened. Its anti-reality nature is an active threat that will try to corrupt intruders.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6173, 2550, 544, 'neutral', false, 'The target of the rescue mission. Stephen believes that despite his corruption within Yaldabaoth, he still remembers how to love and can be reached.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6174, 5489, 544, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by Stephen as a comparison to Hannah''s fiery refusal to back down.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6175, 6332, 544, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Stephen and Jamie are the core, with Benji and Osilari as essential specialists.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6176, 1311, 544, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6177, 514, 544, 'ally', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6239, 6397, 549, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6178, 6138, 544, 'neutral', false, 'The mission is now defined: a four-person team will enter Etheris to perform an ''exorcism on a god'' to save Sam, with a two-week preparation period.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6179, 6336, 544, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.entity_scene_appearances VALUES (6180, 2749, 545, 'ally', true, NULL, 'Focused and diligent, performing the crucial task of applying protective wards to the team before their mission.', NULL, NULL, NULL, 'Acts as a magical protector for the team, alongside Benji, Stephen, and Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6181, 5231, 545, 'ally', true, NULL, 'Studious and determined, using his unique knowledge as a former auditor to chart a path through the dangerous realm of Etheris.', NULL, NULL, NULL, 'Serves as the mission''s navigator, working with Osilari, Stephen, and Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6594, 6759, 577, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6183, 2544, 545, 'ally', true, 'Her skin is also covered in the newly applied protective wards.', 'Shares Stephen''s fear but displays fierce resolve, voicing the mission''s central moral conflict and offering sharp encouragement before they depart.', 'Now bears protective wards painted on her skin.', 'Steps through the portal with Stephen.', NULL, 'Stephen''s partner, providing emotional support and standing with him as they face the mission together.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6184, 2550, 545, 'unknown', false, NULL, NULL, NULL, NULL, NULL, 'The target of the mission. His own desires (to be saved or to die) are unknown, creating the central moral dilemma for Stephen and Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6185, 3993, 545, 'ally', true, NULL, 'Visibly emotional and worried for his father''s safety, managing only a few terse words but conveying deep fear and love.', NULL, 'Remains behind in Elysium as Stephen departs.', 'Appears in the portal chamber to see his father off.', 'Stephen''s son, stands with his sister Hannah to say goodbye.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6186, 6135, 545, 'ally', true, NULL, 'Fiercely loving and worried, expressing her feelings through a quick, strong hug.', NULL, 'Remains behind in Elysium as Stephen departs.', 'Appears in the portal chamber to see her father off.', 'Stephen''s daughter, stands with her brother Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6187, 6344, 545, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Applied by Lady Osilari to the mission team.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6188, 6345, 545, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Used by Benji to plan the team''s path.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6189, 6346, 545, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The entry point for the mission team into Etheris.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6190, 6347, 545, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Serve as the motivation for Stephen''s sacrifice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.entity_scene_appearances VALUES (6192, 2544, 546, 'ally', true, NULL, 'Remains outwardly calm but is inwardly tense, a feeling she communicates to Stephen by holding his hand. She is pragmatic and courageous, arguing for the necessity of summoning Nyarlathotep and offering to protect Benji herself.', NULL, NULL, NULL, 'Holds Stephen''s hand for support. Acts as a brave protector for Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6193, 5231, 546, 'ally', true, 'Scars from a previous attack by Nyarlathotep are still visible on his chest, even within the conceptual space of the Akashic Realm.', 'Initially focused and concentrated while investigating the missing portal. He becomes resigned and peaceful when accepting the danger of summoning Nyarlathotep, facing the prospect of death with a calm demeanor.', NULL, NULL, NULL, 'The subject of Stephen''s protection. The one who must be shielded from Nyarlathotep. He is the one to suggest the dangerous plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6194, 2749, 546, 'ally', true, NULL, 'Remains analytical and proactive. She diagnoses the problem with the Veil and immediately begins creating protective wards for Benji once the decision is made.', NULL, NULL, NULL, 'Acts as the team''s magical expert, diagnosing the problem and providing a magical solution (wards) to mitigate the risk.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6195, 5655, 546, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6196, 6353, 546, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6197, 6354, 546, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6198, 2610, 546, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6199, 6108, 546, 'enemy', false, NULL, 'His motivations have become terrifyingly unclear. Instead of wanting out of his prison, he has actively sealed the entrance, suggesting a change in his plans or awareness.', NULL, NULL, NULL, 'The unseen antagonist who has created the current obstacle by sealing the portal to Etheris.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6200, 6357, 546, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6201, 6105, 546, 'mini-boss', false, NULL, NULL, NULL, NULL, 'Summoned as a last resort to bypass the sealed portal into Etheris.', 'A dangerous and volatile entity who previously tried to erase Benji from existence. He is considered the only being with administrative access to Etheris, making him a necessary evil.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6202, 6359, 546, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6203, 6360, 546, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.entity_scene_appearances VALUES (6204, 5231, 547, 'ally', true, 'Violently torn apart by Nyarlathotep, with extra limbs and eyes erupting from his body, before being imperfectly reassembled by magical wards. He is left traumatized and covered in his own fluids.', 'Experiences extreme agony and terror during the attack, which shifts to a calm, sacrificial resignation when he offers his life to Nyarlathotep.', NULL, NULL, NULL, 'Protected fiercely by both Lady Osilari (via wards) and Lady Illkeserod (via intervention). He is the target of Nyarlathotep''s sadistic torment and transactional demands.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_scene_appearances VALUES (6205, 2749, 547, 'ally', true, NULL, 'Moves from screaming terror for Benji''s safety to focused, professional caution as she inspects the stability of the portal.', 'Her protective wards, previously placed on Benji, are actively used to save his life.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_scene_appearances VALUES (6232, 2544, 549, 'ally', true, NULL, 'Reacts with initial shock, then shifts into a highly trained, precise fighter using pure physical skill. Her focus is broken by panic when Stephen is attacked.', NULL, NULL, 'Enters the chamber with the group.', 'Fights the tentacles directly to protect Stephen and the others.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6206, 6105, 547, 'mini-boss', true, 'Manifests from pooled shadows into a shifting form that wears the shape of a man but moves like liquid chaos. At one point, his form becomes something that hurts to look at directly.', 'Cycles from sadistic amusement during his attack, to cold transactional negotiation, to profound boredom with Benji''s self-sacrifice, finally settling on a detached desire for entertainment.', NULL, 'Remains in the Akashic Realm after opening the portal, intending to watch the events unfold.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_scene_appearances VALUES (6208, 2608, 547, 'ally', true, NULL, NULL, NULL, 'Remains behind in the Akashic Realm as the group enters the portal.', 'Appears unnoticed in the Akashic Realm to intervene when Nyarlathotep attempts to claim Benji.', 'Acts as a possessive and powerful protector of Benji, willing to confront Nyarlathotep directly to prevent him from being taken.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_scene_appearances VALUES (6209, 2544, 547, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Identified by Nyarlathotep as Stephen''s ''twin soul'' and a ''power source''. She stands with Stephen as his anchor and partner.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_scene_appearances VALUES (6210, 6367, 547, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_scene_appearances VALUES (6211, 6354, 547, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_scene_appearances VALUES (6212, 6369, 547, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.entity_scene_appearances VALUES (6214, 2544, 548, 'ally', true, NULL, 'Expresses hatred and disgust for Etheris, her fear palpable. She questions Stephen''s plan but ultimately trusts him, her resolve firming as she faces consumption.', NULL, NULL, NULL, 'Clings to Stephen for support and comfort, a key part of the team''s emotional core.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6215, 5231, 548, 'ally', true, NULL, 'Maintains a cheerful, almost flippant demeanor in the face of cosmic horror, which serves as a coping mechanism. His cheerfulness becomes strained as the prison adapts and the plan unfolds.', NULL, NULL, NULL, 'Acts as the team''s navigator, guiding them through the shifting hellscape of Etheris.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6216, 2749, 548, 'ally', true, NULL, 'Remains focused and professional, though shows signs of strain and horror at the scale of Yaldabaoth''s cruelty. She is the calm, protective center of the group.', NULL, NULL, NULL, 'Serves as the team''s protector, using her symbols to create wards against the horrors of Etheris and the essence of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6217, 6136, 548, 'big-boss', true, 'Appears first as a figure on a throne of souls, then expands into a shifting mass of darkness and teeth, a void-like form whose jaws can swallow stars. His very essence constitutes the internal prison the team navigates.', 'His emotional state shifts from arrogant contempt to suspicion, then to a frenzied, ecstatic hunger upon tasting the power of the wards. He becomes a being of pure, overwhelming appetite and pleasure.', NULL, NULL, NULL, 'The god-jailer of Etheris, he is the primary antagonist who confronts, taunts, and ultimately consumes the team.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6218, 982, 548, 'enemy', true, 'Revealed to be an adaptive, sentient prison that actively resists intruders. It rewrites itself, creating corridors of crystallized screams, shifting realities, and looping rooms of torment to fragment the minds of those within.', NULL, NULL, NULL, NULL, 'The domain of Yaldabaoth, actively hostile to the team.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6219, 6376, 548, 'ally', true, NULL, NULL, NULL, NULL, 'Enters Etheris with a specific, high-risk plan to be consumed by Yaldabaoth.', 'A tightly-knit unit relying on each other''s skills for survival.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6220, 6359, 548, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'The team''s sole protection and the key to their plan''s success.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6221, 6378, 548, 'enemy', true, NULL, NULL, NULL, 'Left behind as the team flees deeper into Etheris.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6222, 6379, 548, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A symbol of Yaldabaoth''s ultimate cruelty and power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6223, 6380, 548, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The intended ''meals'' for Yaldabaoth, being made more potent through suffering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6224, 6381, 548, 'enemy', true, NULL, NULL, NULL, 'They are bypassed when Yaldabaoth consumes the team whole.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6225, 6382, 548, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'An environmental threat inside the god, driven by his appetite.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6226, 3993, 548, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Mentioned as being imprisoned at Yaldabaoth''s core; he is the ultimate goal of the team''s mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6227, 6384, 548, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.entity_scene_appearances VALUES (6229, 3993, 549, 'enemy', true, 'Found suspended in mid-air, convulsing, and held by thousands of invisible tentacles. His eyes are corrupted with black substance. After being freed, he moves with divine speed and then stands in a blank, swaying trance.', 'In a state of agony beyond pain, screaming constantly. This shifts to a violent, focused attack on Stephen, followed by a completely blank, trance-like state.', NULL, NULL, 'Is discovered at the center of the chamber when the group arrives.', 'Acts as a host for the Anti-reality Parasite. Is the objective of Stephen''s rescue attempt, but then attacks Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6230, 2749, 549, 'ally', true, NULL, 'Focused and commanding, immediately taking defensive action and directing the group''s efforts. She remains calm and observant even after Stephen is attacked.', NULL, NULL, 'Enters the chamber with the group.', 'Protects the group with her magic and directs their strategy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6231, 5231, 549, 'ally', true, NULL, 'Initially strained and shocked by Sam''s condition, he quickly becomes focused, using his abilities strategically to create distractions during the fight.', NULL, NULL, 'Enters the chamber with the group.', 'Aids the defense by distracting the tentacles, creating openings for others.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6233, 6391, 549, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6234, 6392, 549, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.entity_scene_appearances VALUES (6269, 6136, 552, 'mini-boss', true, 'Contained within invisible barriers and then engulfed by the Fractal Prison, its form is seen writhing and struggling against its confinement.', 'Experiences terror and desperate fury as it senses its impending, permanent imprisonment.', NULL, 'Permanently contained within the Cosmic Seed''s final form.', NULL, 'The target of the Cosmic Seed; its containment frees trillions of souls.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6241, 3993, 550, 'neutral', true, 'Appears as a gentle, welcoming shepherd, hollowed out by parasites he cannot see. His expression shifts from warm to hard and violent under the parasites'' influence, eventually clearing to one of terrible, complete understanding.', 'His state cycles from genuine warmth to corrupted paranoia and rage. He then collapses into agonized sobbing as the truth is revealed, culminating in a profound, guilt-ridden understanding of his actions.', NULL, NULL, NULL, 'He is the host for The Parasitic Flock, which he believes he is protecting. Stephen is attempting to free him from this delusion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6242, 6400, 550, 'enemy', true, NULL, NULL, NULL, 'Destroyed one by one by Stephen and Sam, dissolving back into the anti-reality they came from.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6244, 6402, 550, 'neutral', false, NULL, NULL, NULL, NULL, 'Begins to manifest as Stephen destroys the first parasite, and becomes fully realized when Sam destroys the last one himself.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6245, 2544, 550, 'ally', false, NULL, 'Her voice sounds strained, indicating she is in a desperate fight outside the pasture realm.', NULL, NULL, 'Her voice is heard warning Stephen and later questioning how long the process will take.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6246, 5231, 550, 'ally', false, NULL, NULL, NULL, NULL, 'His voice is heard raised in an ancient language, indicating he is engaged in a magical battle outside the pasture.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6247, 2749, 550, 'ally', false, NULL, 'Her power flares and her voice is calm and steady, suggesting she is a powerful and composed force in the battle outside.', NULL, NULL, 'Her power is felt flaring, and she responds calmly that the process will take as long as it needs to.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6248, 5522, 550, 'enemy', false, NULL, NULL, NULL, NULL, 'Appears in a brief, flickering memory experienced by Sam during his struggle.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6249, 6407, 550, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'The ultimate source of The Parasitic Flock and Sam''s corruption. Likely an aspect of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6243, 6401, 550, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.entity_scene_appearances VALUES (6252, 3993, 551, 'ally', true, 'Undergoes a horrific deconstruction, his divine body and essence are torn apart, leaving him a mutilated, dissolving mass of flesh before he fades into a single spark of light.', 'Shifts from terror and pleading to relief and acceptance. He expresses profound remorse for his actions before his essence dissolves, finding peace in his unmaking.', NULL, 'His body and consciousness dissolve completely after the parasite is fully extracted, leaving only his core spark behind.', 'Lying limp on top of Stephen after reality snaps back into focus.', 'The host of the parasite, Yaldabaoth. He is the patient and victim of the extraction ritual performed by Lady Illkeserod and Nyarlathotep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6253, 6136, 551, 'mini-boss', true, 'Is violently torn from its host, Sam. It coalesces into a writhing, desperate mass that fights to maintain its anchor in reality before being contained.', 'Exhibits primal rage and desperation, sensing its mortality and fighting violently to avoid extraction and containment.', NULL, 'Fully extracted from Sam and then contained by the Cosmic Seed, rendering it silent and impotent.', NULL, 'A cosmic parasite that has been using Sam as a host for eons. It is the target of the extraction ritual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6254, 2608, 551, 'ally', true, NULL, 'Her power is felt as one of the primary forces driving the ritual, converging with Nyarlathotep''s to force the separation.', NULL, NULL, 'Her presence is felt from outside the prison as she begins the ritual.', 'Works in tandem with Nyarlathotep to perform the extraction ritual on Sam and the parasite.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6255, 6105, 551, 'ally', true, NULL, 'His power is felt rising from the substrate, harmonizing with Lady Illkeserod''s to execute the ritual.', NULL, NULL, 'His presence is felt from deep within the substrate as the ritual begins.', 'Collaborates with Lady Illkeserod to perform the extraction ritual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6256, 2544, 551, 'ally', true, NULL, 'Overcome with horror and grief, she vomits and collapses, sobbing uncontrollably. At the end, she acts with gentle resolve, catching and protecting Sam''s final spark.', NULL, NULL, NULL, 'A horrified witness who finds comfort with Stephen. She becomes the keeper of Sam''s remaining essence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6257, 5231, 551, 'ally', true, NULL, 'Initially reacts with physical sickness to the horror, but then acts with focus and precision to deploy the Cosmic Seed and contain the parasite.', NULL, NULL, NULL, 'A witness who plays a crucial role in containing the extracted parasite.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6258, 2749, 551, 'ally', true, NULL, 'Distraught and weeping, she compares herself to a surgeon who knows the patient won''t survive but must continue. She tries to weave patterns to dull Sam''s pain, but they fail.', NULL, NULL, NULL, 'Maintains the ''surgical field'' for the ritual, forcing the separation despite her immense sorrow.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6259, 6417, 551, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6260, 6418, 551, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6262, 6420, 551, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6263, 6421, 551, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6264, 6422, 551, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.entity_scene_appearances VALUES (6266, 2544, 552, 'ally', true, NULL, 'Moves from concerned to desperate, participating in the violent push through the crowd to survive while protecting Sam''s Spark.', NULL, NULL, NULL, 'Protector of Sam''s Spark; works alongside Stephen to force a path through the crowd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6267, 5231, 552, 'ally', true, NULL, 'Remains focused and urgent, taking a lead role in the escape, but is left grim and shaken by the experience.', NULL, NULL, NULL, 'One of the key figures enabling the escape, both in activating the seed and fighting through the crowd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6482, 6645, 568, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_scene_appearances VALUES (6268, 2749, 552, 'ally', true, NULL, 'Authoritative and calm initially, she becomes focused on escape, using her symbols to clear a path through the desperate souls.', NULL, NULL, NULL, 'A key member of the escaping group, using her unique abilities to aid their passage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6348, 6509, 556, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The mechanism for enacting the Shepherd Initiative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_scene_appearances VALUES (6492, 6136, 569, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Mentioned as the power controlling the Vatican and the Illuminati.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (6270, 982, 552, 'neutral', true, 'The realm itself shatters in a shockwave, its nightmare dimensions collapsing and rejoining reality as a scarred but normalized space once the parasite is fully contained.', NULL, NULL, NULL, NULL, 'The location of the scene and the prison that is destroyed and reformed by the Cosmic Seed''s activation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6271, 2608, 552, 'ally', true, NULL, NULL, NULL, 'The portal closes, severing her connection to the group.', 'Appears on the other side of the portal, her hands helping to create the escape route to Elysium.', 'Works with Nyarlathotep to provide the group''s only means of escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6272, 6105, 552, 'ally', true, NULL, NULL, NULL, 'The portal closes, severing his connection to the group.', 'His power is felt surging from below, helping to form the bridge out of Etheris.', 'Works with Lady Illkeserod to create the portal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6273, 6313, 552, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6274, 6432, 552, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
