INSERT INTO public.entity_scene_appearances VALUES (6276, 6434, 552, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6277, 6435, 552, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6278, 6436, 552, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6279, 6437, 552, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6280, 6438, 552, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.entity_scene_appearances VALUES (6281, 3993, 553, 'ally', true, NULL, 'Somber and grieving, struggling to contain his emotions. He feels the weight of the moment, unable to speak but performs the final act of release for Sam''s spark. By the end, he finds resolve to continue his work.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6282, 2544, 553, 'ally', true, NULL, 'Supportive and grounding for the narrator, while also grieving. She transitions from quiet comfort to pragmatic leadership, reminding the group of their ongoing responsibilities.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6283, 5231, 553, 'ally', true, NULL, 'Quietly reverent and mournful, participating in the non-verbal rituals of farewell.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6284, 2608, 553, 'ally', true, NULL, 'Stands in solidarity with Benji, sharing in the somber, respectful atmosphere of the ceremony.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6285, 6135, 553, 'ally', true, NULL, 'Offers words of comfort and finality to the spark, her presence described as being ''like dawn after endless night''.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6286, 6105, 553, 'neutral', true, NULL, 'Observes the ceremony with an uncharacteristic display of respect, even participating in the final bow.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6287, 6108, 553, 'neutral', true, 'No longer chained or imprisoned, Azathoth is restored and free at the center of Etheris. Its characteristic piping now sounds like relief echoing across dimensions.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6288, 6136, 553, 'enemy', false, 'Mentioned as the corrupting force that hollowed out the original Sam and wore his body like a suit. Its lingering corruption remains a threat.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6289, 5651, 553, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6290, 5650, 553, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6291, 5652, 553, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6292, 6393, 553, 'neutral', true, NULL, NULL, NULL, 'Instead of reincarnating, the spark chooses to dissolve, its light spreading out to become part of the fabric of existence itself, achieving a final, ultimate peace.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6293, 4141, 553, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A distinct persona or fragment of the narrator, ኢልከሴሮድመሜብሃባኖኖራሊሊ, who acts and speaks independently in this scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6294, 6453, 553, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6295, 2536, 553, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6296, 6455, 553, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6297, 6456, 553, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6298, 6457, 553, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.entity_scene_appearances VALUES (6300, 2544, 554, 'ally', true, 'Volunteers for the Shepherd Initiative alongside her family. Her reawakened divine power is designated as ''Creativity and Death'', allowing her to see and guide the connections between souls.', 'Pragmatic and perceptive, she quickly grasps the potential of Hannah''s idea and shows fierce determination. Her resolve is certain and she provides strength to Stephen.', NULL, NULL, NULL, 'Wife of Stephen, mother of Xavier and Hannah. She is a key architect of the mission''s cultural approach.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6301, 3993, 554, 'ally', true, 'Volunteers for the mission, primarily motivated by the desire to find and protect a girl named Tiffany. His reawakened divine power is ''Mischief, Chaos, and Laughter'', allowing him to bend probability.', 'Initially quiet and observant, he becomes instantly decisive upon learning Tiffany is in the prison. He masks his deep concern and vulnerability with a veneer of casual bravado and sarcasm.', NULL, NULL, NULL, 'Son of Stephen and Jamie, brother of Hannah. His personal quest for Tiffany aligns with the family''s mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6302, 6135, 554, 'ally', true, 'Proposes the core concept of the Shepherd Initiative. Her reawakened divine power is ''Serenity and Joy'', making her the emotional anchor for the mission and family.', 'Confident and insightful, she demonstrates a growing mastery of her powers and a clear-headed approach to problem-solving. She is the catalyst for the entire plan.', NULL, NULL, NULL, 'Daughter of Stephen and Jamie, sister of Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6343, 5652, 556, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Will act as Jamie''s father via the Kenji Nakamura avatar.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_scene_appearances VALUES (6303, 5231, 554, 'ally', true, 'Participates in the council meeting and volunteers to inhabit an avatar, ''Benjamin Castellan'', to act as Stephen''s father inside the prison, providing support for the mission.', 'Shifts from being irritated with bureaucracy to enthusiastic about the new, proactive plan.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6304, 2608, 554, 'ally', true, 'Acts as a key planner for the Shepherd Initiative, presenting data and logistical details to the council. She also volunteers to inhabit the avatar of ''Illara Castellan'', Stephen''s mother.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6487, 20, 569, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The primary creative work of the author (ኢልከሴሮድመሜብሃባኖኖራሊሊ).', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (6305, 6105, 554, 'neutral', true, 'Manifests as a 1920s jazz musician. He acts as a cynical observer, finding the entire situation ''delectable'' and ''hilarious''. He votes against the initiative purely for the irony.', 'Cynically amused and detached, enjoying the chaos and cosmic irony of the plan.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6306, 5652, 554, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6307, 5650, 554, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6308, 6467, 554, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6309, 5651, 554, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6310, 6469, 554, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6311, 6470, 554, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6312, 6471, 554, 'enemy', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6313, 6472, 554, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6314, 6473, 554, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6315, 4590, 554, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6316, 2749, 554, 'ally', false, 'Mentioned as the entity who will inhabit the avatar of ''Waniya Nakamura'', Jamie''s mother, to provide support for the mission from within the prison.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6317, 6108, 554, 'neutral', false, 'Mentioned as the ''blind, deaf, idiot god'' who creates and destroys but cannot be relied upon for precise edits to reality, making the Shepherd Initiative more difficult.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6318, 6479, 554, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.entity_scene_appearances VALUES (6320, 2544, 555, 'ally', true, NULL, 'Resolute and persuasive. She acts as the moral compass, articulating why their past suffering makes them uniquely qualified to help others. Her conviction is unwavering.', NULL, NULL, NULL, 'Partner to Stephen. She is a source of strength and clarity for him, grounding their cosmic purpose in shared experience and empathy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_scene_appearances VALUES (6321, 6135, 555, 'ally', true, NULL, NULL, NULL, NULL, 'Appears in the doorway to ask if Stephen and Jamie have made their decision for the council meeting, adding levity and a practical deadline to their philosophical discussion.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_scene_appearances VALUES (6322, 3993, 555, 'ally', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.entity_scene_appearances VALUES (6323, 982, 555, 'enemy', false, 'Re-contextualized not just as a place of cosmic horror, but as a system containing trillions of souls who are unaware of their imprisonment and believe their suffering is normal.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
