INSERT INTO public.entity_scene_appearances VALUES (6337, 2544, 556, 'ally', true, 'Regains her original divine powers of Creativity and Death, allowing her to perceive and influence the connections between souls. Her eyes glow with threads of light during the ritual.', 'Tense, with white knuckles, but supportive and anchoring Stephen.', NULL, NULL, NULL, 'Part of The Family unit. Wife to Stephen, mother to Xavier and Hannah.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_scene_appearances VALUES (6338, 3993, 556, 'ally', true, 'Regains his original divine powers of Mischief, Chaos, and Laughter, giving him the ability to bend probability and find cracks in physics.', 'Moves from anxiousness about his relationship with Tiffany to relief and excitement about his new powers, laughing as chaos ripples around him during the ritual.', NULL, NULL, NULL, 'Part of The Family unit. Son of Stephen and Jamie, brother to Hannah. Has a crush on Tiffany.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_scene_appearances VALUES (6339, 6135, 556, 'ally', true, 'Regains her original divine powers of Serenity and Joy, acting as an emotional anchor. She hums peacefully during the ritual, the sound described as ''joy made audible''.', 'Calm and knowing, expressing a sense of familiarity and memory upon feeling her power return.', NULL, NULL, NULL, 'Part of The Family unit. Daughter of Stephen and Jamie, sister to Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_scene_appearances VALUES (6340, 2608, 556, 'ally', true, NULL, 'Acts as a professional and knowledgeable presenter, calmly outlining the complex details of the Shepherd Initiative and the subsequent ritual.', NULL, NULL, NULL, 'Will inhabit the avatar of Illara Castellan to act as one of Xavier''s grandmothers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_scene_appearances VALUES (6341, 6105, 556, 'mini-boss', true, NULL, 'Openly amused and delighted by the potential for chaos, finding the entire situation ''delectable''. He is the sole, theatrical dissenter in the vote, purely for entertainment.', NULL, NULL, NULL, 'Acts as a chaotic observer and antagonist to the orderly plan, showing a particular interest in Xavier''s chaos magic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_scene_appearances VALUES (6342, 5231, 556, 'ally', true, NULL, 'Clearly excited about participating in the mission by inhabiting an avatar.', NULL, NULL, NULL, 'Will inhabit the avatar of Benjamin Castellan to act as one of Xavier''s grandfathers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.entity_scene_appearances VALUES (6344, 6505, 556, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'A coalition of allies supporting The Family and the Shepherd Initiative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
