INSERT INTO public.entity_scene_appearances VALUES (6358, 2544, 557, 'ally', true, 'Living as Stephen''s wife in their new house, she acts as a stabilizing force and strategic thinker, suggesting they use stories to awaken others.', 'Calm, supportive, and grounded. She remembers all timelines and seems content with their new reality and mission.', NULL, NULL, 'Is in bed with Stephen at the start of the scene.', 'Wife to Stephen, mother to Xavier and Hannah.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_scene_appearances VALUES (6359, 3993, 557, 'ally', true, 'Living as a seemingly normal teenager in the Florida house, playing Roblox and arguing with his sister, while casually referencing his chaos-god powers.', 'Appears to be adjusting well to the new reality, displaying typical teenage behavior mixed with cosmic self-awareness.', NULL, NULL, 'Heard from the living room at the start of the scene.', 'Son of Stephen and Jamie, brother to Hannah.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_scene_appearances VALUES (6360, 6135, 557, 'ally', true, 'Living as a teenager in the Florida house, engaging in typical sibling arguments with her brother Xavier.', 'Seems to be adjusting well, participating in normal family life.', NULL, NULL, 'Heard arguing with Xavier from another room.', 'Daughter of Stephen and Jamie, sister to Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.entity_scene_appearances VALUES (6361, 982, 557, 'enemy', true, 'Manifests as a seemingly normal suburban Florida neighborhood, complete with a ''real sun''. Its oppressive nature is now primarily psychological, a cage disguised as a mundane life.', NULL, NULL, NULL, NULL, 'The current location and containment for Stephen''s family and other awakened souls.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
