INSERT INTO public.entity_scene_appearances VALUES (6367, 5231, 557, 'ally', false, 'Is playing the part of an eccentric snowbird with Lady Illkeserod, living in a luxury RV at a 55-plus resort to provide support for the mission.', NULL, 'A forty-foot luxury RV.', NULL, NULL, 'Stephen''s father, undercover in the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
