INSERT INTO public.entity_scene_appearances VALUES (6371, 3993, 558, 'ally', true, NULL, 'Exuberant, chaotic, and relieved. He is thrilled that his friend Tiffany remembers him and approaches the family''s strange new circumstances with cheerful enthusiasm.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-02-28 23:57:53.114976-05');
