INSERT INTO public.entity_scene_appearances VALUES (6407, 4117, 562, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Acts as a caretaker and protector for his Spatch Weed Plants, which are the last things he loves.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6408, 6570, 562, 'enemy', true, NULL, NULL, NULL, NULL, 'Hits the compound like a wave, beginning a full-scale assault.', 'The primary antagonists, destroying Kai''s compound, androids, and beloved plants.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6409, 6571, 562, 'neutral', true, NULL, NULL, NULL, 'Destroyed by the swarm.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6410, 6572, 562, 'neutral', true, NULL, NULL, NULL, 'Explodes during the swarm''s attack.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6411, 6573, 562, 'ally', true, NULL, NULL, NULL, 'Trampled, shredded, and devoured by the swarm.', NULL, 'Deeply cared for by Kai; their destruction is the catalyst for his rage.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6412, 6557, 562, 'ally', true, NULL, NULL, NULL, 'Crushed by the Multi-Eyed Swarm Crusher.', NULL, 'A specific plant cherished by Kai.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6413, 6575, 562, 'ally', true, NULL, NULL, NULL, NULL, 'Rises up in Kai as he watches his plants being destroyed.', 'An extension of Kai''s will and emotional state.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6414, 6576, 562, 'ally', true, NULL, NULL, NULL, NULL, 'Manifests after Kai''s cry of rage, allowing him to feel the dying plants.', 'Links Kai to all plant life, especially his Spatch Weed Plants.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6415, 6577, 562, 'ally', true, NULL, NULL, NULL, NULL, 'Summoned by Kai when he pulls on the fabric of reality.', 'A weaponized extension of the local flora, controlled by Kai.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6416, 6578, 562, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.entity_scene_appearances VALUES (6417, 4117, 563, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Controller of the Corrupted Roots; victim of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6418, 6580, 563, 'enemy', true, NULL, NULL, NULL, 'Killed and drained of life by the Corrupted Roots.', NULL, 'Prey for the Corrupted Roots.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6419, 6581, 563, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Initially an extension of Kai, they become a manifestation of Yaldabaoth''s corrupting influence.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6420, 6582, 563, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'The gateway for Yaldabaoth''s entry.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6421, 6136, 563, 'mini-boss', true, 'Manifests physically as a seeping, oily, iridescent black substance that moves like a tide and is composed of ''insects of nothingness''.', 'Shifts from a state of ''impotent rage'' while imprisoned to actively answering a ''call to escape'' and pouring into reality.', NULL, NULL, 'Pours through the thinned boundary between reality and anti-reality, drawn by Kai''s power.', 'Imprisoned within the Cosmic Seed Prison; possesses and transforms Kai.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6422, 6470, 563, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Jailer of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6423, 6585, 563, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Witness to Kai''s transformation.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6424, 6586, 563, 'neutral', false, 'It is corrupted into a possessive, bottomless, hungry drive.', NULL, NULL, NULL, NULL, 'A core part of Kai''s identity that is inverted by Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6425, 6587, 563, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.entity_scene_appearances VALUES (6426, 6588, 564, 'mini-boss', true, NULL, NULL, NULL, NULL, 'Rises from the dirt of the ruined garden after a horrific physical transformation of its previous form, Kai.', 'The transformed state of Kai. It destroys The Last Android and corrupts the Spatch Weed Plants into extensions of its will.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_scene_appearances VALUES (6427, 6585, 564, 'enemy', true, NULL, NULL, NULL, 'Unmade by the Kai-Thing''s tendrils; its components were dissolved into constituent atoms and then into nothingness.', 'Already present in the garden when the Kai-Thing manifests.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
