INSERT INTO public.entity_scene_appearances VALUES (6428, 6590, 564, 'ally', true, NULL, NULL, NULL, NULL, 'Already present in the garden, as survivors of a previous attack.', 'Formerly cared for by Kai, they are now corrupted by and allied with the Kai-Thing.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_scene_appearances VALUES (6429, 6591, 564, 'neutral', true, NULL, NULL, NULL, NULL, 'Erupts from the Kai-Thing''s body to attack the android.', 'A direct manifestation and tool of The Kai-Thing.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_scene_appearances VALUES (6430, 6592, 564, 'neutral', true, NULL, NULL, NULL, NULL, 'Emanates from what was Kai''s mouth when the entity declares its existence.', 'The audible expression of The Kai-Thing''s new, multifaceted identity.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.entity_scene_appearances VALUES (6431, 6593, 564, 'neutral', true, NULL, NULL, NULL, 'Flickered and faded to silence as the Planetary Root System spread over the planet, disabling them.', 'Begin to wail in the distance in response to the Kai-Thing''s emergence and actions.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
