INSERT INTO public.entity_scene_appearances VALUES (6465, 3993, 567, 'ally', true, 'His role shifts from a background character to the named protagonist of the new story, symbolizing a transition from an NPC to a person with agency. His accidental physical action inspires the story''s new direction.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_scene_appearances VALUES (6466, 982, 567, 'enemy', false, 'Re-contextualized as the central obstacle that must be escaped ''once and for all'', establishing the core premise for the final book in the series.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.entity_scene_appearances VALUES (6467, 5489, 567, 'ally', false, NULL, NULL, NULL, NULL, 'Appears in the story as an unexpected character, not part of the author''s initial outline, signifying the narrative taking on a life of its own.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
