INSERT INTO public.entity_scene_appearances VALUES (6485, 6648, 568, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.entity_scene_appearances VALUES (6486, 3993, 569, 'ally', true, NULL, 'Expresses a mix of ambition for his creative work and cynical humor regarding marketing, death, and conspiracy. He is forward-looking and self-aware.', NULL, NULL, NULL, 'Identifies his ''one true love'' (ብሪትለሪሌት) as the reason he would reincarnate into his protagonist. Views the Agents of Yaldabaoth as potential assassins.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (6493, 2544, 569, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Identified as the author''s ''one true love'' and the motivation for his desire to reincarnate into his story''s protagonist.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (6494, 6657, 569, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (6495, 6658, 569, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (6491, 6654, 569, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.entity_scene_appearances VALUES (6497, 6661, 570, 'neutral', true, NULL, NULL, NULL, NULL, 'Appears at the start of a ''secret level'' to introduce cosmological stories.', 'Acts as a guide for the ''Readers''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6498, 6607, 570, 'neutral', false, NULL, NULL, NULL, NULL, 'Addressed directly by The Author in the introductory note.', 'The recipients of the author''s exposition.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6499, 6663, 570, 'neutral', false, NULL, NULL, NULL, NULL, 'Introduced by the author as supplemental material.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6500, 982, 570, 'neutral', true, 'Described as an unintentionally muddled space with scrambled frequencies, recursive loops, and memory wipes, built to contain Yaldabaoth.', NULL, NULL, NULL, NULL, 'The prison containing Yaldabaoth and the setting where Stephen, Jamie, and Xavier are trapped.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6501, 2550, 570, 'enemy', true, 'Explicitly defined as a parasitic false god who built the Prison Realm of Etheris. He perpetually clones and traps souls to feed on their consciousness.', NULL, NULL, NULL, NULL, 'The jailer of Etheris and the primary antagonist to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6503, 2544, 570, 'ally', true, 'Revealed to be Stephen''s twin flame and the secret power source keeping Etheris standing. The pain of their separation fuels the prison.', NULL, NULL, NULL, NULL, 'Co-architect of the prison plan with Stephen. Her existence is masked from him by the system.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6504, 5489, 570, 'ally', false, 'Confirmed to have survived deletion/ejection from Etheris and now exists outside of it. She successfully sent a signal to Stephen before contact was lost.', NULL, NULL, NULL, NULL, 'A key external ally to Stephen.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6505, 3993, 570, 'ally', true, 'Now a teenager, he is beginning to notice glitches in the NPCs. He is described as an anomaly and a key factor in the prison''s escalating instability.', NULL, NULL, NULL, NULL, 'Son of Stephen.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6506, 5770, 570, 'neutral', true, NULL, NULL, NULL, NULL, 'Described as the victims and fuel source for the Prison Realm.', 'Prey for Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6507, 456, 570, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned as part of Stephen''s backstory.', 'A creation of Stephen.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6508, 6672, 570, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.entity_scene_appearances VALUES (6509, 6673, 571, 'neutral', true, NULL, NULL, NULL, NULL, 'Awakens due to a random, impossible fluctuation in the void after infinite eternities of nothingness.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6510, 6421, 571, 'neutral', true, NULL, NULL, NULL, NULL, 'Emerged from Bythos as a paradoxical multiplication of consciousness, always having existed but waiting for the moment to manifest.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6511, 6675, 571, 'neutral', true, NULL, NULL, NULL, NULL, 'Emerged as the first split from the Monad, like light through a prism.', 'Forms a perfect syzygy with the Spirit (Bythos). Cautions Sophia against her curiosity.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6512, 6676, 571, 'neutral', true, NULL, NULL, NULL, NULL, 'Emerged along with Barbelo as part of the Pleroma.', 'Warn Sophia to stay within the light and the known.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6513, 6677, 571, 'neutral', true, NULL, NULL, NULL, NULL, 'Manifested as part of the Pleroma''s emergence.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6514, 5524, 571, 'ally', true, NULL, NULL, NULL, NULL, 'Willed herself into independent existence, breaking from the collective harmony of the Pleroma.', 'She is the ''mother'' of Yaldabaoth, not by creation but by accidentally providing a conduit for its emergence.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6515, 234, 571, 'neutral', true, NULL, NULL, NULL, NULL, 'The foundational state of non-being from which everything begins.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6516, 6136, 571, 'mini-boss', true, 'Emerged as a deformed, misshapen entity with multiple faces and a constantly shifting form. It is an infection of reality, wearing Sophia''s stolen light over a core of hunger.', 'Views Sophia as its mother and radiates a powerful hunger. It is not enraged by its imprisonment, but immediately begins creating within it.', NULL, NULL, 'Pulled through from the void when it used Sophia''s will as a bridge. It came ''through'' her, not ''from'' her.', 'Considers Sophia its mother. It is the secret shame she hides from the other aeons.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6517, 6681, 571, 'neutral', true, NULL, NULL, NULL, NULL, 'Created by Sophia in a desperate act to imprison the creature.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6518, 6418, 571, 'neutral', true, NULL, NULL, NULL, NULL, 'Placed inside the prison by Sophia immediately after its creation.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6519, 6683, 571, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.entity_scene_appearances VALUES (6520, 5524, 572, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'She is the ''mother'' of Yaldabaoth, a creator who feels responsible for the abomination she birthed. She becomes the secret benefactor of Adam, granting him a divine spark.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6521, 6685, 572, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Loves his flock with a pure, paternal devotion. He becomes the unwilling vessel and core emotional engine for Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6522, 6136, 572, 'enemy', true, 'Its origin is revealed: it is an anti-reality parasite that consumed and merged with the shepherd Sam, whose pure love for his flock was inverted into a bottomless, possessive hunger. This fusion was inadvertently empowered by Sophia''s divine touch, creating a paradoxical being of stolen light and anti-real void with the face of a lion and the body of a serpent.', 'Born from Sam''s incandescent rage, its core emotion becomes a divine, arrogant will. It is ignorant of its true origin, believing itself to be the one true god, driven by an insatiable hunger to consume.', NULL, NULL, 'Forms when anti-reality pours through a tear in reality and consumes Sam''s essence, rebuilding him from the inside out.', 'Views Sophia''s luminous prison not as a cage but as its personal cosmos and fuel source. It sees its creations, the Archons and humanity, as reflections of itself and a crop of souls to be farmed.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6523, 6687, 572, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'They are the catalyst for Sam''s transformation, their cruelty pushing his love into a reality-breaking rage.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6525, 6689, 572, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6591, 5651, 577, 'ally', true, NULL, NULL, NULL, NULL, 'Drawn to the unnatural calm in the battlefield after Stephen''s act.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6526, 6690, 572, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Their slaughter by the Raiders is the direct cause of Sam''s transformative rage.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6527, 6681, 572, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'A cage that becomes a kingdom and a food source for its prisoner.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6528, 6107, 572, 'neutral', true, 'This specific tear was created by the paradoxical collision of Sophia''s divine power (pure ''is'') and Sam''s impossible rage from a God-Null Zone. It opened a wound into the anti-reality (''is not'') rather than another part of reality.', NULL, NULL, 'It is the conduit through which Anti-reality enters the material world.', 'Forms at the moment Sophia''s power touches Sam''s scream of rage.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6531, 6673, 572, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A parental or higher-order figure to Sophia, who warned her against creation.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6530, 6694, 572, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.entity_scene_appearances VALUES (6533, 5963, 573, 'ally', true, NULL, NULL, NULL, NULL, 'Awakens in the garden as a new creation.', 'Views Yaldabaoth as a flawed creator and Adam as an empty vessel. Develops a deep bond and love with Lucifer, becoming his partner in rebellion.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6534, 6136, 573, 'mini-boss', true, 'Appears as a radiant, terrible, vast entity compressed into a quasi-humanoid form, surmounted by a luminous cloud. Its form swells by consuming souls until it ruptures, collapses reality, and reforms to begin the cycle anew.', 'Expresses confusion, disgust, and a horrified fascination with Lilith''s free will. Acts as a judgmental, controlling prison-keeper whose words are law that bend reality.', NULL, 'Temporarily destroyed when its form ruptures, causing the collapse of the first cycle, but immediately begins to reform.', 'Present at Lilith''s awakening as her creator.', 'Creator of Adam, the obedient humans, and the angels. Views Lilith as a failed experiment and a threat to its perfect, controlled garden.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6536, 5962, 573, 'ally', true, NULL, NULL, NULL, NULL, 'Appears at the barrier of the garden, drawn to the exiled Lilith.', 'Falls in love with Lilith, becoming her partner and co-conspirator against Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6537, 6701, 573, 'neutral', true, NULL, NULL, NULL, NULL, 'Present within Lilith from the moment of her awakening.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6538, 6702, 573, 'neutral', true, NULL, NULL, NULL, 'Collapses and is destroyed at the end of the first cycle.', 'The setting for Lilith''s awakening.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6539, 6703, 573, 'neutral', true, NULL, NULL, NULL, 'Destroyed in the collapse of the garden.', 'Begin to appear in the garden after Lilith is banished.', 'Serve as a food source for Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6540, 6174, 573, 'neutral', true, NULL, NULL, NULL, 'Destroyed in the collapse of the garden.', 'Becomes visible to Lilith upon her banishment.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6541, 5981, 573, 'neutral', true, NULL, NULL, NULL, 'Concludes when Yaldabaoth speaks the words "Let there be light," initiating the next cycle.', 'The scene describes this entire event.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6542, 6706, 573, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.entity_scene_appearances VALUES (6543, 6136, 574, 'mini-boss', true, 'Yaldabaoth evolves from a simple consumer into a sophisticated, learning entity. It analyzes its failures across multiple cosmic cycles, optimizing its methods of imprisoning and harvesting souls from simple compression to complex psychological and spiritual manipulation.', 'Its state shifts from simple hunger to analytical calculation after the first failure. It then experiences dissatisfaction with the ''flavor'' of souls, followed by an intoxicating excitement at the concept of worship, and finally settles into a state of stable, patient certainty in its eternal cycle.', NULL, NULL, NULL, 'Acts as the creator, jailer, and consumer of Humanity and its souls. It utilizes Metatron and The Angels as tools for management and views Lucifer and Lilith as pests who inadvertently improve the quality of its harvest.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6544, 326, 574, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The primary resource and prisoners of Yaldabaoth. They are manipulated by The Angels and occasionally ''awakened'' by Lucifer and Lilith.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6545, 5981, 574, 'neutral', false, NULL, NULL, NULL, 'Collapsed due to overpopulation in a confined conceptual space.', 'Described retrospectively as Yaldabaoth analyzes its failure.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6546, 6710, 574, 'neutral', false, NULL, NULL, NULL, 'Collapsed due to Yaldabaoth''s internal density exceeding its capacity.', 'Created as an optimization following the failure of the first cycle.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6547, 6711, 574, 'neutral', false, NULL, NULL, NULL, 'Collapsed prematurely due to the destabilizing violence of a multi-world holy war.', 'Created to solve the problems of both population and internal compression.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6548, 6712, 574, 'neutral', true, NULL, NULL, NULL, NULL, 'The culmination of Yaldabaoth''s learning, designed for stable, high-quality soul harvesting.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6549, 6713, 574, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6550, 6714, 574, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6551, 6715, 574, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6552, 5962, 574, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned as a persistent problem and an unwitting source of high-quality souls for Yaldabaoth.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6553, 5963, 574, 'ally', false, NULL, NULL, NULL, NULL, 'Mentioned as a catalyst for creating more complex and desirable souls for Yaldabaoth to consume.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6554, 6718, 574, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6555, 6719, 574, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Serve Yaldabaoth and are managed by Metatron.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6557, 6721, 574, 'neutral', true, NULL, NULL, NULL, NULL, 'Created as a ''corrected'' version of the first female, designed for compliance.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6558, 6722, 574, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.entity_scene_appearances VALUES (6590, 6739, 577, 'ally', true, 'Appears as a silent shadow, his presence more like a void than a person.', NULL, NULL, NULL, 'Drawn to the unnatural calm in the battlefield after Stephen''s act.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6592, 6757, 577, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6559, 5963, 575, 'ally', true, 'Her form flickers through multiple versions of herself as she adapts to the freedom of the true cosmos.', 'Moves from a calm teacher to alarmed, then desperate as she tries to save souls from the prison''s collapse. She becomes a refugee, determined to fight back.', NULL, NULL, 'Sensing the initial fracture in the prison while teaching a group of woken humans.', 'Co-leader of the rebellion with Lucifer. Acts as a protector for the trapped consciousnesses.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6560, 5962, 575, 'ally', true, 'Manifests his full angelic form with wings of light and shadow and multi-directional eyes upon the prison''s collapse.', 'His initial alarm turns into strained desperation as he gathers souls. He later becomes a determined strategist, formulating a plan to fight Yaldabaoth.', NULL, NULL, 'Responds instantly to Lilith''s warning through their rebel network.', 'Co-leader of the rebellion with Lilith. He is the one who taught her to perceive the layers of reality.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6561, 6136, 575, 'mini-boss', true, 'Its true form erupts from the prison: a vast, writhing wrongness whose boundaries bleed into impossible dimensions, flickering between matter and antimatter.', 'Experiences a primal, terrifying ecstasy and orgasmic release upon breaking free, which shifts to an endless, mindless hunger to consume all of reality.', NULL, 'Surges through the shattered prison into the true cosmos to begin consuming realities.', NULL, 'Child of Sophia. The jailer and consumer of the Trapped Consciousnesses. Its original identity, Sam, is a screaming prisoner within it.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6562, 6726, 575, 'neutral', true, NULL, NULL, NULL, 'Violently dispersed and atomized across the void when the prison shatters, with a small fraction rescued by Lilith and Lucifer.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6563, 6727, 575, 'neutral', true, NULL, NULL, NULL, NULL, 'Becomes the new setting after the Abyss is destroyed, serving as both a refuge for the survivors and a feeding ground for Yaldabaoth.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6564, 6728, 575, 'enemy', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6565, 6729, 575, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6566, 5524, 575, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Mother of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6567, 5652, 575, 'ally', true, NULL, NULL, NULL, NULL, 'Confronts Lilith and Lucifer when they enter his realm, reeking of a foreign reality.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6568, 3993, 575, 'neutral', false, 'Revealed to be a screaming consciousness still trapped deep inside the monstrous form of Yaldabaoth, a remnant of the being it once was.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6569, 6734, 575, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.entity_scene_appearances VALUES (6570, 6735, 576, 'ally', true, NULL, NULL, NULL, NULL, 'Appears at the start of the scene, already in flight with Lucifer.', 'Partner and co-leader with Lucifer in the resistance against Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6571, 6736, 576, 'ally', true, NULL, NULL, NULL, NULL, 'Appears at the start of the scene, fleeing with Lilith.', 'Partner to Lilith; recruiter of Chernobog.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6572, 6136, 576, 'enemy', true, 'Its presence is defined by the ''infection'' it spreads, a corrupting influence that turns gods and warps reality, acting as the primary antagonistic force in the scene.', NULL, NULL, NULL, NULL, 'The source of the corruption that Lilith, Lucifer, and their allies are fighting against.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6573, 6738, 576, 'ally', true, NULL, NULL, NULL, NULL, 'Are being gathered by Lilith and Lucifer throughout their flight.', 'Wards of Lilith and Lucifer; potential members of the future army.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6574, 6739, 576, 'ally', true, NULL, NULL, NULL, NULL, 'Recruited by Lucifer in the second beat.', 'The first major ally recruited by Lucifer and Lilith.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6575, 6740, 576, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Potential allies for the resistance; Chernobog is a member of this group.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6576, 6741, 576, 'mini-boss', true, NULL, NULL, NULL, NULL, 'The primary threat driving the action of the scene.', 'An extension and weapon of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6577, 6742, 576, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'The ultimate goal of Lucifer and Chernobog''s recruitment efforts.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6578, 6743, 576, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.entity_scene_appearances VALUES (6580, 2544, 577, 'ally', true, 'Suffers grievous wounds from acidic blood and a full impalement by the Chaos Hybrid. These wounds are then erased from existence, leaving her physically pristine but wracked with phantom pain.', 'Moves from defiant determination to pure agony, then to traumatized relief mixed with terror for Stephen, understanding the forbidden nature of the power he used to save her.', NULL, NULL, NULL, 'The object of Stephen''s desperate, reality-breaking love. Her near-death is the trigger for the scene''s central event.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6581, 6746, 577, 'mini-boss', true, NULL, NULL, NULL, 'Erased from existence by Stephen''s act of un-creation, vanishing as if it had never been.', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6582, 2608, 577, 'ally', true, NULL, 'Arrives on the scene and quickly shifts from concern to soul-tearing grief and terror upon realizing Benji is missing. This agony is instantly forged into a pure, incandescent fury directed at Stephen, whom she blames for the loss.', NULL, NULL, 'Drawn to the unnatural silence created by Stephen''s act, she appears with other allied gods.', 'Her parental love for Benji turns to rage at Stephen, whom she holds responsible for his disappearance.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6583, 5231, 577, 'ally', false, 'His position on the battlefield was overrun while Stephen was saving Velistra, and he is now missing and presumed captured or killed.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6584, 5650, 577, 'ally', true, NULL, NULL, NULL, NULL, 'Appears in the circle of silence created by Stephen''s act.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6585, 6750, 577, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6586, 6751, 577, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6587, 6752, 577, 'neutral', true, NULL, NULL, NULL, NULL, 'Present only as a corpse from which Stephen emerges.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6588, 6735, 577, 'ally', true, 'Appears alongside Lucifer, her voice sharp and cold as she pragmatically tries to manage Lady Illkeserod''s panic.', NULL, NULL, NULL, 'Drawn to the unnatural calm in the battlefield after Stephen''s act.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6589, 6736, 577, 'ally', true, 'Appears alongside Lilith, his ethereal light described as burning cold and sharp.', NULL, NULL, NULL, 'Drawn to the unnatural calm in the battlefield after Stephen''s act.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6593, 6758, 577, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.entity_scene_appearances VALUES (6596, 2608, 578, 'ally', true, 'Her origin is revealed as the violent, desperate fusion of two divine sisters, Selyr and Keserod. She is shown evolving from a child into a hardened warrior, a shepherd for the last survivors of her world, and finally a weary refugee.', 'Experiences a transition from childhood innocence (as her precursor selves) to terror, grim determination during the war, bone-deep weariness after centuries of loss, and a final flicker of hope upon being rescued.', NULL, 'Escapes her dying reality through a portal created by Benji.', 'Forms from the merging of Selyr and Keserod as their temple burns.', 'The fused being of Selyr and Keserod; leader of the Last Survivors of Bythos; enemy of Yaldabaoth and his forces.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6597, 6762, 578, 'ally', true, NULL, NULL, NULL, 'Her physical form is destroyed and her soul is violently merged with her sister''s to create Lady Illkeserod.', 'Appears in the memory of Illkeserod''s childhood.', 'Older sister of Keserod.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6598, 6763, 578, 'ally', true, NULL, NULL, NULL, 'Her physical form is destroyed and her soul is violently merged with her sister''s to create Lady Illkeserod.', 'Appears in the memory of Illkeserod''s childhood.', 'Younger sister of Selyr.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6599, 6136, 578, 'enemy', true, 'Appears in a more direct, physical form as a colossal being of shadow and broken light that literally eats reality, devouring souls and the landscape of Illkeserod''s world.', NULL, NULL, NULL, NULL, 'The source of the spiritual infection and the ultimate destroyer of Illkeserod''s homeworld.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6600, 6741, 578, 'enemy', true, 'Shown as a memetic virus spread through words, capable of instantly converting individuals into fervent, zealous followers who abandon their former lives. It creates a hot, feverish, hungry light in their eyes.', NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6601, 6766, 578, 'enemy', true, NULL, NULL, NULL, NULL, 'Appear during the burning of the last temple and lead the final assault on the survivors.', 'Led by Metatron; servants of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6602, 6714, 578, 'mini-boss', true, NULL, NULL, NULL, 'Left behind as the portal closes, denied his final victory.', 'Appears leading the final charge against the last survivors.', 'Commander of the Angelic Host.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6603, 5231, 578, 'ally', true, NULL, 'Frantic, urgent, and under immense strain from maintaining a portal into a hostile, corrupted reality.', NULL, 'Pulls Illkeserod through the portal just as it snaps shut.', 'Bursts through a self-made portal in the midst of the final confrontation to offer an escape.', 'Savior of Lady Illkeserod and her people.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6604, 6769, 578, 'ally', true, NULL, NULL, NULL, 'Escape their doomed world through Benji''s portal.', 'Gathered by Illkeserod over generations of hiding.', 'Followers of Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6605, 6770, 578, 'neutral', true, NULL, NULL, NULL, 'Snaps shut after the last refugee passes through.', 'Created by Benji under great strain.', NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6606, 6771, 578, 'enemy', true, NULL, NULL, NULL, NULL, 'Stops a merchant on the road to convert him.', 'Servant of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6607, 6772, 578, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.entity_scene_appearances VALUES (6609, 5231, 579, 'ally', true, 'He is found being physically and spiritually dismantled by Yaldabaoth. After being rescued, he is violently reformed by Lady Illkeserod into a physically whole but mentally blank being.', 'Experiences agony beyond mortal comprehension as he is unmade. After his restoration, he is left with no memory or consciousness, only a pure, childlike devotion and love for Lady Illkeserod, his creator.', NULL, NULL, NULL, 'His relationship with Lady Illkeserod is fundamentally altered; he now sees her as his creator, imprinting on her with a hollow, unwavering devotion.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6610, 2608, 579, 'ally', true, NULL, 'Her fury transforms into a cold, predatory focus while hunting. Upon finding Benji, this erupts into a unified agony and rage, culminating in a suicidal charge. This is followed by desperate determination to save him, which finally shatters into devastating grief and revulsion at the hollow shell he has become.', NULL, NULL, NULL, 'Becomes the creator of the ''new'' Benji, who is now tethered to her by a powerful, albeit empty, bond of devotion.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6611, 6136, 579, 'mini-boss', true, 'Manifests in a physically distinct and hideously real form: a colossal, roiling, malformed mass of shadow, light, and mouths, with whip-like tentacles. It is described as an avatar of anti-reality, a ''de-maker''.', 'Exhibits predatory hunger and pleasure while feeding on Benji. It expresses genuine pain and surprise when wounded by Lady Illkeserod''s attack before retreating.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6612, 6736, 579, 'ally', true, NULL, 'His usual charm is completely gone, replaced by a flat, grim demeanor. He witnesses the horror alongside the others, but his grief gives way to a cold, strategic understanding of how Sophia contained Yaldabaoth.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6613, 6735, 579, 'ally', true, NULL, 'Shares the group''s horror, but is the first to recognize the significance of Benji''s new state, seeing his hollow devotion as a ''chain'' and key to understanding Sophia''s power.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6614, 6779, 579, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6615, 6780, 579, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6616, 6781, 579, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6617, 5650, 579, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6618, 5651, 579, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6619, 5524, 579, 'unknown', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6620, 6713, 579, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6621, 6786, 579, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6622, 6787, 579, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.entity_scene_appearances VALUES (6623, 6736, 580, 'ally', true, NULL, NULL, NULL, NULL, 'Present at the start of the scene, explaining a key concept.', 'Co-narrator with Lilith, explaining the nature of the Luminous Cloud.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_scene_appearances VALUES (6624, 6735, 580, 'ally', true, NULL, NULL, NULL, NULL, 'Present at the start of the scene, explaining a key concept.', 'Co-narrator with Lucifer, revealing the truth about Sophia''s sacrifice.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_scene_appearances VALUES (6625, 6136, 580, 'mini-boss', true, 'Revealed to be contained within a luminous cloud powered by maternal love. This form is a parasitic prison, allowing it to endlessly consume the essence of its victim, Sophia.', NULL, NULL, NULL, NULL, 'Parasitically feeding on Sophia''s essence, using her maternal love as both fuel and a cage.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_scene_appearances VALUES (6626, 5524, 580, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'Mother figure whose love is being exploited by Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_scene_appearances VALUES (6627, 6792, 580, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_scene_appearances VALUES (6628, 6793, 580, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_scene_appearances VALUES (6629, 6794, 580, 'mini-boss', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.entity_scene_appearances VALUES (6524, 5525, 572, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Acts as a parasite, needing a host (Sam''s rage and will) to become an active agent within reality.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 15:39:36.277259-05');
INSERT INTO public.entity_scene_appearances VALUES (2815, 2107, 242, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:22:13.658445-05', '2026-03-01 15:39:36.277259-05');
INSERT INTO public.entity_scene_appearances VALUES (6261, 6287, 551, 'ally', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-03-01 15:39:36.277259-05');
INSERT INTO public.entity_scene_appearances VALUES (6131, 456, 541, 'neutral', false, NULL, NULL, NULL, NULL, 'Mentioned by Todd as the origin point of the cosmic seed.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-03-01 15:39:36.277259-05');
INSERT INTO public.entity_scene_appearances VALUES (1957, 1968, 167, 'neutral', true, NULL, NULL, NULL, 'The family leaves her home to return to their own country.', 'Is present at the table during the initial conversation.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:57:02.220804-05', '2026-03-01 15:39:36.277259-05');
INSERT INTO public.entity_scene_appearances VALUES (3036, 3103, 265, 'neutral', true, NULL, NULL, NULL, NULL, 'Abruptly interjects during the narrator''s explanation to the U.S. representative.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:40:52.563712-05', '2026-03-01 15:39:36.277259-05');
INSERT INTO public.entity_scene_appearances VALUES (4029, 19, 354, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Husband to Rina and father to Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:04:58.145163-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (1385, 1359, 107, 'neutral', true, 'Seen as inert and coiled in waiting. The dream elevates their status to the crucial ''missing piece'', the ''arteries of an unseen beast'', and an ''unborn titan''.', NULL, NULL, NULL, NULL, 'One of the three core devices, revealed to be the key to uniting the others.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (3188, 2046, 281, 'neutral', false, NULL, NULL, NULL, NULL, 'Introduced as the primary means of interstellar travel for the mission.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (2279, 1080, 192, 'neutral', true, NULL, NULL, NULL, 'The concept is overcome as the family fills the space with ideas and the nanites physically transform it.', 'The son identifies the building''s atmosphere as being like a liminal space video.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (1828, 1863, 155, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The focus of The Narrator''s work.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:45:45.473891-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (2223, 1863, 190, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Referenced by Narrator in conversation with Wife; tied to The Pointers'' legacy', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:59.228789-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (521, 326, 33, 'neutral', false, NULL, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (2984, 326, 260, 'neutral', true, NULL, NULL, NULL, NULL, 'Gathered in the conference space to witness S Corp''s presentation.', 'The audience for S Corp''s private reveal, whose cooperation is needed for a smooth global transition.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:37:13.723076-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (3005, 326, 262, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:38:37.251332-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (1888, 326, 161, 'enemy', false, NULL, NULL, NULL, NULL, NULL, 'Creators of the AutoDoc and the Mangled Human Experiments.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5351, 326, 473, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'Friend of Benji and Whitney; a target for rescue by Ilse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:29:58.036374-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5366, 326, 475, 'ally', true, NULL, 'Feels disheartened, invisible, and exhausted by his wife''s criticism. Experiences a moment of connection and validation with his son, leading to a profound and disturbing realization about his wife''s nature.', NULL, NULL, NULL, 'Husband to አንጀላህጃን, father to Xavier. His relationship with his wife is antagonistic and draining, while his bond with his son deepens through shared understanding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:31:57.262898-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5377, 326, 476, 'ally', true, NULL, 'Experiences a powerful, traumatic vision where he embodies a shepherd consumed by reality-breaking rage and grief. This emotion is then corrupted by an external force into a possessive hunger, leaving a lingering coldness and disorientation when he returns to his body.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:32:54.020373-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5393, 326, 478, 'ally', true, NULL, 'Cycles from a suffocating depression to a morbid, dangerous curiosity. He becomes methodical and determined in his suicide attempts, which are framed as experiments to break his reality. His state shifts to agonizing pain, then to panicked dread and shock upon realizing the rules of his imprisonment.', NULL, NULL, NULL, 'Husband to አንጀላህጃን, who he discovers is a scripted NPC. He is haunted by the words of Xavier, which inform his attempts to break the simulation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:34:33.299402-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5403, 326, 479, 'ally', true, NULL, 'Moves from quiet observation and longing for connection to nostalgic reminiscence of his youth. Experiences a sudden, visceral flash-memory of yearning, followed by a sense of unease and dread when his phone displays an eerily relevant notification.', NULL, NULL, NULL, 'Father of Xavier. He attempts to bridge the generational and technological gap between them through conversation, revealing parts of his past in the process.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:35:31.244588-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5413, 326, 480, 'ally', true, NULL, 'Experiences escalating frustration and exhaustion with the argument, followed by shock at the thrown glass. This shifts to quiet defiance as he sends a message to an old friend, and later a mix of nostalgic hope and sudden, profound terror from a triggered memory.', NULL, NULL, NULL, 'Husband to አንጀላህጃን, who he perceives as part of a scripted loop. He reconnects with his old friend Rebecca Caldwell for the first time in twenty years.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:36:22.141398-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5424, 326, 481, 'ally', true, NULL, 'Experiences a violent, terrifying memory-vision that leaves him with a hammering heart, feeling small and crushed. This fear is quickly replaced by a sense of hope when presented with an opportunity to escape his current environment.', NULL, NULL, NULL, 'Receives messages from Rebecca, which trigger a vision and then offer a social lifeline.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:37:15.111704-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5700, 326, 503, 'ally', false, NULL, NULL, NULL, NULL, 'He is the focus of Whitney''s memories and emotional efforts, the target of her psychic message.', 'Shares a deep, familial bond with Whitney, built on mutual acceptance and understanding of shared trauma. He is the anchor for her power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5432, 326, 482, 'ally', true, NULL, 'Wakes with a profound sense of ''wrongness'' stemming from visceral memories of dying. He feels disconnected from time, exhausted by his domestic situation, and ultimately makes a defiant choice to escape.', NULL, 'Leaves the house to escape the oppressive atmosphere and his life''s responsibilities.', 'Wakes up in his bed at the start of the scene.', 'Husband to አንጀላህጃን, father to Xavier. Feels monitored and controlled by his wife. Receives an invitation from a friend, Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:38:23.206313-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5443, 326, 483, 'ally', true, NULL, 'Starts in a hypnotic, empty state, shifts to wistful longing for a phantom presence, and is then jolted back to a disoriented reality by a sudden noise.', NULL, NULL, NULL, 'Experiences a haunting memory of ''The Phantom Passenger'', which disrupts his solitary drive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:39:10.743052-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5451, 326, 484, 'ally', true, 'His reflection in the shop door reveals him to be unshaven and hallow, with ''two years of unemployment etched into the lines around his eyes''. He looks haunted.', 'Begins the scene feeling ''pissed'' and frustrated with navigation. This shifts to sudden shock and a profound, visceral reaction of recognition upon seeing the name ''Jamie''s Marginalia''. He ends the scene feeling apprehensive and aware of his own haunted state before entering the shop.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:39:55.920791-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5462, 326, 485, 'ally', true, NULL, 'Initially anxious and socially awkward, he experiences a wave of relief and validation from his friends'' acceptance. This shifts to shock and intense distress when confronted with the phrase ''consensus reality'' and his inability to confirm a memory of a phantom girl from his past.', NULL, NULL, 'Enters the bookshop to meet old friends, feeling the weight of his unemployment and personal struggles.', 'Reunites with his old friends, Becca and James. He is haunted by the memory of the Phantom Girl.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5472, 326, 486, 'ally', true, NULL, 'Experiences a profound shift from a guest at a party to a solitary discoverer of ancient secrets. He is overwhelmed by a visceral memory of love, followed by a cosmic vision of creation and divine error that feels like his own autobiography, leaving him shaken and trembling.', 'Temporarily holds a wine glass, then two mysterious books: The Secret Book of John and The Gospel of Judas.', NULL, NULL, 'Led by James into the back room. Experiences a memory involving Becca and Jamie (ብሪትለሪሌት). Discovers books that connect him to Sophia and the Demiurge (ኢሌልመሜብሃባኖኖራሊሊ).', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5486, 326, 487, 'ally', true, NULL, 'Experiences a profound emotional shift from curiosity to overwhelming sensory recognition, love, and grief upon discovering Jamie''s identity. This culminates in a new, terrible sense of purpose and wakefulness.', 'Acquires ''The Gnostic Gospels''.', NULL, NULL, 'His forgotten love for Jamie Reyes is violently reawakened. He feels a sense of camaraderie and gratitude towards Becca and James.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5494, 326, 488, 'ally', true, NULL, 'Begins by attempting to de-escalate but quickly retreats emotionally under his wife''s attack, becoming withdrawn, resigned, and non-responsive. Experiences a sudden shock and confusion when he has an auditory hallucination.', NULL, NULL, NULL, 'Husband of Angela and father of Xavier. He is the target of Angela''s verbal attacks.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:43:37.412246-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5514, 326, 489, 'ally', false, 'Observed as a faint, fading image within Etheris, sitting on a couch and scrolling on a phone, unaware of the cosmic beings watching him.', 'He is in a state of searching, and his mind is beginning to remember things, causing him to press against the walls of his prison.', NULL, NULL, NULL, 'The focus of Whitney''s signal and a key figure whose awakening could either save or doom them all.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:44:22.961777-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5547, 326, 490, 'ally', true, 'Experiences a sudden, violent metaphysical alignment that feels like being ''remembered'' or ''slotted'' into place, causing him to drop his phone.', 'Moves from a normal state to sudden confusion and vertigo, followed by a profound sense of shock at the alignment.', NULL, NULL, NULL, 'The target of a connection created by Lady Illkeserod and the recipient of Whitney''s prayer. He is also a key figure in Whitney''s memories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:51:12.844718-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5554, 326, 491, 'ally', true, NULL, 'Starts frustrated and determined in his search, becomes defensive during the confrontation, and ends with a calm, resigned demeanor after his computer is destroyed.', NULL, NULL, NULL, 'Husband to አንጀላህጃን. He is actively searching for ዊትኒ.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:52:02.890953-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5563, 326, 492, 'ally', true, NULL, 'Begins the scene tired, defeated, and frustrated with his wife''s sabotage. His anxiety and desperation to find answers about Whitney and Jamie are palpable. He becomes shocked and unnerved by the reality-glitching events, and ends the scene with a sense of apprehension and renewed purpose.', NULL, NULL, NULL, 'Reconnects with his old high school friend, Gil. Is confronted by the mysterious Andrew and Morgan. Learns new, contradictory information about his former classmates Patrick and Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:53:10.219175-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5594, 326, 494, 'unknown', false, NULL, NULL, NULL, NULL, 'His name is the last conscious thought Whitney has as the dream walk takes her, identifying him as the source of the calling vibration.', 'Is actively calling out to Whitney across dimensions, creating a beacon she can follow.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5603, 326, 495, 'ally', false, NULL, NULL, NULL, NULL, NULL, 'One of the people Whitney believes still remembers her, providing a motivation for her to find her way back to connection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5609, 326, 496, 'ally', true, NULL, 'Moves from investigative and cautious to suspicious, then terrified during the attack. He acts on instinct, invoking a power he doesn''t understand, leaving him confused but resolute.', 'Briefly possesses a copy of the Gospel of Judas.', NULL, NULL, 'Reunites with his old acquaintance, Patrick. Is targeted by the Whitney Construct.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5628, 326, 498, 'ally', false, 'It is revealed that he is ''waking up'' faster than anticipated due to Whitney''s desperate signal breaking through dimensional barriers.', NULL, NULL, NULL, NULL, 'The subject of Whitney''s powerful emotional connection. He is remembered by her as a kind soul who saw her as whole.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5637, 326, 499, 'ally', true, NULL, 'Moves from confusion about the fading photographs to dawning horror and clarity as he realizes his wife is a malevolent construct and his son is in danger. His headache returns, but brings with it a terrible understanding of his reality.', NULL, NULL, NULL, 'Listens to Patrick''s explanation of their reality, which causes him to re-evaluate his entire life, especially his relationship with his wife and son.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5651, 326, 500, 'ally', true, NULL, 'Begins with clenched-fist anger, shifts to shock and physical weakness upon hearing revelations about his past, and resolves into grim determination to find TJ and save his son.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:00:16.411887-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5682, 326, 502, 'ally', true, 'Sustains a bloody nose after being headbutted by his wife.', 'Cycles through alarm, desperation during a traumatic memory, protective instincts, terror, and finally a complex grief mixed with shock after his wife''s death.', NULL, NULL, NULL, 'Protagonist of the scene. Acts to protect his son, Xavier, from his violent wife. Experiences a memory of his past life as Aspolin.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5711, 326, 504, 'ally', true, NULL, 'Initially wary and investigative, his state shifts to shock, horror, and finally a desperate grief-tinged determination to escape after witnessing TJ''s sacrifice.', NULL, 'Flees the center with Xavier after TJ sacrifices himself to hold back the unraveled NPCs.', 'Arrives at St. Michael''s Outreach Center with his son, Xavier, seeking help from TJ.', 'Protagonist, father of Xavier, old friend of TJ. He is seeking answers and a way to escape the system.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5723, 326, 505, 'ally', true, 'His nose has been re-broken, but feels straighter and allows him to breathe clearly for the first time in years. His body aches, particularly his ribs.', 'A mix of physical pain, exhaustion, and protective concern for his son. He finds a moment of grim humor in his newly aligned nose but is ultimately overwhelmed by the situation, saying the ''lamest, most useless, normal thing'' before collapsing into sleep.', NULL, NULL, NULL, 'Father to Xavier, whom he is tending to and protecting. Ex-husband to Angela, who is publicly framing him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5736, 326, 506, 'ally', true, NULL, 'Starts with physical pain and urgency, which shifts to cold dread and horror upon discovering the burned bookstore, and finally settles into a grim, focused determination.', 'Acquires a garish tie-dye hoodie, a beanie, and sunglasses as a disguise.', NULL, 'Wakes up in the motel room at the start of the scene.', 'Father of Xavier. Seeks help from Becca. Remembers warnings from TJ and Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5751, 326, 507, 'ally', true, 'Reveals a history of extensive martial arts training (''kata'', ''kumite'', ''twenty years of muscle memory''). Suffers a severe stab wound through his left forearm, resulting in massive arterial bleeding.', 'Begins the scene weary, desperate, and ready to give up. Shifts to focused and reactive during the initial fight, then to pure rage after being stabbed, and finally to pained determination during the escape.', NULL, NULL, NULL, 'Father of Xavier, whom he protects. Becomes the target of the King in Yellow and his cultists.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5761, 326, 508, 'ally', true, 'Suffering from a grievous rebar wound to the stomach and a nearly-severed arm held by a tourniquet. He is pale, bleeding profusely, and delirious from blood loss.', 'Starts in a state of delirious agony and desperation, barely able to function. Transitions to immense relief and a profound feeling of safety after receiving care at the farmhouse.', NULL, NULL, NULL, 'Father of Xavier; patient to Maeve and Elara.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5772, 326, 509, 'ally', true, NULL, 'Experiences a profound shift from confusion and defiance to overwhelming grief and love upon recovering his memories of Jamie, culminating in a state of physical and emotional agony.', NULL, 'Wakes up screaming in the farmhouse after his consciousness is flooded with recovered memories.', 'Appears in the Dream plane after surviving his previous encounter.', 'Interacts with Nyarlathotep as a reluctant pawn, reconnects with Whitney as an ally, remembers his profound love for Jamie, and is cared for by his son Xavier upon waking.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5783, 326, 510, 'ally', true, 'Physically injured with stitches that pull and suffering from a fever that makes reality feel distant. He is compelled to tell his story before he loses consciousness.', 'Struggling with a chaotic jumble of new memories, but finds the resolve and determination to explain his true identity to his companions.', NULL, NULL, NULL, 'Acts as a patient and ward to Maeve and Elara, and a protective father-figure to Xavier, feeling an urgent need to inform them of a hidden reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5790, 326, 511, 'ally', true, NULL, 'Experiences profound grief, trauma, and a tight-throated sorrow while recounting the loss of his family and world. A flicker of hope emerges at the end of his story.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5803, 326, 512, 'ally', true, 'Physically wounded, with a throbbing arm and a feverish feeling, making him feel detached as he recounts a traumatic history.', 'A mix of pained exhaustion and grim determination to explain the past. He is reliving immense trauma and sorrow.', NULL, NULL, NULL, 'Narrator of the flashback. Twin flame of Velistra. One of the two primary components of The Prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5819, 326, 513, 'ally', true, 'Serves as the narrator for this scene, recounting the traumatic history of the prison, his lost love Velistra, and their infinite cycles of reincarnation. He reveals his past life as a marine named Hobart McComas III.', 'In deep physical and emotional pain, sorrowful and strained as he recalls past tragedies. His voice cracks when speaking of Velistra''s fate.', NULL, NULL, NULL, 'Lover of Velistra and her reincarnation Si Le Tra Vi. Primary victim of Yaldabaoth''s cycles. Informant to Xavier, Maeve, and Elara.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5835, 326, 514, 'ally', true, NULL, 'Grave and determined, struggling to articulate the complex and reality-shattering truth of his son''s origin and the nature of their prison.', NULL, NULL, NULL, 'Father to Xavier, former partner to the NPC construct of his wife. He is revealing the true nature of these relationships and their consequences.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5846, 326, 515, 'ally', true, NULL, 'Struggles with revelations about his reality, particularly the nature of his wife and children. He is in denial about the potential connection between Whitney and his unborn daughter, Hannah, reacting defensively when the possibility is raised.', NULL, NULL, NULL, 'Father of Xavier and the potential father of Hannah. Views Maeve and Elara as allies who possess more knowledge than he does. Confused by their knowing glances.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5855, 326, 516, 'ally', true, NULL, 'Focused and determined, proposing a high-stakes escape plan based on a dream, but also perceptive enough to realize Maeve and Elara are more than they seem.', NULL, NULL, NULL, 'Father of Xavier; seeking help from Maeve and Elara.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5866, 326, 517, 'ally', true, 'His arm and side are injured and bandaged, with stitches that pull when he moves.', 'Desperate, fearful, and exhausted, culminating in profound doubt about the ritual''s efficacy before being surprised by its success.', 'He is forced to remove all metal, including his wedding ring, and changes from jeans into sweatpants for the ritual.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5877, 326, 518, 'ally', true, NULL, 'Moves from boiling frustration and panic to desperate determination, focused solely on protecting Xavier and escaping through the portal.', 'His jacket sleeve is torn by a bullet.', 'Falls through the newly formed portal into the Akashic Realm.', NULL, 'Protagonist, father to Xavier, husband to the bounty hunter posing as his wife, and temporary ally of Maeve and Elara.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5890, 326, 519, 'ally', true, 'Sustained a bullet graze to his tricep during the escape from Etheris, leaving a bloody wound on his arm.', 'Cycles from disorientation and grief to cognitive impairment under attack, then to explosive anger at Lady Illkeserod, finally settling into a grim understanding of his and Jamie''s sacrifice.', 'His jacket sleeve is torn and soaked with blood from his wound.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5905, 326, 520, 'ally', true, NULL, 'Moves from contemplative and melancholic about his family''s fate to determined and resolute, insisting on facing his wife despite his lack of power.', NULL, NULL, NULL, 'Father to Xavier, former husband to the invading Angela. He feels a strong sense of responsibility for the chaos she is causing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5925, 326, 521, 'ally', true, 'Sustains severe claw wounds to his chest and arm from his wife, ripping open previously stitched injuries.', 'Moves from shared fear with Xavier to the desperate violence of a cornered animal, culminating in horrified shock at his son''s erasure.', 'Briefly acquires and uses a shotgun taken from an enemy agent.', NULL, NULL, 'Acts as a protector for his son, Xavier, and is the target of his warped wife''s attention. Fights alongside the Archives'' Defenders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5947, 326, 523, 'ally', true, NULL, 'Feels he has lost everything and shifts from grief to flat, defiant resolve. He is willing to sacrifice countless realities and restart a cosmic war to save one person, culminating in a nihilistic declaration: ''Let the whole fucking universe burn.''', NULL, NULL, NULL, 'Protagonist, motivated by the loss of his son Xavier and his desire to rescue Jamie. He opposes his allies'' plan to retreat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (5959, 326, 524, 'ally', true, 'His injuries have been magically healed by having the memory of them erased.', 'Resolved and determined to rescue Jamie, pushing past his fear to jump into the portal.', 'Receives the Veilwalker card from Benji.', 'Jumps into the portal to the substrate.', NULL, 'Receives healing from Lady Illkeserod and a gift from Benji. Is motivated by his love for Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6000, 326, 529, 'ally', true, 'Becomes covered in coarse, wet sand and bile after a violent landing.', 'Experiences extreme sensory disorientation and time distortion while falling, followed by shock and disgust upon landing among alien corpses, which shifts to determined dread when faced with his objective.', NULL, NULL, 'Is already present at the start of the scene, falling through the void after a portal closes.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6009, 326, 530, 'ally', true, NULL, 'Moves from desperate survival mode to shock and apprehension after witnessing the barrier''s power. He is physically battered and exhausted.', 'Acquired a Mi-Go spine as a makeshift weapon.', NULL, NULL, 'Receives remote guidance from Whitney and Benji. Is an enemy to the creatures of the horde.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6024, 326, 531, 'ally', true, NULL, 'Exhibits a mixture of audacity and fear, determined to confront a cosmic entity to further his mission.', NULL, NULL, NULL, 'Confronts and negotiates with Nyarlathotep to gain passage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6031, 326, 532, 'ally', true, NULL, 'Experiences a profound shock and horror upon learning the true origin of his children, moving from determined resolve to stunned silence. He clings to the Mi-Go spine as a grounding object in the surreal environment.', 'Is actively holding the Mi-Go Spine.', 'Is sent onward by Nyarlathotep down one of the five paths.', 'Enters the pyramid''s interior.', 'Learns that Whitney is his reincarnated daughter, Hannah, and that Xavier is his son, pulled from a dream plane by his own grief. His relationship with his ''NPC wife'' is framed as a hollow construct.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6040, 326, 533, 'ally', true, 'Physically compressed by the tunnels and then systematically dissolved layer by layer—skin, fat, muscle, organs, bones, and nervous system—until only a single spark of consciousness remains.', 'Moves from grim determination and dread during the descent to absolute, unimaginable agony and the loss of self during his dissolution.', 'Loses the Mi-Go spine as his hands dissolve.', NULL, NULL, 'Taunted by Nyarlathotep, supported by the voices of Whitney and Benji, and ultimately unmade by The Absolute Darkness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6054, 326, 534, 'ally', true, 'His physical body, memories, and identity have been completely dissolved. He now exists as a formless, single point of consciousness, a ''divine spark'', floating in a void.', 'Experiencing profound, cosmic isolation and a desperate struggle for continued existence, stripped of his identity but still possessing a core of will.', NULL, NULL, NULL, 'He is prey to the Nameless Mist and a target of the clinging Echoes of the Dissolved. He uses the Mad Piping of Azathoth as a navigational beacon.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6061, 326, 535, 'ally', true, 'His consciousness is reduced to a fraying point, a divine spark existing in the absolute darkness beneath the void. He realizes he is one half of the prison''s power source.', 'Begins in agony and confusion from perceiving Azathoth, then shifts to absolute recognition and determined love upon seeing Jamie''s spark, culminating in a willful act of union.', NULL, NULL, NULL, 'Recognizes his eternal, fundamental connection to Jamie (ብሪትለሪሌት) as the other half of his soul, forming a ''twin flame connection'' that powers the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6069, 326, 536, 'ally', true, NULL, 'Transitions from a state of restless, perpetual motion to one of calm, aware stillness. He is initially caught in a cycle of ''chasing'' but finds peace by listening to the natural world.', NULL, NULL, NULL, 'Initially dominated by ''The Restless Cycle'', he is guided towards ''Aware Existence'' by ''The Speaking Trees''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6074, 326, 537, 'ally', true, 'Returns to his 46-year-old body, which is overweight with thinning hair. He is physically weak and suffers from muscle atrophy after being in a medically-induced coma.', 'Begins disoriented and resigned to his physical limitations, then feels awe, awkward affection, staggering relief, and finally pained frustration at his body''s weakness.', NULL, NULL, 'Wakes up at the start of the scene in a hospital bed.', 'Reunites with his daughter, Whitney/Hannah, and his son, Xavier. Learns his wife, Jamie, is also safe and waiting for him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6084, 326, 538, 'ally', true, 'Remains in his 46-year-old human form despite being free from the prison''s constraints, a fact Jamie playfully points out.', 'Experiences a profound, cathartic reunion with Jamie, followed by the grief of learning his friends were lost and relief for those who were saved. He ends the scene with a sense of weary resolution.', NULL, NULL, NULL, 'Reunites with his true love, Jamie. Reconnects with his son Xavier and sister Whitney. Learns the fates of his friends from the Divine Council.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6104, 326, 539, 'ally', true, NULL, 'Experiences a profound sense of peace for the first time in lifetimes, reflecting on the perfection of his new family life despite their shared trauma.', NULL, NULL, NULL, 'Father to Hannah and Xavier, partner to Jamie. He acts as the affirming head of the new family unit.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6117, 326, 540, 'ally', true, NULL, 'Overwhelmed by the futility of their mission, calculating the impossible odds of saving everyone and feeling the weight of their limited success.', NULL, NULL, NULL, 'Receives comfort and a counter-perspective from Jamie. Is given urgent, personal news by Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6126, 326, 541, 'ally', true, NULL, 'Experiences a sharp, traumatic flashback upon seeing Todd, causing him to flinch. His focus intensifies and his pulse quickens when he learns of the lost cosmic seed.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (3769, 3522, 329, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'The focal point of Morgan''s initial presentation to the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-03-01 15:51:21.170966-05');
INSERT INTO public.entity_scene_appearances VALUES (6138, 326, 542, 'ally', true, NULL, 'Reflective and burdened by guilt over past actions and the slow progress of their mission. He is plagued by nightmares and spirals into hopelessness, questioning the cyclical nature of his own destructive patterns.', NULL, NULL, 'Already on the observation deck at the start of the scene.', 'Feels deep guilt towards Todd for killing him in a past life. Receives comfort and grounding from Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6148, 326, 543, 'ally', true, NULL, 'Shifts from focused observer to a state of grim realization, culminating in quiet determination as he proposes a radical new plan.', NULL, NULL, NULL, 'Partner to Jamie; leader and strategist for the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6164, 326, 544, 'ally', true, NULL, 'Torn between a desire to protect his family and a grim determination to complete his mission. He is firm and resolute in his decision to forbid his children from joining, but also expresses vulnerability and fear about the potential outcome.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6182, 326, 545, 'ally', true, 'His skin is now covered in protective symbols that feel like armor.', 'Torn between fear for the mission, love for his family, and a grim resolve to see it through. He carries the weight of a morally ambiguous objective.', 'Now bears protective wards painted on his skin.', 'Steps through the portal into Etheris to begin the mission.', NULL, 'Protagonist of the scene. Shares a deep, fearful bond with Jamie. Father to Xavier and Hannah, from whom he receives an emotional farewell.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6191, 326, 546, 'ally', true, NULL, 'Experiences confusion upon seeing the changed Akashic Realm, which turns to dread and terror when the portal''s absence is confirmed. He is fiercely protective of Benji, initially refusing to summon Nyarlathotep, but ultimately relents out of brutal necessity.', NULL, NULL, NULL, 'Protagonist. Feels tension from Jamie through their joined hands. Protective father-figure to Benji. Relies on Lady Osilari''s expertise.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6207, 326, 547, 'ally', true, NULL, 'Assertive and direct in his negotiation with Nyarlathotep, and fiercely protective when the god focuses on Jamie.', NULL, NULL, NULL, 'Leads the negotiation on behalf of the group. Acts as a protector for Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6213, 326, 548, 'ally', true, NULL, 'Initially tense and grimly familiar with the horrors of Etheris, his state shifts to one of resolute, desperate courage as he enacts the plan to be consumed. He is terrified but determined.', NULL, NULL, NULL, 'Leads the team, holds Jamie''s hand for support, trusts Benji''s navigation and Osilari''s protection. He is the primary target of Yaldabaoth''s taunts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6228, 326, 549, 'ally', true, 'Sustains significant injuries: a slash across his shoulder and a chunk of flesh ripped from his calf by the tentacles. He is choked into unconsciousness by Sam.', 'Moves from determined resolve to get to Sam, to shock and pain from the attacks, and finally to a confused, dual state of consciousness after being choked out.', NULL, 'Rendered unconscious by Sam, though his consciousness persists elsewhere.', 'Enters the chamber with the rest of the group.', 'Attempts to rescue Sam, leading to his own incapacitation. Fights alongside Lady Osilari, Benji, and Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6240, 326, 550, 'ally', true, NULL, 'Begins with caution and determination to save Sam. Becomes physically and mentally exhausted from destroying the parasites but remains resolute in his mission.', NULL, 'Is pulled back to reality along with Sam when the pasture realm collapses.', 'Enters the pasture realm to confront the source of Sam''s corruption.', NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6251, 326, 551, 'ally', true, NULL, 'Experiences physical trauma from the ritual''s shockwave (ruptured eardrums, bleeding) and acts as a comforting anchor for Jamie amidst the horror.', NULL, NULL, NULL, 'Acts as a protector and source of comfort for Jamie, holding her as they witness Sam''s destruction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6265, 326, 552, 'ally', true, NULL, 'Shifts from determined resolve to brutal desperation, culminating in shock, guilt, and horror at the violence he committed and witnessed.', NULL, NULL, NULL, 'Leads the group''s escape, protects Jamie and the Rescued Child, and feels immense guilt over the violence against the Freed Souls.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6299, 326, 554, 'ally', true, 'Volunteers to re-enter the cosmic prison as a ''shepherd''. He is designated ''Lord of Wisdom, King of Life'', with his divine powers being reawakened for the mission.', 'Moves from feeling overwhelmed by the scale of the problem to a quiet, firm resolve. He is committed to undertaking the mission with his family.', NULL, NULL, NULL, 'Husband of Jamie, father of Xavier and Hannah. He and his family form the core of the Shepherd Initiative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6319, 326, 555, 'ally', true, NULL, 'Contemplative and hesitant, but ultimately resolved. He weighs the difficulty of their mission against the necessity, moving from doubt to acceptance.', NULL, NULL, NULL, 'Partner to Jamie, father figure to Hannah and Xavier. Feels a profound responsibility towards the trapped souls due to his own experiences with captivity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6336, 326, 556, 'ally', true, 'Regains his original divine powers as Lord of Wisdom and King of Life, which will initially manifest as accelerated healing and flashes of intuition.', 'Resolved but feeling the immense weight of the decision, physically anchored by Jamie''s hand.', NULL, NULL, NULL, 'Part of The Family unit undergoing the ritual. Husband to Jamie, father to Xavier and Hannah.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6357, 326, 557, 'ally', true, 'Now living as a ''trust fund kid'' in a suburban Florida house with his family, tasked with a new mission of awakening others.', 'Experiences a rapid shift from contentment to terror upon realizing he''s back in the prison, followed by profound relief that his memories are intact, and finally settles into a sense of purpose.', NULL, NULL, 'Wakes up in bed at the start of the scene.', 'Husband to Jamie, father to Xavier and Hannah. Son of Benji and Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6370, 326, 558, 'ally', true, NULL, 'Contemplative and authoritative. He observes his family with affection before taking on a leadership role to establish the ground rules for their new, immortal lives.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6382, 326, 559, 'ally', true, NULL, 'Moves from intense anxiety and fear of his new reality being another dream to a state of calm resolution and readiness after channeling his experiences into a manuscript.', NULL, NULL, NULL, 'Husband to Jamie, father to Hannah and Xavier. He acts as the family''s chronicler and prepares to be a ''shepherd'' for humanity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6443, 326, 566, 'ally', true, 'Appears in the role of the author, reflecting on the arduous and complex process of writing ''The Towers of Elysium'' and its subsequent versions.', 'A mix of relief, exhaustion, frustration, and pride after completing a major creative project.', NULL, NULL, NULL, 'The creator of the narrative and its characters, addressing his readers directly.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6461, 326, 567, 'ally', true, NULL, 'Experiences creative frustration when writing himself into a corner, followed by a moment of inspiration, and finally clarity regarding the narrative''s underlying rules and direction.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (3810, 3522, 333, 'neutral', true, NULL, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:45:05.519972-05', '2026-03-01 15:51:21.170966-05');
INSERT INTO public.entity_scene_appearances VALUES (6476, 326, 568, 'ally', true, 'Acts as the author and narrator of this meta-commentary, explaining his world-building and production challenges.', 'Pragmatic and determined, balancing creative integrity with the harsh realities of financial limitation. He expresses a clear priority for reader access over personal profit.', NULL, NULL, NULL, 'The creator of ''The Books'' and ''The Cosmogonic Framework''. He feels a kinship with his protagonist''s poverty and is motivated by ''The Readers''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6502, 326, 570, 'ally', true, 'His memory is now fragmented due to catastrophic events and reality collapses he caused. His very existence is a feedback loop threatening the stability of the prison.', NULL, NULL, NULL, NULL, 'Twin flame of Jamie, father of Xavier, and ally of Whitney. He is the central anomaly in the system.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6579, 326, 577, 'ally', true, 'Emerges from the corpse of a war angel covered in its gore.', 'Moves from disorientation to a white-hot rage and desperate love for Velistra, leading him to break cosmic law. This shifts to shock and the dawning horror of the consequences of his actions when he is confronted by Lady Illkeserod.', NULL, NULL, NULL, 'His love for Velistra is the catalyst for his reality-breaking actions. His focus on her inadvertently leads to Benji''s position being overrun, earning him the absolute fury of Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6595, 326, 578, 'neutral', true, NULL, 'Passively observing and experiencing Lady Illkeserod''s traumatic memories as if they were his own.', NULL, NULL, 'The scene is a memory being experienced by Stephen.', 'Witness to the origin of Lady Illkeserod.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6608, 326, 579, 'ally', true, NULL, 'Returns to his body feeling slammed and disoriented. He then experiences the horror of the hunt, the psychic assault of witnessing Benji''s torture, and finally a dawning, terrible understanding of the solution.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6529, 326, 572, 'neutral', true, NULL, NULL, NULL, NULL, NULL, 'Created by Yaldabaoth, but given life by Sophia. He is the first ''battery'' in Yaldabaoth''s soul farm.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (6535, 326, 573, 'enemy', true, 'A simple, human male created from mud. He is described as naked and unashamed due to ignorance rather than innocence, lacking any true consciousness.', 'Operates on base recognition and dull hunger. Shows possessiveness towards Lilith and confusion when she disobeys his simple commands.', NULL, 'Left behind in the garden when Lilith is banished.', 'Present at Lilith''s awakening.', 'Intended mate for Lilith. He is a completely obedient and mindless creation of Yaldabaoth.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.entity_scene_appearances VALUES (3554, 3598, 312, 'enemy', true, NULL, NULL, NULL, 'Presumably destroyed along with the station.', 'Active at the start of the battle, defending the station.', 'A defensive component of S Corp''s Pluto Station.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-03-01 15:51:21.170966-05');
