INSERT INTO public.entity_scene_appearances VALUES (3602, 1525, 316, 'enemy', true, NULL, NULL, NULL, NULL, NULL, 'Commands ''The Worker'' to struggle and bleed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-03-01 15:51:21.170966-05');
INSERT INTO public.entity_scene_appearances VALUES (3967, 1525, 347, 'neutral', false, NULL, NULL, NULL, NULL, NULL, 'A resource the protagonist can influence to enact Madam O''s plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:58:48.646912-05', '2026-03-01 15:51:21.170966-05');
