INSERT INTO public.entity_scene_appearances VALUES (595, 201, 38, 'ally', true, NULL, NULL, NULL, NULL, NULL, 'Provide the only visual tool against the forest''s darkness, but prove inadequate to the task.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:53:14.875679-05', '2026-03-01 15:51:21.170966-05');
