INSERT INTO public.location_scene_appearances VALUES (8, 8, 7, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:00:36.404425-05', '2026-02-27 13:00:36.404425-05');
INSERT INTO public.location_scene_appearances VALUES (9, 9, 8, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:02:24.372659-05', '2026-02-27 13:02:24.372659-05');
INSERT INTO public.location_scene_appearances VALUES (10, 10, 8, 'Microwave clock at 6:45 AM casting soft digital glow; breakfast plates and tamagoyaki arranged; counter as social hub', 'Quiet morning punctuated by gentle conversation, footsteps, and family laughter', 'Fresh coffee aroma dancing with delicate sweetness of miso soup', 'Warm kitchen environment contrasting with frost-kissed cold outside', 'Domestic sanctuary blending peaceful morning routine with intellectual curiosity about external mystery', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:06:31.037788-05', '2026-02-27 13:06:31.037788-05');
INSERT INTO public.location_scene_appearances VALUES (11, 11, 9, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:07:03.395028-05', '2026-02-27 13:07:03.395028-05');
INSERT INTO public.location_scene_appearances VALUES (12, 12, 10, 'Serene darkness outside; interior illuminated by family presence and warmth of home.', NULL, 'Scent of freshly baked bread embracing upon entry.', 'Warmth of family embrace; soft greeting; couch providing collapse and relief.', 'Transition from surreal, absurd workday clarity to fragile night stillness and temporary peace.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:08:02.245362-05', '2026-02-27 13:08:02.245362-05');
INSERT INTO public.location_scene_appearances VALUES (13, 13, 11, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:08:28.833727-05', '2026-02-27 13:08:28.833727-05');
INSERT INTO public.location_scene_appearances VALUES (14, 14, 11, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:10:59.759386-05', '2026-02-27 13:10:59.759386-05');
INSERT INTO public.location_scene_appearances VALUES (15, 15, 12, 'Unnaturally still night with dim flickering streetlights casting eerie shadows over graffiti-streaked walls; looming warehouse doors ahead', 'Silent, oppressive stillness', NULL, NULL, 'Ominous, foreboding; charged with anticipation and danger', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:11:41.065574-05', '2026-02-27 13:11:41.065574-05');
INSERT INTO public.location_scene_appearances VALUES (16, 8, 13, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:14.109668-05', '2026-02-27 13:12:14.109668-05');
INSERT INTO public.location_scene_appearances VALUES (17, 17, 14, 'Lighting remains the same but feels harsher as the friends'' expressions shift.', 'Laughter fades; forced smiles replace genuine warmth.', NULL, 'Physical and emotional distance increases as friends shift uncomfortably.', 'Shifts from safe and inviting to strained and isolating.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.location_scene_appearances VALUES (18, 18, 15, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.location_scene_appearances VALUES (19, 19, 16, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.location_scene_appearances VALUES (20, 20, 17, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:36.084483-05', '2026-02-27 13:14:36.084483-05');
INSERT INTO public.location_scene_appearances VALUES (21, 21, 18, 'Flooded with ethereal glare from lightning; surfaces melting like wax; colors and scents swirling in vortex.', 'Roaring freight train; blinding flash of thunder breaking silence.', NULL, 'Room shaking; world quivering and cresting; senses dissolving.', NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.location_scene_appearances VALUES (22, 22, 19, 'Workshop becomes swollen with nanite manifestations before vanishing; blank pages glow with urgency; cornfield ripples with otherworldly energy.', 'Wind''s song changes to pulsing electricity; susurration creeps into consciousness like virus.', NULL, NULL, 'Energy building viscerally ready to explode; tempest brewing inside Protagonist mirrored in external environment.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.location_scene_appearances VALUES (23, 23, 20, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:16:09.683429-05', '2026-02-27 13:16:09.683429-05');
INSERT INTO public.location_scene_appearances VALUES (24, 21, 21, NULL, 'Filled with the blare of an alarm and insistent beeping that shatters the morning silence.', NULL, NULL, 'Jarring transition from dream-state tranquility to urgent, disorienting wakefulness.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:16:43.178301-05', '2026-02-27 13:16:43.178301-05');
INSERT INTO public.location_scene_appearances VALUES (25, 25, 22, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:06.05021-05', '2026-02-27 13:17:06.05021-05');
INSERT INTO public.location_scene_appearances VALUES (26, 26, 23, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:17:55.447677-05', '2026-02-27 13:17:55.447677-05');
INSERT INTO public.location_scene_appearances VALUES (27, 27, 24, 'Transition from dark barn interior lit only by blue engine glow to golden dawn breaking through cracks; fields become vibrant with flowers and bees; sky shifts from dark to pink-orange hues.', 'From electrical sounds to silence to bee symphony; protagonist''s screams for help drown in buzzing.', 'From metallic to floral; cloying nectar scent becomes sickly and suffocating.', 'From burning heat to cool morning dew to sharp stinging sensations.', 'Shifts from sanctuary and refuge to existential limbo to wrathful natural trap; from human achievement to nature''s dominion.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:23:10.755388-05', '2026-02-27 13:23:10.755388-05');
INSERT INTO public.location_scene_appearances VALUES (28, 28, 25, 'Midday light setting (not typical morning); intimate spaces giving way to external pressure through technology.', NULL, NULL, NULL, 'Brief moments of hope and wonder quickly shattered by external workplace demands; atmosphere shifts from contemplative to suffocating.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:24:09.210121-05', '2026-02-27 13:24:09.210121-05');
INSERT INTO public.location_scene_appearances VALUES (29, 29, 26, 'Office remains bustling with activity despite the Narrator''s internal turmoil; park bench area characterized by long shadows and oppressive heat.', 'Office hums with keyboard clatter and chatter; park is quieter, allowing for intimate conversation.', NULL, NULL, 'Stark contrast between the ''lighthearted'' office atmosphere and the Narrator''s growing sense of dread and unease.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:46:56.316269-05', '2026-02-27 13:46:56.316269-05');
INSERT INTO public.location_scene_appearances VALUES (30, 30, 27, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:47:35.580676-05', '2026-02-27 13:47:35.580676-05');
INSERT INTO public.location_scene_appearances VALUES (31, 31, 28, 'Warm and domestic; laundry room, bathroom, living room with couch and TV, kitchen with table and computer; glow of screen transforming spaces.', NULL, NULL, NULL, 'Initially tense due to unexplained grease stains; gradually shifts to warmth and comfort during family interaction and dinner; underlying current of unease about reality boundaries persists.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:48:16.546021-05', '2026-02-27 13:48:16.546021-05');
INSERT INTO public.location_scene_appearances VALUES (32, 32, 29, 'Evolves from cozy entertainment space with blankets to chaotic staging ground with scattered gear to neatly organized backpacks and supplies arranged for departure.', NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:48:56.287326-05', '2026-02-27 13:48:56.287326-05');
INSERT INTO public.location_scene_appearances VALUES (33, 21, 30, 'Evening darkness; intimate confines.', 'Silent except for internal mental noise.', NULL, NULL, 'Weighted with tension; a liminal space between comfort and dread, day and night, two conflicting emotional pulls.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:49:27.981808-05', '2026-02-27 13:49:27.981808-05');
INSERT INTO public.location_scene_appearances VALUES (34, 34, 31, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:49:48.022183-05', '2026-02-27 13:49:48.022183-05');
INSERT INTO public.location_scene_appearances VALUES (35, 35, 32, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:07.05205-05', '2026-02-27 13:50:07.05205-05');
INSERT INTO public.location_scene_appearances VALUES (36, 36, 33, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:50:40.783929-05', '2026-02-27 13:50:40.783929-05');
INSERT INTO public.location_scene_appearances VALUES (37, 37, 34, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:51:29.102752-05', '2026-02-27 13:51:29.102752-05');
INSERT INTO public.location_scene_appearances VALUES (69, 69, 63, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:22:10.64191-05', '2026-02-27 14:22:10.64191-05');
INSERT INTO public.location_scene_appearances VALUES (70, 70, 64, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:23:07.257785-05', '2026-02-27 14:23:07.257785-05');
INSERT INTO public.location_scene_appearances VALUES (71, 71, 65, NULL, NULL, NULL, NULL, 'The tension breaks at the end, replaced by a quiet, emotional atmosphere of reconciliation as the computer is turned off.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:24:04.5571-05', '2026-02-27 14:24:04.5571-05');
INSERT INTO public.location_scene_appearances VALUES (72, 31, 66, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.location_scene_appearances VALUES (73, 73, 67, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.location_scene_appearances VALUES (77, 69, 71, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:29:52.894785-05', '2026-02-27 14:29:52.894785-05');
INSERT INTO public.location_scene_appearances VALUES (38, 38, 35, 'Shadows dancing across scouts'' faces; spectral orange glow from dying campfire illuminating the gathering; the fire briefly flares in response to the story.', 'Occasional pops of gas escaping from firewood; gentle breeze stirring tree branches and causing them to creak softly; the scoutmaster''s low, measured voice; silence filled with nervous tension.', NULL, 'Cool air unexpectedly sharp against skin; the weight of the story pressing down on the protagonist.', 'Heavy, charged atmosphere of narrative intensity; the forest seems to listen; faint hum from the depths becomes louder and more present to the protagonist''s awareness.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:51:55.298684-05', '2026-02-27 13:51:55.298684-05');
INSERT INTO public.location_scene_appearances VALUES (39, 39, 36, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:52:24.483424-05', '2026-02-27 13:52:24.483424-05');
INSERT INTO public.location_scene_appearances VALUES (40, 40, 37, 'Sun bleeds lingering light into cooling sky; darkness deepens as evening progresses; clearing becomes less joyful as groups report in.', NULL, NULL, NULL, 'Cheerful triumph gives way to creeping unease; crystallizes into dread and horror upon confirmation of missing patrol.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:52:44.252541-05', '2026-02-27 13:52:44.252541-05');
INSERT INTO public.location_scene_appearances VALUES (41, 41, 38, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:53:14.875679-05', '2026-02-27 13:53:14.875679-05');
INSERT INTO public.location_scene_appearances VALUES (42, 42, 39, 'Campfire dwindled to embers; shadows dancing and shifting with restless movement of branches; circle of firelight surrounded by encroaching darkness.', 'Crackle of fire providing comforting backdrop; snaps of twigs, crunches of leaves beyond the circle of light heightening vigilance.', NULL, 'Fading warmth of the fire barely holding back the night''s chill; sturdy log beneath the narrator.', 'Fragile calm masking underlying unease; jarring contrast between scouts'' laughter and games versus narrator''s hypervigilance and dread.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:54:00.920159-05', '2026-02-27 13:54:00.920159-05');
INSERT INTO public.location_scene_appearances VALUES (43, 43, 40, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:54:34.864627-05', '2026-02-27 13:54:34.864627-05');
INSERT INTO public.location_scene_appearances VALUES (44, 44, 41, 'Fog pierced by faint glow of device; branches twist into cage formations; ground heaves and crumbles; tree shudders; explosion of light before final collapse.', 'Whispers transform to cacophony of screams, then to single shrieking note, culminating in absolute silence.', NULL, 'Ground beneath protagonist shifts from solid to heaving; air thickens like syrup; branches constrict; device radiates contradictory icy heat.', 'Shifts from throbbing with otherworldly energy to violent eruption to suffocating silence; atmosphere of malevolent resistance and containment.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:55:25.624876-05', '2026-02-27 13:55:25.624876-05');
INSERT INTO public.location_scene_appearances VALUES (45, 42, 42, 'Morning sun streaming through the trees; protagonist discovered near the edge of the campsite, surrounded by serene forest setting.', 'Cheerful birdsong; heavy footsteps on forest floor; rustling of pants; aroma of brewing cold pressed coffee wafting through camp.', 'Unmistakable aroma of brewing cold pressed coffee leading back to camp.', NULL, 'Serene, peaceful morning contrasting sharply with protagonist''s internal terror and exhaustion.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:56:07.472375-05', '2026-02-27 13:56:07.472375-05');
INSERT INTO public.location_scene_appearances VALUES (46, 46, 43, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:56:38.884369-05', '2026-02-27 13:56:38.884369-05');
INSERT INTO public.location_scene_appearances VALUES (48, 48, 45, NULL, NULL, NULL, NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:57:58.322291-05', '2026-02-27 13:57:58.322291-05');
INSERT INTO public.location_scene_appearances VALUES (49, 26, 46, 'Fluorescent lights flicker cold and sterile; walls shift and close in; becomes execution chamber; hollow stares of colleagues lining the halls.', 'Wailing and screaming muted by closed door; rhythmic thudding of COO''s movement; door opening brings ominous silence; profanity-laden tirade; squealing chair; fluorescent buzz.', 'Mugginess hits upon exit as slap.', 'Iron grips of security on arms; mechanical precision; dehumanizing force.', 'Ominous beat; air before consuming storm; suffocating gravity; cloak of betrayal settles; cold indifference.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:58:32.087628-05', '2026-02-27 13:58:32.087628-05');
INSERT INTO public.location_scene_appearances VALUES (47, 21, 44, NULL, 'The peaceful sound of steady breathing is shattered by the ''shrill cry'' of an alarm.', NULL, NULL, 'The room''s atmosphere has shifted from a place of rest to one of tension and foreboding, where the boundaries between dream and reality feel thin and dread is a palpable presence.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:57:17.721641-05', '2026-02-27 14:04:23.20534-05');
