INSERT INTO public.location_scene_appearances VALUES (96, 69, 90, 'The ambient glow from the Infinitron vanishes, plunging the machine into darkness, before returning brighter than before.', 'The constant hum of the machine ceases abruptly, creating a stark silence that is later broken by the machine roaring back to life.', NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:46:53.425867-05', '2026-02-27 14:46:53.425867-05');
INSERT INTO public.location_scene_appearances VALUES (97, 97, 91, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:47:49.746694-05', '2026-02-27 14:47:49.746694-05');
INSERT INTO public.location_scene_appearances VALUES (98, 98, 92, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:48:44.800966-05', '2026-02-27 14:48:44.800966-05');
INSERT INTO public.location_scene_appearances VALUES (99, 69, 93, 'Faint light begins to peek around the edges of the garage door, signaling the approach of dawn.', 'The space becomes filled with the sound of laughter.', NULL, NULL, 'The atmosphere transforms dramatically from a ''pressure cooker of unanswerable questions'' to one of fun, joy, and warmth.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:49:34.225008-05', '2026-02-27 14:49:34.225008-05');
INSERT INTO public.location_scene_appearances VALUES (100, 69, 94, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:50:45.736917-05', '2026-02-27 14:50:45.736917-05');
INSERT INTO public.location_scene_appearances VALUES (101, 101, 95, 'The space is dominated by the darkened screen of the powered-down Infinitron.', 'The constant hum of the Infinitron is replaced by a profound silence.', NULL, NULL, 'The atmosphere shifts from one of determined problem-solving and cautious hope to one of shared frustration, wry humor, and finally, quiet resignation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:51:40.884139-05', '2026-02-27 14:51:40.884139-05');
INSERT INTO public.location_scene_appearances VALUES (102, 102, 96, NULL, 'The environment shifts from tense, quiet discussion to the hum of the Infinitron and the pinging of alerts, before falling into a stunned silence.', NULL, NULL, 'The atmosphere transforms from one of heavy tension and financial stress to one of shocked disbelief and cautious optimism after the family''s sudden windfall.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:52:26.990127-05', '2026-02-27 14:52:26.990127-05');
INSERT INTO public.location_scene_appearances VALUES (103, 69, 97, 'The space is illuminated by the faint, rainbow-casting glow of the Infinitron. In a corner sit the scorched remains of a motor, a testament to past failures.', 'Filled with the quiet, constant hum of the Eternal Engine, later joined by the sounds of the Infinitron processing data.', NULL, NULL, 'The atmosphere is a blend of domestic tension and high-concept scientific ambition. It''s a place of both groundbreaking potential and frustrating limitations.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:53:45.224779-05', '2026-02-27 14:53:45.224779-05');
INSERT INTO public.location_scene_appearances VALUES (104, 104, 98, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:54:32.987398-05', '2026-02-27 14:54:32.987398-05');
INSERT INTO public.location_scene_appearances VALUES (105, 105, 99, 'Has morphed into a ''disaster zone'' - a chaotic mix of half-finished experiments, scorched wires, chemical bottles, improvised materials, and precariously balanced glassware.', 'Initially filled with violent hissing and popping from the failed experiment, later replaced by the controlled fizzing of the successful one.', 'Smells of scorched components and choking smoke, which later gives way to the pungent scent of chloroform from the new experiment.', NULL, 'Shifts from a tense and dangerous environment to one of focused collaboration and eventual success.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:15.442117-05', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.location_scene_appearances VALUES (106, 106, 100, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
