INSERT INTO public.location_scene_appearances VALUES (280, 280, 271, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:46:19.829014-05', '2026-02-27 20:46:19.829014-05');
INSERT INTO public.location_scene_appearances VALUES (112, 21, 106, 'The room is illuminated by light spilling through the window, revealing tangled sheets on the bed.', 'The room is still and quiet, a stark contrast to the screaming from the previous night.', NULL, NULL, 'The room, previously a place of rest, is now charged with the aftershocks of a terrifying nightmare and the frantic energy of a world-changing revelation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.location_scene_appearances VALUES (434, 434, 422, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.location_scene_appearances VALUES (435, 435, 423, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.location_scene_appearances VALUES (113, 113, 107, 'The three devices—Eternal Engine, Infinitron, and Superconducting Wires—sit inertly, described as ''silent and taunting''.', 'The low hum of the Eternal Engine and the pulsing sounds of the Infinitron are present.', NULL, NULL, 'The atmosphere is thick with frustration and a sense of stagnation, which is later shattered by the protagonist''s abrupt awakening.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.location_scene_appearances VALUES (114, 10, 108, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.location_scene_appearances VALUES (115, 115, 109, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.location_scene_appearances VALUES (116, 69, 110, 'Transformed from a workshop into a chaotic ruin. The space is strewn with debris, filled with smoke, and its very walls have been twisted by warped reality, now appearing as a ''maelstrom of jagged light and shadow''.', 'The aftermath is filled with an eerie stillness, punctuated only by the ringing in the protagonist''s ears.', 'The air is thick with the smell of acrid smoke.', 'The floor is covered in debris.', 'Shifted from a place of scientific endeavor to a site of a terrifying, reality-bending event, filled with an eerie and tense stillness.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.location_scene_appearances VALUES (117, 69, 111, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
