INSERT INTO public.location_scene_appearances VALUES (120, 120, 114, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:47.945044-05', '2026-02-27 15:08:47.945044-05');
INSERT INTO public.location_scene_appearances VALUES (121, 84, 115, 'The paneling ripples and warps into leering masks before the entire location dissolves and is replaced by the Crimson Landscape.', 'A sharp, metallic shriek and a powerful pounding overwhelm all other sounds.', 'The familiar stink dissolves away.', NULL, 'The atmosphere shifts from tense domestic horror to cosmic, reality-bending terror.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
