INSERT INTO public.location_scene_appearances VALUES (135, 135, 129, NULL, NULL, NULL, NULL, 'The atmosphere shifts dramatically throughout the scene, starting with the quiet tension of creative frustration, moving to collaborative excitement and relief, and finally crashing into a state of sudden, chilling dread.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:21:14.207833-05', '2026-02-27 15:21:14.207833-05');
