INSERT INTO public.location_scene_appearances VALUES (149, 149, 143, 'The dining room corner has been converted into a ''cardboard kingdom'' for the son''s work. The garage, formerly a science lab, is now a chaotic fulfillment center packed with shelves, merchandise, shipping boxes, and packing peanuts.', 'The environment is filled with new sounds: the son''s loud EDM music, his excited shouting, the steady hum of Matter Replicators, and the rustle of packing materials.', NULL, 'The garage is described as a ''sauna of packing material,'' indicating it is hot, humid, and cluttered.', 'The atmosphere has shifted from one of scientific experimentation to one of bustling, chaotic, and energetic family-run commerce.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:34:52.287488-05', '2026-02-27 15:34:52.287488-05');
