INSERT INTO public.location_scene_appearances VALUES (175, 175, 169, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:59:05.452443-05', '2026-02-27 15:59:05.452443-05');
INSERT INTO public.location_scene_appearances VALUES (176, 176, 170, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 16:00:11.118498-05', '2026-02-27 16:00:11.118498-05');
INSERT INTO public.location_scene_appearances VALUES (177, 177, 171, 'The lab now contains two large, intricate gateway structures that house a shimmering, stable wormhole.', 'The sounds of crackling energy and pops from failures are replaced by a constant, sonorous, resonant hum from the stable portal.', 'The air is filled with the sharp, lingering smell of burnt ozone from the portal activations.', NULL, 'The atmosphere shifts dramatically from one of intense frustration and relentless effort to one of awe, triumphant success, and playful discovery.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:00:57.945069-05', '2026-02-27 16:00:57.945069-05');
INSERT INTO public.location_scene_appearances VALUES (178, 178, 172, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 16:01:50.513606-05', '2026-02-27 16:01:50.513606-05');
