INSERT INTO public.location_scene_appearances VALUES (181, 78, 175, 'The first light of dawn is creeping through the window. A newly created portal casts a soft, shimmering glow in the room.', 'The air is filled with the synchronized hum of nanites.', NULL, NULL, 'The atmosphere has shifted from one of clandestine work to one of triumphant anticipation and culmination.', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:04:25.733696-05', '2026-02-27 16:04:25.733696-05');
