INSERT INTO public.location_scene_appearances VALUES (185, 185, 179, NULL, NULL, NULL, NULL, 'Oppressive and siege-like; the familiar space now feels as though the walls are closing in tighter with each new safeguard, transforming from a sanctuary into a war room.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:20:25.637792-05', '2026-02-27 19:20:25.637792-05');
