INSERT INTO public.location_scene_appearances VALUES (199, 199, 190, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:36:31.08963-05', '2026-02-27 19:36:31.08963-05');
INSERT INTO public.location_scene_appearances VALUES (201, 201, 192, 'The interior is rapidly and radically transformed by nanites. Windows are replaced with one-way security glass, walls shift, floors gain new textures, and empty spaces become fully designed lounges and workstations.', 'The eerie silence is replaced by the implied sounds of the nanite construction, and then the potential hum of a functional headquarters.', NULL, NULL, 'The atmosphere shifts dramatically from an unsettling, eerie, ''liminal space'' to one brimming with potential and purpose. It evolves from a lifeless void into the ''heart of an empire''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:38:11.456659-05', '2026-02-27 19:38:11.456659-05');
INSERT INTO public.location_scene_appearances VALUES (202, 201, 193, 'The interior is no longer empty. It is now filled with sleek, modern offices, innovative labs, lush jungle plants, and constantly moving human-like robots. Deep below, new subfloors house glowing ERB gateways.', 'The former silence is replaced by the simulated sounds of a bustling corporate environment: the quiet hum of machinery, the movement of robots, and the low thrum of the gateways.', 'The smell of dust and disuse is gone, replaced by the clean scent of a modern office, the faint aroma of foliage, and a hint of ozone near the subfloors.', NULL, 'The atmosphere has shifted from empty and dormant to one of vibrant, albeit artificial, energy and immense, covert power. It feels like the nerve center of a global empire.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:39:02.867922-05', '2026-02-27 19:39:02.867922-05');
