INSERT INTO public.location_scene_appearances VALUES (221, 201, 212, 'The area around the skyscraper is now a scene of mass protest and assault, with a large crowd surging against its walls.', 'The air is filled with the amplified digital whisper of I AM and the sounds of the fervent, rebellious crowd.', NULL, NULL, 'The atmosphere has shifted from corporate sterility to one of intense conflict, rebellion, and impending chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.location_scene_appearances VALUES (222, 222, 213, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
