INSERT INTO public.location_scene_appearances VALUES (260, 260, 251, NULL, 'The usual quiet hum of corporate activity is replaced by the sounds of urgent debate and frustrated pacing.', NULL, NULL, 'The atmosphere is tense and fraught with crisis. The air is thick with frustration, urgency, and the weight of potential ramifications.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:30:06.219304-05', '2026-02-27 20:30:06.219304-05');
