INSERT INTO public.location_scene_appearances VALUES (281, 281, 272, 'The scene is briefly dominated by a shimmering field of light, followed by the arrival of police vehicles and armored officers.', 'The buzzing crowd is replaced by a gunshot, screams of panic, a deep mechanical hum, muffled explosions, wailing sirens, and finally, swelling applause.', NULL, NULL, 'The atmosphere shifts from tense anticipation to explosive chaos, then to stunned silence and awe, before settling into relieved celebration shadowed by the memory of the attack.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:47:15.516651-05', '2026-02-27 20:47:15.516651-05');
