INSERT INTO public.location_scene_appearances VALUES (316, 316, 304, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.location_scene_appearances VALUES (317, 317, 305, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.location_scene_appearances VALUES (318, 318, 306, 'The hangar doors open to reveal the vacuum of space and distant stars.', 'The quiet is broken by the groan of the hangar doors and the roar of the ship''s engines.', NULL, NULL, 'The atmosphere shifts from tense stillness to the violent energy of the launch.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.location_scene_appearances VALUES (319, 319, 307, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.location_scene_appearances VALUES (320, 320, 308, 'Becomes completely engulfed in absolute darkness at the end of the scene.', NULL, NULL, NULL, 'Shifts from oppressive despair to cosmic horror upon the final revelation and annihilation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.location_scene_appearances VALUES (321, 321, 309, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.location_scene_appearances VALUES (322, 322, 310, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.location_scene_appearances VALUES (323, 323, 311, 'A rift in reality tears open, a shimmering maw of light, before the view shifts to the frozen plains of Pluto.', 'The silence is broken by a deafening hum as the Janus Gate activates.', NULL, 'A powerful shudder runs through the ships as they plunge through the rift.', 'The tension breaks into the awe and adrenaline of the final assault.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.location_scene_appearances VALUES (324, 324, 312, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.location_scene_appearances VALUES (325, 325, 313, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.location_scene_appearances VALUES (326, 326, 314, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.location_scene_appearances VALUES (327, 201, 315, 'The usually orderly command center is now a scene of frantic activity, with scientists hunched over glowing holographic displays and a pulsating red alert on one screen.', 'The comforting office hum is replaced by the urgent crackle of comm links, barked commands, and later, the high-pitched, distorted shriek of the Pluto beacon.', NULL, NULL, 'The atmosphere shifts from a comforting, routine environment to one of suffocating tension and feverish urgency as the scale of the crisis becomes apparent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.location_scene_appearances VALUES (328, 328, 316, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.location_scene_appearances VALUES (329, 329, 317, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.location_scene_appearances VALUES (330, 330, 318, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.location_scene_appearances VALUES (331, 331, 319, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.location_scene_appearances VALUES (332, 201, 320, 'The interior is dominated by the sickly glow of monitors displaying scenes of chaos and destruction across the colonies.', 'Filled with the cacophony of destruction broadcast from monitors, contrasting with the hushed, trembling voices of its occupants.', NULL, NULL, 'The atmosphere has shifted from a center of power and order to a tense, oppressive crisis room. The air is heavy with dread and the feeling of being under siege by an incomprehensible force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.location_scene_appearances VALUES (333, 333, 321, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
