INSERT INTO public.location_scene_appearances VALUES (358, 358, 346, 'Is filled with incandescent stars and newly formed planets by the end of the scene.', NULL, NULL, NULL, 'Transforms from a prison of guilt into a testament of hope and renewal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:57:56.600542-05', '2026-02-28 17:57:56.600542-05');
