INSERT INTO public.location_scene_appearances VALUES (360, 128, 348, 'The void is described as a ''boundless expanse'', emphasizing its infinite and featureless nature as the protagonist''s operational space.', NULL, NULL, NULL, 'The atmosphere is one of profound solitude and contemplation. It serves as both a prison of isolation and a canvas for the protagonist''s work.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:59:50.546184-05', '2026-02-28 17:59:50.546184-05');
