INSERT INTO public.location_scene_appearances VALUES (471, 471, 459, NULL, NULL, NULL, NULL, 'The void begins to thrum with awareness as Yaldabaoth''s consciousness returns.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:17:35.721493-05', '2026-02-28 22:17:35.721493-05');
INSERT INTO public.location_scene_appearances VALUES (472, 472, 460, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:18:26.71525-05', '2026-02-28 22:18:26.71525-05');
