INSERT INTO public.location_scene_appearances VALUES (512, 512, 498, 'The marble floor is cracked from the force of Benji and Whitney''s violent arrival.', 'The sound of a heavy impact as two bodies crash into the floor.', NULL, NULL, 'The atmosphere shifts from placid to one of urgent care and debriefing upon the arrivals'' appearance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
INSERT INTO public.location_scene_appearances VALUES (513, 513, 499, 'The space is filled with wreckage and debris, which the characters kick into corners to make space. Fading photographs hang on the walls.', 'The walls emit a faint, constant hum, suggesting reality itself is unstable in this location.', 'The air stinks of mushrooms and burnt candle wax.', 'The room feels colder as Patrick recounts the plane crash.', 'The atmosphere is tense and unstable, described as a place where ''reality hadn’t decided if it was staying or not''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
