INSERT INTO public.location_scene_appearances VALUES (537, 537, 523, 'The area is now filled with the smoking ruins of a town. A specific spot on the stone is stained with Xavier''s blood. Later, the ground ripples and a green, pudding-like tear in reality opens.', NULL, 'The smell of smoke hangs in the air from the ruins.', 'The air grows cold with the arrival of Nyarlathotep''s presence.', 'The atmosphere shifts from one of desperate urgency to grim, nihilistic resolve, and finally to an eerie, alien tension as a cosmic entity manifests.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.location_scene_appearances VALUES (538, 538, 524, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
