INSERT INTO public.location_scene_appearances VALUES (559, 559, 545, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.location_scene_appearances VALUES (560, 533, 546, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.location_scene_appearances VALUES (561, 533, 547, 'The space ripples and shadows coalesce to form Nyarlathotep. Later, reality itself bends and threatens to tear from the tension between the two gods.', 'Filled with unnatural sounds, including wet percussive pops, a sound like a hurricane rewinding, and Nyarlathotep''s wrongly echoing laughter.', NULL, NULL, 'The air grows thick, heavy, and crackles with tension during the confrontation between Lady Illkeserod and Nyarlathotep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.location_scene_appearances VALUES (562, 562, 548, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.location_scene_appearances VALUES (563, 563, 549, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.location_scene_appearances VALUES (564, 564, 550, 'At the scene''s conclusion, the entire realm fractures. Cracks spread through the ground and sky, and the fabric of the inner world breaks apart before it collapses entirely.', NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.location_scene_appearances VALUES (565, 565, 551, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.location_scene_appearances VALUES (566, 128, 552, 'The vast emptiness of Yaldabaoth''s corpse is first consumed by an expanding sphere of crystalline fractal geometry, then filled with trillions of panicked, translucent souls. Finally, the entire realm shatters and reforms into a normalized, albeit scarred, reality.', 'The environment fills with the overwhelming sound of trillions of panicked voices, followed by the psychic pressure of the fractal wave, and finally a deafening silence after the portal closes.', NULL, 'A psychic pressure wave from the expanding seed makes the body ache. A powerful shockwave from Etheris shattering makes teeth rattle and bones ache.', 'The atmosphere shifts from tense anticipation to pure, unfiltered chaos and desperation, culminating in a shockwave of cosmic realignment and the horrific silence that follows.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.location_scene_appearances VALUES (567, 567, 553, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.location_scene_appearances VALUES (568, 568, 554, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
