INSERT INTO public.location_scene_appearances VALUES (572, 163, 558, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-03-01 15:51:21.170966-05');
INSERT INTO public.location_scene_appearances VALUES (428, 175, 416, 'The room becomes a focal point for reality breaking down. Moonlight casts shadows that don''t match their sources, and the moon itself sets unnaturally fast and bright.', 'The distant, impossible sound of breaking chains can be heard.', NULL, NULL, 'The atmosphere shifts from one of quiet contemplation to one of intense cosmic revelation and existential dread as reality itself becomes unstable and ''personal''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-03-01 15:41:52.027098-05');
