INSERT INTO public.location_scene_appearances VALUES (582, 70, 568, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (92, 31, 86, 'The garage is coated in a layer of charred poultry from a failed experiment. The kitchen and living room are the primary sites for the new NFC experiments, with the crystal and phones being moved around.', 'A new, faint buzzing sound is now present whenever the crystal is near a phone.', 'A lingering smell of explosion and ''charred poultry'' emanates from the garage.', NULL, 'The mood has shifted from one of ''feverish mix of hope and chaos'' to drained frustration punctuated by a brief, baffling discovery.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (174, 31, 168, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:57:51.509036-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (243, 31, 234, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 20:15:46.203421-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (179, 157, 173, NULL, NULL, NULL, NULL, 'The scene ends with an abrupt shift in energy as the narrator decides to act, transitioning out of the contemplative space towards a place of action (the warehouse).', 'gemini', 'gemini-2.5-pro', '2026-02-27 16:02:26.226946-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (205, 157, 196, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:41:28.26476-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (410, 389, 398, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (477, 389, 465, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:22:52.179752-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (489, 389, 477, 'The scene focuses on mundane domestic spaces—the doorway, living room, and kitchen—which become the backdrop for existential horror. The ordinary setting contrasts sharply with the unnatural events.', 'The environment is mostly quiet, amplifying the tension. The silence is broken by the clinical, scripted dialogue of the wife and the loud, jarring scrape of Stephen''s chair as he flees.', NULL, NULL, 'The atmosphere shifts from one of mundane marital friction and exhaustion to one of intense psychological and existential dread as the simulation''s flaws are exposed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:33:45.988017-05', '2026-03-01 15:41:52.027098-05');
INSERT INTO public.location_scene_appearances VALUES (494, 389, 482, NULL, NULL, NULL, NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 22:38:23.206313-05', '2026-03-01 15:41:52.027098-05');
