INSERT INTO public.semantic_tags VALUES (1234, 372, 'emotion', 'frustration', NULL, 'The protagonist is at a breaking point due to a lack of progress.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1235, 372, 'theme', 'stagnation', NULL, 'Days have passed with ''No revelations. No breakthroughs.''', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1236, 372, 'sensory', 'auditory', NULL, 'The constant humming of the Eternal Engine is a key background detail.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1237, 373, 'theme', 'revelation', NULL, 'The dream is not symbolic but a direct impartation of truth.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1238, 373, 'emotion', 'overwhelm', NULL, 'The dream is an aggressive force, ''carving truth'' and ''pressing into me''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1239, 373, 'sensory', 'tactile', NULL, 'The dream''s power is described as ''thrumming through the air'' and feeling like ''static in my veins''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1240, 374, 'emotion', 'shock', NULL, 'The protagonist''s awakening is violent and physical: ''jerked awake, heart pounding''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1241, 374, 'theme', 'epiphany', NULL, 'The protagonist now possesses the answer he was seeking, seared directly into his mind.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1242, 374, 'sensory', 'tactile', NULL, 'The after-effects of the dream are physical, with skin feeling ''electric'' and remnants ''clinging to me like cobwebs''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:02:46.066173-05', '2026-02-27 15:02:46.066173-05');
INSERT INTO public.semantic_tags VALUES (1243, 375, 'emotion', 'ambivalence', NULL, 'The protagonist feels grounded by the routine, but also that something is incomplete or missing.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1244, 375, 'theme', 'routine', NULL, 'The scene is established with the familiar actions of a family breakfast.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (12, 1, 'theme', 'authorship and creative ownership', NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (13, 1, 'sensory', 'visual—typography and formal layout', NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (14, 2, 'theme', 'distribution and accessibility across platforms', NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (15, 2, 'sensory', 'temporal—chronological progression of release dates', NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (16, 3, 'theme', 'technological innovation and revolution', NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (17, 3, 'theme', 'human-alien encounter and extraterrestrial threat', NULL, NULL, 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (18, 3, 'emotion', 'ambition and success shadowed by peril', NULL, 'The catalog describes both achievement (revolutionary technology, interstellar future) and threat (malevolent entity, reality endangered)', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (19, 4, 'emotion', 'hope and aspiration', NULL, 'Eleanor Roosevelt''s epigraph anchors the opening in optimism and belief', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (20, 4, 'emotion', 'dread and inevitability', NULL, 'John Irving''s epigraph introduces the dark counterpoint—nightmares that choose you, not chosen by you', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (21, 4, 'theme', 'dreams versus nightmares', NULL, 'Establishes the central tension of the narrative: aspirational future met by unchosen darkness', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:53:40.989318-05', '2026-02-27 12:53:40.989318-05');
INSERT INTO public.semantic_tags VALUES (22, 5, 'emotion', 'vulnerability', NULL, 'The grain of sand''s smallness against the needle''s delicate dance creates profound vulnerability', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (23, 5, 'theme', 'test and trial', NULL, 'The passage through the needle''s eye represents a spiritual or existential trial', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (24, 5, 'sensory', 'tactile pressure', NULL, 'The narrow passage creates a sense of constraint and pressure', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (25, 6, 'emotion', 'isolation', NULL, 'The grain is lost and adrift, separated from purpose and connection', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (26, 6, 'theme', 'existential uncertainty', NULL, 'The grain exists in an uncertain state of being, fleeting and undefined', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (27, 6, 'sensory', 'void and silence', NULL, 'The lostness is characterized by emptiness and the absence of direction', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (28, 7, 'emotion', 'redemption and hope', NULL, 'The appointed moment brings salvation through destined reunion', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (29, 7, 'theme', 'fate and destiny', NULL, 'Hand-in-hand walking together represents the fulfillment of predetermined purpose', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (30, 7, 'sensory', 'transcendence', NULL, 'The moment when distractions become meaningless and true purpose is revealed', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:26.639702-05', '2026-02-27 12:58:26.639702-05');
INSERT INTO public.semantic_tags VALUES (31, 8, 'emotion', 'dismissal', NULL, 'Initial rationality and deliberate indifference mask deeper vulnerability to fascination', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-02-27 12:58:50.898794-05');
INSERT INTO public.semantic_tags VALUES (32, 8, 'theme', 'mundanity', NULL, 'The ordinary overwhelms the extraordinary; fleeting phenomena disappear into the void', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-02-27 12:58:50.898794-05');
INSERT INTO public.semantic_tags VALUES (33, 8, 'sensory', 'visual', NULL, 'Grainy newscast imagery; flickering, fading perception at the edge of awareness', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-02-27 12:58:50.898794-05');
INSERT INTO public.semantic_tags VALUES (34, 9, 'emotion', 'collective wonder', NULL, 'World-wide fascination creates shared experience of mystery and questioning', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-02-27 12:58:50.898794-05');
INSERT INTO public.semantic_tags VALUES (35, 9, 'theme', 'spectacle', NULL, 'Mundane phenomenon explodes into global event; attention economy transforms understanding', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-02-27 12:58:50.898794-05');
INSERT INTO public.semantic_tags VALUES (36, 9, 'sensory', 'silence', NULL, 'Stark contrast between the silence of The Pointers and ceaseless societal chatter; auditory absence becomes presence', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-02-27 12:58:50.898794-05');
INSERT INTO public.semantic_tags VALUES (37, 10, 'emotion', 'obsession', NULL, 'Consuming compulsion that resists rational control; transformation from dismissal to total preoccupation', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 12:58:50.898794-05', '2026-02-27 12:58:50.898794-05');
