INSERT INTO public.semantic_tags VALUES (189, 49, 'emotion', 'terror', NULL, 'Nightmares deliver visceral, unbearable psychological assault; taste of cold fear.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:14.109668-05', '2026-02-27 13:12:14.109668-05');
INSERT INTO public.semantic_tags VALUES (190, 49, 'emotion', 'desperation', NULL, 'Narrator cannot escape; buried trauma claws toward consciousness; approaching insanity.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:14.109668-05', '2026-02-27 13:12:14.109668-05');
INSERT INTO public.semantic_tags VALUES (191, 49, 'theme', 'loss of control', NULL, 'Nightmares force remembrance; mind becomes a prison narrator cannot escape.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:14.109668-05', '2026-02-27 13:12:14.109668-05');
INSERT INTO public.semantic_tags VALUES (192, 49, 'sensory', 'physical manifestation of psychological horror', NULL, 'Gasping, sweat-drenched waking; hammering pulse; taste of fear; suffocating dread.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:14.109668-05', '2026-02-27 13:12:14.109668-05');
INSERT INTO public.semantic_tags VALUES (193, 50, 'emotion', 'hope', NULL, 'The narrator''s acceptance to MIT represents a fragile hope for a new beginning and acceptance.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (232, 63, 'emotion', 'betrayal', NULL, 'Friends'' silence and discomfort more devastating than explicit rejection.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (194, 50, 'theme', 'memory and suppression', NULL, 'The duality of eidetic memory—perfect recall and conscious forgetting—defines the narrator''s survival strategy.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (195, 50, 'sensory', 'visual', NULL, 'The acceptance letter symbolizes a door cracking open; visual imagery of threshold and transformation.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (196, 51, 'emotion', 'vulnerability', NULL, 'Alcohol lowers defenses; friends'' warmth creates an invitation to trust.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (197, 51, 'theme', 'connection', NULL, 'The narrator begins to believe that these people will be different; walls begin to crack.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (198, 51, 'sensory', 'tactile', NULL, 'Warmth of alcohol and shared physical closeness in the dim dorm room.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (199, 52, 'emotion', 'liberation', NULL, 'Brief glimmer of freedom; release from decades of isolation through the act of speaking.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (200, 52, 'theme', 'trauma disclosure', NULL, 'The narrator finally voices the childhood trauma from 1986; a turning point in the narrative.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (201, 52, 'sensory', 'olfactory', NULL, 'Sharp, acrid smell described as a cocktail of antiseptic and sadness; visceral recall of the traumatic event.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (202, 53, 'emotion', 'dread', NULL, 'The narrator recognizes the familiar pattern; knows how the story will end.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (203, 53, 'theme', 'cyclical abandonment', NULL, 'The pattern repeats; friends withdraw despite their initial warmth and apparent sincerity.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (204, 53, 'sensory', 'visual', NULL, 'Eyes dart away; forced smiles replace genuine warmth; the visual language of withdrawal and discomfort.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:12:39.636819-05', '2026-02-27 13:12:39.636819-05');
INSERT INTO public.semantic_tags VALUES (205, 54, 'emotion', 'dread', NULL, 'Raw dread grips narrator as Death whispers; hollow promises of heaven and hell cannot compete with immediate terror.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (206, 54, 'sensory', 'olfactory', NULL, 'Sharp stench with undertones of rot and sickness; physical manifestation of illness and decay.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (207, 54, 'theme', 'mortality', NULL, 'Narrator confronts finality and last rites; boundary between life and death becomes palpable.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (208, 55, 'emotion', 'relief', NULL, 'Void is not chilling or lonely but a quiet expanse of relief; consciousness finds comfort in dissolution.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (209, 55, 'sensory', 'visual', NULL, 'Shimmering void filled with thousand shades of twilight; spires of nothingness circle in abyss.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (210, 55, 'theme', 'transcendence', NULL, 'Consciousness untethered from body; access to unlimited potential and ancient wisdom beyond mortality''s bounds.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (211, 56, 'emotion', 'defiance', NULL, 'Blazing fire ignites in narrator''s soul; rebellion against oppression fuels return to physical reality.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (212, 56, 'sensory', 'tactile', NULL, 'Narrator experiences reality as muted and dulled; colors fade and sounds muffle upon return to flesh.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (213, 56, 'theme', 'transformation', NULL, 'Narrator returns undeniably different; the void experience fundamentally alters their perception and capabilities.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (214, 57, 'emotion', 'mastery', NULL, 'Narrator gains newfound understanding and control; fear erased; terror no longer binds them.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (215, 57, 'sensory', 'proprioceptive', NULL, 'Each electrical jolt drags narrator deeper into mind''s landscape; body becomes gateway to inner realms.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (216, 57, 'theme', 'inner_power', NULL, 'Sanctuary accessed through consciousness; narrator discovers ability to reshape nightmares into wisdom.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (217, 58, 'emotion', 'isolation', NULL, 'Power arrives with curse of loneliness; narrator marked as outcast and unworthy by society and faith.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (218, 58, 'sensory', 'auditory', NULL, 'Cacophony of visions and voices isolates narrator; internal noise marks them as different.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (219, 58, 'theme', 'condemnation', NULL, 'Church and parents view abilities as demonic; rigid doctrine allows no space for narrator''s gifts.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (220, 59, 'emotion', 'rebellion', NULL, 'Defiance pushes narrator to sacrilege; testing dogma with trembling hands despite taught fear.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (221, 59, 'sensory', 'visual', NULL, 'Fading dusk light accompanies narrator''s sacrilegious burial; darkness and fading light frame transgression.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (222, 59, 'theme', 'disillusionment', NULL, 'World remains unshaken by narrator''s rebellion; no fiery retribution comes; lies of religious authority exposed.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (223, 60, 'emotion', 'emptiness', NULL, 'Aching void persists despite all achievements; gnawing sense of essential absence undermines success.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (224, 60, 'sensory', 'auditory', NULL, 'Screams for relief fall on deaf ears; silence of parental blindness echoes louder than narrator''s pain.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (225, 60, 'theme', 'alienation', NULL, 'Parents shield themselves with faith; cannot perceive child''s turmoil; narrator imprisoned in invisible suffering.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (226, 61, 'emotion', 'determination', NULL, 'Unshakable determination to uncover hidden truth; narrator refuses to rest or surrender.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (227, 61, 'sensory', 'energy', NULL, 'Surrounding air crackles with mysterious energy; hidden truth pulsing just beyond reach; teasing with power.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (228, 61, 'theme', 'quest', NULL, 'Narrator becomes ''boy who lived'' driven by relentless search for hidden truth; final shock interrupts revelation.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:13:14.35138-05', '2026-02-27 13:13:14.35138-05');
INSERT INTO public.semantic_tags VALUES (229, 62, 'emotion', 'anguish', NULL, 'Physical pain mingled with cognitive dissonance of forgotten knowledge resurfacing.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (230, 62, 'sensory', 'tactile pain', NULL, 'Bruising, battering; the body as primary locus of trauma.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (231, 62, 'theme', 'fragmentation of consciousness', NULL, 'Awakening brings return of suppressed knowledge.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (233, 63, 'sensory', 'auditory void', NULL, 'Silence louder than words; the absence of response becomes the response.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (234, 63, 'theme', 'social ostracism', NULL, 'Narrator transformed from insider to outsider; broken curiosity beyond repair.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (235, 64, 'emotion', 'desperation', NULL, 'Driven to self-destruction as the only path to forgetting.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (236, 64, 'theme', 'self-annihilation', NULL, 'Choosing oblivion over authentic existence; sacrifice of self to avoid pain.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (237, 64, 'sensory', 'dissolution', NULL, 'Memories dissolving into shadows; warmth and comfort consumed by darkness.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:09.015358-05', '2026-02-27 13:14:09.015358-05');
INSERT INTO public.semantic_tags VALUES (238, 65, 'emotion', 'vulnerability', NULL, 'The Narrator''s carefully constructed defenses collapse, exposing raw psychological wounds and suppressed truths.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:36.084483-05', '2026-02-27 13:14:36.084483-05');
INSERT INTO public.semantic_tags VALUES (239, 65, 'emotion', 'helplessness', NULL, 'No stopping the memories, no hiding—the Narrator must now bear the weight of unfiltered truths alone.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:36.084483-05', '2026-02-27 13:14:36.084483-05');
INSERT INTO public.semantic_tags VALUES (240, 65, 'theme', 'breakdown of psychological defense', NULL, 'Exhaustion serves as the catalyst that dismantles carefully built mental barriers, forcing confrontation with repressed trauma.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:36.084483-05', '2026-02-27 13:14:36.084483-05');
INSERT INTO public.semantic_tags VALUES (241, 65, 'theme', 'inevitability of truth', NULL, 'Suppression can only hold for so long; sustained pressure (sleeplessness) forces the emergence of buried realities.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:36.084483-05', '2026-02-27 13:14:36.084483-05');
INSERT INTO public.semantic_tags VALUES (242, 65, 'sensory', 'tactile/pain', NULL, 'Memories are described as ''shards of glass''—sharp, cutting sensations that pierce through consciousness.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:36.084483-05', '2026-02-27 13:14:36.084483-05');
INSERT INTO public.semantic_tags VALUES (243, 65, 'sensory', 'overwhelming flood', NULL, 'Visual imagery of walls crumbling and floods surging creates sense of uncontrollable inundation.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:36.084483-05', '2026-02-27 13:14:36.084483-05');
INSERT INTO public.semantic_tags VALUES (244, 66, 'emotion', 'dread', NULL, 'Awakening drenched in sweat; haunted by vivid terrors; helplessness against photographic memory curse.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (245, 66, 'sensory', 'tactile', NULL, 'Sweat dripping down face; physical manifestation of psychological distress; bed and fabric dampened.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (246, 66, 'theme', 'trauma and refuge paradox', NULL, 'Dreams began as coping mechanism against waking abuse but now haunt protagonist; no escape through forgetting.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (247, 67, 'emotion', 'uncertainty and introspection', NULL, 'Protagonist questions whether dreams are prophetic or psychological; frantic journaling reflects search for meaning.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (248, 67, 'theme', 'interpretation and agency', NULL, 'Attempt to decode dreams as deliberate act of interpretive control; protagonist as active meaning-maker.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (249, 67, 'sensory', 'visual', NULL, 'Frantically scribbling journal entries; capturing glimpses of unseen forces through written documentation.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (250, 68, 'sensory', 'auditory', NULL, 'Freight train roar; rumbling shake through room and pictures on wall; thunder flash as climactic sonic moment.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (251, 68, 'emotion', 'fear and anticipation', NULL, 'Fear knotting stomach; protagonist bracing for unraveling; dread of being wrenched from reality.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (252, 68, 'theme', 'reality destabilization', NULL, 'Surfaces melting like wax; fabric of universe becoming unstable; liminal collapse between dream and waking.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (253, 68, 'sensory', 'visual', NULL, 'Ethereal glare from lightning flooding room; blinding flash; colors swirling in vortex; complete sensory dissolution.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:14:55.347367-05', '2026-02-27 13:14:55.347367-05');
INSERT INTO public.semantic_tags VALUES (254, 69, 'emotion', 'desperation', NULL, 'Tantalizing equations just out of reach; wrestling with schematics; struggling to comprehend solutions.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.semantic_tags VALUES (255, 69, 'sensory', 'auditory', NULL, 'Cornstalks clack like bone castanets; eerie voices; electricity crackling through stalks.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.semantic_tags VALUES (256, 69, 'theme', 'threshold_of_creation', NULL, 'Energy building toward explosion; otherworldly charge permeating space; tempest brewing both externally and internally.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.semantic_tags VALUES (257, 70, 'emotion', 'obsessive_determination', NULL, 'Decades of fixation on designs; nightly work as survival mechanism; fretting over liberation and doom.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.semantic_tags VALUES (258, 70, 'sensory', 'tactile', NULL, 'Fingers hovering over pen; worn leather chair; refuge within chaos of workshop.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.semantic_tags VALUES (259, 70, 'theme', 'sacred_work', NULL, 'This is different from trivial work; holds key to liberation and potential doom; eureka moments demand full attention.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.semantic_tags VALUES (260, 71, 'emotion', 'awe_and_ambition', NULL, 'Marvel beyond comprehension; infinite energy source; defies comprehension through perpetual motion.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.semantic_tags VALUES (261, 71, 'sensory', 'auditory', NULL, 'Engine hums with gentle vibration; orchestrates symphony of perpetual motion; gears and levers turn in harmony.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
INSERT INTO public.semantic_tags VALUES (262, 71, 'theme', 'god_like_power', NULL, 'Taps into reality itself; accesses infinite realms; can transform any substance or cure any disease.', 'claude', 'claude-haiku-4-5-20251001', '2026-02-27 13:15:18.882025-05', '2026-02-27 13:15:18.882025-05');
