INSERT INTO public.semantic_tags VALUES (603, 159, 'emotion', 'dread', NULL, 'The narrator feels dread seeping into his bones as reality sets in.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:04:23.20534-05', '2026-02-27 14:04:23.20534-05');
