INSERT INTO public.semantic_tags VALUES (728, 203, 'emotion', 'dread', NULL, 'The researcher''s attempts to fix the problem only reveal a deeper, more sinister corruption and an unseen, watching presence.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:15:25.564744-05', '2026-02-27 14:15:25.564744-05');
