INSERT INTO public.semantic_tags VALUES (813, 230, 'sensory', 'Kinesthetic', NULL, 'The narrator''s frantic pacing, unable to contain his agitated energy.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:24:04.5571-05', '2026-02-27 14:24:04.5571-05');
INSERT INTO public.semantic_tags VALUES (814, 231, 'emotion', 'Love', NULL, 'The wife''s plea is rooted in love and a desire to preserve her husband and their family.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:24:04.5571-05', '2026-02-27 14:24:04.5571-05');
INSERT INTO public.semantic_tags VALUES (815, 231, 'theme', 'Partnership', NULL, 'The wife''s reminder that they are ''in this together''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:24:04.5571-05', '2026-02-27 14:24:04.5571-05');
INSERT INTO public.semantic_tags VALUES (816, 231, 'sensory', 'Tactile', NULL, 'The wife''s gentle, grounding touch on the narrator''s shoulder.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:24:04.5571-05', '2026-02-27 14:24:04.5571-05');
