INSERT INTO public.semantic_tags VALUES (818, 232, 'theme', 'Reconnection', NULL, 'The narrator chooses his family over his obsession, rejoining his wife on the couch.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:24:04.5571-05', '2026-02-27 14:24:04.5571-05');
