INSERT INTO public.semantic_tags VALUES (820, 233, 'theme', 'Surrealism', NULL, 'The seamless transition from a mundane living room to a symbolic battlefield highlights the porous boundary between the narrator''s anxiety and reality.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (821, 233, 'emotion', 'Foreboding', NULL, 'The atmosphere of the battlefield is described as thick with a sense of foreboding.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (822, 233, 'sensory', 'Visual', NULL, 'The blurring glow of the TV screen and the infinite dark, shifting sands of the dreamscape.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (823, 234, 'emotion', 'Overwhelm', NULL, 'The boss is a towering, monstrous form that embodies every professional failure and obstacle at once.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (824, 234, 'theme', 'Personification', NULL, 'Abstract concepts like hiring managers and algorithms are combined into a single, tangible monster.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (825, 234, 'sensory', 'Auditory', NULL, 'The boss''s voice is a ''cacophony of rejection emails and silences''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (826, 235, 'emotion', 'Despair', NULL, 'The narrator''s hope is literally crushed from his chest, and his final defeat is absolute.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (827, 235, 'theme', 'Futility', NULL, 'All of the narrator''s weapons and efforts disintegrate uselessly against the boss.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (828, 235, 'sensory', 'Tactile', NULL, 'The crushing grip of the tentacle, the splattering of viscous slime, and the burning sensation on his skin.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (829, 235, 'sensory', 'Olfactory', NULL, 'The overwhelming stench of rot and malice from the boss.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (830, 236, 'emotion', 'Relief', NULL, 'The narrator''s gasp upon waking is one of both terror and relief at escaping the nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (831, 236, 'theme', 'Sanctuary', NULL, 'The wife''s presence and the safety of their home provide a stark contrast to the battlefield, offering a temporary haven.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (832, 236, 'sensory', 'Tactile', NULL, 'The grounding sensations of his wife''s hand on his forehead and her warm kiss.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:25:05.328292-05', '2026-02-27 14:25:05.328292-05');
INSERT INTO public.semantic_tags VALUES (833, 237, 'emotion', 'dread', NULL, 'The feeling of transitioning from one known terror (the dream) to an unknown, darker one from the past.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (834, 237, 'theme', 'trauma-trigger', NULL, 'The dream''s emotional weight directly causes a repressed memory to surface.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (835, 237, 'sensory', 'psychological', NULL, 'The experience is entirely internal, a feeling of being pulled down into a memory.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (836, 238, 'emotion', 'agony', NULL, 'The narrator experiences intense physical pain and the shattering of his sanity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (837, 238, 'theme', 'dehumanization', NULL, 'The narrator ceases to see his father as human, referring to him as ''it'' and a ''monstrous being''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (838, 238, 'sensory', 'auditory', NULL, 'The ''thunderous cracks'' of the father''s fists echoing through the house.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (839, 239, 'emotion', 'betrayal', NULL, 'The core emotion of the beat, described as cutting deeper than any physical wound.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (840, 239, 'theme', 'complicity', NULL, 'The mother''s silence is not passive but an active, loyal pact with the abuser.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (841, 239, 'sensory', 'visual', NULL, 'The sight of the mother''s eyes, holding ''no trace of compassion or empathy, only a serene detachment''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:04.557296-05', '2026-02-27 14:26:04.557296-05');
INSERT INTO public.semantic_tags VALUES (842, 240, 'emotion', 'despair', NULL, 'The narrator is waking up to a feeling of hopelessness and defeat.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:53.978522-05', '2026-02-27 14:26:53.978522-05');
INSERT INTO public.semantic_tags VALUES (843, 240, 'theme', 'reflection', NULL, 'The scene is initiated by a deep reflection on a lifetime of struggle.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:53.978522-05', '2026-02-27 14:26:53.978522-05');
