INSERT INTO public.semantic_tags VALUES (846, 241, 'theme', 'intellect as refuge', NULL, 'Academia and knowledge are presented as the only sanctuary from a painful world.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:53.978522-05', '2026-02-27 14:26:53.978522-05');
INSERT INTO public.semantic_tags VALUES (847, 242, 'emotion', 'invalidation', NULL, 'The narrator''s life''s work and achievements are rendered worthless by the job market.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:53.978522-05', '2026-02-27 14:26:53.978522-05');
