INSERT INTO public.semantic_tags VALUES (850, 243, 'theme', 'paradox of strength', NULL, 'The narrator''s greatest asset, his individuality, has become his primary liability.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:53.978522-05', '2026-02-27 14:26:53.978522-05');
INSERT INTO public.semantic_tags VALUES (851, 243, 'sensory', 'internal', NULL, 'The feeling of the realization is described with a visceral, burning sensation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:26:53.978522-05', '2026-02-27 14:26:53.978522-05');
INSERT INTO public.semantic_tags VALUES (852, 244, 'theme', 'supernatural ability', NULL, 'The narrator''s power over technology is portrayed as an innate, almost magical quality rather than a learned skill.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:27:52.966538-05', '2026-02-27 14:27:52.966538-05');
