INSERT INTO public.semantic_tags VALUES (854, 244, 'sensory', 'auditory', NULL, 'The specific mention of electronics that ''buzzed and bent'' to his will.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:27:52.966538-05', '2026-02-27 14:27:52.966538-05');
INSERT INTO public.semantic_tags VALUES (855, 245, 'theme', 're-evaluation of the past', NULL, 'The narrator is actively reframing his personal history in light of his current crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:27:52.966538-05', '2026-02-27 14:27:52.966538-05');
