INSERT INTO public.semantic_tags VALUES (861, 246, 'sensory', 'tactile', NULL, 'The thought of his own failure is described as a ''cold and unsettling'' feeling.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:27:52.966538-05', '2026-02-27 14:27:52.966538-05');
