INSERT INTO public.semantic_tags VALUES (897, 258, 'theme', 'Vulnerability', NULL, 'The protagonist''s success and self-worth are tied to the machine''s performance and his family''s reaction.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:31:29.859042-05', '2026-02-27 14:31:29.859042-05');
INSERT INTO public.semantic_tags VALUES (898, 258, 'sensory', 'Auditory', NULL, 'The ''steady ticking of the Eternal Engine filling the silence.''', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:31:29.859042-05', '2026-02-27 14:31:29.859042-05');
INSERT INTO public.semantic_tags VALUES (899, 259, 'emotion', 'anxiety', NULL, 'The protagonist''s nervousness is amplified by the memory of a past, spectacular failure.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:32:17.378803-05', '2026-02-27 14:32:17.378803-05');
INSERT INTO public.semantic_tags VALUES (900, 259, 'theme', 'risk', NULL, 'The family is gathered to witness an event that could either be a major breakthrough or another disaster.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:32:17.378803-05', '2026-02-27 14:32:17.378803-05');
INSERT INTO public.semantic_tags VALUES (901, 259, 'sensory', 'auditory', NULL, 'The scene begins with the sound of tires on the driveway, signaling the arrival of the other characters.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:32:17.378803-05', '2026-02-27 14:32:17.378803-05');
INSERT INTO public.semantic_tags VALUES (902, 260, 'emotion', 'suspense', NULL, 'The ''briefest of a moment'' where nothing happens after flipping the switch creates a peak of suspense before the outcome is known.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:32:17.378803-05', '2026-02-27 14:32:17.378803-05');
INSERT INTO public.semantic_tags VALUES (903, 260, 'theme', 'innovation', NULL, 'The act of activating a new power source and disconnecting from the established infrastructure is a moment of pure innovation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:32:17.378803-05', '2026-02-27 14:32:17.378803-05');
INSERT INTO public.semantic_tags VALUES (904, 260, 'sensory', 'visual', NULL, 'The garage light flickering is a key visual indicator of the power transfer.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:32:17.378803-05', '2026-02-27 14:32:17.378803-05');
