INSERT INTO public.semantic_tags VALUES (908, 261, 'theme', 'ambition', NULL, 'The protagonist''s final line, ''this is just the beginning,'' immediately shifts the focus from a single success to future potential.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:32:17.378803-05', '2026-02-27 14:32:17.378803-05');
INSERT INTO public.semantic_tags VALUES (909, 262, 'emotion', 'Anxiety', NULL, 'The narrator''s relief is immediately replaced by a more pervasive, less specific financial anxiety.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:33:21.947313-05', '2026-02-27 14:33:21.947313-05');
