INSERT INTO public.semantic_tags VALUES (911, 262, 'emotion', 'Emptiness', NULL, 'Described as a ''hollow space where urgency used to live,'' a paradoxical outcome of solving a problem.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:33:21.947313-05', '2026-02-27 14:33:21.947313-05');
