INSERT INTO public.semantic_tags VALUES (914, 263, 'theme', 'Refuge', NULL, 'Time with his son is explicitly called an ''unexpected refuge'' from the ''relentless undercurrent of dread''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:33:21.947313-05', '2026-02-27 14:33:21.947313-05');
INSERT INTO public.semantic_tags VALUES (915, 263, 'sensory', 'Auditory', NULL, 'The sounds of the cartoon and the ''occasional burst of laughter'' are key sensory details.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:33:21.947313-05', '2026-02-27 14:33:21.947313-05');
INSERT INTO public.semantic_tags VALUES (916, 264, 'emotion', 'Curiosity', NULL, 'The son''s initial question shifts the mood from quiet domesticity to intrigued curiosity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:34:09.126964-05', '2026-02-27 14:34:09.126964-05');
