INSERT INTO public.semantic_tags VALUES (922, 266, 'emotion', 'Fear', NULL, 'The narrator feels a ''flicker of fear'' for the first time, moving beyond intellectual curiosity to genuine dread.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:34:09.126964-05', '2026-02-27 14:34:09.126964-05');
