INSERT INTO public.semantic_tags VALUES (933, 269, 'sensory', 'auditory', NULL, 'The son''s voice becomes ''barely audible'' and a ''near whisper'', emphasizing the gravity of the revelation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:34:59.83941-05', '2026-02-27 14:34:59.83941-05');
