INSERT INTO public.semantic_tags VALUES (995, 293, 'emotion', 'chaos', NULL, 'The eruption is a violent, overwhelming sensory assault that throws the characters physically.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.semantic_tags VALUES (996, 293, 'theme', 'catastrophe', NULL, 'The experiment goes wildly out of control, resulting in a destructive implosion.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.semantic_tags VALUES (997, 293, 'sensory', 'olfactory', NULL, 'The bizarre and unexpected smell of fried chicken during a reality-bending event.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
