INSERT INTO public.semantic_tags VALUES (999, 294, 'emotion', 'awe', NULL, 'The father and son are rendered speechless and mesmerized by the impossible object they have created.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.semantic_tags VALUES (1000, 294, 'theme', 'transmutation', NULL, 'A mundane offering of chicken and rice has been transformed into an extraordinary, otherworldly artifact.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.semantic_tags VALUES (1001, 294, 'sensory', 'visual', NULL, 'The description of the crystal as shimmering, iridescent, and endlessly folding in on itself.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.semantic_tags VALUES (1002, 295, 'emotion', 'fascination', NULL, 'The entire family, despite the danger and initial anger, becomes hypnotized by the crystal''s beauty and promise.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
