INSERT INTO public.semantic_tags VALUES (1004, 295, 'sensory', 'visual', NULL, 'The hypnotic patterns of light cast by the crystal, described as a ''shifting lattice of impossible geometry''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:41:10.041695-05', '2026-02-27 14:41:10.041695-05');
INSERT INTO public.semantic_tags VALUES (1005, 296, 'sensory', 'olfactory', NULL, 'The entire scene is initiated by the son noticing a bad smell.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:42:18.622465-05', '2026-02-27 14:42:18.622465-05');
