INSERT INTO public.semantic_tags VALUES (1012, 298, 'emotion', 'surprise', NULL, 'The unexpected breakthrough comes from an accidental, careless act, not a planned experiment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
