INSERT INTO public.semantic_tags VALUES (1014, 298, 'sensory', 'auditory', NULL, 'The ''faint buzz'' from the phone is the first new sensory feedback from the crystal since its creation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.semantic_tags VALUES (1015, 299, 'emotion', 'resignation', NULL, 'The characters accept the baffling, almost playful antagonism of the mystery they''re facing.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
INSERT INTO public.semantic_tags VALUES (1016, 299, 'theme', 'epistemology', NULL, 'The core problem shifts from ''what is the answer?'' to ''how do we even ask the right question?''', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:10.734199-05', '2026-02-27 14:43:10.734199-05');
