INSERT INTO public.semantic_tags VALUES (1021, 301, 'theme', 'technological history', NULL, 'The narrator draws a parallel between his current problem and the methods used in the early days of computing.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:56.362107-05', '2026-02-27 14:43:56.362107-05');
