INSERT INTO public.semantic_tags VALUES (1026, 303, 'sensory', 'auditory', NULL, 'The crystal''s ''hum swelling into something almost resonant'' marks the change in its state.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:56.362107-05', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.semantic_tags VALUES (1027, 303, 'emotion', 'awe', NULL, 'The son''s reaction is described as ''a mix of terror and awe'' at the sight of the structured data.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:56.362107-05', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.semantic_tags VALUES (1028, 303, 'theme', 'breakthrough', NULL, 'The shift from random noise to structured data represents a major step forward in understanding the crystal.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:56.362107-05', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.semantic_tags VALUES (1029, 303, 'sensory', 'visual', NULL, 'The crystal glows, and the data on the screen is described as ''writhing like something alive'' and visualized as a ''spasmodic beating of an alien heart''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:43:56.362107-05', '2026-02-27 14:43:56.362107-05');
INSERT INTO public.semantic_tags VALUES (1030, 304, 'emotion', 'frustration', NULL, 'The scene opens with the narrator''s two weeks of failed attempts, setting a tone of intellectual stalemate.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:44:39.039742-05', '2026-02-27 14:44:39.039742-05');
