INSERT INTO public.semantic_tags VALUES (1054, 312, 'emotion', 'panic', NULL, 'The father''s heart drops ''like a lead weight'' as he desperately tries to revive the dead machine.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:46:53.425867-05', '2026-02-27 14:46:53.425867-05');
