INSERT INTO public.semantic_tags VALUES (1056, 312, 'sensory', 'auditory', NULL, 'The scene is defined by the transition from a hum to a loud ''pop'' and then to a profound, unnerving silence.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:46:53.425867-05', '2026-02-27 14:46:53.425867-05');
