INSERT INTO public.semantic_tags VALUES (1141, 341, 'emotion', 'frustration', NULL, 'The narrator is exasperated by his son''s distraction and choice of ''brain rot'' entertainment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:15.442117-05', '2026-02-27 14:55:15.442117-05');
