INSERT INTO public.semantic_tags VALUES (1146, 343, 'emotion', 'satisfaction', NULL, 'The narrator and his son successfully create something and avoid blowing anything up, ending the scene on a positive note.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:15.442117-05', '2026-02-27 14:55:15.442117-05');
