INSERT INTO public.semantic_tags VALUES (1148, 343, 'sensory', 'auditory', NULL, 'The fizzing sound of chemical reactions provides the soundscape for the successful experiment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:15.442117-05', '2026-02-27 14:55:15.442117-05');
INSERT INTO public.semantic_tags VALUES (1149, 344, 'emotion', 'excitement', NULL, 'The family is energized by the ''exciting pace'' of their experiments.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
