INSERT INTO public.semantic_tags VALUES (1151, 344, 'sensory', 'auditory', NULL, 'The scene is filled with the sounds of a working lab: ''clinking glass and bubbling liquids'' and the ''low hum of equipment''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
