INSERT INTO public.semantic_tags VALUES (1153, 345, 'emotion', 'anticipation', NULL, 'The family watches intently during the ''moment of truth'' as they test the new material.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.semantic_tags VALUES (1154, 345, 'theme', 'discovery', NULL, 'The confirmation of room-temperature superconductivity is a monumental scientific breakthrough.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.semantic_tags VALUES (1155, 345, 'emotion', 'awe', NULL, 'The family freezes, staring in whispered awe at the zero-resistance reading.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.semantic_tags VALUES (1156, 346, 'emotion', 'triumph', NULL, 'The narrator''s successful levitation is a moment of pure, shouted triumph.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.semantic_tags VALUES (1157, 346, 'theme', 'innovation', NULL, 'The discovery immediately sparks imaginative new applications, from power distribution to hoverboards.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:55:57.654487-05', '2026-02-27 14:55:57.654487-05');
INSERT INTO public.semantic_tags VALUES (1509, 465, 'theme', 'anonymity', NULL, 'A once-terrifying ruler is now just another face in the crowd.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:27:13.749211-05', '2026-02-27 15:27:13.749211-05');
