INSERT INTO public.semantic_tags VALUES (1159, 347, 'emotion', 'terror', NULL, 'The protagonist''s initial reaction to the overwhelming and hostile environment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1160, 347, 'theme', 'disorientation', NULL, 'The entire reality is fractured, unstable, and defies understanding.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1161, 347, 'sensory', 'auditory assault', NULL, 'The cacophony is described as physically painful, like shards of agony.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1162, 348, 'emotion', 'hope', NULL, 'The figure''s voice is a ''lifeline'' in the madness, offering the first glimmer of potential survival.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1163, 348, 'theme', 'intervention', NULL, 'A seemingly powerful and knowledgeable entity appears to guide the lost protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1164, 349, 'theme', 'cryptic guidance', NULL, 'The figure offers a path, but it is abstract and based on concepts like ''Truth'' and ''riddles''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1165, 349, 'emotion', 'desperation', NULL, 'The protagonist''s questions reveal their desperate need for a concrete plan.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1166, 350, 'theme', 'psychological warfare', NULL, 'The scene explicitly states that fear empowers the enemy, making the protagonist''s emotional state a battlefield.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1167, 350, 'emotion', 'resolve', NULL, 'Despite the terror, the protagonist chooses to push forward with their new guide.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1168, 350, 'sensory', 'kinesthetic', NULL, 'The feeling of the ground shifting ''like liquid shadow'' is a primary sensory input.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:05.016758-05', '2026-02-27 14:57:05.016758-05');
INSERT INTO public.semantic_tags VALUES (1169, 351, 'emotion', 'desperation', NULL, 'The protagonist is wounded and fighting against impossible odds.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1170, 351, 'theme', 'hopeless struggle', NULL, 'The fight is characterized by pain, agony, and overwhelming opposition.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1171, 351, 'sensory', 'olfactory', NULL, 'The air smells of decay and ozone.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
