INSERT INTO public.semantic_tags VALUES (1173, 352, 'theme', 'endurance', NULL, 'The mysterious voice explicitly states that the protagonist must endure.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1174, 352, 'sensory', 'visual', NULL, 'The scene shifts to a surreal landscape of glass, spiraling stars, and infinite reflections.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1175, 353, 'emotion', 'dread', NULL, 'The protagonist''s weapon is failing as inescapable threats close in.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1176, 353, 'theme', 'powerlessness', NULL, 'The Engine''s light dims, symbolizing the loss of hope and control.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1177, 353, 'sensory', 'auditory', NULL, 'A vast, mechanical grinding sound creates an atmosphere of industrial dread.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1178, 354, 'emotion', 'terror', NULL, 'The protagonist is swallowed by a void and physically attacked.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1179, 354, 'theme', 'glimmer of hope', NULL, 'The superconducting wire represents a single, desperate chance of escape.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1180, 354, 'sensory', 'tactile', NULL, 'The crushing weight of the void and the searing agony from a fiend''s claws.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1181, 355, 'emotion', 'fleeting hope', NULL, 'The sudden arrival of allies provides a brief moment of relief and camaraderie.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1182, 355, 'theme', 'overwhelming force', NULL, 'No amount of skill or bravery can stand against the infinite horde.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1183, 355, 'sensory', 'auditory', NULL, 'The chaos of battle is underscored by distorted voices and childish screams.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1184, 356, 'emotion', 'isolation', NULL, 'After the chaos and brief companionship, the protagonist is left utterly alone again.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1185, 356, 'theme', 'last chance', NULL, 'The entire focus narrows to a single, final action: reaching for the wire.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:57:51.540873-05', '2026-02-27 14:57:51.540873-05');
INSERT INTO public.semantic_tags VALUES (1186, 357, 'emotion', 'desperation', NULL, 'The protagonist''s trembling hands and acknowledgement of past failure show this is a final, desperate act.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1187, 357, 'sensory', 'auditory', NULL, 'The scene is filled with sound: guttural growls, fading whispers, and the ''mournful harmony'' of the sword.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1188, 357, 'theme', 'determination', NULL, 'Despite the fear and past failure, the protagonist commits to the action.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1189, 358, 'emotion', 'awe', NULL, 'The protagonist''s reaction to the vortex is a mix of terror and awe at the cosmic power unleashed.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1190, 358, 'theme', 'consequence', NULL, 'The act of pulling the wire has an immediate, reality-shattering consequence.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1191, 358, 'sensory', 'visual', NULL, 'Dominated by the ''blinding white light'' of the vortex and flashes of ''grotesque figures''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1192, 359, 'theme', 'forbidden knowledge', NULL, 'The protagonist willingly uses an ancient, sinister tome and primal words to escalate the situation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1193, 359, 'emotion', 'defiance', NULL, 'Instead of closing the portal, the protagonist chooses to tear it wider, a clear act of defiance.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1194, 359, 'sensory', 'auditory', NULL, 'The ''primal cacophony'' of the words and the bone-vibrating ''roars'' of the beasts are the key sensory inputs.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1195, 360, 'theme', 'crossing the threshold', NULL, 'The protagonist is physically pulled into the other dimension, a point of no return.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1196, 360, 'emotion', 'terror', NULL, 'The protagonist resists being sucked in, indicating a clear state of terror mixed with a ''maddening curiosity''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1197, 360, 'sensory', 'kinesthetic', NULL, 'The entire beat is defined by the physical sensation of being irresistibly pulled and dragged.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1198, 360, 'theme', 'cosmic horror', NULL, 'The protagonist''s mind unravels under the weight of cosmic truths, and a desire to consume horror takes hold.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:58:39.396494-05', '2026-02-27 14:58:39.396494-05');
INSERT INTO public.semantic_tags VALUES (1199, 361, 'emotion', 'dread', NULL, 'The protagonist feels a suffocating dread from the oppressive weight of Oblivion and its inhabitants.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1200, 361, 'theme', 'insignificance', NULL, 'The Herald''s primary psychological attack is to assert the protagonist''s utter worthlessness in the face of eternity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1201, 361, 'sensory', 'visual', NULL, 'The scene is defined by indescribable forms, writhing shadows, and shimmering crystalline teeth.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1202, 362, 'emotion', 'defiance', NULL, 'The protagonist counters the overwhelming dread with a declaration of his will and purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1203, 362, 'theme', 'cost_of_knowledge', NULL, 'The abominations introduce the central theme that seeking knowledge has a terrible, unavoidable price.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1204, 362, 'sensory', 'auditory', NULL, 'The creature''s laughter is described as ''splintering glass'' and the group''s hiss is like ''acid eating through steel''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1205, 363, 'emotion', 'fury', NULL, 'The protagonist''s defiance boils over into a blinding fury, motivating his sudden and violent attack.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1206, 363, 'theme', 'vulnerability', NULL, 'Even a seemingly eternal and all-powerful creature is shown to have a weakness that can be exploited.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1207, 363, 'sensory', 'tactile', NULL, 'The physical act of driving the blade through the creature''s chest and tearing its heart free is a key sensory moment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1208, 364, 'theme', 'pyrrhic_victory', NULL, 'The protagonist wins the fight but is cursed with the knowledge that his prize—the truth—will ultimately consume him.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1209, 364, 'emotion', 'triumph', NULL, 'A bitter sense of triumph mixed with the dread of the creature''s final curse.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1210, 364, 'sensory', 'tactile', NULL, 'The pulsing fragment of knowledge physically burns itself into the protagonist''s palm and soul.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1211, 365, 'emotion', 'tranquility', NULL, 'An unsettling tranquility is offered as a temptation, contrasting with the terror of the void.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1212, 365, 'theme', 'surrender', NULL, 'The new threat is not violence, but the temptation to abandon the struggle and give in to the void.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1213, 365, 'sensory', 'auditory', NULL, 'The void is filled with a ''soothing hum'' and a ''soft and intimate'' whisper.', 'gemini', 'gemini-2.5-pro', '2026-02-27 14:59:48.319024-05', '2026-02-27 14:59:48.319024-05');
INSERT INTO public.semantic_tags VALUES (1214, 366, 'emotion', 'horror', NULL, 'The protagonist is thrust into a grotesque, pulsating reality, causing immediate shock and horror.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1215, 366, 'theme', 'corruption', NULL, 'Elysium, a presumably positive place, is shown as a decayed, boiling mass of flesh.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1216, 366, 'sensory', 'olfactory', NULL, 'The air ''reeked of decay,'' establishing the scene''s foul nature.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1217, 366, 'sensory', 'auditory', NULL, 'The ''rattling train'' and its ''rhythmic thrum pounding in my skull'' create an oppressive soundscape.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1218, 367, 'emotion', 'agony', NULL, 'The protagonist''s skin erupts as soldiers claw their way out, an intensely painful experience.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1219, 367, 'theme', 'body horror', NULL, 'Living beings emerging from pores and internal organs convulsing violently are classic elements of body horror.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1220, 367, 'sensory', 'tactile', NULL, 'The sensation of soldiers clawing out and fists connecting with flesh that ''burned like molten rock''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1221, 368, 'emotion', 'terrible awe', NULL, 'The sight beyond the barrier is described as ''far more terrible'' than salvation, inspiring a mix of terror and awe at its cosmic scale.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1222, 368, 'theme', 'revelation', NULL, 'Amidst the damnation and chaos, the protagonist finds ''the answer''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1223, 368, 'sensory', 'visual', NULL, 'The scene is dominated by powerful visuals: spiraling shadows, monstrous geometries, and symbols that ''seared themselves'' into vision.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1224, 368, 'sensory', 'auditory', NULL, 'The barrier forms with a ''deafening crack'', a sharp, powerful sound punctuating the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:00:58.852154-05', '2026-02-27 15:00:58.852154-05');
INSERT INTO public.semantic_tags VALUES (1225, 369, 'emotion', 'terror', NULL, 'The protagonist is physically and mentally reeling from the nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1226, 369, 'theme', 'revelation', NULL, 'The dream was not just a dream, but a vessel for profound, actionable knowledge.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1227, 369, 'sensory', 'tactile', NULL, 'The feeling of being slick with sweat and constricted by tangled sheets.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1228, 370, 'emotion', 'worry', NULL, 'The wife''s deep concern for her husband''s well-being is the focus.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1229, 370, 'theme', 'grounding', NULL, 'The wife''s physical touch pulls the protagonist back from the abyss of his nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1230, 370, 'sensory', 'auditory', NULL, 'The memory of the protagonist''s screaming is a key element of the wife''s fear.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1231, 371, 'emotion', 'determination', NULL, 'The protagonist''s hand becomes steady as he commits the knowledge to paper.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1232, 371, 'theme', 'manifestation', NULL, 'An impossible, intangible idea is being made real through the act of writing.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1233, 371, 'sensory', 'visual', NULL, 'The focus is on the act of writing and the wife watching intently.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:01:46.507507-05', '2026-02-27 15:01:46.507507-05');
INSERT INTO public.semantic_tags VALUES (1246, 376, 'emotion', 'determination', NULL, 'The protagonist lays out his new plan with a sense of purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1247, 376, 'theme', 'revelation', NULL, 'The dream has provided a breakthrough insight that changes everything.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1248, 376, 'sensory', 'tactile', NULL, 'The protagonist touches the cold metal case of the Infinitron.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1249, 377, 'emotion', 'tension', NULL, 'The wife''s question about failure introduces a moment of high emotional stakes.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1250, 377, 'theme', 'risk vs reward', NULL, 'The conversation explicitly weighs the possibility of failure against the promise of a reward (the trip).', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1251, 377, 'emotion', 'levity', NULL, 'The protagonist''s dark humor and the son''s negotiation break the serious mood.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1252, 378, 'emotion', 'reassurance', NULL, 'The wife''s words and touch are meant to reassure and stabilize the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1253, 378, 'theme', 'belief', NULL, 'Unconditional belief from a loved one is presented as a powerful, anchoring force.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1254, 378, 'sensory', 'tactile', NULL, 'The feeling of his wife''s warm hand on his.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:03:42.311509-05', '2026-02-27 15:03:42.311509-05');
INSERT INTO public.semantic_tags VALUES (1255, 379, 'emotion', 'despair', NULL, 'The protagonist is surrounded by the ''detritus of my ambition'' and feels the ''weight of failure pressing on my shoulders''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1256, 379, 'theme', 'obsession', NULL, 'The scene is described as containing ''relics of a madman’s obsession'' and the protagonist admits ''I couldn’t stop''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1257, 379, 'sensory', 'auditory', NULL, 'The ''low hum'' of the Eternal Engine is a constant presence.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1258, 380, 'theme', 'otherworldly influence', NULL, 'The protagonist''s hands are ''guided by some unseen will'' and move ''as though possessed''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1259, 380, 'emotion', 'frenzy', NULL, 'The assembly is performed with ''a fervor that bordered on madness''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1260, 380, 'sensory', 'visual', NULL, 'The alloy has a ''kaleidoscope of unnatural iridescence''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1261, 380, 'sensory', 'tactile', NULL, 'The engine''s thrumming resonates ''into my bones''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1262, 381, 'emotion', 'awe', NULL, 'The Inventor feels the ''wrongness of its perfection'', indicating a sense of awe mixed with unease.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1263, 381, 'theme', 'realization', NULL, 'The protagonist understands the object''s true nature: ''This was not a mere device. This was a key.''', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1264, 381, 'sensory', 'kinesthetic', NULL, 'The interlocking joints of the key move ''like tendons, like sinew stretching taut''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:04:42.480403-05', '2026-02-27 15:04:42.480403-05');
INSERT INTO public.semantic_tags VALUES (1265, 382, 'emotion', 'dread', NULL, 'The protagonist''s stomach twists in dread as the experiment begins to go wrong.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1266, 382, 'theme', 'chaos', NULL, 'The room erupts in a violent, reality-bending chaos that throws the protagonist to the floor.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1267, 382, 'sensory', 'auditory', NULL, 'The scene is filled with the roar of the Engine, a mournful wail from the Infinitron, and a deafening crack.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1268, 383, 'emotion', 'awe', NULL, 'The protagonist is in awe of the ''Perfect, terrible construct'' that has been created.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1269, 383, 'theme', 'unnatural creation', NULL, 'Something living and organic is birthed from entirely inorganic, unliving components.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1270, 383, 'sensory', 'olfactory', NULL, 'The air is filled with the sharp, unpleasant smell of acrid smoke.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1271, 384, 'emotion', 'horror', NULL, 'The protagonist''s stomach churns as he stares at the grotesque, fleshy mass created by the device.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1272, 384, 'theme', 'flawed replication', NULL, 'The first test of the device results in an incomplete and monstrous copy, highlighting the danger of the new technology.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1273, 384, 'sensory', 'tactile', NULL, 'The replicated hand is described as having feverish flesh that pulses faintly beneath the protagonist''s touch.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1274, 385, 'emotion', 'exhilaration', NULL, 'The protagonist''s horror is replaced by a manic exhilaration as he realizes the magnitude of his success.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1275, 385, 'theme', 'hubris', NULL, 'Despite the monstrous result, the protagonist immediately summons his family to witness his breakthrough, showing a classic sign of scientific overconfidence.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1276, 385, 'sensory', 'auditory', NULL, 'The protagonist''s triumphant roar reverberates off the walls, and a distant yelp is heard from the kitchen.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:05:27.751266-05', '2026-02-27 15:05:27.751266-05');
INSERT INTO public.semantic_tags VALUES (1277, 386, 'emotion', 'mania', NULL, 'The protagonist''s exhilaration is described as a ''wild grin'' and trembling with excitement, not exhaustion.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1278, 386, 'emotion', 'horror', NULL, 'The wife''s reaction is explicitly stated as ''equal parts horror and disbelief''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1279, 386, 'sensory', 'olfactory', NULL, 'The scene is set within a ''haze of smoke''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1280, 387, 'theme', 'responsibility', NULL, 'The protagonist warns of the device''s unprecedented power, though his son dismisses it as an ''Uncle Ben'' speech.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1281, 387, 'emotion', 'apathy', NULL, 'The son''s initial attitude is described as the ''deadpan apathy of a terminally online teenager''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1282, 388, 'emotion', 'dread', NULL, 'The wife''s fear is specific and existential, believing the cube could be a literal portal to hell.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1283, 388, 'theme', 'cosmic horror', NULL, 'The cube is compared to the Hellraiser box, and the claw to something from the ''Leviathan'', invoking themes of forbidden, dangerous knowledge.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1284, 388, 'sensory', 'visual', NULL, 'The description focuses on the cube''s intricate etchings and its dark, pulsing sheen.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1285, 389, 'emotion', 'skepticism', NULL, 'The wife''s ''razor-sharp'' skepticism doubts the protagonist has ever done anything slowly or carefully.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1286, 389, 'theme', 'hubris vs. caution', NULL, 'The central conflict between the protagonist''s desire to test his powerful creation and his wife''s disbelief in his ability to be cautious.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1287, 390, 'theme', 'unleashing power', NULL, 'The first controlled activation of the device marks a turning point from discussion to action.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1288, 390, 'sensory', 'visual', NULL, 'The cube''s activation creates a distinct visual effect: ''eerie light spreading out in rippling waves, casting long, surreal shadows''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1289, 390, 'sensory', 'auditory', NULL, 'The cube emits a ''faint hum'' against the protagonist''s fingertips.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:06:22.683423-05', '2026-02-27 15:06:22.683423-05');
INSERT INTO public.semantic_tags VALUES (1290, 391, 'theme', 'finality', NULL, 'The beat is defined by the absolute end of something significant.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:07:38.158904-05', '2026-02-27 15:07:38.158904-05');
INSERT INTO public.semantic_tags VALUES (1291, 391, 'emotion', 'solemnity', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 15:07:38.158904-05', '2026-02-27 15:07:38.158904-05');
INSERT INTO public.semantic_tags VALUES (1292, 392, 'theme', 'transition', NULL, 'The shift from one state to another is symbolized by the fading light.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:07:38.158904-05', '2026-02-27 15:07:38.158904-05');
INSERT INTO public.semantic_tags VALUES (1293, 392, 'sensory', 'visual', NULL, 'The primary sensory input is the dimming light of twilight.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:07:38.158904-05', '2026-02-27 15:07:38.158904-05');
INSERT INTO public.semantic_tags VALUES (1294, 392, 'emotion', 'reverence', NULL, 'The presence of the ancestral honor guard imparts a feeling of deep respect for the passing era.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:07:38.158904-05', '2026-02-27 15:07:38.158904-05');
INSERT INTO public.semantic_tags VALUES (1295, 393, 'theme', 'legacy', NULL, 'The fortress represents the lasting, physical and symbolic legacy of the era of conquest.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:07:38.158904-05', '2026-02-27 15:07:38.158904-05');
INSERT INTO public.semantic_tags VALUES (1296, 393, 'sensory', 'visual', NULL, 'The image of the castle is the central focus.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:07:38.158904-05', '2026-02-27 15:07:38.158904-05');
INSERT INTO public.semantic_tags VALUES (1298, 394, 'emotion', 'Hope', NULL, 'The feeling associated with the act of breaking free and the possibility of a new state of being.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:06.506523-05', '2026-02-27 15:08:06.506523-05');
INSERT INTO public.semantic_tags VALUES (1299, 394, 'theme', 'Freedom', NULL, 'The central theme of the beat is the struggle for and attainment of liberation from constraints.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:06.506523-05', '2026-02-27 15:08:06.506523-05');
INSERT INTO public.semantic_tags VALUES (1300, 394, 'sensory', 'Auditory', NULL, 'The imagined, sharp sound of shattering shackles.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:06.506523-05', '2026-02-27 15:08:06.506523-05');
INSERT INTO public.semantic_tags VALUES (1301, 395, 'emotion', 'Despair', NULL, 'The crushing feeling of progress being undone and being returned to a state of confinement.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:06.506523-05', '2026-02-27 15:08:06.506523-05');
INSERT INTO public.semantic_tags VALUES (1302, 395, 'theme', 'Regression', NULL, 'The core action of the beat is a forced return to a previous, undesirable state.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:06.506523-05', '2026-02-27 15:08:06.506523-05');
INSERT INTO public.semantic_tags VALUES (1303, 395, 'sensory', 'Tactile', NULL, 'The physical sensation of being bound, constricted, and pulled backward by an irresistible force.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:06.506523-05', '2026-02-27 15:08:06.506523-05');
INSERT INTO public.semantic_tags VALUES (1304, 396, 'emotion', 'Hope', NULL, 'The emergence of something new after a period of difficulty inspires hope.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:47.945044-05', '2026-02-27 15:08:47.945044-05');
INSERT INTO public.semantic_tags VALUES (1305, 396, 'theme', 'Rebirth', NULL, 'A new era breaking forth from struggle is a classic rebirth motif.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:47.945044-05', '2026-02-27 15:08:47.945044-05');
INSERT INTO public.semantic_tags VALUES (1306, 396, 'sensory', 'Visual', NULL, 'The concept of a ''dawning'' era evokes strong visual imagery of light overcoming darkness.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:47.945044-05', '2026-02-27 15:08:47.945044-05');
INSERT INTO public.semantic_tags VALUES (1307, 397, 'emotion', 'Awe', NULL, 'Contemplating an eternal, unending cycle inspires a sense of cosmic awe.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:47.945044-05', '2026-02-27 15:08:47.945044-05');
INSERT INTO public.semantic_tags VALUES (1308, 397, 'theme', 'Inevitability', NULL, 'The cycle''s eternal continuation suggests that change and repetition are unavoidable forces.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:47.945044-05', '2026-02-27 15:08:47.945044-05');
INSERT INTO public.semantic_tags VALUES (1309, 397, 'sensory', 'Atmospheric', NULL, 'The feeling of timelessness and cosmic scale is an atmospheric sensation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:08:47.945044-05', '2026-02-27 15:08:47.945044-05');
INSERT INTO public.semantic_tags VALUES (1310, 398, 'emotion', 'paranoia', NULL, 'Todd''s frantic belief that Stacey has intentionally done something to him.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1311, 398, 'theme', 'squalor', NULL, 'The oppressive and filthy state of the trailer is described in detail.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1312, 398, 'sensory', 'olfactory', NULL, 'The scene is defined by the smell of stale beer, fried bologna, and a sickly, acrid odor.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1313, 399, 'emotion', 'dawning horror', NULL, 'Stacey''s realization that the hallucination is shared and not a normal ''trip''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1314, 399, 'theme', 'consequence', NULL, 'Stacey''s ''harmless'' act of drugging Todd has unforeseen and terrifying consequences.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1315, 399, 'sensory', 'visual distortion', NULL, 'Hands morphing into branches and walls warping into masks.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1316, 400, 'emotion', 'terror', NULL, 'The complete collapse of reality and Stacey''s scream for her daughter.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1317, 400, 'theme', 'reality shift', NULL, 'The physical transportation from a mundane, albeit horrifying, setting to an alien one.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1318, 400, 'sensory', 'auditory assault', NULL, 'The ''sharp shriek, like metal shearing against metal'' that precedes the reality collapse.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:09:35.797104-05', '2026-02-27 15:09:35.797104-05');
INSERT INTO public.semantic_tags VALUES (1319, 401, 'emotion', 'dread', NULL, 'The slow realization of the scale and nature of the Skeletal Titan inspires a profound sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1320, 401, 'theme', 'cosmic_horror', NULL, 'The impossible landscape and biomechanical titan defy comprehension, suggesting a hostile universe.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1321, 401, 'sensory', 'auditory', NULL, 'The titan''s growl is described as a symphony of both primal and mechanical sounds.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1322, 402, 'emotion', 'terror', NULL, 'Their flight is described as being fueled by a terror so primal it strips them of conscious thought.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1323, 402, 'theme', 'desperate_survival', NULL, 'The characters are reduced to creatures of raw instinct, running to endure.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1324, 402, 'sensory', 'tactile', NULL, 'The feeling of burning lungs and razor-sharp rocks tearing at their feet grounds the horror physically.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1325, 403, 'emotion', 'exhaustion', NULL, 'Stacey''s physical and mental collapse is the central action of the beat.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1326, 403, 'theme', 'fleeting_humanity', NULL, 'Todd''s act of helping Stacey is a small, unexpected moment of connection amidst the nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1327, 403, 'sensory', 'visual', NULL, 'The appearance of a distant green glow provides a stark contrast to the red and black landscape, representing a sliver of hope or change.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1328, 404, 'theme', 'temptation', NULL, 'The mysterious voice offers an end to suffering, a tempting promise in their desperate state.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1329, 404, 'sensory', 'mental', NULL, 'The primary sensory experience is the telepathic voice, an internal rather than external sound.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1330, 404, 'emotion', 'desperation', NULL, 'They are so broken that the voice''s offer, though terrifying, is also a potential lifeline.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:10:22.064882-05', '2026-02-27 15:10:22.064882-05');
INSERT INTO public.semantic_tags VALUES (1331, 405, 'emotion', 'hope', NULL, 'A ''tiny ember of hope'' flickers within them, representing a fragile but persistent will to endure.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.semantic_tags VALUES (1332, 405, 'theme', 'sanctuary', NULL, 'The lake is described as a ''sanctuary amidst chaos,'' offering a mirage of safety and normalcy.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.semantic_tags VALUES (1333, 405, 'sensory', 'visual', NULL, 'The scene is dominated by the visual contrast between the ''emerald lake'' and the ''crimson hellscape''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.semantic_tags VALUES (1334, 405, 'sensory', 'auditory', NULL, 'The ''sound of genuine laughter'' from the visions contrasts with the implied sounds of the hellscape.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.semantic_tags VALUES (1335, 406, 'emotion', 'surrender', NULL, 'Todd and Stacey''s unison acceptance signifies a surrender born of exhaustion and despair.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.semantic_tags VALUES (1336, 406, 'theme', 'temptation', NULL, 'The voice''s offer is described as a temptation that ''pricked like a thousand thorns''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.semantic_tags VALUES (1337, 406, 'sensory', 'auditory', NULL, 'The primary action is driven by ''the voice'' which ''whispered, soft yet insistent''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.semantic_tags VALUES (1338, 406, 'emotion', 'weariness', NULL, 'Their decision is framed by their broken state and ''weary acceptance''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:06.191544-05', '2026-02-27 15:11:06.191544-05');
INSERT INTO public.semantic_tags VALUES (1339, 407, 'emotion', 'confusion', NULL, 'Stacey''s disorientation as she tries to separate the dream from her squalid reality.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.semantic_tags VALUES (1699, 533, 'emotion', 'Dread', NULL, 'The narrator''s mind is being filled with ''unspeakable horrors''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:46:32.702514-05', '2026-02-27 15:46:32.702514-05');
INSERT INTO public.semantic_tags VALUES (1340, 407, 'sensory', 'olfactory', NULL, 'The stink of the trailer and sour beer grounds the scene in a grimy, physical world.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.semantic_tags VALUES (1341, 407, 'theme', 'reality vs. illusion', NULL, 'The physical wound serves as a bridge, proving the illusion was terrifyingly real.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.semantic_tags VALUES (1342, 407, 'emotion', 'dawning horror', NULL, 'The moment Stacey realizes the blood on her jeans is real.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.semantic_tags VALUES (1343, 408, 'emotion', 'resignation', NULL, 'Stacey and Todd''s weariness and acceptance of being marked by something beyond their control.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.semantic_tags VALUES (1344, 408, 'theme', 'shared fate', NULL, 'The wordless understanding solidifies that they are in this together, for better or worse.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.semantic_tags VALUES (1345, 408, 'theme', 'the unknown', NULL, 'The entity''s purpose is a mystery, forcing them into a passive state of waiting.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.semantic_tags VALUES (1346, 408, 'sensory', 'tactile', NULL, 'Todd rubbing his aching side provides a physical sensation tied to the supernatural event.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:11:47.730629-05', '2026-02-27 15:11:47.730629-05');
INSERT INTO public.semantic_tags VALUES (1347, 409, 'theme', 'cosmic horror', NULL, 'The awakening of a vast, unknowable entity from a timeless slumber.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.semantic_tags VALUES (1348, 409, 'emotion', 'awareness', NULL, 'The transition from a state of non-dreaming slumber to active perception.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.semantic_tags VALUES (1349, 409, 'sensory', 'conceptual', NULL, 'The entity perceives a flaw in the concept of reality itself, not a physical sensation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.semantic_tags VALUES (1350, 410, 'theme', 'hubris', NULL, 'Mortals are described as tampering with things beyond their comprehension.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.semantic_tags VALUES (1351, 410, 'emotion', 'curiosity', NULL, 'I AM''s reaction is a mix of amusement and ''something dangerously close to intrigue''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.semantic_tags VALUES (1352, 410, 'sensory', 'extrasensory perception', NULL, 'The entity uses ''eyes that were not eyes'' to peer through veils between realms.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:12:47.75463-05', '2026-02-27 15:12:47.75463-05');
INSERT INTO public.semantic_tags VALUES (1353, 411, 'theme', 'Return', NULL, 'The Watchers return from a state of non-existence or banishment, re-introducing a major force into the narrative.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1354, 411, 'emotion', 'Foreboding', NULL, 'Their ''unspoken intent'' creates a powerful sense of dread and anticipation for what they will do.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1355, 411, 'sensory', 'Energy', NULL, 'Their presence is not just seen or heard, but felt as a ''crackling'' energy in the void.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1356, 412, 'theme', 'Deliberation', NULL, 'The entities weigh the risks and rewards of interfering with a lesser species.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1357, 412, 'emotion', 'Detachment', NULL, 'I AM observes with ancient curiosity, removed from the passionate debate of the Watchers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1358, 412, 'sensory', 'Auditory', NULL, 'The beat is defined by the contrasting voices of the Watchers—some whispered, some roared.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1359, 413, 'theme', 'Incitment', NULL, 'The fourth entity''s demand acts as a catalyst, pushing the group from debate to action.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1360, 413, 'emotion', 'Malice', NULL, 'The fourth''s voice is ''dripping with malice and madness,'' revealing a purely predatory motive.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1361, 413, 'sensory', 'Auditory', NULL, 'The sharp, ''hissed'' command of the fourth being cuts through the other sounds of the debate.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:13:21.912298-05', '2026-02-27 15:13:21.912298-05');
INSERT INTO public.semantic_tags VALUES (1362, 414, 'emotion', 'terror', NULL, 'The overwhelming fear experienced by humanity as their new ''masters'' arrive.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1363, 414, 'theme', 'divine punishment', NULL, 'The entities are framing their actions as a righteous punishment for humanity''s hubris.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1364, 414, 'sensory', 'auditory', NULL, 'The scene is dominated by screams, cries, and the growled words of the entities.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1365, 415, 'emotion', 'mania', NULL, 'The Dreamer''s state of mind is one of maniacal laughter and reckless jubilation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1366, 415, 'theme', 'hubris', NULL, 'The Dreamer''s creation of the Matter Replicator is the ultimate act of mortal arrogance.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1367, 415, 'sensory', 'visual', NULL, 'The description of reality tearing and dimensions crumbling creates a chaotic visual.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1368, 416, 'emotion', 'sadism', NULL, 'The entities debate the most pleasurable and cruel way to destroy mortals.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1369, 416, 'theme', 'manipulation', NULL, 'The chosen method of destruction is not direct force, but corrupting mortals from within.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1370, 416, 'sensory', 'auditory', NULL, 'The beat is characterized by the ''cacophony of voices'' during the debate.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1371, 417, 'emotion', 'despair', NULL, 'The finality of the dreamer''s fate—no redemption, only insanity and death.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1372, 417, 'theme', 'retribution', NULL, 'The entities exact their revenge, ensuring mortals will never threaten the cosmic balance again.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:14:12.843937-05', '2026-02-27 15:14:12.843937-05');
INSERT INTO public.semantic_tags VALUES (1373, 418, 'theme', 'Vigilance', NULL, 'I AM''s observation is patient and predatory, not passive.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.semantic_tags VALUES (1374, 418, 'emotion', 'Stealth', NULL, 'The entity''s withdrawal is seamless and unnoticed, highlighting its clandestine nature.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.semantic_tags VALUES (1375, 418, 'sensory', 'Absence', NULL, 'The focus is on the lack of action and the formless nature of the misty realm.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.semantic_tags VALUES (1376, 419, 'emotion', 'Revelation', NULL, 'A profound and terrible truth about the nature of the world''s suffering is revealed.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.semantic_tags VALUES (1377, 419, 'theme', 'Predation', NULL, 'The language of ''feast'' and ''feeding grounds'' frames the entire conflict as a predator-prey dynamic on a cosmic scale.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.semantic_tags VALUES (1378, 419, 'theme', 'Perverted Sacredness', NULL, 'The term ''sacred'' is used to describe a prison designed for harvesting suffering, twisting a holy concept into something monstrous.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:15:11.588631-05', '2026-02-27 15:15:11.588631-05');
INSERT INTO public.semantic_tags VALUES (1379, 420, 'emotion', 'anticipation', NULL, 'The wife''s eyes glint with anticipation, and the protagonist feels a rush of adrenaline.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1380, 420, 'theme', 'calculated risk', NULL, 'The couple is knowingly taking a huge risk to test the limits of their technology.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1381, 420, 'sensory', 'visual', NULL, 'The scene is established with the couple approaching the massive RV in the corner of the lot.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1382, 421, 'emotion', 'tension', NULL, 'The couple waits in ''tense silence'' while the machine works.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1383, 421, 'theme', 'creation', NULL, 'An otherworldly process is actively creating a complex object from nothing.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1384, 421, 'sensory', 'auditory', NULL, 'The Replicator hums, whirs, and emits a final chime.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1385, 421, 'sensory', 'visual', NULL, 'A faint blue light flickers and an otherworldly mist forms and intensifies.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1386, 422, 'emotion', 'triumph', NULL, 'The protagonist feels a ''surge of triumph'' at the perfect success of the experiment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1387, 422, 'emotion', 'awe', NULL, 'The wife''s jaw drops in disbelief, and they both marvel at the flawless replica.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1388, 422, 'theme', 'consequence', NULL, 'The initial excitement is immediately followed by a discussion of the practical problems and risks the duplicate creates.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:16:17.373813-05', '2026-02-27 15:16:17.373813-05');
INSERT INTO public.semantic_tags VALUES (1389, 423, 'emotion', 'wonder', NULL, 'The family marvels at the perfect duplication of the keys and mug.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.semantic_tags VALUES (1390, 423, 'theme', 'discovery', NULL, 'The initial, safe phase of experimentation with a new technology.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
INSERT INTO public.semantic_tags VALUES (1391, 423, 'sensory', 'auditory', NULL, 'The ''soft hum'' of the replicator is the sound of creation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:17:06.451164-05', '2026-02-27 15:17:06.451164-05');
