INSERT INTO public.semantic_tags VALUES (1700, 533, 'theme', 'Forbidden Knowledge', NULL, 'The realization that human technology is actually a conduit for ancient, sinister forces.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:46:32.702514-05', '2026-02-27 15:46:32.702514-05');
INSERT INTO public.semantic_tags VALUES (1701, 533, 'sensory', 'Tactile', NULL, 'The sharp, digging sensation of the ''unforgiving metal of the office chair''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:46:32.702514-05', '2026-02-27 15:46:32.702514-05');
INSERT INTO public.semantic_tags VALUES (1702, 533, 'sensory', 'Visual', NULL, 'The ''sickly yellow hue'' from the ''flickering fluorescent lights''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:46:32.702514-05', '2026-02-27 15:46:32.702514-05');
INSERT INTO public.semantic_tags VALUES (1703, 534, 'emotion', 'Resignation', NULL, 'The narrator accepts his role as a pawn, no longer fighting the realization.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:46:32.702514-05', '2026-02-27 15:46:32.702514-05');
INSERT INTO public.semantic_tags VALUES (1704, 534, 'theme', 'Cosmic Horror', NULL, 'The central theme of being an insignificant piece in a game played by vast, unknowable entities.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:46:32.702514-05', '2026-02-27 15:46:32.702514-05');
INSERT INTO public.semantic_tags VALUES (1705, 534, 'sensory', 'Auditory', NULL, 'The ''chaotic choir from beyond the stars'' that fills the narrator''s ears.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:46:32.702514-05', '2026-02-27 15:46:32.702514-05');
INSERT INTO public.semantic_tags VALUES (1706, 534, 'emotion', 'Despair', NULL, 'The narrator''s certainty that this is the beginning of a ''descent into madness and despair''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:46:32.702514-05', '2026-02-27 15:46:32.702514-05');
INSERT INTO public.semantic_tags VALUES (1707, 535, 'emotion', 'sorrow', NULL, 'The son''s genuine sadness over his pet''s death.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1708, 535, 'theme', 'cyclical loss', NULL, 'The text implies that the death and replacement of ''Timmy'' is a recurring event.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1709, 535, 'sensory', 'auditory', NULL, 'The initial hum of the matter replicator starting its cycle.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1710, 536, 'emotion', 'anxiety', NULL, 'The father''s simmering fear as he recalls the doctor''s words.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1711, 536, 'theme', 'mortality', NULL, 'The father is forced to confront his own physical decay and the serious consequences.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1712, 536, 'sensory', 'auditory', NULL, 'The faint, oppressive buzz of the fluorescent light in the doctor''s office.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1713, 537, 'emotion', 'epiphany', NULL, 'The ''dangerous idea'' hits the father like a brick, a sudden moment of clarity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1714, 537, 'theme', 'transhumanism', NULL, 'The core idea of using technology to overcome biological limitations is born.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1715, 537, 'sensory', 'visual', NULL, 'The glow of the replicator illuminating the kitchen as it creates a new lifeform.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1716, 538, 'emotion', 'hope', NULL, 'Despite the fear, the father''s idea represents a desperate hope for a solution.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1717, 538, 'theme', 'risk vs reward', NULL, 'The conversation explicitly weighs the scariness of the unknown against the scariness of inaction.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1718, 538, 'sensory', 'tactile', NULL, 'The father places a reassuring hand on his son''s shoulder.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:47:41.342555-05', '2026-02-27 15:47:41.342555-05');
INSERT INTO public.semantic_tags VALUES (1719, 539, 'emotion', 'desperation', NULL, 'The Father is driven by a mix of fear for his health and hope in his own genius.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1720, 539, 'theme', 'secrecy', NULL, 'The entire project is built in secret to shield his family from potential fallout.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1721, 539, 'sensory', 'visual', NULL, 'The description of the AutoDoc''s ''glowing cloud-like interior'' creates a sense of otherworldly potential.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1722, 540, 'emotion', 'agony', NULL, 'The pain is described as absolute and reality-warping, a form of annihilation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1723, 540, 'theme', 'transformation', NULL, 'The Father''s body is being violently torn apart and rebuilt, a painful metamorphosis.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1724, 540, 'sensory', 'tactile', NULL, 'The sensation of being ''flayed apart'' and every nerve being ''alight with fire'' is the core of the beat.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1725, 540, 'sensory', 'auditory', NULL, 'The Father''s ''raw and primal'' scream highlights the intensity of his suffering.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1726, 541, 'emotion', 'fury', NULL, 'The Wife''s initial reaction is blazing anger at her husband''s recklessness and secrecy.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1727, 541, 'theme', 'confrontation', NULL, 'The secrecy of the experiment leads to a direct and angry confrontation with his family.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1728, 541, 'sensory', 'auditory', NULL, 'The beat is punctuated by the ''mechanical banging'' of the robot and the Wife''s yelling.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1729, 542, 'emotion', 'unease', NULL, 'Despite the success, the memory of the agony lingers, creating a sense of unease about the technology.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1730, 542, 'theme', 'consequence', NULL, 'The Wife establishes a firm consequence: the pain must be eliminated. Progress cannot come at such a cost.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1731, 542, 'emotion', 'awe', NULL, 'Both characters acknowledge the ''amazing'' result of the experiment, even amidst the conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:48:27.36101-05', '2026-02-27 15:48:27.36101-05');
INSERT INTO public.semantic_tags VALUES (1732, 543, 'theme', 'transhumanism', NULL, 'Father is actively rewriting the nature of life to overcome aging and illness.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1733, 543, 'emotion', 'empowerment', NULL, 'Father is ''emboldened'' by his initial success with painless operation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1734, 543, 'theme', 'healing', NULL, 'The technology is proven by its ability to effortlessly cure his son.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1735, 544, 'emotion', 'terror', NULL, 'The interface is described as a ''cataclysm'' and an ''all-consuming storm'' that causes existential pain.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1736, 544, 'theme', 'loss_of_self', NULL, 'Father''s ''sense of self dissolved'' under the weight of the infinite knowledge.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1737, 544, 'sensory', 'kinesthetic', NULL, 'The experience is intensely physical: ''body convulsed violently,'' ''limbs twisted, became fluid''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1738, 544, 'theme', 'hubris', NULL, 'He acknowledges the ''daring'' step and the fear of ''venturing too far''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1739, 545, 'emotion', 'love', NULL, 'The final realization is that ''the love in this finite life'' is what truly defines him.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1740, 545, 'theme', 'humanity', NULL, 'Despite gaining infinite knowledge, he chooses a simple, human connection over a complex, calculated response.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1741, 545, 'sensory', 'auditory', NULL, 'His wife''s voice breaks the silence and pulls him back to reality.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:49:24.920784-05', '2026-02-27 15:49:24.920784-05');
INSERT INTO public.semantic_tags VALUES (1742, 546, 'emotion', 'Horror', NULL, 'The protagonist is overwhelmed by horrifying sensations in their new mortal form.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (2663, 845, 'sensory', 'Visual', NULL, 'TJ''s eyes are described as being ''alight with an audacious idea''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:22:13.658445-05', '2026-02-27 20:22:13.658445-05');
INSERT INTO public.semantic_tags VALUES (1743, 546, 'theme', 'Powerlessness', NULL, 'A great deity is stripped of their power and reduced to an insignificant speck.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1744, 546, 'sensory', 'Tactile', NULL, 'The feeling of hot flames licking at the body.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1745, 547, 'emotion', 'Outrage', NULL, 'The protagonist is filled with outrage at the violation of natural laws.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1746, 547, 'theme', 'Confrontation', NULL, 'The ancient deity emerges to directly challenge the protagonist''s beliefs.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1747, 547, 'sensory', 'Auditory', NULL, 'The deity''s voice, which carries both gentleness and authority.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1748, 548, 'emotion', 'Skepticism', NULL, 'The protagonist scoffs at the deity''s ''naïve'' perspective on humanity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1749, 548, 'theme', 'Debate', NULL, 'The core of the beat is a philosophical argument about the merits and dangers of immortality.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1750, 549, 'emotion', 'Hope', NULL, 'The protagonist feels a glimmer of hope that humans could handle immortality if guided.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1751, 549, 'theme', 'Compromise', NULL, 'The protagonist relents and agrees to seek a balance rather than outright forbid immortality.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1752, 549, 'theme', 'Unity', NULL, 'The two deities agree to work together on a shared goal.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:50:21.105545-05', '2026-02-27 15:50:21.105545-05');
INSERT INTO public.semantic_tags VALUES (1753, 550, 'emotion', 'Fear', NULL, 'The narrator''s mind races with fear and revulsion upon arrival.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.semantic_tags VALUES (1754, 550, 'theme', 'Cosmic Horror', NULL, 'The scene is defined by horrors beyond mortal comprehension and the threat of insanity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.semantic_tags VALUES (1755, 550, 'sensory', 'Olfactory', NULL, 'The stench of decay and rotting flesh is a dominant sensory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.semantic_tags VALUES (1756, 550, 'sensory', 'Auditory', NULL, 'The combination of maddening whispers and distant screams creates a horrific soundscape.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.semantic_tags VALUES (1757, 551, 'emotion', 'Fascination', NULL, 'The narrator expresses a ''twisted fascination'' with the mortals'' self-destruction.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.semantic_tags VALUES (1758, 551, 'theme', 'Hubris', NULL, 'The central theme is that mortal hubris in trying to cheat death leads to destruction.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.semantic_tags VALUES (1759, 551, 'theme', 'Transgression', NULL, 'The mortals'' actions are framed as an affront to the natural order of life and death.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.semantic_tags VALUES (1760, 551, 'sensory', 'Kinesthetic', NULL, 'The narrator feels a physical sickness and weakening of their powers due to the realm''s corruption.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:51:16.120877-05', '2026-02-27 15:51:16.120877-05');
INSERT INTO public.semantic_tags VALUES (1761, 552, 'theme', 'family', NULL, 'The trip is motivated by a deep-seated need for family connection and reconnection with heritage.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1762, 552, 'emotion', 'longing', NULL, 'The wife''s unmistakable longing to see her mother is the primary catalyst for the trip.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1763, 553, 'theme', 'inspiration', NULL, 'A random documentary plants a seed of an idea that will grow into an obsession for the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1764, 553, 'emotion', 'fascination', NULL, 'The narrator becomes captivated by the scientific puzzle of teleportation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1765, 553, 'sensory', 'auditory', NULL, 'The droning voice of the documentary''s narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1766, 554, 'emotion', 'joy', NULL, 'The overwhelming emotion of the family reunion at the airport.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1767, 554, 'theme', 'homecoming', NULL, 'The scene is centered on the wife''s emotional return to her country of birth.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1768, 554, 'sensory', 'tactile', NULL, 'The warm embrace between the grandmother and her daughter.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1769, 555, 'theme', 'duality', NULL, 'The narrator is torn between being present with his family and pursuing his intellectual obsession.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1770, 555, 'emotion', 'preoccupation', NULL, 'The narrator''s mind constantly drifts towards his calculations, even amidst beautiful and meaningful moments.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1771, 555, 'sensory', 'visual', NULL, 'The description of Kyoto''s temples in golden light and lantern-lit alleyways.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1772, 555, 'sensory', 'olfactory', NULL, 'The heady aromas of street food in the markets of Kyoto.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:52:21.637217-05', '2026-02-27 15:52:21.637217-05');
INSERT INTO public.semantic_tags VALUES (1773, 556, 'emotion', 'nostalgia', NULL, 'The couple reflects on past visits to Kyoto and how little it has changed.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:53:08.481802-05', '2026-02-27 15:53:08.481802-05');
INSERT INTO public.semantic_tags VALUES (1774, 556, 'theme', 'timelessness', NULL, 'Kyoto is described as timeless, a place that doesn''t change, which contrasts with how the characters have aged.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:53:08.481802-05', '2026-02-27 15:53:08.481802-05');
INSERT INTO public.semantic_tags VALUES (1775, 556, 'sensory', 'olfactory', NULL, 'The air hums with the scent of sizzling yakitori and sweet Sakura blossoms.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:53:08.481802-05', '2026-02-27 15:53:08.481802-05');
INSERT INTO public.semantic_tags VALUES (1776, 557, 'emotion', 'inspiration', NULL, 'The chef''s words provide a reminder about the importance of human connection over raw numbers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:53:08.481802-05', '2026-02-27 15:53:08.481802-05');
INSERT INTO public.semantic_tags VALUES (1777, 557, 'theme', 'passion over profit', NULL, 'The chef''s philosophy that ''Success is measured in smiles, not sales'' resonates with the couple''s business perspective.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:53:08.481802-05', '2026-02-27 15:53:08.481802-05');
INSERT INTO public.semantic_tags VALUES (1778, 557, 'sensory', 'gustatory', NULL, 'The couple savors the taste of the gleaming, perfect sushi.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:53:08.481802-05', '2026-02-27 15:53:08.481802-05');
INSERT INTO public.semantic_tags VALUES (1779, 558, 'emotion', 'obsession', NULL, 'The narrator is tethered to his work, unable to let go despite frustrating setbacks.', 'gemini', 'gemini-2.5-pro', '2026-02-27 15:53:08.481802-05', '2026-02-27 15:53:08.481802-05');
