INSERT INTO public.semantic_tags VALUES (2028, 643, 'sensory', 'visual novelty', NULL, 'Watching robots handle administrative tasks provides a striking, almost surreal visual impression.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:27:27.353131-05', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.semantic_tags VALUES (2029, 644, 'theme', 'concealment and deception', NULL, 'A global network of facades is constructed specifically to misdirect scrutiny and protect The S Corp''s true nature.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:27:27.353131-05', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.semantic_tags VALUES (2030, 644, 'emotion', 'controlled anxiety', NULL, 'The Narrator acknowledges exposure is inevitable but channels unease into strategic planning.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:27:27.353131-05', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.semantic_tags VALUES (2031, 644, 'sensory', 'understated visual presence', NULL, 'The facades are deliberately unassuming — ''nothing grand, nothing ostentatious'' — projecting deliberate ordinariness.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:27:27.353131-05', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.semantic_tags VALUES (2032, 644, 'theme', 'paranoia and preemption', NULL, 'Proactive measures against future exposure reflect a growing awareness that secrecy has limits.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:27:27.353131-05', '2026-02-27 19:27:27.353131-05');
INSERT INTO public.semantic_tags VALUES (2033, 645, 'sensory', 'tactile-cold', NULL, 'Frigid air clings like a shroud; ice encases the entity''s body across millennia of dormancy.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:28:40.312583-05', '2026-02-27 19:28:40.312583-05');
