INSERT INTO public.semantic_tags VALUES (2039, 647, 'emotion', 'primal terror', NULL, 'Claustrophobia grips the entity — an entirely new and alien sensation for its immortal mind.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:28:40.312583-05', '2026-02-27 19:28:40.312583-05');
