INSERT INTO public.semantic_tags VALUES (2042, 647, 'emotion', 'dread', NULL, 'Dread consumes the entity as it recognizes the sacrilege of its imprisonment.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:28:40.312583-05', '2026-02-27 19:28:40.312583-05');
