INSERT INTO public.semantic_tags VALUES (2045, 648, 'emotion', 'explosive release', NULL, 'Power boils under skin with uncontrollable ferocity before rupturing outward — catharsis through annihilation.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:28:40.312583-05', '2026-02-27 19:28:40.312583-05');
