INSERT INTO public.semantic_tags VALUES (2049, 650, 'sensory', 'olfactory-rot', NULL, 'Stench like rotting flesh assails the entity upon exiting the cavern.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.semantic_tags VALUES (2050, 650, 'emotion', 'violation', NULL, 'The entity perceives the colony as a desecration of its ancient sacred domain.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-02-27 19:29:52.368815-05');
