INSERT INTO public.semantic_tags VALUES (2052, 650, 'sensory', 'visual-eerie-glow', NULL, 'Otherworldly light pulsing from alien technology against torn, mangled ice.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.semantic_tags VALUES (2053, 651, 'emotion', 'cosmic-madness', NULL, 'The entity is overwhelmed by an irresistible dark call that supersedes its own fury.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-02-27 19:29:52.368815-05');
