INSERT INTO public.semantic_tags VALUES (2056, 651, 'emotion', 'rage-transcending-to-frenzy', NULL, 'Long-forgotten emotions reignite and are then overwhelmed by something darker and more consuming.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.semantic_tags VALUES (2057, 652, 'emotion', 'primal-fury', NULL, 'Unyielding determination and primal rage drive the entity''s surge toward the surface.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-02-27 19:29:52.368815-05');
