INSERT INTO public.semantic_tags VALUES (2061, 653, 'sensory', 'auditory-screams', NULL, 'Colonists'' screams echo in the entity''s mind like a chorus of insanity.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-02-27 19:29:52.368815-05');
INSERT INTO public.semantic_tags VALUES (2062, 653, 'emotion', 'exultation-in-destruction', NULL, 'The entity revels in the chaos and gore, framing annihilation as righteous vengeance.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:29:52.368815-05', '2026-02-27 19:29:52.368815-05');
