INSERT INTO public.semantic_tags VALUES (2069, 655, 'emotion', 'disorientation', NULL, 'The Entity cannot reconcile the concept of home with its fractured, cosmic existence.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:31:10.357686-05', '2026-02-27 19:31:10.357686-05');
