INSERT INTO public.semantic_tags VALUES (2081, 659, 'emotion', 'awe', NULL, 'Trembling hands and held breath convey the overwhelming emotional weight of the historic confirmation.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:15.870282-05', '2026-02-27 19:32:15.870282-05');
INSERT INTO public.semantic_tags VALUES (2082, 659, 'sensory', 'visual — blinking screen notification', NULL, 'The blinking email notification is the sole sensory trigger that launches the entire scene''s momentum.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:15.870282-05', '2026-02-27 19:32:15.870282-05');
INSERT INTO public.semantic_tags VALUES (2083, 659, 'theme', 'historic milestone', NULL, 'July 8th, 2024 is marked as the precise moment of unprecedented financial ascension.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:15.870282-05', '2026-02-27 19:32:15.870282-05');
INSERT INTO public.semantic_tags VALUES (2084, 660, 'theme', 'secrecy as power', NULL, 'Privacy is framed not as weakness but as a deliberate strategic weapon — information asymmetry as dominance.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:15.870282-05', '2026-02-27 19:32:15.870282-05');
