INSERT INTO public.semantic_tags VALUES (2086, 660, 'sensory', 'tactile — weight of choice', NULL, 'The narrator physically processes the decision, the moment grounded in a sense of deliberate restraint.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:15.870282-05', '2026-02-27 19:32:15.870282-05');
