INSERT INTO public.semantic_tags VALUES (2089, 661, 'sensory', 'conceptual vastness', NULL, 'The ''limitless possibilities ahead'' evokes a panoramic, almost vertiginous sense of scale beyond physical sensation.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:15.870282-05', '2026-02-27 19:32:15.870282-05');
INSERT INTO public.semantic_tags VALUES (2090, 662, 'emotion', 'curiosity', NULL, 'Son''s moody teen energy gives way to genuine fascination with conspiracy theories.', 'claude', 'claude-sonnet-4-6', '2026-02-27 19:32:59.228789-05', '2026-02-27 19:32:59.228789-05');
