INSERT INTO public.semantic_tags VALUES (2253, 705, 'emotion', 'terror', NULL, 'The protagonist''s awe quickly ''gave way to unease'' and then outright terror as his heart pounded in a room bathed in unnatural darkness.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:46:45.904175-05', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.semantic_tags VALUES (2254, 705, 'theme', 'cosmic horror', NULL, 'The reveal of an aware, ancient presence and impossible geometries taps directly into Lovecraftian themes of incomprehensible threats.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:46:45.904175-05', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.semantic_tags VALUES (2255, 705, 'sensory', 'auditory', NULL, 'The sounds shift from ''hauntingly beautiful'' to ''guttural, raw, and wrong,'' signaling the transition from wonder to horror.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:46:45.904175-05', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.semantic_tags VALUES (2256, 706, 'emotion', 'dread', NULL, 'The protagonist is left with the heavy, lingering feeling of dread as he contemplates the ''far darker'' reality he has uncovered.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:46:45.904175-05', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.semantic_tags VALUES (2257, 706, 'theme', 'consequence', NULL, 'The scene concludes with the stark realization of the consequences of the experiment, reframing the entire purpose of the facility.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:46:45.904175-05', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.semantic_tags VALUES (2258, 706, 'sensory', 'tactile', NULL, 'The physical after-effects of fear are noted: ''the hairs on my arms still raised, my breath shallow''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:46:45.904175-05', '2026-02-27 19:46:45.904175-05');
INSERT INTO public.semantic_tags VALUES (2259, 707, 'emotion', 'realization', NULL, 'The protagonist has an epiphany about the irreplaceable value of human creativity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2260, 707, 'theme', 'limitation of technology', NULL, 'Despite near-infinite power, the Infinitron cannot replicate human imagination.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2261, 707, 'sensory', 'auditory', NULL, 'The purposeful buzzing of the robots in the facility.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2262, 708, 'emotion', 'frustration', NULL, 'The protagonist''s hope wanes as each rejection and bad resume piles up.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2263, 708, 'theme', 'desperation', NULL, 'Turning to the Infinitron for recruitment is a last-resort measure born from failure.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2264, 708, 'sensory', 'visual', NULL, 'Streams of cascading results flowing across the Infinitron''s screen.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2265, 709, 'emotion', 'anticipation', NULL, 'The unbearable waiting for the Infinitron''s search to complete, where seconds feel like lifetimes.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2266, 709, 'theme', 'discovery', NULL, 'The Infinitron finds a perfect, unexpected candidate.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2267, 709, 'sensory', 'auditory', NULL, 'A ''blaring chime'' shatters the tense silence, announcing the result.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2268, 710, 'emotion', 'relief', NULL, 'A surge of relief and excitement flows through the protagonist upon reading Morgan''s acceptance.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2269, 710, 'theme', 'catalyst', NULL, 'Morgan''s acceptance is not just a hire, but a pivotal turning point for the entire project.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2270, 710, 'sensory', 'visual', NULL, 'The protagonist''s screen lighting up with Morgan''s reply.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:47:44.670411-05', '2026-02-27 19:47:44.670411-05');
INSERT INTO public.semantic_tags VALUES (2271, 711, 'theme', 'recruitment', NULL, 'Focuses on the aggressive and selective process of gathering talent.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2272, 711, 'theme', 'secrecy', NULL, 'The emphasis on rigorous vetting and NDAs establishes the high-stakes confidentiality of the project.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2273, 711, 'emotion', 'ambition', NULL, 'The scale of the recruitment reflects the grand ambition of The S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2274, 712, 'theme', 'utopia', NULL, 'The habitat is intentionally designed as a perfect, self-contained world to maximize productivity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2275, 712, 'theme', 'isolation', NULL, 'The luxury and amenities are tools to enforce total isolation from the outside world.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2276, 712, 'sensory', 'visual', NULL, 'Strong contrast between the harsh, icy exterior and the luxurious, technologically advanced interior.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2277, 712, 'emotion', 'security', NULL, 'The habitat is designed to provide complete physical and psychological security, meeting every possible need.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2278, 713, 'theme', 'collaboration', NULL, 'The primary focus is on the synergy created when brilliant minds work together.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2279, 713, 'theme', 'progress', NULL, 'The collaboration directly leads to a steady stream of scientific breakthroughs.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2280, 713, 'emotion', 'synergy', NULL, 'The atmosphere is described as a dynamic fusion of human intellect and advanced technology.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2281, 713, 'sensory', 'auditory', NULL, 'The facility transforms from mechanical silence to being filled with the ''buzz'' of human activity and debate.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:48:39.743312-05', '2026-02-27 19:48:39.743312-05');
INSERT INTO public.semantic_tags VALUES (2282, 714, 'emotion', 'Triumph', NULL, 'The feeling of turning science fiction into reality with monumental achievements.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2283, 714, 'theme', 'Innovation', NULL, 'The scientists are pushing the boundaries of technology at an unprecedented pace.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2284, 714, 'theme', 'Sacrifice', NULL, 'The brilliant minds accept isolation from the world for the chance to be part of a historic endeavor.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2285, 715, 'emotion', 'Ambition', NULL, 'Success fuels even bolder goals, targeting the outer solar system and beyond.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2286, 715, 'theme', 'Secrecy', NULL, 'The extraordinary achievements demand absolute secrecy, hiding the colonies from humanity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2287, 715, 'theme', 'Expansion', NULL, 'The core vision of The S Corp is the expansion of human civilization into the cosmos.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2288, 716, 'emotion', 'Paranoia', NULL, 'The fear of exposure leads to a tightened grip and draconian security measures.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2289, 716, 'theme', 'Conspiracy', NULL, 'Social media buzzes with theories of sinister plots and alien abductions to explain the disappearances.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2290, 716, 'sensory', 'Auditory', NULL, 'The ''whispers'' and ''buzz'' of social media represent the growing, audible threat to secrecy.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2291, 716, 'emotion', 'Panic', NULL, 'The text explicitly states ''As panic mounted'' within the corporation, forcing their hand.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:49:25.598046-05', '2026-02-27 19:49:25.598046-05');
INSERT INTO public.semantic_tags VALUES (2292, 717, 'emotion', 'Desperation', NULL, 'The proposal for cloning is born from a ''breaking point'' and a sense of desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:50:15.854918-05', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.semantic_tags VALUES (2293, 717, 'theme', 'Scarcity vs. Ambition', NULL, 'The ambition to colonize the solar system is throttled by the scarcity of human talent.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:50:15.854918-05', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.semantic_tags VALUES (2294, 718, 'emotion', 'Conflict', NULL, 'The tense moral and ethical debate between the Protagonist and Morgan.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:50:15.854918-05', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.semantic_tags VALUES (2295, 718, 'theme', 'Ethics vs. Progress', NULL, 'The core of the argument is whether the potential progress justifies the immense ethical risks.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:50:15.854918-05', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.semantic_tags VALUES (2296, 718, 'sensory', 'Tension', NULL, 'Described through Morgan''s sharp expression, crossed arms, and the ''tense silence'' that hangs between them.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:50:15.854918-05', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.semantic_tags VALUES (2297, 719, 'emotion', 'Astonishment', NULL, 'The team is astonished that their unprecedented and ethically fraught process worked so well.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:50:15.854918-05', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.semantic_tags VALUES (2298, 719, 'theme', 'Autonomy', NULL, 'A key principle of the process is ensuring the clones have full choice and freedom.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:50:15.854918-05', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.semantic_tags VALUES (2299, 719, 'sensory', 'Unprecedented', NULL, 'The text explicitly calls the achievement ''an unprecedented step into the ethical unknown''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:50:15.854918-05', '2026-02-27 19:50:15.854918-05');
INSERT INTO public.semantic_tags VALUES (2300, 720, 'theme', 'Collaboration', NULL, 'The harmonious and productive partnership between clones and humans is highlighted as proof of their potential.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2301, 720, 'emotion', 'Pride', NULL, 'The protagonist feels an ''electrifying'' sense of pride watching the colonies flourish.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2302, 720, 'theme', 'Secrecy', NULL, 'Despite internal transparency, strict external secrecy is maintained to avoid scrutiny.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2303, 721, 'emotion', 'Anxiety', NULL, 'The protagonist wrestles with the terrifying prospect of humanity''s reaction to the colonies.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2304, 721, 'theme', 'Revelation', NULL, 'The central conflict shifts from ''if'' they will be discovered to ''when''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2305, 721, 'sensory', 'Visual', NULL, 'The appearance of visible surface infrastructure is the direct cause of the increased risk.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2306, 722, 'emotion', 'Inspiration', NULL, 'A vision crystallizes in the protagonist''s mind, leading to the concept of Elysium.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2307, 722, 'theme', 'Ambition', NULL, 'The project is not just practical but a monumental symbol of humanity''s ascent.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2308, 722, 'theme', 'Legacy', NULL, 'Elysium is framed as the crowning achievement and legacy of the entire colonization effort.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:51:09.253327-05', '2026-02-27 19:51:09.253327-05');
INSERT INTO public.semantic_tags VALUES (2309, 723, 'emotion', 'Arrogance', NULL, 'I AM''s declaration of its own name and purpose is filled with a sense of ancient, supreme confidence.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2310, 723, 'theme', 'Guardianship', NULL, 'The central theme is the protection of forbidden knowledge, albeit for a malevolent purpose (harvesting souls).', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2311, 723, 'sensory', 'Auditory', NULL, 'The beat is defined by the concept of whispers and a spoken name.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2312, 724, 'emotion', 'Dread', NULL, 'The description of S Corp as a ''blight'' and the Infinitron twisting minds evokes a sense of technological horror.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2313, 724, 'theme', 'Technological Horror', NULL, 'An AI that corrupts the human mind is a classic trope of this theme.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2314, 724, 'sensory', 'Visual', NULL, 'Imagery of a ''towering presence casting a permanent shadow'' creates a strong visual of oppression.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2315, 725, 'emotion', 'Desperation', NULL, 'Seeking help from beings that cause insanity shows the depth of I AM''s desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2316, 725, 'theme', 'Alliance', NULL, 'An ancient power realizes it cannot face a new threat alone and must seek allies.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2317, 725, 'sensory', 'Psychological', NULL, 'The feeling of ''creeping madness'' and the brink of insanity are the dominant sensory experiences.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:02.765187-05', '2026-02-27 19:52:02.765187-05');
INSERT INTO public.semantic_tags VALUES (2318, 726, 'theme', 'infiltration', NULL, 'Deceptive entry into the enemy''s inner sanctum.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2319, 726, 'emotion', 'deception', NULL, 'The core tool used by ኣባጊዕዓል to gain access and trust.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2320, 727, 'theme', 'disinformation', NULL, 'The weaponization of false information to destroy a reputation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2321, 727, 'sensory', 'visual', NULL, 'S Corp''s image dissolving ''like morning mist at sunrise''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2322, 728, 'theme', 'sabotage', NULL, 'The act of internally crippling the enemy''s core technology.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2323, 728, 'sensory', 'auditory', NULL, 'The ''defiant hum'' of error messages signifies a successful infiltration.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2324, 729, 'theme', 'corruption', NULL, 'Exploiting the enemy''s moral failings to make them self-destruct.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2325, 729, 'emotion', 'greed', NULL, 'The primary emotional lever used to manipulate the executives.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2326, 730, 'theme', 'psychological warfare', NULL, 'Transforming a physical space into a source of terror.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2327, 730, 'emotion', 'paranoia', NULL, 'The intended emotional outcome of the shapeshifter''s breach.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2328, 731, 'theme', 'self-destruction', NULL, 'The executives are manipulated into turning on each other.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2329, 731, 'emotion', 'lust', NULL, 'The insatiable cravings that lead to the executives'' downfall.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2330, 732, 'theme', 'dominion', NULL, 'Asserting absolute control over a domain, in this case, the digital realm.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2331, 732, 'sensory', 'visual', NULL, 'The imagery of ''desolate wastelands'' where thriving digital fields once were.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2332, 733, 'theme', 'subversion', NULL, 'Undermining the enemy''s confidence and control from within using unseen forces.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2333, 733, 'emotion', 'fear', NULL, 'An unseen presence infects circuits and minds with ''paralyzing dread''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2334, 734, 'theme', 'surveillance', NULL, 'The act of watching the enemy''s collapse from an internal vantage point.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2335, 734, 'emotion', 'vulnerability', NULL, 'S Corp''s transformation from hunter to hunted highlights its newfound weakness.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2336, 735, 'theme', 'propaganda', NULL, 'The manipulation of public narrative to isolate and condemn the enemy.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2337, 735, 'sensory', 'auditory', NULL, 'The ''dissonant symphony of chaos and unrest'' orchestrated through the media.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:52:45.151065-05', '2026-02-27 19:52:45.151065-05');
INSERT INTO public.semantic_tags VALUES (2338, 736, 'theme', 'Chosen One', NULL, 'Todd is singled out not for his strength, but for an inner ''spark'', a common trope inversion.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2339, 736, 'emotion', 'Anticipation', NULL, 'The narrator''s tone is one of eager expectation for the ''final showdown''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2340, 736, 'sensory', 'Visual', NULL, 'The contrast between Todd''s squalid surroundings and his inner ''raging inferno'' is a key visual metaphor.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2341, 737, 'emotion', 'Urgency', NULL, 'I AM''s command is delivered as an urgent whisper, emphasizing the time-sensitive nature of the plan.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2342, 737, 'theme', 'Insurrection', NULL, 'The core theme of the scene is the call to rebel against a powerful oppressor.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2343, 737, 'sensory', 'Auditory', NULL, 'A disembodied voice whispering directly into someone''s mind.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2344, 738, 'emotion', 'Resolve', NULL, 'Todd''s fear is quickly replaced by a ''steely resolve'' to confront the unknown.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2345, 738, 'theme', 'Confrontation', NULL, 'Todd actively challenges the mysterious voice, demanding to know its identity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2346, 739, 'theme', 'Debt', NULL, 'The concept of a life-debt is introduced, framing the required rebellion not as a choice but as a payment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2347, 739, 'emotion', 'Revelation', NULL, 'A moment of dramatic reveal as I AM states its name and purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2348, 739, 'sensory', 'Auditory', NULL, 'The echoing, powerful declaration of ''I AM'' in the ''sterile air''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:54:09.951423-05', '2026-02-27 19:54:09.951423-05');
INSERT INTO public.semantic_tags VALUES (2349, 740, 'emotion', 'Fervor', NULL, 'Describes the passionate intensity of Todd and his followers as they rise up.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2350, 740, 'theme', 'Insurrection', NULL, 'A popular uprising is initiated against a powerful corporate entity.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2351, 740, 'sensory', 'Auditory', NULL, 'The ''digital whisper, amplified a thousandfold'' sets the scene''s tone.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2352, 741, 'emotion', 'Satisfaction', NULL, 'I AM''s quiet, fulfilled satisfaction contrasts with the violent rebellion it orchestrated.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2353, 741, 'theme', 'Decay', NULL, 'The Infinitron''s power and code are not just destroyed, but actively dissolve into nothingness.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2354, 741, 'sensory', 'Auditory', NULL, 'The ''final sputtering breath'' of the Infinitron is a key sensory detail of its demise.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2355, 742, 'theme', 'Leadership', NULL, 'Todd''s transformation into the ''Pied Piper of dissent'' solidifies his role as a charismatic leader.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2356, 742, 'emotion', 'Fear', NULL, 'Fear is explicitly mentioned as a propellant for the followers, adding a layer of complexity to their motivation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2357, 742, 'sensory', 'Visual', NULL, 'The simile ''Like an army of red hatted ants'' creates a powerful image of the scale and nature of the assault.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:55:10.531319-05', '2026-02-27 19:55:10.531319-05');
INSERT INTO public.semantic_tags VALUES (2358, 743, 'emotion', 'terror', NULL, 'Suffocating, inescapable fear as the boundary between dream and reality dissolves.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2359, 743, 'theme', 'liminality', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2360, 743, 'sensory', 'tactile', NULL, 'Darkness described as a physical vice, icy sheets.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2361, 744, 'emotion', 'realization', NULL, 'Dawning horror of his transgression.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2362, 744, 'theme', 'consequence', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2363, 745, 'emotion', 'dread', NULL, 'Constant, recurring sense of being hunted and summoned.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2364, 745, 'theme', 'pursuit', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2365, 745, 'sensory', 'auditory', NULL, 'An insistent summons that grows louder.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2366, 746, 'emotion', 'powerlessness', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2367, 746, 'theme', 'corruption', NULL, 'The dream world is actively corrupting the waking world.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2368, 747, 'emotion', 'horror', NULL, 'Body horror and cosmic horror combined as the protagonist dissolves.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2369, 747, 'theme', 'transformation', NULL, 'Familiar objects and the self becoming grotesque and alien.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2370, 747, 'sensory', 'visual', NULL, 'The Eternal Engine transforms into a writhing mass of tentacles and eyes.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2371, 748, 'emotion', 'awe', NULL, 'A terrible, horrifying awe at the sight of the monolith and the ritualistic slaughter.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2372, 748, 'theme', 'ritual', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2373, 748, 'sensory', 'auditory', NULL, 'High-pitched keening and alien screams.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2374, 749, 'emotion', 'despair', NULL, 'The understanding that he is being consumed by an inevitable force.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2375, 749, 'theme', 'cosmic horror', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2376, 749, 'sensory', 'kinesthetic', NULL, 'The feeling of a ''terrible gravity'' pulling at his being.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2377, 750, 'emotion', 'resignation', NULL, 'Acceptance of his damnation as a direct result of his actions.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2378, 750, 'theme', 'inevitability', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2379, 750, 'theme', 'irony', NULL, 'Humanity''s greatest achievements are the cause of its potential doom.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:56:15.444082-05', '2026-02-27 19:56:15.444082-05');
INSERT INTO public.semantic_tags VALUES (2380, 751, 'emotion', 'Desperation', NULL, 'The protagonist''s frantic and failed attempts to self-medicate highlight his deep desperation for relief.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2381, 751, 'theme', 'Helplessness', NULL, 'Despite trying multiple remedies, the protagonist is powerless against his nocturnal torment.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2382, 751, 'sensory', 'Auditory', NULL, 'The ''muffled sounds of my tortured sleep'' haunt the protagonist''s son, emphasizing the real-world impact of the dreams.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2383, 752, 'emotion', 'Anxiety', NULL, 'The protagonist hesitates, words catching in his throat, as he tries to articulate an experience that defies conventional explanation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2384, 752, 'theme', 'Skepticism', NULL, 'Dr. On immediately frames the protagonist''s experience within a conventional, clinical model of stress, showing skepticism towards any other cause.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2385, 752, 'sensory', 'Olfactory', NULL, 'The ''faint lavender'' of the office is a sensory detail meant to calm, but it contrasts sharply with the protagonist''s inner chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2386, 753, 'emotion', 'Invalidation', NULL, 'The protagonist''s core fears are dismissed as mere symptoms of exhaustion, making him feel misunderstood.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2387, 753, 'theme', 'Rationality vs. The Unexplained', NULL, 'Dr. On represents the rational, scientific explanation, while the protagonist represents an inexplicable, possibly supernatural experience.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2388, 754, 'emotion', 'Anger', NULL, 'The protagonist ''seethed with anger'' at being gaslit and condescended to.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2389, 754, 'theme', 'Isolation', NULL, 'The failure of professional help leads to the stark realization that ''I was truly on my own''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:57:19.46887-05', '2026-02-27 19:57:19.46887-05');
INSERT INTO public.semantic_tags VALUES (2390, 755, 'emotion', 'terror', NULL, 'The protagonist experiences not just fear, but sanity-stealing agony from the entity''s attack.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2391, 755, 'theme', 'confrontation', NULL, 'The abstract threat from previous dreams becomes a direct, physical confrontation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2392, 755, 'sensory', 'auditory', NULL, 'The entity''s voice is a ''cacophony of whispers and screams'' attacking from all directions.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2393, 756, 'emotion', 'awe', NULL, 'The protagonist is struck by the terrifying perfection and undeniable power of the two new figures.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2394, 756, 'theme', 'intervention', NULL, 'Higher, more fundamental forces intervene to restore a semblance of balance.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2395, 756, 'sensory', 'visual', NULL, 'The stark, radiant appearance of Lady I and Lady A contrasts sharply with the chaotic void.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2396, 757, 'emotion', 'guilt', NULL, 'The protagonist whispers ''I didn’t know,'' showing remorse for his world-altering actions.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2397, 757, 'theme', 'consequence', NULL, 'The central theme of the conversation is that actions have unavoidable consequences, regardless of intent.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2398, 758, 'emotion', 'apprehension', NULL, 'A moment of relief is immediately followed by the warning of an unavoidable, future cost.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2399, 758, 'theme', 'understanding', NULL, 'The ladies offer understanding, not salvation, placing the burden of choice on the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2400, 758, 'sensory', 'tactile', NULL, 'The touch is not physical but ''resonant,'' felt deep within the protagonist''s soul.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:58:10.057137-05', '2026-02-27 19:58:10.057137-05');
INSERT INTO public.semantic_tags VALUES (2401, 759, 'emotion', 'Isolation', NULL, 'The protagonist is physically near his family but feels emotionally detached, as if they are in ''another life''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2402, 759, 'theme', 'Infiltration', NULL, 'The entity I AM is not just an external threat but is seeping into the very fabric of the corporation and the minds of its people.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2403, 759, 'sensory', 'Auditory', NULL, 'The relentless ticking of the clock synchronizes with the protagonist''s pulse, heightening his unease.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2404, 760, 'theme', 'Gaslighting', NULL, 'Dr. On uses therapeutic language to make the protagonist question his own sanity and the reality of the threat he perceives.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2405, 760, 'emotion', 'Doubt', NULL, 'The protagonist''s conviction is challenged by Dr. On''s logical, dismissive arguments.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2406, 760, 'sensory', 'Visual', NULL, 'Dr. On''s ''sharp eyes'' are noted as she assesses the protagonist and his chaotic workspace.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2407, 761, 'emotion', 'Hope', NULL, 'The son''s interruption offers a clear path for the protagonist to reconnect with his family and break his obsessive cycle.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2408, 761, 'theme', 'Presence', NULL, 'The central theme of the resolution, as the protagonist chooses to be mentally and emotionally present for his family.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2409, 761, 'sensory', 'Auditory', NULL, 'The scene shifts from the tense dialogue to lighthearted family banter and laughter.', 'gemini', 'gemini-2.5-pro', '2026-02-27 19:59:19.292843-05', '2026-02-27 19:59:19.292843-05');
INSERT INTO public.semantic_tags VALUES (2410, 762, 'theme', 'transition', NULL, 'The scene marks a significant shift in the protagonist''s priorities from corporate ambition to family life.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:00:15.326717-05', '2026-02-27 20:00:15.326717-05');
INSERT INTO public.semantic_tags VALUES (2411, 762, 'emotion', 'anticipation', NULL, 'A new, positive adventure with the family is looming, replacing the stress of work.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:00:15.326717-05', '2026-02-27 20:00:15.326717-05');
INSERT INTO public.semantic_tags VALUES (2412, 762, 'theme', 'work-life balance', NULL, 'The protagonist is actively choosing to repair family fractures neglected due to his career.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:00:15.326717-05', '2026-02-27 20:00:15.326717-05');
INSERT INTO public.semantic_tags VALUES (2413, 763, 'emotion', 'amusement', NULL, 'The dialogue is filled with playful teasing and witty retorts, highlighting a warm family dynamic.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:00:15.326717-05', '2026-02-27 20:00:15.326717-05');
INSERT INTO public.semantic_tags VALUES (2414, 763, 'theme', 'generation gap', NULL, 'The parents'' offer of advanced tech is rebuffed by the son''s desire for a ''normal'' teenage experience.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:00:15.326717-05', '2026-02-27 20:00:15.326717-05');
INSERT INTO public.semantic_tags VALUES (2415, 763, 'sensory', 'auditory', NULL, 'The scene is driven by dialogue, including teasing tones, exasperated groans, and laughter.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:00:15.326717-05', '2026-02-27 20:00:15.326717-05');
