INSERT INTO public.semantic_tags VALUES (3008, 971, 'sensory', 'Olfactory', NULL, 'The crisp, invigorating tang of the alien atmosphere is a key sensory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.semantic_tags VALUES (3009, 972, 'emotion', 'Wonder', NULL, 'Reflected in the mother''s hesitant steps and the description of the flora.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.semantic_tags VALUES (3010, 972, 'sensory', 'Visual', NULL, 'The bioluminescent flora creates a ''symphony of color'' with its flickering light.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.semantic_tags VALUES (3011, 972, 'theme', 'Family', NULL, 'The shared experience of arrival highlights the family bond.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.semantic_tags VALUES (3012, 973, 'emotion', 'Joy', NULL, 'Expressed through Takashi''s energetic leap and Yukiko''s resulting laughter.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.semantic_tags VALUES (3013, 973, 'theme', 'New Beginnings', NULL, 'The playful interaction signifies the start of their new life, contrasting the formal significance with personal joy.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.semantic_tags VALUES (3014, 973, 'sensory', 'Auditory', NULL, 'Yukiko''s laughter is a prominent sound in this beat.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:51:55.376034-05', '2026-02-27 20:51:55.376034-05');
INSERT INTO public.semantic_tags VALUES (3015, 974, 'emotion', 'dread', NULL, 'The atmosphere is described as having a ''palpable dread'' emanating from the stones.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3016, 974, 'theme', 'decline', NULL, 'The Church''s power has faded over centuries, making it vulnerable to S Corp''s influence.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3017, 974, 'sensory', 'visual', NULL, 'The scene is set with flickering torchlight and jagged shadows in a dark, secret chamber.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3018, 975, 'emotion', 'resolve', NULL, 'Pope Lucius Sixtus VI enters with ''grim resolve'', replacing his usual serene authority.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3019, 975, 'theme', 'conspiracy', NULL, 'A secret meeting with twelve hooded figures and a supernatural entity establishes a conspiratorial tone.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3020, 975, 'theme', 'supernatural', NULL, 'I AM''s manifestation in flames like the burning bush introduces a powerful, otherworldly element.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3022, 976, 'theme', 'declaration of war', NULL, 'The Pope''s speech frames the conflict as a holy war against S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3023, 976, 'sensory', 'auditory', NULL, 'The Pope''s words are described as ''cutting through the silence like a blade''.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3024, 977, 'emotion', 'impatience', NULL, 'Todd''s outburst (''Enough talk!'') and physical actions show his frustration with planning.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3025, 977, 'theme', 'strategic conflict', NULL, 'The conspirators debate different approaches: technology (Gaunt Entity), violence (Todd), and direct strikes (I AM).', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3026, 977, 'sensory', 'auditory', NULL, 'The beat is punctuated by the sharp sound of Todd''s hand hitting the table and the sinister echo in I AM''s voice.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3027, 978, 'emotion', 'doubt', NULL, 'The Pope voices his moral conflict and fear of becoming the evil they fight.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3028, 978, 'theme', 'moral ambiguity', NULL, 'The Pope''s final prayer highlights the central theme: ''Let us pray that we do not become the very thing we seek to destroy.''', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3029, 978, 'theme', 'grim consensus', NULL, 'Despite the debate and moral doubts, the group unites to forge their dangerous plans.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:52:51.181884-05', '2026-02-27 20:52:51.181884-05');
INSERT INTO public.semantic_tags VALUES (3030, 979, 'emotion', 'Anxiety', NULL, 'The guard''s inner turmoil and fear for his family''s safety.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3031, 979, 'theme', 'Duty vs. Family', NULL, 'The central conflict of the guard, torn between his oath and his love.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3032, 979, 'sensory', 'Visual', NULL, 'Dim light, gleaming halberd, and shadowy figures create a tense, secretive atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3033, 980, 'emotion', 'Desperation', NULL, 'The guard''s trembling hands and the urgent, simple content of his message convey his desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3034, 980, 'theme', 'Hope', NULL, 'Sending the message is a desperate act of hope for connection and reassurance.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3035, 980, 'sensory', 'Tactile', NULL, 'The feeling of the small device and the trembling of the guard''s fingers.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3036, 981, 'emotion', 'Shock', NULL, 'The suddenness and silence of the attack.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3037, 981, 'theme', 'Consequence', NULL, 'The guard''s attempt to contact his family directly leads to his death.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3038, 981, 'sensory', 'Auditory', NULL, 'The scene is defined by a lack of sound: the silent attack, the guttural whisper, and the squelch of the blade.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3039, 982, 'emotion', 'Sorrow', NULL, 'The tragic irony of the undelivered message and the family''s ignorance of the sacrifice.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3040, 982, 'theme', 'Sacrifice', NULL, 'The guard makes the ultimate sacrifice for his family, but it will forever go unknown.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3041, 982, 'theme', 'Cosmic Indifference', NULL, 'The vastness of space swallows the message, mirroring the indifference of the powerful forces that killed the guard.', 'gemini', 'gemini-2.5-pro', '2026-02-27 20:53:43.897003-05', '2026-02-27 20:53:43.897003-05');
INSERT INTO public.semantic_tags VALUES (3042, 983, 'emotion', 'awe', NULL, 'The recruits are standing on the precipice of the unknown, looking out at the ''vast cosmic ocean''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3043, 983, 'theme', 'frontier', NULL, 'Pluto is established as the farthest outpost, the very edge of humanity''s reach.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3044, 984, 'theme', 'exploration', NULL, 'The mission is defined not by combat, but by discovery and the search for new worlds.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3045, 984, 'emotion', 'purpose', NULL, 'The recruits are given a clear, intellectual, and noble purpose: to unravel mysteries.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3046, 985, 'theme', 'breakthrough', NULL, 'Einstein-Rosen Bridges are presented as a revolutionary technology unlocking the universe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3047, 985, 'sensory', 'conceptual', NULL, 'The description involves abstract physics concepts like ''shortcuts through the fabric of space-time''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3048, 986, 'sensory', 'tactile', NULL, 'The extreme, ''bone-chilling -240°C'' cold is emphasized as a physical threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3049, 986, 'emotion', 'dread', NULL, 'The description of Pluto''s environment is designed to evoke a sense of hostility and danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3050, 987, 'theme', 'risk', NULL, 'The officer pivots from a known danger (cold) to an unknown, greater one (alien worlds).', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3051, 987, 'emotion', 'apprehension', NULL, 'The duality of ''paradises waiting to bloom or silent graveyards'' creates deep uncertainty.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3052, 988, 'emotion', 'fear', NULL, 'The specific dangers are visceral: a ''silent invader'', DNA being shredded into ''cosmic confetti''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3053, 988, 'theme', 'unseen danger', NULL, 'The threats described are microscopic or invisible, heightening the sense of vulnerability.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3054, 989, 'theme', 'sacrifice', NULL, 'The potential death of recruits is reframed as a heroic act that could save all of humanity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3055, 989, 'emotion', 'solemnity', NULL, 'The acknowledgment of potential casualties brings a grave and serious tone to the speech.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3056, 990, 'emotion', 'unity', NULL, 'The final words emphasize a collective effort: ''we reach for the stars. Together.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3057, 990, 'sensory', 'auditory', NULL, 'The beat functions as a ''rallying cry'', meant to be heard and to inspire.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:44:08.13572-05', '2026-02-28 16:44:08.13572-05');
INSERT INTO public.semantic_tags VALUES (3058, 991, 'emotion', 'nostalgia', NULL, 'The protagonist reflects on the humble beginnings of the Eternal Engine compared to his current position.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3059, 991, 'theme', 'power', NULL, 'The scene is set in an opulent office high above Earth, emphasizing the protagonist''s immense power and influence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3060, 991, 'sensory', 'visual', NULL, 'The protagonist gazes out at the ''sprawling spires piercing the heavens''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3061, 992, 'emotion', 'tension', NULL, 'Patrick''s voice is ''edged with tension'' as he reports on the escalating violence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3062, 992, 'theme', 'narrative control', NULL, 'The protagonist''s insistence on non-lethal measures is explicitly to avoid losing ''the narrative''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3063, 993, 'theme', 'ideological conflict', NULL, 'TJ reframes the conflict as a religious crusade against S Corp''s vision, not just a series of skirmishes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3064, 993, 'sensory', 'auditory', NULL, 'The impact of TJ''s words is described as settling ''over the room like a storm cloud''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3065, 994, 'emotion', 'resolve', NULL, 'The protagonist''s voice is firm as he outlines a dual strategy of outreach and elimination.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3066, 994, 'theme', 'strategy', NULL, 'The entire beat is a debate between advisors on the best strategic approach: soft power, hard power, or information warfare.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3067, 995, 'emotion', 'shock', NULL, 'The news from Afghanistan ''hit like a hammer,'' indicating a sudden and impactful escalation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3068, 995, 'theme', 'betrayal', NULL, 'The protagonist expresses frustration that factions who were given a chance to leave peacefully have chosen violence, described as ''shit in your face''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3069, 995, 'sensory', 'tactile', NULL, 'Patrick''s anger is physically expressed by him slamming a fist on the table.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3070, 996, 'emotion', 'weariness', NULL, 'The protagonist''s final line, ''just fucking tired of willfully stupid people,'' reveals his deep exhaustion with the conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3071, 996, 'theme', 'information warfare', NULL, 'The focus shifts to actively countering propaganda and controlling the narrative on all fronts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:45:16.775552-05', '2026-02-28 16:45:16.775552-05');
INSERT INTO public.semantic_tags VALUES (3072, 997, 'emotion', 'tension', NULL, 'The air is described as ''suffocating'' and ''pulsing like a living thing'', establishing a sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3073, 997, 'theme', 'ideological warfare', NULL, 'James explicitly frames the conflict not as corporate or political, but as a ''jihad'' against S Corp''s very existence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3074, 997, 'sensory', 'visual', NULL, 'The dim, flickering fluorescent lights and ''jagged shadows'' create an unsettling visual atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3075, 998, 'emotion', 'horror', NULL, 'The revelation of children being used as suicide bombers with ''anal bombs'' is deeply disturbing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3076, 998, 'theme', 'fanaticism', NULL, 'The extremists'' belief that progress itself is ''satanic'' highlights their absolute and dangerous conviction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3077, 999, 'emotion', 'shock', NULL, 'The protagonist has to ''take a double take and reread the report'' due to the unbelievable scale of the threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3078, 999, 'theme', 'escalation', NULL, 'The conflict moves from ideological threats and terrorism to a planetary-level nuclear crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3079, 1000, 'emotion', 'urgency', NULL, 'The protagonist''s voice cracks with urgency, and every second of the countdown ''felt like a hammer blow''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3080, 1000, 'theme', 'crisis management', NULL, 'The team rapidly assembles in the command center to formulate a response to an imminent, existential threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3081, 1000, 'sensory', 'auditory', NULL, 'The command center ''buzzed with activity'', contrasting the quiet tension of the office.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:46:19.470878-05', '2026-02-28 16:46:19.470878-05');
INSERT INTO public.semantic_tags VALUES (3082, 1001, 'emotion', 'Tension', NULL, 'The countdown and debate over high-stakes tactical choices create a tense atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.semantic_tags VALUES (3083, 1001, 'theme', 'Surgical Strike', NULL, 'The team opts for a precise ground operation over a blunt drone strike.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.semantic_tags VALUES (3084, 1001, 'sensory', 'Visual', NULL, 'The scene is viewed through live drone feeds and grainy robot eye-cams.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.semantic_tags VALUES (3085, 1002, 'emotion', 'Shock', NULL, 'The sudden revelation and detonation of a second, more powerful device.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.semantic_tags VALUES (3086, 1002, 'theme', 'Misdirection', NULL, 'The first device was a feint to distract from the true target.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.semantic_tags VALUES (3087, 1002, 'sensory', 'Visual', NULL, 'A ''blinding flash'' and ''white-hot glow'' so bright it''s visible from Pluto.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.semantic_tags VALUES (3088, 1002, 'sensory', 'Auditory', NULL, 'The ''eerie silence'' that follows the massive, silent explosion in space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.semantic_tags VALUES (3089, 1003, 'emotion', 'Relief', NULL, 'A collective exhale in the war room as the elevator is revealed to be intact.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
INSERT INTO public.semantic_tags VALUES (3090, 1003, 'emotion', 'Resolve', NULL, 'The protagonist''s decision to stop ''playing games'' and eliminate the threat permanently.', 'gemini', 'gemini-2.5-pro', '2026-02-28 16:47:20.408743-05', '2026-02-28 16:47:20.408743-05');
