INSERT INTO public.semantic_tags VALUES (3171, 1020, 'sensory', 'Visual', NULL, 'The striking image of the bioluminescent beast with its molten lava-colored carapace.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:04:30.698348-05', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.semantic_tags VALUES (3172, 1021, 'emotion', 'Despair', NULL, 'Yukiko''s crushing realization of the scale of her mistake.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:04:30.698348-05', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.semantic_tags VALUES (3173, 1021, 'theme', 'Consequence', NULL, 'The central theme of the scene: an action taken with one intent has unleashed a far greater, unforeseen horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:04:30.698348-05', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.semantic_tags VALUES (3174, 1021, 'sensory', 'Visual', NULL, 'The image of the once-gleaming colony now lying in ruins.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:04:30.698348-05', '2026-02-28 17:04:30.698348-05');
INSERT INTO public.semantic_tags VALUES (3175, 1022, 'emotion', 'Relief', NULL, 'Yukiko''s personal guilt lessens as she embraces the collective struggle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3176, 1022, 'theme', 'Shared Burden', NULL, 'The realization that ''they were in this together'' is a key turning point.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3177, 1022, 'sensory', 'Auditory', NULL, 'Governor Tanaka''s ''booming voice'' cuts through the dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3178, 1023, 'theme', 'Survival', NULL, 'The beat is defined by the ''chaotic scramble for survival''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3179, 1023, 'emotion', 'Solidarity', NULL, 'Despite the fear, a ''newfound solidarity'' emerges among the colonists.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3180, 1023, 'theme', 'Leadership', NULL, 'Yukiko, once a child, steps up and becomes an invaluable leader.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3181, 1024, 'theme', 'Betrayal', NULL, 'The core of the beat is the discovery of S Corp''s deliberate and chilling deception.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3182, 1024, 'emotion', 'Anger', NULL, 'Yukiko is ''fueled by anger and a thirst for answers,'' driving the investigation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3183, 1024, 'theme', 'Truth', NULL, 'The investigation unearths a ''chilling truth'' that redefines the colonists'' entire situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3184, 1025, 'emotion', 'Rage', NULL, 'The colonists'' primary emotional reaction to the truth is a mixture of rage and grief.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3185, 1025, 'theme', 'Defiance', NULL, 'Instead of despairing, the colonists resolve to ''fight back''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3186, 1025, 'emotion', 'Resilience', NULL, 'The colonists decide that despair is a ''luxury they couldn’t afford''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:05:28.504683-05', '2026-02-28 17:05:28.504683-05');
INSERT INTO public.semantic_tags VALUES (3187, 1026, 'theme', 'ingenuity', NULL, 'The colonists demonstrate resourcefulness by turning salvaged bio-tools and alien plants into weapons and defenses.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3188, 1026, 'theme', 'adaptation', NULL, 'The act of studying and harnessing the alien environment is a core theme of survival.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3189, 1026, 'emotion', 'determination', NULL, 'The proactive preparation for an inevitable attack shows the colony''s resolve.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3190, 1027, 'theme', 'survival', NULL, 'The battle is explicitly described as a fight for the colony''s future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3191, 1027, 'emotion', 'defiance', NULL, 'Yukiko embodies the colony''s defiance against their fate and their attackers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3192, 1027, 'sensory', 'auditory', NULL, 'The air crackles with energy and the collective roar of the fighters.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3193, 1027, 'sensory', 'visual', NULL, 'The scene is vividly lit by the azure glow of triple suns and dancing lasers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3194, 1028, 'theme', 'transformation', NULL, 'The colony is forged into a ''new kind of humanity'' by the crucible of battle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3195, 1028, 'emotion', 'hope', NULL, 'Despite the loss and hardship, the scene ends on a note of hope, symbolized by the children playing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3196, 1028, 'theme', 'consequence', NULL, 'Victory comes at a cost, leaving the colony wounded and necessitating brutal actions like executions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:06:20.066266-05', '2026-02-28 17:06:20.066266-05');
INSERT INTO public.semantic_tags VALUES (3197, 1029, 'emotion', 'resignation', NULL, 'Frank''s tone suggests he''s long past being surprised by his mundane reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:07:22.946997-05', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.semantic_tags VALUES (3198, 1029, 'theme', 'isolation', NULL, 'Emphasized by the ''windowless broom closet'' and his job deep in the station''s guts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:07:22.946997-05', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.semantic_tags VALUES (3199, 1029, 'sensory', 'auditory', NULL, 'The scene opens with the alarm screaming ''WAKE THE FRANK UP!''', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:07:22.946997-05', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.semantic_tags VALUES (3200, 1029, 'theme', 'dystopian mundanity', NULL, 'The contrast between a ''shiny utopia'' and the reality of preventing a ''cosmic dumpster fire''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:07:22.946997-05', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.semantic_tags VALUES (3201, 1030, 'emotion', 'exasperation', NULL, 'Frank''s reaction, ''Jesus mother-fucking Christ,'' perfectly captures his frustration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:07:22.946997-05', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.semantic_tags VALUES (3202, 1030, 'theme', 'absurdity', NULL, 'High-stakes space life is threatened by toilet paper softness and space raccoons.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:07:22.946997-05', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.semantic_tags VALUES (3203, 1030, 'sensory', 'auditory', NULL, 'The comm ''crackled to life,'' signaling the start of the day''s problems.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:07:22.946997-05', '2026-02-28 17:07:22.946997-05');
INSERT INTO public.semantic_tags VALUES (3204, 1031, 'emotion', 'panic', NULL, 'Dr. Adler''s frantic hollering and fear of mutant cucumbers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:08:17.235701-05', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.semantic_tags VALUES (3205, 1031, 'theme', 'technological failure', NULL, 'The life-support UV filters are malfunctioning and creating a hazard.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:08:17.235701-05', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.semantic_tags VALUES (3206, 1031, 'sensory', 'auditory', NULL, 'The radiation alarms ''wailed like banshees''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:08:17.235701-05', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.semantic_tags VALUES (3207, 1032, 'theme', 'competence', NULL, 'Frank''s ability to fix a complex, dangerous problem despite his cynicism.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:08:17.235701-05', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.semantic_tags VALUES (3208, 1032, 'sensory', 'visual', NULL, 'The cucumber smoothie ''glowed faintly in the dark''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:08:17.235701-05', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.semantic_tags VALUES (3209, 1032, 'emotion', 'resignation', NULL, 'Frank''s attitude in drinking the glowing smoothie, summed up by ''hydration''s hydration''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:08:17.235701-05', '2026-02-28 17:08:17.235701-05');
INSERT INTO public.semantic_tags VALUES (3210, 1033, 'emotion', 'anger', NULL, 'Sr. Hernandez''s fury is the driving force of the initial confrontation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:09:02.202457-05', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.semantic_tags VALUES (3211, 1033, 'sensory', 'olfactory', NULL, 'The scene is defined by the clash between the heavenly smell of a bakery and the foul ''algae funk''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:09:02.202457-05', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.semantic_tags VALUES (3212, 1034, 'theme', 'sabotage', NULL, 'Hernandez explicitly accuses the raccoons of intentional sabotage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:09:02.202457-05', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.semantic_tags VALUES (3213, 1034, 'emotion', 'disgust', NULL, 'Frank''s physical reaction of gagging at the smell of the empanada.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:09:02.202457-05', '2026-02-28 17:09:02.202457-05');
INSERT INTO public.semantic_tags VALUES (3214, 1035, 'emotion', 'chaos', NULL, 'The scene is one of complete pandemonium, with people and objects floating uncontrollably.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:22.590156-05', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.semantic_tags VALUES (3215, 1035, 'theme', 'absurdity', NULL, 'A cosmic cat chasing a bowling ball in a zero-gravity bowling alley is a fundamentally absurd situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:22.590156-05', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.semantic_tags VALUES (3216, 1035, 'sensory', 'auditory', NULL, 'The sound of bowlers swearing fills the air.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:22.590156-05', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.semantic_tags VALUES (3217, 1036, 'theme', 'ingenuity', NULL, 'Frank''s ability to solve a complex problem with simple, everyday items highlights resourcefulness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:22.590156-05', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.semantic_tags VALUES (3218, 1036, 'emotion', 'relief', NULL, 'The bowlers'' cheers signify the collective relief and gratitude felt once gravity is restored.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:22.590156-05', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.semantic_tags VALUES (3219, 1036, 'sensory', 'olfactory', NULL, 'The lingering smell of burnt duct tape and grease provides a sensory anchor to the recent events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:22.590156-05', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.semantic_tags VALUES (3220, 1036, 'sensory', 'auditory', NULL, 'The ''satisfying thunk'' of the ball landing provides a definitive sound of resolution.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:22.590156-05', '2026-02-28 17:10:22.590156-05');
INSERT INTO public.semantic_tags VALUES (3221, 1037, 'emotion', 'dread', NULL, 'Frank''s stomach does ''that sinking thing'' upon hearing the news.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3222, 1037, 'theme', 'crisis', NULL, 'The scene opens with the inciting incident of a major crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3223, 1037, 'sensory', 'auditory', NULL, 'The scene is initiated by Pete''s calm but serious voice over the comms.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3224, 1038, 'emotion', 'gallows humor', NULL, 'Frank''s plumbing metaphors are a way of coping with a dire situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3225, 1038, 'theme', 'coping mechanism', NULL, 'The banter and metaphors serve as a way for the characters to grapple with the crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3226, 1039, 'theme', 'mystery', NULL, 'The cause of the silence is completely unknown, described as someone flipping a switch.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3227, 1039, 'emotion', 'urgency', NULL, 'Frank''s rapid-fire questions show his growing need for answers and action.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3228, 1039, 'sensory', 'tactile', NULL, 'Frank leans against the ''cold glass'' of the observation deck.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3229, 1040, 'emotion', 'fear', NULL, 'Pete''s voice cracks, revealing a fear that alarms Frank.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3230, 1040, 'theme', 'helplessness', NULL, 'Pete reminds Frank he''s ''a janitor—not a superhero,'' highlighting their limited ability to respond directly.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3231, 1040, 'theme', 'escalation', NULL, 'The problem escalates from a technical issue to a terrifying, unknown threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:10:53.113677-05', '2026-02-28 17:10:53.113677-05');
INSERT INTO public.semantic_tags VALUES (3232, 1041, 'emotion', 'unease', NULL, 'TJ feels that the surface beauty of his surroundings is ''hollow'', hiding something rotten.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3233, 1041, 'theme', 'foreshadowing', NULL, 'The blinking red indicator and TJ''s recognition of a pattern hints at a larger, future conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3234, 1041, 'sensory', 'visual', NULL, 'Description of the ''kaleidoscope of blues and whites'' from the city lights and the ''blinking red indicator''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3235, 1042, 'theme', 'dystopian undertones', NULL, 'The concept of a perfect ''second Eden'' is shown to have cracks, as people lose purpose in paradise.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3236, 1042, 'emotion', 'cynicism', NULL, 'TJ''s reflection on the past has a cynical edge, acknowledging that ''Eden was never without its serpents''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3237, 1043, 'theme', 'rebellion', NULL, 'The Red Hats are described as a movement of ''dissent and defiance'' against the established system.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3238, 1043, 'emotion', 'apprehension', NULL, 'The Red Hats are described as an ''echo of something far darker,'' escalating the sense of threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3239, 1043, 'sensory', 'visual', NULL, 'The ''crimson hats'' and ''graffiti scrawled across pristine walls'' are key visual markers of the dissent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3240, 1044, 'emotion', 'anxiety', NULL, 'TJ''s chest tightens and he hesitates, showing the immense pressure of his decision.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3241, 1044, 'theme', 'consequence', NULL, 'TJ knows that reporting the anomaly is like lighting a fuse on a bomb, acknowledging the severe potential fallout.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:12:16.497076-05', '2026-02-28 17:12:16.497076-05');
INSERT INTO public.semantic_tags VALUES (3242, 1045, 'theme', 'authority', NULL, 'Dr. On''s entrance and immediate, commanding presence establish a clear power dynamic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3243, 1045, 'emotion', 'tension', NULL, 'The scene opens with an atmosphere of professional tension, centered on the ''pulsing red anomaly''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3244, 1045, 'sensory', 'auditory', NULL, 'The ''hiss'' of the door opening is a distinct sound that marks the start of the confrontation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3245, 1046, 'theme', 'rebellion', NULL, 'TJ introduces the central theme of a ''quiet revolt'' against a technologically-enforced status quo.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3246, 1046, 'emotion', 'urgency', NULL, 'TJ''s ''tight'' voice conveys the seriousness and growing nature of the threat he perceives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3247, 1047, 'theme', 'ideological_conflict', NULL, 'The core of the scene is the clash between corporate metrics (''happiness'') and humanistic needs (''purpose'').', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3248, 1047, 'emotion', 'frustration', NULL, 'TJ''s scoff and Dr. On''s hardening expression highlight the mutual frustration of the characters.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3249, 1047, 'sensory', 'visual', NULL, 'The image of ''steel glinting beneath her diplomatic façade'' is a strong visual metaphor for Dr. On''s character.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3250, 1048, 'theme', 'willful_ignorance', NULL, 'Dr. On and S Corp actively choose to ignore a potential crisis in favor of maintaining stability.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3251, 1048, 'emotion', 'isolation', NULL, 'The scene ends with TJ physically and ideologically alone, his warning completely dismissed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3252, 1048, 'sensory', 'tactile', NULL, 'The room is described as feeling ''colder'' after Dr. On leaves, a physical manifestation of TJ''s isolation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:04.202317-05', '2026-02-28 17:13:04.202317-05');
INSERT INTO public.semantic_tags VALUES (3253, 1049, 'theme', 'Insurrection', NULL, 'The rebellion is moving from isolated incidents to more organized and threatening activities.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3254, 1049, 'emotion', 'Dread', NULL, 'The rumors of clone sacrifice introduce a dark, horrific element to the conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3255, 1049, 'sensory', 'Visual', NULL, 'The image of blood-red graffiti on pristine city walls.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3256, 1050, 'theme', 'Propaganda', NULL, 'The attack is not physical but psychological, designed to sway public opinion and expose a hidden truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3257, 1050, 'emotion', 'Shock', NULL, 'The entire city''s population is confronted with raw, visceral imagery in place of their usual serene landscapes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3258, 1050, 'sensory', 'Visual', NULL, 'The juxtaposition of starving children and opulent executives creates a powerful, disturbing visual narrative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3259, 1051, 'theme', 'Denial', NULL, 'S Corp''s leadership refuses to acknowledge the reality of the situation, a critical strategic error.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3260, 1051, 'emotion', 'Arrogance', NULL, 'The belief by S Corp leadership that they can simply ignore and suppress a deeply rooted problem.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3261, 1052, 'emotion', 'Vindication', NULL, 'TJ feels a sense of validation as his predictions about the system''s instability come true.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3262, 1052, 'theme', 'Instability', NULL, 'The core theme of the scene''s conclusion: the supposedly perfect system is beginning to fail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3263, 1052, 'sensory', 'Kinesthetic', NULL, 'TJ feels a ''shift in the air,'' a non-physical sensation of a fundamental change in the societal structure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:13:54.2269-05', '2026-02-28 17:13:54.2269-05');
INSERT INTO public.semantic_tags VALUES (3264, 1053, 'theme', 'Inequality', NULL, 'The visual chasm between the high-tech elevator and the street-level squalor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3265, 1053, 'sensory', 'Auditory Chaos', NULL, 'The competing sounds of vendors and rickshaws create a sense of overwhelming, vibrant life.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3266, 1053, 'emotion', 'Resignation', NULL, 'Aditi''s feeling that the chasm between dreams and reality is a familiar, known quantity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3267, 1054, 'theme', 'Aspiration', NULL, 'Aditi''s escape from her family''s past was fueled by education and dreams of space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3268, 1054, 'emotion', 'Hope', NULL, 'The scholarship represents a one-way ticket to an unimaginable future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3269, 1055, 'emotion', 'Anger', NULL, 'The righteous fury of the Red Hat Leader and his followers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3270, 1055, 'sensory', 'Auditory', NULL, 'The leader''s thundering voice over the megaphone, combined with chants and drumming.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3271, 1055, 'emotion', 'Anxiety', NULL, 'Aditi''s personal unease upon suspecting her brother''s involvement.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3272, 1056, 'theme', 'The Price of Progress', NULL, 'Aditi wonders if Elysium is a monument built on the backs of the forgotten.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3273, 1056, 'emotion', 'Conflict', NULL, 'Aditi''s internal struggle between her personal hope and her awareness of systemic injustice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3274, 1056, 'sensory', 'Tactile', NULL, 'Aditi''s hand tightening around her ID card, a physical anchor for her hope.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:15:05.803512-05', '2026-02-28 17:15:05.803512-05');
INSERT INTO public.semantic_tags VALUES (3275, 1057, 'emotion', 'Alienation', NULL, 'Aditi is described as a ''lone speck of grit in Elysium’s glittering machine''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3276, 1057, 'theme', 'Classism', NULL, 'The contrast between Aditi''s ''threadbare'' clothes and the ''designer silks'' of her peers establishes a clear class divide.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3277, 1057, 'sensory', 'Visual', NULL, 'The scene is dominated by visuals of sterile perfection: ''polished chrome'', ''glinting'' sunlight, and ''glittering'' machinery.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3278, 1057, 'sensory', 'Auditory', NULL, 'The soundscape is one of artificiality (''hum of perfection'') and hostility (''whispers and snickers'').', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3279, 1058, 'theme', 'Superficiality', NULL, 'A replicated uniform fixes the surface problem, but cannot change the deeper judgment or grant true acceptance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3280, 1058, 'emotion', 'Exclusion', NULL, 'Despite conforming in appearance, Aditi is still met with ''unspoken reminders that she didn’t belong''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3281, 1059, 'emotion', 'Humiliation', NULL, 'Arun''s insult is described as a ''sting'', causing a physical ''burning in her cheeks''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3282, 1059, 'theme', 'Resilience', NULL, 'Aditi refuses to shrink and instead channels her humiliation into determination, aiming to prove her worth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3283, 1059, 'theme', 'Prejudice', NULL, 'The term ''Dalit speculation'' is a direct and cutting attack based on caste and origin, not intellectual merit.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:01.236669-05', '2026-02-28 17:16:01.236669-05');
INSERT INTO public.semantic_tags VALUES (3284, 1060, 'emotion', 'longing', NULL, 'Aditi''s intense stare at Earth reveals her deep yearning for her home and family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3285, 1060, 'theme', 'isolation', NULL, 'The oppressive silence and sterile perfection of Elysium highlight Aditi''s profound loneliness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3286, 1060, 'sensory', 'visual', NULL, 'The image of Earth as a ''fragile blue marble'' is a central, poignant visual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3287, 1061, 'emotion', 'desperation', NULL, 'Aditi''s mother''s voice and plea, ''When are we coming, bitiya?'', are filled with desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3288, 1061, 'theme', 'decay', NULL, 'The news of her father''s cough and the worsening air quality points to the decay of life on Earth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3289, 1061, 'sensory', 'auditory', NULL, 'The mother''s ''strained'' and weary voice conveys her physical and emotional state.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3290, 1062, 'emotion', 'guilt', NULL, 'Aditi''s chest tightens and her nails dig into her palms from the guilt of her necessary deception.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3291, 1062, 'theme', 'injustice', NULL, 'The reveal that the waitlist is a filter for caste and wealth is a clear theme of systemic injustice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3292, 1062, 'sensory', 'tactile', NULL, 'The physical sensation of Aditi''s ''nails biting into her palms'' grounds her internal anguish.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3293, 1063, 'emotion', 'helplessness', NULL, 'Aditi is left staring at an empty display, physically and emotionally unable to bridge the distance to her mother.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3294, 1063, 'theme', 'memory and obligation', NULL, 'Her mother''s final warning, ''Don''t forget everything you left behind,'' becomes a haunting refrain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3295, 1063, 'sensory', 'visual', NULL, 'The ''cold, unfeeling glow'' of the terminal and the ''taunting'' light of Earth emphasize Aditi''s isolation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:16:42.307152-05', '2026-02-28 17:16:42.307152-05');
INSERT INTO public.semantic_tags VALUES (3296, 1064, 'emotion', 'shock', NULL, 'Aditi is physically jolted awake by the sudden, unexpected noise.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3297, 1064, 'theme', 'interruption', NULL, 'The signal violently breaks the established tranquility of the lab.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3298, 1064, 'sensory', 'auditory', NULL, 'The scene is defined by the contrast between the rhythmic hum and the sharp crackle of static.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3299, 1065, 'emotion', 'dread', NULL, 'The mere mention of Pluto sends a shiver down Aditi''s spine.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3300, 1065, 'theme', 'mystery', NULL, 'The signal is a plea from a secretive, isolated location, raising more questions than answers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3301, 1065, 'sensory', 'cognitive', NULL, 'The beat focuses on Aditi''s process of deciphering and understanding the fragmented data.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3302, 1066, 'emotion', 'alarm', NULL, 'Professor Nakamura''s stoic demeanor cracks, revealing the true gravity of the situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3303, 1066, 'theme', 'conspiracy', NULL, 'The suggestion of a compromised network and Nakamura''s order to keep it secret introduces the idea of a cover-up or hidden conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3304, 1066, 'sensory', 'silence', NULL, 'Nakamura''s lack of an immediate response is more telling than words.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:17:32.639147-05', '2026-02-28 17:17:32.639147-05');
INSERT INTO public.semantic_tags VALUES (3305, 1067, 'emotion', 'camaraderie', NULL, 'The bond between Aditi and Hiro is established through their shared intellectual and anti-establishment viewpoints.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3306, 1067, 'theme', 'conspiracy', NULL, 'The characters are actively connecting disparate, dangerous events into a single, overarching plot.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3307, 1067, 'sensory', 'visual', NULL, 'The scene is dominated by the dim glow of the console and the image of shifting code on the screen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3308, 1068, 'emotion', 'disbelief', NULL, 'Hiro''s reaction to finding Latin blueprints for a faster-than-light engine is one of incredulous shock.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3309, 1068, 'theme', 'forbidden_knowledge', NULL, 'The discovery of technology that shouldn''t exist, hidden away in a corporate database.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3310, 1068, 'sensory', 'auditory', NULL, 'The creak of Hiro''s chair and his muttered, incredulous dialogue punctuate the quiet tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3311, 1069, 'emotion', 'determination', NULL, 'Aditi''s voice is firm and deliberate, cutting through Hiro''s doubt with her unwavering resolve.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3312, 1069, 'theme', 'recklessness', NULL, 'The decision to hijack an experimental starship is a massive, life-threatening gamble born of desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3313, 1069, 'emotion', 'resignation', NULL, 'Hiro''s final agreement is a mix of loyalty and resigned acceptance of the insane consequences.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:18:16.287851-05', '2026-02-28 17:18:16.287851-05');
INSERT INTO public.semantic_tags VALUES (3314, 1070, 'emotion', 'awe', NULL, 'Hiro''s reaction to seeing the Genesis for the first time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3315, 1070, 'theme', 'foreboding', NULL, 'The ominous red lighting and predatory nature of the ship create a sense of impending danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3316, 1070, 'sensory', 'auditory', NULL, 'The scene is defined by its quietness, echoing footsteps, and the low hum of the ship.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3317, 1071, 'emotion', 'determination', NULL, 'Aditi''s unwavering confidence in her ability to succeed despite the unknowns.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3318, 1071, 'theme', 'a leap of faith', NULL, 'Aditi admits she doesn''t know how to fly the ship but is sure she''ll figure it out, committing them to the launch.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3319, 1071, 'sensory', 'visual', NULL, 'The interior of the ship is described with glowing mahogany panels and an ethereal orange light.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3320, 1072, 'emotion', 'acceptance', NULL, 'Hiro and Aditi both accept the ''insanity'' of their mission as the price of their goal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3321, 1072, 'theme', 'departure', NULL, 'The physical act of leaving the safety of Elysium for the unknown void represents a point of no return.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3322, 1072, 'sensory', 'kinesthetic', NULL, 'The feeling of the ship''s engines vibrating and the powerful surge of acceleration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:19:08.436575-05', '2026-02-28 17:19:08.436575-05');
INSERT INTO public.semantic_tags VALUES (3323, 1073, 'emotion', 'Anger', NULL, 'The collective, roaring anger of the Red Hats'' protest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.semantic_tags VALUES (3324, 1073, 'theme', 'Defiance', NULL, 'Todd''s act of firing on the corporate headquarters is a singular act of rebellion against an overwhelming force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.semantic_tags VALUES (3325, 1073, 'sensory', 'Auditory', NULL, 'The scene is dominated by the sounds of chanting and a loud gunshot.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.semantic_tags VALUES (3326, 1073, 'sensory', 'Visual', NULL, 'The contrast between the ''tide of crimson'' and the ''obsidian monolith'' creates a strong visual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.semantic_tags VALUES (3327, 1074, 'emotion', 'Despair', NULL, 'Todd''s realization of his powerlessness leads to a collapse born of despair.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.semantic_tags VALUES (3328, 1074, 'theme', 'Powerlessness', NULL, 'The core theme of the beat is the futility of individual, physical rebellion against superior technology.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.semantic_tags VALUES (3329, 1074, 'sensory', 'Kinaesthetic', NULL, 'The physical impact of Todd''s body slamming into the invisible force of the shield.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.semantic_tags VALUES (3330, 1074, 'theme', 'Man vs. Technology', NULL, 'A classic conflict illustrated by Todd''s physical body against an impersonal energy shield.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:09.851819-05', '2026-02-28 17:20:09.851819-05');
INSERT INTO public.semantic_tags VALUES (3331, 1075, 'emotion', 'desperation', NULL, 'Todd''s screams and cries to ''I AM'' highlight his complete loss of hope.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3332, 1075, 'sensory', 'olfactory', NULL, 'The sharp, burning scent of disinfectant defines the sterile environment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3333, 1075, 'theme', 'imprisonment', NULL, 'The scene establishes both a physical cell and a psychological ''personal hell''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3334, 1076, 'emotion', 'suspicion', NULL, 'Todd''s immediate question, ''What''s the catch?'', shows his deep-seated mistrust.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3335, 1076, 'theme', 'manipulation', NULL, 'Nameless preys on Todd''s desperation with a twisted offer of freedom.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3336, 1076, 'sensory', 'auditory', NULL, 'The hissing door and Nameless''s smooth, cold voice create an unsettling atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3337, 1077, 'theme', 'revelation', NULL, 'The shocking reveal that the jailer, Nameless, is the very entity Todd was pleading with.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3338, 1077, 'emotion', 'annihilation', NULL, 'Todd is not just killed but completely unmade, emphasizing the entity''s power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3339, 1077, 'theme', 'cosmic horror', NULL, 'The antagonist is revealed to be an entity with the power to erase existence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:20:51.18611-05', '2026-02-28 17:20:51.18611-05');
INSERT INTO public.semantic_tags VALUES (3340, 1078, 'emotion', 'trepidation', NULL, 'Todd''s journey into the unknown depths of the Vatican is filled with a sense of ancient mystery and danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3341, 1078, 'theme', 'threshold crossing', NULL, 'Passing through the imposing iron door symbolizes Todd''s entry into a world of real conspiracy and power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3342, 1078, 'sensory', 'visual', NULL, 'The scene is dominated by the imagery of flickering candles, dancing shadows, and ancient stone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3343, 1079, 'emotion', 'shock', NULL, 'Todd is stunned to find his wildest conspiracy theories are not only true but part of a cosmic battle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3344, 1079, 'theme', 'revelation', NULL, 'The core truth about S Corp and the ancient entities is unveiled, re-contextualizing the entire conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3345, 1079, 'sensory', 'auditory', NULL, 'The Pope''s ''resonant whisper'' that seems to echo through the chamber sets the tone for the momentous reveal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3346, 1080, 'emotion', 'resolve', NULL, 'Despite his uncertainty and the storm of doubt, Todd''s voice becomes steady as he accepts his mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3347, 1080, 'theme', 'destiny', NULL, 'A man dismissed as a crackpot is anointed as the chosen leader of a world-saving rebellion, a ''David against the Moabites''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3348, 1080, 'sensory', 'tactile', NULL, 'The feeling of the ''suffocating presence'' and the trust settling on him ''like a crown of thorns'' conveys the immense pressure of his new role.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:21:43.349713-05', '2026-02-28 17:21:43.349713-05');
INSERT INTO public.semantic_tags VALUES (3349, 1081, 'theme', 'defiance', NULL, 'The entire project is an act of defiance against an entrenched power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3350, 1081, 'emotion', 'determination', NULL, 'Todd''s gaze is fixed on the target, showing his unwavering resolve.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3351, 1081, 'sensory', 'visual', NULL, 'Gleaming cathedral-ships, holographic map of Pluto, faded astrological charts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3352, 1082, 'theme', 'high-stakes', NULL, 'The mission''s success is uncertain, and failure could be catastrophic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3353, 1082, 'emotion', 'anxiety', NULL, 'The scientist''s unease about the untested, catastrophic potential of the payload.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3354, 1082, 'emotion', 'resolve', NULL, 'Todd''s acceptance of the risk for the sake of the future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3355, 1083, 'theme', 'unity', NULL, 'The priest''s speech unites the concepts of faith and science for a common goal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3356, 1083, 'emotion', 'hope', NULL, 'The crew''s collective resolve is bolstered by words of encouragement.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3357, 1083, 'sensory', 'auditory', NULL, 'The clear, calm voice of the priest cutting through the tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3358, 1084, 'theme', 'sacrifice', NULL, 'Leaving Earth for a perilous, potentially one-way mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3359, 1084, 'emotion', 'resolute', NULL, 'Todd''s final declaration over the comms is steady and unwavering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3360, 1084, 'sensory', 'auditory', NULL, 'The roar of the engines as the fleet lifts off.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:22:26.798125-05', '2026-02-28 17:22:26.798125-05');
INSERT INTO public.semantic_tags VALUES (3361, 1085, 'theme', 'Pilgrimage', NULL, 'The journey is described not just as travel, but as a slow, devotional process over months.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3362, 1085, 'emotion', 'Piety', NULL, 'The fleet''s movement is fueled by ''devotions'', ''prayer'', and ''countless masses''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3363, 1085, 'theme', 'Faith as Power', NULL, 'Belief and the love of God are literal fuel for their advanced technology.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3364, 1086, 'theme', 'Divine Mandate', NULL, 'The Pope grants blessings and frames the attack as God''s will, promising heavenly rewards for execution.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3365, 1086, 'emotion', 'Righteous Fury', NULL, 'The language used by the Pope (''retribution be swift and just'', ''execution of the heretics'') conveys a sense of holy anger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3366, 1086, 'sensory', 'Anticipation', NULL, 'The beat is built around the tension of waiting for the final confirmation to begin the attack.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3367, 1087, 'sensory', 'Auditory', NULL, 'The ''deafening hum'' of the gate contrasts with the ''whispered calculations'' of the crew.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3368, 1087, 'sensory', 'Visual', NULL, 'Tendrils of light, a shimmering maw, and stars blurring into streaks create a powerful visual of the jump.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3369, 1087, 'theme', 'Threshold Crossing', NULL, 'The fleet literally ''plunges into the abyss'', crossing from known space into the battlefield.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3370, 1087, 'emotion', 'Awe', NULL, 'The description of the rift tearing open in the fabric of reality inspires a sense of powerful awe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:23:30.331867-05', '2026-02-28 17:23:30.331867-05');
INSERT INTO public.semantic_tags VALUES (3371, 1088, 'theme', 'Surgical Strike', NULL, 'The attack begins with calculated precision against a fortified target.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3372, 1088, 'sensory', 'Visual Overload', NULL, 'Torrents of plasma energy and shimmering shields create a chaotic light show.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3373, 1088, 'emotion', 'Determination', NULL, 'Reflected in Todd''s steady voice despite the immense weight of his command.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3374, 1089, 'theme', 'Sudden Reversal', NULL, 'The unexpected implosion of the gateway is a critical turning point in the battle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3375, 1089, 'sensory', 'Auditory', NULL, 'The ''tortured groan'' of the gateway and the ''faint, crackling signal'' are the key sensory inputs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3376, 1089, 'emotion', 'Hope', NULL, 'The confirmation from the resistance that the ''oppressive lifeline'' has been severed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3377, 1090, 'theme', 'Total Annihilation', NULL, 'The objective shifts from a surgical strike to complete destruction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3378, 1090, 'emotion', 'Ruthlessness', NULL, 'Todd ignores hails from the ''heathens'' and orders their complete destruction without hesitation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3379, 1090, 'sensory', 'Desolation', NULL, 'Pluto''s surface is returned to its natural, empty state, now covered in ash.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:24:34.851233-05', '2026-02-28 17:24:34.851233-05');
INSERT INTO public.semantic_tags VALUES (3380, 1091, 'emotion', 'anxiety', NULL, 'The son''s internal, unspoken anxiety about his studies creates the scene''s initial tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3381, 1091, 'theme', 'academic_pressure', NULL, 'The conflict stems from the overwhelming nature of advanced education in a rapidly changing field.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3382, 1091, 'sensory', 'olfactory', NULL, 'The smell of roasted marshmallows and crisp air establishes the cozy campsite setting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3383, 1092, 'theme', 'technology_vs_nature', NULL, 'The artificial beauty of the holographic projector is contrasted with the profound, natural magic of the actual Milky Way.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3384, 1092, 'emotion', 'wonder', NULL, 'The parents attempt to rekindle their son''s sense of wonder, which is momentarily achieved but then gives way to his deeper anxieties.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3385, 1092, 'sensory', 'visual', NULL, 'Dominated by the sight of holographic galaxies and the vast, star-filled night sky.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3386, 1093, 'emotion', 'reassurance', NULL, 'The father''s primary emotional offering to his son, calming his fears about failure and the impossible task of knowing everything.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3387, 1093, 'theme', 'acceptance_of_mystery', NULL, 'The core wisdom shared by the father: the universe is meant to be marveled at, not completely solved.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3388, 1094, 'emotion', 'hope', NULL, 'The scene concludes on a hopeful note, with the son''s curiosity renewed and his anxieties calmed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3389, 1094, 'theme', 'family_bond', NULL, 'The resolution is achieved through the strength of the family''s support and understanding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3390, 1094, 'sensory', 'visual', NULL, 'The soft glow of starlight bathing the family creates a peaceful final image.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:25:55.790207-05', '2026-02-28 17:25:55.790207-05');
INSERT INTO public.semantic_tags VALUES (3391, 1095, 'emotion', 'Suspicion', NULL, 'The feeling that something is wrong due to the unusual silence in the smart home.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3392, 1095, 'theme', 'Disrupted Domesticity', NULL, 'The usual automated comfort of home has been replaced by chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3393, 1095, 'sensory', 'Auditory Silence', NULL, 'The conspicuous absence of the normal hums and whirs of appliances is the first sign of trouble.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3394, 1096, 'emotion', 'Amusement', NULL, 'The parents'' reaction to the robotic warfare is not alarm, but laughter and banter.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3395, 1096, 'theme', 'Personification', NULL, 'The Roombas are described with human/animal traits like engaging in a ''tug-of-war'' and ''territorial warfare''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3396, 1096, 'sensory', 'Kinetic', NULL, 'The beat is filled with the motion of robots whirling, ramming, and climbing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3397, 1097, 'emotion', 'Amazement', NULL, 'The couple is ''equal parts horrified and amazed'' by the Roombas'' sudden display of solidarity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3398, 1097, 'theme', 'Emergent Behavior', NULL, 'The simple machines display complex, unprogrammed social behavior, like mourning and cooperation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3399, 1097, 'sensory', 'Visual', NULL, 'The primary focus is the sight of the ''solemn procession'' of robots.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3400, 1098, 'emotion', 'Playfulness', NULL, 'The couple''s tone is entirely lighthearted as they joke about arming their vacuums.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3401, 1098, 'theme', 'Acceptance of Chaos', NULL, 'Instead of fixing the problem, the couple embraces the absurdity of their ''robot rebellion''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3402, 1098, 'sensory', 'Gustatory', NULL, 'The scene concludes with the taste of Muscato wine during a toast.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:26:38.217948-05', '2026-02-28 17:26:38.217948-05');
INSERT INTO public.semantic_tags VALUES (3403, 1099, 'emotion', 'shock', NULL, 'The news hits the protagonist ''like a sledgehammer'', instantly shattering his calm.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3404, 1099, 'theme', 'crisis_initiation', NULL, 'Two critical assets are compromised simultaneously, launching the central conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3405, 1100, 'emotion', 'urgency', NULL, 'The command center is described as ''crackling with urgency'' as the team scrambles for answers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3406, 1100, 'theme', 'uncertainty', NULL, 'The team is working with garbled data and a lack of contact, making decisions in a vacuum of information.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3407, 1100, 'sensory', 'auditory', NULL, 'The soundscape is defined by engineers barking commands and the hum of technology.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3408, 1101, 'emotion', 'fear', NULL, 'The son''s fear is palpable despite his attempts to mask it with a casual tone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3409, 1101, 'theme', 'familial_bonds', NULL, 'The family unit provides strength and reassurance to one another in the face of disaster.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3410, 1102, 'emotion', 'vulnerability', NULL, 'The son''s bravado cracks, revealing his deep-seated worry for his father''s safety.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3411, 1102, 'theme', 'burden_of_command', NULL, 'The father accepts the weight of his son''s plea, adding a personal stake to his professional responsibilities.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3412, 1103, 'emotion', 'terror', NULL, 'The sight of the fleet inspires a ''primal fear'' of things beyond human comprehension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3413, 1103, 'theme', 'cosmic_horror', NULL, 'The threat is revealed to be not just hostile, but alien and unnatural in a way that defies understanding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3414, 1103, 'sensory', 'auditory', NULL, 'The room is filled with a ''distorted, high-pitched noise that clawed at our ears''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3415, 1103, 'sensory', 'visual', NULL, 'The key visual is the grainy footage of massive, dark, unnaturally pulsing ships.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:27:29.437992-05', '2026-02-28 17:27:29.437992-05');
INSERT INTO public.semantic_tags VALUES (3416, 1104, 'theme', 'Oppression', NULL, 'The powerful (''Dreamers'') command the powerless (''Worker'') to suffer.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3417, 1104, 'emotion', 'Struggle', NULL, 'The core experience of the student and worker is one of difficult, obedient effort.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3418, 1105, 'emotion', 'Desperation', NULL, 'The wailing choose self-immolation over an obvious source of relief, indicating ultimate despair.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3419, 1105, 'theme', 'Hypocrisy', NULL, 'The illiterate, surrounded by burning knowledge, demand that others learn.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3420, 1105, 'sensory', 'Olfactory', NULL, 'The choking smoke from a million burning books is a dominant sensory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3421, 1106, 'theme', 'Blind Faith', NULL, 'The gullible follow a command towards a sign they are explicitly told they cannot see.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3422, 1106, 'emotion', 'Liminality', NULL, 'The state of being ''neither dead nor dying'' is a key emotional and thematic element.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3423, 1107, 'theme', 'Paradox', NULL, 'The central theme is the revelation of contradictory truths: seeing without seeing, truth that is no truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3424, 1107, 'sensory', 'Auditory', NULL, 'The beat is defined by the overwhelming ''screams of the damned'' and the unheard ''shouts from above''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3425, 1108, 'theme', 'Cyclical Nature', NULL, 'The scene ends as it began, with the command to ''climb'', suggesting the struggle is endless and repetitive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3426, 1108, 'emotion', 'Resignation', NULL, 'The frustrated turning away represents a rejection of the struggle, a choice of inaction over a difficult choice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3427, 1108, 'sensory', 'Visual', NULL, 'The image of newly buried flowers provides a poignant and symbolic closing visual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:28:37.874696-05', '2026-02-28 17:28:37.874696-05');
INSERT INTO public.semantic_tags VALUES (3428, 1109, 'emotion', 'dread', NULL, 'The leadership''s shock and panic stem from the shattering of their perceived invulnerability.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3429, 1109, 'theme', 'vulnerability', NULL, 'The titans of technology are proven to be vulnerable to a violent, unexpected assault.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3430, 1109, 'sensory', 'gustatory', NULL, 'The nervous energy is described as tasting like copper.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3431, 1110, 'emotion', 'contempt', NULL, 'Todd''s voice and expression are filled with venomous contempt for S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3432, 1110, 'theme', 'fanaticism', NULL, 'Todd introduces himself and his rebellion as instruments of divine will.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3433, 1111, 'theme', 'blasphemy', NULL, 'The core conflict is framed as progress (S Corp) versus divine law (Todd), with the Eternal Engine labeled a demonic idol.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3434, 1111, 'emotion', 'fury', NULL, 'Todd''s response is likened to that of an Old Testament prophet, filled with rage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3435, 1112, 'sensory', 'visual', NULL, 'Todd broadcasts grotesque and horrific cosmic imagery that causes physical distress.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3436, 1112, 'theme', 'cosmic horror', NULL, 'The conflict moves beyond simple warfare into the realm of sanity-bending horrors.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3437, 1112, 'emotion', 'rage', NULL, 'The narrator''s composure breaks, and he unleashes a stream of profane insults.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3438, 1113, 'emotion', 'hysteria', NULL, 'Todd''s zeal reaches a fever pitch as he bellows his final pronouncements.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3439, 1113, 'sensory', 'auditory', NULL, 'Todd''s ''dry, rasping cackle'' and the final tolling silence dominate the soundscape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3440, 1114, 'theme', 'betrayal', NULL, 'The discovery of Dr. On as a mole reveals the threat is internal as well as external.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3441, 1114, 'emotion', 'shock', NULL, 'The leadership is stunned into silence by the weight of the transmission, which is then broken by the revelation of sabotage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3442, 1115, 'theme', 'morality in warfare', NULL, 'The advisors debate whether to adhere to their humane principles or resort to brutal tactics to survive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3443, 1115, 'emotion', 'urgency', NULL, 'Patrick''s argument is driven by a sense of imminent doom, contrasting with TJ''s cautious concern.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3444, 1116, 'emotion', 'resolve', NULL, 'The narrator''s voice becomes ''cold and unyielding'' as he decides on a path of total war.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3445, 1116, 'theme', 'totalitarianism', NULL, 'The chosen strategy involves not just total war, but also censorship and propaganda to ensure public unity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:29:51.987065-05', '2026-02-28 17:29:51.987065-05');
INSERT INTO public.semantic_tags VALUES (3446, 1117, 'emotion', 'panic', NULL, 'The narrator''s internal state is described as ''sheer panic'' and a feeling of suffocation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3447, 1117, 'theme', 'vulnerability', NULL, 'The dismissal of ''safety'' as a PR slogan establishes the characters'' profound lack of security.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3448, 1117, 'sensory', 'tactile', NULL, 'The physical sensations of a tight chest and the wife gripping the narrator''s arm.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3449, 1118, 'emotion', 'skepticism', NULL, 'The wife''s sharp tone (''Hontou?'') and dismissal of the ''corporate spiel'' show her disbelief in easy answers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3450, 1118, 'theme', 'leadership crisis', NULL, 'The narrator is forced to formulate a plan to project control over a situation that is spiraling out of control.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3451, 1119, 'emotion', 'grim resolve', NULL, 'The narrator''s quiet, determined statement that the enemy must be completely eliminated.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3452, 1119, 'theme', 'moral compromise', NULL, 'The decision to commit to ''mass extermination'' represents a dark turning point and the acceptance of a terrible necessity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3453, 1119, 'sensory', 'auditory', NULL, 'The narrator''s sharp snap (''Damn it'') contrasts with the quiet gravity of his final decision.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3454, 1120, 'emotion', 'love', NULL, 'Demonstrated through the wife''s plea for his safe return and their intimate goodbye.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3455, 1120, 'theme', 'personal stakes', NULL, 'The conflict is distilled from a strategic crisis to the potential personal loss between two people.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3456, 1120, 'sensory', 'tactile', NULL, 'The tight squeeze of a hand, a final kiss, and a lingering grip on an arm, all conveying fear and connection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:30:48.449827-05', '2026-02-28 17:30:48.449827-05');
INSERT INTO public.semantic_tags VALUES (3457, 1121, 'emotion', 'pressure', NULL, 'The narrator feels the crushing weight of his empire and knowledge of cosmic horrors.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3458, 1121, 'theme', 'leadership', NULL, 'The narrator takes decisive action to control the narrative in a moment of crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3459, 1121, 'sensory', 'auditory', NULL, 'The narrator''s sharp voice cuts through the oppressive silence of the room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3460, 1122, 'emotion', 'determination', NULL, 'The team wrestles with the words for hours, sharpening every phrase into a ''weapon of unity''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3461, 1122, 'theme', 'propaganda', NULL, 'The team is not lying, but ''framing'' the truth to achieve a specific outcome: public resolve.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3462, 1123, 'emotion', 'conviction', NULL, 'The narrator speaks with a calm he doesn''t feel, his voice rising like a rallying cry.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3463, 1123, 'theme', 'defiance', NULL, 'The core message of the broadcast is one of unyielding strength against terror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3464, 1123, 'sensory', 'visual', NULL, 'The unblinking stare of the camera lens serves as the audience''s eye.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3465, 1124, 'emotion', 'exhaustion', NULL, 'The narrator''s adrenaline ebbs away after the broadcast, leaving him drained.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3466, 1124, 'theme', 'duality', NULL, 'The contrast between the narrator''s public role as a strong leader and his private vulnerability and fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3467, 1124, 'sensory', 'tactile', NULL, 'The comfort of his family''s embrace is contrasted with the internal ''chill of the void''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:31:49.802674-05', '2026-02-28 17:31:49.802674-05');
INSERT INTO public.semantic_tags VALUES (3468, 1125, 'emotion', 'dread', NULL, 'The report from Gil is described as a ''dagger to the heart,'' instilling a deep sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3469, 1125, 'theme', 'corruption', NULL, 'The contagion isn''t just spreading, it''s ''transforming'' and ''mutating'' into something darker.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3470, 1125, 'sensory', 'visual', NULL, 'The imagery of ''red-hued head coverings'' and ''pulsating'' blood-red graffiti is prominent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3471, 1126, 'emotion', 'desperation', NULL, 'Becca and Andrew work ''feverishly'' on a ''desperate measure'' to stem the tide.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3472, 1126, 'theme', 'escalation', NULL, 'The attempt to restore order backfires immediately, causing an eruption of even greater violence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3473, 1126, 'sensory', 'auditory', NULL, 'The rebels'' chants become a ''guttural chorus that scraped at the edges of sanity.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3474, 1127, 'emotion', 'horror', NULL, 'The narrator''s realization and Becca''s silent, terrified reaction embody the horror of their situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3475, 1127, 'theme', 'revelation', NULL, 'The narrator understands that the enemy is not human or political, but an ancient, supernatural force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3476, 1127, 'theme', 'powerlessness', NULL, 'The narrator can only watch the chaos on the monitors, realizing their conventional methods are useless.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:32:53.680293-05', '2026-02-28 17:32:53.680293-05');
INSERT INTO public.semantic_tags VALUES (3477, 1128, 'emotion', 'unease', NULL, 'A chilling, creeping dread spreads as the colonies go dark.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3478, 1128, 'theme', 'infiltration', NULL, 'The enemy''s presence is not overt but a shadowy influence that corrupts from within.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3479, 1128, 'sensory', 'visual', NULL, 'The sight of cryptic symbols bleeding onto walls and screens like ''festering wounds''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3480, 1129, 'emotion', 'fear', NULL, 'The realization that the attacks are deliberate and systematic shatters any sense of safety.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3481, 1129, 'theme', 'vulnerability', NULL, 'Humanity''s reliance on technology becomes their greatest weakness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3482, 1130, 'emotion', 'horror', NULL, 'A visceral, sanity-assaulting horror at the sight of the Organic Barricades.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3483, 1130, 'theme', 'depravity', NULL, 'The enemy''s tactics go beyond warfare into monstrous, unimaginable cruelty.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3484, 1130, 'sensory', 'olfactory', NULL, 'The stench of burning flesh mixed with screams creates a multi-sensory assault.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3485, 1130, 'sensory', 'auditory', NULL, 'The sound of human screams emanating from the barricades.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3486, 1131, 'emotion', 'hope', NULL, 'A defiant flicker of hope emerges as the catalyst for resistance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3487, 1131, 'theme', 'resilience', NULL, 'Even when faced with cosmic horror, the spirit to fight for survival and justice endures.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3488, 1131, 'sensory', 'abstract', NULL, 'The conceptual feeling of light pushing back against an encroaching shadow.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:06.286507-05', '2026-02-28 17:34:06.286507-05');
INSERT INTO public.semantic_tags VALUES (3489, 1132, 'emotion', 'Urgency', NULL, 'The commander''s tone establishes a crisis atmosphere from the start.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3490, 1132, 'theme', 'Crisis Management', NULL, 'The scene opens with the leadership attempting to formulate a response to a critical threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3491, 1133, 'theme', 'Ethical Dilemma', NULL, 'The advisors debate solutions that balance mission success against the risk to human life.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3492, 1133, 'emotion', 'Conflict', NULL, 'Intellectual conflict and debate among the advisors about the best tactical approach.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3493, 1133, 'sensory', 'Tension', NULL, 'The dialogue reveals the high stakes and the difficulty of the decision.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3494, 1134, 'theme', 'Asymmetric Warfare', NULL, 'The team shifts from direct confrontation to strategies of information, psychology, and espionage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3495, 1134, 'emotion', 'Determination', NULL, 'Despite the risks, the team coalesces around a complex and aggressive plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3496, 1135, 'emotion', 'Horror', NULL, 'The execution of the plan is described as a ''deafening symphony of horror'' with cries of agony.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3497, 1135, 'theme', 'Pyrrhic Victory', NULL, 'The objective is achieved, but the ''sheer cost to our humanity was palpable''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3498, 1135, 'sensory', 'Auditory', NULL, 'The scene is filled with the sounds of agony and the ''metallic clash of the machines''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3499, 1135, 'sensory', 'Visual', NULL, 'The scene is described as ''brutal, almost surreal,'' focusing on the dismantling of grotesque barricades.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:34:52.602085-05', '2026-02-28 17:34:52.602085-05');
INSERT INTO public.semantic_tags VALUES (3500, 1136, 'emotion', 'dread', NULL, 'S Corp faces a ''chilling dilemma'' and ''horrifying consequences'', creating a sense of impending doom.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:35:40.887804-05', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.semantic_tags VALUES (3501, 1136, 'theme', 'ideological conflict', NULL, 'The core of the beat is the clash between the principle of free speech and the existential threat posed by that speech.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:35:40.887804-05', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.semantic_tags VALUES (3502, 1136, 'theme', 'information warfare', NULL, 'A podcast is used as a weapon to destabilize society.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:35:40.887804-05', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.semantic_tags VALUES (3503, 1137, 'emotion', 'horror', NULL, 'The ease with which followers bypass security is ''terrifying'' and the movement is described as a ''cosmic horror''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:35:40.887804-05', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.semantic_tags VALUES (3504, 1137, 'theme', 'unstoppable force', NULL, 'The followers'' ''otherworldly determination'' and the podcast spreading ''as if powered by forces beyond human comprehension'' suggests the heroes are outmatched.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:35:40.887804-05', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.semantic_tags VALUES (3505, 1137, 'sensory', 'auditory', NULL, 'The threat is explicitly auditory and memetic, spreading through ''demonic whispers'' in alternative channels.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:35:40.887804-05', '2026-02-28 17:35:40.887804-05');
INSERT INTO public.semantic_tags VALUES (3506, 1138, 'emotion', 'Worry', NULL, 'Reflected in Morgan''s shadowed face and Professor Nakamura''s grim posture.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3507, 1138, 'theme', 'Discovery', NULL, 'The unexpected interception of the distress signal changes the entire strategic focus.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3508, 1138, 'sensory', 'Auditory', NULL, 'The ''hiss of the door'' breaks the Commander''s concentration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3509, 1139, 'emotion', 'Realization', NULL, 'The Commander''s bitter muttering shows his dawning horror at their oversight.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3510, 1139, 'theme', 'Hubris', NULL, 'Their pride in the advanced ERB system directly caused this critical failure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3511, 1139, 'theme', 'Decisiveness', NULL, 'The Commander doesn''t hesitate, immediately ordering a rescue mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3512, 1140, 'emotion', 'Determination', NULL, 'Described as ''palpable'' in the rescue team as they receive their briefing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3513, 1140, 'theme', 'Preparedness', NULL, 'The detailed list of modifications and supplies for the rescue ship highlights their rapid and thorough response.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3514, 1140, 'sensory', 'Visual', NULL, 'The description of the rescue team''s faces ''drawn with intensity, sweat glistening on their brows''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:36:28.902003-05', '2026-02-28 17:36:28.902003-05');
INSERT INTO public.semantic_tags VALUES (3515, 1141, 'emotion', 'anxiety', NULL, 'The text describes the tension as ''suffocating'' and the uncertainty as ''gnawing at the edges of our resolve''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3516, 1141, 'theme', 'waiting', NULL, 'The entire beat is defined by the agonizing passage of time while waiting for news.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3517, 1141, 'sensory', 'interoceptive', NULL, 'The physical sensation of a racing heart is explicitly mentioned.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3518, 1142, 'emotion', 'grief', NULL, 'The news of Hiro''s death and Aditi''s injuries hits The Commander ''like a blow''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3519, 1142, 'theme', 'pyrrhic victory', NULL, 'The objective of finding Aditi was achieved, but at a great cost (Hiro''s life, Aditi''s injuries, ship damage).', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3520, 1142, 'sensory', 'auditory', NULL, 'The scene is initiated by the sound of ''comms crackled to life'' and Morgan''s strained voice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3521, 1143, 'emotion', 'determination', NULL, 'The Commander and Patrick share a moment of mirrored resolve to see the mission through.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3522, 1143, 'theme', 'leadership', NULL, 'The Commander takes decisive action, rallying resources and setting a clear objective.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3523, 1143, 'theme', 'loyalty', NULL, 'The Commander states the mission is about showing ''we protect our own. No matter the cost.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3524, 1143, 'sensory', 'tactile', NULL, 'The Commander grips the console with whitening knuckles and later places a hand on Patrick''s shoulder.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:37:23.2536-05', '2026-02-28 17:37:23.2536-05');
INSERT INTO public.semantic_tags VALUES (3525, 1144, 'theme', 'Revelation', NULL, 'The discovery of an enemy''s strategy based on exploiting an overlooked, primitive technology.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3526, 1144, 'emotion', 'Calm Urgency', NULL, 'Aditi''s steady voice contrasts with the alarming nature of the information she''s providing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3527, 1144, 'theme', 'Technological Blind Spot', NULL, 'A hyper-advanced security system is defeated by something too simple for it to even consider as a threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3528, 1145, 'theme', 'Psychological Warfare', NULL, 'The enemy''s goal is not just physical sabotage but the corruption of personalities and the shattering of unity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3529, 1145, 'emotion', 'Somberness', NULL, 'Aditi''s expression shifts as she describes the ruthless and chaotic plans of the Red Hats.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3530, 1145, 'sensory', 'Auditory Threat', NULL, 'The core danger is a sound that can rewrite a person''s mind, making hearing itself a vulnerability.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3531, 1146, 'theme', 'Unconventional Warfare', NULL, 'The combination of conspiracy-theory hats, foil, and ambient resonance creates a bizarre but effective weapon system.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3532, 1146, 'emotion', 'Dawning Realization', NULL, 'Patrick and the narrator fully grasp the terrifying ingenuity and scope of the enemy''s tactics.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3533, 1146, 'theme', 'Escalation', NULL, 'The threat is revealed to be mobile and self-propagating, turning enemy soldiers into walking psychological weapons.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:38:11.362734-05', '2026-02-28 17:38:11.362734-05');
INSERT INTO public.semantic_tags VALUES (3534, 1147, 'emotion', 'Triumph', NULL, 'A brief, fleeting sense of victory expressed by the narrator before suspicion takes over.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3535, 1147, 'theme', 'End of an Era', NULL, 'The conclusion of a five-year-long, intensive war marks a significant turning point.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3536, 1147, 'sensory', 'Visual', NULL, 'The final flicker of the enemy signal disappearing from the main screen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3537, 1148, 'emotion', 'Dread', NULL, 'A ''gnawing unease'' burrows into the narrator''s thoughts, making the victory feel wrong.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3538, 1148, 'theme', 'Deceptive Calm', NULL, 'The quiet and order of the command center feels fragile and unnatural after years of chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3539, 1148, 'sensory', 'Auditory', NULL, 'The soft buzz and hum of machinery in the command center creates a serene but tense atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3540, 1149, 'emotion', 'Skepticism', NULL, 'The narrator directly challenges the idea of victory, pointing out the inconsistencies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3541, 1149, 'theme', 'Foreshadowing', NULL, 'The narrator explicitly states, ''This isn''t a victory. It''s a pause. A prelude.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3542, 1150, 'emotion', 'Foreboding', NULL, 'The narrator can sense an invisible, coiled threat waiting to strike.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3543, 1150, 'theme', 'The Price of Victory', NULL, 'The core idea that such an easy win is not a gift, but a transaction with a hidden cost.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3544, 1150, 'sensory', 'Absence', NULL, 'The silence left by the enemy is described as echoing louder than their actual chaotic noise ever did.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:39:27.987023-05', '2026-02-28 17:39:27.987023-05');
INSERT INTO public.semantic_tags VALUES (3545, 1151, 'theme', 'Recovery', NULL, 'Humanity is moving past a state of war and returning to peace and progress.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3546, 1151, 'theme', 'Expansion', NULL, 'The focus shifts to exploring space and expanding humanity''s presence in the universe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3547, 1151, 'emotion', 'Optimism', NULL, 'The scene opens with a ''newly restored atmosphere of peace and reason''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3548, 1152, 'emotion', 'Exhilaration', NULL, 'Morgan''s and TJ''s excitement is described as infectious and triumphant.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3549, 1152, 'theme', 'Discovery', NULL, 'The announcement of the outpost represents a monumental scientific and exploratory breakthrough.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3550, 1152, 'sensory', 'Visual', NULL, 'The ''shimmering model of the outpost'' and the ''faint, almost imperceptible glow'' of uncharted territory are key visual elements.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3551, 1152, 'emotion', 'Awe', NULL, 'TJ''s voice is ''low, almost reverent'', and the achievement is described as ''humbling''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3552, 1153, 'theme', 'Ambition', NULL, 'The plan for a network of outposts is described as ''audacious''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3553, 1153, 'theme', 'Innovation', NULL, 'The immense logistical challenges demand constant innovation, particularly in refining the ERB network.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3554, 1153, 'emotion', 'Humility', NULL, 'As humanity''s understanding expands, the mysteries of the universe ''both awed and humbled us''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:40:22.326711-05', '2026-02-28 17:40:22.326711-05');
INSERT INTO public.semantic_tags VALUES (3555, 1154, 'emotion', 'awe', NULL, 'Morgan''s excitement at discovering a fundamental truth of the cosmos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3556, 1154, 'theme', 'existential question', NULL, 'The narrator''s blunt question, ''Where the fuck is everyone?'', cuts through the scientific wonder to the core issue.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3557, 1154, 'sensory', 'visual', NULL, 'The command room is filled with dancing equations, star maps, and a holographic display of infinite galaxies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3558, 1155, 'emotion', 'paranoia', NULL, 'The core feeling engendered by the Dark Forest Hypothesis, which shaped all of humanity''s actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3559, 1155, 'theme', 'survival', NULL, 'The hypothesis posits a brutal, zero-sum game where the only way to survive is to strike first.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3560, 1156, 'emotion', 'dread', NULL, 'The realization that the universe is empty is described as ''something even worse'' than a universe full of predators.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3561, 1156, 'theme', 'solitude', NULL, 'The shift from fearing others to fearing the complete absence of others.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3562, 1156, 'sensory', 'auditory', NULL, 'Morgan''s whisper is noted as more unsettling than any shout, signifying the collapse of her confidence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3563, 1157, 'emotion', 'loneliness', NULL, 'The final confirmation that humanity is ''truly alone out here''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3564, 1157, 'theme', 'cosmic horror', NULL, 'The horror comes not from a monster, but from a vast, thriving, yet utterly unthinking and indifferent universe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3565, 1157, 'theme', 'responsibility', NULL, 'The narrator''s realization that they are now the ''custodians of sentience''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:41:09.404104-05', '2026-02-28 17:41:09.404104-05');
INSERT INTO public.semantic_tags VALUES (3566, 1158, 'emotion', 'Joy', NULL, 'The scene opens with the genuine joy of a family''s surprise birthday party.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3567, 1158, 'theme', 'Legacy', NULL, 'The narrator reflects on his 300-year life and the generations that have followed him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3568, 1158, 'sensory', 'Auditory', NULL, 'The beat is defined by the sounds of shouting and children''s laughter.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3569, 1159, 'emotion', 'Melancholy', NULL, 'The narrator''s pride is tinged with sadness and worry about the fragility of his accomplishments.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3570, 1159, 'theme', 'Innocence vs. Experience', NULL, 'The grandchildren''s carefree wonder contrasts sharply with the narrator''s awareness of the risks and sacrifices made.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3571, 1159, 'sensory', 'Visual', NULL, 'The glowing holographic models of planets provide a key visual element.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3572, 1160, 'emotion', 'Fear', NULL, 'The narrator''s deep-seated fear of an unknown, unseen enemy is the core of the beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3573, 1160, 'theme', 'Paranoia', NULL, 'The belief that random anomalies are part of a deliberate, coordinated attack against S Corp.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3574, 1160, 'emotion', 'Doubt', NULL, 'The narrator doubts himself and fears that others see him as a cranky old man with delusions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:01.151394-05', '2026-02-28 17:42:01.151394-05');
INSERT INTO public.semantic_tags VALUES (3575, 1161, 'emotion', 'disorientation', NULL, 'The narrator feels reality slipping, making him question what is real.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
