INSERT INTO public.semantic_tags VALUES (3577, 1161, 'sensory', 'auditory distortion', NULL, 'Laughter and voices are described as ''muffled like echoes in a hollow chamber''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.semantic_tags VALUES (3578, 1162, 'emotion', 'paranoia', NULL, 'The narrator voices his fear of being trapped in a fake, controlled universe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.semantic_tags VALUES (3579, 1162, 'theme', 'existential dread', NULL, 'The narrator''s belief that nothing is real or has stakes reflects a deep sense of meaninglessness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.semantic_tags VALUES (3580, 1163, 'emotion', 'terror', NULL, 'The narrator''s instability escalates into fear as he senses the watching presence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.semantic_tags VALUES (3581, 1163, 'sensory', 'visual distortion', NULL, 'The room''s edges waver and the narrator''s vision flickers with static.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.semantic_tags VALUES (3582, 1164, 'theme', 'cosmic horror', NULL, 'The antagonist is revealed to be a vast, incomprehensible entity woven into the fabric of existence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.semantic_tags VALUES (3583, 1164, 'sensory', 'deafening silence', NULL, 'The climax of the sensory assault is not a loud noise, but an oppressive, all-consuming silence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:42:55.681009-05', '2026-02-28 17:42:55.681009-05');
INSERT INTO public.semantic_tags VALUES (3584, 1165, 'emotion', 'panic', NULL, 'The protagonist wakes in a state of pure terror, gasping and drenched in sweat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 17:44:16.483489-05', '2026-02-28 17:44:16.483489-05');
