INSERT INTO public.semantic_tags VALUES (3811, 1245, 'sensory', 'Conceptual', NULL, 'The beat deals with abstract ideas like academic fields and intellectual prowess rather than physical sensations.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:04:58.145163-05', '2026-02-28 18:04:58.145163-05');
