INSERT INTO public.semantic_tags VALUES (3813, 1246, 'emotion', 'Resonance', NULL, 'The goal of his writing is to create plots that resonate with ''real-world complexities''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:04:58.145163-05', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.semantic_tags VALUES (3814, 1247, 'emotion', 'Anticipation', NULL, 'The phrase ''buckle up for an exciting ride'' is designed to create anticipation in the reader.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:04:58.145163-05', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.semantic_tags VALUES (3815, 1247, 'sensory', 'Kinetic', NULL, 'The invitation to an ''exciting ride'' evokes a sense of movement and energy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:04:58.145163-05', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.semantic_tags VALUES (3816, 1248, 'theme', 'Dedication', NULL, 'The scene ends with a personal dedication to family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:04:58.145163-05', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.semantic_tags VALUES (3817, 1248, 'emotion', 'Love', NULL, 'The dedication to Rina, ''the love of my life'', explicitly states this emotion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:04:58.145163-05', '2026-02-28 18:04:58.145163-05');
INSERT INTO public.semantic_tags VALUES (3818, 1249, 'theme', 'Authorship', NULL, 'Establishing the creator and owner of the work.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3819, 1249, 'sensory', 'Visual', NULL, 'The formal, structured text of a title page.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3820, 1250, 'theme', 'Identification', NULL, 'Assigning unique codes (ISBN, LCCN) for cataloging and commerce.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3821, 1251, 'theme', 'Legality', NULL, 'A formal legal warning about intellectual property rights.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3822, 1251, 'emotion', 'Caution', NULL, 'The tone is cautionary, warning against illegal reproduction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3823, 1252, 'theme', 'Disclaimer', NULL, 'A legal statement to prevent litigation by separating fiction from reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3824, 1253, 'theme', 'Chronology', NULL, 'Establishing the publication history and timeline of the book''s editions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3825, 1254, 'theme', 'Synopsis', NULL, 'Providing a brief overview of the story to entice readers and for cataloging purposes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (4385, 1444, 'theme', 'deception', NULL, 'Jamie''s affection is a calculated performance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (3826, 1254, 'emotion', 'Intrigue', NULL, 'The summary of a fraying reality is designed to create curiosity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3827, 1255, 'theme', 'Data', NULL, 'Presentation of raw identification data for library and retail systems.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3828, 1256, 'theme', 'Classification', NULL, 'The act of sorting the book into specific genres and subject categories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3829, 1256, 'sensory', 'Conceptual', NULL, 'Dealing with abstract ideas like genre (Horror, Sci-Fi) and theme (Identity).', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3830, 1257, 'emotion', 'Warning', NULL, 'A direct and explicit warning to the reader.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3831, 1257, 'theme', 'Safety', NULL, 'The warning serves as a tool for reader safety, allowing them to make an informed decision.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:06:10.507516-05', '2026-02-28 18:06:10.507516-05');
INSERT INTO public.semantic_tags VALUES (3832, 1258, 'emotion', 'Panic', NULL, 'The protagonist''s reaction is described as animalistic as he claws at the release.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3833, 1258, 'theme', 'Technological Betrayal', NULL, 'The machine meant to provide care is actively trying to murder him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3834, 1258, 'sensory', 'Suffocation', NULL, 'Describes the physical sensation of burning lungs and dancing stars behind the eyelids.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3835, 1259, 'emotion', 'Melancholy Love', NULL, 'A deep love is evident, but it''s tinged with the sadness of its distant nature and his wife''s passing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3836, 1259, 'theme', 'Memory as Refuge', NULL, 'After a near-death experience, the protagonist immediately retreats into memories of his wife.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3837, 1259, 'sensory', 'Olfactory', NULL, 'The pod smells like ''crusty socks and regret'', blending a physical smell with an emotional state.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3838, 1260, 'emotion', 'Disillusionment', NULL, 'A profound sense of disappointment with how the future he worked to build actually turned out.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3839, 1260, 'theme', 'Failed Ambition', NULL, 'The contrast between youthful dreams of changing the world and the mundane, disappointing reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3840, 1260, 'sensory', 'Visual', NULL, 'The world outside is described as a ''fever dream painted in rust and disappointment''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3841, 1261, 'emotion', 'Defiant Acceptance', NULL, 'He stops fighting and finds peace in memory, but ends with a curse, challenging the machine to finish the job.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3842, 1261, 'theme', 'Meaning in Small Moments', NULL, 'In the end, it''s not grand achievements but the memory of a smile and green tea that matter.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3843, 1261, 'sensory', 'Memory', NULL, 'The primary sensory experience is internal: the remembered weight of his wife''s hand and the rhythm of her breathing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:07:20.891756-05', '2026-02-28 18:07:20.891756-05');
INSERT INTO public.semantic_tags VALUES (3844, 1262, 'emotion', 'nostalgia', NULL, 'A bitter nostalgia for a time of optimism before the crushing realization of humanity''s limits.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3845, 1262, 'theme', 'hubris', NULL, 'Humanity feeling ''like gods'' for five years before being humbled by the universe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3846, 1263, 'emotion', 'disappointment', NULL, 'The feeling associated with the failures of Mars, Europa (''wet disappointment''), and asteroid mining.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3847, 1263, 'theme', 'confinement', NULL, 'Humanity is described as being ''penned in'' by cosmic radiation and the vastness of space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3848, 1264, 'emotion', 'apathy', NULL, 'The dominant emotional state of a society with no ambition, frontiers, or future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3849, 1264, 'theme', 'societal decay', NULL, 'Depicted through collapsing birth rates, empty playgrounds, and a loss of purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3850, 1265, 'emotion', 'anxiety', NULL, 'The narrator''s growing sense of dread as the glitches become more personal and pervasive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3851, 1265, 'theme', 'reality breakdown', NULL, 'The line between a software bug and a cosmic truth blurs for the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3852, 1265, 'sensory', 'auditory', NULL, 'The unsettling sounds of the AI chanting backwards and the newsfeed speaking in rhyme.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3853, 1265, 'sensory', 'visual', NULL, 'The recurring, impossible geometry of the symbol appearing on screens and glass.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:08:18.883378-05', '2026-02-28 18:08:18.883378-05');
INSERT INTO public.semantic_tags VALUES (3854, 1266, 'emotion', 'resignation', NULL, 'The narrator calmly accepts his death, viewing his past ambitions as irrelevant.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.semantic_tags VALUES (3855, 1266, 'theme', 'mortality', NULL, 'The beat is a direct confrontation with the ordinary, physical process of dying.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.semantic_tags VALUES (3856, 1266, 'sensory', 'olfactory', NULL, 'The impossible scent of peaches and vanilla provides a sharp, surreal sensory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.semantic_tags VALUES (3857, 1266, 'theme', 'existentialism', NULL, 'Reflection on the meaninglessness of dreams and alternate lives in the face of oblivion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.semantic_tags VALUES (3858, 1267, 'emotion', 'transcendence', NULL, 'The narrator''s physical death transforms into a cosmic, auditory experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.semantic_tags VALUES (3859, 1267, 'theme', 'finality', NULL, 'The scene concludes with the narrator''s last words and the cessation of his consciousness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.semantic_tags VALUES (3860, 1267, 'sensory', 'auditory', NULL, 'The focus is on the transformation of a death rattle into a ''perfect hum'' and then silence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.semantic_tags VALUES (3861, 1267, 'theme', 'mystery', NULL, 'The unexplained symbol and code introduce a final, unresolved mystery at the moment of death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:09:14.221319-05', '2026-02-28 18:09:14.221319-05');
INSERT INTO public.semantic_tags VALUES (3862, 1268, 'emotion', 'shock', NULL, 'The protagonist is shocked by the unexpected force and rule-breaking nature of the kick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3863, 1268, 'theme', 'betrayal', NULL, 'The opponent breaks the established rules of a non-full-contact match.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3864, 1268, 'sensory', 'impact', NULL, 'The physical sensation of the kick is described as a ''meteor strike''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3865, 1269, 'emotion', 'overwhelm', NULL, 'The protagonist''s consciousness is flooded with incomprehensible sensory data and visions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3866, 1269, 'theme', 'fractured_reality', NULL, 'Time, space, and memory collapse into a chaotic, non-linear experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3867, 1269, 'sensory', 'auditory_distortion', NULL, 'A referee''s whistle and spoken words are stretched and rearranged into nonsense.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3868, 1269, 'sensory', 'visceral', NULL, 'The physical sensation of vomiting is described as ejecting dreams and regret.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3869, 1270, 'emotion', 'familiarity', NULL, 'The scent of vanilla and peaches provides a moment of recognition amidst the chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3870, 1270, 'theme', 'anchoring', NULL, 'The woman''s appearance provides a single, clear point of focus in the protagonist''s shattered perception.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3871, 1270, 'sensory', 'olfactory', NULL, 'The distinct smell of vanilla and peaches is the first clear sensory detail to emerge from the chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:08.709858-05', '2026-02-28 18:10:08.709858-05');
INSERT INTO public.semantic_tags VALUES (3872, 1271, 'emotion', 'panic', NULL, 'The text explicitly states ''The panic returns, waking up a wild animal inside me.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.semantic_tags VALUES (3873, 1271, 'theme', 'reality collapse', NULL, 'The scene opens with ''The world collapses'' and describes reality fraying and remaking itself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.semantic_tags VALUES (3874, 1271, 'sensory', 'tactile', NULL, 'The feeling of being held down by the mat is a key physical sensation in the midst of mental chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.semantic_tags VALUES (3875, 1271, 'emotion', 'confusion', NULL, 'The protagonist repeatedly asks ''Where am I?'' reflecting his deep disorientation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.semantic_tags VALUES (3876, 1272, 'theme', 'identity crisis', NULL, 'The central conflict of the beat is the protagonist asking ''Who am I?'' and receiving a cryptic answer from another version of himself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.semantic_tags VALUES (3877, 1272, 'emotion', 'fear', NULL, 'The protagonist is frightened by the truth of his fragmented state.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.semantic_tags VALUES (3878, 1272, 'sensory', 'auditory', NULL, 'The beat is dominated by internal dialogue, shouting, and the sound of ''static Latin in broken gospel.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.semantic_tags VALUES (3879, 1272, 'theme', 'existential dread', NULL, 'Visions of ''the death of human ambition'' and seeing himself as a ''dead god at the end of time'' evoke a profound sense of cosmic despair.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:10:49.479606-05', '2026-02-28 18:10:49.479606-05');
INSERT INTO public.semantic_tags VALUES (3880, 1273, 'emotion', 'Confusion', NULL, 'The protagonist cannot distinguish his own thoughts from others and is confused by memories of people both living and dead.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.semantic_tags VALUES (3881, 1273, 'theme', 'Fractured Identity', NULL, 'The use of ''I'', ''we'', ''us'', and ''our minds'' indicates a splintered sense of self.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.semantic_tags VALUES (3882, 1273, 'sensory', 'Auditory', NULL, 'The scene is initiated by a voice from the crowd and dominated by internal dialogue.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.semantic_tags VALUES (3883, 1274, 'theme', 'Surrealism', NULL, 'Reality is distorted with ''shifting geometry'', slow-motion medics, and impossible shadow creatures.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.semantic_tags VALUES (3884, 1274, 'sensory', 'Visual', NULL, 'Focus on shivering lights, blurry crowds, and the writhing forms of the shadows.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.semantic_tags VALUES (3885, 1274, 'emotion', 'Detachment', NULL, 'The protagonist feels he is past panic and is simply an observer to the strange events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.semantic_tags VALUES (3886, 1274, 'emotion', 'Panic', NULL, 'A ''beautiful new panic'' takes hold, suggesting a novel and overwhelming form of terror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:11:31.795623-05', '2026-02-28 18:11:31.795623-05');
INSERT INTO public.semantic_tags VALUES (3887, 1275, 'emotion', 'confusion', NULL, 'The protagonist is unable to reconcile his physical age (16) with his mental age (74).', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.semantic_tags VALUES (3888, 1275, 'sensory', 'synesthesia', NULL, 'Colors have sounds and tastes, and sounds are warped and distorted (e.g., siren as whale song).', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.semantic_tags VALUES (3889, 1275, 'theme', 'perception vs reality', NULL, 'The entire beat is a struggle to understand what is real amidst a sensory overload.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.semantic_tags VALUES (3890, 1275, 'emotion', 'terror', NULL, 'The experience is described with words like ''horror'' and references ''childhood terror''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.semantic_tags VALUES (3891, 1276, 'theme', 'mortality', NULL, 'The protagonist experiences not just one death, but the concept of all his deaths at once.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.semantic_tags VALUES (3892, 1276, 'sensory', 'tactile', NULL, 'The beat is defined by the ''absolute cold'' of the void and the ''lightning'' shock of the defibrillator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.semantic_tags VALUES (3893, 1276, 'emotion', 'despair', NULL, 'The protagonist feels the ''terrible certainty'' that his heart has stopped for good.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.semantic_tags VALUES (3894, 1276, 'theme', 'rebirth', NULL, 'The scene culminates in a violent, forced return to life, cracking the darkness of death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:12:14.619382-05', '2026-02-28 18:12:14.619382-05');
INSERT INTO public.semantic_tags VALUES (3895, 1277, 'emotion', 'shock', NULL, 'The extreme suddenness of the transition from revival to a life-threatening crash.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:01.412884-05', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.semantic_tags VALUES (3896, 1277, 'emotion', 'terror', NULL, 'The feeling of being helpless and trapped inside a tumbling vehicle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:01.412884-05', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.semantic_tags VALUES (3897, 1277, 'theme', 'fragility', NULL, 'A life is given back and then immediately put in mortal danger again, highlighting the precariousness of existence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:01.412884-05', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.semantic_tags VALUES (3898, 1277, 'theme', 'chaos', NULL, 'The world explodes into a disorienting mess of screaming metal, flying equipment, and shattering glass.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:01.412884-05', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.semantic_tags VALUES (3899, 1277, 'sensory', 'auditory', NULL, 'The scene is defined by its sounds: the medic''s voice, the scream of metal, and the final, abrupt silence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:01.412884-05', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.semantic_tags VALUES (3900, 1277, 'sensory', 'kinesthetic', NULL, 'The physical sensation of the ambulance lurching, rolling, and the repeated impacts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:01.412884-05', '2026-02-28 18:13:01.412884-05');
INSERT INTO public.semantic_tags VALUES (3901, 1278, 'sensory', 'auditory distortion', NULL, 'The siren''s ''death-wail distorts to nothing,'' signaling a shift in reality and the onset of shock.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:46.547574-05', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.semantic_tags VALUES (3902, 1278, 'emotion', 'gallows humor', NULL, 'The protagonist laughs in the face of his own death, finding the end of his ''ridiculous story'' absurd.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:46.547574-05', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.semantic_tags VALUES (3903, 1278, 'theme', 'mortality', NULL, 'The protagonist directly confronts his own death, questioning if he''s ''dead again'' before finally surrendering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:46.547574-05', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.semantic_tags VALUES (3904, 1278, 'sensory', 'tactile', NULL, 'The physical sensations of being pinned upside down and blood running through his hair ground the scene in visceral reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:46.547574-05', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.semantic_tags VALUES (3905, 1278, 'emotion', 'resignation', NULL, 'After a brief struggle, the protagonist feels a sense of calm and accepts his fate, allowing ''nothingness'' to take him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:13:46.547574-05', '2026-02-28 18:13:46.547574-05');
INSERT INTO public.semantic_tags VALUES (3906, 1279, 'emotion', 'Desperation', NULL, 'The protagonist is ''scribbling like my life depends on it'' to anchor his sense of self.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3907, 1279, 'theme', 'Temporal Distortion', NULL, 'Time is shown to be broken with impossible values like ''5:69 AM'' and loops.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3908, 1279, 'sensory', 'Olfactory', NULL, 'A complex, layered scent of peaches, vanilla, sadness, and hospital rooms emanates from the clock.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3909, 1280, 'theme', 'Corrupted Memory', NULL, 'Childhood books, anchors of memory and innocence, are warped into monstrous versions of themselves.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3910, 1280, 'sensory', 'Tactile', NULL, 'The paper of the books feels wrong, described as being ''too smooth, like skin''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3911, 1280, 'emotion', 'Dread', NULL, 'The discovery that even physical objects from his past are unstable creates a deep sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3912, 1281, 'emotion', 'Terror', NULL, 'The protagonist is physically attacked by sentient shadows as the world collapses around him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3913, 1281, 'theme', 'Reality Collapse', NULL, 'The scene culminates with reality literally ''folding in half'' and darkness consuming everything.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3914, 1281, 'sensory', 'Auditory', NULL, 'The protagonist is assaulted by both external ''hungry whispers'' and internal ''WAKE UP'' commands.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:14:28.277669-05', '2026-02-28 18:14:28.277669-05');
INSERT INTO public.semantic_tags VALUES (3915, 1282, 'emotion', 'Confusion', NULL, 'The narrator''s immediate reaction to the news report, a clash between his memory and the ''truth'' being presented.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3916, 1282, 'theme', 'Altered History', NULL, 'The scene''s central conflict is introduced via a major historical event being reported incorrectly.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3917, 1282, 'sensory', 'Pain', NULL, 'The physical sensation of the hangover is described as a ''cracked skull''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3918, 1282, 'sensory', 'Auditory', NULL, 'The droning, matter-of-fact voice from the clock-radio delivering world-altering news.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3919, 1283, 'emotion', 'Panic', NULL, 'The narrator''s emotional state escalates as he sees his own handwriting betray him in real-time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3920, 1283, 'theme', 'Unreliable Memory', NULL, 'The journal externalizes the narrator''s memory, only to prove that it is actively and malevolently unstable.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3921, 1283, 'sensory', 'Visual', NULL, 'The act of watching words ''scratch themselves out'' and ''fading mid-sentence'' is the key sensory experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3922, 1284, 'emotion', 'Dread', NULL, 'A creeping horror that comes from the familiar being made subtly wrong, as seen in the cereal boxes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3923, 1284, 'theme', 'Uncanny Valley', NULL, 'The cereal boxes are not wildly different, but their small, incorrect details are deeply unsettling.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3924, 1284, 'sensory', 'Gustatory', NULL, 'The taste of the milk is described as having a ''sour tang of sweetened glue'', and the cereal itself is a ''lie I''m swallowing''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:15:39.523129-05', '2026-02-28 18:15:39.523129-05');
INSERT INTO public.semantic_tags VALUES (3925, 1285, 'emotion', 'Confusion', NULL, 'The narrator is bewildered by the TV showing two different, impossible versions of a movie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:16:14.132125-05', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.semantic_tags VALUES (3926, 1285, 'theme', 'Reality Flux', NULL, 'The boundary between what is real and what is not becomes unstable.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:16:14.132125-05', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.semantic_tags VALUES (3927, 1285, 'sensory', 'Auditory', NULL, 'The incessant clicking of channels and the whir of the VCR create a disorienting soundscape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:16:14.132125-05', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.semantic_tags VALUES (3928, 1286, 'emotion', 'Terror', NULL, 'The narrator experiences paralyzing fear as the shadows emerge and approach.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:16:14.132125-05', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.semantic_tags VALUES (3929, 1286, 'theme', 'Invasion', NULL, 'A hostile force crosses over from a digital realm into physical reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:16:14.132125-05', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.semantic_tags VALUES (3930, 1286, 'sensory', 'Tactile', NULL, 'The intense, unnatural cold and the feeling of icy fingers on the forehead.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:16:14.132125-05', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.semantic_tags VALUES (3931, 1286, 'sensory', 'Olfactory', NULL, 'The distinct smell of copper and ozone accompanies the malevolent entities.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:16:14.132125-05', '2026-02-28 18:16:14.132125-05');
INSERT INTO public.semantic_tags VALUES (3932, 1287, 'emotion', 'desperation', NULL, 'The narrator is desperate for answers and a stable point of reference.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.semantic_tags VALUES (3933, 1287, 'theme', 'fractured identity', NULL, 'The narrator''s self is split into two distinct ages and perspectives, communicating on the page.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.semantic_tags VALUES (3934, 1287, 'sensory', 'tactile', NULL, 'The physical sensation of the pen and the journal as an anchor to reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.semantic_tags VALUES (3935, 1288, 'emotion', 'terror', NULL, 'The fear is described as ''primal'' and causes a physical loss of control.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.semantic_tags VALUES (3936, 1288, 'theme', 'impending doom', NULL, 'The simple, domestic sound of a garage door is framed as the arrival of a monster.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.semantic_tags VALUES (3937, 1288, 'sensory', 'auditory', NULL, 'The sound of the garage door opening is the key sensory input of the beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:00.127024-05', '2026-02-28 18:17:00.127024-05');
INSERT INTO public.semantic_tags VALUES (3938, 1289, 'emotion', 'terror', NULL, 'The narrator''s spine crawls at the sight of his father''s ''wrong'' silhouette.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3939, 1289, 'theme', 'dominance', NULL, 'The father''s entrance immediately establishes his absolute and terrifying authority.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3940, 1289, 'sensory', 'auditory', NULL, 'The scene begins with a door slamming ''like a gunshot'' and a voice that ''fractures reality''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3941, 1290, 'emotion', 'detachment', NULL, 'The narrator dissociates, watching the beating happen to ''someone else'' with clinical coldness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3942, 1290, 'theme', 'trauma', NULL, 'The beat focuses on the brutal physical abuse and the psychological coping mechanism it triggers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3943, 1290, 'sensory', 'tactile', NULL, 'The physical impacts of the belt are described as meteorites, emphasizing the intense pain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3944, 1291, 'emotion', 'defiance', NULL, 'Amidst the pain, the narrator finds a way to resist by choosing to withhold his screams.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3945, 1291, 'theme', 'resilience', NULL, 'A moment of internal strength and realization that he cannot be completely broken.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3946, 1292, 'emotion', 'vindication', NULL, 'The narrator''s knowledge of his parents'' pathetic deaths provides a sense of freedom and justice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3947, 1292, 'theme', 'endurance', NULL, 'The narrator''s goal shifts from fighting back to simply outlasting the abusers until they lose interest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3948, 1292, 'sensory', 'olfactory', NULL, 'The father''s breath smells like ''sulfur and disappointed dreams,'' a scent associated with his demonic rage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:17:43.120803-05', '2026-02-28 18:17:43.120803-05');
INSERT INTO public.semantic_tags VALUES (3949, 1293, 'emotion', 'resilience', NULL, 'The narrator is actively piecing himself back together, driven by ''spite'' in the face of severe injury.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:18:40.25898-05', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.semantic_tags VALUES (4564, 1504, 'emotion', 'rage', NULL, 'Jamie''s transformation is fueled by a desperate, protective fury.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (3950, 1293, 'emotion', 'disorientation', NULL, 'The concussion causes the narrator''s perception of time and space to blur and spin.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:18:40.25898-05', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.semantic_tags VALUES (3951, 1293, 'theme', 'solitude', NULL, 'This is the narrator''s first moment ''alone for the first time since the universe started unraveling''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:18:40.25898-05', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.semantic_tags VALUES (3952, 1293, 'theme', 'mystery', NULL, 'The sudden, inexplicable appearance of a note in his own handwriting creates a sense of unease and foreshadowing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:18:40.25898-05', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.semantic_tags VALUES (3953, 1293, 'sensory', 'auditory', NULL, 'The narrator''s ears are constantly ringing from his injury.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:18:40.25898-05', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.semantic_tags VALUES (3954, 1293, 'sensory', 'kinesthetic', NULL, 'The feeling of the room spinning and the instability of movement is a primary physical sensation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:18:40.25898-05', '2026-02-28 18:18:40.25898-05');
INSERT INTO public.semantic_tags VALUES (3955, 1294, 'sensory', 'tactile_pain', NULL, 'The scene opens with a visceral description of physical agony in every part of the narrator''s body.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:19:18.294406-05', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.semantic_tags VALUES (3956, 1294, 'emotion', 'dread', NULL, 'The realization of the test and his father''s potential wrath creates a fear described as sharper than a concussion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:19:18.294406-05', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.semantic_tags VALUES (3957, 1294, 'theme', 'trauma_recall', NULL, 'The narrator is simultaneously dealing with the physical aftermath and mental replay of a traumatic event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:19:18.294406-05', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.semantic_tags VALUES (3958, 1295, 'emotion', 'rage', NULL, 'The beat culminates in a raw, explosive shout of anger and frustration at his powerlessness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:19:18.294406-05', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.semantic_tags VALUES (3959, 1295, 'theme', 'cognitive_dissonance', NULL, 'The core conflict is the narrator''s awareness that his older self knows the material, while his current self cannot access it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:19:18.294406-05', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.semantic_tags VALUES (3960, 1295, 'sensory', 'auditory', NULL, 'The scene''s climax is the narrator''s loud shout, ''FUCK YOU, UNIVERSE!''', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:19:18.294406-05', '2026-02-28 18:19:18.294406-05');
INSERT INTO public.semantic_tags VALUES (3961, 1296, 'emotion', 'desperation', NULL, 'The narrator''s call is driven by a desperate need for help and connection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3962, 1296, 'theme', 'disorientation', NULL, 'The narrator questions if Jamie is real or a fabrication of his new reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3963, 1296, 'sensory', 'auditory', NULL, 'The scene is established through the ringing phone and Jamie''s sleepy voice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3964, 1297, 'emotion', 'connection', NULL, 'Jamie''s offer to help forges a strong emotional bond between them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3965, 1297, 'theme', 'unspoken feelings', NULL, 'The silence between them is described as a ''live wire,'' full of romantic tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3966, 1298, 'emotion', 'intimacy', NULL, 'Jamie''s ability to ''hear'' the narrator not writing demonstrates a deep, personal knowledge of him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3967, 1298, 'theme', 'understanding', NULL, 'Despite the narrator''s dimensional confusion, Jamie understands his present self perfectly.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3968, 1299, 'emotion', 'appreciation', NULL, 'The narrator''s focus shifts from the lesson to his gratitude for Jamie''s presence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3969, 1299, 'theme', 'exhaustion', NULL, 'The late hour and long conversation create a shared, intimate weariness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3970, 1299, 'sensory', 'tactile', NULL, 'The narrator presses the phone to his ear ''like a lifeline''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3971, 1300, 'emotion', 'vulnerability', NULL, 'Jamie and the narrator share a deeply personal and existential fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3972, 1300, 'theme', 'identity', NULL, 'The conversation directly addresses the feeling of being the ''wrong version'' of oneself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3973, 1301, 'emotion', 'hope', NULL, 'Jamie''s final words and the rising sun leave the narrator feeling more alive and hopeful.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3974, 1301, 'theme', 'parting', NULL, 'The reluctant goodbyes are filled with affection and the promise of meeting again.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3975, 1301, 'sensory', 'visual', NULL, 'The scene concludes with the visual of the sky lightening as dawn breaks.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:20:05.443143-05', '2026-02-28 18:20:05.443143-05');
INSERT INTO public.semantic_tags VALUES (3976, 1302, 'theme', 'routine', NULL, 'Stephen''s description of his Monday actions establishes a baseline of normalcy that is about to be disrupted.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3977, 1302, 'emotion', 'apathy', NULL, 'His reaction (''whatever'') to his significant bruises shows a level of detachment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3978, 1302, 'sensory', 'visual', NULL, 'The focus on how the bruises look in the bathroom mirror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3979, 1303, 'theme', 'social interaction', NULL, 'The scene shifts from internal monologue to external dialogue and social dynamics.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3980, 1303, 'emotion', 'concern', NULL, 'Both Jamie and Becca express worry over Stephen''s physical state, initiating the central conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3981, 1303, 'sensory', 'olfactory', NULL, 'The specific detail of Jamie smelling like ''vanilla and peaches'' grounds the scene and hints at intimacy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3982, 1304, 'emotion', 'confusion', NULL, 'Stephen is completely lost regarding the tension between his friends and why they are focused on him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3983, 1304, 'theme', 'unreliable memory', NULL, 'The older Stephen''s voice introduces the idea that Stephen''s entire perception of his past is flawed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3984, 1304, 'theme', 'internal conflict', NULL, 'The struggle between the oblivious teenager and the all-knowing adult narrator becomes explicit.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3985, 1305, 'emotion', 'paralysis', NULL, 'Stephen''s indecision is so profound it renders him physically unable to act on the opportunity before him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3986, 1305, 'theme', 'rivalry', NULL, 'The competition between Jamie and Becca is crystallized in their competing offers of cookies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3987, 1305, 'theme', 'missed opportunity', NULL, 'The scene ends with Stephen realizing he has failed to act, a central theme reinforced by his older self''s frustration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3988, 1305, 'sensory', 'auditory', NULL, 'The girls'' laughter is described as an ''unreachable song'', emphasizing Stephen''s isolation and failure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:21:18.761858-05', '2026-02-28 18:21:18.761858-05');
INSERT INTO public.semantic_tags VALUES (3989, 1306, 'theme', 'Academic Pressure', NULL, 'The scene is set by the tension of an important test, highlighting the mundane stresses of Stephen''s life.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (3990, 1306, 'emotion', 'Anxiety', NULL, 'Felt by the students, particularly Becca, and the general atmosphere created by Ms. Rodriguez.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (4034, 1322, 'emotion', 'Desire', NULL, 'The dream is a manifestation of Stephen''s deepest desires and wish fulfillment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (3991, 1306, 'sensory', 'Visual', NULL, 'Descriptions of Jamie''s study cards and the ''neat stacks'' of test papers establish the classroom setting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (3992, 1307, 'emotion', 'Terror', NULL, 'The ''perfect moment of terror'' Stephen experiences during the free fall in his vision.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (3993, 1307, 'theme', 'Foreshadowing', NULL, 'The specificity and violence of the vision suggest it is more than a simple daydream and may predict a future event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (3994, 1307, 'sensory', 'Auditory', NULL, 'The shrieking of collapsing scaffolding and the snap of a cable ''with the sound of breaking bones''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (3995, 1308, 'emotion', 'Confusion', NULL, 'Stephen''s primary emotional state as he tries to reconcile the two contradictory versions of reality he just witnessed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (3996, 1308, 'theme', 'Unreliable Reality', NULL, 'The core of the beat, where the objective reality of the classroom becomes unstable and questionable from Stephen''s perspective.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (3997, 1308, 'emotion', 'Concern', NULL, 'Expressed by Jamie, Becca, and Whitney, who all notice Stephen''s distress.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:22:18.394996-05', '2026-02-28 18:22:18.394996-05');
INSERT INTO public.semantic_tags VALUES (3998, 1309, 'theme', 'rivalry', NULL, 'The friendly but pointed competition between Jamie and Becca over Stephen''s attention is established through the offering of cookies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (3999, 1309, 'emotion', 'camaraderie', NULL, 'Despite the underlying tensions, the scene opens with a comfortable gathering of friends.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4000, 1309, 'sensory', 'olfactory', NULL, 'The smell of peanut butter and oatmeal raisin cookies is a tangible element of the social dynamic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4001, 1310, 'emotion', 'alarm', NULL, 'The mood shifts from casual to concerned and tense after Stephen''s question about dying.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4002, 1310, 'theme', 'foreshadowing', NULL, 'Whitney''s warning and the unnatural shadows hint at a larger, unseen conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4003, 1310, 'sensory', 'visual', NULL, 'The shadows under the table are described as ''wrong. Too dark. Too still,'' an unnatural visual cue.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4004, 1311, 'emotion', 'disorientation', NULL, 'Stephen is physically and mentally stunned by the sudden influx of memories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4005, 1311, 'theme', 'memory', NULL, 'The theme of involuntary, fragmented, and potentially past-life memory is central to this beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4006, 1311, 'sensory', 'internal', NULL, 'The primary experience is Stephen''s internal sensation of memories crashing over him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4007, 1312, 'emotion', 'competitiveness', NULL, 'The game becomes a proxy war for the social tensions, especially between Jamie and Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4008, 1312, 'theme', 'mystery', NULL, 'Whitney''s custom ''Veilwalker'' card introduces a supernatural and inexplicable element into the mundane game.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4009, 1312, 'sensory', 'auditory', NULL, 'The sounds of the game—declarations of attacks, spells being cast, and sighs of defeat—dominate the beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4010, 1313, 'emotion', 'fear', NULL, 'Whitney''s final warning is meant to instill fear and caution in Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4011, 1313, 'theme', 'paranoia', NULL, 'The introduction of ''they'' who are ''listening'' creates a sense of being watched by a hostile force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:01.002886-05', '2026-02-28 18:23:01.002886-05');
INSERT INTO public.semantic_tags VALUES (4012, 1314, 'emotion', 'apprehension', NULL, 'Stephen is unsure what to make of Patrick and Whitney approaching him as a team.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4013, 1314, 'theme', 'revelation', NULL, 'The shared secret of the supernatural experiences is brought into the open.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4014, 1314, 'sensory', 'olfactory', NULL, 'The smell of Patrick''s clove cigarettes mixes with the Florida heat, grounding the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4015, 1315, 'theme', 'identity', NULL, 'Whitney''s gender identity and transition are directly linked to her newfound supernatural sensitivity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4016, 1315, 'emotion', 'validation', NULL, 'The friends realize their individual strange experiences are part of a shared, larger phenomenon.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4017, 1315, 'theme', 'supernatural', NULL, 'The characters theorize about the nature of the reality-breaking events they are witnessing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4018, 1316, 'emotion', 'camaraderie', NULL, 'The three friends form a united front against the unknown, ending Stephen''s feeling of isolation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4019, 1316, 'theme', 'conspiracy', NULL, 'The group agrees to meet in secret to investigate, forming a pact.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4020, 1316, 'sensory', 'visual', NULL, 'The long shadows are described as having ''intentional hunger,'' adding a menacing visual element.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:23:56.599271-05', '2026-02-28 18:23:56.599271-05');
INSERT INTO public.semantic_tags VALUES (4021, 1317, 'emotion', 'anxiety', NULL, 'Stephen''s paranoia in his room and his rush to grab the phone before his parents do.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4022, 1317, 'theme', 'shared trauma', NULL, 'Whitney and Stephen connect over their respective supernatural visions and difficult home lives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4023, 1317, 'sensory', 'visual', NULL, 'The description of the sunset bleeding out and staining the ceiling red sets a grim, bloody tone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4024, 1318, 'theme', 'preparation', NULL, 'Whitney is actively preparing to confront the supernatural phenomena by gathering occult supplies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4025, 1318, 'sensory', 'auditory', NULL, 'The sounds of Jamie''s chaotic interruption: giggling, a crash, and wrestling for the phone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4026, 1319, 'emotion', 'flirtation', NULL, 'Jamie''s entire dialogue is laced with playful, romantic innuendo that Stephen misses.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4027, 1319, 'theme', 'miscommunication', NULL, 'A fundamental disconnect where Jamie speaks romantically and Stephen responds technically.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4028, 1320, 'emotion', 'obliviousness', NULL, 'Stephen''s complete failure to understand Jamie''s intentions is the core of this beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4029, 1320, 'theme', 'dramatic irony', NULL, 'The audience, Whitney, and even the shadows understand Jamie''s feelings, but the protagonist does not.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4030, 1320, 'sensory', 'psychological', NULL, 'The shadows watching with ''amusement'' is a projection of Stephen''s internal state and the story''s tone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:24:40.738767-05', '2026-02-28 18:24:40.738767-05');
INSERT INTO public.semantic_tags VALUES (4031, 1321, 'emotion', 'Exhaustion', NULL, 'A bone-deep fatigue described as a ''sledgehammer wrapped in velvet''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4035, 1322, 'theme', 'Wish Fulfillment', NULL, 'Stephen dreams of being wanted by two women who have never shown such interest in reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4036, 1322, 'sensory', 'Tactile', NULL, 'The feeling of Jamie''s and Becca''s hands on his body is a central focus.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4037, 1323, 'emotion', 'Terror', NULL, 'The sensual dream abruptly shifts to a violent, terrifying death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4038, 1323, 'sensory', 'Auditory', NULL, 'The sounds of the crash are visceral: ''Metal screams. Glass explodes.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4039, 1323, 'theme', 'Mortality', NULL, 'The dream culminates in a graphic depiction of death, blending pain and pleasure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4040, 1324, 'emotion', 'Epiphany', NULL, 'Stephen experiences a moment of ''crystalline clarity'' about the nature of his reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4041, 1324, 'theme', 'Alternate Realities', NULL, 'The core revelation is that other timelines exist and are bleeding into his own.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4042, 1324, 'sensory', 'Phantom Sensation', NULL, 'Stephen can still taste gasoline and blood and feel the ghost of their touch after waking.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:25:31.010103-05', '2026-02-28 18:25:31.010103-05');
INSERT INTO public.semantic_tags VALUES (4043, 1325, 'theme', 'Contradiction', NULL, 'The scene is defined by the contrast between expensive, adult luxury and chaotic, teenage mess.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4044, 1325, 'emotion', 'Comfort', NULL, 'Despite the chaos and confusion, the narrator finds the messy environment comforting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4045, 1325, 'sensory', 'Olfactory', NULL, 'The air is thick with the smells of marijuana, sugar, caffeine, and beer.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4046, 1326, 'theme', 'Social Dynamics', NULL, 'The narrator observes the subtle pairings and power structures within the friend group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4047, 1326, 'sensory', 'Tactile', NULL, 'The initiation of physical contact by Jamie and Becca is a key focus.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4048, 1327, 'emotion', 'Tension', NULL, 'The romantic and competitive tension between Jamie and Becca becomes the central focus of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4049, 1327, 'theme', 'Competition', NULL, 'The flirtation is framed as a territorial battle for dominance over the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4050, 1328, 'theme', 'Fate', NULL, 'The spin the bottle game is explicitly framed as letting ''fate decide''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4051, 1328, 'sensory', 'Visual', NULL, 'The spinning bottle catching the blue TV light creates a hypnotic, inevitable feeling.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4052, 1329, 'emotion', 'Agony', NULL, 'The narrator experiences a sudden, violent, and excruciatingly painful psychic event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4053, 1329, 'theme', 'Interruption', NULL, 'A moment of intense romantic culmination is brutally interrupted by an internal force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4054, 1329, 'sensory', 'Kinesthetic', NULL, 'The physical sensation of being violently yanked backward by an unseen force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4055, 1330, 'emotion', 'Concern', NULL, 'The entire group''s focus shifts from drama and games to genuine worry for their friend.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4056, 1330, 'theme', 'Unity', NULL, 'The crisis causes the friends, particularly Jamie and Becca, to set aside their conflicts and unite in support.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:26:40.635031-05', '2026-02-28 18:26:40.635031-05');
INSERT INTO public.semantic_tags VALUES (4057, 1331, 'emotion', 'shock', NULL, 'The group''s reaction to the narrator''s opening line is described as a ''shockwave''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4058, 1331, 'theme', 'confession', NULL, 'The narrator is revealing a deeply buried and traumatic secret for the first time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4059, 1331, 'sensory', 'olfactory', NULL, 'The air is described as heavy with the smell of spilled beer, sweat, and fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4060, 1332, 'emotion', 'horror', NULL, 'The friends are drawn in by the ''horrific magnetism of truth'' and settle in like it''s a ''ghost story that might actually kill them''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4061, 1332, 'theme', 'betrayal', NULL, 'The ultimate betrayal of a mother poisoning her own child is the core of the story.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4062, 1333, 'theme', 'supernatural encounter', NULL, 'The narrator describes meeting a non-human entity in the void between life and death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4063, 1333, 'sensory', 'auditory', NULL, 'The name ''Benji'' is described as ''screaming'' in the narrator''s head and exploding ''like a gunshot'' when spoken.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4064, 1333, 'emotion', 'dread', NULL, 'The description of the void and the entity causes the room to grow cold and breath to mist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4065, 1334, 'theme', 'validation', NULL, 'The narrator presents the polaroid as tangible proof to validate his traumatic memories against his friends'' skepticism.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4066, 1334, 'emotion', 'skepticism', NULL, 'Patrick and TJ immediately offer a rational, scientific explanation (hallucination) for the narrator''s supernatural experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4067, 1335, 'theme', 'poverty', NULL, 'The polaroid and the narrator''s story reveal a past of extreme, grinding poverty and homelessness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4068, 1335, 'emotion', 'shame', NULL, 'The narrator''s words about his father stealing junk ''taste like rust and shame''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4069, 1335, 'sensory', 'visual', NULL, 'The group passes around and closely examines the details of the faded polaroid.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:27:37.669533-05', '2026-02-28 18:27:37.669533-05');
INSERT INTO public.semantic_tags VALUES (4070, 1336, 'emotion', 'dread', NULL, 'The narrator''s explanation instills a sense of a vast, cosmic threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4071, 1336, 'theme', 'existential threat', NULL, 'The idea of an entity hunting them across dimensions is introduced.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4072, 1337, 'emotion', 'terror', NULL, 'The group''s collective scream and panicked actions highlight their extreme fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4073, 1337, 'theme', 'paranormal intrusion', NULL, 'Reality is breached by a hostile, supernatural broadcast that defies physical laws.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4074, 1337, 'sensory', 'auditory assault', NULL, 'The TV erupts at ''maximum volume'' with distorted screaming, causing physical and mental distress.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4075, 1337, 'sensory', 'uncanny valley', NULL, 'The visual of a cartoon dog with realistic human teeth is deeply unsettling.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4076, 1338, 'emotion', 'shock', NULL, 'The group is left in a state of stunned, ringing silence after the violent intrusion and its abrupt end.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4077, 1338, 'theme', 'desperate measures', NULL, 'Physical destruction is the only way to stop the paranormal threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4078, 1338, 'sensory', 'sound of destruction', NULL, 'The noise of wood splintering under assault is a key auditory moment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:28:34.479952-05', '2026-02-28 18:28:34.479952-05');
INSERT INTO public.semantic_tags VALUES (4079, 1339, 'emotion', 'exhaustion', NULL, 'The scene opens with a ''bone-deep exhaustion'' as the characters process a traumatic event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4080, 1339, 'theme', 'connection', NULL, 'New and existing bonds are explored: Jamie comforting the narrator, and Patrick initiating a deeper connection with Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4081, 1339, 'sensory', 'tactile', NULL, 'Physical contact is a key element: Jamie''s warmth, fingers brushing between Patrick and Becca, and Becca''s hug.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4082, 1340, 'emotion', 'confusion', NULL, 'The narrator is confronted with writing and symbols in his journal that he has no memory of creating.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4083, 1340, 'theme', 'discovery', NULL, 'The journal reveals clues that reality is not what it seems, shifting the plot.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4084, 1340, 'sensory', 'visual', NULL, 'The focus is on the ''precise geometric lines'' of the sigil and the newspaper clippings.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4085, 1341, 'emotion', 'terror', NULL, 'Whitney''s confession about death visions and being ''switched'' introduces a profound, existential fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4086, 1341, 'theme', 'existential dread', NULL, 'The characters grapple with the possibility that they are not in their correct reality or even their correct bodies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4087, 1341, 'sensory', 'auditory', NULL, 'The tension is heightened by Whitney''s cracking voice and the burst of static from the TV that sounds like whispers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4088, 1342, 'emotion', 'hope', NULL, 'Despite the terrifying reality, the group finds a sliver of hope in their shared, impossible quest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4089, 1342, 'theme', 'unity', NULL, 'The group solidifies their bond by committing to a shared goal, symbolized by the toast.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4090, 1342, 'sensory', 'auditory', NULL, 'The sound of glass bottles clinking together serves as a ''sacred and profane'' prayer, sealing their pact.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:29:20.446256-05', '2026-02-28 18:29:20.446256-05');
INSERT INTO public.semantic_tags VALUES (4091, 1343, 'emotion', 'Urgency', NULL, 'The late hour and impending responsibilities create a sense of urgency to wrap up the meeting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:30:11.029133-05', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.semantic_tags VALUES (4092, 1343, 'theme', 'Collaboration', NULL, 'The group works together to quickly formulate a plan to continue their investigation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:30:11.029133-05', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.semantic_tags VALUES (4093, 1343, 'sensory', 'Visual', NULL, 'The ''angry green digits'' of the clock are a key visual detail that kicks off the action.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:30:11.029133-05', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.semantic_tags VALUES (4094, 1344, 'emotion', 'Intimacy', NULL, 'The hug between Jamie and the narrator is described as deep and on the verge of changing everything.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:30:11.029133-05', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.semantic_tags VALUES (4095, 1344, 'emotion', 'Frustration', NULL, 'Jamie''s look that could ''freeze fire'' shows her intense frustration at Becca''s interruption.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:30:11.029133-05', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.semantic_tags VALUES (4096, 1344, 'theme', 'Social Power Play', NULL, 'Becca''s interruption is a calculated move to assert dominance and disrupt a rival''s romantic progress.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:30:11.029133-05', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.semantic_tags VALUES (4097, 1344, 'sensory', 'Tactile', NULL, 'The feeling of Jamie''s ''warm and solid'' body and her fingers brushing the narrator''s hand.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:30:11.029133-05', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.semantic_tags VALUES (4098, 1344, 'sensory', 'Auditory', NULL, 'Becca''s ''sharp'' voice and the sound of her mother''s car horn shattering the quiet moment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:30:11.029133-05', '2026-02-28 18:30:11.029133-05');
INSERT INTO public.semantic_tags VALUES (4099, 1345, 'theme', 'Adolescent Freedom', NULL, 'The absence of parental supervision creates an environment where ''terrible decisions feel inevitable''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4100, 1345, 'emotion', 'Anticipation', NULL, 'The group is preparing for a significant, potentially dangerous ritual, creating a tense and expectant mood.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4101, 1345, 'sensory', 'Auditory', NULL, 'The ''satisfying thunk'' of TJ''s beer bottle on the table.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4102, 1346, 'emotion', 'Arousal', NULL, 'The narrator''s stomach does ''complicated gymnastics'' and heat creeps up his neck in response to Jamie''s flirtation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4103, 1346, 'theme', 'Unfinished Business', NULL, 'Jamie explicitly brings up a past romantic moment, creating tension and a promise of future interaction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4104, 1346, 'sensory', 'Tactile', NULL, 'Jamie''s fingertip tracing a pattern on the narrator''s knee is described as feeling like ''writing her name on my soul with electricity''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4105, 1347, 'theme', 'Forbidden Knowledge', NULL, 'The group is using instructions from an obscure occult BBS, delving into things they don''t fully understand.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4106, 1347, 'emotion', 'Pain', NULL, 'The narrator''s concussion becomes a primary focus, described as ''broken glass rattling around in my skull''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4107, 1347, 'sensory', 'Visual Distortion', NULL, 'The narrator''s concussion causes the candlelight to create ''jagged reminders dancing across my peripheral vision''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:31:15.776588-05', '2026-02-28 18:31:15.776588-05');
INSERT INTO public.semantic_tags VALUES (4108, 1348, 'theme', 'irreversibility', NULL, 'Whitney''s warning, ''once we open this door, we can''t just slam it shut,'' sets the stakes for the entire scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:02.688626-05', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.semantic_tags VALUES (4109, 1348, 'emotion', 'apprehension', NULL, 'Becca''s religious fear contrasts with TJ''s casual dismissal, creating a tense atmosphere of anticipation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:02.688626-05', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.semantic_tags VALUES (4110, 1348, 'sensory', 'visual', NULL, 'The description of the tarot cards with shifting images establishes a magical, unstable reality from the start.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:02.688626-05', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.semantic_tags VALUES (4111, 1349, 'theme', 'transgression', NULL, 'The laws of physics are broken as the candle flames freeze, signaling the group has crossed a significant threshold.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:02.688626-05', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.semantic_tags VALUES (4112, 1349, 'sensory', 'tactile', NULL, 'The cold is described not as normal but as something that ''seeps up through the floor and wraps around your bones''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:02.688626-05', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.semantic_tags VALUES (4113, 1349, 'emotion', 'dread', NULL, 'The combination of the cold, the frozen flames, and the disembodied laughter builds a powerful sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:02.688626-05', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.semantic_tags VALUES (4114, 1349, 'sensory', 'auditory', NULL, 'The unseen laughter is the first direct communication from the ''other side'', and it is mocking.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:02.688626-05', '2026-02-28 18:32:02.688626-05');
INSERT INTO public.semantic_tags VALUES (4115, 1350, 'theme', 'Corruption', NULL, 'Both reality and the human body are being violently corrupted and broken down.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4302, 1417, 'emotion', 'terror', NULL, 'The raw, visceral fear of waking from a nightmare that feels real.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4116, 1350, 'sensory', 'Olfactory Assault', NULL, 'The scene is introduced with a litany of visceral, disgusting smells, grounding the horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4117, 1350, 'emotion', 'Dread', NULL, 'The initial wrongness of the chant and the air builds a powerful sense of dread before reality fully breaks.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4118, 1351, 'theme', 'Disassociation', NULL, 'The narrator''s consciousness literally separates from his physical form, a classic trauma response made manifest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4119, 1351, 'emotion', 'Forced Empathy', NULL, 'The silver threads force the narrator to experience the pure, unfiltered agony of his friends, a horrific form of empathy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4120, 1351, 'sensory', 'Synesthesia', NULL, 'The narrator can ''smell their agony'' and ''taste their screams,'' blurring the senses in a traumatic way.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4121, 1352, 'theme', 'Cosmic Horror', NULL, 'The introduction of impossible geometries, pre-human languages, and entities that violate time places the events firmly in the realm of cosmic horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4122, 1352, 'sensory', 'Visual Overload', NULL, 'The scene is a chaotic storm of imagery: multiplying mirrors, burning figures, and centipede choirs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4123, 1352, 'emotion', 'Terror', NULL, 'The horror is no longer just physical but existential, with the revelation of the ''resonance bleed'' and the sheer impossibility of the events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4124, 1353, 'emotion', 'Loss', NULL, 'The snapping of each thread is a distinct moment of loss, culminating in the final, soul-tearing break from Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4125, 1353, 'theme', 'Isolation', NULL, 'The scene ends with the narrator completely alone, severed from everyone he cared about, adrift in darkness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4126, 1353, 'sensory', 'Tactile', NULL, 'The feeling of the warm, thick liquid darkness rising over the narrator''s body provides a final, chilling sensory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:32:52.632028-05', '2026-02-28 18:32:52.632028-05');
INSERT INTO public.semantic_tags VALUES (4127, 1354, 'emotion', 'confusion', NULL, 'The narrator experiences extreme disorientation and ''tonal whiplash'' upon waking in the bizarrely mundane waiting room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4128, 1354, 'theme', 'cosmic bureaucracy', NULL, 'The introduction of a demonic entity who is more concerned with paperwork and procedure than the cosmic horror at play.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4129, 1354, 'sensory', 'gustatory', NULL, 'The taste of the juice boxes directly connects to the narrator''s deep-seated trauma and idealized memories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4130, 1355, 'emotion', 'dread', NULL, 'The narrator begins to understand the scale of his problem, being labeled an ''Existential Hazard''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4131, 1355, 'theme', 'reality breakdown', NULL, 'Benji''s form flickers between mundane and horrifying, mirroring the instability of the narrator''s own reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4132, 1355, 'sensory', 'visual', NULL, 'Flickering lights reveal glimpses of cosmic horrors like the ''centipede choir'', contrasting with the beige surroundings.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4133, 1356, 'emotion', 'revelation', NULL, 'The narrator is hit with the massive, world-shattering truth of his own origin and its consequences.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4134, 1356, 'theme', 'cosmic consequence', NULL, 'A single traumatic event in a child''s life is shown to have catastrophic, reality-spanning repercussions over millions of years.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4135, 1357, 'emotion', 'desperation', NULL, 'Benji''s frantic and failing attempts to provide aid create a sense of hopelessness and urgency as the environment collapses.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4136, 1357, 'theme', 'corrupted aid', NULL, 'Every attempt to help is twisted by The Veil, turning useful tools into near-useless trinkets and clear instructions into nonsense.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4137, 1357, 'sensory', 'auditory', NULL, 'A cosmic multimeter makes sounds ''like a dial-up modem having an aneurysm'' before catching fire, emphasizing the hostile environment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:33:50.421772-05', '2026-02-28 18:33:50.421772-05');
INSERT INTO public.semantic_tags VALUES (4138, 1358, 'emotion', 'Confusion', NULL, 'The narrator''s immediate state upon waking, unable to reconcile his surroundings with his memory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.semantic_tags VALUES (4139, 1358, 'theme', 'Vulnerability', NULL, 'The nakedness and unconsciousness of all the friends highlights their complete helplessness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.semantic_tags VALUES (4140, 1358, 'sensory', 'Tactile', NULL, 'Emphasis on the cold, rough concrete floor and the contrasting temperatures of his friends'' skin.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.semantic_tags VALUES (4141, 1359, 'emotion', 'Terror', NULL, 'The narrator''s fear escalates to sheer terror as multiple, inexplicable supernatural events unfold in rapid succession.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.semantic_tags VALUES (4142, 1359, 'theme', 'Invasion', NULL, 'Reality itself is being invaded, as are the bodies of the friends (Becca''s possession, Jamie''s possession, Patrick''s transformation).', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.semantic_tags VALUES (4143, 1359, 'sensory', 'Auditory', NULL, 'The scene is dominated by unsettling sounds: static, a tinny voice, an unearthly lullaby, and the sound of breathing walls.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.semantic_tags VALUES (4144, 1359, 'sensory', 'Visual', NULL, 'Horrific sights include shifting walls, creeping shadows, and the physical transformation and possession of friends.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:34:45.614633-05', '2026-02-28 18:34:45.614633-05');
INSERT INTO public.semantic_tags VALUES (4145, 1360, 'emotion', 'Disorientation', NULL, 'The characters wake up with no memory, physically and mentally lost.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4146, 1360, 'theme', 'Vulnerability', NULL, 'The group''s nakedness and memory loss leaves them completely exposed and confused.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4147, 1360, 'sensory', 'Olfactory', NULL, 'The scene is defined by the thick, wrong-smelling musk in the air.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4148, 1361, 'theme', 'Transformation', NULL, 'Jamie explicitly states she feels ''changed'', and the obsidian stone physically transforms and then disintegrates.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4149, 1361, 'emotion', 'Intimacy', NULL, 'Jamie''s gaze and words create a sudden, intense, and somewhat unsettling intimacy with the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4150, 1361, 'sensory', 'Visual', NULL, 'The brilliant flash of white light from the stone is a key sensory moment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4151, 1362, 'theme', 'Mundane vs. Supernatural', NULL, 'The sudden appearance of a caring grandmother offering tea provides a jarring contrast to the cosmic horror the group just experienced.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4152, 1362, 'emotion', 'Comfort', NULL, 'TJ''s Nana''s presence, though surreal, brings a sense of safety and maternal care to the exhausted teenagers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4303, 1417, 'theme', 'trauma', NULL, 'The lingering psychological and physical effects of the nightmare.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4153, 1362, 'sensory', 'Auditory', NULL, 'The scene shifts with the sound of Nana''s Irish accent and her shuffling slippers, replacing the tense silence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:35:52.435536-05', '2026-02-28 18:35:52.435536-05');
INSERT INTO public.semantic_tags VALUES (4154, 1363, 'emotion', 'urgency', NULL, 'The group operates with a desperate, addictive energy, trying to recapture a moment of revelation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4155, 1363, 'theme', 'obsession', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4156, 1364, 'theme', 'dissolution', NULL, 'The group begins to fracture as fear and practicality outweigh curiosity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4157, 1364, 'emotion', 'avoidance', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4158, 1365, 'theme', 'manipulation', NULL, 'Jamie plants a false narrative to appear innocent and caring, a classic gaslighting technique.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
