INSERT INTO public.semantic_tags VALUES (4160, 1366, 'emotion', 'frustration', NULL, 'Stephen''s attempts to share vital information are actively shut down by the skeptics.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4161, 1366, 'theme', 'denial', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4162, 1366, 'sensory', 'visual', NULL, 'The shadows are a key visual element, notable for their increasing ability to hide.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4163, 1367, 'emotion', 'tension', NULL, 'A palpable, unspoken conflict between Jamie and Becca comes to the surface.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
