INSERT INTO public.semantic_tags VALUES (4165, 1368, 'theme', 'consequence', NULL, 'Morgan explicitly lists the real-world negative impacts the investigation is having on their lives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
