INSERT INTO public.semantic_tags VALUES (4168, 1369, 'theme', 'reality-bending', NULL, 'The flicker where Patrick disappears is a stark, sensory manifestation of the unstable reality they inhabit.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4169, 1369, 'sensory', 'visual-glitch', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4170, 1370, 'emotion', 'isolation', NULL, 'The scene ends with Stephen being successfully cut off from his remaining allies by Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
