INSERT INTO public.semantic_tags VALUES (4172, 1370, 'sensory', 'auditory', NULL, 'The scene ends in an echoing silence, emphasizing the absence of the now-departed friends.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:37:16.67639-05', '2026-02-28 18:37:16.67639-05');
INSERT INTO public.semantic_tags VALUES (4173, 1371, 'emotion', 'grief', NULL, 'The scene is set during a funeral, with a foundation of sadness and loss.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4174, 1371, 'theme', 'foreboding', NULL, 'The unnatural silence and darkness of the shadows create a sense of impending dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
