INSERT INTO public.semantic_tags VALUES (4176, 1372, 'emotion', 'awe', NULL, 'The characters are stunned into silence by the impossible appearance of Nana''s ghost.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4177, 1372, 'theme', 'supernatural contact', NULL, 'A direct, visual manifestation from a deceased character, confirming the reality of their world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4178, 1372, 'sensory', 'visual', NULL, 'The description focuses on the ''translucent'' figure and the ''glowing'' sigil.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4179, 1373, 'emotion', 'conflict', NULL, 'An immediate clash between those who accept what they saw and those who deny it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4180, 1373, 'theme', 'denial vs. acceptance', NULL, 'The core argument pits rationalization against direct experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4181, 1374, 'emotion', 'apprehension', NULL, 'Jamie voices the group''s underlying fear about the consequences of their actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4182, 1374, 'theme', 'consequence', NULL, 'The dialogue explicitly discusses the real-world costs of their supernatural quest on their lives and relationships.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4183, 1375, 'emotion', 'resolve', NULL, 'Despite their fear, the group makes a firm decision to press forward for answers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4184, 1375, 'theme', 'escalation', NULL, 'The group decides to repeat a dangerous ritual, raising the stakes of the narrative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4185, 1375, 'sensory', 'visual', NULL, 'The final image is of shadows in the car mirror, a visual confirmation that they are being watched or hunted.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:38:19.969551-05', '2026-02-28 18:38:19.969551-05');
INSERT INTO public.semantic_tags VALUES (4186, 1376, 'emotion', 'fear', NULL, 'Jamie explicitly states her fear of not just dying, but of being completely erased from existence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4187, 1376, 'theme', 'consequence', NULL, 'The group is trying to be ''careful'' and learn from past mistakes, showing an awareness of potential negative outcomes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4188, 1376, 'emotion', 'uncertainty', NULL, 'The group debates what they saw at the cemetery, unsure if it was real or imagined.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4189, 1377, 'sensory', 'tactile', NULL, 'The air thickens ''like liquid mercury'' and the temperature plummets, creating a tangible sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4190, 1377, 'theme', 'transgression', NULL, 'The moment the ritual begins, it immediately goes wrong, indicating a boundary has been improperly crossed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4191, 1377, 'emotion', 'dread', NULL, 'The familiar tingle of a summoning quickly escalates into reality buckling at the edges.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4192, 1378, 'theme', 'body horror', NULL, 'Characters suffer grotesque physical violations: a seizure with dark foam, a spontaneous gaping wound, and dissolving body parts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4193, 1378, 'emotion', 'horror', NULL, 'The scene depicts extreme physical and psychological terror as the characters are literally torn apart.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4194, 1378, 'sensory', 'auditory', NULL, 'TJ''s screaming provides a visceral soundtrack to the chaotic violence of the reality breakdown.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4195, 1379, 'emotion', 'shock', NULL, 'Benji''s arrival is not subtle or mysterious, but a violent, fragmented, and furious eruption into their reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4304, 1417, 'sensory', 'tactile', NULL, 'The feeling of cold sweat welding a notebook to Stephen''s chest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4196, 1379, 'theme', 'revelation', NULL, 'Benji reveals the true nature of the sigil and the catastrophic scale of what the group has just done.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4197, 1379, 'sensory', 'auditory', NULL, 'Benji''s voice is physically destructive, causing the ceiling to rain screaming plaster.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4198, 1380, 'theme', 'cosmic horror', NULL, 'The core horror is not a monster, but the revelation that their reality is fragile and they have attracted the attention of things that operate on a scale beyond their comprehension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4199, 1380, 'emotion', 'foreboding', NULL, 'Benji''s final warning that ''the wrong things'' will notice them leaves the group in a state of profound dread for the future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4200, 1380, 'sensory', 'olfactory', NULL, 'The lingering smell of sulfur and surgical antiseptic grounds the cosmic horror in a visceral, unsettling scent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:39:35.856273-05', '2026-02-28 18:39:35.856273-05');
INSERT INTO public.semantic_tags VALUES (4201, 1381, 'emotion', 'fear', NULL, 'TJ''s confidence is replaced by fear, driving him to quit.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4202, 1381, 'theme', 'fracturing alliance', NULL, 'The first crack in the group''s unity appears as a key member leaves.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
