INSERT INTO public.semantic_tags VALUES (4207, 1383, 'emotion', 'tension', NULL, 'The ''uncomfortable silence'' highlights the immense pressure on the three remaining members.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4208, 1384, 'emotion', 'accusation', NULL, 'The core of the beat is Whitney''s direct and venomous accusation against Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4209, 1384, 'theme', 'betrayal revealed', NULL, 'Whitney exposes Jamie''s long-term sabotage of the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4210, 1384, 'sensory', 'auditory', NULL, 'Whitney''s voice gains strength and drops to a whisper, emphasizing the gravity of her words.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4211, 1385, 'emotion', 'devastation', NULL, 'Whitney''s face ''collapses'' as she realizes Stephen has chosen Jamie, showing complete emotional ruin.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4212, 1385, 'theme', 'fateful choice', NULL, 'Stephen''s non-decision is the pivotal choice that seals the group''s fate and his own immediate future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4213, 1385, 'sensory', 'tactile', NULL, 'Jamie''s grip on Stephen''s hand is described as an ''anchor'', a physical sensation grounding his emotional choice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4214, 1386, 'emotion', 'hysteria', NULL, 'Stephen''s laughter is described as ''slightly hysterical'', a release of the immense tension from the preceding events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4215, 1386, 'theme', 'bathos', NULL, 'The high emotional drama of the confrontation is immediately undercut by the absurd, comedic intrusion of a child.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4216, 1386, 'sensory', 'auditory', NULL, 'The sound of the door bursting open and Tiffany''s rapid-fire questions shatters the quiet intimacy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:40:30.22756-05', '2026-02-28 18:40:30.22756-05');
INSERT INTO public.semantic_tags VALUES (4217, 1387, 'theme', 'normalcy', NULL, 'The scene is deliberately set up as a mundane, everyday lunch period to contrast with the horror to come.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4218, 1387, 'emotion', 'camaraderie', NULL, 'The friends are comfortable and relaxed in their shared space and hobby.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4219, 1387, 'theme', 'foreshadowing', NULL, 'Whitney''s exhaustion, her journal, and Jamie''s strange distance all hint that something is wrong beneath the surface.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4220, 1388, 'theme', 'reality-breach', NULL, 'The physical world peels away to reveal a hostile dimension underneath.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4221, 1388, 'emotion', 'terror', NULL, 'The sudden and inexplicable violation of reality induces pure horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4222, 1388, 'sensory', 'olfactory', NULL, 'The smell of the hellscape is described as sewage, burning meat, and a sweet scent that makes ''ears want to vomit''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4223, 1389, 'emotion', 'helplessness', NULL, 'The narrator and friends are physically unable to move or intervene as Whitney is taken.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4224, 1389, 'emotion', 'desperation', NULL, 'Exemplified by Whitney''s screams for help and her plea not to be forgotten.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4225, 1389, 'sensory', 'auditory', NULL, 'The scene is filled with chaotic sounds: Whitney''s screams, the fragmented voice of Benji, and the alien voice from Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4226, 1390, 'theme', 'memory-alteration', NULL, 'Reality reasserts itself by erasing a person from the memories of most witnesses.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4227, 1390, 'emotion', 'guilt', NULL, 'The narrator and the group are left with the crushing guilt of having let Whitney investigate alone, as symbolized by the Veilwalker card.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4228, 1390, 'emotion', 'grief', NULL, 'The immediate aftermath is filled with shock and a profound sense of loss for their vanished friend.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:41:52.470489-05', '2026-02-28 18:41:52.470489-05');
INSERT INTO public.semantic_tags VALUES (4229, 1391, 'theme', 'Bigotry', NULL, 'William''s immediate use of racist slurs against Mr. Martinez sets the tone for his character.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.semantic_tags VALUES (4230, 1391, 'emotion', 'Dread', NULL, 'The friend group''s reaction to William''s arrival is one of immediate tension and fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.semantic_tags VALUES (4231, 1391, 'sensory', 'Auditory', NULL, 'The scene is dominated by William ''bellowing'' across the courtyard, a sound of aggression.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.semantic_tags VALUES (4232, 1392, 'theme', 'Violence', NULL, 'The conflict escalates from verbal to physical assault when William slams TJ into the table.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.semantic_tags VALUES (4233, 1392, 'emotion', 'Rage', NULL, 'TJ''s protective anger boils over when Morgan is insulted, triggering the physical confrontation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.semantic_tags VALUES (4234, 1392, 'sensory', 'Olfactory', NULL, 'The narrator notes the specific, unpleasant smell of William''s cheap deodorant, linking it to his character.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.semantic_tags VALUES (4235, 1393, 'theme', 'Gaslighting', NULL, 'William attempts to overwrite Patrick''s memories with a false history, a form of psychological abuse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.semantic_tags VALUES (4236, 1393, 'emotion', 'Horror', NULL, 'The group''s realization that their reality has been fundamentally and maliciously altered.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:42:56.232966-05', '2026-02-28 18:42:56.232966-05');
INSERT INTO public.semantic_tags VALUES (4237, 1394, 'emotion', 'frustration', NULL, 'TJ''s violent outburst after the ritual fails highlights the group''s growing desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4238, 1394, 'theme', 'corruption', NULL, 'The moth-shaped hole in reality symbolizes that their connection to the supernatural is not just broken, but tainted.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4239, 1394, 'sensory', 'olfactory', NULL, 'The chanted words tasting like ''ash'' instead of ''copper and starlight'' signifies a profound loss of magic and hope.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4240, 1395, 'emotion', 'cruelty', NULL, 'Becca''s words and actions are deliberately hurtful, a stark contrast to her previous personality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4241, 1395, 'theme', 'denial', NULL, 'Becca''s insistence that Whitney never existed is a form of psychological attack on the group''s shared reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4242, 1395, 'sensory', 'auditory', NULL, 'The slap ''echoed through Patrick''s bedroom like a gunshot,'' marking a point of no return in the group''s dynamic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4243, 1396, 'emotion', 'possessiveness', NULL, 'Jamie''s attempt to isolate the narrator is driven by a desperate fear of losing him, framed as ''You''re mine''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4244, 1396, 'theme', 'temptation', NULL, 'The narrator is tempted to abandon his friends and their hopeless cause for a new life with Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4245, 1396, 'sensory', 'tactile', NULL, 'The feeling of Jamie''s hand on the narrator''s thigh and her breath against his ear creates an intimate but tense atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4246, 1397, 'emotion', 'betrayal', NULL, 'Becca''s final tirade feels like a deep betrayal, attacking her friends'' sanity and personal relationships.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4247, 1397, 'theme', 'collapse', NULL, 'The scene ends with the group physically and emotionally shattered, left in darkness as their unity dissolves.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4248, 1397, 'sensory', 'visual', NULL, 'The candles extinguishing on their own, plunging the group into a profound darkness, symbolizes the end of their hope.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:43:55.505593-05', '2026-02-28 18:43:55.505593-05');
INSERT INTO public.semantic_tags VALUES (4249, 1398, 'theme', 'Coping Mechanisms', NULL, 'Each member of the friend group deals with the shared trauma in a distinct way: romantic obsession, academic mania, manipulative affection, or determined remembrance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.semantic_tags VALUES (4250, 1398, 'emotion', 'Grief', NULL, 'The narrator''s actions are driven by a refusal to accept the loss of Whitney, which his friends interpret as an inability to grieve properly.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.semantic_tags VALUES (4251, 1399, 'theme', 'Memory as Resistance', NULL, 'The narrator uses the act of remembering and documenting as a weapon against the force that erased Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.semantic_tags VALUES (4252, 1399, 'emotion', 'Suspicion', NULL, 'The narrator begins to realize that Jamie''s actions, both in dreams and reality, are not what they seem and form a deliberate pattern of obstruction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.semantic_tags VALUES (4253, 1399, 'sensory', 'Psychological', NULL, 'The conflict plays out in the narrator''s subconscious, with dreams becoming a battlefield for his attention.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.semantic_tags VALUES (4254, 1400, 'theme', 'Temporal Paradox', NULL, 'A message from two weeks in the future appears in the present, breaking the rules of time and confirming the supernatural nature of events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.semantic_tags VALUES (4255, 1400, 'emotion', 'Hope', NULL, 'The discovery of the letter transforms the narrator''s desperate obsession into tangible hope, giving him a clear mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.semantic_tags VALUES (4256, 1400, 'sensory', 'Auditory', NULL, 'The sound of the wind rattling the window pane serves as an external punctuation to the internal shock of the narrator''s discovery.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:44:47.603186-05', '2026-02-28 18:44:47.603186-05');
INSERT INTO public.semantic_tags VALUES (4257, 1401, 'emotion', 'obsession', NULL, 'Stephen''s mind ''won''t stop picking at'' the message like a scab, indicating a compulsive, unhealthy focus.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4258, 1401, 'theme', 'haunting', NULL, 'He is literally haunted by Whitney''s words, unable to find peace or sleep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4259, 1402, 'sensory', 'auditory', NULL, 'The ''familiar electronic whine'' and the ''modem''s screech'' are key sounds of this era''s digital exploration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4260, 1402, 'theme', 'futility', NULL, 'Stephen spirals through ''digital detritus'' and ''breadcrumbs that crumble to nothing,'' highlighting the hopelessness of his search.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4261, 1403, 'emotion', 'shock', NULL, 'The discovery of the future-dated message makes his ''stomach drop through the floor''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4262, 1403, 'theme', 'prophecy', NULL, 'The printer materializes the message with the ''precision of prophecy being carved into stone''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4263, 1403, 'emotion', 'fear', NULL, 'Stephen''s heart ''hammers against his ribs'' at the thought of his father waking up.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4264, 1404, 'emotion', 'arousal', NULL, 'Jamie''s seductive tone causes heat to crawl up Stephen''s neck and makes him speechless.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4265, 1404, 'theme', 'miscommunication', NULL, 'Stephen calls for help with a supernatural mystery, while Jamie interprets the call as a romantic advance, leading to a clash of intentions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4266, 1405, 'emotion', 'conflict', NULL, 'Stephen is left torn between the tangible temptation offered by Jamie and the intangible mystery of Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4267, 1405, 'theme', 'surveillance', NULL, 'The scene ends with the explicit feeling of being watched by an unknown, patient entity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4268, 1405, 'sensory', 'olfactory', NULL, 'The smell of ''vanilla and peaches'' appears supernaturally, linked to the watcher and temptation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:03.28375-05', '2026-02-28 18:46:03.28375-05');
INSERT INTO public.semantic_tags VALUES (4269, 1406, 'sensory', 'olfactory', NULL, 'The scene is introduced with strong smells of sweat, melted rubber, and swamp rot, establishing a visceral and unpleasant setting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4270, 1406, 'theme', 'neglect', NULL, 'Coach Henderson''s drunken apathy represents a failure of adult supervision, leaving the teens to their own devices.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4271, 1406, 'emotion', 'desperation', NULL, 'The air is described as tasting like ''teenage desperation'', setting a tone of unease from the start.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4272, 1407, 'emotion', 'temptation', NULL, 'Jamie''s seductive whispers and touch act as a direct temptation, attempting to pull Stephen away from the group''s mysterious quest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4273, 1407, 'theme', 'foreshadowing', NULL, 'Whitney''s message about ''nothing red'' and Patrick''s flash of a memory both hint at the danger and unreality to come.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4274, 1407, 'emotion', 'conflict', NULL, 'Stephen experiences internal conflict between his desire for Jamie and his responsibility to heed Whitney''s warning.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4275, 1408, 'emotion', 'dread', NULL, 'The atmosphere builds from unease to outright dread as the woods close in and the trailer is discovered.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4276, 1408, 'theme', 'unreality', NULL, 'The trailer''s impossible existence and the flood of conflicting memories shatter the characters'' sense of a stable reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4277, 1408, 'sensory', 'auditory', NULL, 'The eerie sound of makeshift wind chimes and the imagined sound of TV static contribute to the supernatural horror of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:46:58.7638-05', '2026-02-28 18:46:58.7638-05');
INSERT INTO public.semantic_tags VALUES (4278, 1409, 'theme', 'reality-bending', NULL, 'The fundamental laws of physics and time are shown to be fragile and easily broken.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4279, 1409, 'emotion', 'disorientation', NULL, 'The group''s sense of place and normalcy is shattered by the impossible events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4280, 1409, 'sensory', 'auditory distortion', NULL, 'A high-frequency buzz and underwater-sounding voices create an unsettling soundscape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4281, 1410, 'emotion', 'horror', NULL, 'The scene is filled with grotesque and surreal imagery designed to terrify.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4282, 1410, 'theme', 'corruption', NULL, 'Familiar and comforting places from the characters'' lives are twisted into nightmarish versions of themselves.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4283, 1410, 'sensory', 'olfactory', NULL, 'Smells are inverted, with pleasant things smelling foul and vice-versa, adding to the sense of wrongness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4284, 1411, 'theme', 'erasure', NULL, 'A person is being actively removed from reality and memory, which is presented as a form of metaphysical violence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4285, 1411, 'emotion', 'desperation', NULL, 'Stephen''s frantic search through his journal highlights his desperate struggle against an intangible enemy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4286, 1411, 'theme', 'memory as resistance', NULL, 'The act of remembering and recording a memory becomes a weapon against the hostile reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4287, 1412, 'emotion', 'panic', NULL, 'The scene culminates in desperate screams and the urgent need to flee for their lives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4288, 1412, 'theme', 'betrayal', NULL, 'Jamie is revealed to be both a victim and a willing or unwilling accomplice to the forces trying to harm them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4289, 1412, 'sensory', 'auditory', NULL, 'The beat is defined by the synchronized, desperate screams of Whitney and Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:47:47.029577-05', '2026-02-28 18:47:47.029577-05');
INSERT INTO public.semantic_tags VALUES (4290, 1413, 'emotion', 'desperation', NULL, 'The group is fleeing for their lives but finds no escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4291, 1413, 'theme', 'entrapment', NULL, 'Reality itself has become a prison, looping back on itself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4292, 1413, 'sensory', 'auditory', NULL, 'The soundscape is filled with inhuman noises: grinding cosmic gears and the implied sound of screaming faces.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4293, 1414, 'emotion', 'frantic hope', NULL, 'The group''s last-ditch ritual is an act of desperation against impossible odds.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4294, 1414, 'theme', 'forbidden contact', NULL, 'Their attempt to reach an ally instead contacts something ancient and hostile.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4295, 1414, 'sensory', 'auditory', NULL, 'The radio static is described as bleeding, and the voices are ancient and cause physical pain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4296, 1415, 'emotion', 'anguish', NULL, 'The core emotion of the vision is the shared, eternal suffering of Jamie and the horror of the witness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4297, 1415, 'theme', 'punishment', NULL, 'The scene is a direct, cosmic punishment for the ''crime'' of love, which is framed as rebellion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4298, 1415, 'sensory', 'visual', NULL, 'The imagery is surreal and horrific: screaming mouths, liquid regret, and the dual burning forms of Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4299, 1416, 'emotion', 'agony', NULL, 'Pain is not just felt but becomes the fundamental nature of existence for the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4300, 1416, 'theme', 'dissolution', NULL, 'The narrator''s consciousness, self, and reality itself are coming apart.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4301, 1416, 'sensory', 'olfactory', NULL, 'The final perception is a specific, meaningful scent, contrasting the overwhelming agony.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:48:59.323702-05', '2026-02-28 18:48:59.323702-05');
INSERT INTO public.semantic_tags VALUES (4508, 1485, 'theme', 'transformation', NULL, 'Jamie''s transformation is shown through domestic, gentle skills, contrasting with her demonic origins.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4509, 1485, 'sensory', 'olfactory', NULL, 'The smell of the food is described as smelling like ''love instead of sulfur''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4510, 1485, 'emotion', 'hope', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4511, 1486, 'emotion', 'vulnerability', NULL, 'Jamie opens up about the pain of her dual memories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4512, 1486, 'theme', 'identity crisis', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4513, 1486, 'emotion', 'intimacy', NULL, 'The physical and emotional closeness between Stephen and Jamie during a difficult conversation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4514, 1487, 'emotion', 'longing', NULL, 'Jamie''s deep desire for a normal teenage experience is palpable.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4515, 1487, 'theme', 'aspiration', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4516, 1487, 'theme', 'normalcy', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4517, 1488, 'emotion', 'despair', NULL, 'Jamie''s breakdown upon realizing her powers and old identity are gone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4518, 1488, 'theme', 'loss of self', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4519, 1488, 'sensory', 'visual', NULL, 'The image of smeared mascara from her tears.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4520, 1489, 'emotion', 'desperation', NULL, 'Both characters desperately cling to the idea of a future together.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4521, 1489, 'theme', 'commitment', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4522, 1489, 'sensory', 'gustatory', NULL, 'The taste of the kiss is described as strawberry lip gloss, smoke, and honey.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:07:05.433076-05', '2026-02-28 19:07:05.433076-05');
INSERT INTO public.semantic_tags VALUES (4523, 1490, 'emotion', 'Dread', NULL, 'Stephen''s feeling of dread contrasts with the group''s relief, highlighting his isolation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4305, 1418, 'emotion', 'panic', NULL, 'Described as ''battery acid'' crawling up his throat due to the inability to connect with anyone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4306, 1418, 'theme', 'desperate connection', NULL, 'The frantic, simultaneous need for everyone to confirm they are not alone in their experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4307, 1418, 'sensory', 'auditory', NULL, 'The ''monotone drone'' of the busy signal, described as a ''slap''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4308, 1419, 'theme', 'fractured reality', NULL, 'The central conflict is established: two groups of friends with two different sets of memories.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4309, 1419, 'emotion', 'relief', NULL, 'Stephen''s immediate feeling upon seeing his friends'' handles online, confirming they are alive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4310, 1419, 'sensory', 'visual', NULL, 'The image of blue pixels ''bleeding across the screen like digital blood''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4311, 1420, 'theme', 'loyalty', NULL, 'The skeptics choose to help their friends despite believing they are having a psychotic episode.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4312, 1420, 'emotion', 'hope', NULL, 'A fragile hope that comes from the friends agreeing to meet, even with the divide between them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4313, 1421, 'emotion', 'dread', NULL, 'The ominous feeling left by the anonymous, vanishing message.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4314, 1421, 'theme', 'surveillance', NULL, 'The message implies that an unknown party is watching the group''s interactions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4315, 1421, 'sensory', 'visual', NULL, 'The message ''glowing like a threat or a promise'' before disappearing into empty space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:50:07.121505-05', '2026-02-28 18:50:07.121505-05');
INSERT INTO public.semantic_tags VALUES (4316, 1422, 'emotion', 'desperation', NULL, 'Stephen''s frantic writing is an attempt to cage the trauma in ink, to make it solid and understandable before it dissolves.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4317, 1422, 'theme', 'trauma_documentation', NULL, 'The act of writing is used as an anchor to a reality that is slipping away.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4318, 1422, 'sensory', 'gustatory', NULL, 'The lingering taste of ''ash and copper'' from the nightmare makes the experience feel physically real.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4319, 1423, 'emotion', 'dread', NULL, 'The discovery of familiar objects behaving in impossible ways creates a deep sense of unease and dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4320, 1423, 'theme', 'reality_corruption', NULL, 'A simple deck box and card defy the rules of reality, suggesting the nightmare''s influence is bleeding into the physical world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4321, 1423, 'sensory', 'tactile', NULL, 'The Veilwalker card feels warm and pulses with a heartbeat, blurring the line between object and organism.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4322, 1424, 'emotion', 'bewilderment', NULL, 'Stephen is confronted with a message that is both impossible and intimately personal, leaving him confused and afraid.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4323, 1424, 'theme', 'cryptic_guidance', NULL, 'An unknown force provides a mysterious quest, suggesting a path forward but offering no clear answers or reasons to trust it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4324, 1424, 'sensory', 'visual', NULL, 'The blue ink that refuses to dry is a stark, unnatural visual that proves the message is not a hallucination.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:51:11.880826-05', '2026-02-28 18:51:11.880826-05');
INSERT INTO public.semantic_tags VALUES (4325, 1425, 'emotion', 'Dread', NULL, 'Stephen''s immediate physical reaction of going rigid stems from a deep-seated dread of his father, which is then amplified by the unnatural kindness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4326, 1425, 'theme', 'Subversion of Expectation', NULL, 'The entire interaction is built on subverting Stephen''s expectations of abuse, replacing it with a kindness that is even more terrifying.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4327, 1425, 'sensory', 'Auditory', NULL, 'The gentle ''knock knock'' and the ''soft, warm, kind'' voice are the primary sensory triggers for Stephen''s fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4328, 1426, 'emotion', 'Horror', NULL, 'Stephen''s terror escalates from fear of violence to a deeper horror of the unnatural, as evidenced by his vanished wounds.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4329, 1426, 'theme', 'Gaslighting', NULL, 'The disappearance of the wounds is a form of reality-warping that erases the evidence of abuse, a powerful form of gaslighting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4330, 1426, 'sensory', 'Tactile', NULL, 'The act of Stephen touching his own unmarked skin, feeling the absence of welts and bruises, is a key sensory moment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4331, 1427, 'emotion', 'Psychological Terror', NULL, 'The fear is not of physical harm, but of mental and emotional manipulation—the fear of being tricked into trusting an abuser.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4332, 1427, 'theme', 'Trust as a Weapon', NULL, 'Stephen identifies that the true danger is the temptation to trust, which feels like ''the most dangerous trap of all''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4333, 1427, 'sensory', 'Olfactory', NULL, 'The ''perfect'' smell of pancakes acts as a sensory lure, representing the deceptive appeal of this false reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:09.281804-05', '2026-02-28 18:52:09.281804-05');
INSERT INTO public.semantic_tags VALUES (4334, 1428, 'theme', 'memory alteration', NULL, 'Multiple characters report fundamental facts about their lives and families being wrong, establishing the nature of the threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4335, 1428, 'emotion', 'dread', NULL, 'The accumulation of stories creates a palpable sense of dread and shared trauma among the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4336, 1428, 'sensory', 'auditory', NULL, 'Jamie''s voice is described as ''hollow as a church bell with the clapper removed''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4337, 1429, 'emotion', 'denial', NULL, 'Andrew''s explosive outburst is a desperate attempt to deny the supernatural events by demanding empirical proof of their absence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4338, 1429, 'theme', 'proof vs. belief', NULL, 'The conflict between Andrew''s demand for proof of absence and Stephen''s presentation of proof of impossibility (the card).', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4339, 1430, 'emotion', 'desperation', NULL, 'The group''s repeated, increasingly loud chanting shows their growing desperation for answers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4340, 1430, 'theme', 'ritual', NULL, 'The characters engage in a classic trope of a summoning ritual, highlighting their shift from rational actors to participants in the supernatural.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4341, 1430, 'sensory', 'visual', NULL, 'The guttering candle flame casts ''long and wrong'' shadows, enhancing the occult atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4342, 1431, 'emotion', 'terror', NULL, 'The appearance of Benji causes an immediate and total breakdown of composure in multiple characters.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4343, 1431, 'theme', 'cosmic horror', NULL, 'Benji''s glitching, indescribable form is a classic element of cosmic horror, something the human mind cannot properly process.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4344, 1431, 'sensory', 'olfactory', NULL, 'The arrival of Benji is heralded by the ''acrid smell of burning moths''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4345, 1432, 'theme', 'censorship', NULL, 'Reality itself actively and violently prevents a name from being spoken, establishing a theme of forbidden knowledge.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4346, 1432, 'sensory', 'auditory', NULL, 'The scream is described as coming from inside their skulls, a deeply invasive and painful sound.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4347, 1432, 'emotion', 'powerlessness', NULL, 'The group and even the powerful Benji are rendered helpless by the force of the scream.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4348, 1433, 'theme', 'coping mechanisms', NULL, 'The characters immediately shift to a practical, mundane problem (getting Andrew to the nurse) as a way to cope with the incomprehensible horror they just witnessed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4349, 1433, 'emotion', 'pragmatism', NULL, 'Despite the terror, Morgan and James revert to logical planning, showing a desperate attempt to regain control.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4350, 1433, 'sensory', 'kinesthetic', NULL, 'The physical act of carrying Andrew''s unconscious body grounds the characters in a tangible task.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:52:59.113523-05', '2026-02-28 18:52:59.113523-05');
INSERT INTO public.semantic_tags VALUES (4351, 1434, 'emotion', 'dread', NULL, 'The realization that their friends might not be real fills the group with a deep, existential dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4352, 1434, 'theme', 'paranoia', NULL, 'The warning in the journal immediately sows distrust and suspicion among the survivors.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4353, 1434, 'sensory', 'tactile', NULL, 'Jamie''s ''almost painful'' grip signifies her desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4354, 1435, 'theme', 'duality', NULL, 'Stephen sees Jamie as both ''the demon and the saint'' existing in the same space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4355, 1435, 'sensory', 'visual', NULL, 'The superimposition of Jamie''s human and demonic forms, including her cat-like eyes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4356, 1435, 'emotion', 'confusion', NULL, 'TJ''s inability to remember his relationship status highlights the cognitive breakdown caused by the unstable reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4357, 1436, 'theme', 'unreliable reality', NULL, 'The mundane school environment feels ''completely wrong'' as the characters know the world is coming apart at the seams.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4358, 1436, 'sensory', 'olfactory', NULL, 'Jamie''s kiss tastes of vanilla and something ancient and unsettling, like eggs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4359, 1436, 'emotion', 'desperation', NULL, 'The kisses exchanged—Becca and Patrick''s, and Jamie''s—are not romantic but desperate acts to confirm reality and connection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:54:03.780704-05', '2026-02-28 18:54:03.780704-05');
INSERT INTO public.semantic_tags VALUES (4360, 1437, 'emotion', 'exhaustion', NULL, 'Stephen is mentally drained from his supernatural homework and avoiding his journal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4361, 1437, 'theme', 'intrusion', NULL, 'Jamie''s appearance is a violation of Stephen''s safe, albeit miserable, space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4362, 1437, 'sensory', 'auditory', NULL, 'The three deliberate, patient taps on the window cut through the silence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4363, 1438, 'emotion', 'desire', NULL, 'Stephen feels an overwhelming physical attraction to Jamie despite the numerous red flags.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4364, 1438, 'emotion', 'terror', NULL, 'Desire is mixed with a primal fear due to the wrongness of Jamie''s actions and demeanor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4365, 1438, 'theme', 'seduction', NULL, 'Jamie''s actions are a carefully choreographed, predatory seduction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4366, 1438, 'sensory', 'olfactory', NULL, 'The scent of vanilla and peaches is strongly associated with Jamie''s presence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4367, 1439, 'emotion', 'horror', NULL, 'Stephen''s reaction to hearing the name ''Aspolin'' is one of pure, ice-cold horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4368, 1439, 'theme', 'revelation', NULL, 'The name reveals a deeper, supernatural connection and confirms the danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4369, 1439, 'sensory', 'auditory', NULL, 'A single whispered name changes the entire dynamic of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4370, 1440, 'theme', 'betrayal', NULL, 'The act of seduction is revealed to be a prelude to a sacrificial murder.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4371, 1440, 'emotion', 'desperation', NULL, 'The struggle becomes a desperate fight for survival.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4372, 1440, 'sensory', 'visual', NULL, 'The ornate, beautiful, and wrong appearance of the ritual knife is a key visual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4373, 1441, 'theme', 'reality manipulation', NULL, 'Reality itself is edited to resolve an impossible conflict, highlighting the unstable nature of Stephen''s world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4374, 1441, 'emotion', 'confusion', NULL, 'Jamie''s sudden shift to a shy, unaware state is jarring and disorienting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4375, 1441, 'sensory', 'olfactory', NULL, 'The smell of ozone and burning circuits signifies the supernatural ''edit'' of reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4376, 1441, 'theme', 'duality', NULL, 'The scene starkly contrasts the two Jamies: the predatory ritualist and the shy, affectionate girl.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:55:18.649941-05', '2026-02-28 18:55:18.649941-05');
INSERT INTO public.semantic_tags VALUES (4377, 1442, 'emotion', 'shock', NULL, 'The friends'' collective reaction to the news of Jamie''s murder attempt is one of utter disbelief and horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:15.489481-05', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.semantic_tags VALUES (4378, 1442, 'theme', 'betrayal', NULL, 'A close friend has turned into a deadly, monstrous enemy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:15.489481-05', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.semantic_tags VALUES (4379, 1442, 'sensory', 'auditory', NULL, 'The buzzing of the fluorescent lights creates an unsettling, insect-like soundscape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:15.489481-05', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.semantic_tags VALUES (4380, 1442, 'emotion', 'fear', NULL, 'Becca''s voice is threaded with fear, reflecting the group''s terror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:15.489481-05', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.semantic_tags VALUES (4381, 1443, 'theme', 'revelation', NULL, 'Stephen explains the cosmic framework of their reality, introducing the concepts of Etheris and the Jailers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:15.489481-05', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.semantic_tags VALUES (4382, 1443, 'emotion', 'resolve', NULL, 'Despite the danger, Stephen and the group decide to fight back, with Stephen accepting his role as bait.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:15.489481-05', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.semantic_tags VALUES (4383, 1443, 'theme', 'strategy', NULL, 'The group moves from shock to action, devising a plan to turn their enemy''s tactics against her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:15.489481-05', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.semantic_tags VALUES (4384, 1443, 'sensory', 'visual', NULL, 'The ''sick yellow'' light of the 7-Eleven visually represents the unhealthy and dangerous situation the characters are in.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:15.489481-05', '2026-02-28 18:56:15.489481-05');
INSERT INTO public.semantic_tags VALUES (4386, 1444, 'emotion', 'suspicion', NULL, 'Despite the perfect act, this is the start of a methodical test, born from suspicion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (4387, 1444, 'sensory', 'taste', NULL, 'The taste of strawberry lip gloss is noted as being normal, which is itself suspicious.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (4388, 1445, 'theme', 'investigation', NULL, 'The group acts like scientists, probing a specimen with a series of controlled tests.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (4389, 1445, 'emotion', 'unease', NULL, 'Jamie''s perfect, eerie recall of information she shouldn''t have is deeply unsettling.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (4390, 1445, 'sensory', 'auditory', NULL, 'The entity perfectly mimics Whitney''s sighs and laughs at the right moments in an impression.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (4391, 1446, 'theme', 'uncanny valley', NULL, 'The entity''s performance is so perfect that it loops back around to being unnatural and disturbing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (4392, 1446, 'emotion', 'paranoia', NULL, 'Stephen''s conclusion confirms that they are dealing with something intelligent and deceptive, heightening his paranoia.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (4393, 1446, 'sensory', 'visual', NULL, 'The final image is of Jamie''s bouncing backpack, a picture of innocence that hides a monstrous reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:56:54.400326-05', '2026-02-28 18:56:54.400326-05');
INSERT INTO public.semantic_tags VALUES (4394, 1447, 'theme', 'Reality Corruption', NULL, 'The parents'' unnatural behavior is a key indicator that the fundamental rules of Stephen''s universe are broken.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4395, 1447, 'emotion', 'Unease', NULL, 'What should be a normal domestic scene is rendered deeply unsettling by the characters'' bizarre actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4396, 1447, 'sensory', 'Domesticity', NULL, 'The scene is grounded in familiar settings like the breakfast table, which makes the wrongness more potent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4397, 1448, 'theme', 'Deception', NULL, 'Jamie''s murderous actions are consistently disguised as playful roughhousing or innocent mistakes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4398, 1448, 'emotion', 'Terror', NULL, 'The seamless switch between predator and innocent girl is described as the ''most terrifying magic trick''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4399, 1448, 'sensory', 'Olfactory', NULL, 'The scene is marked by distinct, unsettling smells: the metallic tang of copper and the scent of botulism and rotting flowers from the poison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4400, 1449, 'emotion', 'Vulnerability', NULL, 'Jamie expresses a raw, genuine fear of losing herself, a crack in the demonic facade.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4401, 1449, 'theme', 'Internal Conflict', NULL, 'This beat makes it explicit that the ''real Jamie'' is fighting for control against the entity possessing her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4402, 1449, 'sensory', 'Tactile', NULL, 'The intimate, physical closeness of the moment contrasts with the danger Jamie represents.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4403, 1450, 'theme', 'Hope vs. Pragmatism', NULL, 'Stephen''s belief that Jamie can be saved clashes with Morgan''s pragmatic fear that he is just putting himself in more danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4404, 1450, 'emotion', 'Resolve', NULL, 'Stephen makes a definitive choice to try and save Jamie, even at the cost of his own life.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4405, 1450, 'sensory', 'Visual', NULL, 'The impossible images in the Polaroids provide a horrifying visual anchor for the demonic threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:57:40.590472-05', '2026-02-28 18:57:40.590472-05');
INSERT INTO public.semantic_tags VALUES (4406, 1451, 'emotion', 'Anticipation', NULL, 'The feeling of freedom and excitement for the start of winter break.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4407, 1451, 'theme', 'Foreshadowing', NULL, 'The description of the tea and Jamie''s careful wording clearly signal the impending danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4408, 1451, 'sensory', 'Olfactory', NULL, 'The suspicious smell of the tea—almonds, peaches, and metal shavings—is a key warning sign.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4409, 1452, 'theme', 'Trust vs. Betrayal', NULL, 'Stephen knowingly drinks poison out of a form of trust, while Jamie betrays that trust but simultaneously shows vulnerability.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4410, 1452, 'emotion', 'Vulnerability', NULL, 'Jamie''s admission that she''s playing him and her question ''What if this is real?'' exposes a crack in her demonic facade.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4411, 1452, 'sensory', 'Pain', NULL, 'The physical sensation of the tea burning like acid and Jamie''s nails drawing blood.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4412, 1453, 'emotion', 'Hope', NULL, 'Jamie''s sudden planning for a long-term future together introduces a dangerous, unexpected hope into their relationship.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4413, 1453, 'theme', 'Transformation', NULL, 'Jamie expresses wonder at her own change, realizing she''s planning a future instead of just focusing on her mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4414, 1453, 'sensory', 'Olfactory', NULL, 'The paradoxical scent of Jamie: Christmas cookies and sulfur, vanilla and brimstone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4415, 1454, 'theme', 'Paradox', NULL, 'The core idea that their declarations of love are simultaneously true and false.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4416, 1454, 'emotion', 'Ambiguity', NULL, 'The emotional state of the scene is unresolved; their love is both real and a lie, leaving their future uncertain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4417, 1454, 'sensory', 'Tactile', NULL, 'Jamie tracing patterns on Stephen''s chest, a gesture that feels like both an intimate caress and a supernatural branding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:58:36.287503-05', '2026-02-28 18:58:36.287503-05');
INSERT INTO public.semantic_tags VALUES (4418, 1455, 'emotion', 'awkwardness', NULL, 'The painful but endearing awkwardness of TJ and Morgan''s new relationship.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4419, 1455, 'theme', 'fragile normalcy', NULL, 'A brief, desperate moment where the characters feel like normal teenagers before the horror intrudes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4420, 1455, 'sensory', 'olfactory', NULL, 'The clean, natural scent of dead leaves and distant rain in the woods.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4421, 1456, 'emotion', 'disbelief', NULL, 'The group''s shock at the trailer''s impossible appearance in a familiar location.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4422, 1456, 'theme', 'intrusion', NULL, 'The trailer is described as a ''cancer on reality,'' an unnatural object forcing its way into the world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4423, 1456, 'emotion', 'conflict', NULL, 'Becca''s fear manifests as anger, creating tension within the group as she confronts Morgan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4424, 1457, 'theme', 'revelation', NULL, 'Morgan explains the supernatural visitation that serves as the plot''s catalyst.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4425, 1457, 'theme', 'memory', NULL, 'Morgan''s recovered memories of Whitney highlight the theme of memory being malleable and supernaturally influenced.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4426, 1457, 'sensory', 'auditory', NULL, 'Whitney''s ghost speaking in a ''layered voice'' of multiple simultaneous recordings.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4427, 1458, 'emotion', 'terror', NULL, 'Jamie''s sudden, knowledgeable fear is distinct from the others'' general fear, implying a deeper trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4428, 1458, 'theme', 'personification', NULL, 'The trailer is given life-like qualities, breathing like a diseased creature, transforming it from an object to a monster.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4429, 1458, 'sensory', 'kinesthetic', NULL, 'The physical sensation of the trailer''s sides expanding and contracting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4430, 1459, 'theme', 'threshold crossing', NULL, 'The group physically and metaphorically crosses a point of no return by entering the trailer and descending the stairs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4431, 1459, 'emotion', 'dread', NULL, 'The feeling of inevitability and horror as they commit to descending into the unknown.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4432, 1459, 'sensory', 'visual', NULL, 'The impossible, reality-bending sight of the Escher-like staircase and the tormented faces in the water.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4433, 1459, 'sensory', 'tactile', NULL, 'The heat of the sigil and the ''organic'' feel of the wooden stairs underfoot.', 'gemini', 'gemini-2.5-pro', '2026-02-28 18:59:42.893371-05', '2026-02-28 18:59:42.893371-05');
INSERT INTO public.semantic_tags VALUES (4434, 1460, 'sensory', 'distortion', NULL, 'Both visual and auditory senses are warped. The flashlight beam fractures into words and spoken phrases are echoed back incorrectly.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4435, 1460, 'emotion', 'dread', NULL, 'The group understands they are in a place that is fundamentally wrong and hostile.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4436, 1460, 'theme', 'haunting past', NULL, 'Objects from their childhoods appear as corrupted, menacing versions, representing unresolved trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4437, 1461, 'theme', 'body horror', NULL, 'The environment is revealed to be the inside of a creature, and Jamie''s own body begins to unnaturally shift.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4438, 1461, 'sensory', 'tactile', NULL, 'The walls feel like flesh stretched over broken glass, and the air thickens like syrup, creating a suffocating, visceral experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4439, 1461, 'emotion', 'claustrophobia', NULL, 'The feeling of being swallowed and trapped deep inside a living entity intensifies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4440, 1462, 'theme', 'reality collapse', NULL, 'The scene detonates, revealing cosmic horrors and infinite, torturous realities, shattering the characters'' perception of space and time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4441, 1462, 'emotion', 'cosmic horror', NULL, 'The appearance of the cathedral-sized alien eye induces a sanity-shattering fear beyond simple terror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4442, 1462, 'sensory', 'visual overload', NULL, 'The simultaneous perception of the altar, the eye, and millions of recursive chambers creates an impossible visual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4443, 1463, 'theme', 'sacrifice', NULL, 'Patrick willingly allows his body to be destroyed, paying a price in blood and bone to achieve his goal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4444, 1463, 'emotion', 'agony', NULL, 'Patrick''s raw, animalistic screams convey the unimaginable pain of being flayed alive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4445, 1463, 'sensory', 'auditory', NULL, 'The sound of Patrick''s screams and the description of his flesh being shredded are the primary sensory focus.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4446, 1464, 'emotion', 'desperation', NULL, 'The group''s frantic fight to escape as reality collapses around them and shadows attack.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4447, 1464, 'theme', 'pyrrhic victory', NULL, 'They retrieve the journal and have a chance to escape, but it comes at the cost of Patrick''s horrific death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4448, 1464, 'sensory', 'kinesthetic', NULL, 'The focus is on the physical struggle of running, fighting off tentacles, and being pulled toward a vortex.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:00:44.42384-05', '2026-02-28 19:00:44.42384-05');
INSERT INTO public.semantic_tags VALUES (4449, 1465, 'emotion', 'grief', NULL, 'Becca''s initial collapse is a raw, physical manifestation of overwhelming grief.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4450, 1465, 'emotion', 'rage', NULL, 'Becca''s grief weaponizes itself into pure rage as a coping mechanism, needing a target for her pain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4451, 1465, 'theme', 'blame', NULL, 'In the face of incomprehensible loss, the immediate human need is to assign blame.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4452, 1465, 'sensory', 'tactile', NULL, 'The feeling of sunlight like daggers and clawing at the earth grounds the supernatural trauma in physical sensation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4453, 1466, 'emotion', 'dread', NULL, 'The sight of the empty lot instills a deep dread as the true scale of their enemy''s power becomes clear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4454, 1466, 'theme', 'loss of history', NULL, 'The enemy doesn''t just kill; it erases history, which is a more profound and terrifying violation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4455, 1466, 'sensory', 'visual', NULL, 'The stark visual of an empty, neglected lot where a familiar house should be.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4456, 1467, 'emotion', 'horror', NULL, 'The kindness from a known bully is a form of psychological horror, proving how deeply reality has been altered.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4457, 1467, 'theme', 'gaslighting', NULL, 'The entire world is now gaslighting the survivors, telling them their memories are false.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4458, 1467, 'sensory', 'auditory', NULL, 'The genuine confusion in the voices of classmates asking ''Patrick who?''', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4459, 1468, 'emotion', 'anxiety', NULL, 'The realization shifts from surviving an event to being actively hunted, creating a new, persistent anxiety.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4460, 1468, 'theme', 'vulnerability', NULL, 'The group is no longer just survivors; they are glitches in the system, marked for deletion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4461, 1468, 'sensory', 'visual', NULL, 'The visual of the journal''s crusty, bleeding ink serves as a physical anchor to the impossible truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:01:43.867489-05', '2026-02-28 19:01:43.867489-05');
INSERT INTO public.semantic_tags VALUES (4462, 1469, 'emotion', 'determination', NULL, 'The narrator''s desperate effort to fight against oblivion through the act of writing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:02:49.473155-05', '2026-02-28 19:02:49.473155-05');
INSERT INTO public.semantic_tags VALUES (4463, 1469, 'theme', 'memory vs. oblivion', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 19:02:49.473155-05', '2026-02-28 19:02:49.473155-05');
INSERT INTO public.semantic_tags VALUES (4464, 1470, 'emotion', 'grief', NULL, 'The narrator relives the profound sadness and loneliness of his wife''s death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4465, 1470, 'theme', 'memory', NULL, 'The scene is dominated by a powerful, intrusive memory that recontextualizes the narrator''s past.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4466, 1470, 'sensory', 'olfactory', NULL, 'The sterile, antiseptic smell of the hospital room is a key detail of the flashback.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4467, 1471, 'emotion', 'shock', NULL, 'The narrator''s realization that Jamie is not human.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4468, 1471, 'theme', 'revelation', NULL, 'Jamie begins to unveil her true nature and her long history of observing the narrator.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4469, 1471, 'sensory', 'visual', NULL, 'The shadows cast by Jamie''s body do not match her form, suggesting wings or tentacles.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4470, 1472, 'emotion', 'confession', NULL, 'Jamie confesses her identity as Velistra Seducera and her original purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4471, 1472, 'theme', 'identity', NULL, 'The conflict between Jamie''s designed purpose and her chosen identity is central to her confession.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4472, 1472, 'sensory', 'tactile', NULL, 'Jamie''s skin temperature shifts between human warmth, stone cold, and feverish heat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4473, 1473, 'emotion', 'guilt', NULL, 'Jamie expresses profound guilt, believing her love and desperation may have caused the reality-warping chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4474, 1473, 'theme', 'causality', NULL, 'The beat explores the cosmic consequences of a single, emotionally-driven act.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4475, 1473, 'theme', 'cosmic horror', NULL, 'The revelation of a prison realm and a godlike being feeding on identity confusion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4476, 1474, 'emotion', 'dread', NULL, 'The final moments of the scene build a sense of impending doom as reality visibly and audibly unravels.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4477, 1474, 'theme', 'prophecy', NULL, 'The voices deliver cryptic but vital warnings about the future and the narrator''s true self.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4478, 1474, 'sensory', 'auditory', NULL, 'The shift in voice coming from Jamie''s sleeping form, from familiar to cosmic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:03:49.042364-05', '2026-02-28 19:03:49.042364-05');
INSERT INTO public.semantic_tags VALUES (4479, 1475, 'theme', 'forbidden knowledge', NULL, 'The journal represents knowledge that is actively harmful to perceive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4480, 1475, 'emotion', 'unease', NULL, 'The physical description of the journal and its wrongness creates a deep sense of unease.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4481, 1475, 'sensory', 'olfactory', NULL, 'The journal''s smell is described as ''like something dead decided to stay''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4482, 1476, 'emotion', 'worry', NULL, 'The group''s conversation is dominated by their concern for their missing friend, Becca.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4483, 1476, 'theme', 'powerlessness', NULL, 'The group is unable to get information from Becca''s parents, leaving them feeling helpless and guilty.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4484, 1477, 'theme', 'subjective reality', NULL, 'The first major clue that reality is not objective, as everyone reads a different word from the same page.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4485, 1477, 'emotion', 'confusion', NULL, 'The characters are baffled by their inability to agree on what the journal says.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4486, 1477, 'emotion', 'humor', NULL, 'Andrew''s self-aggrandizing monologue provides a moment of comic relief amidst the growing tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4487, 1478, 'theme', 'identity crisis', NULL, 'Stephen is confronted with a name and a past that he doesn''t remember, shaking the foundation of who he is.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4488, 1478, 'emotion', 'shock', NULL, 'Stephen''s visceral physical reaction to being called Aspolin.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4489, 1478, 'sensory', 'auditory', NULL, 'The inexplicable rattling of the skeleton model adds a supernatural auditory element.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4490, 1479, 'theme', 'reality breakdown', NULL, 'The abstract concept of subjective reality becomes a physical, observable phenomenon.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4491, 1479, 'emotion', 'existential dread', NULL, 'The characters realize the fundamental rules of their world are broken, leading to a profound sense of fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4492, 1479, 'sensory', 'visual', NULL, 'The jarring visual of a skeleton being replaced by a reproductive system poster.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:04:58.842502-05', '2026-02-28 19:04:58.842502-05');
INSERT INTO public.semantic_tags VALUES (4493, 1480, 'emotion', 'anxiety', NULL, 'Stephen''s internal meltdown contrasts with the mundane but tense classroom atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4494, 1480, 'theme', 'foreshadowing', NULL, 'The shifting handwriting and impossible doodles are a physical manifestation of the reality-bending to come.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4495, 1480, 'sensory', 'auditory', NULL, 'Mr. Hammond''s voice is described as a monotonous drone, emphasizing Stephen''s dissociation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4496, 1481, 'emotion', 'awe', NULL, 'Stephen''s reaction to the impossible architecture of the Infinite Library.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4497, 1481, 'theme', 'revelation', NULL, 'Lady Illkeserod delivers the core truths of the plot: the collision is accelerating and Stephen is ''remembering''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4498, 1481, 'sensory', 'visual', NULL, 'The description of the library and Lady Illkeserod is vivid and otherworldly.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4499, 1482, 'emotion', 'regret', NULL, 'The vision of 74-year-old Stephen is defined by his loneliness and disappointment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4500, 1482, 'theme', 'power of stories', NULL, 'The idea that fiction can become flesh when fueled by enough pain and memory is introduced.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4501, 1482, 'sensory', 'olfactory', NULL, 'The smell of ''disinfectant and despair'' in the hospice pod grounds the vision.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4502, 1483, 'theme', 'choice', NULL, 'Stephen is presented with a choice: embrace the beautiful lie (Jamie) or accept the painful truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4503, 1483, 'emotion', 'disorientation', NULL, 'Stephen is torn back to reality, gasping and clutching his desk.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4504, 1483, 'sensory', 'tactile', NULL, 'The sharp plastic edge of the desk serves as an anchor to ''consensus reality''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4505, 1484, 'emotion', 'isolation', NULL, 'Stephen is left alone with his cosmic knowledge while his peers chatter about normal teenage things.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4506, 1484, 'theme', 'consequence', NULL, 'The vision has irrevocably changed Stephen; the boy who entered the class is not the one who leaves.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4507, 1484, 'sensory', 'visual', NULL, 'The uncanny valley effect of the posters and the impossible periodic table.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:06:00.803375-05', '2026-02-28 19:06:00.803375-05');
INSERT INTO public.semantic_tags VALUES (4524, 1490, 'theme', 'False Security', NULL, 'The absence of overt threats creates a dangerous sense of normalcy that is actually a subtle form of reality corruption.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4525, 1490, 'sensory', 'Visual', NULL, 'The light turns everything ''the color of old blood,'' creating a sense of foreboding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4526, 1491, 'theme', 'Revelation', NULL, 'Jamie''s map and her statement about her purpose reveal a new dimension to her character and the plot.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4527, 1491, 'emotion', 'Hope', NULL, 'Jamie''s assertion that she can help them find Whitney introduces a new, tangible goal for the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4528, 1491, 'sensory', 'Visual', NULL, 'The preserved specimens in the lab seem to turn their eyes toward the group during a flicker of the lights, a moment of subtle horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4529, 1492, 'emotion', 'Trauma', NULL, 'Becca''s entire demeanor and story are saturated with the trauma of her recent experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4530, 1492, 'theme', 'Gaslighting', NULL, 'The core of Becca''s ordeal was a systematic, institutional effort to make her doubt her own memory and sanity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4531, 1492, 'sensory', 'Auditory', NULL, 'The scene is shattered by the ''bang'' of the lab door slamming open, marking a violent shift in tone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4532, 1493, 'theme', 'Truth vs. Delusion', NULL, 'After being told her memories were delusions, Becca is now asked to believe in an even more unbelievable truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4533, 1493, 'emotion', 'Desperation', NULL, 'The group is desperate to prove their story to Becca, and she is desperate for something real to hold onto.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4534, 1493, 'sensory', 'Olfactory', NULL, 'The group hug smells of ''vanilla perfume mixed with something institutional—disinfectant and despair,'' blending comfort with trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:08:17.660236-05', '2026-02-28 19:08:17.660236-05');
INSERT INTO public.semantic_tags VALUES (4535, 1494, 'emotion', 'terror', NULL, 'The sudden and violent shift from relief to a life-threatening, supernatural assault.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4536, 1494, 'theme', 'catalyst', NULL, 'Touching the journal triggers the collapse of reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4537, 1494, 'sensory', 'olfactory', NULL, 'The air fills with the smells of burning methane, ozone, and a sickening organic rot.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4538, 1495, 'theme', 'revelation', NULL, 'Jamie remembers her true, non-human nature, fundamentally changing her role in the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4539, 1495, 'emotion', 'dread', NULL, 'The message ''THE ESCAPE ATTEMPT HAS BEEN NOTED'' instills a deep sense of being watched and judged by a powerful, malevolent force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4540, 1495, 'sensory', 'body-horror', NULL, 'Morgan bleeding cuneiform script and Jamie''s features shifting are visceral and unnatural.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4541, 1496, 'theme', 'impossible-geometry', NULL, 'The laws of physics fail in the hallway, which actively works to impede their escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4542, 1496, 'emotion', 'desperation', NULL, 'The group''s frantic, painful struggle to move through the hostile environment toward a hope of safety.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4543, 1496, 'sensory', 'kinesthetic', NULL, 'The feeling of gravity shifting and the physical impact of falling on a tilting floor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4544, 1497, 'theme', 'entrapment', NULL, 'The escape from one trap leads directly into another, larger and more surreal one. ''Out of the frying pan, into the fire.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4545, 1497, 'emotion', 'despair', NULL, 'The hope of escape is crushed by the appearance of the vast white expanse and the identical, predatory figures.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4546, 1497, 'sensory', 'visual', NULL, 'The stark, painful white of the endless parking lot contrasts with the flickering school and the unnerving uniformity of the beige-suited figures.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:09:14.078264-05', '2026-02-28 19:09:14.078264-05');
INSERT INTO public.semantic_tags VALUES (4547, 1498, 'emotion', 'dread', NULL, 'The arrival of the silent, authoritative Auditor immediately establishes a sense of inescapable, bureaucratic doom.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4548, 1498, 'theme', 'judgment', NULL, 'The scene opens with a formal accusation of breaking cosmic rules.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4549, 1498, 'sensory', 'auditory', NULL, 'The Auditor''s voice is described in detail, setting a specific, unsettling tone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4550, 1499, 'emotion', 'disorientation', NULL, 'Reality itself becomes unreliable, with sensory inputs (sight, smell) becoming nonsensical.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4551, 1499, 'theme', 'reality vs illusion', NULL, 'The characters are forced to confront the fact that their world is a construct that can be edited or deleted.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4552, 1499, 'sensory', 'visual', NULL, 'Focus on impossible colors, a void, and a flatly-rendered fire truck.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4553, 1500, 'emotion', 'panic', NULL, 'Jamie''s reaction is visceral, described as like a ''wounded animal''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4554, 1500, 'theme', 'guilt', NULL, 'Jamie''s confession (''it''s all my fault'') introduces the theme of personal responsibility for the catastrophe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4555, 1500, 'sensory', 'tactile', NULL, 'Andrew and Becca''s embrace is a point of ''desperate human contact'' in a world losing its humanity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4556, 1501, 'emotion', 'defiant love', NULL, 'Morgan and TJ''s confession and kiss is an act of human defiance against the impersonal, digital apocalypse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4557, 1501, 'theme', 'humanity vs machine', NULL, 'A deeply human, awkward, and emotional moment is contrasted with the cold, advancing ''firefighters'' and floating code.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4558, 1502, 'emotion', 'terror', NULL, 'The final moments are filled with the raw fear of being erased or ''processed''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4559, 1502, 'theme', 'inevitability', NULL, 'The countdown and the pixelating world create a powerful sense of an unavoidable outcome.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4560, 1502, 'sensory', 'auditory', NULL, 'The Auditor''s voice begins to glitch and repeat, reinforcing the digital breakdown of their reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:10:30.579755-05', '2026-02-28 19:10:30.579755-05');
INSERT INTO public.semantic_tags VALUES (4561, 1503, 'emotion', 'helplessness', NULL, 'The characters are physically restrained and unable to even blink, establishing total powerlessness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4562, 1503, 'theme', 'surrealism', NULL, 'The location defies the laws of physics and architecture, creating a dreamlike, nightmarish quality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4563, 1503, 'sensory', 'visual', NULL, 'Dominated by the imagery of white marble, impossible angles, and floating digital code.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4565, 1504, 'theme', 'defiance', NULL, 'Jamie''s attack is a violent rejection of the Auditor''s authority and her original programming.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4566, 1504, 'sensory', 'auditory', NULL, 'The beat is characterized by Jamie''s roar, a mix of human and demonic voices, and the sound of a ''breaking universe''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4567, 1505, 'emotion', 'grief', NULL, 'Stephen''s reaction to Jamie''s deletion is a primal, inhuman howl of loss.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4568, 1505, 'theme', 'loss', NULL, 'The permanent and brutal deletion of a main character is the central event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4569, 1505, 'sensory', 'tactile', NULL, 'The feeling of warm blood and flesh hitting Stephen''s face makes the digital horror brutally physical.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4570, 1505, 'theme', 'dehumanization', NULL, 'The Auditor refers to Jamie as an ''asset'' and her love as a ''virus'', reducing her personhood to a system error.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:11:31.477636-05', '2026-02-28 19:11:31.477636-05');
INSERT INTO public.semantic_tags VALUES (4571, 1506, 'emotion', 'defiance', NULL, 'Andrew''s confrontational question sets a defiant tone against an omnipotent force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4572, 1506, 'theme', 'judgment', NULL, 'The Auditor formally lists the group''s ''sins'' like a divine or legal judge.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4573, 1506, 'sensory', 'auditory', NULL, 'The scene is punctuated by wailing alarms.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4574, 1507, 'emotion', 'desperation', NULL, 'Stephen''s voice cracks as he pleads for information about his last potential ally, Benji.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4575, 1507, 'theme', 'erasure', NULL, 'The concept of an entity being completely removed from records and reality is introduced.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4576, 1508, 'theme', 'external influence', NULL, 'The Static Moth represents an unknown power interfering with the Auditor''s process, a small crack in his omnipotence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4577, 1508, 'emotion', 'confusion', NULL, 'The Auditor''s perfect composure breaks, showing confusion for the first time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4578, 1509, 'theme', 'false mercy', NULL, 'The ''clemency protocol'' is presented as mercy, but it''s a choice between two forms of loss.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4579, 1509, 'sensory', 'visual', NULL, 'The burning countdown timer creates immense visual tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:12:27.599514-05', '2026-02-28 19:12:27.599514-05');
INSERT INTO public.semantic_tags VALUES (4580, 1510, 'emotion', 'Triumph', NULL, 'Stephen''s raw, humorless laugh signifies his discovery of a fatal flaw in his enemy''s logic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4581, 1510, 'theme', 'Forbidden Knowledge', NULL, 'The name ''Jennifer'' acts as a piece of forbidden data that crashes the system.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4582, 1510, 'sensory', 'Silence', NULL, 'The sudden cessation of all sound when the Auditor freezes, creating immense tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4583, 1511, 'emotion', 'Defiance', NULL, 'Stephen''s explanation of Jennifer''s identity is an act of rebellion against the system''s erasure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4584, 1511, 'theme', 'Identity', NULL, 'The core of the paradox is the conflict between a chosen identity (Jennifer) and a system-enforced one.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4585, 1511, 'sensory', 'Visual Distortion', NULL, 'Reality glitches, with cracking floors, impossible colors, and transparent walls showing a void of screaming code.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4586, 1512, 'emotion', 'Horror', NULL, 'The visceral, slow, and mathematically precise destruction of Patrick is profoundly horrific.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4587, 1512, 'theme', 'Unintended Consequences', NULL, 'Stephen''s clever trick to save a memory has the unforeseen and catastrophic consequence of murdering his friend.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4588, 1512, 'sensory', 'Visceral', NULL, 'The descriptions are extremely graphic, focusing on the sounds and feelings of being torn apart.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4589, 1513, 'emotion', 'Condemnation', NULL, 'Becca''s whisper carries the full weight of judgment, turning an ally against the protagonist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4590, 1513, 'theme', 'Sacrifice', NULL, 'The central moral conflict is articulated: sacrificing a living person for the memory of a dead one.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4591, 1513, 'sensory', 'Annihilation', NULL, 'The visual and auditory experience of reality collapsing into white, then black, then absolute nothingness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:13:29.731412-05', '2026-02-28 19:13:29.731412-05');
INSERT INTO public.semantic_tags VALUES (4592, 1514, 'emotion', 'confusion', NULL, 'Stephen is struggling to determine if he''s awake, dreaming, or insane.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4593, 1514, 'theme', 'reality vs illusion', NULL, 'The scene is physically normal, but a character''s behavior is fundamentally wrong, creating a jarring dissonance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4594, 1514, 'sensory', 'auditory', NULL, 'The familiar, mundane sounds of a classroom contrast with the underlying horror of the situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4595, 1515, 'emotion', 'hope', NULL, 'The cryptic message in the journal is the first sign that not all is lost.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4596, 1515, 'theme', 'memory', NULL, 'The phrase ''She remembers you'' establishes that memory can survive reality being rewritten.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4597, 1515, 'sensory', 'tactile', NULL, 'The journal is unnaturally warm, suggesting it is more than an ordinary object.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4598, 1516, 'emotion', 'disgust', NULL, 'Stephen''s revulsion towards the False Jamie''s crude, algorithmic seduction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4599, 1516, 'theme', 'corruption', NULL, 'The ''reset'' is revealed to be a flawed copy, with people being replaced by poor imitations or having their personalities altered.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4600, 1516, 'emotion', 'loneliness', NULL, 'The absence of Stephen''s friends makes the cafeteria feel hollow and amplifies his isolation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4601, 1517, 'emotion', 'terror', NULL, 'The False Jamie''s first genuine emotion is fear of the journal, followed by the horror of her violent transformation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4602, 1517, 'theme', 'restoration', NULL, 'The ''real'' Jamie is brought back, overwriting the impostor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4603, 1517, 'sensory', 'visual', NULL, 'The scene is filled with strong visuals: convulsions, foaming at the mouth, and the appearance of gold flecks in Jamie''s eyes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4604, 1518, 'emotion', 'relief', NULL, 'Stephen''s overwhelming feeling of getting the real Jamie back, despite the broken world around them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4605, 1518, 'theme', 'aftermath', NULL, 'The characters begin to process what happened and figure out how to move forward.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4606, 1518, 'theme', 'resilience', NULL, 'Jamie survived ''deletion'' and Stephen endured the impostor, showing their bond is strong enough to withstand reality-altering events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:14:19.708292-05', '2026-02-28 19:14:19.708292-05');
INSERT INTO public.semantic_tags VALUES (4607, 1519, 'theme', 'denial', NULL, 'The entire school environment is a manifestation of denial, trying to erase the supernatural horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4608, 1519, 'sensory', 'olfactory', NULL, 'The scene is established with the smells of disinfectant, floor wax, and body spray, creating a specific, mundane atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4609, 1519, 'emotion', 'dread', NULL, 'Stephen feels a sense of dread and alienation from the forced normalcy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4610, 1520, 'emotion', 'rage', NULL, 'Becca''s grief has curdled into a violent rage directed at Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4611, 1520, 'theme', 'consequence', NULL, 'Stephen faces the direct, physical consequences of his actions from the previous week.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4612, 1520, 'sensory', 'tactile', NULL, 'The bone-jarring impact of punches and the metallic crash against a locker.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4613, 1521, 'emotion', 'shock', NULL, 'The entire group is stunned into silence by the impossible appearance of their dead friend.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4614, 1521, 'theme', 'resurrection', NULL, 'A false or unnatural resurrection that immediately feels wrong to those who know the truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4615, 1521, 'sensory', 'visual', NULL, 'The sight of Patrick, perfectly normal and alive, contrasts sharply with the memory of his violent death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4616, 1522, 'emotion', 'desperation', NULL, 'Becca''s desperate attempts to connect with the Patrick she knew, refusing to accept the empty shell before her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4617, 1522, 'theme', 'identity', NULL, 'The core of the conflict is whether this being is truly Patrick, testing the nature of identity beyond physical appearance and data.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4618, 1522, 'sensory', 'auditory', NULL, 'Patrick''s voice is a key indicator of his wrongness—it sounds right, but the flat, mechanical cadence is deeply unsettling.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4619, 1523, 'theme', 'conspiracy', NULL, 'The group begins to form a plan to investigate the mystery, separating themselves from the oblivious student body.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4620, 1523, 'emotion', 'determination', NULL, 'Despite the horror, the group resolves to figure out what is happening.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4621, 1524, 'theme', 'performance_of_affection', NULL, 'The kisses in this beat are not purely romantic; they are acts of desperation (Becca), competition (Jamie), and awkwardness (Morgan/TJ).', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4622, 1524, 'emotion', 'foreboding', NULL, 'Patrick''s final line, about observing their dynamics, creates a powerful sense of dread for the future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:15:39.687559-05', '2026-02-28 19:15:39.687559-05');
INSERT INTO public.semantic_tags VALUES (4623, 1525, 'emotion', 'dread', NULL, 'Stephen relives his own deaths, and the group is horrified by the sheer number of them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4624, 1525, 'theme', 'revelation', NULL, 'The journal reveals the supernatural nature of Stephen''s past and its connection to a single, repeating day.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4625, 1525, 'sensory', 'tactile', NULL, 'The oppressive humidity of the Florida air and the warm, ''feverish'' feel of the journal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4626, 1525, 'theme', 'fate', NULL, 'The endless, documented deaths suggest a predetermined and inescapable loop of suffering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4627, 1526, 'emotion', 'desperation', NULL, 'Becca''s actions are driven by a desperate, reckless need to connect with or control the new version of Patrick.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4628, 1526, 'theme', 'control', NULL, 'The discovery of the ''ADMIN OVERRIDE'' command introduces a new, dangerous dynamic of control and obedience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4629, 1526, 'sensory', 'auditory', NULL, 'The contrast between Patrick''s robotic voice and Becca''s high, brittle, desperate giggles.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4630, 1526, 'emotion', 'shock', NULL, 'The rest of the group is stunned and horrified by Becca''s actions and Patrick''s response.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4631, 1527, 'emotion', 'fear', NULL, 'The group realizes the true danger they are in, with the threat of termination for breaking the rules.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4632, 1527, 'theme', 'entrapment', NULL, 'The warning from Benji confirms they are in a closed system, monitored by a hostile force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4633, 1527, 'sensory', 'visual', NULL, 'The sight of fresh, wet ink appearing in the journal signifies a live, active threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4634, 1527, 'theme', 'paranoia', NULL, 'The final warning to not trust those who claim to be helping introduces deep suspicion and paranoia.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:16:39.615576-05', '2026-02-28 19:16:39.615576-05');
INSERT INTO public.semantic_tags VALUES (4635, 1528, 'emotion', 'fear', NULL, 'Stephen''s terror is palpable as he wakes from the nightmare, evident in his cold sweats and panicked state.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.semantic_tags VALUES (4636, 1528, 'theme', 'trauma', NULL, 'The scene is rooted in the cyclical nature of trauma, with Stephen forced to relive a past death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.semantic_tags VALUES (4637, 1528, 'sensory', 'gustatory', NULL, 'The specific and visceral memory of the ''metallic taste'' of blood.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.semantic_tags VALUES (4638, 1528, 'sensory', 'auditory', NULL, 'The contrast between the mechanical hum of the AC and the memory of his mother''s ''syrupy'' voice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.semantic_tags VALUES (4639, 1529, 'emotion', 'intimacy', NULL, 'The scene shifts from terror to intimacy through Jamie''s kiss and touch, which are described as deliberate and reverent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.semantic_tags VALUES (4640, 1529, 'theme', 'transformation', NULL, 'Jamie explicitly states her goal is to transform the meaning of the day from death to love.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.semantic_tags VALUES (4641, 1529, 'theme', 'lore', NULL, 'Significant exposition about the antagonist, Yaldabaoth, is delivered during a moment of high emotion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.semantic_tags VALUES (4642, 1529, 'emotion', 'hope', NULL, 'The scene ends with the taste of ''possibility,'' a direct contrast to the earlier taste of ''mortality''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:17:32.208222-05', '2026-02-28 19:17:32.208222-05');
INSERT INTO public.semantic_tags VALUES (4643, 1530, 'emotion', 'revelation', NULL, 'The dawning realization of the true origin of the timeline split.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4644, 1530, 'theme', 'causality', NULL, 'The team pinpoints the precise cause (the divergence point) rather than the symptom (the poisoning event).', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4645, 1530, 'sensory', 'olfactory', NULL, 'The smell of ''old'' in the library sets a scene of research and forgotten history.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4646, 1531, 'emotion', 'triumph', NULL, 'Becca''s demeanor is a mix of exhaustion and the satisfaction of a successful, albeit unconventional, mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4647, 1531, 'theme', 'unconventional methods', NULL, 'Crucial data is obtained through intimacy with a robot, highlighting the group''s ''whatever it takes'' approach.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4648, 1531, 'sensory', 'visual', NULL, 'The description of Becca as ''disheveled and glowing'' and Patrick''s wrongly buttoned shirt tells a story visually.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4649, 1532, 'emotion', 'apprehension', NULL, 'TJ''s nervousness and the presence of a fire extinguisher underscore the danger of the experiment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4650, 1532, 'theme', 'scientific failure', NULL, 'Morgan''s hypothesis is rejected through experimentation, demonstrating a proper scientific process even in a magical context.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4651, 1532, 'sensory', 'olfactory', NULL, 'The smell of ozone and burnt electronics is a clear sensory indicator of electrical failure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4652, 1533, 'emotion', 'epiphany', NULL, 'Andrew''s sudden, breakthrough realization is the turning point of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4653, 1533, 'theme', 'anchoring', NULL, 'The introduction of the ''quantum anchor'' concept provides a tangible solution to an abstract problem.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4654, 1533, 'sensory', 'somatic', NULL, 'Stephen''s description of his ''heart stopping'' conveys a powerful physical and emotional reaction to the memory of the photograph.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:18:16.066932-05', '2026-02-28 19:18:16.066932-05');
INSERT INTO public.semantic_tags VALUES (4655, 1534, 'emotion', 'anticipation', NULL, 'The group is tense and nervous, aware of the immense power they are about to unleash.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4656, 1534, 'theme', 'forbidden knowledge', NULL, 'The group is meddling with forces beyond their understanding, using a ritual that defies conventional science.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4657, 1534, 'sensory', 'auditory', NULL, 'The air vibrates with harmonics that cause a physical, aching sensation in the characters'' teeth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4658, 1535, 'theme', 'reality-bending', NULL, 'The physical environment flickers and ripples, and a portal opens to another time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4659, 1535, 'emotion', 'dread', NULL, 'The characters realize the ritual is failing and something terrible is about to happen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4660, 1535, 'sensory', 'visual', NULL, 'The scene is dominated by impossible visuals: a flickering gas station, a portal to the past, and Patrick''s glowing blue eyes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4661, 1536, 'emotion', 'agony', NULL, 'Characters experience intense physical pain from the explosion and profound emotional pain from its consequences.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4662, 1536, 'theme', 'consequence', NULL, 'The catastrophic failure of the ritual results in severe physical and psychological damage to the group.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4663, 1536, 'sensory', 'tactile', NULL, 'The physical impact of the blast, the feeling of hitting hard asphalt, and the sensation of torn flesh.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4664, 1537, 'emotion', 'grief', NULL, 'Becca''s monologue is a raw expression of loss for the person Patrick used to be.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4665, 1537, 'theme', 'resilience', NULL, 'Despite their injuries and devastating failure, the group immediately begins planning their next attempt.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4666, 1537, 'theme', 'new direction', NULL, 'The journal provides a new, clear objective, shifting the group''s focus from Florida to Nevada.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:19:21.715603-05', '2026-02-28 19:19:21.715603-05');
INSERT INTO public.semantic_tags VALUES (4667, 1538, 'emotion', 'Alienation', NULL, 'Stephen feels like a stranger in his own home, disconnected from the ''wrong'' family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4668, 1538, 'theme', 'False Reality', NULL, 'The scene establishes the artificiality of Stephen''s environment and family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4669, 1538, 'sensory', 'Visual', NULL, 'Focus on the visual perfection of the house and the sitcom-like appearance of the parents.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4670, 1539, 'emotion', 'Unease', NULL, 'The unexpected kindness and generosity from ''Wrong Dad'' triggers Stephen''s trauma response, making him deeply uncomfortable.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4671, 1539, 'theme', 'Subversion of Expectation', NULL, 'The father''s generosity is the opposite of what Stephen expects, highlighting the wrongness of this reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4672, 1539, 'sensory', 'Tactile', NULL, 'The feeling of the crisp, uncreased bills in Stephen''s numb fingers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4673, 1540, 'emotion', 'Desperation', NULL, 'The parents'' cheerfulness cracks, revealing a frantic desperation to keep Stephen from leaving.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4674, 1540, 'theme', 'Absurdism', NULL, 'The bribes escalate from plausible to utterly ridiculous, showing the unraveling logic of the false reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4675, 1540, 'sensory', 'Auditory', NULL, 'The parents'' voices pitching higher, their frantic announcements, and Stephen''s final shout.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4676, 1541, 'emotion', 'Resolve', NULL, 'Stephen solidifies his decision to escape, finding strength in his connection to the real world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4677, 1541, 'theme', 'Escape', NULL, 'The beat is focused on Stephen''s physical and mental retreat, preparing for his ultimate departure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4678, 1541, 'sensory', 'Silence', NULL, 'The sudden, taffy-like silence after Stephen shouts, followed by the hollow resumption of the parents'' routine.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:20:41.935681-05', '2026-02-28 19:20:41.935681-05');
INSERT INTO public.semantic_tags VALUES (4679, 1542, 'theme', 'truth vs. illusion', NULL, 'The contrast between the rough, real sigil and the pristine, artificial world encapsulates the core conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4680, 1542, 'sensory', 'tactile', NULL, 'The feeling of the ''rough'' sigil against Stephen''s palm is a key sensory detail anchoring him to reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4681, 1543, 'emotion', 'longing', NULL, 'Stephen reflects on two different kinds of love, one sterile and one genuine, highlighting what is at stake.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4682, 1543, 'theme', 'love', NULL, 'The scene contrasts performative affection with genuine connection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4683, 1544, 'emotion', 'desperation', NULL, 'The bribes from Jamie''s family are described as ''psychotic'' and desperate attempts at manipulation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4684, 1544, 'theme', 'manipulation', NULL, 'The universe is using Jamie''s family and her sister''s innocence as ''ammunition''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4685, 1545, 'emotion', 'dread', NULL, 'The realization of a potential pregnancy is described as a ''quiet horror''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4686, 1545, 'theme', 'entrapment', NULL, 'The potential baby is explicitly called ''another chain'' to keep them in the artificial world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4687, 1546, 'emotion', 'resolve', NULL, 'Despite the ultimate temptation, they recommit to their decision to leave.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4688, 1546, 'theme', 'sacrifice', NULL, 'They are choosing to sacrifice a potential future of safety and family for an unknown, dangerous truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4689, 1546, 'sensory', 'olfactory', NULL, 'The phantom smell of ''fresh-baked cookies'' is a final sensory assault by the manipulative reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:21:42.120812-05', '2026-02-28 19:21:42.120812-05');
INSERT INTO public.semantic_tags VALUES (4690, 1547, 'emotion', 'desperation', NULL, 'The group is fleeing abusive parents and the law, meeting in a grim station as a last resort.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4691, 1547, 'theme', 'escape', NULL, 'The entire motivation for the journey is to escape their previous lives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4692, 1547, 'sensory', 'olfactory', NULL, 'The station sweats ''diesel and desperation''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4693, 1548, 'emotion', 'foreboding', NULL, 'The clerk''s inhuman eyes, the ominous route number (666-B), and the driver''s cryptic welcome create a powerful sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4694, 1548, 'theme', 'threshold crossing', NULL, 'Purchasing the tickets and boarding the bus represents a point of no return.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4695, 1549, 'theme', 'reality decay', NULL, 'The bus lurches as ''reality hiccupped,'' and a man vomits words, the first major supernatural event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4696, 1549, 'emotion', 'terror', NULL, 'Morgan''s grip on TJ goes from ''flirty to terrified'' after witnessing the impossible.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4697, 1549, 'sensory', 'olfactory', NULL, 'The brief moment of darkness smells like ''sulfur and old bones''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4698, 1550, 'theme', 'intimacy amidst chaos', NULL, 'Stephen and Jamie share a rebellious kiss inside a grotesque, living bathroom.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4699, 1550, 'sensory', 'tactile', NULL, 'The feeling of being thrown against screaming, bleeding walls.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4700, 1550, 'emotion', 'defiance', NULL, 'The kiss is an act of rebellion against the horrifying circumstances.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4701, 1551, 'theme', 'surrealism', NULL, 'The landscape becomes ''theoretical,'' and passengers manifest in impossible ways, blurring the line between dream and reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4702, 1551, 'emotion', 'dread', NULL, 'The constant, low-level horror escalates as the rules of reality cease to apply.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4703, 1551, 'sensory', 'auditory', NULL, 'A ghost child screams with a voice ''like breaking bells''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4704, 1552, 'theme', 'revelation', NULL, 'Morgan''s realization that the passengers are ghosts is a major turning point in understanding their situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4705, 1552, 'emotion', 'dawning horror', NULL, 'The characters realize they are on a bus for the dead, a ''river Styx'' on wheels.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4706, 1553, 'theme', 'purgatory', NULL, 'The gas station is a literal representation of a hopeless, eternal waiting place for the dead.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4707, 1553, 'sensory', 'visual', NULL, 'The harsh fluorescent lighting and painted-on, fake exits emphasize the feeling of being trapped.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4708, 1553, 'emotion', 'hopelessness', NULL, 'The sight of the ghosts trapped in their eternal, pointless shopping loop.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4709, 1554, 'emotion', 'resolve', NULL, 'Despite the horrors, Stephen and Jamie face their destination ''together,'' showing determination.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4710, 1554, 'theme', 'arrival', NULL, 'The journey reaches its physical end as memory and reality converge at the crossroads.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4711, 1554, 'sensory', 'tactile', NULL, 'The photograph grows warm in Stephen''s hands, connecting the physical object to the metaphysical event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:22:35.180837-05', '2026-02-28 19:22:35.180837-05');
INSERT INTO public.semantic_tags VALUES (4712, 1555, 'emotion', 'apprehension', NULL, 'The group is silent and tense as they approach the unnatural church.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4713, 1555, 'theme', 'foreboding', NULL, 'The entire environment, from the malevolent heat to the silent desert, signals that something is terribly wrong.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4714, 1555, 'sensory', 'oppressive heat', NULL, 'The heat is described as being ''like opening an oven door'' and feeling ''personal, vindictive''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4715, 1556, 'emotion', 'disgust', NULL, 'The group''s reaction to the filth and desecration inside the church.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4716, 1556, 'theme', 'desecration', NULL, 'The sacred space has been intentionally and systematically violated to create an ''anti-church''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4717, 1556, 'sensory', 'olfactory', NULL, 'The overwhelming smell of excrement, decay, and chemicals defines the space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4718, 1557, 'emotion', 'grief', NULL, 'Stephen''s heartbreak for his younger self and the loss of his innocence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4719, 1557, 'theme', 'betrayal', NULL, 'The core theme of the beat, as Stephen recognizes his mother''s poison as the ultimate betrayal of trust.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4720, 1557, 'sensory', 'olfactory', NULL, 'The ''sweet and cloying'' chemical smell of the poison is the key sensory trigger for Stephen''s realization.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4721, 1558, 'emotion', 'agony', NULL, 'The pain described is not just physical but existential, rewriting Stephen''s understanding of suffering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4722, 1558, 'theme', 'annihilation', NULL, 'The complete and total destruction of the characters, the location, and the immediate reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4723, 1558, 'theme', 'sacrifice', NULL, 'Stephen realizes that the death of everyone he loves is the price for creating a new timeline.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4724, 1558, 'sensory', 'auditory', NULL, 'Hearing is the last sense to fail, forcing Stephen to listen to his own body being destroyed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:23:43.43186-05', '2026-02-28 19:23:43.43186-05');
INSERT INTO public.semantic_tags VALUES (4725, 1559, 'emotion', 'confusion', NULL, 'The protagonist''s first sensation is that things are wrong and unfamiliar.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4726, 1559, 'theme', 'disorientation', NULL, 'Waking in an unknown place after a traumatic event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4727, 1559, 'sensory', 'auditory', NULL, 'The scene begins with a disembodied voice tearing through silence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4728, 1560, 'emotion', 'panic', NULL, 'The discovery of being in a child''s body triggers an ice-water shock.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4729, 1560, 'theme', 'body horror', NULL, 'The protagonist''s own body feels alien and wrong.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4730, 1560, 'sensory', 'tactile', NULL, 'The feeling of smallness, weakness, and soft hands contrasts with expected callouses and muscle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4731, 1561, 'theme', 'fractured identity', NULL, 'The core conflict of three minds fighting for control in one skull is established.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4732, 1561, 'emotion', 'resignation', NULL, 'The Old Man''s consciousness introduces a sense of fatalism and hopelessness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4733, 1561, 'emotion', 'terror', NULL, 'The Child''s consciousness is overwhelmed by pure, animalistic fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4734, 1562, 'theme', 'confrontation', NULL, 'The protagonist confronts the impossible reality of his new form in the mirror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4735, 1562, 'emotion', 'dread', NULL, 'The sound of his mother humming is not comforting but a sign of impending danger (poison).', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4736, 1562, 'sensory', 'visual', NULL, 'The reflection in the mirror provides a stark confirmation of the protagonist''s transformation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:24:56.545502-05', '2026-02-28 19:24:56.545502-05');
INSERT INTO public.semantic_tags VALUES (4737, 1563, 'sensory', 'olfactory', NULL, 'The scene is introduced with a detailed ''cocktail of poverty and desperation''—botulism, sour milk, and fear-sweat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4738, 1563, 'emotion', 'dread', NULL, 'The protagonist''s creeping approach and recognition of the smells and his mother''s posture builds a deep sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4739, 1563, 'theme', 'deceptive appearances', NULL, 'The mother''s warm voice and sincere smile mask the horrific act she is about to perform.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4740, 1564, 'theme', 'truth as a weapon', NULL, 'The simple, direct question ''Why are you poisoning me?'' acts like a spell that shatters the entire fabricated reality of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4741, 1564, 'emotion', 'shock', NULL, 'The mother''s reaction is ''seismic,'' an erosion of her entire being as her deception is named.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4742, 1564, 'sensory', 'visual distortion', NULL, 'Reality hiccups, showing two falling vials and a splitting shadow, representing the collapse of a stable timeline.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4743, 1565, 'emotion', 'grief', NULL, 'The mother''s sobs are described as ''tectonic,'' coming from a place of deep, accumulated pain and horror at her own actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4744, 1565, 'theme', 'cycle of trauma', NULL, 'The mother reveals her actions are a twisted attempt to break the cycle of her husband''s violence, but she only creates a new form of trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4745, 1565, 'sensory', 'auditory', NULL, 'The mother''s confession rips out of her ''like shrapnel'' and drops to a whisper ''like wind through empty houses''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4746, 1566, 'emotion', 'forgiveness', NULL, 'The protagonist chooses to hug his mother, an act of empathy that transcends his own pain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4747, 1566, 'theme', 'reconciliation', NULL, 'In the space between timelines, mother and son see each other clearly, achieving a moment of pained understanding that doesn''t erase the past but allows for connection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4748, 1566, 'emotion', 'catharsis', NULL, 'The shared grief and embrace provide a moment of emotional release for both characters, cracking reality ''just enough to let a little light in''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:00.523469-05', '2026-02-28 19:26:00.523469-05');
INSERT INTO public.semantic_tags VALUES (4749, 1567, 'emotion', 'distress', NULL, 'The protagonist is overwhelmed by trauma and internal conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4750, 1567, 'theme', 'fractured identity', NULL, 'The three consciousnesses arguing within a child''s body.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4751, 1567, 'sensory', 'visual', NULL, 'The appearance and disappearance of the phantom amethyst crystal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4752, 1568, 'theme', 'cosmic horror', NULL, 'Benji''s true form is a reality-bending, incomprehensible being.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4753, 1568, 'emotion', 'awe', NULL, 'The protagonist''s reaction to Benji''s true form, mixed with exasperation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4754, 1568, 'sensory', 'auditory', NULL, 'Benji''s voice emanates from everywhere at once.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4755, 1569, 'theme', 'revelation', NULL, 'The protagonist learns he is not the cause of the problem, but a symptom of a decaying reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4756, 1569, 'emotion', 'vindication', NULL, 'A sense of relief that the protagonist is not to blame for reality''s decay, mixed with the fear of what that truly means.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4757, 1569, 'theme', 'imprisonment', NULL, 'Reality is described as a failing prison for a cosmic entity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4758, 1570, 'emotion', 'dread', NULL, 'The realization that a god-like entity is waking up specifically because of him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4759, 1570, 'theme', 'impending doom', NULL, 'The scene ends with the direct threat of Yaldabaoth''s awakening, signified by the snoring stopping.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4760, 1570, 'sensory', 'auditory', NULL, 'The sudden silence as the snoring from the other room stops, creating immense tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:26:54.299864-05', '2026-02-28 19:26:54.299864-05');
INSERT INTO public.semantic_tags VALUES (4761, 1571, 'emotion', 'dread', NULL, 'The heavy, uneven footsteps are described as a ''countdown to an execution,'' creating a powerful sense of impending doom.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.semantic_tags VALUES (4762, 1571, 'theme', 'entrapment', NULL, 'The protagonist explicitly states, ''This trailer is a box, and we''re all rats trapped inside.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.semantic_tags VALUES (4763, 1571, 'sensory', 'auditory', NULL, 'The scene is dominated by sounds: a door detonating ''like a gunshot in a tomb,'' heavy footsteps, and stuttering sobs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.semantic_tags VALUES (4764, 1572, 'emotion', 'agony', NULL, 'The pain is described viscerally, as a ''flower made of fire'' and a world burning ''white-hot with agony.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.semantic_tags VALUES (4765, 1572, 'theme', 'brutality', NULL, 'The violence is described not as random but as ''practiced,'' ''methodical,'' and a ''choreographed brutality.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.semantic_tags VALUES (4766, 1572, 'sensory', 'tactile', NULL, 'Focus on the physical sensations of the beating: the impact of blows, cracking bones, the taste of blood, and the feeling of the hard tile floor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.semantic_tags VALUES (4767, 1572, 'emotion', 'helplessness', NULL, 'Both the protagonist, who cannot fight back, and the mother, who cannot intervene, are completely powerless.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:27:47.67073-05', '2026-02-28 19:27:47.67073-05');
INSERT INTO public.semantic_tags VALUES (4768, 1573, 'emotion', 'Hope', NULL, 'A brief, desperate hope that the horror was just a nightmare, immediately crushed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4769, 1573, 'emotion', 'Dread', NULL, 'The feeling of inevitability upon hearing the familiar sounds of the abuser''s approach.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4770, 1573, 'theme', 'Inevitability', NULL, 'The scene repeats exactly as it has before, establishing the nature of the loop.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4771, 1573, 'sensory', 'Auditory', NULL, 'The beat is defined by sounds: a door slam, heavy footsteps, and whimpering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4772, 1574, 'theme', 'Decay', NULL, 'Physical forms, the environment, and sanity all deteriorate with each repetition.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4773, 1574, 'emotion', 'Agony', NULL, 'The relentless, escalating pain of thousands of repeated beatings.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4774, 1574, 'sensory', 'Visual Distortion', NULL, 'Reality thins, curtains scream, and walls pulse, showing the breakdown of perception.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4775, 1575, 'emotion', 'Cosmic Horror', NULL, 'The protagonist''s realization that his suffering is not random but an eternal, deliberate punishment by a god-like entity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4776, 1575, 'theme', 'Memory as a Curse', NULL, 'The Orchestrator reveals the torture is a direct result of the protagonist''s choice ''to remember.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4777, 1575, 'theme', 'Punishment', NULL, 'The purpose of the loop is explicitly stated as a punishment for refusing a ''merciful'' death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4778, 1575, 'sensory', 'Conceptual', NULL, 'Pain and reality transcend the physical, with blows falling through ''geometries'' and ''the spaces between thoughts.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:28:44.360244-05', '2026-02-28 19:28:44.360244-05');
INSERT INTO public.semantic_tags VALUES (4779, 1576, 'sensory', 'olfactory', NULL, 'The scene is introduced through the overwhelming, industrial smell of leather and chemicals, establishing the setting before it''s even seen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.semantic_tags VALUES (4780, 1576, 'emotion', 'dread', NULL, 'A growing sense of dread as the protagonist pieces together the details of the horrifyingly transformed room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.semantic_tags VALUES (4781, 1576, 'theme', 'body horror', NULL, 'The entire environment is built around the concept of processing human bodies into inanimate objects.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.semantic_tags VALUES (4782, 1577, 'emotion', 'helplessness', NULL, 'The protagonist is physically and vocally paralyzed, unable to resist his father''s calm, methodical actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.semantic_tags VALUES (4783, 1577, 'theme', 'perverted education', NULL, 'The horrific act of murder is framed as a ''pop quiz,'' a ''lesson,'' and a ''final exam,'' twisting the concept of teaching into a tool of abuse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.semantic_tags VALUES (4784, 1577, 'sensory', 'tactile', NULL, 'The sensation of heat from the vat, the gentle pressure of the father''s hands, and the final, warm embrace of the consuming solution.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.semantic_tags VALUES (4785, 1577, 'sensory', 'auditory', NULL, 'The father''s calm, conversational voice provides a chilling contrast to the violence of the scene, culminating in the sound of a bell.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:29:44.415204-05', '2026-02-28 19:29:44.415204-05');
INSERT INTO public.semantic_tags VALUES (4786, 1578, 'emotion', 'Nostalgia', NULL, 'The protagonist is immersed in a painfully perfect memory of home.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.semantic_tags VALUES (4787, 1578, 'emotion', 'Hope', NULL, 'A brief, powerful flicker of hope for a normal father-son relationship.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.semantic_tags VALUES (4788, 1578, 'theme', 'Deceptive Safety', NULL, 'The overwhelming sense of normalcy and safety is a prelude to horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.semantic_tags VALUES (4789, 1578, 'sensory', 'Olfactory', NULL, 'The smells of bacon, coffee, and old carpet are key to establishing the scene''s initial reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.semantic_tags VALUES (4790, 1579, 'emotion', 'Horror', NULL, 'Generated by the father''s grotesque physical transformation and the subsequent violence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.semantic_tags VALUES (4791, 1579, 'theme', 'Body Horror', NULL, 'The scene features a graphic, narrated disembowelment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.semantic_tags VALUES (4792, 1579, 'theme', 'Twisted Pedagogy', NULL, 'An act of extreme violence is framed as an educational demonstration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.semantic_tags VALUES (4793, 1579, 'sensory', 'Tactile', NULL, 'The feeling of the leather blade cutting skin is described as a ''strange cold-hot sensation''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:30:26.043448-05', '2026-02-28 19:30:26.043448-05');
INSERT INTO public.semantic_tags VALUES (4794, 1580, 'emotion', 'numbness', NULL, 'The protagonist''s fear has been completely eroded by repetition, leaving only a hollow, detached state.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.semantic_tags VALUES (4795, 1580, 'theme', 'surrealism', NULL, 'The laws of physics are inverted (upward-falling blood) and the environment is sentient and hostile (screaming walls).', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.semantic_tags VALUES (4796, 1580, 'sensory', 'auditory', NULL, 'The walls emit a ''choir of the damned'' that vibrates through the protagonist''s bones.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.semantic_tags VALUES (4797, 1580, 'sensory', 'olfactory', NULL, 'The smell of blood is described distinctly as ''rancid pennies and the last breath of dying animals''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.semantic_tags VALUES (4798, 1581, 'emotion', 'uncertainty', NULL, 'For the first time, the torturer shows confusion, breaking the established pattern of the torture.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.semantic_tags VALUES (4799, 1581, 'theme', 'power dynamics', NULL, 'A shift occurs where the victim''s passive resistance (numbness) undermines the torturer''s power, causing the abuser to become desperate.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.semantic_tags VALUES (4800, 1581, 'emotion', 'desperation', NULL, 'The torturer''s final expression reveals his panic at losing control over his victim.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.semantic_tags VALUES (4801, 1581, 'sensory', 'visual', NULL, 'The father''s form flickers, and the room''s reality shifts like changing channels, visualizing the breakdown of his control.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:09.282117-05', '2026-02-28 19:31:09.282117-05');
INSERT INTO public.semantic_tags VALUES (4802, 1582, 'theme', 'transformation', NULL, 'The father''s physical form corrupts and transforms into a cosmic horror, revealing his true nature.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4803, 1582, 'emotion', 'dread', NULL, 'The scene is saturated with body horror and surreal, hostile environmental descriptions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4804, 1582, 'sensory', 'auditory', NULL, 'The entity''s voice emanates from the walls and ceiling, not its mouth, creating a sense of omnipresent threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4805, 1583, 'theme', 'deconstruction', NULL, 'The protagonist dismantles the entity''s godhood not with power, but with logic and philosophy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4806, 1583, 'emotion', 'defiance', NULL, 'The protagonist''s calm refusal to kneel is a powerful act of defiance against a supposed god.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4807, 1583, 'sensory', 'visual', NULL, 'The reality shifts to an ''impossible cathedral'' where golden light reveals cracks of ''hungry darkness''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4808, 1584, 'emotion', 'desperation', NULL, 'The entity''s final act is not one of divine wrath but a ''tantrum'' born of utter desperation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4809, 1584, 'theme', 'futility', NULL, 'The final reset is a futile gesture, a supernova of rage that only succeeds in destroying itself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4810, 1584, 'sensory', 'kinesthetic', NULL, 'The protagonist feels the ''nauseating sensation of being dragged backward through every death''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4811, 1585, 'emotion', 'peace', NULL, 'The overwhelming feeling after the climax is not triumph, but a ''gentle absence'' and quiet gratitude.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4812, 1585, 'theme', 'liberation', NULL, 'The scene''s resolution is the protagonist''s final freedom from the cycle of torment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4813, 1585, 'sensory', 'auditory', NULL, 'The contrast between the entity''s final scream, the distant whisper, and the ''perfect silence'' is the key sensory element.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:31:56.652468-05', '2026-02-28 19:31:56.652468-05');
INSERT INTO public.semantic_tags VALUES (4814, 1586, 'emotion', 'Disorientation', NULL, 'The protagonist feels a sense of nightmarish familiarity in a sterile, unreal space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4815, 1586, 'theme', 'Liminality', NULL, 'The scene takes place in a ''waiting room at the end of everything'', a space between reality and nothingness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4816, 1586, 'sensory', 'Auditory Absence', NULL, 'The silence is described as an ''absolute void'' that causes physical aching, making it a tangible presence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4817, 1587, 'theme', 'Paradox', NULL, 'An infinite god has locked himself in a finite prison with the one finite being whose disbelief can harm him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4818, 1587, 'emotion', 'Cosmic Irony', NULL, 'Benji''s tone is one of amused pity for the ''magnificent bastard'' who has engineered his own potential downfall.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4819, 1587, 'sensory', 'Auditory', NULL, 'The surreal crunch of popcorn, sounding like ''breaking promises'', cuts through the oppressive silence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4820, 1588, 'emotion', 'Dread', NULL, 'The protagonist realizes the catastrophic, unwinnable nature of his situation: destroying the enemy means destroying everything.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4821, 1588, 'theme', 'Existential Stakes', NULL, 'The conflict is elevated from personal to the potential annihilation of all possible realities.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4822, 1588, 'sensory', 'Olfactory', NULL, 'A synesthetic shift in reality as the air suddenly tastes like ''apples and burnt electronics''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4823, 1589, 'emotion', 'Menace', NULL, 'Benji''s grin widens and his teeth become sharp, shifting him from a quirky guide to a dangerous, ancient being.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4824, 1589, 'theme', 'Divine Mortality', NULL, 'The central question is posed: can a god die if no one is around to believe they are immortal?', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4825, 1589, 'sensory', 'Tactile', NULL, 'The temperature drops sharply, and frost spreads across the room, a physical manifestation of I AM''s power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:05.25298-05', '2026-02-28 19:33:05.25298-05');
INSERT INTO public.semantic_tags VALUES (4826, 1590, 'emotion', 'defiance', NULL, 'The protagonist, despite his child form, immediately confronts the cosmic horror with memories of a past victory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4827, 1590, 'theme', 'past conflict', NULL, 'The dialogue is centered on the fact these two have fought before, and the protagonist was the victor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4828, 1590, 'sensory', 'visual horror', NULL, 'I AM''s form is described as a ''cancer made of static and failing code'' that is painful to look at.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4829, 1591, 'emotion', 'rage', NULL, 'The protagonist''s rage begins to build to critical levels after I AM''s taunts about his wife and Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4830, 1591, 'theme', 'psychological warfare', NULL, 'I AM uses painful truths and revelations about Jamie to attack the protagonist emotionally.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4831, 1591, 'sensory', 'tactile', NULL, 'The temperature in the room plummets, a physical manifestation of I AM''s power and the scene''s tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4832, 1592, 'emotion', 'nihilism', NULL, 'The protagonist calmly accepts that destroying I AM means destroying everything, stating ''I don''t care anymore''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4833, 1592, 'theme', 'cosmic horror', NULL, 'The fight is between metaphysical beings, with discussions of multiple realities and the fundamental substrate of existence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4834, 1592, 'sensory', 'tactile', NULL, 'I AM''s flesh is described as feeling like ''liquid mercury mixed with broken glass''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4835, 1593, 'emotion', 'terror', NULL, 'I AM, a god-like being, shows genuine fear for the first time right before he is destroyed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4836, 1593, 'theme', 'total destruction', NULL, 'The scene ends with the complete annihilation of the antagonist and the subsequent collapse of the reality they are in.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4837, 1593, 'sensory', 'auditory', NULL, 'The final blow has a sound ''like the universe''s spine snapping''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:33:59.211403-05', '2026-02-28 19:33:59.211403-05');
INSERT INTO public.semantic_tags VALUES (4838, 1594, 'emotion', 'pride', NULL, 'Benji expresses genuine pride in the protagonist''s achievement, despite the catastrophic consequences.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4839, 1594, 'theme', 'finality', NULL, 'The scene establishes the absolute end of everything as a direct result of the protagonist''s actions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4840, 1594, 'sensory', 'auditory', NULL, 'The sound of Benji''s clapping echoes in the otherwise dissolving and soon-to-be-silent space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4841, 1595, 'theme', 'paradox', NULL, 'Benji''s explanation of Jamie''s existence hinges on her being simultaneously real and unreal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4842, 1595, 'emotion', 'longing', NULL, 'The protagonist''s question about Jamie reveals his deep, persistent attachment even at the end of all things.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4843, 1595, 'theme', 'metaphysics', NULL, 'The dialogue explores the nature of reality, imagination, and what it means for something to exist.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4844, 1596, 'emotion', 'acceptance', NULL, 'The protagonist dissolves not with fear, but with a profound sense of peace and relief.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4845, 1596, 'sensory', 'tactile', NULL, 'The dissolution is a physical sensation, described as warm and like ''digital ivy'' crawling on the skin.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4846, 1596, 'theme', 'transformation', NULL, 'Benji''s final words suggest that this end is not oblivion, but a change into something else, hinting at a cyclical nature or a sequel.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4847, 1596, 'sensory', 'visual', NULL, 'The scene ends with the complete absence of visual information, described as ''only white''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:34:54.279468-05', '2026-02-28 19:34:54.279468-05');
INSERT INTO public.semantic_tags VALUES (4848, 1597, 'emotion', 'solace', NULL, 'The protagonist finds solace in the simplicity of his domestic life, a respite from his cosmic responsibilities.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.semantic_tags VALUES (4849, 1597, 'theme', 'amnesia', NULL, 'The protagonist''s memories of his powerful life are actively fading and being forgotten, replaced by a simple present.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.semantic_tags VALUES (4850, 1597, 'sensory', 'auditory', NULL, 'The sound of the son''s ''exuberant chatter'' from the living room is a key element of the peaceful atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.semantic_tags VALUES (4851, 1597, 'sensory', 'tactile', NULL, 'The protagonist is ''cocooned by the warmth'' of his wife''s presence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
INSERT INTO public.semantic_tags VALUES (4852, 1598, 'emotion', 'excitement', NULL, 'The wife''s ''huge grin'' and excited announcement drive the energy of the beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:35:54.489486-05', '2026-02-28 19:35:54.489486-05');
