INSERT INTO public.semantic_tags VALUES (4861, 1601, 'emotion', 'confusion', NULL, 'The protagonist and his family are bewildered by his utterance of ''Sorhhinda''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:36:44.274997-05', '2026-02-28 19:36:44.274997-05');
