INSERT INTO public.semantic_tags VALUES (4869, 1604, 'emotion', 'Dread', NULL, 'A growing sense of wrongness as comforting family moments become corrupted and sinister.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:37:41.028865-05', '2026-02-28 19:37:41.028865-05');
