INSERT INTO public.semantic_tags VALUES (4873, 1605, 'emotion', 'Disorientation', NULL, 'The complete and unnatural freezing of time is a profoundly disorienting experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:37:41.028865-05', '2026-02-28 19:37:41.028865-05');
