INSERT INTO public.semantic_tags VALUES (4876, 1606, 'emotion', 'Relief', NULL, 'The return to normalcy brings a sense of safety, even with mundane problems.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:37:41.028865-05', '2026-02-28 19:37:41.028865-05');
