INSERT INTO public.semantic_tags VALUES (4878, 1606, 'sensory', 'Olfactory', NULL, 'The normal smell of sweet waffles and coffee helps ground the protagonist in reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:37:41.028865-05', '2026-02-28 19:37:41.028865-05');
INSERT INTO public.semantic_tags VALUES (4879, 1607, 'emotion', 'resignation', NULL, 'The protagonist''s acceptance of the ''torture'' of updating his resume, framed by his thought, ''Back to the fucking grindstone.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:38:22.705997-05', '2026-02-28 19:38:22.705997-05');
INSERT INTO public.semantic_tags VALUES (4880, 1607, 'theme', 'mundanity', NULL, 'The scene focuses on the universally tedious and unglamorous task of applying for jobs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:38:22.705997-05', '2026-02-28 19:38:22.705997-05');
