INSERT INTO public.semantic_tags VALUES (4889, 1609, 'theme', 'Subconscious Revelation', NULL, 'The protagonist''s mouth says something ''like it knew something my brain didn''t'', hinting at a deeper, hidden consciousness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:39:11.351125-05', '2026-02-28 19:39:11.351125-05');
INSERT INTO public.semantic_tags VALUES (4890, 1610, 'theme', 'Memory Recovery', NULL, 'The core of the beat is the protagonist suddenly remembering a past he didn''t know he had forgotten.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:39:11.351125-05', '2026-02-28 19:39:11.351125-05');
