INSERT INTO public.semantic_tags VALUES (4893, 1610, 'theme', 'The Past is Not Dead', NULL, 'A call from a ''memory that was never supposed to exist'' demonstrates that the protagonist''s past is actively returning to haunt him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 19:39:11.351125-05', '2026-02-28 19:39:11.351125-05');
