INSERT INTO public.semantic_tags VALUES (5170, 1699, 'sensory', 'auditory', NULL, 'The buzzing of the phone serves as a grounding stimulus, pulling Stephen back from his vision and into the present moment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:37:15.111704-05', '2026-02-28 22:37:15.111704-05');
