INSERT INTO public.semantic_tags VALUES (5180, 1702, 'theme', 'monotony', NULL, 'The ''hypnotic'' and ''endless'' nature of the drive reflects a state of mindless autopilot.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:39:10.743052-05', '2026-02-28 22:39:10.743052-05');
