INSERT INTO public.semantic_tags VALUES (5184, 1703, 'sensory', 'olfactory', NULL, 'The conflict between the phantom smell of vanilla and the real-world smell of peaches from a roadside stand.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:39:10.743052-05', '2026-02-28 22:39:10.743052-05');
INSERT INTO public.semantic_tags VALUES (5185, 1703, 'emotion', 'disorientation', NULL, 'The sudden screech from the radio shatters the reverie, causing Stephen to swerve and become abruptly aware of his solitude.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:39:10.743052-05', '2026-02-28 22:39:10.743052-05');
