INSERT INTO public.semantic_tags VALUES (5196, 1707, 'emotion', 'Anxiety', NULL, 'Stephen''s initial stiffness and social awkwardness upon entering a social situation after a long time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
