INSERT INTO public.semantic_tags VALUES (5198, 1707, 'sensory', 'Olfactory', NULL, 'The scene opens with a detailed description of the shop''s smells: old paper, coffee, and a mysterious floral scent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
