INSERT INTO public.semantic_tags VALUES (5200, 1708, 'theme', 'Economic Precarity', NULL, 'The conversation directly addresses the broken job market and widespread unemployment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.semantic_tags VALUES (5201, 1709, 'emotion', 'Shock', NULL, 'Stephen''s reaction to the phrase ''consensus reality'' is visceral and immediate.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.semantic_tags VALUES (5202, 1709, 'theme', 'Reality Breakdown', NULL, 'James introduces the core thematic concept that shared reality is collapsing, which resonates deeply with Stephen''s internal state.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.semantic_tags VALUES (5203, 1709, 'sensory', 'Auditory', NULL, 'The shift from tense, quiet conversation to ''real laughter'' is a notable auditory change.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.semantic_tags VALUES (5204, 1710, 'emotion', 'Agony', NULL, 'Stephen''s feeling is described as ''the worst kind of loss''—the agony of knowing without remembering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.semantic_tags VALUES (5205, 1710, 'theme', 'Memory vs. Reality', NULL, 'The beat hinges on the conflict between Stephen''s vivid memory and Becca''s complete lack of one.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.semantic_tags VALUES (5206, 1710, 'sensory', 'Olfactory', NULL, 'The smell of vanilla and peaches returns, directly triggering Stephen''s memory and subsequent questioning.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:40:43.101452-05', '2026-02-28 22:40:43.101452-05');
INSERT INTO public.semantic_tags VALUES (5207, 1711, 'theme', 'neglect', NULL, 'The room and its contents are described as actual neglect, not a curated aesthetic, suggesting forgotten or forbidden knowledge.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5208, 1711, 'sensory', 'auditory', NULL, 'The abrupt transition from muffled party sounds to silence emphasizes the separation and otherness of the back room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
