INSERT INTO public.semantic_tags VALUES (5210, 1712, 'emotion', 'love', NULL, 'Stephen experiences a profound, ancient love that feels ''coded into my marrow,'' not just a teenage crush.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5211, 1712, 'theme', 'fractured reality', NULL, 'The memory is unstable, with details like the teacher''s name flickering between two possibilities, suggesting reality itself is unreliable.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5212, 1712, 'sensory', 'olfactory', NULL, 'The scent of vanilla and peaches is a powerful, anomalous sensory detail that ''colonized'' the memory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5213, 1713, 'emotion', 'disorientation', NULL, 'Stephen returns from his memory to find books in his hands he doesn''t remember grabbing, highlighting a break in his conscious action.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5214, 1713, 'theme', 'fated discovery', NULL, 'The books seem to have chosen him rather than the other way around, appearing in his hands as if by magic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5215, 1713, 'sensory', 'tactile', NULL, 'The books are described as ''body warm'' and ''alive'', a key physical sensation that marks them as supernatural.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5216, 1714, 'theme', 'divine error', NULL, 'The central theme of the vision is that the flawed reality was created not from malice, but from a mistake made out of curiosity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5217, 1714, 'emotion', 'revelation', NULL, 'The text feels like an autobiography to Stephen, a personal confession rather than mythology.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5218, 1714, 'theme', 'imprisonment', NULL, 'The vision describes the creation of the ''prison realm disguised as reality,'' a core concept of the narrative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:41:32.351858-05', '2026-02-28 22:41:32.351858-05');
INSERT INTO public.semantic_tags VALUES (5219, 1715, 'theme', 'mystery', NULL, 'The origin and behavior of the books are inexplicable to the bookstore owners.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.semantic_tags VALUES (5220, 1715, 'emotion', 'relief', NULL, 'Becca and James feel a physical relief at being unburdened of the strange books.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.semantic_tags VALUES (5221, 1715, 'sensory', 'tactile', NULL, 'Stephen feels the books are warm and pulsing, as if alive.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
INSERT INTO public.semantic_tags VALUES (5222, 1716, 'emotion', 'grief', NULL, 'Stephen experiences a sudden, overwhelming grief for a loss he couldn''t remember until this moment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
