INSERT INTO public.semantic_tags VALUES (5225, 1717, 'emotion', 'determination', NULL, 'Stephen''s grief crystallizes into a promise and a mission to find Jamie, or what''s left of her.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:42:34.544324-05', '2026-02-28 22:42:34.544324-05');
