INSERT INTO public.semantic_tags VALUES (5329, 1745, 'emotion', 'relief', NULL, 'Finding the structure provides a stark contrast to the chaos of the fight, offering a moment of safety.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.semantic_tags VALUES (5330, 1745, 'theme', 'sanctuary', NULL, 'The structure is a haven in a hostile world, a place of quiet and safety.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.semantic_tags VALUES (5331, 1745, 'sensory', 'visual', NULL, 'The sigils are described as physically painful to look at, suggesting their extra-dimensional nature.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
INSERT INTO public.semantic_tags VALUES (5332, 1746, 'theme', 'connection', NULL, 'A powerful, targeted call reaches Whitney across dimensions, suggesting she is not alone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:00.715933-05', '2026-02-28 22:55:00.715933-05');
