INSERT INTO public.semantic_tags VALUES (5335, 1747, 'emotion', 'horror', NULL, 'The scene depicts a surreal, body-horror-inflected vision of personal annihilation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
