INSERT INTO public.semantic_tags VALUES (5339, 1748, 'emotion', 'isolation', NULL, 'Whitney experiences a profound, absolute loneliness as a disembodied consciousness in the void.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.semantic_tags VALUES (5340, 1748, 'theme', 'resilience', NULL, 'Despite total hopelessness, a stubborn part of Whitney''s consciousness fights back, learning to dream and escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.semantic_tags VALUES (5341, 1748, 'sensory', 'sensory deprivation', NULL, 'The Void is defined by a total lack of sensory input—no light, no sound, no touch.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
