INSERT INTO public.semantic_tags VALUES (5343, 1749, 'theme', 'memory', NULL, 'The idea that being remembered by others is a form of anchor against non-existence is central to this beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.semantic_tags VALUES (5344, 1749, 'sensory', 'kinesthetic', NULL, 'The feeling of the ''vibration'' and the act of ''falling'' through the portal are the dominant sensations.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:55:44.180429-05', '2026-02-28 22:55:44.180429-05');
INSERT INTO public.semantic_tags VALUES (5345, 1750, 'theme', 'isolation', NULL, 'Patrick''s compound is deliberately cut off from the world, both physically and digitally.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.semantic_tags VALUES (5346, 1750, 'emotion', 'apprehension', NULL, 'Stephen is entering a strange, potentially hostile environment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
INSERT INTO public.semantic_tags VALUES (5347, 1750, 'sensory', 'olfactory', NULL, 'The compound has a distinct and unsettling layered smell.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
