INSERT INTO public.semantic_tags VALUES (5354, 1753, 'theme', 'empowerment', NULL, 'Stephen taps into a latent, powerful ability he didn''t know he had.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:56:51.719407-05', '2026-02-28 22:56:51.719407-05');
