INSERT INTO public.semantic_tags VALUES (5363, 1756, 'sensory', 'caustic', NULL, 'The air burns against Benji''s form ''like acid on exposed nerve endings''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:58:18.004458-05', '2026-02-28 22:58:18.004458-05');
