INSERT INTO public.semantic_tags VALUES (5379, 1762, 'theme', 'revelation', NULL, 'Patrick''s backstory reveals the origins of his knowledge and the catalyst for his awakening.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.semantic_tags VALUES (5380, 1762, 'emotion', 'disbelief', NULL, 'Stephen''s reaction to Patrick''s history highlights how extraordinary and unbelievable the events are.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
