INSERT INTO public.semantic_tags VALUES (5385, 1764, 'emotion', 'horror', NULL, 'Stephen''s realization that his wife is not just a stranger, but a malevolent guard in his personal prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
INSERT INTO public.semantic_tags VALUES (5386, 1764, 'emotion', 'clarity', NULL, 'Described as a ''lens snapping into focus,'' Stephen''s pain brings understanding, connecting disparate strange events into a cohesive, terrifying picture.', 'gemini', 'gemini-2.5-pro', '2026-02-28 22:59:15.731939-05', '2026-02-28 22:59:15.731939-05');
