INSERT INTO public.semantic_tags VALUES (5395, 1766, 'sensory', 'auditory', NULL, 'The beat is defined by Patrick''s final, impactful words of warning and revelation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:00:16.411887-05', '2026-02-28 23:00:16.411887-05');
INSERT INTO public.semantic_tags VALUES (5396, 1767, 'theme', 'obedience', NULL, 'The Buried command simply because they were always told to, and the Student seeks for the same reason.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:01:18.113297-05', '2026-02-28 23:01:18.113297-05');
