INSERT INTO public.semantic_tags VALUES (5410, 1773, 'emotion', 'disgust', NULL, 'The reaction of The Frustrated to the endless, paradoxical struggle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:01:18.113297-05', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.semantic_tags VALUES (5411, 1773, 'theme', 'finality', NULL, 'The flowers are ''newly buried forever,'' suggesting the end of a cycle or hope.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:01:18.113297-05', '2026-02-28 23:01:18.113297-05');
INSERT INTO public.semantic_tags VALUES (5412, 1774, 'emotion', 'fear', NULL, 'Xavier''s fear is mixed with resignation, while Stephen''s is one of alarm upon entering the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
