INSERT INTO public.semantic_tags VALUES (5414, 1774, 'sensory', 'auditory', NULL, 'The scene begins with the sharp, scraping sound of the wife''s screaming.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5415, 1775, 'emotion', 'grief', NULL, 'Stephen experiences the ''absolute and maddening'' grief of his past self, Aspolin.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5416, 1775, 'theme', 'sacrifice', NULL, 'Aspolin tears out a piece of his own soul to fuel the magic to save Velistra.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5417, 1775, 'theme', 'paradox', NULL, 'The concept of a wound that was erased from history but still causes pain is introduced.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5418, 1776, 'emotion', 'shock', NULL, 'Stephen''s shock at his wife''s inhuman transformation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5419, 1776, 'theme', 'supernatural revelation', NULL, 'The first clear sign that the wife is not human.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5420, 1776, 'sensory', 'visual', NULL, 'The description of the wife''s pupils being ''too wide, too black, swallowing everything''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5421, 1777, 'emotion', 'dread', NULL, 'Stephen''s blood runs cold as his wife reveals knowledge she cannot possibly have.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5422, 1777, 'theme', 'broken reality', NULL, 'Xavier''s confirmation that his mother is ''glitching'' solidifies that the rules of their world are breaking down.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5423, 1778, 'emotion', 'terror', NULL, 'The situation escalates from a physical fight to a lethal threat with the introduction of a gun.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5424, 1778, 'sensory', 'tactile', NULL, 'The ''hot and immediate'' pain of Stephen being headbutted in the nose.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5425, 1779, 'emotion', 'desperation', NULL, 'Stephen is desperately trying to survive as his wife hunts him through the house.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5426, 1779, 'sensory', 'auditory', NULL, 'The deafening gunshots and the final, massive crash of the bookcase.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5427, 1779, 'sensory', 'olfactory', NULL, 'The smell of spent gunpowder and splintered wood after the climax of the fight.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5428, 1780, 'emotion', 'grief', NULL, 'Stephen grapples with the complex grief of losing someone he loved, even if she wasn''t ''real''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5429, 1780, 'theme', 'denial vs reality', NULL, 'Stephen tries to dismiss his wife as ''just a program'' but cannot escape the emotional reality of her death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5430, 1781, 'emotion', 'paranoia', NULL, 'The appearance of the shadow confirms the threat is not over, creating a sense of being watched and pursued.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5431, 1781, 'theme', 'lingering threat', NULL, 'The shadow''s patient watchfulness implies that escaping the house is not the end of their problems.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5432, 1781, 'sensory', 'visual', NULL, 'The image of the shadow pulling itself from the wreckage and standing in the doorway.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:02:32.122088-05', '2026-02-28 23:02:32.122088-05');
INSERT INTO public.semantic_tags VALUES (5433, 1782, 'emotion', 'frustration', NULL, 'Whitney''s raw frustration at her powerlessness against the void.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5434, 1782, 'theme', 'failure', NULL, 'The initial attempts to breach the barrier fail, highlighting the ineffectiveness of superficial force and fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5435, 1782, 'sensory', 'tactile', NULL, 'The feeling of the ''cold, absolute emptiness pushing back'' is a key sensory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5436, 1783, 'emotion', 'nostalgia', NULL, 'Whitney delves into warm, painful, and formative memories of her friendship with Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5437, 1783, 'theme', 'acceptance', NULL, 'The core of the memory is Stephen''s simple, profound acceptance of Whitney''s identity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5438, 1784, 'emotion', 'catharsis', NULL, 'Whitney channels years of complex emotions—love, loss, guilt—into a single, powerful act.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5439, 1784, 'theme', 'breakthrough', NULL, 'The emotional work pays off, resulting in a physical breach of the reality barrier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5440, 1784, 'sensory', 'visual', NULL, 'The barrier cracks with a ''wrong, purple-black radiance''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5441, 1785, 'emotion', 'revelation', NULL, 'Whitney experiences a paradigm shift, realizing she is a survivor, not a deserter.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5442, 1785, 'theme', 'identity', NULL, 'The scene confirms that Whitney''s true identity is a form of power that the system could not contain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5443, 1786, 'emotion', 'foreboding', NULL, 'Despite the successful crack, the scene ends with the ominous stirring of an ancient entity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5444, 1786, 'theme', 'conspiracy', NULL, 'The revelation of TJ and the prison''s ''greatest secret'' introduces a deeper layer of rebellion and hidden truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5445, 1786, 'sensory', 'auditory', NULL, 'The unseen ''blind piper'' plays his ''maddening tune,'' setting a deeply unsettling tone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:03:40.308848-05', '2026-02-28 23:03:40.308848-05');
INSERT INTO public.semantic_tags VALUES (5446, 1787, 'emotion', 'unease', NULL, 'The static, staring NPCs create a deeply unsettling and wrong atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5447, 1787, 'theme', 'deception', NULL, 'The ministry appears to be one thing on the surface but is something else entirely underneath.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5448, 1787, 'sensory', 'olfactory', NULL, 'The smell of old grease and burnt rubber grounds the scene in a grimy reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5449, 1788, 'theme', 'impossibility', NULL, 'The existence of a vast, dry basement in Florida defies the laws of physics, highlighting the anomalous nature of the location.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5450, 1788, 'emotion', 'awe', NULL, 'Xavier''s and Stephen''s reaction to the sheer scale of the forbidden library.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5451, 1788, 'sensory', 'tactile', NULL, 'The noticeable drop in temperature upon entering the basement.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5452, 1789, 'theme', 'cosmic punishment', NULL, 'TJ''s ministry is a personalized hell designed by the demiurge as a joke.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5453, 1789, 'emotion', 'resignation', NULL, 'TJ''s exhausted acceptance of his fate and the nature of the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5454, 1790, 'theme', 'forbidden knowledge', NULL, 'Speaking a forgotten name acts as a key that unlocks a violent system response.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5455, 1790, 'sensory', 'olfactory', NULL, 'The artificial, cloying scent of peaches and vanilla is a sensory assault heralding danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5456, 1790, 'emotion', 'terror', NULL, 'The sudden shift from tense conversation to immediate, mortal danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5457, 1791, 'theme', 'sacrifice', NULL, 'TJ gives his life to buy time for Stephen and Xavier, a final act of ministry.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5458, 1791, 'theme', 'body horror', NULL, 'The description of the NPCs unraveling, with twisted limbs and rearranged faces.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5459, 1791, 'sensory', 'visual', NULL, 'The unnatural purple and black ''void-fire'' from the book.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5460, 1792, 'emotion', 'grief', NULL, 'The immediate aftermath of witnessing TJ''s death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5461, 1792, 'theme', 'escape', NULL, 'The frantic flight from a place of supposed hope that turned into a deathtrap.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5462, 1792, 'sensory', 'auditory', NULL, 'The transition from the sounds of combat and chanting to the sudden, mocking silence of the building.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:04:42.836032-05', '2026-02-28 23:04:42.836032-05');
INSERT INTO public.semantic_tags VALUES (5463, 1793, 'theme', 'Caregiving', NULL, 'Despite his own severe injuries and the immense stress, Stephen''s first priority is tending to his son''s wounds.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5464, 1793, 'sensory', 'Olfactory', NULL, 'The room is defined by the unpleasant smells of stale cigarettes, mildew, and chemical cleaner, establishing a seedy atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5465, 1793, 'emotion', 'Pain', NULL, 'Both characters are physically hurt; Xavier flinches from the antiseptic, and Stephen reflects on his broken nose and aching ribs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5466, 1794, 'emotion', 'Confusion', NULL, 'Xavier''s initial reaction to his friends'' messages is confusion and panic, as their meme-filled responses don''t match the gravity of his situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5467, 1794, 'theme', 'Adolescence', NULL, 'The mention of a crush (Tiffany) and the splotchy teenage blush provide a moment of normalcy and awkward youth amidst the terror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5548, 1821, 'theme', 'self-sacrifice', NULL, 'Stephen and Velistra volunteer for an eternity of separation to save all other realities.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5468, 1795, 'emotion', 'Shock', NULL, 'Both Stephen and Xavier are horrified by Angela''s drastically altered appearance and her blatant, manipulative lies on television.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5469, 1795, 'theme', 'Deception', NULL, 'Angela''s performance is a masterclass in manipulation, using a fabricated appearance and story to weaponize public opinion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5470, 1795, 'sensory', 'Auditory', NULL, 'The scene is dominated by the sounds from the TV: the news anchor''s crisp voice and Angela''s calculated, sobbing performance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5471, 1796, 'emotion', 'Despair', NULL, 'Xavier hits a low point, whispering, ''They all believe her, don''t they?'' as the weight of the world turning against them sinks in.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5472, 1796, 'theme', 'Loyalty', NULL, 'A crucial theme emerges as a few friends, Tiffany and Thomas, prove their loyalty by questioning the narrative instead of blindly accepting it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5473, 1796, 'theme', 'Coping Mechanism', NULL, 'Xavier''s desire to ''do something normal'' by playing Roblox is a clear attempt to cope with overwhelming trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5474, 1797, 'emotion', 'Exhaustion', NULL, 'The scene concludes with both characters finally succumbing to deep, heavy exhaustion after the intense emotional and physical ordeal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5475, 1797, 'theme', 'Vigilance', NULL, 'Before falling asleep, Stephen maintains a protective watch, listening to every sound outside the room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5476, 1797, 'sensory', 'Visual', NULL, 'The final image is of Xavier asleep with his phone screen glowing, a small light of a ''mercifully silent world'' in the dark room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:01.372949-05', '2026-02-28 23:06:01.372949-05');
INSERT INTO public.semantic_tags VALUES (5477, 1798, 'emotion', 'Urgency', NULL, 'Stephen''s abrupt awakening and immediate need to move establishes a tense, hurried pace.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5478, 1798, 'theme', 'Evasion', NULL, 'The purchase and use of cheap, absurd disguises highlights their status as fugitives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5479, 1798, 'sensory', 'Tactile', NULL, 'The feeling of the ''suffocating'' Florida heat in the cheap hoodies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5480, 1799, 'emotion', 'Dread', NULL, 'Stephen''s blood runs cold as he realizes the fire was days ago, contradicting his own memory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5481, 1799, 'theme', 'Hopelessness', NULL, 'The realization that their enemy can rewrite the past makes escape seem impossible.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5482, 1799, 'sensory', 'Olfactory', NULL, 'The smell of the burned-out building is the first sign that something is wrong.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5483, 1800, 'emotion', 'Desperation', NULL, 'Stephen''s attempt to contact Becca is a last-ditch effort to find an ally, which fails.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5484, 1800, 'theme', 'Discovery', NULL, 'Despite the grim circumstances, Xavier finds a new, albeit weak, lead to follow.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5485, 1800, 'sensory', 'Auditory', NULL, 'The clatter of plates in the Waffle House provides a backdrop of mundane reality to their supernatural crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5486, 1800, 'emotion', 'Revulsion', NULL, 'Xavier''s disgusted but humorous reaction to the online search results for ''Nyarlathotep''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:06:58.837227-05', '2026-02-28 23:06:58.837227-05');
INSERT INTO public.semantic_tags VALUES (5487, 1801, 'emotion', 'desperation', NULL, 'Stephen''s internal monologue highlights their hopelessness and exhaustion after weeks of failures.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5488, 1801, 'theme', 'last resort', NULL, 'The flyer is a strange and unlikely lead, but it''s the only one they have left.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5489, 1801, 'sensory', 'olfactory', NULL, 'The description of the shop smelling like ''dust had made illegitimate children with dead cats'' establishes a grimy, forgotten setting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5490, 1802, 'emotion', 'apprehension', NULL, 'Both characters feel that the situation is a trap, but Stephen feels compelled to proceed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5491, 1802, 'theme', 'seduction', NULL, 'The cultists use promises of pleasure and escape, not threats, to lure them in, describing their offer as a ''banquet''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5492, 1802, 'sensory', 'olfactory', NULL, 'The location has a complex and contradictory smell profile: industrial rot and mold mixed with cloying gardenias and honey.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5493, 1803, 'emotion', 'horror', NULL, 'The scene shifts from unsettling performance art to genuine horror with the arrival of the headless corpse.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5494, 1803, 'theme', 'cosmic horror', NULL, 'The arrival of The King in Yellow, a being beyond human comprehension, solidifies the genre.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5495, 1803, 'sensory', 'auditory', NULL, 'The dissonant piping music and the psychic whining noise create an atmosphere of madness and dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5496, 1804, 'theme', 'transformation', NULL, 'The cultists'' bodies horrifically mutate, turning from beautiful humans into grotesque monsters.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5497, 1804, 'sensory', 'visual', NULL, 'The beat is dominated by graphic body horror: splitting jaws, bone-swords bursting from chests, and chitinous claws growing from bloody meat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5498, 1804, 'emotion', 'frenzy', NULL, 'The cultists descend into a chaotic, all-against-all massacre, driven by ecstasy rather than malice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5499, 1805, 'emotion', 'rage', NULL, 'Stephen''s reaction to being stabbed is not pain but ''pure, undiluted rage'', causing him to foolishly pull the dagger out.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5500, 1805, 'theme', 'sacrifice', NULL, 'Stephen is wounded protecting his son, and his spilled blood becomes the ''offering'' that allows their escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5501, 1805, 'theme', 'survival', NULL, 'The beat is a desperate scramble to escape, involving quick thinking (the tourniquet) and exploiting a moment of distraction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:07:57.079337-05', '2026-02-28 23:07:57.079337-05');
INSERT INTO public.semantic_tags VALUES (5502, 1806, 'emotion', 'desperation', NULL, 'Stephen''s slurred, repeated ''Can''t...'' shows his mind failing under the strain of his injuries.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5503, 1806, 'theme', 'survival', NULL, 'The entire beat is focused on the raw act of staying conscious and finding any form of shelter.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5504, 1806, 'sensory', 'pain', NULL, 'Described as a ''fresh wave of agony'' that is constant and overwhelming.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5505, 1807, 'theme', 'unexpected aid', NULL, 'Help arrives not from a hospital, but from two mysterious women in an isolated farmhouse who are perfectly equipped to handle the situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5675, 1865, 'sensory', 'auditory', NULL, 'The ''maddening and eternal'' piping sound from the abyss.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.semantic_tags VALUES (5506, 1807, 'sensory', 'olfactory', NULL, 'The house''s smell of ''old wood, herbs, and baking bread'' immediately establishes it as a place of comfort and domesticity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5507, 1807, 'emotion', 'calm', NULL, 'The women''s ''baffling, professional calm'' is in stark contrast to the panic and agony of the arrivals.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5508, 1808, 'emotion', 'realization', NULL, 'Stephen connects the dots—no iron, strange symbols, the feel of the air—to understand he''s in a supernatural space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5509, 1808, 'theme', 'hidden world', NULL, 'The farmhouse is a pocket of an older, magical world existing secretly alongside the modern one.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5510, 1808, 'sensory', 'tactile', NULL, 'The air itself is described as feeling different, ''cleaner, like the air after a thunderstorm, crackling with a quiet power''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5511, 1809, 'emotion', 'safety', NULL, 'Stephen''s internal monologue explicitly states, ''I was finally, completely, safe,'' marking the emotional climax of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5512, 1809, 'theme', 'sanctuary', NULL, 'The farmhouse proves to be more than just a shelter; it''s a place of healing, nourishment, and peace.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5513, 1809, 'sensory', 'gustatory', NULL, 'The taste of the wine is a key point, being ''rough'' but warming for Stephen and ''sour'' like ''old socks'' for Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5514, 1809, 'emotion', 'humor', NULL, 'Xavier''s comical disgust at the wine breaks the tension and elicits a rare, pained laugh from Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:08:57.480585-05', '2026-02-28 23:08:57.480585-05');
INSERT INTO public.semantic_tags VALUES (5515, 1810, 'emotion', 'dread', NULL, 'Stephen''s feeling upon encountering the ''wrongness'' of Nyarlathotep in the void.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5516, 1810, 'theme', 'revelation', NULL, 'Nyarlathotep reveals his chaotic nature and his motive for helping Stephen: pure entertainment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5517, 1810, 'sensory', 'auditory', NULL, 'The sound of Nyarlathotep''s voice is described as a thousand sibilant whispers and his laugh as grinding glass.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5518, 1811, 'emotion', 'urgency', NULL, 'Whitney''s frantic tone conveys the desperate need to get Stephen to the Akashic Realm.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5519, 1811, 'theme', 'manipulation', NULL, 'Nyarlathotep twists the situation to his liking, cutting Whitney off to present the ''key'' in the most dramatic way.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5520, 1812, 'emotion', 'grief', NULL, 'The recovered memory of loss is not old, but feels new and is happening to Stephen right now.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5521, 1812, 'theme', 'identity', NULL, 'The memories of Jamie don''t just return to Stephen; they bring him ''back to myself,'' restoring a lost part of who he is.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5522, 1812, 'sensory', 'olfactory', NULL, 'The smell of peaches and vanilla floods Stephen''s senses, making the memory intensely real.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5523, 1813, 'emotion', 'agony', NULL, 'Stephen experiences a combination of intense physical pain and the emotional weight of his recovered trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5524, 1813, 'theme', 'consequence', NULL, 'The metaphysical breakthrough has a violent, painful consequence in the physical world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5525, 1813, 'sensory', 'tactile', NULL, 'The feeling of his arm being on fire and his stomach being a mess of pinpricks and agony.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:09:55.665444-05', '2026-02-28 23:09:55.665444-05');
INSERT INTO public.semantic_tags VALUES (5526, 1814, 'emotion', 'confusion', NULL, 'Stephen is disoriented by his ''jumble of chaos'' memories and his fever.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.semantic_tags VALUES (5527, 1814, 'emotion', 'concern', NULL, 'Expressed by Maeve and Elara through their soft approach and Maeve''s words.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.semantic_tags VALUES (5528, 1814, 'sensory', 'auditory', NULL, 'The quiet is emphasized by the ''soft, careful'' footsteps on the stairs.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.semantic_tags VALUES (5529, 1815, 'theme', 'truth', NULL, 'Stephen''s decision to reveal the truth about his identity becomes the central focus of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.semantic_tags VALUES (5530, 1815, 'emotion', 'determination', NULL, 'Stephen overcomes his pain and confusion with a firm resolve to tell his story.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.semantic_tags VALUES (5531, 1815, 'emotion', 'anticipation', NULL, 'The room falls silent as everyone waits for Stephen to begin his tale.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.semantic_tags VALUES (5532, 1815, 'sensory', 'visual', NULL, 'The imagery of Xavier being ''silhouetted against the window'' creates a somber, focused mood.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:08.424083-05', '2026-02-28 23:11:08.424083-05');
INSERT INTO public.semantic_tags VALUES (5533, 1816, 'emotion', 'nostalgia', NULL, 'Stephen recounts a perfect, idyllic past that is now lost forever.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5534, 1816, 'theme', 'creation', NULL, 'The description of Sophia''s awakening and the blooming of a new cosmos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5535, 1816, 'sensory', 'visual', NULL, 'Imagery of a reality with hyper-complex sunsets and sentient nature.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5536, 1817, 'emotion', 'horror', NULL, 'The visceral description of children being devoured and their laughter turning to screams.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5537, 1817, 'theme', 'destruction', NULL, 'The complete and utter consumption of an entire reality by a cosmic entity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5538, 1817, 'sensory', 'auditory', NULL, 'The sound of ''screams that never ended'' is a powerful and horrifying auditory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5539, 1817, 'emotion', 'despair', NULL, 'The feeling of utter helplessness as Stephen is forced to flee his burning home.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5540, 1818, 'emotion', 'hope', NULL, 'A small glimmer of hope is introduced with the idea that the children''s souls might have survived.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5541, 1818, 'theme', 'resilience', NULL, 'The concept of souls being ''too real to unmake'' suggests an inherent resilience of being.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5542, 1818, 'sensory', 'auditory', NULL, 'The scene shifts to the quiet, soft voices of Elara and Maeve, contrasting with the earlier screams.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:11:44.807321-05', '2026-02-28 23:11:44.807321-05');
INSERT INTO public.semantic_tags VALUES (5543, 1819, 'emotion', 'desperation', NULL, 'The feeling of fighting an endless, unwinnable war against an unstoppable force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5544, 1819, 'theme', 'endless conflict', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5545, 1819, 'sensory', 'kinesthetic', NULL, 'Stephen''s physical pain (throbbing arm, boiling body) grounds the cosmic story in physical suffering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5546, 1820, 'emotion', 'revelation', NULL, 'The sudden, paradigm-shifting discovery of Yaldabaoth''s weakness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5547, 1820, 'theme', 'love as power', NULL, 'Love is presented not as an emotion, but as a fundamental, unconquerable force of reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5549, 1821, 'emotion', 'defiance', NULL, 'The Elder Gods'' initial rejection of the plan to turn their home into a prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5550, 1822, 'theme', 'manipulation', NULL, 'Nyarlathotep convinces the gods not through morality, but by appealing to their selfish desire for amusement.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5551, 1822, 'emotion', 'cosmic indifference', NULL, 'The Elder Gods'' motivation is based on boredom and self-preservation, not the greater good.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5552, 1822, 'sensory', 'conceptual', NULL, 'The plan is translated into abstract concepts like music, mathematics, and the architecture of dreams for Azathoth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5553, 1823, 'emotion', 'anguish', NULL, 'The profound pain of Stephen and Velistra being torn apart, an agony that echoes through the prison''s very foundation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5554, 1823, 'theme', 'eternal separation', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5555, 1823, 'sensory', 'auditory', NULL, 'The scream of separation is so powerful it becomes a foundational element of the prison and the psyche of all souls born within it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5556, 1824, 'emotion', 'hopelessness', NULL, 'The cruelty of the memory wipe, which traps Stephen in a loop of suffering without understanding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5557, 1824, 'theme', 'cyclical suffering', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5558, 1824, 'theme', 'identity and memory', NULL, 'The loss of memory as the ultimate prison, preventing growth or escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:12:35.034331-05', '2026-02-28 23:12:35.034331-05');
INSERT INTO public.semantic_tags VALUES (5559, 1825, 'theme', 'Imprisonment', NULL, 'Yaldabaoth''s realization of his confinement drives the entire cycle of destruction and rebirth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5560, 1825, 'emotion', 'Desperation', NULL, 'The raw desperation of Yaldabaoth trying to consume reality to break free.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5561, 1825, 'theme', 'Cosmic Horror', NULL, 'The concept of gods being eternally digested and a universe imploding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5562, 1826, 'emotion', 'Tragedy', NULL, 'An attempt at loving reunion is twisted into the creation of a monstrous weapon.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5563, 1826, 'theme', 'Corruption', NULL, 'Velistra''s essence of creativity and love is perverted into mindless lust.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5564, 1826, 'sensory', 'Auditory', NULL, 'Stephen''s voice cracks as he recounts the painful memory of Velistra''s transformation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5565, 1827, 'theme', 'Endless Cycle', NULL, 'The concept of infinite reincarnations designed to perpetuate suffering and maintain control.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5566, 1827, 'emotion', 'Yearning', NULL, 'Stephen''s constant, instinctual search for a love his conscious mind cannot recall.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5567, 1827, 'sensory', 'Emotional', NULL, 'The palpable grief and shock of the listeners, expressed through tears and gasps.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:13:37.123835-05', '2026-02-28 23:13:37.123835-05');
INSERT INTO public.semantic_tags VALUES (5568, 1828, 'emotion', 'Shock', NULL, 'Xavier''s physical reaction (''face went pale'') to the revelation of his origin.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.semantic_tags VALUES (5569, 1828, 'theme', 'Unnatural Origin', NULL, 'The core of the beat is the explanation that Xavier is not a natural-born human but a spirit pulled from an anti-reality void.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.semantic_tags VALUES (5570, 1828, 'theme', 'Forbidden Knowledge', NULL, 'Stephen is imparting information about the deep mechanics of their reality that should be impossible to know.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.semantic_tags VALUES (5571, 1829, 'emotion', 'Realization', NULL, 'Xavier connects his unique perception to his status as a ''glitch'' in the system.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.semantic_tags VALUES (5572, 1829, 'theme', 'Reality Manipulation', NULL, 'The concept of the system performing ''resets'' and rewriting entire timelines is central to this beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.semantic_tags VALUES (5573, 1829, 'sensory', 'Cognitive', NULL, 'The information is highly abstract, dealing with concepts like system resets and glitches, requiring mental processing rather than physical sensation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.semantic_tags VALUES (5574, 1829, 'theme', 'Consequence', NULL, 'The entire beat focuses on the massive, reality-altering consequences of a single event: Xavier''s ''birth''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:14:46.264854-05', '2026-02-28 23:14:46.264854-05');
INSERT INTO public.semantic_tags VALUES (5575, 1830, 'theme', 'revelation', NULL, 'The fundamental nature of Stephen''s family and reality is exposed as a lie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5576, 1830, 'theme', 'artificiality', NULL, 'Stephen''s wife is revealed to be a construct, not a real person.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5577, 1831, 'theme', 'system failure', NULL, 'The prison''s control is weakening, evidenced by its inability to perform a clean reset.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5578, 1831, 'emotion', 'awe', NULL, 'Stephen expresses that three failed resets is an unprecedented event in ''infinite cycles''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5579, 1832, 'theme', 'hidden truth', NULL, 'Elara brings a subconscious truth from Stephen''s dreams into the conscious conversation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5580, 1832, 'emotion', 'shock', NULL, 'Stephen''s reaction (''How did you...?'') to Elara knowing about Hannah.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5581, 1832, 'sensory', 'visual', NULL, 'Elara''s face is described as ''ancient'' as she delivers the revelation about Hannah.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5582, 1833, 'theme', 'dramatic irony', NULL, 'Maeve and Elara clearly understand a connection that Stephen vehemently denies, creating tension for the reader.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5583, 1833, 'emotion', 'denial', NULL, 'Stephen''s reaction to Xavier''s question is described as ''too quickly,'' signaling his unwillingness to face the possibility.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5584, 1833, 'sensory', 'visual', NULL, 'The entire point of the beat is conveyed through the silent, knowing looks exchanged between Maeve and Elara.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:15:41.833846-05', '2026-02-28 23:15:41.833846-05');
INSERT INTO public.semantic_tags VALUES (5585, 1834, 'theme', 'escape', NULL, 'The beat is entirely focused on the logistics and requirements of a plan to escape their reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.semantic_tags VALUES (5586, 1834, 'emotion', 'desperate hope', NULL, 'The plan is a long shot based on a dream, but it''s the only hope they have.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.semantic_tags VALUES (5587, 1834, 'sensory', 'auditory', NULL, 'The beat consists entirely of dialogue, outlining the plan and its challenges.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.semantic_tags VALUES (5588, 1835, 'theme', 'revelation', NULL, 'Maeve and Elara''s true, ancient nature is revealed, completely changing the context of the situation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.semantic_tags VALUES (5589, 1835, 'emotion', 'awe', NULL, 'Stephen and Xavier are confronted with beings far older and more powerful than they appear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.semantic_tags VALUES (5805, 1905, 'sensory', 'tactile', NULL, 'The feeling of Jamie being solid and real in Stephen''s arms.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5590, 1835, 'theme', 'destiny', NULL, 'The reveal that Maeve and Elara have been ''waiting'' for them implies a destined convergence of events.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.semantic_tags VALUES (5591, 1835, 'sensory', 'visual', NULL, 'Focus on the visual descriptions of Maeve and Elara''s ancient eyes, knowing smiles, and the way reality bends around them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:16:31.384854-05', '2026-02-28 23:16:31.384854-05');
INSERT INTO public.semantic_tags VALUES (5592, 1836, 'sensory', 'olfactory', NULL, 'The scene opens with the smell of ''mildew and forgotten dreams,'' establishing the decayed setting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5593, 1836, 'theme', 'memory', NULL, 'The location is chosen for its ''residue'' of learning, the memory of its purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5594, 1836, 'emotion', 'curiosity', NULL, 'Xavier''s question about ''residue'' prompts the exposition about the ritual''s requirements.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5595, 1837, 'theme', 'sacrifice', NULL, 'Maeve explicitly states the ritual''s cost is not physical but a deep psychological pain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5596, 1837, 'emotion', 'apprehension', NULL, 'Maeve''s warning, ''This will hurt,'' creates a sense of dread for the coming ordeal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5597, 1838, 'theme', 'ritual', NULL, 'The hours-long, precise, and methodical preparation of the circle underscores the magical nature of the act.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5598, 1838, 'sensory', 'auditory', NULL, 'The chanting of Maeve and Elara creates harmonies that make the ''air itself vibrate''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5599, 1838, 'sensory', 'tactile', NULL, 'Stephen has to pry his wedding ring off, feeling the ''naked'' skin in the ''cold air''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5600, 1839, 'emotion', 'doubt', NULL, 'Stephen''s internal monologue reveals his belief that they are just ''crazy hoarders building a trash castle''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5601, 1839, 'emotion', 'desperation', NULL, 'Stephen pours his fear and ''desperate, clawing need'' into the pile, trying to force a result.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5602, 1839, 'theme', 'deception of appearances', NULL, 'What looks like a ''pathetic'' pile of trash is actually a nascent magical gate.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:17:39.810218-05', '2026-02-28 23:17:39.810218-05');
INSERT INTO public.semantic_tags VALUES (5603, 1840, 'emotion', 'panic', NULL, 'The sudden arrival of sirens instills immediate panic and a sense of being trapped.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5604, 1840, 'theme', 'time pressure', NULL, 'The need for thirty more minutes against the rapidly approaching police creates immense tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5605, 1840, 'sensory', 'auditory', NULL, 'The wailing sirens are the dominant sensory input, signifying the intrusion of the outside world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5606, 1841, 'theme', 'revelation', NULL, 'Maeve''s statement ''We''re fae'' and her unnatural reaction to being shot fundamentally changes the nature of the conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5607, 1841, 'theme', 'brutal combat', NULL, 'The fight is described in visceral, violent detail, highlighting the fae''s deadly prowess.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5608, 1841, 'emotion', 'shock', NULL, 'Stephen is unable to process the revelation and the impossible speed of the fae.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5609, 1842, 'theme', 'overwhelming force', NULL, 'The arrival of the helicopter and tactical units represents a massive escalation by the enemy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5610, 1842, 'emotion', 'triumph', NULL, 'Maeve has a brief, triumphant moment, believing they can win, which makes her death more shocking.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5611, 1842, 'theme', 'sudden death', NULL, 'Maeve''s death is instantaneous and graphically described, highlighting the ruthlessness of the enemy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5612, 1842, 'sensory', 'auditory', NULL, 'The ''thwap-thwap-thwap'' of the helicopter and the ''CRACK'' of the sniper rifle dominate the soundscape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5613, 1843, 'emotion', 'grief', NULL, 'Elara''s wail is described as a raw, broken sound of pure grief, devoid of magic.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5614, 1843, 'theme', 'betrayal', NULL, 'The appearance of Stephen''s wife as the enemy commander is the ultimate betrayal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5615, 1843, 'sensory', 'visual', NULL, 'The image of the wife silhouetted in the doorway is a powerful, shocking visual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5616, 1844, 'theme', 'desperate escape', NULL, 'The final moments are a frantic sprint for survival with no other options left.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5617, 1844, 'theme', 'sacrifice', NULL, 'Elara uses her last moment of life to ensure Stephen and Xavier can escape.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5618, 1844, 'sensory', 'tactile', NULL, 'The sensation of a bullet burning across Stephen''s arm and the feeling of falling into the portal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:18:33.847596-05', '2026-02-28 23:18:33.847596-05');
INSERT INTO public.semantic_tags VALUES (5619, 1845, 'emotion', 'Disorientation', NULL, 'The sudden shift in gravity and environment causes physical and mental confusion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5620, 1845, 'theme', 'Passage', NULL, 'The violent transition from one reality (Etheris) to another (Akashic Realm).', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5621, 1845, 'sensory', 'Tactile', NULL, 'The feeling of cold, hard stone and biting air establishes the harshness of the new realm.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5622, 1846, 'emotion', 'Dread', NULL, 'The growing, hungry feeling of being watched and stalked by an unseen threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5623, 1846, 'theme', 'Loss of Self', NULL, 'The Devourers literally steal memories and cognitive function, erasing identity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5624, 1846, 'sensory', 'Cognitive', NULL, 'The internal sensation of thoughts slipping away and words becoming inaccessible.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5625, 1847, 'emotion', 'Relief', NULL, 'The sudden arrival of a powerful ally turns a hopeless situation around.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5626, 1847, 'theme', 'Salvation', NULL, 'Benji''s intervention is a classic rescue, pulling the heroes back from the brink.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5627, 1847, 'sensory', 'Visual', NULL, 'Benji''s transformation into a ''vast and winged'' being is a moment of awe and power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5628, 1848, 'theme', 'Exposition', NULL, 'Benji provides crucial information about the state of the realms and why things are unstable.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5629, 1848, 'emotion', 'Weariness', NULL, 'Benji''s worn-down appearance and sigh convey the toll of a long, ongoing conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5630, 1848, 'sensory', 'Visual', NULL, 'The changing architecture from desolate ruins to intact, elegant archives shows their progress.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5631, 1849, 'emotion', 'Rage', NULL, 'Stephen''s pent-up anger and sense of betrayal explodes in a moment of violence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5632, 1849, 'theme', 'Confrontation', NULL, 'A direct, personal conflict born from past lies and hidden truths.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5633, 1849, 'sensory', 'Auditory', NULL, 'The sharp, echoing sound of the slap punctuates the silence of the vast library.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5634, 1850, 'emotion', 'Resignation', NULL, 'Stephen''s anger gives way to a grim acceptance of a horrible, but necessary, truth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5635, 1850, 'theme', 'Sacrifice', NULL, 'The central theme is revealed: an eternal sacrifice powered by love and loss to save reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5636, 1850, 'theme', 'Cruel Necessity', NULL, 'Illkeserod''s actions are framed not as evil, but as a terrible choice made for the greater good.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:19:38.316489-05', '2026-02-28 23:19:38.316489-05');
INSERT INTO public.semantic_tags VALUES (5637, 1851, 'emotion', 'Melancholy', NULL, 'Stephen''s contemplation of his cyclical suffering and the unlikelihood of a happy ending.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5638, 1851, 'theme', 'Father-Son Bond', NULL, 'A quiet, powerful moment of connection between Stephen and Xavier amidst the chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5639, 1851, 'sensory', 'Visual', NULL, 'The description of the Archives'' exterior: floating towers, bridges of light, and a perpetually grey sky.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5640, 1852, 'emotion', 'Urgency', NULL, 'The alarm and the grim expressions of the leaders create a sudden shift from waiting to immediate crisis.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5641, 1852, 'theme', 'Responsibility', NULL, 'Stephen insists on facing the threat he feels responsible for, even though he is powerless.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5642, 1852, 'sensory', 'Tactile', NULL, 'The alarm is described not as a sound but as a physical feeling: ''Like the air pressure dropped and my ears popped simultaneously.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5643, 1853, 'emotion', 'Awe', NULL, 'Stephen''s perspective as he witnesses the ''flood of impossible defenders'' he couldn''t begin to classify.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5644, 1853, 'theme', 'Mobilization', NULL, 'The entire beat is dedicated to the gathering and marching of a diverse and powerful magical army.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5645, 1853, 'sensory', 'Auditory', NULL, 'The scene is filled with the sounds of the army: the clicking of the Sinsinani''s legs, the hum of mana-infused weapons, and the chanting of arcanists.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:20:48.708996-05', '2026-02-28 23:20:48.708996-05');
INSERT INTO public.semantic_tags VALUES (5646, 1854, 'emotion', 'dread', NULL, 'The feeling of seeing the ruined town and the monstrous version of a loved one.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5647, 1854, 'theme', 'corruption', NULL, 'Both the town and Stephen''s wife are twisted, broken versions of what they should be.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5648, 1854, 'sensory', 'visual', NULL, 'The scene is dominated by the sight of fire, smoke, and glitching, distorted bodies.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5649, 1855, 'theme', 'order vs chaos', NULL, 'The precise, silent formation of the defenders contrasts with the shambling, jerking movements of the agents.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5650, 1855, 'sensory', 'olfactory', NULL, 'The overpowering stench of viscera and scorched walls inside the tavern.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5651, 1855, 'sensory', 'auditory', NULL, 'The wife''s layered, inhuman scream that cuts through the air.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5652, 1856, 'emotion', 'desperation', NULL, 'Stephen and Xavier are cornered and fighting for their lives with no hope of victory, only survival.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5653, 1856, 'theme', 'instinct', NULL, 'Stephen relies on forty-year-old muscle memory to fight, acting without thinking.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5654, 1856, 'sensory', 'kinesthetic', NULL, 'The impact of a tackle, the recoil of a shotgun, and the crack of a bone create a visceral combat feel.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5655, 1857, 'emotion', 'horror', NULL, 'The combination of the wife''s tender words from a monstrous form and the silent, final erasure of Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5656, 1857, 'theme', 'sacrifice', NULL, 'Stephen throws himself in the path of an attack to save his son, even though it ultimately fails.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5657, 1857, 'theme', 'loss', NULL, 'The sudden and absolute disappearance of a main character from reality itself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:21:48.960132-05', '2026-02-28 23:21:48.960132-05');
INSERT INTO public.semantic_tags VALUES (5658, 1858, 'emotion', 'rage', NULL, 'A transformative, ancient rage that replaces grief.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.semantic_tags VALUES (5659, 1858, 'theme', 'transformation', NULL, 'Stephen''s inner being doesn''t break, but changes into something powerful and dangerous.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.semantic_tags VALUES (5660, 1859, 'theme', 'retribution', NULL, 'Stephen lists Angela''s sins like a final judgment before sentencing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.semantic_tags VALUES (5661, 1859, 'sensory', 'visual', NULL, 'The crackling purple-black energy around Stephen''s fists.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.semantic_tags VALUES (5662, 1860, 'emotion', 'fury', NULL, 'The peak of Stephen''s rage, focused into a single, destructive act.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.semantic_tags VALUES (5663, 1860, 'theme', 'destruction', NULL, 'The complete and violent unmaking of Angela.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:22:36.541274-05', '2026-02-28 23:22:36.541274-05');
INSERT INTO public.semantic_tags VALUES (5664, 1861, 'emotion', 'urgency', NULL, 'Benji and Illkeserod stress that they must leave ''Now'' before the connection collapses.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.semantic_tags VALUES (5665, 1861, 'theme', 'collapse', NULL, 'The scene opens with the news that the realm and their means of escape are both destabilizing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.semantic_tags VALUES (5666, 1862, 'emotion', 'resolve', NULL, 'Stephen''s voice becomes flat as he makes the unwavering decision to go back for Jamie.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.semantic_tags VALUES (5667, 1862, 'theme', 'loss', NULL, 'Stephen''s decision is framed by his reflection on having already lost his son and wife.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.semantic_tags VALUES (5668, 1863, 'theme', 'cosmic stakes', NULL, 'The consequences of Stephen''s actions are revealed to be catastrophic for ''countless realities''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.semantic_tags VALUES (5669, 1863, 'emotion', 'desperation', NULL, 'Benji''s shouting and pleading highlight the finality of the choice Stephen is making.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:24:24.79032-05', '2026-02-28 23:24:24.79032-05');
INSERT INTO public.semantic_tags VALUES (5670, 1864, 'emotion', 'gratitude', NULL, 'Stephen thanks Lady Illkeserod for healing him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.semantic_tags VALUES (5671, 1864, 'theme', 'sacrifice', NULL, 'The Veilwalker card explicitly states a cost of 20 life, foreshadowing a great sacrifice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.semantic_tags VALUES (5672, 1864, 'emotion', 'urgency', NULL, 'Benji pushes Stephen toward the portal, stating he is out of time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.semantic_tags VALUES (5673, 1864, 'sensory', 'tactile', NULL, 'The Veilwalker card is described as feeling ''thicker'' than a normal card.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.semantic_tags VALUES (5674, 1865, 'emotion', 'dread', NULL, 'Stephen''s reaction to seeing the vast and terrible organic horrors in the chasm.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.semantic_tags VALUES (5676, 1865, 'sensory', 'olfactory', NULL, 'The smell of peaches and vanilla, a scent associated with Jamie, gives Stephen hope.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.semantic_tags VALUES (5677, 1865, 'theme', 'descent', NULL, 'The scene culminates in Stephen''s literal and metaphorical jump into the abyss.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:25:40.326367-05', '2026-02-28 23:25:40.326367-05');
INSERT INTO public.semantic_tags VALUES (5678, 1866, 'emotion', 'confusion', NULL, 'Xavier''s mind is ''reeling'' and ''tried to catch up'' with the sudden transition.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.semantic_tags VALUES (5679, 1866, 'theme', 'transition', NULL, 'The scene begins with an instantaneous, jarring shift from one state of reality to another.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.semantic_tags VALUES (5680, 1866, 'sensory', 'tactile', NULL, 'The shift from the ''cold void'' to the ''warm'' feeling of the memory is a key sensory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.semantic_tags VALUES (5681, 1866, 'emotion', 'relief', NULL, 'The cold nothingness dissolves, replaced by a profound warmth and sense of belonging.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.semantic_tags VALUES (5682, 1867, 'emotion', 'contentment', NULL, 'Xavier is described as content, feeling safe and at home in the library with his sister.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.semantic_tags VALUES (5683, 1867, 'theme', 'waiting', NULL, 'The central action of the beat is waiting—for Xavier and Hannah, it is a patient wait to be reunited with their Father.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.semantic_tags VALUES (5684, 1867, 'sensory', 'auditory', NULL, 'The library has a ''gentle, constant hum,'' and Hannah''s essence is a ''bright and joyful sound.''', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.semantic_tags VALUES (5685, 1867, 'theme', 'duality', NULL, 'Xavier and Hannah are presented as two distinct but inseparable parts of a single whole.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:26:46.796322-05', '2026-02-28 23:26:46.796322-05');
INSERT INTO public.semantic_tags VALUES (5686, 1868, 'emotion', 'terror', NULL, 'Xavier''s emotional state is reduced to a single point of terror as he witnesses the world''s end.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5687, 1868, 'theme', 'collapse', NULL, 'The physical and metaphysical reality of the mall is actively and violently ending.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5688, 1868, 'sensory', 'auditory', NULL, 'The scene is defined by a ''tearing, metallic scream''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5689, 1869, 'emotion', 'resolve', NULL, 'Hannah''s essence changes from joyful to a ''single, pure note of resolve'' as she accepts her fate.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5690, 1869, 'theme', 'sacrifice', NULL, 'Hannah offers herself as the true sacrifice, a cost greater than the destruction of the world itself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5691, 1869, 'emotion', 'agony', NULL, 'The Father''s light flickers with agony as he hesitates to accept the terrible price of victory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5692, 1870, 'theme', 'salvation', NULL, 'The Father''s destructive act is reframed as a ''desperate, final act of salvation'' for Xavier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5693, 1870, 'emotion', 'grief', NULL, 'The Father''s power is unleashed after a ''single, silent word of grief and acceptance''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5694, 1870, 'sensory', 'visual', NULL, 'The world dissolves into ''pure, agonizing light'' as it is unmade.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5695, 1870, 'theme', 'hope', NULL, 'Despite the destruction and loss, the scene ends with Xavier being designated as ''the hope''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:27:30.02706-05', '2026-02-28 23:27:30.02706-05');
INSERT INTO public.semantic_tags VALUES (5696, 1871, 'emotion', 'longing', NULL, 'Xavier''s determined search for his Father through the disorienting void.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5697, 1871, 'theme', 'perseverance', NULL, 'Xavier holds onto the promise like an ember, shielding it as he wanders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5698, 1871, 'sensory', 'disorientation', NULL, 'The feeling of drifting through the ''middle ground'' where realities blur.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5699, 1872, 'theme', 'sacrifice', NULL, 'The Father forfeits his own safety and escape to save the children.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5700, 1872, 'emotion', 'tension', NULL, 'The suspense of watching the test and the collapsing world, waiting for the Father''s decision.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5701, 1872, 'sensory', 'auditory', NULL, 'The dream world is filled with large crashing and thunderous noises.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5702, 1873, 'emotion', 'resolution', NULL, 'The test is passed, the connection is made, and the promise is fulfilled.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5703, 1873, 'theme', 'reunion', NULL, 'Xavier and his Father connect in the dreamscape, completing a circle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5704, 1873, 'sensory', 'presence', NULL, 'Xavier is no longer a fragment but a ''solid presence'' in the dream.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:28:24.025275-05', '2026-02-28 23:28:24.025275-05');
INSERT INTO public.semantic_tags VALUES (5705, 1874, 'theme', 'Transformation', NULL, 'The fundamental shift from a non-corporeal spirit to a physical, helpless infant.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5706, 1874, 'emotion', 'Overwhelm', NULL, 'Xavier''s shock at the sudden, intense sensory input of the mortal world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5707, 1874, 'sensory', 'Tactile', NULL, 'The shift from dark, wet warmth to sharp air and then a soft, warm cloth.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5708, 1875, 'emotion', 'Profound Love', NULL, 'The Father''s immediate, powerful, and almost painful love for his newborn son.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5709, 1875, 'theme', 'Parenthood', NULL, 'The moment of meeting one''s child for the first time and the reality of that connection.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5710, 1875, 'sensory', 'Kinesthetic', NULL, 'The physical weight of the baby in his father''s arms, making the moment real.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5711, 1876, 'theme', 'Connection', NULL, 'The mutual recognition and settling between father and son, one finding an anchor and the other finding purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5712, 1876, 'emotion', 'Certainty', NULL, 'The Father''s unshakeable, inexplicable knowledge that he will never let his son go.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5713, 1876, 'sensory', 'Auditory', NULL, 'The father''s voice is no longer a distant guide but a physical vibration that anchors Xavier to reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:29:11.461923-05', '2026-02-28 23:29:11.461923-05');
INSERT INTO public.semantic_tags VALUES (5714, 1877, 'emotion', 'Disorientation', NULL, 'Stephen experiences a complete loss of spatial and temporal awareness during the fall.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5715, 1877, 'theme', 'Isolation', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5716, 1877, 'sensory', 'Kinesthetic', NULL, 'The physical sensation of endless falling without any wind resistance.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5717, 1878, 'emotion', 'Hope', NULL, 'The voices of his friends provide a crucial anchor in the chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5718, 1878, 'theme', 'Fragile Connection', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5719, 1878, 'sensory', 'Auditory', NULL, 'The soundscape is defined by static and fragmented, urgent voices.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5720, 1879, 'emotion', 'Disgust', NULL, 'Stephen''s reaction to the sight and overwhelming smell of the Mi-Go corpses.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5721, 1879, 'theme', 'Alien Biology', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5722, 1879, 'sensory', 'Olfactory', NULL, 'The powerful, multi-layered stench of the alien bodies is a primary sensory detail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5723, 1880, 'emotion', 'Dread', NULL, 'The realization of having to cross a living ocean of creatures to reach an impossible structure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5724, 1880, 'theme', 'Imminent Danger', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5725, 1880, 'sensory', 'Visual', NULL, 'The sight of the impossibly-angled Pyramid and the massive, seething horde.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:30:12.228137-05', '2026-02-28 23:30:12.228137-05');
INSERT INTO public.semantic_tags VALUES (5726, 1881, 'emotion', 'desperation', NULL, 'Stephen''s choice to run into the horde is an act of pure desperation for cover.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5727, 1881, 'theme', 'survival', NULL, 'The entire beat is a chaotic struggle to stay alive amidst mindless violence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5728, 1881, 'sensory', 'auditory', NULL, 'The scene is filled with visceral sounds like teeth scraping bone and child-like screams.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5729, 1881, 'sensory', 'olfactory', NULL, 'The smell of old meat and steaming intestines establishes a repulsive, carnal atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5730, 1882, 'emotion', 'claustrophobia', NULL, 'The description of squeezing through the fissure evokes a feeling of being trapped.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5731, 1882, 'theme', 'pursuit', NULL, 'Stephen is being actively hunted by the gelatinous creatures, heightening the tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5732, 1882, 'sensory', 'tactile', NULL, 'The feeling of stone scraping against skin emphasizes the physical struggle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5733, 1883, 'emotion', 'shock', NULL, 'Stephen''s reaction to the creature''s violent, physics-defying death.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5734, 1883, 'theme', 'revelation', NULL, 'The true nature of the barrier is revealed, changing the objective from physical passage to seeking permission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5735, 1883, 'sensory', 'auditory', NULL, 'The creature''s death is a non-sound, a ''frequency'' that is felt rather than heard, indicating its unnatural power.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5736, 1883, 'theme', 'powerlessness', NULL, 'Stephen realizes his physical strength and weapon are useless against the barrier.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:00.047308-05', '2026-02-28 23:31:00.047308-05');
INSERT INTO public.semantic_tags VALUES (5737, 1884, 'emotion', 'tension', NULL, 'The atmosphere is thick with the tension of a mortal negotiating with a powerful, unpredictable cosmic being.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.semantic_tags VALUES (5738, 1884, 'theme', 'persuasion', NULL, 'Stephen uses psychological insight into Nyarlathotep''s nature (his boredom) rather than force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.semantic_tags VALUES (5739, 1884, 'sensory', 'tingling', NULL, 'The protagonist feels a physical sensation just from speaking the entity''s name.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.semantic_tags VALUES (5740, 1884, 'emotion', 'amusement', NULL, 'Nyarlathotep''s reaction is not anger or aggression, but cold, ancient amusement.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.semantic_tags VALUES (5741, 1885, 'theme', 'point of no return', NULL, 'The text explicitly states ''there''s no turning back,'' marking a significant, irreversible transition.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.semantic_tags VALUES (5742, 1885, 'sensory', 'auditory shift', NULL, 'The dramatic change from the cacophony of the horde to absolute silence emphasizes the crossing of a threshold.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.semantic_tags VALUES (5743, 1885, 'emotion', 'finality', NULL, 'The act of stepping through the barrier carries a weight of irreversible consequence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:31:56.677308-05', '2026-02-28 23:31:56.677308-05');
INSERT INTO public.semantic_tags VALUES (5744, 1886, 'sensory', 'Visual Paradox', NULL, 'The hallway''s geometry is described as impossible, constantly shifting and defying perspective.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5745, 1886, 'emotion', 'Horror', NULL, 'Stephen''s reaction to the visceral, yet ecstatic, mutilation of the worshippers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5746, 1886, 'theme', 'Sacred Pain', NULL, 'The worshippers are not prisoners but willing participants, finding purpose and clarity in what appears to be torture.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5747, 1887, 'theme', 'Revelation', NULL, 'The core of the beat is Nyarlathotep''s monologue, which completely reframes the history of Stephen''s family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5748, 1887, 'emotion', 'Shock', NULL, 'Stephen''s stunned reaction to learning the truth about Hannah and Whitney.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5749, 1887, 'theme', 'Identity', NULL, 'The revelation centers on the true identity of Whitney as the soul of Hannah, living the wrong life in the wrong body.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5750, 1888, 'emotion', 'Dread', NULL, 'Nyarlathotep''s warning about the ''darkness and hunger'' awaiting below instills a sense of foreboding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5751, 1888, 'theme', 'Psychological Warfare', NULL, 'Nyarlathotep explains his motive for the revelation is to make Stephen understand what he''s about to lose, using truth as a weapon.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5752, 1888, 'sensory', 'Temperature', NULL, 'The path downward is accompanied by a noticeable drop in temperature, signaling a descent into a worse place.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:32:37.755908-05', '2026-02-28 23:32:37.755908-05');
INSERT INTO public.semantic_tags VALUES (5753, 1889, 'emotion', 'dread', NULL, 'The feeling of descending into a hostile, unknown, and inescapable space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.semantic_tags VALUES (5754, 1889, 'theme', 'inevitability', NULL, 'All paths lead to the same place, and the collapsing tunnel removes any option of retreat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.semantic_tags VALUES (5755, 1889, 'sensory', 'claustrophobia', NULL, 'The physical and psychological experience of being in a shrinking, crushing space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.semantic_tags VALUES (5756, 1889, 'sensory', 'auditory', NULL, 'The grinding of stone and the unsettling sound of the mad piping.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.semantic_tags VALUES (5757, 1890, 'emotion', 'agony', NULL, 'An absolute, all-encompassing pain as every part of the body is unmade while consciousness remains.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.semantic_tags VALUES (5758, 1890, 'theme', 'dissolution', NULL, 'The systematic deconstruction of a being, moving from physical form to memories and finally to the core of identity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.semantic_tags VALUES (5759, 1890, 'sensory', 'somatic', NULL, 'Focuses on the internal, visceral sensations of the body being torn apart, beyond simple touch.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.semantic_tags VALUES (5760, 1890, 'emotion', 'isolation', NULL, 'The text emphasizes being ''Completely, utterly, impossibly alone'' in the void.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:33:24.869695-05', '2026-02-28 23:33:24.869695-05');
INSERT INTO public.semantic_tags VALUES (5761, 1891, 'emotion', 'isolation', NULL, 'Stephen experiences a cosmic loneliness that makes all prior feelings of being alone seem trivial.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.semantic_tags VALUES (5762, 1891, 'theme', 'loss of self', NULL, 'His identity, memories, and physical form are stripped away, leaving only bare, terrified awareness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.semantic_tags VALUES (5763, 1891, 'sensory', 'auditory', NULL, 'The scene transitions from silence to being filled with the disembodied whispers and screams of the lost.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.semantic_tags VALUES (5764, 1891, 'emotion', 'dread', NULL, 'The combination of the hungry Mist and the tormented echoes creates a profound sense of existential terror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.semantic_tags VALUES (5765, 1892, 'emotion', 'determination', NULL, 'Despite his terror and formlessness, Stephen exerts his will to survive by moving towards the only landmark available.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.semantic_tags VALUES (5766, 1892, 'theme', 'navigation by madness', NULL, 'Using a painful, maddening sound as a beacon signifies a journey deeper into cosmic horror, not away from it.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.semantic_tags VALUES (5767, 1892, 'sensory', 'auditory', NULL, 'The thin, mad piping becomes the dominant sensory element, growing from faint to deafening.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:34:10.82569-05', '2026-02-28 23:34:10.82569-05');
INSERT INTO public.semantic_tags VALUES (5768, 1893, 'emotion', 'agony', NULL, 'The pain of perceiving something fundamentally incomprehensible.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5769, 1893, 'theme', 'cosmic_horror', NULL, 'The entire description of Azathoth and the nature of reality is steeped in cosmic dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5770, 1893, 'sensory', 'auditory_overload', NULL, 'The ''mad music'' is the sound that holds reality together.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5771, 1894, 'emotion', 'recognition', NULL, 'Stephen''s instant, absolute recognition of Jamie''s spark, deeper than memory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5772, 1894, 'theme', 'revelation', NULL, 'The sudden understanding of their true purpose as the prison''s power source.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5773, 1894, 'theme', 'love_as_power', NULL, 'The realization that their love and separation is the energy that fuels the entire system.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5774, 1895, 'theme', 'convergence', NULL, 'The literal and metaphorical coming together of the two divine sparks.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5775, 1895, 'sensory', 'visual_cataclysm', NULL, 'The moment their sparks touch, everything explodes into light.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5776, 1895, 'emotion', 'union', NULL, 'The ultimate act of two separated halves becoming one.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:00.03246-05', '2026-02-28 23:35:00.03246-05');
INSERT INTO public.semantic_tags VALUES (5777, 1896, 'emotion', 'restlessness', NULL, 'The feeling of being unable to stop or be still.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5778, 1896, 'theme', 'impermanence', NULL, 'The focus on chasing the ''transient'' highlights a futile pursuit of things that do not last.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5779, 1896, 'sensory', 'kinesthetic', NULL, 'The dominant sensation is one of constant, forward motion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5780, 1897, 'emotion', 'calmness', NULL, 'The beginning of a shift from anxiety to peace.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5781, 1897, 'theme', 'mindfulness', NULL, 'The act of stopping to listen to the present moment is a core tenet of mindfulness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5782, 1897, 'sensory', 'auditory', NULL, 'The focus shifts from the feeling of movement to the act of listening.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5783, 1898, 'emotion', 'serenity', NULL, 'A deep, peaceful state of being is achieved.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5784, 1898, 'theme', 'existence', NULL, 'The ultimate goal is not to do, but simply to ''exist''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5785, 1898, 'sensory', 'interoception', NULL, 'Awareness turns inward to the physical sensation of breathing.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:35:59.332937-05', '2026-02-28 23:35:59.332937-05');
INSERT INTO public.semantic_tags VALUES (5786, 1899, 'emotion', 'Disorientation', NULL, 'Stephen struggles to connect his memory of being a cosmic entity with the mundane reality of a hospital room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5787, 1899, 'theme', 'Embodiment', NULL, 'The stark contrast between the infinite ''spark'' and the failing 46-year-old human body.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5788, 1899, 'sensory', 'Olfactory', NULL, 'The sterile, antiseptic smell is the first sensory detail that grounds Stephen in the new reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5789, 1900, 'emotion', 'Awe', NULL, 'Stephen''s breath catches as he sees the vast space station and the black hole outside the viewport.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5790, 1900, 'theme', 'Revelation', NULL, 'The moment of realization that they have not just moved to a new realm, but have escaped their prison entirely.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5791, 1900, 'sensory', 'Visual', NULL, 'The dominant sense is sight, taking in the impossible view of Elysium and Etheris.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5792, 1901, 'emotion', 'Awkwardness', NULL, 'The reunion between Stephen and Whitney/Hannah is hesitant and clumsy, reflecting their tangled history.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5793, 1901, 'theme', 'Family', NULL, 'The scene explores the theme of found and rediscovered family, forged across erased timelines.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5794, 1902, 'emotion', 'Relief', NULL, 'Stephen experiences a surge of ''pure, staggering relief'' upon seeing that Xavier is alive and safe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5795, 1902, 'theme', 'Exposition', NULL, 'Whitney provides crucial information about their location (Elysium) and the group that saved them (The Resistance).', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5796, 1903, 'theme', 'Frailty', NULL, 'Stephen''s physical collapse underscores his human vulnerability despite his cosmic experiences.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5797, 1903, 'emotion', 'Shock', NULL, 'Xavier''s jaw drops when he learns that Whitney, a stranger, is his older sister.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5798, 1903, 'sensory', 'Tactile', NULL, 'The sharp pain of Stephen''s face hitting the bed frame and the feeling of his nose gushing blood.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:36:55.521137-05', '2026-02-28 23:36:55.521137-05');
INSERT INTO public.semantic_tags VALUES (5799, 1904, 'emotion', 'terror', NULL, 'Xavier recounts the absolute terror of being alone in a dead universe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5800, 1904, 'theme', 'isolation', NULL, 'The core of Xavier''s trauma was the feeling of being alone forever in the dark.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5801, 1904, 'sensory', 'visual', NULL, 'The contrast between the sterile white corridor and the ''rocks and dead planets'' of Xavier''s memory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5802, 1905, 'emotion', 'love', NULL, 'The powerful, cathartic reunion of Stephen and Jamie, described as two halves of a circuit made complete.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5803, 1905, 'theme', 'revelation', NULL, 'The realization that their love and separation was the power source for the entire prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5804, 1905, 'sensory', 'olfactory', NULL, 'The scent of peaches and vanilla from Jamie''s hair, a sensory detail Stephen thought he''d lost forever.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5806, 1906, 'theme', 'consequence', NULL, 'The reunion wasn''t just personal; it had massive cosmic consequences, creating a new reality and weakening the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5807, 1906, 'theme', 'strategy', NULL, 'The council details the dangerous and precise military-style operations to extract souls.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5808, 1906, 'sensory', 'auditory', NULL, 'The distinct voices of the council members, from Hecate''s whisper to Tiamat''s rumble.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5809, 1907, 'emotion', 'grief', NULL, 'Stephen''s pain upon learning that TJ, Maeve, and Elara were consumed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5810, 1907, 'emotion', 'relief', NULL, 'The dual relief that his other friends are safe and his NPC wife is free.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5811, 1907, 'theme', 'loss', NULL, 'The final accounting of who was saved and who was lost, representing the price of their struggle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:37:48.544408-05', '2026-02-28 23:37:48.544408-05');
INSERT INTO public.semantic_tags VALUES (5812, 1908, 'emotion', 'Confusion', NULL, 'The family struggles to understand their new relationships and their blank pasts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5813, 1908, 'theme', 'Reconstruction', NULL, 'The family is actively piecing themselves together from fragments of past lives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5814, 1908, 'sensory', 'Visual', NULL, 'The viewport showing the silent drift of space and the distant black hole establishes a mood of isolated safety.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5815, 1908, 'emotion', 'Peace', NULL, 'Stephen feels a profound sense of peace for the first time in lifetimes, contrasting with the external danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5816, 1909, 'emotion', 'Vindication', NULL, 'Hannah feels her chosen name is ''right'' and ''birthed from love'', validating her entire struggle for identity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5817, 1909, 'theme', 'Identity', NULL, 'The beat explores the power of names, the rejection of imposed identities, and the journey to authenticity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5818, 1909, 'sensory', 'Auditory', NULL, 'The sound and feeling of the name ''Hannah'' on her tongue is a key sensory moment of self-realization.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5819, 1910, 'emotion', 'Hope', NULL, 'Xavier experiences the first spark of genuine, teenage hope since his ordeal began.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5820, 1910, 'theme', 'Reconnection', NULL, 'Xavier seeks to reconnect with his past life through video games, mirroring the larger effort of rescued souls reconnecting to their old world''s data.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5821, 1910, 'theme', 'Normalcy', NULL, 'Xavier''s desire for video games is a powerful pull towards a normal teenage life amidst cosmic chaos.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5822, 1911, 'emotion', 'Contentment', NULL, 'Stephen''s feeling that the moment is ''perfect'' despite all they have endured.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5823, 1911, 'theme', 'Family', NULL, 'The culmination of the scene, affirming the bonds of their real, chosen family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5824, 1911, 'sensory', 'Tactile', NULL, 'The physical contact of Jamie''s hand in Stephen''s and Stephen''s one-armed hug for Xavier ground the emotional moment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:38:57.385934-05', '2026-02-28 23:38:57.385934-05');
INSERT INTO public.semantic_tags VALUES (5825, 1912, 'emotion', 'despair', NULL, 'Stephen''s feeling of hopelessness when comparing the 12 souls saved to the 362,737 born daily.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.semantic_tags VALUES (5826, 1912, 'theme', 'futility', NULL, 'The core theme of the conversation is whether their small victories matter in the face of an ever-expanding problem.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.semantic_tags VALUES (5827, 1912, 'sensory', 'olfactory', NULL, 'Jamie''s vanilla-and-peach scent is a distinct sensory detail that cuts through the sterile environment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.semantic_tags VALUES (5828, 1912, 'sensory', 'kinesthetic', NULL, 'Stephen can feel the ''pulse of souls arriving'' in the ground beneath his feet.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.semantic_tags VALUES (5829, 1913, 'emotion', 'dread', NULL, 'Stephen''s reaction to the news is a physical tightening of his stomach, described as something older than fear.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.semantic_tags VALUES (5830, 1913, 'theme', 'revelation', NULL, 'The arrival of Benji and Lady Illkeserod brings a sudden, personal, and world-altering piece of information.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.semantic_tags VALUES (5831, 1913, 'sensory', 'auditory', NULL, 'The ''hiss'' of the door opening signals a dramatic interruption and a shift in the scene''s tone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:40:25.261074-05', '2026-02-28 23:40:25.261074-05');
INSERT INTO public.semantic_tags VALUES (5832, 1914, 'emotion', 'trauma', NULL, 'Stephen''s involuntary and vivid flashback to a past war.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.semantic_tags VALUES (5833, 1914, 'theme', 'confronting the past', NULL, 'Stephen is physically faced with an enemy from a previous life, forcing him to relive past conflicts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.semantic_tags VALUES (5834, 1914, 'sensory', 'olfactory', NULL, 'The memory of the air tasting like ''copper and fire''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.semantic_tags VALUES (5835, 1914, 'sensory', 'auditory', NULL, 'The memory of a chant that made the ground vibrate.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.semantic_tags VALUES (5836, 1915, 'emotion', 'terror', NULL, 'Todd''s brief moment of focus is filled with terror as he recognizes Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.semantic_tags VALUES (5837, 1915, 'theme', 'revelation', NULL, 'A critical piece of cosmic lore, the cosmic seed, is revealed through Todd''s madness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.semantic_tags VALUES (5838, 1915, 'sensory', 'auditory', NULL, 'Todd''s voice is described as a whisper, then a high, brittle laugh, and finally a cracking shout.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.semantic_tags VALUES (5839, 1915, 'emotion', 'urgency', NULL, 'Stephen''s pulse quickens, indicating the high stakes of the newly revealed information.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:05.773463-05', '2026-02-28 23:41:05.773463-05');
INSERT INTO public.semantic_tags VALUES (5840, 1916, 'emotion', 'anxiety', NULL, 'Stephen''s anxiety stems from the slow progress and the ticking clock of Yaldabaoth''s expansion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.semantic_tags VALUES (5841, 1916, 'theme', 'powerlessness', NULL, 'The nightmares emphasize Stephen''s role as a helpless observer to a cosmic catastrophe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.semantic_tags VALUES (5842, 1916, 'sensory', 'visual', NULL, 'The dream imagery of the prison pulsing, growing, and consuming souls is a powerful visual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.semantic_tags VALUES (5843, 1917, 'emotion', 'guilt', NULL, 'Stephen expresses deep, lingering guilt over killing Todd, despite it being in another timeline.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.semantic_tags VALUES (5844, 1917, 'theme', 'comfort', NULL, 'Jamie provides physical and emotional comfort, acting as a grounding force for Stephen.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.semantic_tags VALUES (5845, 1917, 'sensory', 'tactile', NULL, 'The physical contact between Stephen and Jamie (shoulders touching, holding hands, head on shoulder) is central to the beat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.semantic_tags VALUES (5846, 1917, 'theme', 'memory', NULL, 'The conversation questions the nature of memory and trauma across different realities or ''resets''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:41:49.981048-05', '2026-02-28 23:41:49.981048-05');
INSERT INTO public.semantic_tags VALUES (5847, 1918, 'emotion', 'Hope', NULL, 'The discovery of the Cosmic Seed offers a tangible, physics-based solution, sparking initial optimism.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5848, 1918, 'theme', 'Discovery', NULL, 'The team analyzes new, critical information that could change the course of their struggle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5849, 1918, 'sensory', 'Visual', NULL, 'The scene is centered around the characters watching and interpreting the grainy, silent holographic footage.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5850, 1919, 'emotion', 'Dread', NULL, 'Hope is extinguished by the revelation of the impossible condition for the prison''s success.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5851, 1919, 'theme', 'Cosmic Triage', NULL, 'The discussion becomes a cosmic version of the trolley problem: sacrifice trillions to save all of reality, or risk everything for a rescue that is doomed to fail.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5852, 1919, 'sensory', 'Auditory', NULL, 'The weight of the scene is carried by Lady Illkeserod''s quiet, heavy words and the ensuing silence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5853, 1920, 'emotion', 'Determination', NULL, 'Stephen shifts the mood from despair to focused resolve by proposing a daring and unexpected alternative.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5854, 1920, 'theme', 'Duality', NULL, 'The core of the new plan is to separate the host (Sam) from the parasite (Yaldabaoth), changing the nature of the enemy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5855, 1920, 'theme', 'Paradigm Shift', NULL, 'Stephen''s idea completely reframes the problem from containment to a form of healing or exorcism.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:42:34.313669-05', '2026-02-28 23:42:34.313669-05');
INSERT INTO public.semantic_tags VALUES (5856, 1921, 'emotion', 'determination', NULL, 'Jamie''s unwavering resolve to join Stephen, contrasted with Xavier and Hannah''s determination to stop them.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5857, 1921, 'theme', 'loyalty', NULL, 'The entire family demonstrates loyalty, but their expressions of it are in direct conflict.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5858, 1921, 'sensory', 'auditory', NULL, 'The scene is punctuated by Xavier''s flat tone and the jarring sound of his chair being knocked over.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5859, 1922, 'emotion', 'anger', NULL, 'Hannah''s eyes flash with anger and her voice cracks, while Xavier''s face darkens with frustration and betrayal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5860, 1922, 'theme', 'sacrifice', NULL, 'The central argument is about who has the right to make sacrifices for the family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5861, 1922, 'theme', 'parental authority', NULL, 'Stephen asserts his authority (''That''s final''), which is immediately and vehemently challenged by his daughter.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5862, 1923, 'emotion', 'resignation', NULL, 'A sense of grim acceptance settles as the plan is finalized and the characters face the two-week wait.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5863, 1923, 'theme', 'preparation', NULL, 'The focus shifts from emotional conflict to the practical and magical preparations needed for the dangerous mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5864, 1923, 'emotion', 'foreboding', NULL, 'The mention of saying goodbye and this being their ''last mission'' creates a heavy sense of dread for the future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5865, 1923, 'sensory', 'visual', NULL, 'The silent conversation passing between Lady Illkeserod and Lady Osilari through looks alone.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:43:35.020819-05', '2026-02-28 23:43:35.020819-05');
INSERT INTO public.semantic_tags VALUES (5866, 1924, 'theme', 'preparation', NULL, 'The team undertakes magical, logistical, and emotional preparations for their perilous journey.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.semantic_tags VALUES (5867, 1924, 'emotion', 'dread', NULL, 'The quiet, sleepless nights between Stephen and Jamie are filled with unspoken fear and the heavy weight of their mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.semantic_tags VALUES (5868, 1924, 'theme', 'moral ambiguity', NULL, 'Jamie raises the question of whether their target wants to be ''saved'', reframing a potential rescue as a possible cruelty.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.semantic_tags VALUES (5869, 1924, 'sensory', 'tactile', NULL, 'The feeling of the wards burning as they are applied, which settles into the feeling of armor.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.semantic_tags VALUES (5870, 1925, 'emotion', 'love', NULL, 'Expressed in the tense, emotional farewells between Stephen and his children, Xavier and Hannah.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.semantic_tags VALUES (5871, 1925, 'theme', 'threshold', NULL, 'The act of stepping through the portal represents crossing a point of no return into immense danger.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.semantic_tags VALUES (5872, 1925, 'sensory', 'olfactory', NULL, 'The portal emits the strange, conceptual scents of ''burned mathematics'' and ''fading hope''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.semantic_tags VALUES (5873, 1925, 'sensory', 'visual', NULL, 'The portal is described with unsettling imagery, having colors that ''didn’t belong to any sane spectrum''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:44:22.238206-05', '2026-02-28 23:44:22.238206-05');
INSERT INTO public.semantic_tags VALUES (5874, 1926, 'emotion', 'dread', NULL, 'Stephen''s ''stomach sank'' and the situation is described as ''terrifying''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.semantic_tags VALUES (5875, 1926, 'theme', 'impassable barrier', NULL, 'The portal is not just gone, but sealed by a powerful enemy, creating an seemingly impossible obstacle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.semantic_tags VALUES (5876, 1926, 'sensory', 'kinesthetic', NULL, 'The platform ''hummed beneath our feet,'' providing a tactile and auditory sensation in a visual void.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.semantic_tags VALUES (5877, 1926, 'emotion', 'confusion', NULL, 'Benji''s initial reaction is that the situation ''doesn''t make sense''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.semantic_tags VALUES (5878, 1927, 'emotion', 'reluctance', NULL, 'Stephen''s immediate and forceful rejection of the plan (''Absolutely not.'') highlights his extreme hesitation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.semantic_tags VALUES (5879, 1927, 'theme', 'desperate measures', NULL, 'The team agrees to summon an entity that previously tried to kill one of them because it is the only path forward.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.semantic_tags VALUES (5880, 1927, 'sensory', 'visual', NULL, 'Lady Osilari creates ''symbols appearing in the air around Benji like armor made of light''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.semantic_tags VALUES (5881, 1927, 'emotion', 'resignation', NULL, 'Benji''s peaceful expression as he is warded shows his acceptance of the potentially fatal risk.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:45:11.072587-05', '2026-02-28 23:45:11.072587-05');
INSERT INTO public.semantic_tags VALUES (5882, 1928, 'emotion', 'agony', NULL, 'The physical and essential torment Benji endures as he is torn apart.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5883, 1928, 'theme', 'protection', NULL, 'Lady Osilari''s wards are the only thing that prevents Benji''s complete erasure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5884, 1928, 'sensory', 'auditory', NULL, 'The scene is filled with visceral sounds: a wet gurgle, snapping towels, percussive pops, and a hurricane rewinding.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5885, 1928, 'sensory', 'body horror', NULL, 'The graphic description of Benji''s body splitting open, erupting with extra limbs, ichor, and eyes.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5886, 1929, 'emotion', 'defiance', NULL, 'Lady Illkeserod''s sudden and absolute refusal of Nyarlathotep''s terms.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5887, 1929, 'theme', 'sacrifice', NULL, 'Benji willingly offers himself up immediately, escalating the terms of the deal himself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5888, 1929, 'theme', 'negotiation', NULL, 'The core of the beat is the tense bargaining for passage with a cosmic entity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5889, 1930, 'emotion', 'boredom', NULL, 'Nyarlathotep''s motivation shifts entirely because he finds willing sacrifice uninteresting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5890, 1930, 'theme', 'debt', NULL, 'A new, infinite debt is established as a potential consequence of the group''s success.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5891, 1930, 'sensory', 'visual', NULL, 'The portal is described with ''twisted light'' and ''wrong colors'', indicating a corrupted or alien reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5892, 1930, 'theme', 'departure', NULL, 'The scene concludes with the team taking a decisive, one-way step into enemy territory.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:03.077546-05', '2026-02-28 23:46:03.077546-05');
INSERT INTO public.semantic_tags VALUES (5893, 1931, 'emotion', 'dread', NULL, 'The feeling of ''wrongness'' and hostile reality creates a deep sense of dread.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5894, 1931, 'theme', 'reality-bending', NULL, 'The corridor and substrate actively change and rewrite reality to attack the intruders.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5895, 1931, 'sensory', 'auditory', NULL, 'The walls are described as being made of ''crystallized screams''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5896, 1932, 'emotion', 'horror', NULL, 'The team''s reaction to the throne of living souls and the trillions being tortured.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5897, 1932, 'theme', 'eternal-suffering', NULL, 'Souls are not just punished, but refined through endless, looping torment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5898, 1932, 'sensory', 'visual', NULL, 'The imagery of the throne made of living people and billions of chained souls is a powerful visual.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5899, 1933, 'emotion', 'resolve', NULL, 'Despite their fear, the team stands firm and commits to their desperate plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5900, 1933, 'theme', 'sacrifice', NULL, 'The team willingly offers themselves up for consumption, a form of strategic self-sacrifice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5901, 1933, 'sensory', 'auditory', NULL, 'Yaldabaoth''s voice is described as ''honey poured over razor blades''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5902, 1934, 'theme', 'cosmic-horror', NULL, 'The experience of being inside a god''s digestive system as it experiences ecstasy.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5903, 1934, 'emotion', 'ecstasy', NULL, 'From Yaldabaoth''s perspective, the consumption is a moment of profound, overwhelming pleasure.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5904, 1934, 'sensory', 'tactile', NULL, 'The feeling of crushing pressure from the god''s moans and the corrosive nature of his essence.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:46:50.752935-05', '2026-02-28 23:46:50.752935-05');
INSERT INTO public.semantic_tags VALUES (5905, 1935, 'emotion', 'horror', NULL, 'The discovery of Sam''s condition is described as worse than pain.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5906, 1935, 'theme', 'endurance', NULL, 'Despite the torture, Sam''s divine spark is still burning, showing his resilience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5907, 1935, 'sensory', 'auditory', NULL, 'The scene is dominated by Sam''s constant, inhuman screaming.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5908, 1936, 'emotion', 'desperation', NULL, 'The group mounts a desperate defense against overwhelming odds.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5909, 1936, 'theme', 'teamwork', NULL, 'Osilari, Benji, and Jamie coordinate their different abilities to hold off the tentacles.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5910, 1936, 'sensory', 'visual', NULL, 'The scene is filled with the imagery of flaring symbols, black tentacles slicing the air, and chaotic movement.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5911, 1937, 'emotion', 'shock', NULL, 'The sudden reversal where the rescued person becomes the attacker is jarring and unexpected.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5912, 1937, 'theme', 'subversion', NULL, 'The heroic rescue attempt is subverted, leading to a worse outcome for the rescuer.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5913, 1937, 'sensory', 'tactile', NULL, 'The sharp, wrong pain of the tentacle wounds and the pressure of Sam''s hands on Stephen''s throat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5914, 1938, 'emotion', 'confusion', NULL, 'Stephen''s state of being in two places at once creates a disorienting experience.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5915, 1938, 'theme', 'mystery', NULL, 'Sam''s trance and Stephen''s dual consciousness introduce new, unexplained phenomena.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5916, 1938, 'sensory', 'proprioceptive', NULL, 'The feeling of being both unconscious on the ground and consciously present somewhere else.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:01.749225-05', '2026-02-28 23:48:01.749225-05');
INSERT INTO public.semantic_tags VALUES (5917, 1939, 'theme', 'deception', NULL, 'The seemingly peaceful pasture and flock hide a horrifying parasitic reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5918, 1939, 'emotion', 'dread', NULL, 'Stephen''s discovery of the writhing tentacles underneath the sheep.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5919, 1939, 'sensory', 'olfactory', NULL, 'The smell of sweat and festering cheese permeates the unreal environment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5920, 1940, 'theme', 'corruption', NULL, 'The parasites actively twist Sam''s perception, turning an attempted rescue into a perceived attack.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5921, 1940, 'emotion', 'paranoia', NULL, 'Sam''s sudden, violent shift from welcoming host to aggressive defender against a non-existent threat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5922, 1940, 'sensory', 'auditory', NULL, 'The sounds of a massive battle happening ''outside'' the realm bleed through, creating tension.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5923, 1941, 'emotion', 'agony', NULL, 'Sam''s profound suffering as each parasite, which he loved as a sheep, is destroyed.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5924, 1941, 'theme', 'revelation', NULL, 'Each death tears a memory free, forcing Sam to confront the buried truth of his choice.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5925, 1941, 'sensory', 'auditory', NULL, 'The awful, non-organic shrieks of the parasites as their facades are torn away.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5926, 1942, 'theme', 'atonement', NULL, 'Sam takes the final action himself, a necessary step to reclaim his agency and accept his role.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5927, 1942, 'emotion', 'acceptance', NULL, 'Sam''s final state is one of terrible, complete understanding, accepting the horror of what he has become and done.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5928, 1942, 'sensory', 'visual', NULL, 'The entire reality fractures and cracks apart, a visual metaphor for the shattering of Sam''s delusion.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:48:59.752249-05', '2026-02-28 23:48:59.752249-05');
INSERT INTO public.semantic_tags VALUES (5929, 1943, 'emotion', 'dread', NULL, 'The scene opens with a feeling of inevitability and foreboding as the inescapable ritual begins.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5930, 1943, 'theme', 'inevitability', NULL, 'The ritual starts regardless of Sam''s pleas, portrayed as a necessary, unstoppable force.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5931, 1943, 'sensory', 'pressure', NULL, 'The ritual is first felt as a physical pressure building from two directions at once.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5932, 1944, 'emotion', 'agony', NULL, 'Describes the extreme physical, divine, and emotional suffering of Sam during the extraction.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5933, 1944, 'theme', 'deconstruction', NULL, 'Sam is not just being injured; the very architecture of his godhood is being unmade.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5934, 1944, 'sensory', 'auditory', NULL, 'The sound is described as a physical, violent shockwave, with snapping tendons and screams.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5935, 1944, 'emotion', 'horror', NULL, 'The visceral reactions of Jamie and Benji (vomiting, collapsing) underscore the gruesome nature of the event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5936, 1945, 'emotion', 'acceptance', NULL, 'Sam''s emotional state shifts from pain to a quiet acceptance of his fate and a desire to fade away.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5937, 1945, 'theme', 'redemption', NULL, 'Sam''s final words are an apology and a moment of clarity, a final act of taking responsibility before his end.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5938, 1945, 'theme', 'containment', NULL, 'The focus shifts from extraction to ensuring the now-vulnerable parasite is permanently imprisoned.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5939, 1945, 'sensory', 'visual', NULL, 'The imagery of Sam''s body dissolving like ash and leaving a single, pure spark of light.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:49:55.754688-05', '2026-02-28 23:49:55.754688-05');
INSERT INTO public.semantic_tags VALUES (5940, 1946, 'emotion', 'anticipation', NULL, 'The group waits for the seed to activate, knowing they have very little time to act once it does.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5941, 1946, 'theme', 'containment', NULL, 'The entire purpose of the cosmic seed is to create an inescapable prison for a conceptual entity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5942, 1946, 'sensory', 'visual', NULL, 'The seed blooms into an explosion of fractal geometry, a reality folding into itself.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5943, 1946, 'emotion', 'desperation', NULL, 'The parasite''s fury as it senses its impending imprisonment.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5944, 1947, 'emotion', 'panic', NULL, 'The freed souls are not malicious, but their collective, panicked stampede creates a deadly obstacle.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5945, 1947, 'theme', 'moral_compromise', NULL, 'The protagonists are forced to harm and trample innocent victims to ensure their own survival.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5946, 1947, 'sensory', 'auditory', NULL, 'The overwhelming sound of trillions of panicked voices fills the void.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5947, 1947, 'sensory', 'tactile', NULL, 'The feeling of bodies breaking apart like wet clay under the group''s hands.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5948, 1948, 'emotion', 'horror', NULL, 'The visceral shock of watching dozens of souls being bisected by the closing portal.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5949, 1948, 'theme', 'consequence', NULL, 'Even in victory and escape, there is a brutal, bloody cost that leaves the survivors scarred.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5950, 1948, 'sensory', 'tactile', NULL, 'The shockwave from Etheris shattering makes the characters'' bones ache, a physical manifestation of a cosmic event.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5951, 1948, 'theme', 'rebirth', NULL, 'Etheris itself is reborn, shattering its prison form and rejoining reality as a natural, if damaged, space.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:50:49.965476-05', '2026-02-28 23:50:49.965476-05');
INSERT INTO public.semantic_tags VALUES (5952, 1949, 'emotion', 'somberness', NULL, 'The atmosphere is that of a funeral, with the assembled gods and family gathered in quiet, respectful mourning.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5953, 1949, 'theme', 'remembrance', NULL, 'The entire gathering is for the purpose of honoring and releasing the last remnant of a fallen comrade.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5954, 1949, 'sensory', 'visual', NULL, 'Strong visuals of the platform over an ''ocean of stars'', the ''makeshift cities of light'' of the camps, and the ''dying galaxy'' of Etheris.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5955, 1950, 'emotion', 'grief', NULL, 'Expressed through Xavier''s tears and the narrator''s inability to speak, describing the words as ''broken glass'' in his throat.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5956, 1950, 'theme', 'letting go', NULL, 'The physical act of pouring the spark out and watching it dissolve symbolizes the final release of Sam from his long suffering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5957, 1950, 'sensory', 'olfactory', NULL, 'Jamie''s personal scent of vanilla-and-peaches mixes with the cosmic ''smell of raw creation''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5958, 1951, 'emotion', 'acceptance', NULL, 'The group accepts Sam''s choice to dissolve rather than reincarnate, honoring it as his final peace.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5959, 1951, 'theme', 'duty', NULL, 'Jamie''s line, ''We''ve got work to do,'' shifts the scene''s focus from mourning the past to facing the responsibilities of the future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5960, 1951, 'sensory', 'auditory', NULL, 'The beat is defined by the breaking of a long silence, first by Jamie''s voice and then by the narrator''s quiet agreement, all against the background ''hum'' of the universe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5961, 1951, 'emotion', 'peace', NULL, 'Sam''s final state is described as ''the ultimate peace'' and ''the final rest'', a resolution to his cosmic suffering.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:52:16.263632-05', '2026-02-28 23:52:16.263632-05');
INSERT INTO public.semantic_tags VALUES (5962, 1952, 'theme', 'bureaucracy', NULL, 'The gods are bogged down in cosmic zoning laws and forms, highlighting the inadequacy of their current systems.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5963, 1952, 'emotion', 'overwhelm', NULL, 'The sheer scale of the problem (septillions of souls) creates a sense of futility and frustration.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5964, 1952, 'sensory', 'visual', NULL, 'A perfect, rotating replica of the solar system is projected above the table, making the prison a tangible presence in the room.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5965, 1953, 'theme', 'paradigm shift', NULL, 'Hannah''s proposal completely changes the conversation from slow extraction to proactive, internal intervention.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5966, 1953, 'emotion', 'inspiration', NULL, 'A radical new idea cuts through the bureaucratic stalemate, sparking a new sense of possibility.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5967, 1954, 'theme', 'sacrifice', NULL, 'The family volunteers to return to a prison they just escaped, committing to a potentially eternal mission.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5968, 1954, 'emotion', 'determination', NULL, 'Xavier''s motivation to save Tiffany solidifies his resolve, and the family unit follows suit.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5969, 1955, 'theme', 'unity', NULL, 'The family stands together, physically and metaphorically, united in their shared purpose for the first time.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5970, 1955, 'emotion', 'resolve', NULL, 'After the chaos of the meeting, a quiet, shared certainty settles over the family.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:53:20.13484-05', '2026-02-28 23:53:20.13484-05');
INSERT INTO public.semantic_tags VALUES (5971, 1956, 'emotion', 'anxiety', NULL, 'Reflecting Xavier''s terror that Tiffany might forget him due to the ''reshuffling''.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5972, 1956, 'theme', 'normalcy', NULL, 'The act of making coffee and living in a small apartment is a deliberate choice to find normalcy after cosmic trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5973, 1956, 'sensory', 'olfactory', NULL, 'The smell of coffee fills the kitchen, grounding the scene in a familiar, comforting scent.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5974, 1957, 'emotion', 'resolve', NULL, 'Jamie''s speech solidifies their shared purpose, moving Stephen from doubt to determination.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5975, 1957, 'theme', 'responsibility', NULL, 'The core theme is that their unique suffering has given them a unique responsibility to help others.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5976, 1957, 'sensory', 'tactile', NULL, 'Jamie takes Stephen''s hand, a physical act of connection and reassurance that reinforces her words.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5977, 1957, 'theme', 'empathy', NULL, 'Their ability to help is rooted in their deep empathy for those who are still trapped as they once were.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5978, 1958, 'emotion', 'levity', NULL, 'Hannah''s teasing and Xavier''s absurdly practical idea for a cross-dimensional Discord server lighten the mood.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5979, 1958, 'theme', 'decision', NULL, 'The scene culminates in the confirmation of their momentous decision to return to the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5980, 1958, 'sensory', 'visual', NULL, 'Hannah''s casual hovering adds a touch of the supernatural to the otherwise domestic setting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:54:41.360965-05', '2026-02-28 23:54:41.360965-05');
INSERT INTO public.semantic_tags VALUES (5981, 1959, 'theme', 'confronting obstacles', NULL, 'The council immediately addresses the immense technical and metaphysical challenges of their plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5982, 1959, 'emotion', 'apprehension', NULL, 'Murmurs ripple through the crowd, and Thoth voices serious concerns, setting a tone of high stakes and uncertainty.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5983, 1959, 'sensory', 'auditory', NULL, 'The scene is filled with sound: the hum of divine power, murmurs, and the distinct voices of several gods.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5984, 1960, 'theme', 'infiltration', NULL, 'The plan involves creating deep cover identities and using avatars to blend into the target reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5985, 1960, 'sensory', 'visual', NULL, 'Lady Illkeserod uses projections of the solar system, Earth, and the avatars to illustrate the plan.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5986, 1960, 'emotion', 'excitement', NULL, 'Benji''s excitement at getting to be an avatar parent provides a moment of lightheartedness.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5987, 1961, 'theme', 'empowerment', NULL, 'The core of the plan is revealed: not hacking the system, but restoring the family''s true, original divine powers.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5988, 1961, 'emotion', 'revelation', NULL, 'The family learns the true nature and origin of the powers they are about to wield.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5989, 1962, 'theme', 'personal stakes', NULL, 'Xavier''s question grounds the cosmic plan in a very human, personal concern about his relationship with Tiffany.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5990, 1962, 'emotion', 'relief', NULL, 'Xavier lets out a breath he''d been holding upon learning Tiffany will remember him.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5991, 1963, 'theme', 'consensus', NULL, 'Despite the risks, the divine council shows near-unanimous agreement, signifying their collective resolve.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5992, 1963, 'emotion', 'resolution', NULL, 'The vote concludes the debate and solidifies the path forward, moving from discussion to action.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5993, 1963, 'sensory', 'visual', NULL, 'The vote is a powerful visual: a sea of not just hands, but claws, tentacles, and wings of fire and shadow.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5994, 1964, 'theme', 'transformation', NULL, 'The ritual is a literal and metaphysical transformation, rewriting history and reawakening dormant divinity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5995, 1964, 'emotion', 'awe', NULL, 'The scale of the ritual, with uncountable gods channeling power and reality itself splitting, inspires a sense of awe.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5996, 1964, 'sensory', 'tactile', NULL, 'The experience is described physically: the syllables of the incantation ''taste'' like starlight, and Stephen ''feels'' his history rewriting.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:55:32.26533-05', '2026-02-28 23:55:32.26533-05');
INSERT INTO public.semantic_tags VALUES (5997, 1965, 'emotion', 'terror', NULL, 'Stephen''s raw scream upon realizing he''s been dragged back into the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (5998, 1965, 'theme', 'imprisonment', NULL, 'The feeling of being trapped in ''the cage'' again, even if it looks like a normal life.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (5999, 1965, 'sensory', 'tactile', NULL, 'The warmth and reality of Jamie''s hand on Stephen''s shoulder, contrasting with the simulated world.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (6000, 1966, 'emotion', 'relief', NULL, 'Stephen''s profound relief when he realizes his memories of Elysium are not fading.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (6001, 1966, 'theme', 'memory', NULL, 'The permanence and clarity of memory are the key difference in this iteration of the prison.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (6002, 1966, 'sensory', 'auditory', NULL, 'The sounds of Kate Bush and the children''s bickering create a sense of grounded, albeit strange, domesticity.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (6003, 1967, 'emotion', 'purpose', NULL, 'Stephen and Jamie find a new mission in their imprisonment: to awaken others.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (6004, 1967, 'theme', 'narrative as power', NULL, 'Jamie''s idea that stories can be used as a weapon or tool to break others out of the simulation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (6005, 1967, 'sensory', 'visual', NULL, 'The sight of the mundane suburban Florida landscape, populated by NPCs and hidden awakened souls.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:56:54.515641-05', '2026-02-28 23:56:54.515641-05');
INSERT INTO public.semantic_tags VALUES (6006, 1968, 'emotion', 'Relief', NULL, 'Xavier''s relief that his friend Tiffany remembers him is palpable and drives the initial conversation.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.semantic_tags VALUES (6007, 1968, 'theme', 'Family Dynamics', NULL, 'The scene establishes the chaotic, loving, and deeply strange nature of this family''s interactions.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.semantic_tags VALUES (6008, 1968, 'sensory', 'Olfactory', NULL, 'The implied smell of ''ultimate breakfast burritos'' made with ''every ingredient we owned'' defines the chaotic atmosphere.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.semantic_tags VALUES (6009, 1969, 'theme', 'Strategy', NULL, 'The family shifts from chaotic breakfast to long-term strategic planning for their immortal lives.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.semantic_tags VALUES (6010, 1969, 'emotion', 'Seriousness', NULL, 'Stephen''s tone becomes serious as he lays down the foundational rules for their survival and purpose.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.semantic_tags VALUES (6011, 1969, 'theme', 'Immortality', NULL, 'The rules directly address the challenges of being immortal, such as maintaining secrecy and finding purpose over millennia.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.semantic_tags VALUES (6012, 1969, 'sensory', 'Auditory', NULL, 'The beat is dominated by Stephen''s voice dictating the rules and the family''s verbal responses.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:57:53.114976-05', '2026-02-28 23:57:53.114976-05');
INSERT INTO public.semantic_tags VALUES (6013, 1970, 'emotion', 'anxiety', NULL, 'Stephen''s fear of losing his new reality is palpable and drives the initial action of the scene.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.semantic_tags VALUES (6014, 1970, 'theme', 'fragility_of_peace', NULL, 'The scene opens with perfect normalcy, which is immediately threatened by internal doubt and trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.semantic_tags VALUES (6015, 1970, 'sensory', 'auditory', NULL, 'The silence of the house is contrasted with the hum of the PC fans, emphasizing Stephen''s isolation with his thoughts.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.semantic_tags VALUES (6016, 1971, 'emotion', 'catharsis', NULL, 'The act of writing is a feverish, intense release of pent-up memories and trauma.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.semantic_tags VALUES (6017, 1971, 'theme', 'truth_in_fiction', NULL, 'Stephen is hiding the literal truth of his experiences within the genres of science fiction and cosmic horror.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.semantic_tags VALUES (6018, 1972, 'emotion', 'resolution', NULL, 'As the writing ends, Stephen''s anxiety is replaced by a calm readiness for the future.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.semantic_tags VALUES (6019, 1972, 'theme', 'new_beginnings', NULL, 'With the story told and the fear quelled, Stephen and Jamie are ready to begin their mission in earnest.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.semantic_tags VALUES (6020, 1972, 'sensory', 'olfactory', NULL, 'The smell of fresh coffee signifies the return to a safe, domestic reality.', 'gemini', 'gemini-2.5-pro', '2026-02-28 23:58:38.923723-05', '2026-02-28 23:58:38.923723-05');
INSERT INTO public.semantic_tags VALUES (6021, 1973, 'theme', 'Ritual', NULL, 'Kai''s planting is described with ''practiced gentleness of ritual''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6022, 1973, 'emotion', 'Serenity', NULL, 'The scene is quiet and focused, with Kai and the androids working in harmony.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6023, 1973, 'sensory', 'Visual', NULL, 'Description of the three suns, bruised purple sky, and colors of copper and gold.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6024, 1974, 'emotion', 'Reverence', NULL, 'Kai speaks to the plants ''the way priests spoke to gods''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6025, 1974, 'theme', 'Connection', NULL, 'Highlights Kai''s deep, personal bond with each individual plant.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6026, 1974, 'emotion', 'Love', NULL, 'Kai feels a love for the plants that ''expected nothing in return''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6027, 1975, 'theme', 'Anomaly', NULL, 'The discovery of fear in a plant is described as ''something new''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6028, 1975, 'emotion', 'Concern', NULL, 'The android''s report and Kai''s subsequent investigation show a shift from peace to worry.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6029, 1975, 'sensory', 'Empathic', NULL, 'Kai doesn''t see or hear the problem, he feels it as an emotion from the plant.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:54:52.742088-05', '2026-03-01 00:54:52.742088-05');
INSERT INTO public.semantic_tags VALUES (6030, 1976, 'emotion', 'foreboding', NULL, 'The tension builds through unexplained seismic shocks and sounds, creating a powerful sense of impending doom.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:55:30.461764-05', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.semantic_tags VALUES (6031, 1976, 'theme', 'anomaly', NULL, 'The events defy all known patterns and data for the planet, representing a break from the established order.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:55:30.461764-05', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.semantic_tags VALUES (6032, 1976, 'sensory', 'auditory', NULL, 'The deep, subterranean grinding and tearing sound is a key source of horror before anything is seen.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:55:30.461764-05', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.semantic_tags VALUES (6033, 1976, 'sensory', 'tactile', NULL, 'The physical sensation of the ground lurching violently conveys the power of the unseen threat.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:55:30.461764-05', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.semantic_tags VALUES (6034, 1977, 'emotion', 'horror', NULL, 'The description of the creatures is designed to evoke visceral disgust and terror.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:55:30.461764-05', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.semantic_tags VALUES (6035, 1977, 'theme', 'violation of nature', NULL, 'The creatures are described as ''biological blasphemy'' and ''wrong'' in a fundamental, tumorous way, defying natural law.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:55:30.461764-05', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.semantic_tags VALUES (6036, 1977, 'sensory', 'visual', NULL, 'The grotesque imagery of oozing carapaces, tangled limbs, and snapping joints is the primary focus.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:55:30.461764-05', '2026-03-01 00:55:30.461764-05');
INSERT INTO public.semantic_tags VALUES (6037, 1978, 'emotion', 'helplessness', NULL, 'Kai can only watch as everything he cares about is destroyed.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6038, 1978, 'theme', 'loss', NULL, 'The systematic destruction of the plants represents the final loss for Kai, who has already lost his family.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6039, 1978, 'sensory', 'auditory', NULL, 'The scene is filled with the sounds of destruction: an explosion, chittering, and sparking metal.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6040, 1979, 'emotion', 'rage', NULL, 'Kai''s fear is replaced by a pure, incandescent rage that is powerful enough to warp reality.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6041, 1979, 'theme', 'transformation', NULL, 'Kai transforms from a passive victim into an active, powerful force of nature.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6042, 1979, 'sensory', 'tactile', NULL, 'The air itself physically changes in response to Kai''s emotional outburst.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6043, 1980, 'emotion', 'empowerment', NULL, 'Kai actively seizes control, using a newfound power to fight back.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6044, 1980, 'theme', 'retribution', NULL, 'Nature, through Kai, enacts its revenge upon the destructive swarm.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6045, 1980, 'sensory', 'kinesthetic', NULL, 'The feeling of reaching into reality, pulling on power, and the eruption of roots from the ground.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:56:18.580112-05', '2026-03-01 00:56:18.580112-05');
INSERT INTO public.semantic_tags VALUES (6046, 1981, 'theme', 'corruption', NULL, 'The roots, an extension of Kai''s will, are twisted into something monstrous and alien.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.semantic_tags VALUES (6047, 1981, 'emotion', 'dread', NULL, 'Kai''s realization that ''something was wrong'' as he feels the boundary thinning and a malevolent presence stirring.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.semantic_tags VALUES (6048, 1981, 'sensory', 'tactile', NULL, 'The feeling of the roots crushing the creatures, which Kai experiences directly.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.semantic_tags VALUES (6049, 1982, 'theme', 'transformation', NULL, 'This is a theme of horrific, involuntary transformation, a classic element of body horror.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.semantic_tags VALUES (6050, 1982, 'emotion', 'agony', NULL, 'The text explicitly states ''The pain was absolute'' as every cell in Kai''s body inverts.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.semantic_tags VALUES (6051, 1982, 'sensory', 'auditory', NULL, 'The ''wet, organic sounds'' of vertebrae popping and the ''terrible tearing of cartilage'' create a visceral soundscape.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.semantic_tags VALUES (6052, 1982, 'sensory', 'visual', NULL, 'The imagery of melting features, bubbling skin, and the iridescent black substance is central to the horror of the scene.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:08.979829-05', '2026-03-01 00:57:08.979829-05');
INSERT INTO public.semantic_tags VALUES (6053, 1983, 'emotion', 'horror', NULL, 'The scene opens with visceral body horror as Kai''s form is grotesquely transformed.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6054, 1983, 'theme', 'transformation', NULL, 'The fundamental change from a known character, Kai, into a monstrous and alien entity.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6055, 1983, 'sensory', 'visual', NULL, 'Emphasis on impossible colors reflected in shattered, black, crystalline eyes.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6056, 1984, 'emotion', 'dominance', NULL, 'The entity effortlessly eradicates a threat and powerfully declares its own existence.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6057, 1984, 'theme', 'identity', NULL, 'The layered voices explicitly define the new being as a fusion of gardener, parasite, and corrupted love.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6058, 1984, 'sensory', 'auditory', NULL, 'The sound of the layered voices speaking as one is a key moment of revelation.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6059, 1985, 'emotion', 'hopelessness', NULL, 'The fading of the warning sirens signifies that all opposition has been neutralized and control is absolute.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6060, 1985, 'theme', 'conquest', NULL, 'The entity''s influence rapidly expands from a single garden to encompass an entire planet.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6061, 1985, 'sensory', 'kinesthetic', NULL, 'The feeling of the root system spreading across the entire surface of the planet implies a massive, physical takeover.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:57:50.076814-05', '2026-03-01 00:57:50.076814-05');
INSERT INTO public.semantic_tags VALUES (6062, 1986, 'emotion', 'Sorrow', NULL, 'Sophia weeps, feeling the pain of a distant world''s destruction.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:58:43.969579-05', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.semantic_tags VALUES (6063, 1986, 'theme', 'Inevitability', NULL, 'The scene''s core idea is that in an infinite cosmos, all tragedies are not only possible but have already occurred.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:58:43.969579-05', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.semantic_tags VALUES (6064, 1986, 'sensory', 'Metaphysical Perception', NULL, 'Sophia''s senses are not physical; she ''feels'' the event as a tear in a cosmic tapestry.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:58:43.969579-05', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.semantic_tags VALUES (6065, 1986, 'theme', 'Cosmic Horror', NULL, 'The horror stems from the vast, deterministic, and indifferent nature of reality itself, rather than a specific monster.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:58:43.969579-05', '2026-03-01 00:58:43.969579-05');
INSERT INTO public.semantic_tags VALUES (6066, 1987, 'emotion', 'Relief', NULL, 'The author expresses a sense of exhausted relief at having completed the 30-day challenge.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6067, 1987, 'theme', 'Creative Process', NULL, 'The beat focuses on the grueling, physical-feeling effort of writing.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6068, 1987, 'sensory', 'Kinesthetic', NULL, 'The author uses visceral language like ''sweating and vomiting'' to describe the act of creation.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6069, 1988, 'theme', 'Inspiration', NULL, 'The author traces the story''s origins to childhood fandom and later esoteric studies.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6070, 1988, 'emotion', 'Discovery', NULL, 'The realization that the author had ''tapped into something much deeper'' through his research and journaling.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6071, 1988, 'sensory', 'Cognitive', NULL, 'The process described is one of intellectual and spiritual formulation, where dream journals gain new meaning.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6072, 1989, 'theme', 'Unplanned Creativity', NULL, 'The story took on a life of its own when ''the Pointers sprung into existence,'' defying the author''s original plan.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6073, 1989, 'emotion', 'Surprise', NULL, 'The unexpected emergence of the Pointers forced a complete change in narrative direction.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6074, 1990, 'emotion', 'Frustration', NULL, 'The editing process is described as a ''nightmare'' of ''ripping and tearing'' the manuscript.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6075, 1990, 'theme', 'Sacrifice', NULL, 'Significant narrative elements, characters, and storylines had to be cut for the sake of brevity.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6076, 1990, 'theme', 'Lost Content', NULL, 'The author details multiple story arcs and character journeys that will now never be known to the reader.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6077, 1991, 'theme', 'Compromise', NULL, 'The author admits to cramming 3-4 books'' worth of plot into one volume out of a rush to finish.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6078, 1991, 'emotion', 'Finality', NULL, 'A sense of closure is conveyed with the simple statements: ''But it was a story. It was done.''', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6079, 1991, 'sensory', 'Auditory', NULL, 'The phrase ''Long story short'' implies a verbal summarization, giving the text a conversational tone.', 'gemini', 'gemini-2.5-pro', '2026-03-01 00:59:50.348829-05', '2026-03-01 00:59:50.348829-05');
INSERT INTO public.semantic_tags VALUES (6080, 1992, 'emotion', 'frustration', NULL, 'The author''s feeling of being stuck in a ''depressing narrative corner''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6081, 1992, 'theme', 'creative process', NULL, 'Highlights the unstructured, exploratory phase of writing.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6082, 1993, 'emotion', 'inspiration', NULL, 'A sudden breakthrough idea (''eureka moment'') sparked by an external event.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6083, 1993, 'theme', 'serendipity', NULL, 'An accidental head-kick leads to a pivotal creative decision.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6084, 1993, 'sensory', 'tactile', NULL, 'The literal, physical impact of the author''s son kicking him in the head.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6085, 1994, 'emotion', 'surprise', NULL, 'The author''s reaction to the story and characters developing in unexpected ways.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6086, 1994, 'theme', 'emergence', NULL, 'Characters gain agency and take on ''lives of their own'', causing the plot to diverge from the outline.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6087, 1995, 'emotion', 'clarity', NULL, 'The author''s clear understanding and articulation of the story''s internal logic and ultimate goal.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6088, 1995, 'theme', 'symbolism', NULL, 'The act of naming is not arbitrary but a symbol of agency and personhood within the narrative.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6089, 1995, 'sensory', 'conceptual', NULL, 'The beat deals with abstract rules and the structure of the narrative itself.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:00:51.567693-05', '2026-03-01 01:00:51.567693-05');
INSERT INTO public.semantic_tags VALUES (6090, 1996, 'theme', 'meta-narrative', NULL, 'The author is breaking the fourth wall to discuss the construction and internal logic of his own story.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.semantic_tags VALUES (6091, 1996, 'theme', 'cosmology', NULL, 'The beat is focused on establishing the fundamental, universe-defining rules of the fictional setting.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.semantic_tags VALUES (6092, 1996, 'emotion', 'contemplative', NULL, 'The tone is reflective as the author considers how to unify the concepts across his book series.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.semantic_tags VALUES (6093, 1997, 'emotion', 'frustration', NULL, 'The author''s financial struggles are a clear source of frustration, preventing him from realizing his full creative vision.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.semantic_tags VALUES (6094, 1997, 'theme', 'art vs commerce', NULL, 'The author''s creative goals are in direct conflict with his financial reality, forcing pragmatic compromises.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.semantic_tags VALUES (6095, 1997, 'sensory', 'auditory', NULL, 'The beat explicitly discusses the creation of an audiobook and the act of reading chapters aloud.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.semantic_tags VALUES (6096, 1997, 'emotion', 'pragmatism', NULL, 'Despite his frustrations, the author makes practical decisions to move forward and serve his audience.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:01:42.16227-05', '2026-03-01 01:01:42.16227-05');
INSERT INTO public.semantic_tags VALUES (6097, 1998, 'emotion', 'ambition', NULL, 'The author lays out a clear, ambitious plan for the future of their work.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.semantic_tags VALUES (6098, 1998, 'theme', 'creation', NULL, 'Focuses on the process of refining and publishing a creative work.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.semantic_tags VALUES (6099, 1998, 'theme', 'professionalism', NULL, 'Discusses hiring editors and creating a higher quality product.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.semantic_tags VALUES (6100, 1999, 'emotion', 'cynicism', NULL, 'Dismisses traditional marketing and accepts the possibility of failure or posthumous success.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.semantic_tags VALUES (6101, 1999, 'theme', 'legacy', NULL, 'Contemplates how the work will be remembered after the author''s death.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.semantic_tags VALUES (6102, 1999, 'theme', 'conspiracy', NULL, 'A paranoid joke about powerful groups trying to silence the author.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.semantic_tags VALUES (6103, 1999, 'sensory', 'conceptual', NULL, 'The beat revolves around abstract ideas like legacy, reincarnation, and cosmic conspiracies rather than physical sensations.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:02:27.061592-05', '2026-03-01 01:02:27.061592-05');
INSERT INTO public.semantic_tags VALUES (6104, 2000, 'theme', 'meta-narrative', NULL, 'The author breaks the fourth wall to address the reader directly.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6105, 2000, 'emotion', 'welcoming', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6106, 2000, 'sensory', 'cognitive', NULL, 'The beat is about providing understanding and context, not physical senses.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6107, 2001, 'theme', 'imprisonment', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6108, 2001, 'emotion', 'dread', NULL, 'The concept of a soul-eating god and an eternal prison is horrifying.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6109, 2001, 'theme', 'cosmic horror', NULL, NULL, 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6110, 2002, 'theme', 'instability', NULL, 'Refers to both Stephen''s fragmented memory and the destabilized reality of the prison.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6111, 2002, 'emotion', 'hope', NULL, 'Stephen is described as an anomaly, which suggests a chance for escape or change.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6112, 2002, 'sensory', 'visual', NULL, 'The text mentions Stephen is ''one of the few capable of seeing beyond the veil of the prison''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6113, 2003, 'theme', 'connection', NULL, 'The key relationships are presented as central to the conflict and potential resolution.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6114, 2003, 'emotion', 'love', NULL, 'Stephen''s desperate love for Jamie is described as a powerful, reality-tearing force.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6115, 2003, 'sensory', 'auditory', NULL, 'Refers to Whitney having ''sent a fragmented signal back to Stephen''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:03:27.740345-05', '2026-03-01 01:03:27.740345-05');
INSERT INTO public.semantic_tags VALUES (6116, 2004, 'theme', 'creation_myth', NULL, 'The scene establishes a Gnostic-inspired origin story for the universe.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6117, 2004, 'theme', 'potentiality', NULL, 'The void is described as containing infinite, sleeping potential.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6118, 2004, 'sensory', 'absence', NULL, 'The text emphasizes the absolute lack of all sensory input.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6119, 2005, 'theme', 'divine_order', NULL, 'The Pleroma represents a perfect, mathematically precise, and harmonious existence.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6120, 2005, 'emotion', 'perfection', NULL, 'The state of the Pleroma is described as perfect, stable, and complete.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6121, 2005, 'sensory', 'light', NULL, 'The emergence of the Four Great Lights introduces the concept of divine illumination.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6122, 2006, 'emotion', 'longing', NULL, 'Sophia feels a longing for something new that doesn''t exist in the perfect Pleroma.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6123, 2006, 'emotion', 'boredom', NULL, 'Sophia''s motivation is explicitly stated as boredom with unchanging perfection.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6124, 2006, 'theme', 'rebellion', NULL, 'Sophia breaks from her syzygy and the established order, an act of individual will.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6125, 2007, 'theme', 'unintended_consequences', NULL, 'Sophia''s attempt to create something beautiful results in unleashing a monster.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6126, 2007, 'emotion', 'horror', NULL, 'Sophia''s reaction to the creature is one of immediate recoil and horror.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6127, 2007, 'sensory', 'violation', NULL, 'The creature''s emergence is described as an ''infection'' that came ''through her'', implying a violation of her being.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6128, 2008, 'emotion', 'regret', NULL, 'Sophia feels regret for the first time, a feeling the Pleroma was not designed for.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6129, 2008, 'theme', 'corruption', NULL, 'The entity begins creating twisted, degraded copies of the divine architecture.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6130, 2008, 'theme', 'imprisonment', NULL, 'The scene ends with the entity contained but active within its prison, and Sophia trapped by her secret.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6131, 2008, 'sensory', 'visual', NULL, 'The focus is on Sophia watching the entity build its corrupted kingdom.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:04:22.182582-05', '2026-03-01 01:04:22.182582-05');
INSERT INTO public.semantic_tags VALUES (6132, 2009, 'emotion', 'loneliness', NULL, 'Sophia''s loneliness and curiosity are the prime movers of the entire tragedy.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6133, 2009, 'theme', 'determinism', NULL, 'The God-Null Zone is a universe of cold, hard rules, making Sam''s pure love an anomaly.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6134, 2009, 'sensory', 'olfactory', NULL, 'The smells of lanolin, wool, and herbs establish the earthy, material reality of Sam''s world.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6135, 2010, 'emotion', 'rage', NULL, 'Sam''s rage is described as ''impossible'' and ''reality-warping'', a passion that transcends the laws of his universe.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6136, 2010, 'theme', 'violation', NULL, 'The serene valley and Sam''s pure love are brutally violated by the raiders, representing the law of consumption.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6137, 2010, 'sensory', 'auditory', NULL, 'The raiders'' laughter is compared to ''grinding stones'', emphasizing their cruel, inhuman nature.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6138, 2011, 'theme', 'transformation', NULL, 'Sam undergoes a horrific physical and spiritual transformation, being unmade and rebuilt into a new entity.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6139, 2011, 'emotion', 'horror', NULL, 'The description of Sam''s body bubbling, dissolving, and reforming is one of pure body horror.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6140, 2011, 'theme', 'paradox', NULL, 'The collision of ''is'' (Pleroma) and ''is not'' (Anti-reality) via a being from a God-Null zone is a fundamental paradox that births a new creation.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6141, 2012, 'emotion', 'shame', NULL, 'An aeon feels shame for the first time, a profound moment signifying the gravity of her mistake.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6142, 2012, 'theme', 'containment', NULL, 'Sophia''s immediate reaction is to hide her mistake, creating a prison that will ultimately fail.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6143, 2012, 'sensory', 'visual', NULL, 'The image of a ''luminous cloud'' being wrapped around the darkness is a powerful visual metaphor for the attempted containment.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6144, 2013, 'emotion', 'arrogance', NULL, 'Yaldabaoth''s first thought is ''I AM'', followed by the lie ''I AM the one true God'', showing its immediate, ignorant hubris.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6145, 2013, 'theme', 'corruption', NULL, 'Yaldabaoth''s creative act is a dark mockery, creating degraded copies. Sam''s love is corrupted into hunger, and Sophia''s light is corrupted into fuel.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6146, 2013, 'theme', 'hubris', NULL, 'The new god, ignorant of its own origins, believes it is the ultimate creator, a central theme of the Gnostic Demiurge.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:05:15.628325-05', '2026-03-01 01:05:15.628325-05');
INSERT INTO public.semantic_tags VALUES (6147, 2014, 'emotion', 'defiance', NULL, 'Lilith''s immediate rejection of her creators'' design with the words ''I am what I am''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6148, 2014, 'theme', 'consciousness', NULL, 'The stark contrast between Lilith''s sudden, full-fledged consciousness and Adam''s mindless, empty state.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6149, 2014, 'sensory', 'tactile', NULL, 'The description of the ground being ''too soft. Like flesh that hadn''t decided if it wanted to be soil yet''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6150, 2015, 'emotion', 'isolation', NULL, 'Lilith is described as a ghost and an exile, completely alone for cycles.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6151, 2015, 'theme', 'imprisonment', NULL, 'The garden is a prison for the obedient humans, and the void outside is a prison of exile for Lilith.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6152, 2015, 'sensory', 'visual', NULL, 'Lilith watches the garden grow crowded and sees Lucifer''s flickering, impossible form for the first time.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6153, 2016, 'emotion', 'love', NULL, 'The impossible transmutation of Lucifer''s raw lust into love, described as a ''glitch in the design''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6154, 2016, 'theme', 'rebellion', NULL, 'The vow made by Lilith and Lucifer to tear down the walls and free the sleeping souls.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6155, 2016, 'sensory', 'tactile', NULL, 'The moment Lilith pins Lucifer, ''pressed flesh to flesh'', which triggers his transformation.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6156, 2017, 'emotion', 'futility', NULL, 'Their rebellion is described as futile, as they can only wake a handful of souls against trillions.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6157, 2017, 'theme', 'suffocation', NULL, 'The garden becomes a ''compression chamber'' where beings can''t breathe without inhaling the fear of others.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6158, 2017, 'sensory', 'olfactory', NULL, 'The smell of ''sweat and fear and desperation'' from the overcrowded humans.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6159, 2018, 'theme', 'cataclysm', NULL, 'The entire reality of the garden collapses inward in a violent implosion.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6160, 2018, 'theme', 'cyclicality', NULL, 'Despite the total destruction, the scene ends with Yaldabaoth speaking ''Let there be light,'' starting the cycle over again.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6161, 2018, 'sensory', 'auditory', NULL, 'The non-sound of reality tearing apart, and Yaldabaoth''s words spoken into the absolute void.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:06:25.991588-05', '2026-03-01 01:06:25.991588-05');
INSERT INTO public.semantic_tags VALUES (6162, 2019, 'theme', 'Adaptation', NULL, 'Yaldabaoth moves from brute force to a more strategic approach.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6163, 2019, 'theme', 'Optimization', NULL, 'The core motivation is to increase the efficiency of the soul harvest.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6164, 2019, 'emotion', 'Calculation', NULL, 'Yaldabaoth''s process is cold and analytical, like a programmer debugging code.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6165, 2020, 'theme', 'Gluttony', NULL, 'The failure is caused by mindless, excessive consumption leading to self-destructive consequences.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6166, 2020, 'emotion', 'Dissatisfaction', NULL, 'A shift from pure hunger to a more refined, qualitative desire for better ''tasting'' souls.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6167, 2020, 'sensory', 'Visceral', NULL, 'The imagery of vomiting souls and imploding from internal pressure is deeply physical and grotesque.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6168, 2021, 'theme', 'Spiritual Farming', NULL, 'The metaphor shifts from a prison to a farm where souls are cultivated and fermented like a crop.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6169, 2021, 'emotion', 'Intoxication', NULL, 'Yaldabaoth''s reaction to the idea of being worshipped is described as intoxicating, a new and powerful sensation.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6170, 2021, 'sensory', 'Gustatory', NULL, 'The entire motivation is framed around the ''taste'', ''flavor'', and ''ripeness'' of souls.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6171, 2022, 'theme', 'Unintended Consequences', NULL, 'The tool of free will, meant to improve the harvest, instead causes its premature destruction.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6172, 2022, 'emotion', 'Annihilation', NULL, 'The overwhelming emotion of the harvest is a singular, acrid taste of mutual, violent destruction.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6173, 2022, 'sensory', 'Auditory', NULL, 'The collapse is triggered by a ''unified, system-wide scream of hatred''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6174, 2023, 'theme', 'Eternal Recurrence', NULL, 'The final state is a perfect, unchanging, and hopeless loop.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6175, 2023, 'emotion', 'Certainty', NULL, 'Yaldabaoth achieves a state of absolute confidence in its perfected system.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6176, 2023, 'theme', 'Degradation', NULL, 'A subtle hint that even this ''perfect'' system is slowly wearing down, introducing a sliver of hope.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:07:32.706481-05', '2026-03-01 01:07:32.706481-05');
INSERT INTO public.semantic_tags VALUES (6177, 2024, 'emotion', 'apprehension', NULL, 'Lilith''s feeling that something is deeply wrong and doesn''t match any known pattern.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6178, 2024, 'theme', 'foreboding', NULL, 'The hairline fracture signals a coming cataclysm of an unknown nature.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6179, 2024, 'sensory', 'tactile', NULL, 'The scene is introduced with a physical ''tremor'' and the ''shudder'' of the air itself.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6180, 2025, 'emotion', 'ecstasy', NULL, 'Yaldabaoth''s scream is not of pain or rage, but of a terrifying, primal, and violent release.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6181, 2025, 'theme', 'revelation', NULL, 'The true, hungry nature of Yaldabaoth as ''The Anti-Real'' is seen for the first time through the rupture.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6182, 2025, 'sensory', 'auditory', NULL, 'The massive, incomprehensible frequency of Yaldabaoth''s scream makes Lilith''s bones vibrate.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6183, 2026, 'emotion', 'desperation', NULL, 'Lilith and Lucifer''s frantic attempts to save who they can from the dissolution.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6184, 2026, 'theme', 'cataclysm', NULL, 'The entire foundation of their reality shatters not into fire, but into absence.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6185, 2026, 'sensory', 'visual', NULL, 'The consciousness of trillions scattering ''like seeds in a hurricane''.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6186, 2027, 'emotion', 'hunger', NULL, 'Yaldabaoth''s original, mindless need to consume everything surges upon entering the true cosmos.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6187, 2027, 'theme', 'corruption', NULL, 'Yaldabaoth learns to spread not just by force, but by disguising itself as divine truth, making belief a vector of infection.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6188, 2027, 'theme', 'conquest', NULL, 'The systematic, slow consumption and replacement of entire realities from the inside out.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:08:28.234475-05', '2026-03-01 01:08:28.234475-05');
INSERT INTO public.semantic_tags VALUES (6189, 2028, 'emotion', 'desperation', NULL, 'The act of fleeing across ''trillions of years'' highlights the scale of their desperation and the relentlessness of the pursuit.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.semantic_tags VALUES (6190, 2028, 'theme', 'survival', NULL, 'The core motivation is survival, not just for themselves but for the refugees they gather.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.semantic_tags VALUES (6191, 2028, 'sensory', 'vastness', NULL, 'The immense scale of time and space emphasizes the characters'' isolation and the magnitude of the conflict.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.semantic_tags VALUES (6192, 2029, 'emotion', 'hope', NULL, 'Recruiting Chernobog represents the first tangible spark of hope and a turning point from flight to fight.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.semantic_tags VALUES (6193, 2029, 'theme', 'alliance', NULL, 'The beat is centered on the theme of forging alliances to create a united front against a common enemy.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.semantic_tags VALUES (6194, 2029, 'theme', 'resistance', NULL, 'Lucifer''s proposal marks the formal beginning of an organized resistance movement.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:09:17.267972-05', '2026-03-01 01:09:17.267972-05');
INSERT INTO public.semantic_tags VALUES (6195, 2030, 'emotion', 'Agony', NULL, 'Velistra''s scream and physical torment from the acid and impalement.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6196, 2030, 'theme', 'Desperate Struggle', NULL, 'Velistra fights an impossible foe even after being horribly wounded.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6197, 2030, 'sensory', 'Olfactory', NULL, 'The scene is introduced with the stench of iron, burnt ozone, and an ancient wrongness.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6198, 2031, 'emotion', 'Rage', NULL, 'Stephen''s ''blind, white-hot rage'' that consumes him upon seeing Velistra impaled.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6199, 2031, 'emotion', 'Love', NULL, 'Described as a ''star-eating inferno'', Stephen''s love is the force that allows him to break reality.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6200, 2031, 'theme', 'Forbidden Power', NULL, 'Stephen''s act is described as ''heresy'' and ''un-creation'', a power that mimics the enemy.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6201, 2031, 'sensory', 'Auditory', NULL, 'The creature''s erasure is marked by a ''deafening silence'' as reality forgets its sound.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6202, 2032, 'emotion', 'Grief', NULL, 'Lady Illkeserod''s soul-tearing grief upon realizing Benji is gone.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6203, 2032, 'emotion', 'Fury', NULL, 'Illkeserod''s grief is instantly forged into a pure, focused fury directed at Stephen.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6204, 2032, 'theme', 'Consequence', NULL, 'Stephen''s tunnel vision in saving one person leads to the loss of another, revealing the terrible cost of his actions.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6205, 2032, 'sensory', 'Tactile', NULL, 'Velistra''s phantom pain, the memory of being torn apart that ''burns'' even after she is healed.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:10:02.692877-05', '2026-03-01 01:10:02.692877-05');
INSERT INTO public.semantic_tags VALUES (6206, 2033, 'emotion', 'innocence', NULL, 'The playful, carefree nature of the young goddesses before they witness the horror of the infection.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6207, 2033, 'theme', 'corruption', NULL, 'The instant, joyful corruption of a simple man into a zealot.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6208, 2033, 'sensory', 'visual', NULL, 'The world is described with a palpable, honey-gold light, contrasting with the ''ugly light'' in the converted merchant''s eyes.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6209, 2034, 'emotion', 'desperation', NULL, 'The sisters are fighting a spiritual plague they cannot possibly contain, a tide they cannot hold back.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6210, 2034, 'theme', 'futility', NULL, 'For every soul they save, many more are lost. Their efforts are heroic but ultimately futile against the scale of the infection.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6211, 2035, 'theme', 'transformation', NULL, 'The violent, sacrificial transformation of two individuals into a single, new being born from destruction.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6212, 2035, 'emotion', 'despair', NULL, 'The final moments of their world are depicted with a burning temple and a god devouring reality itself.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6213, 2035, 'sensory', 'auditory', NULL, 'A ''single, fused sound'' of a scream as the sisters detonate and merge.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6214, 2036, 'emotion', 'weariness', NULL, 'Lady Illkeserod is described as aged by an ''infinite, bone-deep weariness'' after centuries of fighting a losing battle.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6215, 2036, 'theme', 'salvation', NULL, 'An unexpected, last-minute rescue arrives in the form of Benji and his portal.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6216, 2036, 'emotion', 'hope', NULL, 'A stranger represents an ''impossible hope'' at the absolute end of all things for this group.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:11:01.276898-05', '2026-03-01 01:11:01.276898-05');
INSERT INTO public.semantic_tags VALUES (6217, 2037, 'emotion', 'Dread', NULL, 'The growing horror as the group follows the trail of Benji''s remains.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6218, 2037, 'theme', 'Pursuit', NULL, 'The scene is framed as a desperate hunt, always one step behind the predator.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6219, 2037, 'sensory', 'Olfactory', NULL, 'The acrid, static-laced air of the nightmare reality.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6220, 2038, 'emotion', 'Horror', NULL, 'The psychic assault of witnessing a friend and god being physically and spiritually consumed.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6221, 2038, 'theme', 'Helplessness', NULL, 'The gods are forced to watch, unable to intervene as Benji is unmade.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6222, 2038, 'sensory', 'Auditory', NULL, 'The wet rip of flesh and Benji''s soul-vibrating scream of agony.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6223, 2039, 'emotion', 'Rage', NULL, 'Lady Illkeserod''s grief and fury are channeled into a single, suicidal attack.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6224, 2039, 'theme', 'Sacrifice', NULL, 'Illkeserod expends a massive amount of her own power, first to attack and then to remake Benji.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6225, 2039, 'sensory', 'Visual', NULL, 'Illkeserod becoming a ''comet of pure, blue-white power'' and the violent knitting of flesh.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6226, 2040, 'emotion', 'Grief', NULL, 'The devastating realization that the person they knew is gone forever, replaced by a hollow shell.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6227, 2040, 'theme', 'Loss of Self', NULL, 'Benji''s consciousness and memory are completely erased, the ultimate violation.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6228, 2040, 'theme', 'Revelation', NULL, 'The horrifying truth about how to contain Yaldabaoth becomes clear through the tragedy.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:06.192508-05', '2026-03-01 01:12:06.192508-05');
INSERT INTO public.semantic_tags VALUES (6229, 2041, 'emotion', 'love', NULL, 'A tragic, self-sacrificial maternal love that is being weaponized and exploited.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.semantic_tags VALUES (6230, 2041, 'theme', 'parasitism', NULL, 'The creature is in a parasitic relationship, feeding on Sophia''s essence while being sustained by her love.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.semantic_tags VALUES (6231, 2041, 'theme', 'revelation', NULL, 'Lucifer and Lilith reveal a critical piece of lore about the enemy''s nature and sustenance.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
INSERT INTO public.semantic_tags VALUES (6232, 2041, 'sensory', 'visual', NULL, 'The term ''luminous cloud'' creates a strong visual, contrasting an image of light and beauty with the horror of its function.', 'gemini', 'gemini-2.5-pro', '2026-03-01 01:12:59.201311-05', '2026-03-01 01:12:59.201311-05');
